module GavinTools
  module SULinkHubMultiSpace
    # Bootstrap API is normally defined by main.rb. During an in-session upgrade
    # from v0.9.29, SketchUp still has the old GavinTools::SULinkHub bootstrap in
    # memory and only the files on disk are replaced. Define the API fallback here
    # so the new runtime can operate before SketchUp is restarted.
    BOOTSTRAP_API = 4 unless const_defined?(:BOOTSTRAP_API, false)
    RUNTIME_SESSION_ID = "#{Process.pid}-#{SecureRandom.hex(10)}" unless const_defined?(:RUNTIME_SESSION_ID, false)
    SKETCHUP_UI_THREAD_OBJECT_ID = Thread.current.object_id unless const_defined?(:SKETCHUP_UI_THREAD_OBJECT_ID, false)

    # v0.13.0: 更新安装不能假定当前 SketchUp 会话已经载入最新版 main.rb。
    # 从旧版本热更新到新 runtime 时，磁盘上的 main.rb 已更新，但内存中的 bootstrap
    # 仍可能没有 install_archive_and_reload!，因此在 runtime 侧提供兼容兜底。
    unless respond_to?(:install_archive_and_reload!)
      def self.install_archive_and_reload!(archive_path, show_dialog: false)
        path = File.expand_path(archive_path.to_s)
        raise "LinkHub 更新包不存在：#{path}" unless File.file?(path)
        raise '当前 SketchUp 不支持从 RBZ 安装插件。' unless Sketchup.respond_to?(:install_from_archive)

        installed = begin
          Sketchup.install_from_archive(path, false)
        rescue ArgumentError
          Sketchup.install_from_archive(path)
        end
        raise "SketchUp 未能安装更新包：#{path}" unless installed

        latest_main = File.expand_path('main.rb', __dir__)
        raise "安装完成，但找不到新版 main.rb：#{latest_main}" unless File.file?(latest_main)
        Kernel.load(latest_main)

        unless GavinTools::SULinkHubMultiSpace.respond_to?(:load_runtime!)
          raise '新版 main.rb 已安装，但热重载接口 load_runtime! 未就绪；请重新启动 SketchUp。'
        end

        UI.start_timer(0.08, false) do
          begin
            loaded = GavinTools::SULinkHubMultiSpace.load_runtime!(
              show_dialog: show_dialog,
              reason: "安装更新包 #{File.basename(path)}"
            )
            if GavinTools::SULinkHubMultiSpace.respond_to?(:refresh_toolbar_command_state!)
              GavinTools::SULinkHubMultiSpace.refresh_toolbar_command_state!
            end
            if loaded
              current = GavinTools::SULinkHubMultiSpace.runtime rescue nil
              version = current.const_get(:EXTENSION_VERSION).to_s rescue '未知'
              completed_at = Time.now.strftime('%Y-%m-%d-%H:%M')
              message = "你成功更新到#{completed_at}-----(v#{version}版)"
              current.show_status(message, 'success') if current && current.respond_to?(:show_status)
              UI.messagebox(message)
            else
              UI.messagebox("SU LinkHub 更新包已经安装，但新版运行时未能成功载入。\n\n请使用“检查”查看具体问题；必要时重新启动 SketchUp。")
            end
          rescue StandardError => e
            UI.messagebox("SU LinkHub 更新包已经安装，但热重载失败。\n\n#{e.class}: #{e.message}\n\n请重新启动 SketchUp 后继续使用。")
          end
        end
        true
      rescue Interrupt
        false
      rescue Exception => e # rubocop:disable Lint/RescueException
        UI.messagebox(
          "SU LinkHub 更新失败。\n\n" \
          "#{e.class}: #{e.message}\n\n" \
          "更新包：#{File.basename(path.to_s)}\n" \
          "建议：确认插件发布目录可访问、RBZ 文件完整，然后重试。"
        )
        false
      end
    end

    unless respond_to?(:schedule_runtime_reload!)
      def self.schedule_runtime_reload!(show_dialog: false)
        raise '当前 LinkHub bootstrap 缺少 load_runtime!，请重新启动 SketchUp。' unless respond_to?(:load_runtime!)
        UI.start_timer(0.05, false) do
          load_runtime!(show_dialog: show_dialog, reason: '手动热重载')
          refresh_toolbar_command_state! if respond_to?(:refresh_toolbar_command_state!)
        end
        true
      end
    end

    # The legacy bootstrap removes GavinTools::SULinkHub::Runtime, not this new
    # namespace. On a second hot reload, discard the previously aliased runtime
    # here so Kernel.load creates a genuinely fresh runtime module.
    legacy_bootstrap = if GavinTools.const_defined?(:SULinkHub, false)
                         GavinTools.const_get(:SULinkHub, false)
                       end
    if legacy_bootstrap.is_a?(Module) &&
       !legacy_bootstrap.const_defined?(:Runtime, false) &&
       const_defined?(:Runtime, false)
      remove_const(:Runtime)
    end

