    def runtime_contract_check!
      missing_runtime = RUNTIME_REQUIRED_PUBLIC_METHODS.reject { |name| respond_to?(name) }
      raise "运行时缺少公开接口：#{missing_runtime.join(', ')}" unless missing_runtime.empty?

      raise 'WorkspaceToolbarOverlay 类未定义。' unless defined?(WorkspaceToolbarOverlay)
      overlay_public = WorkspaceToolbarOverlay.public_instance_methods(true)
      missing_overlay = WORKSPACE_OVERLAY_REQUIRED_PUBLIC_METHODS.reject { |name| overlay_public.include?(name) }
      unless missing_overlay.empty?
        private_hits = missing_overlay.select { |name| WorkspaceToolbarOverlay.private_instance_methods(true).include?(name) }
        detail = private_hits.empty? ? '' : "；其中被误设为 private：#{private_hits.join(', ')}"
        raise "抽屉 Overlay 缺少公开桥接接口：#{missing_overlay.join(', ')}#{detail}"
      end

      raise 'WorkspaceToolbarClickTool 类未定义。' unless defined?(WorkspaceToolbarClickTool)
      click_public = WorkspaceToolbarClickTool.public_instance_methods(true)
      missing_click = WORKSPACE_CLICK_TOOL_REQUIRED_PUBLIC_METHODS.reject { |name| click_public.include?(name) }
      raise "抽屉点击 Tool 缺少公开事件接口：#{missing_click.join(', ')}" unless missing_click.empty?
      true
    end

