    def log(message)
      line = "[#{Time.now.strftime('%Y-%m-%d %H:%M:%S')}] #{message}\n"
      File.open(LOG_PATH, 'ab') { |file| file.write(line.encode('UTF-8')) }
      # SketchUp 的 Ruby Console 只能由 UI 主线程可靠写入。后台发布 worker 调用
      # puts 会等待 SketchUp 控制台/主线程锁；诊断实测一条可阻塞 60~116 秒，导致
      # 实际毫秒级的 hard-link 发布在 64% 后看似“永远发布不完”。后台仍完整写日志文件。
      puts("SU LinkHub: #{message}") if Thread.current.object_id == SKETCHUP_UI_THREAD_OBJECT_ID
      true
    rescue StandardError
      false
    end

    def log_exception(context, error)
      details = error.respond_to?(:full_message) ? error.full_message : "#{error.class}: #{error.message}"
      log("#{context}\n#{details}")
    end

    # v0.13.6.53：采购清单专项“最后落点”诊断。每一条只写本机 TEMP，
    # 不经过 NAS；每次立即 flush，所以即使随后卡死也能保留最后一条。
    def soft_schedule_trace(message, model = nil)
      model ||= (Sketchup.active_model rescue nil)
      @soft_schedule_trace_run_id ||= SecureRandom.hex(4)
      stamp = Time.now.strftime('%Y-%m-%d %H:%M:%S.%L')
      gc = begin
        stat = GC.stat
        "heap=#{stat[:heap_live_slots]} old=#{stat[:old_objects]} major=#{stat[:major_gc_count]}"
      rescue StandardError
        ''
      end
      line = "[#{stamp}] run=#{@soft_schedule_trace_run_id} model=#{model ? model.object_id : 'nil'} #{gc} | #{message}\n"
      File.open(SCHEDULE_TRACE_PATH, 'ab') do |file|
        file.sync = true
        file.write(line.encode('UTF-8'))
        file.flush
      end
      true
    rescue StandardError
      false
    end

    def begin_soft_schedule_trace!(model = Sketchup.active_model, force: false, fast_local: false)
      begin
        File.delete(SCHEDULE_TRACE_PATH) if File.file?(SCHEDULE_TRACE_PATH) && File.size(SCHEDULE_TRACE_PATH).to_i > 4 * 1024 * 1024
      rescue StandardError
        nil
      end
      @soft_schedule_trace_run_id = SecureRandom.hex(4)
      soft_schedule_trace("REFRESH BEGIN version=#{EXTENSION_VERSION} force=#{force} fast_local=#{fast_local}", model)
    end

    def export_soft_schedule_trace
      source = SCHEDULE_TRACE_PATH
      unless File.file?(source)
        UI.messagebox("还没有生成采购清单诊断日志。\n请先打开或刷新一次项目软装清单。")
        return false
      end
      default_name = "SU_LinkHub_清单诊断_#{Time.now.strftime('%Y%m%d_%H%M%S')}.log"
      target = UI.savepanel('导出 SU LinkHub 清单诊断日志', File.dirname(source), default_name)
      return false if target.to_s.empty?
      FileUtils.cp(source, target)
      UI.messagebox("诊断日志已导出：\n#{target}")
      true
    rescue StandardError => e
      log_exception('导出采购清单诊断日志失败', e)
      UI.messagebox("导出诊断日志失败：#{e.message}\n\n原始日志：#{SCHEDULE_TRACE_PATH}") rescue nil
      false
    end

    # v0.13.6.53：资料提交专项诊断。与“清单加载诊断”分开保存，避免大量刷新日志
    # 淹没真正的路径/身份解析过程。只使用本机 TEMP，逐行 flush；不为了写日志额外扫描 NAS。
    def soft_schedule_submit_trace(message, model = nil)
      model ||= (Sketchup.active_model rescue nil)
      @soft_schedule_submit_run_id ||= SecureRandom.hex(4)
      stamp = Time.now.strftime('%Y-%m-%d %H:%M:%S.%L')
      gc = begin
        stat = GC.stat
        "heap=#{stat[:heap_live_slots]} old=#{stat[:old_objects]} major=#{stat[:major_gc_count]}"
      rescue StandardError
        ''
      end
      line = "[#{stamp}] submit=#{@soft_schedule_submit_run_id} model=#{model ? model.object_id : 'nil'} #{gc} | #{message}\n"
      File.open(SUBMIT_TRACE_PATH, 'ab') do |file|
        file.sync = true
        file.write(line.encode('UTF-8'))
        file.flush
      end
      true
    rescue StandardError
      false
    end

    def begin_soft_schedule_submit_trace!(model = Sketchup.active_model, change_count: 0, active_sheet: '')
      begin
        # 每次点击提交都从一份干净报告开始。若 SU 随后卡死/崩溃，最后一条仍在。
        File.delete(SUBMIT_TRACE_PATH) if File.file?(SUBMIT_TRACE_PATH)
      rescue StandardError
        nil
      end
      @soft_schedule_submit_run_id = SecureRandom.hex(4)
      @soft_schedule_submit_change_code = ''
      soft_schedule_submit_trace("SUBMIT BEGIN version=#{EXTENSION_VERSION} changes=#{change_count} active_sheet=#{active_sheet}", model)
      soft_schedule_submit_trace("ENV library_root=#{soft_library_root.inspect} organized_root=#{soft_library_organized_dir(soft_library_root).inspect}", model)
      @soft_schedule_submit_run_id
    end

    def soft_schedule_submit_trace_exception(context, error, model = nil)
      details = error.respond_to?(:full_message) ? error.full_message : "#{error.class}: #{error.message}"
      soft_schedule_submit_trace("#{context}\n#{details}", model)
    rescue StandardError
      false
    end

    def export_soft_schedule_submit_trace
      source = SUBMIT_TRACE_PATH
      unless File.file?(source)
        UI.messagebox("还没有生成资料提交诊断报告。\n请先在采购清单里点一次“提交资料修改”；即使提交失败，也会生成报告。")
        return false
