      default_name = "SU_LinkHub_提交失败报告_#{Time.now.strftime('%Y%m%d_%H%M%S')}.log"
      target = UI.savepanel('导出 SU LinkHub 提交失败报告', File.dirname(source), default_name)
      return false if target.to_s.empty?
      FileUtils.cp(source, target)
      UI.messagebox("提交诊断报告已导出：\n#{target}")
      true
    rescue StandardError => e
      log_exception('导出采购清单提交诊断报告失败', e)
      UI.messagebox("导出提交报告失败：#{e.message}\n\n原始报告：#{SUBMIT_TRACE_PATH}") rescue nil
      false
    end

    def diagnostic_root
      FileUtils.mkdir_p(TEMP_DIAGNOSTIC_DIR)
      TEMP_DIAGNOSTIC_DIR
    rescue StandardError
      TEMP_ROOT_DIR
    end

    def publish_active_journal_path
      File.join(diagnostic_root, PUBLISH_ACTIVE_JOURNAL_NAME)
    end

    def publish_history_path
      File.join(diagnostic_root, PUBLISH_HISTORY_NAME)
    end

    def publish_last_stage_path
      File.join(diagnostic_root, PUBLISH_LAST_STAGE_NAME)
    end

    # 关键阶段日志必须在调用 SketchUp 原生保存 API 之前真正落盘。普通 File.write
    # 可能仍停留在系统缓存，SU 原生崩溃时看不到最后一条；这里 flush + fsync。
    def durable_write_file(path, content)
      FileUtils.mkdir_p(File.dirname(path.to_s))
      temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.open(temp, 'wb') do |file|
        file.write(content.to_s.encode('UTF-8'))
        file.flush
        file.fsync rescue nil
      end
      linkhub_mv(temp, path)
      true
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    # 进度/诊断类小文件只需要在 SketchUp 进程异常退出后仍可读取，不需要为每个阶段
    # 强制 fsync 到物理盘。6.64 每个 breadcrumb 两次 fsync，3MB 测试文件也因此被放大到几十秒。
    def fast_atomic_write_file(path, content)
      FileUtils.mkdir_p(File.dirname(path.to_s))
      temp = "#{path}.tmp-fast-#{Process.pid}-#{SecureRandom.hex(2)}"
      File.open(temp, 'wb') do |file|
        file.write(content.to_s.encode('UTF-8'))
        file.flush
      end
      linkhub_mv(temp, path)
      true
    rescue StandardError
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def durable_append_file(path, content)
      FileUtils.mkdir_p(File.dirname(path.to_s))
      File.open(path, 'ab') do |file|
        file.write(content.to_s.encode('UTF-8'))
        file.flush
        file.fsync rescue nil
      end
      true
    rescue StandardError
      false
    end

    def process_alive?(pid)
      value = pid.to_i
      return false unless value.positive?
      Process.kill(0, value)
      true
    rescue Errno::EPERM
      true
    rescue StandardError
      false
    end

    def read_publish_journal
      path = publish_active_journal_path
      return nil unless File.file?(path)
      parsed = JSON.parse(File.read(path, mode: 'rb'))
      parsed.is_a?(Hash) ? parsed : nil
    rescue StandardError
      nil
    end

    def write_publish_journal!(payload)
      durable_write_file(publish_active_journal_path, JSON.pretty_generate(payload))
      @active_publish_journal = payload
      true
    rescue StandardError => e
      log_exception('写入发布崩溃追踪文件失败', e)
      false
    end

    def active_publish_id
      payload = @active_publish_journal
      payload.is_a?(Hash) ? payload['publish_id'].to_s : ''
    rescue StandardError
      ''
    end

    def publish_breadcrumb_for_id!(publish_id, stage, details = {})
      wanted = publish_id.to_s
      return false if wanted.empty? || active_publish_id != wanted
      publish_breadcrumb!(stage, details)
    rescue StandardError
      false
    end

    def publish_breadcrumb!(stage, details = {})
      async_payload = begin
        Thread.current[:sulink_async_publish_context]
      rescue StandardError
        nil
      end
      if async_payload.is_a?(Hash)
        async_job = begin
          Thread.current[:sulink_async_publish_job]
        rescue StandardError
          nil
        end
        update_background_publish_job_stage!(async_job, stage, details) if async_job.is_a?(Hash)
        async_payload['stage'] = stage.to_s
        async_payload['stage_at'] = Time.now.iso8601(6)
        async_payload['stage_index'] = async_payload['stage_index'].to_i + 1
        async_payload['details'] = (async_payload['details'].is_a?(Hash) ? async_payload['details'] : {}).merge(
          details.is_a?(Hash) ? details.transform_keys(&:to_s) : { 'detail' => details.to_s }
        )
        # 后台阶段进度以 registry 内存状态和专用 append-only trace 为准。旧逻辑每个
        # breadcrumb 都原子改写“最后阶段”与队列 JSON，再向通用日志追加一次；Windows
        # 实时防护/同步过滤器会让这些小文件 rename 逐级等待 10/30/40/60 秒，真正毫秒级
        # 的 hard-link 发布因此被拖成数分钟。危险替换仍由随机 stage + rollback + 内容
        # 指纹保护；队列在入队和最终结果边界持久化即可，中间进度不再同步写盘。
        return true
      end

      payload = @active_publish_journal
      return false unless payload.is_a?(Hash)
      payload['stage'] = stage.to_s
      payload['stage_at'] = Time.now.iso8601(6)
      payload['stage_index'] = payload['stage_index'].to_i + 1
      payload['details'] = (payload['details'].is_a?(Hash) ? payload['details'] : {}).merge(
        details.is_a?(Hash) ? details.transform_keys(&:to_s) : { 'detail' => details.to_s }
      )
      fast_atomic_write_file(publish_active_journal_path, JSON.pretty_generate(payload))
      @active_publish_journal = payload
      fast_atomic_write_file(
        publish_last_stage_path,
        [
          "time=#{payload['stage_at']}",
          "publish_id=#{payload['publish_id']}",
          "kind=#{payload['kind']}",
          "subject=#{payload['subject']}",
          "stage=#{payload['stage']}",
          "target=#{payload['target']}",
          "model=#{payload['model_path']}",
          "pid=#{payload['pid']}",
          "runtime=#{payload['runtime_session_id']}"
        ].join("\n") + "\n"
      )
      log("发布阶段[#{payload['publish_id']}]: #{payload['stage']} #{details.inspect}")
      true
    rescue StandardError => e
      log_exception("记录发布阶段 #{stage} 失败", e)
      false
    end

    def start_publish_journal!(kind:, subject:, target:, model: Sketchup.active_model)
      payload = {
        'schema' => PUBLISH_JOURNAL_SCHEMA,
        'status' => 'running',
        'publish_id' => "#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}",
        'plugin_version' => EXTENSION_VERSION,
        'kind' => kind.to_s,
        'subject' => subject.to_s,
        'target' => target.to_s,
        'model_path' => model ? model.path.to_s : '',
        'model_title' => model ? model.title.to_s : '',
        'pid' => Process.pid,
        'runtime_session_id' => GavinTools::SULinkHubMultiSpace::RUNTIME_SESSION_ID.to_s,
        'runtime_generation' => @runtime_generation.to_i,
        'user' => current_user_name,
        'host' => current_host_name,
        'started_at' => Time.now.iso8601(6),
        'stage' => 'guard_entered',
        'stage_at' => Time.now.iso8601(6),
        'stage_index' => 1,
        'details' => {}
      }
      write_publish_journal!(payload)
      publish_breadcrumb!('guard_entered')
      payload
    end

    def finish_publish_journal!(success:, error: nil)
      payload = @active_publish_journal || read_publish_journal
      return false unless payload.is_a?(Hash)
      payload['status'] = success ? 'success' : 'ruby_error'
      payload['finished_at'] = Time.now.iso8601(6)
      payload['error_class'] = error.class.to_s if error
      payload['error_message'] = error.message.to_s if error
      payload['error_backtrace'] = Array(error.backtrace).first(30) if error
      durable_append_file(publish_history_path, JSON.generate(payload) + "\n")
      durable_write_file(publish_last_stage_path, JSON.pretty_generate(payload))
      File.delete(publish_active_journal_path) if File.file?(publish_active_journal_path)
      @active_publish_journal = nil
      true
    rescue StandardError => e
      log_exception('结束发布追踪文件失败', e)
      false
    end

    def recover_unfinished_publish_journal!(notify: false)
      payload = read_publish_journal
      return nil unless payload.is_a?(Hash) && payload['status'].to_s == 'running'
      # 当前进程正在正常执行的发布不能被自检误报。完整闪退后 PID 会失效；
      # 热重载残留则通过 runtime session / generation 识别为异常中断。
      same_live_publish = payload['pid'].to_i == Process.pid && publish_critical_section?
      return nil if same_live_publish
      age = Time.now - (Time.parse(payload['stage_at'].to_s) rescue Time.at(0))
      return nil if payload['pid'].to_i == Process.pid && age < 8.0
      payload['status'] = process_alive?(payload['pid']) ? 'abandoned_runtime' : 'native_crash_suspected'
      payload['recovered_at'] = Time.now.iso8601(6)
      payload['recovered_by_pid'] = Process.pid
      @last_recovered_publish_crash = payload
      durable_append_file(publish_history_path, JSON.generate(payload) + "\n")
      File.delete(publish_active_journal_path) if File.file?(publish_active_journal_path)
      @active_publish_journal = nil
      message = "检测到上一次发布异常中断：#{payload['subject']}，最后阶段“#{payload['stage']}”。诊断目录：#{diagnostic_root}"
      log(message)
      show_status(message, 'error') if notify
      payload
    rescue StandardError => e
      log_exception('恢复上次发布崩溃记录失败', e)
      nil
    end

    def publish_critical_section?
      @publish_critical_depth.to_i.positive? || !!@global_publish_in_progress
    rescue StandardError
      false
    end

    def publish_post_quiet?
      monotonic_time < @publish_quiet_until.to_f
    rescue StandardError
      false
    end

    def publish_quiet_remaining
      [@publish_quiet_until.to_f - monotonic_time, 0.0].max
    rescue StandardError
      0.0
    end

    # v0.13.6.141：原生保存返回后的 quiet 窗口（2s）短于发布最小间隔（3s）。
    # 空间发布完成后附带同步协同组件时，不能只等 quiet 结束；还必须等完整的
    # PUBLISH_MIN_INTERVAL_SECONDS，否则会在约剩 0.6~1.0s 时被发布临界区主动拒绝。
    def publish_min_interval_remaining
      finished = @last_publish_finished_at.to_f
      return 0.0 unless finished.positive?
      [PUBLISH_MIN_INTERVAL_SECONDS - (monotonic_time - finished), 0.0].max
    rescue StandardError
      0.0
    end

    def publish_timer_allowed?(label)
      text = label.to_s
      text.start_with?('publish:') || text.start_with?('lock_heartbeat')
    end

    # 所有建筑、景观、室内和首次发布共用一个全局原生保存临界区。它不仅阻止
    # Ruby 层重复点击，也暂停缓存预热、定义清理和观察器延迟回调，避免第二次
    # definition.save_as 与第一次发布的原生收尾工作交叠。
    def enter_publish_critical_section!(kind:, subject:, target:, model: Sketchup.active_model)
      raise '另一个发布任务仍在进行，请等待完成后再试。' if publish_critical_section?
      raise '模型库正在批量刷新或删除，请等待任务完成后再发布。' if @soft_model_batch_job
      if @updating || @single_space_update_job || @space_batch_update_job
        raise '模型正在更新或准备本地镜像，请等待完成后再发布。'
      end
      # 上一次发布已成功返回、仅剩崩溃尾部观察时，下一次发布前先正常封存旧记录，
      # 防止新发布覆盖旧的 active journal。
      previous = @active_publish_journal || read_publish_journal
      if previous.is_a?(Hash) && previous['status'].to_s == 'running' &&
         %w[native_publish_returned_waiting_quiet post_publish_ui_resumed temporary_definition_cleanup_deferred post_publish_cleanup_begin post_publish_cleanup_returned].include?(previous['stage'].to_s)
        finish_publish_journal!(success: true)
      end
      wait = publish_min_interval_remaining
      if wait.positive? && @last_publish_finished_at.to_f.positive?
        # 旧版在这里 sleep，SketchUp 界面会表现为假死。继续保留原生保存安全间隔，
        # 但立即拒绝本次重复发布，让用户稍后再点，而不是阻塞建模主线程。
        raise format('上一次发布仍在原生收尾，请 %.1f 秒后再发布。', wait)
      end
      @global_publish_in_progress = true
      @publish_critical_depth = 1
      @publish_observers_suspended = true
      @publish_quiet_until = monotonic_time + PUBLISH_POST_QUIET_SECONDS
      begin_soft_heavy_interaction(:publish)
      cancel_soft_cache_warmup!
      @soft_full_cleanup_tokens = {}
      @soft_managed_definition_cleanup_records = {}
      @native_submit_prompt_scheduled = {}
      start_publish_journal!(kind: kind, subject: subject, target: target, model: model)
      true
    rescue StandardError
      @global_publish_in_progress = false
      @publish_critical_depth = 0
      @publish_observers_suspended = false
      end_soft_heavy_interaction(:publish)
      raise
    end

    def flush_deferred_publish_ui!(model = Sketchup.active_model)
      pending_refresh = !!@publish_deferred_refresh
      deferred_status = @publish_deferred_status
      deferred_notice = @publish_deferred_native_notice
      @publish_deferred_refresh = false
      @publish_deferred_status = nil
      @publish_deferred_native_notice = nil
      refresh_dialog if pending_refresh
      show_status(deferred_status[:message], deferred_status[:level]) if deferred_status.is_a?(Hash)
      show_native_notice(deferred_notice[:message], deferred_notice[:level]) if deferred_notice.is_a?(Hash)
      true
    rescue StandardError => e
      log_exception('恢复发布后界面提示失败', e)
      false
    end

    def finalize_settling_publish_journal_on_shutdown!
      return false if publish_critical_section?
      payload = @active_publish_journal || read_publish_journal
      return false unless payload.is_a?(Hash) && payload['status'].to_s == 'running'
      return false unless %w[native_publish_returned_waiting_quiet post_publish_ui_resumed temporary_definition_cleanup_deferred post_publish_cleanup_begin post_publish_cleanup_returned].include?(payload['stage'].to_s)
      publish_breadcrumb_for_id!(payload['publish_id'], 'clean_shutdown_after_publish')
      finish_publish_journal!(success: true)
    rescue StandardError => e
      log_exception('关闭时封存发布追踪失败', e)
      false
    end

    def leave_publish_critical_section!(success:, error: nil, model: Sketchup.active_model)
      publish_id = active_publish_id
      if success
        publish_breadcrumb_for_id!(publish_id, 'native_publish_returned_waiting_quiet')
      else
        publish_breadcrumb_for_id!(publish_id, 'ruby_error', error ? { error: error.message.to_s } : {})
        finish_publish_journal!(success: false, error: error)
      end
      @last_publish_finished_at = monotonic_time
      @publish_quiet_until = @last_publish_finished_at + PUBLISH_POST_QUIET_SECONDS
      @global_publish_in_progress = false
      @publish_critical_depth = 0
      @publish_observers_suspended = false
      end_soft_heavy_interaction(:publish)
      # 原生保存返回后先给 SketchUp 安静窗口，再恢复 HtmlDialog/Overlay 和缓存预热。
      runtime_start_timer(PUBLISH_POST_QUIET_SECONDS + 0.20, false, label: 'publish:resume_background') do
        schedule_soft_representation_cache_warmup(model, delay: 0.15) if model && model == Sketchup.active_model
        publish_breadcrumb_for_id!(publish_id, 'post_publish_ui_resumed') if success
        @publish_deferred_refresh = true
        flush_deferred_publish_ui!(model)
      end
      if success
        # 追踪文件继续保留到延迟定义清理完成之后。若这几秒内发生原生闪退，
        # 下次启动可明确判断是“保存已返回后的收尾阶段”而非候选写出阶段。
        runtime_start_timer(PUBLISH_JOURNAL_TAIL_SECONDS, false, label: 'publish:finalize_journal') do
          next unless active_publish_id == publish_id
          publish_breadcrumb_for_id!(publish_id, 'post_publish_tail_completed')
          finish_publish_journal!(success: true)
        end
      end
      true
    rescue StandardError => e
      log_exception('退出发布临界区失败', e)
      @global_publish_in_progress = false
      @publish_critical_depth = 0
      @publish_observers_suspended = false
      end_soft_heavy_interaction(:publish)
      false
    end

    def diagnostic_write_test(directory)
      dir = directory.to_s
      return [false, '目录为空'] if dir.empty?
      FileUtils.mkdir_p(dir)
      test = File.join(dir, ".sulink-write-test-#{Process.pid}-#{SecureRandom.hex(3)}")
      durable_write_file(test, "ok\n")
      File.delete(test) if File.file?(test)
      [true, '可写']
    rescue StandardError => e
      [false, "#{e.class}: #{e.message}"]
    ensure
      File.delete(test) if defined?(test) && test && File.file?(test)
    end

    def diagnostic_publish_artifacts(paths)
      roots = Array(paths).map { |path| File.directory?(path.to_s) ? path.to_s : File.dirname(path.to_s) }
                          .reject(&:empty?).uniq
      artifacts = []
      roots.each do |root|
        next unless File.directory?(root)
        Dir.glob(File.join(root, '.*.sulink-*')).first(300).each do |path|
          next unless File.file?(path)
          artifacts << {
            'path' => path,
            'size' => (File.size(path) rescue 0),
            'mtime' => ((File.mtime(path).iso8601) rescue ''),
            'age_seconds' => ((Time.now - File.mtime(path)).round rescue 0),
            'kind' => File.basename(path).include?('rollback') ? 'rollback' : 'temp'
          }
        end
        # v0.13.6.189：原子写入（锁/JSON/清单）在进程崩溃或共享盘删除失败时留下的
        # “*.tmp-<pid>-<hex>”。只匹配 LinkHub 自己的命名格式，由自检修复按年龄清理。
        Dir.glob(File.join(root, '*.tmp-*')).first(300).each do |path|
          next unless File.basename(path) =~ LINKHUB_WRITE_TEMP_LEFTOVER_PATTERN && File.file?(path)
          artifacts << {
            'path' => path,
            'size' => (File.size(path) rescue 0),
            'mtime' => ((File.mtime(path).iso8601) rescue ''),
            'age_seconds' => ((Time.now - File.mtime(path)).round rescue 0),
            'kind' => 'write_temp'
          }
        end
      rescue StandardError => e
        artifacts << { 'path' => root, 'kind' => 'scan_error', 'error' => e.message.to_s }
      end
      artifacts
    end

    def diagnostic_report_paths
      stamp = Time.now.strftime('%Y%m%d_%H%M%S')
      base = File.join(diagnostic_root, "LinkHub自检_#{stamp}_#{Process.pid}")
      ["#{base}.txt", "#{base}.json"]
    end

    def diagnostic_recent_publish_history(limit = 20)
      path = publish_history_path
      return [] unless File.file?(path)
      File.readlines(path, encoding: 'UTF-8').last(limit.to_i.clamp(1, 100)).filter_map do |line|
        parsed = JSON.parse(line)
        parsed.is_a?(Hash) ? parsed : nil
      rescue StandardError
        nil
      end
    rescue StandardError
      []
    end

    def diagnostic_advice_for(message)
      text = message.to_s
      case text
      when /上次发布.*崩溃|发布疑似.*崩溃|异常中断/
        '先确认当前模型和共享文件是否完整；若当前对象仍显示“修改中”，重新进入该对象后发布一次即可。'
      when /协同.*JSON|项目状态无法读取|未连接.*协同|连接.*异常|连接.*失败/
        '检查当前连接的协同.json 是否存在且可访问；必要时用“连接项目”重新选择正确的协同.json。'
      when /共享.*SKP.*不存在|共享 SKP 不存在|文件缺失/
        '检查协同项目目录及项目设置中的固定路径，确认文件没有被移动、改名或离线。'
      when /不可写|写入权限|没有权限|权限/
        '检查 NAS/共享文件夹是否在线，以及当前 Windows 账号是否有创建、改名和删除文件的权限。'
      when /当前由 .* 占用|占用/
        '如果是其他成员正在修改，等待对方通过 LinkHub 发布/取消修改即可；如果确认是本人中断会话留下的遗留占用，可使用“回收本人遗留占用”。'
      when /组件编辑层级|编辑层级/
        '按 Esc 退出当前正在编辑的内部组件层级后再发布；普通空间修改状态不会因此丢失。'
      when /重复根组件|多个.*受管根组件/
        '不要手工复制 LinkHub 受管根组件；保留正确的一份，并用单空间更新恢复缺失或异常对象。'
      when /结构异常|组件定义与开始修改时不同/
        '受管根模型可能被炸开、替换或改了容器结构。先不要强制发布，恢复正确根组件后重新检查。'
      when /多个受管根模型同时解锁/
        '通常只应有当前正在修改的协同对象解锁。结束其他对象的修改状态，或重新连接项目后再检查。'
      when /发布回滚文件/
        '回滚文件用于保护上一次发布。先确认正式共享 SKP 是否正确；确认无误后再手工归档，不建议直接删除。'
      when /发布候选|临时文件/
        '若文件刚生成可能是正常发布过程；超过 30 分钟的旧候选会由检查自动清理。'
      when /插件发布目录.*不存在|插件更新检查异常/
        '打开项目设置，重新选择有效的 LinkHub 插件发布目录。'
      when /模型库|材质库|固定路径/
        '打开项目设置核对固定路径；连接同一协同.json 后这些路径应自动恢复。'
      else
        '按上面的具体描述修正后，再点一次“检查”确认状态。'
      end
    end

    def diagnostic_dialog_html
      <<~HTML
        <!doctype html><html><head><meta charset="utf-8"><style>
        *{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#20242d;font:13px/1.45 "Microsoft YaHei",sans-serif}.wrap{padding:16px}.head{display:flex;align-items:center;justify-content:space-between;gap:10px}.title{font-size:17px;font-weight:700}.summary{margin-top:3px;color:#6f7785;font-size:11px}.badge{min-width:70px;text-align:center;padding:6px 10px;border-radius:999px;font-size:11px;font-weight:700}.badge.ok{background:#e7f4eb;color:#287341}.badge.warn{background:#fff2d9;color:#96600d}.badge.err{background:#fde7e7;color:#a63a3a}.section{margin-top:13px}.section-title{display:flex;align-items:center;gap:7px;font-weight:700;font-size:12px;margin-bottom:6px}.count{font-size:10px;color:#7b8492;font-weight:500}.card{background:#fff;border:1px solid #e0e4ea;border-radius:9px;padding:9px 10px;margin:6px 0}.card.issue{border-left:3px solid #cf5454}.card.warning{border-left:3px solid #d49a39}.card.fix{border-left:3px solid #4e9a68}.msg{font-weight:600;word-break:break-all}.advice{margin-top:4px;color:#717a88;font-size:11px;word-break:break-all}.empty{background:#fff;border:1px solid #e0e4ea;border-radius:9px;padding:10px;color:#7a8492}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:6px}.metric{background:#fff;border:1px solid #e0e4ea;border-radius:8px;padding:7px 9px}.metric b{display:block;font-size:10px;color:#7b8492;font-weight:500}.metric span{font-size:12px;word-break:break-all}.foot{position:sticky;bottom:0;background:linear-gradient(180deg,rgba(244,245,247,0),#f4f5f7 24%);padding-top:14px;display:flex;gap:8px}.foot button{height:34px;border:1px solid #d5dae2;border-radius:8px;background:#fff;cursor:pointer;flex:1;color:#3e4654}.foot .primary{background:#50596a;color:white;border-color:#50596a}.foot .settings{background:#edf0f5}.technical{margin-top:9px;color:#9299a5;font-size:10px}
        </style></head><body><div class="wrap"><div class="head"><div><div class="title">LinkHub 全面检查</div><div id="summary" class="summary">正在生成诊断结果…</div></div><div id="badge" class="badge ok">检查中</div></div><div id="content"></div><div class="foot"><button class="settings" onclick="sketchup.open_settings()">项目设置</button><button onclick="sketchup.close_diagnostic()">关闭</button><button class="primary" onclick="sketchup.rerun_diagnostic()">重新检查</button></div></div><script>
        function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
        function cards(title,kind,items){let a=items||[];let h='<div class="section"><div class="section-title">'+esc(title)+' <span class="count">'+a.length+' 项</span></div>';if(!a.length)return h+'<div class="empty">无</div></div>';return h+a.map(x=>'<div class="card '+kind+'"><div class="msg">'+esc(x.message||x)+'</div>'+(x.advice?'<div class="advice">建议：'+esc(x.advice)+'</div>':'')+'</div>').join('')+'</div>'}
        function render(p){p=p||{};let ic=(p.issues||[]).length,wc=(p.warnings||[]).length,fc=(p.fixes||[]).length;let b=document.getElementById('badge');b.className='badge '+(ic?'err':(wc?'warn':'ok'));b.textContent=ic?'发现问题':(wc?'需要注意':'状态正常');document.getElementById('summary').textContent='严重问题 '+ic+' · 警告 '+wc+' · 已自动处理 '+fc+' · '+(p.elapsed_ms||0)+' ms';let m=p.metrics||{};let metric='<div class="section"><div class="section-title">运行概况</div><div class="metrics"><div class="metric"><b>当前工作区</b><span>'+esc(m.workspace||'未配置')+'</span></div><div class="metric"><b>硬装/软装空间</b><span>'+esc(m.space_count==null?'-':m.space_count)+'</span></div><div class="metric"><b>当前 SU</b><span>'+esc(m.model_title||m.model_path||'未命名')+'</span></div><div class="metric"><b>发布任务</b><span>'+(m.publish_in_progress?'正在进行':'空闲')+'</span></div></div></div>';document.getElementById('content').innerHTML=cards('严重问题','issue',p.issue_items||[])+cards('需要注意','warning',p.warning_items||[])+cards('已自动处理','fix',p.fix_items||[])+metric+'<div class="technical">技术报告仍会后台保留用于深度故障追踪；日常判断以上面列出的具体问题为准。</div>'}
        function setBusy(t){document.getElementById('summary').textContent=t||'正在重新检查…';document.getElementById('badge').className='badge warn';document.getElementById('badge').textContent='检查中'}window.LinkHubDiagnostic={render,setBusy};
        </script></body></html>
      HTML
    end

    def show_linkhub_diagnostic_dialog(payload, model = Sketchup.active_model)
      data = payload.is_a?(Hash) ? payload : {}
      json = JSON.generate(data).gsub('</', '<\\/')
      if @linkhub_diagnostic_dialog && @linkhub_diagnostic_dialog.visible?
        @linkhub_diagnostic_dialog.bring_to_front
        @linkhub_diagnostic_dialog.execute_script("window.LinkHubDiagnostic.render(#{json})")
        return true
      end
      dialog = UI::HtmlDialog.new(dialog_title: 'SU LinkHub · 全面检查', preferences_key: 'SU_LinkHub_Diagnostic', scrollable: true, resizable: true, width: 650, height: 600, style: UI::HtmlDialog::STYLE_DIALOG)
      dialog.set_html(diagnostic_dialog_html)
      dialog.add_action_callback('rerun_diagnostic') do |_ctx|
        safe_callback('重新全面检查') do
          dialog.execute_script("window.LinkHubDiagnostic.setBusy('正在重新检查协同、占用、路径、代理与发布状态…')") if dialog.visible?
          run_linkhub_full_check(model, repair: true, notify: true)
        end
      end
      dialog.add_action_callback('open_settings') do |_ctx|
        safe_callback('打开项目设置') { show_project_settings_dialog(model) }
      end
      dialog.add_action_callback('close_diagnostic') { |_ctx| dialog.close }
      dialog.set_on_closed { @linkhub_diagnostic_dialog = nil }
      @linkhub_diagnostic_dialog = dialog
      dialog.show
      runtime_start_timer(0.05, false, label: 'diagnostic_dialog_seed') do
        next unless dialog.visible?
        dialog.execute_script("window.LinkHubDiagnostic.render(#{json})")
      end
      true
    rescue StandardError => e
      log_exception('显示全面检查结果失败', e)
      false
    end

    # 抽屉盾牌按钮执行的完整检查。它不会加载任何外部 SKP，也不会清理用户模型；
    # 自动修复仅限运行时残留标记、过期候选临时文件和缓存索引。
    def run_linkhub_full_check(model = Sketchup.active_model, repair: true, notify: true)
      started = monotonic_time
      issues = []
      warnings = []
      fixes = []
      metrics = {}
      details = {}
      previous_crash = @last_recovered_publish_crash || recover_unfinished_publish_journal!(notify: false)
      if previous_crash
        issues << "上次发布疑似原生崩溃，最后阶段：#{previous_crash['stage']}（#{previous_crash['subject']}）"
        details['previous_publish_crash'] = previous_crash
      end
      details['last_publish_stage_file'] = File.file?(publish_last_stage_path) ? File.read(publish_last_stage_path, encoding: 'UTF-8') : ''
      details['recent_publish_history'] = diagnostic_recent_publish_history(20)
      metrics['diagnostic_root'] = diagnostic_root
      metrics['runtime_log'] = LOG_PATH

      unless model
        issues << '当前 SketchUp 模型不可用。'
      else
        metrics['model_title'] = model.title.to_s
        metrics['model_path'] = model.path.to_s
        metrics['active_path_depth'] = Array(model.active_path).length
        warnings << '当前仍在组件编辑层级内；发布前必须先退出到模型根层级。' unless model.active_path.nil?
        if model.path.to_s.empty?
          warnings << '当前工作 SU 尚未命名保存；硬装/软装空间仍可使用发布恢复快照，但建议先保存一次工作 SU 以获得稳定项目路径。'
        else
          dir_ok, dir_detail = diagnostic_write_test(File.dirname(model.path.to_s))
          issues << "当前工作 SU 文件夹不可写：#{dir_detail}" unless dir_ok
        end
      end

      state = model ? load_state(model) : nil
      if state.is_a?(Hash)
        host = host_discipline_for(state)
        metrics['workspace'] = host
        metrics['space_count'] = Array(state['space_models']).length
        begin
          connection = collaboration_connection_info(state, model)
          details['connection'] = connection
          unless connection['connected'] == true
            issues << "协同项目连接异常：#{connection['message'].to_s.empty? ? '当前没有有效协同连接' : connection['message']}"
          end
        rescue StandardError => e
          issues << "协同项目连接检查失败：#{e.message}"
        end
        begin
          project_paths = current_project_path_settings(model, force: true)
          details['project_paths'] = project_paths
          project_paths.each do |key, path|
            next if path.to_s.empty?
            label = PROJECT_PATH_SETTING_KEYS[key.to_s] || key.to_s
            unless Dir.exist?(path.to_s)
              issues << "项目固定路径不存在（#{label}）：#{path}"
              next
            end
            readable = File.readable?(path.to_s) rescue false
            warnings << "项目固定路径不可读（#{label}）：#{path}" unless readable
          end
          update_status = plugin_update_status(model, force: true)
          details['plugin_update_status'] = update_status
          warnings << "插件更新检查异常：#{update_status[:error]}" unless update_status[:error].to_s.empty?
          metrics['plugin_update_available'] = update_status[:available] == true
          metrics['plugin_update_version'] = update_status[:version].to_s
        rescue StandardError => e
          warnings << "项目固定路径检查失败：#{e.message}"
        end
        source_paths = []
        %w[architecture landscape].each do |key|
          next if key == 'architecture' && architecture_collection_active?(state, model)
          link = state.dig('links', key) || {}
          path = resolve_path(link['collab_full_path'].to_s.empty? ? link['model_path'].to_s : link['collab_full_path'].to_s, model)
          next if path.to_s.empty?
          source_paths << path
          unless File.file?(path)
            warnings << "#{DISCIPLINES.dig(key, 'name')}共享 SKP 不存在：#{path}"
            next
          end
          dir_ok, dir_detail = diagnostic_write_test(File.dirname(path))
          issues << "#{DISCIPLINES.dig(key, 'name')}共享目录不可写：#{dir_detail}" unless dir_ok
          entities = managed_model_entities(model, discipline: key)
          warnings << "模型中发现 #{entities.length} 个#{DISCIPLINES.dig(key, 'name')}受管根组件，正常应为 1 个。" if entities.length > 1
          metrics["#{key}_source_bytes"] = File.size(path) rescue 0
          lock = source_lock_info(path, link, model, state) rescue nil
          details["#{key}_lock"] = lock if lock.is_a?(Hash)
          if lock.is_a?(Hash) && lock['exists'] && !lock['stale'] && !lock['owned']
            warnings << "#{DISCIPLINES.dig(key, 'name')}当前由 #{lock['owner']}@#{lock['host']} 占用。"
          end
          checkpoint = latest_safe_publish_checkpoint_status(path, key) rescue nil
          details["#{key}_latest_safe_checkpoint"] = checkpoint if checkpoint.is_a?(Hash)
          if checkpoint.is_a?(Hash) && checkpoint['drift']
            issues << "#{DISCIPLINES.dig(key, 'name')}共享 SKP 与最近安全发布快照内容不一致。可能被旧版插件、旧会话或外部程序覆盖；继续编辑/发布前请先核对并保留两份文件。"
          end
        end

        # 共享清单的顶层 plugin_version 能帮助快速判断“最近一次清单写入”是否来自
        # 旧版客户端。旧版本本身不会理解新协议，所以这里只做取证告警；完整保护仍要求
        # 项目成员统一升级。
        begin
          manifest_path = space_models_manifest_path(state, model)
          if File.file?(manifest_path)
            manifest_data = read_json_file(manifest_path) rescue {}
            manifest_version = manifest_data['plugin_version'].to_s
            details['space_manifest_plugin_version'] = manifest_version unless manifest_version.empty?
            if !manifest_version.empty? && compare_linkhub_versions(manifest_version, COLLAB_DATA_SAFETY_MIN_VERSION).negative?
              warnings << "空间共享清单最近由旧版 SU LinkHub v#{manifest_version} 写入；该版本低于 v#{COLLAB_DATA_SAFETY_MIN_VERSION} 当前协同安全基线，可能缺少空间编辑域、内部锁防误操作或发布保护。请确认所有成员已升级。"
            end
          end
        rescue StandardError => e
          warnings << "读取空间共享清单发布版本失败：#{e.message}"
        end

        Array(state['space_models']).each do |item|
          path = auto_relocate(item['model_path'].to_s, model)
          source_paths << path unless path.to_s.empty?
          entity = space_model_entity(item['id'], model)
          warnings << "空间 #{item['number']}:#{item['name']} 在清单中存在，但模型根组件未载入。" unless entity && entity.valid?
          (details['space_publish_attribution'] ||= {})[item['id'].to_s] = {
            'published_at' => item['last_publish_at'].to_s,
            'published_by' => item['last_publish_by'].to_s,
            'published_host' => item['last_publish_host'].to_s,
            'plugin_version' => item['last_publish_plugin_version'].to_s
          }
          item_version = item['last_publish_plugin_version'].to_s
          if !item_version.empty? && compare_linkhub_versions(item_version, COLLAB_DATA_SAFETY_MIN_VERSION).negative?
            warnings << "空间 #{item['number']}:#{item['name']} 最近记录的发布版本为 SU LinkHub v#{item_version}，低于当前协同数据安全基线。"
          end
          next if path.to_s.empty?
          warnings << "空间 #{item['number']}:#{item['name']} 的共享 SKP 不存在：#{path}" unless File.file?(path)
          lock = space_lock_info(item, model, source_path: path, state: state) rescue nil
          if lock.is_a?(Hash) && lock['exists'] && !lock['stale'] && !lock['owned']
            warnings << "空间 #{item['number']}:#{item['name']} 当前由 #{lock['owner']}@#{lock['host']} 占用。"
          end
          checkpoint = latest_safe_publish_checkpoint_status(path, "space_#{item['id']}") rescue nil
          if checkpoint.is_a?(Hash)
            (details['space_latest_safe_checkpoints'] ||= {})[item['id'].to_s] = checkpoint
            if checkpoint['drift']
              issues << "空间 #{item['number']}:#{item['name']} 的共享 SKP 与最近安全发布快照内容不一致。高度怀疑旧版插件/旧会话/外部覆盖；请先停止发布并核对安全快照。"
            end
          end
        end

        root_soft = root_level_managed_soft_instances(model)
        unless root_soft.empty?
          details['root_level_soft_models'] = root_soft.first(50).map do |soft|
            metadata = soft_instance_metadata(soft)
            {
              'name' => metadata['model_name'].to_s,
              'model_id' => metadata['model_id'].to_s,
              'host_space_id' => soft.get_attribute(SOFT_MODEL_DICT, 'host_space_id', '').to_s,
              'placed_at' => soft.get_attribute(SOFT_MODEL_DICT, 'placed_at', '').to_s,
              'placed_plugin_version' => soft.get_attribute(SOFT_MODEL_DICT, 'placed_plugin_version', '').to_s
            }
          rescue StandardError
            {}
          end
          issues << "模型根层级发现 #{root_soft.length} 个受管软装实例。空间发布只保存空间根定义，这些根层级软装不会进入任何空间共享 SKP，属于明确的数据丢失风险；请先定位并移回正确空间。"
        end

        if architecture_collection_active?(state, model)
          begin
            manifest_path = architecture_models_manifest_path(state, model)
            if File.file?(manifest_path)
              manifest_data = read_json_file(manifest_path) rescue {}
              manifest_version = manifest_data['plugin_version'].to_s
              details['architecture_manifest_plugin_version'] = manifest_version unless manifest_version.empty?
              if !manifest_version.empty? && compare_linkhub_versions(manifest_version, COLLAB_DATA_SAFETY_MIN_VERSION).negative?
                warnings << "建筑共享清单最近由旧版 SU LinkHub v#{manifest_version} 写入；请确认所有成员统一升级到 v#{COLLAB_DATA_SAFETY_MIN_VERSION} 或更高版本。"
              end
            end
          rescue StandardError => e
            warnings << "读取建筑共享清单发布版本失败：#{e.message}"
          end
          Array(state['architecture_models']).each do |item|
            entity = architecture_model_entity(item['id'], model)
            warnings << "建筑 #{architecture_display_name(item, state)} 在清单中存在，但根组件尚未载入。" unless entity && entity.valid?
            (details['architecture_publish_attribution'] ||= {})[item['id'].to_s] = {
              'published_at' => item['last_publish_at'].to_s,
              'published_by' => item['last_publish_by'].to_s,
              'published_host' => item['last_publish_host'].to_s,
              'plugin_version' => item['last_publish_plugin_version'].to_s
            }
            item_version = item['last_publish_plugin_version'].to_s
            if !item_version.empty? && compare_linkhub_versions(item_version, COLLAB_DATA_SAFETY_MIN_VERSION).negative?
              warnings << "建筑 #{architecture_display_name(item, state)} 最近记录的发布版本为 SU LinkHub v#{item_version}，低于当前协同数据安全基线。"
            end
            source = auto_relocate(item['model_path'].to_s, model)
            warnings << "建筑 #{architecture_display_name(item, state)} 的共享 SKP 不存在：#{source}" unless source.to_s.empty? || File.file?(source)
            unless source.to_s.empty?
              checkpoint = latest_safe_publish_checkpoint_status(source, "architecture_model_#{item['id']}") rescue nil
              if checkpoint.is_a?(Hash)
                (details['architecture_latest_safe_checkpoints'] ||= {})[item['id'].to_s] = checkpoint
                if checkpoint['drift']
                  issues << "建筑 #{architecture_display_name(item, state)} 的共享 SKP 与最近安全发布快照内容不一致。高度怀疑旧版插件/旧会话/外部覆盖。"
                end
              end
            end
            if entity && entity.valid?
              duplicates = root_architecture_model_entities_for_id(item['id'], model)
              issues << "建筑 #{architecture_display_name(item, state)} 出现 #{duplicates.length} 个重复根组件。" if duplicates.length > 1
            end
          end
        end

        active_root_keys = active_edit_root_keys(state, model)
        structural_issues = active_root_keys.map { |key| [key, protected_root_issue(key, model)] }.reject { |_key, issue| issue.to_s.empty? }
        details['edit_structure_issues'] = structural_issues.map { |key, issue| { 'key' => key, 'issue' => issue } }
        structural_issues.each { |key, issue| issues << "编辑根模型结构异常（#{key}）：#{issue}" }
        unlocked_roots = []
        unexpected_unlocked_roots = []
        %w[architecture landscape].each do |discipline|
          next if discipline == 'architecture' && architecture_collection_active?(state, model)
          entity = native_edit_entity(discipline, model)
          next unless entity && entity.valid? && !entity_native_locked?(entity)
          unlocked_roots << discipline
          link = state.dig('links', discipline) || {}
          unexpected_unlocked_roots << discipline unless managed_discipline_local_edit_active?(discipline, state, model) || link['preview_edit_active']
        end
        Array(state['space_models']).each do |item|
          entity = space_model_entity(item['id'], model)
          next unless entity && entity.valid? && !entity_native_locked?(entity)
          key = "space:#{item['id']}"
          unlocked_roots << key
          unexpected_unlocked_roots << key unless local_space_edit_session?(item, state, model)
        end
        Array(state['architecture_models']).each do |item|
          entity = architecture_model_entity(item['id'], model)
          next unless entity && entity.valid? && !entity_native_locked?(entity)
          key = edit_root_key_for_architecture_model(item['id'])
          unlocked_roots << key
          unexpected_unlocked_roots << key unless local_architecture_model_edit_session?(item, state, model)
        end
        metrics['unlocked_managed_roots'] = unlocked_roots
        metrics['unexpected_unlocked_managed_roots'] = unexpected_unlocked_roots
        warnings << "发现未取得有效修改会话却保持解锁的受管根模型：#{unexpected_unlocked_roots.join('、')}。" unless unexpected_unlocked_roots.empty?

        artifacts = diagnostic_publish_artifacts(source_paths)
        details['publish_artifacts'] = artifacts
        artifacts.each do |artifact|
          case artifact['kind']
          when 'rollback'
            warnings << "发现发布回滚文件，请保留并检查：#{artifact['path']}"
          when 'temp'
            if repair && artifact['age_seconds'].to_i > 1800
              begin
                File.delete(artifact['path'])
                fixes << "已删除超过 30 分钟的发布候选临时文件：#{artifact['path']}"
              rescue StandardError => e
                warnings << "无法清理发布临时文件：#{artifact['path']}（#{e.message}）"
              end
            else
              warnings << "发现尚未清理的发布候选文件：#{artifact['path']}"
            end
          when 'write_temp'
            if repair && artifact['age_seconds'].to_i > 1800
              begin
                File.delete(artifact['path'])
                fixes << "已删除写入中断遗留的临时文件：#{artifact['path']}"
              rescue StandardError => e
                warnings << "无法清理写入中断遗留的临时文件：#{artifact['path']}（#{e.message}）"
              end
            elsif artifact['age_seconds'].to_i > 1800
              warnings << "发现写入中断遗留的临时文件（可用自检修复清理）：#{artifact['path']}"
            end
          end
        end
      else
        issues << '当前模型中的 LinkHub 项目状态无法读取。'
      end

      metrics['runtime_generation'] = @runtime_generation.to_i
      metrics['runtime_timer_count'] = runtime_timer_registry.length
      metrics['runtime_keyed_timer_count'] = runtime_timer_key_registry.length
      metrics['space_prefetch_job_count'] = (@space_batch_prefetch_jobs || {}).length
      metrics['safe_callback_active'] = (@safe_callback_active || {}).dup
      metrics['soft_heavy_interaction_started_at'] = (@soft_heavy_interaction_started_at || {}).dup
      metrics['publish_in_progress'] = publish_critical_section?
      metrics['publish_quiet_remaining'] = publish_quiet_remaining.round(3)
      metrics['soft_heavy_interactions'] = (@soft_heavy_interactions || {}).dup
      details['runtime_timers'] = runtime_timer_diagnostics

      if repair && !publish_critical_section?
        @architecture_explicit_publish_in_progress = false
        @space_explicit_publish_in_progress = false
        @space_publish_in_progress = false
        @space_publish_after_proxy = {}
        @publish_presave_in_progress = false
        @syncing_native_preview_state = false
        @soft_full_cleanup_tokens = {}
        cancel_soft_cache_warmup!
        invalidate_managed_root_index(model, reason: 'full_diagnostic') if model
        schedule_edit_structure_audit(model, 0.02) if model
        fixes << '已重置无活动发布任务的运行时发布标记，取消可能重叠的后台任务，并安排根模型结构复核。'
      end

      begin
        refresh_linkhub_status(model, notify: false) if model
      rescue StandardError => e
        warnings << "协同状态刷新失败：#{e.message}"
      end

      txt_path, json_path = diagnostic_report_paths
      payload = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'generated_at' => Time.now.iso8601(6),
        'user' => current_user_name,
        'host' => current_host_name,
        'pid' => Process.pid,
        'issues' => issues,
        'warnings' => warnings,
        'fixes' => fixes,
        'issue_items' => issues.map { |message| { 'message' => message, 'advice' => diagnostic_advice_for(message) } },
        'warning_items' => warnings.map { |message| { 'message' => message, 'advice' => diagnostic_advice_for(message) } },
        'fix_items' => fixes.map { |message| { 'message' => message, 'advice' => '' } },
        'metrics' => metrics,
        'details' => details,
        'elapsed_ms' => elapsed_ms(started)
      }
      durable_write_file(json_path, JSON.pretty_generate(payload))
      text = []
      text << "SU LinkHub v#{EXTENSION_VERSION} 全面自检"
      text << "时间：#{payload['generated_at']}"
      text << "工作 SU：#{metrics['model_path']}"
      text << "工作区：#{metrics['workspace']}"
      text << ''
      text << "严重问题（#{issues.length}）"
      text.concat(issues.empty? ? ['- 无'] : issues.map { |item| "- #{item}" })
      text << ''
      text << "警告（#{warnings.length}）"
      text.concat(warnings.empty? ? ['- 无'] : warnings.map { |item| "- #{item}" })
      text << ''
      text << "已修复（#{fixes.length}）"
      text.concat(fixes.empty? ? ['- 无'] : fixes.map { |item| "- #{item}" })
      text << ''
      text << "JSON 详细报告：#{json_path}"
      durable_write_file(txt_path, text.join("\n") + "\n")
      summary = "自检完成：#{issues.length} 个严重问题，#{warnings.length} 个警告，#{fixes.length} 项已自动处理。"
      @last_full_check_payload = payload
      if notify
        show_status(summary, issues.empty? ? (warnings.empty? ? 'success' : 'warning') : 'error')
        shown = show_linkhub_diagnostic_dialog(payload, model)
        show_native_notice([summary, *(issues + warnings).first(6)].join("\n"), issues.empty? ? 'warning' : 'error') unless shown
      end
      log("#{summary} 技术报告：#{txt_path}")
      txt_path
    rescue StandardError => e
      log_exception('执行 LinkHub 全面自检失败', e)
      show_native_notice("全面自检失败：#{e.message}", 'error') if notify
      ''
    end

    # 所有运行时定时任务统一登记，并绑定当前热重载 generation。
    # 旧运行时即使已有一次性回调排队，热重载后也只会静默退出，不能再修改新状态。
    def runtime_timer_registry
      @runtime_timer_registry ||= {}
    end

    def runtime_timer_key_registry
      @runtime_timer_key_registry ||= {}
    end

    def runtime_model_token(model)
      return '' unless model
      guid = model.respond_to?(:guid) ? model.guid.to_s : ''
      path = model.respond_to?(:path) ? model.path.to_s : ''
      [model.object_id, guid, path].join('|')
    rescue StandardError
      model ? model.object_id.to_s : ''
    end

    def runtime_model_callback_valid?(model, token, active_model_only = false)
      return true unless model
      return false if active_model_only && Sketchup.active_model != model
      runtime_model_token(model) == token.to_s
    rescue StandardError
      false
    end

    # v0.13.6.166：Observer/Timer 内部维护事务必须与用户事务隔离。
    # 使用深度计数而不是单一布尔值，允许一个内部同步安全地调用另一个内部同步。
    def internal_sync_active?
      @internal_sync_depth.to_i.positive?
    rescue StandardError
      false
    end

    # v0.13.6.170：轻量事件总线先承担跨子系统“通知”职责，逐步替代 Runtime 内部
    # 为了刷新 UI/缓存而层层直接调用。listener 异常隔离，不允许一个 UI 监听器破坏主流程。
    def runtime_event_listeners
      @runtime_event_listeners ||= Hash.new { |hash, key| hash[key] = [] }
    end

    def on_runtime_event(event, key: nil, &block)
      return nil unless block
      token = key.to_s.empty? ? "evt-#{SecureRandom.hex(6)}" : key.to_s
      bucket = runtime_event_listeners[event.to_sym]
      bucket.reject! { |row| row[:token].to_s == token }
      bucket << { token: token, callback: block }
      token
    rescue StandardError
      nil
    end

    def off_runtime_event(event, token)
      bucket = runtime_event_listeners[event.to_sym]
      before = bucket.length
      bucket.reject! { |row| row[:token].to_s == token.to_s }
      before != bucket.length
    rescue StandardError
      false
    end

    def emit_runtime_event(event, *args)
      Array(runtime_event_listeners[event.to_sym]).dup.each do |row|
        callback = row[:callback]
        next unless callback
        callback.call(*args)
      rescue StandardError => e
        log_exception("运行时事件监听失败（#{event}）", e) rescue nil
      end
      true
    rescue StandardError
      false
    end

    def clear_runtime_event_listeners!
      @runtime_event_listeners = Hash.new { |hash, key| hash[key] = [] }
      true
    rescue StandardError
      false
    end

    def with_internal_sync_guard
      @internal_sync_depth = @internal_sync_depth.to_i + 1
      yield
    ensure
      @internal_sync_depth = [@internal_sync_depth.to_i - 1, 0].max
    end

    # 所有后台/纠错型模型事务统一走这里，保证异常时一定 abort，不把半截 operation
    # 留在 SketchUp 撤销栈里。transparent 由调用点显式决定；默认绝不偷偷并入用户操作。
    def safe_model_operation(model, name, disable_ui: true, next_transparent: false, transparent: false, internal_sync: true)
      return yield unless model && model.respond_to?(:start_operation)
      runner = proc do
        operation_open = false
        committed = false
        begin
          model.start_operation(name.to_s, !!disable_ui, !!next_transparent, !!transparent)
          operation_open = true
          result = yield
          model.commit_operation
          committed = true
          operation_open = false
          result
        ensure
          # ensure 也覆盖 block 内的非局部 return/break，避免将来调用点提前退出时
          # 遗留一个没有 commit/abort 的 SketchUp operation。异常继续原样向外抛出。
          model.abort_operation rescue nil if operation_open && !committed
        end
      end
      internal_sync ? with_internal_sync_guard { runner.call } : runner.call
    end

    def runtime_forget_timer(timer_id)
      record = runtime_timer_registry.delete(timer_id) if timer_id
      key = record.is_a?(Hash) ? record[:key].to_s : ''
      runtime_timer_key_registry.delete(key) if !key.empty? && runtime_timer_key_registry[key] == timer_id
      true
    rescue StandardError
      false
    end

    # key 用于“最后一次请求获胜”的高频任务，例如选择刷新、模型资源复核、抽屉刷新。
    # model + active_model_only 可阻止切换 SU 文档后旧回调继续作用到新活动模型。
    def runtime_start_timer(seconds, repeat = false, label: nil, key: nil, model: nil, active_model_only: false, &callback)
      return nil unless callback
      generation = @runtime_generation.to_i
      task_label = label.to_s
      if task_label.empty?
        location = caller_locations(1, 1)&.first
        task_label = location ? "#{File.basename(location.path)}:#{location.lineno}" : 'anonymous'
      end
      timer_key = key.to_s
      if !timer_key.empty? && (previous = runtime_timer_key_registry[timer_key])
        runtime_stop_timer(previous)
      end
      model_token = runtime_model_token(model)
      owner = self
      timer_id = nil
      timer_id = ::UI.start_timer(seconds.to_f, !!repeat) do
        begin
          active = !owner.instance_variable_get(:@shutting_down) &&
                   owner.instance_variable_get(:@runtime_generation).to_i == generation
          model_active = owner.runtime_model_callback_valid?(model, model_token, active_model_only)
          unless active && model_active
            owner.runtime_stop_timer(timer_id) if repeat && timer_id
            next
          end
          if owner.publish_critical_section? && !owner.publish_timer_allowed?(task_label)
            # 重复监视器本轮直接跳过；一次性回调延后，不能在原生 save/save_as
            # 临界区中扫描定义、刷新 HtmlDialog 或改写模型状态。
            unless repeat
              owner.runtime_start_timer(
                0.35, false, label: task_label, key: timer_key, model: model,
                active_model_only: active_model_only, &callback
              )
            end
            next
          end
          callback_started = owner.monotonic_time
          callback.call
          owner.log_slow_operation("定时任务 #{task_label}", callback_started, 150.0)
        rescue LocalJumpError
          nil
        rescue StandardError => e
          owner.log_exception("定时任务失败（#{task_label}）", e)
        ensure
          owner.runtime_forget_timer(timer_id) unless repeat
        end
      end
      runtime_timer_registry[timer_id] = {
        repeat: !!repeat,
        generation: generation,
        label: task_label,
        key: timer_key,
        model_token: model_token,
        active_model_only: !!active_model_only,
        started_at: monotonic_time
      }
      runtime_timer_key_registry[timer_key] = timer_id unless timer_key.empty?
      timer_id
    rescue StandardError => e
      log_exception('创建运行时定时任务失败', e)
      nil
    end

    def runtime_stop_timer(timer_id)
      return false unless timer_id
      begin
        ::UI.stop_timer(timer_id)
      ensure
        runtime_forget_timer(timer_id)
      end
      true
    rescue StandardError
      runtime_forget_timer(timer_id)
      false
    end

    # v0.13.6.189：后台线程 GVL 让渡泵。
    # SketchUp 主线程回到自己的消息循环时仍持有 Ruby GVL；后台 Ruby 线程每做完一次
    # 文件操作都要等主线程下一次执行 Ruby 才能拿回 GVL。旧诊断日志里“网络替换完成 →
    # 复用内容校验”这类纯内存步骤之间出现 5~11 秒空档，旧注释里“NAS 读回 SHA 要
    # 16~60 秒”也是同一原因（NAS 实测顺序读约 110MB/s）。存在后台工作线程时，这里用
    # 一个 50ms 的轻量定时器短暂 sleep，把 GVL 交给后台线程连续完成多次 I/O；
    # 定时器迟到（主线程正忙）或用户刚操作时只让出 3ms，不影响建模手感。
    # 所有后台线程结束后定时器自动停止，空闲时零开销。
    def register_background_gvl_thread!(thread)
      return thread unless thread.is_a?(Thread)
      @background_gvl_threads_mutex ||= Mutex.new
      @background_gvl_threads_mutex.synchronize do
        @background_gvl_threads ||= []
        @background_gvl_threads.select!(&:alive?)
        @background_gvl_threads << thread unless @background_gvl_threads.include?(thread)
      end
      ensure_background_gvl_pump!
      thread
    rescue StandardError
      thread
    end

    def background_gvl_threads_alive?
      @background_gvl_threads_mutex ||= Mutex.new
      @background_gvl_threads_mutex.synchronize do
        @background_gvl_threads ||= []
        @background_gvl_threads.select!(&:alive?)
        !@background_gvl_threads.empty?
      end
    rescue StandardError
      false
    end

    # 只在 SketchUp UI 线程创建定时器；后台线程里登记的新线程由已在运行的泵覆盖
    # （线程重启总是在旧线程退出前登记，泵不会出现空窗）。
    def ensure_background_gvl_pump!
      return false if @shutting_down
      return false unless Thread.current.object_id == SKETCHUP_UI_THREAD_OBJECT_ID
      return true if @background_gvl_pump_timer
      @background_gvl_pump_last_tick = monotonic_time
      @background_gvl_pump_timer = runtime_start_timer(
        BACKGROUND_GVL_PUMP_INTERVAL, true, label: 'background:gvl_handoff', key: 'background:gvl_handoff'
      ) do
        background_gvl_pump_tick!
      end
      !@background_gvl_pump_timer.nil?
    rescue StandardError
      false
    end

    def stop_background_gvl_pump!
      timer = @background_gvl_pump_timer
      @background_gvl_pump_timer = nil
      runtime_stop_timer(timer) if timer
      true
    rescue StandardError
      @background_gvl_pump_timer = nil
      false
    end

    def background_gvl_pump_tick!
      now = monotonic_time
      gap = now - @background_gvl_pump_last_tick.to_f
      @background_gvl_pump_last_tick = now
      unless background_gvl_threads_alive?
        stop_background_gvl_pump!
        return false
      end
      model = Sketchup.active_model
      last_interaction = model ? (@runtime_last_interaction_at || {})[model.object_id].to_f : 0.0
      input_idle = system_input_idle_seconds
      busy = gap > BACKGROUND_GVL_PUMP_INTERVAL * 2.4 ||
             (input_idle && input_idle < BACKGROUND_GVL_PUMP_INTERACTION_SECONDS) ||
             (last_interaction.positive? && (now - last_interaction) < BACKGROUND_GVL_PUMP_INTERACTION_SECONDS) ||
             soft_heavy_interaction?
      sleep(busy ? BACKGROUND_GVL_PUMP_BUSY_SLICE : BACKGROUND_GVL_PUMP_IDLE_SLICE)
      true
    rescue StandardError
      false
    end

    # 距离最近一次鼠标/键盘输入的秒数（Windows GetLastInputInfo）。画线、拖动、
    # 旋转视图都不经过 LinkHub 回调，只能用系统输入时间判断“用户正在操作”。
    # 不可用（非 Windows / 无 Fiddle）时返回 nil，泵退回定时器迟到判断。
    def system_input_idle_seconds
      return nil unless windows_platform?
      if @system_input_idle_api.nil?
        @system_input_idle_api = begin
          require 'fiddle'
          user32 = Fiddle.dlopen('user32')
          kernel32 = Fiddle.dlopen('kernel32')
          {
            last_input: Fiddle::Function.new(user32['GetLastInputInfo'], [Fiddle::TYPE_VOIDP], Fiddle::TYPE_INT),
            tick: Fiddle::Function.new(kernel32['GetTickCount'], [], Fiddle::TYPE_INT)
          }
        rescue StandardError, LoadError
          false
        end
      end
      api = @system_input_idle_api
      return nil unless api
      info = [8, 0].pack('LL')
      return nil if api[:last_input].call(info).to_i.zero?
      last = info.unpack('LL')[1].to_i
      now = api[:tick].call.to_i & 0xFFFFFFFF
      ((now - last) & 0xFFFFFFFF) / 1000.0
    rescue StandardError
      nil
    end

    # v0.13.6.75：顶部“发布队列”升级为统一任务中心。发布仍使用自己的严格队列，
    # 但 Excel、清单刷新、模型库/材质库扫描等明显耗时任务会以统一快照显示在同一
    # 左上角面板中。后台线程只更新 Ruby 内存任务状态；真正 UI 刷新仍由主线程 timer 完成。
    def task_center_trace!(message)
      stamp = Time.now.strftime('%Y-%m-%d %H:%M:%S.%L')
      @task_center_trace_mutex ||= Mutex.new
      @task_center_trace_mutex.synchronize do
        File.open(TASK_CENTER_TRACE_PATH, 'ab') do |file|
          file.write("[#{stamp}] #{message}\n".encode('UTF-8'))
          file.flush
        end
      end
      true
    rescue StandardError
      false
    end

    def task_center_visible_io_kind?(kind)
      %w[xlsx_write soft_library_directory_scan landscape_library_scan material_library_scan].include?(kind.to_s)
    end

    def task_center_registry
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
    end

    def start_task_center_job!(kind, label:, task_id: nil, stage: '等待开始', progress: 0, detail: '', status: 'queued')
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      id = task_id.to_s.strip
      id = "task-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}" if id.empty?
      now = Time.now.iso8601(6)
      @task_center_mutex.synchronize do
        existing = @task_center_registry[id]
        if existing
          existing[:kind] = kind.to_s unless kind.to_s.empty?
          existing[:label] = label.to_s unless label.to_s.empty?
          existing[:status] = status.to_s unless status.to_s.empty?
          existing[:stage_label] = stage.to_s unless stage.to_s.empty?
          existing[:progress] = progress.to_i
          existing[:stage_detail] = detail.to_s
          existing[:stage_at] = now
        else
          @task_center_registry[id] = {
            task_id: id, kind: kind.to_s, label: label.to_s, status: status.to_s,
            stage: stage.to_s, stage_label: stage.to_s, progress: progress.to_i,
            stage_detail: detail.to_s, queued_at: now, started_at: (status.to_s == 'running' ? now : ''),
            finished_at: '', stage_at: now, error_message: ''
          }
        end
      end
      task_center_trace!("START id=#{id} kind=#{kind} label=#{label} status=#{status} progress=#{progress}% stage=#{stage} detail=#{detail}")
      id
    rescue StandardError => e
      log_exception('创建统一任务中心任务失败', e)
      ''
    end

    def update_task_center_job!(task_id, progress: nil, stage: nil, detail: nil, status: nil)
      id = task_id.to_s
      return false if id.empty?
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      snapshot = nil
      should_trace = false
      @task_center_mutex.synchronize do
        job = @task_center_registry[id]
        return false unless job
        now = Time.now.iso8601(6)
        old_progress = job[:progress].to_i
        old_stage = job[:stage_label].to_s
        old_status = job[:status].to_s
        job[:progress] = [[progress.to_i, 0].max, 100].min unless progress.nil?
        unless stage.nil?
          job[:stage] = stage.to_s
          job[:stage_label] = stage.to_s
          job[:stage_at] = now if old_stage != stage.to_s
        end
        job[:stage_detail] = detail.to_s unless detail.nil?
        unless status.nil?
          job[:status] = status.to_s
          job[:started_at] = now if status.to_s == 'running' && job[:started_at].to_s.empty?
          job[:finished_at] = now if %w[completed failed cancelled].include?(status.to_s)
          job[:progress] = 100 if %w[completed failed cancelled].include?(status.to_s)
          job[:stage_at] = now if old_status != status.to_s
        end
        should_trace = old_stage != job[:stage_label].to_s || old_status != job[:status].to_s || (job[:progress].to_i - old_progress).abs >= 5
        snapshot = job.dup
      end
      task_center_trace!("STAGE id=#{id} kind=#{snapshot[:kind]} status=#{snapshot[:status]} progress=#{snapshot[:progress]}% stage=#{snapshot[:stage_label]} detail=#{snapshot[:stage_detail]}") if snapshot && should_trace
      true
    rescue StandardError => e
      log_exception('更新统一任务中心失败', e)
      false
    end

    def finish_task_center_job!(task_id, success: true, stage: nil, detail: '', cancelled: false, error: nil)
      status = cancelled ? 'cancelled' : (success ? 'completed' : 'failed')
      label = stage.to_s
      label = cancelled ? '已取消' : (success ? '完成' : '失败') if label.empty?
      id = task_id.to_s
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      @task_center_mutex.synchronize do
        job = @task_center_registry[id]
        if job
          job[:error_message] = error ? error.message.to_s : ''
        end
      end
      update_task_center_job!(id, progress: 100, stage: label, detail: detail, status: status)
    end

    def task_center_job_snapshot(task_id)
      id = task_id.to_s
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      @task_center_mutex.synchronize do
        row = @task_center_registry[id]
        row ? row.dup : nil
      end
    rescue StandardError
      nil
    end

    def task_center_nonpublish_snapshot
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      rows = @task_center_mutex.synchronize do
        @task_center_registry.values.map do |row|
          queued_at = row[:queued_at].to_s
          finished_at = row[:finished_at].to_s
          elapsed = begin
            if !queued_at.empty?
              finish = finished_at.empty? ? Time.now : Time.iso8601(finished_at)
              [(finish - Time.iso8601(queued_at)).to_i, 0].max
            else
              0
            end
          rescue StandardError
            0
          end
          stage_elapsed = begin
            stamp = row[:stage_at].to_s
            stamp.empty? ? 0 : [(Time.now - Time.iso8601(stamp)).to_i, 0].max
          rescue StandardError
            0
          end
          {
            'job_id' => row[:task_id].to_s, 'space_id' => '', 'job_kind' => row[:kind].to_s,
            'label' => row[:label].to_s, 'status' => row[:status].to_s,
            'queued_at' => queued_at, 'started_at' => row[:started_at].to_s, 'finished_at' => finished_at,
            'published_at' => '', 'publish_elapsed_seconds' => 0,
            'target' => '', 'candidate' => '', 'stage' => row[:stage].to_s,
            'stage_label' => row[:stage_label].to_s, 'progress' => row[:progress].to_i,
            'stage_detail' => row[:stage_detail].to_s, 'stage_elapsed_seconds' => stage_elapsed,
            'total_elapsed_seconds' => elapsed, 'error' => row[:error_message].to_s,
            'main_finalize_pending' => false, 'history' => []
          }
        end
      end
      active = rows.select { |row| %w[queued running].include?(row['status'].to_s) }
      history = rows - active
      active.sort_by! { |row| row['queued_at'].to_s }
      history.sort_by! { |row| row['finished_at'].to_s }.reverse!
      active + history.first(TASK_CENTER_MAX_HISTORY)
    rescue StandardError
      []
    end

    def task_center_snapshot
      publish_rows = space_publish_queue_snapshot
      generic_rows = task_center_nonpublish_snapshot
      active = (publish_rows + generic_rows).select { |row| %w[queued running success].include?(row['status'].to_s) || row['main_finalize_pending'] == true }
      passive = (publish_rows + generic_rows) - active
      active.sort_by! { |row| row['queued_at'].to_s }
      passive.sort_by! { |row| row['finished_at'].to_s }.reverse!
      active + passive.first([TASK_CENTER_MAX_HISTORY, 24].max)
    rescue StandardError
      space_publish_queue_snapshot
    end

    def task_center_active_count
      task_center_snapshot.count { |row| %w[queued running success].include?(row['status'].to_s) || row['main_finalize_pending'] == true }
    rescue StandardError
      0
    end

    def trim_task_center_history!
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      @task_center_mutex.synchronize do
        inactive = @task_center_registry.values.reject { |row| %w[queued running].include?(row[:status].to_s) }
        inactive.sort_by! { |row| row[:finished_at].to_s }.reverse!
        keep = inactive.first(TASK_CENTER_MAX_HISTORY).map { |row| row[:task_id].to_s }
        @task_center_registry.delete_if { |_id, row| !%w[queued running].include?(row[:status].to_s) && !keep.include?(row[:task_id].to_s) }
      end
      true
    rescue StandardError
      false
    end

    def clear_completed_task_center_history!
      clear_completed_space_publish_history!
      @task_center_mutex ||= Mutex.new
      @task_center_registry ||= {}
      @task_center_mutex.synchronize do
        @task_center_registry.delete_if { |_id, row| !%w[queued running].include?(row[:status].to_s) }
      end
      refresh_workspace_toolbar(Sketchup.active_model) rescue nil
      true
    rescue StandardError => e
      log_exception('清除任务中心历史失败', e)
      false
    end

    def sync_task_center_overlay_ui!(model = Sketchup.active_model)
      return false unless model
      snapshot = task_center_snapshot
      signature = Digest::SHA1.hexdigest(JSON.generate(snapshot.map { |row| [row['job_id'], row['status'], row['progress'], row['stage_label'], row['stage_detail']] }))
      return false if @task_center_overlay_signature.to_s == signature
      @task_center_overlay_signature = signature
      refresh_publish_queue_overlay_only!(model, snapshot)
    rescue StandardError => e
      log_exception('同步统一任务中心界面失败', e)
      false
    end

    # v0.13.6.69：正式发布队列只服务“共享发布”关键链；缓存写盘、目录扫描、Excel
    # 等低优先级纯文件任务使用独立 I/O worker，避免一个大目录扫描排在发布前面。
    # 注意：这个 worker 绝不允许调用 SketchUp model/entities/definition/material API。
    def enqueue_background_io_task(kind, key:, data: {}, label: '')
      return false if @shutting_down
      @background_io_mutex ||= Mutex.new
      @background_io_queue ||= []
      @background_io_results ||= Queue.new
      kind = kind.to_s
      task_key = "#{kind}|#{key}"
      payload = data.is_a?(Hash) ? data : {}
      resource = case kind
                 when 'json_write' then payload[:path]
                 when 'xlsx_write' then payload[:target]
                 when 'landscape_library_scan', 'material_library_scan', 'soft_library_directory_scan' then payload[:root]
                 end
      resource_key = resource.to_s.empty? ? task_key : "#{kind}|#{FastPath.expand(resource.to_s).downcase}"
      visible_task = task_center_visible_io_kind?(kind)
      requested_task_id = payload[:task_id].to_s
      if visible_task && requested_task_id.empty?
        requested_task_id = start_task_center_job!(
          kind == 'xlsx_write' ? 'excel_export' : 'background_scan',
          label: (label.to_s.empty? ? kind : label.to_s), stage: '等待后台处理', progress: 3
        )
        payload = payload.merge(task_id: requested_task_id)
      end
      @background_io_mutex.synchronize do
        existing = @background_io_queue.reverse.find { |job| job[:task_key].to_s == task_key && job[:status].to_s == 'queued' }
        if existing
          existing[:data] = payload
          existing[:resource_key] = resource_key
          existing[:label] = label.to_s
          existing[:queued_at] = Time.now.iso8601(6)
          existing[:task_id] = requested_task_id unless requested_task_id.empty?
        else
          @background_io_queue << {
            kind: kind, task_key: task_key, resource_key: resource_key, data: payload, label: label.to_s, task_id: requested_task_id,
            status: 'queued', queued_at: Time.now.iso8601(6)
          }
        end
      end
      start_background_io_worker!
      ensure_background_io_poll_timer!
      true
    rescue StandardError => e
      log_exception("加入后台 I/O 队列失败：#{kind}", e)
      false
    end

    def start_background_io_worker!
      return false if @shutting_down
      @background_io_mutex ||= Mutex.new
      @background_io_queue ||= []
      @background_io_results ||= Queue.new
      @background_io_threads ||= []
      @background_io_running_keys ||= {}
      # 185：只在调度边界避让远端正式发布，不中断已经执行的文件操作。
      # 待办留在队列且不占 worker/资源锁；原有 poll 在发布结束后继续调度。
      deferred_kinds = %w[json_write landscape_library_scan material_library_scan soft_library_directory_scan].freeze
      remote_busy = !@shutting_down && background_publish_remote_io_busy185?
      @background_io_mutex.synchronize do
        @background_io_threads.select! { |thread| thread && thread.alive? }
        runnable_keys = @background_io_queue.reject do |job|
          remote_busy && deferred_kinds.include?(job[:kind].to_s)
        end.map { |job| job[:resource_key].to_s }.reject do |resource_key|
          @background_io_running_keys[resource_key]
        end.uniq
        capacity = [BACKGROUND_IO_WORKER_COUNT - @background_io_threads.length, 0].max
        [capacity, runnable_keys.length].min.times do |worker_index|
          thread = Thread.new do
            Thread.current.name = "SU_LinkHub-background-io-#{worker_index + 1}" if Thread.current.respond_to?(:name=)
            begin
              loop do
                job = nil
                busy_now = !@shutting_down && background_publish_remote_io_busy185?
                @background_io_mutex.synchronize do
                  index = @background_io_queue.index do |candidate|
                    !@background_io_running_keys[candidate[:resource_key].to_s] &&
                      !(busy_now && deferred_kinds.include?(candidate[:kind].to_s))
                  end
                  if index
                    job = @background_io_queue.delete_at(index)
                    job[:status] = 'running'
                    @background_io_running_keys[job[:resource_key].to_s] = true
                  end
                end
                break unless job
                started = monotonic_time
                begin
                  task_id = job[:task_id].to_s
                  unless task_id.empty?
                    existing_task = task_center_job_snapshot(task_id)
                    start_progress = [existing_task ? existing_task[:progress].to_i : 0, 8].max
                    update_task_center_job!(task_id, progress: start_progress, stage: '后台任务开始', detail: job[:label].to_s, status: 'running')
                  end
                  result = perform_background_io_task(job[:kind].to_s, job[:data])
                  @background_io_results << { job: job, success: true, result: result, elapsed_ms: elapsed_ms(started) }
                rescue StandardError => e
                  @background_io_results << { job: job, success: false, error: e, elapsed_ms: elapsed_ms(started) }
                ensure
                  @background_io_mutex.synchronize do
                    @background_io_running_keys.delete(job[:resource_key].to_s)
                  end
                end
              end
            ensure
              @background_io_mutex.synchronize do
                @background_io_threads.delete(Thread.current)
              end
            end
          end
          @background_io_threads << thread
          register_background_gvl_thread!(thread)
        end
      end
      true
    rescue StandardError => e
      log_exception('启动后台 I/O worker 失败', e)
      false
    end

    def perform_background_io_task(kind, data)
      case kind.to_s
      when 'json_write'
        path = data[:path].to_s
        raise '后台缓存写入缺少目标路径。' if path.empty?
        FileUtils.mkdir_p(File.dirname(path))
        write_json_atomic(path, data[:payload])
        { path: path }
      when 'xlsx_write'
        target = data[:target].to_s
        raise '后台 Excel 导出缺少目标路径。' if target.empty?
        task_id = data[:task_id].to_s
        FileUtils.mkdir_p(File.dirname(target))
        progress = lambda do |pct, stage, detail = ''|
          update_task_center_job!(task_id, progress: pct, stage: stage, detail: detail, status: 'running') unless task_id.empty?
        end
        write_soft_schedule_xlsx!(target, data[:sheets], progress: progress)
        raise 'Excel 文件未能写出。' unless File.file?(target) && File.size(target).positive?
        { target: target, size: File.size(target) }
      when 'landscape_library_scan'
        task_id = data[:task_id].to_s
        update_task_center_job!(task_id, progress: 22, stage: '扫描景观模型目录', detail: data[:root].to_s, status: 'running') unless task_id.empty?
        result = background_scan_landscape_library_data(data[:root].to_s)
        update_task_center_job!(task_id, progress: 88, stage: '景观目录扫描完成', detail: "#{Array(result[:items]).length} 个模型", status: 'running') unless task_id.empty?
        result
      when 'material_library_scan'
        task_id = data[:task_id].to_s
        update_task_center_job!(task_id, progress: 22, stage: '扫描材质目录', detail: data[:root].to_s, status: 'running') unless task_id.empty?
        result = background_scan_material_library_data(data[:discipline].to_s, data[:root].to_s)
        update_task_center_job!(task_id, progress: 88, stage: '材质目录扫描完成', detail: "#{Array(result[:items]).length} 个材质", status: 'running') unless task_id.empty?
        result
      when 'soft_library_directory_scan'
        root = data[:root].to_s
        organized_root = data[:organized_root].to_s
        task_id = data[:task_id].to_s
        raise '软装模型库目录不可用。' if root.empty? || organized_root.empty?
        update_task_center_job!(task_id, progress: 18, stage: '扫描软装模型库目录', detail: organized_root, status: 'running') unless task_id.empty?
        files = Dir.glob(File.join(organized_root, '**', '*.skp'), File::FNM_CASEFOLD)
        update_task_center_job!(task_id, progress: 82, stage: '目录扫描完成 · 等待主线程合并', detail: "#{files.length} 个 SKP", status: 'running') unless task_id.empty?
        { root: root, files: files, token: data[:token].to_s }
      else
        raise "未知后台 I/O 任务：#{kind}"
      end
    end

    def ensure_background_io_poll_timer!
      return true if @background_io_poll_timer
      @background_io_poll_timer = runtime_start_timer(0.12, true, label: 'background_io:poll', key: 'background_io:poll') do
        drain_background_io_results!
        sync_task_center_overlay_ui!(Sketchup.active_model) rescue nil
        alive = false
        queued = false
        if @background_io_mutex
          @background_io_mutex.synchronize do
            @background_io_threads ||= []
            @background_io_threads.select! { |thread| thread && thread.alive? }
            alive = @background_io_threads.any?
            queued = !Array(@background_io_queue).empty?
          end
        end
        pending_results = @background_io_results && !@background_io_results.empty?
        start_background_io_worker! if queued && !alive
        unless alive || queued || pending_results
          timer = @background_io_poll_timer
          @background_io_poll_timer = nil
          runtime_stop_timer(timer) if timer
        end
      end
      true
    rescue StandardError => e
      log_exception('创建后台 I/O 回收定时器失败', e)
      false
    end

    def drain_background_io_results!
      return false unless @background_io_results
      loop do
        item = @background_io_results.pop(true)
        handle_background_io_result(item)
      rescue ThreadError
        break
      end
      true
    rescue StandardError => e
      log_exception('回收后台 I/O 任务失败', e)
      false
    end

    def handle_background_io_result(item)
      job = item[:job] || {}
      kind = job[:kind].to_s
      unless item[:success]
        error = item[:error]
        task_id = job[:task_id].to_s
        finish_task_center_job!(task_id, success: false, stage: '后台任务失败', detail: error ? error.message.to_s : '未知错误', error: error) unless task_id.empty?
        log_exception("后台 I/O 任务失败：#{job[:label].to_s.empty? ? kind : job[:label]}", error) if error
        if kind == 'soft_library_directory_scan'
          @soft_library_scanning = false
          refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: false) if @soft_designer_dialog && @soft_designer_dialog.visible?
        end
        if %w[xlsx_write landscape_library_scan material_library_scan soft_library_directory_scan].include?(kind)
          show_status("#{job[:label].to_s.empty? ? '后台任务' : job[:label]}失败：#{error ? error.message : '未知错误'}", 'warning')
        end
        return false
      end
      result = item[:result].is_a?(Hash) ? item[:result] : {}
      case kind
      when 'xlsx_write'
        message = job.dig(:data, :success_message).to_s
        message = "软装清单已导出：#{result[:target]}" if message.empty?
        severity = job.dig(:data, :success_severity).to_s
        severity = 'success' if severity.empty?
        task_id = job[:task_id].to_s
        finish_task_center_job!(task_id, success: true, stage: 'Excel 导出完成', detail: result[:target].to_s) unless task_id.empty?
        show_status(message, severity)
      when 'landscape_library_scan'
        root = result[:root].to_s
        if !root.empty? && normalize_soft_library_key(landscape_library_root) == normalize_soft_library_key(root)
          items = Array(result[:items])
          @landscape_library_cache = {
            root: normalize_soft_library_key(root), signature: result[:signature].to_s,
            items: items, by_id: items.each_with_object({}) { |entry, memo| memo[entry['id'].to_s] = entry },
            warmed_at: monotonic_time
          }
          enqueue_background_io_task('json_write', key: "landscape_catalog|#{normalize_soft_library_key(root)}",
            data: { path: landscape_library_catalog_path(root), payload: {
              'schema' => 2, 'root' => FastPath.expand(root), 'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S'), 'items' => items
            } }, label: '景观目录缓存')
          refresh_landscape_library_dialog(refresh_library: false, include_models: true) if @landscape_library_dialog && @landscape_library_dialog.visible?
        end
      when 'material_library_scan'
        discipline = result[:discipline].to_s
        root = result[:root].to_s
        if !discipline.empty? && !root.empty? && normalize_soft_library_key(material_library_root(discipline)) == normalize_soft_library_key(root)
          @material_library_caches ||= {}
          items = Array(result[:items])
          @material_library_caches[discipline] = {
            root: normalize_soft_library_key(root), signature: result[:signature].to_s,
            items: items, by_id: items.each_with_object({}) { |entry, memo| memo[entry['id'].to_s] = entry }
          }
          refresh_material_library_dialog(force: false) if @material_library_dialog && @material_library_dialog.visible? && @material_library_discipline.to_s == discipline
          refresh_integrated_material_dialogs(discipline, force: false)
        end
      when 'soft_library_directory_scan'
        token = result[:token].to_s
        if !token.empty? && @soft_library_dialog_load_token.to_s == token
          scan_started = monotonic_time
          begin_soft_heavy_interaction(:library_scan)
          begin
            scan_soft_library!(force: true, discovered_files: Array(result[:files]))
          ensure
            @soft_library_scanning = false
            end_soft_heavy_interaction(:library_scan)
          end
          log("软装模型库后台目录刷新：#{elapsed_ms(scan_started)}ms 主线程增量合并，#{Array(@soft_library_cache && @soft_library_cache[:items]).length} 个模型")
          refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false) if @soft_designer_dialog && @soft_designer_dialog.visible?
        end
      end
      if kind != 'xlsx_write' && task_center_visible_io_kind?(kind)
        task_id = job[:task_id].to_s
        finish_task_center_job!(task_id, success: true, stage: '后台扫描完成', detail: job[:label].to_s) unless task_id.empty?
      end
      trim_task_center_history!
      sync_task_center_overlay_ui!(Sketchup.active_model) rescue nil
      log_slow_operation("后台 I/O：#{job[:label].to_s.empty? ? kind : job[:label]}", monotonic_time - item[:elapsed_ms].to_f / 1000.0, 350.0) rescue nil
      true
    rescue StandardError => e
      log_exception("应用后台 I/O 结果失败：#{kind}", e)
      false
    end

    def stop_background_io_worker!
      @background_io_mutex ||= Mutex.new
      threads = []
      @background_io_mutex.synchronize do
        @background_io_queue = []
        @background_io_running_keys = {}
        threads = Array(@background_io_threads).dup
      end
      threads.each do |thread|
        thread.join(0.35) rescue nil if thread && thread.alive?
      end
      @background_io_threads = []
      @background_io_thread = nil
      if @background_io_poll_timer
        timer = @background_io_poll_timer
        @background_io_poll_timer = nil
        runtime_stop_timer(timer) rescue nil
      end
      true
    rescue StandardError => e
      log_exception('停止后台 I/O worker 失败', e)
      false
    end

    def stop_all_runtime_timers!
      ids = runtime_timer_registry.keys
      ids.each { |timer_id| runtime_stop_timer(timer_id) }
      @runtime_timer_registry = {}
      @runtime_timer_key_registry = {}
      ids.length
    rescue StandardError => e
      log_exception('停止运行时定时任务失败', e)
      @runtime_timer_registry = {}
      @runtime_timer_key_registry = {}
      0
    end

    def runtime_timer_diagnostics
      runtime_timer_registry.values.map(&:dup)
    rescue StandardError
      []
    end

    # 缩略图生成、模型库扫描等低优先级任务在放置或代/真切换时暂停，
    # 避免多个 Ruby 主线程任务同时争用 SketchUp 视口。
    def begin_soft_heavy_interaction(kind = :generic)
      @soft_heavy_interactions ||= Hash.new(0)
      @soft_heavy_interaction_started_at ||= {}
      key = kind.to_sym
      @soft_heavy_interactions[key] += 1
      @soft_heavy_interaction_started_at[key] ||= monotonic_time
      true
    rescue StandardError
      false
    end

    def end_soft_heavy_interaction(kind = :generic)
      @soft_heavy_interactions ||= Hash.new(0)
      @soft_heavy_interaction_started_at ||= {}
      key = kind.to_sym
      @soft_heavy_interactions[key] = [@soft_heavy_interactions[key].to_i - 1, 0].max
      if @soft_heavy_interactions[key].zero?
        @soft_heavy_interactions.delete(key)
        @soft_heavy_interaction_started_at.delete(key)
      end
      true
    rescue StandardError
      false
    end

    def soft_heavy_interaction?
      (@soft_heavy_interactions || {}).values.any? { |value| value.to_i.positive? }
    rescue StandardError
      false
    end

    def with_soft_selection_refresh_suspended
      @soft_selection_refresh_suspended = @soft_selection_refresh_suspended.to_i + 1
      yield
    ensure
      @soft_selection_refresh_suspended = [@soft_selection_refresh_suspended.to_i - 1, 0].max
    end

    def soft_selection_refresh_suspended?
      @soft_selection_refresh_suspended.to_i.positive?
    end

    def schedule_soft_selection_refresh(model = Sketchup.active_model, delay = 0.08)
      return false unless model
      @soft_selection_refresh_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6)
      @soft_selection_refresh_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
        delay.to_f, false, label: 'selection:soft_designer', key: "selection:soft_designer:#{key}",
        model: model, active_model_only: true
      ) do
        next unless @soft_selection_refresh_tokens[key] == token
        next if soft_heavy_interaction?
        next unless @soft_designer_dialog && @soft_designer_dialog.visible?
        send_soft_selection_snapshot(model)
      rescue StandardError
        nil
      end
      true
    rescue StandardError
      false
    end

    # -------------------------
    # Project metadata storage
    # -------------------------

    # Persistent JSON support files are stored below a single folder beside each SKP.
    # This keeps the user's model directory clean while preserving relative collaboration paths.
    def metadata_root_for(asset_path)
      expanded = FastPath.expand(asset_path.to_s)
      File.join(File.dirname(expanded), METADATA_DIR_NAME)
    rescue StandardError
      File.join(File.dirname(asset_path.to_s), METADATA_DIR_NAME)
    end

    def metadata_file_path(asset_path, category, filename)
      File.join(metadata_root_for(asset_path), category.to_s, filename.to_s)
    end

    def ensure_metadata_target!(target)
      directory = File.dirname(target.to_s)
      FileUtils.mkdir_p(directory)
      root = File.dirname(directory)
      notice = File.join(root, METADATA_NOTICE_NAME)
      unless File.file?(notice)
        File.write(
          notice,
          "此目录由 SU LinkHub 自动维护。\n用于保存项目清单、坐标基准、参考包记录和发布记录。\n请勿手动修改或删除正在使用的文件。\n",
          mode: 'w:UTF-8'
        )
      end
      target
    rescue StandardError => e
      log_exception('创建 SU LinkHub 数据目录失败', e)
      target
    end

    def legacy_metadata_path(asset_path, suffix, strip_skp: false)
      base = FastPath.expand(asset_path.to_s)
      base = base.sub(/\.skp\z/i, '') if strip_skp
      "#{base}#{suffix}"
    rescue StandardError
      base = asset_path.to_s
      base = base.sub(/\.skp\z/i, '') if strip_skp
      "#{base}#{suffix}"
    end

    def migrate_legacy_metadata_file(legacy, target)
      return target if File.file?(target)
      return target unless File.file?(legacy)
      ensure_metadata_target!(target)
      FileUtils.mv(legacy, target)
      target
    rescue StandardError => e
      log_exception('迁移旧版 SU LinkHub 元数据失败', e)
      legacy
    end

    def metadata_read_path(target, legacy)
      return target if File.file?(target)
      return target unless legacy && File.file?(legacy)
      migrated = migrate_legacy_metadata_file(legacy, target)
      File.file?(migrated) ? migrated : legacy
    rescue StandardError
      File.file?(legacy.to_s) ? legacy : target
    end

    def retire_legacy_metadata_file(legacy, target)
      return true unless legacy && File.file?(legacy)
      return false unless File.file?(target)
      same = begin
        File.size(legacy) == File.size(target) && File.binread(legacy) == File.binread(target)
      rescue StandardError
        false
      end
      if same
        File.delete(legacy)
      else
        root = File.dirname(File.dirname(target))
        archive_dir = File.join(root, 'legacy')
        FileUtils.mkdir_p(archive_dir)
        stamp = Time.now.strftime('%Y%m%d_%H%M%S')
        name = "#{File.basename(legacy)}.legacy_#{stamp}"
        linkhub_mv(legacy, File.join(archive_dir, name))
      end
      true
    rescue StandardError => e
      log_exception('整理旧版 SU LinkHub 元数据失败', e)
      false
    end

    def project_metadata_root(model = Sketchup.active_model)
      path = model && model.respond_to?(:path) ? model.path.to_s : ''
      return '' if path.empty?
      metadata_root_for(path)
    rescue StandardError
      ''
    end

    def organize_metadata_for_asset!(asset_path)
      raw = asset_path.to_s
      return false if raw.empty?
      path = FastPath.expand(raw)

      pairs = [
        [legacy_manifest_path_for(path), manifest_path_for(path)],
        [legacy_coordinate_meta_path_for(path), coordinate_meta_path_for(path)],
        [legacy_coordinate_track_path_for(path), coordinate_track_path_for(path)],
        [legacy_reference_meta_path_for(path), reference_meta_path_for(path)],
        [legacy_native_publish_manifest_path(path), native_publish_manifest_path(path)]
      ]
      pairs.each do |legacy, target|
        migrate_legacy_metadata_file(legacy, target) if File.file?(legacy)
      end
      true
    rescue StandardError => e
      log_exception('整理项目元数据失败', e)
      false
    end

    def organize_project_metadata!(model = Sketchup.active_model)
      return false unless model
      assets = []
      assets << model.path.to_s unless model.path.to_s.empty?
      state = load_state(model) rescue nil
      if state && state['links'].is_a?(Hash)
        state['links'].each_value do |link|
          path = resolve_source_for_edit(link['model_path'].to_s, model) rescue ''
          assets << path unless path.to_s.empty?
        end
      end
      assets.uniq.each { |path| organize_metadata_for_asset!(path) }
      true
    rescue StandardError => e
      log_exception('整理项目数据目录失败', e)
      false
    end

    def open_project_metadata_folder
      model = Sketchup.active_model
      path = model.path.to_s
      raise '请先保存当前 SketchUp 模型。' if path.empty?
      root = metadata_root_for(path)
      FileUtils.mkdir_p(root)
      ensure_metadata_target!(File.join(root, 'manifests', '.keep'))
      if windows_platform?
        script = <<~POWERSHELL
          $ErrorActionPreference = 'Stop';
          Start-Process explorer.exe -ArgumentList @('/e,', $env:SU_LINKHUB_DATA_DIR);
        POWERSHELL
        pid = Process.spawn(
          { 'SU_LINKHUB_DATA_DIR' => root },
          *powershell_command(script),
          out: File::NULL,
          err: File::NULL
        )
        Process.detach(pid)
      else
        command = RUBY_PLATFORM =~ /darwin/i ? ['open', root] : ['xdg-open', root]
        pid = Process.spawn(*command, out: File::NULL, err: File::NULL)
        Process.detach(pid)
      end
      true
    end

    # -------------------------
    # Stable coordinate tracking
    # -------------------------

    def legacy_coordinate_meta_path_for(model_path)
      legacy_metadata_path(model_path, COORD_META_SUFFIX)
    end

    def coordinate_meta_path_for(model_path)
      filename = "#{File.basename(model_path.to_s)}#{COORD_META_SUFFIX}"
      metadata_file_path(model_path, 'coordinates', filename)
    end

    def legacy_coordinate_track_path_for(model_path)
      legacy_metadata_path(model_path, COORD_TRACK_SUFFIX)
    end

    def coordinate_track_path_for(model_path)
      filename = "#{File.basename(model_path.to_s)}#{COORD_TRACK_SUFFIX}"
      metadata_file_path(model_path, 'coordinates', filename)
    end

    def transformation_array(value)
      array = value.respond_to?(:to_a) ? value.to_a : Array(value)
      array = array.map(&:to_f)
      array.length == 16 ? array : []
    rescue StandardError
      []
    end

    def transformation_from_array(value)
      array = transformation_array(value)
      return nil unless array.length == 16
      Geom::Transformation.new(array)
    rescue StandardError
      nil
    end

    def transformations_different?(a, b, tolerance = 1.0e-8)
      aa = transformation_array(a)
      bb = transformation_array(b)
      return false unless aa.length == 16 && bb.length == 16
      aa.zip(bb).any? { |left, right| (left - right).abs > tolerance }
    rescue StandardError
      false
    end

    def request_coordinate_tracking(source_path)
      source = FastPath.expand(source_path.to_s)
      return false unless File.file?(source)
      target = coordinate_track_path_for(source)
      ensure_metadata_target!(target)
      payload = {
        'schema' => COORD_SCHEMA,
        'source' => source,
        'requested_at' => Time.now.iso8601,
        'requested_by' => current_user_name,
        'host' => current_host_name
      }
      temp = "#{target}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(temp, target)
      retire_legacy_metadata_file(legacy_coordinate_track_path_for(source), target)
      true
    rescue StandardError => e
      log_exception('创建坐标跟踪请求失败', e)
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def coordinate_tracking_requested?(source_path)
      target = coordinate_track_path_for(source_path)
      legacy = legacy_coordinate_track_path_for(source_path)
      File.file?(metadata_read_path(target, legacy))
    rescue StandardError
      false
    end

    def read_coordinate_metadata(source_path)
      target = coordinate_meta_path_for(source_path)
      target = metadata_read_path(target, legacy_coordinate_meta_path_for(source_path))
      return nil unless File.file?(target)
      payload = JSON.parse(File.read(target, encoding: 'UTF-8'))
      axes = transformation_array(payload['axes'])
      return nil unless axes.length == 16
      payload['axes'] = axes
      payload
    rescue StandardError => e
      log_exception('读取坐标元数据失败', e)
      nil
    end

    def tracked_source_model?(model)
      path = model.path.to_s
      return false if path.empty?
      coordinate_tracking_requested?(path) || File.file?(edit_lock_path_for(path))
    rescue StandardError
      false
    end

    def write_coordinate_metadata_for_model(model)
      return false if publish_critical_section?
      return false unless model && model.respond_to?(:path)
      return false unless workspace_ready?(nil, model)
      path = model.path.to_s
      return false if path.empty? || !File.file?(path)
      return false unless tracked_source_model?(model)
      return false unless model.respond_to?(:axes) && model.axes.respond_to?(:transformation)

      axes = transformation_array(model.axes.transformation)
      return false unless axes.length == 16
      payload = {
        'schema' => COORD_SCHEMA,
        'source' => FastPath.expand(path),
        'guid' => (model.respond_to?(:guid) ? model.guid.to_s : ''),
        'axes' => axes,
        'saved_at' => Time.now.iso8601,
        'sketchup_version' => Sketchup.version.to_s
      }
      target = coordinate_meta_path_for(path)
      ensure_metadata_target!(target)
      temp = "#{target}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(temp, target)
      retire_legacy_metadata_file(legacy_coordinate_meta_path_for(path), target)
      log("已写入坐标基准：#{target}")
      true
    rescue StandardError => e
      log_exception('写入坐标元数据失败', e)
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    # v0.13.6.170：Observer / 双击桥接 / 家具退出确认工具拆出，热重载仍用 Kernel.load。
    Kernel.load(File.expand_path('observer_coordinator.rb', __dir__))

    def workspace_color_components(color)
      return nil unless color
      values = [color.red.to_i, color.green.to_i, color.blue.to_i]
      values << (color.respond_to?(:alpha) ? color.alpha.to_i : 255)
      values
    rescue StandardError
      nil
    end

    def workspace_locked_selection_discipline(model = Sketchup.active_model)
      return '' unless model && model == Sketchup.active_model && model.active_path.nil?
      selected = model.selection.to_a
      return '' unless selected.length == 1
      entity = selected.first
      return '' unless entity && entity.valid? && entity.respond_to?(:get_attribute)
      return '' unless entity.get_attribute(ENTITY_DICT, 'managed', false)
      return '' unless entity.respond_to?(:locked?) && entity.locked?

      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
      discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
      discipline = entity.get_attribute(ENTITY_DICT, 'space_collection_key', discipline).to_s if kind == 'space_model'
      discipline = 'architecture' if kind == 'architecture_model'
      discipline = normalize_space_collection_key(discipline) if kind == 'space_model'
      WORKSPACE_LOCKED_SELECTION_COLORS.key?(discipline) ? discipline : ''
    rescue StandardError
      ''
    end

    # LockedColor 是 SketchUp 自己绘制锁定选择轮廓时使用的颜色。这里只在唯一选中
    # LinkHub 锁定根模型期间临时替换，离开选择后恢复用户原值；不改材质、标签或实体。
    def sync_workspace_locked_selection_color!(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:rendering_options)
      @workspace_locked_selection_color_states ||= {}
      key = model.object_id
      options = model.rendering_options
      discipline = workspace_locked_selection_discipline(model)
      state = @workspace_locked_selection_color_states[key]

      if discipline.empty?
        if state
          current = workspace_color_components(options['LockedColor'])
          if current && current.first(3) == Array(state[:applied]).first(3)
            original = Array(state[:original])
            options['LockedColor'] = Sketchup::Color.new(*original) unless original.empty?
          end
          @workspace_locked_selection_color_states.delete(key)
          model.active_view.invalidate if model == Sketchup.active_model
        end
        return false
      end

      desired = WORKSPACE_LOCKED_SELECTION_COLORS[discipline]
      unless state
        state = {
          model: model,
          original: workspace_color_components(options['LockedColor']),
          applied: nil,
          discipline: ''
        }
        @workspace_locked_selection_color_states[key] = state
      end
      return true if state[:discipline].to_s == discipline &&
                     Array(workspace_color_components(options['LockedColor'])).first(3) == desired

      options['LockedColor'] = Sketchup::Color.new(*desired)
      state[:applied] = desired.dup
      state[:discipline] = discipline
      model.active_view.invalidate if model == Sketchup.active_model
      true
    rescue StandardError => e
      log_exception('同步锁定空间专业选择色失败', e)
      false
    end

    def restore_workspace_locked_selection_colors!(except_model: nil)
      states = @workspace_locked_selection_color_states || {}
      remaining = {}
      states.each_value do |state|
        model = state[:model]
        if except_model && model.equal?(except_model)
          remaining[model.object_id] = state
          next
        end
        next unless model && model.respond_to?(:rendering_options)
        current = workspace_color_components(model.rendering_options['LockedColor'])
        next unless current && current.first(3) == Array(state[:applied]).first(3)
        original = Array(state[:original])
        model.rendering_options['LockedColor'] = Sketchup::Color.new(*original) unless original.empty?
        model.active_view.invalidate if model == Sketchup.active_model
      rescue StandardError
        next
      end
      @workspace_locked_selection_color_states = remaining
      true
    rescue StandardError
      @workspace_locked_selection_color_states = {}
      false
    end

    def workspace_toolbar_selection_changed(model = Sketchup.active_model)
      return if soft_commit_world_context_active?(model)
      return false if @soft_thumbnail_rendering
      note_runtime_interaction!(model)
      return false unless model && model == Sketchup.active_model
      sync_workspace_locked_selection_color!(model)
      # Reuse the last state already loaded by the runtime. Reading and comparing the complete
      # project_json attribute on every click measured hundreds of milliseconds in larger files.
      # A cache miss pays one authoritative read, then following selections stay memory-only.
      hot_state = cached_project_state_hot_readonly(model)
      hot_state ||= cached_project_state_readonly(model) || load_state(model)
      return false unless workspace_selection_configured?(hot_state, model)
      @workspace_toolbar_selection_tokens ||= {}
      key = model.object_id
      token = @workspace_toolbar_selection_tokens[key].to_i + 1
      @workspace_toolbar_selection_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
        0.04, false, label: 'selection:workspace_toolbar', key: "selection:workspace_toolbar:#{key}",
        model: model, active_model_only: true
      ) do
        next unless @workspace_toolbar_selection_tokens[key] == token
        next if soft_heavy_interaction?
        # v0.13.6.135：空间内部绝大多数选择仍不重建顶部状态，保留大型空间的性能优化；
        # 但“协同组件”按钮本身就是内部选择上下文动作，因此选中单个普通/协同组件时
        # 必须立即刷新；从组件切到其它对象时也要刷新一次，把旧的组件按钮及时收掉。
        # 世界根选择仍按原逻辑正常刷新。
        if model.active_path.nil? || workspace_toolbar_component_selection_relevant?(model)
          # v0.13.6.155：联动空间实例调整/原生复制的收尾必须发生在 SelectionObserver
          # 回调之后。先识别 Move+Ctrl 生成的额外实例，再在用户切走选择时自动锁回
          # 已登记联动空间，避免留下长期解锁的实例。
          if model.active_path.nil?
            # v0.13.6.170：SelectionObserver 的延迟回调也属于内部维护链。这里过去
            # 直接执行 reconcile，其 transparent transaction 会再次触发 ModelObserver，
            # 从选择刷新绕回 transaction timer。统一放进内部同步屏障，彻底切断反馈环。
            with_internal_sync_guard do
              reconcile_linked_space_native_copies!(model)
              reconcile_linked_space_transform_selection!(model)
              normalize_pending_linked_space_selection!(model)
            end
          end
          selection_refresh_started = monotonic_time
          # Selection never changes the drawer tree. Preserve its last detailed snapshot and
          # rebuild only the quick actions; this avoids scanning every space while the drawer is open.
          refresh_workspace_toolbar(model, detailed: false, state: hot_state, selection_fast: true)
          elapsed_ms = (monotonic_time - selection_refresh_started) * 1000.0
          log("选择轻量刷新偏慢：#{elapsed_ms.round}ms / selection=#{model.selection.length} / active_path=#{Array(model.active_path).length}") if elapsed_ms > 180.0
        end
        refresh_material_library_dialog(force: false) if @material_library_dialog && @material_library_dialog.visible?
      rescue StandardError => e
        log_exception('刷新顶部快捷条选择状态失败', e)
      end
      true
    rescue StandardError
      false
    end

    # 只做 O(1) 的选择检查，不计算组件签名/共享清单。这样空间内部普通家具、面、边的
    # 高频选择不会触发工具条重建；只有组件协同按钮需要出现/消失时才刷新。
    def workspace_toolbar_component_selection_relevant?(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:selection)
      selected = model.selection.to_a
      if selected.length == 1
        entity = selected.first
        if entity && entity.valid? && entity.is_a?(Sketchup::ComponentInstance) && !managed_entity?(entity)
          return true
        end
      end

      # 如果上一帧已经显示了组件按钮，哪怕当前选择被清空或切成其它对象，也刷新一次
      # 让按钮立即消失，避免悬浮条保留一个指向旧选择的“定义/发布/更新组件”动作。
      previous = @workspace_toolbar_last_good_state && @workspace_toolbar_last_good_state[model.object_id]
      previous.is_a?(Hash) && !previous['quick_component_action'].to_s.empty?
    rescue StandardError
      false
    end

    WORKSPACE_DOUBLE_CLICK_MIN_SECONDS = 0.12
    WORKSPACE_DOUBLE_CLICK_MAX_SECONDS = 0.85
    # v0.13.6.132：双击桥只应短暂存在于“两次点击之间”。旧版第一次选中受管空间后
    # 会一直把自定义 Tool 压在原生 SelectionTool 上，视觉上变成白色系统箭头，且
    # Shift/Ctrl 复选会被桥接 Tool 吞掉。超过双击窗口、或鼠标明显移向别处时立即
    # 让回 SketchUp 原生选择工具；真正双击仍在 0.85 秒窗口内由桥接层接管。
    WORKSPACE_DOUBLE_CLICK_BRIDGE_IDLE_SECONDS = 1.00
    WORKSPACE_DOUBLE_CLICK_POINTER_RELEASE_PX = 10.0
    WORKSPACE_DOUBLE_CLICK_REARM_SUPPRESS_SECONDS = 0.22
    WORKSPACE_SELECTION_TOOL_ID = 21_022

    def monotonic_seconds
      Process.clock_gettime(Process::CLOCK_MONOTONIC)
    rescue StandardError
      Time.now.to_f
    end

    def workspace_double_click_entity_id(entity)
      return '' unless entity && entity.valid?
      if entity.respond_to?(:persistent_id)
        value = entity.persistent_id.to_i
        return "pid:#{value}" if value.positive?
      end
      "oid:#{entity.object_id}"
    rescue StandardError
      "oid:#{entity.object_id}"
    end

    # 双击入口有三类：
    # 1. 全模根层级的受管工作模型：沿用原来的“双击进入协同修改”。
    # 2. 当前正在协同修改的空间内部，若唯一选择的是 LinkHub 家具代理，双击时只把
    #    该实例切换为真模型、设为独立 Definition，并直接进入该实例内部编辑。
    # 3. 空间单一编辑脊柱上的核心层若存在共享 Definition 锁冲突，双击时只把当前层
    #    设为独立 Definition 后进入，避免 SketchUp 原生三选一弹窗。
    def workspace_double_click_candidate(model = Sketchup.active_model)
      return nil unless model && model == Sketchup.active_model
      state = cached_project_state_readonly(model) || load_state(model)
      return nil unless workspace_selection_configured?(state, model)
      # v0.13.6.97：如果上一次退出竞态留下“active_path 仍在空间里但根已经锁定”，
      # 必须先自愈再判断双击候选，否则 SketchUp 原生 SelectionTool 会先弹三选一。
      active_root = Array(model.active_path).first
      liminal = active_root && active_root.valid? &&
                (entity_native_locked?(active_root) ||
                 active_root.get_attribute(ENTITY_DICT, 'safe_paused', false))
      if liminal
        heal_active_liminal_space_context!(model, reason: 'double-click candidate preflight')
        state = cached_project_state_readonly(model) || load_state(model)
      end
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      return nil unless entity && entity.valid?

      # 选择事件可能在一次点击中触发 removed/added/bulk 三次。这里必须使用只读缓存，
      # 不能每次 deep-dup 整份项目状态。
      role = host_discipline_for(state)

      # 受管家具双击必须严格限制在“本人当前正在修改且仍持有协作锁”的空间内部。
      # 不读取模型库、不扫描整个空间，只依据实例/Definition 上已有的 model_id 与表示状态。
      if space_workspace_role?(role) && !model.active_path.nil? &&
         (entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group))
        begin
          space_item = space_model_record(state, state['space_editing_id'].to_s)
          space_entity = space_item ? space_model_entity(space_item['id'], model) : nil
          if space_item && space_entity && space_entity.valid? &&
             local_space_edit_session?(space_item, state, model) &&
             active_path_inside_space?(space_entity, model)
            info = soft_instance_metadata(entity)
            model_id = info['model_id'].to_s
            representation = soft_instance_representation(entity)
            # v0.13.6.100：确认层覆盖所有受管家具，不只代理。活动空间可能会从会话缓存
            # 自动恢复部分真模型；这些 full 实例同样必须先确认，不能掉进普通 space_nested
            # 双击路径后被原生/隔离逻辑直接进入。
            # 当前 Selection 来自 active_entities，而 active_path 已确认位于此空间内，
            # 因此无需再递归遍历整个空间 Definition 树确认同一件事。
            if !model_id.empty? && %w[proxy full].include?(representation)
              model_name = info['model_name'].to_s
              model_name = entity.respond_to?(:name) ? entity.name.to_s : '' if model_name.empty?
              model_name = '家具' if model_name.empty?
              return {
                kind: 'soft_proxy', id: model_id, role: role,
                space_id: space_item['id'].to_s,
                entity_id: workspace_double_click_entity_id(entity),
                label: model_name,
                representation: representation,
                entity: entity
              }
            end
          end
        rescue StandardError => e
          log_exception('识别受管家具双击候选失败', e)
        end
      end

      # v0.13.6.97 根因修复：SketchUp 的父实例锁会向整棵嵌套 Definition occurrence
      # 传播，因此冲突并不只出现在 PACKAGE/PAYLOAD 的“单一编辑脊柱”。家具组合、
      # 分支组、普通核心组件只要与其它已锁空间复用 Definition，也会弹三选一。
      # 现在对“当前 LinkHub 空间 active_entities 中、确实存在共享/锁风险”的任意嵌套
      # 容器接管双击；仍然只唯一化当前实例，不解锁其它 occurrence。
      if space_workspace_role?(role) && !model.active_path.nil? &&
         (entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group))
        begin
          space_item = space_model_record(state, state['space_editing_id'].to_s)
          space_entity = space_item ? space_model_entity(space_item['id'], model) : nil
          if space_item && space_entity && space_entity.valid? &&
             local_space_edit_session?(space_item, state, model) &&
             active_path_inside_space?(space_entity, model) &&
             space_edit_candidate_in_current_context?(space_entity, entity, model) &&
             (space_edit_definition_shared?(entity) ||
              space_edit_definition_lock_conflict?(entity) ||
              space_edit_other_locked_definition_instance?(entity) ||
              (entity.respond_to?(:locked?) && entity.locked?))
            return {
              kind: 'space_nested', id: space_item['id'].to_s, role: role,
              entity_id: workspace_double_click_entity_id(entity),
              label: '空间嵌套层', entity: entity
            }
          end
        rescue StandardError => e
          log_exception('识别空间嵌套层双击锁冲突失败', e)
        end
      end

      # 全模根层级的硬装/软装空间允许跨工作区识别。这里不能再以“当前工作区”
      # 或“根是否锁定”为前置条件：一个待发布空间会保持解锁，而跨专业目标本来就
      # 不属于当前工作区。先按精确根实例识别受管空间，再决定是否提示切换工作区。
      return nil unless model.active_path.nil?
      # v0.13.6.158：原生 Move+Ctrl 新复制出来、尚未命名的联动副本也由 LinkHub
      # 接管双击，禁止 SketchUp 原生双击误进入共享 Definition 内部修改。
      if pending_linked_space_clone?(entity)
        temp_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_temp_id', '').to_s
        temp_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if temp_id.empty?
        return {
          kind: 'linked_space_pending_transform', id: temp_id, role: role,
          entity_id: workspace_double_click_entity_id(entity), label: '待命名联动副本', entity: entity
        }
      end
      managed_space = selected_managed_space_record(state, model)
      if managed_space
        # v0.13.6.155：联动空间双击只调整实例矩阵，不进入来源模型编辑。
        # 这样即使来源共享 revision 与当前载入快照存在先后差，也不会错误触发
        # “共享版本更旧/普通修改禁止”的内容版本保护。
        candidate_kind = linked_space_record?(managed_space) ? 'linked_space_transform' : 'space'
        return {
          kind: candidate_kind,
          id: managed_space['id'].to_s,
          role: space_record_collection_key(managed_space),
          entity_id: workspace_double_click_entity_id(entity),
          label: space_ui_label(managed_space),
          entity: entity
        }
      end

      # v0.13.6.190：原生复制/粘贴产生的“重复空间根”（与另一根实例共用 space_id）
      # 不在受管索引里，过去双击完全没反应。现在接管双击，询问后登记为待命名联动副本。
      duplicate_root = selected_duplicate_space_root_info(model, state: state)
      if duplicate_root
        return {
          kind: 'linked_space_duplicate_adopt',
          id: duplicate_root[:item]['id'].to_s,
          role: role,
          entity_id: workspace_double_click_entity_id(entity),
          label: '原生复制的空间副本',
          entity: entity
        }
      end
      lh_note_double_click_miss(entity, state, model)

      # 建筑/景观仍只接管 LinkHub 原生锁保护的受管根，保持既有安全边界。
      return nil unless entity_native_locked?(entity)
      case role
      when 'architecture'
        architecture_id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s rescue ''
        item = architecture_model_record(state, architecture_id)
        managed = item ? architecture_model_entity(architecture_id, model) : nil
        if item && managed && managed.valid? && managed == entity
          return {
            kind: 'architecture_model',
            id: item['id'].to_s,
            role: role,
            entity_id: workspace_double_click_entity_id(entity),
            label: architecture_display_name(item, state),
            entity: entity
          }
        end
        # 多建筑项目中旧单建筑 FULL 已经退役，不能再抢占双击入口。
        return nil if architecture_collection_active?(state, model)
        managed = native_edit_entity(role, model)
        return nil unless managed && managed.valid? && managed == entity
        return nil if host_native_link?(state, role, model)
        {
          kind: 'discipline', id: role, role: role,
          entity_id: workspace_double_click_entity_id(entity),
          label: DISCIPLINES.dig(role, 'name').to_s, entity: entity
        }
      when 'landscape'
        managed = native_edit_entity(role, model)
        return nil unless managed && managed.valid? && managed == entity
        return nil if host_native_link?(state, role, model)
        {
          kind: 'discipline', id: role, role: role,
          entity_id: workspace_double_click_entity_id(entity),
          label: DISCIPLINES.dig(role, 'name').to_s, entity: entity
        }
      else
        nil
      end
    rescue StandardError => e
      lh_note_double_click_candidate_error(e) rescue nil
      nil
    end

    def workspace_double_click_candidate_signature(candidate)
      return '' unless candidate.is_a?(Hash)
      [candidate[:kind], candidate[:id], candidate[:role], candidate[:entity_id]].join('|')
    rescue StandardError
      ''
    end

    def arm_workspace_double_click_candidate(model = Sketchup.active_model)
      @workspace_double_click_candidates ||= {}
      return false unless model
      return false if workspace_escape_transition_active?(model)
      key = model.object_id
      @workspace_double_click_rearm_suppress_until ||= {}
      if @workspace_double_click_rearm_suppress_until[key].to_f > monotonic_seconds
        @workspace_double_click_candidates.delete(key)
        @workspace_double_click_bridge_tokens&.delete(key)
        @workspace_double_click_action_tokens&.delete(key)
        return false
      end
      candidate = workspace_double_click_candidate(model)
      unless candidate
        @workspace_double_click_candidates.delete(key)
        return false
      end
      signature = workspace_double_click_candidate_signature(candidate)
      now = monotonic_seconds
      record = @workspace_double_click_candidates[key]
      if record.is_a?(Hash) && record[:signature].to_s == signature
        # 同一实体在第二次点击时，SelectionObserver 可能再次发出 BulkChange。
        # 不重置首击时间，否则真正的双击会被误当成第一次点击。
        record[:candidate] = candidate
        record[:last_selection_at] = now
      else
        @workspace_double_click_candidates[key] = {
          signature: signature,
          candidate: candidate,
          armed_at: now,
          last_click_at: nil,
          last_action_at: nil,
          last_selection_at: now
        }
      end
      schedule_workspace_double_click_bridge(model, signature)
      true
    rescue StandardError
      false
    end

    def workspace_selection_tool?(tool_name, tool_id)
      tool_id.to_i == WORKSPACE_SELECTION_TOOL_ID || tool_name.to_s.casecmp('SelectionTool').zero?
    rescue StandardError
      false
    end

    def schedule_workspace_double_click_bridge(model = Sketchup.active_model, signature = '')
      return false if @shutting_down
      return false unless model && model == Sketchup.active_model
      return false if workspace_escape_transition_active?(model)
      @workspace_double_click_bridge_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6)
      @workspace_double_click_bridge_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) do
        next unless @workspace_double_click_bridge_tokens[key] == token
        activate_workspace_double_click_bridge(model, signature)
      rescue StandardError => e
        log_exception('启动工作模型双击桥接工具失败', e)
      end
      true
    rescue StandardError
      false
    end

    def activate_workspace_double_click_bridge(model = Sketchup.active_model, signature = '')
      return false if @shutting_down
      return false unless model && model == Sketchup.active_model
      return false if workspace_escape_transition_active?(model)
      @workspace_double_click_candidates ||= {}
      @workspace_double_click_bridge_records ||= {}
      key = model.object_id
      record = @workspace_double_click_candidates[key]
      return false unless record.is_a?(Hash) && record[:signature].to_s == signature.to_s

      # v0.13.5.23 根因修复：旧逻辑这里只允许 active_path=nil，实际上这会把
      # “空间内部家具代理”永远挡在桥接工具之外。家具代理候选恰恰只会在已经
      # 进入当前协同空间（active_path 非 nil）时成立，所以 v0.13.5.20 虽然写了
      # 双击切真代码，却没有任何事件路径能真正走到执行函数。
      candidate = record[:candidate]
      nested_managed_edit = candidate.is_a?(Hash) && %w[soft_proxy space_spine space_nested].include?(candidate[:kind].to_s)
      # v0.13.6.90 虽然识别了 space_spine，但这里仍只放行 soft_proxy，导致核心层
      # 双击桥永远无法在 active_path 内激活；随后原生 SelectionTool 抢先弹三选一。
      # 0.13.6.92 同时放行两种 LinkHub 明确管理的嵌套入口。
      return false unless model.active_path.nil? || nested_managed_edit
      existing = @workspace_double_click_bridge_records[key]
      if existing.is_a?(Hash) && existing[:active]
        existing[:signature] = signature.to_s
        return true
      end
      tool = WorkspaceDoubleClickBridgeTool.new(model, signature)
      @workspace_double_click_bridge_records[key] = {
        model: model, tool: tool, signature: signature.to_s, active: true, handled: false
      }
      pushed = model.tools.push_tool(tool)
      unless pushed
        @workspace_double_click_bridge_records.delete(key)
        return false
      end
      schedule_workspace_double_click_bridge_expiry(model, tool, signature)
      log("双击桥接已激活：#{signature}")
      true
    rescue StandardError => e
      @workspace_double_click_bridge_records&.delete(model.object_id) if model
      log_exception('激活工作模型双击桥接工具失败', e)
      false
    end

    def workspace_double_click_bridge_activated(model, tool, signature)
      return false unless model && tool
      @workspace_double_click_bridge_records ||= {}
      key = model.object_id
      record = @workspace_double_click_bridge_records[key]
      unless record.is_a?(Hash) && record[:tool].equal?(tool)
        record = { model: model, tool: tool, signature: signature.to_s, handled: false }
        @workspace_double_click_bridge_records[key] = record
      end
      record[:active] = true
      true
    rescue StandardError
      false
    end

    def workspace_double_click_bridge_deactivated(model, tool)
      return false unless model && tool
      key = model.object_id
      record = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      if record.is_a?(Hash) && record[:tool].equal?(tool)
        handled = record[:handled] == true
        @workspace_double_click_bridge_records.delete(key)
        @workspace_double_click_candidates&.delete(key) unless handled
      end
      @workspace_double_click_bridge_expiry_tokens&.delete(key)
      true
    rescue StandardError
      false
    end

    # 第一次点击后桥接 Tool 只保留一个双击窗口。超时仍未发生第二击时，
    # 自动 pop 回原生 SelectionTool，避免白色系统鼠标长期驻留并阻断多选。
    def schedule_workspace_double_click_bridge_expiry(model, tool, signature, delay: WORKSPACE_DOUBLE_CLICK_BRIDGE_IDLE_SECONDS)
      return false unless model && tool
      @workspace_double_click_bridge_expiry_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(5)
      @workspace_double_click_bridge_expiry_tokens[key] = token
      runtime_start_timer(
        delay.to_f, false, label: 'workspace:double_click_bridge_expiry',
        key: "workspace:double_click_bridge_expiry:#{key}", model: model, active_model_only: true
      ) do
        next unless @workspace_double_click_bridge_expiry_tokens[key] == token
        bridge = (@workspace_double_click_bridge_records || {})[key]
        next unless bridge.is_a?(Hash) && bridge[:tool].equal?(tool) && bridge[:active]
        next if bridge[:awaiting_confirmation]
        candidate = (@workspace_double_click_candidates || {})[key]
        if candidate.is_a?(Hash) && candidate[:signature].to_s == signature.to_s
          latest = [candidate[:armed_at], candidate[:last_click_at]].compact.map(&:to_f).max.to_f
          age = latest.positive? ? monotonic_seconds - latest : WORKSPACE_DOUBLE_CLICK_BRIDGE_IDLE_SECONDS
          if age < WORKSPACE_DOUBLE_CLICK_BRIDGE_IDLE_SECONDS - 0.03
            schedule_workspace_double_click_bridge_expiry(
              model, tool, signature,
              delay: [WORKSPACE_DOUBLE_CLICK_BRIDGE_IDLE_SECONDS - age + 0.02, 0.05].max
            )
            next
          end
        end
        workspace_double_click_bridge_pointer_moved_away(model, tool, reason: '双击窗口超时')
      ensure
        if @workspace_double_click_bridge_expiry_tokens && @workspace_double_click_bridge_expiry_tokens[key] == token
          @workspace_double_click_bridge_expiry_tokens.delete(key)
        end
      end
      true
    rescue StandardError => e
      log_exception('安排双击桥自动释放失败', e)
      false
    end

    def suppress_workspace_double_click_rearm!(model = Sketchup.active_model, seconds: WORKSPACE_DOUBLE_CLICK_REARM_SUPPRESS_SECONDS)
      return false unless model
      key = model.object_id
      @workspace_double_click_rearm_suppress_until ||= {}
      @workspace_double_click_rearm_suppress_until[key] = monotonic_seconds + [seconds.to_f, 0.0].max
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_bridge_tokens&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      @workspace_double_click_bridge_expiry_tokens&.delete(key)
      true
    rescue StandardError
      false
    end

    def workspace_double_click_bridge_pointer_moved_away(model, tool, reason: '鼠标移出双击目标')
      return false unless model && tool
      key = model.object_id
      bridge = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      return false unless bridge.is_a?(Hash) && bridge[:tool].equal?(tool)
      return false if bridge[:awaiting_confirmation]
      bridge[:handled] = false
      suppress_workspace_double_click_rearm!(model, seconds: 0.08)
      begin
        active_tool = model.tools.active_tool if model.respond_to?(:tools)
        model.tools.pop_tool if active_tool && active_tool.equal?(tool)
      rescue StandardError
        nil
      end
      log("双击桥已让回原生选择工具：#{reason}") if ENV['SULINK_TOOL_TRACE'].to_s == '1'
      true
    rescue StandardError => e
      log_exception('释放双击桥失败', e)
      false
    end

    def workspace_double_click_interaction_active?(model = Sketchup.active_model, quiet_seconds: 0.70)
      return false unless model
      key = model.object_id
      bridge = (@workspace_double_click_bridge_records || {})[key]
      return false unless bridge.is_a?(Hash) && bridge[:active]
      return true if bridge[:awaiting_confirmation]
      candidate = (@workspace_double_click_candidates || {})[key]
      return false unless candidate.is_a?(Hash)
      recent = [candidate[:armed_at], candidate[:last_selection_at], candidate[:last_click_at], candidate[:last_action_at]].compact.map(&:to_f).max.to_f
      recent.positive? && (monotonic_seconds - recent) < quiet_seconds.to_f
    rescue StandardError
      false
    end

    def cancel_workspace_double_click_bridge(model, tool)
      return false unless model && tool
      key = model.object_id
      record = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      return false unless record.is_a?(Hash) && record[:tool].equal?(tool)
      record[:handled] = false
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_bridge_tokens&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      model.tools.pop_tool
      true
    rescue StandardError
      false
    end

    # v0.13.6.94：临时双击桥不能拥有 ESC。用户按 ESC 时，先退出桥本身，
    # 再把当前 SketchUp active_path 安全退一级；到空间最外层时则回到模型根。
    # 退层动作故意安排到 onCancel 回调之后，避免在 SketchUp 正在切 Tool 的内部
    # 状态中同时修改 active_path。普通的程序化 pop/deactivate 不会进入这条路径。
    def workspace_double_click_bridge_cancelled(model, tool, reason = nil)
      return false unless model && tool
      key = model.object_id
      record = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      return false unless record.is_a?(Hash) && record[:tool].equal?(tool)

      user_escape = reason.to_i == 0
      record[:handled] = false
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_bridge_tokens&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      model.tools.pop_tool
      return true unless user_escape

      # v0.13.6.98：不再由双击桥自己安排一次性的 active_path 修改。双击桥和
      # Overlay 点击层统一走同一个退层事务；事务期间禁止任何 LinkHub 临时 Tool
      # 重新 push，直到目标 active_path 连续稳定，杜绝“刚 pop 又 push”的 ESC 饥饿。
      request_workspace_escape_step!(model, source: 'double_click_bridge')
      true
    rescue StandardError => e
      log_exception('处理双击桥 ESC 退出失败', e)
      false
    end

    # v0.13.6.98：LinkHub 临时 Tool 的 ESC 统一退层状态机。一次 ESC 只退 SketchUp
    # active_path 一级：家具内部仍可先退出家具并触发自动保存；在空间根再按一次才
    # 回到世界根。事务进行期间，双击桥和 Overlay 点击层都禁止重新 push_tool。
    WORKSPACE_ESCAPE_STEP_INTERVAL = 0.035
    WORKSPACE_ESCAPE_STEP_STABLE_FRAMES = 2
    WORKSPACE_ESCAPE_STEP_MAX_ATTEMPTS = 24
    WORKSPACE_ESCAPE_POST_SUPPRESS_SECONDS = 0.18

    def workspace_escape_transition_active?(model = Sketchup.active_model)
      return false unless model
      key = model.object_id
      record = @workspace_escape_transition_records && @workspace_escape_transition_records[key]
      return true if record.is_a?(Hash)
      until_at = (@workspace_escape_suppress_until || {})[key].to_f
      until_at > monotonic_seconds
    rescue StandardError
      false
    end

    def clear_workspace_escape_transient_tools!(model = Sketchup.active_model)
      return false unless model
      key = model.object_id
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_bridge_tokens&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      @workspace_double_click_bridge_expiry_tokens&.delete(key)
      @workspace_toolbar_click_tool_pending&.delete(key)
      true
    rescue StandardError
      false
    end

    def finish_workspace_escape_transition!(model, token, status = '完成')
      return false unless model
      key = model.object_id
      record = @workspace_escape_transition_records && @workspace_escape_transition_records[key]
      return false unless record.is_a?(Hash) && record[:token].to_s == token.to_s
      @workspace_escape_transition_records.delete(key)
      @workspace_escape_suppress_until ||= {}
      @workspace_escape_suppress_until[key] = monotonic_seconds + WORKSPACE_ESCAPE_POST_SUPPRESS_SECONDS
      clear_workspace_escape_transient_tools!(model)
      schedule_restore_default_select_tool(model, delay: 0.04, reason: 'ESC/退出编辑完成')
      log("ESC 稳定退层#{status}：source=#{record[:source]} / #{record[:start_depth]} -> #{Array(model.active_path).length}")
      true
    rescue StandardError
      false
    end

    def request_workspace_escape_step!(model = Sketchup.active_model, source: 'linkhub_tool')
      return false unless model && model == Sketchup.active_model
      path_before = Array(model.active_path).select { |node| node && node.valid? }
      return false if path_before.empty?

      key = model.object_id
      @workspace_escape_transition_records ||= {}
      @workspace_escape_suppress_until ||= {}

      # 若上一拍已经在处理同一次 ESC，不叠加第二个 driver；快速连按时由原生 Tool
      # 在当前事务结束后处理下一层，避免一次按键被算成多层。
      existing = @workspace_escape_transition_records[key]
      return true if existing.is_a?(Hash)

      root = path_before.first
      target_path = path_before[0...-1]
      token = SecureRandom.hex(6)
      record = {
        token: token, source: source.to_s, root: root, target_path: target_path,
        start_depth: path_before.length, target_depth: target_path.length,
        attempts: 0, stable_frames: 0, started_at: monotonic_seconds
      }
      @workspace_escape_transition_records[key] = record
      @workspace_escape_suppress_until[key] = monotonic_seconds + 2.0
      clear_workspace_escape_transient_tools!(model)
      model.selection.clear rescue nil
      log("ESC 稳定退层开始：source=#{source} / depth=#{path_before.length} -> #{target_path.length}")

      tick = nil
      tick = lambda do
        current = @workspace_escape_transition_records && @workspace_escape_transition_records[key]
        next unless current.is_a?(Hash) && current[:token].to_s == token
        next unless model && model == Sketchup.active_model

        current_path = Array(model.active_path).select { |node| node && node.valid? }
        current[:attempts] = current[:attempts].to_i + 1
        same_root = current_path.empty? || current_path.first.equal?(root)
        unless same_root
          finish_workspace_escape_transition!(model, token, '取消（已进入其它编辑树）')
          next
        end

        target_depth = current[:target_depth].to_i
        reached = if target_depth.zero?
                    current_path.empty?
                  else
                    current_path.length <= target_depth && current_path == target_path[0, current_path.length]
                  end

        if reached
          current[:stable_frames] = current[:stable_frames].to_i + 1
          if current[:stable_frames].to_i >= WORKSPACE_ESCAPE_STEP_STABLE_FRAMES
            finish_workspace_escape_transition!(model, token)
            # 主动补一次编辑层级处理，避免某些 SU 版本 ActivePathChanged 合并/漏帧。
            runtime_start_timer(0.01, false, label: 'workspace:esc_post_path_sync', model: model, active_model_only: true) do
              handle_soft_individual_edit_active_path_change(model)
              handle_space_active_path_change(model)
            end
            next
          end
        else
          current[:stable_frames] = 0
          begin
            if target_depth.zero?
              model.active_path = nil if model.respond_to?(:active_path=)
            elsif model.respond_to?(:active_path=)
              model.active_path = target_path
            end
            model.selection.clear rescue nil
          rescue StandardError => e
            log_exception('ESC 稳定退层写入 active_path 失败', e)
          end
        end

        if current[:attempts].to_i >= WORKSPACE_ESCAPE_STEP_MAX_ATTEMPTS
          finish_workspace_escape_transition!(model, token, '超时')
          show_status('ESC 退层没有在预期时间内稳定；LinkHub 已停止临时 Tool 重挂，可再按一次 ESC。', 'error')
          next
        end

        runtime_start_timer(
          WORKSPACE_ESCAPE_STEP_INTERVAL, false, label: 'workspace:esc_stable_step',
          key: "workspace:esc_stable_step:#{key}", model: model, active_model_only: true
        ) { tick.call }
      rescue StandardError => e
        finish_workspace_escape_transition!(model, token, '异常')
        log_exception('ESC 稳定退层事务失败', e)
      end

      runtime_start_timer(
        0.01, false, label: 'workspace:esc_stable_step',
        key: "workspace:esc_stable_step:#{key}", model: model, active_model_only: true
      ) { tick.call }
      true
    rescue StandardError => e
      log_exception('启动 ESC 稳定退层事务失败', e)
      false
    end

    def workspace_double_click_pick_path(view, x, y)
      helper = view.pick_helper
      helper.do_pick(x, y)
      best = helper.best_picked
      path = nil
      begin
        path = helper.path_at(0) if helper.count.to_i.positive?
      rescue StandardError
        path = nil
      end
      [best, Array(path)]
    rescue StandardError
      [nil, []]
    end

    def workspace_double_click_pick_matches?(candidate, view, x, y)
      entity = candidate.is_a?(Hash) ? candidate[:entity] : nil
      return false unless entity && entity.valid?
      best, path = workspace_double_click_pick_path(view, x, y)
      best == entity || path.include?(entity)
    rescue StandardError
      false
    end

    def workspace_double_click_select_other_root(model, view, x, y)
      best, path = workspace_double_click_pick_path(view, x, y)
      root = path.find do |entry|
        entry && entry.valid? &&
          (entry.is_a?(Sketchup::Group) || entry.is_a?(Sketchup::ComponentInstance))
      end
      root ||= best
      model.selection.clear
      return true unless root && root.valid?
      model.selection.add(root)
      true
    rescue StandardError
      false
    end

    # 单件家具代理进入真模型编辑后，退出组件层级必须形成一个完整的“编辑事务”。
    # 旧流程要求用户退出后再手动点“家具入库”，非常容易遗忘，随后再切代/真就会让
    # 旧代理尺寸与刚改过的真模型互相打架。这里记录进入编辑前的代理 Definition / 变换，
    # 退出时统一询问：完成=写回原 model_id 并重建六面代理；取消=恢复进入前代理，不写库。
    def soft_individual_edit_session(model = Sketchup.active_model)
      return nil unless model
      @soft_individual_edit_sessions ||= {}
      record = @soft_individual_edit_sessions[model.object_id]
      return nil unless record.is_a?(Hash)
      entity = record[:entity]
      unless entity && entity.valid?
        detach_soft_individual_edit_entities_observers!(record)
        cleanup_soft_individual_edit_definitions!(record, model)
        @soft_individual_edit_sessions.delete(model.object_id)
        return nil
      end
      record
    rescue StandardError
      nil
    end

    # v0.13.6.150：为当前家具编辑层级挂实体级修改观察器。
    # 只监听用户此刻真正进入的 active_entities；进入更深子组件时 ActivePathChanged
    # 会补挂新的集合。这样无需遍历整个高模 Definition 图，也能覆盖真模型直接编辑。
    # v0.13.6.154：单件家具编辑会话是“瞬时控制状态”，不能比 SketchUp 的真实
    # active_path 更权威。旧版只要 @soft_individual_edit_sessions 里残留一条 Hash，
    # 下一件家具就会永久被“已有一件家具处于真模型编辑/自动收尾中”挡住；发布、
    # 热重载或确认 Tool 丢失后尤其容易形成这种幽灵会话。这里统一做自愈：
    # 真正仍在家具 active_path 内才算活跃编辑；已经退出但会话还在，则按默认“否”
    # 完成收尾（有修改则安全写库并登记代理，无修改则结束查看）。
    def soft_individual_edit_entity_inside?(record, model = Sketchup.active_model)
      return false unless record.is_a?(Hash) && model
      entity = record[:entity]
      return false unless entity && entity.valid?
      Array(model.active_path).include?(entity)
    rescue StandardError
      false
    end

    # v0.13.6.165：双击桥在家具退出/Tool 切换的极短窗口里可能暂时让回原生
    # SelectionTool。若用户连续“退出 -> 立即再双击”，SketchUp 有机会先于 LinkHub
    # 直接把六面代理（或尚未登记编辑事务的真模型）打开成普通组件编辑，从而看到
    # 六面体内部而不是进入 LinkHub 的安全真模型编辑。这里把 active_path 作为最后一道
    # 防线：只要发现当前协同空间里已经原生钻进了受管家具、但没有对应单件家具编辑
    # 会话，就立即退回该家具的父层级、重新选中家具并武装 LinkHub 双击确认。
    def native_soft_furniture_entry_without_session(model = Sketchup.active_model)
      return nil unless model
      path = Array(model.active_path).select { |node| node && node.valid? }
      return nil if path.length < 2
      active_session = soft_individual_edit_session(model)
      state, space_item, space_entity = current_local_editing_space(nil, model, required: false)
      return nil unless space_item && space_entity && space_entity.valid?
      return nil unless path.first.equal?(space_entity)

      managed_index = nil
      managed_entity = nil
      managed_info = nil
      managed_representation = ''
      path.each_with_index do |node, index|
        next if index.zero?
        next unless node.is_a?(Sketchup::ComponentInstance) || node.is_a?(Sketchup::Group)
        info = soft_instance_metadata(node) rescue {}
        model_id = info['model_id'].to_s
        representation = soft_instance_representation(node).to_s rescue ''
        next if model_id.empty? || !%w[proxy full].include?(representation)
        managed_index = index
        managed_entity = node
        managed_info = info
        managed_representation = representation
        break
      end
      return nil unless managed_entity && managed_entity.valid?

      # 正常 LinkHub 单件家具编辑会话已经在 active_path= 之前建立，绝不能误拦。
      if active_session.is_a?(Hash) && active_session[:entity] && active_session[:entity].valid?
        return nil if active_session[:entity].equal?(managed_entity) && soft_individual_edit_entity_inside?(active_session, model)
      end

      {
        entity: managed_entity,
        model_id: managed_info['model_id'].to_s,
        model_name: managed_info['model_name'].to_s,
        representation: managed_representation,
        parent_path: path[0...managed_index],
        space_id: space_item['id'].to_s
      }
    rescue StandardError => e
      log_exception('识别原生误入家具编辑层级失败', e)
      nil
    end

    # 把同一家具定义的其它实例重新锁上（只处理受管软装、只上锁不解锁）。
    def relock_soft_furniture_siblings!(entity, model = Sketchup.active_model)
      return 0 unless entity && entity.valid? && entity.respond_to?(:definition)
      siblings = entity.definition.instances.select do |instance|
        instance.valid? && !instance.equal?(entity) && instance.respond_to?(:locked?) && !instance.locked?
      end
      return 0 if siblings.empty?
      model.start_operation('重新锁定同款家具', true, false, true)
      siblings.each { |instance| instance.locked = true rescue nil }
      model.commit_operation
      siblings.length
    rescue StandardError => e
      model.abort_operation rescue nil
      log_exception('重新锁定同款家具失败', e)
      0
    end

    def guard_native_soft_furniture_entry!(model = Sketchup.active_model)
      return false unless model
      @native_soft_furniture_entry_guard ||= {}
      key = model.object_id
      return false if @native_soft_furniture_entry_guard[key]
      hit = native_soft_furniture_entry_without_session(model)
      return false unless hit.is_a?(Hash)
      entity = hit[:entity]
      return false unless entity && entity.valid?

      @native_soft_furniture_entry_guard[key] = true
      parent_path = Array(hit[:parent_path]).select { |node| node && node.valid? }
      begin
        # 这是家具内部的误入回退，不是“退出空间”；允许随后立即重新武装双击桥。
        @workspace_escape_suppress_until&.delete(key)
        suppress_workspace_double_click_rearm!(model, seconds: 0.0)
        @workspace_double_click_rearm_suppress_until&.delete(key)
        model.active_path = (parent_path.empty? ? nil : parent_path) if model.respond_to?(:active_path=)
        # v0.13.7.7：若用户在 SketchUp 原生提示里点了“全部解锁”，同一家具的其它实例
        # （含联动副本里的同一件）都被解锁了；立即把它们重新锁上，防止一次编辑改动全部。
        relocked = relock_soft_furniture_siblings!(entity, model)
        model.selection.clear rescue nil
        model.selection.add(entity) rescue nil
        label = hit[:model_name].to_s
        label = entity.name.to_s if label.empty? && entity.respond_to?(:name)
        label = '家具' if label.empty?
        log("检测到原生误入受管家具，已退回父层并重新接管：#{label} / #{hit[:representation]} / #{hit[:model_id]} / 重新锁定同款 #{relocked} 个")
        candidate = { entity: entity, id: hit[:model_id].to_s, space_id: hit[:space_id].to_s }
        runtime_start_timer(0.02, false, label: 'soft:native_entry_rearm', key: "soft:native_entry_rearm:#{key}", model: model, active_model_only: true) do
          @workspace_escape_suppress_until&.delete(key) if !model.active_path.nil?
          @workspace_double_click_rearm_suppress_until&.delete(key)
          # 直接改走 LinkHub 安全单件编辑（只让这一件独立，其它同款保持不变），无需再次双击确认。
          begin
            edit_soft_proxy_instance_via_double_click!(candidate, model)
            show_workspace_floating_notice("已自动改为只编辑这一件 · #{label} · 同款其它家具不受影响", 'info', duration: 3.2, model: model)
          rescue StandardError => edit_error
            log("原生误入后自动进入安全编辑失败：#{edit_error.message}")
            show_workspace_floating_notice("已阻止直接编辑共享家具 · #{label} · 请再次双击进入（#{edit_error.message}）", 'info', duration: 4.0, model: model)
            arm_workspace_double_click_candidate(model)
          end
        end
      ensure
        @native_soft_furniture_entry_guard.delete(key)
      end
      true
    rescue StandardError => e
      @native_soft_furniture_entry_guard&.delete(model.object_id) if model
      log_exception('阻止原生误入家具编辑层级失败', e)
      false
    end

    # v0.13.6.171：SketchUp 的 active_path= 检查的是“occurrence 是否被锁传播”，
    # 不只是 instance.locked?。一个家具兄弟实例自身可能 locked? == false，但只要它位于
    # 某个 locked 的父组件 occurrence 内，SketchUp 仍会抛出：
    # ArgumentError: Cannot open instance path with locked sibling instances。
    #
    # 旧版只解开 Definition#instances 中直接 locked 的实例，遗漏了这种父级锁传播。
    # 现在沿 instance -> parent Definition -> parent Definition 的 instances 递归向上，
    # 只收集真正造成锁传播的“直接 locked occurrence”，临时解锁后再进入家具；退出时
    # 仍由 restore_soft_individual_edit_path_locks! 按原状态逐个恢复。
    def soft_individual_edit_locked_occurrence_blockers(definition, trail = nil, depth = 0)
      return [] unless definition && definition.valid?
      return [] if depth.to_i > 32
      path = trail.is_a?(Hash) ? trail.dup : {}
      key = definition.object_id
      return [] if path[key]
      path[key] = true

      blockers = []
      instances = definition.respond_to?(:instances) ? definition.instances.to_a : []
      instances.each do |instance|
        next unless instance && instance.valid?
        if instance.respond_to?(:locked?) && instance.respond_to?(:locked=) && instance.locked?
          blockers << instance
        end
        parent_definition = space_edit_instance_parent_definition(instance)
        if parent_definition && parent_definition.valid?
          blockers.concat(
            soft_individual_edit_locked_occurrence_blockers(parent_definition, path, depth.to_i + 1)
          )
        end
      rescue StandardError
        next
      end
      blockers.uniq
    rescue StandardError
      []
    end

    def unlock_soft_individual_edit_path_siblings!(path, model = Sketchup.active_model)
      return [] unless model
      rows = []
      recorded = {}
      seen = {}
      definitions = Array(path).filter_map do |node|
        next unless node && node.valid? && node.respond_to?(:definition)
        definition = node.definition rescue nil
        next unless definition && definition.valid?
        oid = definition.object_id
        next if seen[oid]
        seen[oid] = true
        definition
      end

      # 最多做三轮：第一轮通常已经清完；额外轮次用于处理某些 SketchUp 版本在解除
      # 外层 occurrence 锁后才暴露出来的下一层锁传播。只解真正处于 locked 状态的实体。
      3.times do
        blockers = definitions.flat_map do |definition|
          soft_individual_edit_locked_occurrence_blockers(definition)
        end.compact.uniq
        blockers.select! do |instance|
          instance && instance.valid? && instance.respond_to?(:locked?) &&
            instance.respond_to?(:locked=) && instance.locked?
        rescue StandardError
          false
        end
        break if blockers.empty?

        changed = 0
        blockers.each do |instance|
          key = instance.object_id
          unless recorded[key]
            rows << { instance: instance, definition: (instance.definition rescue nil), locked: true }
            recorded[key] = true
          end
          instance.locked = false
          changed += 1
        rescue StandardError
          next
        end
        break if changed.zero?
      end

      remaining = definitions.count { |definition| space_edit_definition_has_locked_occurrence?(definition) rescue false }
      log("家具编辑路径临时解除锁传播：#{rows.length} 个直接锁 occurrence#{remaining.positive? ? "；仍有#{remaining}个Definition存在锁传播" : ''}") if rows.any? || remaining.positive?
      rows
    rescue StandardError => e
      log_exception('临时解除家具编辑路径锁传播失败', e)
      rows || []
    end

    def restore_soft_individual_edit_path_locks!(record, model = Sketchup.active_model)
      return 0 unless record.is_a?(Hash) && model
      rows = Array(record[:path_unlocks])
      record[:path_unlocks] = []
      return 0 if rows.empty?
      state = load_state(model) rescue {}
      restored = 0
      kept_for_space_isolation = 0
      rows.reverse_each do |row|
        instance = row.is_a?(Hash) ? row[:instance] : nil
        next unless instance && instance.valid? && instance.respond_to?(:locked=)
        # 其它“参考空间根”若本来就应该在当前空间编辑期间保持临时解锁，则不要
        # 因家具退出把它重新锁上；真正退出空间时 restore_space_isolation! 会按快照恢复。
        keep_unlocked = false
        if state.is_a?(Hash) && instance.respond_to?(:get_attribute)
          sid = instance.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
          unless sid.empty?
            item = space_model_record(state, sid) rescue nil
            keep_unlocked = !!(item && space_reference_root_temporarily_unlocked?(item, instance, state, model))
          end
        end
        if keep_unlocked
          kept_for_space_isolation += 1
          next
        end
        instance.locked = true if row[:locked] == true
        restored += 1 if row[:locked] == true
      rescue StandardError
        next
      end
      log("家具编辑路径恢复同定义兄弟锁：#{restored} 个实例；空间隔离继续保持解锁 #{kept_for_space_isolation} 个") if restored.positive? || kept_for_space_isolation.positive?
      log("家具编辑路径恢复同定义兄弟锁：#{restored} 个实例") if restored.positive?
      restored
    rescue StandardError => e
      log_exception('恢复家具编辑路径兄弟锁失败', e)
      0
    end

    # 用户显式执行“家具入库/更新模型库”并成功后，如果同一款家具之前留下
    # save_failed，会话就不应继续永久封锁双击/发布。只有源模型已明确写回，或该
    # 实例已经回到权威代理终态时才退休失败会话；其余情况仍保守保留。
    def retire_soft_save_failed_session_after_explicit_repair!(model_id, model = Sketchup.active_model, source_updated: false)
      return false unless model
      record = soft_individual_edit_session(model)
      return false unless record.is_a?(Hash) && record[:phase].to_s == 'save_failed'
      return false unless record[:model_id].to_s == model_id.to_s && !model_id.to_s.empty?
      return false if soft_individual_edit_entity_inside?(record, model)
      entity = record[:entity]
      authoritative_proxy = entity && entity.valid? &&
                            soft_instance_representation_ready?(entity, 'proxy') &&
                            soft_instance_uses_authoritative_visual_proxy?(entity)
      return false unless source_updated || authoritative_proxy
      if entity && entity.valid?
        clear_soft_individual_edit_markers!(entity)
        clear_soft_individual_edit_save_failed_marker!(entity)
      end
      restore_soft_individual_edit_path_locks!(record, model)
      detach_soft_individual_edit_entities_observers!(record)
      @soft_individual_edit_sessions&.delete(model.object_id)
      cleanup_soft_individual_edit_definitions!(record, model)
      log("显式家具入库已解除旧 save_failed 会话：#{record[:model_name]} / #{model_id}")
      true
    rescue StandardError => e
      log_exception('显式家具入库解除 save_failed 会话失败', e)
      false
    end

    def reconcile_orphan_soft_individual_edit_session!(model = Sketchup.active_model, reason: '', force: false)
      record = soft_individual_edit_session(model)
      return nil unless record.is_a?(Hash)
      entity = record[:entity]
      return nil unless entity && entity.valid?
      phase = record[:phase].to_s
      inside = soft_individual_edit_entity_inside?(record, model)

      # 真实仍在该家具内部时绝不能猜测收尾。
      return record if inside && phase == 'editing'
      # v0.13.6.181：保存失败后，用户修改已经安全留在当前项目的 unique 真模型里。
      # 旧版把 save_failed 会话永久留在全局表中，导致其它家具、发布和代真切换全部被锁死。
      # 只要已经退出该家具真实 active_path，就把失败状态落到该实例自身并释放全局会话。
      if phase == 'save_failed'
        return record if inside
        quarantined = quarantine_soft_individual_edit_save_failure!(
          record, nil, model, reason: (record[:save_error].to_s.empty? ? reason.to_s : record[:save_error].to_s)
        )
        return nil if quarantined
        return record
      end

      # 正常 ESC 退出后的 0.12s settle 窗口仍然保留；只有新操作/发布明确要求 force
      # 时才可提前接管。避免最后一拍 transaction 尚未到达就过早判定“未修改”。
      unless force
        recent_exit = record[:exit_detected_at].to_f
        if phase == 'editing' && recent_exit.positive? && (monotonic_time - recent_exit) < 0.30
          return record
        end
      end

      # waiting_publish 正常路径在 finalize 中已经从会话表删除；能走到这里说明只是
      # 遗留控制记录，直接退休即可，不重复写库。
      if %w[waiting_publish waiting_proxy].include?(phase)
        restore_soft_individual_edit_path_locks!(record, model)
        detach_soft_individual_edit_entities_observers!(record)
        @soft_individual_edit_sessions&.delete(model.object_id)
        cleanup_soft_individual_edit_definitions!(record, model)
        log("已清理家具幽灵会话：#{record[:model_name]} / phase=#{phase} / reason=#{reason}")
        return nil
      end

      # 已经退出真实 active_path，却仍停在 editing / awaiting_proxy_choice / saving 等
      # 状态：按退出确认默认“否”完成。这样不会丢修改，也不会强制立即生成代理。
      if %w[editing prompting awaiting_proxy_choice saving unchanged].include?(phase) || phase.empty?
        record[:exit_token] = ''
        record[:exit_confirmation_token] = ''
        record[:exit_confirmation_tool] = nil
        detach_soft_individual_edit_entities_observers!(record) if phase != 'editing'
        if soft_individual_edit_content_unchanged?(record)
          record[:phase] = :unchanged
          cancel_soft_individual_edit!(record, model, no_change: true)
          schedule_restore_default_select_tool(
            model, delay: 0.02, reason: '家具未修改退出', rearm_workspace_candidate: true
          ) rescue nil
          log("家具幽灵会话自动结束（未修改）：#{record[:model_name]} / reason=#{reason}")
        else
          record[:phase] = :saving
          ok = finalize_soft_individual_edit!(record, model)
          unless ok
            record[:phase] = :save_failed
            return record
          end
          log("家具幽灵会话自动收尾（已保存）：#{record[:model_name]} / reason=#{reason}")
        end
        return soft_individual_edit_session(model)
      end

      # 未知旧版本 phase：若已不在家具内部，也按保守的“有修改”路径尝试完成，
      # 失败则保留 save_failed，绝不直接删除可能未保存的数据。
      unless inside
        record[:phase] = :saving
        ok = finalize_soft_individual_edit!(record, model)
        return nil if ok
        record[:phase] = :save_failed
      end
      record
    rescue StandardError => e
      record[:phase] = :save_failed if defined?(record) && record.is_a?(Hash)
      log_exception('家具幽灵编辑会话自愈失败', e)
      record
    end

    def reconcile_soft_individual_edit_after_boot!(model = Sketchup.active_model)
      return false unless model
      record = soft_individual_edit_session(model)
      return true unless record
      # 热重载时仍真实处于家具内部：保留会话并重新挂 observer；否则旧 Tool/timer
      # 不再可信，直接走默认“否”收尾。
      if soft_individual_edit_entity_inside?(record, model) && record[:phase].to_s == 'editing'
        record[:exit_token] = ''
        record[:exit_confirmation_token] = ''
        record[:exit_confirmation_tool] = nil
        record[:observe_changes] = true
        record[:last_inside_at] = monotonic_time
        ensure_soft_individual_edit_entities_observer!(record, model)
        log("热重载接回真实家具编辑会话：#{record[:model_name]}")
        return true
      end
      reconcile_orphan_soft_individual_edit_session!(model, reason: '热重载/启动恢复', force: true)
      true
    rescue StandardError => e
      log_exception('启动后家具编辑会话恢复失败', e)
      false
    end

    def finalize_soft_individual_edit_before_space_publish!(space_id, model = Sketchup.active_model)
      record = soft_individual_edit_session(model)
      return true unless record
      record_space_id = record[:space_id].to_s
      target_space_id = space_id.to_s
      if !record_space_id.empty? && !target_space_id.empty? && record_space_id != target_space_id
        label = record[:model_name].to_s.empty? ? '另一件家具' : "“#{record[:model_name]}”"
        raise "#{label}仍属于另一个空间的家具编辑事务；请先完成该空间，再发布当前空间。"
      end
      remaining = reconcile_orphan_soft_individual_edit_session!(
        model, reason: "发布空间 #{target_space_id} 前统一结清家具编辑", force: true
      )
      unless remaining
        # 局部写库失败不再阻断发布；这些实例会在代理准备阶段自动保持真模型。
        # 给用户明确说明“谁被保留、其它内容仍会发布”，避免再次出现只说失败不说办法。
        begin
          space_entity = space_model_entity(target_space_id, model)
          failed_instances = space_entity && space_entity.valid? ? soft_instances_for_space(space_entity, model).select { |node| soft_individual_edit_save_failed?(node) } : []
          unless failed_instances.empty?
            names = soft_proxy_switch_instance_summary(failed_instances)
            show_workspace_floating_notice("发布继续 · #{names} 保持真模型", 'warning', duration: 5.5, model: model)
            show_status("#{names} 的修改尚未成功写回模型库，本次发布会保留它们的当前真模型；其它家具正常按代理发布。之后重新执行“家具入库”即可修复并恢复代理。", 'warning')
          end
        rescue StandardError
          nil
        end
        return true
      end
      label = remaining[:model_name].to_s.empty? ? '当前家具' : "“#{remaining[:model_name]}”"
      if soft_individual_edit_entity_inside?(remaining, model)
        raise "#{label}仍真实处于组件编辑层级；请先退出家具后再发布空间。"
      end
      if remaining[:phase].to_s == 'save_failed'
        raise "#{label}上一次家具修改自动保存失败；为避免丢失修改，空间发布已停止。请先重新退出/处理该家具。"
      end
      raise "#{label}的家具编辑收尾尚未完成，请稍候后再发布空间。"
    end

    def ensure_soft_individual_edit_entities_observer!(record, model = Sketchup.active_model)
      return false unless record.is_a?(Hash) && model
      return false unless record[:phase].to_s == 'editing' && record[:observe_changes] == true
      entity = record[:entity]
      return false unless entity && entity.valid?
      return false unless Array(model.active_path).include?(entity)
      entities = model.active_entities rescue nil
      return false unless entities && entities.respond_to?(:add_observer)
      record[:entity_observers] ||= {}
      key = entities.object_id
      return true if record[:entity_observers].key?(key)
      observer = SoftIndividualEditEntitiesObserver.new(model)
      entities.add_observer(observer)
      record[:entity_observers][key] = { entities: entities, observer: observer }
      true
    rescue StandardError => e
      log_exception('挂接家具编辑实体观察器失败', e)
      false
    end

    def detach_soft_individual_edit_entities_observers!(record)
      return false unless record.is_a?(Hash)
      rows = record[:entity_observers]
      return true unless rows.is_a?(Hash)
      rows.each_value do |entry|
        entities = entry.is_a?(Hash) ? entry[:entities] : nil
        observer = entry.is_a?(Hash) ? entry[:observer] : nil
        entities.remove_observer(observer) if entities && observer && entities.respond_to?(:remove_observer)
      rescue StandardError
        nil
      end
      rows.clear
      true
    rescue StandardError
      false
    end

    def mark_soft_individual_edit_entities_change!(model = Sketchup.active_model)
      return false unless model
      record = @soft_individual_edit_sessions && @soft_individual_edit_sessions[model.object_id]
      return false unless record.is_a?(Hash) && record[:phase].to_s == 'editing'
      return false unless record[:observe_changes] == true
      ignore_until = record[:ignore_transactions_until].to_f
      return false if ignore_until.positive? && monotonic_time < ignore_until
      entity = record[:entity]
      return false unless entity && entity.valid?
      record[:content_changed] = true
      record[:content_change_events] = record[:content_change_events].to_i + 1
      if record[:content_change_events] == 1
        log("家具编辑修改跟踪已标记：source=entities / representation=#{record[:entry_representation]}")
      end
      true
    rescue StandardError
      false
    end

    # v0.13.6.77：这里只做 SketchUp 已长期验证稳定的“最外层 make_unique”。
    # v0.13.6.76 曾在代理切真后递归改写整棵嵌套 Definition 图；部分复杂家具会在
    # SketchUp 原生组件依赖重建时直接崩溃，Ruby rescue 无法捕获。取消时通过清除
    # 本次源真模 resident/cache 引用，确保后续再次切真会从模型库重新载入，而不是
    # 继续复用本次可能被嵌套编辑污染的会话高模。
    def isolate_soft_individual_edit_definition_graph!(root_instance, model = Sketchup.active_model)
      raise '待编辑家具实例无效。' unless root_instance && root_instance.valid? && root_instance.respond_to?(:definition)
      original = root_instance.definition
      preserved_matrix = root_instance.transformation.to_a.map(&:to_f)
      root_instance.make_unique if root_instance.respond_to?(:make_unique)
      restore_instance_exact_transform_matrix!(root_instance, preserved_matrix, '单件家具编辑隔离')
      isolated = root_instance.definition
      raise 'SketchUp 未能建立独立的家具编辑定义。' unless isolated && isolated.valid?
      created = (isolated == original ? [] : [isolated])
      { root_definition: isolated, definitions: created }
    rescue StandardError => e
      log_exception('隔离单件家具最外层定义失败', e)
      raise
    end

    # 单件编辑结束后，进入编辑前那份 resident 真模型不能继续作为快速切真缓存。
    # 特别是用户曾进入二级/三级组件时，最外层 make_unique 并不会复制所有嵌套 Definition；
    # 清除 resident + loaded 快路径后，下一次切真会按源文件当前签名重新载入。
    def invalidate_soft_individual_edit_source_full_cache!(record, model = Sketchup.active_model)
      return false unless record.is_a?(Hash) && model
      definition = record[:source_full_definition]
      return true unless definition && definition.valid?
      forget_soft_resident_definition_references!(definition, model)
      invalidate_soft_representation_pair_cache!(model, definition: definition)
      soft_clear_definition_bounds_cache!(definition)
      # 去掉旧签名，避免 cached_soft_library_definition 在 Ruby 缓存清空后扫描 definitions
      # 时又把这份旧/可能受嵌套编辑影响的 Definition 认回当前权威源。现有实例仍可显示。
      definition.delete_attribute(SOFT_MODEL_DICT, 'source_signature') rescue nil
      true
    rescue StandardError => e
      log_exception('清除单件家具旧真模缓存失败', e)
      false
    end

    def cleanup_soft_individual_edit_definitions!(record, model = Sketchup.active_model)
      return 0 unless record.is_a?(Hash) && model
      pending = Array(record[:edit_definitions]).select { |definition| definition && definition.valid? }.uniq
      removed = 0
      loop do
        removed_this_pass = 0
        pending.delete_if do |definition|
          deleted = remove_unused_definition!(definition, model)
          if deleted
            removed += 1
            removed_this_pass += 1
          end
          deleted
        end
        break if pending.empty? || removed_this_pass.zero?
      end
      removed
    rescue StandardError => e
      log_exception('清理单件家具隔离定义失败', e)
      0
    end

    # v0.13.6.100：单件家具只有“内容真的变化”才写回模型库并重建六面代理。
    # 签名在自动切真、make_unique、历史壳修复全部完成之后采集，因此这些 LinkHub
    # 自己的准备动作不会被误判为用户修改。签名失败时返回空串，退出时按安全策略
    # 默认更新，宁可多算一次代理，也不能漏掉真实修改。
    def soft_edit_material_signature(material)
      return '' unless material
      color = material.respond_to?(:color) ? material.color : nil
      color_text = color ? [color.red, color.green, color.blue, (material.respond_to?(:alpha) ? material.alpha.to_f : 1.0)].join(',') : ''
      texture = material.respond_to?(:texture) ? material.texture : nil
      texture_name = texture && texture.respond_to?(:filename) ? texture.filename.to_s : ''
      [material.respond_to?(:name) ? material.name.to_s : '', color_text, texture_name].join('|')
    rescue StandardError
      ''
    end

    def soft_edit_point_signature(point)
      return '' unless point
      [point.x, point.y, point.z].map { |value| format('%.9f', value.to_f) }.join(',')
    rescue StandardError
      ''
    end

    def soft_edit_transform_signature(transformation)
      return '' unless transformation
      transformation.to_a.map { |value| format('%.9f', value.to_f) }.join(',')
    rescue StandardError
      ''
    end

    def soft_edit_face_uv_signature(face)
      return '' unless face && face.valid?
      front_tex = face.material && face.material.respond_to?(:texture) ? face.material.texture : nil
      back_tex = face.back_material && face.back_material.respond_to?(:texture) ? face.back_material.texture : nil
      return '' unless front_tex || back_tex
      helper = face.get_UVHelper(true, true)
      face.vertices.map do |vertex|
        point = vertex.position
        front = if front_tex
                  uvq = helper.get_front_UVQ(point)
                  [uvq.x, uvq.y, uvq.z].map { |v| format('%.9f', v.to_f) }.join(',')
                else
                  ''
                end
        back = if back_tex
                 uvq = helper.get_back_UVQ(point)
                 [uvq.x, uvq.y, uvq.z].map { |v| format('%.9f', v.to_f) }.join(',')
               else
                 ''
               end
        "#{front}/#{back}"
      end.join(';')
    end

    def soft_individual_edit_content_signature(root_instance, max_entities: 180_000)
      return '' unless root_instance && root_instance.valid? && root_instance.respond_to?(:definition)
      root_definition = root_instance.definition
      return '' unless root_definition && root_definition.valid?

      # 内容签名故意不写 persistent_id / object_id / Definition 名称。
      # 这些“身份值”可能因为 make_unique、旧壳折叠等安全准备动作改变，但几何内容完全相同。
      # 这里按“实体语义 + 嵌套内容”生成排序后的结构指纹，因此仅复制 Definition 而不改模型
      # 不会误判为用户修改；真正新增/删除/移动/缩放/改材质/贴图 UV 则一定改变签名。
      definition_cache = {}
      visiting = {}
      entity_count = 0

      definition_signature = nil
      definition_signature = lambda do |definition|
        raise 'definition invalid' unless definition && definition.valid?
        oid = definition.object_id
        cached = definition_cache[oid]
        return cached if cached
        raise 'recursive definition graph' if visiting[oid]
        visiting[oid] = true

        rows = definition.entities.to_a.filter_map do |entity|
          next unless entity && entity.valid?
          entity_count += 1
          raise "signature entity limit #{max_entities}" if entity_count > max_entities.to_i

          layer_name = entity.respond_to?(:layer) && entity.layer ? entity.layer.name.to_s : ''
          hidden = entity.respond_to?(:hidden?) ? (entity.hidden? ? 1 : 0) : 0
          material = entity.respond_to?(:material) ? soft_edit_material_signature(entity.material) : ''
          base = [entity.class.name.to_s, layer_name, hidden, material]

          case entity
          when Sketchup::Edge
            (base + [soft_edit_point_signature(entity.start.position), soft_edit_point_signature(entity.end.position),
                     (entity.respond_to?(:soft?) && entity.soft? ? 1 : 0),
                     (entity.respond_to?(:smooth?) && entity.smooth? ? 1 : 0)]).join('|')
          when Sketchup::Face
            vertices = entity.vertices.map { |vertex| soft_edit_point_signature(vertex.position) }.join(';')
            back = entity.respond_to?(:back_material) ? soft_edit_material_signature(entity.back_material) : ''
            uv = soft_edit_face_uv_signature(entity)
            (base + [vertices, back, uv]).join('|')
          when Sketchup::ComponentInstance, Sketchup::Group
            name = entity.respond_to?(:name) ? entity.name.to_s : ''
            locked = entity.respond_to?(:locked?) ? (entity.locked? ? 1 : 0) : 0
            child = entity.definition rescue nil
            raise 'child definition invalid' unless child && child.valid?
            child_signature = definition_signature.call(child)
            (base + [name, locked, soft_edit_transform_signature(entity.transformation), child_signature]).join('|')
          when Sketchup::ConstructionPoint
            (base + [soft_edit_point_signature(entity.position)]).join('|')
          else
            # 对未覆盖的特殊实体不猜“没变化”。尺寸、图片、剖面、文字等少见实体
            # 一旦存在，本次签名判定降级为“默认更新”，避免漏掉真实修改。
            raise "unsupported edit entity #{entity.class.name}"
          end
        end

        behavior = definition.respond_to?(:behavior) ? definition.behavior : nil
        behavior_signature = if behavior
                               [
                                 (behavior.respond_to?(:cuts_opening?) && behavior.cuts_opening? ? 1 : 0),
                                 (behavior.respond_to?(:always_face_camera?) && behavior.always_face_camera? ? 1 : 0),
                                 (behavior.respond_to?(:shadows_face_sun?) && behavior.shadows_face_sun? ? 1 : 0),
                                 (behavior.respond_to?(:snapto) ? behavior.snapto.to_i : 0)
                               ].join(',')
                             else
                               ''
                             end
        insertion = definition.respond_to?(:insertion_point) ? soft_edit_point_signature(definition.insertion_point) : ''
        digest = Digest::SHA256.hexdigest((["B=#{behavior_signature}", "I=#{insertion}"] + rows.sort).join("\n"))
        signature = "D:#{rows.length}:#{digest}"
        definition_cache[oid] = signature
        visiting.delete(oid)
        signature
      ensure
        visiting.delete(oid) if defined?(oid) && oid && !definition_cache.key?(oid)
      end

      root_sig = definition_signature.call(root_definition)
      "v2:#{entity_count}:#{Digest::SHA256.hexdigest(root_sig)}"
    rescue StandardError => e
      log("家具内容签名不可用，将按安全策略默认更新：#{e.class}: #{e.message}")
      ''
    end

    def soft_individual_edit_content_unchanged?(record)
      return false unless record.is_a?(Hash)
      # v0.13.6.109：新会话由 ModelObserver 记录编辑期间是否发生过事务。
      # 退出时只读一个布尔值，避免再次递归扫描数十万条边、面、材质和 UV。
      if record[:change_tracking].to_s == 'transaction'
        return record[:content_changed] != true
      end

      # 兼容热加载升级前已经建立的旧会话；旧会话没有事务标记，只能沿用内容签名。
      before = record[:content_signature_before].to_s
      return false if before.empty?
      entity = record[:entity]
      return false unless entity && entity.valid?
      after = soft_individual_edit_content_signature(entity)
      return false if after.empty?
      record[:content_signature_after] = after
      before == after
    rescue StandardError
      false
    end

    def mark_soft_individual_edit_transaction_change!(model = Sketchup.active_model)
      return false unless model
      record = @soft_individual_edit_sessions && @soft_individual_edit_sessions[model.object_id]
      return false unless record.is_a?(Hash) && record[:phase].to_s == 'editing'
      return false unless record[:observe_changes] == true
      return false if soft_representation_switching?(model) || publish_critical_section? || publish_post_quiet?
      # SketchUp 部分版本会在 active_path= 返回后才补发“进入组件”的事务提交。
      # 这仍是插件入口动作，不是用户改动；短隔离窗只覆盖这一拍延迟回调。
      ignore_until = record[:ignore_transactions_until].to_f
      return false if ignore_until.positive? && monotonic_time < ignore_until
      entity = record[:entity]
      return false unless entity && entity.valid?
      inside = Array(model.active_path).include?(entity)
      recent_inside = (monotonic_time - record[:last_inside_at].to_f) <= 0.75
      # v0.13.6.150：复杂真模型最后一次 commit 可能落在 active_path 退层之后。
      # 只要该编辑会话仍处于 editing，且 0.75 秒内刚刚还在家具树中，就应把这次
      # commit 算作家具修改；避免真模型路径漏标记，同时不会吞进之后的其它空间操作。
      return false unless inside || recent_inside
      record[:content_changed] = true
      record[:content_change_events] = record[:content_change_events].to_i + 1
      if record[:content_change_events] == 1
        log("家具编辑修改跟踪已标记：source=transaction / representation=#{record[:entry_representation]}")
      end
      true
    rescue StandardError
      false
    end

    # 空间发布只需要知道“本次编辑会话是否发生过内容事务”，不需要在发布按钮
    # 被点击后递归遍历几十万条边面。记录只存在于当前 SketchUp 进程，并随热重载
    # 交接；若记录丢失则按保守策略正常发布，绝不会漏交真实修改。
    def space_edit_change_session(model, space_id)
      return nil unless model
      records = @space_edit_change_sessions && @space_edit_change_sessions[model.object_id]
      records.is_a?(Hash) ? records[space_id.to_s] : nil
    rescue StandardError
      nil
    end

    def start_or_resume_space_edit_change_session!(item, entity, model = Sketchup.active_model, new_session: false)
      return false unless item && entity && entity.valid? && model
      @space_edit_change_sessions ||= {}
      records = (@space_edit_change_sessions[model.object_id] ||= {})
      space_id = item['id'].to_s
      record = records[space_id]
      if new_session
        record = {
          entity: entity,
          content_changed: false,
          content_change_events: 0,
          entry_transformation: entity.transformation.to_a.map(&:to_f),
          entry_definition_guid: space_edit_definition_guid(entity),
          started_at: Time.now.to_f
        }
        records[space_id] = record
      elsif !record.is_a?(Hash)
        # 插件安装前已经开始的编辑会话没有可信基线，不能凭空认定为未修改。
        return false
      end
      record[:entity] = entity
      record[:observe_changes] = true
      record[:ignore_transactions_until] = monotonic_time + 0.18
      true
    rescue StandardError => e
      log_exception('建立空间轻量修改跟踪失败', e)
      false
    end

    def mark_current_space_session_shared_component_change!(component_id, model = Sketchup.active_model)
      id = component_id.to_s
      return false if id.empty? || !model
      records = @space_edit_change_sessions && @space_edit_change_sessions[model.object_id]
      return false unless records.is_a?(Hash) && !records.empty?
      path = Array(model.active_path)
      root = path.first
      space_id = root && root.respond_to?(:get_attribute) ? root.get_attribute(ENTITY_DICT, 'space_id', '').to_s : ''
      return false if space_id.empty?
      record = records[space_id]
      return false unless record.is_a?(Hash)
      record[:shared_component_changed_ids] ||= {}
      record[:shared_component_changed_ids][id] = true
      true
    rescue StandardError
      false
    end

    def clear_space_edit_change_session!(model, space_id)
      return false unless model
      records = @space_edit_change_sessions && @space_edit_change_sessions[model.object_id]
      return false unless records.is_a?(Hash)
      removed = records.delete(space_id.to_s)
      @space_edit_change_sessions.delete(model.object_id) if records.empty?
      !removed.nil?
    rescue StandardError
      false
    end

    def mark_space_edit_transaction_change!(model = Sketchup.active_model)
      return false unless model
      records = @space_edit_change_sessions && @space_edit_change_sessions[model.object_id]
      return false unless records.is_a?(Hash) && !records.empty?
      return false if soft_representation_switching?(model) || publish_critical_section? || publish_post_quiet?
      return false if @shared_component_sync_depth.to_i.positive?
      return false if @space_edit_edge_rendering_optimization_running
      return false if (@space_exit_commit_in_progress || {})[model.object_id]
      path = Array(model.active_path)
      selection = path.empty? && model.respond_to?(:selection) ? model.selection.to_a : []
      return false if path.empty? && selection.empty?
      changed = false
      records.each_value do |record|
        next unless record.is_a?(Hash) && record[:observe_changes] == true
        next if monotonic_time < record[:ignore_transactions_until].to_f
        entity = record[:entity]
        next unless entity && entity.valid? && (path.include?(entity) || selection.include?(entity))
        root_index = path.index(entity)
        nested_edit = !root_index.nil? && path.length > root_index + 1
        # 协同组件内部几何不计入“空间自身内容修改”，但必须记录到本次空间会话。
        # 这样退出后不会被误判成完全无修改而自动释放；用户仍然只需要点一次空间发布，
        # 空间提交成功后会把本次/当前缓存的协同组件修改一并上传。
        if nested_edit && transaction_inside_shared_component_below?(path, root_index)
          shared_instance = Array(path[(root_index + 1)..-1]).reverse.find do |candidate|
            candidate && candidate.valid? && candidate.is_a?(Sketchup::ComponentInstance) && shared_component_definition?(candidate.definition)
          end
          if shared_instance && shared_instance.valid?
            component_id = shared_component_definition_id(shared_instance.definition)
            unless component_id.empty?
              record[:shared_component_changed_ids] ||= {}
              record[:shared_component_changed_ids][component_id] = true
            end
          end
          next
        end
        transform_changed = !space_edit_root_transform_unchanged?(record, entity)
        entry_guid = record[:entry_definition_guid].to_s
        current_guid = space_edit_definition_guid(entity)
        definition_changed = entry_guid.empty? || current_guid.empty? || entry_guid != current_guid
        # SketchUp 会把项目属性保存、锁心跳恢复和 active_path 收尾也报告成事务。
        # 当事务只停留在空间根，且根 Definition GUID 与变换都没变时，它不是模型
        # 内容修改。真正的直接子项增删/移动会改变根 GUID；更深层编辑由 path 深度兜底。
        next unless nested_edit || transform_changed || definition_changed
        record[:content_changed] = true
        record[:content_change_events] = record[:content_change_events].to_i + 1
        if record[:content_change_events] == 1
          log("空间修改跟踪已标记：path_depth=#{root_index.nil? ? 0 : path.length - root_index} / definition=#{definition_changed} / transform=#{transform_changed}")
        end
        changed = true
      end
      changed
    rescue StandardError
      false
    end

    def space_edit_root_transform_unchanged?(record, entity)
      before = record.is_a?(Hash) ? Array(record[:entry_transformation]).map(&:to_f) : []
      return false unless before.length == 16 && entity && entity.valid? && entity.respond_to?(:transformation)
      after = entity.transformation.to_a.map(&:to_f)
      before.zip(after).all? { |left, right| (left - right).abs <= 1.0e-9 }
    rescue StandardError
      false
    end

    def space_edit_definition_guid(entity)
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      return '' unless definition && definition.respond_to?(:guid)
      definition.guid.to_s
    rescue StandardError
      ''
    end

    def space_edit_content_unchanged?(item, entity, target, model = Sketchup.active_model)
      return false unless item && entity && entity.valid? && model
      return false unless File.file?(target.to_s)
      return false if initial_space_publish_pending?(item)
      return false unless soft_pending_proxy_records_for_space(item, entity, model).empty?
      return false if @soft_ingest_batch_job && @soft_ingest_batch_job[:model].equal?(model)
      record = space_edit_change_session(model, item['id'])
      return false unless record.is_a?(Hash) && record[:observe_changes] == true
      return false if record[:content_changed] == true
      changed_component_ids = Hash(record[:shared_component_changed_ids]).keys.map(&:to_s).reject(&:empty?)
      unless changed_component_ids.empty?
        component_still_dirty = changed_component_ids.any? do |component_id|
          shared_component_definitions(model, component_id: component_id).any? { |definition| shared_component_dirty?(definition, model) }
        end
        return false if component_still_dirty
      end
      return false unless record[:entity] && record[:entity].valid? && record[:entity].equal?(entity)
      space_edit_root_transform_unchanged?(record, entity)
    rescue StandardError => e
      log_exception('判断空间是否未修改失败', e)
      false
    end

    def capture_soft_instance_edit_attributes(entity)
      result = {}
      dict = entity.attribute_dictionary(SOFT_MODEL_DICT, false) rescue nil
      dict.each_pair { |key, value| result[key.to_s] = value } if dict
      result
    rescue StandardError
      {}
    end

    def restore_soft_instance_edit_attributes!(entity, snapshot)
      return false unless entity && entity.valid?
      current = entity.attribute_dictionary(SOFT_MODEL_DICT, false) rescue nil
      keys = []
      current.each_pair { |key, _value| keys << key.to_s } if current
      keys.each { |key| entity.delete_attribute(SOFT_MODEL_DICT, key) rescue nil }
      Hash(snapshot).each { |key, value| entity.set_attribute(SOFT_MODEL_DICT, key.to_s, value) }
      true
    rescue StandardError => e
      log_exception('恢复家具编辑前属性失败', e)
      false
    end

    def clear_soft_individual_edit_markers!(entity)
      return false unless entity && entity.valid?
      %w[
        individual_edit_copy individual_edit_started_at individual_edit_plugin_version
        individual_edit_source_path individual_edit_source_snapshot_signature
      ].each { |key| entity.delete_attribute(SOFT_MODEL_DICT, key) rescue nil }
      true
    rescue StandardError
      false
    end

    # v0.13.6.181：单件家具写库失败只隔离这一件，绝不能把整个空间变成“全局故障态”。
    # 失败家具继续保留当前真模型和用户修改，并用持久化标记告诉代真/发布链路：
    # 1) 不要套回旧代理；2) 其它家具照常切换；3) 发布候选允许这件保留真模型。
    def soft_individual_edit_save_failed?(entity)
      return false unless entity && entity.valid? && entity.respond_to?(:get_attribute)
      !!entity.get_attribute(SOFT_MODEL_DICT, 'individual_edit_save_failed', false)
    rescue StandardError
      false
    end

    def clear_soft_individual_edit_save_failed_marker!(entity)
      return false unless entity && entity.valid?
      %w[
        individual_edit_save_failed individual_edit_save_failed_reason
        individual_edit_save_failed_at individual_edit_save_failed_model_name
      ].each { |key| entity.delete_attribute(SOFT_MODEL_DICT, key) rescue nil }
      true
    rescue StandardError
      false
    end

    def quarantine_soft_individual_edit_save_failure!(record, error = nil, model = Sketchup.active_model, reason: '')
      return false unless record.is_a?(Hash) && model
      entity = record[:entity]
      message = error ? error.message.to_s : reason.to_s
      message = record[:save_error].to_s if message.empty? && !record[:save_error].to_s.empty?
      message = '上一次自动保存未完成' if message.empty?
      record[:phase] = :save_failed
      record[:save_error] = message

      if entity && entity.valid?
        clear_soft_individual_edit_markers!(entity)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed', true)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_reason', message[0, 800])
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_at', Time.now.iso8601(6))
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_model_name', record[:model_name].to_s)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'full')
        entity.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
      end

      # 当前项目里的 unique 真模型就是用户尚未写回模型库的安全副本；释放会话控制锁，
      # 但绝不替换/删除这份 Definition。这样其它家具、发布、入库队列都可继续工作。
      invalidate_soft_individual_edit_source_full_cache!(record, model) rescue nil
      restore_soft_individual_edit_path_locks!(record, model) rescue nil
      detach_soft_individual_edit_entities_observers!(record) rescue nil
      @soft_individual_edit_sessions&.delete(model.object_id)
      cleanup_soft_individual_edit_definitions!(record, model) rescue nil
      bump_soft_instance_registry_revision(model) rescue nil
      model.selection.clear rescue nil
      model.selection.add(entity) rescue nil if entity && entity.valid?
      model.active_view.invalidate rescue nil
      log("家具保存失败已局部隔离：#{record[:model_name]} / #{message}")
      true
    rescue StandardError => e
      log_exception('隔离家具自动保存失败状态失败', e)
      false
    end

    # 冷启动无法继承 Ruby 会话，但失败/异常中断前写在实例上的 individual_edit_copy
    # 会随 SKP 保存下来。旧版没有把它迁移成局部失败标记，导致重启后发布可能把当前
    # 修改过的真模型误套回旧代理。启动后只扫描受管空间中的家具，发现这种孤儿标记就
    # 就地迁移为 v181 的局部失败状态；不访问模型库、不做写盘。
    def recover_orphan_soft_individual_edit_markers_from_model!(model = Sketchup.active_model)
      return 0 unless model
      active = soft_individual_edit_session(model)
      active_entity = active.is_a?(Hash) ? active[:entity] : nil
      state = load_state(model) rescue nil
      candidates = []
      if state.is_a?(Hash)
        Array(state['space_models']).each do |item|
          sid = item.is_a?(Hash) ? item['id'].to_s : ''
          next if sid.empty?
          root = space_model_entity(sid, model) rescue nil
          next unless root && root.valid?
          candidates.concat(soft_instances_for_space(root, model))
        end
      end
      candidates.concat(root_level_managed_soft_instances(model)) rescue nil
      migrated = 0
      candidates.uniq.each do |entity|
        next unless entity && entity.valid? && entity.respond_to?(:get_attribute)
        next if active_entity && active_entity.equal?(entity)
        next if Array(model.active_path).include?(entity)
        next unless entity.get_attribute(SOFT_MODEL_DICT, 'individual_edit_copy', false)
        next if soft_individual_edit_save_failed?(entity)
        name = soft_instance_metadata(entity)['model_name'].to_s rescue ''
        name = entity.definition.name.to_s if name.empty? && entity.respond_to?(:definition) && entity.definition
        clear_soft_individual_edit_markers!(entity)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed', true)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_reason', '检测到上一运行/旧版本未结清的家具编辑；当前真模型已保留，请重新执行家具入库完成写库。')
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_at', Time.now.iso8601(6))
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_save_failed_model_name', name)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'full')
        entity.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
        migrated += 1
      rescue StandardError
        next
      end
      if migrated.positive?
        bump_soft_instance_registry_revision(model) rescue nil
        log("启动时迁移旧家具编辑失败标记：#{migrated} 个实例；均保持真模型，不阻塞其它家具与发布")
      end
      migrated
    rescue StandardError => e
      log_exception('启动时迁移旧家具编辑失败标记失败', e)
      0
    end

    # 家具完成修改后只登记待刷新；正式发布时统一生成。
    # pending 标记同时写在实例上；插件热重载/Runtime 重启后会做一次轻量恢复，避免
    # 真模型已经写库但内存队列丢失，之后用户误以为任务已经处理完。
    def recover_soft_pending_proxy_rebuilds_from_model!(model = Sketchup.active_model)
      return [] unless model
      @soft_pending_proxy_recovery_checked ||= {}
      key = model.object_id
      return [] if @soft_pending_proxy_recovery_checked[key]
      @soft_pending_proxy_recovery_checked[key] = true
      @soft_pending_proxy_rebuilds ||= {}
      records = (@soft_pending_proxy_rebuilds[key] ||= [])
      found = []
      walk = nil
      walk = lambda do |entities, trail, parent_path|
        entities.each do |entity|
          next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
          pending = entity.get_attribute(SOFT_MODEL_DICT, 'proxy_rebuild_pending', false) rescue false
          if pending
            # v184: a pending marker is not cleared by six-view metadata alone.
            info = soft_instance_metadata(entity)
            model_id = entity.get_attribute(SOFT_MODEL_DICT, 'proxy_rebuild_model_id', '').to_s rescue ''
            model_id = info['model_id'].to_s if model_id.empty?
            unless model_id.empty?
              found << {
                entity: entity, model_id: model_id, model_name: info['model_name'].to_s,
                source_path: info['source_path'].to_s, scope_space_id: '', source_definition: entity.definition,
                phase: :waiting_proxy, force_rebuild: true, queued_at: Time.now.to_f, proxy_task_id: '',
                highlight_path: Array(parent_path) + [entity]
              }
            end
            next
          end
          definition = entity.definition rescue nil
          next unless definition && definition.valid?
          oid = definition.object_id
          next if trail[oid]
          walk.call(definition.entities, trail.merge(oid => true), Array(parent_path) + [entity])
        end
      end
      walk.call(model.entities, {}, [])
      found.each do |record|
        next if records.any? { |row| row[:entity].equal?(record[:entity]) rescue false }
        records << record
      end
      log("已从模型实例恢复待生成代理任务：#{found.length} 件") if found.any?
      found
    rescue StandardError => e
      log_exception('恢复待生成代理任务失败', e)
      []
    end

    def soft_pending_proxy_rebuild_records(model = Sketchup.active_model)
      return [] unless model
      @soft_pending_proxy_rebuilds ||= {}
      recover_soft_pending_proxy_rebuilds_from_model!(model)
      records = (@soft_pending_proxy_rebuilds[model.object_id] ||= [])
      records.delete_if do |record|
        entity = record.is_a?(Hash) ? record[:entity] : nil
        invalid = !record.is_a?(Hash) || !entity || !entity.valid?
        next true if invalid
        # 内存队列也要执行与热重载恢复器相同的终态清理。未修改退出恢复了仍然
        # 权威的代理时，旧内存记录不能继续冒充“待重建”并拦住真模型按钮。
        false # v184: only verified queue success consumes a live pending record.
      end
      records
    rescue StandardError
      []
    end

    def assign_soft_pending_proxy_task_id!(model_id, task_id, model = Sketchup.active_model)
      id = model_id.to_s
      tid = task_id.to_s
      return false if id.empty? || tid.empty? || !model
      soft_pending_proxy_rebuild_records(model).each do |record|
        record[:proxy_task_id] = tid if record[:model_id].to_s == id
      end
      true
    rescue StandardError
      false
    end

    def register_soft_pending_proxy_rebuild!(record, model = Sketchup.active_model)
      return false unless record.is_a?(Hash) && model
      entity = record[:entity]
      return false unless entity && entity.valid?
      records = soft_pending_proxy_rebuild_records(model)
      previous = records.find { |item| item[:entity].equal?(entity) rescue false }
      if previous && record[:desired_representation].to_s.empty?
        record[:desired_representation] = previous[:desired_representation]
      end
      records.delete_if { |item| item[:entity].equal?(entity) rescue false }
      # v184: 写库完成登记代理待办；退出/按钮立即续接队列。蓝框只在代理验收和关联成功后清除。
      record[:phase] = :waiting_proxy
      record[:force_rebuild] = true
      record[:queued_at] = Time.now.to_f
      # :auto 保持原有“退出/发布时自动切代理”；用户随后手动点真/代理时会覆盖。
      record[:desired_representation] = 'auto' if record[:desired_representation].to_s.empty?
      active_path = Array(model.active_path).select { |node| node && node.valid? && node.respond_to?(:transformation) }
      highlight_path = if active_path.empty?
                         find_soft_pending_proxy_entity_path(entity, model)
                       elsif active_path.last.equal?(entity)
                         active_path
                       else
                         active_path + [entity]
                       end
      record[:highlight_path] = highlight_path unless highlight_path.empty?
      records << record
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_rebuild_pending', true)
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_rebuild_model_id', record[:model_id].to_s)
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_rebuild_started_at', Time.now.iso8601(6))
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      true
    rescue StandardError => e
      log_exception('登记单件家具待生成代理任务失败', e)
      false
    end

    def defer_soft_visual_proxy_seeds_until_publish!(seeds, model = Sketchup.active_model)
      return 0 unless model
      registered = 0
      Array(seeds).each do |seed|
        next unless seed.is_a?(Hash)
        Array(seed[:replace_instances]).select { |entity| entity && entity.valid? }.uniq.each do |entity|
          record = {
            entity: entity,
            model_id: seed[:model_id].to_s,
            model_name: seed[:model_name].to_s,
            source_path: seed[:source_path].to_s,
            source_definition: (seed[:source_definition] if seed[:source_definition] && seed[:source_definition].valid?),
            scope_space_id: seed[:scope_space_id].to_s,
            desired_representation: seed[:desired_representation].to_s
          }
          registered += 1 if register_soft_pending_proxy_rebuild!(record, model)
        end
      end
      if registered.positive? && model.active_path.nil? && !@soft_ingest_batch_job && !soft_commit_world_context_active?(model)
        schedule_soft_pending_proxy_exit_batch!(model, delay: 0.20)
      end
      registered
    rescue StandardError => e
      log_exception('登记发布前待生成家具代理失败', e)
      0
    end

    def find_soft_pending_proxy_entity_path(target, model = Sketchup.active_model)
      return [] unless target && target.valid? && model
      found = nil
      walk = nil
      walk = lambda do |entities, path, trail|
        entities.each do |node|
          next unless node.is_a?(Sketchup::ComponentInstance) || node.is_a?(Sketchup::Group)
          node_path = Array(path) + [node]
          if node.equal?(target)
            found = node_path
            return true
          end
          definition = node.definition rescue nil
          next unless definition && definition.valid?
          oid = definition.object_id
          next if trail[oid]
          return true if walk.call(definition.entities, node_path, trail.merge(oid => true))
        end
        false
      end
      walk.call(model.entities, [], {})
      Array(found)
    rescue StandardError
      []
    end

    def soft_pending_proxy_record_path(record, model = Sketchup.active_model)
      return [] unless record.is_a?(Hash) && model
      entity = record[:entity]
      return [] unless entity && entity.valid?
      path = Array(record[:highlight_path]).select { |node| node && node.valid? && node.respond_to?(:transformation) }
      unless !path.empty? && path.last.equal?(entity)
        path = find_soft_pending_proxy_entity_path(entity, model)
        record[:highlight_path] = path unless path.empty?
      end
      path
    rescue StandardError
      []
    end

    def soft_pending_proxy_highlight_boxes(model = Sketchup.active_model)
      return [] unless model
      records = soft_pending_proxy_rebuild_records(model)
      return [] if records.empty?
      active_id = ''
      if @soft_visual_proxy_upgrade_job.is_a?(Hash)
        active_state = @soft_visual_proxy_upgrade_job[:active_candidate_state]
        active_candidate = active_state.is_a?(Hash) ? active_state[:candidate] : nil
        active_id = active_candidate[:model_id].to_s if active_candidate.is_a?(Hash)
      end
      records.filter_map do |record|
        entity = record[:entity]
        next unless entity && entity.valid? && entity.respond_to?(:definition) && entity.definition && entity.definition.valid?
        path = soft_pending_proxy_record_path(record, model)
        next if path.empty?
        transform = path.inject(identity_transformation) { |memo, node| memo * node.transformation }
        bounds = entity.definition.bounds
        points = (0..7).map { |index| bounds.corner(index).transform(transform) }
        model_id = record[:model_id].to_s
        status = if record[:phase].to_s == 'failed'
                   'failed'
                 elsif !active_id.empty? && active_id == model_id
                   'processing'
                 else
                   'pending'
                 end
        { points: points, model_id: model_id, status: status, kind: 'edit' }
      end
    rescue StandardError => e
      log_exception('读取待提交家具高亮范围失败', e)
      []
    end

    # 批量入库提交后只保存队列和视口路径，不给家具换材质、不 make_unique，
    # 蓝色半透明框完全由 Overlay 绘制，所以等待退出期间模型内容保持原样。
    def soft_pending_ingest_candidate_entities(candidate)
      return [] unless candidate.is_a?(Hash)
      action = (candidate[:action] || :new).to_sym
      rows = if action == :new
               Array(candidate[:marked_entities]) + [candidate[:entity]]
             else
               Array(candidate[:entities]) + [candidate[:entity]]
             end
      rows.select { |entity| entity && entity.valid? && entity.respond_to?(:definition) }.uniq
    rescue StandardError
      []
    end

    def prepare_soft_pending_ingest_candidates!(candidates, model = Sketchup.active_model)
      return [] unless model
      active_path = Array(model.active_path).select { |node| node && node.valid? && node.respond_to?(:transformation) }
      Array(candidates).each do |candidate|
        next unless candidate.is_a?(Hash)
        candidate[:ingest_phase] = :waiting_workspace_exit
        primary_entity = candidate[:entity]
        if primary_entity && primary_entity.valid? && primary_entity.respond_to?(:definition)
          primary_path = find_soft_pending_proxy_entity_path(primary_entity, model)
          primary_transform = if primary_path.empty?
                                absolute_transformation_for_selected_entity(primary_entity, model)
                              else
                                primary_path.inject(identity_transformation) { |memo, node| memo * node.transformation }
                              end
          begin
            candidate[:captured_axis_mm] = soft_library_actual_axis_dimensions_mm(primary_entity, model, combined_transform: primary_transform)
          rescue StandardError => e
            candidate.delete(:captured_axis_mm)
            log_exception('捕获待入库家具可见尺寸失败', e)
          end
        end
        candidate[:highlight_entities] = soft_pending_ingest_candidate_entities(candidate).map do |entity|
          path = if !active_path.empty? && active_path.last.equal?(entity)
                   active_path.dup
                 elsif !active_path.empty?
                   active_path + [entity]
                 else
                   find_soft_pending_proxy_entity_path(entity, model)
                 end
          { entity: entity, path: path }
        end
      end
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      Array(candidates)
    rescue StandardError => e
      log_exception('准备待入库家具蓝色高亮失败', e)
      Array(candidates)
    end

    def soft_pending_ingest_entities(model = Sketchup.active_model)
      job = @soft_ingest_batch_job
      return [] unless model && job.is_a?(Hash) && job[:model].equal?(model)
      candidates = Array(job[:queue]) + Array(job[:failed_candidates])
      candidates << job[:active_candidate] if job[:active_candidate].is_a?(Hash)
      candidates.flat_map { |candidate| soft_pending_ingest_candidate_entities(candidate) }.uniq
    rescue StandardError
      []
    end

    def soft_pending_ingest_highlight_boxes(model = Sketchup.active_model)
      job = @soft_ingest_batch_job
      return [] unless model && job.is_a?(Hash) && job[:model].equal?(model)
      candidates = Array(job[:queue]) + Array(job[:failed_candidates])
      candidates.unshift(job[:active_candidate]) if job[:active_candidate].is_a?(Hash)
      seen = {}
      candidates.filter_map do |candidate|
        next unless candidate.is_a?(Hash)
        status = candidate[:ingest_phase].to_s
        status = 'processing' if candidate.equal?(job[:active_candidate])
        Array(candidate[:highlight_entities]).filter_map do |row|
          entity = row.is_a?(Hash) ? row[:entity] : nil
          next unless entity && entity.valid? && entity.respond_to?(:definition) && entity.definition && entity.definition.valid?
          next if seen[entity.object_id]
          seen[entity.object_id] = true
          path = Array(row[:path]).select { |node| node && node.valid? && node.respond_to?(:transformation) }
          unless !path.empty? && path.last.equal?(entity)
            path = find_soft_pending_proxy_entity_path(entity, model)
            row[:path] = path if row.is_a?(Hash) && !path.empty?
          end
          next if path.empty?
          transform = path.inject(identity_transformation) { |memo, node| memo * node.transformation }
          bounds = entity.definition.bounds
          points = (0..7).map { |index| bounds.corner(index).transform(transform) }
          { points: points, status: (status == 'failed' ? 'failed' : status), kind: 'ingest' }
        end
      end.flatten
    rescue StandardError => e
      log_exception('读取待入库家具蓝色高亮失败', e)
      []
    end

    def clear_soft_pending_proxy_rebuild_markers!(entity)
      return false unless entity && entity.valid?
      %w[proxy_rebuild_pending proxy_rebuild_model_id proxy_rebuild_started_at proxy_rebuild_error].each do |key|
        begin
          entity.delete_attribute(SOFT_MODEL_DICT, key)
        rescue StandardError
          # 某些旧实例/共享定义状态下 delete_attribute 偶尔会失败；pending 是布尔真相，
          # 至少把它明确写成 false，避免下次恢复器再次把已完成任务当成待生成任务。
          soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, key, false) if key == 'proxy_rebuild_pending'
        end
      end
      # 二次确认：即使 SketchUp 没真正删除字典项，也绝不能留下 truthy pending。
      if entity.get_attribute(SOFT_MODEL_DICT, 'proxy_rebuild_pending', false) == true
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_rebuild_pending', false)
      end
      entity.get_attribute(SOFT_MODEL_DICT, 'proxy_rebuild_pending', false) != true
    rescue StandardError
      false
    end

    # v0.13.6.95：pending 表示“权威六面代理文件需要重建”，不是“当前实例必须已经显示为代理”。
    # 一旦候选成功生成并写入权威映射，pending 必须成为终态并被消费；实例同步是独立的显示步骤。
    # 旧逻辑要求 entity 已经切回 authoritative proxy 才清 pending，导致 result[:replaced] == 0 时
    # 每 4~5 秒被“退出工作空间恢复失效旧任务”重新排队并重复截图六面。
    def complete_soft_pending_proxy_rebuilds_for_model!(model_id, model = Sketchup.active_model)
      target_id = model_id.to_s
      return 0 if target_id.empty? || !model
      records = soft_pending_proxy_rebuild_records(model)
      completed = 0
      records.dup.each do |record|
        next unless record[:model_id].to_s == target_id
        entity = record[:entity]
        record[:phase] = :completed
        record[:completed_at] = Time.now.to_f
        markers_cleared = true
        markers_cleared = clear_soft_pending_proxy_rebuild_markers!(entity) if entity && entity.valid?
        records.delete(record)
        completed += 1
        display_mode = if entity && entity.valid?
                         soft_instance_representation_ready?(entity, 'proxy') && soft_instance_uses_authoritative_visual_proxy?(entity) ? 'proxy' : 'full'
                       else
                         'missing'
                       end
        log("单件家具代理重建终态完成：#{record[:model_name]} / #{record[:model_id]} / display=#{display_mode} / markers_cleared=#{markers_cleared}")
      end
      @soft_pending_proxy_rebuilds.delete(model.object_id) if records.empty? && @soft_pending_proxy_rebuilds
      model.active_view.invalidate if completed.positive? && model == Sketchup.active_model && model.respond_to?(:active_view)
      completed
    rescue StandardError => e
      log_exception('结束单件家具待生成代理任务失败', e)
      0
    end

    def mark_soft_pending_proxy_rebuild_failed!(model_id, message, model = Sketchup.active_model)
      target_id = model_id.to_s
      soft_pending_proxy_rebuild_records(model).each do |record|
        next unless record[:model_id].to_s == target_id
        record[:phase] = :failed
        record[:error] = message.to_s
        entity = record[:entity]
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_rebuild_error', message.to_s) if entity && entity.valid?
      end
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      true
    rescue StandardError
      false
    end

    # 把当前模型所有“已写库、等待代理”的记录按 model_id 合并成一次退出空间批处理。
    # 同款多实例只生成一次代理，最后一起替换；同款反复修改时采用最后一次写库后的 Definition。
    def soft_pending_proxy_records_for_space(item, entity, model = Sketchup.active_model)
      return [] unless item && entity && entity.valid? && model
      space_id = item['id'].to_s
      soft_pending_proxy_rebuild_records(model).select do |record|
        next false unless record.is_a?(Hash)
        scope_id = record[:scope_space_id].to_s
        next scope_id == space_id unless scope_id.empty?
        pending_entity = record[:entity]
        pending_entity && pending_entity.valid? && entity_inside_definition_tree?(pending_entity, entity.definition)
      rescue StandardError
        false
      end
    rescue StandardError
      []
    end

    def soft_pending_proxy_exit_batch_seeds(model = Sketchup.active_model, scope_space_id: '')
      scope_id = scope_space_id.to_s
      records = soft_pending_proxy_rebuild_records(model).select do |record|
        record.is_a?(Hash) && !%w[failed completed].include?(record[:phase].to_s) &&
          record[:entity] && record[:entity].valid? &&
          (scope_id.empty? || record[:scope_space_id].to_s.empty? || record[:scope_space_id].to_s == scope_id)
      end
      grouped = {}
      records.sort_by { |record| record[:queued_at].to_f }.each do |record|
        model_id = record[:model_id].to_s
        next if model_id.empty?
        entry = (grouped[model_id] ||= {
          model_id: model_id, model_name: record[:model_name].to_s,
          source_path: record[:source_path].to_s, scope_space_id: record[:scope_space_id].to_s,
          replace_instances: [], source_definition: nil, force_rebuild: true, proxy_task_id: record[:proxy_task_id].to_s
        })
        entity = record[:entity]
        # 用户明确要求继续显示真模型时，仍生成/更新权威代理文件，但不在任务完成
        # 瞬间把这个实例强制替回代理；后续发布候选仍可按发布规则统一代理化。
        desired_representation = record[:desired_representation].to_s
        entry[:replace_instances] << entity if entity && entity.valid? && desired_representation != 'full'
        entry[:model_name] = record[:model_name].to_s unless record[:model_name].to_s.empty?
        entry[:source_path] = record[:source_path].to_s unless record[:source_path].to_s.empty?
        entry[:scope_space_id] = record[:scope_space_id].to_s unless record[:scope_space_id].to_s.empty?
        entry[:source_definition] = if record[:source_definition] && record[:source_definition].valid?
                                      record[:source_definition]
                                    elsif entity && entity.valid? && entity.respond_to?(:definition)
                                      entity.definition
                                    else
                                      entry[:source_definition]
                                    end
        entry[:proxy_task_id] = record[:proxy_task_id].to_s unless record[:proxy_task_id].to_s.empty?
      end
      grouped.values.each { |seed| seed[:replace_instances] = Array(seed[:replace_instances]).uniq }
    rescue StandardError => e
      log_exception('整理退出空间代理批处理失败', e)
      []
    end

    def start_soft_pending_proxy_exit_batch!(model = Sketchup.active_model, scope_space_id: '', reason: '用户明确刷新代理', foreground_exit_batch: true)
      return false unless model && model.active_path.nil?
      scope_id = scope_space_id.to_s
      records = soft_pending_proxy_rebuild_records(model).select do |record|
        record.is_a?(Hash) && (scope_id.empty? || record[:scope_space_id].to_s.empty? || record[:scope_space_id].to_s == scope_id)
      end
      records.each do |record|
        next if record[:phase].to_s == 'failed'
        record[:phase] = :queued unless record[:phase].to_s == 'completed'
        record[:error] = ''
      end
      seeds = soft_pending_proxy_exit_batch_seeds(model, scope_space_id: scope_id)
      return false if seeds.empty?
      seeds.each do |seed|
        task_id = seed[:proxy_task_id].to_s
        if task_id.empty?
          task_id = ensure_soft_visual_proxy_seed_task!(seed, model, detail: "#{reason} · 准备统一生成")
          seed[:proxy_task_id] = task_id.to_s
        else
          snapshot = task_center_job_snapshot(task_id)
          unless snapshot && %w[queued running].include?(snapshot[:status].to_s)
            seed[:proxy_task_id] = ''
            task_id = ensure_soft_visual_proxy_seed_task!(seed, model, detail: "#{reason} · 恢复失效的旧代理任务")
            seed[:proxy_task_id] = task_id.to_s
          end
          update_task_center_job!(task_id, progress: 4, stage: reason.to_s, detail: '开始统一生成六面代理', status: 'queued') unless task_id.to_s.empty?
        end
        assign_soft_pending_proxy_task_id!(seed[:model_id], task_id, model) unless task_id.to_s.empty?
      end
      result = start_soft_schedule_visual_proxy_upgrade(
        model, reason: reason.to_s, seeds: seeds, scope_space_id: scope_id,
        foreground_exit_batch: !!foreground_exit_batch
      )
      unless result.is_a?(Hash) && result[:running]
        message = result.is_a?(Hash) ? result[:error].to_s : ''
        message = '六面代理批处理未能启动' if message.empty?
        seeds.each do |seed|
          mark_soft_pending_proxy_rebuild_failed!(seed[:model_id].to_s, message, model)
          finish_task_center_job!(seed[:proxy_task_id].to_s, success: false, stage: '批处理未启动', detail: message) unless seed[:proxy_task_id].to_s.empty?
        end
        @soft_proxy_switch_after_refresh&.delete(model.object_id)
        show_workspace_floating_notice("代理刷新未启动 · #{message}", 'warning', duration: 5.0, model: model)
        return false
      end
      show_workspace_floating_notice("代理刷新中 · 0/#{seeds.length} · 准备生成", 'info', progress: 0, persistent: true, model: model)
      true
    rescue StandardError => e
      log_exception('启动退出空间六面代理批处理失败', e)
      @soft_proxy_switch_after_refresh&.delete(model.object_id) if model
      show_workspace_floating_notice("代理刷新失败 · #{e.message}", 'error', duration: 5.5, model: model)
      false
    end

    def schedule_soft_pending_proxy_exit_batch!(model = Sketchup.active_model, delay: 0.18, scope_space_id: '')
      return false unless model
      scope_id = scope_space_id.to_s
      pending = soft_pending_proxy_rebuild_records(model).select do |record|
        scope_id.empty? || record[:scope_space_id].to_s.empty? || record[:scope_space_id].to_s == scope_id
      end
      return false if pending.empty?
      timer_key = "soft:proxy_batch_after_workspace_exit:#{model.object_id}:#{scope_id.empty? ? 'all' : scope_id}"
      runtime_start_timer(delay.to_f, false, label: 'soft:proxy_batch_after_workspace_exit', key: timer_key) do
        next unless model && model.active_path.nil?
        exit_context_pending = (@space_edit_contexts && @space_edit_contexts[model.object_id]) ||
                               (@space_context_exit_handling && @space_context_exit_handling[model.object_id])
        if exit_context_pending || @soft_ingest_batch_job || publish_critical_section? || publish_post_quiet? || @space_publish_in_progress || @space_explicit_publish_in_progress || @updating
          schedule_soft_pending_proxy_exit_batch!(model, delay: 0.24, scope_space_id: scope_id)
        else
          start_soft_pending_proxy_exit_batch!(model, scope_space_id: scope_id, reason: '退出空间统一更新代理')
        end
      end
      true
    rescue StandardError
      false
    end

    def show_workspace_floating_notice(message, level = 'info', progress: nil, persistent: false, duration: nil, model: Sketchup.active_model)
      overlay = ensure_workspace_toolbar_for_model(model, required_methods: [:show_floating_notice, :clear_floating_notice])
      if overlay
        overlay.enabled = true if overlay.respond_to?(:enabled=)
        overlay.activate! if overlay.respond_to?(:activate!)
        shown = overlay.show_floating_notice(message, level, progress: progress, persistent: persistent, duration: duration)
        if shown
          model.active_view.invalidate if model && model == Sketchup.active_model
          return true
        end
      end
      Sketchup.set_status_text(message.to_s, SB_PROMPT) if Sketchup.respond_to?(:set_status_text)
      log("视口悬浮提示降级到状态栏：#{message}")
      true
    rescue StandardError => e
      log_exception('显示视口悬浮提示失败', e)
      Sketchup.set_status_text(message.to_s, SB_PROMPT) if Sketchup.respond_to?(:set_status_text)
      false
    end

    def clear_workspace_floating_notice(model = Sketchup.active_model)
      overlay = ensure_workspace_toolbar_for_model(model, required_methods: [:show_floating_notice, :clear_floating_notice])
      overlay.clear_floating_notice if overlay
      true
    rescue StandardError => e
      log_exception('清除视口悬浮提示失败', e)
      false
    end

    def request_soft_pending_proxy_refresh_from_button!(model = Sketchup.active_model, state: nil)
      state = ensure_space_models_ready!(model) unless state.is_a?(Hash)
      scope_id = state['space_editing_id'].to_s
      scope_id = state['space_preview_full_id'].to_s if scope_id.empty?
      records = soft_pending_proxy_rebuild_records(model).select do |record|
        scope_id.empty? || record[:scope_space_id].to_s.empty? || record[:scope_space_id].to_s == scope_id
      end
      return false if records.empty?
      count = request_immediate_soft_proxy_refresh_for_records!(records, model, desired: 'proxy')
      count == records.map { |record| record[:model_id].to_s }.uniq.length
    rescue StandardError => e
      log_exception('代理按钮提交失败', e)
      false
    end

    # 编辑中、保存中或新代理尚未重建完成时，禁止任何代/真切换。否则一次空间级切换
    # 就可能直接把正在编辑的 unique 真模型替换掉，或把刚更新的真模型套回旧代理。
    def guard_soft_individual_edit_representation_switch!(model = Sketchup.active_model, desired: '', targets: nil)
      # 代/真切换也不应被已经退出真实 active_path 的幽灵会话永久阻塞。
      record = reconcile_orphan_soft_individual_edit_session!(
        model, reason: '代真切换前检查家具编辑会话', force: false
      )
      if record
        entity = record[:entity]
        if record[:phase].to_s == 'save_failed'
          # v0.13.6.182：写库失败是“这一件”的局部状态，不是空间级锁。失败实例本身由
          # apply_space_soft_proxies! 按实例跳过（保留 unique 真模型），其它家具照常切换。
          @soft_individual_edit_sessions&.delete(model.object_id)
          label = record[:model_name].to_s.empty? ? '一件家具' : "“#{record[:model_name]}”"
          log("代真切换：#{label}上次写库失败，保留其真模型，其它家具正常切换")
        else
          label = record[:model_name].to_s.empty? ? '当前家具' : "“#{record[:model_name]}”"
          phase = record[:phase].to_s
          detail = case phase
                   when 'saving' then '正在写回模型库'
                   else '仍处于单件真模型编辑事务中'
                   end
          raise "#{label}#{detail}；为避免代理与真模型尺寸错乱，自动保存完成前禁止切换代/真模型。"
        end
      end
      # v0.13.6.177：待代理刷新不再作为代/真切换的全局硬锁。
      # 真正处于单件编辑/保存事务中的家具仍由上面的安全闸门保护；一旦真模型已经
      # 安全写回，用户可以继续切真，也可以点击“代理”把这一款立即提升到代理队列
      # 前台生成。具体 pending 实例的分流由 set_selected_external_soft_display_mode 处理。
      true
    end

    # 返回当前明确选中范围里真正“真模型已写库、代理仍待刷新”的实例记录。
    # 其它家具即使同处一个代理队列，也绝不能连带锁住本次切换。
    def soft_pending_proxy_records_for_targets(targets, model = Sketchup.active_model)
      selected = Array(targets).select { |entity| entity && entity.valid? }
      return [] if selected.empty?
      selected_ids = selected.each_with_object({}) { |entity, memo| memo[entity.object_id] = true }
      soft_pending_proxy_rebuild_records(model).select do |record|
        entity = record.is_a?(Hash) ? record[:entity] : nil
        entity && entity.valid? && selected_ids[entity.object_id]
      rescue StandardError
        false
      end
    rescue StandardError
      []
    end

    # 记录用户对“代理刷新完成后当前实例应该显示什么”的显式意图。
    # :auto 保持原有退出/发布自动切代理；用户手动点“真模型”后设为 full，当前正在
    # 运行的代理任务也会把该实例从 replace_instances 中移除，避免任务完成后又强制
    # 弹回代理。再次点“代理”会改为 proxy，并把该款立即提升到队首生成。
    def set_soft_pending_proxy_display_intent!(targets, desired, model = Sketchup.active_model)
      desired = desired.to_s == 'proxy' ? 'proxy' : 'full'
      selected = Array(targets).select { |entity| entity && entity.valid? }.uniq
      return [] if selected.empty?
      selected_ids = selected.each_with_object({}) { |entity, memo| memo[entity.object_id] = true }
      records = soft_pending_proxy_records_for_targets(selected, model)
      records.each { |record| record[:desired_representation] = desired }

      # 如果这一款已经在 scan/queue/active 中，真模型意图必须立即从最终替换名单剔除。
      # 代理意图会由 request_immediate_soft_proxy_refresh! 再次合并 seed，不在这里直接
      # 操作队列，避免自己构造 model_id/source_path 不完整的候选。
      if desired == 'full' && @soft_visual_proxy_upgrade_job.is_a?(Hash) && @soft_visual_proxy_upgrade_job[:model].equal?(model)
        job = @soft_visual_proxy_upgrade_job
        candidates = Array(job[:scan_queue]) + Array(job[:queue])
        state = job[:active_candidate_state]
        candidates << state[:candidate] if state.is_a?(Hash) && state[:candidate].is_a?(Hash)
        candidates.each do |candidate|
          next unless candidate.is_a?(Hash)
          candidate[:replace_instances] = Array(candidate[:replace_instances]).select do |entity|
            entity && entity.valid? && !selected_ids[entity.object_id]
          end
        end
      end
      records
    rescue StandardError => e
      log_exception('记录待刷新家具显示意图失败', e)
      []
    end

    # 用户在空间内点击“代理”时，不再提示“等待退出/发布”。只把当前明确选中的
    # pending 款提升为 allow_inside_space + priority，现有代理队列会自动合并，不会
    # 为同一款重复截图。生成完成后由权威同步把这些实例切到最新代理。
    def request_immediate_soft_proxy_refresh_for_records!(records, model = Sketchup.active_model, desired: 'proxy')
      grouped = Array(records).select { |record| record.is_a?(Hash) }.group_by { |record| record[:model_id].to_s }
      started = 0
      grouped.each do |model_id, rows|
        next if model_id.empty?
        rows.each do |record|
          record[:desired_representation] = desired.to_s unless desired.nil?
          record[:phase] = :waiting_proxy if record[:phase].to_s == 'failed'
          record[:error] = ''
          record[:force_rebuild] = true
        end
        scope_id = rows.map { |record| record[:scope_space_id].to_s }.find { |value| !value.empty? }.to_s
        started += 1 if request_immediate_soft_proxy_refresh!(model_id, scope_space_id: scope_id, model: model)
      end
      started
    rescue StandardError => e
      log_exception('选中家具立即更新代理失败', e)
      0
    end

    # v0.13.6.179：代理切换失败提示必须告诉用户“具体是哪几件”，而不是只给数量。
    # 同款多实例按“名称 × 数量”聚合，避免 20 把同款椅子刷 20 行。
    def soft_proxy_switch_instance_rows(instances, model = Sketchup.active_model)
      grouped = {}
      Array(instances).each do |instance|
        next unless instance && instance.valid?
        info = soft_instance_metadata(instance)
        name = info['model_name'].to_s
        if name.empty? && instance.respond_to?(:definition) && instance.definition
          name = soft_identity_display_name(instance.definition.name.to_s)
        end
        name = '未命名家具' if name.empty?
        model_id = info['model_id'].to_s
        source_path = info['source_path'].to_s
        key = [model_id, normalize_soft_library_key(source_path), name]
        row = (grouped[key] ||= {
          name: name, model_id: model_id, source_path: source_path,
          count: 0, instances: [], source_definition: nil
        })
        row[:count] += 1
        row[:instances] << instance
        row[:source_definition] ||= (instance.definition if instance.respond_to?(:definition))
      end
      grouped.values.sort_by { |row| [row[:name].to_s.downcase, row[:model_id].to_s] }
    rescue StandardError
      []
    end

    def soft_proxy_switch_instance_summary(instances, limit: 8)
      rows = soft_proxy_switch_instance_rows(instances)
      return '未命名家具' if rows.empty?
      labels = rows.first([limit.to_i, 1].max).map do |row|
        row[:count].to_i > 1 ? "#{row[:name]} ×#{row[:count]}" : row[:name].to_s
      end
      labels << "另 #{rows.length - labels.length} 款" if rows.length > labels.length
      labels.join('、')
    rescue StandardError
      "#{Array(instances).length} 个家具"
    end

    # 普通家具并不一定处于“修改后待刷新”记录中。以前空间级切代理遇到这类缺失/
    # 过期六面代理会把整次事务回滚，导致 45 件已经能切、只因 2 件缺代理就全部切不回。
    # 现在把这些真正未就绪的实例直接构造成高优先级 seed：已有代理的家具先正常切换，
    # 缺代理的家具暂时保持真模型，并在当前空间内立即生成；完成后只替换这些实例。
    def request_immediate_soft_proxy_refresh_for_instances!(instances, model = Sketchup.active_model, scope_space_id: '')
      selected = Array(instances).select { |entity| entity && entity.valid? }.uniq
      return { started: 0, rows: [], error: '' } if selected.empty? || !model
      rows = soft_proxy_switch_instance_rows(selected, model)
      seeds = rows.filter_map do |row|
        model_id = row[:model_id].to_s
        source_path = row[:source_path].to_s
        source_path = auto_relocate(source_path, model) unless source_path.empty?
        # 旧实例偶尔 source_path 为空，但稳定 model_id 仍可由候选解析器从索引恢复。
        next if model_id.empty? && source_path.empty?
        seed = {
          model_id: model_id,
          model_name: row[:name].to_s,
          source_path: source_path,
          scope_space_id: scope_space_id.to_s,
          replace_instances: Array(row[:instances]).select { |entity| entity && entity.valid? },
          source_definition: (row[:source_definition] if row[:source_definition] && row[:source_definition].valid?),
          allow_inside_space: true,
          priority: true
        }
        seed[:proxy_task_id] = ensure_soft_visual_proxy_seed_task!(
          seed, model, detail: '代真切换缺失代理 · 立即生成并自动切换'
        ).to_s
        seed
      end
      return { started: 0, rows: rows, error: '缺少可用于生成代理的模型库身份' } if seeds.empty?

      result = start_soft_schedule_visual_proxy_upgrade(
        model,
        reason: '代真切换缺失代理立即补齐',
        seeds: seeds,
        scope_space_id: scope_space_id.to_s,
        foreground_exit_batch: false
      )
      running = result.is_a?(Hash) && result[:running]
      unless running
        message = result.is_a?(Hash) ? result[:error].to_s : ''
        message = '代理生成任务未能启动' if message.empty?
        seeds.each do |seed|
          tid = seed[:proxy_task_id].to_s
          finish_task_center_job!(tid, success: false, stage: '代理生成未启动', detail: message) unless tid.empty?
        end
        return { started: 0, rows: rows, error: message }
      end
      { started: seeds.length, rows: rows, error: '' }
    rescue StandardError => e
      log_exception('代真切换缺失代理立即补齐失败', e)
      { started: 0, rows: (defined?(rows) ? rows : []), error: e.message.to_s }
    end

    def cancel_soft_individual_edit!(record, model = Sketchup.active_model, no_change: false)
      entity = record[:entity]
      raise '待恢复的家具实例已经失效。' unless entity && entity.valid?
      entry_definition = record[:entry_definition] || record[:proxy_definition]
      entry_representation = record[:entry_representation].to_s
      entry_representation = 'proxy' if entry_representation.empty?
      unless no_change || (entry_definition && entry_definition.valid?)
        raise '进入编辑前的家具 Definition 已失效，无法安全自动恢复。'
      end
      edited_definition = entity.definition rescue nil
      operation_started = false
      begin
        model.start_operation(no_change ? "结束家具查看 #{record[:model_name]}" : "取消家具修改 #{record[:model_name]}", true, false, false)
        operation_started = true
        entity.locked = false if entity.respond_to?(:locked=)
        if no_change
          # “进去看一眼”结束后保留已经展开并隔离好的真模型。它仍是当前实例唯一
          # Definition，下一次双击 make_unique 会直接 no-op，不再重新复制复杂家具。
          clear_soft_individual_edit_markers!(entity)
          soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'full')
          entity.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
          entity.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
          entity.locked = record[:entry_locked] if entity.respond_to?(:locked=)
        else
          entity.definition = entry_definition
          entity.transformation = record[:proxy_transformation] if record[:proxy_transformation]
          entity.name = record[:proxy_name].to_s if entity.respond_to?(:name=) && record.key?(:proxy_name)
          entity.layer = record[:proxy_layer] if entity.respond_to?(:layer=) && record[:proxy_layer]
          restore_soft_instance_edit_attributes!(entity, record[:soft_attributes])
          entity.locked = record[:proxy_locked] if entity.respond_to?(:locked=)
        end
        model.commit_operation
        operation_started = false
      rescue StandardError
        model.abort_operation rescue nil if operation_started
        raise
      end
      # 内容签名已经证明完全未改时，不要把原本可复用的真模 resident/cache 清掉；
      # 这样活动空间下次进入仍可走内存热缓存。只有异常/显式取消才按旧安全策略失效缓存。
      invalidate_soft_individual_edit_source_full_cache!(record, model) unless no_change
      restore_soft_individual_edit_path_locks!(record, model)
      detach_soft_individual_edit_entities_observers!(record)
      @soft_individual_edit_sessions&.delete(model.object_id)
      cleanup_soft_individual_edit_definitions!(record, model)
      bump_soft_instance_registry_revision(model)
      schedule_soft_managed_definition_cleanup(model, delay: 0.8) unless no_change
      model.selection.clear rescue nil
      model.selection.add(entity) rescue nil
      model.active_view.invalidate rescue nil
      unless no_change
        refresh_workspace_toolbar(model)
        refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: false) if @soft_designer_dialog && @soft_designer_dialog.visible?
      end
      if no_change
        overlay = workspace_toolbar_overlay(model)
        overlay.set_representation_mode_local!('full') if overlay && overlay.respond_to?(:set_representation_mode_local!)
        show_workspace_floating_notice("未检测到修改 · #{record[:model_name]} · 保持真模型", 'info', duration: 2.4, model: model)
        show_status("“#{record[:model_name]}”没有检测到几何、结构或材质变化；本次不入库、不高亮、不登记代理任务，并保持真模型显示。", 'info')
      else
        show_status("已取消“#{record[:model_name]}”本次修改；已恢复进入编辑前的家具显示状态，模型库没有写入任何修改。", 'info')
      end
      true
    rescue StandardError => e
      record[:phase] = :save_failed if record.is_a?(Hash)
      log_exception('取消单件家具编辑失败', e)
      raise
    ensure
      if defined?(edited_definition) && edited_definition && edited_definition.valid? && edited_definition.instances.empty?
        remove_unused_definition!(edited_definition, model) rescue nil
      end
    end

    def finalize_soft_individual_edit!(record, model = Sketchup.active_model)
      entity = record[:entity]
      raise '待完成的家具实例已经失效。' unless entity && entity.valid?
      record[:phase] = :saving
      result = update_existing_soft_library_from_entity!(
        entity,
        model_id: record[:model_id].to_s,
        source_path: record[:source_path].to_s,
        model_name: record[:model_name].to_s,
        model: model,
        expected_source_signature: record[:source_snapshot_signature].to_s
      )
      clear_soft_individual_edit_markers!(entity)
      invalidate_soft_individual_edit_source_full_cache!(record, model)
      cleanup_soft_individual_edit_definitions!(record, model)

      if result[:planar_reference]
        operation_started = false
        begin
          model.start_operation("完成家具修改 #{record[:model_name]}", true, false, false)
          operation_started = true
          soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'proxy')
          soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'proxy_passthrough', true)
          soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'planar_reference', true)
          model.commit_operation
          operation_started = false
        rescue StandardError
          model.abort_operation rescue nil if operation_started
          raise
        end
        restore_soft_individual_edit_path_locks!(record, model)
        detach_soft_individual_edit_entities_observers!(record)
        @soft_individual_edit_sessions&.delete(model.object_id)
        refresh_workspace_toolbar(model)
        show_status("“#{record[:model_name]}”已完成修改并写回模型库；该平面模型已同步更新代理状态。", 'success')
        return true
      end

      record[:model_id] = result[:model_id].to_s
      record[:model_name] = result[:model_name].to_s
      record[:source_path] = result[:source_path].to_s
      record[:entity] = Array(result[:instances]).find { |node| node && node.valid? } || entity
      _state, space_item, _space_entity = current_local_editing_space(nil, model, required: false)
      scope_space_id = record[:space_id].to_s
      scope_space_id = space_item['id'].to_s if scope_space_id.empty? && space_item
      record[:scope_space_id] = scope_space_id
      seed = {
        model_id: result[:model_id].to_s,
        model_name: result[:model_name].to_s,
        source_path: result[:source_path].to_s,
        scope_space_id: scope_space_id,
        replace_instances: Array(result[:instances]).select { |node| node && node.valid? },
        source_definition: result[:source_definition]
      }

      # 完成修改只做“真模型安全写库 + 登记代理待处理”。v0.13.6.151 由退出确认决定：
      # 默认“否”继续保持真模型，完全退出空间后统一生成；“是”立即优先生成当前这一款。
      record[:source_definition] = result[:source_definition] if result[:source_definition] && result[:source_definition].valid?
      if record[:source_definition] && record[:source_definition].valid?
        touch_soft_resident_full_definition!(
          record[:source_definition], model,
          space_id: scope_space_id,
          library_item: {
            'id' => result[:model_id].to_s,
            'name' => result[:model_name].to_s,
            'path' => result[:source_path].to_s
          }
        )
      end
      # 同一旧 Definition 的其它实例也已由写库事务接管为新真模，它们共享同一款
      # 待更新代理。逐实例登记后，每个真正受影响的对象都会蓝色高亮；未受影响的
      # 其它家具既不高亮，也不会被它们的待办阻塞代理切换。
      registered = defer_soft_visual_proxy_seeds_until_publish!([seed], model)
      raise '模型库已写回，但无法登记待生成六面代理任务；当前保持真模型。' unless registered.positive?
      record[:proxy_task_id] = ''
      record[:phase] = :waiting_proxy
      record[:force_rebuild] = true
      restore_soft_individual_edit_path_locks!(record, model)
      detach_soft_individual_edit_entities_observers!(record)
      @soft_individual_edit_sessions&.delete(model.object_id)

      model.selection.clear rescue nil
      model.selection.add(record[:entity]) rescue nil
      refresh_workspace_toolbar(model)
      refresh_soft_designer_dialog(refresh_library: true, include_library: true, include_measurements: false) if @soft_designer_dialog && @soft_designer_dialog.visible?
      show_workspace_floating_notice("已保存修改 · #{record[:model_name]} · 代理待更新", 'success', duration: 2.6, model: model)
      true
    rescue StandardError => e
      record[:phase] = :save_failed if record.is_a?(Hash)
      record[:save_error] = e.message.to_s if record.is_a?(Hash)
      quarantined = record.is_a?(Hash) ? quarantine_soft_individual_edit_save_failure!(record, e, model) : false
      restore_soft_individual_edit_path_locks!(record, model) if record.is_a?(Hash) && !quarantined
      log_exception('完成单件家具编辑失败', e)
      if record.is_a?(Hash)
        show_workspace_floating_notice(
          "保存失败 · #{record[:model_name]} · 已保留当前真模型，其他家具/发布可继续",
          'warning', duration: 6.5, model: model
        )
        show_status(
          "“#{record[:model_name]}”未能写回模型库：#{e.message}。当前项目内修改已保留为真模型；其他家具仍可正常代真切换和发布。请选择该家具再次执行“家具入库”即可重试写库。",
          'warning'
        )
      end
      false
    end

    # v0.13.6.151：家具退出编辑先做短暂稳定确认，再在真实修改时弹“是否立即更新代理”。
    # SketchUp 在复杂真模型里可能先通知 active_path 已退出，再补最后一次 transaction commit。
    # 旧版这里立即判断 content_changed，导致真模型直接编辑偶发/稳定漏报。现在先等 0.12 秒，
    # 让最后一拍 EntitiesObserver / ModelObserver 到达，再做“未修改/已修改”终判。
    def handle_soft_individual_edit_active_path_change(model = Sketchup.active_model)
      record = soft_individual_edit_session(model)
      return false unless record
      return false unless record[:phase].to_s == 'editing'
      entity = record[:entity]
      return false unless entity && entity.valid?
      if Array(model.active_path).include?(entity)
        record[:last_inside_at] = monotonic_time
        record[:exit_token] = ''
        ensure_soft_individual_edit_entities_observer!(record, model)
        return true
      end

      # 同一退层事件可能由 ModelObserver/ESC 补偿链重复到达，只保留一个 settle timer。
      return true unless record[:exit_token].to_s.empty?
      token = SecureRandom.hex(6)
      record[:exit_token] = token
      record[:exit_detected_at] = monotonic_time
      runtime_start_timer(
        0.12, false, label: 'soft:individual_edit_exit_settle',
        key: "soft:individual_edit_exit_settle:#{model.object_id}", model: model, active_model_only: true
      ) { settle_soft_individual_edit_exit!(model, token) }
      true
    rescue StandardError => e
      record[:phase] = :save_failed if record.is_a?(Hash)
      log_exception('识别单件家具退出编辑失败', e)
      show_workspace_floating_notice("家具自动保存失败 · #{e.message}", 'error', duration: 5.5, model: model)
      false
    end

    def settle_soft_individual_edit_exit!(model = Sketchup.active_model, token = '')
      record = soft_individual_edit_session(model)
      return false unless record.is_a?(Hash) && record[:phase].to_s == 'editing'
      return false unless record[:exit_token].to_s == token.to_s
      entity = record[:entity]
      return false unless entity && entity.valid?
      if Array(model.active_path).include?(entity)
        # 用户/SketchUp 又回到了家具内部，本次退层只是瞬态；恢复监听，不做收尾。
        record[:exit_token] = ''
        record[:last_inside_at] = monotonic_time
        ensure_soft_individual_edit_entities_observer!(record, model)
        return true
      end

      record[:exit_token] = ''
      @soft_individual_edit_prompting ||= {}
      key = model.object_id
      return true if @soft_individual_edit_prompting[key]
      @soft_individual_edit_prompting[key] = true
      begin
        if soft_individual_edit_content_unchanged?(record)
          log("家具编辑退出：内容未变化，跳过入库与六面代理 / #{record[:model_name]} / entry=#{record[:entry_representation]}")
          record[:phase] = :unchanged
          cancel_soft_individual_edit!(record, model, no_change: true)
          schedule_restore_default_select_tool(
            model, delay: 0.02, reason: '家具未修改退出', rearm_workspace_candidate: true
          ) rescue nil
        else
          record[:phase] = :awaiting_proxy_choice
          detach_soft_individual_edit_entities_observers!(record)
          show_soft_individual_edit_exit_confirmation!(record, model)
        end
      ensure
        @soft_individual_edit_prompting.delete(key)
      end
      true
    rescue StandardError => e
      record[:phase] = :save_failed if record.is_a?(Hash)
      log_exception('家具退出稳定收尾失败', e)
      show_workspace_floating_notice("家具自动保存失败 · #{e.message}", 'error', duration: 5.5, model: model)
      false
    end

    def show_soft_individual_edit_exit_confirmation!(record, model = Sketchup.active_model)
      return false unless record.is_a?(Hash) && model
      return false unless record[:phase].to_s == 'awaiting_proxy_choice'
      token = SecureRandom.hex(8)
      record[:exit_confirmation_token] = token
      tool = SoftIndividualEditExitConfirmTool.new(model, token, record[:prompt_x], record[:prompt_y])
      record[:exit_confirmation_tool] = tool
      model.tools.push_tool(tool)
      show_workspace_floating_notice("#{record[:model_name]} 已修改 · 是=立即更新本次并切回代理；否=退出空间后队列更新", 'info', duration: 4.2, model: model)
      true
    rescue StandardError => e
      log_exception('显示家具退出代理确认失败', e)
      # 确认层不可用时按默认“否”继续，绝不阻塞本次修改保存。
      record[:phase] = :saving if record.is_a?(Hash)
      finalize_soft_individual_edit!(record, model) if record.is_a?(Hash)
      false
    end

    def soft_individual_edit_exit_confirmation_choice!(model = Sketchup.active_model, token = '', action = :cancel, tool_already_gone: false)
      record = soft_individual_edit_session(model)
      return false unless record.is_a?(Hash)
      return false unless record[:phase].to_s == 'awaiting_proxy_choice'
      return false unless record[:exit_confirmation_token].to_s == token.to_s
      immediate = action.to_sym == :edit
      record[:exit_confirmation_token] = ''
      record[:exit_confirmation_tool] = nil
      unless tool_already_gone
        begin
          model.tools.pop_tool
        rescue StandardError
          nil
        end
      end

      record[:phase] = :saving
      show_workspace_floating_notice(
        immediate ? "正在保存并更新代理 · #{record[:model_name]}" : "已保留修改 · #{record[:model_name]} · 退出空间后统一更新代理",
        'info', persistent: immediate, duration: (immediate ? nil : 2.8), model: model
      )
      model_id = record[:model_id].to_s
      scope_space_id = record[:space_id].to_s
      ok = finalize_soft_individual_edit!(record, model)
      if ok && immediate
        request_immediate_soft_proxy_refresh!(model_id, scope_space_id: scope_space_id, model: model)
      elsif ok
        show_workspace_floating_notice("已保存修改 · #{record[:model_name]} · 退出空间后统一更新代理", 'success', duration: 3.0, model: model)
      end
      schedule_restore_default_select_tool(model, delay: 0.04, reason: '家具退出代理确认', rearm_workspace_candidate: true) rescue nil
      ok
    rescue StandardError => e
      log_exception('处理家具退出代理确认失败', e)
      show_workspace_floating_notice("家具修改收尾失败 · #{e.message}", 'error', duration: 5.5, model: model)
      false
    end

    def request_immediate_soft_proxy_refresh!(model_id, scope_space_id: '', model: Sketchup.active_model)
      target_id = model_id.to_s
      return false if target_id.empty? || !model

      # v0.13.6.165：“是”只代表立即处理本次修改，不再代表退出空间。真模型源文件
      # 已由 finalize_soft_individual_edit! 安全写回；这里仅把本次 model_id 提升为最高
      # 优先级，就地生成/更新六面代理并把受影响实例切回代理。active_path 全程保持
      # 用户退出家具后的父层级。“否”则只保留 pending，等正常退出空间后统一批处理。
      seed = soft_pending_proxy_exit_batch_seeds(model, scope_space_id: scope_space_id.to_s).find do |row|
        row.is_a?(Hash) && row[:model_id].to_s == target_id
      end
      return false unless seed
      soft_pending_proxy_rebuild_records(model).each do |record|
        next unless record[:model_id].to_s == target_id
        record[:phase] = :queued unless record[:phase].to_s == 'completed'
        record[:error] = ''
      end
      seed[:allow_inside_space] = true
      seed[:priority] = true
      task_id = ensure_soft_visual_proxy_seed_task!(seed, model, detail: '立即更新本次家具 · 保持当前编辑层级')
      seed[:proxy_task_id] = task_id.to_s
      assign_soft_pending_proxy_task_id!(target_id, task_id, model) unless task_id.to_s.empty?
      result = start_soft_schedule_visual_proxy_upgrade(
        model, reason: '家具修改后立即更新代理', seeds: [seed],
        scope_space_id: scope_space_id.to_s, foreground_exit_batch: false
      )
      unless result.is_a?(Hash) && result[:running]
        message = result.is_a?(Hash) ? result[:error].to_s : ''
        message = '代理任务未能启动' if message.empty?
        mark_soft_pending_proxy_rebuild_failed!(target_id, message, model)
        raise message
      end
      show_workspace_floating_notice("立即更新本次家具 · #{seed[:model_name]} · 保持当前层级", 'info', progress: 4, persistent: true, model: model)
      true
    rescue StandardError => e
      log_exception('立即更新单件家具代理失败', e)
      show_workspace_floating_notice("已保存真模型 · 本次代理转入退出空间队列 · #{e.message}", 'warning', duration: 5.0, model: model)
      false
    end

    def complete_soft_individual_edit_proxy_rebuilds!(job)
      return false unless job.is_a?(Hash)
      model = job[:model] || Sketchup.active_model
      completed_ids = Array(job[:completed]).map { |candidate| candidate.is_a?(Hash) ? candidate[:model_id].to_s : '' }.reject(&:empty?).uniq
      changed = completed_ids.inject(0) { |memo, model_id| memo + complete_soft_pending_proxy_rebuilds_for_model!(model_id, model) }
      changed.positive?
    rescue StandardError => e
      log_exception('结束单件家具代理批处理失败', e)
      false
    end

    # 将当前唯一双击的家具代理实例切成真模型，并隔离成独立 Definition 后直接进入编辑。
    # 只作用于这一实例：其它同款家具仍保持六面代理，也不会因为组件共享 Definition
    # 而跟着一起被内部编辑。退出实例后由 LinkHub 默认自动完成：写回原 model_id 并保持真模型；
    # 六面代理延迟到完全退出工作空间或用户主动点击“代理”后统一前台生成。
    def edit_soft_proxy_instance_via_double_click!(candidate, model = Sketchup.active_model)
      raise '家具代理双击上下文已经失效。' unless candidate.is_a?(Hash) && model
      entity = candidate[:entity]
      raise '家具代理实例已经失效。' unless entity && entity.valid?

      state, space_item, space_entity = current_local_editing_space(nil, model, required: false)
      raise '当前空间已经不在本人协同修改状态。' unless space_item && space_entity && space_entity.valid?
      raise '家具已经不属于当前修改空间。' unless space_item['id'].to_s == candidate[:space_id].to_s
      raise '请先进入当前空间后再编辑家具。' unless active_path_inside_space?(space_entity, model)
      entry_representation = soft_instance_representation(entity).to_s
      raise '当前对象已经不再是可编辑的受管家具。' unless %w[proxy full].include?(entry_representation)

      info = soft_instance_metadata(entity)
      model_id = info['model_id'].to_s
      raise '当前代理缺少 model_id，无法定位真模型。' if model_id.empty?
      if !candidate[:id].to_s.empty? && model_id != candidate[:id].to_s
        raise '家具代理身份在双击过程中发生变化，请重新选择后再试。'
      end
      existing_edit = reconcile_orphan_soft_individual_edit_session!(
        model, reason: '进入下一件家具前检查', force: false
      )
      if existing_edit
        existing_name = existing_edit[:model_name].to_s
        existing_label = existing_name.empty? ? '当前家具' : "“#{existing_name}”"
        if soft_individual_edit_entity_inside?(existing_edit, model)
          raise "#{existing_label}仍在真模型编辑中；请先退出这件家具，再编辑下一件。"
        elsif existing_edit[:phase].to_s == 'save_failed'
          model.selection.clear rescue nil
          model.selection.add(existing_edit[:entity]) rescue nil
          raise "#{existing_label}上一次修改自动保存失败；已选中该家具，请先处理后再编辑下一件。"
        else
          raise "#{existing_label}仍在自动收尾中；请稍候片刻后再编辑下一件。"
        end
      end
      # v0.13.6.78：后台代理队列不再阻止继续编辑下一件家具；真正生成时会主动等待前台空闲。

      # 已经载入过的真模型先走纯内存 resident；不要每次双击都先扫描模型库并
      # File.stat 共享盘。resident 中保存的路径、名称和 Definition 身份足够进入查看。
      resident = resident_soft_full_match(info, model)
      library_item = resident && resident[:library_item]
      if !library_item && entry_representation == 'full'
        current_path = info['source_path'].to_s
        library_item = {
          'id' => model_id,
          'path' => current_path,
          'name' => info['model_name'].to_s
        } unless current_path.empty?
      end
      library_item ||= full_soft_library_item_for(info, model)
      raise '当前家具无法定位模型库真模型，不能进入可自动回滚的安全编辑。' unless library_item
      source_path = FastPath.expand(library_item['path'].to_s)
      # v0.13.6.164：进入“可写回编辑”不能只相信 resident Definition 上次留下的
      # source_signature。v162 延长 resident 生命周期后，模型库文件已经更新、内存高模
      # 仍是旧版时，会在退出编辑才被误判为“其他用户刚刚更新”。编辑入口只做一次
      # 很轻的 File.stat，确认 resident 与磁盘当前版本一致；发现旧缓存就精确失效并
      # 在下面的代理/真模准备事务中重新载入当前源。完整 SHA-256 仍留到真正写回。
      current_source_signature = fast_file_signature(source_path).to_s
      raise '无法读取模型库源文件的稳定版本签名；为避免覆盖其他用户修改，已停止进入编辑。' if current_source_signature.empty?
      cached_edit_signature = if resident && resident[:definition] && resident[:definition].valid?
                                resident[:definition].get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s
                              elsif entry_representation == 'full' && entity.definition && entity.definition.valid?
                                entity.definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s
                              else
                                ''
                              end
      cached_definition_present = (resident && resident[:definition] && resident[:definition].valid?) ||
                                  (entry_representation == 'full' && entity.definition && entity.definition.valid?)
      stale_source_definition = !!cached_definition_present &&
                                (cached_edit_signature.empty? ||
                                 normalize_fast_signature(cached_edit_signature) != normalize_fast_signature(current_source_signature))
      if stale_source_definition
        target_source_key = normalize_soft_library_key(source_path)
        target_id = model_id.to_s
        stale_definitions = []
        records = @soft_resident_full_records && @soft_resident_full_records[model.object_id]
        if records.is_a?(Hash)
          records.values.each do |row|
            next unless row.is_a?(Hash)
            definition = row[:definition]
            next unless definition && definition.valid?
            same_id = !target_id.empty? && row[:model_id].to_s == target_id
            same_path = !target_source_key.empty? && normalize_soft_library_key(row[:source_path].to_s) == target_source_key
            next unless same_id || same_path
            stored = definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s rescue ''
            next if !stored.empty? && normalize_fast_signature(stored) == normalize_fast_signature(current_source_signature)
            stale_definitions << definition
          end
        end
        if entry_representation == 'full' && entity.definition && entity.definition.valid?
          stored = entity.definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s rescue ''
          stale_definitions << entity.definition if stored.empty? || normalize_fast_signature(stored) != normalize_fast_signature(current_source_signature)
        end
        stale_definitions.compact.uniq.each { |definition| forget_soft_resident_definition_references!(definition, model) }
        invalidate_soft_library_file_signature!(source_path)
        resident = nil
        log("家具编辑入口发现旧 resident，已改用模型库当前版本：#{library_item['name']} / #{model_id}")
      end
      source_snapshot_signature = current_source_signature
      entry_definition_before_edit = entity.definition
      entry_transformation_before_edit = entity.transformation
      entry_locked_before_edit = entity.respond_to?(:locked?) ? entity.locked? : false
      entry_name_before_edit = entity.respond_to?(:name) ? entity.name.to_s : ''
      entry_layer_before_edit = entity.respond_to?(:layer) ? entity.layer : nil
      soft_attributes_before_edit = capture_soft_instance_edit_attributes(entity)

      original_path = Array(model.active_path).select { |node| node && node.valid? }
      operation_started = false
      begin
        model.start_operation("双击编辑家具 #{candidate[:label]}", true, false, false)
        operation_started = true
        if entry_representation == 'proxy' || stale_source_definition
          if stale_source_definition && entry_representation == 'full'
            log("单件家具双击阶段 1/4：旧缓存真模型已失效，重新载入模型库当前版本 / #{model_id}")
          else
            log("单件家具双击阶段 1/4：开始代理切真 / #{model_id}")
          end
          apply_space_soft_full_models!(space_entity, model, instances: [entity])
          raise '真模型切换失败。' unless entity.valid? && soft_instance_representation(entity) == 'full'
          # 原本就是 full 但缓存过期时，自动刷新属于进入编辑前的准备动作；取消本次
          # 编辑应回到“刚刷新后的当前模型库版本”，不能再回滚成旧 resident。
          if stale_source_definition && entry_representation == 'full'
            entry_definition_before_edit = entity.definition
            entry_transformation_before_edit = entity.transformation
            entry_locked_before_edit = entity.respond_to?(:locked?) ? entity.locked? : false
            entry_name_before_edit = entity.respond_to?(:name) ? entity.name.to_s : ''
            entry_layer_before_edit = entity.respond_to?(:layer) ? entity.layer : nil
            soft_attributes_before_edit = capture_soft_instance_edit_attributes(entity)
          end
        else
          log("单件家具双击阶段 1/4：当前已有且版本一致的缓存真模型，直接建立独立编辑副本 / #{model_id}")
        end
        source_full_definition = entity.definition
        legacy_flatten = flatten_soft_instance_legacy_wrappers!(entity, model)
        source_full_definition = entity.definition if legacy_flatten[:changed]
        log("单件家具双击阶段 2/4：代理切真完成#{legacy_flatten[:changed] ? "，已压平历史空壳#{legacy_flatten[:depth]}层" : ''}，准备最外层 make_unique / #{model_id}")

        # 仅最外层 make_unique。不要在这里递归改写普通嵌套 Definition 图；只在上一步
        # 压平 LinkHub 自己产生的历史纯 wrapper，用户正常组件结构保持原样。
        edit_isolation = isolate_soft_individual_edit_definition_graph!(entity, model)
        furniture_shell_repair = repair_redundant_empty_shells!(
          entity, model, context: "家具 #{candidate[:label]} 编辑入口"
        )
        shell_detail = furniture_shell_repair[:count].to_i.positive? ? "，并折叠普通空壳#{furniture_shell_repair[:count].to_i}层" : ''
        log("单件家具双击阶段 3/4：最外层 make_unique 完成#{shell_detail} / #{model_id}")
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'full')
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'model_id', model_id)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_copy', true)
        # v0.13.6.6：这里原先误用了不存在的局部变量 iso_time，代理成功切成
        # 真模型后会在写入编辑时间时抛 NameError，并把整个双击事务撤销。
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_started_at', Time.now.iso8601(6))
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_plugin_version', EXTENSION_VERSION)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_source_path', source_path)
        soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'individual_edit_source_snapshot_signature', source_snapshot_signature)
        @soft_individual_edit_sessions ||= {}
        @soft_individual_edit_sessions[model.object_id] = {
          phase: :editing, entity: entity, space_id: space_item['id'].to_s,
          model_id: model_id, model_name: (library_item['name'].to_s.empty? ? candidate[:label].to_s : library_item['name'].to_s),
          source_path: source_path, source_snapshot_signature: source_snapshot_signature,
          entry_representation: entry_representation, entry_definition: entry_definition_before_edit,
          entry_transformation: entry_transformation_before_edit, entry_locked: entry_locked_before_edit,
          entry_name: entry_name_before_edit, entry_layer: entry_layer_before_edit,
          # 兼容既有取消/回滚字段；它们现在表示“进入编辑前状态”，不再强制一定是代理。
          proxy_definition: entry_definition_before_edit, proxy_transformation: entry_transformation_before_edit,
          proxy_locked: entry_locked_before_edit, proxy_name: entry_name_before_edit, proxy_layer: entry_layer_before_edit,
          soft_attributes: soft_attributes_before_edit,
          source_full_definition: source_full_definition,
          edit_definitions: Array(edit_isolation[:definitions]),
          change_tracking: 'transaction', content_changed: false,
          content_change_events: 0, observe_changes: false,
          content_signature_before: '', entity_observers: {}, path_unlocks: [],
          last_inside_at: monotonic_time, exit_token: '',
          prompt_x: candidate[:trigger_x], prompt_y: candidate[:trigger_y],
          started_at: Time.now.to_f
        }
        bump_soft_instance_registry_revision(model)
        model.commit_operation
        operation_started = false
      rescue StandardError
        model.abort_operation rescue nil if operation_started
        @soft_individual_edit_sessions&.delete(model.object_id)
        raise
      end

      log("单件家具双击阶段 4/4：事务已提交，准备进入组件编辑 / #{model_id}")
      model.selection.clear
      model.selection.add(entity)
      if model.respond_to?(:active_path=)
        # v0.13.6.181：代理切真、历史壳压平、make_unique 都可能让进入前缓存的
        # InstancePath 变成旧路径。必须在结构操作完成后按“当前 entity 对象”重新
        # 从模型根定位一次有效路径，避免 Provided instance path is not valid。
        rebuilt_path = find_soft_pending_proxy_entity_path(entity, model)
        edit_path = rebuilt_path.empty? ? (original_path + [entity]) : rebuilt_path
        edit_record = soft_individual_edit_session(model)
        begin
          # “临时解锁 -> active_path=”必须处于同一个 internal guard 窗口，避免临时锁状态
          # 触发 ModelObserver 后又被后台锁维护逻辑在真正进入前抢先恢复。
          with_internal_sync_guard do
            edit_record[:path_unlocks] = unlock_soft_individual_edit_path_siblings!(edit_path, model) if edit_record
            path_definitions = edit_path.filter_map do |node|
              definition = node.definition rescue nil
              definition if definition && definition.valid?
            end.uniq
            remaining = path_definitions.select { |definition| space_edit_definition_has_locked_occurrence?(definition) rescue false }
            unless remaining.empty?
              raise ArgumentError, "进入家具前仍检测到 #{remaining.length} 个编辑路径 Definition 存在锁传播。"
            end
            model.active_path = edit_path
          end
        rescue StandardError => entry_error
          # v170 的缺口：active_path= 抛错时，代理切真/make_unique 已经提交，而旧代码
          # 只把异常冒泡，可能遗留临时解锁和半完成编辑会话。现在进入失败立即回滚。
          record = soft_individual_edit_session(model)
          unless Array(model.active_path).include?(entity)
            begin
              cancel_soft_individual_edit!(record, model) if record
            rescue StandardError => rollback_error
              restore_soft_individual_edit_path_locks!(record, model) if record
              @soft_individual_edit_sessions&.delete(model.object_id)
              log_exception('家具进入失败后的自动回滚失败', rollback_error)
            end
          end
          raise entry_error
        end
      end
      unless Array(model.active_path).include?(entity)
        record = soft_individual_edit_session(model)
        cancel_soft_individual_edit!(record, model) if record
        raise 'SketchUp 未能自动进入该家具；LinkHub 已恢复进入编辑前状态，本次没有留下未完成的真模型修改。'
      end
      # 确认 active_path 已经进入家具后才开启监听。额外 0.18 秒只吸收部分
      # SketchUp 版本延迟补发的入口事务，避免“进去看一眼”被误判成内容修改。
      edit_record = soft_individual_edit_session(model)
      if edit_record
        edit_record[:ignore_transactions_until] = monotonic_time + 0.18
        edit_record[:observe_changes] = true
        edit_record[:last_inside_at] = monotonic_time
        ensure_soft_individual_edit_entities_observer!(edit_record, model)
      end
      show_status("已将“#{candidate[:label]}”保持为真模型并进入安全编辑；未修改退出时继续显示真模型且不高亮，实际修改后保持真模型并蓝色高亮，发布时才统一生成和切换代理。", 'success')
      true
    rescue StandardError => e
      log_exception('双击家具代理进入独立真模型编辑失败', e)
      raise
    end

    def execute_workspace_double_click_candidate(candidate, model = Sketchup.active_model)
      return false unless candidate.is_a?(Hash) && model
      kind = candidate[:kind].to_s
      label = candidate[:label].to_s
      log("双击确认进入修改：#{kind}/#{candidate[:id]}")
      target_label = label.empty? ? '工作模型' : label
      show_workspace_floating_notice("已接收 · 正在进入#{target_label}", 'info', duration: 2.2, model: model)
      # 双击桥接层已经按候选对象、原生双击节奏和 suppress token 做了完整防重复。
      # 这里若再套通用 action_key 门禁，热重载或 SketchUp 嵌套工具回调留下的旧计数
      # 会只吞掉这个空间的后续进入动作：提示条显示“正在进入”，实际 block 从未执行。
      safe_callback("双击进入#{target_label}修改", guard: false) do
        case kind
        when 'soft_proxy'
          edit_soft_proxy_instance_via_double_click!(candidate, model)
        when 'space_spine', 'space_nested'
          enter_space_spine_entity_with_definition_isolation!(candidate[:entity], model)
        when 'space'
          switch_workspace_and_edit_space!(candidate[:id].to_s, model)
        when 'linked_space_transform'
          begin_linked_space_transform!(candidate[:id].to_s, candidate[:entity], model)
        when 'linked_space_pending_transform'
          begin_pending_linked_space_transform!(candidate[:entity], model)
        when 'linked_space_duplicate_adopt'
          adopt_duplicate_space_root_as_linked_pending!(model, candidate[:entity])
        when 'architecture_model'
          edit_architecture_model(candidate[:id].to_s, model)
        when 'discipline'
          begin_edit_session(candidate[:id].to_s)
        else
          raise '当前双击对象不是可修改的工作模型或家具代理。'
        end
      end
      true
    rescue StandardError => e
      log_exception('执行工作模型双击修改失败', e)
      false
    end

    def workspace_double_click_bridge_click(model, tool, signature, x, y, view, native_double_click = false)
      return false if @shutting_down
      return false unless model && model == Sketchup.active_model && tool && view
      key = model.object_id
      @workspace_double_click_candidates ||= {}
      @workspace_double_click_bridge_records ||= {}
      @workspace_double_click_suppress_until ||= {}
      bridge = @workspace_double_click_bridge_records[key]
      return false unless bridge.is_a?(Hash) && bridge[:tool].equal?(tool) && bridge[:active]
      return false if bridge[:handled]
      record = @workspace_double_click_candidates[key]
      candidate = workspace_double_click_candidate(model)
      current_signature = workspace_double_click_candidate_signature(candidate)
      unless record.is_a?(Hash) && candidate &&
             record[:signature].to_s == signature.to_s && current_signature == signature.to_s
        bridge[:handled] = false
        model.tools.pop_tool
        return false
      end

      unless workspace_double_click_pick_matches?(candidate, view, x, y)
        # 用户不是在执行双击，而是想选择别的根对象。尽量保留普通单击选择语义，
        # 随后退出桥接工具，下一次操作继续由原生 SelectionTool 接管。
        bridge[:handled] = false
        model.tools.pop_tool
        if candidate[:kind].to_s == 'soft_proxy'
          GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) do
            best, path = workspace_double_click_pick_path(view, x, y)
            picked = best || Array(path).reverse.find { |entry| entry && entry.valid? }
            model.selection.clear
            model.selection.add(picked) if picked && picked.valid?
          end
        else
          GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { workspace_double_click_select_other_root(model, view, x, y) }
        end
        return false
      end

      now = monotonic_seconds
      return false if @workspace_double_click_suppress_until[key].to_f > now
      previous = record[:last_click_at]
      gap = previous ? now - previous.to_f : now - record[:armed_at].to_f
      record[:last_click_at] = now
      qualifies = native_double_click ||
                  (gap >= WORKSPACE_DOUBLE_CLICK_MIN_SECONDS && gap <= WORKSPACE_DOUBLE_CLICK_MAX_SECONDS)
      unless qualifies
        # 当前已经选中该模型时，第一次点击只重新武装；第二次快速点击才进入。
        record[:armed_at] = now if gap > WORKSPACE_DOUBLE_CLICK_MAX_SECONDS
        return false
      end

      # v0.13.6.100：受管家具不再把“双击”直接等同于“开始真模型编辑”。
      # 双击只在鼠标原位置打开一个极小确认层；第三下原地点击“编辑真模型”才真正
      # 切真并进入。这样浏览空间时误双击家具不会产生入库/代理重建事务。
      if candidate[:kind].to_s == 'soft_proxy' && tool.respond_to?(:show_soft_edit_confirmation)
        bridge[:awaiting_confirmation] = true
        bridge[:confirmation_kind] = :soft_proxy
        bridge[:handled] = false
        bridge[:candidate] = candidate
        @workspace_double_click_suppress_until[key] = now + 0.18
        tool.show_soft_edit_confirmation(x, y, view)
        return true
      end

      # 跨硬装/软装根双击沿用家具确认层：鼠标旁只问一次“进入某工作区？”。
      # 点“是”后再切工作区并进入修改；点“否”完全不改变当前工作区和模型状态。
      if candidate[:kind].to_s == 'space' && space_workspace_role?(candidate[:role]) &&
         current_workspace_role(model) != candidate[:role].to_s &&
         tool.respond_to?(:show_workspace_switch_confirmation)
        bridge[:awaiting_confirmation] = true
        bridge[:confirmation_kind] = :workspace_switch
        bridge[:handled] = false
        bridge[:candidate] = candidate
        @workspace_double_click_suppress_until[key] = now + 0.18
        tool.show_workspace_switch_confirmation(workspace_role_label(candidate[:role]), x, y, view)
        return true
      end

      bridge[:handled] = true
      @workspace_double_click_suppress_until[key] = now + 1.0
      @workspace_double_click_candidates.delete(key)
      model.tools.pop_tool
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { execute_workspace_double_click_candidate(candidate, model) }
      true
    rescue StandardError => e
      log_exception('桥接工具处理工作模型双击失败', e)
      false
    end

    def workspace_double_click_confirmation_click(model, tool, signature, x, y, view)
      return false unless model && model == Sketchup.active_model && tool && view
      key = model.object_id
      bridge = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      return false unless bridge.is_a?(Hash) && bridge[:tool].equal?(tool) && bridge[:active]
      return false unless bridge[:awaiting_confirmation]
      candidate = bridge[:candidate]
      confirmation_kind = bridge[:confirmation_kind]
      valid_confirmation = candidate.is_a?(Hash) &&
                           ((confirmation_kind == :soft_proxy && candidate[:kind].to_s == 'soft_proxy') ||
                            (confirmation_kind == :workspace_switch && candidate[:kind].to_s == 'space'))
      unless valid_confirmation
        tool.clear_soft_edit_confirmation(view) if tool.respond_to?(:clear_soft_edit_confirmation)
        bridge[:awaiting_confirmation] = false
        bridge[:confirmation_kind] = nil
        model.tools.pop_tool rescue nil
        return false
      end

      action = tool.respond_to?(:soft_edit_confirmation_action_at) ? tool.soft_edit_confirmation_action_at(x, y) : nil
      # 点击确认框外等价于“取消”，避免确认层长期霸占 SelectionTool。
      if action == :edit
        candidate[:trigger_x] = x.to_f if candidate.is_a?(Hash)
        candidate[:trigger_y] = y.to_f if candidate.is_a?(Hash)
        bridge[:handled] = true
        bridge[:awaiting_confirmation] = false
        bridge[:confirmation_kind] = nil
        @workspace_double_click_suppress_until ||= {}
        @workspace_double_click_suppress_until[key] = monotonic_seconds + 0.9
        @workspace_double_click_candidates&.delete(key)
        tool.clear_soft_edit_confirmation(view) if tool.respond_to?(:clear_soft_edit_confirmation)
        model.tools.pop_tool rescue nil
        GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) do
          execute_workspace_double_click_candidate(candidate, model)
        end
        if confirmation_kind == :workspace_switch
          log("空间跨工作区双击确认：进入#{workspace_role_label(candidate[:role])} / #{candidate[:id]}")
        else
          log("家具双击确认：编辑真模型 / #{candidate[:id]}")
        end
        true
      else
        bridge[:handled] = false
        bridge[:awaiting_confirmation] = false
        bridge[:confirmation_kind] = nil
        @workspace_double_click_suppress_until ||= {}
        @workspace_double_click_suppress_until[key] = monotonic_seconds + 0.35
        @workspace_double_click_candidates&.delete(key)
        tool.clear_soft_edit_confirmation(view) if tool.respond_to?(:clear_soft_edit_confirmation)
        model.tools.pop_tool rescue nil
        if action == :cancel
          if confirmation_kind == :workspace_switch
            log("空间跨工作区双击确认：取消 / #{candidate[:id]}")
          else
            log("家具双击确认：取消 / #{candidate[:id]}")
          end
        end
        true
      end
    rescue StandardError => e
      log_exception('处理双击就地确认失败', e)
      false
    end

    def workspace_double_click_tool_changed(model, tool_name, tool_id)
      return if soft_commit_world_context_active?(model)
      return false unless model
      key = model.object_id
      bridge = @workspace_double_click_bridge_records && @workspace_double_click_bridge_records[key]
      # push_tool 激活桥接工具时会先收到 ActiveToolChanged；此时不能把刚刚
      # 记录的候选清掉。真正切换到其他工具时，桥接工具的 deactivate 会清理。
      return true if bridge.is_a?(Hash) && bridge[:active]
      return true if workspace_selection_tool?(tool_name, tool_id)
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      false
    rescue StandardError
      false
    end

    # ToolsObserver 回调自身不写模型，只安排一次主线程空闲处理。这样不会在原生
    # SelectionTool 的内部状态切换中直接解锁实体，也不会污染 Undo 事务。
    def workspace_double_click_tool_action(model, tool_name, tool_id, _tool_state = nil)
      return if soft_commit_world_context_active?(model)
      return false if @shutting_down
      return false unless model && model == Sketchup.active_model
      return false if workspace_escape_transition_active?(model)
      return false unless workspace_selection_tool?(tool_name, tool_id)
      return false unless workspace_selection_configured?(nil, model)
      @workspace_double_click_action_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(5)
      @workspace_double_click_action_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) do
        next unless @workspace_double_click_action_tokens[key] == token
        process_workspace_double_click_action(model)
      rescue StandardError => e
        log_exception('处理工作模型双击失败', e)
      end
      true
    rescue StandardError
      false
    end

    def process_workspace_double_click_action(model = Sketchup.active_model)
      return false if @shutting_down
      return false unless model && model == Sketchup.active_model
      return false if workspace_escape_transition_active?(model)
      @workspace_double_click_candidates ||= {}
      @workspace_double_click_suppress_until ||= {}
      key = model.object_id
      now = monotonic_seconds
      return false if @workspace_double_click_suppress_until[key].to_f > now

      candidate = workspace_double_click_candidate(model)
      # 全模根层级的空间/建筑仍维持原来的限制；active_path 内部只允许家具代理
      # 和“存在锁冲突的空间单一编辑脊柱”通过 ToolsObserver 回退链识别双击。
      # 普通嵌套组件仍不接管。
      if !model.active_path.nil? && (!candidate || !%w[soft_proxy space_spine space_nested].include?(candidate[:kind].to_s))
        @workspace_double_click_candidates.delete(key)
        return false
      end
      unless candidate
        @workspace_double_click_candidates.delete(key)
        return false
      end
      signature = workspace_double_click_candidate_signature(candidate)
      record = @workspace_double_click_candidates[key]
      unless record.is_a?(Hash) && record[:signature].to_s == signature
        @workspace_double_click_candidates[key] = {
          signature: signature, candidate: candidate, armed_at: now,
          last_action_at: now, last_selection_at: now
        }
        return false
      end

      previous_action = record[:last_action_at]
      record[:candidate] = candidate
      record[:last_action_at] = now
      if previous_action
        gap = now - previous_action.to_f
      else
        # 某些 SketchUp 版本在“改变选择”的第一击只发 SelectionObserver，
        # 不一定同时发 ToolState。此时第二击直接用 arm 时间判断，避免必须三击。
        gap = now - record[:armed_at].to_f
      end
      return false if gap < WORKSPACE_DOUBLE_CLICK_MIN_SECONDS
      if gap > WORKSPACE_DOUBLE_CLICK_MAX_SECONDS
        record[:armed_at] = now
        return false
      end

      @workspace_double_click_candidates.delete(key)
      @workspace_double_click_suppress_until[key] = now + 1.0
      execute_workspace_double_click_candidate(candidate, model)
    rescue StandardError => e
      log_exception('执行工作模型双击修改失败', e)
      false
    end

    def attach_workspace_double_click_tools_observer(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:tools)
      @workspace_double_click_tool_observers ||= {}
      key = model.object_id
      return true if @workspace_double_click_tool_observers[key]
      observer = WorkspaceDoubleClickToolsObserver.new(model)
      model.tools.add_observer(observer)
      @workspace_double_click_tool_observers[key] = { model: model, observer: observer }
      true
    rescue StandardError => e
      log_exception('挂接工作模型双击观察器失败', e)
      false
    end

    def forget_workspace_double_click_tools_observer(model)
      return false unless model
      key = model.object_id
      record = @workspace_double_click_tool_observers&.delete(key)
      observer = record.is_a?(Hash) ? record[:observer] : record
      begin
        model.tools.remove_observer(observer) if observer && model.respond_to?(:tools)
      rescue StandardError
        nil
      end
      @workspace_double_click_candidates&.delete(key)
      @workspace_double_click_action_tokens&.delete(key)
      @workspace_double_click_suppress_until&.delete(key)
      @workspace_double_click_bridge_tokens&.delete(key)
      bridge = @workspace_double_click_bridge_records&.delete(key)
      begin
        model.tools.pop_tool if bridge.is_a?(Hash) && bridge[:active] && model.respond_to?(:tools)
      rescue StandardError
        nil
      end
      true
    rescue StandardError
      false
    end

    def attach_workspace_toolbar_selection_observer(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:selection)
      @workspace_toolbar_selection_observers ||= {}
      key = model.object_id
      return true if @workspace_toolbar_selection_observers[key]
      observer = WorkspaceToolbarSelectionObserver.new(model)
      model.selection.add_observer(observer)
      @workspace_toolbar_selection_observers[key] = { model: model, observer: observer }
      true
    rescue StandardError => e
      log_exception('挂接顶部快捷条选择观察器失败', e)
      false
    end

    def forget_workspace_toolbar_selection_observer(model)
      return false unless model
      record = @workspace_toolbar_selection_observers&.delete(model.object_id)
      observer = record.is_a?(Hash) ? record[:observer] : record
      begin
        model.selection.remove_observer(observer) if observer && model.respond_to?(:selection)
      rescue StandardError
        nil
      end
      @workspace_toolbar_selection_tokens&.delete(model.object_id)
      true
    rescue StandardError
      false
    end

    def attach_coordinate_observer(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:add_observer)
      return false unless workspace_ready?(nil, model)
      attach_workspace_toolbar_selection_observer(model)
      attach_workspace_double_click_tools_observer(model)
      @coordinate_model_observers ||= {}
      key = model.object_id
      return true if @coordinate_model_observers[key]
      observer = CoordinateModelObserver.new
      model.add_observer(observer)
      @coordinate_model_observers[key] = { model: model, observer: observer }
      remember_model_resource_snapshot!(model)
      write_coordinate_metadata_for_model(model)
      recover_space_edit_context_tracking(model) if respond_to?(:recover_space_edit_context_tracking)
      true
    rescue StandardError => e
      log_exception('挂接坐标观察器失败', e)
      false
    end

    def forget_coordinate_model_observer(model)
      return false unless model
      @coordinate_model_observers&.delete(model.object_id)
      true
    rescue StandardError
      false
    end

    def install_coordinate_observers
      model = Sketchup.active_model
      attach_coordinate_observer(model) if model
      unless @coordinate_app_observer
        @coordinate_app_observer = CoordinateAppObserver.new
        Sketchup.add_observer(@coordinate_app_observer)
      end
      true
    rescue StandardError => e
      log_exception('安装坐标观察器失败', e)
      false
    end

    # 监听 SketchUp 自带右键“解锁/锁定”。这不是外部文件实时更新：
    # 只读取当前模型中最多四个联动根组件的 locked? 状态，不访问网络盘，
    # 不读取 SKP，也绝不会触发重载。这样既保留原生右键的稳定性，
    # 又能可靠显示“提交修改”按钮。

    # 项目软装清单只在清单页可见时刷新。第一轮性能治理把“全项目轮询”
    # 改为“当前空间脏标记 + 按空间缓存 + 低频兜底”。大多数移动、缩放、复制、
    # 删除都由事务/实体观察器即时标记；兜底轮询只检查当前正在查看的空间。
    def soft_measurement_revision(model = Sketchup.active_model)
      @soft_measurement_revisions ||= {}
      model ? @soft_measurement_revisions[model.object_id].to_i : 0
    rescue StandardError
      0
    end

    def soft_measurement_entity_key(entity, model = Sketchup.active_model)
      return '' unless entity && model
      local = if entity.respond_to?(:persistent_id)
                entity.persistent_id.to_i
              elsif entity.respond_to?(:entityID)
                entity.entityID.to_i
              else
                entity.object_id
              end
      "#{model.object_id}:#{local}"
    rescue StandardError
      ''
    end

    def soft_measurement_current_space_id(model = Sketchup.active_model, state = nil)
      return '' unless model
      state ||= cached_project_state_readonly(model) || load_state(model)
      id = state['space_editing_id'].to_s
      return id unless id.empty?
      path = Array(model.active_path)
      return '' if path.empty?
      Array(state['space_models']).each do |item|
        root = space_model_entity(item['id'], model)
        return item['id'].to_s if root && root.valid? && path.include?(root)
      rescue StandardError
        next
      end
      ''
    rescue StandardError
      ''
    end

    # 清单与软装工作台都关闭时，事务回调不能为了判断“哪个空间变了”去读取项目
    # JSON 或共享目录。活动编辑路径的第一层空间根已经带有稳定 space_id，优先从
    # 当前模型内存直接取得；只有无法确定范围的根级事务才退回“全项目过期”。
    def soft_measurement_current_space_id_fast(model = Sketchup.active_model)
      return '' unless model
      path = Array(model.active_path)
      unless path.empty?
        root = path.first
        if root && root.valid? && root.respond_to?(:get_attribute)
          id = root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
          return id unless id.empty?
        end
      end
      state = cached_project_state_readonly(model)
      return '' unless state.is_a?(Hash)
      state['space_editing_id'].to_s
    rescue StandardError
      ''
    end

    def soft_measurement_dirty_map(model = Sketchup.active_model)
      @soft_measurement_dirty_spaces ||= {}
      return {} unless model
      @soft_measurement_dirty_spaces[model.object_id] ||= {}
    rescue StandardError
      {}
    end

    def mark_soft_measurement_dirty(model = Sketchup.active_model, space_id = nil)
      return false unless model
      id = space_id.to_s
      dirty = soft_measurement_dirty_map(model)
      if id.empty?
        dirty['*'] = true
        (@soft_measurement_space_row_caches || {})[model.object_id]&.clear
        (@soft_schedule_location_hit_caches || {})[model.object_id]&.clear
      else
        dirty[id] = true
        (@soft_measurement_space_row_caches || {}).dig(model.object_id)&.delete(id)
        (@soft_schedule_location_hit_caches || {}).dig(model.object_id)&.delete(id)
      end
      true
    rescue StandardError
      false
    end

    def clear_soft_measurement_dirty(model = Sketchup.active_model, space_id = nil)
      return false unless model
      dirty = soft_measurement_dirty_map(model)
      id = space_id.to_s
      if id.empty?
        dirty.clear
      else
        dirty.delete(id)
        # “全部过期”时缓存已整体清空；当前空间重新计算后可以移除通配标记，
        # 其他空间因为没有缓存仍会在真正请求时自动重算。
        dirty.delete('*')
      end
      true
    rescue StandardError
      false
    end

    def soft_measurement_dirty?(model = Sketchup.active_model, space_id = nil)
      dirty = soft_measurement_dirty_map(model)
      id = space_id.to_s
      dirty['*'] || (!id.empty? && dirty[id])
    rescue StandardError
      true
    end

    def bump_soft_measurement_revision(model = Sketchup.active_model, space_id = nil)
      return 0 unless model
      @soft_measurement_revisions ||= {}
      key = model.object_id
      @soft_measurement_revisions[key] = @soft_measurement_revisions[key].to_i + 1
      mark_soft_measurement_dirty(model, space_id)
      @soft_measurement_revisions[key]
    rescue StandardError
      0
    end

    # Dynamic Components 在事务结束后仍可能延迟更新 LenX/LenY/LenZ。这里只保留
    # 两次低频复核，并用 token 取消上一轮残留任务；不会再一口气排四次全项目扫描。
    def schedule_soft_measurement_refresh_burst(model = Sketchup.active_model)
      return false unless model && @soft_measurement_view_active
      @soft_measurement_burst_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6)
      @soft_measurement_burst_tokens[key] = token
      SOFT_MEASUREMENT_REFRESH_BURST_DELAYS.each_with_index do |delay, index|
        GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
          delay, false, label: 'measurement:delayed_verify',
          key: "measurement:delayed_verify:#{key}:#{index}", model: model, active_model_only: true
        ) do
          next unless @soft_measurement_burst_tokens[key] == token
          next unless @soft_measurement_view_active
          next unless @soft_designer_dialog && @soft_designer_dialog.visible?
          refresh_soft_measurements_if_changed(soft_measurement_revision(model), model, force_compare: true)
        rescue StandardError => e
          log_exception('复核软装实例尺寸失败', e)
        end
      end
      true
    rescue StandardError
      false
    end

    # 仅记录用户可见的建模事务。发布、批量更新、代真切换等 LinkHub 内部事务
    # 已由 heavy/update guard 排除，因此可以判断“自上次安全保存后用户是否又编辑过”。
    def user_edit_generation(model = Sketchup.active_model)
      @user_edit_generations ||= {}
      model ? @user_edit_generations[model.object_id].to_i : 0
    rescue StandardError
      0
    end

    def bump_user_edit_generation(model = Sketchup.active_model)
      return user_edit_generation(model) unless model
      return user_edit_generation(model) if @updating || soft_heavy_interaction? || publish_critical_section? || publish_post_quiet?
      @user_edit_generations ||= {}
      key = model.object_id
      @user_edit_generations[key] = @user_edit_generations[key].to_i + 1
    rescue StandardError
      0
    end

    # SketchUp 自带“清除未使用项”可以删除插件为了加速而暂存在模型中的、当前
    # 没有实例的真模型/代理定义。它不会删除正在使用的空间组件，也不会修改外部
    # 模型库文件。这里检测资源数量下降并只清理失效的 Ruby 缓存，下一次需要时
    # 从模型库按需重载，因此原生清理与 LinkHub 可以安全共存。
    def model_resource_snapshot(model = Sketchup.active_model)
      return {} unless model
      {
        definitions: (model.definitions.length rescue 0),
        materials: (model.materials.length rescue 0),
        layers: (model.layers.length rescue 0),
        styles: (model.styles.length rescue 0)
      }
    rescue StandardError
      {}
    end

    def remember_model_resource_snapshot!(model = Sketchup.active_model)
      return false unless model
      @model_resource_snapshots ||= {}
      @model_resource_snapshots[model.object_id] = model_resource_snapshot(model)
      true
    rescue StandardError
      false
    end

    def prune_invalid_definition_caches_after_native_purge!(model = Sketchup.active_model)
      return false unless model
      key = model.object_id
      [@soft_loaded_definition_caches, @soft_proxy_definition_caches, @soft_custom_proxy_definition_caches].compact.each do |root_cache|
        cache = root_cache[key]
        cache.delete_if { |_cache_key, definition| !definition || !definition.valid? } if cache.respond_to?(:delete_if)
      end
      if @soft_full_definition_tree_caches && (cache = @soft_full_definition_tree_caches[key])
        cache.delete_if do |_cache_key, tree|
          Array(tree).none? { |definition| definition && definition.valid? }
        end
      end
      # 原生清理只会让一部分定义失效。旧版把所有模型的外包盒缓存一刀清空，
      # 导致清理后第一次代/真切换重新递归扫描全部高模。现在只丢弃失效对象。
      @soft_definition_bounds_cache&.delete_if do |_definition_id, record|
        definition = record.is_a?(Hash) ? record[:definition] : nil
        definition && (!definition.respond_to?(:valid?) || !definition.valid?)
      end
      if @soft_representation_pair_caches && (pair_cache = @soft_representation_pair_caches[key])
        pair_cache.delete_if do |_pair_key, record|
          proxy_definition = record.is_a?(Hash) ? record[:proxy_definition] : nil
          full_definition = record.is_a?(Hash) ? record[:full_definition] : nil
          !proxy_definition || !full_definition || !proxy_definition.valid? || !full_definition.valid?
        end
      end
      if @soft_resident_full_records && (resident = @soft_resident_full_records[key])
        resident.delete_if do |_definition_id, record|
          definition = record.is_a?(Hash) ? record[:definition] : nil
          !definition || !definition.valid?
        end
      end
      @soft_instance_registry_cache&.delete(key)
      @soft_full_cleanup_reconciled_models&.delete(key)
      @soft_managed_definition_cleanup_records&.delete(key)
      @landscape_loaded_definition_caches&.delete(key) if @landscape_loaded_definition_caches.respond_to?(:delete)
      bump_soft_instance_registry_revision(model)
      mark_soft_measurement_dirty(model)
      true
    rescue StandardError => e
      log_exception('原生清理后修复插件缓存失败', e)
      false
    end

    def reconcile_model_resources_after_transaction!(model, token = nil)
      return false unless model
      @model_resource_reconcile_tokens ||= {}
      return false if token && @model_resource_reconcile_tokens[model.object_id].to_s != token.to_s
      @model_resource_snapshots ||= {}
      previous = @model_resource_snapshots[model.object_id] || model_resource_snapshot(model)
      current = model_resource_snapshot(model)
      @model_resource_snapshots[model.object_id] = current
      reduced = current.any? { |name, count| count.to_i < previous[name].to_i }
      return true unless reduced

      changes = current.keys.filter_map do |name|
        before = previous[name].to_i
        after = current[name].to_i
        "#{name}=#{before}->#{after}" if after < before
      end
      prune_invalid_definition_caches_after_native_purge!(model)
      schedule_soft_representation_cache_warmup(model, delay: 0.65) unless soft_heavy_interaction?
      log("检测到原生资源清理或删除：#{changes.join(', ')}；已丢弃失效缓存，外部模型库不受影响。")
      true
    rescue StandardError => e
      log_exception('核对原生资源清理结果失败', e)
      false
    end

    def schedule_model_resource_reconcile(model = Sketchup.active_model)
      return false unless model
      @model_resource_reconcile_tokens ||= {}
      token = SecureRandom.hex(6)
      @model_resource_reconcile_tokens[model.object_id] = token
      runtime_start_timer(
        NATIVE_RESOURCE_RECONCILE_DELAY, false, label: 'native_resource_reconcile',
        key: "native_resource_reconcile:#{model.object_id}", model: model, active_model_only: true
      ) do
        reconcile_model_resources_after_transaction!(model, token)
      end
      true
    rescue StandardError
      false
    end

    # v0.13.5.16：采购清单只修改名称/厂家等元数据时，不应被当成一次几何编辑。
    # 旧版在同步实例名称时会触发 ModelObserver#onTransactionCommit，随后把所有空间
    # 的软装统计缓存全部标脏；大型项目一次名称修改因此会重新扫描全部空间，耗时可达
    # 数十秒甚至一分钟。这个轻量事务域只屏蔽“纯元数据同步”造成的几何失效链。
    def soft_metadata_sync_active?(model = Sketchup.active_model)
      return false unless model
      (@soft_metadata_sync_models || {})[model.object_id].to_i.positive?
    rescue StandardError
      false
    end

    def with_soft_metadata_sync(model = Sketchup.active_model)
      return yield unless model
      @soft_metadata_sync_models ||= Hash.new(0)
      key = model.object_id
      @soft_metadata_sync_models[key] += 1
      yield
    ensure
      if defined?(key) && key && @soft_metadata_sync_models
        @soft_metadata_sync_models[key] = [@soft_metadata_sync_models[key].to_i - 1, 0].max
        @soft_metadata_sync_models.delete(key) if @soft_metadata_sync_models[key].zero?
      end
    end

    def soft_model_transaction_committed(model = Sketchup.active_model)
      return false unless model
      # transaction commit 既可能来自用户，也可能来自 LinkHub 自己的属性/状态同步。
      # 保留它作为“刚有模型事务”的信号，但不要和真正的鼠标/按钮/选择交互等权处理。
      note_runtime_interaction!(model, source: :model_transaction)
      # 采购清单名称/路径/资料同步只修改属性和显示名称，不改变几何、材质或实例数量。
      # 在该事务域内直接返回，避免 ModelObserver 把全部空间测量缓存清空。
      return true if soft_metadata_sync_active?(model)
      soft_invalidate_active_path_bounds!(model)
      mark_soft_individual_edit_transaction_change!(model)
      mark_shared_component_transaction_change!(model)
      mark_space_edit_transaction_change!(model)
      schedule_model_resource_reconcile(model)
      return true if publish_critical_section? || publish_post_quiet?
      # v0.13.6.19：在空间/组件内部编辑时，受管“根实例集合”不可能因内部几何事务
      # 发生增删。旧版仍然每次让全局根索引失效，并安排根锁同步与结构审计，导致
      # 下一轮监视器反复重建全局索引。只有模型根层级事务才需要这三项全局保护。
      root_level_transaction = model.active_path.nil?
      invalidate_managed_root_index(model, reason: 'transaction') if root_level_transaction
      bump_user_edit_generation(model)
      if root_level_transaction
        schedule_native_lock_sync(model, 0.12)
        schedule_edit_structure_audit(model, 0.90)
      end
      bump_soft_instance_registry_revision(model) unless soft_representation_switching?(model)
      schedule_open = @soft_schedule_dialog && @soft_schedule_dialog.visible?

      # v0.13.6.40：采购清单第一次模型变化已经把整份快照标记为“需刷新”后，
      # 后续连续移动/旋转/缩放不需要每个 Commit 再 load_state、识别空间、删缓存、
      # 发 HtmlDialog 状态。刷新前快照本来就不允许提交/导出，因此一次脏标记足够。
      # 软装尺寸工作台开启时仍保持原有实时测量链，不能走这条快速返回。
      if schedule_open && !@soft_measurement_view_active &&
         @soft_schedule_snapshot_stale && @soft_schedule_snapshot_stale[model.object_id]
        return true
      end

      unless @soft_measurement_view_active || schedule_open
        # 清单都关闭时绝不读取项目/共享状态。若当前正在某个空间内部编辑，只让
        # 该空间缓存过期；根级事务无法可靠归属时才把全项目标脏。
        fast_space_id = soft_measurement_current_space_id_fast(model)
        mark_soft_measurement_dirty(model, fast_space_id.empty? ? nil : fast_space_id)
        return true
      end
      space_id = soft_measurement_current_space_id(model)
      # 没有进入任何可编辑空间时，普通建模事务不可能改变已经锁定的空间内容。
      return true if space_id.to_s.empty?

      if @soft_measurement_view_active
        bump_soft_measurement_revision(model, space_id)
        schedule_soft_measurement_refresh(model, 0.10)
        schedule_soft_measurement_refresh_burst(model)
        # 同时开着软装工作台与采购清单时，工作台尺寸仍可实时更新；采购清单继续
        # 保持手动刷新快照，绝不能因为另一个窗口活跃又偷偷恢复整表自动重算。
        mark_soft_schedule_snapshot_stale!(model, space_id, revision_already_bumped: true) if schedule_open
      elsif schedule_open
        # v0.13.6.39 PERFORMANCE PASS 1：采购清单作为“可审阅快照”存在时，
        # SketchUp 每一次移动/缩放/编辑事务只把当前空间标脏并通知网页“模型有变化”。
        # 不再在 1.25 秒空闲后递归统计空间、读取共享 manifest/NAS 状态并重建整张清单。
        # 用户点“刷新”时才统一计算，从根源上避免开着采购清单时每动一下都卡。
        schedule_soft_schedule_idle_transaction_refresh(model, space_id)
      else
        bump_soft_measurement_revision(model, space_id)
      end
      true
    rescue StandardError
      false
    end

    def soft_measurement_entity_changed(entity = nil, model = Sketchup.active_model)
      return false unless model && @soft_measurement_view_active
      key = soft_measurement_entity_key(entity, model)
      space_id = (@soft_measurement_entity_space_ids || {})[key].to_s
      space_id = soft_measurement_current_space_id(model) if space_id.empty?
      bump_soft_measurement_revision(model, space_id)
      schedule_soft_measurement_refresh(model, 0.10)
      schedule_soft_measurement_refresh_burst(model)
      true
    rescue StandardError
      false
    end

    def start_soft_measurement_poll_timer(model = Sketchup.active_model)
      return true if @soft_measurement_poll_timer
      @soft_measurement_poll_timer = GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(SOFT_MEASUREMENT_POLL_INTERVAL, true, label: 'measurement:fallback_poll') do
        unless @soft_measurement_view_active && @soft_designer_dialog && @soft_designer_dialog.visible?
          stop_soft_measurement_poll_timer
          next
        end
        active = Sketchup.active_model || model
        attach_soft_measurement_entity_observers(active)
        refresh_soft_measurements_if_changed(soft_measurement_revision(active), active, force_compare: true)
      rescue StandardError => e
        log_exception('轮询软装实例尺寸失败', e)
      end
      true
    rescue StandardError
      @soft_measurement_poll_timer = nil
      false
    end

    def stop_soft_measurement_poll_timer
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_stop_timer(@soft_measurement_poll_timer) if @soft_measurement_poll_timer
      @soft_measurement_poll_timer = nil
      true
    rescue StandardError
      @soft_measurement_poll_timer = nil
      false
    end

    def collect_soft_managed_entities_for_observer(definition, result, trail = [])
      return result unless definition && definition.valid?
      oid = definition.object_id
      return result if trail.include?(oid)
      next_trail = trail + [oid]
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        model_id = soft_instance_metadata(entity)['model_id'].to_s
        if !model_id.empty?
          result << entity
          next
        end
        collect_soft_managed_entities_for_observer(entity.definition, result, next_trail)
      end
      result
    rescue StandardError
      result
    end

    def attach_soft_measurement_entity_observers(model = Sketchup.active_model, force: false)
      return false unless model
      @soft_measurement_entity_observer ||= SoftMeasurementEntityObserver.new
      @soft_measurement_observed_entities ||= {}
      @soft_measurement_entity_space_ids ||= {}
      @soft_measurement_observer_scan_records ||= {}
      model_key = model.object_id
      record = @soft_measurement_observer_scan_records[model_key] || {}
      now = monotonic_time
      state = load_state(model)
      current_space_id = soft_measurement_current_space_id(model, state)
      if !force && record[:space_id].to_s == current_space_id &&
         (now - record[:scanned_at].to_f) < SOFT_MEASUREMENT_OBSERVER_RESCAN_INTERVAL
        return true
      end

      started = monotonic_time
      live_keys = {}
      target_spaces = Array(state['space_models']).select { |space| space['id'].to_s == current_space_id }
      target_spaces.each do |space|
        root = space_model_entity(space['id'], model)
        next unless root && root.valid?
        entities = []
        collect_soft_managed_entities_for_observer(root.definition, entities)
        entities.each do |entity|
          next unless entity.valid? && entity.respond_to?(:add_observer)
          key = soft_measurement_entity_key(entity, model)
          next if key.empty?
          live_keys[key] = true
          @soft_measurement_entity_space_ids[key] = space['id'].to_s
          next if @soft_measurement_observed_entities[key] && @soft_measurement_observed_entities[key].valid?
          entity.add_observer(@soft_measurement_entity_observer)
          @soft_measurement_observed_entities[key] = entity
        rescue StandardError
          next
        end
      end
      @soft_measurement_observed_entities.delete_if do |key, entity|
        remove = key.start_with?("#{model_key}:") && (!live_keys[key] || !entity || !entity.valid?)
        @soft_measurement_entity_space_ids.delete(key) if remove
        remove
      end
      @soft_measurement_observer_scan_records[model_key] = {
        scanned_at: now,
        count: live_keys.length,
        space_id: current_space_id
      }
      log_slow_operation('清单当前空间观察器复核', started, 100.0, "#{live_keys.length} 个家具")
      true
    rescue StandardError => e
      log_exception('挂接软装实例尺寸观察器失败', e)
      false
    end

    def detach_soft_measurement_entity_observers(model = nil)
      records = @soft_measurement_observed_entities ||= {}
      prefix = model ? "#{model.object_id}:" : nil
      records.keys.each do |key|
        next if prefix && !key.start_with?(prefix)
        entity = records.delete(key)
        begin
          entity.remove_observer(@soft_measurement_entity_observer) if entity && entity.valid? && @soft_measurement_entity_observer
        rescue StandardError
          nil
        end
        @soft_measurement_entity_space_ids&.delete(key)
      end
      @soft_measurement_observer_scan_records&.delete(model.object_id) if model
      true
    rescue StandardError
      false
    end

    def set_soft_measurement_view_active(active, model = Sketchup.active_model)
      @soft_measurement_view_active = !!active
      if @soft_measurement_view_active
        space_id = soft_measurement_current_space_id(model)
        mark_soft_measurement_dirty(model, space_id)
        attach_soft_measurement_entity_observers(model, force: true)
        start_soft_measurement_poll_timer(model)
        schedule_soft_measurement_refresh(model, 0.06)
      else
        stop_soft_measurement_poll_timer
        detach_soft_measurement_entity_observers(model)
        @soft_measurement_burst_tokens&.delete(model.object_id) if model
      end
      true
    rescue StandardError
      false
    end

    def schedule_soft_measurement_refresh(model = Sketchup.active_model, delay = 0.35)
      return false unless model && @soft_designer_dialog && @soft_designer_dialog.visible?
      @soft_measurement_refresh_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6)
      @soft_measurement_refresh_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
        delay.to_f, false, label: 'measurement:debounced_refresh',
        key: "measurement:debounced_refresh:#{key}", model: model, active_model_only: true
      ) do
        next unless @soft_measurement_refresh_tokens[key] == token
        next unless @soft_measurement_view_active
        next unless @soft_designer_dialog && @soft_designer_dialog.visible?
        attach_soft_measurement_entity_observers(model)
        refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: true)
      rescue StandardError => e
        log_exception('实时刷新项目软装清单失败', e)
      end
      true
    rescue StandardError
      false
    end

    def collect_soft_measurement_signature_parts(definition, parent_transform, parts, trail = [], occurrence_path = '')
      return parts unless definition && definition.valid?
      oid = definition.object_id
      return parts if trail.include?(oid)
      next_trail = trail + [oid]
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        model_id = soft_instance_metadata(entity)['model_id'].to_s
        combined = parent_transform * entity.transformation
        if !model_id.empty?
          dims = soft_instance_schedule_dimensions_mm(entity, combined)
          # 清单只关心产品、数量和实际规格；家具在空间内平移/旋转并不会改变采购清单。
          # 因此兜底签名不再序列化 16 个变换矩阵值，重复字符串本身即可表达数量。
          parts << [model_id, *dims.map { |value| format('%.2f', value.to_f) }].join('|')
          next
        end
        collect_soft_measurement_signature_parts(entity.definition, combined, parts, next_trail, occurrence_path)
      end
      parts
    rescue StandardError
      parts
    end

    def soft_measurement_geometry_signature(state = nil, model = Sketchup.active_model, space_ids: nil, all_spaces: false)
      return '' unless model
      state ||= load_state(model)
      ids = Array(space_ids).map(&:to_s).reject(&:empty?)
      unless all_spaces || !ids.empty?
        current = soft_measurement_current_space_id(model, state)
        ids = [current] unless current.empty?
      end
      spaces = Array(state['space_models'])
      spaces = spaces.select { |item| ids.include?(item['id'].to_s) } unless all_spaces || ids.empty?
      parts = []
      spaces.sort_by { |item| item['number'].to_i }.each do |space|
        entity = space_model_entity(space['id'], model)
        next unless entity && entity.valid?
        collect_soft_measurement_signature_parts(entity.definition, entity.transformation, parts, [], "space:#{space['id']}")
      end
      Digest::SHA1.hexdigest(parts.sort.join("\n"))
    rescue StandardError
      ''
    end

    def refresh_soft_measurements_if_changed(client_revision, model = Sketchup.active_model, force_compare: false)
      return false unless @soft_measurement_view_active && model
      @soft_measurement_signatures ||= {}
      key = model.object_id
      state = load_state(model)
      space_id = soft_measurement_current_space_id(model, state)
      return true if space_id.empty?
      signature = soft_measurement_geometry_signature(state, model, space_ids: [space_id])
      signature_key = "#{key}:#{space_id}"
      previous = @soft_measurement_signatures[signature_key].to_s
      signature_changed = !signature.empty? && signature != previous
      if signature_changed
        @soft_measurement_signatures[signature_key] = signature
        bump_soft_measurement_revision(model, space_id) unless previous.empty? || soft_measurement_dirty?(model, space_id)
      end
      current = soft_measurement_revision(model)
      return true if !signature_changed && current.to_i == client_revision.to_i
      return true if !signature_changed && !force_compare
      refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: true)
      true
    rescue StandardError => e
      log_exception('比较软装清单变化失败', e)
      false
    end

    # Undo / Redo 可能同时还原根组件的 locked 状态。这里只把当前真实状态写入
    # Ruby 内存缓存，防止 0.25 秒监视器把一次历史回退误认为新的“解锁/锁定”
    # 动作并再次写模型，从而破坏 Redo。此方法可安全地从 ModelObserver 调用。
    def native_history_transaction_finished(model = Sketchup.active_model)
      return false unless model
      return true if publish_critical_section? || publish_post_quiet?
      @native_lock_state_cache ||= {}
      unless @native_lock_monitor_timer
        # 面板、抽屉和修改会话都未运行时，只丢弃该模型的旧锁定快照。
        # 不解析项目状态、不访问协同目录，也不向 Undo/Redo 追加任何操作。
        @native_lock_state_cache.delete_if do |cache_key, _value|
          cache_key.is_a?(Array) && cache_key.first == model.object_id
        end
        return true
      end
      state = load_state(model)
      return false unless workspace_selection_configured?(state, model)

      state['links'].each do |key, _link|
        next unless %w[architecture landscape].include?(key.to_s)
        cache_key = [model.object_id, key]
        entity = native_edit_entity(key, model)
        if entity && entity.valid?
          @native_lock_state_cache[cache_key] = entity_native_locked?(entity)
        else
          @native_lock_state_cache.delete(cache_key)
        end
      rescue StandardError
        @native_lock_state_cache.delete(cache_key) if defined?(cache_key)
      end

      Array(state['architecture_models']).each do |item|
        cache_key = [model.object_id, edit_root_key_for_architecture_model(item['id'])]
        entity = architecture_model_entity(item['id'], model)
        if entity && entity.valid?
          @native_lock_state_cache[cache_key] = entity_native_locked?(entity)
        else
          @native_lock_state_cache.delete(cache_key)
        end
      rescue StandardError
        @native_lock_state_cache.delete(cache_key) if defined?(cache_key)
      end

      Array(state['space_models']).each do |item|
        cache_key = space_native_cache_key(model, item['id'])
        entity = space_model_entity(item['id'], model)
        if entity && entity.valid?
          @native_lock_state_cache[cache_key] = entity_native_locked?(entity)
        else
          @native_lock_state_cache.delete(cache_key)
        end
      rescue StandardError
        @native_lock_state_cache.delete(cache_key) if defined?(cache_key)
      end

      schedule_edit_structure_audit(model, 0.07)
      @native_history_refresh_tokens ||= {}
      token = SecureRandom.hex(6)
      @native_history_refresh_tokens[model.object_id] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
        0.03, false, label: 'history:refresh_ui', key: "history:refresh_ui:#{model.object_id}",
        model: model, active_model_only: true
      ) do
        next unless @native_history_refresh_tokens[model.object_id] == token
        next if soft_heavy_interaction?
        refresh_dialog
      rescue StandardError
        nil
      end
      true
    rescue StandardError => e
      log_exception('撤回后刷新原生锁定缓存失败', e)
      false
    end

    def preview_source_for_entity(link, entity, model = Sketchup.active_model)
      candidates = []
      candidates << resolve_source_for_edit(link['model_path'].to_s, model)
      if entity && entity.valid? && entity.respond_to?(:get_attribute)
        stored = entity.get_attribute(ENTITY_DICT, 'source', '').to_s
        candidates << resolve_path(stored, model) unless stored.empty?
      end
      candidates.compact.map(&:to_s).find { |path| !path.empty? && File.file?(path) } ||
        candidates.compact.map(&:to_s).find { |path| !path.empty? }.to_s
    rescue StandardError
      ''
    end

    def sync_native_preview_state(model = Sketchup.active_model)
      return false if publish_critical_section? || publish_post_quiet? || soft_heavy_interaction?
      return false if @syncing_native_preview_state || @updating || @architecture_explicit_publish_in_progress || @publish_presave_in_progress
      return false if edit_transition_quiet? || @edit_focus_switch_in_progress
      return false unless model
      @syncing_native_preview_state = true
      with_internal_sync_guard do
        @native_lock_state_cache ||= {}
        state = load_state(model)
        return false unless workspace_selection_configured?(state, model)
        changed = heartbeat_edit_locks_if_due(state)

        state['links'].each do |key, link|
          # 软装＋硬装已改为多个空间实例，必须由下方空间锁定同步单独处理。
          # 若继续走旧的单专业预览流程，会把第一个空间误判为“硬装总模型”。
          next unless %w[architecture landscape].include?(key.to_s)
          next if host_native_link?(state, key, model)
          entity = native_edit_entity(key, model)
          cache_key = [model.object_id, key]
          unless entity && entity.valid?
            @native_lock_state_cache.delete(cache_key)
            next
          end

          locked = entity_native_locked?(entity)
          previous = @native_lock_state_cache[cache_key]
          @native_lock_state_cache[cache_key] = locked

          # 第一次观察到一个已经锁定、且没有任何预览会话的对象时，只建缓存。
          # 已经解锁的对象，或旧会话中已记录为编辑状态的对象，仍会立即恢复状态。
          if previous.nil?
            next if locked && !(link['preview_edit_active'] || link['preview_pending_publish'] || entity.get_attribute(ENTITY_DICT, 'preview_editing', false))
          else
            next if previous == locked
          end

          source = preview_source_for_entity(link, entity, model)

          if !locked
            # 原生解锁绝不再创建/接管协作锁。唯一允许保持解锁的是已经通过 LinkHub
            # “修改”建立的会话，并且共享锁仍有效且归当前工作区所有。这样热重载可以恢复，
            # 但普通右键误解锁不会悄悄占用项目。
            lock_info = source.to_s.empty? ? {} : source_lock_info(source, link, model, state)
            valid_linkhub_session = link['edit_session_active'] && lock_info['exists'] && !lock_info['stale'] && lock_info['owned']
            unless valid_linkhub_session
              safe_model_operation(model, "保护#{link['name']}协作锁定") do
                entity.locked = true if entity.respond_to?(:locked=)
                entity.set_attribute(ENTITY_DICT, 'editing', false)
                entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
              end
              @native_lock_state_cache[cache_key] = true
              link['preview_edit_active'] = false
              link['preview_pending_publish'] = false
              link['status'] = '已阻止原生解锁 · 请使用 LinkHub 修改'
              changed = true
              show_status("#{link['name']} 已自动重新锁定；请使用 LinkHub“修改”进入协作编辑。", 'info')
              next
            end
            clear_managed_safe_pause!(link) if managed_edit_safe_paused?(link)
            entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
            # 这里只恢复视图锁定状态，不重新建立 preview baseline。否则插件热重载时
            # 可能把原编辑基线/冲突标记重置为当前共享文件，削弱后续冲突检测。
            link['preview_edit_active'] = true
            link['preview_pending_publish'] = false
            link['status'] = "#{current_user_name} 正在修改#{link['name']}"
            entity.set_attribute(ENTITY_DICT, 'editing', true)
            entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
            capture_edit_root_protection!(key, entity, model)
            changed = true
          else
            # 原生“锁定”也绝不代表发布。合法 LinkHub 编辑中误锁时自动恢复解锁；
            # 旧版遗留的 preview 状态若没有合法 edit_session，则保持锁定并停止该旧流程，
            # 不弹提交提示、不写共享 SKP，用户必须回到 LinkHub 的“恢复/修改/发布”。
            next if managed_edit_safe_paused?(link)
            had_preview = previous == false || link['preview_edit_active'] || entity.get_attribute(ENTITY_DICT, 'preview_editing', false)
            next unless had_preview || link['preview_pending_publish']
            lock_info = source.to_s.empty? ? {} : source_lock_info(source, link, model, state)
            valid_linkhub_session = link['edit_session_active'] && lock_info['exists'] && !lock_info['stale'] && lock_info['owned']
            if valid_linkhub_session
              entity.locked = false if entity.respond_to?(:locked=)
              entity.set_attribute(ENTITY_DICT, 'editing', true)
              entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
              @native_lock_state_cache[cache_key] = false
              link['preview_edit_active'] = true
              link['preview_pending_publish'] = false
              link['status'] = '待发布 · 请使用 LinkHub 发布按钮'
              changed = true
              show_status("#{link['name']} 仍保持修改；请使用 LinkHub 发布按钮提交。", 'info')
            else
              entity.set_attribute(ENTITY_DICT, 'editing', false)
              entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
              link['preview_edit_active'] = false
              link['preview_pending_publish'] = false
              link['status'] = '已锁定 · 旧编辑状态未提交'
              changed = true
              show_status("#{link['name']} 已保持锁定；原生锁定不会发布，请使用 LinkHub 恢复/修改后再发布。", 'info')
            end
          end
        end

        changed = sync_native_architecture_model_lock_state!(state, model) || changed
        changed = sync_native_space_lock_state!(state, model) || changed
        # 原生 Lock 菜单无法移除；除事务提交后的即时检查外，再用现有轻量监视器
        # 兜底一次，只看当前 selection，不递归扫描空间，因此不会放大大型项目开销。
        guard_space_internal_native_locks!(model, state: state)

        if changed
          save_state(state, model, write_manifest: false)
          refresh_dialog
        end
        @native_lock_last_full_check ||= {}
        @native_lock_last_full_check[model.object_id] = monotonic_time
        changed
      end
    rescue StandardError => e
      log_exception('同步原生锁定预览状态失败', e)
      false
    ensure
      @syncing_native_preview_state = false
    end

    def native_lock_cache_key_for_managed_root(entity, model = Sketchup.active_model)
      return nil unless entity && entity.valid? && model
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
      case kind
      when 'space_model'
        space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
        space_id.empty? ? nil : space_native_cache_key(model, space_id)
      when 'architecture_model'
        architecture_id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
        architecture_id.empty? ? nil : [model.object_id, edit_root_key_for_architecture_model(architecture_id)]
      when 'model', 'skp'
        discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
        %w[architecture landscape].include?(discipline) ? [model.object_id, discipline] : nil
      end
    rescue StandardError
      nil
    end

    # 0.55 秒常驻监视器只走这条内存/实体快照路径。没有变化时不 load_state、
    # 不读取网络锁文件，也不刷新 HtmlDialog；变化值故意不覆盖旧缓存，让后续
    # sync_native_preview_state 仍能判断从锁定到解锁（或反向）的真实转换。
    def native_lock_snapshot_changed?(model = Sketchup.active_model)
      return false unless model
      @native_lock_state_cache ||= {}
      Array(managed_root_index(model)[:all]).each do |entity|
        cache_key = native_lock_cache_key_for_managed_root(entity, model)
        next unless cache_key
        locked = entity_native_locked?(entity)
        previous = @native_lock_state_cache[cache_key]
        editing = entity.get_attribute(ENTITY_DICT, 'editing', false) ||
                  entity.get_attribute(ENTITY_DICT, 'preview_editing', false) ||
                  entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
        if previous.nil?
          if locked && !editing
            @native_lock_state_cache[cache_key] = true
            next
          end
          return true
        end
        return true if previous != locked
      rescue StandardError
        next
      end
      false
    rescue StandardError
      true
    end

    def start_native_lock_monitor
      return false unless workspace_connection_valid_cached?(Sketchup.active_model, max_age: 0.0)
      return true if @native_lock_monitor_timer
      @native_lock_monitor_timer = GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(NATIVE_LOCK_MONITOR_INTERVAL, true, label: 'native_lock_monitor') do
        begin
          model = Sketchup.active_model
          # 事务提交和 active_path 观察器已经负责即时安全检查；周期监视器只做低频
          # 兜底。连接有效性最多 30 秒触碰一次磁盘/NAS，且用户持续建模时不做
          # 全根快照扫描，避免每几百毫秒与 SketchUp 主线程争抢。
          unless model && workspace_connection_valid_cached?(model, max_age: 30.0)
            stop_native_lock_monitor
            next
          end
          next unless background_work_idle?(model, min_idle: 1.0)
          @native_lock_last_full_check ||= {}
          now = monotonic_time
          heartbeat_due = now - @native_lock_last_full_check[model.object_id].to_f >= NATIVE_LOCK_HEARTBEAT_INTERVAL
          if native_lock_snapshot_changed?(model) || heartbeat_due
            @native_lock_last_full_check[model.object_id] = now
            sync_native_preview_state(model)
          end
        rescue StandardError => e
          log_exception('原生锁定状态检查失败', e)
        end
      end
      true
    rescue StandardError => e
      log_exception('启动原生锁定状态检查失败', e)
      false
    end

    def dialog_visible?(dialog)
      dialog && dialog.visible?
    rescue StandardError
      false
    end

    def native_monitor_required?(model = Sketchup.active_model)
      return false unless workspace_connection_valid_cached?(model)
      state = load_state(model)
      # 原生右键“解锁”没有可靠的 ModelObserver 回调。旧逻辑在抽屉收起后
      # 停掉 0.25 秒锁定监视器，导致解锁动作无人发现；直到抽屉再次展开才
      # 重启监视并自动进入组件。工作区配置完成后持续保留这条轻量监视，
      # 每轮只读取少量根组件 locked? 状态，确保抽屉是否固定都不影响进入。
      return true if workspace_selection_configured?(state, model)
      return true if dialog_visible?(@dialog)
      return true if workspace_toolbar_open?(model)
      return true if (Array(state['space_models']) + Array(state['architecture_models'])).any? do |item|
        !item['edit_lock_token'].to_s.empty? || item['publish_pending'] || item['editing'] || space_edit_safe_paused?(item)
      end
      state['links'].any? do |key, link|
        link['preview_edit_active'] || link['preview_pending_publish'] || link['edit_session_active'] ||
          begin
            entity = native_edit_entity(key, model)
            entity && entity.valid? && !entity_native_locked?(entity)
          rescue StandardError
            false
          end
      end
    rescue StandardError
      false
    end

    def stop_native_lock_monitor
      return true unless @native_lock_monitor_timer
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_stop_timer(@native_lock_monitor_timer)
      @native_lock_monitor_timer = nil
      true
    rescue StandardError
      @native_lock_monitor_timer = nil
      false
    end

    def schedule_native_submit_prompt(key, model = Sketchup.active_model)
      @native_submit_prompt_scheduled ||= {}
      token = [model.object_id, key]
      return false if @native_submit_prompt_scheduled[token]
      timer_id = GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.12, false) do
        begin
          state = load_state(model)
          link = state.dig('links', key)
          entity = native_edit_entity(key, model)
          next unless link && link['preview_pending_publish']
          next unless entity && entity.valid? && entity_native_locked?(entity)

          refresh_dialog
          @dialog.bring_to_front if @dialog && @dialog.visible?
          flags = defined?(MB_YESNO) ? MB_YESNO : 4
          yes = defined?(IDYES) ? IDYES : 6
          if %w[architecture landscape].include?(key.to_s) && link['edit_session_active']
            result = UI.messagebox(
              "#{link['name']}是否发布修改？

是：立即写入共享#{link['name']}。
否：保留本地修改和协作占用，稍后可在顶部或卡片发布。",
              flags
            )
            if result == yes
              native_publish_and_lock(key)
            else
              link['commit_countdown_started_at'] = ''
              link['commit_countdown_until'] = 0.0
              link['status'] = "#{link['name']}本地修改待发布 · 协作占用保留"
              save_state(state, model, write_manifest: false)
              refresh_dialog
            end
            next
          end
          result = UI.messagebox(
            "#{link['name']}是否提交修改？\n\n是：进入提交确认，可在卡片点击“确认提交”。\n否：不提交，直接恢复普通更新状态，不重新载入模型。",
            flags
          )
          if result == yes
            arm_commit_countdown!(key, model)
          else
            cancel_preview_without_reload!(key, model, '已载入')
          end
        rescue StandardError => e
          log_exception('显示提交提示失败', e)
        ensure
          @native_submit_prompt_scheduled.delete(token)
        end
      end
      @native_submit_prompt_scheduled[token] = timer_id
      true
    rescue StandardError => e
      @native_submit_prompt_scheduled.delete(token) if defined?(token)
      log_exception('安排提交提示失败', e)
      false
    end

    def stored_axes_for_instance(instance, link)
      raw = instance && instance.valid? ? instance.get_attribute(ENTITY_DICT, 'source_axes_json', '').to_s : ''
      if !raw.empty?
        parsed = JSON.parse(raw) rescue nil
        array = transformation_array(parsed)
        return array if array.length == 16
      end
      transformation_array(link['last_source_axes'])
    rescue StandardError
      transformation_array(link['last_source_axes'])
    end

    # SketchUp 2026 起会对不可逆变换严格抛出 ArgumentError。这里在调用
    # Transformation#inverse 前先检查三轴行列式，并把零缩放等异常转换成
    # 可读提示；镜像变换的行列式为负但仍可逆，因此不会被误拦截。
    def safe_inverse_transformation(transform, context = '坐标变换')
      values = transform.respond_to?(:to_a) ? Array(transform.to_a).map(&:to_f) : []
      raise "#{context}数据不完整。" unless values.length == 16

      determinant =
        values[0] * (values[5] * values[10] - values[9] * values[6]) -
        values[4] * (values[1] * values[10] - values[9] * values[2]) +
        values[8] * (values[1] * values[6] - values[5] * values[2])
      unless determinant.finite? && determinant.abs > 1.0e-12
        raise "#{context}不可逆，可能包含零尺寸缩放；请恢复有效尺寸后重试。"
      end
      transform.inverse
    rescue ArgumentError => e
      raise "#{context}不可逆：#{e.message}"
    end

    def store_position_state!(instance, link, source_axes = nil)
      transform = transformation_array(instance.transformation)
      link['last_instance_transform'] = transform if transform.length == 16
      if source_axes && transformation_array(source_axes).length == 16
        axes = transformation_array(source_axes)
        link['last_source_axes'] = axes
        instance.set_attribute(ENTITY_DICT, 'source_axes_json', JSON.generate(axes))
      end
      instance.set_attribute(ENTITY_DICT, 'last_transform_json', JSON.generate(transform)) if transform.length == 16
      true
    rescue StandardError => e
      log_exception('保存联动位置状态失败', e)
      false
    end

    # SketchUp 把整个 SKP 作为组件读取时，会使用源模型保存的坐标轴。
    # 如果源文件改变了坐标轴，组件定义内部坐标会变化，即使外层实例矩阵不变，几何也会错位。
    # 通过源模型保存时记录的 axes transformation，按 Tnew = Told * Aold^-1 * Anew
    # 修正外层实例，保持实体在协调模型中的世界坐标不变。
    def preserve_link_world_position!(instance, link, old_transform, old_axes, new_axes)
      base = old_transform || transformation_from_array(link['last_instance_transform']) || Geom::Transformation.new
      instance.transformation = base
      adjusted = false
      if link['position_lock_enabled'] && old_axes && new_axes
        old_frame = transformation_from_array(old_axes)
        new_frame = transformation_from_array(new_axes)
        if old_frame && new_frame && !(soft_rigid_frame?(old_frame) && soft_rigid_frame?(new_frame))
          # v0.13.7.7：坐标轴记录带缩放/斜切时不做自动补偿，否则整个模型会被压扁或拉伸。
          log('联动模型坐标轴记录不是刚体（含缩放/斜切），已跳过自动坐标补偿，保持原位置。')
        elsif old_frame && new_frame
          old_inverse = safe_inverse_transformation(old_frame, '旧模型坐标轴变换')
          instance.transformation = base * old_inverse * new_frame
          adjusted = transformations_different?(old_axes, new_axes)
        end
      end
      store_position_state!(instance, link, new_axes || old_axes)
      adjusted
    rescue StandardError => e
      log_exception('保持联动模型世界坐标失败', e)
      instance.transformation = base if base && instance && instance.valid?
      store_position_state!(instance, link, new_axes || old_axes) if instance && instance.valid?
      false
    end

    # -------------------------
    # Absolute world-coordinate wrappers
    # -------------------------

    def identity_transformation
      Geom::Transformation.new
    end

    def identity_transformation_array
      transformation_array(identity_transformation)
    end

    def world_wrapper_definition?(definition)
      return false unless definition && definition.valid?
      definition.get_attribute(ENTITY_DICT, 'world_wrapper_schema', 0).to_i.positive?
    rescue StandardError
      false
    end

    def world_wrapper_instance?(instance)
      instance && instance.valid? && instance.is_a?(Sketchup::ComponentInstance) && world_wrapper_definition?(instance.definition)
    rescue StandardError
      false
    end

    def world_source_child(instance)
      return nil unless world_wrapper_instance?(instance)
      children = instance.definition.entities.grep(Sketchup::ComponentInstance)
      children.find do |child|
        child.get_attribute(ENTITY_DICT, 'world_source_role', '').to_s == 'material' ||
          child.get_attribute(ENTITY_DICT, 'world_source_child', false)
      end || children.first
    rescue StandardError
      nil
    end

    def set_world_source_child_attributes!(child, key, source_path)
      child.set_attribute(ENTITY_DICT, 'world_source_child', true)
      child.set_attribute(ENTITY_DICT, 'world_source_role', 'material')
      child.set_attribute(ENTITY_DICT, 'world_source_discipline', key.to_s)
      child.set_attribute(ENTITY_DICT, 'world_source_path', source_path.to_s)
      child.locked = false if child.respond_to?(:locked=)
      child
    rescue StandardError
      child
    end

    def collect_definition_tree(definition, seen = {}, result = [])
      return result unless definition && definition.valid?
      id = definition.object_id
      return result if seen[id]
      seen[id] = true
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
        collect_definition_tree(entity.definition, seen, result)
      rescue StandardError
        next
      end
      result << definition
      result
    rescue StandardError
      result
    end

    # The source model may use a moved/rotated display axis. When SketchUp reads the whole SKP as
    # a component definition, its definition coordinates are relative to that source axis frame.
    # We never move the outer linked instance. Instead, the source frame is applied once inside an
    # identity wrapper, equivalent to copying the source model and using Paste in Place at world 0,0,0.
    def absolute_world_frame_for_asset(asset, source_path, link)
      if asset[:type].to_s == 'reference'
        return {
          transformation: identity_transformation,
          axes: identity_transformation_array,
          source: 'reference-package',
          metadata_ready: true,
          warning: ''
        }
      end

      metadata = read_coordinate_metadata(source_path)
      axes = metadata ? transformation_array(metadata['axes']) : []
      source = 'sidecar'
      if axes.length != 16
        axes = transformation_array(link['last_source_axes'])
        source = 'stored-fallback'
      end
      if axes.length != 16
        axes = identity_transformation_array
        source = 'identity-fallback'
      end
      transformation = transformation_from_array(axes) || identity_transformation
      warning = source == 'identity-fallback' ? '源模型尚未建立绝对世界轴元数据；已暂按世界原点载入，请通过 LinkHub 打开源模型并保存一次' : ''
      {
        transformation: transformation,
        axes: axes,
        source: source,
        metadata_ready: source != 'identity-fallback',
        warning: warning
      }
    rescue StandardError => e
      log_exception('读取绝对世界轴失败', e)
      {
        transformation: identity_transformation,
        axes: identity_transformation_array,
        source: 'identity-error',
        metadata_ready: false,
        warning: '绝对世界轴读取失败，已暂按世界原点载入'
      }
    end

    def create_world_wrapper!(key, source_definition, world_frame, source_path, model = Sketchup.active_model)
      wrapper = model.definitions.add("LH_WORLD_#{key}_#{SecureRandom.hex(6)}")
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_schema', WORLD_WRAPPER_SCHEMA)
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_discipline', key.to_s)
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_source', source_path.to_s)
      child = wrapper.entities.add_instance(source_definition, world_frame)
      soft_invalidate_definition_bounds!(wrapper)
      set_world_source_child_attributes!(child, key, source_path)
      outer = model.entities.add_instance(wrapper, identity_transformation)
      [wrapper, child, outer]
    end

    def replace_world_source_child!(outer, source_definition, world_frame, key, source_path)
      wrapper = outer.definition
      old_children = wrapper.entities.grep(Sketchup::ComponentInstance)
      old_children.each do |child|
        child.locked = false if child.respond_to?(:locked=)
        child.erase! if child.valid?
      rescue StandardError
        next
      end
      child = wrapper.entities.add_instance(source_definition, world_frame)
      soft_invalidate_definition_bounds!(wrapper)
      set_world_source_child_attributes!(child, key, source_path)
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_schema', WORLD_WRAPPER_SCHEMA)
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_discipline', key.to_s)
      wrapper.set_attribute(ENTITY_DICT, 'world_wrapper_source', source_path.to_s)
      child
    end

    def reload_world_source_definition!(outer, path, model, key, source_path)
      child = world_source_child(outer)
      if child && child.valid? && child.definition.respond_to?(:reload) && child.definition.instances.length <= 1
        begin
          definition = child.definition
          result = definition.reload(path)
          raise 'SketchUp 未能重载绝对世界源定义。' if result == false
          soft_invalidate_definition_bounds!(definition)
          definition.set_attribute(ENTITY_DICT, 'loaded_from_newer_version', false)
          return [definition, child]
        rescue StandardError => error
          raise unless newer_model_version_error?(error)
        end
      end

      loaded = load_definition_compat(model.definitions, path)
      raise '模型定义载入失败。' unless loaded
      child = replace_world_source_child!(outer, loaded, identity_transformation, key, source_path)
      [loaded, child]
    end

    def managed_model_instances_for(key, model = Sketchup.active_model)
      managed_model_entities(model, discipline: key).select do |entity|
        next false unless entity.valid? && entity.is_a?(Sketchup::ComponentInstance)
        %w[model skp].include?(entity.get_attribute(ENTITY_DICT, 'kind', '').to_s)
      end
    rescue StandardError
      []
    end

    def consolidate_managed_model_instances!(key, keep, model = Sketchup.active_model)
      removed = 0
      managed_model_instances_for(key, model).each do |entity|
        next if keep && entity == keep
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase! if entity.valid?
        removed += 1
      rescue StandardError
        next
      end
      removed
    end

    # -------------------------
    # Project state and migration
    # -------------------------

    def default_link(key)
      info = DISCIPLINES.fetch(key)
      {
        'discipline' => key,
        'name' => info['name'],
        'code' => info['code'],
        'folder_name' => info['folder'],
        'model_tag' => info['model_tag'],
        'model_path' => '',
        'enabled' => true,
        # 启用/禁用语义：禁用=断开当前模型里的该专业联动实例；配置路径保留，启用时重新载入。
        'disconnected_at' => '',
        'disconnect_removed_count' => 0,
        'mode' => 'full',
        'auto_update' => false,
        'collab_manifest_path' => '',
        'collab_project_manifest_path' => '',
        'collab_full_path' => '',
        'collab_cache_version' => 0,
        'collab_revision_id' => '',
        'collab_last_publish_at' => '',
        'collab_full_signature' => '',
        'collab_last_published_by' => '',
        'collab_last_publish_host' => '',
        # 建筑工作文件完成首次协同切换后，建筑也使用统一受管根组件；副本由用户自选。
        # 建筑与景观首次发布后都切换为统一受管根组件，后续共享同一套锁定/修改/发布逻辑。
        'architecture_collab_managed' => false,
        'landscape_collab_managed' => false,
