    def default_state(model = Sketchup.active_model)
      {
        'schema' => PROJECT_SCHEMA,
        'safe_mode' => true,
        'project_name' => model.title.to_s.empty? ? '未命名项目' : model.title.to_s,
        # 协同缓存根目录可以独立于当前 SKP 所在目录。
        # 各专业工作模型可保存在本机任意磁盘，共享目录只存 协同.json 与 _SU_LinkHub协同 缓存。
        'collab_project_dir' => '',
        'collab_project_json' => '',
        'host_discipline' => 'coordination',
        # 必须在连接有效的协同.json后由用户明确选择一次建筑/室内/景观。
        # 不再把默认 coordination 当作已经配置完成。
        'workspace_configured' => false,
        'auto_discover_dependencies' => true,
        'strip_embedded_links' => true,
        # 建筑从单一 FULL 模型升级为可分组的多建筑模型集合。
        'architecture_models' => [],
        'architecture_groups' => [],
        'architecture_layout_revision' => '',
        'architecture_layout_updated_at' => '',
        'architecture_layout_updated_by' => '',
        'architecture_layout_updated_host' => '',
        'architecture_next_number' => 1,
        'architecture_editing_id' => '',
        'architecture_collection_hidden' => false,
        'architecture_collection_visibility_snapshot' => {},
        'architecture_legacy_migrated' => false,
        # 专业板块展开/收纳属于当前文件本机偏好；首次按当前工作区自动展开。
        'professional_section_collapsed' => {},
        # 软装与硬装不再各占一个单模型，而是共享同一组按空间拆分的 SKP。
        'space_models' => [],
        # 仅用于浏览与管理的逻辑分组；不合并、不打散、不改写任何空间 SKP。
        'space_groups' => [],
        # 分组布局有独立共享 revision；折叠/显隐仍是每台电脑的本地偏好。
        'space_layout_revision' => '',
        'space_layout_updated_at' => '',
        'space_layout_updated_by' => '',
        'space_layout_updated_host' => '',
        'space_next_number' => 1,
        'space_editing_id' => '',
        # 强制解锁只用于从历史/旧快照中取物。它不取得协作锁、不允许发布，
        # 退出组件或再次点击强制解锁时必须恢复进入前定义快照。
        'space_force_recovery_id' => '',
        # v0.13.6.20：硬装与软装是两个独立工作区，总眼睛/恢复快照也必须独立。
        # 旧字段继续保留为硬装兼容镜像，避免历史项目升级后丢失显隐状态。
        'space_collection_hidden' => false,
        'space_collection_visibility_snapshot' => {},
        'space_collection_hidden_by_key' => {
          SPACE_COLLECTION_KEY => false,
          SOFT_SPACE_COLLECTION_KEY => false
        },
        'space_collection_visibility_snapshot_by_key' => {
          SPACE_COLLECTION_KEY => {},
          SOFT_SPACE_COLLECTION_KEY => {}
        },
        # 空间编辑眼睛采用“最后一次选择”作为下一次进入任意空间的默认值。
        # false=进入时隐藏其他受管参考；true=进入时按进入前显隐快照显示其他参考。
        'space_edit_references_visible_preference' => false,
        # 视口眼睛在非空间编辑状态下，只隐藏“当前工作区以外”的受管根模型。
        # 保存进入专注显示前的根实体显隐，确保再次点击时能逐一恢复，而不是一律强制显示。
        'workspace_references_visible' => true,
        'workspace_reference_visibility_snapshot' => {},
        'workspace_reference_focus_owner' => '',
        # 默认以家具代理显示；空间硬装与结构始终使用同一个空间文件。
        'space_display_mode' => 'proxy',
        # 修改空间期间的临时显示模式；不覆盖退出后的全局代/真偏好。
        'space_edit_display_mode' => '',
        # 建筑/景观大项目中可只把一个选中空间临时切为真模型；全局偏好仍保持代理。
        'space_preview_full_id' => '',
        'space_legacy_migrated' => false,
        'links' => DISCIPLINES.keys.each_with_object({}) { |key, memo| memo[key] = default_link(key) }
      }
    end

    def migrate_link!(link, key)
      defaults = default_link(key)
      defaults.each { |field, value| link[field] = value unless link.key?(field) }

      # v0.1 有“完整路径”和“代理路径”。v0.2 只保留一个模型源路径。
      if link['model_path'].to_s.empty?
        old_full = link['full_path'].to_s
        old_proxy = link['proxy_path'].to_s
        link['model_path'] = old_full.empty? ? old_proxy : old_full
      end

      info = DISCIPLINES.fetch(key)
      link['name'] = info['name']
      link['code'] = info['code']
      link['folder_name'] = info['folder']
      link['model_tag'] = info['model_tag']
      link['enabled'] = link.key?('enabled') ? !!link['enabled'] : true
      link['disconnected_at'] = link['disconnected_at'].to_s
      link['disconnect_removed_count'] = link['disconnect_removed_count'].to_i
      link['last_mtimes'] ||= {}
      link['last_sizes'] ||= {}
      link['last_signatures'] ||= {}
      link['embedded_dependencies'] = Array(link['embedded_dependencies'])
      link['embedded_link_count'] = link['embedded_dependencies'].length if link['embedded_link_count'].to_i <= 0
      link['last_stripped_reference_count'] = link['last_stripped_reference_count'].to_i
      link['last_blocked_backflow_count'] = link['last_blocked_backflow_count'].to_i
      link['last_blocked_backflow'] = Array(link['last_blocked_backflow']).map(&:to_s)
      link['edit_session_active'] = !!link['edit_session_active']
      link['edit_lock_token'] = link['edit_lock_token'].to_s
      link['edit_actor_role'] = WORKSPACE_ROLES.include?(link['edit_actor_role'].to_s) ? link['edit_actor_role'].to_s : ''
      link['edit_lock_path'] = link['edit_lock_path'].to_s
      link['edit_source_signature'] = link['edit_source_signature'].to_s
      link['edit_started_at'] = link['edit_started_at'].to_s
      link['edit_owner'] = link['edit_owner'].to_s
      link['edit_host'] = link['edit_host'].to_s
      link['edit_pid'] = link['edit_pid'].to_i
      link['edit_previous_mode'] = %w[proxy full].include?(link['edit_previous_mode'].to_s) ? link['edit_previous_mode'].to_s : 'proxy'
      link['edit_previous_auto_update'] = false
      link['auto_update'] = false
      link['edit_workflow'] = %w[native_inline native_preview architecture_managed landscape_managed native_commit external_source legacy_inline].include?(link['edit_workflow'].to_s) ? link['edit_workflow'].to_s : 'native_inline'
      link['edit_safe_paused'] = !!link['edit_safe_paused']
      link['edit_safe_paused_at'] = link['edit_safe_paused_at'].to_s
      link['edit_safe_pause_reason'] = link['edit_safe_pause_reason'].to_s
      link['source_newer_version'] = !!link['source_newer_version']
      link['sync_strategy'] = %w[direct mirror].include?(link['sync_strategy'].to_s) ? link['sync_strategy'].to_s : 'direct'
      link['prefer_reference_package'] = link['prefer_reference_package'].nil? ? true : !!link['prefer_reference_package']
      link['ignore_section_planes'] = link['ignore_section_planes'].nil? ? true : !!link['ignore_section_planes']
      link['display_filter_enabled'] = !!link['display_filter_enabled']
      link['display_selected_tags'] = Array(link['display_selected_tags']).map(&:to_s).map(&:strip).reject(&:empty?).uniq
      link['display_tag_catalog'] = Array(link['display_tag_catalog']).map(&:to_s).map(&:strip).reject(&:empty?).uniq.sort
      link['system_hidden'] = !!link['system_hidden']
      link['visibility_mode'] = 'system_dual'
      link['visibility_snapshot'] = link['visibility_snapshot'].is_a?(Hash) ? link['visibility_snapshot'] : {}
      link['visibility_snapshot'] = link['visibility_snapshot'].each_with_object({}) { |(name, value), memo| memo[name.to_s] = !!value }
      link['visibility_entity_snapshot'] = link['visibility_entity_snapshot'].is_a?(Hash) ? link['visibility_entity_snapshot'] : {}
      link['visibility_entity_snapshot'] = link['visibility_entity_snapshot'].each_with_object({}) { |(name, value), memo| memo[name.to_s] = !!value }
      link['visibility_last_changed'] = link['visibility_last_changed'].to_s
      link['last_load_ms'] = link['last_load_ms'].to_i
      link['last_asset_type'] = link['last_asset_type'].to_s
      link['last_section_plane_count'] = link['last_section_plane_count'].to_i
      link['position_lock_enabled'] = link['position_lock_enabled'].nil? ? true : !!link['position_lock_enabled']
      link['last_source_axes'] = Array(link['last_source_axes']).map(&:to_f)
      link['last_source_axes'] = [] unless link['last_source_axes'].length == 16
      link['last_instance_transform'] = Array(link['last_instance_transform']).map(&:to_f)
      link['last_instance_transform'] = [] unless link['last_instance_transform'].length == 16
      link['coordinate_tracking_requested'] = !!link['coordinate_tracking_requested']
      link['absolute_world_enabled'] = link['absolute_world_enabled'].nil? ? true : !!link['absolute_world_enabled']
      link['world_wrapper_schema'] = link['world_wrapper_schema'].to_i
      link['world_wrapper_schema'] = WORLD_WRAPPER_SCHEMA if link['world_wrapper_schema'] <= 0
      link['last_world_frame_source'] = link['last_world_frame_source'].to_s
      link['native_publish_path'] = link['native_publish_path'].to_s
      link['native_original_source_path'] = link['native_original_source_path'].to_s
      link['native_last_publish_at'] = link['native_last_publish_at'].to_s
      link['native_last_publish_ms'] = link['native_last_publish_ms'].to_i
      link['last_commit_result'] = link['last_commit_result'].to_s
      link['last_commit_path'] = link['last_commit_path'].to_s
      link['last_commit_backup_path'] = link['last_commit_backup_path'].to_s
      link['last_commit_verified'] = !!link['last_commit_verified']
      link['preview_edit_active'] = !!link['preview_edit_active']
      link['preview_pending_publish'] = !!link['preview_pending_publish']
      link['preview_base_signature'] = link['preview_base_signature'].to_s
      link['preview_source_path'] = link['preview_source_path'].to_s
      link['preview_started_at'] = link['preview_started_at'].to_s
      link['preview_relocked_at'] = link['preview_relocked_at'].to_s
      link['preview_conflict'] = !!link['preview_conflict']
      link['preview_conflict_detail'] = link['preview_conflict_detail'].to_s
      # v0.9.35 已取消提交倒计时，旧模型残留的截止时间不能继续禁用按钮。
      link['commit_countdown_started_at'] = ''
      link['commit_countdown_until'] = 0
      link['collab_manifest_path'] = link['collab_manifest_path'].to_s
      link['collab_project_manifest_path'] = link['collab_project_manifest_path'].to_s
      link['collab_full_path'] = link['collab_full_path'].to_s
      link['collab_cache_version'] = link['collab_cache_version'].to_i
      link['collab_revision_id'] = link['collab_revision_id'].to_s
      link['collab_last_publish_at'] = link['collab_last_publish_at'].to_s
      link['collab_full_signature'] = link['collab_full_signature'].to_s
      link['collab_last_published_by'] = link['collab_last_published_by'].to_s
      link['collab_last_publish_host'] = link['collab_last_publish_host'].to_s
      link['architecture_collab_managed'] = !!link['architecture_collab_managed']
      link['landscape_collab_managed'] = !!link['landscape_collab_managed']
      link['architecture_last_backup_path'] = link['architecture_last_backup_path'].to_s
      link['architecture_last_backup_at'] = link['architecture_last_backup_at'].to_s
      link['native_work_entity_pid'] = link['native_work_entity_pid'].to_i
      link['native_work_entity_definition_guid'] = link['native_work_entity_definition_guid'].to_s
      link['native_work_entity_name'] = link['native_work_entity_name'].to_s
      link['native_work_entity_assigned_at'] = link['native_work_entity_assigned_at'].to_s
      link['auto_update'] = false
      link['mode'] = 'full'
      link['edit_previous_mode'] = 'full' unless link['edit_session_active']
      link.delete('full_path')
      link.delete('proxy_path')
      link.delete('tag_name')
      link
    end

    # v0.13.6.40 PERFORMANCE PASS 2：高频只读链路（例如模型每次事务提交时
    # 判断“当前正在编辑哪个空间”）不能为了读取两个字段就 deep_dup 整份项目状态。
    # 这里返回内部缓存的只读引用；仅允许明确不会修改 state 的调用点使用。
    # 缓存与模型属性原始 JSON / 模型 token 任一不一致时立即放弃并回退 load_state。
    def cached_project_state_readonly(model = Sketchup.active_model)
      return nil unless model
      @project_state_cache ||= {}
      cached = @project_state_cache[model.object_id]
      return nil unless cached && cached[:state].is_a?(Hash)
      return nil unless cached[:model_token].to_s == runtime_model_token(model).to_s
      raw = model.get_attribute(DICT, PROJECT_KEY, '')
      raw_text = raw.is_a?(String) ? raw : raw.to_s
      return nil unless cached[:raw].to_s == raw_text
      cached[:state]
    rescue StandardError
      nil
    end

    # SelectionObserver / mouse hot path only consumes display hints. The cache is written by
    # every load_state/save_state and discarded with the model runtime token, so reading the
    # complete project_json attribute again for every click adds latency without improving the
    # authority of the eventual edit/publish action. Those actions still use load_state and the
    # shared-file preflight checks.
    def cached_project_state_hot_readonly(model = Sketchup.active_model)
      return nil unless model
      cached = (@project_state_cache || {})[model.object_id]
      return nil unless cached && cached[:state].is_a?(Hash)
      return nil unless cached[:model_token].to_s == runtime_model_token(model).to_s
      cached[:state]
    rescue StandardError
      nil
    end

    def load_state(model = Sketchup.active_model)
      raw = model.get_attribute(DICT, PROJECT_KEY, '')
      raw_text = raw.is_a?(String) ? raw : raw.to_s
      @project_state_cache ||= {}
      cache_key = model.object_id
      model_token = runtime_model_token(model)
      cached = @project_state_cache[cache_key]
      if cached && cached[:raw].to_s == raw_text && cached[:model_token].to_s == model_token
        return deep_dup_runtime_value(cached[:state])
      end

      state = default_state(model)
      saved_schema = 0
      if raw.is_a?(String) && !raw.empty?
        begin
          saved = JSON.parse(raw)
          saved_schema = saved['schema'].to_i
          state['project_name'] = saved['project_name'] if saved['project_name']
          state['collab_project_dir'] = saved['collab_project_dir'].to_s if saved.key?('collab_project_dir')
          state['collab_project_json'] = saved['collab_project_json'].to_s if saved.key?('collab_project_json')
          state['host_discipline'] = saved['host_discipline'].to_s if saved['host_discipline']
          if saved.key?('workspace_configured')
            state['workspace_configured'] = !!saved['workspace_configured']
          elsif WORKSPACE_ROLES.include?(state['host_discipline'].to_s)
            # 旧项目已经明确保存为某一专业时直接迁移，不强迫每次升级重选。
            state['workspace_configured'] = true
          end
          state['auto_discover_dependencies'] = saved['auto_discover_dependencies'] unless saved['auto_discover_dependencies'].nil?
          state['strip_embedded_links'] = saved['strip_embedded_links'] unless saved['strip_embedded_links'].nil?
          state['architecture_models'] = saved['architecture_models'] if saved['architecture_models'].is_a?(Array)
          state['architecture_groups'] = saved['architecture_groups'] if saved['architecture_groups'].is_a?(Array)
          state['architecture_layout_revision'] = saved['architecture_layout_revision'].to_s if saved.key?('architecture_layout_revision')
          state['architecture_layout_updated_at'] = saved['architecture_layout_updated_at'].to_s if saved.key?('architecture_layout_updated_at')
          state['architecture_layout_updated_by'] = saved['architecture_layout_updated_by'].to_s if saved.key?('architecture_layout_updated_by')
          state['architecture_layout_updated_host'] = saved['architecture_layout_updated_host'].to_s if saved.key?('architecture_layout_updated_host')
          state['architecture_next_number'] = saved['architecture_next_number'].to_i if saved.key?('architecture_next_number')
          state['architecture_editing_id'] = saved['architecture_editing_id'].to_s if saved.key?('architecture_editing_id')
          state['architecture_collection_hidden'] = !!saved['architecture_collection_hidden'] if saved.key?('architecture_collection_hidden')
          if saved['architecture_collection_visibility_snapshot'].is_a?(Hash)
            state['architecture_collection_visibility_snapshot'] = saved['architecture_collection_visibility_snapshot']
          end
          state['architecture_legacy_migrated'] = !!saved['architecture_legacy_migrated'] if saved.key?('architecture_legacy_migrated')
          state['professional_section_collapsed'] = saved['professional_section_collapsed'] if saved['professional_section_collapsed'].is_a?(Hash)
          state['space_models'] = saved['space_models'] if saved['space_models'].is_a?(Array)
          # v0.9.82 首次加入空间分组时漏读了模型属性中的 space_groups，
          # 导致成组后下一次状态刷新只保留 group_id 排序，却丢失组名和组卡片。
          # 分组属于项目清单结构，必须与 space_models 一起从工作 SU 恢复。
          state['space_groups'] = saved['space_groups'] if saved['space_groups'].is_a?(Array)
          state['space_layout_revision'] = saved['space_layout_revision'].to_s if saved.key?('space_layout_revision')
          state['space_layout_updated_at'] = saved['space_layout_updated_at'].to_s if saved.key?('space_layout_updated_at')
          state['space_layout_updated_by'] = saved['space_layout_updated_by'].to_s if saved.key?('space_layout_updated_by')
          state['space_layout_updated_host'] = saved['space_layout_updated_host'].to_s if saved.key?('space_layout_updated_host')
          state['space_next_number'] = saved['space_next_number'].to_i if saved.key?('space_next_number')
          state['space_editing_id'] = saved['space_editing_id'].to_s if saved.key?('space_editing_id')
          # 空间集合总显隐必须随项目状态一同恢复。v0.7.6 虽然保存了这两个字段，
          # 但 load_state 漏读，导致每次刷新都回到“未隐藏”，眼睛无法切回显示。
          state['space_collection_hidden'] = !!saved['space_collection_hidden'] if saved.key?('space_collection_hidden')
          if saved.key?('space_edit_references_visible_preference')
            state['space_edit_references_visible_preference'] = !!saved['space_edit_references_visible_preference']
          end
          if saved['space_collection_visibility_snapshot'].is_a?(Hash)
            state['space_collection_visibility_snapshot'] = saved['space_collection_visibility_snapshot']
          end
          if saved['space_collection_hidden_by_key'].is_a?(Hash)
            state['space_collection_hidden_by_key'] = saved['space_collection_hidden_by_key']
          end
          if saved['space_collection_visibility_snapshot_by_key'].is_a?(Hash)
            state['space_collection_visibility_snapshot_by_key'] = saved['space_collection_visibility_snapshot_by_key']
          end
          state['workspace_references_visible'] = !!saved['workspace_references_visible'] if saved.key?('workspace_references_visible')
          if saved['workspace_reference_visibility_snapshot'].is_a?(Hash)
            state['workspace_reference_visibility_snapshot'] = saved['workspace_reference_visibility_snapshot']
          end
          state['workspace_reference_focus_owner'] = saved['workspace_reference_focus_owner'].to_s if saved.key?('workspace_reference_focus_owner')
          state['space_display_mode'] = saved['space_display_mode'].to_s if saved.key?('space_display_mode')
          state['space_edit_display_mode'] = saved['space_edit_display_mode'].to_s if saved.key?('space_edit_display_mode')
          state['space_preview_full_id'] = saved['space_preview_full_id'].to_s if saved.key?('space_preview_full_id')
          state['space_legacy_migrated'] = !!saved['space_legacy_migrated'] unless saved['space_legacy_migrated'].nil?
          saved_links = saved['links'].is_a?(Hash) ? saved['links'] : {}
          DISCIPLINES.keys.each do |key|
            state['links'][key].merge!(saved_links[key]) if saved_links[key].is_a?(Hash)
            migrate_link!(state['links'][key], key)
          end
        rescue JSON::ParserError
          UI.messagebox('SU LinkHub 项目配置损坏，已使用默认配置。')
        end
      end
      # v0.3.2 首次升级进入安全模式，避免旧版保存的实时更新在打开模型后立即执行重载。
      if saved_schema.positive? && saved_schema < 4
        state['links'].each_value { |link| link['auto_update'] = false }
        state['safe_mode'] = true
      end
      # 专业模型始终使用有材质源模型或 FULL 协同缓存。
      state['links'].each_value do |link|
        link['auto_update'] = false
        link['edit_previous_auto_update'] = false
        link['mode'] = 'full'
        link['edit_previous_mode'] = 'full' unless link['edit_session_active']
      end
      # v0.5.2 起停止把组件定义覆盖回源 SKP；旧版仍在进行中的内嵌编辑会话标记为恢复模式。
      if saved_schema.positive? && saved_schema < 10
        state['links'].each_value do |link|
          link['edit_workflow'] = 'legacy_inline' if link['edit_session_active']
        end
      end
      state['host_discipline'] = SOFT_SPACE_COLLECTION_KEY if state['host_discipline'].to_s == 'furniture'
      state['host_discipline'] = 'coordination' unless DISCIPLINES.key?(state['host_discipline'].to_s) || state['host_discipline'].to_s == 'coordination'
      state['workspace_configured'] = !!state['workspace_configured'] && WORKSPACE_ROLES.include?(state['host_discipline'].to_s)
      normalize_architecture_models_state!(state, model)
      normalize_space_models_state!(state, model)
      state['professional_section_collapsed'] = state['professional_section_collapsed'].is_a?(Hash) ? state['professional_section_collapsed'].each_with_object({}) { |(key, value), memo| memo[key.to_s] = !!value } : {}
      state['collab_project_dir'] = state['collab_project_dir'].to_s
      state['collab_project_json'] = state['collab_project_json'].to_s
      state['space_layout_revision'] = state['space_layout_revision'].to_s
      state['space_layout_updated_at'] = state['space_layout_updated_at'].to_s
      state['space_layout_updated_by'] = state['space_layout_updated_by'].to_s
      state['space_layout_updated_host'] = state['space_layout_updated_host'].to_s
      state['space_edit_references_visible_preference'] = !!state['space_edit_references_visible_preference']
      state['workspace_references_visible'] = state['workspace_references_visible'].nil? ? true : !!state['workspace_references_visible']
      snapshot = state['workspace_reference_visibility_snapshot']
      state['workspace_reference_visibility_snapshot'] = snapshot.is_a?(Hash) ? snapshot.each_with_object({}) { |(id, hidden), memo| memo[id.to_s] = !!hidden } : {}
      state['workspace_reference_focus_owner'] = state['workspace_reference_focus_owner'].to_s
      state['schema'] = PROJECT_SCHEMA
      @project_state_cache[cache_key] = {
        raw: raw_text,
        model_token: model_token,
        state: deep_dup_runtime_value(state)
      }
      deep_dup_runtime_value(state)
    end

    # 项目状态只包含 JSON 可表达的 Hash / Array / String / 数值 / 布尔值。
    # 每次从缓存返回独立副本，调用方仍可像旧版一样就地修改，再明确 save_state；
    # 这样既省掉反复 JSON.parse/normalize，又不会让未保存修改泄漏到其他入口。
    def deep_dup_runtime_value(value)
      case value
      when Hash
        value.each_with_object({}) { |(key, item), memo| memo[key] = deep_dup_runtime_value(item) }
      when Array
        value.map { |item| deep_dup_runtime_value(item) }
      when String
        value.dup
      else
        value
      end
    rescue StandardError
      value
    end

    def save_state(state, model = Sketchup.active_model, write_manifest: true)
      state['schema'] = PROJECT_SCHEMA
      payload = JSON.generate(state)
      # set_attribute 即使写入相同内容，也可能在 SketchUp 撤回栈中形成一次事务。
      # 所有状态保存先做字节级比较，杜绝界面刷新和安全检查制造空 Undo 记录。
      current = model.get_attribute(DICT, PROJECT_KEY, '').to_s
      model.set_attribute(DICT, PROJECT_KEY, payload) unless current == payload
      @project_state_cache ||= {}
      @project_state_cache[model.object_id] = {
        raw: payload,
        model_token: runtime_model_token(model),
        state: deep_dup_runtime_value(state)
      }
      # 协作锁、签出状态、心跳等并不会改变模型之间的链接关系，
      # 因此这些高频状态更新不再反复读写网络盘上的 sidecar 清单。
      write_sidecar_manifest(state, model) if write_manifest
      true
    end

    # -------------------------
    # 软装＋硬装：按空间拆分的模型集合
    # -------------------------

    def default_space_model(number = 1, name = '未命名空间', stored_path = '')
      {
        'id' => SecureRandom.uuid,
        'number' => number.to_i.positive? ? number.to_i : 1,
        'name' => name.to_s.strip.empty? ? '未命名空间' : name.to_s.strip,
        # 硬装/软装共享同一份空间清单文件，但每个空间拥有明确专业身份。
        # 旧记录没有该字段时按硬装迁移，避免升级后把历史室内模型误归到软装。
        'collection_key' => SPACE_COLLECTION_KEY,
        'model_path' => stored_path.to_s,
        'group_id' => '',
        'group_order' => 0,
        'proxy_path' => '',
        'proxy_signature' => '',
        'proxy_published_at' => '',
        'legacy_key' => '',
        'status' => '未载入',
        'last_update' => '',
        'last_publish_at' => '',
        'last_signature' => '',
        'source_revision' => '',
        'editing' => false,
        'edit_lock_token' => '',
        'edit_actor_role' => '',
        'edit_lock_owner' => '',
        'edit_lock_host' => '',
        'edit_lock_started_at' => '',
        # 当前空间记录最近一次眼睛状态；全局 preference 决定下次进入任意空间的默认值。
        'edit_references_visible' => false,
        'isolation_snapshot' => {},
        'isolation_lock_snapshot' => {},
        'publish_pending' => false,
        'edit_safe_paused' => false,
        'edit_safe_paused_at' => '',
        'edit_safe_pause_reason' => '',
        'force_recovery_active' => false,
        'force_recovery_snapshot_path' => '',
        'force_recovery_snapshot_signature' => '',
        'force_recovery_started_at' => '',
        'force_recovery_original_locked' => true,
        'force_recovery_original_hidden' => false,
        'force_recovery_original_name' => '',
        'force_recovery_original_transform' => [],
        'force_recovery_original_attrs' => {},
        'force_recovery_original_representation' => 'full',
        'publish_countdown_started_at' => '',
        'publish_countdown_until' => 0.0,
        # 首次新增空间也统一进入后台发布队列。正式共享 SKP 写出前，
        # 本机根实例与候选必须保留，且普通 manifest 同步不能把这条本机记录冲掉。
        'initial_publish_pending' => false,
        'initial_publish_candidate' => '',
        'initial_publish_error' => '',
        'background_publish_state' => '',
        'background_publish_job_id' => '',
        'background_publish_candidate' => '',
        'background_publish_error' => '',
        # v0.13.6.145：空间 SKP 是基础快照，协同组件是独立最新覆盖层。若一次空间发布
        # 同时带组件修改，先把这一批次标记为 pending；只有组件资产全部提交后才 committed。
        # 接收端在 committed 前不会消费这个空间版本，避免“空间已新、组件资产还旧”的窗口。
        'component_bundle_id' => '',
        'component_bundle_state' => '',
        'component_bundle_started_at' => '',
        'component_bundle_completed_at' => '',
        'component_bundle_dependencies' => [],
        # 联动空间不保存第二份 SKP；它指向一个权威来源空间，
        # 只独立保存名称、分组和世界坐标变换。
        'linked_source_space_id' => '',
        'linked_source_name' => '',
        'linked_transform' => []
      }
    end

    def normalize_space_name(value)
      value.to_s.gsub(/[\x00-\x1f]/, '').strip
    rescue StandardError
      value.to_s.strip
    end

    def safe_space_filename(value)
      text = normalize_space_name(value)
      text = text.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ').strip
      text = '未命名空间' if text.empty?
      text[0, 80]
    end


    # 硬装/软装是两套独立工作区，但为了兼容既有协同目录仍共享空间模型清单。
    # 所有业务判断都必须通过 collection_key 过滤，不能再用“室内”作为隐式总集合。
    def space_workspace_role?(value)
      SPACE_COLLECTION_KEYS.include?(value.to_s)
    rescue StandardError
      false
    end

    def normalize_space_collection_key(value, fallback = SPACE_COLLECTION_KEY)
      key = value.to_s
      return key if SPACE_COLLECTION_KEYS.include?(key)
      fallback_key = fallback.to_s
      SPACE_COLLECTION_KEYS.include?(fallback_key) ? fallback_key : SPACE_COLLECTION_KEY
    rescue StandardError
      SPACE_COLLECTION_KEY
    end

    def space_record_collection_key(item, fallback = SPACE_COLLECTION_KEY)
      normalize_space_collection_key(item.is_a?(Hash) ? item['collection_key'] : '', fallback)
    end

    def space_collection_label(value)
      normalize_space_collection_key(value) == SOFT_SPACE_COLLECTION_KEY ? '软装' : '硬装'
    end

    # 面向用户的空间名称始终带专业，而不是显示内部排序号。
    # “软装：三层大客房”比“10:三层大客房”更容易判断正在操作哪一套空间。
    def space_ui_label(item)
      return '当前空间' unless item.is_a?(Hash)
      collection = space_collection_label(space_record_collection_key(item))
      name = item['name'].to_s.strip
      name.empty? ? "#{collection}空间" : "#{collection}：#{name}"
    rescue StandardError
      '当前空间'
    end

    # 自动分组只接受“字母+数字”或“数字+字母”的短楼层/区域代码，
    # 如 B1 / B2 / 1F / 2F / A12。纯中文“二层小客房”绝不会被当成组名。
    def structured_space_group_token?(value)
      token = normalize_space_name(value)
      !!(token =~ /\A(?:[A-Za-z]{1,4}\d{1,3}|\d{1,3}[A-Za-z]{1,4})\z/)
    rescue StandardError
      false
    end

    def normalize_structured_space_group_token(value)
      token = normalize_space_name(value)
      structured_space_group_token?(token) ? token.upcase : ''
    rescue StandardError
      ''
    end

    # 解析“B1-二层小客房-硬装”一类结构化名称。后缀只识别末尾完整词，
    # 因此房间名中间包含“软装/硬装”不会误分类。
    def parse_structured_space_name(value, default_collection: SPACE_COLLECTION_KEY)
      raw = normalize_space_name(value).gsub(/[－—–]/, '-')
      parts = raw.split('-').map { |part| normalize_space_name(part) }.reject(&:empty?)
      suffix = parts.last.to_s
      target_role = case suffix
                    when '建筑' then 'architecture'
                    when '硬装' then SPACE_COLLECTION_KEY
                    when '软装' then SOFT_SPACE_COLLECTION_KEY
                    else normalize_space_collection_key(default_collection)
                    end
      explicit_suffix = %w[建筑 硬装 软装].include?(suffix)
      parts.pop if explicit_suffix
      group_name = ''
      if parts.length >= 2 && structured_space_group_token?(parts.first)
        group_name = normalize_structured_space_group_token(parts.shift)
      end
      name = normalize_space_name(parts.join('-'))
      name = normalize_space_name(raw) if name.empty? && !explicit_suffix
      {
        'raw' => raw,
        'name' => name,
        'group_name' => group_name,
        'target_role' => target_role,
        'collection_key' => target_role == SOFT_SPACE_COLLECTION_KEY ? SOFT_SPACE_COLLECTION_KEY : SPACE_COLLECTION_KEY,
        'explicit_suffix' => explicit_suffix
      }
    rescue StandardError
      {
        'raw' => normalize_space_name(value), 'name' => normalize_space_name(value), 'group_name' => '',
        'target_role' => normalize_space_collection_key(default_collection),
        'collection_key' => normalize_space_collection_key(default_collection), 'explicit_suffix' => false
      }
    end

    def ensure_named_space_group!(state, group_name)
      name = normalize_structured_space_group_token(group_name)
      return '' if name.empty?
      state['space_groups'] = Array(state['space_groups'])
      existing = state['space_groups'].find { |group| group.is_a?(Hash) && group['name'].to_s.casecmp(name).zero? }
      return existing['id'].to_s if existing
      group = {
        'id' => SecureRandom.uuid, 'name' => name, 'order' => state['space_groups'].length,
        'collapsed' => true, 'visibility_suspended' => false, 'visibility_restore_ids' => [],
        'collection_visibility' => {}
      }
      state['space_groups'] << group
      group['id'].to_s
    end

    def ensure_named_architecture_group!(state, group_name)
      name = normalize_structured_space_group_token(group_name)
      return '' if name.empty?
      state['architecture_groups'] = Array(state['architecture_groups'])
      existing = state['architecture_groups'].find { |group| group.is_a?(Hash) && group['name'].to_s.casecmp(name).zero? }
      return existing['id'].to_s if existing
      group = {
        'id' => SecureRandom.uuid, 'name' => name, 'order' => state['architecture_groups'].length,
        'collapsed' => true, 'visibility_suspended' => false, 'visibility_restore_ids' => []
      }
      state['architecture_groups'] << group
      group['id'].to_s
    end

    def spaces_for_collection(state, collection_key)
      key = normalize_space_collection_key(collection_key)
      Array(state['space_models']).select { |item| space_record_collection_key(item) == key }
    rescue StandardError
      []
    end

    def normalize_space_models_state!(state, model = Sketchup.active_model)
      records = Array(state['space_models'])
      seen_ids = {}
      seen_numbers = {}
      normalized = []
      auto_group_names = {}
      records.each_with_index do |raw, index|
        item = raw.is_a?(Hash) ? raw.dup : {}
        number = item['number'].to_i
        number = index + 1 unless number.positive?
        number += 1 while seen_numbers[number]
        seen_numbers[number] = true
        id = item['id'].to_s.strip
        id = SecureRandom.uuid if id.empty? || seen_ids[id]
        seen_ids[id] = true
        defaults = default_space_model(number, item['name'], item['model_path'])
        defaults.each { |key, value| item[key] = value unless item.key?(key) }
        item['id'] = id
        item['number'] = number
        item['name'] = normalize_space_name(item['name'])
        item['name'] = '未命名空间' if item['name'].empty?
        # v0.13.6.20：旧“室内”空间默认迁入硬装；末尾明确写了 -硬装/-软装 的
        # 记录按名称自动拆分，并只在首段是 B1/1F 这类严格代码时自动建立分组。
        parsed_identity = parse_structured_space_name(item['name'], default_collection: item['collection_key'])
        # 如果清单里的显示名已经被旧版本去掉后缀，再从 model_path 文件名做一次纯字符串兜底。
        # 这里只解析名字，不访问网络盘，因此升级打开大项目不会多出文件 IO。
        unless parsed_identity['explicit_suffix']
          stem = begin
            File.basename(item['model_path'].to_s, File.extname(item['model_path'].to_s)).sub(/\A\d+[_-]?/, '')
          rescue StandardError
            ''
          end
          file_identity = parse_structured_space_name(stem, default_collection: item['collection_key'])
          if file_identity['explicit_suffix'] && SPACE_COLLECTION_KEYS.include?(file_identity['target_role'].to_s)
            parsed_identity = file_identity.merge('name' => item['name'].to_s.empty? ? file_identity['name'].to_s : item['name'].to_s)
          end
        end
        if parsed_identity['explicit_suffix'] && SPACE_COLLECTION_KEYS.include?(parsed_identity['target_role'].to_s)
          item['collection_key'] = parsed_identity['target_role'].to_s
          # 名称本身带后缀时才去掉；若只是文件名带后缀，则保留现有清单显示名。
          original_name_identity = parse_structured_space_name(item['name'], default_collection: item['collection_key'])
          item['name'] = original_name_identity['name'].to_s if original_name_identity['explicit_suffix'] && !original_name_identity['name'].to_s.empty?
          auto_group_names[id] = parsed_identity['group_name'].to_s unless parsed_identity['group_name'].to_s.empty?
        else
          item['collection_key'] = normalize_space_collection_key(item['collection_key'])
        end
        item['model_path'] = item['model_path'].to_s
        item['group_id'] = item['group_id'].to_s
        item['group_order'] = item['group_order'].to_i
        # v0.8.9 起不再维护空间级代理文件；代理只绑定软装家具模型。
        item['proxy_path'] = ''
        item['proxy_signature'] = ''
        item['proxy_published_at'] = ''
        item['legacy_key'] = item['legacy_key'].to_s
        item['status'] = item['status'].to_s
        item['last_update'] = item['last_update'].to_s
        item['last_publish_at'] = item['last_publish_at'].to_s
        item['last_signature'] = item['last_signature'].to_s
        item['source_revision'] = item['source_revision'].to_s
        item['editing'] = !!item['editing']
        item['edit_lock_token'] = item['edit_lock_token'].to_s
        item['edit_actor_role'] = WORKSPACE_ROLES.include?(item['edit_actor_role'].to_s) ? item['edit_actor_role'].to_s : ''
        item['edit_lock_owner'] = item['edit_lock_owner'].to_s
        item['edit_lock_host'] = item['edit_lock_host'].to_s
        item['edit_lock_started_at'] = item['edit_lock_started_at'].to_s
        item['edit_references_visible'] = !!item['edit_references_visible']
        item['isolation_snapshot'] = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
        item['isolation_lock_snapshot'] = item['isolation_lock_snapshot'].is_a?(Hash) ? item['isolation_lock_snapshot'] : {}
        item['publish_pending'] = !!item['publish_pending']
        item['edit_safe_paused'] = !!item['edit_safe_paused']
        item['edit_safe_paused_at'] = item['edit_safe_paused_at'].to_s
        item['edit_safe_pause_reason'] = item['edit_safe_pause_reason'].to_s
        item['force_recovery_active'] = !!item['force_recovery_active']
        item['force_recovery_snapshot_path'] = item['force_recovery_snapshot_path'].to_s
        item['force_recovery_snapshot_signature'] = item['force_recovery_snapshot_signature'].to_s
        item['force_recovery_started_at'] = item['force_recovery_started_at'].to_s
        item['force_recovery_original_locked'] = item.key?('force_recovery_original_locked') ? !!item['force_recovery_original_locked'] : true
        item['force_recovery_original_hidden'] = !!item['force_recovery_original_hidden']
        item['force_recovery_original_name'] = item['force_recovery_original_name'].to_s
        item['force_recovery_original_transform'] = Array(item['force_recovery_original_transform']).map(&:to_f)
        item['force_recovery_original_transform'] = [] unless item['force_recovery_original_transform'].length == 16
        item['force_recovery_original_attrs'] = item['force_recovery_original_attrs'].is_a?(Hash) ? item['force_recovery_original_attrs'] : {}
        item['force_recovery_original_representation'] = item['force_recovery_original_representation'].to_s == 'proxy' ? 'proxy' : 'full'
        item['publish_countdown_started_at'] = item['publish_countdown_started_at'].to_s
        item['publish_countdown_until'] = item['publish_countdown_until'].to_f
        item['component_bundle_id'] = item['component_bundle_id'].to_s
        item['component_bundle_state'] = item['component_bundle_state'].to_s
        item['component_bundle_state'] = '' unless %w[pending committed incomplete].include?(item['component_bundle_state'])
        item['component_bundle_started_at'] = item['component_bundle_started_at'].to_s
        item['component_bundle_completed_at'] = item['component_bundle_completed_at'].to_s
        item['component_bundle_dependencies'] = Array(item['component_bundle_dependencies']).filter_map do |row|
          next unless row.is_a?(Hash)
          component_id = row['id'].to_s
          next if component_id.empty?
          {
            'id' => component_id,
            'name' => row['name'].to_s,
            'content_signature' => row['content_signature'].to_s
          }
        end.uniq { |row| row['id'] }
        item['linked_source_space_id'] = item['linked_source_space_id'].to_s.strip
        item['linked_source_space_id'] = '' if item['linked_source_space_id'] == id
        item['linked_source_name'] = item['linked_source_name'].to_s
        item['linked_transform'] = Array(item['linked_transform']).map(&:to_f)
        item['linked_transform'] = [] unless item['linked_transform'].length == 16
        normalized << item
      end

      # 联动关系一律压到最顶层来源，防止“副本再复制”形成链式循环。
      normalized_by_id = normalized.each_with_object({}) { |item, memo| memo[item['id'].to_s] = item }
      normalized.each do |item|
        source_id = item['linked_source_space_id'].to_s
        next if source_id.empty?
        visited = { item['id'].to_s => true }
        24.times do
          source = normalized_by_id[source_id]
          break unless source
          next_id = source['linked_source_space_id'].to_s
          break if next_id.empty?
          if visited[next_id]
            source_id = ''
            break
          end
          visited[source_id] = true
          source_id = next_id
        end
        item['linked_source_space_id'] = source_id
        source = normalized_by_id[source_id]
        item['linked_source_name'] = source['name'].to_s if source
        unless source_id.empty?
          # 联动副本只复用来源内容与发布结果，从不拥有独立协作锁或待发布会话。
          # 清理旧版误回填的 token，避免副本心跳/释放来源空间的锁文件。
          item['editing'] = false
          item['edit_lock_token'] = ''
          item['edit_actor_role'] = ''
          item['edit_lock_owner'] = ''
          item['edit_lock_host'] = ''
          item['edit_lock_started_at'] = ''
          item['publish_pending'] = false
          item['edit_safe_paused'] = false
          item['edit_safe_paused_at'] = ''
          item['edit_safe_pause_reason'] = ''
        end
      end

      force_id = state['space_force_recovery_id'].to_s
      state['space_force_recovery_id'] = normalized.any? { |record| record['id'].to_s == force_id && record['force_recovery_active'] } ? force_id : ''

      # 这是全新的多空间插件，不在每次读取状态时迁移旧“硬装/软装单模型”。
      # 旧逻辑会对所有空间反复 File.file?，路径失效时甚至递归扫描整个项目目录；
      # 它既不属于状态规范化，也会让简单的解锁/修改产生与模型大小无关的长卡顿。
      # 单个空间的路径只在用户实际更新、修改或发布该空间时校验。
      state['space_legacy_migrated'] = true

      # 从本版本起，硬装和软装不再保留各自的单模型入口。
      %w[hard_finish soft_finish furniture].each do |legacy_key|
        link = state.dig('links', legacy_key)
        next unless link.is_a?(Hash)
        link['model_path'] = ''
        link['collab_manifest_path'] = ''
        link['collab_project_manifest_path'] = ''
        link['collab_full_path'] = ''
        link['collab_cache_version'] = 0
        link['status'] = '已并入硬装／软装空间模型'
      end

      raw_groups = Array(state['space_groups'])
      seen_group_ids = {}
      groups = raw_groups.each_with_index.map do |raw, index|
        group = raw.is_a?(Hash) ? raw.dup : {}
        id = group['id'].to_s.strip
        id = SecureRandom.uuid if id.empty? || seen_group_ids[id]
        seen_group_ids[id] = true
        name = normalize_space_name(group['name'])
        name = "空间组#{index + 1}" if name.empty?
        {
          'id' => id,
          'name' => name,
          'order' => group['order'].to_i,
          'collapsed' => group.key?('collapsed') ? !!group['collapsed'] : true,
          # 组显隐属于本机浏览状态：隐藏时只记录当时真正可见的成员，
          # 再次显示只恢复这些成员，不会改动原本单独隐藏的空间。
          'visibility_suspended' => !!group['visibility_suspended'],
          'visibility_restore_ids' => Array(group['visibility_restore_ids']).map(&:to_s).reject(&:empty?).uniq,
          'collection_visibility' => group['collection_visibility'].is_a?(Hash) ? deep_dup_runtime_value(group['collection_visibility']) : {}
        }
      end
      groups.each_with_index { |group, index| group['order'] = index if group['order'].negative? }
      groups.sort_by! { |group| [group['order'].to_i, group['name'].to_s] }
      # 先把现有组放回 state，再为结构化命名中识别出的 B1/1F 等组创建缺失记录。
      state['space_groups'] = groups
      auto_group_names.each do |space_id, group_name|
        item = normalized.find { |candidate| candidate['id'].to_s == space_id.to_s }
        next unless item
        item['group_id'] = ensure_named_space_group!(state, group_name)
      end
      groups = Array(state['space_groups']).sort_by { |group| [group['order'].to_i, group['name'].to_s] }
      groups.each_with_index { |group, index| group['order'] = index }
      valid_group_ids = groups.each_with_object({}) { |group, memo| memo[group['id'].to_s] = true }
      normalized.each do |item|
        item['group_id'] = '' unless valid_group_ids[item['group_id'].to_s]
      end
      member_ids_by_group = normalized.group_by { |item| item['group_id'].to_s }.transform_values do |items|
        items.each_with_object({}) { |item, memo| memo[item['id'].to_s] = true }
      end
      groups.each do |group|
        valid_members = member_ids_by_group[group['id'].to_s] || {}
        SPACE_COLLECTION_KEYS.each do |collection_key|
          entry = group_collection_visibility_state(group, collection_key)
          collection_members = normalized.select do |item|
            item['group_id'].to_s == group['id'].to_s && space_record_collection_key(item) == collection_key
          end.each_with_object({}) { |item, memo| memo[item['id'].to_s] = true }
          entry['restore_ids'] = Array(entry['restore_ids']).select { |space_id| collection_members[space_id.to_s] }
          entry['suspended'] = false if entry['suspended'] && entry['restore_ids'].empty?
        end
        sync_legacy_group_visibility_from_collection!(group)
      end
      state['space_groups'] = groups
      state['space_models'] = normalized.sort_by do |item|
        group = groups.find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
        [group ? group['order'].to_i : 9_999_999, item['group_order'].to_i, item['number'].to_i]
      end
      # 删除空间后不重排现有文件；下一次新增优先补齐最小空缺编号。
      state['space_next_number'] = smallest_available_space_number(state['space_models'])
      state['space_editing_id'] = state['space_editing_id'].to_s
      legacy_hidden = !!state['space_collection_hidden']
      legacy_snapshot = normalize_space_collection_visibility_snapshot(state['space_collection_visibility_snapshot'])
      hidden_by_key = state['space_collection_hidden_by_key'].is_a?(Hash) ? state['space_collection_hidden_by_key'] : {}
      snapshot_by_key = state['space_collection_visibility_snapshot_by_key'].is_a?(Hash) ? state['space_collection_visibility_snapshot_by_key'] : {}
      state['space_collection_hidden_by_key'] = {
        SPACE_COLLECTION_KEY => hidden_by_key.key?(SPACE_COLLECTION_KEY) ? !!hidden_by_key[SPACE_COLLECTION_KEY] : legacy_hidden,
        SOFT_SPACE_COLLECTION_KEY => hidden_by_key.key?(SOFT_SPACE_COLLECTION_KEY) ? !!hidden_by_key[SOFT_SPACE_COLLECTION_KEY] : false
      }
      state['space_collection_visibility_snapshot_by_key'] = {
        SPACE_COLLECTION_KEY => normalize_space_collection_visibility_snapshot(snapshot_by_key.key?(SPACE_COLLECTION_KEY) ? snapshot_by_key[SPACE_COLLECTION_KEY] : legacy_snapshot),
        SOFT_SPACE_COLLECTION_KEY => normalize_space_collection_visibility_snapshot(snapshot_by_key[SOFT_SPACE_COLLECTION_KEY])
      }
      # 旧字段只镜像硬装，供尚未迁移的旧代码/历史项目安全读取。
      state['space_collection_hidden'] = state['space_collection_hidden_by_key'][SPACE_COLLECTION_KEY]
      state['space_collection_visibility_snapshot'] = state['space_collection_visibility_snapshot_by_key'][SPACE_COLLECTION_KEY]
      state['space_display_mode'] = %w[proxy full].include?(state['space_display_mode'].to_s) ? state['space_display_mode'].to_s : 'proxy'
      state['space_edit_display_mode'] = %w[proxy full].include?(state['space_edit_display_mode'].to_s) ? state['space_edit_display_mode'].to_s : ''
      state['space_preview_full_id'] = state['space_preview_full_id'].to_s
      unless state['space_preview_full_id'].empty? || state['space_models'].any? { |item| item['id'].to_s == state['space_preview_full_id'] }
        state['space_preview_full_id'] = ''
      end
      state
    rescue StandardError => e
      log_exception('整理软装＋硬装空间模型状态失败', e)
      state['space_models'] = [] unless state['space_models'].is_a?(Array)
      state['space_next_number'] = 1 unless state['space_next_number'].to_i.positive?
      state
    end

    def space_model_record(state, space_id)
      Array(state['space_models']).find { |item| item.is_a?(Hash) && item['id'].to_s == space_id.to_s }
    end

    def linked_space_record?(item)
      item.is_a?(Hash) && !item['linked_source_space_id'].to_s.empty?
    rescue StandardError
      false
    end

    def canonical_space_record(state, item_or_id)
      item = item_or_id.is_a?(Hash) ? item_or_id : space_model_record(state, item_or_id)
      return nil unless item
      visited = {}
      24.times do
        id = item['id'].to_s
        return nil if visited[id]
        visited[id] = true
        source_id = item['linked_source_space_id'].to_s
        return item if source_id.empty?
        item = space_model_record(state, source_id)
        return nil unless item
      end
      nil
    rescue StandardError
      nil
    end

    def linked_space_dependents(state, source_id)
      canonical = canonical_space_record(state, source_id)
      canonical_id = canonical ? canonical['id'].to_s : source_id.to_s
      Array(state['space_models']).select do |item|
        next false unless linked_space_record?(item)
        source = canonical_space_record(state, item)
        source && source['id'].to_s == canonical_id
      end
    rescue StandardError
      []
    end

    def linked_space_copy_record(model = Sketchup.active_model)
      @linked_space_copy_placements ||= {}
      record = model ? @linked_space_copy_placements[model.object_id] : nil
      if record
        phase = record[:phase].to_s
        if phase == 'adjusting'
          unless record[:entity] && record[:entity].valid?
            @linked_space_copy_placements.delete(model.object_id)
            record = nil
          end
        else
          unless record[:source_entity] && record[:source_entity].valid?
            @linked_space_copy_placements.delete(model.object_id)
            record = nil
          end
        end
      end
      record
    rescue StandardError
      nil
    end

    def linked_space_copy_active?(model = Sketchup.active_model)
      !!linked_space_copy_record(model)
    rescue StandardError
      false
    end

    # v0.13.6.156：联动空间实例调整是一种“只改实例矩阵”的本机临时解锁，
    # 不属于普通空间协作编辑，因此绝不能被 native lock monitor 按“无协作锁的
    # 原生解锁”重新锁回。以当前 placement record + item_id + 实体身份三重确认，
    # 只给正在调整的这一实例开例外；其它联动空间仍保持根层锁定。
    def linked_space_transform_adjustment_active?(item, entity = nil, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && linked_space_record?(item) && model
      record = linked_space_copy_record(model)
      return false unless record.is_a?(Hash) && record[:mode].to_s == 'transform' && record[:phase].to_s == 'adjusting'
      return false unless record[:item_id].to_s == item['id'].to_s
      target = record[:entity]
      return false unless target && target.valid?
      return false if entity && (!entity.valid? || !target.equal?(entity))
      true
    rescue StandardError
      false
    end

    # v0.13.6.155：联动空间分成“来源内容”和“实例变换”两层。已登记联动空间
    # 双击只进入实例变换，不再走来源 SKP 的普通编辑/版本预检；原生 Move+Ctrl 复制
    # 出来的额外实例先标记为待登记副本，逐个选中点顶部对勾命名即可。
    def pending_linked_space_clone?(entity)
      entity && entity.valid? && entity.respond_to?(:get_attribute) &&
        entity.get_attribute(ENTITY_DICT, 'linked_pending_clone', false) == true
    rescue StandardError
      false
    end

    def pending_linked_space_clones(model = Sketchup.active_model)
      return [] unless model
      model.entities.select { |entity| pending_linked_space_clone?(entity) }
    rescue StandardError
      []
    end

    def selected_pending_linked_space_clones(model = Sketchup.active_model)
      return [] unless model && model.respond_to?(:selection)
      model.selection.to_a.select { |entity| pending_linked_space_clone?(entity) }
    rescue StandardError
      []
    end

    def selected_pending_linked_space_clone(model = Sketchup.active_model)
      return nil unless model
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      pending_linked_space_clone?(entity) ? entity : nil
    rescue StandardError
      nil
    end

    # v0.13.6.159：原生 Move+Ctrl 复制待登记联动空间时，不能假设 SketchUp 一定
    # 复制实体属性字典。部分版本/工具路径只会创建同 Definition 的新根实例，因此 158
    # 只找 linked_pending_clone 属性会漏掉第二、第三个副本。现在观察表同时保存“已知根
    # 实例集合 + 来源空间身份”；事务完成后只比较这个 Definition 的根实例增量，新出现
    # 的实例即使完全没有 LinkHub 属性，也会被补登记为独立待命名联动空间。
    def linked_space_root_instance?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid? && model
      return true unless entity.respond_to?(:parent)
      entity.parent.equal?(model.entities)
    rescue StandardError
      false
    end

    def linked_space_instance_watch_key(entity)
      return '' unless entity && entity.valid?
      if entity.respond_to?(:persistent_id)
        pid = entity.persistent_id.to_i
        return "pid:#{pid}" if pid.positive?
      end
      "obj:#{entity.object_id}"
    rescue StandardError
      "obj:#{entity.object_id}" rescue ''
    end

    def linked_space_definition_root_instances(definition, model = Sketchup.active_model)
      return [] unless definition && definition.respond_to?(:instances) && model
      definition.instances.to_a.select { |instance| linked_space_root_instance?(instance, model) }
    rescue StandardError
      []
    end

    def track_pending_linked_space_definition!(entity, model = Sketchup.active_model)
      return false unless model && entity && entity.valid? && entity.respond_to?(:definition) && entity.definition
      definition = entity.definition
      @linked_pending_definition_watches ||= {}
      bucket = (@linked_pending_definition_watches[model.object_id] ||= {})
      watch = bucket[definition.object_id]
      source_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_source_space_id', '').to_s
      source_id = entity.get_attribute(ENTITY_DICT, 'linked_source_space_id', '').to_s if source_id.empty?
      origin_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_origin_space_id', '').to_s
      origin_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if origin_id.empty?
      if watch.is_a?(Hash)
        watch[:definition] = definition
        watch[:source_id] = source_id unless source_id.empty?
        watch[:origin_id] = origin_id unless origin_id.empty?
        watch[:known_instance_keys] ||= {}
        # 已存在的 watch 绝不能在这里重做全量快照，否则恰好刚复制出来、尚未被
        # reconcile 的新实例会被吞进“已知集合”，从而永远失去待登记身份。
        linked_space_definition_root_instances(definition, model).each do |instance|
          next unless instance.equal?(entity)
          key = linked_space_instance_watch_key(instance)
          watch[:known_instance_keys][key] = true unless key.empty?
        end
        watch[:touched_at] = monotonic_time
      else
        known = {}
        linked_space_definition_root_instances(definition, model).each do |instance|
          key = linked_space_instance_watch_key(instance)
          known[key] = true unless key.empty?
        end
        bucket[definition.object_id] = {
          definition: definition, source_id: source_id, origin_id: origin_id,
          known_instance_keys: known, touched_at: monotonic_time
        }
      end
      true
    rescue StandardError => e
      log_exception('登记联动副本 Definition 增量观察失败', e)
      false
    end

    def pending_linked_space_watch_active?(model = Sketchup.active_model)
      return false unless model
      bucket = @linked_pending_definition_watches && @linked_pending_definition_watches[model.object_id]
      bucket.is_a?(Hash) && !bucket.empty?
    rescue StandardError
      false
    end

    def pending_linked_space_clone_by_id(temp_id, model = Sketchup.active_model)
      return nil unless model
      wanted = temp_id.to_s
      return nil if wanted.empty?
      model.entities.each do |entity|
        next unless pending_linked_space_clone?(entity)
        current = entity.get_attribute(ENTITY_DICT, 'linked_pending_temp_id', '').to_s
        current = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if current.empty?
        return entity if current == wanted
      end
      nil
    rescue StandardError
      nil
    end

    def select_and_finish_pending_linked_space_clone!(temp_id, model = Sketchup.active_model)
      entity = pending_linked_space_clone_by_id(temp_id, model)
      raise '这个待登记联动副本已不存在，请重新选择模型。' unless entity && entity.valid?
      model.selection.clear
      model.selection.add(entity)
      finish_pending_linked_space_clone!(model)
    end

    def begin_pending_linked_space_transform!(entity, model = Sketchup.active_model)
      raise '请先退出组件内部，再调整待登记联动副本。' unless model && model.active_path.nil?
      raise '该对象已不是待登记联动副本。' unless pending_linked_space_clone?(entity)
      entity.locked = false if entity.respond_to?(:locked=)
      model.selection.clear
      model.selection.add(entity)
      refresh_workspace_toolbar(model, selection_fast: true)
      show_status('待登记联动副本：可用原生移动/旋转/缩放/镜像调整；顶部绿色对勾用于命名登记。', 'info')
      true
    end

    def normalize_pending_linked_space_selection!(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:selection)
      selected = model.selection.to_a
      pending = selected.select { |entity| pending_linked_space_clone?(entity) }
      return false if pending.empty? || selected.length == 1
      # 待登记副本需要逐个命名，主动收成单选，避免一次选中多个后不知道名称该落到谁。
      keep = pending.last
      model.selection.clear
      model.selection.add(keep) if keep && keep.valid?
      true
    rescue StandardError
      false
    end

    def clear_pending_linked_space_clone_attributes!(entity)
      return false unless entity && entity.valid?
      %w[
        linked_pending_clone linked_pending_source_space_id linked_pending_origin_space_id
        linked_pending_temp_id linked_pending_created_at
      ].each { |key| entity.delete_attribute(ENTITY_DICT, key) rescue nil }
      true
    rescue StandardError
      false
    end

    def convert_linked_native_clone_to_pending!(entity, source, origin_id, model = Sketchup.active_model, temp_id: nil)
      return false unless entity && entity.valid? && source.is_a?(Hash)
      temp_id = temp_id.to_s
      temp_id = SecureRandom.uuid if temp_id.empty?
      collection_key = space_record_collection_key(source)
      entity.set_attribute(ENTITY_DICT, 'managed', false)
      entity.set_attribute(ENTITY_DICT, 'kind', 'linked_space_pending')
      entity.set_attribute(ENTITY_DICT, 'discipline', collection_key)
      entity.set_attribute(ENTITY_DICT, 'space_collection_key', collection_key)
      entity.set_attribute(ENTITY_DICT, 'space_id', temp_id)
      entity.set_attribute(ENTITY_DICT, 'linked_space', true)
      entity.set_attribute(ENTITY_DICT, 'linked_source_space_id', source['id'].to_s)
      entity.set_attribute(ENTITY_DICT, 'linked_pending_clone', true)
      entity.set_attribute(ENTITY_DICT, 'linked_pending_source_space_id', source['id'].to_s)
      entity.set_attribute(ENTITY_DICT, 'linked_pending_origin_space_id', origin_id.to_s)
      entity.set_attribute(ENTITY_DICT, 'linked_pending_temp_id', temp_id)
      entity.set_attribute(ENTITY_DICT, 'linked_pending_created_at', Time.now.iso8601)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.delete_attribute(ENTITY_DICT, 'safe_paused') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'force_recovery') rescue nil
      entity.name = '联动副本（待命名）' if entity.respond_to?(:name=)
      entity.locked = false if entity.respond_to?(:locked=)
      track_pending_linked_space_definition!(entity, model)
      true
    rescue StandardError => e
      log_exception('标记原生复制的联动空间待登记副本失败', e)
      false
    end

    def pending_linked_space_drawer_rows(state, collection_key, model = Sketchup.active_model)
      return [] unless model && state.is_a?(Hash)
      normalized = normalize_space_collection_key(collection_key)
      pending_linked_space_clones(model).filter_map do |entity|
        next unless entity && entity.valid?
        discipline = entity.get_attribute(ENTITY_DICT, 'space_collection_key', '').to_s
        discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s if discipline.empty?
        next unless normalize_space_collection_key(discipline, normalized) == normalized
        temp_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_temp_id', '').to_s
        temp_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if temp_id.empty?
        source_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_source_space_id', '').to_s
        source_id = entity.get_attribute(ENTITY_DICT, 'linked_source_space_id', '').to_s if source_id.empty?
        source = canonical_space_record(state, source_id)
        source_name = source ? source['name'].to_s : '来源空间'
        {
          'id' => "pending:#{temp_id}", 'number' => 0, 'collection_key' => normalized,
          'raw_name' => '联动副本（待命名）', 'group_id' => '', 'group_order' => 9_999_999,
          'name' => "联动副本（待命名） · #{source_name}",
          'status_code' => 'pending', 'status' => '待命名 · 位置已保留', 'last_update' => '',
          'loaded' => true, 'manage_selectable' => false, 'manage_can_rename' => false,
          'manage_can_delete' => false, 'manage_can_group' => false, 'color' => [42, 154, 104],
          'publish_warning' => false, 'linked_space' => true, 'linked_source_space_id' => source_id,
          'linked_source_name' => source_name, 'action' => "drawer_linked_pending_finish:#{temp_id}",
          'action_label' => '命名', 'tooltip' => '登记这个联动副本并输入独立空间名称', 'enabled' => true,
          'release_occupancy_action' => '', 'resident_action' => '', 'resident_tooltip' => '',
          'resident_enabled' => false, 'resident_loaded' => true, 'visibility_action' => '',
          'visibility_tooltip' => '待命名副本请先完成登记', 'visibility_enabled' => false,
          'visible' => !entity.hidden?
        }
      end
    rescue StandardError => e
      log_exception('构造待登记联动副本卡片失败', e)
      []
    end

    def save_linked_space_transform_record!(record, model = Sketchup.active_model, notify: true, reason: '完成调整')
      return false unless record.is_a?(Hash) && model
      entity = record[:entity]
      item_id = record[:item_id].to_s
      raise '待调整联动空间已不存在。' unless entity && entity.valid? && !item_id.empty?
      raise '联动空间变换已退化（某个缩放轴接近 0）。' unless supported_linked_space_transformation?(entity.transformation)
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, item_id)
      raise '联动空间记录已不存在。' unless item && linked_space_record?(item)
      source = canonical_space_record(state, item)
      raise '联动来源已缺失，不能保存实例变换。' unless source

      operation_open = false
      model.start_operation('完成联动空间位置调整', true)
      operation_open = true
      item['linked_transform'] = entity.transformation.to_a.map(&:to_f)
      item['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['status'] = "联动于（#{source['name']}）"
      entity.set_attribute(ENTITY_DICT, 'linked_space', true)
      entity.set_attribute(ENTITY_DICT, 'linked_source_space_id', source['id'].to_s)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.locked = true if entity.respond_to?(:locked=)
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
      save_state(state, model, write_manifest: false)
      write_space_models_manifest!(state, model, preserve_remote_layout: true, local_space_ids: [item['id']])
      model.commit_operation
      operation_open = false
      @linked_space_copy_placements&.delete(model.object_id)
      invalidate_managed_root_index(model, reason: 'linked_space_transform_finish')
      mark_soft_measurement_dirty(model)
      refresh_dialog
      refresh_workspace_toolbar(model, detailed: true)
      show_status("已保存 #{item['number']}:#{item['name']} 的移动/旋转/缩放/镜像（#{reason}）。", 'success') if notify
      warn_linked_space_non_uniform_scale!(entity, model) if notify
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    end

    def begin_linked_space_transform!(space_id, entity = nil, model = Sketchup.active_model)
      raise '请先退出组件内部，再调整联动空间。' unless model && model.active_path.nil?
      raise '已有联动空间操作未完成，请先点顶部对勾。' if linked_space_copy_active?(model)
      raise '发布或更新正在执行，请稍候再调整。' if publish_critical_section? || publish_post_quiet? || @updating || @single_space_update_job || @space_batch_update_job
      ensure_soft_ingest_batch_not_writing!('联动空间调整')
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到联动空间记录。' unless item && linked_space_record?(item)
      source = canonical_space_record(state, item)
      raise '该联动空间的来源已缺失，请先刷新协同清单。' unless source
      entity ||= space_model_entity(item['id'], model)
      raise '该联动空间尚未载入。' unless entity && entity.valid?

      operation_open = false
      model.start_operation('调整联动空间实例', true)
      operation_open = true
      entity.locked = false if entity.respond_to?(:locked=)
      model.commit_operation
      operation_open = false
      # 与原生锁监视器同步当前事实：这个解锁由 LinkHub 的联动实例调整明确授权。
      # 若仍保留旧的 true 缓存，下一拍监视器会把它误判成用户右键“解锁”并立刻锁回。
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      @linked_space_copy_placements ||= {}
      @linked_space_copy_placements[model.object_id] = {
        mode: 'transform', phase: 'adjusting', entity: entity, source_entity: entity,
        item_id: item['id'].to_s, source_id: source['id'].to_s, source_name: source['name'].to_s,
        collection_key: space_record_collection_key(source),
        original_transformation: entity.transformation.to_a.map(&:to_f),
        transformation: entity.transformation.to_a.map(&:to_f)
      }
      model.selection.clear
      model.selection.add(entity)
      invalidate_managed_root_index(model, reason: 'linked_space_transform_begin')
      refresh_workspace_toolbar(model, detailed: true)
      show_status("已进入 #{item['number']}:#{item['name']} 实例调整：可用原生移动/旋转/缩放/镜像；Move+Ctrl 可连续复制，顶部对勾完成。", 'info')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    end

    # v0.13.6.157：联动副本一旦完成“基点 -> 目标点”就立即结束 LinkHub 的复制事务，
    # 之后 Move/Rotate/Scale/Move+Ctrl 全部交给 SketchUp 原生工具。这里只在原生复制
    # 的 transaction commit 后做一次“同 Definition 小范围”身份整理，不再每次扫整个
    # model.entities。这样不会因为一个未结束的 placement record 持续触发全局刷新，
    # 也避免第二个副本仍冒充第一个临时 space_id，导致顶部对勾登记错对象。
    def reconcile_linked_space_native_copies!(model = Sketchup.active_model)
      return false unless model && model.active_path.nil?
      record = linked_space_copy_record(model)
      # Ordinary root-level selection has nothing to reconcile. The old path still loaded and
      # normalized the complete space state, enumerated formal ids and rescanned root instances
      # on every click. Only an active transform, a live Definition watch, or an explicitly
      # selected pending clone can produce native linked copies.
      selected_pending = model.selection.to_a.any? { |entity| pending_linked_space_clone?(entity) }
      return false unless record.is_a?(Hash) || pending_linked_space_watch_active?(model) || selected_pending
      changed = false
      clones_created = 0
      pending_converted = 0

      # 已登记联动空间在“实例调整”模式里用 Move+Ctrl 复制时，新实例会继承相同
      # space_id。只检查 origin.definition.instances（通常只有极少数），不再扫描整个模型。
      if record.is_a?(Hash) && record[:mode].to_s == 'transform'
        origin = record[:entity]
        item_id = record[:item_id].to_s
        state = ensure_space_models_ready!(model)
        item = space_model_record(state, item_id)
        source = item ? canonical_space_record(state, item) : nil
        if origin && origin.valid? && item && source && origin.respond_to?(:definition) && origin.definition
          duplicates = origin.definition.instances.to_a.select do |entity|
            next false unless entity && entity.valid? && !entity.equal?(origin) && entity.respond_to?(:get_attribute)
            parent_ok = linked_space_root_instance?(entity, model)
            parent_ok &&
              entity.get_attribute(ENTITY_DICT, 'managed', false) == true &&
              entity.get_attribute(ENTITY_DICT, 'kind', '').to_s == 'space_model' &&
              entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s == item_id
          end
          unless duplicates.empty?
            operation_open = false
            model.start_operation('识别原生复制的联动空间', true, false, true)
            operation_open = true
            duplicates.each do |clone|
              next unless convert_linked_native_clone_to_pending!(clone, source, item_id, model)
              clones_created += 1
              pending_converted += 1
            end
            model.commit_operation
            operation_open = false
            changed = clones_created.positive?
            invalidate_managed_root_index(model, reason: 'linked_space_native_clone_pending') if changed
          end
        end
      end

      state_for_pending = ensure_space_models_ready!(model)
      formal_ids = Array(state_for_pending['space_models']).each_with_object({}) do |row, memo|
        memo[row['id'].to_s] = true unless row['id'].to_s.empty?
      end
      watch_bucket = (@linked_pending_definition_watches ||= {})[model.object_id] ||= {}

      # 当前明确选中的 pending 一定补进观察表；即使热重载后 watch 丢失，用户一选中
      # 第一份副本就能恢复增量观察。
      model.selection.to_a.each do |selected|
        next unless pending_linked_space_clone?(selected)
        track_pending_linked_space_definition!(selected, model)
      end

      stale_watch_keys = []
      pending_to_rekey = []
      newly_discovered = []
      now = monotonic_time

      watch_bucket.each do |watch_key, watch|
        definition = watch.is_a?(Hash) ? watch[:definition] : nil
        unless definition && definition.respond_to?(:instances)
          stale_watch_keys << watch_key
          next
        end

        roots = linked_space_definition_root_instances(definition, model)
        known = (watch[:known_instance_keys] ||= {})
        source_id = watch[:source_id].to_s
        origin_id = watch[:origin_id].to_s

        # 兼容 158 运行代留下来的旧 watch：从现有 pending 实例反补来源身份。
        if source_id.empty?
          seed = roots.find { |entity| pending_linked_space_clone?(entity) }
          if seed
            source_id = seed.get_attribute(ENTITY_DICT, 'linked_pending_source_space_id', '').to_s
            source_id = seed.get_attribute(ENTITY_DICT, 'linked_source_space_id', '').to_s if source_id.empty?
            origin_id = seed.get_attribute(ENTITY_DICT, 'linked_pending_origin_space_id', '').to_s if origin_id.empty?
            watch[:source_id] = source_id unless source_id.empty?
            watch[:origin_id] = origin_id unless origin_id.empty?
          end
        end

        source = source_id.empty? ? nil : canonical_space_record(state_for_pending, source_id)

        # 159 核心：比较 Definition 根实例的增量，而不是要求新实例已经带 pending 属性。
        # SketchUp Move+Ctrl 若只复制几何/Definition 而没复制实体属性，这里仍能抓到。
        roots.each do |entity|
          key = linked_space_instance_watch_key(entity)
          next if key.empty? || known[key]

          if pending_linked_space_clone?(entity)
            # 已经是 pending，只需后续检查临时 id 是否冲突。
            newly_discovered << entity
          elsif source
            # 已知 Definition 在“联动副本待登记”上下文中新出现了世界根实例，视为
            # 原生 Move+Ctrl 新副本。即使其 LinkHub 属性完全为空，也补齐身份。
            newly_discovered << entity
          end
          known[key] = true
        end

        pending_instances = roots.select { |entity| pending_linked_space_clone?(entity) }
        pending_instances.each do |entity|
          temp_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
          # 先只收集，统一在一个 operation 里 rekey。
          pending_to_rekey << entity if temp_id.empty? || formal_ids[temp_id]
        end

        # 没有任何 pending 时仍短暂保留 watch，兜住“刚命名第一份、第二份复制事务稍后才
        # 回调”的边界；超过 30 秒且无 pending 才退休，避免长期扫描 Definition。
        if pending_instances.empty? && (now - watch[:touched_at].to_f) > 30.0
          stale_watch_keys << watch_key
        else
          watch[:touched_at] = now if pending_instances.any? || newly_discovered.any?
        end
      end

      stale_watch_keys.each { |key| watch_bucket.delete(key) }
      @linked_pending_definition_watches.delete(model.object_id) if watch_bucket.empty?

      # 先把完全没有 pending 属性的新实例正式转成 pending。使用每个 watch 保存的来源
      # 身份，因此不会把同 Definition 的来源空间误登记；“已知集合”确保只处理新出现的根实例。
      unless newly_discovered.empty?
        operation_open = false
        model.start_operation('登记原生复制的联动空间副本', true, false, true)
        operation_open = true
        newly_discovered.uniq.each do |clone|
          next unless clone && clone.valid?
          next if pending_linked_space_clone?(clone)
          definition = clone.respond_to?(:definition) ? clone.definition : nil
          watch = definition ? watch_bucket[definition.object_id] : nil
          source_id = watch.is_a?(Hash) ? watch[:source_id].to_s : ''
          origin_id = watch.is_a?(Hash) ? watch[:origin_id].to_s : ''
          source = source_id.empty? ? nil : canonical_space_record(state_for_pending, source_id)
          next unless source
          origin_id = source['id'].to_s if origin_id.empty?
          next unless convert_linked_native_clone_to_pending!(clone, source, origin_id, model)
          pending_converted += 1
          clones_created += 1
        end
        model.commit_operation
        operation_open = false
        changed = true if pending_converted.positive?
      end

      # 所有 pending 必须拥有彼此独立、且不与正式空间冲突的临时 id。这里重新按
      # Definition 汇总一次，覆盖“原生复制继承同一个 temp id”的情况。
      current_pending = pending_linked_space_clones(model)
      seen_ids = {}
      current_pending.each do |entity|
        temp_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
        collision = temp_id.empty? || formal_ids[temp_id] || seen_ids[temp_id]
        pending_to_rekey << entity if collision
        seen_ids[temp_id] = true unless collision || temp_id.empty?
      end
      pending_to_rekey.uniq!

      unless pending_to_rekey.empty?
        operation_open = false
        model.start_operation('整理联动空间待登记副本', true, false, true)
        operation_open = true
        pending_to_rekey.each do |clone|
          next unless clone && clone.valid? && pending_linked_space_clone?(clone)
          temp_id = SecureRandom.uuid
          clone.set_attribute(ENTITY_DICT, 'space_id', temp_id)
          clone.set_attribute(ENTITY_DICT, 'linked_pending_temp_id', temp_id)
          clone.set_attribute(ENTITY_DICT, 'linked_pending_created_at', Time.now.iso8601)
          clone.name = '联动副本（待命名）' if clone.respond_to?(:name=)
          clone.locked = false if clone.respond_to?(:locked=)
          track_pending_linked_space_definition!(clone, model)
          clones_created += 1
        end
        model.commit_operation
        operation_open = false
        changed = true
      end

      if clones_created.positive? && record.is_a?(Hash) && record[:mode].to_s == 'transform'
        save_linked_space_transform_record!(record, model, notify: false, reason: '原生复制后自动锁回')
      end

      if changed || clones_created.positive?
        invalidate_managed_root_index(model, reason: 'linked_space_native_clone_pending')
        refresh_workspace_toolbar(model, selection_fast: true)
        # 抽屉卡片来自完整 UI state，必须显式合并刷新；158 只刷顶部，所以即使实体已
        # 识别，抽屉也可能一直看不到第二份副本。
        schedule_coalesced_refresh_dialog(0.05)
        show_status("已识别 #{clones_created} 个联动空间待登记副本；选中任意一个点顶部对勾即可命名。", 'info') if clones_created.positive?
      end
      changed
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      log_exception('整理原生复制联动空间失败', e)
      false
    end

    def reconcile_linked_space_transform_selection!(model = Sketchup.active_model)
      record = linked_space_copy_record(model)
      return false unless record.is_a?(Hash) && record[:mode].to_s == 'transform'
      entity = record[:entity]
      return false unless entity && entity.valid?
      return false if model.selection.to_a.include?(entity)
      save_linked_space_transform_record!(record, model, notify: false, reason: '切换选择时自动完成')
      true
    rescue StandardError => e
      log_exception('联动空间切换选择自动收尾失败', e)
      false
    end

    def finish_pending_linked_space_clone!(model = Sketchup.active_model)
      raise '请先退出组件内部，再登记联动空间副本。' unless model && model.active_path.nil?
      selected = model.selection.to_a
      pending = selected_pending_linked_space_clones(model)
      raise '请只选中一个待登记联动空间副本。' unless selected.length == 1 && pending.length == 1
      entity = pending.first
      source_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_source_space_id', '').to_s
      source_id = entity.get_attribute(ENTITY_DICT, 'linked_source_space_id', '').to_s if source_id.empty?
      state = ensure_space_models_ready!(model)
      source = canonical_space_record(state, source_id)
      raise '该副本的联动来源已缺失，请删除后重新复制。' unless source
      raise '联动空间变换已退化（某个缩放轴接近 0），请恢复有效尺寸后再完成。' unless supported_linked_space_transformation?(entity.transformation)
      default_name = suggested_linked_space_name(state, source)
      response = UI.inputbox(['模型空间名称'], [default_name], '登记联动空间副本')
      return false unless response
      parsed = parse_structured_space_name(response[0], default_collection: space_record_collection_key(source))
      name = parsed['name'].to_s
      raise '空间名称不能为空。' if name.empty?
      collection_key = normalize_space_collection_key(parsed['collection_key'], space_record_collection_key(source))
      raise '联动空间必须与来源空间属于同一专业。' unless collection_key == space_record_collection_key(source)
      duplicate = Array(state['space_models']).any? do |item|
        space_record_collection_key(item) == collection_key && item['name'].to_s.casecmp(name).zero?
      end
      raise "#{space_collection_label(collection_key)}空间名称“#{name}”已经存在，请使用不同名称。" if duplicate

      temp_id = entity.get_attribute(ENTITY_DICT, 'linked_pending_temp_id', '').to_s
      temp_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if temp_id.empty?
      temp_id = SecureRandom.uuid if temp_id.empty?
      operation_open = false
      model.start_operation("登记联动空间 #{name}", true)
      operation_open = true
      item = default_space_model(next_space_number!(state), name, source['model_path'])
      item['id'] = temp_id
      item['collection_key'] = collection_key
      item['group_id'] = parsed['group_name'].to_s.empty? ? source['group_id'].to_s : ensure_named_space_group!(state, parsed['group_name'])
      item['linked_source_space_id'] = source['id'].to_s
      item['linked_source_name'] = source['name'].to_s
      item['linked_transform'] = entity.transformation.to_a.map(&:to_f)
      item['last_signature'] = source['last_signature'].to_s
      item['source_revision'] = source['source_revision'].to_s
      item['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['status'] = "联动于（#{source['name']}）"
      representation = entity.get_attribute(ENTITY_DICT, 'space_representation', state['space_display_mode']).to_s
      mark_space_model_entity!(
        entity, item, source['model_path'].to_s, source['last_signature'].to_s, model,
        representation: representation, revision: source['source_revision'].to_s,
        preserve_transformation: true,
        verified_package_revision: source['source_revision'].to_s,
        verified_package_identity: "linked-#{source['id']}"
      )
      clear_pending_linked_space_clone_attributes!(entity)
      entity.name = "#{item['number']}:#{item['name']}.skp" if entity.respond_to?(:name=)
      entity.locked = true if entity.respond_to?(:locked=)
      state['space_models'] << item
      normalize_space_models_state!(state, model)
      save_state(state, model, write_manifest: false)
      write_space_models_manifest!(state, model, preserve_remote_layout: true, local_space_ids: [item['id']])
      model.commit_operation
      operation_open = false
      invalidate_managed_root_index(model, reason: 'linked_space_pending_finish')
      model.selection.clear
      model.selection.add(entity)
      mark_soft_measurement_dirty(model)
      refresh_dialog
      refresh_workspace_toolbar(model, detailed: true)
      remaining = pending_linked_space_clones(model).length
      suffix = remaining.positive? ? "；还有 #{remaining} 个待登记副本，继续选中后点顶部对勾" : ''
      show_status("已登记联动空间 #{item['number']}:#{item['name']}，联动于（#{source['name']}）#{suffix}。", 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    end

    def linked_space_copy_transform_changed(model, entity = nil)
      record = linked_space_copy_record(model)
      return false unless record
      target = entity && entity.valid? ? entity : record[:entity]
      return false unless target && target.valid?
      record[:transformation] = target.transformation.to_a.map(&:to_f)
      true
    rescue StandardError
      false
    end

    def linked_space_copy_transaction_committed(model = Sketchup.active_model)
      record = linked_space_copy_record(model)
      selected_pending = model && model.respond_to?(:selection) && model.selection.to_a.any? { |entity| pending_linked_space_clone?(entity) }
      return false unless record || selected_pending || pending_linked_space_watch_active?(model)
      linked_space_copy_transform_changed(model) if record
      # 原生 Move/Rotate/Scale 提交后只安排一次极轻量整理；同 key 会合并连续事务。
      runtime_start_timer(
        0.06, false, label: 'linked_space:transform_refresh',
        key: "linked_space:transform_refresh:#{model.object_id}", model: model, active_model_only: true
      ) do
        with_internal_sync_guard do
          changed = reconcile_linked_space_native_copies!(model)
          refresh_workspace_toolbar(model, selection_fast: true) unless changed
        end
      end
      true
    rescue StandardError
      false
    end

    def linked_space_copy_base_point_selected(model, entity, position)
      record = linked_space_copy_record(model)
      return false unless record
      if entity
        return false unless record[:entity] == entity && entity.valid?
      else
        return false unless record[:source_entity] && record[:source_entity].valid?
      end
      record[:phase] = 'target_point'
      record[:base_point] = [position.x.to_f, position.y.to_f, position.z.to_f] if position
      refresh_workspace_toolbar(model)
      true
    rescue StandardError
      false
    end

    # v0.13.6.157：第二击确认位置后，第一份副本立刻转成普通“待登记联动副本”，
    # 并立即结束 @linked_space_copy_placements。之后不再维持一个全局“当前复制对象”；
    # Move/Rotate/Scale/Move+Ctrl 都由 SketchUp 原生工具负责，顶部对勾永远以当前选择
    # 的 pending 实例为准，因此不会出现“选第二个却登记了第一个”。
    def linked_space_copy_initial_placement_finished(model, entity = nil, transformation = nil)
      record = linked_space_copy_record(model)
      return false unless record
      state = ensure_space_models_ready!(model)
      source = canonical_space_record(state, record[:source_id])
      raise '来源空间已不存在，不能完成联动复制。' unless source
      if entity && entity.valid?
        target = entity
      else
        source_entity = record[:source_entity]
        return false unless source_entity && source_entity.valid?
        transform = transformation || begin
          values = Array(record[:transformation]).map(&:to_f)
          values.length == 16 ? Geom::Transformation.new(values) : source_entity.transformation
        end
        operation_open = false
        model.start_operation('放置联动空间副本', true)
        operation_open = true
        target = model.entities.add_instance(source_entity.definition, transform)
        raise 'SketchUp 未能创建联动空间副本。' unless target && target.valid?
        copy_entity_attribute_dictionaries!(source_entity, target)
        copy_instance_visual_properties!(source_entity, target)
        unless convert_linked_native_clone_to_pending!(target, source, source['id'].to_s, model, temp_id: record[:temp_id].to_s)
          raise '无法把联动空间副本登记为待命名状态。'
        end
        model.commit_operation
        operation_open = false
      end
      # 如果调用方传入了现成实体，也统一确保它进入 pending，而不是继续占用 placement record。
      if entity && entity.valid? && !pending_linked_space_clone?(target)
        operation_open = false
        model.start_operation('标记联动空间待登记副本', true)
        operation_open = true
        raise '无法把联动空间副本登记为待命名状态。' unless convert_linked_native_clone_to_pending!(target, source, source['id'].to_s, model, temp_id: record[:temp_id].to_s)
        model.commit_operation
        operation_open = false
      end
      @linked_space_copy_placements&.delete(model.object_id)
      invalidate_managed_root_index(model, reason: 'linked_space_copy_placed_pending')
      model.selection.clear
      model.selection.add(target)
      refresh_workspace_toolbar(model, selection_fast: true)
      show_status('副本已进入待登记状态；可直接移动/旋转/缩放/镜像，Move+Ctrl 可继续复制。选中任一副本点顶部对勾命名。', 'info')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      @linked_space_copy_placements&.delete(model.object_id) if model
      log_exception('完成联动空间初次放置失败', e)
      false
    end

    # v0.13.6.148：联动空间继续保留完整实例矩阵。负行列式就是合法镜像，轴长变化
    # 就是合法缩放；同步来源 Definition 时只替换 Definition，再恢复 linked_transform，
    # 因此不应再把镜像/非均匀缩放误判为非法。这里只拒绝退化到零体积的矩阵。
    def supported_linked_space_transformation?(transformation)
      return false unless transformation
      axes = [transformation.xaxis, transformation.yaxis, transformation.zaxis]
      return false unless axes.all? { |axis| axis && axis.length.to_f > 1.0e-7 }
      determinant = axes[0].cross(axes[1]).dot(axes[2]).to_f
      determinant.abs > 1.0e-9
    rescue StandardError
      false
    end

    def suggested_linked_space_name(state, source)
      base = "#{source['name']} 副本"
      candidate = base
      index = 2
      used = Array(state['space_models']).map { |item| item['name'].to_s.downcase }
      while used.include?(candidate.downcase)
        candidate = "#{base} #{index}"
        index += 1
      end
      candidate
    rescue StandardError
      '联动空间'
    end

    # v0.13.6.160：第一次联动复制不再用 Ruby 自定义 InputPoint 工具去“模仿”
    # SketchUp Move。直接先建立一个与来源重合的轻量组件实例，登记成待命名联动副本，
    # 然后激活 SketchUp 原生 MoveTool。基点、目标点、端点/中点/交点推断、轴向锁定、
    # Shift 推断锁以及中键临时 Orbit 全部由 SketchUp 自己处理，手感与用户平时 M / Ctrl
    # 移动复制一致；LinkHub 只负责身份和后续命名，不再参与逐帧捕捉。
    def begin_linked_space_copy!(space_id, model = Sketchup.active_model)
      raise '请先退出所有组件编辑层级，再复制空间。' unless model.active_path.nil?
      raise '已有一个联动空间正在调整，请先点击顶部对勾完成。' if linked_space_copy_active?(model)
      raise '发布或更新正在执行，请等待完成后再复制空间。' if publish_critical_section? || publish_post_quiet? || @updating || @single_space_update_job || @space_batch_update_job
      ensure_soft_ingest_batch_not_writing!('复制空间')
      state = ensure_space_models_ready!(model)
      selected = space_model_record(state, space_id)
      raise '找不到要复制的空间。' unless selected
      source = canonical_space_record(state, selected)
      raise '该空间的联动来源已缺失，请先刷新协同清单。' unless source
      source_entity = space_model_entity(selected['id'], model)
      source_entity ||= space_model_entity(source['id'], model)
      raise '请先载入要复制的空间。' unless source_entity && source_entity.valid?
      raise '正在修改或后台发布的空间暂时不能复制。' if local_space_edit_session?(source, state, model) || background_publish_active_state?(source)

      temp_id = SecureRandom.uuid
      target = nil
      operation_open = false
      model.start_operation('建立联动空间原生移动副本', true)
      operation_open = true
      target = model.entities.add_instance(source_entity.definition, source_entity.transformation)
      raise 'SketchUp 未能创建联动空间副本。' unless target && target.valid?
      copy_entity_attribute_dictionaries!(source_entity, target)
      copy_instance_visual_properties!(source_entity, target)
      unless convert_linked_native_clone_to_pending!(target, source, source['id'].to_s, model, temp_id: temp_id)
        raise '无法把联动空间副本登记为待命名状态。'
      end
      model.commit_operation
      operation_open = false

      invalidate_managed_root_index(model, reason: 'linked_space_native_move_begin')
      # 选中 pending 会触发 SelectionObserver；先压住双击桥，避免它在 MoveTool 激活后
      # 又 push 回一个临时 Ruby Tool，破坏原生移动手感。
      suppress_workspace_double_click_rearm!(model, seconds: 0.8)
      model.selection.clear
      model.selection.add(target)
      refresh_workspace_toolbar(model, selection_fast: true)
      schedule_coalesced_refresh_dialog(0.08)

      # send_action 是 SketchUp 目前仍可用于激活原生 MoveTool 的入口。它是异步的，
      # 因此在极短 timer 中执行，让当前 selection/operation 回调先完全退栈。
      runtime_start_timer(
        0.02, false, label: 'linked_space:native_move_tool',
        key: "linked_space:native_move_tool:#{model.object_id}", model: model, active_model_only: true
      ) do
        next unless target && target.valid?
        suppress_workspace_double_click_rearm!(model, seconds: 0.8)
        model.selection.clear
        model.selection.add(target)
        activated = Sketchup.send_action('selectMoveTool:') rescue false
        unless activated
          show_status('联动副本已建立；请按 M 使用 SketchUp 原生移动工具选择基点和目标点。', 'warning')
        end
      end
      show_status("已建立 #{source['number']}:#{source['name']} 的待命名副本；现在直接按 SketchUp 原生 Move 方式点基点、点目标点。可用 Shift/方向键/中键 Orbit，Ctrl 可继续复制。", 'info')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      begin
        target.erase! if target && target.valid? && defined?(operation_open) && operation_open
      rescue StandardError
        nil
      end
      raise
    end

    def finish_linked_space_copy!(model = Sketchup.active_model)
      raise '请先退出组件内部，再完成联动复制。' unless model.active_path.nil?
      record = linked_space_copy_record(model)
      raise '当前没有待完成的联动空间。' unless record
      if record[:mode].to_s == 'transform'
        return save_linked_space_transform_record!(record, model, notify: true, reason: '顶部对勾确认')
      end
      raise '请先在视口中选择基准点和目标点完成复制。' unless record[:phase].to_s == 'adjusting'
      entity = record[:entity]
      raise '待完成的联动空间已不存在。' unless entity && entity.valid?
      raise '联动空间变换已退化（某个缩放轴接近 0），请恢复有效尺寸后再完成。' unless supported_linked_space_transformation?(entity.transformation)
      state = ensure_space_models_ready!(model)
      source = canonical_space_record(state, record[:source_id])
      raise '来源空间已不存在，不能完成联动复制。' unless source
      default_name = suggested_linked_space_name(state, source)
      response = UI.inputbox(['模型空间名称'], [default_name], '完成联动空间')
      return false unless response
      parsed = parse_structured_space_name(response[0], default_collection: space_record_collection_key(source))
      name = parsed['name'].to_s
      raise '空间名称不能为空。' if name.empty?
      collection_key = normalize_space_collection_key(parsed['collection_key'], space_record_collection_key(source))
      raise '联动空间必须与来源空间属于同一专业。' unless collection_key == space_record_collection_key(source)
      duplicate = Array(state['space_models']).any? do |item|
        space_record_collection_key(item) == collection_key && item['name'].to_s.casecmp(name).zero?
      end
      raise "#{space_collection_label(collection_key)}空间名称“#{name}”已经存在，请使用不同名称。" if duplicate

      operation_open = false
      model.start_operation("完成联动空间 #{name}", true)
      operation_open = true
      item = default_space_model(next_space_number!(state), name, source['model_path'])
      item['id'] = record[:temp_id].to_s
      item['collection_key'] = collection_key
      item['group_id'] = parsed['group_name'].to_s.empty? ? source['group_id'].to_s : ensure_named_space_group!(state, parsed['group_name'])
      item['linked_source_space_id'] = source['id'].to_s
      item['linked_source_name'] = source['name'].to_s
      item['linked_transform'] = entity.transformation.to_a.map(&:to_f)
      item['last_signature'] = source['last_signature'].to_s
      item['source_revision'] = source['source_revision'].to_s
      item['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['status'] = "联动于（#{source['name']}）"
      representation = entity.get_attribute(ENTITY_DICT, 'space_representation', state['space_display_mode']).to_s
      mark_space_model_entity!(
        entity, item, source['model_path'].to_s, source['last_signature'].to_s, model,
        representation: representation, revision: source['source_revision'].to_s,
        preserve_transformation: true,
        verified_package_revision: source['source_revision'].to_s,
        verified_package_identity: "linked-#{source['id']}"
      )
      entity.name = "#{item['number']}:#{item['name']}.skp" if entity.respond_to?(:name=)
      entity.locked = true if entity.respond_to?(:locked=)
      state['space_models'] << item
      normalize_space_models_state!(state, model)
      save_state(state, model, write_manifest: false)
      write_space_models_manifest!(state, model, preserve_remote_layout: true, local_space_ids: [item['id']])
      model.commit_operation
      operation_open = false
      @linked_space_copy_placements.delete(model.object_id)
      invalidate_managed_root_index(model, reason: 'linked_space_copy_finish')
      model.selection.clear
      model.selection.add(entity)
      mark_soft_measurement_dirty(model)
      refresh_dialog
      refresh_workspace_toolbar(model, detailed: true)
      show_status("已建立联动空间 #{item['number']}:#{item['name']}，联动于（#{source['name']}）。", 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    end

    def cancel_linked_space_copy!(model = Sketchup.active_model, reason: '取消复制')
      record = linked_space_copy_record(model)
      return false unless record
      entity = record[:entity]
      operation_open = false
      if entity && entity.valid?
        model.start_operation('取消联动空间复制', true)
        operation_open = true
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase!
        model.commit_operation
        operation_open = false
        invalidate_managed_root_index(model, reason: 'linked_space_copy_cancel')
      end
      @linked_space_copy_placements.delete(model.object_id)
      refresh_workspace_toolbar(model)
      show_status("已取消联动空间复制（#{reason}）。", 'info')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      @linked_space_copy_placements&.delete(model.object_id) if model
      false
    end

    def sync_linked_space_instances_for_source!(state, source_item, source_entity, model = Sketchup.active_model)
      source = canonical_space_record(state, source_item)
      return 0 unless source && source_entity && source_entity.valid?
      dependents = linked_space_dependents(state, source['id'])
      return 0 if dependents.empty?
      representation = source_entity.get_attribute(ENTITY_DICT, 'space_representation', state['space_display_mode']).to_s
      signature = source['last_signature'].to_s
      revision = source['source_revision'].to_s
      count = 0
      dependents.each do |item|
        linked = space_model_entity(item['id'], model)
        transform_values = Array(item['linked_transform']).map(&:to_f)
        transformation = transform_values.length == 16 ? Geom::Transformation.new(transform_values) : identity_transformation
        # v0.13.6.190：来源空间载入/发布收尾同步联动副本时，正在“实例调整”的那一个
        # 保留当前位置且保持解锁；过去会被强制弹回上次保存的位置并锁上。
        adjusting_linked = linked && linked.valid? && linked_space_transform_adjustment_active?(item, linked, model)
        transformation = linked.transformation if adjusting_linked
        if linked && linked.valid?
          was_locked = linked.respond_to?(:locked?) ? linked.locked? : true
          linked.locked = false if linked.respond_to?(:locked=)
          linked.definition = source_entity.definition unless linked.definition == source_entity.definition
          linked.transformation = transformation
          linked.locked = was_locked if linked.respond_to?(:locked=)
        else
          linked = model.entities.add_instance(source_entity.definition, transformation)
        end
        item['model_path'] = source['model_path'].to_s
        item['last_signature'] = signature
        item['source_revision'] = revision
        item['linked_source_name'] = source['name'].to_s
        item['status'] = "联动于（#{source['name']}）"
        mark_space_model_entity!(
          linked, item, source['model_path'].to_s, signature, model,
          representation: representation, revision: revision,
          invalidate_index: false, preserve_transformation: true,
          verified_package_revision: revision,
          verified_package_identity: "linked-#{source['id']}"
        )
        linked.name = "#{item['number']}:#{item['name']}.skp" if linked.respond_to?(:name=)
        linked.locked = (adjusting_linked ? false : true) if linked.respond_to?(:locked=)
        count += 1
      rescue StandardError => e
        log_exception("同步联动空间失败：#{item && item['id']}", e)
      end
      invalidate_managed_root_index(model, reason: 'linked_space_sync') if count.positive?
      mark_soft_measurement_dirty(model) if count.positive?
      count
    rescue StandardError => e
      log_exception('同步联动空间失败', e)
      0
    end

    def space_models_project_dir(state, model = Sketchup.active_model)
      selected_collab_project_dir_for_state(state, model).to_s
    rescue StandardError
      ''
    end

    def space_models_root(state, model = Sketchup.active_model)
      project_dir = space_models_project_dir(state, model)
      return '' if project_dir.empty?
      File.join(project_dir, COLLAB_FOLDER_NAME, SPACE_MODELS_FOLDER)
    end

    def space_models_assets_dir(state, model = Sketchup.active_model)
      root = space_models_root(state, model)
      root.empty? ? '' : File.join(root, '空间模型')
    end

    def space_models_manifest_path(state, model = Sketchup.active_model)
      root = space_models_root(state, model)
      root.empty? ? '' : File.join(root, SPACE_MODELS_MANIFEST)
    end

    def space_groups_manifest_path(state, model = Sketchup.active_model)
      root = space_models_root(state, model)
      root.empty? ? '' : File.join(root, SPACE_GROUPS_MANIFEST)
    end

    def manifest_space_path(project_dir, path)
      expanded = FastPath.expand(path.to_s)
      base = FastPath.expand(project_dir.to_s)
      relative = Pathname.new(expanded).relative_path_from(Pathname.new(base)).to_s.tr('\\', '/')
      relative.start_with?('../') ? expanded : relative
    rescue ArgumentError
      expanded.to_s.empty? ? path.to_s : expanded
    rescue StandardError
      path.to_s
    end

    def with_space_manifest_write_lock(path, timeout: 4.0)
      lock_path = "#{path}.sulink-write.lock"
      deadline = monotonic_time + timeout.to_f
      acquired = false
      loop do
        begin
          File.open(lock_path, File::WRONLY | File::CREAT | File::EXCL) do |io|
            io.write(JSON.generate({
              'pid' => Process.pid,
              'host' => current_host_name,
              'user' => current_user_name,
              'created_at' => Time.now.iso8601(6)
            }))
          end
          acquired = true
          break
        rescue Errno::EEXIST
          begin
            age = Time.now.to_f - File.mtime(lock_path).to_f
            File.delete(lock_path) if age > 20.0
          rescue StandardError
            nil
          end
          raise '空间模型清单正由其他成员写入，请稍后重试。' if monotonic_time >= deadline
          sleep(0.06)
        end
      end
      yield
    ensure
      File.delete(lock_path) if acquired && File.file?(lock_path)
    end

    def write_space_groups_manifest!(state, model = Sketchup.active_model, include_initial_space_ids: [])
      path = space_groups_manifest_path(state, model)
      return false if path.to_s.empty?
      FileUtils.mkdir_p(File.dirname(path))
      with_space_manifest_write_lock(path) do
        # 首次发布尚未成功写入共享 SKP 的空间是纯本地记录，不能因为用户操作其他组
        # 就被空间组清单提前泄漏到共享端。共享组真相源只包含已经完成首次发布的空间。
        allowed_initial_ids = Array(include_initial_space_ids).map(&:to_s).reject(&:empty?).each_with_object({}) { |id, memo| memo[id] = true }
        shared_space_rows = Array(state['space_models']).select do |item|
          item.is_a?(Hash) && !item['id'].to_s.empty? &&
            (!initial_space_publish_pending?(item) || allowed_initial_ids[item['id'].to_s])
        end
        valid_ids = shared_space_rows.each_with_object({}) { |item, memo| memo[item['id'].to_s] = true }
        shared_group_ids = shared_space_rows.each_with_object({}) do |item, memo|
          gid = item['group_id'].to_s
          memo[gid] = true unless gid.empty?
        end
        payload = {
          'schema' => SPACE_GROUPS_SCHEMA,
          'kind' => 'sulink_space_groups',
          'plugin_version' => EXTENSION_VERSION,
          'layout_revision' => state['space_layout_revision'].to_s,
          'updated_at' => state['space_layout_updated_at'].to_s.empty? ? Time.now.iso8601(6) : state['space_layout_updated_at'].to_s,
          'updated_by' => state['space_layout_updated_by'].to_s,
          'updated_host' => state['space_layout_updated_host'].to_s,
          'groups' => Array(state['space_groups']).select { |group| shared_group_ids[group['id'].to_s] }.sort_by { |group| group['order'].to_i }.map do |group|
            { 'id' => group['id'].to_s, 'name' => group['name'].to_s, 'order' => group['order'].to_i }
          end,
          'spaces' => shared_space_rows.filter_map do |item|
            next unless item.is_a?(Hash) && valid_ids[item['id'].to_s]
            { 'id' => item['id'].to_s, 'group_id' => item['group_id'].to_s, 'group_order' => item['group_order'].to_i }
          end
        }
        temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
        linkhub_mv(temp, path)
        @space_groups_manifest_cache ||= {}
        @space_groups_manifest_cache[FastPath.expand(path)] = { signature: small_file_content_signature(path), data: payload }
      ensure
        File.delete(temp) if defined?(temp) && temp && File.file?(temp)
      end
      true
    end

    def sync_space_groups_from_manifest!(state, model = Sketchup.active_model)
      path = space_groups_manifest_path(state, model)
      return false unless !path.to_s.empty? && File.file?(path)
      key = FastPath.expand(path)
      signature = small_file_content_signature(path)
      @space_groups_manifest_cache ||= {}
      cached = @space_groups_manifest_cache[key]
      data = if cached.is_a?(Hash) && cached[:signature].to_s == signature
               cached[:data]
             else
               parsed = JSON.parse(File.read(path, mode: 'rb'))
               @space_groups_manifest_cache[key] = { signature: signature, data: parsed }
               parsed
             end
      return false unless data.is_a?(Hash) && data['kind'].to_s == 'sulink_space_groups'

      local_groups_before_sync = Array(state['space_groups']).select { |group| group.is_a?(Hash) }.map { |group| deep_dup_runtime_value(group) }
      pending_local_group_ids = Array(state['space_models']).each_with_object({}) do |item, memo|
        next unless item.is_a?(Hash) && initial_space_publish_pending?(item)
        gid = item['group_id'].to_s
        memo[gid] = true unless gid.empty?
      end
      local_preferences = local_groups_before_sync.each_with_object({}) do |group, memo|
        next unless group.is_a?(Hash)
        memo[group['id'].to_s] = {
          'collapsed' => !!group['collapsed'],
          'visibility_suspended' => !!group['visibility_suspended'],
          'visibility_restore_ids' => Array(group['visibility_restore_ids']).map(&:to_s).reject(&:empty?).uniq,
          'collection_visibility' => group['collection_visibility'].is_a?(Hash) ? deep_dup_runtime_value(group['collection_visibility']) : {}
        }
      end
      groups = Array(data['groups']).filter_map do |raw|
        next unless raw.is_a?(Hash)
        id = raw['id'].to_s.strip
        next if id.empty?
        pref = local_preferences[id] || {}
        {
          'id' => id,
          'name' => raw['name'].to_s,
          'order' => raw['order'].to_i,
          'collapsed' => pref.key?('collapsed') ? !!pref['collapsed'] : true,
          'visibility_suspended' => !!pref['visibility_suspended'],
          'visibility_restore_ids' => Array(pref['visibility_restore_ids']).dup,
          'collection_visibility' => pref['collection_visibility'].is_a?(Hash) ? deep_dup_runtime_value(pref['collection_visibility']) : {}
        }
      end
      remote_group_ids = groups.each_with_object({}) { |group, memo| memo[group['id'].to_s] = true }
      local_groups_before_sync.each do |group|
        gid = group['id'].to_s
        next if gid.empty? || remote_group_ids[gid] || !pending_local_group_ids[gid]
        groups << group
        remote_group_ids[gid] = true
      end
      memberships = Array(data['spaces']).each_with_object({}) do |raw, memo|
        next unless raw.is_a?(Hash)
        id = raw['id'].to_s
        next if id.empty?
        memo[id] = [raw['group_id'].to_s, raw['group_order'].to_i]
      end
      group_ids = groups.each_with_object({}) { |group, memo| memo[group['id'].to_s] = true }
      Array(state['space_models']).each do |item|
        next unless item.is_a?(Hash)
        membership = memberships[item['id'].to_s]
        if membership
          item['group_id'] = group_ids[membership[0]] ? membership[0] : ''
          item['group_order'] = membership[1]
        else
          # 首次发布纯本地空间没有共享 membership；保留它自己的本地组归属。
          item['group_id'] = '' unless initial_space_publish_pending?(item) || group_ids[item['group_id'].to_s]
        end
      end
      state['space_groups'] = groups
      state['space_layout_revision'] = data['layout_revision'].to_s
      state['space_layout_updated_at'] = data['updated_at'].to_s
      state['space_layout_updated_by'] = data['updated_by'].to_s
      state['space_layout_updated_host'] = data['updated_host'].to_s
      normalize_space_models_state!(state, model)
      true
    rescue JSON::ParserError => e
      log_exception('读取共享空间分组清单失败', e)
      false
    rescue StandardError => e
      log_exception('同步共享空间分组失败', e)
      false
    end

    # 所有空间清单写入都经过跨进程短锁。空间清单同时承载两类彼此独立的数据：
    # 1) 分组、排序等布局层；2) 发布 revision/signature/path 等内容层。
    # 写入前必须在同一把跨进程锁内合并另一层的共享最新值，否则一次成组就可能
    # 覆盖其他成员刚发布的 revision，或一次长耗时发布又把刚完成的分组覆盖回去。
    def write_space_models_manifest!(
      state,
      model = Sketchup.active_model,
      preserve_remote_publish_metadata: false,
      preserve_remote_layout: false,
      local_space_ids: [],
      deleted_space_ids: [],
      include_initial_space_ids: []
    )
      path = space_models_manifest_path(state, model)
      return false if path.empty?
      FileUtils.mkdir_p(File.dirname(path))
      with_space_manifest_write_lock(path) do
        if File.file?(path)
          if preserve_remote_publish_metadata
            merge_latest_space_publish_metadata!(state, model)
          elsif preserve_remote_layout
            merge_latest_space_manifest_for_content_write!(
              state,
              model,
              local_space_ids: local_space_ids,
              deleted_space_ids: deleted_space_ids
            )
          end
        end
        write_space_models_manifest_unlocked!(
          state, model, include_initial_space_ids: include_initial_space_ids
        )
      end
    end

    def write_space_models_manifest_unlocked!(state, model = Sketchup.active_model, include_initial_space_ids: [])
      path = space_models_manifest_path(state, model)
      return false if path.empty?
      project_dir = space_models_project_dir(state, model)
      FileUtils.mkdir_p(File.dirname(path))
      allowed_initial_ids = Array(include_initial_space_ids).map(&:to_s).reject(&:empty?).each_with_object({}) { |id, memo| memo[id] = true }
      manifest_space_rows = Array(state['space_models']).select do |item|
        next false unless item.is_a?(Hash)
        !initial_space_publish_pending?(item) || allowed_initial_ids[item['id'].to_s]
      end
      manifest_group_ids = manifest_space_rows.each_with_object({}) do |item, memo|
        gid = item['group_id'].to_s
        memo[gid] = true unless gid.empty?
      end
      payload = {
        'schema' => SPACE_MODELS_SCHEMA,
        'kind' => 'sulink_space_models',
        'plugin_version' => EXTENSION_VERSION,
        'collection' => SPACE_COLLECTION_NAME,
        'updated_at' => Time.now.iso8601,
        'layout_revision' => state['space_layout_revision'].to_s,
        'layout_updated_at' => state['space_layout_updated_at'].to_s,
        'layout_updated_by' => state['space_layout_updated_by'].to_s,
        'layout_updated_host' => state['space_layout_updated_host'].to_s,
        'groups' => Array(state['space_groups']).select { |group| manifest_group_ids[group['id'].to_s] }.sort_by { |group| group['order'].to_i }.map do |group|
          {
            'id' => group['id'].to_s,
            'name' => group['name'].to_s,
            'order' => group['order'].to_i
          }
        end,
        'spaces' => manifest_space_rows.sort_by { |item| [item['group_id'].to_s, item['group_order'].to_i, item['number'].to_i] }.map do |item|
          # 发布收尾只使用项目已保存的确定路径。路径失效时明确记为缺失，
          # 不在界面等待期间递归搜索整个项目目录。
          resolved = resolve_path(item['model_path'].to_s, model)
          {
            'id' => item['id'].to_s,
            'number' => item['number'].to_i,
            'name' => item['name'].to_s,
            'collection_key' => space_record_collection_key(item),
            'group_id' => item['group_id'].to_s,
            'group_order' => item['group_order'].to_i,
            'file' => resolved.to_s.empty? ? '' : manifest_space_path(project_dir, resolved),
            'signature' => item['last_signature'].to_s.empty? && File.file?(resolved) ? fast_file_signature(resolved) : item['last_signature'].to_s,
            'revision' => item['source_revision'].to_s,
            'published_at' => item['last_publish_at'].to_s,
            'published_by' => item['last_publish_by'].to_s,
            'published_host' => item['last_publish_host'].to_s,
            'publish_plugin_version' => item['last_publish_plugin_version'].to_s,
            'component_bundle_id' => item['component_bundle_id'].to_s,
            'component_bundle_state' => item['component_bundle_state'].to_s,
            'component_bundle_started_at' => item['component_bundle_started_at'].to_s,
            'component_bundle_completed_at' => item['component_bundle_completed_at'].to_s,
            'component_bundle_dependencies' => Array(item['component_bundle_dependencies']).map do |row|
              next unless row.is_a?(Hash)
              {
                'id' => row['id'].to_s,
                'name' => row['name'].to_s,
                'content_signature' => row['content_signature'].to_s
              }
            end.compact,
            'linked_source_space_id' => item['linked_source_space_id'].to_s,
            'linked_source_name' => item['linked_source_name'].to_s,
            'linked_transform' => Array(item['linked_transform']).map(&:to_f),
            'soft_representation_schema' => 1
          }
        end
      }
      temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(temp, path)
      @space_manifest_data_cache ||= {}
      @space_manifest_data_cache[FastPath.expand(path)] = {
        signature: small_file_content_signature(path),
        data: payload
      }
      true
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def resolve_space_manifest_file(project_dir, value)
      text = value.to_s
      return '' if text.empty?
      if absolute_file_path?(text) || (Pathname.new(text).absolute? rescue false)
        FastPath.expand(text)
      else
        FastPath.expand(text, project_dir)
      end
    rescue StandardError
      value.to_s
    end

    def sync_space_models_from_manifest!(state, model = Sketchup.active_model, verify_files: true)
      path = space_models_manifest_path(state, model)
      return false unless !path.empty? && File.file?(path)
      manifest_key = FastPath.expand(path)
      manifest_signature = small_file_content_signature(path)
      @space_manifest_data_cache ||= {}
      cached_manifest = @space_manifest_data_cache[manifest_key]
      data = if cached_manifest.is_a?(Hash) && cached_manifest[:signature].to_s == manifest_signature
               cached_manifest[:data]
             else
               parsed = JSON.parse(File.read(path, mode: 'rb'))
               @space_manifest_data_cache[manifest_key] = { signature: manifest_signature, data: parsed }
               parsed
             end
      return false unless data.is_a?(Hash) && data['kind'].to_s == 'sulink_space_models'
      project_dir = space_models_project_dir(state, model)
      local_groups_before_sync = Array(state['space_groups']).select { |group| group.is_a?(Hash) }.map { |group| deep_dup_runtime_value(group) }
      pending_local_group_ids = Array(state['space_models']).each_with_object({}) do |item, memo|
        next unless item.is_a?(Hash) && initial_space_publish_pending?(item)
        gid = item['group_id'].to_s
        memo[gid] = true unless gid.empty?
      end
      local_group_preferences = local_groups_before_sync.each_with_object({}) do |group, memo|
        next unless group.is_a?(Hash)
        memo[group['id'].to_s] = {
          'collapsed' => !!group['collapsed'],
          'visibility_suspended' => !!group['visibility_suspended'],
          'visibility_restore_ids' => Array(group['visibility_restore_ids']).map(&:to_s).reject(&:empty?).uniq,
          'collection_visibility' => group['collection_visibility'].is_a?(Hash) ? deep_dup_runtime_value(group['collection_visibility']) : {}
        }
      end
      manifest_groups = Array(data['groups']).filter_map do |raw|
        next unless raw.is_a?(Hash)
        id = raw['id'].to_s.strip
        next if id.empty?
        {
          'id' => id,
          'name' => raw['name'].to_s,
          'order' => raw['order'].to_i,
          # 折叠与组显隐快照属于每台电脑的浏览偏好，不写入共享清单，
          # 避免一名成员展开、隐藏组时影响其他协作者。
          'collapsed' => local_group_preferences.key?(id) ? !!local_group_preferences[id]['collapsed'] : true,
          'visibility_suspended' => local_group_preferences.key?(id) ? !!local_group_preferences[id]['visibility_suspended'] : false,
          'visibility_restore_ids' => local_group_preferences.key?(id) ? Array(local_group_preferences[id]['visibility_restore_ids']).dup : [],
          'collection_visibility' => local_group_preferences.key?(id) && local_group_preferences[id]['collection_visibility'].is_a?(Hash) ? deep_dup_runtime_value(local_group_preferences[id]['collection_visibility']) : {}
        }
      end
      if data.key?('groups')
        remote_group_ids = manifest_groups.each_with_object({}) { |group, memo| memo[group['id'].to_s] = true }
        local_groups_before_sync.each do |group|
          gid = group['id'].to_s
          next if gid.empty? || remote_group_ids[gid] || !pending_local_group_ids[gid]
          manifest_groups << group
        end
        state['space_groups'] = manifest_groups
      end
      local = Array(state['space_models']).each_with_object({}) { |item, memo| memo[item['id'].to_s] = item if item.is_a?(Hash) }
      imported = Array(data['spaces']).map do |raw|
        next unless raw.is_a?(Hash)
        id = raw['id'].to_s.strip
        id = SecureRandom.uuid if id.empty?
        existing = local[id] || {}
        resolved = resolve_space_manifest_file(project_dir, raw['file'])
        item = default_space_model(raw['number'], raw['name'], resolved.empty? ? '' : store_path(resolved, model))
        item.merge!(existing)
        item['id'] = id
        item['number'] = raw['number'].to_i
        item['number'] = 1 unless item['number'].positive?
        item['name'] = normalize_space_name(raw['name'])
        item['name'] = '未命名空间' if item['name'].empty?
        item['collection_key'] = normalize_space_collection_key(raw['collection_key'], item['collection_key']) if raw.key?('collection_key')
        item['group_id'] = raw['group_id'].to_s if raw.key?('group_id')
        item['group_order'] = raw['group_order'].to_i if raw.key?('group_order')
        item['model_path'] = resolved.empty? ? '' : store_path(resolved, model)
        item['last_signature'] = raw['signature'].to_s unless raw['signature'].to_s.empty?
        raw_revision = raw['revision'].to_s
        # Older publishers do not write revision. Their published_at/signature remain a
        # compatibility revision until that member upgrades and publishes once.
        item['source_revision'] = raw_revision.empty? ? ['space-legacy', raw['published_at'].to_s, raw['signature'].to_s].join('|') : raw_revision
        item['last_publish_at'] = raw['published_at'].to_s unless raw['published_at'].to_s.empty?
        item['last_publish_by'] = raw['published_by'].to_s unless raw['published_by'].to_s.empty?
        item['last_publish_host'] = raw['published_host'].to_s unless raw['published_host'].to_s.empty?
        item['last_publish_plugin_version'] = raw['publish_plugin_version'].to_s unless raw['publish_plugin_version'].to_s.empty?
        item['component_bundle_id'] = raw['component_bundle_id'].to_s if raw.key?('component_bundle_id')
        item['component_bundle_state'] = raw['component_bundle_state'].to_s if raw.key?('component_bundle_state')
        item['component_bundle_started_at'] = raw['component_bundle_started_at'].to_s if raw.key?('component_bundle_started_at')
        item['component_bundle_completed_at'] = raw['component_bundle_completed_at'].to_s if raw.key?('component_bundle_completed_at')
        item['component_bundle_dependencies'] = Array(raw['component_bundle_dependencies']).map do |row|
          next unless row.is_a?(Hash)
          { 'id' => row['id'].to_s, 'name' => row['name'].to_s, 'content_signature' => row['content_signature'].to_s }
        end.compact if raw.key?('component_bundle_dependencies')
        item['linked_source_space_id'] = raw['linked_source_space_id'].to_s if raw.key?('linked_source_space_id')
        item['linked_source_name'] = raw['linked_source_name'].to_s if raw.key?('linked_source_name')
        item['linked_transform'] = Array(raw['linked_transform']).map(&:to_f) if raw.key?('linked_transform')
        # 采购清单的普通打开只需要共享 manifest 中的 revision/signature，不应该为
        # 每一个空间同步 File.file?。当协同目录位于 NAS/SMB 时，一个离线/失效路径就
        # 可能让 Windows 的网络文件探测阻塞几十秒，17 个空间会被放大成数分钟。
        # verify_files=false 时只同步清单元数据，真实文件存在性留给显式“更新/发布/提交”验证。
        item['status'] = if verify_files
                           File.file?(resolved) ? (existing.empty? ? '协同空间已发现 · 请点击更新' : item['status'].to_s) : '协同空间文件缺失'
                         elsif resolved.empty?
                           '协同空间路径缺失'
                         elsif existing.empty?
                           '协同空间已发现 · 待按需验证'
                         else
                           item['status'].to_s.empty? ? '协同空间清单已同步' : item['status'].to_s
                         end
        item
      end.compact
      imported_ids = imported.each_with_object({}) { |item, memo| memo[item['id'].to_s] = true }
      # 首次升级时，本地旧版“单一硬装/软装”可能尚未来得及写入共享清单。
      # 只保留这些明确标记为待迁移的本地记录，避免连接共享清单时丢失旧项目入口。
      local.each_value do |item|
        next unless item.is_a?(Hash)
        next if imported_ids[item['id'].to_s]
        # 共享 manifest 尚未出现的首次后台发布空间必须保留在本机状态。
        # 否则抽屉/定时刷新会在 worker 完成前把刚创建的根空间从 state 中冲掉，
        # 最终收尾找不到 item，表现为“首次发布完成但卡片消失/无法编辑”。
        keep_local_unpublished = initial_space_publish_pending?(item) || background_publish_active_state?(item)
        next if item['legacy_key'].to_s.empty? && !keep_local_unpublished
        imported << item
      end
      before = JSON.generate({
        'groups' => Array(state['space_groups']).map { |group| [group['id'], group['name'], group['order'], group['collapsed']] },
        'spaces' => Array(state['space_models']).map { |item| [item['id'], item['number'], item['name'], space_record_collection_key(item), item['model_path'], item['group_id'], item['group_order'], item['last_signature'], item['source_revision'], item['last_publish_at'], item['component_bundle_id'], item['component_bundle_state'], Array(item['component_bundle_dependencies']).map { |row| [row['id'], row['content_signature']] }, item['linked_source_space_id'], item['linked_transform']] }
      })
      state['space_models'] = imported
      state['space_layout_revision'] = data['layout_revision'].to_s if data.key?('layout_revision')
      state['space_layout_updated_at'] = data['layout_updated_at'].to_s if data.key?('layout_updated_at')
      state['space_layout_updated_by'] = data['layout_updated_by'].to_s if data.key?('layout_updated_by')
      state['space_layout_updated_host'] = data['layout_updated_host'].to_s if data.key?('layout_updated_host')
      normalize_space_models_state!(state, model)
      # v0.9.89 起空间分组使用独立共享文件；旧版客户端改写空间模型.json
      # 也不能再把分组覆盖掉。独立文件存在时始终作为布局真相源。
      sync_space_groups_from_manifest!(state, model)
      after = JSON.generate({
        'groups' => Array(state['space_groups']).map { |group| [group['id'], group['name'], group['order'], group['collapsed']] },
        'spaces' => Array(state['space_models']).map { |item| [item['id'], item['number'], item['name'], space_record_collection_key(item), item['model_path'], item['group_id'], item['group_order'], item['last_signature'], item['source_revision'], item['last_publish_at'], item['component_bundle_id'], item['component_bundle_state'], Array(item['component_bundle_dependencies']).map { |row| [row['id'], row['content_signature']] }, item['linked_source_space_id'], item['linked_transform']] }
      })
      before != after
    rescue JSON::ParserError => e
      log_exception('读取空间模型清单失败', e)
      false
    rescue StandardError => e
      log_exception('同步空间模型清单失败', e)
      false
    end

    def space_model_entities(model = Sketchup.active_model)
      Array(managed_root_index(model).dig(:by_kind, 'space_model')).select { |entity| entity && entity.valid? }
    rescue StandardError
      []
    end

    def space_model_entity(space_id, model = Sketchup.active_model)
      entity = managed_root_index(model).dig(:spaces_by_id, space_id.to_s)
      entity && entity.valid? ? entity : nil
    rescue StandardError
      nil
    end

    def adopt_legacy_space_entities!(state, model = Sketchup.active_model)
      changed = false
      Array(state['space_models']).each do |item|
        collection_key = space_record_collection_key(item)
        structure = ensure_professional_structure(collection_key, model)
        next if space_model_entity(item['id'], model)
        candidate = nil
        legacy_key = item['legacy_key'].to_s
        candidate = managed_model_instances_for(legacy_key, model).first if DISCIPLINES.key?(legacy_key)
        if candidate.nil?
          stored = item['model_path'].to_s
          candidate = model.entities.to_a.find do |entity|
            managed_entity?(entity) && entity.get_attribute(ENTITY_DICT, 'source', '').to_s == stored
          end
        end
        next unless candidate && candidate.valid?
        candidate.set_attribute(ENTITY_DICT, 'discipline', collection_key)
        candidate.set_attribute(ENTITY_DICT, 'kind', 'space_model')
        candidate.set_attribute(ENTITY_DICT, 'space_collection_key', collection_key)
        candidate.set_attribute(ENTITY_DICT, 'space_id', item['id'].to_s)
        candidate.set_attribute(ENTITY_DICT, 'space_number', item['number'].to_i)
        candidate.set_attribute(ENTITY_DICT, 'source', item['model_path'].to_s)
        candidate.name = "#{item['number']}:#{item['name']}.skp" if candidate.respond_to?(:name=)
        candidate.layer = structure[:model_tag] if candidate.respond_to?(:layer=)
        candidate.locked = true if candidate.respond_to?(:locked=)
        item['status'] = '旧单模型已迁入空间列表'
        item['legacy_key'] = ''
        changed = true
      end
      changed
    rescue StandardError => e
      log_exception('迁移旧软装/硬装实例失败', e)
      false
    end

    # v0.13.6.20：升级后把已经载入工作 SU 的空间根实体身份与 collection_key 对齐。
    # 只改 LinkHub 元数据、Tag 和显示名称，不重载 definition、不改变 transformation。
    def reconcile_space_collection_entity_identity!(state, model = Sketchup.active_model)
      changed = false
      Array(state['space_models']).each do |item|
        entity = space_model_entity(item['id'], model)
        next unless entity && entity.valid?
        expected = space_record_collection_key(item)
        current = entity.get_attribute(ENTITY_DICT, 'space_collection_key', '').to_s
        current = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s if current.empty?
        next if current == expected && entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s == expected
        structure = ensure_professional_structure(expected, model)
        entity.set_attribute(ENTITY_DICT, 'discipline', expected)
        entity.set_attribute(ENTITY_DICT, 'space_collection_key', expected)
        entity.set_attribute(ENTITY_DICT, 'kind', 'space_model')
        entity.set_attribute(ENTITY_DICT, 'space_id', item['id'].to_s)
        entity.name = "#{item['number']}:#{item['name']}.skp" if entity.respond_to?(:name=)
        entity.layer = structure[:model_tag] if entity.respond_to?(:layer=)
        changed = true
      end
      invalidate_managed_root_index(model, reason: 'space_collection_reconcile') if changed
      changed
    rescue StandardError => e
      log_exception('同步硬装/软装空间根身份失败', e)
      false
    end

    def ensure_space_models_ready!(model = Sketchup.active_model)
      state = load_state(model)
      sync_space_models_from_manifest!(state, model)
      sync_space_groups_from_manifest!(state, model)
      if Array(state['space_models']).any? { |item| !item['legacy_key'].to_s.empty? }
        model.start_operation('迁移软装＋硬装空间模型', true)
        adopt_legacy_space_entities!(state, model)
        model.commit_operation
      end
      reconcile_space_collection_entity_identity!(state, model)
      active_id = state['space_editing_id'].to_s
      if !active_id.empty? && !space_model_entity(active_id, model)
        active = space_model_record(state, active_id)
        if active
          restore_space_isolation!(active, model)
          release_space_lock!(active, auto_relocate(active['model_path'].to_s, model), process_cleanup: true, model: model, state: state)
          active['editing'] = false
        end
        state['space_editing_id'] = ''
      elsif !active_id.empty?
        active = space_model_record(state, active_id)
        entity = space_model_entity(active_id, model)
        if active && entity && entity.valid? && !entity_native_locked?(entity)
          lock = space_lock_info(active, model)
          unless lock['exists'] && !lock['stale'] && lock['owned']
            if !lock['exists'] || lock['stale']
              begin
                source = auto_relocate(active['model_path'].to_s, model)
                acquire_space_lock!(active, source, state) if File.file?(source)
                active['editing'] = true
              rescue StandardError => e
                active['status'] = "本地修改仍保留，但未能恢复协作占用：#{e.message}"
              end
            end
          end
        end
      end
      save_state(state, model, write_manifest: false)
      state
    rescue StandardError => e
      model.abort_operation rescue nil
      log_exception('准备空间模型失败', e)
      load_state(model)
    end

    def active_context_world_transformation(model = Sketchup.active_model)
      transformation = identity_transformation
      Array(model.active_path).each do |instance|
        transformation = transformation * instance.transformation
      end
      transformation
    rescue StandardError
      identity_transformation
    end

    def absolute_transformation_for_selected_entity(entity, model = Sketchup.active_model)
      active_context_world_transformation(model) * entity.transformation
    rescue StandardError
      entity.transformation
    end

    def selected_space_source_entities(model = Sketchup.active_model)
      model.selection.to_a.select do |entity|
        (entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)) &&
          !managed_entity?(entity)
      end
    rescue StandardError
      []
    end

    # 组件最外层的材质、投射阴影和接收阴影属于实例属性，不包含在 definition.save_as 中。
    # 统一复制这些视觉属性，避免 FULL 缓存、空间初次发布和空间再次发布时出现“本机有、别人无”。
    def copy_instance_visual_properties!(source, target, copy_layer: true, copy_name: true)
      return target unless source && target
      target.name = source.name.to_s if copy_name && target.respond_to?(:name=) && source.respond_to?(:name)
      target.layer = source.layer if copy_layer && target.respond_to?(:layer=) && source.respond_to?(:layer)
      target.material = source.material if target.respond_to?(:material=) && source.respond_to?(:material)
      if target.respond_to?(:casts_shadows=) && source.respond_to?(:casts_shadows?)
        target.casts_shadows = source.casts_shadows?
      end
      if target.respond_to?(:receives_shadows=) && source.respond_to?(:receives_shadows?)
        target.receives_shadows = source.receives_shadows?
      end
      target
    rescue StandardError => e
      log_exception('复制组件实例视觉属性失败', e)
      target
    end

    # 返回定义内所有具备组件定义身份的子实例。Group 与 ComponentInstance
    # 都会参与；Image 等没有 make_unique 的实体不会被错误纳入。
    def space_definition_child_instances(definition)
      return [] unless definition && definition.valid?
      definition.entities.to_a.select do |entity|
        entity && entity.valid? && entity.respond_to?(:definition) &&
          entity.respond_to?(:make_unique) && entity.definition
      end
    rescue StandardError
      []
    end

    def collect_space_definition_graph(root_definition)
      return [] unless root_definition && root_definition.valid?
      result = []
      queue = [root_definition]
      seen = {}
      until queue.empty?
        definition = queue.shift
        next unless definition && definition.valid?
        key = definition.object_id
        next if seen[key]
        seen[key] = true
        result << definition
        space_definition_child_instances(definition).each do |child|
          child_definition = child.definition rescue nil
          queue << child_definition if child_definition && child_definition.valid?
        end
      end
      result
    rescue StandardError => e
      log_exception('收集空间定义图失败', e)
      []
    end

    # make_unique 在实例已经唯一时会什么都不做。这里额外放置一个临时实例，
    # 强制 SketchUp 真正生成新定义身份；完成后立即删除临时实例。
    def force_space_instance_unique_definition!(instance, model = Sketchup.active_model)
      raise '空间包实例无效。' unless instance && instance.valid? && instance.respond_to?(:definition)
      original = instance.definition
      preserved_matrix = instance.transformation.to_a.map(&:to_f)
      instance.make_unique if instance.respond_to?(:make_unique)
      if instance.definition != original
        restore_instance_exact_transform_matrix!(instance, preserved_matrix, '空间发布定义隔离')
        return instance.definition
      end

      scratch = nil
      begin
        scratch = model.entities.add_instance(original, identity_transformation)
        scratch.hidden = true if scratch.respond_to?(:hidden=)
        instance.make_unique if instance.respond_to?(:make_unique)
      ensure
        scratch.erase! if scratch && scratch.valid?
      end
      raise 'SketchUp 未能生成独立组件定义身份。' if instance.definition == original
      restore_instance_exact_transform_matrix!(instance, preserved_matrix, '空间发布定义隔离')
      instance.definition
    end

    def tag_space_package_definition!(definition, package_identity, package_revision, space_id, node_id)
      definition.set_attribute(ENTITY_DICT, 'space_package_graph_schema', 1)
      definition.set_attribute(ENTITY_DICT, 'space_package_identity', package_identity.to_s)
      definition.set_attribute(ENTITY_DICT, 'space_package_revision', package_revision.to_s)
      definition.set_attribute(ENTITY_DICT, 'space_package_space_id', space_id.to_s)
      definition.set_attribute(ENTITY_DICT, 'space_package_node_id', node_id.to_s)
      true
    rescue StandardError
      false
    end

    # 标准软装代理是 LinkHub 自动生成的 6 面方块，几何由 model_id + 外包盒签名稳定决定。
    # v0.13.5.7 根因修复：旧逻辑用“9 位小数签名字符串完全相等”验证代理。definition.save_as
    # 再被 SketchUp 载入后，GUID/原生 bounds 缓存 token 可能变化，持久化 bounds 缓存会失效，
    # 此时重新从几何计算会产生极小浮点往返误差，导致一个完全正确的方块被误判为“叶节点无效”。
    # 现在改为：元数据身份严格校验 + 六轴 bounds 数值容差校验。容差只覆盖序列化浮点误差，
    # 不允许尺寸真正发生变化。
    def standard_soft_publish_proxy_expected_bounds(definition)
      signature = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s
      parts = signature.split('|')
      return nil unless parts.length == 6
      values = parts.map { |value| Float(value) }
      soft_bounds_values_valid?(values) ? values : nil
    rescue StandardError
      nil
    end

    def standard_soft_publish_proxy_bounds_match?(definition, tolerance = 1.0e-5)
      expected = standard_soft_publish_proxy_expected_bounds(definition)
      actual = soft_definition_bounds_values(definition)
      return false unless soft_bounds_values_valid?(expected) && soft_bounds_values_valid?(actual)
      expected.zip(actual).all? { |left, right| (left.to_f - right.to_f).abs <= tolerance.to_f }
    rescue StandardError
      false
    end

    def standard_soft_publish_proxy_definition?(definition)
      return false unless definition && definition.valid?
      return false unless definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s == 'proxy'
      return false unless definition.get_attribute(SOFT_MODEL_DICT, 'managed_tree', false) == true
      return false unless definition.get_attribute(SOFT_MODEL_DICT, 'exact_bounds_proxy', false) == true
      style = definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_style', '').to_s
      fallback = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s
      return false unless style == 'box' || !fallback.empty?
      return false unless space_definition_child_instances(definition).empty?
      return false unless standard_soft_publish_proxy_bounds_match?(definition)
      faces = definition.entities.grep(Sketchup::Face).length rescue 0
      faces >= 6
    rescue StandardError
      false
    end

    def parse_standard_soft_publish_proxy_key(value)
      parts = value.to_s.split('|')
      return nil if parts.length < 8
      model_id = parts.shift.to_s
      bounds_text = parts.shift(6)
      version_text = parts.pop.to_s
      fallback = parts.join('|')
      bounds = bounds_text.map { |item| Float(item) }
      version = Integer(version_text)
      return nil unless soft_bounds_values_valid?(bounds)
      {
        model_id: model_id,
        bounds: bounds.map(&:to_f),
        bounds_signature: soft_bounds_signature_from_values(bounds),
        fallback_key: fallback,
        version: version
      }
    rescue StandardError
      nil
    end

    def standard_soft_publish_proxy_diagnostics(definition)
      return 'definition=nil/invalid' unless definition && definition.valid?
      expected = standard_soft_publish_proxy_expected_bounds(definition)
      actual = soft_definition_bounds_values(definition)
      faces = definition.entities.grep(Sketchup::Face).length rescue 0
      children = space_definition_child_instances(definition).length rescue -1
      [
        "name=#{definition.name}",
        "representation=#{definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s}",
        "managed=#{definition.get_attribute(SOFT_MODEL_DICT, 'managed_tree', false).inspect}",
        "exact=#{definition.get_attribute(SOFT_MODEL_DICT, 'exact_bounds_proxy', false).inspect}",
        "style=#{definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_style', '').to_s}",
        "faces=#{faces}",
        "children=#{children}",
        "expected=#{expected ? soft_bounds_signature_from_values(expected) : 'invalid'}",
        "actual=#{soft_bounds_values_valid?(actual) ? soft_bounds_signature_from_values(actual) : 'invalid'}"
      ].join(' / ')
    rescue StandardError => e
      "diagnostics_error=#{e.message}"
    end

    # 兼容 v0.12.8~v0.13.5.6 已发布的“共享标准代理叶”。共享 SKP 载入当前工作 SU 时，
    # SketchUp 可能按 definition GUID 复用本机残留的旧代理定义；也可能因为保存/载入后的
    # bounds cache token 变化而让正确代理失去缓存。旧代码直接阻止更新。这里不盲目信任当前
    # definition，而是以发布包在 child 上保存的 proxy key 为权威，必要时重建一个精确 6 面方块
    # 并重新绑定该 child。这样既不把错误几何当成最新，也不会因为本机旧定义碰撞造成假失败。
    def repair_legacy_shared_soft_publish_proxy_leaf!(child, stored_key, model = Sketchup.active_model)
      # v0.13.6.23：不再为了兼容旧发布包新建白盒代理。旧白盒若无法由现有
      # 六面代理链正常恢复，就让上层明确阻止更新并提示修复，而不是制造新的白盒。
      return nil if SOFT_REQUIRE_VISUAL_PROXY
      parsed = parse_standard_soft_publish_proxy_key(stored_key)
      return nil unless parsed && child && child.valid? && child.respond_to?(:definition)
      old_definition = child.definition rescue nil
      repaired = model.definitions.add(model.definitions.unique_name("LH_共享代理修复_#{parsed[:model_id].to_s[0, 12]}"))

      # 尽可能保留模型库身份信息；真正决定安全性的字段随后由发布 key 强制覆盖。
      if old_definition && old_definition.valid?
        dictionary = old_definition.attribute_dictionary(SOFT_MODEL_DICT, false) rescue nil
        if dictionary
          dictionary.each_pair do |key, value|
            repaired.set_attribute(SOFT_MODEL_DICT, key.to_s, value) rescue nil
          end
        end
      end

      build_soft_auto_proxy_geometry_from_bounds!(repaired, parsed[:bounds])
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'model_id', parsed[:model_id]) unless parsed[:model_id].empty?
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'fallback_proxy_key', parsed[:fallback_key]) unless parsed[:fallback_key].empty?
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'auto_proxy_version', parsed[:version])
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'auto_proxy_style', 'box')
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'representation', 'proxy')
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'managed_tree', true)
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'exact_bounds_proxy', true)
      soft_set_attribute_if_changed(repaired, SOFT_MODEL_DICT, 'proxy_full_bounds_signature', parsed[:bounds_signature])
      persist_soft_definition_bounds_values!(repaired, parsed[:bounds])
      child.definition = repaired

      unless standard_soft_publish_proxy_definition?(repaired) && standard_soft_publish_proxy_key(repaired) == stored_key.to_s
        remove_unused_definition!(repaired, model) rescue nil
        return nil
      end
      log("旧共享软装代理叶已按发布 key 安全重建：#{parsed[:model_id]} / #{parsed[:bounds_signature]}")
      repaired
    rescue StandardError => e
      log_exception('重建旧共享软装代理叶失败', e)
      remove_unused_definition!(repaired, model) if defined?(repaired) && repaired && repaired.valid? && repaired.instances.empty? rescue nil
      nil
    end

    def standard_soft_publish_proxy_key(definition)
      [
        definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s,
        definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s,
        definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s,
        definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_version', 0).to_i
      ].join('|')
    rescue StandardError
      definition.object_id.to_s
    end

    def collect_namespaced_space_package_graph(root_definition)
      result = []
      queue = [root_definition]
      seen = {}
      until queue.empty?
        definition = queue.shift
        next unless definition && definition.valid?
        oid = definition.object_id
        next if seen[oid]
        seen[oid] = true
        result << definition
        space_definition_child_instances(definition).each do |child|
          next if child.get_attribute(ENTITY_DICT, 'space_package_shared_proxy_leaf', false) == true
          child_definition = child.definition rescue nil
          queue << child_definition if child_definition && child_definition.valid?
        end
      end
      result
    rescue StandardError
      []
    end

    # 递归把发布包内的每一级组件/群组定义都变成全新身份。v0.9.89 只克隆了
    # 最外层定义；旧工作 SU 仍可能复用内层旧定义，导致“包版本是新的、几何却是旧的”。
    # 这里保持同一组件在包内的复用关系，同时确保整棵定义图不再与工作模型碰撞。
    def namespace_space_package_graph!(root_instance, model, package_identity:, package_revision:, space_id:)
      root_original = root_instance.definition
      root_clone = force_space_instance_unique_definition!(root_instance, model)
      definition_map = { root_original.object_id => root_clone }
      visited = {}
      node_ids = {}
      shared_proxy_keys = []
      queue = [root_clone]

      until queue.empty?
        definition = queue.shift
        next unless definition && definition.valid?
        key = definition.object_id
        next if visited[key]
        visited[key] = true
        node_id = node_ids[key] ||= SecureRandom.hex(12)
        tag_space_package_definition!(definition, package_identity, package_revision, space_id, node_id)

        space_definition_child_instances(definition).each do |child|
          original_child_definition = child.definition

          if standard_soft_publish_proxy_definition?(original_child_definition)
            proxy_key = standard_soft_publish_proxy_key(original_child_definition)
            child.set_attribute(ENTITY_DICT, 'space_package_shared_proxy_leaf', true)
            child.set_attribute(ENTITY_DICT, 'space_package_shared_proxy_key', proxy_key)
            shared_proxy_keys << proxy_key
            next
          end

          child.delete_attribute(ENTITY_DICT, 'space_package_shared_proxy_leaf') rescue nil
          child.delete_attribute(ENTITY_DICT, 'space_package_shared_proxy_key') rescue nil
          mapped = definition_map[original_child_definition.object_id]
          child_definition = nil

          if mapped && child.respond_to?(:definition=) && !child.is_a?(Sketchup::Group)
            preserved_matrix = child.transformation.to_a.map(&:to_f)
            child.definition = mapped
            restore_instance_exact_transform_matrix!(child, preserved_matrix, '空间发布共享定义映射')
            child_definition = mapped
          else
            child_definition = force_space_instance_unique_definition!(child, model)
            definition_map[original_child_definition.object_id] ||= child_definition
          end

          child_key = child_definition.object_id
          child_node_id = node_ids[child_key] ||= SecureRandom.hex(12)
          tag_space_package_definition!(child_definition, package_identity, package_revision, space_id, child_node_id)
          queue << child_definition
        end
      end

      ids = node_ids.values.sort
      shared_proxy_keys = shared_proxy_keys.reject(&:empty?).sort
      {
        root_definition: root_clone,
        count: ids.length,
        hash: Digest::SHA256.hexdigest(ids.join('|')),
        node_ids: ids,
        shared_proxy_count: shared_proxy_keys.length,
        shared_proxy_hash: Digest::SHA256.hexdigest(shared_proxy_keys.join('|'))
      }
    end

    def verify_space_package_graph!(root_definition, package_identity, expected_count, expected_hash, expected_shared_count: 0, expected_shared_hash: '')
      identity = package_identity.to_s
      raise '空间发布包缺少定义图身份。' if identity.empty?
      definitions = collect_namespaced_space_package_graph(root_definition)
      raise '空间发布包定义图为空。' if definitions.empty?
      node_ids = definitions.map do |definition|
        actual_identity = definition.get_attribute(ENTITY_DICT, 'space_package_identity', '').to_s
        node_id = definition.get_attribute(ENTITY_DICT, 'space_package_node_id', '').to_s
        raise '空间发布包内层定义被旧模型复用，已阻止虚假更新。' unless actual_identity == identity && !node_id.empty?
        node_id
      end
      shared_keys = []
      definitions.each do |definition|
        space_definition_child_instances(definition).each do |child|
          next unless child.get_attribute(ENTITY_DICT, 'space_package_shared_proxy_leaf', false) == true
          proxy_definition = child.definition rescue nil
          stored_key = child.get_attribute(ENTITY_DICT, 'space_package_shared_proxy_key', '').to_s
          valid_leaf = standard_soft_publish_proxy_definition?(proxy_definition)
          key_matches = valid_leaf && !stored_key.empty? && standard_soft_publish_proxy_key(proxy_definition) == stored_key
          unless key_matches
            before = standard_soft_publish_proxy_diagnostics(proxy_definition)
            repaired = repair_legacy_shared_soft_publish_proxy_leaf!(child, stored_key, Sketchup.active_model)
            proxy_definition = repaired || (child.definition rescue nil)
            valid_leaf = standard_soft_publish_proxy_definition?(proxy_definition)
            key_matches = valid_leaf && !stored_key.empty? && standard_soft_publish_proxy_key(proxy_definition) == stored_key
            unless key_matches
              after = standard_soft_publish_proxy_diagnostics(proxy_definition)
              log("空间共享代理叶校验失败：stored_key=#{stored_key} / before=#{before} / after=#{after}")
              raise "空间发布包的标准软装代理叶无法安全验证或修复，已阻止更新。诊断：#{after}"
            end
          end
          shared_keys << stored_key
        end
      end
      actual_count = node_ids.length
      actual_hash = Digest::SHA256.hexdigest(node_ids.sort.join('|'))
      if expected_count.to_i.positive? && actual_count != expected_count.to_i
        raise "空间发布包定义数量不一致（实际#{actual_count}/预期#{expected_count}），已阻止虚假更新。"
      end
      if !expected_hash.to_s.empty? && actual_hash != expected_hash.to_s
        raise '空间发布包定义图校验失败，已阻止虚假更新。'
      end
      shared_keys.sort!
      shared_hash = Digest::SHA256.hexdigest(shared_keys.join('|'))
      if expected_shared_count.to_i.positive? && shared_keys.length != expected_shared_count.to_i
        raise "空间发布包标准代理数量不一致（实际#{shared_keys.length}/预期#{expected_shared_count}），已阻止发布。"
      end
      if !expected_shared_hash.to_s.empty? && shared_hash != expected_shared_hash.to_s
        raise '空间发布包标准代理校验失败，已阻止发布。'
      end
      { verified: true, count: actual_count, hash: actual_hash, shared_proxy_count: shared_keys.length, shared_proxy_hash: shared_hash }
    end

    # 空间 SKP 使用一个仅在文件中存在的发布包裹层：内层实例保留最外层材质等实例属性。
    # 其他成员载入时会立即拆除此包裹层，并把属性还原到 LinkHub 管理的最外层实例，
    # 因此不会随着多次发布不断增加组件嵌套。
    def build_space_publish_wrapper!(entity, model = Sketchup.active_model, representation: nil, package_revision: '', space_id: '')
      wrapper = model.definitions.add("LH_SPACE_PACKAGE_#{SecureRandom.hex(7)}")
      wrapper.set_attribute(ENTITY_DICT, 'space_publish_wrapper_schema', SPACE_PUBLISH_WRAPPER_SCHEMA)
      package_representation = representation.to_s
      package_representation = entity.get_attribute(ENTITY_DICT, 'space_representation', 'full').to_s if package_representation.empty?
      # v0.13.6.182：'mixed' = 大部分家具已是代理、少数因缺代理仍为真模型。载入端不认识 mixed 就不会
      # 走“包标直通”快路径，而是逐件校验并把可解析的家具切成代理，其余交给自动修复。
      package_representation = %w[full mixed].include?(package_representation) ? package_representation : 'proxy'
      identity = SecureRandom.hex(16)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_representation', package_representation)
      wrapper.set_attribute(ENTITY_DICT, 'space_fast_load_schema', 3)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_revision', package_revision.to_s)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_space_id', space_id.to_s)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_identity', identity)
      source_definition, collapsed_package_depth, collapsed_package_transform = canonical_space_publish_source_definition(entity.definition)
      raise '空间发布源 Definition 无效。' unless source_definition && source_definition.valid?
      payload = wrapper.entities.add_instance(source_definition, collapsed_package_transform || identity_transformation)
      log("空间发布前已阻止旧包裹层继续嵌套：折叠 #{collapsed_package_depth} 层") if collapsed_package_depth.to_i.positive?

      graph_started = monotonic_time
      graph = namespace_space_package_graph!(
        payload, model,
        package_identity: identity,
        package_revision: package_revision,
        space_id: space_id
      )
      raise '未能建立独立的空间发布定义图，已取消发布。' unless graph[:root_definition] == payload.definition

      safe_id = space_id.to_s.gsub(/[^0-9A-Za-z]/, '')[0, 12]
      payload.definition.name = model.definitions.unique_name("LH_SPACE_PAYLOAD_#{safe_id}_#{identity[0, 10]}") if payload.definition.respond_to?(:name=)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_graph_schema', 2)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_graph_count', graph[:count].to_i)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_graph_hash', graph[:hash].to_s)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_shared_proxy_count', graph[:shared_proxy_count].to_i)
      wrapper.set_attribute(ENTITY_DICT, 'space_package_shared_proxy_hash', graph[:shared_proxy_hash].to_s)
      payload.definition.set_attribute(ENTITY_DICT, 'space_package_revision', package_revision.to_s)
      payload.definition.set_attribute(ENTITY_DICT, 'space_package_space_id', space_id.to_s)
      payload.definition.set_attribute(ENTITY_DICT, 'space_package_identity', identity)
      payload.set_attribute(ENTITY_DICT, 'space_publish_payload', true)
      payload.set_attribute(ENTITY_DICT, 'space_package_revision', package_revision.to_s)
      payload.set_attribute(ENTITY_DICT, 'space_package_space_id', space_id.to_s)
      payload.set_attribute(ENTITY_DICT, 'space_package_identity', identity)
      copy_instance_visual_properties!(entity, payload, copy_layer: false, copy_name: false)
      graph_elapsed = elapsed_ms(graph_started)
      log("空间发布包定义图已隔离：#{graph[:count]} 个定义 / 跳过标准软装代理 #{graph[:shared_proxy_count]} 个 / #{graph[:hash][0, 12]} / #{graph_elapsed}ms")
      log_slow_operation('空间发布定义图隔离', graph_started, 80.0, "#{graph[:count]} 个定义 / 标准代理跳过 #{graph[:shared_proxy_count]}")
      [wrapper, payload]
    end

    def space_publish_wrapper_payload(definition)
      return nil unless definition && definition.valid?
      schema = definition.get_attribute(ENTITY_DICT, 'space_publish_wrapper_schema', 0).to_i
      return nil unless schema.positive?
      children = definition.entities.grep(Sketchup::ComponentInstance)
      payload = children.find { |child| child.get_attribute(ENTITY_DICT, 'space_publish_payload', false) }
      payload ||= children.first if children.length == 1
      return nil unless payload && payload.valid? && payload.definition
      package_representation = definition.get_attribute(ENTITY_DICT, 'space_package_representation', '').to_s
      package_representation = '' unless %w[proxy full].include?(package_representation)
      {
        definition: payload.definition,
        transformation: payload.transformation,
        material: (payload.respond_to?(:material) ? payload.material : nil),
        casts_shadows: (payload.respond_to?(:casts_shadows?) ? payload.casts_shadows? : nil),
        receives_shadows: (payload.respond_to?(:receives_shadows?) ? payload.receives_shadows? : nil),
        representation: package_representation,
        fast_load_schema: definition.get_attribute(ENTITY_DICT, 'space_fast_load_schema', 0).to_i,
        package_revision: definition.get_attribute(ENTITY_DICT, 'space_package_revision', payload.definition.get_attribute(ENTITY_DICT, 'space_package_revision', '')).to_s,
        package_space_id: definition.get_attribute(ENTITY_DICT, 'space_package_space_id', payload.definition.get_attribute(ENTITY_DICT, 'space_package_space_id', '')).to_s,
        package_identity: definition.get_attribute(ENTITY_DICT, 'space_package_identity', payload.definition.get_attribute(ENTITY_DICT, 'space_package_identity', '')).to_s,
        wrapper_schema: schema,
        graph_schema: definition.get_attribute(ENTITY_DICT, 'space_package_graph_schema', 0).to_i,
        graph_count: definition.get_attribute(ENTITY_DICT, 'space_package_graph_count', 0).to_i,
        graph_hash: definition.get_attribute(ENTITY_DICT, 'space_package_graph_hash', '').to_s,
        shared_proxy_count: definition.get_attribute(ENTITY_DICT, 'space_package_shared_proxy_count', 0).to_i,
        shared_proxy_hash: definition.get_attribute(ENTITY_DICT, 'space_package_shared_proxy_hash', '').to_s
      }
    rescue StandardError => e
      log_exception('读取空间发布包裹层失败', e)
      nil
    end

    def remove_unused_definition!(definition, model = Sketchup.active_model)
      return false unless definition && definition.valid?
      return false if soft_visual_proxy_definition_in_use?(definition)
      return false if definition.respond_to?(:instances) && !definition.instances.empty?
      return false unless model.definitions.respond_to?(:remove)
      !!model.definitions.remove(definition)
    rescue StandardError
      false
    end

    # 六面代理的种子、排队候选和当前分片都可能持有一个暂时没有实例的 Definition。
    # Ruby 引用不会阻止 DefinitionList#remove；统一在删除入口保护，任务结束后自动释放。
    def soft_visual_proxy_definition_in_use?(definition)
      return false unless definition && definition.valid?
      job = @soft_visual_proxy_upgrade_job
      return false unless job.is_a?(Hash)
      active = job[:active_candidate_state]
      return true if active.is_a?(Hash) && active[:source_definition].equal?(definition)
      candidate = active[:candidate] if active.is_a?(Hash)
      return true if candidate.is_a?(Hash) && candidate[:source_definition].equal?(definition)
      (Array(job[:scan_queue]) + Array(job[:queue])).any? do |row|
        row.is_a?(Hash) && row[:source_definition].equal?(definition)
      end
    rescue StandardError
      false
    end

    # definition.save_as 返回后立即删除刚保存的临时定义，在部分 SU 2025/2026
    # 环境中可能与原生保存线程的资源释放相撞。发布临时定义统一延后到安静期后清理。
    def defer_publish_definition_cleanup!(definition, model = Sketchup.active_model)
      return false unless definition && definition.valid? && model
      object_id = definition.object_id
      publish_id = active_publish_id
      publish_breadcrumb_for_id!(publish_id, 'temporary_definition_cleanup_deferred', definition_id: object_id)
      child_definitions = collect_space_definition_graph(definition).drop(1).reject { |child| standard_soft_publish_proxy_definition?(child) }
      runtime_start_timer(PUBLISH_POST_QUIET_SECONDS + 0.35, false, label: 'post_publish_definition_cleanup') do
        next unless definition && definition.valid?
        next unless definition.respond_to?(:instances) && definition.instances.empty?
        publish_breadcrumb_for_id!(publish_id, 'post_publish_cleanup_begin', definition_id: object_id)
        removed = remove_unused_definition!(definition, model)
        child_removed = 0
        pending = Array(child_definitions).dup
        loop do
          removed_this_pass = 0
          pending.delete_if do |child|
            removed = remove_unused_definition!(child, model)
            if removed
              child_removed += 1
              removed_this_pass += 1
            end
            removed
          end
          break if removed_this_pass.zero? || pending.empty?
        end
        publish_breadcrumb_for_id!(publish_id, 'post_publish_cleanup_returned', definition_id: object_id, removed: !!removed, child_removed: child_removed)
        log("发布临时定义延迟清理：#{object_id} / #{removed ? '已删除' : '保留'} / 子定义#{child_removed}")
      end
      true
    rescue StandardError => e
      log_exception('安排发布临时定义延迟清理失败', e)
      false
    end

    # 复制实体属性字典。仅用于 Definition 原位替换失败后的安全 fallback，
    # 确保 space_id / LinkHub 身份等不会因为清理历史包裹层而丢失。
    def copy_entity_attribute_dictionaries!(source, target)
      return false unless source && source.valid? && target && target.valid?
      dictionaries = source.attribute_dictionaries
      return true unless dictionaries
      dictionaries.each do |dictionary|
        dictionary.each_pair do |key, value|
          target.set_attribute(dictionary.name.to_s, key.to_s, value)
        rescue StandardError
          next
        end
      end
      true
    rescue StandardError
      false
    end

    # 将发布文件中的 LinkHub 包裹层递归拆回正常的“一个空间根组件”。
    # 旧版只拆最外面一层；如果历史文件已经发生 package -> package -> payload，
    # 更新一次后仍会留下一层，反复后用户就需要钻很多层空组件。新版严格只识别
    # space_publish_wrapper_schema 标记，并最多拆 24 层；用户自己的普通组件绝不处理。
    def normalize_loaded_space_instance!(instance, loaded_definition, model = Sketchup.active_model)
      current_definition = loaded_definition
      wrappers = []
      outer_payload = nil
      graph_result = { verified: false, count: 0, hash: '' }
      original_transform = instance.transformation
      payload_transform = identity_transformation

      24.times do
        payload = space_publish_wrapper_payload(current_definition)
        break unless payload
        outer_payload ||= payload
        local_transform = payload[:transformation] || identity_transformation
        payload_transform = payload_transform * local_transform
        if payload[:graph_schema].to_i.positive?
          graph_result = verify_space_package_graph!(
            payload[:definition], payload[:package_identity],
            payload[:graph_count], payload[:graph_hash],
            expected_shared_count: payload[:shared_proxy_count],
            expected_shared_hash: payload[:shared_proxy_hash]
          )
        end
        wrappers << current_definition
        current_definition = payload[:definition]
        break unless current_definition && current_definition.valid?
      end

      unless outer_payload
        instance.material = nil if instance.respond_to?(:material=)
        return instance
      end
      raise '空间发布包递归拆包后没有有效 payload Definition。' unless current_definition && current_definition.valid?
      normalized_transform = original_transform * payload_transform

      assigned = false
      begin
        if instance.respond_to?(:definition=)
          result = (instance.definition = current_definition)
          assigned = result != false && instance.definition == current_definition
          instance.transformation = normalized_transform if assigned && instance.respond_to?(:transformation=)
        end
      rescue StandardError
        assigned = false
      end
      unless assigned
        old_instance = instance
        old_locked = old_instance.respond_to?(:locked?) ? old_instance.locked? : false
        replacement = model.entities.add_instance(current_definition, normalized_transform)
        copy_entity_attribute_dictionaries!(old_instance, replacement)
        copy_instance_visual_properties!(old_instance, replacement)
        replacement.name = old_instance.name.to_s if replacement.respond_to?(:name=) && old_instance.respond_to?(:name)
        replacement.layer = old_instance.layer if replacement.respond_to?(:layer=) && old_instance.respond_to?(:layer) && old_instance.layer
        replacement.hidden = old_instance.hidden? if replacement.respond_to?(:hidden=) && old_instance.respond_to?(:hidden?)
        old_instance.locked = false if old_instance.respond_to?(:locked=)
        old_instance.erase! if old_instance.valid?
        replacement.locked = old_locked if replacement.respond_to?(:locked=)
        instance = replacement
      end

      # 最外层 package 是本次共享文件的权威实例属性/元数据；内部若还有历史 package，
      # 只作为需要清理的旧壳，不让它覆盖最新发布信息。
      instance.material = outer_payload[:material] if instance.respond_to?(:material=)
      if !outer_payload[:casts_shadows].nil? && instance.respond_to?(:casts_shadows=)
        instance.casts_shadows = outer_payload[:casts_shadows]
      end
      if !outer_payload[:receives_shadows].nil? && instance.respond_to?(:receives_shadows=)
        instance.receives_shadows = outer_payload[:receives_shadows]
      end
      unless outer_payload[:representation].to_s.empty?
        instance.set_attribute(ENTITY_DICT, 'space_package_representation_hint', outer_payload[:representation].to_s)
        instance.set_attribute(ENTITY_DICT, 'space_fast_load_schema', outer_payload[:fast_load_schema].to_i)
      end
      instance.set_attribute(ENTITY_DICT, 'space_package_revision_hint', outer_payload[:package_revision].to_s)
      instance.set_attribute(ENTITY_DICT, 'space_package_space_id_hint', outer_payload[:package_space_id].to_s)
      instance.set_attribute(ENTITY_DICT, 'space_package_identity_hint', outer_payload[:package_identity].to_s)
      instance.set_attribute(ENTITY_DICT, 'space_package_wrapper_schema_hint', outer_payload[:wrapper_schema].to_i)
      instance.set_attribute(ENTITY_DICT, 'space_package_graph_schema_hint', outer_payload[:graph_schema].to_i)
      instance.set_attribute(ENTITY_DICT, 'space_package_graph_count_hint', graph_result[:count].to_i)
      instance.set_attribute(ENTITY_DICT, 'space_package_graph_hash_hint', graph_result[:hash].to_s)
      instance.set_attribute(ENTITY_DICT, 'space_package_graph_verified_hint', !!graph_result[:verified])

      removed = 0
      wrappers.each do |definition|
        removed += 1 if remove_unused_definition!(definition, model)
      rescue StandardError
        next
      end
      log("空间发布包已递归拆平：#{wrappers.length} 层 / 清理定义 #{removed}") if wrappers.length > 1
      instance
    rescue StandardError => e
      log_exception('还原空间最外层实例属性失败', e)
      # 新版全层定义图只要任一步异常就必须终止更新，不能降级成旧版的
      # “尽量继续”，否则仍可能把旧几何写成已最新。
      raise if defined?(outer_payload) && outer_payload && outer_payload[:graph_schema].to_i.positive?
      instance
    end

    def space_publish_wrapper_chain_depth(definition, limit = 24)
      depth = 0
      current = definition
      while depth < limit.to_i
        payload = space_publish_wrapper_payload(current)
        break unless payload && payload[:definition] && payload[:definition].valid?
        depth += 1
        current = payload[:definition]
      end
      depth
    rescue StandardError
      0
    end

    # 发布前最后一道根因保护：即使历史项目里某个空间根绕过了更新时的 normalize，
    # 也只使用最深层真实 payload 作为新 package 的内容，绝不把旧 package 再包进去。
    def canonical_space_publish_source_definition(definition, limit = 24)
      current = definition
      depth = 0
      combined_transform = identity_transformation
      while depth < limit.to_i
        payload = space_publish_wrapper_payload(current)
        break unless payload && payload[:definition] && payload[:definition].valid?
        combined_transform = combined_transform * (payload[:transformation] || identity_transformation)
        current = payload[:definition]
        depth += 1
      end
      [current, depth, combined_transform]
    rescue StandardError
      [definition, 0, identity_transformation]
    end

    # 更新旧工作 SU 时，必须在载入新包之前先退休当前空间实例及其不再使用的
    # 定义。只在载入之后删除旧实例会让 SketchUp 在解析阶段复用旧定义。
    # v0.13.6.92：继续修复“套娃式空壳”。这里和发布 package 拆包是两套规则：
    # package 拆包只认 LinkHub 明确标记；本规则允许处理普通历史模型，但必须同时满足
    # “根定义只有一个子容器 + 该壳完全没有语义属性”。任何材质、Tag、锁定、隐藏、
    # 自定义属性、动态组件/粘附/切孔行为、实例名称等都会阻止自动折叠。
    #
    # 折叠使用 SketchUp 原生 explode，只去掉中间容器层，子实例自身 Definition 不改写，
    # 并在提交前后复核最外层 Bounds；只要尺寸/位置有可见变化就撤销本次修复。
    def redundant_shell_definition_for(entity)
      return nil unless entity && entity.valid?
      definition = entity.definition if entity.respond_to?(:definition)
      if (!definition || !definition.valid?) && entity.is_a?(Sketchup::Group) && entity.respond_to?(:entities)
        parent = entity.entities.parent rescue nil
        definition = parent if parent.is_a?(Sketchup::ComponentDefinition)
      end
      definition && definition.valid? ? definition : nil
    rescue StandardError
      nil
    end

    # v0.13.6.92：历史空间里还可能残留“有 Definition 名称、也带 LinkHub 包元数据”的
    # 运输壳，例如 LH_SPACE_PACKAGE_xxx -> LH_SPACE_PACKAGE_xxx -> LH_SPACE_PAYLOAD_xxx -> 实际内容。
    # 这些层不是用户语义组件；0.13.6.88 因为把“Definition 有属性/名字”一律视为重要而会跳过。
    # 新版单独识别 LinkHub 自己的运输壳：只接受 LinkHub 专用命名/包元数据，仍拒绝用户名称、
    # 非默认 Tag、隐藏、动态行为及任何非包元数据属性。运输壳自身的历史 locked 标记允许在删除前临时解除。这样可以安全拆掉历史 PACKAGE/PAYLOAD，
    # 同时保留最外层 LinkHub 空间根以及真正的“软装/硬装”等核心内容层。
    def linkhub_space_transport_definition_kind(definition, trusted_chain: false)
      return nil unless definition && definition.valid?
      raw_name = definition.respond_to?(:name) ? definition.name.to_s.strip : ''
      name = raw_name.sub(/#\d+\z/, '')
      package_named = name.match?(/\A(?:L?H_)?SPACE_PACKAGE_[0-9A-Za-z][0-9A-Za-z_\-]*\z/i)
      payload_named = name.match?(/\A(?:(?:L?H_)?SPACE_)?PAYLOAD_[0-9A-Za-z][0-9A-Za-z_\-]*\z/i)

      wrapper_schema = definition.get_attribute(ENTITY_DICT, 'space_publish_wrapper_schema', 0).to_i
      graph_schema = definition.get_attribute(ENTITY_DICT, 'space_package_graph_schema', 0).to_i
      identity = definition.get_attribute(ENTITY_DICT, 'space_package_identity', '').to_s
      node_id = definition.get_attribute(ENTITY_DICT, 'space_package_node_id', '').to_s

      return :package if wrapper_schema.positive? || package_named
      package_metadata = graph_schema.positive? && !identity.empty? && !node_id.empty?
      return :payload if payload_named && (trusted_chain || package_metadata)
      nil
    rescue StandardError
      nil
    end

    def linkhub_space_transport_attributes_only?(object)
      return true unless object && object.respond_to?(:attribute_dictionaries)
      dictionaries = object.attribute_dictionaries
      return true unless dictionaries
      dictionaries.each do |dictionary|
        return false unless dictionary.name.to_s == ENTITY_DICT
        dictionary.each_pair do |key, _value|
          key = key.to_s
          allowed = key.start_with?('space_package_') ||
                    %w[space_publish_wrapper_schema space_publish_payload space_fast_load_schema
                       linkhub_space_content_root_schema loaded_from_newer_version stripped_reference_count].include?(key)
          return false unless allowed
        end
      end
      true
    rescue StandardError
      false
    end

    def linkhub_space_transport_definition_behavior_safe?(definition)
      return false unless definition && definition.valid?
      return false if definition.respond_to?(:image?) && definition.image?
      return false if definition.respond_to?(:live_component?) && definition.live_component?
      behavior = definition.behavior if definition.respond_to?(:behavior)
      if behavior
        return false if behavior.respond_to?(:cuts_opening?) && behavior.cuts_opening?
        return false if behavior.respond_to?(:always_face_camera?) && behavior.always_face_camera?
        return false if behavior.respond_to?(:shadows_face_sun?) && behavior.shadows_face_sun?
        snap = behavior.snapto if behavior.respond_to?(:snapto)
        return false if !snap.nil? && snap.to_i != 0
      end
      true
    rescue StandardError
      false
    end

    def linkhub_space_transport_shell_kind(entity, model = Sketchup.active_model, trusted_chain: false)
      return nil unless entity && entity.valid?
      return nil unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
      return nil if entity.respond_to?(:name) && !entity.name.to_s.strip.empty?
      return nil if entity.respond_to?(:hidden?) && entity.hidden?
      # v0.13.6.92：历史 PACKAGE/PAYLOAD 本身可能残留 LinkHub 旧版原生锁。
      # “locked” 对普通用户组件仍然是强语义，但对已经被严格识别为 LinkHub 运输壳的
      # 节点不能继续作为保留理由，否则恰好会把用户截图中的两层空壳永远挡在清理之外。
      # collapse 阶段只对即将删除的运输壳临时解锁；普通空壳仍继续拒绝 locked 实例。
      return nil if entity.respond_to?(:glued_to) && entity.glued_to
      return nil unless redundant_shell_default_tag?(entity, model)
      return nil unless linkhub_space_transport_attributes_only?(entity)

      definition = redundant_shell_definition_for(entity)
      return nil unless definition
      kind = linkhub_space_transport_definition_kind(definition, trusted_chain: trusted_chain)
      return nil unless kind
      return nil unless linkhub_space_transport_attributes_only?(definition)
      return nil unless linkhub_space_transport_definition_behavior_safe?(definition)
      return nil if definition.entities.to_a.none? { |child| child && child.valid? }
      kind
    rescue StandardError
      nil
    end

    def redundant_shell_has_attributes?(object)
      return false unless object && object.respond_to?(:attribute_dictionaries)
      dictionaries = object.attribute_dictionaries
      return false unless dictionaries
      dictionaries.each { |_dictionary| return true }
      false
    rescue StandardError
      true
    end

    def redundant_shell_special_definition?(definition)
      return true unless definition && definition.valid?
      return true if definition.respond_to?(:image?) && definition.image?
      return true if definition.respond_to?(:live_component?) && definition.live_component?
      description = definition.respond_to?(:description) ? definition.description.to_s.strip : ''
      return true unless description.empty?
      return true if redundant_shell_has_attributes?(definition)

      insertion = definition.insertion_point if definition.respond_to?(:insertion_point)
      if insertion
        coords = [insertion.x.to_f, insertion.y.to_f, insertion.z.to_f]
        return true if coords.any? { |value| value.abs > 1.0e-8 }
      end

      behavior = definition.behavior if definition.respond_to?(:behavior)
      if behavior
        return true if behavior.respond_to?(:cuts_opening?) && behavior.cuts_opening?
        return true if behavior.respond_to?(:always_face_camera?) && behavior.always_face_camera?
        return true if behavior.respond_to?(:shadows_face_sun?) && behavior.shadows_face_sun?
        snap = behavior.snapto if behavior.respond_to?(:snapto)
        return true if !snap.nil? && snap.to_i != 0
      end
      false
    rescue StandardError
      true
    end

    def redundant_shell_definition_name_safe?(definition, child_definition = nil)
      name = definition && definition.respond_to?(:name) ? definition.name.to_s.strip : ''
      return true if name.empty?
      # SketchUp 自动生成的普通组/组件名称可以视为结构噪音。
      return true if name.match?(/\A(?:Group|Component|群组|组件|组)(?:[#_\-\s]*\d+)?\z/i)

      child_name = child_definition && child_definition.respond_to?(:name) ? child_definition.name.to_s.strip : ''
      return false if child_name.empty?
      normalize = lambda do |value|
        value.to_s.strip.downcase
             .sub(/(?:\s+copy|\s+副本)\z/i, '')
             .sub(/(?:[#_\-\s]+\d+)\z/, '')
      end
      !normalize.call(name).empty? && normalize.call(name) == normalize.call(child_name)
    rescue StandardError
      false
    end

    def redundant_shell_default_tag?(entity, model = Sketchup.active_model)
      return true unless entity && entity.respond_to?(:layer)
      layer = entity.layer
      return true unless layer
      default_layer = model && model.respond_to?(:layers) ? model.layers[0] : nil
      default_layer ? layer == default_layer : %w[Layer0 Untagged].include?(layer.name.to_s)
    rescue StandardError
      false
    end

    def redundant_empty_shell_payload(entity, model = Sketchup.active_model)
      return nil unless entity && entity.valid?
      return nil unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
      return nil if entity.respond_to?(:name) && !entity.name.to_s.strip.empty?
      return nil if entity.respond_to?(:material) && entity.material
      return nil if entity.respond_to?(:hidden?) && entity.hidden?
      return nil if entity.respond_to?(:locked?) && entity.locked?
      return nil if entity.respond_to?(:casts_shadows?) && !entity.casts_shadows?
      return nil if entity.respond_to?(:receives_shadows?) && !entity.receives_shadows?
      return nil if entity.respond_to?(:glued_to) && entity.glued_to
      return nil unless redundant_shell_default_tag?(entity, model)
      return nil if redundant_shell_has_attributes?(entity)

      definition = redundant_shell_definition_for(entity)
      return nil if redundant_shell_special_definition?(definition)
      children = definition.entities.to_a.select { |child| child && child.valid? }
      return nil unless children.length == 1
      child = children.first
      return nil unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)
      child_definition = redundant_shell_definition_for(child)
      return nil unless child_definition
      return nil unless redundant_shell_definition_name_safe?(definition, child_definition)
      child
    rescue StandardError
      nil
    end

    def redundant_shell_bounds_values(entity)
      return nil unless entity && entity.valid? && entity.respond_to?(:bounds)
      bounds = entity.bounds
      return nil if bounds.respond_to?(:valid?) && !bounds.valid?
      min = bounds.min
      max = bounds.max
      [min.x, min.y, min.z, max.x, max.y, max.z].map(&:to_f)
    rescue StandardError
      nil
    end

    def redundant_shell_bounds_match?(before_values, after_values)
      before = Array(before_values).map(&:to_f)
      after = Array(after_values).map(&:to_f)
      return true if before.length != 6 || after.length != 6
      span = [
        (before[3] - before[0]).abs,
        (before[4] - before[1]).abs,
        (before[5] - before[2]).abs,
        (after[3] - after[0]).abs,
        (after[4] - after[1]).abs,
        (after[5] - after[2]).abs
      ].max.to_f
      tolerance = [0.001, span * 1.0e-7].max
      before.each_index.all? { |index| (before[index] - after[index]).abs <= tolerance }
    rescue StandardError
      false
    end

    # 只折叠“指定根 Definition 顶层”的连续空壳链，不递归改写子 Definition。
    # 这样即使子组件被别处复用，也不会因为本次修复改变其它实例；同时恰好解决
    # “进入空间 -> LH_SPACE_PACKAGE -> LH_SPACE_PACKAGE -> LH_SPACE_PAYLOAD -> 核心内容”的钻层问题。
    # 第一优先级是 LinkHub 运输壳：即使它有 Definition 名称和包元数据也允许拆，因为这些恰好
    # 是插件自己生成的结构标记；第二优先级才是普通无语义单子节点壳。对裸 PAYLOAD 名称只在
    # 已经进入 LinkHub PACKAGE 链或同时具备完整 package graph 元数据时信任，避免误拆用户组件。
    def collapse_redundant_empty_shell_chain!(root_definition, model = Sketchup.active_model, limit: 32)
      return 0 unless root_definition && root_definition.valid? && root_definition.respond_to?(:entities)
      collapsed = 0
      trusted_linkhub_chain = :none
      [limit.to_i, 1].max.times do
        entities = root_definition.entities.to_a.select { |entity| entity && entity.valid? }
        break unless entities.length == 1
        shell = entities.first

        transport_kind = linkhub_space_transport_shell_kind(shell, model, trusted_chain: trusted_linkhub_chain == :package)
        if transport_kind
          old_definition = redundant_shell_definition_for(shell)
          old_name = old_definition && old_definition.respond_to?(:name) ? old_definition.name.to_s : transport_kind.to_s
          if transport_kind == :payload && old_definition && old_definition.valid?
            if old_definition.get_attribute(ENTITY_DICT, 'linkhub_space_content_root_schema', 0).to_i.positive?
              root_definition.set_attribute(ENTITY_DICT, 'linkhub_space_content_root_schema', 1)
            end
            %w[loaded_from_newer_version stripped_reference_count].each do |key|
              value = old_definition.get_attribute(ENTITY_DICT, key, nil)
              root_definition.set_attribute(ENTITY_DICT, key, value) unless value.nil?
            end
            if root_definition.respond_to?(:description=) && root_definition.respond_to?(:description) &&
               root_definition.description.to_s.strip.empty? && old_definition.respond_to?(:description)
              description = old_definition.description.to_s
              root_definition.description = description unless description.strip.empty?
            end
          end
          # 运输壳若带有旧版原生锁，只解锁这个马上要被删除的壳。不能执行
          # “全部解锁”，也不会改变真正业务组件的锁状态。
          shell_was_locked = shell.respond_to?(:locked?) && shell.locked?
          shell.locked = false if shell_was_locked && shell.respond_to?(:locked=)
          exploded = shell.explode
          unless exploded
            shell.locked = true if shell_was_locked && shell.valid? && shell.respond_to?(:locked=)
            break
          end
          collapsed += 1
          soft_invalidate_definition_bounds!(root_definition)
          trusted_linkhub_chain = transport_kind == :package ? :package : :payload_done
          remove_unused_definition!(old_definition, model) if old_definition && old_definition.valid?
          log("自动拆平 LinkHub 空间运输壳：#{transport_kind} / #{old_name}")
          next
        end

        break unless redundant_empty_shell_payload(shell, model)
        old_definition = redundant_shell_definition_for(shell)
        exploded = shell.explode
        break unless exploded
        collapsed += 1
        soft_invalidate_definition_bounds!(root_definition)
        trusted_linkhub_chain = :none
        remove_unused_definition!(old_definition, model) if old_definition && old_definition.valid?
      end
      collapsed
    rescue StandardError => e
      log_exception('折叠冗余空壳链失败', e)
      0
    end

    def repair_redundant_empty_shells!(root_entity, model = Sketchup.active_model, context: '模型')
      return { changed: false, count: 0 } unless root_entity && root_entity.valid? && model
      definition = redundant_shell_definition_for(root_entity)
      return { changed: false, count: 0 } unless definition
      before_bounds = redundant_shell_bounds_values(root_entity)
      count = collapse_redundant_empty_shell_chain!(definition, model)
      return { changed: false, count: 0 } if count <= 0
      after_bounds = redundant_shell_bounds_values(root_entity)
      unless redundant_shell_bounds_match?(before_bounds, after_bounds)
        raise "#{context}空壳修复后外包盒发生变化，已停止自动修复。"
      end
      log("自动清理冗余空壳：#{context} / #{count} 层 / Bounds复核通过")
      { changed: true, count: count }
    end

    # 在独立 Undo 事务中执行，任何异常都只撤销“空壳修复”本身，不影响随后退出、
    # 发布或锁回动作。用于已经离开 active_path 的空间收尾/发布入口。
    def repair_redundant_empty_shells_operation!(root_entity, model = Sketchup.active_model, context: '模型')
      return { changed: false, count: 0 } unless root_entity && root_entity.valid? && model
      return { changed: false, count: 0, skipped: true } unless model.active_path.nil?
      operation_open = false
      begin
        model.start_operation("自动清理空壳 #{context}", true, false, true)
        operation_open = true
        result = repair_redundant_empty_shells!(root_entity, model, context: context)
        if result[:changed]
          model.commit_operation
        else
          model.abort_operation
        end
        operation_open = false
        result
      rescue StandardError => e
        model.abort_operation rescue nil if operation_open
        log_exception("#{context}自动清理空壳已安全跳过", e)
        { changed: false, count: 0, skipped: true, error: e.message.to_s }
      end
    end


    # v0.13.6.92：0.13.6.91 把“Definition 有多个实例”直接当成锁冲突，并把
    # 编辑脊柱上任何仍共享的 Definition 都作为硬失败。用户实测证明这个条件过宽：
    # 新建空空间也可能因为正常的共享/载入期 Definition 引用被误判，从而完全无法进入修改。
    #
    # 这里拆成两个概念：
    # 1) shared：Definition 在 definitions 表里确实有多个实例对象——用于“尽力隔离”，避免跨空间串改；
    # 2) lock_conflict：Definition 的某个 occurrence 直接 locked，或它位于一个存在 locked occurrence
    #    的父 Definition 之下——这才是 SketchUp“部分实例已锁定”三选一弹窗真正相关的风险。
    #
    # 空间进入只把“空间根自身仍存在有效锁冲突”当作硬失败；内部核心层全部改成尽力隔离，
    # 即使诊断仍看到普通 shared 也不会再阻断空空间。核心层用户再次双击前由双击桥按 lock_conflict
    # 做最后一次兜底。绝不执行“全部解锁”。
    def space_edit_definition_instances(definition)
      return [] unless definition && definition.valid? && definition.respond_to?(:instances)
      definition.instances.to_a.select { |instance| instance && instance.valid? }
    rescue StandardError
      []
    end

    # 返回一个嵌套实例所在的父 ComponentDefinition；模型根层级返回 nil。
    def space_edit_instance_parent_definition(instance)
      return nil unless instance && instance.valid? && instance.respond_to?(:parent)
      parent = instance.parent
      owner = if parent.is_a?(Sketchup::Entities) && parent.respond_to?(:parent)
                parent.parent
              else
                parent
              end
      owner.is_a?(Sketchup::ComponentDefinition) ? owner : nil
    rescue StandardError
      nil
    end

    # Definition 的一个实例对象即使 locked? == false，只要它嵌在“父 Definition 的某个
    # occurrence 被锁”的路径中，SketchUp 仍会把这个子 Definition 视为存在锁定 occurrence。
    # 这里沿“子实例 -> 父 Definition -> 父 Definition 的实例”向上递归，覆盖这种锁传播。
    def space_edit_definition_has_locked_occurrence?(definition, trail = nil, depth = 0)
      return false unless definition && definition.valid?
      return false if depth.to_i > 32
      path = trail.is_a?(Hash) ? trail.dup : {}
      key = definition.object_id
      return false if path[key]
      path[key] = true

      space_edit_definition_instances(definition).any? do |instance|
        direct_locked = instance.respond_to?(:locked?) && instance.locked?
        next true if direct_locked
        parent_definition = space_edit_instance_parent_definition(instance)
        parent_definition && space_edit_definition_has_locked_occurrence?(parent_definition, path, depth.to_i + 1)
      rescue StandardError
        false
      end
    rescue StandardError
      false
    end

    def space_edit_definition_lock_conflict?(entity)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      return true if entity.respond_to?(:locked?) && entity.locked?
      definition = entity.definition
      return false unless definition && definition.valid?
      space_edit_definition_has_locked_occurrence?(definition)
    rescue StandardError
      false
    end

    # 保留旧调用名，但语义升级为“其它 instance 本身或其父 occurrence 有锁”。
    def space_edit_other_locked_definition_instance?(entity)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      definition = entity.definition
      return false unless definition && definition.valid?
      space_edit_definition_instances(definition).any? do |instance|
        next false if instance.equal?(entity)
        direct_locked = instance.respond_to?(:locked?) && instance.locked?
        next true if direct_locked
        parent_definition = space_edit_instance_parent_definition(instance)
        parent_definition && space_edit_definition_has_locked_occurrence?(parent_definition)
      rescue StandardError
        false
      end
    rescue StandardError
      false
    end

    def space_edit_definition_shared?(entity)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      definition = entity.definition
      return false unless definition && definition.valid?
      space_edit_definition_instances(definition).length > 1
    rescue StandardError
      false
    end

    def space_edit_single_container_child(entity)
      return nil unless entity && entity.valid? && entity.respond_to?(:definition)
      definition = entity.definition
      return nil unless definition && definition.valid? && definition.respond_to?(:entities)
      entities = definition.entities.to_a.select { |child| child && child.valid? }
      return nil unless entities.length == 1
      child = entities.first
      return nil unless child.is_a?(Sketchup::Group) || child.is_a?(Sketchup::ComponentInstance)
      child
    rescue StandardError
      nil
    end

    # 空间编辑专用的强制唯一化。普通 make_unique 首先执行；只有 SketchUp 没有真的
    # 切 Definition 时才临时放一个同定义 scratch 实例，再重试并立即删除。scratch 优先
    # 放在当前实例所属 Entities，避免在 active_path 内无意义污染模型根。
    def force_space_edit_instance_unique_definition!(instance, model = Sketchup.active_model)
      raise '空间编辑实例无效。' unless instance && instance.valid? && instance.respond_to?(:definition)
      original = instance.definition
      instance.make_unique if instance.respond_to?(:make_unique)
      return instance.definition if instance.definition && instance.definition.valid? && !instance.definition.equal?(original)

      scratch = nil
      begin
        parent_entities = instance.respond_to?(:parent) ? instance.parent : nil
        scratch_entities = parent_entities.is_a?(Sketchup::Entities) ? parent_entities : (model && model.respond_to?(:entities) ? model.entities : nil)
        raise '无法取得空间编辑实例的父实体集合。' unless scratch_entities && scratch_entities.respond_to?(:add_instance)
        scratch = scratch_entities.add_instance(original, identity_transformation)
        scratch.hidden = true if scratch && scratch.respond_to?(:hidden=)
        instance.make_unique if instance.respond_to?(:make_unique)
      ensure
        scratch.erase! if scratch && scratch.valid?
      end
      raise 'SketchUp 未能为当前空间编辑层生成独立 Definition。' if instance.definition.equal?(original)
      instance.definition
    end

    # 只对当前实例做 Definition 隔离。优先调用空间编辑专用的强制唯一化辅助器：它会处理
    # SketchUp 在某些 Group/单实例场景 make_unique 无动作的情况，但绝不会解锁其它实例。
    # 若当前 Definition 只有一个实例对象、冲突仅来自仍共享的父 Definition，则不能直接
    # 在这里强制唯一化子层（那会改父 Definition 的所有 occurrence）；应由从外到内的脊柱
    # 隔离先把父层切断，下一轮子层自然会变成多个真实 instance 对象再安全 make_unique。
    def make_space_edit_node_unique_if_lock_conflict!(entity, label = '空间编辑层', model = Sketchup.active_model)
      return false unless entity && entity.valid?
      return false unless entity.respond_to?(:make_unique) && entity.respond_to?(:definition)
      old_definition = entity.definition
      return false unless old_definition && old_definition.valid?
      instances_before = space_edit_definition_instances(old_definition)
      lock_conflict_before = space_edit_definition_lock_conflict?(entity)
      return false unless instances_before.length > 1 || lock_conflict_before

      if instances_before.length <= 1 && lock_conflict_before
        log("#{label}存在父级锁传播，但当前子 Definition 只有单一实例对象；等待父层先隔离后再处理。")
        return false
      end

      old_name = old_definition.respond_to?(:name) ? old_definition.name.to_s : ''
      new_definition = force_space_edit_instance_unique_definition!(entity, model)
      return false unless new_definition && new_definition.valid?
      if new_definition.equal?(old_definition) && instances_before.length > 1
        log("#{label}请求唯一化后 Definition 未变化：#{old_name.empty? ? '(未命名)' : old_name}")
        return false
      end

      if entity.respond_to?(:set_attribute)
        entity.set_attribute(ENTITY_DICT, 'space_edit_unique_guard_schema', 3)
        entity.set_attribute(ENTITY_DICT, 'space_edit_unique_guard_at', Time.now.iso8601(6))
      end
      if new_definition.respond_to?(:set_attribute)
        new_definition.set_attribute(ENTITY_DICT, 'space_edit_unique_guard_schema', 3)
      end
      instances_after = space_edit_definition_instances(new_definition).length
      lock_after = space_edit_definition_lock_conflict?(entity)
      log("自动隔离空间编辑Definition：#{label} / #{old_name.empty? ? '(未命名)' : old_name} / 原实例#{instances_before.length} -> 新实例#{instances_after}#{lock_after ? ' / 仍有锁传播' : ''}")
      true
    rescue StandardError => e
      log_exception("隔离#{label}共享Definition失败", e)
      false
    end

    def space_edit_shared_spine_nodes(space_entity, limit: 12)
      result = []
      return result unless space_entity && space_entity.valid?
      current = space_entity
      depth = 0
      max_depth = [[limit.to_i, 1].max, 32].min
      while current && current.valid? && depth < max_depth
        shared = space_edit_definition_shared?(current)
        conflict = space_edit_definition_lock_conflict?(current)
        if shared || conflict
          definition = current.definition rescue nil
          result << {
            depth: depth, entity: current,
            name: (definition && definition.valid? && definition.respond_to?(:name) ? definition.name.to_s : ''),
            instances: (definition && definition.valid? ? space_edit_definition_instances(definition).length : 0),
            lock_conflict: conflict
          }
        end
        child = space_edit_single_container_child(current)
        break unless child && child.valid?
        current = child
        depth += 1
      end
      result
    rescue StandardError
      []
    end

    def isolate_space_edit_definition_spine!(space_entity, model = Sketchup.active_model, limit: 12)
      return { changed: false, count: 0, remaining: 0, remaining_lock_conflicts: 0 } unless space_entity && space_entity.valid? && model
      changed = 0
      current = space_entity
      depth = 0
      max_depth = [[limit.to_i, 1].max, 32].min
      while current && current.valid? && depth < max_depth
        if make_space_edit_node_unique_if_lock_conflict!(current, depth.zero? ? '空间根' : "核心层#{depth}", model)
          changed += 1
        end
        child = space_edit_single_container_child(current)
        break unless child && child.valid?
        current = child
        depth += 1
      end

      remaining_nodes = space_edit_shared_spine_nodes(space_entity, limit: limit)
      remaining_lock_nodes = remaining_nodes.select { |row| row[:lock_conflict] == true }
      model.active_view.invalidate if changed.positive? && model.respond_to?(:active_view)
      if remaining_nodes.any?
        detail = remaining_nodes.first(6).map do |row|
          suffix = row[:lock_conflict] ? '锁风险' : '普通共享'
          "L#{row[:depth]} #{row[:name].to_s.empty? ? '(未命名)' : row[:name]}×#{row[:instances]}(#{suffix})"
        end.join('、')
        log("空间编辑Definition隔离后仍有诊断项：#{detail}")
      end
      {
        changed: changed.positive?, count: changed,
        remaining: remaining_nodes.length, remaining_nodes: remaining_nodes,
        remaining_lock_conflicts: remaining_lock_nodes.length,
        remaining_lock_nodes: remaining_lock_nodes
      }
    rescue StandardError => e
      log_exception('自动隔离空间编辑共享Definition失败', e)
      # 0.13.6.91 的 remaining=-1 会被入口当成硬失败，导致新建空空间也无法进入。
      # 0.13.6.92 明确把诊断异常降级为“未完成隔离”，由空间根锁校验 + 双击桥继续兜底。
      { changed: false, count: 0, remaining: 0, remaining_nodes: [], remaining_lock_conflicts: 0, error: e.message.to_s }
    end

    def space_edit_spine_member?(space_entity, candidate, limit: 12)
      return false unless space_entity && space_entity.valid? && candidate && candidate.valid?
      current = space_entity
      depth = 0
      max_depth = [[limit.to_i, 1].max, 32].min
      while current && current.valid? && depth < max_depth
        child = space_edit_single_container_child(current)
        return false unless child && child.valid?
        return true if child.equal?(candidate)
        current = child
        depth += 1
      end
      false
    rescue StandardError
      false
    end

    # v0.13.6.97：锁冲突并不只发生在“唯一子容器脊柱”。只要当前选择实体位于
    # LinkHub 空间当前 active_entities 中，它就可能因为其它已锁空间复用了同一
    # Definition 而触发 SketchUp 原生“部分实例已锁定”弹窗。
    def space_edit_candidate_in_current_context?(space_entity, candidate, model = Sketchup.active_model)
      return false unless space_entity && space_entity.valid? && candidate && candidate.valid? && model
      path = Array(model.active_path)
      return false if path.empty? || path.first != space_entity
      active_entities = model.respond_to?(:active_entities) ? model.active_entities : nil
      parent = candidate.respond_to?(:parent) ? candidate.parent : nil
      active_entities && parent.equal?(active_entities)
    rescue StandardError
      false
    end

    # 已经在空间内部时，用户可能从核心组退回一层后立刻再次双击进入。
    # 这条路径不会重新执行 begin_space_edit_state!，所以在双击桥接工具里再放一道
    # 按需修复：仅当选中的实体确实位于空间单一编辑脊柱、且存在 Definition 锁冲突时接管。
    def enter_space_spine_entity_with_definition_isolation!(candidate, model = Sketchup.active_model)
      raise '空间核心编辑对象不可用。' unless candidate && candidate.valid? && model
      original_path = Array(model.active_path)
      raise '当前不在 LinkHub 空间内部。' if original_path.empty?
      state, item, space_entity = current_local_editing_space(nil, model, required: false)
      raise '当前空间没有有效的 LinkHub 修改占用。' unless item && space_entity && space_entity.valid?
      raise '该对象不在当前空间的活动编辑层级。' unless space_edit_candidate_in_current_context?(space_entity, candidate, model)

      # 当前父编辑层必须已经属于本空间独立沙箱。若父层本身仍共享，直接改其子实例
      # Definition 会同步影响父层的其它 occurrence；这种情况宁可阻止本次进入，也绝不
      # 执行“全部解锁”或跨空间改写。正常由 LinkHub 从空间根进入时父层都会满足此条件。
      parent_node = original_path.last
      if parent_node && (space_edit_definition_shared?(parent_node) || space_edit_definition_lock_conflict?(parent_node))
        raise '当前父编辑层仍与其它实例共享。请先退回上一层再重新进入；LinkHub 不会解锁其它空间。'
      end

      operation_started = false
      model.start_operation('进入空间嵌套组', true, false, true)
      operation_started = true
      # 先解开当前实例自身的原生锁；其它实例一律不动。随后只对当前层做 Definition 隔离。
      candidate.locked = false if candidate.respond_to?(:locked=) && candidate.respond_to?(:locked?) && candidate.locked?
      isolated = make_space_edit_node_unique_if_lock_conflict!(candidate, '双击嵌套层', model)
      # 0.13.6.92 不再因为普通 shared 阻断进入；只有仍存在“有效锁传播”时才停止，
      # 否则 SketchUp 不会弹“部分实例已锁定”，普通共享由本次隔离尽力切断。
      nested_lock_conflict = space_edit_definition_lock_conflict?(candidate)
      nested_instance_count = space_edit_definition_instances(candidate.definition).length rescue -1
      log("空间嵌套层进入前锁诊断：definition=#{definition_identity_key(candidate.definition)} / instances=#{nested_instance_count} / conflict=#{nested_lock_conflict} / isolated=#{isolated}")
      if nested_lock_conflict
        raise '当前嵌套层仍存在锁定 occurrence 传播，LinkHub 已阻止 SketchUp 原生“全部解锁/设为唯一”弹窗。请退回上一层后重试；其它实例不会被解锁。'
      end
      model.commit_operation
      operation_started = false

      model.selection.clear
      model.selection.add(candidate)
      model.active_path = original_path + [candidate] if model.respond_to?(:active_path=)
      unless Array(model.active_path).include?(candidate)
        raise 'SketchUp 未能进入该核心组。'
      end
      model.active_view.invalidate if model.respond_to?(:active_view)
      show_status(isolated ? '已自动将当前嵌套层设为独立 Definition 并进入编辑；其它锁定实例未受影响。' : '已进入当前空间嵌套层。', 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      raise
    end

    def remove_unused_space_definition_graph!(definitions, model = Sketchup.active_model)
      pending = Array(definitions).compact.uniq.reject { |definition| standard_soft_publish_proxy_definition?(definition) }
      removed = 0
      loop do
        removed_this_pass = 0
        pending.delete_if do |definition|
          next true unless definition && definition.valid?
          next false unless definition.respond_to?(:instances) && definition.instances.empty?
          begin
            ok = model.definitions.respond_to?(:remove) ? model.definitions.remove(definition) : false
            if ok
              removed += 1
              removed_this_pass += 1
              true
            else
              false
            end
          rescue StandardError
            false
          end
        end
        break if removed_this_pass.zero? || pending.empty?
      end
      removed
    end

    def retire_existing_space_before_fresh_load!(space_id, previous, model = Sketchup.active_model)
      instances = space_model_entities(model).select do |entity|
        entity && entity.valid? && entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s == space_id.to_s
      end
      instances << previous if previous && previous.valid? && !instances.include?(previous)
      definitions = instances.flat_map do |entity|
        entity.respond_to?(:definition) ? collect_space_definition_graph(entity.definition) : []
      end.compact.uniq
      instances.each do |entity|
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase! if entity.valid?
      end
      removed = remove_unused_space_definition_graph!(definitions, model)
      invalidate_managed_root_index(model, reason: 'space_fresh_load_retire')
      log("更新前已退休旧空间：#{space_id} / 实例#{instances.length} / 清理定义#{removed}")
      { instances: instances.length, definitions: definitions.length, removed: removed }
    end

    # v0.13.3：本机按需卸载。这里只修改当前工作 SU，不写空间/建筑共享清单，
    # 不删除协同 SKP，也不改变其他成员的加载状态。删除根实例后只清理已经没有任何
    # 实例引用的定义图；共享的标准软装代理定义继续保留，避免影响其他已载入空间。
    def unload_managed_collection_entity!(entity, label:, model: Sketchup.active_model)
      raise '请先退出所有组件编辑层级，再卸载模型。' unless model.active_path.nil?
      return { instances: 0, definitions: 0, removed: 0 } unless entity && entity.valid?
      definitions = entity.respond_to?(:definition) ? collect_space_definition_graph(entity.definition) : []
      entity.locked = false if entity.respond_to?(:locked=)
      model.selection.remove(entity) if model.selection.include?(entity) rescue nil
      entity.erase! if entity.valid?
      removed = remove_unused_space_definition_graph!(definitions, model)
      invalidate_managed_root_index(model, reason: 'local_collection_unload')
      prune_invalid_definition_caches_after_native_purge!(model)
      mark_soft_measurement_dirty(model)
      log("本机卸载 #{label}：定义图#{definitions.length} / 已清理定义#{removed}")
      { instances: 1, definitions: definitions.length, removed: removed }
    end

    def unload_space_model_from_current_model!(space_id, model = Sketchup.active_model)
      # 卸载必须是纯本机操作：即使 NAS/协同目录此刻不可访问，也允许用户先给当前 SU 减负。
      state = load_state(model)
      space = space_model_record(state, space_id)
      raise '找不到该空间。' unless space
      raise '该空间正在后台发布；发布完成前不能卸载当前空间根组件。' if background_publish_active_state?(space)
      if initial_space_publish_pending?(space)
        raise '该空间尚未完成首次发布；为保证本地根实例与待发布候选一致，首次发布完成前不能卸载。可重试发布或删除本地待发布空间。'
      end
      raise '该空间正处于强制解锁历史取物模式。请先退出并恢复进入前状态，再卸载。' if space_force_recovery_active?(space, state)
      entity = space_model_entity(space['id'], model)
      return false unless entity && entity.valid?
      editing_self = space['editing'] == true || space_edit_safe_paused?(space) ||
                     state['space_editing_id'].to_s == space['id'].to_s ||
                     entity.get_attribute(ENTITY_DICT, 'editing', false) == true
      raise '该空间有本机未发布修改。请先发布或使用顶部“取消修改”，再卸载。' if editing_self
      label = space_ui_label(space)
      prompt = <<~TEXT
        是否确认卸载“#{label}”？

        卸载只会从当前工作 SU 中移除这个空间，并清理仅由它使用的本机定义。
        共享空间文件不会删除，其他协同成员不会受到影响；之后仍可从抽屉重新载入。
      TEXT
      return false unless native_confirm_yes?(prompt)
      model.start_operation("卸载 #{label}", true)
      result = unload_managed_collection_entity!(entity, label: label, model: model)
      space['editing'] = false
      space['status'] = '已卸载 · 可随时载入'
      save_state(state, model, write_manifest: false)
      model.commit_operation
      refresh_dialog
      show_status("#{label} 已从当前模型卸载；共享文件未改变，其他协同成员不受影响。", 'success')
      result
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    def unload_architecture_model_from_current_model!(architecture_id, model = Sketchup.active_model)
      # 与室内一致，卸载不读取共享目录，只处理当前工作 SU。
      state = load_state(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      entity = architecture_model_entity(item['id'], model)
      return false unless entity && entity.valid?
      editing_self = item['editing'] == true || space_edit_safe_paused?(item) ||
                     state['architecture_editing_id'].to_s == item['id'].to_s ||
                     entity.get_attribute(ENTITY_DICT, 'editing', false) == true
      raise '该建筑模型有本机未发布修改。请先发布或使用顶部“取消修改”，再卸载。' if editing_self
      label = "建筑：#{architecture_display_name(item, state)}"
      prompt = <<~TEXT
        是否确认卸载“#{label}”？

        卸载只会从当前工作 SU 中移除这个建筑模型，并清理仅由它使用的本机定义。
        共享建筑文件不会删除，其他协同成员不会受到影响；之后仍可从抽屉重新载入。
      TEXT
      return false unless native_confirm_yes?(prompt)
      model.start_operation("卸载 #{label}", true)
      result = unload_managed_collection_entity!(entity, label: label, model: model)
      item['editing'] = false
      item['status'] = '已卸载 · 可随时载入'
      save_state(state, model, write_manifest: false)
      model.commit_operation
      refresh_dialog
      show_status("#{label} 已从当前模型卸载；共享文件未改变，其他协同成员不受影响。", 'success')
      result
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    # 更新回滚目录必须基于当前协同项目，而不是调用并不存在的 project_path。
    # 未保存的新工作 SU 也允许通过已连接的协同.json建立稳定目录；只有完全未连接时
    # 才退回当前模型路径/GUID，避免空路径和跨项目共用同一回滚目录。
    def space_update_project_identity(model = Sketchup.active_model)
      # 只读身份计算会被清单草稿持久化高频调用；优先复用内部状态缓存，
      # 避免对大型项目状态做整树 deep_dup。绝不把该引用传入任何写操作。
      state = cached_project_state_readonly(model) || load_state(model)
      basis = selected_collab_project_dir_for_state(state, model).to_s
      if basis.empty?
        raw_json = state['collab_project_json'].to_s
        resolved_json = resolve_collab_json_value(raw_json, model) rescue ''
        basis = resolved_json.to_s unless resolved_json.to_s.empty?
      end
      basis = model.path.to_s if basis.empty? && model && model.respond_to?(:path)
      basis = model.guid.to_s if basis.empty? && model && model.respond_to?(:guid)
      basis = "#{model.title}|#{model.object_id}" if basis.empty? && model
      basis = 'unbound-project' if basis.to_s.empty?
      FastPath.expand(basis.to_s) rescue basis.to_s
    rescue StandardError
      model && model.respond_to?(:guid) ? model.guid.to_s : 'unbound-project'
    end

    def space_update_rollback_directory(model = Sketchup.active_model)
      base = ENV['LOCALAPPDATA'].to_s
      base = File.join(Dir.tmpdir, 'SU_LinkHub_Local') if base.empty?
      project_token = Digest::SHA1.hexdigest(space_update_project_identity(model))[0, 12]
      dir = File.join(base, 'SU_LinkHub', 'space_update_rollback', project_token)
      FileUtils.mkdir_p(dir)
      dir
    end

    def create_space_update_rollback_snapshot!(item, entity, model = Sketchup.active_model)
      return '' unless entity && entity.valid? && entity.respond_to?(:definition)
      safe_name = safe_space_filename("#{item['number']}_#{item['name']}")
      path = File.join(space_update_rollback_directory(model), "#{safe_name}_#{Time.now.strftime('%Y%m%d_%H%M%S')}.skp")
      saved = if entity.definition.respond_to?(:save_copy)
                entity.definition.save_copy(path)
              else
                entity.definition.save_as(path)
              end
      raise '无法创建更新前回滚副本。' unless saved != false && File.file?(path) && File.size(path).positive?
      prefix = File.join(space_update_rollback_directory(model), "#{safe_name}_*.skp")
      Dir.glob(prefix).sort_by { |candidate| File.mtime(candidate) rescue Time.at(0) }.reverse_each.with_index do |candidate, index|
        File.delete(candidate) if index >= 3 && File.file?(candidate)
      rescue StandardError
        next
      end
      log("已创建空间更新回滚副本：#{path}")
      path
    rescue StandardError => e
      log_exception('创建空间更新回滚副本失败', e)
      raise
    end

    def unique_space_load_alias(path, item, revision)
      dir = File.join(cache_directory, 'load_alias')
      FileUtils.mkdir_p(dir)
      safe_id = item['id'].to_s.gsub(/[^0-9A-Za-z]/, '')[0, 12]
      token = Digest::SHA1.hexdigest(revision.to_s)[0, 10]
      target = File.join(dir, "space_#{safe_id}_#{token}_#{SecureRandom.hex(6)}.skp")
      begin
        File.link(path, target)
      rescue StandardError
        FileUtils.cp(path, target)
      end
      raise '无法建立独立的空间载入副本。' unless File.file?(target) && File.size(target) == File.size(path)
      target
    end

    def defer_space_load_alias_cleanup!(path)
      runtime_start_timer(2.5, false, label: 'space_load_alias_cleanup') do
        File.delete(path) if File.file?(path)
      rescue StandardError
        nil
      end
      true
    rescue StandardError
      false
    end

    def definition_object_snapshot(model = Sketchup.active_model)
      model.definitions.to_a.each_with_object({}) do |definition, result|
        result[definition.object_id] = {
          definition: definition,
          instances: (definition.respond_to?(:instances) ? definition.instances.length : 0)
        }
      end
    rescue StandardError
      {}
    end

    def reused_preexisting_definitions(root_definition, snapshot)
      collect_space_definition_graph(root_definition).select do |definition|
        snapshot.key?(definition.object_id) && !standard_soft_publish_proxy_definition?(definition)
      end
    rescue StandardError
      []
    end


    # 清理一次失败载入中新加入、但尚未真正放入模型的定义。先删除最外层，再多轮
    # 删除失去实例引用的子定义，避免失败尝试残留在定义表中并影响下一次载入。
    def remove_definitions_added_since_snapshot!(snapshot, model = Sketchup.active_model)
      pending = model.definitions.to_a.reject { |definition| snapshot.key?(definition.object_id) }
      removed = 0
      loop do
        removed_this_pass = 0
        pending.delete_if do |definition|
          next true unless definition && definition.valid?
          next false unless definition.respond_to?(:instances) && definition.instances.empty?
          begin
            ok = model.definitions.respond_to?(:remove) ? model.definitions.remove(definition) : false
            if ok
              removed += 1
              removed_this_pass += 1
              true
            else
              false
            end
          rescue StandardError
            false
          end
        end
        break if removed_this_pass.zero? || pending.empty?
      end
      removed
    rescue StandardError => e
      log_exception('清理失败载入定义失败', e)
      0
    end

    def with_temporarily_unlocked_instance(instance)
      was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
      instance.locked = false if was_locked && instance.respond_to?(:locked=)
      yield
    ensure
      instance.locked = true if was_locked && instance && instance.valid? && instance.respond_to?(:locked=)
    end

    # SketchUp 会按内层 definition GUID 复用当前工作 SU 中的旧定义。这里不是把
    # 共享包降级成“相信旧定义”，而是先把当前模型里占用这些身份的实例原样迁移到
    # 新定义，再删除旧身份，随后重新载入共享包。组件实例继续共享同一个克隆定义；
    # Group 本来就应独立，逐个 make_unique 不改变几何、材质或位置。
    def quarantine_space_definition_collisions!(definitions, model = Sketchup.active_model)
      collisions = Array(definitions).compact.uniq.select { |definition| definition && definition.valid? }
      moved_instances = 0
      removed_definitions = 0
      unresolved = []

      collisions.each do |definition|
        instances = definition.respond_to?(:instances) ? definition.instances.to_a.select { |instance| instance && instance.valid? } : []
        groups, components = instances.partition { |instance| instance.is_a?(Sketchup::Group) }

        unless components.empty?
          seed = components.shift
          replacement_definition = nil
          with_temporarily_unlocked_instance(seed) do
            replacement_definition = force_space_instance_unique_definition!(seed, model)
          end
          moved_instances += 1
          components.each do |instance|
            with_temporarily_unlocked_instance(instance) do
              instance.definition = replacement_definition
            end
            moved_instances += 1
          end
        end

        groups.each do |group|
          with_temporarily_unlocked_instance(group) do
            force_space_instance_unique_definition!(group, model)
          end
          moved_instances += 1
        end

        if definition.valid? && definition.respond_to?(:instances) && definition.instances.empty?
          begin
            removed = model.definitions.respond_to?(:remove) ? model.definitions.remove(definition) : false
            removed_definitions += 1 if removed
          rescue StandardError
            nil
          end
        end
        unresolved << definition if definition.valid? && definition.respond_to?(:instances) && !definition.instances.empty?
      rescue StandardError => e
        log_exception("隔离冲突定义失败：#{definition.respond_to?(:name) ? definition.name : definition.object_id}", e)
        unresolved << definition if definition && definition.valid?
      end

      unless unresolved.empty?
        names = unresolved.first(6).map { |definition| definition.name.to_s }.reject(&:empty?)
        detail = names.empty? ? unresolved.length.to_s : names.join('、')
        raise "无法安全释放旧组件定义身份（#{detail}）。更新已回滚，当前模型内容未被替换。"
      end

      invalidate_managed_root_index(model, reason: 'space_definition_collision_quarantine')
      {
        definitions: collisions.length,
        instances: moved_instances,
        removed: removed_definitions
      }
    end

    # 每次使用唯一临时路径还不足以阻止 SketchUp 复用内层定义。先探测载入结果；
    # 若发现与当前模型定义表碰撞，就清理本次候选、隔离碰撞身份并重新载入。
    # 最多重试两次，始终处在调用方的单一 SketchUp operation 内，失败可完整回滚。
    def load_space_definition_collision_safe!(path, item, revision, model = Sketchup.active_model)
      attempts = 0
      snapshot = definition_object_snapshot(model)

      loop do
        attempts += 1
        load_alias = unique_space_load_alias(path, item, "#{revision}|attempt#{attempts}")
        definition = nil
        begin
          definition = load_definition_compat(model.definitions, load_alias)
        ensure
          defer_space_load_alias_cleanup!(load_alias) if load_alias
        end
        raise 'SketchUp 未能载入空间模型。' unless definition

        reused = reused_preexisting_definitions(definition, snapshot)
        if reused.empty?
          log("空间定义干净载入：#{item['number']}:#{item['name']} / 尝试#{attempts}") if attempts > 1
          return [definition, snapshot, attempts]
        end

        names = reused.first(6).map { |candidate| candidate.name.to_s }.reject(&:empty?)
        detail = names.empty? ? reused.length.to_s : names.join('、')
        removed = remove_definitions_added_since_snapshot!(snapshot, model)
        if attempts >= 3
          raise "共享空间包连续复用了当前 SU 的旧内层定义（#{detail}）。已自动隔离两次仍未成功，更新已回滚。"
        end

        result = quarantine_space_definition_collisions!(reused, model)
        log(
          "空间定义碰撞已自动隔离：#{item['number']}:#{item['name']} / "           "定义#{result[:definitions]} / 实例#{result[:instances]} / 删除#{result[:removed]} / "           "清理候选#{removed} / 准备第#{attempts + 1}次载入"
        )
        snapshot = definition_object_snapshot(model)
      end
    end

    def mark_space_model_entity!(entity, item, stored_path, signature, model = Sketchup.active_model, representation: 'full', revision: '', invalidate_index: true, structure: nil, verified_package_revision: nil, verified_package_identity: nil, verified_package_schema: SPACE_LOAD_VERIFIED_SCHEMA, preserve_transformation: false)
      collection_key = space_record_collection_key(item)
      structure ||= ensure_professional_structure(collection_key, model)
      mark_entity(
        entity,
        discipline: collection_key,
        kind: 'space_model',
        source: stored_path,
        display_name: "#{item['number']}:#{item['name']}.skp",
        tag: structure[:model_tag],
        mode: 'absolute_world',
        signature: signature,
        locked: true,
        editing: false
      )
      entity.set_attribute(ENTITY_DICT, 'space_id', item['id'].to_s)
      entity.set_attribute(ENTITY_DICT, 'space_number', item['number'].to_i)
      entity.set_attribute(ENTITY_DICT, 'space_collection_key', collection_key)
      entity.set_attribute(ENTITY_DICT, 'source_file_signature', signature.to_s)
      entity.set_attribute(ENTITY_DICT, 'source_revision', revision.to_s) unless revision.to_s.empty?
      unless verified_package_revision.nil?
        entity.set_attribute(ENTITY_DICT, 'source_load_verified_schema', verified_package_schema.to_i)
        entity.set_attribute(ENTITY_DICT, 'source_verified_signature', signature.to_s)
        entity.set_attribute(ENTITY_DICT, 'source_package_revision', verified_package_revision.to_s)
        entity.set_attribute(ENTITY_DICT, 'source_package_identity', verified_package_identity.to_s)
      end
      entity.set_attribute(ENTITY_DICT, 'source_published_at', item['last_publish_at'].to_s)
      begin
        resolved_source = resolve_path(stored_path.to_s, model)
        entity.set_attribute(ENTITY_DICT, 'source_file_mtime', File.mtime(resolved_source).to_f) if File.file?(resolved_source)
      rescue StandardError
        nil
      end
      normalized_representation = representation.to_s == 'proxy' ? 'proxy' : 'full'
      entity.set_attribute(ENTITY_DICT, 'space_representation', normalized_representation)
      entity.set_attribute(ENTITY_DICT, 'space_representation_verified', normalized_representation)
      entity.set_attribute(ENTITY_DICT, 'space_representation_verified_signature', signature.to_s)
      entity.delete_attribute(ENTITY_DICT, 'space_package_representation_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_revision_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_space_id_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_identity_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_wrapper_schema_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_graph_schema_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_graph_count_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_graph_hash_hint') rescue nil
      entity.delete_attribute(ENTITY_DICT, 'space_package_graph_verified_hint') rescue nil
      entity.set_attribute(ENTITY_DICT, 'load_asset_path', stored_path.to_s)
      entity.set_attribute(ENTITY_DICT, 'absolute_world', true)
      entity.transformation = identity_transformation if !preserve_transformation && entity.respond_to?(:transformation=)
      if linked_space_record?(item)
        entity.set_attribute(ENTITY_DICT, 'linked_space', true)
        entity.set_attribute(ENTITY_DICT, 'linked_source_space_id', item['linked_source_space_id'].to_s)
      else
        entity.delete_attribute(ENTITY_DICT, 'linked_space') rescue nil
        entity.delete_attribute(ENTITY_DICT, 'linked_source_space_id') rescue nil
      end
      invalidate_managed_root_index(model, reason: 'mark_space_model') if invalidate_index
      entity
    end

    def smallest_available_space_number(records)
      used = Array(records).map { |item| item.is_a?(Hash) ? item['number'].to_i : 0 }.select(&:positive?).uniq
      number = 1
      number += 1 while used.include?(number)
      number
    end

    def next_space_number!(state)
      number = smallest_available_space_number(state['space_models'])
      # space_next_number 仅作为兼容字段保存；真正编号始终以当前最小空缺为准。
      state['space_next_number'] = number + 1
      number
    end

    def soft_stable_model_id?(value)
      value.to_s.strip.match?(/\A[0-9a-f]{20}\z/i)
    rescue StandardError
      false
    end

    def soft_legacy_proxy_definition?(definition)
      return false unless definition && definition.valid?
      fallback = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_for', '').to_s.strip
      key = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s.strip
      name = definition.respond_to?(:name) ? definition.name.to_s : ''
      !fallback.empty? || !key.empty? || name.start_with?('LH_同尺寸代理_')
    rescue StandardError
      false
    end

    def soft_legacy_proxy_entity?(entity)
      entity && entity.valid? && entity.respond_to?(:definition) && soft_legacy_proxy_definition?(entity.definition)
    rescue StandardError
      false
    end

    # 只有存在 LinkHub 自己留下的明确身份痕迹，实体才有资格进入软装身份解析。
    # 绝不能因为“名称刚好与模型库某项唯一相同”就把普通建筑/硬装 Component/Group
    # 反向认成软装。v0.13.6.14 的清单扫描曾对每个普通组件调用历史恢复器，
    # SketchUp 默认名“组件”因此可能被误绑到模型库中同名条目，造成几十个硬装构件
    # 出现在采购清单并共用同一张缩略图。
    def soft_entity_managed_identity_evidence?(entity, info = nil)
      return false unless entity && entity.valid?
      return true if soft_legacy_proxy_entity?(entity)
      data = info.is_a?(Hash) ? info : soft_instance_metadata(entity)
      return true unless data['model_id'].to_s.strip.empty?
      return true unless data['source_path'].to_s.strip.empty?
      return true unless data['proxy_source_path'].to_s.strip.empty?

      owners = [entity]
      owners << entity.definition if entity.respond_to?(:definition) && entity.definition
      owners.compact.any? do |owner|
        model_id = owner.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s.strip rescue ''
        source = owner.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s.strip rescue ''
        proxy_source = owner.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s.strip rescue ''
        fallback = owner.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_for', '').to_s.strip rescue ''
        fallback_key = owner.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s.strip rescue ''
        managed_tree = owner.get_attribute(SOFT_MODEL_DICT, 'managed_tree', false) rescue false
        representation = owner.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s rescue ''
        model_name = owner.get_attribute(SOFT_MODEL_DICT, 'model_name', '').to_s.strip rescue ''
        !model_id.empty? || !source.empty? || !proxy_source.empty? || !fallback.empty? || !fallback_key.empty? ||
          managed_tree == true || (%w[proxy full].include?(representation) && !model_name.empty?)
      end
    rescue StandardError
      false
    end

    def soft_identity_generic_name?(value)
      text = soft_identity_display_name(value).to_s.downcase.gsub(/[\s_\-－—–﹣‐‑‒#\d]+/, '')
      %w[组件 群组 未命名组件 未命名群组 component componentinstance group].include?(text)
    rescue StandardError
      true
    end

    def soft_identity_display_name(value)
      text = value.to_s.strip.gsub(/\s+/, ' ')
      text = text.sub(/\ALH_同尺寸代理_/, '')
                 .sub(/\ALH_六面代理_/, '')
                 .sub(/\ALH_视觉代理_/, '')
                 .sub(/\ALH_代理_/, '')
                 .strip
      text
    rescue StandardError
      value.to_s.strip
    end

    # 历史代理的名称可能经历过“#1 / -1 / 分类前缀”整理。这里只生成用于
    # 身份恢复的比较形态，不会反向改模型库名称；最终仍必须由其它证据或唯一性约束确认。
    def soft_identity_name_forms(value)
      raw = soft_identity_display_name(value)
      return [] if raw.empty?
      rows = [raw]
      if (match = /[（(]([^（）()]+)[）)]\z/.match(raw))
        rows << match[1].to_s.strip
      end
      rows << raw.sub(/#\d+\z/i, '').strip
      rows << raw.sub(/[\-_\s]+\d+\z/i, '').strip
      rows << raw.gsub(/[\s_\-－—–﹣‐‑‒]+/, '')
      rows.map { |item| item.to_s.strip.downcase }.reject(&:empty?).uniq
    rescue StandardError
      []
    end

    def soft_legacy_proxy_marker_and_bounds(definition)
      return { marker: '', bounds_values: nil, bounds_signature: '' } unless definition && definition.valid?
      marker = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_for', '').to_s.strip
      fallback_key = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s.strip
      signature = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s.strip
      parts = fallback_key.split('|')
      if marker.empty? && !parts.empty?
        candidate = parts.first.to_s.strip
        marker = candidate if candidate.match?(/\A[0-9a-f]{12,20}\z/i)
      end
      if signature.empty? && parts.length >= 7
        signature = parts[1, 6].join('|')
      end
      values = begin
        parsed = signature.split('|').map { |item| Float(item) }
        soft_bounds_values_valid?(parsed) ? parsed.map(&:to_f) : nil
      rescue StandardError
        nil
      end
      { marker: marker, bounds_values: values, bounds_signature: signature, fallback_key: fallback_key }
    rescue StandardError
      { marker: '', bounds_values: nil, bounds_signature: '' }
    end

    def soft_bounds_extents_from_values(values)
      data = Array(values).map(&:to_f)
      return nil unless data.length == 6
      result = [
        (data[3] - data[0]).abs,
        (data[4] - data[1]).abs,
        (data[5] - data[2]).abs
      ]
      return nil if result.any? { |value| value < 1.0e-9 }
      result
    rescue StandardError
      nil
    end

    # 返回任意 XYZ 轴置换后的最小相对误差。历史白盒可能是“旧横轴”，而模型库
    # 已经归正为世界 Z，所以恢复身份时必须允许六种轴排列；这里只比较形状，不改实例。
    def soft_legacy_proxy_bounds_match_error(proxy_values, candidate_values)
      left = soft_bounds_extents_from_values(proxy_values)
      right = soft_bounds_extents_from_values(candidate_values)
      return Float::INFINITY unless left && right
      best = Float::INFINITY
      left.permutation.each do |permutation|
        error = permutation.each_with_index.map do |value, index|
          denominator = [right[index].to_f.abs, 1.0e-9].max
          (value.to_f.abs - right[index].to_f.abs).abs / denominator
        end.max.to_f
        best = error if error < best
      end
      best
    rescue StandardError
      Float::INFINITY
    end

    def soft_library_candidate_name_values(item)
      return [] unless item.is_a?(Hash)
      path = item['path'].to_s
      [
        item['name'].to_s,
        item['logical_name'].to_s,
        (path.empty? ? '' : File.basename(path, File.extname(path)))
      ].map { |value| soft_identity_display_name(value) }.reject(&:empty?).uniq
    rescue StandardError
      []
    end

    # 只读解析一个历史白盒最可能对应的当前模型库条目。自动认领必须满足强证据：
    # 1) 稳定 20 位 model_id / 有效当前路径；或
    # 2) 旧 12 位名称指纹；或
    # 3) 唯一名称 + 尺寸/轴置换证据。
    # 证据接近时返回 nil，宁可让白盒保持原位，也绝不猜错真模型。
    def recover_legacy_soft_library_item(info, model = Sketchup.active_model)
      data = info.is_a?(Hash) ? info : {}
      model_id = data['model_id'].to_s.strip
      source = data['source_path'].to_s.strip
      source = auto_relocate(source, model) unless source.empty?
      if soft_stable_model_id?(model_id)
        direct = soft_library_item(model_id, force: false, source_path: source) rescue nil
        direct_path = direct.is_a?(Hash) ? direct['path'].to_s : ''
        source_agrees = source.empty? || direct_path.empty? || same_file_path?(direct_path, source) || !File.file?(source)
        return direct if direct && source_agrees && File.file?(direct_path)
      end

      external_source_fallback = nil
      if !source.empty? && File.file?(source)
        scan_soft_library!(force: false)
        cache = @soft_library_cache
        row = Array(cache.is_a?(Hash) ? cache[:items] : []).find do |candidate|
          same_file_path?(candidate['path'].to_s, source)
        rescue StandardError
          false
        end
        return row if row && File.file?(row['path'].to_s)
        fallback = {
          'id' => soft_model_id_for_path(source),
          'path' => FastPath.expand(source),
          'name' => (data['model_name'].to_s.empty? ? File.basename(source, File.extname(source)) : data['model_name'].to_s)
        }
        # 旧路径如果还指向模型库外的原始素材，先继续用 marker/name/bounds 反查
        # 当前“已整理模型库”；只有完全找不到当前库身份时才把这个旧文件作为最后兜底。
        return fallback if soft_library_source_path?(source)
        external_source_fallback = fallback
      end

      marker = data['legacy_proxy_marker'].to_s.strip
      marker = data['fallback_proxy_for'].to_s.strip if marker.empty?
      legacy_authorized = data['legacy_proxy'] == true || !marker.empty? ||
                          !data['fallback_proxy_key'].to_s.strip.empty? ||
                          soft_bounds_values_valid?(data['legacy_proxy_bounds_values'])
      # 没有历史代理证据时绝不进入名称/尺寸猜测。普通硬装即使叫“组件”，
      # 也只能返回 nil，不允许因为模型库中恰好有唯一同名项而被认成软装。
      return external_source_fallback unless legacy_authorized
      if soft_stable_model_id?(marker)
        direct = soft_library_item(marker, force: false, source_path: source) rescue nil
        return direct if direct && File.file?(direct['path'].to_s)
      end

      scan_soft_library!(force: false)
      cache = @soft_library_cache
      # 扫描缓存本身已经来自已整理库的 SKP 列表。这里不能为“每一个旧白盒”
      # 再对整个模型库逐文件 File.file?，否则几十个白盒 × 上千个 NAS 模型会形成
      # 数万次网络 stat。先纯内存打分，只对最高分少量候选做存在性确认。
      items = Array(cache.is_a?(Hash) ? cache[:items] : []).select { |row| row.is_a?(Hash) && !row['path'].to_s.empty? }
      return external_source_fallback if items.empty?

      proxy_names = Array(data['identity_names'])
      proxy_names += [data['model_name'].to_s]
      proxy_forms = proxy_names.flat_map { |value| soft_identity_name_forms(value) }.uniq
      proxy_bounds = data['legacy_proxy_bounds_values']
      proxy_path = data['proxy_source_path'].to_s

      scored = items.map do |item|
        score = 0
        evidence = []
        candidate_names = soft_library_candidate_name_values(item)
        candidate_forms = candidate_names.flat_map { |value| soft_identity_name_forms(value) }.uniq

        # 早期白盒 fallback_proxy_for 是 Digest::SHA1.hexdigest(model_name)[0, 12]。
        marker_match = false
        if marker.match?(/\A[0-9a-f]{12}\z/i)
          marker_match = candidate_names.any? { |name| Digest::SHA1.hexdigest(name.to_s)[0, 12].casecmp(marker).zero? }
          if marker_match
            score += 150
            evidence << '旧名称指纹'
          end
        end

        exact_name = !(proxy_forms & candidate_forms).empty?
        meaningful_name = proxy_forms.any? { |form| !soft_identity_generic_name?(form) }
        exact_name = false unless meaningful_name
        if exact_name
          score += 70
          evidence << '名称'
        end

        unless proxy_path.empty?
          item_proxy = item['proxy_path'].to_s
          if !item_proxy.empty? && same_file_path?(proxy_path, item_proxy)
            score += 180
            evidence << '代理路径'
          end
        end

        bounds_error = Float::INFINITY
        if soft_bounds_values_valid?(proxy_bounds) && soft_bounds_values_valid?(item['bounds_values'])
          bounds_error = soft_legacy_proxy_bounds_match_error(proxy_bounds, item['bounds_values'])
          if bounds_error <= 0.01
            score += 80
            evidence << '尺寸≤1%'
          elsif bounds_error <= 0.03
            score += 65
            evidence << '尺寸≤3%'
          elsif bounds_error <= 0.06
            score += 45
            evidence << '尺寸≤6%'
          elsif bounds_error <= 0.12
            score += 20
            evidence << '尺寸≤12%'
          end
        end

        {
          item: item,
          score: score,
          marker_match: marker_match,
          exact_name: exact_name,
          bounds_error: bounds_error,
          evidence: evidence
        }
      end.select { |row| row[:score].positive? }
      return external_source_fallback if scored.empty?
      scored.sort_by! { |row| [-row[:score].to_i, row[:bounds_error].to_f, row[:item]['name'].to_s.downcase] }
      # 只验证少量最高分候选的实际文件，避免全库 NAS stat。若缓存里最高分条目已经
      # 被手工删除，允许后面的同等可信候选接替，而不是因为一个陈旧目录缓存直接失败。
      live_scored = scored.first(8).select { |row| File.file?(row[:item]['path'].to_s) rescue false }
      return external_source_fallback if live_scored.empty?
      best = live_scored[0]
      second = live_scored[1]

      # 旧 12 位指纹几乎等价于稳定身份；但若发生极小概率碰撞，仍要求第一名有明显优势。
      accepted = if best[:marker_match]
                   second.nil? || !second[:marker_match] || (best[:score].to_i - second[:score].to_i) >= 20
                 elsif best[:exact_name]
                   same_name = live_scored.select { |row| row[:exact_name] }
                   same_name.length == 1 || (best[:score].to_i >= 115 && (second.nil? || best[:score].to_i - second[:score].to_i >= 25))
                 else
                   best[:score].to_i >= 140 && (second.nil? || best[:score].to_i - second[:score].to_i >= 35)
                 end
      return external_source_fallback unless accepted

      result = best[:item].dup
      result['_identity_recovered'] = true
      result['_identity_recovery_evidence'] = best[:evidence].join('+')
      result
    rescue StandardError => e
      log_exception('恢复历史白盒模型身份失败', e)
      nil
    end

    def soft_instance_metadata(entity)
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      model_id = entity.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
      source_path = entity.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
      model_name = entity.get_attribute(SOFT_MODEL_DICT, 'model_name', '').to_s
      proxy_source_path = entity.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s
      identity_names = []
      identity_names << model_name unless model_name.empty?
      identity_names << entity.name.to_s if entity.respond_to?(:name) && !entity.name.to_s.empty?
      legacy = { marker: '', bounds_values: nil, bounds_signature: '', fallback_key: '' }
      if definition
        model_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s if model_id.empty?
        source_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s if source_path.empty?
        model_name = definition.get_attribute(SOFT_MODEL_DICT, 'model_name', '').to_s if model_name.empty?
        proxy_source_path = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s if proxy_source_path.empty?
        identity_names << definition.get_attribute(SOFT_MODEL_DICT, 'model_name', '').to_s
        identity_names << definition.name.to_s if definition.respond_to?(:name)
        legacy = soft_legacy_proxy_marker_and_bounds(definition)

        # 早期白盒 fallback_proxy_for 有两种语义：20 位是真 model_id；12 位只是
        # SHA1(model_name) 的历史名称指纹。只有 20 位稳定 id 才能写进 model_id，
        # 绝不再把 12 位 marker 当成 model_id 送进模型库索引。
        if model_id.empty? && soft_stable_model_id?(legacy[:marker])
          model_id = legacy[:marker]
        end
        if model_name.empty? && definition.respond_to?(:name)
          model_name = soft_identity_display_name(definition.name.to_s)
        end
      end
      identity_names << model_name unless model_name.empty?
      {
        'model_id' => model_id,
        'source_path' => source_path,
        'model_name' => soft_identity_display_name(model_name),
        'proxy_source_path' => proxy_source_path,
        'legacy_proxy_marker' => legacy[:marker].to_s,
        'fallback_proxy_for' => legacy[:marker].to_s,
        'fallback_proxy_key' => legacy[:fallback_key].to_s,
        'legacy_proxy_bounds_values' => legacy[:bounds_values],
        'proxy_full_bounds_signature' => legacy[:bounds_signature].to_s,
        'legacy_proxy' => !!(definition && soft_legacy_proxy_definition?(definition)),
        'identity_names' => identity_names.map { |value| soft_identity_display_name(value) }.reject(&:empty?).uniq
      }
    rescue StandardError
      { 'model_id' => '', 'source_path' => '', 'model_name' => '', 'identity_names' => [] }
    end

    # 需要真正操作旧代理时，再把只读历史身份解析到“当前模型库”。
    # 日常注册表扫描仍使用 soft_instance_metadata，避免每个观察器回调都触发模型库扫描。
    def resolved_soft_instance_metadata(entity, model = Sketchup.active_model)
      info = soft_instance_metadata(entity).dup
      # 普通 Component/Group 只允许作为容器继续递归，禁止进入“按名称反查模型库”。
      # 历史白盒恢复只服务于已经有 LinkHub 身份痕迹的实体。
      return info unless soft_entity_managed_identity_evidence?(entity, info)
      model_id = info['model_id'].to_s.strip
      if soft_stable_model_id?(model_id)
        direct = soft_library_item(model_id, force: false, source_path: info['source_path'].to_s, include_proxy: false) rescue nil
        source_hint = info['source_path'].to_s
        direct_path = direct.is_a?(Hash) ? direct['path'].to_s : ''
        source_agrees = source_hint.empty? || direct_path.empty? || same_file_path?(direct_path, source_hint) || !File.file?(source_hint)
        if direct && source_agrees && File.file?(direct_path)
          info['source_path'] = direct['path'].to_s
          info['model_name'] = direct['name'].to_s unless direct['name'].to_s.empty?
          return info
        end
      end

      source = info['source_path'].to_s
      source = auto_relocate(source, model) unless source.empty?
      if !source.empty? && File.file?(source)
        info['source_path'] = FastPath.expand(source)
      end
      item = full_soft_library_item_for(info, model)
      if item
        info['model_id'] = item['id'].to_s unless item['id'].to_s.empty?
        info['source_path'] = item['path'].to_s
        info['model_name'] = item['name'].to_s unless item['name'].to_s.empty?
      end
      info
    rescue StandardError
      soft_instance_metadata(entity)
    end

    def collect_soft_instances_in_definition(definition, results = [], trail = {})
      return results unless definition && definition.valid?
      oid = definition.object_id
      return results if trail[oid]
      next_trail = trail.merge(oid => true)
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        metadata = soft_instance_metadata(entity)
        # v0.13.6.13：旧白盒可能完全没有 model_id，只剩 fallback_proxy_for/key。
        # 它仍然是“受管家具”，必须出现在批量救援、代真切换和清单扫描里，而不是
        # 被当成普通父组件递归穿过去后永久漏掉。
        if !metadata['model_id'].to_s.empty? || soft_legacy_proxy_entity?(entity)
          results << entity
        else
          collect_soft_instances_in_definition(entity.definition, results, next_trail)
        end
      end
      results.uniq
    rescue StandardError
      results.uniq
    end

    def soft_instance_registry_revision(model = Sketchup.active_model)
      @soft_instance_registry_revisions ||= {}
      @soft_instance_registry_revisions[model.object_id].to_i
    rescue StandardError
      0
    end

    def bump_soft_instance_registry_revision(model = Sketchup.active_model)
      return 0 unless model
      @soft_instance_registry_revisions ||= {}
      key = model.object_id
      @soft_instance_registry_revisions[key] = @soft_instance_registry_revisions[key].to_i + 1
    rescue StandardError
      0
    end

    def soft_representation_switching?(model = Sketchup.active_model)
      (@soft_representation_switch_models || {})[model.object_id].to_i.positive?
    rescue StandardError
      false
    end

    def with_soft_representation_switch(model = Sketchup.active_model)
      @soft_representation_switch_models ||= Hash.new(0)
      key = model.object_id
      @soft_representation_switch_models[key] += 1
      begin_soft_heavy_interaction(:representation)
      yield
    ensure
      # ModelObserver 的事务回调在部分 SketchUp 版本中会延迟到 commit_operation
      # 返回后的空闲帧。稍后再解除标记，避免把纯 definition 切换误判为实例树变化。
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.05, false) do
        @soft_representation_switch_models[key] = [@soft_representation_switch_models[key].to_i - 1, 0].max
        @soft_representation_switch_models.delete(key) if @soft_representation_switch_models[key].zero?
        end_soft_heavy_interaction(:representation)
      rescue StandardError
        end_soft_heavy_interaction(:representation)
      end
    end

    def soft_instances_for_space(entity, model = Sketchup.active_model, force: false)
      return [] unless entity && entity.valid? && entity.respond_to?(:definition)
      @soft_instance_registry_cache ||= {}
      model_cache = (@soft_instance_registry_cache[model.object_id] ||= {})
      key = entity.definition.object_id
      revision = soft_instance_registry_revision(model)
      cached = model_cache[key]
      direct_count = entity.definition.entities.length.to_i
      if !force && cached && cached[:revision] == revision && cached[:direct_count].to_i == direct_count
        instances = Array(cached[:instances])
        return instances if instances.all? { |instance| instance && instance.valid? }
      end
      instances = collect_soft_instances_in_definition(entity.definition)
      model_cache[key] = { revision: revision, direct_count: direct_count, instances: instances }
      instances
    rescue StandardError
      collect_soft_instances_in_definition(entity.definition)
    end

    def forget_soft_model_caches(model)
      return false unless model
      key = model.object_id
      [
        @soft_instance_registry_cache,
        @soft_instance_registry_revisions,
        @soft_loaded_definition_caches,
        @soft_proxy_definition_caches,
        @soft_custom_proxy_definition_caches,
        @soft_session_visual_proxy_caches,
        @soft_loaded_visual_proxy_indexes,
        @soft_resident_full_records,
        @soft_resident_cleanup_records,
        @soft_full_definition_tree_caches,
        @soft_representation_pair_caches,
        @soft_representation_scope_cache,
        @soft_managed_definition_cleanup_records,
        @soft_library_file_signature_cache,
        @soft_measurement_revisions,
        @soft_measurement_signatures,
        @soft_measurement_dirty_spaces,
        @soft_measurement_space_row_caches,
        @soft_schedule_location_hit_caches,
        @soft_measurement_observer_scan_records,
        @soft_measurement_burst_tokens,
        @soft_schedule_last_payloads,
        @soft_schedule_last_signatures,
        @soft_schedule_last_payload_jsons,
        @soft_schedule_last_contexts,
        @soft_schedule_metadata_context_caches,
        @soft_schedule_photo_manifest_caches,
        @soft_schedule_snapshot_stale,
        @soft_schedule_snapshot_stale_notified,
        @soft_schedule_thumbnail_attempted,
        @project_state_cache,
        @runtime_last_interaction_at,
        @space_presence_signatures,
        @model_resource_snapshots,
        @model_resource_reconcile_tokens,
        @soft_individual_edit_sessions,
        @space_edit_change_sessions,
        @soft_pending_proxy_rebuilds,
        @soft_individual_edit_prompting,
        @linked_space_copy_placements
      ].compact.each { |cache| cache.delete(key) if cache.respond_to?(:delete) }
      @native_lock_last_full_check&.delete(key)
      if @soft_measurement_entity_space_ids
        @soft_measurement_entity_space_ids.delete_if { |entity_key, _| entity_key.start_with?("#{key}:") }
      end
      @soft_measurement_signatures&.delete_if { |signature_key, _| signature_key.to_s.start_with?("#{key}:") }
      @soft_schedule_sent_signatures&.delete(key)
      @soft_schedule_refresh_tokens&.delete(key)
      if @soft_representation_recent_scope.is_a?(Hash) && @soft_representation_recent_scope[:model_id] == key
        @soft_representation_recent_scope = nil
      end
      true
    rescue StandardError
      false
    end

    # 代/真切换的大部分“第一次卡顿”来自 Ruby 热重载后内存 Hash 被清空：
    # 组件定义仍在 SketchUp 模型中，但运行时必须重新扫描 definitions、空间家具、
    # 源路径签名和有效外包盒。以下桥接只在同一 SketchUp 进程的相邻运行代之间
    # 保存可验证的索引；实体本身仍由各缓存读取函数逐次检查 valid?。
    def export_soft_hot_reload_cache!
      owner = GavinTools::SULinkHubMultiSpace
      payload = {
        schema: SOFT_HOT_RELOAD_CACHE_SCHEMA,
        session_id: GavinTools::SULinkHubMultiSpace::RUNTIME_SESSION_ID.to_s,
        created_at: Time.now.to_f,
        instance_registry_cache: @soft_instance_registry_cache,
        instance_registry_revisions: @soft_instance_registry_revisions,
        loaded_definition_caches: @soft_loaded_definition_caches,
        proxy_definition_caches: @soft_proxy_definition_caches,
        custom_proxy_definition_caches: @soft_custom_proxy_definition_caches,
        session_visual_proxy_caches: @soft_session_visual_proxy_caches,
        loaded_visual_proxy_indexes: @soft_loaded_visual_proxy_indexes,
        resident_full_records: @soft_resident_full_records,
        full_definition_tree_caches: @soft_full_definition_tree_caches,
        representation_pair_caches: @soft_representation_pair_caches,
        definition_bounds_cache: @soft_definition_bounds_cache,
        library_index_cache: @soft_library_index_cache,
        library_file_signature_cache: @soft_library_file_signature_cache,
        individual_edit_sessions: @soft_individual_edit_sessions,
        space_edit_change_sessions: @space_edit_change_sessions,
        pending_proxy_rebuilds: @soft_pending_proxy_rebuilds
      }
      owner.instance_variable_set(:@soft_hot_reload_cache_snapshot, payload)
      true
    rescue StandardError => e
      log_exception('保存热重载代真缓存失败', e)
      false
    end

    def import_soft_hot_reload_cache!
      owner = GavinTools::SULinkHubMultiSpace
      payload = owner.instance_variable_get(:@soft_hot_reload_cache_snapshot)
      return false unless payload.is_a?(Hash)
      return false unless [5, SOFT_HOT_RELOAD_CACHE_SCHEMA].include?(payload[:schema].to_i)
      return false unless payload[:session_id].to_s == GavinTools::SULinkHubMultiSpace::RUNTIME_SESSION_ID.to_s
      return false if Time.now.to_f - payload[:created_at].to_f > SOFT_HOT_RELOAD_CACHE_MAX_AGE

      @soft_instance_registry_cache = payload[:instance_registry_cache] || {}
      @soft_instance_registry_revisions = payload[:instance_registry_revisions] || {}
      @soft_loaded_definition_caches = payload[:loaded_definition_caches] || {}
      @soft_proxy_definition_caches = payload[:proxy_definition_caches] || {}
      @soft_custom_proxy_definition_caches = payload[:custom_proxy_definition_caches] || {}
      @soft_session_visual_proxy_caches = payload[:session_visual_proxy_caches] || {}
      @soft_loaded_visual_proxy_indexes = payload[:loaded_visual_proxy_indexes] || {}
      @soft_resident_full_records = payload[:resident_full_records] || {}
      @soft_full_definition_tree_caches = payload[:full_definition_tree_caches] || {}
      @soft_representation_pair_caches = payload[:representation_pair_caches] || {}
      @soft_definition_bounds_cache = payload[:definition_bounds_cache] || {}
      @soft_library_index_cache = payload[:library_index_cache] || {}
      @soft_library_file_signature_cache = payload[:library_file_signature_cache] || {}
      @soft_individual_edit_sessions = payload[:individual_edit_sessions] || {}
      @space_edit_change_sessions = payload[:space_edit_change_sessions] || {}
      @soft_pending_proxy_rebuilds = payload[:pending_proxy_rebuilds] || {}
      owner.remove_instance_variable(:@soft_hot_reload_cache_snapshot) if owner.instance_variable_defined?(:@soft_hot_reload_cache_snapshot)
      log('已接回上一运行代的家具代真缓存；首次切换无需重新冷扫描。')
      true
    rescue StandardError => e
      log_exception('接回热重载代真缓存失败', e)
      false
    end

    def cancel_soft_cache_warmup!(model = nil)
      @soft_cache_warmup_records ||= {}
      if model
        @soft_cache_warmup_records.delete(model.object_id)
      else
        @soft_cache_warmup_records.clear
      end
      true
    rescue StandardError
      false
    end

    # 完整重启或从旧版本升级时没有可接回的 Ruby 缓存。这里不预载任何外部高模，
    # 只在空闲帧分批登记“当前 SKP 已经存在”的定义、空间实例和外包盒。这样成本
    # 从用户第一次点击代/真按钮前移到后台，同时不破坏建筑/景观的代理优先内存策略。
    def schedule_soft_representation_cache_warmup(model = Sketchup.active_model, delay: 0.65)
      return false unless model
      @soft_cache_warmup_records ||= {}
      key = model.object_id
      token = SecureRandom.hex(8)
      @soft_cache_warmup_records[key] = {
        token: token,
        model: model,
        phase: :prepare,
        definitions: [],
        definition_index: 0,
        spaces: [],
        space_index: 0,
        bounds_definitions: [],
        bounds_index: 0,
        started_at: monotonic_time
      }
      runtime_start_timer(delay.to_f, false, label: '代真缓存后台预热') do
        run_soft_representation_cache_warmup_step(model, token)
      end
      true
    rescue StandardError => e
      log_exception('安排代真缓存后台预热失败', e)
      false
    end

    def run_soft_representation_cache_warmup_step(model, token)
      @soft_cache_warmup_records ||= {}
      key = model.object_id
      record = @soft_cache_warmup_records[key]
      return false unless record && record[:token].to_s == token.to_s
      unless model == Sketchup.active_model || model.respond_to?(:valid?) && model.valid?
        @soft_cache_warmup_records.delete(key)
        return false
      end
      unless background_work_idle?(model)
        runtime_start_timer(BACKGROUND_WORK_RETRY_SECONDS, false, label: '代真缓存预热避让') do
          run_soft_representation_cache_warmup_step(model, token)
        end
        return true
      end

      case record[:phase]
      when :prepare
        record[:definitions] = model.definitions.to_a
        state = load_state(model)
        current_id = soft_measurement_current_space_id(model, state)
        ordered = Array(state['space_models']).sort_by do |item|
          item['id'].to_s == current_id ? 0 : (item['hidden'] ? 2 : 1)
        end
        record[:spaces] = ordered.filter_map do |item|
          entity = space_model_entity(item['id'], model)
          entity if entity && entity.valid?
        rescue StandardError
          nil
        end
        record[:bounds_map] = {}
        record[:phase] = :definitions
      when :definitions
        list = record[:definitions]
        from = record[:definition_index].to_i
        batch = Array(list[from, SOFT_CACHE_WARMUP_DEFINITION_BATCH])
        loaded_cache = soft_loaded_definition_cache(model)
        @soft_proxy_definition_caches ||= {}
        proxy_cache = (@soft_proxy_definition_caches[key] ||= {})
        @soft_custom_proxy_definition_caches ||= {}
        custom_cache = (@soft_custom_proxy_definition_caches[key] ||= {})
        batch.each do |definition|
          next unless definition && definition.valid?
          source = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
          signature = definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s
          unless source.empty? || signature.empty?
            cache_key = [normalize_soft_library_key(source), signature]
            current = loaded_cache[cache_key]
            if current.nil? || (soft_loaded_definition_candidate_rank(definition) <=> soft_loaded_definition_candidate_rank(current)) == 1
              loaded_cache[cache_key] = definition
            end
          end
          fallback_key = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s
          proxy_cache[fallback_key] ||= definition unless fallback_key.empty?
          wrapper_key = definition.get_attribute(SOFT_MODEL_DICT, 'custom_proxy_wrapper_key', '').to_s
          custom_cache[wrapper_key] ||= definition unless wrapper_key.empty?
        rescue StandardError
          next
        end
        record[:definition_index] = from + batch.length
        if record[:definition_index] >= list.length
          @soft_loaded_definition_seed_counts ||= {}
          @soft_loaded_definition_seed_counts[key] = model.definitions.length if model.definitions.length == list.length
          record[:phase] = :spaces
        end
      when :spaces
        spaces = record[:spaces]
        index = record[:space_index].to_i
        entity = spaces[index]
        if entity && entity.valid?
          soft_instances_for_space(entity, model).each do |instance|
            next unless instance && instance.valid?
            definition = instance.definition
            record[:bounds_map][definition.object_id] = definition if definition && definition.valid?
          end
        end
        record[:space_index] = index + 1
        if record[:space_index] >= spaces.length
          record[:bounds_definitions] = record[:bounds_map].values
          record[:phase] = :bounds
        end
      when :bounds
        list = record[:bounds_definitions]
        from = record[:bounds_index].to_i
        batch = Array(list[from, SOFT_CACHE_WARMUP_BOUNDS_BATCH])
        batch.each { |definition| soft_definition_bounds_values(definition) if definition && definition.valid? }
        record[:bounds_index] = from + batch.length
        record[:phase] = :done if record[:bounds_index] >= list.length
      end

      if record[:phase] == :done
        elapsed = elapsed_ms(record[:started_at])
        log("代真缓存后台预热完成：定义 #{record[:definitions].length}，空间 #{record[:spaces].length}，家具定义 #{record[:bounds_definitions].length}，#{elapsed}ms")
        @soft_cache_warmup_records.delete(key)
        return true
      end
      runtime_start_timer(SOFT_CACHE_WARMUP_INTERVAL, false, label: '代真缓存分批预热') do
        run_soft_representation_cache_warmup_step(model, token)
      end
      true
    rescue StandardError => e
      @soft_cache_warmup_records&.delete(model.object_id)
      log_exception('代真缓存后台预热失败', e)
      false
    end

    def effective_space_display_mode(state)
      editing = !state['space_editing_id'].to_s.empty?
      candidate = editing ? state['space_edit_display_mode'].to_s : state['space_display_mode'].to_s
      candidate = state['space_display_mode'].to_s if candidate.empty?
      %w[proxy full].include?(candidate) ? candidate : 'proxy'
    rescue StandardError
      'proxy'
    end

    # 旧版可能出现“状态写着代理，但视口仍是真模型”。快捷条若只按状态反转，
    # 第一次点击会切到已经存在的真模型，看起来仍然没有作用。这里从受管家具
    # 实例读取实际表示；只有全部实例一致时才覆盖状态，混合状态仍按项目设置。
    def actual_space_display_mode(state, model = Sketchup.active_model)
      editing_id = state['space_editing_id'].to_s
      preview_id = state['space_preview_full_id'].to_s
      scope_id = editing_id.empty? ? preview_id : editing_id
      representations = []
      Array(state['space_models']).each do |item|
        next if !scope_id.empty? && item['id'].to_s != scope_id
        entity = space_model_entity(item['id'], model)
        next unless entity && entity.valid?
        root_value = entity.get_attribute(ENTITY_DICT, 'space_representation', '').to_s
        # 锁定的协同引用以根标记为准。旧版每次抽屉刷新都递归枚举所有家具，
        # 空间越多，鼠标悬停和按钮响应越慢。
        if %w[proxy full].include?(root_value) && entity.respond_to?(:locked?) && entity.locked?
          representations << root_value
          next
        end
        soft_instances_for_space(entity, model).each do |instance|
          next unless instance && instance.valid?
          value = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
          if !%w[proxy full].include?(value)
            value = instance.definition.get_attribute(SOFT_MODEL_DICT, 'representation', 'full').to_s rescue 'full'
          end
          representations << (%w[proxy full].include?(value) ? value : 'full')
        end
      end
      return '' if representations.empty?
      return 'proxy' if representations.all? { |value| value == 'proxy' }
      return 'full' if representations.all? { |value| value == 'full' }
      ''
    rescue StandardError
      ''
    end

    def displayed_space_display_mode(state, model = Sketchup.active_model)
      actual = actual_space_display_mode(state, model)
      actual.empty? ? effective_space_display_mode(state) : actual
    rescue StandardError
      effective_space_display_mode(state)
    end

    def toggled_space_display_mode(state, model = Sketchup.active_model)
      displayed_space_display_mode(state, model) == 'proxy' ? 'full' : 'proxy'
    rescue StandardError
      effective_space_display_mode(state) == 'proxy' ? 'full' : 'proxy'
    end

    # 模型库允许在根层级或任意普通组件内临时放置家具。此类家具不属于协同
    # 空间，不能继续依赖 space_models 扫描。只要当前编辑路径不在空间根组件内，
    # 顶部代/真按钮就优先作用于当前选中的受管家具，且不改变任何空间的显示状态。
    def active_edit_context_inside_space?(state, model = Sketchup.active_model)
      path = model.respond_to?(:active_path) ? model.active_path : nil
      return false unless path.is_a?(Array) && !path.empty?
      first = path.first
      Array(state['space_models']).any? do |item|
        entity = space_model_entity(item['id'], model)
        entity && entity.valid? && entity == first
      end
    rescue StandardError
      false
    end

    def soft_instance_representation(instance)
      return '' unless instance && instance.valid? && instance.respond_to?(:definition)
      value = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
      if !%w[proxy full].include?(value)
        value = instance.definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s rescue ''
      end
      %w[proxy full].include?(value) ? value : 'full'
    rescue StandardError
      'full'
    end

    # 不能只相信实例上的 representation 字符串：旧版失败路径可能已经写成 proxy，
    # 但 definition 仍是真模型。这里同时核对实例与定义标记，供切换、入库和发布共用。
    def soft_instance_representation_ready?(instance, representation)
      return false unless instance && instance.valid? && instance.respond_to?(:definition)
      desired = representation.to_s == 'full' ? 'full' : 'proxy'
      instance_mode = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
      definition = instance.definition
      definition_mode = definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s rescue ''
      fallback_marker = definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_for', '').to_s rescue ''
      custom_marker = definition.get_attribute(SOFT_MODEL_DICT, 'custom_proxy_wrapper_key', '').to_s rescue ''
      proxy_definition = definition_mode == 'proxy' || !fallback_marker.empty? || !custom_marker.empty?
      planar_passthrough = soft_instance_planar_reference?(instance)
      if desired == 'proxy'
        instance_mode == 'proxy' && (proxy_definition || planar_passthrough)
      else
        instance_mode == 'full' && (!proxy_definition || planar_passthrough)
      end
    rescue StandardError
      false
    end

    # 这里只排除协同建筑、景观和空间最外层根组件。家具实例自身也带有
    # LinkHub 管理属性，不能再用 soft_library_managed_root_entity? 判断，否则会把
    # 刚从模型库放置的空间外家具误判成协同根模型并排除。
    def collaboration_root_entity?(entity, model = Sketchup.active_model, state = nil)
      return false unless entity && entity.valid?
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s rescue ''
      return true if kind == 'space_model'
      state = load_state(model) unless state.is_a?(Hash)
      return true if %w[architecture landscape].any? do |discipline|
        candidate = managed_model_instance_for(discipline, model)
        candidate && candidate.valid? && candidate == entity
      end
      Array(state['space_models']).any? do |space|
        candidate = space_model_entity(space['id'], model)
        candidate && candidate.valid? && candidate == entity
      end
    rescue StandardError
      false
    end

    # 顶部代/真切换使用统一“选择作用域”解析，而不是只认直接家具实例。
    # 作用域按优先级分为：
    # 1) 直接选中的 LinkHub 家具；
    # 2) 选中的普通 Group / Component 容器内的 LinkHub 家具；
    # 3) 没有家具选择作用域时，才由上层决定是否退回空间级切换。
    # 这样“把几件软装成组后选中该组”不会再误落到整个空间。
    def soft_representation_managed_instance?(entity, model = Sketchup.active_model, state = nil)
      return false unless entity && entity.valid?
      is_component = defined?(Sketchup::ComponentInstance) && entity.is_a?(Sketchup::ComponentInstance)
      return false unless is_component
      return false if collaboration_root_entity?(entity, model, state)
      info = soft_instance_metadata(entity)
      !info['model_id'].to_s.empty? || !info['source_path'].to_s.empty? || soft_legacy_proxy_entity?(entity)
    rescue StandardError
      false
    end

    def soft_representation_container_entity?(entity, model = Sketchup.active_model, state = nil)
      return false unless entity && entity.valid?
      is_component = defined?(Sketchup::ComponentInstance) && entity.is_a?(Sketchup::ComponentInstance)
      is_group = defined?(Sketchup::Group) && entity.is_a?(Sketchup::Group)
      return false unless is_component || is_group
      return false if collaboration_root_entity?(entity, model, state)
      !soft_representation_managed_instance?(entity, model, state)
    rescue StandardError
      false
    end

    def collect_soft_representation_targets_in_definition(definition, model = Sketchup.active_model, state = nil, results = [], trail = {})
      return results unless definition && definition.valid?
      oid = definition.object_id
      return results if trail[oid]
      next_trail = trail.merge(oid => true)
      definition.entities.each do |entity|
        next unless entity && entity.valid?
        if soft_representation_managed_instance?(entity, model, state)
          results << entity
          next
        end
        next unless soft_representation_container_entity?(entity, model, state)
        child_definition = entity.respond_to?(:definition) ? entity.definition : nil
        collect_soft_representation_targets_in_definition(child_definition, model, state, results, next_trail)
      end
      results.uniq
    rescue StandardError
      results.uniq
    end

    def soft_representation_targets_for_root(root, model = Sketchup.active_model, state = nil)
      return [] unless root && root.valid?
      return [root] if soft_representation_managed_instance?(root, model, state)
      return [] unless soft_representation_container_entity?(root, model, state)
      definition = root.respond_to?(:definition) ? root.definition : nil
      collect_soft_representation_targets_in_definition(definition, model, state)
    rescue StandardError
      []
    end

    def soft_representation_occurrence_count_for_root(root, model = Sketchup.active_model, state = nil, trail = {})
      return 0 unless root && root.valid?
      return 1 if soft_representation_managed_instance?(root, model, state)
      return 0 unless soft_representation_container_entity?(root, model, state)
      definition = root.respond_to?(:definition) ? root.definition : nil
      return 0 unless definition && definition.valid?
      oid = definition.object_id
      return 0 if trail[oid]
      next_trail = trail.merge(oid => true)
      definition.entities.sum do |child|
        if soft_representation_managed_instance?(child, model, state)
          1
        elsif soft_representation_container_entity?(child, model, state)
          soft_representation_occurrence_count_for_root(child, model, state, next_trail)
        else
          0
        end
      end
    rescue StandardError
      0
    end

    def soft_representation_selection_signature(selection, model = Sketchup.active_model)
      ids = Array(selection).select { |entity| entity && entity.valid? }.map do |entity|
        definition_id = entity.respond_to?(:definition) && entity.definition ? entity.definition.object_id : 0
        "#{entity.object_id}:#{definition_id}"
      end
      [model.object_id, soft_instance_registry_revision(model), ids.sort.join('|')].join('/')
    rescue StandardError
      ''
    end

    def resolve_soft_representation_selection_scope(model = Sketchup.active_model, state = nil, allow_recent: false)
      return { kind: :none, roots: [], targets: [], explicit: false, container_count: 0, occurrence_count: 0, label: '' } unless model
      state = load_state(model) unless state.is_a?(Hash)
      selection = Array(model.selection.to_a)

      unless selection.empty?
        signature = soft_representation_selection_signature(selection, model)
        @soft_representation_scope_cache ||= {}
        cached = @soft_representation_scope_cache[model.object_id]
        if cached.is_a?(Hash) && cached[:signature].to_s == signature &&
           Array(cached[:roots]).all? { |entity| entity && entity.valid? } &&
           Array(cached[:targets]).all? { |entity| entity && entity.valid? }
          return cached[:scope]
        end

        roots = selection.select do |entity|
          soft_representation_managed_instance?(entity, model, state) ||
            soft_representation_container_entity?(entity, model, state)
        end.uniq
        direct_roots = roots.select { |entity| soft_representation_managed_instance?(entity, model, state) }
        container_roots = roots.reject { |entity| direct_roots.include?(entity) }
        targets = roots.flat_map { |root| soft_representation_targets_for_root(root, model, state) }.uniq
        occurrence_count = roots.sum { |root| soft_representation_occurrence_count_for_root(root, model, state) }
        kind = if targets.empty?
                 container_roots.empty? ? :none : :empty_container
               elsif container_roots.empty?
                 :instances
               elsif direct_roots.empty?
                 :container
               else
                 :mixed
               end
        label = case kind
                when :container then container_roots.length == 1 ? '选中组/组件内' : "选中 #{container_roots.length} 个容器内"
                when :mixed then '当前选择范围内'
                when :instances then '已选中'
                else ''
                end
        scope = {
          kind: kind,
          roots: roots,
          targets: targets,
          explicit: !roots.empty?,
          container_count: container_roots.length,
          occurrence_count: occurrence_count,
          label: label
        }
        @soft_representation_scope_cache[model.object_id] = {
          signature: signature,
          roots: roots,
          targets: targets,
          scope: scope
        }
        if targets.any?
          @soft_representation_recent_scope = {
            model_id: model.object_id,
            captured_at: monotonic_time,
            roots: roots,
            kind: kind,
            label: label
          }
        end
        return scope
      end

      # 点击 Ruby Overlay 时部分 SketchUp 版本会先清空 Selection。缓存的不再只是
      # “直接家具”，而是整个选择根作用域，因此选中 Group 后点击代/真也不会掉回空间级。
      if allow_recent
        recent = @soft_representation_recent_scope
        if recent.is_a?(Hash) && recent[:model_id] == model.object_id &&
           (monotonic_time - recent[:captured_at].to_f) <= 1.8
          roots = Array(recent[:roots]).select { |entity| entity && entity.valid? }
          unless roots.empty?
            targets = roots.flat_map { |root| soft_representation_targets_for_root(root, model, state) }.uniq
            occurrence_count = roots.sum { |root| soft_representation_occurrence_count_for_root(root, model, state) }
            unless targets.empty?
              return {
                kind: recent[:kind] || :instances,
                roots: roots,
                targets: targets,
                explicit: true,
                container_count: roots.count { |root| soft_representation_container_entity?(root, model, state) },
                occurrence_count: occurrence_count,
                label: recent[:label].to_s
              }
            end
          end
        end
      end
      { kind: :none, roots: [], targets: [], explicit: false, container_count: 0, occurrence_count: 0, label: '' }
    rescue StandardError => e
      log_exception('解析家具代真选择作用域失败', e)
      { kind: :none, roots: [], targets: [], explicit: false, container_count: 0, occurrence_count: 0, label: '' }
    end

    # 为“容器作用域”真正执行切换时建立 occurrence 隔离。
    # 若选中的普通组件/组或其内部父容器 Definition 被其它 occurrence 共用，直接修改
    # 其内部家具实例会影响容器外的同定义实例。这里仅沿“确实包含受管家具”的分支
    # make_unique，并在同一个 Undo 事务内完成；直接选中的家具实例本身不会 unique。
    def materialize_soft_representation_container_targets!(root, model = Sketchup.active_model, state = nil, trail = {})
      return [] unless root && root.valid?
      return [root] if soft_representation_managed_instance?(root, model, state)
      return [] unless soft_representation_container_entity?(root, model, state)

      definition = root.respond_to?(:definition) ? root.definition : nil
      return [] unless definition && definition.valid?
      oid = definition.object_id
      return [] if trail[oid]

      probe = collect_soft_representation_targets_in_definition(definition, model, state)
      return [] if probe.empty?

      shared_count = if definition.respond_to?(:instances)
                       Array(definition.instances).count { |instance| instance && instance.valid? }
                     else
                       1
                     end
      if shared_count > 1
        unless root.respond_to?(:make_unique)
          raise '选中的家具容器被多个实例共享，当前 SketchUp 无法安全隔离该容器。'
        end
        root.make_unique
        definition = root.definition if root.respond_to?(:definition)
        raise '家具容器实例隔离失败。' unless definition && definition.valid?
      end

      next_trail = trail.merge(definition.object_id => true)
      results = []
      definition.entities.each do |child|
        next unless child && child.valid?
        if soft_representation_managed_instance?(child, model, state)
          results << child
        elsif soft_representation_container_entity?(child, model, state)
          child_probe = soft_representation_targets_for_root(child, model, state)
          next if child_probe.empty?
          results.concat(materialize_soft_representation_container_targets!(child, model, state, next_trail))
        end
      end
      results.uniq
    end

    def materialize_soft_representation_selection_targets!(scope, model = Sketchup.active_model, state = nil)
      roots = Array(scope && scope[:roots]).select { |entity| entity && entity.valid? }
      return Array(scope && scope[:targets]).select { |entity| entity && entity.valid? }.uniq if roots.empty?
      roots.flat_map do |root|
        if soft_representation_managed_instance?(root, model, state)
          [root]
        else
          materialize_soft_representation_container_targets!(root, model, state)
        end
      end.select { |entity| entity && entity.valid? }.uniq
    end

    # 兼容旧调用方：现在返回的是统一 Scope Resolver 的家具目标，既包含直接选择，
    # 也包含选中普通 Group / Component 内的受管家具。
    def selected_external_soft_instances(model = Sketchup.active_model, state = nil, allow_recent: false)
      resolve_soft_representation_selection_scope(model, state, allow_recent: allow_recent)[:targets]
    rescue StandardError
      []
    end

    def selected_soft_instances_display_mode(instances)
      modes = Array(instances).filter_map do |instance|
        next unless instance && instance.valid?
        soft_instance_representation(instance)
      end
      return '' if modes.empty?
      modes.all? { |value| value == 'proxy' } ? 'proxy' : 'full'
    rescue StandardError
      ''
    end

    def selected_soft_instances_mixed?(instances)
      modes = Array(instances).filter_map do |instance|
        next unless instance && instance.valid?
        soft_instance_representation(instance)
      end.uniq
      modes.length > 1
    rescue StandardError
      false
    end

    def set_selected_external_soft_display_mode(mode, instances, model = Sketchup.active_model, silent: false, selection_scope: nil)
      desired = mode.to_s == 'full' ? 'full' : 'proxy'
      targets = Array(instances).select { |instance| instance && instance.valid? }.uniq
      raise '请先选择一个由 LinkHub 管理的家具。' if targets.empty?
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再切换家具。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再切换家具。' if @updating || @single_space_update_job || @space_batch_update_job
      raise '模型库批量任务正在执行，请等待完成后再切换家具。' if @soft_model_batch_job
      # v0.13.6.177：家具入库“等待退出”的队列不再锁住整个空间的代/真切换。
      # 已提交对象若后来被切成代理，真正写库时会自动临时恢复真模型；其它未提交家具
      # 更不应该被一条入库队列连带锁住。
      guard_soft_individual_edit_representation_switch!(model, desired: desired, targets: targets)

      # 容器选择需要先物化到真实受管家具，再判断哪些实例正等待代理刷新。
      if selection_scope.is_a?(Hash) && Array(selection_scope[:roots]).any?
        targets = materialize_soft_representation_selection_targets!(selection_scope, model, load_state(model))
        raise '当前选择范围内没有可切换的 LinkHub 家具。' if targets.empty?
      end

      ingest_targets = request_soft_ingest_commit_from_button!(targets, desired, model)
      targets = targets.reject { |entity| ingest_targets.include?(entity) }
      return true if targets.empty? && ingest_targets.any?

      pending_records = soft_pending_proxy_records_for_targets(targets, model)
      pending_targets = pending_records.filter_map do |record|
        entity = record[:entity]
        entity if entity && entity.valid?
      end.uniq
      queued_proxy_count = 0

      if desired == 'full'
        # 用户手动点真模型：立即显示真模型，并阻止正在跑的代理任务完成后把这些实例
        # 强制弹回代理。代理文件本身仍会继续更新，发布时仍可按发布规则使用新代理。
        unless pending_targets.empty?
          set_soft_pending_proxy_display_intent!(pending_targets, 'full', model)
          queued_proxy_count = request_immediate_soft_proxy_refresh_for_records!(pending_records, model, desired: 'full')
          raise '所选家具提交未全部启动；真模型已保留，请查看任务中心。' if queued_proxy_count < pending_records.map { |row| row[:model_id].to_s }.uniq.length
        end
      elsif !pending_targets.empty?
        # 用户手动点代理：这批 pending 不再等待退出空间/发布，立即提升到代理队列。
        # 其它普通家具照常马上切代理；pending 家具在最新六面代理生成完成后自动同步。
        set_soft_pending_proxy_display_intent!(pending_targets, 'proxy', model)
        queued_proxy_count = request_immediate_soft_proxy_refresh_for_records!(pending_records, model)
        raise '所选家具代理提交未全部启动；当前模型已保留，请查看任务中心。' if queued_proxy_count < pending_records.map { |row| row[:model_id].to_s }.uniq.length
        pending_ids = pending_targets.each_with_object({}) { |entity, memo| memo[entity.object_id] = true }
        targets = targets.reject { |entity| pending_ids[entity.object_id] }
      end

      # 全部目标都只是“待刷新并已立即提升”的情况，不再拿旧代理强行覆盖。
      if targets.empty?
        unless silent
          show_status("已请求更新 #{pending_targets.length} 个待刷新家具；验收和关联完成后显示最新代理，不需要退出空间或等待发布。", 'info')
          show_workspace_floating_notice("代理立即更新 · #{pending_targets.length} 件", 'info', duration: 3.5, model: model)
        end
        schedule_coalesced_refresh_dialog(0.12)
        return true
      end

      # 已经全部处于目标状态时直接返回。容器作用域尤其不能为了“重复点击当前状态”
      # 去执行 make_unique，否则会制造没有视觉变化的 Definition 技术债。
      if targets.all? { |instance| soft_instance_representation_ready?(instance, desired) }
        overlay = workspace_toolbar_overlay(model)
        overlay.set_representation_mode_local!(desired) if overlay && overlay.respond_to?(:set_representation_mode_local!) && queued_proxy_count.zero?
        schedule_coalesced_refresh_dialog(0.08)
        return true
      end

      # 取消上一轮代理切换遗留的延迟 Definition 删除。删除高模并不会可靠地把
      # SketchUp 原生/Undo 内存还给系统，反而会让下一轮切真重新 load 同一批 SKP。
      cancel_soft_full_definition_cleanup!(model)
      operation_started = false
      changed = 0
      with_soft_representation_switch(model) do
        model.start_operation(desired == 'full' ? '所选家具切换为真模型' : '所选家具切换为代理', true)
        operation_started = true
        changed = if desired == 'full'
                    apply_space_soft_full_models!(nil, model, instances: targets).to_i
                  else
                    # 缺失/过期代理不再让整批选择回滚：能切的先切，剩余实例在提交后
                    # 立即进入高优先级代理生成队列。
                    apply_space_soft_proxies!(nil, model, instances: targets, strict: false).length
                  end
        model.commit_operation
        operation_started = false
      end
      failed = targets.select do |instance|
        !soft_instance_representation_ready?(instance, desired)
      end
      missing_proxy_refresh = { started: 0, rows: [], error: '' }
      local_save_failed = failed.select { |instance| soft_individual_edit_save_failed?(instance) }
      refreshable_failed = failed.reject { |instance| local_save_failed.include?(instance) }
      if desired == 'proxy' && refreshable_failed.any?
        scope_id = begin
          item = current_soft_designer_fab_space(model)
          item.is_a?(Hash) ? item['id'].to_s : ''
        rescue StandardError
          ''
        end
        missing_proxy_refresh = request_immediate_soft_proxy_refresh_for_instances!(
          refreshable_failed, model, scope_space_id: scope_id
        )
      end
      cleanup_scheduled = false
      model.active_view.invalidate if model.respond_to?(:active_view) && model.active_view
      overlay = workspace_toolbar_overlay(model)
      overlay.set_representation_mode_local!(desired) if overlay && overlay.respond_to?(:set_representation_mode_local!) && failed.empty? && queued_proxy_count.zero?
      schedule_coalesced_refresh_dialog(0.12)
      unless silent
        if failed.empty?
          scope_label = selection_scope.is_a?(Hash) ? selection_scope[:label].to_s : ''
          subject = scope_label.empty? ? '选中的' : scope_label
          if desired == 'proxy' && pending_targets.any?
            show_status("已将#{subject}其它 #{targets.length} 个家具切换为代理；另有 #{pending_targets.length} 个修改后家具已立即开始更新六面代理，完成后自动切换。", 'info')
          else
            message = "已将#{subject} #{targets.length} 个家具切换为#{desired == 'full' ? '真模型' : '代理'}；其它家具保持不变。"
            message += ' 真模型已保留为本次 SketchUp 会话缓存，后续再次切真将直接复用，不再重复载入。' if desired == 'proxy'
            show_status(message, 'success')
          end
        elsif desired == 'full'
          success_count = targets.length - failed.length
          show_status("真模型部分切换完成：成功 #{success_count} 个，#{failed.length} 个因源文件/身份问题保持原代理。", 'warning')
          show_soft_full_switch_failure_report(failed, model, title: '所选家具：真模型部分切换完成')
        else
          names = soft_proxy_switch_instance_summary(failed)
          save_failed_names = soft_proxy_switch_instance_summary(local_save_failed) unless local_save_failed.empty?
          if !local_save_failed.empty? && refreshable_failed.empty?
            show_status("其它家具已正常切换为代理；#{save_failed_names} 的修改尚未成功写回模型库，因此继续保留当前真模型。重新选择它执行“家具入库”修复成功后即可切代理；不会阻塞其它家具和发布。", 'warning')
            show_workspace_floating_notice("保持真模型 · #{save_failed_names} · 请重新入库", 'warning', duration: 5.5, model: model)
          elsif missing_proxy_refresh[:started].to_i.positive?
            extra = local_save_failed.empty? ? '' : "；#{save_failed_names} 因修改未写库继续保持真模型"
            show_status("其它家具已正常切换为代理；#{soft_proxy_switch_instance_summary(refreshable_failed)} 暂保持真模型，正在立即生成最新代理，完成后自动切换#{extra}。", 'warning')
            show_workspace_floating_notice("代理补齐中 · #{names}", 'info', duration: 4.5, model: model)
          else
            detail = missing_proxy_refresh[:error].to_s
            detail = '代理生成任务未能启动' if detail.empty?
            if !local_save_failed.empty?
              detail = "#{save_failed_names} 修改未写库，请重新入库；#{detail}"
            end
            show_status("以下家具暂时无法切换为代理：#{names}。#{detail}；其它已成功切换的家具不会被撤销。", 'error')
          end
        end
      end
      log("所选家具代真切换 #{desired}：即时目标 #{targets.length}，待刷新提升 #{pending_targets.length}，替换 #{changed}，失败/保持原状 #{failed.length}#{failed.any? ? " / #{soft_proxy_switch_instance_summary(failed)}" : ''}")
      desired == 'full' ? true : (refreshable_failed.empty? || missing_proxy_refresh[:started].to_i.positive?)
    rescue StandardError
      model.abort_operation rescue nil if operation_started
      raise
    end

    def soft_representation_pressure_profile(state, model = Sketchup.active_model, scope_space_id: '')
      scope_id = scope_space_id.to_s
      instance_count = 0
      model_sizes = {}
      unknown_size = 8 * 1024 * 1024
      Array(state['space_models']).each do |item|
        next if !scope_id.empty? && item['id'].to_s != scope_id
        entity = space_model_entity(item['id'], model)
        next unless entity && entity.valid?
        soft_instances_for_space(entity, model).each do |instance|
          next unless instance && instance.valid?
          instance_count += 1
          info = soft_instance_metadata(instance)
          model_id = info['model_id'].to_s.strip
          path = info['source_path'].to_s
          identity = if soft_stable_model_id?(model_id)
                       "id:#{model_id}"
                     elsif !path.empty?
                       "path:#{normalize_soft_library_key(path)}"
                     else
                       "definition:#{instance.definition.object_id}"
                     end
          next if model_sizes.key?(identity)

          signature = instance.definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s rescue ''
          if signature.empty? && !path.empty? && @soft_library_file_signature_cache.is_a?(Hash)
            cached = @soft_library_file_signature_cache[normalize_soft_library_key(path)]
            signature = cached[:signature].to_s if cached.is_a?(Hash)
          end
          size = signature.to_s.split('|', 3)[1].to_i
          model_sizes[identity] = size.positive? ? size : unknown_size
        end
      end
      {
        instances: instance_count,
        unique_models: model_sizes.length,
        source_bytes: model_sizes.values.sum,
        space_scope: scope_id
      }
    rescue StandardError => e
      log_exception('估算代真切换压力失败', e)
      { instances: 0, unique_models: 0, source_bytes: 0, space_scope: scope_id.to_s }
    end

    def soft_global_full_pressure_high?(profile)
      profile[:instances].to_i > SOFT_GLOBAL_FULL_MAX_INSTANCES ||
        profile[:unique_models].to_i > SOFT_GLOBAL_FULL_MAX_UNIQUE_MODELS ||
        profile[:source_bytes].to_i > SOFT_GLOBAL_FULL_MAX_SOURCE_BYTES
    rescue StandardError
      false
    end

    def soft_pressure_summary(profile)
      mb = (profile[:source_bytes].to_f / 1024.0 / 1024.0).round(1)
      "#{profile[:instances].to_i} 个家具实例 / #{profile[:unique_models].to_i} 个模型 / 源文件约 #{mb} MB"
    rescue StandardError
      '规模未知'
    end

    def collect_soft_definition_tree(definition, results = [], trail = {})
      return results unless definition && definition.valid?
      oid = definition.object_id
      return results if trail[oid]
      trail[oid] = true
      results << definition unless results.include?(definition)
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        collect_soft_definition_tree(entity.definition, results, trail)
      end
      results
    rescue StandardError
      results
    ensure
      trail.delete(oid) if defined?(oid) && oid
    end

    def remember_soft_full_definition_tree!(definition, model = Sketchup.active_model)
      return false unless definition && definition.valid? && model
      @soft_full_definition_tree_caches ||= {}
      model_cache = (@soft_full_definition_tree_caches[model.object_id] ||= {})
      model_cache[definition.object_id] = collect_soft_definition_tree(definition)
      true
    rescue StandardError
      false
    end

    # 只清理插件为真模型预览载入、且已经没有任何实例的定义树。不会调用全局
    # definitions.purge_unused，避免误删用户准备稍后放置的普通组件定义。
    def reconcile_soft_full_definition_cache!(model = Sketchup.active_model)
      @soft_full_cleanup_reconciled_models ||= {}
      return true if @soft_full_cleanup_reconciled_models[model.object_id]
      @soft_full_definition_tree_caches ||= {}
      cache = (@soft_full_definition_tree_caches[model.object_id] ||= {})
      model.definitions.each do |definition|
        next unless definition && definition.valid?
        next unless definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s == 'full'
        cache[definition.object_id] ||= collect_soft_definition_tree(definition)
      rescue StandardError
        next
      end
      @soft_full_cleanup_reconciled_models[model.object_id] = true
      true
    rescue StandardError
      false
    end

    def purge_unused_soft_full_definition_trees!(model = Sketchup.active_model, max_definitions: SOFT_FULL_DEFINITION_CLEANUP_BATCH, reconcile: true, return_details: false)
      reconcile_soft_full_definition_cache!(model) if reconcile
      @soft_full_definition_tree_caches ||= {}
      cache = (@soft_full_definition_tree_caches[model.object_id] ||= {})
      limit = [max_definitions.to_i, 1].max
      removed = 0
      4.times do
        candidates = cache.values.flat_map { |tree| Array(tree) }.uniq.select do |definition|
          definition && definition.valid? && definition.respond_to?(:instances) && definition.instances.empty?
        rescue StandardError
          false
        end
        break if candidates.empty? || removed >= limit
        candidates.each do |definition|
          break if removed >= limit
          next if soft_session_resident_full_definition?(definition, model)
          removed += 1 if remove_unused_definition!(definition, model)
        rescue StandardError
          next
        end
      end
      cache.delete_if { |_key, tree| Array(tree).none? { |definition| definition && definition.valid? } }
      pending = cache.values.any? do |tree|
        Array(tree).any? do |definition|
          definition && definition.valid? && definition.respond_to?(:instances) && definition.instances.empty?
        rescue StandardError
          false
        end
      end
      details = { removed: removed, pending: pending, cached_trees: cache.length }
      return_details ? details : removed
    rescue StandardError => e
      log_exception('卸载真模型预览定义失败', e)
      return_details ? { removed: 0, pending: false, cached_trees: 0 } : 0
    end

    def cancel_soft_full_definition_cleanup!(model = Sketchup.active_model)
      return false unless model
      @soft_full_cleanup_tokens ||= {}
      @soft_full_cleanup_tokens.delete(model.object_id)
      true
    rescue StandardError
      false
    end


    # -------------------------
    # 软装真模型会话驻留 / 生命周期回收 v0.13.6.27
    # -------------------------

    def soft_resident_full_records(model = Sketchup.active_model)
      @soft_resident_full_records ||= {}
      return {} unless model
      @soft_resident_full_records[model.object_id] ||= {}
    rescue StandardError
      {}
    end

    def soft_resident_space_id(entity = nil, model = Sketchup.active_model)
      id = ''
      if entity && entity.valid? && entity.respond_to?(:get_attribute)
        id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
      end
      id = soft_measurement_current_space_id(model).to_s if id.empty?
      id
    rescue StandardError
      ''
    end

    def touch_soft_resident_full_definition!(definition, model = Sketchup.active_model, space_id: '', library_item: nil)
      return false unless SOFT_SESSION_RESIDENT_FULL_DEFINITIONS
      return false unless definition && definition.valid? && model
      return false unless definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s == 'full'
      now = monotonic_time
      records = soft_resident_full_records(model)
      record = (records[definition.object_id] ||= {
        definition: definition,
        model_id: '',
        source_path: '',
        loaded_at: now,
        last_used_at: now,
        spaces: {}
      })
      record[:definition] = definition
      model_id = if library_item.is_a?(Hash)
                   library_item['id'].to_s
                 else
                   definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s rescue ''
                 end
      source_path = if library_item.is_a?(Hash)
                      library_item['path'].to_s
                    else
                      definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s rescue ''
                    end
      record[:model_id] = model_id unless model_id.empty?
      record[:source_path] = source_path unless source_path.empty?
      record[:last_used_at] = now
      sid = space_id.to_s
      unless sid.empty?
        record[:spaces] ||= {}
        meta = (record[:spaces][sid] ||= {})
        meta[:last_used_at] = now
        # 重新进入/重新切真表示这个空间又变热，撤销之前发布产生的回收资格。
        meta[:releasable] = false
        meta[:release_after] = 0.0
        meta[:release_reason] = ''
      end
      schedule_soft_resident_cache_cleanup(model, delay: 0.8, reason: 'pressure', force_pressure: true) if soft_resident_cache_pressure?(model)
      true
    rescue StandardError => e
      log_exception('记录软装真模型驻留缓存失败', e)
      false
    end

    def soft_resident_cache_pressure?(model = Sketchup.active_model)
      records = soft_resident_full_records(model)
      valid = records.values.select do |record|
        definition = record.is_a?(Hash) ? record[:definition] : nil
        definition && definition.valid?
      rescue StandardError
        false
      end
      spaces = valid.flat_map { |record| (record[:spaces] || {}).keys }.reject(&:empty?).uniq
      valid.length > SOFT_RESIDENT_CACHE_MAX_DEFINITIONS || spaces.length > SOFT_RESIDENT_CACHE_MAX_SPACES
    rescue StandardError
      false
    end

    def mark_soft_resident_space_releasable!(space_id, model = Sketchup.active_model, reason: 'publish', grace: SOFT_RESIDENT_CACHE_PUBLISH_GRACE_SECONDS)
      sid = space_id.to_s
      return false if sid.empty? || !model
      now = monotonic_time
      matched = 0
      soft_resident_full_records(model).each_value do |record|
        next unless record.is_a?(Hash)
        spaces = record[:spaces]
        next unless spaces.is_a?(Hash) && spaces.key?(sid)
        meta = (spaces[sid] ||= {})
        meta[:releasable] = true
        meta[:release_after] = now + [grace.to_f, 0.0].max
        meta[:release_reason] = reason.to_s
        matched += 1
      end
      if matched.positive?
        schedule_soft_resident_cache_cleanup(
          model,
          delay: [grace.to_f + 0.15, SOFT_RESIDENT_CACHE_STEP_DELAY].max,
          reason: reason.to_s,
          force_pressure: false
        )
        log("软装真模型缓存已进入可回收状态：空间 #{sid} / #{matched} 个高模 / 原因=#{reason}")
      end
      matched.positive?
    rescue StandardError => e
      log_exception('标记软装真模型缓存可回收失败', e)
      false
    end

    def soft_resident_record_release_ready?(record, now = monotonic_time)
      return false unless record.is_a?(Hash)
      spaces = record[:spaces]
      return false unless spaces.is_a?(Hash) && !spaces.empty?
      spaces.values.all? do |meta|
        meta.is_a?(Hash) &&
          meta[:releasable] == true &&
          meta[:release_after].to_f <= now.to_f
      end
    rescue StandardError
      false
    end

    def soft_resident_cleanup_candidates(model = Sketchup.active_model, force_pressure: false)
      return [] unless model
      records = soft_resident_full_records(model)
      now = monotonic_time
      active_space_id = soft_measurement_current_space_id(model).to_s
      pressure = force_pressure || soft_resident_cache_pressure?(model)
      rows = []
      records.delete_if do |_key, record|
        definition = record.is_a?(Hash) ? record[:definition] : nil
        invalid = !definition || !definition.valid?
        invalid
      rescue StandardError
        true
      end
      records.each_value do |record|
        definition = record[:definition]
        next unless definition && definition.valid?
        next unless definition.respond_to?(:instances) && definition.instances.empty?
        spaces = record[:spaces].is_a?(Hash) ? record[:spaces] : {}
        # 当前正在编辑/查看的空间永远不被压力淘汰。发布后 editing_id 已清空，
        # 但仍有 grace + idle 窗口，用户若马上继续编辑会 touch 并重新变热。
        next if !active_space_id.empty? && spaces.key?(active_space_id)
        normal_ready = soft_resident_record_release_ready?(record, now)
        next unless normal_ready || pressure
        rows << record
      rescue StandardError
        next
      end
      rows.sort_by do |record|
        normal_rank = soft_resident_record_release_ready?(record, now) ? 0 : 1
        [normal_rank, record[:last_used_at].to_f]
      end
    rescue StandardError
      []
    end

    def forget_soft_resident_definition_references!(definition, model = Sketchup.active_model)
      return false unless definition && model
      key = model.object_id
      [@soft_loaded_definition_caches, @soft_proxy_definition_caches, @soft_custom_proxy_definition_caches].compact.each do |root_cache|
        cache = root_cache[key] rescue nil
        cache.delete_if { |_cache_key, candidate| candidate == definition || !candidate || !candidate.valid? } if cache.respond_to?(:delete_if)
      end
      if @soft_full_definition_tree_caches && (cache = @soft_full_definition_tree_caches[key])
        cache.delete_if do |_cache_key, tree|
          Array(tree).any? { |candidate| candidate == definition } ||
            Array(tree).none? { |candidate| candidate && candidate.valid? }
        end
      end
      if @soft_representation_pair_caches && (cache = @soft_representation_pair_caches[key])
        cache.delete_if do |_cache_key, pair|
          proxy_definition = pair.is_a?(Hash) ? pair[:proxy_definition] : nil
          full_definition = pair.is_a?(Hash) ? pair[:full_definition] : nil
          full_definition == definition ||
            !proxy_definition || !full_definition ||
            !proxy_definition.valid? || !full_definition.valid?
        end
      end
      @soft_resident_full_records&.dig(key)&.delete(definition.object_id)
      true
    rescue StandardError
      false
    end

    def cancel_soft_resident_cache_cleanup!(model = Sketchup.active_model)
      return false unless model
      @soft_resident_cleanup_records ||= {}
      @soft_resident_cleanup_records.delete(model.object_id)
      true
    rescue StandardError
      false
    end


    def soft_direct_child_definitions(definition)
      return [] unless definition && definition.valid?
      seen = {}
      rows = []
      definition.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        child = entity.definition rescue nil
        next unless child && child.valid?
        oid = child.object_id
        next if seen[oid]
        seen[oid] = true
        rows << child
      rescue StandardError
        next
      end
      rows
    rescue StandardError
      []
    end

    def schedule_soft_resident_cache_cleanup(model = Sketchup.active_model, delay: SOFT_RESIDENT_CACHE_STEP_DELAY, reason: 'idle', force_pressure: false)
      return false unless model
      @soft_resident_cleanup_records ||= {}
      key = model.object_id
      token = SecureRandom.hex(8)
      @soft_resident_cleanup_records[key] = {
        token: token,
        reason: reason.to_s,
        force_pressure: !!force_pressure,
        removed_roots: 0,
        removed_children: 0,
        cycle_removed: 0,
        attempts: 0,
        pending_children: [],
        deferred_children: [],
        deferred_passes: 0,
        seen_child_ids: {},
        scheduled_at: monotonic_time
      }
      runtime_start_timer(delay.to_f, false, label: '软装真模型驻留缓存回收') do
        run_soft_resident_cache_cleanup_step(model, token)
      end
      true
    rescue StandardError => e
      log_exception('安排软装真模型驻留缓存回收失败', e)
      false
    end

    def run_soft_resident_cache_cleanup_step(model, token)
      @soft_resident_cleanup_records ||= {}
      key = model.object_id
      job = @soft_resident_cleanup_records[key]
      return false unless job && job[:token].to_s == token.to_s
      unless model == Sketchup.active_model || (model.respond_to?(:valid?) && model.valid?)
        @soft_resident_cleanup_records.delete(key)
        return false
      end
      unless background_work_idle?(model, min_idle: SOFT_RESIDENT_CACHE_IDLE_SECONDS)
        runtime_start_timer(SOFT_RESIDENT_CACHE_RETRY_DELAY, false, label: '软装真模型回收避让用户操作') do
          run_soft_resident_cache_cleanup_step(model, token)
        end
        return true
      end

      interaction_started = false
      begin
        begin_soft_heavy_interaction(:resident_full_cleanup)
        interaction_started = true
        started = monotonic_time
        before_removed = job[:removed_roots].to_i + job[:removed_children].to_i

        # 已经删除了顶层高模后，子 Definition 会逐步变成 unused。图遍历也必须增量：
        # 每一帧只看“当前一个 Definition”的直接子定义，绝不一次递归整棵树。
        pending = Array(job[:pending_children])
        deferred = Array(job[:deferred_children])
        child = pending.shift
        if child && child.valid?
          children = soft_direct_child_definitions(child)
          protected_proxy = soft_six_view_proxy_definition?(child) || standard_soft_publish_proxy_definition?(child)
          if !protected_proxy && child.respond_to?(:instances) && child.instances.empty? && remove_unused_definition!(child, model)
            job[:removed_children] = job[:removed_children].to_i + 1
            children.each do |nested|
              next unless nested && nested.valid?
              oid = nested.object_id
              next if job[:seen_child_ids][oid]
              job[:seen_child_ids][oid] = true
              pending << nested
            end
          else
            deferred << child
          end
        end
        job[:pending_children] = pending
        job[:deferred_children] = deferred

        if job[:pending_children].empty?
          force_pressure = job[:force_pressure] || soft_resident_cache_pressure?(model)
          candidate = soft_resident_cleanup_candidates(model, force_pressure: force_pressure).first
          if candidate
            definition = candidate[:definition]
            if definition && definition.valid? && definition.instances.empty?
              children = soft_direct_child_definitions(definition)
              if remove_unused_definition!(definition, model)
                forget_soft_resident_definition_references!(definition, model)
                job[:removed_roots] = job[:removed_roots].to_i + 1
                children.each do |child_definition|
                  next unless child_definition && child_definition.valid?
                  oid = child_definition.object_id
                  next if job[:seen_child_ids][oid]
                  job[:seen_child_ids][oid] = true
                  job[:pending_children] << child_definition
                end
              end
            end
          elsif !job[:deferred_children].empty? && job[:deferred_passes].to_i < 2
            # 某些共享子定义在父定义尚未删完时仍有实例。当前批次顶层都处理完后
            # 再重试最多两轮；仍被其它有效定义引用的就安全保留。
            job[:pending_children] = job[:deferred_children]
            job[:deferred_children] = []
            job[:deferred_passes] = job[:deferred_passes].to_i + 1
          end
        end

        elapsed = elapsed_ms(started)
        job[:attempts] = job[:attempts].to_i + 1
        total_removed = job[:removed_roots].to_i + job[:removed_children].to_i
        removed_this_step = [total_removed - before_removed.to_i, 0].max
        job[:cycle_removed] = job[:cycle_removed].to_i + removed_this_step
        more = !job[:pending_children].empty? ||
               (!job[:deferred_children].empty? && job[:deferred_passes].to_i < 2) ||
               !soft_resident_cleanup_candidates(model, force_pressure: (job[:force_pressure] || soft_resident_cache_pressure?(model))).empty?
        if more && job[:attempts].to_i < 120
          # 每清一小段就主动留出更长空闲窗口，避免发布成功后出现连续几十秒的“后台卡顿”。
          if job[:cycle_removed].to_i >= SOFT_RESIDENT_CACHE_MAX_REMOVALS_PER_CYCLE
            job[:cycle_removed] = 0
            next_delay = [SOFT_RESIDENT_CACHE_RETRY_DELAY * 2.0, 2.0].max
          else
            next_delay = elapsed >= SOFT_RESIDENT_CACHE_HEAVY_STEP_MS ? SOFT_RESIDENT_CACHE_RETRY_DELAY : SOFT_RESIDENT_CACHE_STEP_DELAY
          end
          runtime_start_timer(next_delay, false, label: '软装真模型驻留缓存继续回收') do
            run_soft_resident_cache_cleanup_step(model, token)
          end
        else
          @soft_resident_cleanup_records.delete(key)
          if total_removed.positive?
            prune_invalid_definition_caches_after_native_purge!(model)
            log("软装真模型驻留缓存回收完成：顶层 #{job[:removed_roots]} / 子定义 #{job[:removed_children]} / 原因=#{job[:reason]}")
          elsif more
            log("软装真模型驻留缓存回收达到安全尝试上限，剩余内容留待下次空闲/发布继续处理。")
          end
        end
        true
      rescue StandardError => e
        @soft_resident_cleanup_records&.delete(key)
        log_exception('执行软装真模型驻留缓存回收失败', e)
        false
      ensure
        end_soft_heavy_interaction(:resident_full_cleanup) if interaction_started
      end
    end

    def soft_session_resident_full_definition?(definition, model = Sketchup.active_model)
      return false unless SOFT_SESSION_RESIDENT_FULL_DEFINITIONS
      return false unless definition && definition.valid? && model
      return false unless definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s == 'full'
      records = @soft_resident_full_records && @soft_resident_full_records[model.object_id]
      return true if records.is_a?(Hash) && records.key?(definition.object_id)
      # 兼容从旧运行代接回、尚未经过 v0.13.6.27 touch 的缓存。
      root = @soft_loaded_definition_caches
      cache = root && root[model.object_id]
      return false unless cache.respond_to?(:each_value)
      cache.each_value.any? { |candidate| candidate && candidate.valid? && candidate == definition }
    rescue StandardError
      false
    end

    def schedule_soft_full_definition_cleanup(model = Sketchup.active_model, delay: SOFT_FULL_DEFINITION_CLEANUP_DELAY, attempt: 0, reconcile: true, max_definitions: SOFT_FULL_DEFINITION_CLEANUP_BATCH)
      return false unless model
      # 软装工作区从 v0.13.6.27 起禁止“为了清理而扫 model.definitions 全表”。
      # 已知临时树（入库 wrapper / 轴壳等）仍可按 @soft_full_definition_tree_caches 精准清理；
      # 建筑/景观保留旧 reconcile 行为，避免改变它们的参考模型生命周期。
      if reconcile && SOFT_SESSION_RESIDENT_FULL_DEFINITIONS
        begin
          host_key = host_discipline_for(load_state(model))
          reconcile = false if host_key == SOFT_SPACE_COLLECTION_KEY
        rescue StandardError
          nil
        end
      end
      @soft_full_cleanup_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6) if attempt.to_i.zero?
      token ||= @soft_full_cleanup_tokens[key]
      @soft_full_cleanup_tokens[key] = token
      runtime_start_timer(delay.to_f, false, label: '闲置真模型分批清理') do
        next unless @soft_full_cleanup_tokens[key] == token
        if soft_heavy_interaction? || @updating
          schedule_soft_full_definition_cleanup(model, delay: 0.8, attempt: attempt.to_i + 1, reconcile: reconcile, max_definitions: max_definitions) if attempt.to_i < 30
          next
        end
        details = purge_unused_soft_full_definition_trees!(model, max_definitions: max_definitions, reconcile: (reconcile && attempt.to_i.zero?), return_details: true)
        log("后台卸载闲置真模型：本批 #{details[:removed]}，剩余树 #{details[:cached_trees]}") if details[:removed].positive?
        if details[:pending] && attempt.to_i < 30
          schedule_soft_full_definition_cleanup(model, delay: 0.35, attempt: attempt.to_i + 1, reconcile: false, max_definitions: max_definitions)
        else
          @soft_full_cleanup_tokens.delete(key)
        end
      end
      true
    rescue StandardError => e
      log_exception('安排闲置真模型后台清理失败', e)
      false
    end

    # v0.13.6.170：六面代理截图/抠图/队列/原子写入从 God File 拆出。
    # Kernel.load 而不是 require_relative，保证 LinkHub 热重载每次都重新读取最新版实现。
    Kernel.load(File.expand_path('proxy_visual.rb', __dir__))
    Kernel.load(File.expand_path('proxy_queue.rb', __dir__))
    Kernel.load(File.expand_path('proxy_commit.rb', __dir__))

    # 自动家具代理的内部兜底仍使用真实模型局部外包盒。正式工作流优先读取模型库中的
    # 六面可视代理；只有六面代理缺失或生成失败时才落回这个白盒，不再对用户暴露为一种模式。
    def soft_auto_proxy_style(_model_name, _source_definition = nil)
      'box'
    end

    def soft_auto_proxy_style_label(_style)
      '六面代理缺失（严格模式不使用白盒）'
    end

    def soft_native_bounds_values(definition_or_bounds)
      bounds = definition_or_bounds.respond_to?(:bounds) ? definition_or_bounds.bounds : definition_or_bounds
      return nil unless bounds
      [
        bounds.min.x.to_f, bounds.min.y.to_f, bounds.min.z.to_f,
        bounds.max.x.to_f, bounds.max.y.to_f, bounds.max.z.to_f
      ]
    rescue StandardError
      nil
    end

    def soft_bounds_values_valid?(values)
      return false unless values.is_a?(Array) && values.length == 6
      numbers = values.map(&:to_f)
      return false unless numbers.all?(&:finite?)
      (numbers[3] - numbers[0]).abs > 1.0e-9 ||
        (numbers[4] - numbers[1]).abs > 1.0e-9 ||
        (numbers[5] - numbers[2]).abs > 1.0e-9
    rescue StandardError
      false
    end

    def soft_bounds_axis_dimensions_mm(values)
      return [0.0, 0.0, 0.0] unless soft_bounds_values_valid?(values)
      data = Array(values).map(&:to_f)
      [
        (data[3] - data[0]).abs * 25.4,
        (data[4] - data[1]).abs * 25.4,
        (data[5] - data[2]).abs * 25.4
      ]
    rescue StandardError
      [0.0, 0.0, 0.0]
    end

    # 恰有一轴近似为 0、另外两轴有效时，判定为“平面指代模型”。真正空模型
    # （两轴或三轴均为 0）仍保持无效，避免把空组件误当作可入库图片。
    def soft_bounds_planar_reference?(values, epsilon_mm = SOFT_PLANAR_REFERENCE_EPSILON_MM)
      dimensions = soft_bounds_axis_dimensions_mm(values)
      return false unless dimensions.all?(&:finite?)
      positive = dimensions.count { |value| value.to_f > epsilon_mm.to_f }
      flat = dimensions.count { |value| value.to_f <= epsilon_mm.to_f }
      positive == 2 && flat == 1
    rescue StandardError
      false
    end

    def soft_metadata_planar_reference?(metadata)
      data = metadata.is_a?(Hash) ? metadata : {}
      marked = data['planar_reference'] == true ||
               soft_visual_proxy_truthy?(data['planar_reference']) ||
               soft_visual_proxy_truthy?(data['proxy_passthrough'])
      return true if marked
      return true if soft_bounds_planar_reference?(data['bounds_values'])
      # v0.13.6.192：bounds_values 随每次源模型写回刷新（带 bounds_source_signature），是权威尺寸；
      # ingested_actual_axis_mm 只在首次入库写入，源模型更新（如平面迎宾册改成 50mm 厚的实体）后
      # 会过期。旧逻辑仍按过期轴判成“平面图片”，六面代理候选直接返回 nil，
      # 表现为“待刷新家具无法建立六面代理候选”且永远失败。有效且非平面的 bounds 优先。
      return false if soft_bounds_values_valid?(data['bounds_values'])
      if data['dimensions_cached'] == true
        dims = [data['length_mm'], data['width_mm'], data['height_mm']].map(&:to_f)
        return false if dims.all? { |value| value.finite? && value > SOFT_PLANAR_REFERENCE_EPSILON_MM }
      end
      axes = Array(data['ingested_actual_axis_mm']).map(&:to_f)
      if axes.length == 3 && axes.all?(&:finite?)
        positive = axes.count { |value| value > SOFT_PLANAR_REFERENCE_EPSILON_MM }
        flat = axes.count { |value| value <= SOFT_PLANAR_REFERENCE_EPSILON_MM }
        return true if positive == 2 && flat == 1
      end
      false
    rescue StandardError
      false
    end

    def soft_definition_planar_reference?(definition)
      return false unless definition && definition.valid?
      marked = definition.get_attribute(SOFT_MODEL_DICT, 'planar_reference', false)
      return true if marked == true || soft_visual_proxy_truthy?(marked)
      # v0.13.7.3：朝向相机的片状组件与平面图片一样直接作为代理，不生成六面代理。
      return true if soft_definition_face_camera?(definition)
      soft_bounds_planar_reference?(soft_definition_bounds_values(definition))
    rescue StandardError
      false
    end

    def soft_instance_planar_reference?(instance)
      return false unless instance && instance.valid? && instance.respond_to?(:definition)
      marked = instance.get_attribute(SOFT_MODEL_DICT, 'planar_reference', false)
      return true if marked == true || soft_visual_proxy_truthy?(marked)
      soft_definition_planar_reference?(instance.definition)
    rescue StandardError
      false
    end

    def mark_soft_planar_reference!(definition, planar = nil)
      return false unless definition && definition.valid?
      planar = soft_bounds_planar_reference?(soft_definition_bounds_values(definition)) if planar.nil?
      if planar
        soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'planar_reference', true)
        soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'proxy_passthrough', true)
      else
        definition.delete_attribute(SOFT_MODEL_DICT, 'planar_reference') rescue nil
        definition.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
      end
      !!planar
    rescue StandardError
      false
    end

    def soft_add_bounds_corners!(box, bounds, transform = nil)
      values = soft_native_bounds_values(bounds)
      return 0 unless values && values.length == 6
      x0, y0, z0, x1, y1, z1 = values
      points = [
        Geom::Point3d.new(x0, y0, z0), Geom::Point3d.new(x1, y0, z0),
        Geom::Point3d.new(x1, y1, z0), Geom::Point3d.new(x0, y1, z0),
        Geom::Point3d.new(x0, y0, z1), Geom::Point3d.new(x1, y0, z1),
        Geom::Point3d.new(x1, y1, z1), Geom::Point3d.new(x0, y1, z1)
      ]
      points.each { |point| box.add(transform ? point.transform(transform) : point) }
      points.length
    rescue StandardError
      0
    end

    # ComponentDefinition#bounds 会把标注、文字、辅助点、辅助线以及隐藏的
    # 遗留对象一起计入。模型库文件中只要有一个远处辅助对象，“底部中心”就会
    # 跑到几米甚至几公里之外。这里按真实可见建模几何重新计算外包盒：
    # 面、独立边和嵌套组/组件参与，标注/文字/辅助线/辅助点不参与。
    def soft_collect_visual_bounds!(definition, box, transform, trail, counter, limit)
      return 0 unless definition && definition.valid?
      oid = definition.object_id
      return 0 if trail[oid]
      trail[oid] = true
      added = 0
      definition.entities.each do |entity|
        next unless entity && entity.valid?
        next if entity.respond_to?(:hidden?) && entity.hidden?

        if entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
          child_transform = transform * entity.transformation
          if counter[0] >= limit
            added += soft_add_bounds_corners!(box, entity.bounds, transform)
          else
            child_added = soft_collect_visual_bounds!(entity.definition, box, child_transform, trail, counter, limit)
            if child_added.zero?
              added += soft_add_bounds_corners!(box, entity.bounds, transform)
            else
              added += child_added
            end
          end
          next
        end

        if entity.is_a?(Sketchup::Edge)
          # 每条边只访问一次端点。旧版遍历每个面的全部顶点，同一个顶点会被
          # 相邻面重复读取多次；高模首次放置时这里可能成为主要耗时。
          box.add(entity.start.position.transform(transform))
          box.add(entity.end.position.transform(transform))
          counter[0] += 2
          added += 2
          next
        end

        # 面的边已经完整表达其几何范围，无需再次遍历 Face#vertices。
        next if entity.is_a?(Sketchup::Face)

        if defined?(Sketchup::Image) && entity.is_a?(Sketchup::Image)
          added += soft_add_bounds_corners!(box, entity.bounds, transform)
        end
      end
      added
    rescue StandardError => e
      log_exception('计算软装有效几何外包盒失败', e)
      added || 0
    ensure
      trail.delete(oid) if defined?(oid) && oid
    end

    def soft_definition_bounds_cache_token(definition)
      guid = definition.respond_to?(:guid) ? definition.guid.to_s : ''
      count = definition.respond_to?(:entities) ? definition.entities.length.to_i : 0
      native_values = soft_native_bounds_values(definition)
      native_signature = soft_bounds_values_valid?(native_values) ? soft_bounds_signature_from_values(native_values) : ''
      source_signature = definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s rescue ''
      "#{guid}|#{count}|#{native_signature}|#{source_signature}"
    rescue StandardError
      definition.object_id.to_s
    end

    def clear_soft_definition_persisted_bounds!(definition)
      return false unless definition && definition.valid?
      %w[bounds_attribute_schema bounds_cache_token bounds_values_json].each do |key|
        definition.delete_attribute(SOFT_MODEL_DICT, key) rescue nil
      end
      true
    rescue StandardError
      false
    end

    def soft_definition_persisted_bounds_values(definition)
      return nil unless definition && definition.valid?
      schema = definition.get_attribute(SOFT_MODEL_DICT, 'bounds_attribute_schema', 0).to_i
      return nil unless schema == SOFT_DEFINITION_BOUNDS_ATTRIBUTE_SCHEMA
      stored_token = definition.get_attribute(SOFT_MODEL_DICT, 'bounds_cache_token', '').to_s
      return nil if stored_token.empty? || stored_token != soft_definition_bounds_cache_token(definition)
      raw = definition.get_attribute(SOFT_MODEL_DICT, 'bounds_values_json', '').to_s
      return nil if raw.empty?
      values = JSON.parse(raw)
      soft_bounds_values_valid?(values) ? Array(values).map(&:to_f) : nil
    rescue StandardError
      nil
    end

    # 只在模型库定义真正载入、代理生成或归一化完成时写入。普通后台扫描不会
    # 修改模型，因此打开旧项目不会因为预热缓存而突然变成“未保存”。
    def persist_soft_definition_bounds_values!(definition, values)
      return false unless definition && definition.valid? && soft_bounds_values_valid?(values)
      normalized = Array(values).map(&:to_f)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'bounds_attribute_schema', SOFT_DEFINITION_BOUNDS_ATTRIBUTE_SCHEMA)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'bounds_cache_token', soft_definition_bounds_cache_token(definition))
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'bounds_values_json', JSON.generate(normalized))
      seed_soft_definition_bounds_cache!(definition, normalized)
      true
    rescue StandardError => e
      log_exception('持久化家具外包盒缓存失败', e)
      false
    end

    def soft_clear_definition_bounds_cache!(definition = nil)
      @soft_definition_bounds_cache ||= {}
      if definition
        @soft_definition_bounds_cache.delete(definition.object_id)
        # v0.13.7.7：同时让 SketchUp 重算原生外包盒（含上层定义），否则读到的是改动前的旧值。
        soft_invalidate_definition_bounds!(definition) if definition.valid?
        invalidate_soft_representation_pair_cache!(nil, definition: definition) if respond_to?(:invalidate_soft_representation_pair_cache!)
      else
        @soft_definition_bounds_cache.clear
        invalidate_soft_representation_pair_cache! if respond_to?(:invalidate_soft_representation_pair_cache!)
      end
      true
    rescue StandardError
      false
    end

    # v0.13.6.167：在不改变“有效可视几何 bounds”语义的前提下优先走 C++ native bounds。
    # 这里只做轻量实体类型/hidden 审计，不读取任何顶点，也不做 Point3d#transform。
    # 若整棵定义树只有当前精确算法本来就会计入的可见 Edge/Face/Image/组件，
    # definition.bounds 与递归收集结果等价；遇到隐藏实体、标注、辅助线等特殊对象立即回退。
    # visited 按 Definition 去重，重复嵌套组件只检查一次。
    def soft_definition_native_bounds_fast_safe?(definition, visited = nil)
      return false unless definition && definition.valid?
      visited ||= {}
      oid = definition.object_id
      return true if visited[oid]
      visited[oid] = true
      definition.entities.each do |entity|
        next unless entity && entity.valid?
        return false if entity.respond_to?(:hidden?) && entity.hidden?
        if entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
          child = entity.definition rescue nil
          return false unless child && child.valid? && soft_definition_native_bounds_fast_safe?(child, visited)
          next
        end
        next if entity.is_a?(Sketchup::Edge) || entity.is_a?(Sketchup::Face)
        next if defined?(Sketchup::Image) && entity.is_a?(Sketchup::Image)
        return false
      end
      true
    rescue StandardError
      false
    end

    def soft_definition_visual_bounds_values(definition)
      return nil unless definition && definition.valid?
      @soft_definition_bounds_cache ||= {}
      token = soft_definition_bounds_cache_token(definition)
      cached = @soft_definition_bounds_cache[definition.object_id]
      if cached && cached[:token] == token
        return cached[:values] ? cached[:values].dup : nil
      end

      persisted = soft_definition_persisted_bounds_values(definition)
      if soft_bounds_values_valid?(persisted)
        @soft_definition_bounds_cache[definition.object_id] = {
          token: token,
          values: persisted.dup,
          definition: definition
        }
        return persisted
      end

      if soft_definition_native_bounds_fast_safe?(definition)
        native = soft_native_bounds_values(definition)
        if soft_bounds_values_valid?(native)
          @soft_definition_bounds_cache[definition.object_id] = {
            token: token,
            values: native.dup,
            definition: definition
          }
          return native
        end
      end

      box = Geom::BoundingBox.new
      counter = [0]
      added = soft_collect_visual_bounds!(definition, box, identity_transformation, {}, counter, 180_000)
      values = added.positive? ? soft_native_bounds_values(box) : nil
      values = nil unless soft_bounds_values_valid?(values)
      @soft_definition_bounds_cache[definition.object_id] = {
        token: token,
        values: values ? values.dup : nil,
        definition: definition
      }
      values
    rescue StandardError => e
      log_exception('读取软装有效几何外包盒失败', e)
      nil
    end

    # 软装放置、代理、替换和尺寸统一使用有效建模几何外包盒。若模型确实没有
    # 面/边（极少数纯图片组件），再回退 SketchUp 原生 definition.bounds。
    def soft_definition_bounds_values(definition)
      visual = soft_definition_visual_bounds_values(definition)
      return visual if soft_bounds_values_valid?(visual)
      soft_native_bounds_values(definition)
    rescue StandardError
      soft_native_bounds_values(definition)
    end

    def soft_definition_bounds_signature(definition)
      values = soft_definition_bounds_values(definition)
      return '' unless values
      values.map { |value| format('%.9f', value.to_f) }.join('|')
    rescue StandardError
      ''
    end

    def soft_definition_bounds_equivalent?(first, second, tolerance = 1.0e-6)
      a = soft_definition_bounds_values(first)
      b = soft_definition_bounds_values(second)
      return false unless a && b && a.length == b.length
      a.zip(b).all? { |left, right| (left.to_f - right.to_f).abs <= tolerance.to_f }
    rescue StandardError
      false
    end

    def add_soft_proxy_box!(entities, x0, y0, z0, x1, y1, z1)
      dx = x1.to_f - x0.to_f
      dy = y1.to_f - y0.to_f
      dz = z1.to_f - z0.to_f
      return 0 if dx.abs < 1.0e-9 || dy.abs < 1.0e-9 || dz.abs < 1.0e-9
      points = [
        Geom::Point3d.new(x0, y0, z0),
        Geom::Point3d.new(x1, y0, z0),
        Geom::Point3d.new(x1, y1, z0),
        Geom::Point3d.new(x0, y1, z0)
      ]
      face = entities.add_face(points)
      return 0 unless face && face.valid?
      face.reverse! if face.normal.z.to_f < 0
      face.pushpull(dz)
      6
    rescue StandardError => e
      log_exception('创建同尺寸家具代理方块失败', e)
      0
    end

    def soft_bounds_signature_from_values(values)
      return '' unless soft_bounds_values_valid?(values)
      Array(values).map { |value| format('%.9f', value.to_f) }.join('|')
    rescue StandardError
      ''
    end

    def build_soft_auto_proxy_geometry_from_bounds!(definition, values)
      raise '真实家具有效几何外包尺寸无效，无法生成代理方块。' unless soft_bounds_values_valid?(values)
      entities = definition.entities
      existing = entities.to_a
      entities.erase_entities(existing) unless existing.empty?
      normalized = Array(values).map(&:to_f)
      face_count = add_soft_proxy_box!(entities, *normalized)
      raise '真实家具有效几何外包尺寸无效，无法生成代理方块。' if face_count.zero?
      soft_clear_definition_bounds_cache!(definition)
      seed_soft_definition_bounds_cache!(definition, normalized)
      signature = soft_bounds_signature_from_values(normalized)
      definition.set_attribute(SOFT_MODEL_DICT, 'auto_proxy_face_count', face_count)
      definition.set_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', signature)
      definition.set_attribute(SOFT_MODEL_DICT, 'exact_bounds_proxy', true)
      persist_soft_definition_bounds_values!(definition, normalized)
      face_count
    end

    def build_soft_auto_proxy_geometry!(definition, source_definition)
      raise '缺少真实家具定义，无法生成同尺寸代理。' unless source_definition && source_definition.valid?
      values = soft_definition_bounds_values(source_definition)
      build_soft_auto_proxy_geometry_from_bounds!(definition, values)
    end

    def soft_bounds_axis_extents_from_values(values)
      return [0.0, 0.0, 0.0] unless soft_bounds_values_valid?(values)
      data = Array(values).map(&:to_f)
      [data[3] - data[0], data[4] - data[1], data[5] - data[2]]
    rescue StandardError
      [0.0, 0.0, 0.0]
    end

    def soft_bounds_bottom_center_from_values(values)
      return Geom::Point3d.new(0, 0, 0) unless soft_bounds_values_valid?(values)
      data = Array(values).map(&:to_f)
      Geom::Point3d.new((data[0] + data[3]) * 0.5, (data[1] + data[4]) * 0.5, data[2])
    rescue StandardError
      Geom::Point3d.new(0, 0, 0)
    end

    def soft_definition_bounds_equivalent_to_values?(definition, values, tolerance = 1.0e-6)
      actual = soft_definition_bounds_values(definition)
      return false unless soft_bounds_values_valid?(actual) && soft_bounds_values_valid?(values)
      actual.zip(Array(values)).all? { |left, right| (left.to_f - right.to_f).abs <= tolerance.to_f }
    rescue StandardError
      false
    end

    def soft_proxy_fit_transformation_to_bounds(proxy_definition, full_values)
      proxy_values = soft_definition_bounds_values(proxy_definition)
      raise '代理模型有效外包盒无效。' unless soft_bounds_values_valid?(proxy_values)
      raise '真模型有效外包盒无效。' unless soft_bounds_values_valid?(full_values)
      proxy_extents = soft_bounds_axis_extents_from_values(proxy_values)
      full_extents = soft_bounds_axis_extents_from_values(full_values)
      proxy_x = [proxy_extents[0].to_f.abs, 1.0e-9].max
      proxy_y = [proxy_extents[1].to_f.abs, 1.0e-9].max
      proxy_z = [proxy_extents[2].to_f.abs, 1.0e-9].max
      scale_x = full_extents[0].to_f / proxy_x
      scale_y = full_extents[1].to_f / proxy_y
      scale_z = full_extents[2].to_f / proxy_z
      source_anchor = soft_bounds_bottom_center_from_values(proxy_values)
      target_anchor = soft_bounds_bottom_center_from_values(full_values)
      x_axis = Geom::Vector3d.new(scale_x, 0.0, 0.0)
      y_axis = Geom::Vector3d.new(0.0, scale_y, 0.0)
      z_axis = Geom::Vector3d.new(0.0, 0.0, scale_z)
      origin = Geom::Point3d.new(
        target_anchor.x.to_f - x_axis.x.to_f * source_anchor.x.to_f - y_axis.x.to_f * source_anchor.y.to_f - z_axis.x.to_f * source_anchor.z.to_f,
        target_anchor.y.to_f - x_axis.y.to_f * source_anchor.x.to_f - y_axis.y.to_f * source_anchor.y.to_f - z_axis.y.to_f * source_anchor.z.to_f,
        target_anchor.z.to_f - x_axis.z.to_f * source_anchor.x.to_f - y_axis.z.to_f * source_anchor.y.to_f - z_axis.z.to_f * source_anchor.z.to_f
      )
      soft_exact_axes_transformation(origin, x_axis, y_axis, z_axis)
    end

    def soft_proxy_fit_transformation(proxy_definition, full_definition)
      soft_proxy_fit_transformation_to_bounds(proxy_definition, soft_definition_bounds_values(full_definition))
    end

    def exact_soft_proxy_for_full?(proxy_definition, full_definition)
      return false unless proxy_definition && proxy_definition.valid? && full_definition && full_definition.valid?
      marked = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'exact_bounds_proxy', false)
      signature = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s
      expected = signature.split('|').map { |value| Float(value) }
      full_values = soft_definition_bounds_values(full_definition)
      return false unless marked == true && soft_bounds_values_valid?(expected) && soft_bounds_values_valid?(full_values)

      # exact_bounds_proxy 是 LinkHub 在按真模型局部 bounds 构建/归一化代理以后写入的
      # 权威标记。SKP 保存再载入后，图片面或嵌套 Definition 的原生 bounds 可能出现
      # 极小浮点往返，不能因此降级到“按外包盒重算实例矩阵”。这里只用持久化的真模
      # bounds 签名做数值容差复核；通过后代/真切换必须逐位复用实例原 4×4 变换。
      expected.zip(Array(full_values)).all? { |left, right| (left.to_f - right.to_f).abs <= 1.0e-5 }
    rescue StandardError
      false
    end

    def soft_representation_pair_cache(model = Sketchup.active_model)
      @soft_representation_pair_caches ||= {}
      model ? (@soft_representation_pair_caches[model.object_id] ||= {}) : {}
    rescue StandardError
      {}
    end

    def soft_representation_pair_token(proxy_definition, full_definition)
      [
        soft_definition_bounds_cache_token(proxy_definition),
        soft_definition_bounds_cache_token(full_definition),
        proxy_definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s,
        full_definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s
      ].join('||')
    rescue StandardError
      ''
    end

    def invalidate_soft_representation_pair_cache!(model = nil, definition: nil)
      @soft_representation_pair_caches ||= {}
      caches = model ? [[model.object_id, @soft_representation_pair_caches[model.object_id]]] : @soft_representation_pair_caches.to_a
      caches.each do |model_key, cache|
        next unless cache.respond_to?(:delete_if)
        if definition
          oid = definition.object_id
          cache.delete_if do |pair_key, record|
            Array(pair_key).include?(oid) ||
              (record.is_a?(Hash) && [record[:proxy_definition], record[:full_definition]].compact.any? { |item| item.object_id == oid })
          end
        else
          cache.clear
        end
        @soft_representation_pair_caches.delete(model_key) if cache.empty?
      end
      true
    rescue StandardError
      false
    end

    # 同一款家具在一个项目中可能有几十个实例，并且用户会反复切换代/真。
    # 精确外包盒配对只在定义真正变化后重新核对，不再每次点击都递归验证。
    def soft_exact_representation_pair?(proxy_definition, full_definition, model = Sketchup.active_model)
      return false unless proxy_definition && proxy_definition.valid? && full_definition && full_definition.valid?
      return false unless soft_representation_identity_compatible?(proxy_definition, full_definition)
      cache = soft_representation_pair_cache(model)
      key = [proxy_definition.object_id, full_definition.object_id]
      token = soft_representation_pair_token(proxy_definition, full_definition)
      cached = cache[key]
      if cached && cached[:token].to_s == token && cached[:proxy_definition]&.valid? && cached[:full_definition]&.valid?
        cached[:touched_at] = monotonic_time
        return cached[:exact] == true
      end
      exact = exact_soft_proxy_for_full?(proxy_definition, full_definition)
      cache[key] = {
        token: token,
        exact: exact,
        proxy_definition: proxy_definition,
        full_definition: full_definition,
        touched_at: monotonic_time
      }
      if cache.length > SOFT_REPRESENTATION_PAIR_CACHE_MAX
        overflow = cache.length - SOFT_REPRESENTATION_PAIR_CACHE_MAX
        cache.sort_by { |_cache_key, record| record[:touched_at].to_f }.first(overflow).each { |cache_key, _| cache.delete(cache_key) }
      end
      exact
    rescue StandardError
      exact_soft_proxy_for_full?(proxy_definition, full_definition)
    end

    # 外包盒相同并不等于同一款模型。模型库条目被复制过 sidecar 时，两个完全不同的
    # SKP 可能共享 model_id；旧代理也可能仍保留源文件修改前的签名。任何一项明确
    # 冲突时都禁止走“原矩阵直换”的快路径，避免错误定义被拉伸到当前家具尺寸。
    def soft_representation_identity_compatible?(proxy_definition, full_definition)
      proxy_id = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s.strip rescue ''
      full_id = full_definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s.strip rescue ''
      if soft_stable_model_id?(proxy_id) && soft_stable_model_id?(full_id) && proxy_id != full_id
        return false
      end

      proxy_source = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s rescue ''
      full_source = full_definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s rescue ''
      if !proxy_source.empty? && !full_source.empty? && !same_file_path?(proxy_source, full_source)
        return false
      end

      proxy_signature = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_signature', '').to_s rescue ''
      full_signature = full_definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s rescue ''
      return false if !proxy_signature.empty? && !full_signature.empty? && proxy_signature != full_signature

      true
    rescue StandardError
      false
    end

    # LinkHub 六面代理直接建立在生成时真模型的局部坐标中。源 SKP 后来发生尺寸
    # 或几何更新时，旧代理的 bounds/signature 会与当前真模型不同，但实例上的
    # transformation 仍是用户原来的放置、旋转、缩放和镜像。此时若按旧代理外包盒
    # 拟合新真模型，会把新模型逐轴拉伸并以旧底面重新定位。只要稳定 model_id 在
    # 当前模型库中唯一，并且当前 Definition 确认是本插件生成的精确六面代理，就应
    # 采用 SketchUp 原生 definition 替换语义，逐位保留 4×4 实例矩阵。
    def soft_native_full_swap_from_visual_proxy?(proxy_definition, library_item)
      return false unless proxy_definition && proxy_definition.valid?
      return false unless library_item.is_a?(Hash)
      return false unless soft_six_view_proxy_definition?(proxy_definition)
      return false unless proxy_definition.get_attribute(SOFT_MODEL_DICT, 'exact_bounds_proxy', false) == true

      proxy_id = proxy_definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s.strip rescue ''
      target_id = library_item['id'].to_s.strip
      return false unless soft_stable_model_id?(proxy_id) && soft_stable_model_id?(target_id)
      return false unless proxy_id == target_id
      return false if soft_library_id_ambiguous?(target_id)
      true
    rescue StandardError
      false
    end

    # 每个自动代理只包含一个 6 面方块，且方块直接建立在真实家具定义的
    # 局部 bounds.min / bounds.max 上。实例变换因此可以原样复用。
    # 可直接由已缓存的局部外包盒创建代理，无需先载入高模。该缓存与源 SKP
    # 的 mtime/size 签名绑定，源文件一旦修改就会自动回退到真实载入并重算。
    def fallback_soft_proxy_definition_from_bounds(model_id, model_name, bounds_values, model = Sketchup.active_model, source_path: '')
      raise '缺少真实家具外包盒，无法生成默认代理。' unless soft_bounds_values_valid?(bounds_values)
      values = Array(bounds_values).map(&:to_f)

      # 从根上废除“已有六面代理却又生成白盒”的路径：任何旧代码/快速放置/旧空间
      # 只要最终走到 fallback，只要该 model_id 已有权威六面代理，就透明地返回六面代理。
      # 白盒仅在这款模型从未成功生成六面代理时才作为内部兜底。
      unless model_id.to_s.empty?
        record = soft_visual_proxy_registry_record(model_id.to_s, soft_library_root)
        if record
          visual_metadata = overlay_authoritative_visual_proxy_metadata(
            {
              'model_id' => model_id.to_s,
              'model_name' => model_name.to_s,
              'source_path' => source_path.to_s
            },
            model_id.to_s,
            soft_library_root
          )
          visual_definition = load_bound_soft_proxy_definition(
            visual_metadata,
            model,
            source_bounds_values: values,
            model_id: model_id.to_s,
            model_name: model_name.to_s
          )
          return visual_definition if visual_definition && visual_definition.valid?
        end
      end

      # v0.13.6.23：用户已明确废止白盒代理。上面的权威六面代理若无法读取，
      # 这里直接返回 nil，让调用方保持原模型并报告缺失；不得再创建 LH_同尺寸代理_ 白盒。
      return nil if SOFT_REQUIRE_VISUAL_PROXY

      model_marker = model_id.to_s.empty? ? Digest::SHA1.hexdigest(model_name.to_s)[0, 12] : model_id.to_s
      bounds_signature = soft_bounds_signature_from_values(values)
      marker = "#{model_marker}|#{bounds_signature}"
      @soft_proxy_definition_caches ||= {}
      model_cache = (@soft_proxy_definition_caches[model.object_id] ||= {})
      definition = model_cache[marker]
      unless definition && definition.valid?
        definition = model.definitions.to_a.find do |candidate|
          candidate.valid? && candidate.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_key', '').to_s == marker
        end
      end
      definition ||= model.definitions.add(model.definitions.unique_name("LH_同尺寸代理_#{model_name}"))
      model_cache[marker] = definition
      version = definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_version', 0).to_i
      old_signature = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s
      if version != SOFT_AUTO_PROXY_VERSION || old_signature != bounds_signature || definition.entities.to_a.empty?
        build_soft_auto_proxy_geometry_from_bounds!(definition, values)
      else
        seed_soft_definition_bounds_cache!(definition, values)
      end
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'fallback_proxy_for', model_marker)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'fallback_proxy_key', marker)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'auto_proxy_version', SOFT_AUTO_PROXY_VERSION)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'auto_proxy_style', 'box')
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_id', model_id.to_s) unless model_id.to_s.empty?
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_name', model_name.to_s)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'source_path', source_path.to_s) unless source_path.to_s.empty?
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'representation', 'proxy')
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'managed_tree', true)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'exact_bounds_proxy', true)
      definition
    end

    def fallback_soft_proxy_definition(model_id, model_name, model = Sketchup.active_model, source_definition: nil)
      raise '缺少真实家具定义，无法生成默认代理。' unless source_definition && source_definition.valid?
      fallback_soft_proxy_definition_from_bounds(
        model_id, model_name, soft_definition_bounds_values(source_definition), model,
        source_path: source_definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
      )
    end

    def soft_proxy_metadata_for(source_path, model_id = '', root: nil, index: nil)
      root = soft_library_root if root.nil?
      return {} if root.to_s.empty?
      index ||= read_soft_library_index(root)
      key = normalize_soft_library_key(source_path)
      metadata = index['models'][key]
      if !metadata.is_a?(Hash) && !model_id.to_s.empty?
        # 先让当前目录缓存按 source_path 消歧。模型记录里保留着迁移前后的历史路径，
        # 不能再用 keys.find 随机拿到同 model_id 的第一条记录。
        item = soft_library_item(model_id, force: false, source_path: source_path)
        if item
          item_key = normalize_soft_library_key(item['path'])
          metadata = index['models'][item_key]
          source_path = item['path'].to_s unless item['path'].to_s.empty?
        end
        unless metadata.is_a?(Hash)
          matches = index['models'].select do |stored_key, record|
            (record.is_a?(Hash) && record['model_id'].to_s == model_id.to_s) ||
              soft_model_id_for_path(stored_key).to_s == model_id.to_s
          end
          if matches.length == 1
            matched_key, metadata = matches.first
            source_path = matched_key.to_s if source_path.to_s.empty?
          end
        end
      end
      metadata = metadata.dup if metadata.is_a?(Hash)
      metadata['source_path'] = source_path.to_s if metadata.is_a?(Hash) && !source_path.to_s.empty?
      if metadata.is_a?(Hash) && !metadata['proxy_relative_path'].to_s.empty?
        candidate = FastPath.expand(metadata['proxy_relative_path'].to_s, root)
        metadata['proxy_path'] = candidate if metadata['proxy_path'].to_s.empty? || !File.file?(metadata['proxy_path'].to_s)
      end
      resolved_id = model_id.to_s
      resolved_id = metadata['model_id'].to_s if resolved_id.empty? && metadata.is_a?(Hash)
      overlay_authoritative_visual_proxy_metadata(metadata, resolved_id, root)
    rescue StandardError
      {}
    end

    def load_bound_soft_proxy_definition(metadata, model = Sketchup.active_model, source_definition: nil, source_bounds_values: nil, model_id: '', model_name: '')
      proxy_path = metadata['proxy_path'].to_s
      return nil if proxy_path.empty? || !File.file?(proxy_path)
      full_values = soft_bounds_values_valid?(source_bounds_values) ? Array(source_bounds_values).map(&:to_f) : nil
      full_values ||= soft_definition_bounds_values(source_definition) if source_definition && source_definition.valid?
      return nil unless soft_bounds_values_valid?(full_values)

      full_signature = soft_bounds_signature_from_values(full_values)
      file_signature_value = soft_library_file_signature(proxy_path).to_s rescue ''
      source_path = metadata['source_path'].to_s
      source_path = metadata['path'].to_s if source_path.empty?
      source_identity = source_path.empty? ? '' : normalize_soft_library_key(source_path)
      source_identity = metadata['proxy_source_signature'].to_s if source_identity.empty?
      wrapper_key = Digest::SHA1.hexdigest([proxy_path, file_signature_value, full_signature, source_identity].join('|'))
      @soft_custom_proxy_definition_caches ||= {}
      model_cache = (@soft_custom_proxy_definition_caches[model.object_id] ||= {})
      wrapper = model_cache[wrapper_key]
      unless wrapper && wrapper.valid?
        wrapper = model.definitions.to_a.find do |candidate|
          candidate.valid? && candidate.get_attribute(SOFT_MODEL_DICT, 'custom_proxy_wrapper_key', '').to_s == wrapper_key
        end
      end
      if wrapper && wrapper.valid? && !wrapper.entities.to_a.empty? &&
         wrapper.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s == full_signature
        model_cache[wrapper_key] = wrapper
        return wrapper
      end

      raw_item = {
        'id' => "proxy:#{Digest::SHA1.hexdigest(normalize_soft_library_key(proxy_path))[0, 16]}",
        'path' => proxy_path,
        'name' => File.basename(proxy_path, File.extname(proxy_path))
      }
      raw_definition = load_soft_library_definition(raw_item, model)
      return nil unless raw_definition && raw_definition.valid?

      wrapper ||= model.definitions.add(model.definitions.unique_name("LH_同尺寸自定义代理_#{model_name}"))
      model_cache[wrapper_key] = wrapper
      existing = wrapper.entities.to_a
      wrapper.entities.erase_entities(existing) unless existing.empty?
      transform = soft_proxy_fit_transformation_to_bounds(raw_definition, full_values)
      wrapper.entities.add_instance(raw_definition, transform)
      soft_clear_definition_bounds_cache!(wrapper)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'custom_proxy_wrapper_key', wrapper_key)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'proxy_full_bounds_signature', full_signature)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'exact_bounds_proxy', true)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'representation', 'proxy')
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'proxy_source_path', proxy_path)
      if metadata['proxy_kind'].to_s == SOFT_VISUAL_PROXY_KIND
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'auto_proxy_style', SOFT_VISUAL_PROXY_KIND)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'visual_proxy_kind', SOFT_VISUAL_PROXY_KIND)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'visual_proxy_version', metadata['proxy_visual_version'].to_i)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'proxy_registry_authoritative', metadata['proxy_registry_authoritative'] == true)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'proxy_source_signature', metadata['proxy_source_signature'].to_s) unless metadata['proxy_source_signature'].to_s.empty?
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'proxy_stale', false)
      end
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_id', model_id.to_s) unless model_id.to_s.empty?
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_name', model_name.to_s)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'source_path', source_path) unless source_path.empty?
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'managed_tree', true)
      persist_soft_definition_bounds_values!(wrapper, full_values)
      return nil unless soft_definition_bounds_equivalent_to_values?(wrapper, full_values, 1.0e-5)
      wrapper
    rescue StandardError => e
      log_exception("载入并归一化软装代理模型失败：#{proxy_path}", e)
      nil
    end

    # 判断一个已经加载到当前 SketchUp 会话中的 Definition 是否真的是六视图代理。
    # 这里故意不要求 NAS 权威映射仍可访问：如果用户眼前本来就是六视图代理，
    # 代→真→代必须能够原样切回来，不能因为网络映射暂时不可读而判它“不是代理”。
    def soft_six_view_proxy_definition?(definition)
      return false unless definition && definition.valid?
      kind = definition.get_attribute(SOFT_MODEL_DICT, 'visual_proxy_kind', '').to_s rescue ''
      style = definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_style', '').to_s rescue ''
      return true if kind == SOFT_VISUAL_PROXY_KIND || style == SOFT_VISUAL_PROXY_KIND
      name = definition.name.to_s rescue ''
      return true if name.start_with?('LH_六面可视代理_')
      path = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s rescue ''
      return true if !path.empty? && File.basename(path).include?('六面代理')
      # 兼容已经打包进空间 SKP 的旧六视图代理：某些 wrapper 的标记可能在
      # 内层六面 Definition / Image 上，而不是最外层 Definition。最多看 32 个直接子项，
      # 不递归全模型，不会重现 0.13.6.22 的 definitions 全表扫描。
      views = 0
      Array(definition.entities.to_a).first(32).each do |entity|
        view = entity.get_attribute(SOFT_MODEL_DICT, 'visual_proxy_view', '').to_s rescue ''
        views += 1 unless view.empty?
        child_definition = entity.respond_to?(:definition) ? (entity.definition rescue nil) : nil
        if child_definition && child_definition.valid?
          child_kind = child_definition.get_attribute(SOFT_MODEL_DICT, 'visual_proxy_kind', '').to_s rescue ''
          child_style = child_definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_style', '').to_s rescue ''
          return true if child_kind == SOFT_VISUAL_PROXY_KIND || child_style == SOFT_VISUAL_PROXY_KIND
        end
      end
      views >= 4
    rescue StandardError
      false
    end

    def soft_session_visual_proxy_cache(model = Sketchup.active_model)
      @soft_session_visual_proxy_caches ||= {}
      @soft_session_visual_proxy_caches[model.object_id] ||= {}
    rescue StandardError
      {}
    end

    def soft_session_visual_proxy_identity_current?(definition, info)
      return false unless definition && definition.valid?
      data = info.is_a?(Hash) ? info : {}
      model_id = data['model_id'].to_s.strip
      source_path = data['source_path'].to_s
      definition_source = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s rescue ''
      if !source_path.empty? && !definition_source.empty? && !same_file_path?(source_path, definition_source)
        return false
      end

      @soft_session_proxy_identity_checks ||= {}
      proxy_signature = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_signature', '').to_s rescue ''
      normalized_source = source_path.empty? ? '' : normalize_soft_library_key(source_path)
      cache_key = [definition.object_id, model_id, normalized_source, proxy_signature].join('|')
      cached = @soft_session_proxy_identity_checks[cache_key]
      now = monotonic_time
      return cached[:current] == true if cached.is_a?(Hash) && (now - cached[:checked_at].to_f) <= 30.0

      item = if soft_stable_model_id?(model_id)
               soft_library_item(model_id, force: false, source_path: source_path) rescue nil
             end
      expected_signature = item.is_a?(Hash) ? item['bounds_source_signature'].to_s : ''
      current = expected_signature.empty? || proxy_signature.empty? || expected_signature == proxy_signature
      @soft_session_proxy_identity_checks[cache_key] = { current: current, checked_at: now }
      current
    rescue StandardError
      false
    end

    def remember_soft_session_visual_proxy!(instance, model = Sketchup.active_model)
      return false unless instance && instance.valid? && model
      return false unless soft_instance_representation(instance) == 'proxy'
      definition = instance.definition rescue nil
      return false unless (soft_six_view_proxy_definition?(definition) || soft_instance_planar_reference?(instance))
      return false if !soft_instance_planar_reference?(instance) && soft_visual_proxy_definition_stale?(definition)
      info = soft_instance_metadata(instance)
      return false if !soft_instance_planar_reference?(instance) && !soft_session_visual_proxy_identity_current?(definition, info)
      cache = soft_session_visual_proxy_cache(model)
      proxy_source_path = instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s
      proxy_source_path = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s if proxy_source_path.empty?
      cache[instance.object_id] = {
        definition: definition,
        model_id: info['model_id'].to_s,
        source_path: (info['source_path'].to_s.empty? ? '' : normalize_soft_library_key(info['source_path'])),
        proxy_source_path: proxy_source_path,
        planar: soft_instance_planar_reference?(instance),
        touched_at: monotonic_time
      }
      if cache.length > SOFT_SESSION_VISUAL_PROXY_CACHE_MAX
        overflow = cache.length - SOFT_SESSION_VISUAL_PROXY_CACHE_MAX
        cache.sort_by { |_key, record| record[:touched_at].to_f }.first(overflow).each { |key, _| cache.delete(key) }
      end
      true
    rescue StandardError => e
      log_exception('记录会话六视图代理失败', e)
      false
    end

    def recover_loaded_soft_visual_proxy(instance, model = Sketchup.active_model)
      return nil unless instance && instance.valid? && model
      info = soft_instance_metadata(instance)
      model_id = info['model_id'].to_s
      source_key = info['source_path'].to_s.empty? ? '' : normalize_soft_library_key(info['source_path'])

      # 第一优先：复用 LinkHub 自己已经加载过的代理 Definition cache。热重载时这些
      # cache 会跨 runtime generation 保留，因此即使用户已经在 0.13.6.23 切到真模型，
      # 升级 0.13.6.24 后也有机会立刻找回刚才那份六视图代理。
      candidates = []
      [@soft_custom_proxy_definition_caches, @soft_proxy_definition_caches].compact.each do |root_cache|
        model_cache = root_cache[model.object_id] rescue nil
        next unless model_cache.respond_to?(:each_value)
        model_cache.each_value { |definition| candidates << definition }
      end
      match = candidates.compact.uniq.find do |definition|
        next false unless definition && definition.valid? && soft_six_view_proxy_definition?(definition)
        next false if soft_visual_proxy_definition_stale?(definition)
        did = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s rescue ''
        raw_source = (definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '') rescue '').to_s
        dsrc = normalize_soft_library_key(raw_source)
        if !source_key.empty?
          !dsrc.empty? && dsrc == source_key
        else
          !model_id.empty? && !soft_library_id_ambiguous?(model_id) && did == model_id
        end
      end

      # 仅当运行时 cache 也没有时，才做一次“浅层 Definition 索引”。这里只读每个
      # Definition 自己的几个 attribute，不递归 entities/tree；与 0.13.6.22 那种全模型
      # 递归清理扫描完全不同。索引按当前 model 缓存，最多构建一次。
      unless match
        @soft_loaded_visual_proxy_indexes ||= {}
        index = @soft_loaded_visual_proxy_indexes[model.object_id]
        unless index.is_a?(Hash)
          by_model_id = {}
          by_source = {}
          model.definitions.each do |definition|
            begin
              next unless definition && definition.valid? && soft_six_view_proxy_definition?(definition)
              next if soft_visual_proxy_definition_stale?(definition)
              did = (definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '') rescue '').to_s
              raw_source = (definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '') rescue '').to_s
              dsrc = normalize_soft_library_key(raw_source)
              by_model_id[did] ||= definition unless did.empty?
              by_source[dsrc] ||= definition unless dsrc.empty?
            rescue StandardError
              next
            end
          end
          index = { by_model_id: by_model_id, by_source: by_source }
          @soft_loaded_visual_proxy_indexes[model.object_id] = index
        end
        match = index[:by_source][source_key] unless source_key.empty?
        match ||= index[:by_model_id][model_id] if !model_id.empty? && !soft_library_id_ambiguous?(model_id)
      end
      return nil unless match && match.valid? && soft_six_view_proxy_definition?(match)
      return nil unless soft_session_visual_proxy_identity_current?(match, info)

      proxy_source_path = match.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s rescue ''
      record = {
        definition: match, model_id: model_id, source_path: source_key,
        proxy_source_path: proxy_source_path, planar: false, touched_at: monotonic_time
      }
      soft_session_visual_proxy_cache(model)[instance.object_id] = record
      record
    rescue StandardError => e
      log_exception('从已加载 Definition 恢复六视图代理失败', e)
      nil
    end

    def cached_soft_session_visual_proxy(instance, model = Sketchup.active_model)
      return nil unless instance && instance.valid? && model
      cache = soft_session_visual_proxy_cache(model)
      record = cache[instance.object_id]
      record = recover_loaded_soft_visual_proxy(instance, model) unless record.is_a?(Hash)
      return nil unless record.is_a?(Hash)
      definition = record[:definition]
      unless definition && definition.valid? && (record[:planar] || soft_six_view_proxy_definition?(definition)) &&
             (record[:planar] || !soft_visual_proxy_definition_stale?(definition))
        cache.delete(instance.object_id)
        return nil
      end
      info = soft_instance_metadata(instance)
      unless record[:planar] || soft_session_visual_proxy_identity_current?(definition, info)
        cache.delete(instance.object_id)
        return nil
      end
      current_id = info['model_id'].to_s
      stored_id = record[:model_id].to_s
      if !current_id.empty? && !stored_id.empty? && current_id != stored_id
        cache.delete(instance.object_id)
        return nil
      end
      current_source = info['source_path'].to_s.empty? ? '' : normalize_soft_library_key(info['source_path'].to_s)
      stored_source = record[:source_path].to_s
      if !current_source.empty? && !stored_source.empty? && current_source != stored_source
        cache.delete(instance.object_id)
        return nil
      end
      record[:touched_at] = monotonic_time
      record
    rescue StandardError
      nil
    end

    def soft_instance_uses_authoritative_visual_proxy?(instance, root = soft_library_root)
      return true unless instance && instance.valid?
      # 平面图片的权威代理就是自身，不需要六面代理文件或映射表。
      return true if soft_instance_planar_reference?(instance)
      definition = instance.definition rescue nil
      return false unless definition && definition.valid?
      # 当前实例虽然是六视图，但模型库刚更新后旧 Definition 会被标记 stale；
      # stale 代理不能继续作为“权威代理已经同步”的证据。网络映射不可读时，未标记
      # stale 的现有六视图仍然允许离线复用。
      return false if soft_visual_proxy_definition_stale?(definition)
      return true if soft_six_view_proxy_definition?(definition)
      info = soft_instance_metadata(instance)
      model_id = info['model_id'].to_s
      record = soft_visual_proxy_registry_record(model_id, root)
      return false unless record
      kind = definition.get_attribute(SOFT_MODEL_DICT, 'visual_proxy_kind', '').to_s
      style = definition.get_attribute(SOFT_MODEL_DICT, 'auto_proxy_style', '').to_s
      path = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s
      path = instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s if path.empty?
      visual = kind == SOFT_VISUAL_PROXY_KIND || style == SOFT_VISUAL_PROXY_KIND
      same_path = !path.empty? && same_file_path?(path, record['proxy_path'].to_s)
      visual && same_path
    rescue StandardError
      false
    end

    def space_proxy_visual_upgrade_needed?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid?
      soft_instances_for_space(entity, model).any? do |instance|
        next false unless instance && instance.valid?
        next false if soft_instance_planar_reference?(instance)
        representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
        representation == 'proxy' && !soft_instance_uses_authoritative_visual_proxy?(instance)
      end
    rescue StandardError
      false
    end

    def soft_source_bounds_values_for_proxy(metadata, info, source_definition, model = Sketchup.active_model)
      source_path = info['source_path'].to_s
      source_path = auto_relocate(source_path, model) unless source_path.empty?
      if metadata.is_a?(Hash) && !source_path.empty?
        cached_item = metadata.dup
        cached_item['path'] = source_path
        cached = soft_library_cached_bounds_values(cached_item)
        return cached if soft_bounds_values_valid?(cached)
      end

      persisted = soft_definition_persisted_bounds_values(source_definition)
      return persisted if soft_bounds_values_valid?(persisted)

      values = soft_definition_bounds_values(source_definition)
      if soft_bounds_values_valid?(values)
        persist_soft_definition_bounds_values!(source_definition, values)
        unless source_path.empty?
          item = {
            'id' => info['model_id'].to_s,
            'name' => info['model_name'].to_s,
            'path' => source_path,
            'bounds_values' => values,
            'bounds_source_signature' => soft_library_file_signature(source_path)
          }
          schedule_soft_library_bounds_persist!(item, values) if soft_library_source_path?(source_path)
        end
      end
      values
    rescue StandardError => e
      log_exception('准备家具代理外包盒失败', e)
      soft_definition_bounds_values(source_definition)
    end

    # 同款、同当前定义的实例先归组，再解析一次模型库元数据、一次外包盒和一次
    # 代/真配对。仍逐实例保留锁定、变换和属性，但把最重的工作从实例数降到款式数。
    def apply_space_soft_proxies!(entity, model = Sketchup.active_model, instances: nil, strict: true, prefer_session: true, verified_commit: false)
      started = monotonic_time
      swaps = []
      proxy_cache = {}
      planar_definition_cache = {}
      metadata_cache = {}
      instances ||= soft_instances_for_space(entity, model)
      instances = Array(instances).select { |instance| instance && instance.valid? }
      # v0.13.6.181：写库失败的家具必须保留项目内 unique 真模型，绝不能为了
      # 空间级“切代理/发布候选”偷偷套回旧代理。这里只跳过这些局部失败实例；
      # 同空间其它家具继续正常切换，最终空间状态自然会是 mixed。
      save_failed_instances = instances.select { |instance| soft_individual_edit_save_failed?(instance) }
      unless verified_commit
        pending_entities = soft_pending_proxy_rebuild_records(model).map { |row| row[:entity] }
        save_failed_instances |= instances.select { |instance| pending_entities.include?(instance) }
      end
      unless save_failed_instances.empty?
        labels = save_failed_instances.map { |instance| soft_instance_metadata(instance)['model_name'].to_s rescue '' }.reject(&:empty?).uniq
        log("代理切换局部跳过未写库真模型：#{labels.empty? ? save_failed_instances.length.to_s + ' 个实例' : labels.join('、')}")
        instances = instances.reject { |instance| save_failed_instances.include?(instance) }
      end

      # v0.13.6.24 快路径：如果这些实例刚刚从六视图代理切成真模型，直接使用
      # “切真之前那一份实际 Definition”切回来。这样既不需要重新扫模型库/NAS，
      # 也不会因为六面代理映射缺项而把 23 个本来可见的代理全部判失败。
      session_restored = {}
      if prefer_session
        instances.each do |instance|
          record = cached_soft_session_visual_proxy(instance, model)
          next unless record
          proxy_definition = record[:definition]
          next unless proxy_definition && proxy_definition.valid?
          current_representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
          next if current_representation == 'proxy' && instance.definition == proxy_definition
          swap_record = nil
          begin
          swap_record = {
            entity: instance,
            definition: instance.definition,
            transformation: instance.transformation,
            locked: (instance.respond_to?(:locked?) ? instance.locked? : false),
            representation: current_representation,
            proxy_source_path: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s,
            proxy_passthrough: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_passthrough', nil),
            planar_reference: instance.get_attribute(SOFT_MODEL_DICT, 'planar_reference', nil)
          }
          swaps << swap_record
          was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
          instance.locked = false if was_locked && instance.respond_to?(:locked=)
          preserved = instance.transformation
          if record[:planar]
            instance.definition = proxy_definition unless instance.definition == proxy_definition
            instance.transformation = preserved
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'proxy_passthrough', true)
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'planar_reference', true)
          else
            if soft_exact_representation_pair?(proxy_definition, instance.definition, model)
              replace_instance_definition_preserving_exact_transform!(instance, proxy_definition, '会话代理恢复')
            else
              replace_instance_definition_preserving_box!(instance, proxy_definition)
            end
            instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
          end
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'proxy')
          proxy_source_path = record[:proxy_source_path].to_s
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'proxy_source_path', proxy_source_path) unless proxy_source_path.empty?
          instance.locked = true if was_locked && instance.respond_to?(:locked=)
          session_restored[instance.object_id] = true
          rescue StandardError => e
            restore_space_soft_proxies!([swap_record]) if swap_record
            swaps.delete(swap_record) if swap_record
            log_exception('会话六视图代理快速恢复失败，转入常规解析', e)
          end
        end
      end

      unresolved_instances = instances.reject { |instance| session_restored[instance.object_id] }
      # 只有真的还有未命中会话代理的家具，才访问模型库索引/NAS。
      root = soft_library_root
      index = if unresolved_instances.empty? || root.to_s.empty?
                { 'models' => {} }
              else
                read_soft_library_index(root)
              end
      groups = {}
      Array(unresolved_instances).each do |instance|
        next unless instance && instance.valid?
        info = soft_instance_metadata(instance)
        key = [
          instance.definition.object_id,
          info['model_id'].to_s,
          normalize_soft_library_key(info['source_path']),
          info['model_name'].to_s
        ]
        group = (groups[key] ||= { definition: instance.definition, info: info, instances: [] })
        group[:instances] << instance
      end

      groups.each_value do |group|
        source_definition = group[:definition]
        next unless source_definition && source_definition.valid?
        info = group[:info]
        metadata_key = [info['model_id'].to_s, normalize_soft_library_key(info['source_path'])].join('|')
        metadata = metadata_cache[metadata_key] ||= soft_proxy_metadata_for(
          info['source_path'], info['model_id'], root: root, index: index
        )
        full_values = soft_source_bounds_values_for_proxy(metadata, info, source_definition, model)
        next unless soft_bounds_values_valid?(full_values)
        if soft_metadata_planar_reference?(metadata) || soft_bounds_planar_reference?(full_values)
          # 新识别出的平面图片有时仍以旧版六面代理定义显示。此时不能只给旧代理
          # 打上 planar 标记，而要把实例真正换回模型库中的原始平面定义；变换保持不变。
          planar_definition = source_definition
          unless soft_definition_planar_reference?(planar_definition)
            cache_key = [info['model_id'].to_s, normalize_soft_library_key(info['source_path'])].join('|')
            planar_definition = planar_definition_cache[cache_key]
            unless planar_definition && planar_definition.valid?
              library_item = full_soft_library_item_for(info, model)
              candidate_definition = library_item ? load_soft_library_definition(library_item, model) : nil
              planar_definition = candidate_definition if candidate_definition && soft_definition_planar_reference?(candidate_definition)
              planar_definition_cache[cache_key] = planar_definition if planar_definition && planar_definition.valid?
            end
          end
          unless planar_definition && planar_definition.valid? && soft_definition_planar_reference?(planar_definition)
            log("平面图片家具暂时无法载入原始定义，保持当前模型：#{info['model_name']}")
            next
          end
          mark_soft_planar_reference!(planar_definition, true)
          group[:instances].each do |instance|
            next unless instance && instance.valid?
            current_representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
            next if current_representation == 'proxy' && instance.definition == planar_definition &&
                    soft_instance_representation_ready?(instance, 'proxy')
            swaps << {
              entity: instance,
              definition: instance.definition,
              transformation: instance.transformation,
              locked: (instance.respond_to?(:locked?) ? instance.locked? : false),
              representation: current_representation,
              proxy_source_path: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s,
              proxy_passthrough: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_passthrough', nil),
              planar_reference: instance.get_attribute(SOFT_MODEL_DICT, 'planar_reference', nil)
            }
            was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
            instance.locked = false if was_locked && instance.respond_to?(:locked=)
            preserved = instance.transformation
            instance.definition = planar_definition unless instance.definition == planar_definition
            instance.transformation = preserved
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'proxy')
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'proxy_passthrough', true)
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'planar_reference', true)
            instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
            instance.locked = true if was_locked && instance.respond_to?(:locked=)
          end
          next
        end
        bounds_key = soft_bounds_signature_from_values(full_values)
        proxy_key = metadata['proxy_path'].to_s
        proxy_key = "fallback:#{info['model_id']}:#{info['model_name']}" if proxy_key.empty?
        proxy_key = "#{proxy_key}|#{bounds_key}"
        proxy_definition = proxy_cache[proxy_key]
        unless proxy_definition && proxy_definition.valid?
          proxy_definition = load_bound_soft_proxy_definition(
            metadata,
            model,
            source_definition: source_definition,
            source_bounds_values: full_values,
            model_id: info['model_id'],
            model_name: info['model_name']
          )
          unless proxy_definition && proxy_definition.valid?
            proxy_definition = fallback_soft_proxy_definition_from_bounds(
              info['model_id'], info['model_name'], full_values, model,
              source_path: info['source_path']
            ) unless SOFT_REQUIRE_VISUAL_PROXY
          end
          proxy_cache[proxy_key] = proxy_definition if proxy_definition && proxy_definition.valid?
        end
        unless proxy_definition && proxy_definition.valid?
          log("六面代理不可用，保持当前模型：#{info['model_name']} / model_id=#{info['model_id']}")
          next
        end
        exact_pair = soft_exact_representation_pair?(proxy_definition, source_definition, model)

        group[:instances].each do |instance|
          next unless instance && instance.valid?
          current_representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
          next if current_representation == 'proxy' && instance.definition == proxy_definition

          swaps << {
            entity: instance,
            definition: instance.definition,
            transformation: instance.transformation,
            locked: (instance.respond_to?(:locked?) ? instance.locked? : false),
            representation: current_representation,
            proxy_source_path: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s
          }
          was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
          instance.locked = false if was_locked && instance.respond_to?(:locked=)
          if exact_pair
            replace_instance_definition_preserving_exact_transform!(instance, proxy_definition, '真模型切换为代理')
          else
            replace_instance_definition_preserving_box!(instance, proxy_definition)
          end
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'proxy')
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'proxy_source_path', metadata['proxy_path'].to_s)
          instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
          instance.locked = true if was_locked && instance.respond_to?(:locked=)
        end
      end
      failures = instances.reject { |instance| soft_instance_representation_ready?(instance, 'proxy') }
      # v0.13.6.182：单件家具缺代理不再让整批切换回滚。已经切好的实例一律保留，
      # 缺代理的家具保持真模型，并按“名称 ×数量”记录下来交给调用方：空间级切换
      # 会立即排队自动补生成，发布候选会带着这份名单继续发布（mixed 包）。
      # strict 参数保留兼容语义，但只影响日志级别，不再抛异常。
      remember_soft_proxy_switch_unresolved!(model, failures)
      unless failures.empty?
        root = soft_library_root.to_s
        cause = if root.empty? || !Dir.exist?(root)
                  '软装模型库路径未设置或不可访问'
                else
                  '既无会话六视图代理、也无法从模型库解析六视图代理'
                end
        summary = soft_proxy_switch_instance_summary(failures)
        log("代理切换局部保留真模型（#{strict ? '严格调用' : '宽松调用'}）：#{summary} / 原因：#{cause} / 已切换 #{swaps.length} 个实例保持不变")
      end
      log_slow_operation('家具切换代理核心', started, 120.0, "#{instances.length} 实例 / #{groups.length} 款")
      swaps
    rescue StandardError
      restore_space_soft_proxies!(swaps)
      raise
    end

    # 最近一次 apply_space_soft_proxies! 没能切成代理的实例（按 model 记录）。
    # 调用方读取后应立即消费（take_ 版本），避免旧名单影响下一次切换。
    def remember_soft_proxy_switch_unresolved!(model, instances)
      return [] unless model
      @soft_proxy_switch_unresolved ||= {}
      rows = Array(instances).select { |instance| instance && instance.valid? }.uniq
      @soft_proxy_switch_unresolved[model.object_id] = rows
      rows
    rescue StandardError
      []
    end

    def take_soft_proxy_switch_unresolved!(model)
      return [] unless model && @soft_proxy_switch_unresolved.is_a?(Hash)
      rows = @soft_proxy_switch_unresolved.delete(model.object_id)
      Array(rows).select { |instance| instance && instance.valid? }
    rescue StandardError
      []
    end

    # “名称 ×数量、名称 …（另 N 款）”——所有面向用户的家具提示统一走这里，绝不再只报个数。
    def soft_furniture_name_summary(names, limit: 6, empty: '未命名家具')
      counts = Hash.new(0)
      order = []
      Array(names).each do |raw|
        name = raw.to_s.strip
        name = empty if name.empty?
        order << name unless counts.key?(name)
        counts[name] += 1
      end
      return empty if order.empty?
      shown = order.first([limit.to_i, 1].max).map { |name| counts[name] > 1 ? "#{name} ×#{counts[name]}" : name }
      shown << "另 #{order.length - shown.length} 款" if order.length > shown.length
      shown.join('、')
    rescue StandardError
      Array(names).length.to_s + ' 款'
    end

    # v0.13.6.182：丢失/过期代理的自动修复。只要实例仍能通过 model_id + 源文件签名
    # 找回模型库中的真模型，就直接从真模型重新生成六面代理并自动切回，不再弹错误框；
    # 身份对不上的实例保留原样并记入日志。返回 { started:, names:, skipped: }。
    def soft_lost_proxy_repair_candidates(instances, model = Sketchup.active_model)
      root = soft_library_root.to_s
      return { rows: [], skipped: [] } if root.empty? || !Dir.exist?(root)
      rows = []
      skipped = []
      Array(instances).select { |instance| instance && instance.valid? }.uniq.each do |instance|
        info = soft_instance_metadata(instance)
        name = info['model_name'].to_s
        name = soft_identity_display_name(instance.definition.name.to_s) if name.empty? && instance.respond_to?(:definition) && instance.definition
        name = '未命名家具' if name.empty?
        if soft_instance_planar_reference?(instance)
          next
        end
        if soft_individual_edit_save_failed?(instance)
          skipped << "#{name}：上次写库失败，保留项目内真模型"
          next
        end
        unless soft_entity_managed_identity_evidence?(instance, info)
          skipped << "#{name}：没有 LinkHub 身份证据"
          next
        end
        library_item = full_soft_library_item_for(info, model)
        unless library_item.is_a?(Hash) && File.file?(library_item['path'].to_s)
          skipped << "#{name}：模型库中找不到可读真模型"
          next
        end
        stable_id = info['model_id'].to_s.strip
        if soft_stable_model_id?(stable_id) && !library_item['id'].to_s.empty? && library_item['id'].to_s != stable_id
          skipped << "#{name}：model_id 与模型库不一致（#{stable_id} ≠ #{library_item['id']}）"
          next
        end
        stored_signature = begin
          instance.definition.get_attribute(SOFT_MODEL_DICT, 'source_signature', '').to_s
        rescue StandardError
          ''
        end
        # 只有项目内仍是“真模型”且它带着旧签名时才比较；代理/白盒本身没有源签名可比。
        if soft_instance_representation(instance) == 'full' && !stored_signature.empty?
          library_signature = soft_library_file_signature(library_item['path'].to_s)
          if !library_signature.empty? && library_signature != stored_signature
            skipped << "#{name}：项目内真模型与模型库源文件签名不一致，请先“更新源模型”"
            next
          end
        end
        rows << {
          instance: instance, name: library_item['name'].to_s.empty? ? name : library_item['name'].to_s,
          model_id: library_item['id'].to_s, source_path: FastPath.expand(library_item['path'].to_s),
          legacy: soft_legacy_proxy_entity?(instance)
        }
      rescue StandardError => e
        log_exception('检查丢失代理实例失败', e)
        next
      end
      { rows: rows, skipped: skipped }
    end

    # 多个空间连续载入时合并成一次检查；真正的身份校验与排队在 1.6s 后的空闲回调里完成。
    def request_soft_lost_proxy_auto_repair_for_space!(entity, model = Sketchup.active_model, space_id: '', extra_instances: nil)
      return false unless entity && entity.valid? && model
      @soft_lost_proxy_repair_requests ||= {}
      rows = (@soft_lost_proxy_repair_requests[model.object_id] ||= {})
      key = space_id.to_s.empty? ? entity.object_id.to_s : space_id.to_s
      request = (rows[key] ||= { entity: entity, extra: [] })
      request[:entity] = entity
      request[:extra] = (Array(request[:extra]) + Array(extra_instances)).select { |instance| instance && instance.valid? }.uniq
      runtime_start_timer(1.6, false, label: 'soft:lost_proxy_auto_repair', key: "soft:lost_proxy_auto_repair:#{model.object_id}", model: model, active_model_only: true) do
        flush_soft_lost_proxy_auto_repair_requests!(model)
      end
      true
    rescue StandardError => e
      log_exception('登记丢失代理自动修复失败', e)
      false
    end

    def flush_soft_lost_proxy_auto_repair_requests!(model = Sketchup.active_model)
      return false unless model && @soft_lost_proxy_repair_requests.is_a?(Hash)
      pending = @soft_lost_proxy_repair_requests[model.object_id]
      return false unless pending.is_a?(Hash) && !pending.empty?
      # 前台正忙（发布/入库/重操作）时延后，不抢用户操作；队列本身也会再次让路。
      if publish_critical_section? || publish_post_quiet? || soft_heavy_interaction? || @updating || @single_space_update_job || @space_batch_update_job
        @soft_lost_proxy_repair_wait_rounds ||= Hash.new(0)
        rounds = (@soft_lost_proxy_repair_wait_rounds[model.object_id] += 1)
        if rounds > 48
          # 前台持续繁忙约 2 分钟：放弃本轮，不无限重排；下一次载入/切代理会重新登记。
          @soft_lost_proxy_repair_wait_rounds.delete(model.object_id)
          @soft_lost_proxy_repair_requests.delete(model.object_id)
          return false
        end
        runtime_start_timer(2.5, false, label: 'soft:lost_proxy_auto_repair_wait', key: "soft:lost_proxy_auto_repair:#{model.object_id}", model: model, active_model_only: true) do
          flush_soft_lost_proxy_auto_repair_requests!(model)
        end
        return false
      end
      @soft_lost_proxy_repair_wait_rounds&.delete(model.object_id)
      @soft_lost_proxy_repair_requests.delete(model.object_id)
      total = 0
      # 已经登记为“写库后待重建”的实例由发布/退出批处理负责，不重复排队。
      pending_ids = soft_pending_proxy_rebuild_records(model).map { |record| record[:entity] && record[:entity].valid? ? record[:entity].object_id : nil }.compact
      budget = SOFT_LOST_PROXY_AUTO_REPAIR_MAX_MODELS_PER_ROUND
      pending.each do |space_id, request|
        break if budget <= 0
        entity = request.is_a?(Hash) ? request[:entity] : request
        next unless entity && entity.valid?
        lost = soft_lost_proxy_instances_for_space(entity, model)
        lost = (lost + Array(request[:extra])).select { |instance| instance && instance.valid? }.uniq if request.is_a?(Hash)
        lost = lost.reject { |instance| pending_ids.include?(instance.object_id) }
        next if lost.empty?
        # 一轮最多自动排队 N 款，超出的留到下次载入/切代理再补，避免老项目大量白盒一次性排队数百款。
        limited = []
        seen_models = {}
        lost.each do |instance|
          mid = (soft_instance_metadata(instance)['model_id'].to_s rescue '')
          key = mid.empty? ? "oid:#{instance.object_id}" : mid
          next if !seen_models[key] && seen_models.length >= budget
          seen_models[key] = true
          limited << instance
        end
        skipped_count = lost.length - limited.length
        log("自动修复代理：本轮先处理 #{seen_models.length} 款，另有 #{skipped_count} 个实例留待下次") if skipped_count.positive?
        result = schedule_soft_lost_proxy_auto_repair!(limited, model, scope_space_id: space_id.to_s, reason: '载入后自动修复代理', notify: true)
        budget -= seen_models.length
        total += result[:started].to_i
      rescue StandardError => e
        log_exception('执行丢失代理自动修复失败', e)
        next
      end
      total.positive?
    rescue StandardError => e
      log_exception('汇总丢失代理自动修复失败', e)
      false
    end

    def schedule_soft_lost_proxy_auto_repair!(instances, model = Sketchup.active_model, scope_space_id: '', reason: '自动修复丢失代理', notify: true, replace: true)
      result = { started: 0, names: [], skipped: [] }
      return result unless model
      selected = Array(instances).select { |instance| instance && instance.valid? }.uniq
      return result if selected.empty?
      checked = soft_lost_proxy_repair_candidates(selected, model)
      result[:skipped] = Array(checked[:skipped])
      rows = Array(checked[:rows])
      unless result[:skipped].empty?
        log("自动修复代理跳过：#{result[:skipped].first(12).join(' | ')}#{result[:skipped].length > 12 ? " | 另 #{result[:skipped].length - 12} 条" : ''}")
      end
      return result if rows.empty?

      @soft_lost_proxy_repair_recent ||= {}
      now = monotonic_time
      grouped = rows.group_by { |row| row[:model_id].to_s }
      seeds = []
      grouped.each do |model_id, group|
        next if model_id.empty?
        recent = @soft_lost_proxy_repair_recent[model_id]
        if recent.is_a?(Hash)
          snapshot = task_center_job_snapshot(recent[:task_id].to_s) rescue nil
          # 同款最近刚失败过：10 分钟内不再自动重试，避免每次载入都重复截图/报错；
          # 用户仍可通过“代理”按钮或家具入库校对手动触发。
          if snapshot && snapshot[:status].to_s == 'failed' && (now - recent[:at].to_f) < 600.0
            result[:skipped] << "#{group.first[:name]}：最近一次自动修复失败，暂不重试"
            next
          end
          if (now - recent[:at].to_f) < 90.0 && snapshot && %w[queued running].include?(snapshot[:status].to_s)
            # 同款已在队列里：只把新实例并进去，不再新开一张任务卡。
            merge_seed = {
              model_id: model_id, model_name: group.first[:name].to_s, source_path: group.first[:source_path].to_s,
              scope_space_id: scope_space_id.to_s,
              replace_instances: (replace ? group.map { |row| row[:instance] } : []), allow_inside_space: true, priority: true,
              proxy_task_id: recent[:task_id].to_s, auto_repair: true
            }
            seeds << merge_seed
            next
          end
        end
        seed = {
          model_id: model_id, model_name: group.first[:name].to_s, source_path: group.first[:source_path].to_s,
          scope_space_id: scope_space_id.to_s,
          replace_instances: (replace ? group.map { |row| row[:instance] } : []),
          source_definition: nil,
          legacy_recovery: group.any? { |row| row[:legacy] },
          allow_inside_space: true, priority: true, auto_repair: true
        }
        seed[:proxy_task_id] = ensure_soft_visual_proxy_seed_task!(
          seed, model, detail: "#{reason} · 从模型库真模型重新生成并自动切回"
        ).to_s
        @soft_lost_proxy_repair_recent[model_id] = { at: now, task_id: seed[:proxy_task_id].to_s }
        seeds << seed
      end
      return result if seeds.empty?

      started = start_soft_schedule_visual_proxy_upgrade(
        model, reason: reason.to_s, seeds: seeds, scope_space_id: scope_space_id.to_s, foreground_exit_batch: false
      )
      unless started.is_a?(Hash) && started[:running]
        message = started.is_a?(Hash) ? started[:error].to_s : ''
        message = '代理生成任务未能启动' if message.empty?
        seeds.each do |seed|
          tid = seed[:proxy_task_id].to_s
          finish_task_center_job!(tid, success: false, stage: '自动修复未启动', detail: message) unless tid.empty?
        end
        log("自动修复代理未启动：#{message}")
        return result
      end
      result[:started] = seeds.length
      seeded_ids = seeds.map { |seed| seed[:model_id].to_s }
      result[:names] = rows.select { |row| seeded_ids.include?(row[:model_id].to_s) }.map { |row| row[:name].to_s }
      summary = soft_furniture_name_summary(result[:names])
      log("自动修复代理已排队：#{summary} / #{reason}")
      # 排队阶段不打扰用户；真正修复完成后由代理队列收尾弹出“已自动修复代理 · 名称”提示。
      Sketchup.set_status_text("自动修复代理 · #{summary}") if notify && Sketchup.respond_to?(:set_status_text)
      result
    rescue StandardError => e
      log_exception('安排自动修复丢失代理失败', e)
      result
    end

    # 空间里“应该是代理却不是权威代理”的实例：代理文件丢失、映射失效、旧白盒、
    # 或因缺代理被迫保留真模型的家具。用于载入/进入空间后的自动修复检测。
    # 最后的用户意图优先：用户刚把某个作用域切成真模型后，队列里的自动修复/代理刷新
    # 只更新权威代理文件，不再在完成瞬间把这些实例弹回代理。scope 为空表示全部空间。
    def drop_soft_proxy_queue_replace_targets!(model = Sketchup.active_model, scope_space_id: '')
      job = @soft_visual_proxy_upgrade_job
      return 0 unless job.is_a?(Hash) && job[:model].equal?(model)
      scope_id = scope_space_id.to_s
      scope_entity = nil
      unless scope_id.empty?
        scope_entity = space_model_entity(scope_id, model)
        return 0 unless scope_entity && scope_entity.valid?
      end
      dropped = 0
      candidates = Array(job[:scan_queue]) + Array(job[:queue])
      state = job[:active_candidate_state]
      candidates << state[:candidate] if state.is_a?(Hash) && state[:candidate].is_a?(Hash)
      candidates.each do |candidate|
        next unless candidate.is_a?(Hash)
        before = Array(candidate[:replace_instances])
        next if before.empty?
        kept = before.select do |instance|
          next false unless instance && instance.valid?
          next false if scope_entity.nil?
          !entity_inside_definition_tree?(instance, scope_entity.definition)
        rescue StandardError
          true
        end
        dropped += before.length - kept.length
        candidate[:replace_instances] = kept
      end
      log("代理队列已按用户真模型意图剔除 #{dropped} 个待替换实例（作用域 #{scope_id.empty? ? '全部' : scope_id}）") if dropped.positive?
      dropped
    rescue StandardError => e
      log_exception('按用户意图剔除代理队列替换实例失败', e)
      0
    end

    def soft_lost_proxy_instances_for_space(entity, model = Sketchup.active_model)
      return [] unless entity && entity.valid?
      soft_instances_for_space(entity, model).select do |instance|
        next false unless instance && instance.valid?
        next false if soft_instance_planar_reference?(instance)
        representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
        representation == 'proxy' && !soft_instance_uses_authoritative_visual_proxy?(instance)
      rescue StandardError
        false
      end
    rescue StandardError
      []
    end

    def restore_space_soft_proxies!(swaps)
      Array(swaps).reverse_each do |record|
        instance = record[:entity]
        next unless instance && instance.valid?
        instance.locked = false if instance.respond_to?(:locked=)
        instance.definition = record[:definition] if record[:definition] && record[:definition].valid?
        instance.transformation = record[:transformation]
        if record[:representation].to_s.empty?
          instance.delete_attribute(SOFT_MODEL_DICT, 'representation') rescue nil
        else
          instance.set_attribute(SOFT_MODEL_DICT, 'representation', record[:representation].to_s)
        end
        if record[:proxy_source_path].to_s.empty?
          instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
        else
          instance.set_attribute(SOFT_MODEL_DICT, 'proxy_source_path', record[:proxy_source_path].to_s)
        end
        if record.key?(:proxy_passthrough)
          if record[:proxy_passthrough].nil?
            instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
          else
            instance.set_attribute(SOFT_MODEL_DICT, 'proxy_passthrough', record[:proxy_passthrough])
          end
        end
        if record.key?(:planar_reference)
          if record[:planar_reference].nil?
            instance.delete_attribute(SOFT_MODEL_DICT, 'planar_reference') rescue nil
          else
            instance.set_attribute(SOFT_MODEL_DICT, 'planar_reference', record[:planar_reference])
          end
        end
        instance.locked = record[:locked] if instance.respond_to?(:locked=)
      end
      true
    rescue StandardError => e
      log_exception('恢复空间真模型失败', e)
      false
    end

    def soft_managed_definition?(definition)
      return false unless definition && definition.valid?
      !definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s.empty? ||
        !definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s.empty? ||
        !definition.get_attribute(SOFT_MODEL_DICT, 'fallback_proxy_for', '').to_s.empty? ||
        !definition.get_attribute(SOFT_MODEL_DICT, 'placement_wrapper_for', '').to_s.empty? ||
        definition.get_attribute(SOFT_MODEL_DICT, 'managed_tree', false)
    rescue StandardError
      false
    end

    def purge_unused_soft_definitions_batch!(model = Sketchup.active_model, candidates: nil, max_definitions: SOFT_MANAGED_DEFINITION_CLEANUP_BATCH)
      return { removed: 0, inspected: 0 } unless model
      rows = Array(candidates || model.definitions.to_a).first([max_definitions.to_i, 1].max)
      removed = 0
      inspected = 0
      rows.each do |definition|
        inspected += 1
        next unless definition && definition.valid? && definition.instances.empty?
        next unless soft_managed_definition?(definition)
        # 六视图代理本身是很轻的可再生资源。更新模型库后旧代理会被标记 stale，
        # 但不要在交互后 1 秒左右立刻删除其 Definition/Image 图，否则又会把原生
        # Definition 清理成本推到用户操作之后造成“明明切完了又突然卡住”。旧代理
        # 留到关闭会话/SketchUp 原生清理即可；当前实例已经不会再复用 stale 代理。
        next if soft_six_view_proxy_definition?(definition) && soft_visual_proxy_definition_stale?(definition)
        # 本会话因“代理 -> 真”载入的高模是有意驻留的热缓存。即使当前画面已经切回
        # 六视图代理，也不要被其它后台受管定义清理顺手删除，否则下一次切真会再次 load。
        next if soft_session_resident_full_definition?(definition, model)
        removed += 1 if remove_unused_definition!(definition, model)
      end
      { removed: removed, inspected: inspected }
    rescue StandardError => e
      log_exception('分批卸载未使用软装定义失败', e)
      { removed: 0, inspected: 0 }
    end

    def run_soft_managed_definition_cleanup_step(model, token)
      @soft_managed_definition_cleanup_records ||= {}
      key = model.object_id
      record = @soft_managed_definition_cleanup_records[key]
      return false unless record && record[:token].to_s == token.to_s
      unless model == Sketchup.active_model || (model.respond_to?(:valid?) && model.valid?)
        @soft_managed_definition_cleanup_records.delete(key)
        return false
      end
      unless background_work_idle?(model, min_idle: 0.55)
        runtime_start_timer(BACKGROUND_WORK_RETRY_SECONDS, false, label: '受管定义清理避让') do
          run_soft_managed_definition_cleanup_step(model, token)
        end
        return true
      end

      interaction_started = false
      begin
        begin_soft_heavy_interaction(:definition_cleanup)
        interaction_started = true
        record[:definitions] ||= model.definitions.to_a
        record[:cursor] = record[:cursor].to_i
        batch = Array(record[:definitions]).slice(record[:cursor], SOFT_MANAGED_DEFINITION_CLEANUP_BATCH) || []
        result = purge_unused_soft_definitions_batch!(
          model, candidates: batch, max_definitions: SOFT_MANAGED_DEFINITION_CLEANUP_BATCH
        )
        record[:cursor] += batch.length
        record[:removed] = record[:removed].to_i + result[:removed].to_i
        record[:pass_removed] = record[:pass_removed].to_i + result[:removed].to_i

        pass_finished = record[:cursor] >= Array(record[:definitions]).length
        if !pass_finished
          runtime_start_timer(0.10, false, label: '受管定义继续分批清理') do
            run_soft_managed_definition_cleanup_step(model, token)
          end
        else
          record[:passes] = record[:passes].to_i + 1
          continue_pass = record[:pass_removed].to_i.positive? &&
                          record[:passes].to_i < SOFT_MANAGED_DEFINITION_CLEANUP_MAX_PASSES
          if continue_pass
            # 删除父定义后，部分嵌套子定义才会变成未使用；下一轮重新拍一次轻量列表。
            record[:definitions] = nil
            record[:cursor] = 0
            record[:pass_removed] = 0
            runtime_start_timer(0.16, false, label: '受管定义下一轮清理') do
              run_soft_managed_definition_cleanup_step(model, token)
            end
          else
            @soft_managed_definition_cleanup_records.delete(key)
            prune_invalid_definition_caches_after_native_purge!(model) if record[:removed].to_i.positive?
            log("受管软装定义后台清理完成：#{record[:removed]} 个定义，#{record[:passes]} 轮") if record[:removed].to_i.positive?
          end
        end
        true
      rescue StandardError => e
        @soft_managed_definition_cleanup_records&.delete(key)
        log_exception('执行受管软装定义后台清理失败', e)
        false
      ensure
        end_soft_heavy_interaction(:definition_cleanup) if interaction_started
      end
    end

    def schedule_soft_managed_definition_cleanup(model = Sketchup.active_model, delay: SOFT_MANAGED_DEFINITION_CLEANUP_DELAY)
      return false unless model
      @soft_managed_definition_cleanup_records ||= {}
      key = model.object_id
      token = SecureRandom.hex(8)
      @soft_managed_definition_cleanup_records[key] = {
        token: token,
        passes: 0,
        removed: 0,
        pass_removed: 0,
        cursor: 0,
        definitions: nil,
        scheduled_at: monotonic_time
      }
      runtime_start_timer(delay.to_f, false, label: '受管软装定义后台清理') do
        run_soft_managed_definition_cleanup_step(model, token)
      end
      true
    rescue StandardError => e
      log_exception('安排受管软装定义后台清理失败', e)
      false
    end

    # 保留旧接口，但不再在更新、删除或代/真切换的交互路径中同步扫描 definitions 六轮。
    # 真正删除会在用户空闲时小批量完成；当前仍被实例引用的定义绝不会被删除。
    def purge_unused_soft_definitions!(model = Sketchup.active_model)
      schedule_soft_managed_definition_cleanup(model)
    end

    # v0.13.6.61：会话里已经载入过的真模型必须先于 NAS/模型库解析命中。
    # 旧流程虽然“保留了高模 Definition”，再次切真时仍先 soft_library_item -> File.file?
    # -> source_signature，再去缓存找 Definition；NAS 慢时会出现“明明内存里有真模型还等很久”。
    # 这里直接按稳定 model_id（旧记录再按 source_path）命中 resident 记录，全程纯内存。
    def resident_soft_full_match(info, model = Sketchup.active_model)
      return nil unless model
      data = info.is_a?(Hash) ? info : {}
      model_id = data['model_id'].to_s.strip
      source_key = data['source_path'].to_s.empty? ? '' : normalize_soft_library_key(data['source_path'].to_s)
      records = @soft_resident_full_records && @soft_resident_full_records[model.object_id]
      return nil unless records.is_a?(Hash)
      matches = records.values.select do |candidate|
        next false unless candidate.is_a?(Hash)
        definition = candidate[:definition]
        next false unless definition && definition.valid?
        candidate_id = candidate[:model_id].to_s.strip
        candidate_source = normalize_soft_library_key(candidate[:source_path].to_s)
        if soft_stable_model_id?(model_id)
          next false unless candidate_id == model_id
          source_key.empty? || (!candidate_source.empty? && candidate_source == source_key)
        else
          !source_key.empty? && candidate_source == source_key
        end
      rescue StandardError
        false
      end
      record = matches.max_by { |candidate| [candidate[:last_used_at].to_f, candidate[:loaded_at].to_f] }
      return nil unless record
      definition = record[:definition]
      return nil unless definition && definition.valid?
      path = record[:source_path].to_s
      path = data['source_path'].to_s if path.empty?
      name = definition.get_attribute(SOFT_MODEL_DICT, 'model_name', '').to_s rescue ''
      name = data['model_name'].to_s if name.empty?
      {
        definition: definition,
        library_item: {
          'id' => (record[:model_id].to_s.empty? ? model_id : record[:model_id].to_s),
          'path' => path,
          'name' => name
        },
        record: record
      }
    rescue StandardError
      nil
    end

    # 代理只作用于空间内部的受管软装家具，不再生成“空间代理文件”。
    # 单一空间 SKP 保存硬装真实几何和家具代理实例；代/真切换仅替换家具组件定义。
    def full_soft_library_item_for(info, model = Sketchup.active_model)
      data = info.is_a?(Hash) ? info : {}
      model_id = data['model_id'].to_s.strip
      source = data['source_path'].to_s
      source = auto_relocate(source, model) unless source.empty?

      if File.file?(source)
        scan_soft_library!(force: false)
        cache = @soft_library_cache
        by_path = Array(cache.is_a?(Hash) ? cache[:items] : []).find do |row|
          same_file_path?(row['path'].to_s, source)
        rescue StandardError
          false
        end
        return by_path if by_path && File.file?(by_path['path'].to_s)
        return {
          'id' => soft_stable_model_id?(model_id) ? model_id : soft_model_id_for_path(source),
          'path' => FastPath.expand(source),
          'name' => data['model_name'].to_s.empty? ? File.basename(source, File.extname(source)) : data['model_name'].to_s
        }
      end

      legacy_hint = data['legacy_proxy'] == true || !data['legacy_proxy_marker'].to_s.empty? ||
                    !data['fallback_proxy_key'].to_s.empty? || soft_bounds_values_valid?(data['legacy_proxy_bounds_values'])
      if legacy_hint
        recovered = recover_legacy_soft_library_item(data, model)
        return recovered if recovered && File.file?(recovered['path'].to_s)
      end

      item = if soft_stable_model_id?(model_id)
               soft_library_item(model_id, force: false, source_path: source) rescue nil
             end
      if item && !item['path'].to_s.empty?
        return item if File.file?(item['path'].to_s)
      end

      # 只有已经证明是历史 LinkHub 代理的对象，才允许进入名称/尺寸反查。
      # 普通组件无 model_id/source_path 时到此直接结束，彻底封死“组件 -> 某个软装”误认。
      return nil unless legacy_hint
      recovered = recover_legacy_soft_library_item(data, model)
      return recovered if recovered && File.file?(recovered['path'].to_s)
      nil
    rescue StandardError => e
      log_exception('解析家具真模型源失败', e)
      nil
    end

    # 将“已经高置信度找回真模型”的旧白盒重新写回稳定身份。这里只修复项目里的
    # 代理元数据，不会把白盒写回模型库 SKP，也不会改变实例变换/尺寸。
    def repair_legacy_soft_proxy_identity!(entity, library_item, model = Sketchup.active_model, bump_registry: true)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      return false unless library_item.is_a?(Hash) && File.file?(library_item['path'].to_s)
      definition = entity.definition
      model_id = library_item['id'].to_s
      source_path = FastPath.expand(library_item['path'].to_s)
      model_name = library_item['name'].to_s
      model_name = File.basename(source_path, File.extname(source_path)) if model_name.empty?

      # 实例身份。
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'model_id', model_id)
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'source_path', source_path)
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'model_name', model_name)
      soft_set_attribute_if_changed(entity, SOFT_MODEL_DICT, 'representation', 'proxy') if soft_legacy_proxy_definition?(definition)
      begin
        entity.name = model_name if entity.respond_to?(:name=) && entity.name.to_s.empty?
      rescue StandardError
        nil
      end
      layer = soft_furniture_layer(model)
      entity.layer = layer if layer && entity.respond_to?(:layer=) rescue nil

      # 定义身份。不能调用 stamp_soft_library_definition!，因为该方法在“身份变化”时
      # 会清空 bounds cache；旧白盒的 bounds 正是后续轴语义迁移的重要证据，必须保留。
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_id', model_id)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'source_path', source_path)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_name', model_name)
      soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'managed_tree', true)
      if soft_legacy_proxy_definition?(definition)
        soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'representation', 'proxy')
        soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'fallback_proxy_for', model_id)
        signature = definition.get_attribute(SOFT_MODEL_DICT, 'proxy_full_bounds_signature', '').to_s
        soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'fallback_proxy_key', "#{model_id}|#{signature}") unless signature.empty?
      end
      bump_soft_instance_registry_revision(model) if bump_registry && !soft_representation_switching?(model)
      true
    rescue StandardError => e
      log_exception('回写历史白盒稳定身份失败', e)
      false
    end

    def soft_full_switch_failure_reason(instance, model = Sketchup.active_model)
      return '实例已经失效' unless instance && instance.valid?
      stored = instance.get_attribute(SOFT_MODEL_DICT, 'last_full_switch_error', '').to_s rescue ''
      return stored unless stored.empty?
      info = soft_instance_metadata(instance)
      item = full_soft_library_item_for(info, model)
      return '真模型源文件未找到或历史代理身份无法唯一确认' unless item
      return '真模型源文件不存在' unless File.file?(item['path'].to_s)
      '真模型载入失败或旧代理轴关系无法安全确认'
    rescue StandardError
      '真模型源文件未找到或载入失败'
    end

    def mark_soft_full_switch_failure(instances, reason)
      Array(instances).each do |instance|
        next unless instance && instance.valid?
        soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'last_full_switch_error', reason.to_s)
      end
      false
    rescue StandardError
      false
    end

    def clear_soft_full_switch_failure(instance)
      instance.delete_attribute(SOFT_MODEL_DICT, 'last_full_switch_error') if instance && instance.valid?
      true
    rescue StandardError
      false
    end

    def soft_full_switch_failure_rows(instances, model = Sketchup.active_model)
      grouped = {}
      Array(instances).each do |instance|
        next unless instance && instance.valid?
        info = soft_instance_metadata(instance)
        name = info['model_name'].to_s
        name = soft_identity_display_name(instance.definition.name.to_s) if name.empty? && instance.respond_to?(:definition)
        name = '未命名家具' if name.empty?
        reason = soft_full_switch_failure_reason(instance, model)
        key = [name, reason]
        grouped[key] ||= { name: name, reason: reason, count: 0, instances: [] }
        grouped[key][:count] += 1
        grouped[key][:instances] << instance
      end
      grouped.values.sort_by { |row| [row[:name].to_s.downcase, row[:reason].to_s] }
    rescue StandardError
      []
    end

    def show_soft_full_switch_failure_report(instances, model = Sketchup.active_model, title: '真模型部分切换完成')
      rows = soft_full_switch_failure_rows(instances, model)
      return false if rows.empty?
      lines = rows.first(40).each_with_index.map do |row, index|
        suffix = row[:count].to_i > 1 ? " ×#{row[:count]}" : ''
        "#{index + 1}. #{row[:name]}#{suffix} — #{row[:reason]}"
      end
      lines << "……另有 #{rows.length - 40} 款，完整记录已写入 LinkHub 日志。" if rows.length > 40
      message = "可正常找到源文件的家具已经切换为真模型。\n以下 #{rows.sum { |row| row[:count].to_i }} 个实例保持原代理，没有被删除或改坏：\n\n#{lines.join("\n")}"
      log("真模型部分切换失败清单：#{rows.map { |row| "#{row[:name]}×#{row[:count]}=#{row[:reason]}" }.join(' | ')}")
      UI.messagebox("#{title}\n\n#{message}", MB_OK) if defined?(UI) && UI.respond_to?(:messagebox)
      true
    rescue StandardError => e
      log_exception('显示真模型失败清单失败', e)
      false
    end

    def apply_space_soft_full_models!(entity, model = Sketchup.active_model, instances: nil)
      started = monotonic_time
      definition_cache = {}
      swaps = []
      changed = 0
      instances ||= soft_instances_for_space(entity, model)
      instances = Array(instances).select { |instance| instance && instance.valid? }
      resident_space_id = soft_resident_space_id(entity, model)
      groups = {}
      Array(instances).each do |instance|
        next unless instance && instance.valid?
        info = soft_instance_metadata(instance)
        key = [
          instance.definition.object_id,
          info['model_id'].to_s,
          normalize_soft_library_key(info['source_path']),
          info['model_name'].to_s,
          info['legacy_proxy_marker'].to_s
        ]
        group = (groups[key] ||= { definition: instance.definition, info: info, instances: [] })
        group[:instances] << instance
      end
      furniture_layer = soft_furniture_layer(model)

      groups.each_value do |group|
        current_definition = group[:definition]
        info = group[:info]
        group_instances = Array(group[:instances]).select { |instance| instance && instance.valid? }
        next if group_instances.empty?

        # 代→真之前先记住每个实例当前实际正在显示的六视图代理。
        # 这是回切代理时最可靠、也最快的来源；不依赖 NAS、JSON 映射或重新加载 SKP。
        group_instances.each { |instance| remember_soft_session_visual_proxy!(instance, model) }

        begin
          if soft_definition_planar_reference?(current_definition)
            group_instances.each do |instance|
              current_representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
              next if current_representation == 'full' && soft_instance_representation_ready?(instance, 'full')
              swaps << {
                entity: instance,
                definition: instance.definition,
                transformation: instance.transformation,
                locked: (instance.respond_to?(:locked?) ? instance.locked? : false),
                representation: current_representation,
                proxy_source_path: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s,
                proxy_passthrough: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_passthrough', nil),
                planar_reference: instance.get_attribute(SOFT_MODEL_DICT, 'planar_reference', nil)
              }
              was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
              instance.locked = false if was_locked && instance.respond_to?(:locked=)
              soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'full')
              soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'planar_reference', true)
              instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
              instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_passthrough') rescue nil
              clear_soft_full_switch_failure(instance)
              instance.locked = true if was_locked && instance.respond_to?(:locked=)
              changed += 1
            end
            next
          end

          # 先走纯内存 resident 快路径。再次查看同一空间、或另一个空间复用同款家具时，
          # 不再为了“确认源文件还在”访问 NAS；模型库显式刷新/入库更新会让对应缓存失效。
          resident = resident_soft_full_match(info, model)
          library_item = resident && resident[:library_item]
          full_definition = resident && resident[:definition]
          resident_hit = !!(full_definition && full_definition.valid?)

          unless resident_hit
            library_item = full_soft_library_item_for(info, model)
            unless library_item && !library_item['path'].to_s.empty?
              reason = soft_legacy_proxy_entity?(group_instances.first) ?
                '历史白盒仍在，但无法从 model_id / 旧路径 / 名称指纹 / 尺寸唯一找回真模型' :
                '真模型源文件未找到'
              mark_soft_full_switch_failure(group_instances, reason)
              next
            end
          end

          # 一旦历史白盒已经高置信度找回当前模型库条目，立即补回稳定 model_id/path。
          # resident 命中也可以安全补写，因为它已经是本会话同一稳定身份的真模型。
          if soft_legacy_proxy_definition?(current_definition)
            group_instances.each do |instance|
              repair_legacy_soft_proxy_identity!(instance, library_item, model, bump_registry: false)
            end
          end

          source = library_item['path'].to_s
          source_key = source.empty? ? '' : normalize_soft_library_key(source)
          cache_key = if soft_stable_model_id?(library_item['id'].to_s)
                        "id:#{library_item['id']}|path:#{source_key}"
                      else
                        source_key
                      end
          full_definition ||= definition_cache[cache_key]
          unless full_definition && full_definition.valid?
            load_started = monotonic_time
            full_definition = load_soft_library_definition(library_item, model)
            unless full_definition && full_definition.valid?
              mark_soft_full_switch_failure(group_instances, '真模型源文件存在，但 SketchUp 载入失败')
              next
            end
            load_elapsed = elapsed_ms(load_started)
            log("真模型首次载入：#{info['model_name']} / #{load_elapsed}ms / #{File.basename(source)}") if load_elapsed >= 80.0
            # 交互式真模切换只需让 loaded_definition_cache 持有顶层 Definition；
            # 不再递归收集整棵 Definition tree。
            definition_cache[cache_key] = full_definition
          else
            definition_cache[cache_key] ||= full_definition
          end
          exact_pair = soft_exact_representation_pair?(current_definition, full_definition, model)
          native_visual_swap = !exact_pair && soft_native_full_swap_from_visual_proxy?(current_definition, library_item)
          stamp_soft_library_definition!(full_definition, library_item) unless resident_hit
          touch_soft_resident_full_definition!(
            full_definition,
            model,
            space_id: resident_space_id,
            library_item: library_item
          )

          relation = nil
          unless exact_pair || native_visual_swap
            relation = soft_fallback_proxy_axis_relation(current_definition, full_definition)
            if relation[:kind] == :ambiguous
              mark_soft_full_switch_failure(group_instances, '旧白盒与当前真模型三轴关系不明确；为避免压扁/放倒已保持代理')
              next
            end
          end

          group_swap_start = swaps.length
          group_changed = 0
          begin
            group_instances.each do |instance|
              next unless instance && instance.valid?
              current_representation = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
              current_source = instance.definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s rescue ''
              if current_representation == 'full' && same_file_path?(current_source, source) && instance.definition == full_definition
                clear_soft_full_switch_failure(instance)
                next
              end
              swaps << {
                entity: instance,
                definition: instance.definition,
                transformation: instance.transformation,
                locked: (instance.respond_to?(:locked?) ? instance.locked? : false),
                representation: current_representation,
                proxy_source_path: instance.get_attribute(SOFT_MODEL_DICT, 'proxy_source_path', '').to_s
              }
              was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
              instance.locked = false if was_locked && instance.respond_to?(:locked=)
              if exact_pair || native_visual_swap
                replace_instance_definition_preserving_exact_transform!(instance, full_definition, '代理切换为真模型')
              else
                case relation[:kind]
                when :legacy
                  replace_legacy_fallback_proxy_with_canonical_full!(instance, full_definition, relation)
                else
                  replace_instance_definition_preserving_box!(instance, full_definition)
                end
              end
              stamp_soft_library_instance!(
                instance, library_item, model,
                stamp_definition: false, layer: furniture_layer, bump_registry: false
              )
              soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'full')
              instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
              clear_soft_full_switch_failure(instance)
              instance.locked = true if was_locked && instance.respond_to?(:locked=)
              group_changed += 1
            end
            if native_visual_swap && group_changed.positive?
              log("过期六面代理切回真模型：#{info['model_name']} / 保留原生实例矩阵，未按旧外包盒缩放或补位")
            end
            changed += group_changed
          rescue StandardError => e
            group_swaps = swaps.slice(group_swap_start, swaps.length - group_swap_start) || []
            restore_space_soft_proxies!(group_swaps)
            swaps.slice!(group_swap_start, swaps.length - group_swap_start) if swaps.length > group_swap_start
            mark_soft_full_switch_failure(group_instances, "真模型替换失败：#{e.message}")
            log_exception("单款家具切换真模型失败，已只回滚该款：#{info['model_name']}", e)
            next
          end
        rescue StandardError => e
          mark_soft_full_switch_failure(group_instances, "真模型处理失败：#{e.message}")
          log_exception("单款家具切换真模型异常，已跳过该款：#{info['model_name']}", e)
          next
        end
      end

      bump_soft_instance_registry_revision(model) if changed.positive?
      failures = instances.reject { |instance| soft_instance_representation_ready?(instance, 'full') }
      log_slow_operation(
        '家具切换真模型核心', started, 120.0,
        "#{instances.length} 实例 / #{groups.length} 款 / #{definition_cache.length} 个源文件 / 成功 #{instances.length - failures.length} / 保持代理 #{failures.length}"
      )
      changed
    rescue StandardError
      # 只有方法级不可恢复异常才回滚本次已经发生的全部交换；普通“某款源文件丢失”
      # 已在上面的组级逻辑中隔离，不再拖累其它正常家具。
      restore_space_soft_proxies!(swaps)
      raise
    end

    def apply_space_soft_representation!(entity, representation, model = Sketchup.active_model, purge: false, instances: nil)
      desired = representation.to_s == 'full' ? 'full' : 'proxy'
      instances ||= soft_instances_for_space(entity, model)
      instances = Array(instances).select { |instance| instance && instance.valid? }
      changed = if desired == 'full'
                  apply_space_soft_full_models!(entity, model, instances: instances)
                else
                  # 新入库家具的六面代理可能仍在排队。先切换所有已有代理的家具，
                  # 待生成项保持真模型；不因一项未就绪而回滚整个空间的正常替换。
                  apply_space_soft_proxies!(entity, model, instances: instances, strict: false).length
                end
      unresolved = instances.reject { |instance| soft_instance_representation_ready?(instance, desired) }
      root_mode = unresolved.any? ? 'mixed' : desired
      soft_set_attribute_if_changed(entity, ENTITY_DICT, 'space_representation', root_mode) if entity && entity.valid?
      # 编辑中的内容仍可能继续变化，不能把旧签名当作永久可信；锁定引用会在
      # mark_space_model_entity! 时重新写入可信标记。mixed 明确表示“可用真模已切换，
      # 少数失联对象仍保持代理”，防止根标记把真实混合状态掩盖掉。
      if entity && entity.valid?
        entity.delete_attribute(ENTITY_DICT, 'space_representation_verified') rescue nil
        entity.delete_attribute(ENTITY_DICT, 'space_representation_verified_signature') rescue nil
      end
      purge_unused_soft_definitions!(model) if purge
      changed
    end

    def trusted_space_representation?(entity, representation)
      return false unless entity && entity.valid?
      desired = representation.to_s == 'full' ? 'full' : 'proxy'
      actual = entity.get_attribute(ENTITY_DICT, 'space_representation', '').to_s
      return false unless actual == desired
      return false unless entity.respond_to?(:locked?) && entity.locked?
      verified = entity.get_attribute(ENTITY_DICT, 'space_representation_verified', '').to_s
      verified_signature = entity.get_attribute(ENTITY_DICT, 'space_representation_verified_signature', '').to_s
      source_signature = entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s
      verified == desired && !source_signature.empty? && verified_signature == source_signature
    rescue StandardError
      false
    end

    def space_soft_representation_matches?(entity, representation)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      desired = representation.to_s == 'full' ? 'full' : 'proxy'
      actual = entity.get_attribute(ENTITY_DICT, 'space_representation', 'full').to_s
      return false unless actual == desired
      model = entity.respond_to?(:model) ? entity.model : Sketchup.active_model
      trusted = trusted_space_representation?(entity, desired)
      return true if trusted && !(desired == 'proxy' && space_proxy_visual_upgrade_needed?(entity, model))
      matched = soft_instances_for_space(entity, model).all? do |instance|
        soft_instance_representation_ready?(instance, desired) &&
          (desired != 'proxy' || soft_instance_uses_authoritative_visual_proxy?(instance))
      end
      if matched && entity.respond_to?(:locked?) && entity.locked?
        signature = entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s
        unless signature.empty?
          entity.set_attribute(ENTITY_DICT, 'space_representation_verified', desired)
          entity.set_attribute(ENTITY_DICT, 'space_representation_verified_signature', signature)
        end
      end
      matched
    rescue StandardError
      false
    end

    # v0.13.6.182：发布候选阶段某几件家具缺代理时，不再让整个空间发布失败或回滚。
    # 已切好的代理照常打包，缺代理的家具以真模型随包发布（混合包），并把“名称 ×数量”
    # 写进警告；同时在发布事务之外排队自动补生成，下次进入/切代理即自动换新。
    def note_space_publish_partial_proxy_layout!(entity, model = Sketchup.active_model, space_id: '')
      unresolved = take_soft_proxy_switch_unresolved!(model)
      return '' if unresolved.empty?
      summary = soft_proxy_switch_instance_summary(unresolved)
      warning = "以下家具暂无可用六面代理，本次以真模型随空间发布：#{summary}；已自动排队重新生成代理。"
      log("空间发布局部保留真模型：#{summary} / 发布继续（混合包）")
      scope_id = space_id.to_s
      if scope_id.empty? && entity && entity.valid?
        scope_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
      end
      instance_ids = unresolved.map { |instance| instance.object_id }
      runtime_start_timer(1.5, false, label: 'soft:publish_partial_proxy_repair', key: "soft:publish_partial_proxy_repair:#{model.object_id}", model: model) do
        begin
          targets = unresolved.select { |instance| instance && instance.valid? && instance_ids.include?(instance.object_id) }
          # 空间此刻若正以真模型显示（用户在编辑/预览），只重建权威代理文件，不把这几件
          # 单独切成代理；空间处于代理模式时才自动切回。最后的用户意图优先。
          space_mode = entity && entity.valid? ? entity.get_attribute(ENTITY_DICT, 'space_representation', 'full').to_s : 'full'
          schedule_soft_lost_proxy_auto_repair!(targets, model, scope_space_id: scope_id, reason: '发布后补齐缺失代理', notify: true, replace: space_mode != 'full') unless targets.empty?
        rescue StandardError => e
          log_exception('发布后排队补齐缺失代理失败', e)
        end
      end
      warning
    rescue StandardError => e
      log_exception('记录发布局部代理缺失失败', e)
      ''
    end

    def proxy_layout_candidate_error?(error)
      text = error.message.to_s
      text.include?('提交候选模型为空') || text.include?('未能写出提交候选模型') ||
        text.include?('未能写出空间模型') || text.include?('缺少可用代理或外包盒')
    rescue StandardError
      false
    end

    # v0.13.6.27：现有空间发布的第一阶段只生成“本机候选”。
    # 所有 proxy/full 临时替换、wrapper、make_unique 都由外层 candidate operation
    # 保护；候选写出后外层会 abort_operation，使这些临时 Definition 不进入 Undo。
    def prepare_single_space_publish_candidate!(entity, target, key, link, package_revision: '', space_id: '', defer_content_signature: false)
      swaps = nil
      wrapper = nil
      proxy_layout = true
      proxy_was_ready = false
      warning = ''
      begin
        proxy_stage_started = monotonic_time
        proxy_was_ready = space_soft_representation_matches?(entity, 'proxy')
        unless proxy_was_ready
          swaps = apply_space_soft_proxies!(entity, Sketchup.active_model)
          warning = note_space_publish_partial_proxy_layout!(entity, Sketchup.active_model, space_id: space_id)
        end
        proxy_stage_ms = elapsed_ms(proxy_stage_started)
        log("空间发布候选代理准备：#{proxy_was_ready ? '已是代理，跳过替换' : "替换#{Array(swaps).length}个实例"} / #{proxy_stage_ms}ms")

        wrapper_stage_started = monotonic_time
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: true)
        wrapper, = build_space_publish_wrapper!(
          entity, Sketchup.active_model,
          representation: (warning.empty? ? 'proxy' : 'mixed'),
          package_revision: package_revision,
          space_id: space_id
        )
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id)
        log("空间发布候选包建立：#{elapsed_ms(wrapper_stage_started)}ms")
        prepared = serialize_publish_definition_candidate!(wrapper, target, key, defer_content_signature: defer_content_signature)
      rescue StandardError => proxy_error
        raise unless proxy_layout_candidate_error?(proxy_error)
        raise if proxy_was_ready

        log_exception('家具代理布局候选写出失败，候选阶段回退真家具空间文件', proxy_error)
        restore_space_soft_proxies!(swaps) if swaps
        swaps = nil
        proxy_layout = false
        warning = '家具代理布局写出失败，本次已回退发布真模型；代模式仍可在载入后替换家具。'
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: false)
        wrapper, = build_space_publish_wrapper!(
          entity, Sketchup.active_model,
          representation: 'full',
          package_revision: package_revision,
          space_id: space_id
        )
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id)
        prepared = serialize_publish_definition_candidate!(wrapper, target, key, defer_content_signature: defer_content_signature)
      end
      {
        prepared: prepared,
        proxy_layout: proxy_layout,
        warning: warning
      }
    end

    # 优先将空间中的受管家具替换为家具代理后写入唯一的空间 SKP。
    # 若某个特殊代理定义导致 SketchUp 无法生成候选文件，则安全回退为真家具空间文件，
    # 发布仍然完成；代模式载入后会立刻把家具替换为代理并卸载真家具定义。
    def publish_single_space_file!(entity, target, key, link, expected_signature: '', baseline_path: '', baseline_signature: '', force_overwrite: false, package_revision: '', space_id: '')
      swaps = nil
      wrapper = nil
      proxy_layout = true
      proxy_was_ready = false
      warning = ''
      begin
        # 默认代模式下家具已经是代理，不再为发布重复读取模型库、替换定义
        # 再恢复一次；只有当前空间确实含真模型时才做临时转换。
        proxy_stage_started = monotonic_time
        proxy_was_ready = space_soft_representation_matches?(entity, 'proxy')
        unless proxy_was_ready
          swaps = apply_space_soft_proxies!(entity, Sketchup.active_model)
          warning = note_space_publish_partial_proxy_layout!(entity, Sketchup.active_model, space_id: space_id)
        end
        proxy_stage_ms = elapsed_ms(proxy_stage_started)
        log("空间发布代理准备：#{proxy_was_ready ? '已是代理，跳过替换' : "替换#{Array(swaps).length}个实例"} / #{proxy_stage_ms}ms")
        wrapper_stage_started = monotonic_time
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: true)
        wrapper, = build_space_publish_wrapper!(entity, Sketchup.active_model, representation: (warning.empty? ? 'proxy' : 'mixed'), package_revision: package_revision, space_id: space_id)
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id)
        log("空间发布包建立：#{elapsed_ms(wrapper_stage_started)}ms")
        atomic_stage_started = monotonic_time
        result = atomic_publish_definition(
          wrapper,
          target,
          key,
          link,
          expected_signature: expected_signature,
          baseline_path: baseline_path,
          baseline_signature: baseline_signature,
          force_overwrite: force_overwrite
        )
        log("空间发布候选序列化+共享写入：#{elapsed_ms(atomic_stage_started)}ms")
      rescue StandardError => proxy_error
        raise unless proxy_layout_candidate_error?(proxy_error)
        # 当前空间本来就是代理时没有可恢复的真模型，不能把第二次同样的
        # 代理写出伪装成“已回退真模型”。直接报告原始错误更安全。
        raise if proxy_was_ready
        log_exception('家具代理布局候选写出失败，回退发布真家具空间文件', proxy_error)
        defer_publish_definition_cleanup!(wrapper, Sketchup.active_model) if wrapper
        wrapper = nil
        restore_space_soft_proxies!(swaps) if swaps
        swaps = nil
        proxy_layout = false
        warning = '家具代理布局写出失败，本次已回退发布真模型；代模式仍可在载入后替换家具。'
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: false)
        wrapper, = build_space_publish_wrapper!(entity, Sketchup.active_model, representation: 'full', package_revision: package_revision, space_id: space_id)
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id)
        result = atomic_publish_definition(
          wrapper,
          target,
          key,
          link,
          expected_signature: expected_signature,
          baseline_path: baseline_path,
          baseline_signature: baseline_signature,
          force_overwrite: force_overwrite
        )
      ensure
        publish_breadcrumb!('space_restore_begin', wrapper_id: (wrapper.object_id rescue 0), swap_count: Array(swaps).length)
        defer_publish_definition_cleanup!(wrapper, Sketchup.active_model) if wrapper
        restore_space_soft_proxies!(swaps) if swaps
        publish_breadcrumb!('space_restore_returned')
      end
      { result: result, proxy_layout: proxy_layout, warning: warning }
    end

    def space_asset_for(item, state, model = Sketchup.active_model, representation: nil)
      desired = representation.to_s
      desired = state['space_display_mode'].to_s if desired.empty?
      desired = 'full' unless %w[proxy full].include?(desired)
      path = auto_relocate(item['model_path'].to_s, model)
      { representation: desired, path: path, stored: item['model_path'].to_s }
    end


    def initial_space_publish_pending?(item)
      item.is_a?(Hash) && item['initial_publish_pending'] == true
    rescue StandardError
      false
    end

    # 首次新增空间不需要为了撤回临时 wrapper 而 abort 整个“新增空间”事务。
    # 这里与普通空间发布共用同一套 proxy/full 包装与本机候选格式，但候选写出后
    # 仅恢复临时家具替换、延迟清理 wrapper 定义；真正新增的空间根实例继续 commit。
    # 这样首次发布前台只承担一次 Definition.save_as，而 NAS/SMB 全部进入同一个后台 worker。
    def prepare_initial_space_publish_candidate!(entity, target, key, link, package_revision: '', space_id: '')
      swaps = nil
      wrapper = nil
      proxy_layout = true
      proxy_was_ready = false
      warning = ''
      begin
        proxy_was_ready = space_soft_representation_matches?(entity, 'proxy')
        unless proxy_was_ready
          swaps = apply_space_soft_proxies!(entity, Sketchup.active_model)
          warning = note_space_publish_partial_proxy_layout!(entity, Sketchup.active_model, space_id: space_id)
        end
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: true, initial_publish: true)
        wrapper, = build_space_publish_wrapper!(
          entity, Sketchup.active_model,
          representation: (warning.empty? ? 'proxy' : 'mixed'), package_revision: package_revision, space_id: space_id
        )
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id, initial_publish: true)
        prepared = serialize_publish_definition_candidate!(wrapper, target, key, defer_content_signature: true)
      rescue StandardError => proxy_error
        raise unless proxy_layout_candidate_error?(proxy_error)
        raise if proxy_was_ready
        log_exception('首次空间发布代理布局候选写出失败，回退真家具候选', proxy_error)
        defer_publish_definition_cleanup!(wrapper, Sketchup.active_model) if wrapper
        wrapper = nil
        restore_space_soft_proxies!(swaps) if swaps
        swaps = nil
        proxy_layout = false
        warning = '家具代理布局写出失败，本次首次发布已回退真模型候选。'
        publish_breadcrumb!('space_wrapper_build_begin', proxy_layout: false, initial_publish: true)
        wrapper, = build_space_publish_wrapper!(
          entity, Sketchup.active_model,
          representation: 'full', package_revision: package_revision, space_id: space_id
        )
        publish_breadcrumb!('space_wrapper_built', definition_id: wrapper.object_id, initial_publish: true)
        prepared = serialize_publish_definition_candidate!(wrapper, target, key, defer_content_signature: true)
      ensure
        # 新增空间事务会 commit，不能依赖 abort 自动撤回这些临时对象。
        restore_space_soft_proxies!(swaps) if swaps
        defer_publish_definition_cleanup!(wrapper, Sketchup.active_model) if wrapper
      end
      { prepared: prepared, proxy_layout: proxy_layout, warning: warning }
    end

    def add_space_model_from_selection
      publish_guard_acquired = false
      publish_error = nil
      operation_open = false
      enqueued = false
      reservation_acquired = false
      model = Sketchup.active_model
      raise '请先退出组件编辑层级，在模型根层级选择要发布的组件或群组。' unless model.active_path.nil?
      selected = selected_space_source_entities(model)
      raise '请先选择一个或多个普通组件/群组，再点击“新增空间模型”。' if selected.empty?
      state = ensure_space_models_ready!(model)
      project_dir = ensure_collab_project_ready!(state, model, interactive: true)
      return false if project_dir.to_s.empty?

      host_role = host_discipline_for(state)
      default_collection = space_workspace_role?(host_role) ? host_role : SPACE_COLLECTION_KEY
      prompt = "空间名称\n支持：B1-二层小客房-硬装 / 2F-客厅-软装 / A1-主楼-建筑\n已选择 #{selected.length} 个对象；末尾专业后缀会自动归类。"
      response = UI.inputbox([prompt], [''], '新增模型空间')
      return false unless response
      parsed = parse_structured_space_name(response[0], default_collection: default_collection)
      name = parsed['name'].to_s
      raise '空间名称不能为空。' if name.empty?

      if parsed['target_role'].to_s == 'architecture'
        return add_architecture_model_from_selection(selected: selected, parsed_input: parsed, allow_cross_workspace: true)
      end

      collection_key = normalize_space_collection_key(parsed['collection_key'], default_collection)
      if Array(state['space_models']).any? { |row| space_record_collection_key(row) == collection_key && row['name'].to_s.casecmp(name).zero? }
        raise "#{space_collection_label(collection_key)}空间名称“#{name}”已经存在，请使用不同名称。"
      end

      number = next_space_number!(state)
      item = default_space_model(number, name)
      item['collection_key'] = collection_key
      item['group_id'] = ensure_named_space_group!(state, parsed['group_name']) unless parsed['group_name'].to_s.empty?
      assets_dir = space_models_assets_dir(state, model)
      FileUtils.mkdir_p(assets_dir)
      storage_name = "#{name}-#{space_collection_label(collection_key)}"
      target = File.join(assets_dir, "#{number}_#{safe_space_filename(storage_name)}.skp")
      stored = store_path(target, model)
      raise '首次发布目标已经存在。为避免覆盖其他成员刚创建的空间，请刷新后重新新增或改名。' if File.exist?(target)

      publish_guard_acquired = enter_publish_critical_section!(
        kind: 'new_space',
        subject: "新增#{space_collection_label(collection_key)}空间 #{number}:#{name} · 后台首次发布候选",
        target: target,
        model: model
      )
      # 在正式 SKP 尚不存在时先创建同路径协作占用，作为首次发布 reservation。
      # 同为 6.67+ 的另一客户端若恰好创建相同目标，会在这里互斥；最终写入仍由 create-only 再兜底。
      acquire_space_lock!(item, target, state)
      reservation_acquired = true

      source_revision = new_publish_revision("space-#{item['id']}")
      job_id = "bgspace-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      label = "#{number}:#{name}"
      publish_breadcrumb!('new_space_operation_start_begin', selected_count: selected.length, background_queue: true)
      model.start_operation("新增#{space_collection_label(collection_key)}空间 #{label}", true)
      operation_open = true

      definition = model.definitions.add("LH_SPACE_#{number}_#{SecureRandom.hex(5)}")
      definition.set_attribute(ENTITY_DICT, 'linkhub_space_content_root_schema', 1)
      selected.each do |source_entity|
        copied = definition.entities.add_instance(source_entity.definition, absolute_transformation_for_selected_entity(source_entity, model))
        copy_instance_visual_properties!(source_entity, copied)
        # 这里刻意不 explode 用户自己创建的组件/群组。空间根是 LinkHub 的管理边界，
        # 用户原有分组是业务结构；新版只在发布/更新链路压平“明确带 LinkHub 标记”的
        # 空包裹层，避免为了减少层级误拆用户有意义的建模结构。
      end
      instance = model.entities.add_instance(definition, identity_transformation)

      stamp_shared_component_space_snapshot_baselines!(instance, model)
      candidate_outcome = prepare_initial_space_publish_candidate!(
        instance, target, "space_#{item['id']}", { 'name' => label },
        package_revision: source_revision, space_id: item['id']
      )
      prepared_candidate = candidate_outcome[:prepared]
      raise '首次发布候选未能生成。' unless prepared_candidate.is_a?(Hash) && File.file?(prepared_candidate[:path].to_s)

      apply_space_soft_representation!(instance, state['space_display_mode'], model)
      selected.each do |source_entity|
        source_entity.locked = false if source_entity.respond_to?(:locked=)
        source_entity.erase! if source_entity.valid?
      end

      # 正式共享 SKP 此刻还不存在；本地根实例先以“首次发布待完成”身份入模。
      # 后台成功收尾时会原位写回正式 signature/revision，不会重新下载/重建一次空间。
      local_candidate_signature = fast_file_signature(prepared_candidate[:path].to_s)
      mark_space_model_entity!(
        instance, item, stored, local_candidate_signature, model,
        representation: state['space_display_mode'], revision: source_revision,
        verified_package_revision: source_revision, verified_package_identity: 'local-initial-publish-pending'
      )
      instance.locked = true if instance.respond_to?(:locked=)
      instance.set_attribute(ENTITY_DICT, 'editing', false)

      if space_collection_hidden_for(state, collection_key)
        snapshot = space_collection_visibility_snapshot_for(state, collection_key)
        snapshot['entities'][space_collection_entity_visibility_key(instance)] = false
        set_space_collection_visibility_snapshot_for!(state, collection_key, snapshot)
        instance.hidden = true if instance.respond_to?(:hidden=)
      end

      item['model_path'] = stored
      item['last_signature'] = ''
      item['source_revision'] = source_revision
      item['proxy_path'] = ''
      item['proxy_signature'] = ''
      item['proxy_published_at'] = ''
      item['initial_publish_pending'] = true
      item['initial_publish_candidate'] = prepared_candidate[:path].to_s
      item['initial_publish_error'] = ''
      item['background_publish_state'] = 'queued'
      item['background_publish_job_id'] = job_id
      item['background_publish_candidate'] = prepared_candidate[:path].to_s
      item['background_publish_error'] = ''
      item['status'] = '首次发布已加入队列 · 本地空间已创建'
      state['space_models'] << item
      normalize_space_models_state!(state, model)
      save_state(state, model, write_manifest: false)
      model.selection.clear
      model.selection.add(instance)
      model.commit_operation
      operation_open = false

      component_publish_plan = shared_component_publish_plan_for_space_entity(instance, model)
      job = {
        job_id: job_id,
        space_id: item['id'].to_s,
        label: label,
        target: target.to_s,
        expected_signature: '',
        source_revision: source_revision.to_s,
        source_model_path: model.path.to_s,
        model_object_id: model.object_id,
        prepared: prepared_candidate,
        proxy_layout: !!candidate_outcome[:proxy_layout],
        warning: candidate_outcome[:warning].to_s,
        recovery_plan: nil,
        queued_from_display_mode: state['space_display_mode'].to_s,
        initial_publish: true,
        shared_component_publish_plan: component_publish_plan
      }
      enqueue_space_publish_job!(job, model)
      enqueued = true
      publish_breadcrumb!('background_initial_publish_queued', job_id: job_id, label: label, candidate: prepared_candidate[:path].to_s)
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      group_note = parsed['group_name'].to_s.empty? ? '' : " · 组 #{parsed['group_name']}"
      show_status("已新增#{space_collection_label(collection_key)} #{label}#{group_note}；首次发布已进入后台队列，现在可继续操作其它空间。", 'success')
      true
    rescue StandardError => e
      publish_error = e
      model.abort_operation rescue nil if operation_open
      if defined?(item) && item && !enqueued
        begin
          current_state = load_state(model)
          current_item = space_model_record(current_state, item['id'])
          if current_item
            current_item['initial_publish_pending'] = true
            current_item['initial_publish_error'] = "首次发布入队失败：#{e.message}"
            current_item['background_publish_state'] = ''
            current_item['background_publish_job_id'] = ''
            current_item['status'] = '首次发布待重试 · 本地空间已保留'
            release_space_lock!(current_item, target, clear_state: true, model: model, state: current_state) rescue nil
            save_state(current_state, model, write_manifest: false)
          elsif reservation_acquired
            release_space_lock!(item, target, clear_state: true, model: model, state: state) rescue nil
          end
        rescue StandardError => recovery_error
          log_exception('首次空间发布入队失败后的本地恢复失败', recovery_error)
        end
      elsif reservation_acquired
        release_space_lock!(item, target, clear_state: true, model: model, state: state) rescue nil
      end
      raise
    ensure
      leave_publish_critical_section!(success: !!enqueued, error: publish_error, model: model) if publish_guard_acquired
    end

    # 首次发布失败/中断后，根空间仍安全保留在当前工作 SU。点击“重试”优先直接复用
    # 已经落盘的候选；只有候选丢失时才在主线程重新序列化一次，NAS 阶段仍全部后台执行。
    def retry_initial_space_publish!(space_id, model = Sketchup.active_model)
      state = load_state(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      raise '该空间不是待完成的首次发布。' unless initial_space_publish_pending?(item)
      raise '该空间已经在后台发布队列中。' if background_publish_active_state?(item)
      entity = space_model_entity(item['id'], model)
      raise '首次发布本地空间根实例已不存在，无法重试。' unless entity && entity.valid?
      target = resolve_path(item['model_path'].to_s, model)
      raise '首次发布目标路径无效。' if target.to_s.empty?
      if File.file?(target)
        raise '协同目录已经出现同名空间 SKP。为避免覆盖其他成员版本，本机首次发布不能继续；请刷新核对后改名或删除本机待发布空间。'
      end

      acquire_space_lock!(item, target, state)
      source_revision = item['source_revision'].to_s
      source_revision = new_publish_revision("space-#{item['id']}") if source_revision.empty?
      candidate_path = item['initial_publish_candidate'].to_s
      prepared = nil
      proxy_layout = true
      warning = ''
      if !candidate_path.empty? && File.file?(candidate_path) && File.size(candidate_path).positive?
        prepared = { path: candidate_path, size: File.size(candidate_path), content_signature: '', token: "retry-#{SecureRandom.hex(4)}" }
      else
        operation_open = false
        begin
          model.start_operation("重建首次发布候选 #{item['number']}:#{item['name']}", true)
          operation_open = true
          entity.locked = false if entity.respond_to?(:locked=)
          stamp_shared_component_space_snapshot_baselines!(entity, model)
          outcome = prepare_initial_space_publish_candidate!(
            entity, target, "space_#{item['id']}", { 'name' => "#{item['number']}:#{item['name']}" },
            package_revision: source_revision, space_id: item['id']
          )
          prepared = outcome[:prepared]
          proxy_layout = !!outcome[:proxy_layout]
          warning = outcome[:warning].to_s
          entity.locked = true if entity.respond_to?(:locked=)
          model.commit_operation
          operation_open = false
          candidate_path = prepared[:path].to_s
        rescue StandardError
          model.abort_operation rescue nil if operation_open
          raise
        end
      end

      job_id = "bgspace-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      item['initial_publish_pending'] = true
      item['initial_publish_candidate'] = candidate_path
      item['initial_publish_error'] = ''
      item['background_publish_state'] = 'queued'
      item['background_publish_job_id'] = job_id
      item['background_publish_candidate'] = candidate_path
      item['background_publish_error'] = ''
      item['status'] = '首次发布重试已加入队列'
      save_state(state, model, write_manifest: false)
      component_publish_plan = shared_component_publish_plan_for_space_entity(entity, model)
      enqueue_space_publish_job!({
        job_id: job_id, space_id: item['id'].to_s,
        label: "#{item['number']}:#{item['name']}", target: target.to_s,
        expected_signature: '', source_revision: source_revision,
        source_model_path: model.path.to_s, model_object_id: model.object_id,
        prepared: prepared, proxy_layout: proxy_layout, warning: warning,
        recovery_plan: nil, queued_from_display_mode: state['space_display_mode'].to_s,
        initial_publish: true, shared_component_publish_plan: component_publish_plan
      }, model)
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      show_status("#{item['number']}:#{item['name']} 首次发布已重新加入后台队列。", 'success')
      true
    rescue StandardError => e
      begin
        state ||= load_state(model)
        item ||= space_model_record(state, space_id)
        if item
          item['background_publish_state'] = ''
          item['background_publish_job_id'] = ''
          item['initial_publish_pending'] = true
          item['initial_publish_error'] = e.message.to_s
          item['status'] = '首次发布待重试 · 本地空间已保留'
          release_space_lock!(item, (resolve_path(item['model_path'].to_s, model) rescue ''), clear_state: true, model: model, state: state) rescue nil
          save_state(state, model, write_manifest: false)
        end
      rescue StandardError
        nil
      end
      raise
    end

    def space_lock_record_stale?(record, lock_path = nil)
      return true unless record.is_a?(Hash)
      return false if lock_record_from_current_process?(record)
      # Windows 可能很快复用刚关闭 SketchUp 的 PID。旧版只看“同机 PID 仍存在”，
      # 会把新进程误判成旧编辑进程，从而继续显示修改中。相同 PID 但运行会话不同
      # 时，锁一定来自已经结束的旧 SketchUp，会话可立即判定为过期。
      return true if lock_record_from_replaced_current_session?(record)
      host = record['host'].to_s
      pid = record['pid'].to_i
      heartbeat = parse_time_value(record['heartbeat_at']) || parse_time_value(record['started_at'])
      if !host.empty? && host.casecmp(current_host_name).zero?
        return false if local_process_alive?(pid) && (!heartbeat || (Time.now - heartbeat) <= SPACE_LOCK_STALE_SECONDS)
        return true unless local_process_alive?(pid)
      end
      return (Time.now - heartbeat) > SPACE_LOCK_STALE_SECONDS if heartbeat
      return (Time.now - File.mtime(lock_path)) > SPACE_LOCK_STALE_SECONDS if lock_path && File.file?(lock_path)
      true
    rescue StandardError
      false
    end

    def schedule_stale_lock_cleanup!(lock_path, source_path, record, label = 'stale_lock')
      return false unless record.is_a?(Hash) && !lock_path.to_s.empty?
      token = record['token'].to_s
      return false if token.empty?
      @stale_lock_cleanup_tokens ||= {}
      cleanup_key = FastPath.expand(lock_path.to_s) rescue lock_path.to_s
      return true if @stale_lock_cleanup_tokens[cleanup_key] == token
      @stale_lock_cleanup_tokens[cleanup_key] = token
      Thread.new do
        begin
          current = read_lock_record(lock_path)
          next unless current && current['token'].to_s == token
          stale = if current['kind'].to_s == 'sulink_space_edit_lock'
                    space_lock_record_stale?(current, lock_path)
                  else
                    lock_record_stale?(current, lock_path)
                  end
          next unless stale
          archived = archive_lock_file(lock_path, source_path, label)
          File.delete(lock_path) if !archived && File.file?(lock_path)
          log("已后台回收过期协作锁：#{File.basename(source_path.to_s)}")
        rescue StandardError => e
          log_exception('后台回收过期协作锁失败', e)
        ensure
          @stale_lock_cleanup_tokens.delete(cleanup_key)
          # 文件回收在线程中完成；界面由现有协作状态轮询在下一次轻量刷新时更新，
          # 不从后台线程调用任何 SketchUp/UI API。
        end
      end
      true
    rescue StandardError => e
      log_exception('安排过期协作锁回收失败', e)
      false
    end

    def space_lock_info(item, model = Sketchup.active_model, source_path: nil, state: nil)
      # 联动副本共享来源 SKP，但不拥有独立编辑会话。读取来源锁并把 token 回填到副本，
      # 会让副本心跳/释放时误操作来源空间的真实锁，进而把来源卡片变成“修改锁失效”。
      if linked_space_record?(item)
        return { 'exists' => false, 'stale' => false, 'owned' => false, 'same_user' => false,
                 'same_user_recoverable' => false, 'path' => '', 'actor_role' => '', 'linked' => true }
      end
      source = source_path.to_s.empty? ? auto_relocate(item['model_path'].to_s, model) : source_path.to_s
      path = source.to_s.empty? ? '' : edit_lock_path_for(source)
      return { 'exists' => false, 'stale' => false, 'owned' => false, 'same_user' => false, 'same_user_recoverable' => false, 'path' => path, 'actor_role' => '' } if path.empty?
      record = read_lock_record(path)
      return { 'exists' => false, 'stale' => false, 'owned' => false, 'same_user' => false, 'same_user_recoverable' => false, 'path' => path, 'actor_role' => '' } unless record
      state ||= load_state(model)
      actor_role = lock_record_actor_role(record, item['edit_actor_role'])
      subject_role = normalize_workspace_role(item['collection_key'])
      if actor_role.empty? && lock_record_from_current_process?(record)
        # v0.9.54 及更早的锁没有记录实际工作区。为避免升级后的第一次读取
        # 又把旧锁绑定到“刚好切换到的景观/建筑工作区”，空间旧锁一律按
        # 空间所属的室内专业保守迁移。新创建的跨专业锁会明确写入 actor_role。
        actor_role = item['collection_key'].to_s.empty? ? SPACE_COLLECTION_KEY : item['collection_key'].to_s
        record['actor_role'] = actor_role
        record['actor_role_name'] = workspace_role_label(actor_role)
        write_lock_record(path, record, expected_token: record['token'])
      elsif lock_record_from_current_process?(record) && space_workspace_role?(subject_role) && actor_role != subject_role
        # v0.13.6.114 之前/热更新中的旧逻辑可能曾把软装锁随 UI 切换误重绑成硬装（反之亦然）。
        # 读取时按空间自己的 collection_key 自愈，避免错误角色继续污染后续发布与心跳。
        previous_role = actor_role
        actor_role = subject_role
        record['previous_actor_role'] = previous_role unless previous_role.empty? || previous_role == actor_role
        record['actor_role'] = actor_role
        record['actor_role_name'] = workspace_role_label(actor_role)
        record['workspace_role_repaired_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        write_lock_record(path, record, expected_token: record['token'])
        log("已修复当前会话空间锁的专业身份：#{workspace_role_label(previous_role)} -> #{workspace_role_label(actor_role)} / #{item['number']}:#{item['name']}")
      end
      stale = space_lock_record_stale?(record, path)
      schedule_stale_lock_cleanup!(path, source, record, 'stale_space_auto') if stale
      token = item['edit_lock_token'].to_s
      exact_owned = lock_record_owned_by_current_process?(record, token)
      process_owned = lock_record_from_current_process?(record)
      active_owned = lock_record_owned_by_active_workspace?(record, token, actor_role, model, state)
      # 硬装/软装空间的协作占用属于“当前 SketchUp 会话 + 具体空间”，不是属于
      # 当前 UI 正停在哪个工作区。切工作区只是导航，不能把同进程真实占用误判失效。
      session_owned = space_workspace_role?(subject_role) ? (exact_owned || process_owned) : active_owned
      if session_owned && !exact_owned
        apply_space_lock_record_to_item!(item, record, actor_role: actor_role)
        log("已恢复当前 SketchUp 会话持有的#{workspace_role_label(actor_role)}空间锁：#{item['number']}:#{item['name']}")
      end
      {
        'exists' => true,
        'stale' => stale,
        'owned' => !!session_owned,
        'active_workspace_owned' => !!active_owned,
        'process_owned' => process_owned,
        'same_user' => lock_record_owned_by_current_user?(record),
        'same_user_recoverable' => same_user_lock_recoverable?(record),
        'path' => path,
        'token' => record['token'].to_s,
        'actor_role' => actor_role,
        'actor_role_name' => workspace_role_label(actor_role),
        'owner' => record['owner'].to_s,
        'host' => record['host'].to_s,
        'pid' => record['pid'].to_i,
        'started_at' => record['started_at'].to_s,
        'heartbeat_at' => record['heartbeat_at'].to_s
      }
    rescue StandardError
      { 'exists' => false, 'stale' => false, 'owned' => false, 'same_user' => false, 'same_user_recoverable' => false, 'path' => '', 'actor_role' => '' }
    end

    def apply_space_lock_record_to_item!(item, record, actor_role: '')
      return false unless item.is_a?(Hash) && record.is_a?(Hash)
      role = actor_role.to_s
      role = lock_record_actor_role(record, item['edit_actor_role']) if role.empty?
      item['edit_lock_token'] = record['token'].to_s
      item['edit_actor_role'] = role
      item['edit_lock_owner'] = record['owner'].to_s
      item['edit_lock_host'] = record['host'].to_s
      item['edit_lock_started_at'] = record['started_at'].to_s
      true
    rescue StandardError
      false
    end

    def clear_space_lock_state!(item)
      item['edit_lock_token'] = ''
      item['edit_actor_role'] = ''
      item['edit_lock_owner'] = ''
      item['edit_lock_host'] = ''
      item['edit_lock_started_at'] = ''
      # 眼睛状态是用户的持久偏好，释放协作锁、退出或发布都不能重置。
      item['publish_pending'] = false
      item['edit_safe_paused'] = false
      item['edit_safe_paused_at'] = ''
      item['edit_safe_pause_reason'] = ''
      item['publish_countdown_started_at'] = ''
      item['publish_countdown_until'] = 0.0
      true
    end

    def acquire_space_lock!(item, source_path, state)
      lock_path = edit_lock_path_for(source_path)
      existing = read_lock_record(lock_path)
      if File.file?(lock_path) && existing.nil?
        unless archive_lock_file(lock_path, source_path, 'corrupt_space')
          raise '发现损坏的空间协作锁且无法清理，请检查共享文件夹权限。'
        end
      end
      if existing
        if lock_record_from_current_process?(existing)
          actor_role = lock_record_actor_role(existing, item['edit_actor_role'])
          actor_role = item['collection_key'].to_s.empty? ? SPACE_COLLECTION_KEY : item['collection_key'].to_s if actor_role.empty?
          current_role = current_workspace_role(Sketchup.active_model, state)
          subject_role = normalize_workspace_role(item['collection_key'])
          actor_role = subject_role if space_workspace_role?(subject_role)
          if !actor_role.empty? && actor_role != current_role && !space_workspace_role?(subject_role)
            raise "#{item['number']}:#{item['name']} 正由当前 SketchUp 中的#{workspace_role_label(actor_role)}工作区修改。请切回该工作区发布或结束修改，不能由#{workspace_role_label(current_role)}工作区接管。"
          end
          existing['actor_role'] = actor_role unless actor_role.empty?
          existing['actor_role_name'] = workspace_role_label(actor_role) unless actor_role.empty?
          item['edit_lock_token'] = existing['token'].to_s
          item['edit_actor_role'] = actor_role
          item['edit_lock_owner'] = existing['owner'].to_s
          item['edit_lock_host'] = existing['host'].to_s
          item['edit_lock_started_at'] = existing['started_at'].to_s
          existing['heartbeat_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
          write_lock_record(lock_path, existing, expected_token: existing['token'])
          existing['lock_path'] = lock_path
          log("接回当前#{workspace_role_label(actor_role)}工作区遗留的空间锁：#{item['number']}:#{item['name']}")
          return existing
        elsif same_user_lock_recoverable?(existing)
          unless interrupt_same_user_lock_file!(lock_path, source_path, existing, 'same_user_space_takeover')
            raise "#{item['number']}:#{item['name']} 的本人遗留占用无法中断，请检查协同文件夹权限。"
          end
          # 旧锁已归档；继续创建当前进程的新空间锁。
        elsif space_lock_record_stale?(existing, lock_path)
          unless archive_lock_file(lock_path, source_path, 'stale_space')
            File.delete(lock_path) if File.file?(lock_path)
          end
        elsif lock_record_owned_by_current_process?(existing, item['edit_lock_token'])
          existing['lock_path'] = lock_path
          return existing
        else
          owner = existing['owner'].to_s.empty? ? '其他成员' : existing['owner'].to_s
          host = existing['host'].to_s
          started = existing['started_at'].to_s
          if !host.empty? && host.casecmp(current_host_name).zero?
            raise "#{item['number']}:#{item['name']} 正由同一台电脑上的另一个 SketchUp 进程修改（#{owner}，PID #{existing['pid']}，#{started}）。"
          end
          raise "#{item['number']}:#{item['name']} 正由 #{owner}@#{host} 修改（#{started}），请等待对方发布或放弃修改。"
        end
      end

      now = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      record = {
        'schema' => 2,
        'kind' => 'sulink_space_edit_lock',
        'discipline' => (item['collection_key'].to_s.empty? ? SPACE_COLLECTION_KEY : item['collection_key'].to_s),
        'plugin_version' => EXTENSION_VERSION,
        'token' => SecureRandom.hex(18),
        'space_id' => item['id'].to_s,
        'space_number' => item['number'].to_i,
        'space_name' => item['name'].to_s,
        'source_path' => source_path.to_s,
        'owner' => current_user_name,
        'host' => current_host_name,
        'pid' => Process.pid,
        'session_id' => current_runtime_session_id,
        'actor_role' => begin
          subject_role = normalize_workspace_role(item['collection_key'])
          space_workspace_role?(subject_role) ? subject_role : current_workspace_role(Sketchup.active_model, state)
        end,
        'actor_role_name' => begin
          subject_role = normalize_workspace_role(item['collection_key'])
          workspace_role_label(space_workspace_role?(subject_role) ? subject_role : current_workspace_role(Sketchup.active_model, state))
        end,
        'started_at' => now,
        'heartbeat_at' => now,
        'project_name' => state['project_name'].to_s,
        'coordination_model' => Sketchup.active_model.path.to_s
      }
      write_lock_record(lock_path, record, exclusive: true)
      apply_space_lock_record_to_item!(
        item, record,
        actor_role: lock_record_actor_role(record, current_workspace_role(Sketchup.active_model, state))
      )
      record['lock_path'] = lock_path
      record
    rescue Errno::EEXIST
      raise '该空间刚刚被其他成员占用，请刷新后重试。'
    rescue Errno::EACCES
      raise '没有权限创建空间协作锁，请检查协同文件夹写入权限。'
    end

    def force_takeover_same_user_space_lock!(item, source_path, state, model = Sketchup.active_model, allow_current_process: false)
      path = edit_lock_path_for(source_path)
      record = read_lock_record(path)
      return nil unless lock_record_owned_by_current_user?(record)
      if lock_record_from_current_process?(record)
        return nil unless allow_current_process
        previous_role = lock_record_actor_role(record, item['edit_actor_role'])
        subject_role = normalize_workspace_role(item['collection_key'])
        current_role = current_workspace_role(model, state)
        lock_role = space_workspace_role?(subject_role) ? subject_role : current_role
        record['previous_actor_role'] = previous_role unless previous_role.empty? || previous_role == lock_role
        record['actor_role'] = lock_role unless lock_role.empty?
        record['actor_role_name'] = workspace_role_label(lock_role) unless lock_role.empty?
        record['owner'] = current_user_name if record['owner'].to_s.empty?
        record['workspace_rebound_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        record['heartbeat_at'] = record['workspace_rebound_at']
        write_lock_record(path, record, expected_token: record['token'])
        item['edit_lock_token'] = record['token'].to_s
        item['edit_actor_role'] = lock_role
        item['edit_lock_owner'] = record['owner'].to_s
        item['edit_lock_host'] = record['host'].to_s
        item['edit_lock_started_at'] = record['started_at'].to_s
        log("空间 #{item['number']}:#{item['name']} 显式发布：当前进程内本人锁已恢复，专业身份保持为#{workspace_role_label(lock_role)}。")
      else
        unless interrupt_same_user_lock_file!(path, source_path, record, 'same_user_space_force_publish')
          raise "#{item['number']}:#{item['name']} 的本人遗留占用无法中断。"
        end
        acquire_space_lock!(item, source_path, state)
      end
      item['editing'] = true
      item['status'] = "已中断 #{current_user_name} 的遗留编辑状态 · 当前会话已接管"
      state['space_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      log("空间 #{item['number']}:#{item['name']} 已由同名用户强制接管。")
      space_lock_info(item, model, source_path: source_path, state: state)
    end

    # 顶部“解除/取消修改”是一次真正的放弃编辑：只有在共享上一发布版确认未变化时，
    # 才从本地镜像重新载入它。载入成功后再释放锁，任何准备/载入失败都保留当前本地修改与占用。
    def cancel_space_modifications!(space_id, model = Sketchup.active_model)
      raise '已有发布或更新任务正在执行，请等待完成后再取消修改。' if publish_critical_section? || @updating || @single_space_update_job
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      raise '该空间仍在后台发布中，不能取消修改。' if background_publish_active_state?(item)
      if initial_space_publish_pending?(item)
        raise '该空间尚未完成首次发布，没有可恢复的“共享上一发布版”；请重试首次发布或删除本地待发布空间。'
      end
      entity = space_model_entity(item['id'], model)
      raise '该空间模型尚未载入。' unless entity && entity.valid?
      raise '该空间当前不是本机待发布状态。' unless explicit_local_pending_space?(item, state, model)

      source_path = auto_relocate(item['model_path'].to_s, model)
      raise '空间上一发布版文件不存在，不能安全取消修改。' unless File.file?(source_path)
      lock = space_lock_info(item, model, source_path: source_path, state: state)
      unless lock['exists'] && !lock['stale'] && (lock['owned'] || lock['process_owned'])
        raise '当前会话已经不再持有该空间占用；为避免覆盖本地内容，未执行取消修改。'
      end

      baseline = normalize_fast_signature(item['last_signature'].to_s)
      current_source_signature = normalize_fast_signature(fast_file_signature(source_path))
      if !baseline.empty? && !current_source_signature.empty? && baseline != current_source_signature
        raise '共享上一发布版在你修改期间发生了变化。为避免恢复到错误版本，已停止取消修改；请先使用“检查”确认版本状态。'
      end

      # 没有任何模型修改时，“取消修改”没有数据丢失风险，也没有必要再弹确认、
      # 准备本地镜像、重新解析同一份 SKP。直接结束会话并释放占用即可。
      if space_edit_content_unchanged?(item, entity, source_path, model)
        prepare_explicit_publish_root_context!('space', item['id'], state, model)
        state = load_state(model)
        item = space_model_record(state, space_id)
        entity = item ? space_model_entity(item['id'], model) : nil
        raise '结束未修改会话前目标空间已失效。' unless item && entity && entity.valid?
        close_space_publish_dialog(item['id'], :cancel_edit)
        return finish_unmodified_space_edit_session!(
          state, item, entity, source_path, model,
          reason: :cancel, preserve_representation: true, notify: true
        )
      end

      label = "#{item['number']}:#{item['name']}"
      prompt = <<~TEXT
        取消修改“#{label}”？

        将放弃当前 SketchUp 中该空间所有未发布修改，恢复到开始修改前的上一发布版，并释放协作占用。
        其他仍在待发布的空间不会受影响。

        确定继续吗？
      TEXT
      return false unless native_confirm_yes?(prompt)

      # 自动退出任意嵌套层级。若当前正在另一个 LinkHub 单元里，只结束其“当前焦点”，
      # 不释放另一个单元的锁或丢弃它的待发布内容。
      prepare_explicit_publish_root_context!('space', item['id'], state, model)
      close_space_publish_dialog(item['id'], :cancel_edit)
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      entity = space_model_entity(space_id, model)
      raise '取消修改前目标空间已失效。' unless item && entity && entity.valid?

      current_source_signature = fast_file_signature(source_path)
      revision = space_authoritative_revision(item, source_path, actual_signature: current_source_signature)
      revision = "space-file|#{current_source_signature}" if revision.empty?
      source_snapshot = space_source_snapshot_signature(source_path)
      raise '无法验证空间上一发布版内容，请检查协同目录后重试。' if source_snapshot.empty?

      token = SecureRandom.hex(8)
      context = {
        token: token,
        model: model,
        space_id: item['id'].to_s,
        revision: revision.to_s,
        source_signature: current_source_signature.to_s,
        source_snapshot: source_snapshot,
        notify: true,
        other_editor: '',
        clear_local_session: true,
        cancel_edit: true
      }
      @single_space_update_job = context
      @updating = true
      begin_soft_heavy_interaction(:space_single_update)
      Sketchup.set_status_text("LinkHub 正在恢复 #{label} 的上一发布版…") rescue nil
      show_status("正在取消 #{label} 的未发布修改并准备上一发布版…", 'info')
      jobs = [{
        id: item['id'].to_s,
        key: space_mirror_key(item),
        source: source_path,
        revision: revision.to_s,
        source_signature: context[:source_signature].to_s,
        source_snapshot: context[:source_snapshot].to_s
      }]
      started = prefetch_space_batch_mirrors_async!(jobs, workers: 1, model: model) do |results, error|
        schedule_complete_single_space_update!(context, results, prefetch_error: error)
      end
      unless started
        finish_single_space_update_interaction!(model)
        raise '无法启动上一发布版恢复任务。'
      end
      refresh_workspace_toolbar(model)
      true
    rescue StandardError => e
      finish_single_space_update_interaction!(model) if @single_space_update_job
      log_exception('启动取消空间修改失败', e)
      raise
    end

    # 用户回收“本人用户名”遗留的空间占用。此操作只处理锁与当前 SU 的
    # 安全编辑状态，不发布、不更新、不覆盖共享 SKP。锁文件会归档而不是直接丢失，
    # 便于事后排查误操作或异常关闭。
    def release_same_user_space_occupancy!(space_id, model = Sketchup.active_model)
      raise '已有发布或更新任务正在执行，请等待完成后再回收遗留占用。' if publish_critical_section? || @updating || @single_space_update_job
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      clear_orphan_background_publish_state!(item, model, state)
      item = space_model_record(state, item['id']) || item
      raise '该空间正在后台发布，发布完成前不能回收协作占用。' if background_publish_active_state?(item)
      source = auto_relocate(item['model_path'].to_s, model)
      raise '该空间模型文件不存在，无法定位占用锁。' if source.to_s.empty?
      lock_path = edit_lock_path_for(source)
      record = read_lock_record(lock_path)
      raise '该空间当前已经没有修改占用。' unless record

      owner = record['owner'].to_s
      current = current_user_name.to_s
      strict_same_user = !owner.empty? &&
                         normalize_lock_identity(owner) == normalize_lock_identity(current)
      raise "该空间当前由 #{owner.empty? ? '其他成员' : owner} 占用，当前用户无权解除。" unless strict_same_user

      host = record['host'].to_s
      pid = record['pid'].to_i
      same_process = lock_record_from_current_process?(record)
      entity = space_model_entity(item['id'], model)
      local_session = same_process || local_space_edit_session?(item, state, model) ||
                      state['space_editing_id'].to_s == item['id'].to_s
      if local_session
        raise '当前 SketchUp 正在修改这个空间，不能单独解除占用。请使用“发布”提交并释放，或使用“取消修改”恢复上一发布版后释放。'
      end
      unless same_user_lock_recoverable?(record) || space_lock_record_stale?(record, lock_path)
        raise '同名用户的另一个活动 SketchUp 会话仍在持有该占用。为避免让它失去发布权限，不能从这里强制解除；请回到原会话发布/取消，或关闭原会话后再回收遗留占用。'
      end
      process_hint = if same_process
                       '占用来自当前 SketchUp。解除后空间根组件会重新锁定，本机未发布内容仍保留在当前 SU，但不会上传。'
                     elsif !host.empty? && host.casecmp(current_host_name).zero? && local_process_alive?(pid)
                       "同一台电脑上的另一个 SketchUp 进程（PID #{pid}）看起来仍在运行。解除后它将失去发布权限。"
                     else
                       '占用来自同名用户的中断会话或遗留锁。回收后旧会话不能继续发布，必须重新取得占用。'
                     end
      prompt = <<~TEXT
        #{item['number']}:#{item['name']} 当前由 #{owner}#{host.empty? ? '' : "@#{host}"} 修改。

        #{process_hint}

        此操作不会发布、更新、删除或覆盖任何空间模型。
        确定回收这个遗留占用吗？
      TEXT
      return false unless native_confirm_yes?(prompt)

      # 点击确认后再次核对 token 与 owner，防止提示期间锁已被另一会话重新创建。
      current_record = read_lock_record(lock_path)
      unless current_record && current_record['token'].to_s == record['token'].to_s &&
             !current_record['owner'].to_s.empty? &&
             normalize_lock_identity(current_record['owner']) == normalize_lock_identity(current_user_name)
        raise '占用状态刚刚发生变化，未执行解除；请刷新后重试。'
      end

      operation_open = false
      lock_removed = false
      # 能走到这里的只能是已经中断/可回收的旧会话。当前本机正在编辑时上面已经
      # 硬阻止，因此“回收占用”绝不会锁住当前模型或保留一份脱离协作锁的未发布编辑。
      annotated = current_record.dup
      annotated['released_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      annotated['released_reason'] = 'same_user_manual_release'
      annotated['released_by_owner'] = current_user_name
      annotated['released_by_host'] = current_host_name
      annotated['released_by_pid'] = Process.pid
      annotated['released_by_session_id'] = current_runtime_session_id
      write_lock_record(lock_path, annotated, expected_token: current_record['token'])
      verified = read_lock_record(lock_path)
      unless verified && verified['token'].to_s == current_record['token'].to_s
        raise '回收前锁文件校验失败，未修改占用。'
      end
      archived = archive_lock_file(lock_path, source, 'same_user_manual_release')
      File.delete(lock_path) if !archived && File.file?(lock_path)
      raise '无法归档或删除占用锁，请检查协同文件夹权限。' if File.file?(lock_path)
      lock_removed = true

      close_space_publish_dialog(item['id'], :release_occupancy)
      clear_space_publish_pending!(item)
      clear_space_lock_state!(item)
      item['editing'] = false
      item['status'] = '已回收本人遗留占用'
      state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
      state['space_edit_display_mode'] = ''
      state['space_preview_full_id'] = '' if state['space_preview_full_id'].to_s == item['id'].to_s
      @space_edit_contexts&.delete(model.object_id)
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true if entity && entity.valid?
      save_state(state, model, write_manifest: false)
      if operation_open
        model.commit_operation
        operation_open = false
      end

      refresh_dialog
      message = "已回收 #{owner} 的遗留占用；现在可以重新点击“修改”取得新的协作占用。"
      show_status(message, 'success')
      log("回收本人空间遗留占用：#{item['number']}:#{item['name']} / #{owner}@#{host} / 原 PID #{pid}")
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      # 若锁文件已经成功移走，但后续本地状态保存异常，至少保证当前空间根组件
      # 立即回到锁定状态，绝不能留下“无协作锁但模型仍解锁”的危险窗口。
      if defined?(lock_removed) && lock_removed && defined?(entity) && entity && entity.valid?
        begin
          entity.locked = true if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', false)
        rescue StandardError
          nil
        end
      end
      log_exception('回收本人空间遗留占用失败', e)
      raise
    end

    def release_space_lock!(item, source_path, clear_state: true, process_cleanup: false, model: Sketchup.active_model, state: nil)
      if linked_space_record?(item)
        clear_space_lock_state!(item) if clear_state
        return true
      end
      path = source_path.to_s.empty? ? '' : edit_lock_path_for(source_path)
      record = path.empty? ? nil : read_lock_record(path)
      token = item['edit_lock_token'].to_s
      state ||= load_state(model) unless process_cleanup
      subject_role = normalize_workspace_role(item['collection_key'])
      owned = if process_cleanup
                lock_record_owned_by_current_process?(record, token) || lock_record_from_current_process?(record)
              elsif space_workspace_role?(subject_role)
                lock_record_owned_by_current_process?(record, token) || lock_record_from_current_process?(record)
              else
                lock_record_owned_by_active_workspace?(record, token, item['edit_actor_role'], model, state)
              end
      if record && lock_record_from_current_process?(record) && !owned
        return false
      end
      File.delete(path) if owned && File.file?(path)
      clear_space_lock_state!(item) if clear_state && (!record || owned)
      true
    rescue StandardError => e
      log_exception('释放空间协作锁失败', e)
      false
    end

    def heartbeat_space_edit_locks(state, model = Sketchup.active_model)
      now = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      recovered = false
      (Array(state['space_models']) + Array(state['architecture_models'])).each do |item|
        next if linked_space_record?(item)
        token = item['edit_lock_token'].to_s
        local_edit_hint = !token.empty? || initial_space_publish_pending?(item) || local_space_edit_session?(item, state, model) ||
                          local_architecture_model_edit_session?(item, state, model)
        next unless local_edit_hint
        source = auto_relocate(item['model_path'].to_s, model)
        next if source.to_s.empty?
        path = edit_lock_path_for(source)
        record = read_lock_record(path)
        next unless record
        exact_owned = lock_record_owned_by_current_process?(record, token)
        same_process = lock_record_from_current_process?(record)
        next unless exact_owned || same_process
        actor_role = lock_record_actor_role(record, item['edit_actor_role'])
        actor_role = item['collection_key'].to_s.empty? ? SPACE_COLLECTION_KEY : item['collection_key'].to_s if actor_role.empty?
        record['actor_role'] = actor_role
        record['actor_role_name'] = workspace_role_label(actor_role)
        if same_process && !exact_owned
          item['edit_lock_token'] = record['token'].to_s
          item['edit_actor_role'] = actor_role
          item['edit_lock_owner'] = record['owner'].to_s
          item['edit_lock_host'] = record['host'].to_s
          item['edit_lock_started_at'] = record['started_at'].to_s
          recovered = true
        end
        record['heartbeat_at'] = now
        write_lock_record(path, record, expected_token: record['token'])
      rescue StandardError => e
        log_exception('更新空间协作锁心跳失败', e)
      end
      recovered
    end

    # 协作锁监视只比较会影响界面的语义字段，主动忽略 heartbeat_at。
    # 否则本机每次续租都会让 3 秒监视器误判“状态变化”，继而完整刷新抽屉状态。
    def space_presence_signature(state, model = Sketchup.active_model)
      parts = []
      (Array(state['space_models']) + Array(state['architecture_models'])).sort_by { |item| [item['collection_key'].to_s, item['id'].to_s] }.each do |item|
        if linked_space_record?(item)
          parts << "#{item['id']}|linked|#{item['linked_source_space_id']}"
          next
        end
        source = resolve_path(item['model_path'].to_s, model)
        lock_path = source.to_s.empty? ? '' : edit_lock_path_for(source)
        record = lock_path.empty? ? nil : read_lock_record(lock_path)
        if record
          stale = space_lock_record_stale?(record, lock_path)
          parts << [
            item['id'].to_s, record['token'].to_s, record['owner'].to_s,
            record['host'].to_s, record['pid'].to_i, record['actor_role'].to_s,
            record['started_at'].to_s, stale ? 1 : 0,
            item['publish_pending'] ? 1 : 0, item['edit_safe_paused'] ? 1 : 0
          ].join('|')
        else
          parts << [item['id'].to_s, 'none', item['publish_pending'] ? 1 : 0].join('|')
        end
      rescue StandardError
        parts << "#{item['id']}|error"
      end
      Digest::SHA1.hexdigest(parts.join("\n"))
    rescue StandardError
      ''
    end

    def start_space_presence_monitor
      return false unless workspace_connection_valid_cached?(Sketchup.active_model)
      return true if @space_presence_monitor_timer
      @space_presence_monitor_timer = GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(SPACE_PRESENCE_MONITOR_INTERVAL, true) do
        begin
          model = Sketchup.active_model
          unless workspace_connection_valid_cached?(model, max_age: 0.0)
            stop_space_presence_monitor
            next
          end
          state = load_state(model)
          has_local_edit = (Array(state['space_models']) + Array(state['architecture_models'])).any? do |item|
            !item['edit_lock_token'].to_s.empty? || local_space_edit_session?(item, state, model) ||
              local_architecture_model_edit_session?(item, state, model)
          end
          drawer_open = workspace_toolbar_open?(model)
          panel_visible = dialog_visible?(@dialog) || drawer_open
          toolbar_present = begin
            record = (@workspace_toolbar_records || {})[model.object_id]
            record.is_a?(Hash) && !record[:overlay].nil?
          rescue StandardError
            false
          end
          # v0.13.6.136：即使左侧抽屉收起，只要顶部悬浮条仍存在，也保留 20 秒一次的
          # 轻量协同组件版本检查，保证别人的组件提交能自动点亮黄色更新按钮。空间锁文件
          # 的全量扫描仍只在面板/抽屉可见时执行，避免为了一个黄色按钮增加 NAS 压力。
          unless panel_visible || toolbar_present || has_local_edit
            stop_space_presence_monitor
            next
          end
          recovered = heartbeat_space_edit_locks(state, model) if has_local_edit
          save_state(state, model, write_manifest: false) if recovered
          key = model.object_id
          changed = false
          if background_work_idle?(model, min_idle: 1.0)
            if panel_visible
              @space_presence_signatures ||= {}
              signature = space_presence_signature(state, model)
              space_changed = !signature.empty? && @space_presence_signatures[key].to_s != signature
              @space_presence_signatures[key] = signature unless signature.empty?
              changed ||= space_changed
            end

            if panel_visible || toolbar_present
              component_plan = shared_component_bulk_update_plan(model, state, force: true)
              updates = Array(component_plan[:rows])
              blocked_component_updates = Array(component_plan[:blocked])
              all_component_updates = updates + blocked_component_updates
              component_signature = Digest::SHA1.hexdigest(
                all_component_updates.map { |row| "#{row[:id]}|#{row.dig(:record, 'revision')}|#{blocked_component_updates.include?(row) ? 1 : 0}" }.sort.join("\n")
              )
              @shared_component_presence_signatures ||= {}
              previous_component_signature = @shared_component_presence_signatures[key].to_s
              component_changed = previous_component_signature != component_signature
              @shared_component_presence_signatures[key] = component_signature
              changed ||= component_changed
              if component_changed && !all_component_updates.empty? && !previous_component_signature.empty?
                if blocked_component_updates.any?
                  show_status("#{all_component_updates.length} 个协同组件有更新；#{blocked_component_updates.length} 个含本机修改暂不覆盖", 'warning')
                else
                  show_status("#{updates.length} 个协同组件有更新；点击顶部黄色按钮一致更新空间与组件", 'info')
                end
              end
            end
          end
          if recovered || changed
            if @dialog && @dialog.visible?
              refresh_dialog
            elsif drawer_open && !workspace_toolbar_fast_interaction_active?(model)
              refresh_workspace_toolbar(model, detailed: true)
            elsif toolbar_present && !workspace_toolbar_fast_interaction_active?(model)
              refresh_workspace_toolbar(model, detailed: false, state: state)
            end
          end
        rescue StandardError => e
          log_exception('刷新空间协同状态失败', e)
        end
      end
      true
    rescue StandardError => e
      log_exception('启动空间协同状态监视失败', e)
      false
    end

    def stop_space_presence_monitor
      return true unless @space_presence_monitor_timer
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_stop_timer(@space_presence_monitor_timer)
      @space_presence_monitor_timer = nil
      true
    rescue StandardError
      @space_presence_monitor_timer = nil
      false
    end

    def forget_shared_component_caches(model)
      return false unless model
      key = model.object_id
      [
        @shared_component_content_signature_cache,
        @shared_component_dirty_ids,
        @shared_component_presence_signatures,
        @shared_component_discovery_cache,
        @shared_component_bulk_plan_cache,
        @shared_component_fast_identity_cache,
        @shared_component_definition_identity_index_cache
      ].compact.each { |cache| cache.delete(key) if cache.respond_to?(:delete) }
      true
    rescue StandardError
      false
    end

    def entity_snapshot_id(entity)
      value = entity.respond_to?(:persistent_id) ? entity.persistent_id : entity.entityID
      value.to_s
    rescue StandardError
      entity.object_id.to_s
    end

    # v0.7.5 起，总显隐快照按空间 id 保存，并同时管理专用控制标记。
    # 兼容 v0.7.3 / v0.7.4 以 persistent_id 为键的旧扁平快照。
    def normalize_space_collection_visibility_snapshot(snapshot)
      raw = snapshot.is_a?(Hash) ? snapshot : {}
      if raw['entities'].is_a?(Hash) || raw['tags'].is_a?(Hash)
        {
          'entities' => raw['entities'].is_a?(Hash) ? raw['entities'] : {},
          'tags' => raw['tags'].is_a?(Hash) ? raw['tags'] : {}
        }
      else
        { 'entities' => raw, 'tags' => {} }
      end
    rescue StandardError
      { 'entities' => {}, 'tags' => {} }
    end

    def space_collection_entity_visibility_key(entity)
      space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s if entity.respond_to?(:get_attribute)
      return "space:#{space_id}" unless space_id.to_s.empty?
      "entity:#{entity_snapshot_id(entity)}"
    rescue StandardError
      "entity:#{entity_snapshot_id(entity)}"
    end

    def space_collection_hidden_for(state, collection_key)
      key = normalize_space_collection_key(collection_key)
      map = state.is_a?(Hash) && state['space_collection_hidden_by_key'].is_a?(Hash) ? state['space_collection_hidden_by_key'] : {}
      return !!map[key] if map.key?(key)
      key == SPACE_COLLECTION_KEY ? !!(state && state['space_collection_hidden']) : false
    rescue StandardError
      false
    end

    def set_space_collection_hidden_for!(state, collection_key, hidden)
      key = normalize_space_collection_key(collection_key)
      state['space_collection_hidden_by_key'] = {} unless state['space_collection_hidden_by_key'].is_a?(Hash)
      state['space_collection_hidden_by_key'][key] = !!hidden
      state['space_collection_hidden'] = !!hidden if key == SPACE_COLLECTION_KEY
      !!hidden
    end

    def space_collection_visibility_snapshot_for(state, collection_key)
      key = normalize_space_collection_key(collection_key)
      map = state.is_a?(Hash) && state['space_collection_visibility_snapshot_by_key'].is_a?(Hash) ? state['space_collection_visibility_snapshot_by_key'] : {}
      raw = if map.key?(key)
              map[key]
            elsif key == SPACE_COLLECTION_KEY && state.is_a?(Hash)
              state['space_collection_visibility_snapshot']
            else
              {}
            end
      normalize_space_collection_visibility_snapshot(raw)
    rescue StandardError
      { 'entities' => {}, 'tags' => {} }
    end

    def set_space_collection_visibility_snapshot_for!(state, collection_key, snapshot)
      key = normalize_space_collection_key(collection_key)
      normalized = normalize_space_collection_visibility_snapshot(snapshot)
      state['space_collection_visibility_snapshot_by_key'] = {} unless state['space_collection_visibility_snapshot_by_key'].is_a?(Hash)
      state['space_collection_visibility_snapshot_by_key'][key] = normalized
      state['space_collection_visibility_snapshot'] = normalized if key == SPACE_COLLECTION_KEY
      normalized
    end

    def space_model_entities_for_collection(state, collection_key, model = Sketchup.active_model)
      valid_ids = spaces_for_collection(state, collection_key).each_with_object({}) { |item, memo| memo[item['id'].to_s] = true }
      space_model_entities(model).select do |entity|
        space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
        valid_ids[space_id]
      end
    rescue StandardError
      []
    end

    def space_collection_control_tags(model = Sketchup.active_model, collection_key = SPACE_COLLECTION_KEY)
      professional_control_tags(normalize_space_collection_key(collection_key), model)
    rescue StandardError
      []
    end

    # 硬装/软装总眼睛各自读取真实标签和根组件可见性，不再互相影响。
    def space_collection_hidden_active?(state, model = Sketchup.active_model, collection_key = nil)
      inferred = collection_key.to_s
      if inferred.empty?
        host = host_discipline_for(state)
        inferred = space_workspace_role?(host) ? host : SPACE_COLLECTION_KEY
      end
      key = normalize_space_collection_key(inferred)
      entities = space_model_entities_for_collection(state, key, model)
      return false if entities.empty?

      tags = space_collection_control_tags(model, key)
      tags_hidden = !tags.empty? && tags.all? do |tag|
        tag.respond_to?(:visible?) && !tag.visible?
      rescue StandardError
        false
      end
      return true if tags_hidden

      if space_collection_hidden_for(state, key)
        return entities.all? do |entity|
          entity.respond_to?(:hidden?) && entity.hidden?
        rescue StandardError
          false
        end
      end
      false
    rescue StandardError
      space_collection_hidden_for(state, collection_key || SPACE_COLLECTION_KEY)
    end

    def group_collection_visibility_state(group, collection_key)
      key = normalize_space_collection_key(collection_key)
      group['collection_visibility'] = {} unless group['collection_visibility'].is_a?(Hash)
      entry = group['collection_visibility'][key]
      unless entry.is_a?(Hash)
        entry = if key == SPACE_COLLECTION_KEY
                  {
                    'suspended' => !!group['visibility_suspended'],
                    'restore_ids' => Array(group['visibility_restore_ids']).map(&:to_s).reject(&:empty?).uniq
                  }
                else
                  { 'suspended' => false, 'restore_ids' => [] }
                end
        group['collection_visibility'][key] = entry
      end
      entry['suspended'] = !!entry['suspended']
      entry['restore_ids'] = Array(entry['restore_ids']).map(&:to_s).reject(&:empty?).uniq
      entry
    rescue StandardError
      { 'suspended' => false, 'restore_ids' => [] }
    end

    def sync_legacy_group_visibility_from_collection!(group)
      entry = group_collection_visibility_state(group, SPACE_COLLECTION_KEY)
      group['visibility_suspended'] = !!entry['suspended']
      group['visibility_restore_ids'] = Array(entry['restore_ids']).dup
      group
    rescue StandardError
      group
    end

    def space_isolation_visibility_snapshot_value(snapshot, entity)
      return nil unless snapshot.is_a?(Hash) && entity
      space_id = entity.respond_to?(:get_attribute) ? (entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue '') : ''
      return !!snapshot["space:#{space_id}"] if !space_id.empty? && snapshot.key?("space:#{space_id}")
      key = entity_snapshot_id(entity) rescue ''
      return !!snapshot[key] if !key.to_s.empty? && snapshot.key?(key)
      nil
    rescue StandardError
      nil
    end

    # 隔离期间参考空间根的锁状态不能只用 persistent_id 作为恢复依据。
    # SketchUp 在内部编辑/撤销/自动唯一化过程中可能刷新根对象或其 persistent_id；
    # space_id 才是 LinkHub 跨事务稳定身份。新快照同时写 pid + space_id，旧项目仍兼容 pid。
    def space_isolation_lock_snapshot_keys(entity)
      keys = []
      if entity && entity.respond_to?(:get_attribute)
        space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
        keys << "space:#{space_id}" unless space_id.empty?
      end
      snapshot_id = entity_snapshot_id(entity) rescue ''
      unless snapshot_id.to_s.empty?
        keys << snapshot_id.to_s
        keys << "entity:#{snapshot_id}"
      end
      keys.uniq
    rescue StandardError
      []
    end

    def space_isolation_lock_snapshot_value(lock_snapshot, entity)
      return nil unless lock_snapshot.is_a?(Hash) && entity
      space_isolation_lock_snapshot_keys(entity).each do |key|
        return !!lock_snapshot[key] if lock_snapshot.key?(key)
      end
      nil
    rescue StandardError
      nil
    end

    def restore_space_isolation_reference_locks!(item, model = Sketchup.active_model)
      return 0 unless item.is_a?(Hash) && model
      lock_snapshot = item['isolation_lock_snapshot'].is_a?(Hash) ? item['isolation_lock_snapshot'] : {}
      return 0 if lock_snapshot.empty?
      restored = 0
      model.entities.to_a.each do |entity|
        next unless entity && entity.valid? && entity.respond_to?(:get_attribute)
        space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
        next if space_id.empty? || space_id == item['id'].to_s
        original_locked = space_isolation_lock_snapshot_value(lock_snapshot, entity)
        next unless original_locked == true
        if entity.respond_to?(:locked=) && !entity_native_locked?(entity)
          entity.locked = true
          restored += 1
        end
        @native_lock_state_cache ||= {}
        @native_lock_state_cache[space_native_cache_key(model, space_id)] = true
      rescue StandardError
        next
      end
      log("空间退出过渡期已提前恢复 #{restored} 个参考空间根锁") if restored.positive?
      restored
    rescue StandardError => e
      log_exception('提前恢复空间参考根锁失败', e)
      0
    end

    def restore_space_isolation!(item, model = Sketchup.active_model)
      snapshot = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
      lock_snapshot = item['isolation_lock_snapshot'].is_a?(Hash) ? item['isolation_lock_snapshot'] : {}
      unless snapshot.empty? && lock_snapshot.empty?
        model.entities.to_a.each do |entity|
          key = entity_snapshot_id(entity)
          original_hidden = space_isolation_visibility_snapshot_value(snapshot, entity)
          entity.hidden = !!original_hidden unless original_hidden.nil? || !entity.respond_to?(:hidden=)
          original_locked = space_isolation_lock_snapshot_value(lock_snapshot, entity)
          unless original_locked.nil?
            if entity.respond_to?(:locked=)
              entity.locked = !!original_locked
              space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
              unless space_id.empty?
                @native_lock_state_cache ||= {}
                @native_lock_state_cache[space_native_cache_key(model, space_id)] = !!original_locked
              end
            end
          end
        rescue StandardError
          next
        end
      end
      # 只清除本次进入时的显隐快照；edit_references_visible 是用户最后一次眼睛选择，
      # 退出组件、暂不发布、正式发布以及释放锁后都继续保留。
      item['isolation_snapshot'] = {}
      item['isolation_lock_snapshot'] = {}
      true
    rescue StandardError => e
      log_exception('恢复空间模型隔离显示失败', e)
      false
    end

    def isolate_space_for_edit!(item, entity, model = Sketchup.active_model, state: nil)
      snapshot = {}
      lock_snapshot = {}
      temporarily_unlocked = 0
      preferred_visible = if state.is_a?(Hash) && state.key?('space_edit_references_visible_preference')
                            !!state['space_edit_references_visible_preference']
                          else
                            !!item['edit_references_visible']
                          end
      model.entities.to_a.each do |other|
        next unless other.respond_to?(:get_attribute) && other.get_attribute(ENTITY_DICT, 'managed', false)
        original_hidden = !!other.hidden?
        snapshot_key = entity_snapshot_id(other)
        snapshot[snapshot_key] = original_hidden
        other_space_id_for_snapshot = other.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
        snapshot["space:#{other_space_id_for_snapshot}"] = original_hidden unless other_space_id_for_snapshot.empty?
        # 其它空间根即使只作为当前编辑上下文外的参考，只要保持原生 locked，
        # SketchUp 就会把锁沿共享的内部 Definition 传播回来，双击普通组件时弹出
        # “部分实例已锁定”。进入空间期间仅临时解除这些顶层根的本机原生锁；
        # 协作锁文件、editing 状态和共享文件均不改变，退出时按快照逐一恢复。
        other_space_id = other.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
        if other != entity && !other_space_id.empty? && other.respond_to?(:locked?) && other.locked? && other.respond_to?(:locked=)
          # pid 用于兼容旧快照；space_id 是跨 SketchUp 内部事务稳定的恢复键。
          lock_snapshot[snapshot_key] = true
          lock_snapshot["space:#{other_space_id}"] = true
          lock_snapshot["entity:#{snapshot_key}"] = true
          other.locked = false
          @native_lock_state_cache ||= {}
          @native_lock_state_cache[space_native_cache_key(model, other_space_id)] = false
          temporarily_unlocked += 1
        end
        next unless other.respond_to?(:hidden=)
        if other == entity
          other.hidden = false
        else
          # “显示其他”并不强制显示进入前原本已隐藏的模型，只恢复进入前快照；
          # “隐藏其他”则把所有其他受管根模型临时隐藏。
          other.hidden = preferred_visible ? original_hidden : true
        end
      rescue StandardError
        next
      end
      item['isolation_snapshot'] = snapshot
      item['isolation_lock_snapshot'] = lock_snapshot
      item['edit_references_visible'] = preferred_visible
      entity.hidden = false if entity.respond_to?(:hidden=)
      log("空间编辑期间已临时解除 #{temporarily_unlocked} 个参考空间根的原生锁；退出时自动恢复。") if temporarily_unlocked.positive?
      true
    end

    def set_space_edit_references_visible!(item, entity, visible, model = Sketchup.active_model)
      snapshot = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
      model.entities.to_a.each do |other|
        next unless other.respond_to?(:get_attribute) && other.get_attribute(ENTITY_DICT, 'managed', false)
        if other == entity
          other.hidden = false if other.respond_to?(:hidden=)
        elsif other.respond_to?(:hidden=)
          original_hidden = space_isolation_visibility_snapshot_value(snapshot, other)
          other.hidden = visible ? !!original_hidden : true
        end
      rescue StandardError
        next
      end
      item['edit_references_visible'] = !!visible
      true
    end

    # 热重载、撤回或原生工具切换可能清空 @native_lock_state_cache。只靠缓存会让
    # 锁监视器把编辑期间临时解锁的参考空间根重新锁上，内部共享组件随即再次弹窗。
    # 以当前 active_path + 编辑空间持久快照复核，不依赖工作区 UI，也不访问网络。
    def space_reference_root_isolation_member?(item, entity, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && entity && entity.valid? && state.is_a?(Hash) && model
      editing_id = state['space_editing_id'].to_s
      if editing_id.empty?
        record = @space_edit_contexts && @space_edit_contexts[model.object_id]
        editing_id = record[:space_id].to_s if record.is_a?(Hash)
      end
      if editing_id.empty?
        latch = space_world_root_exit_latch(model)
        editing_id = latch[:space_id].to_s if latch.is_a?(Hash)
      end
      if editing_id.empty?
        finalize = @space_exit_finalize_records && @space_exit_finalize_records[model.object_id]
        editing_id = finalize[:space_id].to_s if finalize.is_a?(Hash)
      end
      return false if editing_id.empty? || item['id'].to_s == editing_id
      active_item = space_model_record(state, editing_id)
      return false unless active_item
      lock_snapshot = active_item['isolation_lock_snapshot'].is_a?(Hash) ? active_item['isolation_lock_snapshot'] : {}
      space_isolation_lock_snapshot_value(lock_snapshot, entity) == true
    rescue StandardError
      false
    end

    def space_reference_root_temporarily_unlocked?(item, entity, state, model = Sketchup.active_model)
      return false unless space_reference_root_isolation_member?(item, entity, state, model)
      active_path = Array(model.active_path)
      return false if active_path.empty?
      active_root = active_path.first
      return false unless active_root && active_root.valid?
      active_space_id = active_root.get_attribute(ENTITY_DICT, 'space_id', '').to_s rescue ''
      editing_id = state['space_editing_id'].to_s
      return false if editing_id.empty? || active_space_id != editing_id
      active_item = space_model_record(state, editing_id)
      active_item && active_item['editing']
    rescue StandardError
      false
    end

    # active_path 从空间退到世界根后，隔离快照尚未完成显隐恢复的约 0.1~0.2 秒内，
    # 参考空间根仍可能处于“为了编辑兼容而临时解锁”的状态。旧逻辑此时把它们逐个
    # 当成本地编辑会话，再因为没有各自协作锁而显示“修改锁失效”。退出事务期间这些
    # 根应被视作正在恢复的参考根，并尽快重新锁回，而不是创建任何本地编辑状态。
    def space_reference_root_exit_transition?(item, entity, state, model = Sketchup.active_model)
      return false unless space_reference_root_isolation_member?(item, entity, state, model)
      return false unless model.active_path.nil?
      latch = space_world_root_exit_latch(model)
      finalize = @space_exit_finalize_records && @space_exit_finalize_records[model.object_id]
      exit_active = latch.is_a?(Hash) || finalize.is_a?(Hash) || (@space_exit_commit_in_progress && @space_exit_commit_in_progress[model.object_id])
      !!exit_active
    rescue StandardError
      false
    end

    def toggle_space_edit_references(space_id)
      model = Sketchup.active_model
      state = load_state(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      entity = space_model_entity(space_id, model)
      raise '该空间模型尚未载入。' unless entity && entity.valid?
      raise '当前已退出到全模；请先双击或点击“进入”回到该空间，再切换空间参考。' unless active_path_inside_space?(entity, model)
      lock = space_lock_info(item, model)
      unless lock['exists'] && !lock['stale'] && lock['owned'] && state['space_editing_id'].to_s == item['id'].to_s
        raise '只有当前正在修改该空间的成员，才能切换参考模型显示。'
      end
      visible = !item['edit_references_visible']
      model.start_operation(visible ? '显示空间修改参考' : '隐藏空间修改参考', true)
      set_space_edit_references_visible!(item, entity, visible, model)
      # 记录最后一次眼睛选择：退出、发布或切换到另一个空间后，下次进入仍按此状态。
      state['space_edit_references_visible_preference'] = !!visible
      item['status'] = visible ? '修改中 · 参考模型已显示' : '修改中 · 参考模型已隐藏'
      save_state(state, model, write_manifest: false)
      model.commit_operation
      refresh_dialog
      show_status(visible ? '已显示其他参考模型；当前空间仍保持解锁。' : '已再次隐藏其他参考模型。', 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    def clear_space_publish_pending!(item)
      item['publish_pending'] = false
      item['publish_countdown_started_at'] = ''
      item['publish_countdown_until'] = 0.0
      true
    end

    def space_native_cache_key(model, space_id)
      [model.object_id, "space:#{space_id}"]
    end

    def close_space_publish_dialog(space_id, action = :closed)
      @space_publish_dialog_actions ||= {}
      @space_publish_dialogs ||= {}
      key = space_id.to_s
      dialog = @space_publish_dialogs[key]
      return false unless dialog
      @space_publish_dialog_actions[key] = action
      dialog.close if dialog.respond_to?(:close)
      true
    rescue StandardError
      @space_publish_dialogs.delete(key) if defined?(key)
      false
    end

    def mark_space_publish_pending_state!(item)
      item['publish_pending'] = true
      item['publish_countdown_started_at'] = ''
      item['publish_countdown_until'] = 0.0
      item['status'] = '待发布'
      true
    end

    # 模型空间进入编辑台时只做一次单向显示优化：关闭轮廓线与端点短横。
    # 不保存进入前状态、不在退出时恢复；用户进入后手动重新开启时，本轮编辑保持其选择。
    def optimize_space_edit_edge_rendering!(model = Sketchup.active_model)
      return 0 unless model
      options = model.rendering_options
      available = options.respond_to?(:keys) ? options.keys : []
      keys = %w[DrawSilhouettes DrawLineEnds].select do |key|
        available.include?(key) && options[key] == true
      rescue StandardError
        false
      end
      return 0 if keys.empty?

      @space_edit_edge_rendering_optimization_running = true
      operation_started = false
      begin
        model.start_operation('优化模型空间编辑显示', true, false, true)
        operation_started = true
        keys.each { |key| options[key] = false }
        model.commit_operation
        operation_started = false
      rescue StandardError
        model.abort_operation rescue nil if operation_started
        raise
      end
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      log("模型空间编辑显示已轻量优化：关闭 #{keys.join('、')}")
      keys.length
    rescue StandardError => e
      log_exception('关闭模型空间轮廓线/端点短横失败', e)
      0
    ensure
      @space_edit_edge_rendering_optimization_running = false
    end

    def schedule_space_edit_edge_rendering_optimization!(space_id, model = Sketchup.active_model)
      return false unless model
      id = space_id.to_s
      return false if id.empty?
      runtime_start_timer(
        0.01, false, label: 'space:optimize_edit_edge_rendering',
        key: "space:optimize_edit_edge_rendering:#{model.object_id}"
      ) do
        next unless model == Sketchup.active_model
        root = Array(model.active_path).first
        next unless root && root.valid? && root.respond_to?(:get_attribute)
        next unless root.get_attribute(ENTITY_DICT, 'space_id', '').to_s == id
        state = load_state(model)
        item = space_model_record(state, id)
        next unless item && local_space_edit_session?(item, state, model)
        optimize_space_edit_edge_rendering!(model)
      end
      true
    rescue StandardError => e
      log_exception('安排模型空间边线显示优化失败', e)
      false
    end

    # 自动进入空间最外层组件。这里只改变 SketchUp 编辑上下文，不创建几何事务。
    # 记录必须在 active_path= 之前写入，因为 onActivePathChanged 可能同步触发。
    def enter_space_edit_context!(item, entity, model = Sketchup.active_model)
      return false unless item && entity && entity.valid? && model
      # 明确的“修改/继续”是新的进入事务，允许清除上一次世界根退出意图。
      clear_space_world_root_exit_latch!(model, reason: '开始新的空间进入事务') if space_world_root_exit_latch(model)
      @space_edit_contexts ||= {}
      key = model.object_id
      @space_edit_contexts[key] = {
        space_id: item['id'].to_s,
        inside: true,
        transitioning: true
      }
      return true if active_path_inside_space?(entity, model)
      unless model.active_path.nil?
        @space_edit_contexts.delete(key)
        return false
      end
      model.selection.clear
      model.selection.add(entity)
      if model.respond_to?(:active_path=)
        model.active_path = [entity]
      end
      inside = active_path_inside_space?(entity, model)
      if inside
        @space_edit_contexts[key][:transitioning] = false
        schedule_space_edit_edge_rendering_optimization!(item['id'], model)
      else
        @space_edit_contexts.delete(key)
      end
      inside
    rescue StandardError => e
      @space_edit_contexts&.delete(model.object_id) if model
      log_exception('自动进入空间组件失败', e)
      false
    end

    def recover_space_edit_context_tracking(model = Sketchup.active_model)
      return false unless model
      state = load_state(model)
      space_id = state['space_editing_id'].to_s
      return false if space_id.empty?
      item = space_model_record(state, space_id)
      entity = item ? space_model_entity(space_id, model) : nil
      return false unless entity && entity.valid? && active_path_inside_space?(entity, model)
      @space_edit_contexts ||= {}
      @space_edit_contexts[model.object_id] = { space_id: space_id, inside: true, transitioning: false }
      true
    rescue StandardError
      false
    end

    # v0.13.6.100：日志证明真正的问题不是 ESC 没有到达 SketchUp，而是 active_path
    # 已经从 1 -> 0、甚至连续 3 帧稳定为空以后，LinkHub 自己的后续收尾又让路径回到
    # 同一空间，并由“临界状态自愈”重新解锁/恢复 editing。于是用户看到必须连续按很多次 ESC。
    #
    # 这里增加“世界根退出意图锁（exit latch）”：一旦观察到当前 LinkHub 空间从非空
    # active_path 真正退到 nil，就把这次动作认定为明确的退出意图。在退出事务彻底结束前，
    # 如果 SketchUp/某个模型操作又让 active_path 回流到同一空间，LinkHub 不再把它当成
    # “需要自愈的合法编辑”，而是立即再次压回 nil。只有用户明确再次点击/双击“修改/继续”
    # 才会清除这个 latch。这样退出和继续编辑成为两个单向事务，不再互相打架。
    SPACE_WORLD_ROOT_EXIT_LATCH_SECONDS = 15.0
    SPACE_WORLD_ROOT_EXIT_LATCH_RELEASE_DELAY = 1.0

    def space_world_root_exit_latch(model = Sketchup.active_model)
      return nil unless model
      key = model.object_id
      record = @space_world_root_exit_latches && @space_world_root_exit_latches[key]
      return nil unless record.is_a?(Hash)
      if record[:expires_at].to_f.positive? && monotonic_seconds > record[:expires_at].to_f
        @space_world_root_exit_latches.delete(key)
        return nil
      end
      record
    rescue StandardError
      nil
    end

    def space_world_root_exit_latch_for?(model, space_id = nil)
      record = space_world_root_exit_latch(model)
      return false unless record
      wanted = space_id.to_s
      wanted.empty? || record[:space_id].to_s == wanted
    rescue StandardError
      false
    end

    def arm_space_world_root_exit_latch!(model, space_id, source: 'active_path -> nil')
      return false unless model
      sid = space_id.to_s
      return false if sid.empty?
      @space_world_root_exit_latches ||= {}
      key = model.object_id
      existing = @space_world_root_exit_latches[key]
      now = monotonic_seconds
      if existing.is_a?(Hash) && existing[:space_id].to_s == sid
        existing[:expires_at] = now + SPACE_WORLD_ROOT_EXIT_LATCH_SECONDS
        existing[:last_source] = source.to_s
        return true
      end
      @space_world_root_exit_latches[key] = {
        space_id: sid, armed_at: now, expires_at: now + SPACE_WORLD_ROOT_EXIT_LATCH_SECONDS,
        source: source.to_s, last_source: source.to_s, forced_nil_count: 0, completed: false
      }
      log("空间世界根退出意图已锁定：#{sid} / #{source}")
      true
    rescue StandardError => e
      log_exception('建立空间世界根退出意图失败', e)
      false
    end

    def clear_space_world_root_exit_latch!(model = Sketchup.active_model, reason: '')
      return false unless model
      key = model.object_id
      record = @space_world_root_exit_latches && @space_world_root_exit_latches.delete(key)
      if record
        log("空间世界根退出意图已清除：#{record[:space_id]}#{reason.to_s.empty? ? '' : " / #{reason}"}")
      end
      !!record
    rescue StandardError
      false
    end

    def force_space_world_root_exit_if_needed!(model = Sketchup.active_model, reason: '')
      record = space_world_root_exit_latch(model)
      return false unless record && model
      path = Array(model.active_path).select { |node| node && node.valid? }
      return false if path.empty?
      state = load_state(model)
      item = space_model_record(state, record[:space_id])
      entity = item ? space_model_entity(item['id'], model) : nil
      unless item && entity && entity.valid?
        clear_space_world_root_exit_latch!(model, reason: '空间实体失效')
        return false
      end
      unless active_path_inside_space?(entity, model)
        # 用户真的进入了另一棵编辑树，不应替用户强退。
        clear_space_world_root_exit_latch!(model, reason: "已进入其它编辑树 depth=#{path.length}")
        return false
      end

      @space_exit_path_force_in_progress ||= {}
      key = model.object_id
      return true if @space_exit_path_force_in_progress[key]
      begin
        @space_exit_path_force_in_progress[key] = true
        model.selection.clear rescue nil
        model.active_path = nil unless model.active_path.nil?
        record[:forced_nil_count] = record[:forced_nil_count].to_i + 1
        record[:expires_at] = monotonic_seconds + SPACE_WORLD_ROOT_EXIT_LATCH_SECONDS
        log("空间退出回流已强制压回世界根：#{item['number']}:#{item['name']} / count=#{record[:forced_nil_count]}#{reason.to_s.empty? ? '' : " / #{reason}"}")
      ensure
        @space_exit_path_force_in_progress[key] = false
      end
      true
    rescue StandardError => e
      log_exception('强制保持空间世界根退出失败', e)
      false
    end

    def schedule_space_world_root_exit_latch_release!(model, space_id)
      return false unless model
      key = model.object_id
      sid = space_id.to_s
      runtime_start_timer(
        SPACE_WORLD_ROOT_EXIT_LATCH_RELEASE_DELAY, false, label: 'space:world_root_exit_latch_release',
        key: "space:world_root_exit_latch_release:#{key}", model: model, active_model_only: true
      ) do
        record = space_world_root_exit_latch(model)
        next unless record && record[:space_id].to_s == sid
        if model.active_path.nil?
          clear_space_world_root_exit_latch!(model, reason: '退出事务完成且世界根稳定')
        else
          force_space_world_root_exit_if_needed!(model, reason: '退出事务完成后的延迟复核')
          schedule_space_world_root_exit_latch_release!(model, sid)
        end
      end
      true
    rescue StandardError => e
      log_exception('安排空间世界根退出意图释放失败', e)
      false
    end

    # v0.13.6.97：空间退出必须是一个“稳定 active_path=nil”事务。
    # SketchUp 在 ESC / Close Component / Tool 切换时，active_path 与 Tool 栈可能跨多个
    # 空闲帧才最终稳定。旧版在第一次观察到 nil 时就立刻锁空间根、切代理；如果下一拍
    # active_path 又回到空间内部，就会形成“仍在组件编辑上下文 + 空间根已锁”的临界死锁。
    # 这里要求连续多个空闲帧都保持 nil，才允许真正执行退出收尾。
    SPACE_EXIT_STABLE_NIL_FRAMES = 3
    SPACE_EXIT_STABLE_INTERVAL = 0.045

    def heal_active_liminal_space_context!(model = Sketchup.active_model, reason: '')
      return false unless model
      path = Array(model.active_path).select { |node| node && node.valid? }
      return false if path.empty?
      root = path.first
      return false unless root && root.respond_to?(:get_attribute)
      space_id = root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
      return false if space_id.empty?
      state = load_state(model)
      item = space_model_record(state, space_id)
      return false unless item
      heal_liminal_space_edit_context!(state, item, root, model, reason: reason)
    rescue StandardError => e
      log_exception('检查空间退出临界状态失败', e)
      false
    end

    def cancel_space_exit_finalize!(model = Sketchup.active_model, reason = '')
      return false unless model
      @space_exit_finalize_records ||= {}
      @space_exit_finalize_tokens ||= {}
      key = model.object_id
      record = @space_exit_finalize_records.delete(key)
      @space_exit_finalize_tokens.delete(key)
      if record
        log("空间退出稳定确认已取消：#{record[:space_id]}#{reason.to_s.empty? ? '' : " / #{reason}"}")
      end
      !!record
    rescue StandardError
      false
    end

    def heal_liminal_space_edit_context!(state, item, entity, model = Sketchup.active_model, reason: '')
      return false unless state && item && entity && entity.valid? && model
      return false unless active_path_inside_space?(entity, model)
      # v0.13.6.100：明确的“退出到世界根”事务优先级高于临界状态自愈。
      # 旧逻辑正是在这里把已经退出成功的空间重新恢复成 editing，造成 1->0 无限回流。
      if space_world_root_exit_latch_for?(model, item['id'])
        force_space_world_root_exit_if_needed!(model, reason: "阻止临界自愈反向重入 / #{reason}")
        return false
      end
      return false unless local_space_edit_session?(item, state, model)
      needs_heal = entity_native_locked?(entity) || space_edit_safe_paused?(item) ||
                   entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      return false unless needs_heal

      lock = space_lock_info(item, model, state: state)
      return false unless lock['exists'] && !lock['stale'] && lock['owned']

      operation_started = false
      model.start_operation("恢复空间编辑上下文 #{item['number']}:#{item['name']}", true, false, true)
      operation_started = true
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      clear_space_safe_pause!(item, entity)
      item['editing'] = true
      item['status'] = '修改中 · 已自动修复退出临界状态'
      state['space_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_started = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      @space_edit_contexts ||= {}
      @space_edit_contexts[model.object_id] = { space_id: item['id'].to_s, inside: true, transitioning: false }
      cancel_space_exit_finalize!(model, 'active_path 已回到空间内部')
      refresh_workspace_toolbar(model)
      log("已修复空间退出临界状态：#{item['number']}:#{item['name']} / #{reason}")
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      log_exception('修复空间退出临界状态失败', e)
      false
    end

    def schedule_space_exit_finalize!(state, item, entity, model = Sketchup.active_model, reason: 'active_path changed')
      return false unless state && item && entity && entity.valid? && model
      @space_exit_finalize_records ||= {}
      @space_exit_finalize_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(6)
      record = {
        token: token, space_id: item['id'].to_s, stable_nil_frames: 0, attempts: 0,
        started_at: monotonic_seconds, reason: reason.to_s
      }
      @space_exit_finalize_records[key] = record
      @space_exit_finalize_tokens[key] = token

      tick = nil
      tick = lambda do
        next unless @space_exit_finalize_tokens[key] == token
        next unless model && model == Sketchup.active_model
        current_state = load_state(model)
        current_item = space_model_record(current_state, record[:space_id])
        current_entity = current_item ? space_model_entity(current_item['id'], model) : nil
        unless current_item && current_entity && current_entity.valid?
          cancel_space_exit_finalize!(model, '空间实体已失效')
          next
        end

        path = Array(model.active_path).select { |node| node && node.valid? }
        record[:attempts] = record[:attempts].to_i + 1
        if path.empty?
          # 一旦确认已经退到世界根，参考空间根立即恢复原生锁；显隐仍等 3 帧稳定后
          # 统一恢复。这样卡片刷新/锁监视器没有窗口把几十个参考空间误判成“修改锁失效”。
          restore_space_isolation_reference_locks!(current_item, model) if record[:stable_nil_frames].to_i.zero?
          record[:stable_nil_frames] = record[:stable_nil_frames].to_i + 1
          if record[:stable_nil_frames].to_i >= SPACE_EXIT_STABLE_NIL_FRAMES
            @space_exit_finalize_records.delete(key)
            @space_exit_finalize_tokens.delete(key)
            log("空间退出 active_path 已稳定为空：#{current_item['number']}:#{current_item['name']} / #{record[:stable_nil_frames]} 帧 / #{record[:reason]}")
            finish_space_edit_context_exit!(current_state, current_item, current_entity, model)
          else
            runtime_start_timer(
              SPACE_EXIT_STABLE_INTERVAL, false, label: 'space:exit_stable_nil',
              key: "space:exit_stable_nil:#{key}", model: model, active_model_only: true
            ) { tick.call }
          end
          next
        end

        # 任何一帧重新进入当前空间，都说明 SketchUp 的退出动作尚未真正完成。
        # 此时绝不能锁根；若旧版本已经留下 locked+inside 的坏状态，则立即解锁自愈。
        if active_path_inside_space?(current_entity, model)
          if space_world_root_exit_latch_for?(model, current_item['id'])
            record[:stable_nil_frames] = 0
            force_space_world_root_exit_if_needed!(model, reason: '退出稳定确认期间 active_path 回流')
            runtime_start_timer(
              SPACE_EXIT_STABLE_INTERVAL, false, label: 'space:exit_stable_nil',
              key: "space:exit_stable_nil:#{key}", model: model, active_model_only: true
            ) { tick.call }
          else
            heal_liminal_space_edit_context!(current_state, current_item, current_entity, model, reason: '退出稳定确认期间 active_path 回流')
          end
        else
          cancel_space_exit_finalize!(model, "active_path 转入其它上下文 depth=#{path.length}")
        end
      rescue StandardError => e
        cancel_space_exit_finalize!(model, '稳定确认异常')
        log_exception('确认空间退出 active_path 稳定状态失败', e)
      end

      runtime_start_timer(
        SPACE_EXIT_STABLE_INTERVAL, false, label: 'space:exit_stable_nil',
        key: "space:exit_stable_nil:#{key}", model: model, active_model_only: true
      ) { tick.call }
      true
    rescue StandardError => e
      log_exception('安排空间退出稳定确认失败', e)
      false
    end

    # ModelObserver 只调用这个调度入口；真正的锁定和提示在回调结束后的空闲帧执行。
    def space_active_path_changed(model = Sketchup.active_model)
      return if soft_commit_world_context_active?(model)
      return false if publish_critical_section? || publish_post_quiet?
      return false if @soft_thumbnail_rendering
      return false unless model
      sync_workspace_locked_selection_color!(model)
      return false unless workspace_ready?(nil, model)
      @space_active_path_change_tokens ||= {}
      @workspace_last_active_path_depth ||= {}
      @workspace_last_active_path_space_id ||= {}
      @workspace_escape_suppress_until ||= {}
      key = model.object_id
      current_path = Array(model.active_path).select { |node| node && node.valid? }
      current_depth = current_path.length
      current_root = current_path.first
      current_root_space_id = if current_root && current_root.respond_to?(:get_attribute)
                                current_root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
                              else
                                ''
                              end
      previous_depth = @workspace_last_active_path_depth[key]
      previous_root_space_id = @workspace_last_active_path_space_id[key].to_s
      @workspace_last_active_path_depth[key] = current_depth
      @workspace_last_active_path_space_id[key] = current_root_space_id
      # v0.13.6.98：即使退层来自 SketchUp 原生“关闭组件”而不是 LinkHub Tool 的 ESC，
      # 只要 active_path 深度确实下降，也给临时 Tool 一个短暂停挂窗口。这样原生退层
      # 后不会被同一鼠标位置上的 Overlay/双击桥在下一拍立刻重新 push_tool 干扰。
      if !previous_depth.nil? && current_depth < previous_depth.to_i
        @workspace_escape_suppress_until[key] = [@workspace_escape_suppress_until[key].to_f, monotonic_seconds + WORKSPACE_ESCAPE_POST_SUPPRESS_SECONDS].max
        clear_workspace_escape_transient_tools!(model)
        log("检测到原生 active_path 退层：#{previous_depth} -> #{current_depth}；临时 Tool 短暂停挂")
        if current_depth.zero?
          begin
            tracked = @space_edit_contexts && @space_edit_contexts[key]
            exit_state = load_state(model)
            exit_space_id = previous_root_space_id
            exit_space_id = tracked[:space_id].to_s if exit_space_id.empty? && tracked.is_a?(Hash)
            exit_space_id = exit_state['space_editing_id'].to_s if exit_space_id.empty?
            arm_space_world_root_exit_latch!(model, exit_space_id, source: "原生 active_path #{previous_depth}->0") unless exit_space_id.empty?
          rescue StandardError => e
            log_exception('记录空间世界根退出意图失败', e)
          end
        end
      end
      token = SecureRandom.hex(6)
      @space_active_path_change_tokens[key] = token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.06, false) do
        next unless @space_active_path_change_tokens[key] == token
        # v0.13.6.165：先阻止 SketchUp 原生双击直接钻进六面代理/受管家具。
        # 正常 LinkHub 单件家具编辑会话已经登记，因此不会命中这里。
        next if guard_native_soft_furniture_entry!(model)
        handle_soft_individual_edit_active_path_change(model)
        handle_space_active_path_change(model)
        handle_architecture_model_active_path_change(model)
        handle_architecture_active_path_change(model)
      rescue StandardError => e
        log_exception('处理空间/建筑编辑层级变化失败', e)
      end
      true
    rescue StandardError
      false
    end

    def active_path_inside_architecture_model?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid? && model
      path = Array(model.active_path)
      !path.empty? && path.first == entity
    rescue StandardError
      false
    end

    # 多建筑使用与室内空间一致的编辑上下文跟踪。ESC 只退出到全模审阅，
    # 不释放修改占用；之后可再次双击进入，发布只允许由 LinkHub 发布按钮触发。
    def enter_architecture_model_edit_context!(item, entity, model = Sketchup.active_model)
      return false unless item && entity && entity.valid? && model
      @architecture_model_edit_contexts ||= {}
      key = model.object_id
      @architecture_model_edit_contexts[key] = {
        architecture_id: item['id'].to_s,
        inside: true,
        transitioning: true
      }
      return true if active_path_inside_architecture_model?(entity, model)
      unless model.active_path.nil?
        @architecture_model_edit_contexts.delete(key)
        return false
      end
      model.selection.clear
      model.selection.add(entity)
      model.active_path = [entity] if model.respond_to?(:active_path=)
      inside = active_path_inside_architecture_model?(entity, model)
      if inside
        @architecture_model_edit_contexts[key][:transitioning] = false
      else
        @architecture_model_edit_contexts.delete(key)
      end
      inside
    rescue StandardError => e
      @architecture_model_edit_contexts&.delete(model.object_id) if model
      log_exception('自动进入建筑模型组件失败', e)
      false
    end

    def handle_architecture_model_active_path_change(model = Sketchup.active_model)
      return false unless model && workspace_ready?(nil, model)
      return false if @shutting_down || @architecture_explicit_publish_in_progress
      state = load_state(model)
      return false unless architecture_collection_active?(state, model)
      @architecture_model_edit_contexts ||= {}
      key = model.object_id
      record = @architecture_model_edit_contexts[key]
      active_root = Array(model.active_path).first
      active_architecture_id = if active_root && active_root.respond_to?(:get_attribute)
                                 active_root.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
                               else
                                 ''
                               end
      if !active_architecture_id.empty?
        candidate = architecture_model_record(state, active_architecture_id)
        if candidate && local_architecture_model_edit_session?(candidate, state, model)
          state['architecture_editing_id'] = active_architecture_id
          save_state(state, model, write_manifest: false)
          record ||= { architecture_id: active_architecture_id, inside: true, transitioning: false }
        end
      end
      architecture_id = record ? record[:architecture_id].to_s : state['architecture_editing_id'].to_s
      return false if architecture_id.empty?
      item = architecture_model_record(state, architecture_id)
      entity = item ? architecture_model_entity(architecture_id, model) : nil
      unless item && entity && entity.valid?
        @architecture_model_edit_contexts.delete(key)
        return false
      end

      if active_path_inside_architecture_model?(entity, model)
        @architecture_model_edit_contexts[key] = { architecture_id: architecture_id, inside: true, transitioning: false }
        refresh_workspace_toolbar(model)
        return true
      end

      tracked_exit = record && record[:inside]
      recovered_exit = record.nil? && local_architecture_model_edit_session?(item, state, model)
      return false unless tracked_exit || recovered_exit
      return false unless model.active_path.nil?

      lock = space_lock_info(item, model, state: state)
      unless lock['exists'] && !lock['stale'] && lock['owned']
        operation_started = false
        model.start_operation("保护未发布建筑 #{architecture_display_name(item, state)}", true)
        operation_started = true
        entity.locked = true if entity.respond_to?(:locked=)
        entity.set_attribute(ENTITY_DICT, 'editing', false)
        restore_architecture_model_isolation!(item, model)
        clear_space_lock_state!(item)
        item['editing'] = false
        item['status'] = '本地修改未发布 · 协作占用失效'
        state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == architecture_id
        save_state(state, model, write_manifest: false)
        model.commit_operation
        operation_started = false
        clear_edit_root_protection!(edit_root_key_for_architecture_model(architecture_id), model)
        @native_lock_state_cache ||= {}
        @native_lock_state_cache[[model.object_id, edit_root_key_for_architecture_model(architecture_id)]] = true
        @architecture_model_edit_contexts.delete(key)
        refresh_dialog
        show_status("#{architecture_display_name(item, state)} 占用已失效；本地内容保留，已安全锁定。", 'error')
        return false
      end

      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      item['editing'] = true
      item['status'] = '修改中 · 已退出组件查看全模'
      state['architecture_editing_id'] = architecture_id
      save_state(state, model, write_manifest: false)
      @architecture_model_edit_contexts.delete(key)
      refresh_dialog
      refresh_workspace_toolbar(model)
      show_status("已退出到全模；#{architecture_display_name(item, state)} 占用保留。双击继续，顶部按钮发布。", 'info')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      log_exception('识别建筑模型编辑层级失败', e)
      false
    end

    def handle_space_active_path_change(model = Sketchup.active_model)
      return false unless model
      return false unless workspace_ready?(nil, model)
      return false if @shutting_down || @space_publish_in_progress || @space_explicit_publish_in_progress
      @space_edit_contexts ||= {}
      key = model.object_id
      record = @space_edit_contexts[key]
      state = load_state(model)
      return false if @space_force_recovery_restoring
      placement = linked_space_copy_record(model)
      if placement
        placement_entity = placement[:entity]
        if placement_entity && placement_entity.valid? && Array(model.active_path).first == placement_entity
          begin
            @space_force_recovery_restoring = true
            model.active_path = nil unless model.active_path.nil?
          ensure
            @space_force_recovery_restoring = false
          end
          placement_entity.locked = false if placement_entity.respond_to?(:locked=)
          model.selection.clear
          model.selection.add(placement_entity)
          show_status('联动空间命名前不可进入；定位完成后点顶部对勾。', 'info')
          refresh_workspace_toolbar(model)
          return true
        end
      end
      # v0.13.6.100：如果上一拍已经明确退出到世界根，但 active_path 又回流到同一空间，
      # 不再进入下面的“恢复 editing / 临界状态自愈”分支，直接把路径压回 nil。
      if space_world_root_exit_latch(model)
        if force_space_world_root_exit_if_needed!(model, reason: 'ModelObserver 发现退出后回流')
          return true
        end
      end
      force_item = space_force_recovery_record(state)
      if force_item
        force_entity = space_model_entity(force_item['id'], model)
        if force_entity && force_entity.valid? && active_path_inside_space?(force_entity, model)
          @space_force_recovery_models ||= {}
          @space_force_recovery_models[model.object_id] = force_item['id'].to_s
          refresh_workspace_toolbar(model)
          return true
        end
        if model.active_path.nil?
          finish_space_force_recovery!(force_item['id'], model, reason: '退出强制解锁空间')
          return true
        end
        return false
      end
      active_root = Array(model.active_path).first
      active_space_id = if active_root && active_root.respond_to?(:get_attribute)
                          active_root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
                        else
                          ''
                        end
      if !active_space_id.empty?
        candidate = space_model_record(state, active_space_id)
        if candidate && local_space_edit_session?(candidate, state, model)
          new_space_entry = !record.is_a?(Hash) || record[:space_id].to_s != active_space_id || record[:inside] != true
          state['space_editing_id'] = active_space_id
          save_state(state, model, write_manifest: false)
          record ||= { space_id: active_space_id, inside: true, transitioning: false }
          schedule_space_edit_edge_rendering_optimization!(active_space_id, model) if new_space_entry
        elsif candidate
          # 原生解锁后如果用户在锁监控下一拍之前就双击进入，也不能形成一个没有
          # LinkHub 协作占用的“偷跑编辑”上下文。立即退回根层级并锁回；待更新时明确要求先更新。
          candidate_entity = space_model_entity(candidate['id'], model)
          latest_for_edit = candidate_entity && candidate_entity.valid? && space_ready_for_normal_edit?(candidate, candidate_entity, model)
          begin
            @space_force_recovery_restoring = true
            model.active_path = nil unless model.active_path.nil?
          ensure
            @space_force_recovery_restoring = false
          end
          candidate_entity.locked = true if candidate_entity && candidate_entity.valid? && candidate_entity.respond_to?(:locked=)
          @native_lock_state_cache ||= {}
          @native_lock_state_cache[space_native_cache_key(model, candidate['id'])] = true
          if latest_for_edit
            show_status("#{candidate['number']}:#{candidate['name']} 已阻止直接进入；请先点“修改”取得占用。", 'info')
          else
            show_status("#{candidate['number']}:#{candidate['name']} 不是最新发布版；请先更新。历史取物可用“强制解锁”。", 'error')
          end
          refresh_workspace_toolbar(model)
          return false
        end
      end
      space_id = record ? record[:space_id].to_s : state['space_editing_id'].to_s
      return false if space_id.empty?
      item = space_model_record(state, space_id)
      entity = item ? space_model_entity(space_id, model) : nil
      unless item && entity && entity.valid?
        @space_edit_contexts.delete(key)
        return false
      end

      if active_path_inside_space?(entity, model)
        # v0.13.6.98：ESC 稳定退层事务期间 active_path 可能短暂仍在旧深度。
        # 此时只维持合法编辑态，不执行任何会重新隔离/重新武装临时 Tool 的 UI 收尾；
        # 由退层 driver 在下一空闲帧继续推进到目标深度。
        if workspace_escape_transition_active?(model)
          cancel_space_exit_finalize!(model, 'ESC 稳定退层进行中')
          heal_liminal_space_edit_context!(state, item, entity, model, reason: 'ESC 稳定退层进行中')
          @space_edit_contexts[key] = { space_id: space_id, inside: true, transitioning: true }
          return true
        end
        # 只要 active_path 仍在当前空间里，任何“退出收尾”都必须取消。
        # 若旧版本/竞态已经形成 locked + inside 的临界状态，则先把当前根恢复为合法编辑态。
        cancel_space_exit_finalize!(model, 'active_path 仍在当前空间')
        heal_liminal_space_edit_context!(state, item, entity, model, reason: 'ModelObserver 检测到 locked+inside')
        # ESC 审阅后用户也可以直接双击空间重新进入。此时恢复原来的聚焦显示，
        # 保证“参考已隐藏”的状态与视口真实情况一致。
        if record.nil? && item['editing'] && (!item['isolation_snapshot'].is_a?(Hash) || item['isolation_snapshot'].empty?)
          operation_started = false
          model.start_operation("继续进入空间 #{item['number']}:#{item['name']}", true, false, true)
          operation_started = true
          isolate_space_for_edit!(item, entity, model, state: state)
          item['status'] = item['edit_references_visible'] ? '修改中 · 参考模型已显示' : '修改中 · 参考模型已隐藏'
          save_state(state, model, write_manifest: false)
          model.commit_operation
          operation_started = false
        end
        @space_edit_contexts[key] = { space_id: space_id, inside: true, transitioning: false }
        refresh_dialog if record.nil?
        refresh_workspace_toolbar(model)
        return true
      end

      # 从空间内部退回根层级只切换到全模审阅；进入另一个嵌套上下文时先等待。
      tracked_exit = record && record[:inside]
      recovered_exit = record.nil? && item['editing'] && !entity_native_locked?(entity)
      return false unless tracked_exit || recovered_exit
      return false unless model.active_path.nil?
      # 第一次观察到 nil 只代表“准备退出”。必须跨多个空闲帧确认 active_path
      # 持续为空，再恢复世界视图；正常退出只改变编辑上下文，不改变当前代/真显示。
      schedule_space_exit_finalize!(state, item, entity, model, reason: 'ModelObserver observed nil')
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      log_exception('识别空间编辑层级失败', e)
      false
    end

    def finish_space_edit_context_exit!(state, item, entity, model = Sketchup.active_model)
      return false unless state && item && entity && entity.valid? && model
      unless model.active_path.nil?
        log("拒绝空间退出收尾：active_path 尚未真正回到模型根 / depth=#{Array(model.active_path).length} / #{item['number']}:#{item['name']}")
        heal_liminal_space_edit_context!(state, item, entity, model, reason: 'finish guard detected non-nil path') if active_path_inside_space?(entity, model)
        return false
      end
      @space_context_exit_handling ||= {}
      key = model.object_id
      return false if @space_context_exit_handling[key]
      @space_context_exit_handling[key] = true
      lock = space_lock_info(item, model)
      unless lock['exists'] && !lock['stale'] && lock['owned']
        # 本地几何仍完整保留，但失去协作占用后绝不能继续保持根组件解锁，
        # 否则用户可能在根层级误改，同时误以为之后仍可安全覆盖共享文件。
        operation_started = false
        model.start_operation("保护未发布空间 #{item['number']}:#{item['name']}", true)
        operation_started = true
        entity.locked = true if entity.respond_to?(:locked=)
        entity.set_attribute(ENTITY_DICT, 'editing', false)
        entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
        restore_space_isolation!(item, model)
        clear_space_lock_state!(item)
        item['editing'] = false
        item['status'] = '本地修改未发布 · 协作占用失效'
        state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
        state['space_edit_display_mode'] = ''
        save_state(state, model, write_manifest: false)
        model.commit_operation
        operation_started = false
        @native_lock_state_cache ||= {}
        @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
        @space_edit_contexts&.delete(key)
        refresh_dialog
        refresh_workspace_toolbar(model)
        show_status("#{space_ui_label(item)} 占用已失效；修改保留并已锁定。请重新点“修改”后再发布。", 'error')
        return false
      end

      # v0.13.6.131：如果这一轮只是误双击/查看，退出时直接回到进入前状态。
      # 轻量 change session 已经在进入后开始记录真正的模型事务；这里复用发布按钮
      # 原本就有的“未修改快速结束”判定。只有确认没有内容变化、没有待生成家具代理、
      # 且共享源仍可验证时才自动锁回并释放占用。任何不确定情况都继续保留原来的
      # “全局预览 + 待发布”安全路径，不替用户猜测。
      unchanged_target = auto_relocate(item['model_path'].to_s, model)
      if space_edit_content_unchanged?(item, entity, unchanged_target, model)
        finished = finish_unmodified_space_edit_session!(
          state, item, entity, unchanged_target, model,
          reason: :exit, preserve_representation: true, notify: true
        )
        schedule_space_world_root_exit_latch_release!(model, item['id']) if space_world_root_exit_latch_for?(model, item['id'])
        return finished
      end

      # 进入空间到正式发布是一段连续编辑会话。只有确认发生过修改或无法安全证明
      # “完全没改”时，退出组件才恢复到全模审阅并继续保留协作占用。
      # 保留协作占用、根组件解锁状态以及当前代/真表示；用户可直接观察软硬装关系，
      # 也可双击同一空间继续修改。最终发布才统一生成/切换代理并锁根。
      operation_started = false
      @space_exit_commit_in_progress ||= {}
      @space_exit_commit_in_progress[key] = true
      model.start_operation("切换空间到全局预览 #{item['number']}:#{item['name']}", true, false, true)
      operation_started = true
      restore_space_isolation!(item, model)
      clear_space_publish_pending!(item)
      if !model.active_path.nil? && active_path_inside_space?(entity, model)
        model.active_path = nil
      end
      raise '退出收尾期间 active_path 再次进入其它编辑上下文，已停止切换全局预览。' unless model.active_path.nil?
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      clear_space_safe_pause!(item, entity)
      item['editing'] = true
      item['status'] = '修改中 · 全局预览 · 保持当前显示'
      state['space_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_started = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      @space_edit_contexts&.delete(key)
      if @soft_designer_dialog && @soft_designer_dialog.visible?
        @soft_designer_dialog.close
      end
      refresh_dialog
      refresh_workspace_toolbar(model)
      pending_count = soft_pending_proxy_records_for_space(item, entity, model).length
      if pending_count.positive?
        # v0.13.6.151：用户在单件家具退出确认里选择默认“否”时，只保存真模型并继续工作；
        # 真正离开整个空间后再把本空间所有待处理家具一次性生成/切回代理。
        # 这和“是=当前这一款立即更新”形成清晰的快/慢两条路径。
        schedule_soft_pending_proxy_exit_batch!(model, delay: 0.20, scope_space_id: item['id'].to_s)
      end
      proxy_note = pending_count.positive? ? "；#{pending_count} 件家具正在统一更新代理" : ''
      show_status("#{item['number']}:#{item['name']} 已退出编辑，保留解锁与协作占用#{proxy_note}；双击继续，发布时锁定。", 'info')
      schedule_space_world_root_exit_latch_release!(model, item['id']) if space_world_root_exit_latch_for?(model, item['id'])
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      log_exception('ESC 后退出空间查看全模失败', e)
      show_status("未能退出空间查看全模：#{e.message}", 'error')
      false
    ensure
      @space_exit_commit_in_progress[key] = false if defined?(key) && @space_exit_commit_in_progress
      @space_context_exit_handling[key] = false if defined?(key) && @space_context_exit_handling
    end

    # v0.13.6.18：普通编辑与“强制解锁取物”彻底分成两条状态机。
    # 普通编辑必须证明当前已载入实体就是共享目录的最新、且已通过当前快照验证；
    # 强制解锁从不取得协作锁，也永远不能发布，只允许临时进入本机已载入的历史内容。
    def space_force_recovery_active?(item, state = nil)
      return false unless item.is_a?(Hash) && item['force_recovery_active'] == true
      return true unless state.is_a?(Hash)
      force_id = state['space_force_recovery_id'].to_s
      force_id.empty? || force_id == item['id'].to_s
    rescue StandardError
      false
    end

    def space_force_recovery_record(state)
      return nil unless state.is_a?(Hash)
      force_id = state['space_force_recovery_id'].to_s
      item = force_id.empty? ? nil : space_model_record(state, force_id)
      item ||= Array(state['space_models']).find { |candidate| candidate.is_a?(Hash) && candidate['force_recovery_active'] == true }
      item && item['force_recovery_active'] == true ? item : nil
    rescue StandardError
      nil
    end

    # v0.13.6.146：SelectionObserver 只需要决定顶部按钮样式，不需要每次单击
    # 都去共享空间 SKP 做 File.stat/签名比较。这里仅比较已载入实体和本机 state 中保存的
    # 最近权威签名；真正点击“修改”时 space_edit_latest_preflight! 仍会访问共享文件严格校验。
    def space_ready_for_normal_edit_cached?(item, entity, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && entity && entity.valid?
      return false if space_force_recovery_active?(item)
      return false if initial_space_publish_pending?(item) || background_publish_active_state?(item)
      local = entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s rescue ''
      expected = item['last_signature'].to_s
      expected = item['source_signature'].to_s if expected.empty?
      return false if local.empty? || expected.empty?
      normalize_fast_signature(local) == normalize_fast_signature(expected)
    rescue StandardError
      false
    end

    def space_ready_for_normal_edit?(item, entity, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && entity && entity.valid?
      return false if space_force_recovery_active?(item)
      source = auto_relocate(item['model_path'].to_s, model)
      snapshot = space_status_file_snapshot(source)
      return false unless snapshot[:exists] == true && !snapshot[:signature].to_s.empty?
      direction = space_update_direction(
        item, entity, source,
        remote_signature: snapshot[:signature].to_s,
        remote_mtime: (snapshot[:signature].to_s.split('|', 2).first.to_f rescue nil)
      )
      direction == :same
    rescue StandardError
      false
    end

    def space_edit_latest_preflight!(item, entity, model = Sketchup.active_model)
      raise '找不到空间记录。' unless item.is_a?(Hash)
      raise '空间尚未载入，请先更新。' unless entity && entity.valid?
      raise '该空间正处于强制解锁恢复模式；请先结束强制解锁并恢复进入前状态。' if space_force_recovery_active?(item)
      source = auto_relocate(item['model_path'].to_s, model)
      raise '空间源文件不存在，普通修改已禁止；如仅需从当前历史模型取物，可使用“强制解锁”。' unless File.file?(source)
      remote_signature = fast_file_signature(source)
      raise '无法读取共享空间文件签名，普通修改已禁止；请检查网络盘后重试。' if remote_signature.to_s.empty?
      remote_revision = space_authoritative_revision(item, source, actual_signature: remote_signature)
      direction = space_update_direction(
        item, entity, source,
        remote_signature: remote_signature,
        remote_mtime: (File.mtime(source).to_f rescue nil)
      )
      case direction
      when :newer
        raise "#{item['number']}:#{item['name']} 有新发布版本尚未载入。必须先点击“更新”载入最新模型后才能修改；若只需从当前历史模型取物，请使用“强制解锁”。"
      when :older
        raise "#{item['number']}:#{item['name']} 的共享版本比当前已载入模型更旧，版本关系异常。为避免覆盖，普通修改已禁止；仅历史取物可使用“强制解锁”，且不能发布。"
      when :unknown
        raise "无法确认 #{item['number']}:#{item['name']} 是否为最新版本。为避免旧模型覆盖新模型，普通修改已禁止；请先更新/核对版本，或仅用“强制解锁”取物。"
      end
      raise '空间尚未通过最新载入验证，必须先执行一次更新。' unless direction == :same
      verify_loaded_space_snapshot!(entity, remote_revision, remote_signature)
      # 发布文件已成功替换、进程却在安全快照与清单收尾之间中断时，v124 只修复了
      # 清单。此时当前实体、包 revision、文件签名均已完整验证为同一新版，可安全
      # 补齐旧安全快照；否则普通外部漂移仍由后面的严格检查继续阻止。
      repair_verified_space_safe_checkpoint_gap!(
        item, entity, source, remote_revision, remote_signature
      )
      assert_latest_safe_checkpoint_consistent!(source, "space_#{item['id']}", "空间 #{item['number']}:#{item['name']}")
      snapshot = space_source_snapshot_signature(source)
      raise '无法稳定验证共享空间文件内容，普通修改已禁止；请检查网络盘后重试。' if snapshot.to_s.empty?
      {
        source: source,
        signature: remote_signature.to_s,
        revision: remote_revision.to_s,
        snapshot: snapshot.to_s
      }
    end

    def verify_space_edit_preflight_unchanged!(item, entity, preflight, model = Sketchup.active_model)
      raise '编辑前置验证信息缺失。' unless preflight.is_a?(Hash)
      source = preflight[:source].to_s
      raise '空间源文件在进入编辑期间消失，已取消修改。' unless File.file?(source)
      signature = fast_file_signature(source)
      snapshot = space_source_snapshot_signature(source)
      if signature.to_s.empty? || snapshot.to_s.empty? ||
         signature.to_s != preflight[:signature].to_s || snapshot.to_s != preflight[:snapshot].to_s
        raise '在取得编辑占用期间共享空间版本发生了变化。已取消进入修改，请先更新到最新模型。'
      end
      direction = space_update_direction(
        item, entity, source,
        remote_signature: signature,
        remote_mtime: (File.mtime(source).to_f rescue nil)
      )
      raise '取得编辑占用后版本验证不再为最新，已取消修改；请先更新。' unless direction == :same
      verify_loaded_space_snapshot!(entity, preflight[:revision].to_s, signature)
      true
    end

    def space_force_recovery_directory(model = Sketchup.active_model)
      base = ENV['LOCALAPPDATA'].to_s
      base = File.join(Dir.tmpdir, 'SU_LinkHub_Local') if base.empty?
      project_token = Digest::SHA1.hexdigest(space_update_project_identity(model))[0, 12]
      dir = File.join(base, 'SU_LinkHub', 'force_recovery', project_token)
      FileUtils.mkdir_p(dir)
      dir
    end

    def primitive_entity_dictionary_snapshot(entity, dictionary = ENTITY_DICT)
      result = {}
      dict = entity.attribute_dictionary(dictionary, false) if entity && entity.respond_to?(:attribute_dictionary)
      return result unless dict
      dict.each do |key, value|
        case value
        when String, Numeric, TrueClass, FalseClass, NilClass
          result[key.to_s] = value
        end
      end
      result
    rescue StandardError
      {}
    end

    def create_space_force_recovery_snapshot!(item, entity, model = Sketchup.active_model)
      raise '空间实例不可用，无法建立强制解锁快照。' unless entity && entity.valid? && entity.respond_to?(:definition)
      definition = entity.definition
      raise '空间定义不可用，无法建立强制解锁快照。' unless definition && definition.valid?
      safe_name = safe_space_filename("#{item['number']}_#{item['name']}")
      stamp = Time.now.strftime('%Y%m%d_%H%M%S')
      path = File.join(space_force_recovery_directory(model), "#{safe_name}_force_#{stamp}_#{SecureRandom.hex(3)}.skp")
      saved = definition.respond_to?(:save_copy) ? definition.save_copy(path) : definition.save_as(path)
      raise '无法创建强制解锁进入前快照。' unless saved != false && File.file?(path) && File.size(path).positive?
      signature = full_file_content_signature(path)
      raise '强制解锁快照完整性验证失败。' if signature.to_s.empty?
      prefix = File.join(space_force_recovery_directory(model), "#{safe_name}_force_*.skp")
      Dir.glob(prefix).sort_by { |candidate| File.mtime(candidate) rescue Time.at(0) }.reverse_each.with_index do |candidate, index|
        File.delete(candidate) if index >= 3 && File.file?(candidate)
      rescue StandardError
        next
      end
      [path, signature]
    end

    def clear_space_force_recovery_state!(state, item, entity = nil)
      return false unless item.is_a?(Hash)
      item['force_recovery_active'] = false
      item['force_recovery_snapshot_path'] = ''
      item['force_recovery_snapshot_signature'] = ''
      item['force_recovery_started_at'] = ''
      item['force_recovery_original_locked'] = true
      item['force_recovery_original_hidden'] = false
      item['force_recovery_original_name'] = ''
      item['force_recovery_original_transform'] = []
      item['force_recovery_original_attrs'] = {}
      item['force_recovery_original_representation'] = 'full'
      state['space_force_recovery_id'] = '' if state.is_a?(Hash) && state['space_force_recovery_id'].to_s == item['id'].to_s
      entity.delete_attribute(ENTITY_DICT, 'force_recovery') if entity && entity.valid? && entity.respond_to?(:delete_attribute)
      @space_force_recovery_models ||= {}
      @space_force_recovery_models.delete_if { |_model_key, active_id| active_id.to_s == item['id'].to_s }
      true
    rescue StandardError
      false
    end

    def begin_space_force_recovery!(space_id, model = Sketchup.active_model)
      raise '发布或更新正在进行，请等待完成后再强制解锁。' if publish_critical_section? || @updating || @single_space_update_job
      raise '请先退出当前组件编辑层级，再使用强制解锁。' unless model.active_path.nil?
      state = ensure_space_models_ready!(model)
      existing_force = space_force_recovery_record(state)
      if existing_force
        return finish_space_force_recovery!(existing_force['id'], model, reason: '再次点击强制解锁') if existing_force['id'].to_s == space_id.to_s
        raise "已有空间 #{existing_force['number']}:#{existing_force['name']} 处于强制解锁恢复模式，请先结束它。"
      end
      if local_pending_space_records(state, model).any? || local_pending_architecture_records(state, model).any?
        raise '当前已有未发布修改。请先发布或取消修改，不能与强制解锁恢复模式并行。'
      end
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      raise '该空间仍在后台发布中，不能进入强制解锁恢复模式。' if background_publish_active_state?(item)
      if initial_space_publish_pending?(item)
        raise '该空间尚未完成首次发布，没有可作为“历史已发布版”的恢复基线；请先重试首次发布或删除本地待发布空间。'
      end
      entity = space_model_entity(item['id'], model)
      raise '该空间当前没有已载入的本机模型，无法强制解锁；请先正常载入，或从备份恢复。' unless entity && entity.valid?
      raise '该空间已有正常 LinkHub 编辑会话，不能改用强制解锁。' if local_space_edit_session?(item, state, model)

      warning = <<~TEXT
        强制解锁只用于从“当前本机已载入的历史/旧空间”中复制、找回模型。

        · 不取得协同修改占用；
        · 不把当前旧模型视为最新；
        · 强制解锁期间禁止发布；
        · 退出空间（ESC）或再次点击“强制解锁”后，会恢复到进入前快照；
        · 在该空间内部做的移动、删除、修改都会被丢弃。

        你可以在空间内复制需要找回的对象，退出恢复后再粘贴到安全位置。

        是否继续？
      TEXT
      return false unless native_confirm_yes?(warning)

      snapshot_path, snapshot_signature = create_space_force_recovery_snapshot!(item, entity, model)
      item['force_recovery_active'] = true
      item['force_recovery_snapshot_path'] = snapshot_path.to_s
      item['force_recovery_snapshot_signature'] = snapshot_signature.to_s
      item['force_recovery_started_at'] = Time.now.iso8601(6)
      item['force_recovery_original_locked'] = entity_native_locked?(entity)
      item['force_recovery_original_hidden'] = entity.respond_to?(:hidden?) ? entity.hidden? : false
      item['force_recovery_original_name'] = entity.respond_to?(:name) ? entity.name.to_s : ''
      item['force_recovery_original_transform'] = entity.respond_to?(:transformation) ? entity.transformation.to_a.map(&:to_f) : []
      item['force_recovery_original_attrs'] = primitive_entity_dictionary_snapshot(entity, ENTITY_DICT)
      item['force_recovery_original_representation'] = entity.get_attribute(ENTITY_DICT, 'space_representation', 'full').to_s == 'proxy' ? 'proxy' : 'full'
      item['status'] = '强制解锁 · 历史取物 · 禁止发布'
      state['space_force_recovery_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)

      operation_started = false
      model.start_operation("强制解锁空间 #{item['number']}:#{item['name']}", true, false, true)
      operation_started = true
      entity.locked = false if entity.respond_to?(:locked=)
      # 恢复模式只解锁空间根，不批量改写内层锁；内层定义可能被其他空间共享，
      # 不能为了历史取物把共享定义中的锁状态一起改掉。
      entity.set_attribute(ENTITY_DICT, 'force_recovery', true)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      model.selection.clear
      model.selection.add(entity)
      model.commit_operation
      operation_started = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      @space_force_recovery_models ||= {}
      @space_force_recovery_models[model.object_id] = item['id'].to_s
      model.active_path = [entity] if model.respond_to?(:active_path=)
      unless active_path_inside_space?(entity, model)
        finish_space_force_recovery!(item['id'], model, reason: '自动进入失败')
        raise '未能进入强制解锁空间，已恢复进入前状态。'
      end
      refresh_dialog
      refresh_workspace_toolbar(model)
      show_status("#{item['number']}:#{item['name']} 已强制解锁，仅供历史取物；禁止发布，ESC 后自动恢复。", 'info')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      begin
        recovery_state = load_state(model)
        recovery_item = space_model_record(recovery_state, space_id)
        finish_space_force_recovery!(space_id, model, reason: '强制解锁启动失败自动恢复') if recovery_item && space_force_recovery_active?(recovery_item, recovery_state)
      rescue StandardError => recovery_error
        log_exception('强制解锁启动失败后的自动恢复也失败', recovery_error)
      end
      raise e
    end

    def restore_space_force_recovery_snapshot!(state, item, entity, model = Sketchup.active_model)
      path = item['force_recovery_snapshot_path'].to_s
      expected = item['force_recovery_snapshot_signature'].to_s
      raise '强制解锁恢复快照路径丢失；为防止错误覆盖，已停止恢复。' unless File.file?(path)
      actual = full_file_content_signature(path)
      raise '强制解锁恢复快照已损坏或被改写；为防止错误恢复，已停止。' if actual.to_s.empty? || actual.to_s != expected
      raise '空间根实例已经不存在，无法自动恢复强制解锁快照。' unless entity && entity.valid? && entity.respond_to?(:definition=)

      original_transform = Array(item['force_recovery_original_transform']).map(&:to_f)
      original_attrs = item['force_recovery_original_attrs'].is_a?(Hash) ? item['force_recovery_original_attrs'].dup : {}
      original_hidden = !!item['force_recovery_original_hidden']
      original_name = item['force_recovery_original_name'].to_s
      revision = "force-restore|#{Digest::SHA1.hexdigest(expected)[0, 12]}|#{SecureRandom.hex(3)}"
      definition, = load_space_definition_collision_safe!(path, item, revision, model)
      raise '未能载入强制解锁进入前快照。' unless definition && definition.valid?
      entity.definition = definition
      if original_transform.length == 16
        entity.transformation = Geom::Transformation.new(original_transform)
      end
      entity.hidden = original_hidden if entity.respond_to?(:hidden=)
      entity.name = original_name if entity.respond_to?(:name=)
      if entity.respond_to?(:attribute_dictionary) && entity.respond_to?(:delete_attribute)
        current_dict = entity.attribute_dictionary(ENTITY_DICT, false)
        current_keys = []
        current_dict.each { |key, _value| current_keys << key.to_s } if current_dict
        current_keys.each { |key| entity.delete_attribute(ENTITY_DICT, key) }
      end
      original_attrs.each { |key, value| entity.set_attribute(ENTITY_DICT, key.to_s, value) }
      entity.set_attribute(ENTITY_DICT, 'force_recovery', false)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      entity.locked = true if entity.respond_to?(:locked=)
      invalidate_managed_root_index(model, reason: 'force_recovery_restore')
      mark_soft_measurement_dirty(model, item['id'])
      true
    end

    def finish_space_force_recovery!(space_id, model = Sketchup.active_model, reason: '结束强制解锁')
      return false if @space_force_recovery_restoring
      state = load_state(model)
      item = space_model_record(state, space_id)
      return false unless item && space_force_recovery_active?(item, state)
      entity = space_model_entity(item['id'], model)
      @space_force_recovery_restoring = true
      operation_started = false
      if !model.active_path.nil?
        model.active_path = nil
        raise '未能退出强制解锁空间层级，恢复已停止。' unless model.active_path.nil?
      end
      model.start_operation("恢复强制解锁前空间 #{item['number']}:#{item['name']}", true, false, true)
      operation_started = true
      restore_space_force_recovery_snapshot!(state, item, entity, model)
      clear_space_force_recovery_state!(state, item, entity)
      item['status'] = "已恢复强制解锁前状态 · #{reason}"
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_started = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
      refresh_dialog
      refresh_workspace_toolbar(model)
      show_status("#{item['number']}:#{item['name']} 已恢复强制解锁前快照；临时修改未保留。", 'success')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      begin
        entity = space_model_entity(space_id, model)
        entity.locked = true if entity && entity.valid? && entity.respond_to?(:locked=)
      rescue StandardError
        nil
      end
      log_exception('恢复强制解锁前空间失败', e)
      show_status("强制解锁恢复失败：#{e.message}。该空间已锁定且仍禁止发布，请保留本机恢复快照并联系检查。", 'error')
      raise
    ensure
      @space_force_recovery_restoring = false
    end

    def recover_interrupted_space_force_recovery!(model = Sketchup.active_model)
      state = load_state(model)
      item = space_force_recovery_record(state)
      return false unless item
      entity = space_model_entity(item['id'], model)
      unless entity && entity.valid?
        show_status("检测到 #{item['number']}:#{item['name']} 上次强制解锁未正常结束，但空间根实例不存在；该空间保持禁止发布，请从本机恢复快照处理。", 'error')
        return false
      end
      finish_space_force_recovery!(item['id'], model, reason: '启动时自动恢复上次未结束的强制解锁')
    rescue StandardError => e
      log_exception('启动时恢复强制解锁状态失败', e)
      false
    end

    def begin_space_edit_state!(state, item, entity, model = Sketchup.active_model, unlock: true, preflight: nil)
      if @soft_visual_proxy_upgrade_job && @soft_visual_proxy_upgrade_job[:foreground_exit_batch]
        raise '刚退出工作空间的六面代理正在统一前台生成；请等待本批次完成后再重新进入空间。'
      end
      # 先验证目标并取得目标空间锁，再暂存当前编辑焦点。这样目标空间若在等待锁的
      # 窗口里刚好被别人发布，不会先把用户当前合法的另一空间编辑会话切走。
      switched_focus = false
      preflight_ready = preflight.is_a?(Hash) && !preflight[:source].to_s.empty?
      # edit_space_model 已完成清单同步、遗留任务恢复和最新版本预检。沿用同一份
      # state/item/entity，避免双击进入时马上把项目状态和安全快照再读一遍。
      state = load_state(model) unless preflight_ready && state.is_a?(Hash)
      item = space_model_record(state, item['id'])
      entity = space_model_entity(item['id'], model)
      raise '空间根组件不可用，无法进入修改。' unless item && entity && entity.valid?
      if linked_space_record?(item)
        source = canonical_space_record(state, item)
        source_name = source ? source['name'].to_s : item['linked_source_name'].to_s
        raise "该空间联动于（#{source_name}），请修改来源空间；联动空间只保留独立名称、位置、旋转、缩放与镜像。"
      end
      unless preflight_ready
        clear_orphan_background_publish_state!(item, model, state)
        state = load_state(model)
        item = space_model_record(state, item['id'])
        entity = space_model_entity(item['id'], model)
      end
      raise '该空间正在后台发布，发布完成前不能再次进入修改。' if background_publish_active_state?(item)
      safe_resume = space_edit_safe_paused?(item)
      new_edit_change_session = !item['editing'] && !entity.get_attribute(ENTITY_DICT, 'editing', false)
      started_at = Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f
      stage_started_at = started_at
      stage_times = {}
      acquired_here = false
      source = preflight_ready ? preflight[:source].to_s : auto_relocate(item['model_path'].to_s, model)
      raise '空间源文件不存在。' unless File.file?(source)
      assert_latest_safe_checkpoint_consistent!(source, "space_#{item['id']}", "空间 #{item['number']}:#{item['name']}") unless preflight_ready
      stage_times[:source] = (((Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f) - stage_started_at) * 1000.0).round
      stage_started_at = Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f

      lock = space_lock_info(item, model, source_path: source, state: state)
      unless lock['exists'] && !lock['stale'] && lock['owned']
        lock_path = edit_lock_path_for(source)
        previous_lock_record = read_lock_record(lock_path)
        acquired_record = acquire_space_lock!(item, source, state)
        # “继续”可能只是接回当前进程原来的同一把锁。只有真的创建/替换成新 token
        # 才算 acquired_here；否则后续进入上下文失败时不能把原本保留的协作占用释放掉。
        acquired_here = previous_lock_record.nil? ||
                        previous_lock_record['token'].to_s != acquired_record['token'].to_s
        lock = space_lock_info(item, model, source_path: source, state: state)
      end
      stage_times[:lock] = (((Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f) - stage_started_at) * 1000.0).round
      stage_started_at = Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f
      # 取得协作锁之后再做一次同一份源文件快照验证，封住“检查最新 -> 等待锁 -> 远端刚好发布”窗口。
      preflight ||= space_edit_latest_preflight!(item, entity, model)
      verify_space_edit_preflight_unchanged!(item, entity, preflight, model)

      switched_focus = prepare_edit_focus_switch!(edit_root_key_for_space(item['id']), model)
      state = load_state(model)
      item = space_model_record(state, item['id'])
      entity = space_model_entity(item['id'], model)
      raise '切换编辑焦点后目标空间根组件不可用，已取消修改。' unless item && entity && entity.valid?
      # acquire_space_lock! 修改的是预检阶段那份 state。切换焦点会重新 load_state，
      # 必须把已验证的同一把锁带回新 item；否则令牌会丢失，后续监视器不断恢复锁，
      # 卡片显示“修改锁失效”，还会把恢复状态的事务误判为用户修改。
      apply_space_lock_record_to_item!(item, lock, actor_role: lock['actor_role'].to_s)

      # 进入修改时只继承代/真偏好，不再遍历全部空间执行定义替换。
      # 其他联动根模型马上隐藏，本就不会参与当前编辑；代/真转换仅在用户
      # 明确点击切换、更新或发布时运行，避免轻模型也因定义扫描和模型库 I/O 卡顿。
      state['space_edit_display_mode'] = state['space_display_mode'].to_s unless state['space_editing_id'].to_s == item['id'].to_s && %w[proxy full].include?(state['space_edit_display_mode'].to_s)
      close_space_publish_dialog(item['id'], :resume_edit) if item['publish_pending']
      clear_space_publish_pending!(item)
      # 继续安全暂存时必须同时清掉 item + 实体两份 safe_paused 标记。
      # 也无条件执行一次，用来自动修复 0.13.5.6/0.13.5.7 已留下的幽灵标记。
      clear_space_safe_pause!(item, entity)
      model.start_operation("修改空间 #{item['number']}:#{item['name']}", true)
      # 从全局预览重新进入同一空间时，不再遍历其它空间，也不再恢复/替换家具 Definition。
      # 当前表示从进入到发布保持原样，重复进出只切换 active_path 与隔离可见性。
      inactive_proxy_changed = 0
      package_depth_before_edit = space_publish_wrapper_chain_depth(entity.definition)
      if package_depth_before_edit.positive?
        entity = normalize_loaded_space_instance!(entity, entity.definition, model)
        log("进入空间前已自动拆平历史发布包裹层：#{item['number']}:#{item['name']} / #{package_depth_before_edit} 层")
      end

      # v0.13.6.92 编辑沙箱顺序：
      # 1) 已取得 LinkHub 协作锁后先解锁当前根；
      # 2) 根 Definition 若仍被其它实例共享，先 make_unique，保证后面的 explode 只改当前空间；
      # 3) 先清旧版内部锁，再拆 PACKAGE/PAYLOAD（旧锁不再挡住空壳修复）；
      # 4) 空壳拆完后沿唯一编辑脊柱按“是否共享”继续 make_unique，而不是只看直接 locked?。
      entity.locked = false if unlock && entity.respond_to?(:locked=)
      root_definition_isolated = make_space_edit_node_unique_if_lock_conflict!(entity, '空间根编辑沙箱', model)
      # 0.13.6.91 的回归点：把整个编辑脊柱的“普通 Definition 共享”当成硬失败，
      # 导致新建空空间也可能完全无法进入。0.13.6.92 只在“空间根自身仍有有效锁传播”时
      # 阻止进入；这是进入根组件时唯一会立即触发原生三选一的必要硬保护。
      root_lock_conflict = space_edit_definition_lock_conflict?(entity)
      root_instance_count = space_edit_definition_instances(entity.definition).length rescue -1
      log("空间根进入前锁诊断：#{item['number']}:#{item['name']} / definition=#{definition_identity_key(entity.definition)} / instances=#{root_instance_count} / conflict=#{root_lock_conflict}")
      if root_lock_conflict
        raise '当前空间根仍存在锁定 occurrence 传播，LinkHub 无法安全进入。已保持其它实例锁定，不会执行“全部解锁”。请重新载入该空间后再试。'
      end
      internal_unlock_count = clear_space_internal_native_locks!(item, entity, model)
      shell_repair = repair_redundant_empty_shells!(
        entity, model, context: "空间 #{item['number']}:#{item['name']}"
      )
      definition_isolation = isolate_space_edit_definition_spine!(entity, model)
      if definition_isolation.is_a?(Hash) && definition_isolation[:remaining_lock_conflicts].to_i.positive?
        detail = Array(definition_isolation[:remaining_lock_nodes]).first(4).map do |row|
          "L#{row[:depth]} #{row[:name].to_s.empty? ? '(未命名)' : row[:name]}"
        end.join('、')
        log("空间进入前仍有内部锁传播诊断项，允许进入根并交由核心层双击桥继续隔离：#{detail}")
      end
      # explode / make_unique 后再扫一次，处理历史壳内部原本不可达的锁。
      post_shell_unlock_count = clear_space_internal_native_locks!(item, entity, model)
      internal_unlock_count += post_shell_unlock_count.to_i
      # 进入也不再因为内存里恰好有真模型缓存而自动替换 Definition；当前看到什么
      # 就保持什么，用户明确点“真模型/代理”或正式发布时才转换。
      resident_restore = { matched: 0, skipped: true }
      isolate_space_for_edit!(item, entity, model, state: state) unless item['editing'] && item['isolation_snapshot'].is_a?(Hash) && !item['isolation_snapshot'].empty?
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      item['editing'] = true
      item['last_signature'] = fast_file_signature(source) if item['last_signature'].to_s.empty?
      reference_label = item['edit_references_visible'] ? '参考模型已显示' : '参考模型已隐藏'
      item['status'] = "修改中 · #{reference_label}"
      state['space_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      capture_edit_root_protection!(edit_root_key_for_space(item['id']), entity, model)
      stage_times[:isolate] = (((Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f) - stage_started_at) * 1000.0).round
      stage_started_at = Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      entered = enter_space_edit_context!(item, entity, model)
      stage_times[:enter] = (((Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f) - stage_started_at) * 1000.0).round
      elapsed = (((Process.clock_gettime(Process::CLOCK_MONOTONIC) rescue Time.now.to_f) - started_at) * 1000.0).round
      log("空间修改快速入口：#{item['number']}:#{item['name']} / #{elapsed}ms / 路径#{stage_times[:source]} 锁#{stage_times[:lock]} 隔离#{stage_times[:isolate]} 进入#{stage_times[:enter]} / LinkHub修改按钮")
      if entered
        start_or_resume_space_edit_change_session!(
          item, entity, model, new_session: new_edit_change_session
        )
        message = if safe_resume
                    "#{item['number']}:#{item['name']} 已继续未发布修改；本地内容与协作占用均保持不变。"
                  elsif switched_focus
                    "已安全暂存上一编辑焦点，并进入 #{item['number']}:#{item['name']}；旧修改未发布、未丢失。"
                  else
                    "#{item['number']}:#{item['name']} 已进入 LinkHub 空间根；退出后保持当前显示与解锁编辑态，发布时统一切代理并锁定。"
                  end
        message += " 已自动清理 #{internal_unlock_count} 个旧的空间内部锁。" if internal_unlock_count.to_i.positive?
        if defined?(shell_repair) && shell_repair.is_a?(Hash) && shell_repair[:count].to_i.positive?
          message += " 已自动折叠 #{shell_repair[:count].to_i} 层无语义空壳。"
        end
        isolation_count = (defined?(definition_isolation) && definition_isolation.is_a?(Hash) ? definition_isolation[:count].to_i : 0)
        isolation_count += 1 if defined?(root_definition_isolated) && root_definition_isolated
        if isolation_count.positive?
          message += " 已建立当前空间独立编辑沙箱（隔离 #{isolation_count} 层共享Definition），避免锁定实例弹窗。"
        end
        if defined?(resident_restore) && resident_restore.is_a?(Hash) && resident_restore[:matched].to_i.positive?
          message += " 已从会话缓存恢复 #{resident_restore[:matched].to_i} 个家具真模；未命中缓存的继续代理，不访问模型库。"
        end
        if defined?(inactive_proxy_changed) && inactive_proxy_changed.to_i.positive?
          message += " 其它软装空间已自动回代理。"
        end
        show_status(message, 'success')
      else
        # 自动进入失败时绝不能把空间根留在整个 SKP 根层级的解锁状态。
        # 保留协作占用和本地内容，但立即切到安全暂存，下一次点“继续”再尝试进入。
        state = load_state(model)
        item = space_model_record(state, item['id'])
        entity = space_model_entity(item['id'], model)
        if item && entity && entity.valid?
          model.start_operation("保护未进入的空间 #{item['number']}:#{item['name']}", true, false, true)
          restore_space_isolation!(item, model)
          entity.locked = true if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', true)
          entity.set_attribute(ENTITY_DICT, 'safe_paused', true)
          item['editing'] = true
          item['edit_safe_paused'] = true
          item['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
          item['edit_safe_pause_reason'] = '自动进入空间失败'
          item['status'] = '未发布修改已安全暂存 · 自动进入失败'
          state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
          state['space_edit_display_mode'] = ''
          save_state(state, model, write_manifest: false)
          model.commit_operation
          @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
        end
        show_status("未能进入空间根；已自动锁回并暂存。请点“继续”重试。", 'error')
      end
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { refresh_dialog }
      true
    rescue StandardError
      model.abort_operation rescue nil
      release_space_lock!(item, source, model: model, state: state) if acquired_here && item && !source.to_s.empty?
      raise
    end

    def switch_workspace_and_edit_space!(space_id, model = Sketchup.active_model)
      # 真正进入修改的 edit_space_model 会做一次完整共享清单与版本预检；这里仅用
      # 当前模型缓存判断目标工作区，避免同一次双击连续执行两遍共享目录同步。
      state = cached_project_state_readonly(model) || load_state(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      target_role = space_record_collection_key(item)
      raise '该模型不是硬装或软装空间。' unless space_workspace_role?(target_role)
      current_role = host_discipline_for(state)
      log("空间编辑入口已执行：#{space_id} / #{workspace_role_label(current_role)} -> #{workspace_role_label(target_role)}")
      if current_role != target_role
        set_host_discipline_value_fast(target_role, model, notify: false)
        log("跨工作区进入空间修改：#{workspace_role_label(current_role)} -> #{workspace_role_label(target_role)} / #{item['number']}:#{item['name']}")
      end
      edit_space_model(space_id)
    end

    def edit_space_model_with_workspace_prompt(space_id, model = Sketchup.active_model)
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      target_role = space_record_collection_key(item)
      raise '该模型不是硬装或软装空间。' unless space_workspace_role?(target_role)
      current_role = host_discipline_for(state)
      if current_role != target_role
        current_label = workspace_role_label(current_role)
        target_label = workspace_role_label(target_role)
        prompt = <<~TEXT
          当前位于#{current_label}工作区。
          “#{space_ui_label(item)}”属于#{target_label}工作区。

          是否切换到#{target_label}工作区并进入修改？

          切换只改变当前工作区焦点；其它空间的未发布修改与本机协作占用会继续保留。
        TEXT
        return false unless native_confirm_yes?(prompt)
      end
      switch_workspace_and_edit_space!(space_id, model)
    end

    def edit_space_model(space_id)
      model = Sketchup.active_model
      log("空间编辑预检开始：#{space_id}")
      # 每次真正进入修改前都重新读取共享空间清单；顶部按钮是否可点只是体验层，
      # 这里才是不可绕过的安全边界。
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      clear_orphan_background_publish_state!(item, model, state)
      item = space_model_record(state, item['id']) || item
      raise '该空间仍在后台发布中；正式共享发布完成并释放占用后才能重新修改。' if background_publish_active_state?(item)
      if initial_space_publish_pending?(item)
        raise '该空间尚未完成首次发布；首次发布完成前不能进入修改。请点击“重试/发布”，或删除本地待发布空间。'
      end
      host_key = host_discipline_for(state)
      raise '请先切换到该空间所属的硬装或软装工作区再修改。' unless space_workspace_role?(host_key) && space_record_collection_key(item) == host_key
      entity = space_model_entity(space_id, model)
      raise '空间尚未载入，请先更新。' unless entity && entity.valid?
      preflight = space_edit_latest_preflight!(item, entity, model)
      log("空间编辑预检通过：#{item['number']}:#{item['name']} / #{space_id}")
      begin_space_edit_state!(state, item, entity, model, unlock: true, preflight: preflight)
    end

    def sync_native_architecture_model_lock_state!(state, model = Sketchup.active_model)
      return false if @architecture_explicit_publish_in_progress
      changed = false
      @native_lock_state_cache ||= {}
      Array(state['architecture_models']).each do |item|
        entity = architecture_model_entity(item['id'], model)
        cache_key = [model.object_id, edit_root_key_for_architecture_model(item['id'])]
        unless entity && entity.valid?
          @native_lock_state_cache.delete(cache_key)
          next
        end
        locked = entity_native_locked?(entity)
        previous = @native_lock_state_cache[cache_key]
        @native_lock_state_cache[cache_key] = locked
        local_flag = item['editing'] || state['architecture_editing_id'].to_s == item['id'].to_s ||
                     entity.get_attribute(ENTITY_DICT, 'editing', false)
        if previous.nil?
          next if locked && !local_flag
        else
          next if previous == locked
        end

        if !locked
          # 热重载/重启插件时 native cache 会丢失，但合法的 LinkHub 编辑会话可能仍在。
          # 只有“本地编辑标记 + 当前有效且归本工作区所有的协作锁”同时成立才保留解锁；
          # 其余原生解锁一律回锁，避免误点右键解锁就创建/伪装成协作编辑。
          owned_lock = local_flag ? space_lock_info(item, model, state: state) : {}
          valid_linkhub_session = local_flag && owned_lock['exists'] && !owned_lock['stale'] && owned_lock['owned']
          if valid_linkhub_session
            entity.set_attribute(ENTITY_DICT, 'editing', true)
            item['editing'] = true
            @native_lock_state_cache[cache_key] = false
            next
          end
          entity.locked = true if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', false)
          @native_lock_state_cache[cache_key] = true
          item['editing'] = false
          state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
          item['status'] = '已阻止原生解锁 · 请使用 LinkHub 修改'
          changed = true
          show_status("#{architecture_display_name(item, state)} 已自动重新锁定；请点击 LinkHub“修改”取得协作占用。", 'info')
        else
          next if space_edit_safe_paused?(item)
          had_edit = previous == false || local_flag
          next unless had_edit
          lock = space_lock_info(item, model, state: state)
          unless lock['exists'] && !lock['stale'] && lock['owned']
            item['editing'] = false
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
            item['status'] = '已锁定 · 未取得协同占用'
            changed = true
            next
          end
          # v0.13.0：右键原生“锁定”不再代表发布。误锁建筑根时自动恢复解锁，
          # 真正发布只允许走 LinkHub 发布按钮，由插件按 architecture_id 锁定正确根层级。
          entity.locked = false if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', true)
          entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
          item['editing'] = true
          item['status'] = '待发布 · 请使用 LinkHub 发布按钮'
          @native_lock_state_cache[cache_key] = false
          changed = true
          show_status("#{architecture_display_name(item, state)} 仍保持修改；请使用 LinkHub 发布按钮提交。", 'info')
        end
      end
      changed
    rescue StandardError => e
      log_exception('同步建筑模型原生锁定状态失败', e)
      false
    end

    def sync_native_space_lock_state!(state, model = Sketchup.active_model)
      return false if @space_publish_in_progress || @space_explicit_publish_in_progress
      changed = false
      @native_lock_state_cache ||= {}
      Array(state['space_models']).each do |item|
        entity = space_model_entity(item['id'], model)
        cache_key = space_native_cache_key(model, item['id'])
        unless entity && entity.valid?
          @native_lock_state_cache.delete(cache_key)
          next
        end
        locked = entity_native_locked?(entity)
        previous = @native_lock_state_cache[cache_key]
        @native_lock_state_cache[cache_key] = locked

        # v0.13.6.156：联动空间没有独立共享 SKP/协作锁，它的根层解锁只允许发生在
        # “实例调整”事务中。155 虽然双击后正确 entity.locked=false，但下一拍这里仍把
        # 它当成普通空间的非法原生解锁，执行版本检查并重新锁定，于是顶部绿勾出现却
        # Move/Rotate/Scale 全部不可用。联动空间在这里走独立状态机，不参与普通空间
        # 的协作锁判断。
        if linked_space_record?(item)
          if linked_space_transform_adjustment_active?(item, entity, model)
            if locked && entity.respond_to?(:locked=)
              entity.locked = false
            end
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            @native_lock_state_cache[cache_key] = false
          else
            unless locked
              entity.locked = true if entity.respond_to?(:locked=)
            end
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            @native_lock_state_cache[cache_key] = true
          end
          next
        end

        if space_reference_root_temporarily_unlocked?(item, entity, state, model)
          if locked
            entity.locked = false if entity.respond_to?(:locked=)
            @native_lock_state_cache[cache_key] = false
          end
          next
        end
        if space_reference_root_exit_transition?(item, entity, state, model)
          unless locked
            entity.locked = true if entity.respond_to?(:locked=)
          end
          @native_lock_state_cache[cache_key] = true
          next
        end
        if space_force_recovery_active?(item, state)
          # 强制解锁是唯一允许没有协作锁却保持空间根解锁的状态；原生“锁定”也不能
          # 把它误转成发布流程，直接恢复为解锁，直到 ESC/强制解锁按钮触发快照恢复。
          if locked
            entity.locked = false if entity.respond_to?(:locked=)
            @native_lock_state_cache[cache_key] = false
          end
          entity.set_attribute(ENTITY_DICT, 'editing', false)
          entity.set_attribute(ENTITY_DICT, 'force_recovery', true)
          next
        end
        local_flag = item['editing'] || state['space_editing_id'].to_s == item['id'].to_s || entity.get_attribute(ENTITY_DICT, 'editing', false)
        if previous.nil?
          next if locked && !local_flag
        else
          next if previous == locked
        end

        if !locked
          # 原生右键“解锁”不再隐式取得协作占用。热重载时 cache 可能为空，所以
          # 先验证是否真的是 LinkHub 已建立且仍归本工作区所有的合法编辑会话；合法
          # 会话保持解锁，其他情况立即回锁。
          owned_lock = local_flag ? space_lock_info(item, model, state: state) : {}
          valid_linkhub_session = local_flag && owned_lock['exists'] && !owned_lock['stale'] && owned_lock['owned']
          if valid_linkhub_session
            entity.set_attribute(ENTITY_DICT, 'editing', true)
            item['editing'] = true
            @native_lock_state_cache[cache_key] = false
            next
          end
          entity.locked = true if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', false)
          @native_lock_state_cache[cache_key] = true
          item['editing'] = false
          clear_space_publish_pending!(item)
          state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
          if background_publish_active_state?(item)
            item['status'] = '后台发布中 · 已阻止原生解锁'
            changed = true
            show_status("#{item['number']}:#{item['name']} 正在后台发布；已锁定，可继续其它空间。", 'info')
            next
          elsif initial_space_publish_pending?(item)
            item['status'] = '首次发布待完成 · 已阻止原生解锁'
            changed = true
            show_status("#{item['number']}:#{item['name']} 首次发布未完成；已锁定，请重试发布或删除待发布空间。", 'info')
            next
          end
          source_for_guard = auto_relocate(item['model_path'].to_s, model)
          latest_for_edit = File.file?(source_for_guard) && space_update_direction(item, entity, source_for_guard) == :same
          if latest_for_edit
            item['status'] = '已阻止原生解锁 · 请使用 LinkHub 修改'
            message = "#{item['number']}:#{item['name']} 已自动重新锁定；普通修改必须使用 LinkHub“修改”取得协作占用。"
          else
            item['status'] = '已阻止原生解锁 · 必须先更新最新模型'
            message = "#{item['number']}:#{item['name']} 当前不是已验证的最新版本，已自动重新锁定。请先更新/载入最新模型；若仅需从历史模型取物，请使用顶部“强制解锁”。"
          end
          changed = true
          show_status(message, 'info')
        else
          next if space_edit_safe_paused?(item)
          had_edit = previous == false || local_flag
          next unless had_edit
          lock = space_lock_info(item, model)
          unless lock['exists'] && !lock['stale'] && lock['owned']
            item['editing'] = false
            clear_space_publish_pending!(item)
            clear_space_safe_pause!(item, entity)
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
            item['status'] = '已锁定 · 未取得协同占用'
            changed = true
            next
          end
          # 原生右键“锁定”只视为误操作并立即恢复，不触发隐式发布。
          # LinkHub 发布按钮会自动退出任何嵌套层级、找到正确 space_id 根组件、上传并最终锁定它。
          entity.locked = false if entity.respond_to?(:locked=)
          entity.set_attribute(ENTITY_DICT, 'editing', true)
          entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
          item['editing'] = true
          item['status'] = '待发布 · 请使用 LinkHub 发布按钮'
          @native_lock_state_cache[cache_key] = false
          changed = true
          show_status("#{item['number']}:#{item['name']} 仍保持修改；请使用 LinkHub 发布按钮提交。", 'info')
        end
      end
      changed
    rescue StandardError => e
      log_exception('同步空间原生锁定状态失败', e)
      false
    end

    def arm_space_publish_confirmation!(state, item, entity, model = Sketchup.active_model, show_dialog: true)
      mark_space_publish_pending_state!(item)
      entity.set_attribute(ENTITY_DICT, 'editing', false) if entity && entity.valid?
      save_state(state, model, write_manifest: false)
      refresh_dialog
      open_space_publish_confirmation(item['id'], model) if show_dialog
      true
    end

    # SketchUp 在退出组件编辑上下文时，可能才真正完成父定义的自动唯一化/身份刷新。
    # 这在“空间内创建组合组件 -> 复制多个实例 -> 进入组合实例移动/旋转子家具”时尤其常见。
    # 旧流程在 LinkHub 发布按钮中先删除编辑上下文跟踪，再 model.active_path=nil；如果
    # Definition 身份恰好在这一步变化，发布前结构校验已经处于根层级，无法再证明这是
    # 一次正常的上下文退出，于是会误报“设为唯一/替换定义”并阻止发布。
    #
    # 这里严格只接受“插件主动退出 active_path 的同步瞬间”发生的定义身份变化：
    # - 根实例必须仍是同一个 persistent_id / 对象；
    # - 根容器类型不能变化；
    # - 根实例 transformation 在开始编辑以来、以及退出前后都不能变化；
    # - Definition 必须确实是在 active_path=nil 这一句前后才发生变化。
    # 任何用户事先主动替换定义、移动/旋转空间根、嵌套/复制根组件，仍由原结构检查阻止。
    def rebase_protected_definition_after_publish_context_exit!(key, entity, before_definition, before_definition_key, before_transform, model = Sketchup.active_model)
      return false unless model && entity && entity.valid?
      @edit_root_protections ||= {}
      record = @edit_root_protections[[model.object_id, key.to_s]]
      return false unless record.is_a?(Hash)

      current_pid = entity_persistent_key(entity)
      same_root = (record[:entity] && entity.equal?(record[:entity])) ||
                  (current_pid.positive? && current_pid == record[:entity_pid].to_i)
      return false unless same_root

      current_class = entity.is_a?(Sketchup::Group) ? 'group' : 'component'
      return false unless current_class == record[:entity_class].to_s

      current_transform = entity.respond_to?(:transformation) ? entity.transformation.to_a.map(&:to_f) : []
      return false unless same_transformation_array?(before_transform, record[:transformation])
      return false unless same_transformation_array?(current_transform, before_transform)

      current_definition = entity.respond_to?(:definition) ? entity.definition : nil
      return false unless current_definition && current_definition.valid?
      current_key = definition_identity_key(current_definition)
      changed_during_exit = !current_definition.equal?(before_definition) || current_key != before_definition_key.to_s
      return false unless changed_during_exit

      # 如果进入退出动作之前就已经与保护基线不同，说明变化不是这次 LinkHub 主动
      # 退出造成的，不能自动吞掉；仍交给后面的交互式结构校验判断。
      baseline_definition = record[:definition]
      baseline_key = record[:definition_key].to_s
      before_matches_baseline = if baseline_definition && baseline_definition.respond_to?(:valid?) && baseline_definition.valid?
                                  before_definition && (before_definition.equal?(baseline_definition) || before_definition == baseline_definition)
                                else
                                  !baseline_key.empty? && before_definition_key.to_s == baseline_key
                                end
      return false unless before_matches_baseline

      return false unless rebind_protected_definition!(entity, record)
      record[:publish_context_exit_rebased_at] = monotonic_time
      record[:publish_context_exit_from_definition_key] = before_definition_key.to_s
      record[:publish_context_exit_to_definition_key] = current_key.to_s
      log("发布主动退出组件层级时检测到 SketchUp 自动刷新根定义身份，已安全重绑保护基线：#{key} / #{before_definition_key} -> #{current_key}")
      true
    rescue StandardError => e
      log_exception('发布主动退出后重绑根定义保护失败', e)
      false
    end

    def exit_protected_root_context_for_publish!(key, entity, model = Sketchup.active_model)
      return true unless model
      return true if model.active_path.nil?
      path = Array(model.active_path)
      return false unless entity && entity.valid? && !path.empty? && path.first == entity

      before_definition = entity.respond_to?(:definition) ? entity.definition : nil
      before_definition_key = definition_identity_key(before_definition)
      before_transform = entity.respond_to?(:transformation) ? entity.transformation.to_a.map(&:to_f) : []
      model.active_path = nil
      raise 'LinkHub 未能自动退出当前组件层级，发布已取消。' unless model.active_path.nil?
      rebase_protected_definition_after_publish_context_exit!(
        key, entity, before_definition, before_definition_key, before_transform, model
      )
      true
    end

    # 只有明确点击 LinkHub“发布”才会结束空间修改并写共享 SKP。这里在退出 active_path
    # 之前先立守卫，防止 ModelObserver 把主动退出误判为一次 ESC 审阅。
    def prepare_explicit_publish_root_context!(target_kind, target_id, state, model = Sketchup.active_model)
      return true unless model
      path = Array(model.active_path)
      return true if path.empty?
      root = path.first
      protected_exit_key = ''
      protected_exit_entity = nil
      if root && root.respond_to?(:get_attribute)
        active_space_id = root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
        active_architecture_id = root.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
        if !active_space_id.empty? && target_kind.to_s == 'space' && active_space_id == target_id.to_s
          # 当前目标空间：保留退出前的 Definition 身份证据，active_path=nil 后只允许
          # 对“退出瞬间”发生的 SketchUp 自动定义刷新做安全重绑。
          protected_exit_key = edit_root_key_for_space(active_space_id)
          protected_exit_entity = root
          @space_edit_contexts&.delete(model.object_id)
        elsif !active_space_id.empty?
          active_item = space_model_record(state, active_space_id)
          if active_item && local_space_edit_session?(active_item, state, model)
            restore_space_isolation!(active_item, model)
            clear_space_publish_pending!(active_item)
            active_item['editing'] = true
            active_item['status'] = '待发布'
            state['space_editing_id'] = '' if state['space_editing_id'].to_s == active_space_id
            @space_edit_contexts&.delete(model.object_id)
          end
        elsif !active_architecture_id.empty? && target_kind.to_s == 'architecture_model' && active_architecture_id == target_id.to_s
          protected_exit_key = edit_root_key_for_architecture_model(active_architecture_id)
          protected_exit_entity = root
          @architecture_model_edit_contexts&.delete(model.object_id)
        elsif !active_architecture_id.empty?
          active_item = architecture_model_record(state, active_architecture_id)
          if active_item && local_architecture_model_edit_session?(active_item, state, model)
            restore_architecture_model_isolation!(active_item, model)
            active_item['editing'] = true
            active_item['status'] = '待发布'
            state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == active_architecture_id
            @architecture_model_edit_contexts&.delete(model.object_id)
          end
        end
      end
      if protected_exit_entity && !protected_exit_key.to_s.empty?
        exited = exit_protected_root_context_for_publish!(protected_exit_key, protected_exit_entity, model)
        raise 'LinkHub 未能识别当前受管根组件，发布已取消。' unless exited
      else
        model.active_path = nil unless model.active_path.nil?
        raise 'LinkHub 未能自动退出当前组件层级，发布已取消。' unless model.active_path.nil?
      end
      save_state(state, model, write_manifest: false)
      true
    rescue StandardError => e
      log_exception('发布前自动退出组件层级失败', e)
      raise
    end

    def publish_space_now(space_id, model = Sketchup.active_model)
      guard_acquired = false
      was_inside = false
      raise '空间发布正在进行，请稍候。' if @space_explicit_publish_in_progress || @space_publish_in_progress
      raise '空间与协同组件一致性更新正在进行，请等待完成后再发布。' if @consistency_update_job
      raise '空间正在更新或恢复上一发布版，请等待完成后再发布。' if @updating || @single_space_update_job
      state = load_state(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      clear_orphan_background_publish_state!(item, model, state)
      item = space_model_record(state, item['id']) || item
      raise '该空间已经在后台发布队列中，请等待完成后再发布。' if background_publish_active_state?(item)
      raise '该空间正处于强制解锁历史取物模式，禁止发布。请先结束强制解锁并恢复进入前状态。' if space_force_recovery_active?(item, state)
      entity = space_model_entity(item['id'], model)
      raise '该空间模型尚未载入。' unless entity && entity.valid?
      target_role = space_record_collection_key(item)
      current_role = host_discipline_for(state)
      if space_workspace_role?(target_role) && current_role != target_role
        target_label = workspace_role_label(target_role)
        current_label = workspace_role_label(current_role)
        prompt = <<~TEXT
          当前位于#{current_label}工作区。
          “#{space_ui_label(item)}”属于#{target_label}工作区。

          是否直接发布这个#{target_label}空间？

          发布不会切换当前工作区；只提交这个空间并在成功后释放它的协作占用。
        TEXT
        return false unless native_confirm_yes?(prompt)
      end
      if initial_space_publish_pending?(item)
        return retry_initial_space_publish!(item['id'], model)
      end
      lock = space_lock_info(item, model, state: state)
      if lock['exists'] && !lock['owned'] && lock['same_user']
        source = auto_relocate(item['model_path'].to_s, model)
        lock = force_takeover_same_user_space_lock!(item, source, state, model, allow_current_process: true)
      end
      unless lock && lock['exists'] && !lock['stale'] && lock['owned'] && (item['editing'] || entity.get_attribute(ENTITY_DICT, 'editing', false) || !entity_native_locked?(entity))
        raise '请先点击“修改”并取得该空间的协作占用。'
      end
      was_inside = active_path_inside_space?(entity, model)
      prepare_explicit_publish_root_context!('space', item['id'], state, model)
      unless confirm_empty_definition_publish?("空间 #{item['number']}:#{item['name']}", entity.definition)
        cancel_space_publish_confirmation(item['id'], model) if item['publish_pending'] || entity_native_locked?(entity)
        return false
      end

      @space_explicit_publish_in_progress = true
      guard_acquired = true
      @space_edit_contexts&.delete(model.object_id)
      model.active_path = nil unless model.active_path.nil?
      raise '未能退出空间组件层级，发布尚未开始。' unless model.active_path.nil?
      # v0.13.6.154：发布是本轮空间工作的明确提交边界。若家具真实层级早已退出，
      # 但内存仍残留 editing/awaiting_proxy_choice，会在这里按默认“否”安全收尾；
      # 发布成功后绝不能还留下一个看不见的“真模型编辑中”幽灵会话。
      finalize_soft_individual_edit_before_space_publish!(item['id'], model)
      repair_redundant_empty_shells_operation!(
        entity, model, context: "空间 #{item['number']}:#{item['name']} 发布前"
      )
      publish_space_model(item['id'], confirm: false)
    rescue StandardError => e
      begin
        raise StopIteration unless guard_acquired
        recovery_state = load_state(model)
        recovery_item = space_model_record(recovery_state, space_id)
        recovery_entity = recovery_item ? space_model_entity(recovery_item['id'], model) : nil
        recovery_lock = recovery_item ? space_lock_info(recovery_item, model) : {}
        if recovery_item && recovery_entity && recovery_entity.valid? &&
           recovery_lock['exists'] && !recovery_lock['stale'] && recovery_lock['owned']
          recovery_entity.locked = false if recovery_entity.respond_to?(:locked=)
          recovery_entity.set_attribute(ENTITY_DICT, 'editing', true)
          clear_space_safe_pause!(recovery_item, recovery_entity)
          clear_space_publish_pending!(recovery_item)
          recovery_item['editing'] = true
          recovery_state['space_editing_id'] = recovery_item['id'].to_s
          if was_inside
            enter_space_edit_context!(recovery_item, recovery_entity, model)
          else
            restore_space_isolation!(recovery_item, model)
            recovery_item['status'] = '发布未完成 · 已保留全模审阅'
          end
          save_state(recovery_state, model, write_manifest: false)
          @native_lock_state_cache ||= {}
          @native_lock_state_cache[space_native_cache_key(model, recovery_item['id'])] = false
        end
      rescue StopIteration
        nil
      rescue StandardError => recovery_error
        log_exception('空间发布失败后恢复编辑层级失败', recovery_error)
      end
      raise e
    ensure
      @space_explicit_publish_in_progress = false if guard_acquired
      refresh_workspace_toolbar(model) rescue nil
    end

    def request_space_publish(space_id)
      model = Sketchup.active_model
      state = load_state(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      clear_orphan_background_publish_state!(item, model, state)
      item = space_model_record(state, item['id']) || item
      raise '该空间已经在后台发布队列中，请等待完成后再发布。' if background_publish_active_state?(item)
      raise '该空间正处于强制解锁历史取物模式，禁止发布；只能先恢复到强制解锁前状态。' if space_force_recovery_active?(item, state)
      raise '请先退出组件，再发布。' unless model.active_path.nil?
      entity = space_model_entity(space_id, model)
      raise '空间尚未载入。' unless entity && entity.valid?
      lock = space_lock_info(item, model)
      unless lock['exists'] && !lock['stale'] && lock['owned'] && state['space_editing_id'].to_s == item['id'].to_s
        raise '请先解锁该空间。'
      end
      if item['publish_pending'] && entity_native_locked?(entity)
        open_space_publish_confirmation(item['id'], model)
        return true
      end
      unless entity_native_locked?(entity)
        model.start_operation("锁定空间 #{item['number']}:#{item['name']}", true)
        entity.locked = true if entity.respond_to?(:locked=)
        model.commit_operation
      end
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
      arm_space_publish_confirmation!(state, item, entity, model, show_dialog: true)
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    def cancel_space_publish_confirmation(space_id, model = Sketchup.active_model)
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      return false unless item
      entity = space_model_entity(space_id, model)
      return false unless entity && entity.valid?
      lock = space_lock_info(item, model)
      unless lock['exists'] && !lock['stale'] && lock['owned']
        clear_space_publish_pending!(item)
        save_state(state, model, write_manifest: false)
        refresh_dialog
        return false
      end
      model.start_operation("继续修改空间 #{item['number']}:#{item['name']}", true)
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      clear_space_safe_pause!(item, entity)
      clear_space_publish_pending!(item)
      item['editing'] = true
      item['status'] = '修改中 · 已取消发布'
      state['space_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.selection.clear
      model.selection.add(entity)
      model.commit_operation
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      entered = enter_space_edit_context!(item, entity, model)
      refresh_dialog
      show_status(entered ? "#{item['number']}:#{item['name']} 已重新进入。" : "#{item['number']}:#{item['name']} 已继续修改；双击进入。", 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    # “暂不发布”只结束本次聚焦编辑：恢复进入修改前的联动模型可见性，
    # 保留本地修改、待发布标记和协作占用，不丢数据也不允许他人覆盖。
    def defer_space_publish_confirmation(space_id, model = Sketchup.active_model)
      state = load_state(model)
      item = space_model_record(state, space_id)
      return false unless item
      entity = space_model_entity(space_id, model)
      return false unless entity && entity.valid?
      operation_started = false
      model.start_operation("暂不发布空间 #{item['number']}:#{item['name']}", true)
      operation_started = true
      restore_space_isolation!(item, model)
      item['status'] = '本地修改已保留 · 待发布'
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_started = false
      refresh_dialog
      show_status("#{item['number']}:#{item['name']} 暂不发布；修改与占用已保留。", 'success')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      log_exception('暂不发布空间失败', e)
      show_status("暂不发布处理失败：#{e.message}", 'error')
      false
    end

    def space_publish_dialog_html(item)
      title = "#{item['number']}:#{item['name']}"
      safe_title = title.to_s.gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;').gsub('"', '&quot;')
      <<~HTML
        <!doctype html><html><head><meta charset="utf-8"><style>
        *{box-sizing:border-box}body{margin:0;background:#f7f8fa;color:#1f2937;font:13px -apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}
        .box{padding:18px}.title{font-size:15px;font-weight:750;margin-bottom:6px}.sub{font-size:12px;color:#667085;margin-bottom:18px}
        .actions{display:flex;justify-content:flex-end;gap:8px}button{height:32px;padding:0 15px;border:1px solid #d0d5dd;border-radius:8px;background:white;color:#344054;cursor:pointer;font-weight:650}button.primary{border-color:#2563eb;background:#2563eb;color:white}button:disabled{opacity:.48;cursor:default}.error{min-height:16px;margin-top:10px;color:#b42318;font-size:11px}
        </style></head><body><div class="box"><div class="title">发布“#{safe_title}”？</div><div class="sub">已退出空间编辑层级。暂不发布会恢复整体模型显示，保留本地修改并继续占用该空间。</div><div class="actions"><button onclick="deferPublish()">暂不发布</button><button id="publish" class="primary" onclick="confirmPublish()">发布</button></div><div id="error" class="error"></div></div>
        <script>
        const btn=document.getElementById('publish');
        function confirmPublish(){if(btn.disabled)return;btn.disabled=true;btn.textContent='发布中…';sketchup.confirm_publish();}
        function deferPublish(){sketchup.defer_publish();}
        function showError(message){document.getElementById('error').textContent=message||'发布失败';btn.disabled=false;btn.textContent='发布';}
        </script></body></html>
      HTML
    end

    def open_space_publish_confirmation(space_id, model = Sketchup.active_model)
      state = load_state(model)
      item = space_model_record(state, space_id)
      return false unless item && item['publish_pending']
      entity = space_model_entity(space_id, model)
      return false unless entity && entity.valid? && entity_native_locked?(entity)
      @space_publish_dialogs ||= {}
      @space_publish_dialog_actions ||= {}
      key = item['id'].to_s
      existing = @space_publish_dialogs[key]
      if existing
        existing.bring_to_front if existing.respond_to?(:bring_to_front)
        return true
      end
      dialog = UI::HtmlDialog.new(
        dialog_title: '发布空间', preferences_key: "GavinTools_SULinkHubMultiSpace_SpacePublish_#{key}",
        scrollable: false, resizable: false, width: 380, height: 196,
        min_width: 380, min_height: 196, style: UI::HtmlDialog::STYLE_DIALOG
      )
      @space_publish_dialogs[key] = dialog
      @space_publish_dialog_actions.delete(key)
      dialog.set_html(space_publish_dialog_html(item))
      dialog.add_action_callback('confirm_publish') do |_ctx|
        begin
          confirm_space_publish(key, model)
          dialog.close if dialog.visible?
        rescue StandardError => e
          log_exception('确认发布空间失败', e)
          dialog.execute_script("showError(#{JSON.generate(e.message.to_s)})") rescue nil
          show_status(e.message.to_s, 'error')
        end
      end
      dialog.add_action_callback('defer_publish') do |_ctx|
        begin
          @space_publish_dialog_actions[key] = :deferred
          defer_space_publish_confirmation(key, model)
        ensure
          dialog.close
        end
      end
      dialog.set_can_close do
        action = @space_publish_dialog_actions[key]
        if action.nil?
          @space_publish_dialog_actions[key] = :deferred
          defer_space_publish_confirmation(key, model)
        end
        true
      end
      dialog.set_on_closed do
        @space_publish_dialogs.delete(key)
        @space_publish_dialog_actions.delete(key)
      end
      dialog.show
      true
    rescue StandardError => e
      log_exception('打开空间发布确认失败', e)
      false
    end

    def confirm_space_publish(space_id, model = Sketchup.active_model)
      require_workspace_ready!(nil, model)
      publish_space_model(space_id, confirm: false)
    end

    def load_space_model_instance!(item, model = Sketchup.active_model, representation: nil, purge: true, state: nil, existing_entity: :auto, dedupe: true, invalidate_index: true, structure: nil, create_repair_snapshot: false, force_visible: false, load_path_override: '', expected_revision: '', expected_source_signature: '', expected_source_snapshot: '')
      state ||= load_state(model)
      if representation.to_s.empty?
        editing_id = state['space_editing_id'].to_s
        representation = if editing_id.empty?
                           state['space_display_mode'].to_s
                         elsif item['id'].to_s == editing_id
                           effective_space_display_mode(state)
                         else
                           'proxy'
                         end
      end
      asset = space_asset_for(item, state, model, representation: representation)
      source_path = asset[:path]
      representation = asset[:representation]
      raise '空间模型文件不存在。' unless File.file?(source_path)
      load_started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      source_signature_value = fast_file_signature(source_path)
      source_revision_value = space_authoritative_revision(item, source_path, actual_signature: source_signature_value)
      source_revision_value = "space-file|#{source_signature_value}" if source_revision_value.empty?
      unless expected_source_signature.to_s.empty?
        expected_sig = normalize_fast_signature(expected_source_signature)
        actual_sig = normalize_fast_signature(source_signature_value)
        raise '共享空间在镜像准备后又发生变化，本次已取消；请重新更新。' unless expected_sig == actual_sig
      end
      unless expected_revision.to_s.empty?
        raise '共享空间清单在镜像准备后又发生变化，本次已取消；请重新更新。' unless expected_revision.to_s == source_revision_value.to_s
      end
      unless expected_source_snapshot.to_s.empty?
        current_snapshot = space_source_snapshot_signature(source_path)
        raise '共享空间内容在镜像准备后发生变化，本次已取消；请重新更新。' unless current_snapshot == expected_source_snapshot.to_s
      end
      override = load_path_override.to_s
      path = if !override.empty? && File.file?(override) && File.size(override).positive?
               override
             else
               preferred_space_load_path(item, source_path, source_revision_value, model)
             end
      mirror_ready_at = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      stored = store_path(source_path, model)
      existing = existing_entity == :auto ? space_model_entity(item['id'], model) : existing_entity
      hidden = force_visible ? false : (existing && existing.respond_to?(:hidden?) ? existing.hidden? : false)
      # 旧工作 SU 中的定义必须在载入前退出模型定义表，否则 SketchUp 可能在
      # 解析共享 SKP 时直接复用旧定义。更新位于调用方的单一 operation 中；任何
      # 后续失败都会 abort_operation 恢复旧空间。旧验证架构首次迁移时额外创建
      # 一个本机回滚 SKP，避免异常退出后无处找回。
      previous = existing && existing.valid? ? existing : nil
      candidate = nil
      previous_verified_schema = previous ? previous.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i : 0
      if create_repair_snapshot && previous && previous_verified_schema < SPACE_LOAD_VERIFIED_SCHEMA
        create_space_update_rollback_snapshot!(item, previous, model)
      end
      retire_existing_space_before_fresh_load!(item['id'], previous, model) if previous
      definition, preexisting_definitions, collision_load_attempts = load_space_definition_collision_safe!(
        path, item, source_revision_value, model
      )
      candidate = model.entities.add_instance(definition, identity_transformation)
      definition_ready_at = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      existing = normalize_loaded_space_instance!(candidate, definition, model)
      candidate = existing
      update_shell_repair = repair_redundant_empty_shells!(
        existing, model, context: "空间 #{item['number']}:#{item['name']} 更新载入"
      )
      if update_shell_repair.is_a?(Hash) && update_shell_repair[:count].to_i.positive?
        log("空间更新载入已自动折叠历史运输壳：#{item['number']}:#{item['name']} / #{update_shell_repair[:count]} 层")
      end
      normalized_at = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      package_revision = existing.get_attribute(ENTITY_DICT, 'space_package_revision_hint', '').to_s
      package_space_id = existing.get_attribute(ENTITY_DICT, 'space_package_space_id_hint', '').to_s
      package_identity = existing.get_attribute(ENTITY_DICT, 'space_package_identity_hint', '').to_s
      package_graph_schema = existing.get_attribute(ENTITY_DICT, 'space_package_graph_schema_hint', 0).to_i
      package_graph_verified = !!existing.get_attribute(ENTITY_DICT, 'space_package_graph_verified_hint', false)
      if !package_space_id.empty? && package_space_id != item['id'].to_s
        raise "载入包属于其他空间（#{package_space_id}），已阻止错误替换。"
      end
      if !package_revision.empty? && !source_revision_value.empty? && package_revision != source_revision_value
        if recoverable_space_package_manifest_gap?(
          item, package_revision, package_space_id, source_revision_value,
          package_graph_verified: package_graph_verified
        )
          previous_revision = source_revision_value.to_s
          source_revision_value = package_revision.to_s
          item['source_revision'] = source_revision_value
          item['last_signature'] = source_signature_value
          package_time = revision_time_value(package_revision)
          item['last_publish_at'] = Time.at(package_time).iso8601(6) if package_time.positive?
          item['last_publish_plugin_version'] = EXTENSION_VERSION
          item['_manifest_package_recovery_pending'] = true
          log("空间发布收尾自动恢复：#{item['number']}:#{item['name']} / 包版本 #{package_revision} 已通过校验，将替代中断前清单 #{previous_revision}")
        else
          raise "载入包版本与共享清单不一致（包 #{package_revision} / 清单 #{source_revision_value}），已阻止虚假更新。"
        end
      end
      # 成功载入前已经执行定义碰撞探测与自动隔离。这里仅保留最后一道断言，
      # 防止 normalize 包裹层时又意外指回旧定义；不再把正常含组件的空间一律拒绝。
      reused_definitions = reused_preexisting_definitions(existing.definition, preexisting_definitions)
      unless reused_definitions.empty?
        names = reused_definitions.first(6).map { |candidate_definition| candidate_definition.name.to_s }.reject(&:empty?)
        detail = names.empty? ? reused_definitions.length.to_s : names.join('、')
        raise "空间归一化后仍指向旧组件定义（#{detail}）。更新已回滚，未写入虚假最新状态。"
      end
      if package_graph_schema.positive? && !package_graph_verified
        raise '空间发布包定义图未通过验证，已阻止把旧模型标记为最新。'
      end
      package_hint = existing.get_attribute(ENTITY_DICT, 'space_package_representation_hint', '').to_s
      package_fast = existing.get_attribute(ENTITY_DICT, 'space_fast_load_schema', 0).to_i.positive?
      # v0.9.85+ 发布包已经声明文件内部的家具表示。命中时直接跳过递归家具
      # 枚举与定义替换；旧文件或表示不一致时仍走完整兼容校验。
      representation_fast_path = package_fast && package_hint == representation
      # 即使旧空间包声明“已经是代理”，只要权威映射表里已有六面代理而包内仍是旧白盒，
      # 就不能走快速跳过。这样旧版成员发布的空间在最新版载入时会自动映射为六面代理。
      if representation == 'proxy' && representation_fast_path && space_proxy_visual_upgrade_needed?(existing, model)
        representation_fast_path = false
      end
      load_unresolved = []
      unless representation_fast_path
        unless space_soft_representation_matches?(existing, representation)
          apply_space_soft_representation!(existing, representation, model)
          load_unresolved = take_soft_proxy_switch_unresolved!(model) if representation == 'proxy'
        end
      end
      # v0.13.6.182：载入后若仍有家具不是权威六面代理（代理文件丢失/映射失效/旧白盒/
      # 因缺代理被迫保留真模型），不再等用户发现，直接在空闲窗口从模型库真模型自动重建；
      # 事务外延迟触发，避免拖慢载入。
      if representation == 'proxy' && !representation_fast_path
        request_soft_lost_proxy_auto_repair_for_space!(existing, model, space_id: item['id'].to_s, extra_instances: load_unresolved)
      end
      represented_at = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      signature = source_signature_value
      verified_identity = package_identity.to_s.empty? ? "fresh-load-#{Digest::SHA1.hexdigest(source_signature_value)[0, 16]}" : package_identity
      mark_space_model_entity!(existing, item, stored, signature, model, representation: representation, revision: source_revision_value, invalidate_index: invalidate_index, structure: structure, verified_package_revision: package_revision, verified_package_identity: verified_identity, verified_package_schema: SPACE_LOAD_VERIFIED_SCHEMA)
      verify_loaded_space_snapshot!(existing, source_revision_value, source_signature_value)
      rebase_loaded_space_shared_component_snapshots!(existing, model)
      existing.hidden = hidden if existing.respond_to?(:hidden=)
      if previous && previous.valid? && previous != existing
        previous.locked = false if previous.respond_to?(:locked=)
        previous.erase!
      end
      if dedupe
        space_model_entities(model).each do |other|
          next if other == existing
          next unless other.get_attribute(ENTITY_DICT, 'space_id', '').to_s == item['id'].to_s
          other.locked = false if other.respond_to?(:locked=)
          other.erase! if other.valid?
        rescue StandardError
          next
        end
      end
      item['model_path'] = stored
      item['last_signature'] = signature
      item['source_revision'] = source_revision_value
      item['proxy_path'] = ''
      item['proxy_signature'] = ''
      item['proxy_published_at'] = ''
      item['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['editing'] = false
      item['legacy_key'] = ''
      item['status'] = representation == 'proxy' ? '空间已载入 · 家具使用代理' : '空间已载入 · 家具使用真模型'
      sync_linked_space_instances_for_source!(state, item, existing, model) unless linked_space_record?(item)
      purge_unused_soft_definitions!(model) if purge
      finished_at = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      log(
        "空间载入性能：#{item['number']}:#{item['name']} / " \
        "镜像#{((mirror_ready_at - load_started) * 1000.0).round}ms / " \
        "SKP解析#{((definition_ready_at - mirror_ready_at) * 1000.0).round}ms / " \
        "归一#{((normalized_at - definition_ready_at) * 1000.0).round}ms / " \
        "代真#{((represented_at - normalized_at) * 1000.0).round}ms / " \
        "总计#{((finished_at - load_started) * 1000.0).round}ms / " \
        "#{same_file_path?(path, source_path) ? '源文件' : '本地镜像'} / " \
        "#{representation_fast_path ? '包标直通' : '兼容校验'} / " \
        "#{package_graph_verified ? '全层定义图验证' : '旧包干净载入验证'} / 定义载入#{collision_load_attempts}次"
      )
      schedule_space_shared_component_latest_reconcile!(item['id'].to_s, model, reason: 'space_load') rescue nil
      existing
    rescue StandardError
      begin
        candidate.locked = false if defined?(candidate) && candidate && candidate.valid? && candidate.respond_to?(:locked=)
        candidate.erase! if defined?(candidate) && candidate && candidate.valid?
      rescue StandardError
        nil
      end
      raise
    end

    def finish_single_space_update_interaction!(model = Sketchup.active_model)
      Sketchup.set_status_text('') rescue nil
      @single_space_update_job = nil
      @updating = false
      end_soft_heavy_interaction(:space_single_update)
      true
    rescue StandardError
      @single_space_update_job = nil
      @updating = false
      end_soft_heavy_interaction(:space_single_update)
      false
    end

    def schedule_complete_single_space_update!(context, mirror_results, prefetch_error: nil, attempt: 0)
      model = context[:model]
      job = @single_space_update_job
      return false unless job && job[:token].to_s == context[:token].to_s
      if Sketchup.active_model != model
        return complete_single_space_update!(context, mirror_results, prefetch_error: '活动 SketchUp 模型已经切换，空间更新已取消。')
      end

      blocked = publish_critical_section? || (model.respond_to?(:active_path) && !model.active_path.nil?)
      unless blocked
        return complete_single_space_update!(context, mirror_results, prefetch_error: prefetch_error)
      end

      if attempt.to_i.zero?
        show_status('上一发布版已缓存；退出当前组件后自动载入。', 'info') if context[:notify]
      end
      if attempt.to_i * 0.5 >= SINGLE_SPACE_UPDATE_SAFE_WAIT_SECONDS
        return complete_single_space_update!(context, mirror_results, prefetch_error: '等待安全载入超时，空间更新已取消；本地镜像已保留。')
      end
      runtime_start_timer(0.5, false, label: 'single_space_wait_safe_load') do
        schedule_complete_single_space_update!(context, mirror_results, prefetch_error: prefetch_error, attempt: attempt.to_i + 1)
      end
      true
    rescue StandardError => e
      log_exception('等待单空间安全更新失败', e)
      complete_single_space_update!(context, mirror_results, prefetch_error: e.message.to_s)
    end

    def complete_single_space_update!(context, mirror_results, prefetch_error: nil)
      model = context[:model]
      space_id = context[:space_id].to_s
      notify = context[:notify] == true
      completion_result = false
      begin
        raise prefetch_error.to_s unless prefetch_error.to_s.empty?
        mirror = mirror_results[space_id]
        raise((mirror && mirror[:error].to_s.empty?) ? '本地镜像准备失败。' : mirror[:error].to_s) unless mirror && mirror[:ok]
        unless mirror[:revision].to_s == context[:revision].to_s &&
               mirror[:source_signature].to_s == context[:source_signature].to_s &&
               mirror[:source_snapshot].to_s == context[:source_snapshot].to_s
          raise '后台镜像任务返回了不属于本次更新的快照，已取消载入。'
        end
        raise '活动 SketchUp 模型已经切换，空间更新已取消。' unless Sketchup.active_model == model

        state = ensure_space_models_ready!(model)
        item = space_model_record(state, space_id)
        raise '找不到该空间模型。' unless item
        entity = space_model_entity(space_id, model)
        source_path = auto_relocate(item['model_path'].to_s, model)
        raise '空间模型文件不存在。' unless File.file?(source_path)
        latest_signature = fast_file_signature(source_path)
        latest_revision = space_authoritative_revision(item, source_path, actual_signature: latest_signature)
        if !context[:revision].to_s.empty? && latest_revision.to_s != context[:revision].to_s
          raise '准备更新期间共享空间已经发布了新版本。为避免载入过渡版本，本次已取消，请重新点击更新。'
        end
        if !context[:source_signature].to_s.empty? && normalize_fast_signature(latest_signature) != normalize_fast_signature(context[:source_signature])
          raise '准备更新期间共享空间文件发生变化。为避免载入过渡版本，本次已取消，请重新点击更新。'
        end
        if !context[:source_snapshot].to_s.empty? && space_source_snapshot_signature(source_path) != context[:source_snapshot].to_s
          raise '准备更新期间共享空间内容发生变化。为避免同大小旧文件混入，本次已取消，请重新点击更新。'
        end
        assert_space_update_direction!(item, entity, source_path, allow_unknown: false) unless context[:cancel_edit] == true

        operation_open = false
        operation_name = context[:cancel_edit] == true ? "取消空间修改 #{item['number']}:#{item['name']}" : "更新空间 #{item['number']}:#{item['name']}"
        model.start_operation(operation_name, true)
        operation_open = true
        restore_space_isolation!(item, model)
        entity.locked = true if entity && entity.respond_to?(:locked=)
        loaded_entity = load_space_model_instance!(
          item, model,
          representation: state['space_display_mode'], purge: false,
          create_repair_snapshot: true, force_visible: true, state: state,
          load_path_override: mirror[:path].to_s,
          expected_revision: context[:revision].to_s,
          expected_source_signature: context[:source_signature].to_s,
          expected_source_snapshot: context[:source_snapshot].to_s
        )
        item_collection = space_record_collection_key(item)
        unless space_collection_hidden_for(state, item_collection)
          loaded_entity.hidden = false if loaded_entity && loaded_entity.valid? && loaded_entity.respond_to?(:hidden=)
          group = item['group_id'].to_s.empty? ? nil : space_group_record(state, item['group_id'].to_s)
          if group
            visibility_state = group_collection_visibility_state(group, item_collection)
            if visibility_state['suspended']
              restore_ids = Array(visibility_state['restore_ids']).map(&:to_s).reject { |candidate| candidate == item['id'].to_s }
              visibility_state['restore_ids'] = restore_ids
              visibility_state['suspended'] = false if restore_ids.empty?
              sync_legacy_group_visibility_from_collection!(group) if item_collection == SPACE_COLLECTION_KEY
            end
          end
        end
        if space_collection_hidden_for(state, item_collection) && loaded_entity && loaded_entity.valid?
          snapshot = space_collection_visibility_snapshot_for(state, item_collection)
          key = space_collection_entity_visibility_key(loaded_entity)
          snapshot['entities'][key] = false unless snapshot['entities'].key?(key)
          set_space_collection_visibility_snapshot_for!(state, item_collection, snapshot)
          loaded_entity.hidden = true if loaded_entity.respond_to?(:hidden=)
        end

        # 只释放当前会话真正拥有的锁。若另一成员正在编辑，当前共享 SKP 仍是上一
        # 发布版，本次读取不会删除、改写或中断对方的锁与未发布内容。
        release_space_lock!(item, source_path, model: model, state: state)
        clear_space_publish_pending!(item) if context[:cancel_edit] == true
        clear_space_lock_state!(item) if context[:clear_local_session]
        state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
        state['space_edit_display_mode'] = ''
        @native_lock_state_cache ||= {}
        @native_lock_state_cache[space_native_cache_key(model, item['id'])] = true
        manifest_package_recovery = item.delete('_manifest_package_recovery_pending') == true
        save_state(state, model, write_manifest: false)
        model.commit_operation
        operation_open = false

        if manifest_package_recovery
          write_space_models_manifest!(
            state, model,
            preserve_remote_layout: true,
            local_space_ids: [item['id'].to_s]
          )
          save_state(state, model, write_manifest: false)
          repair_verified_space_safe_checkpoint_gap!(
            item, loaded_entity, source_path,
            item['source_revision'].to_s, item['last_signature'].to_s
          )
          log("空间中断发布清单已补写：#{item['number']}:#{item['name']} / #{item['source_revision']}")
        end

        overlay = workspace_toolbar_overlay(model)
        if overlay && !space_collection_hidden_for(state, item_collection)
          overlay.mark_space_loaded_visible_local!(item['id']) if overlay.respond_to?(:mark_space_loaded_visible_local!)
          if defined?(group) && group && overlay.respond_to?(:set_space_group_visibility_local!)
            visibility_state = group_collection_visibility_state(group, item_collection)
            overlay.set_space_group_visibility_local!(group['id'], visibility_state['suspended'], visibility_state['restore_ids'])
          end
        end
        schedule_soft_full_definition_cleanup(model, delay: 1.8)
        refresh_dialog
        suffix = context[:other_editor].to_s.empty? ? '' : "；#{context[:other_editor]} 的未发布修改未受影响"
        message = if context[:cancel_edit] == true
                    "#{item['number']}:#{item['name']} 已取消修改并恢复到上次发布版；占用已释放。"
                  else
                    "#{item['number']}:#{item['name']} 已从本地镜像载入上一发布版#{suffix}。"
                  end
        show_status(message, 'success') if notify
        completion_result = true
        true
      rescue StandardError => e
        model.abort_operation rescue nil if defined?(operation_open) && operation_open
        log_exception(context[:cancel_edit] == true ? '取消空间修改失败' : '单空间更新失败', e)
        failure_prefix = context[:cancel_edit] == true ? '取消修改失败' : '空间未更新'
        show_status("#{failure_prefix}：#{e.message}", 'error') if notify
        false
      ensure
        finish_single_space_update_interaction!(model)
        callback = context[:completion_callback]
        if callback.respond_to?(:call)
          runtime_start_timer(0.01, false, label: 'consistency:space_complete') do
            begin
              callback.call(completion_result)
            rescue StandardError => callback_error
              log_exception('空间一致性更新完成回调失败', callback_error)
            end
          end
        end
      end
    end

    def update_space_model(space_id, notify: true, completion_callback: nil, consistency_token: '')
      model = Sketchup.active_model
      if @consistency_update_job.is_a?(Hash) && @consistency_update_job[:token].to_s != consistency_token.to_s
        raise '空间与协同组件一致性更新正在进行，请等待完成。'
      end
      raise '请先退出所有组件编辑层级。' unless model.active_path.nil?
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再更新。' if publish_critical_section? || publish_post_quiet?
      raise '已有发布或更新任务正在执行，请等待完成。' if @updating || @single_space_update_job || @space_batch_update_job || @shared_component_batch_update_job
      raise '模型库批量任务正在执行，请等待完成后再更新。' if @soft_model_batch_job
      state = ensure_space_models_ready!(model)
      item = space_model_record(state, space_id)
      raise '找不到该空间模型。' unless item
      unless space_component_bundle_ready?(item)
        raise space_component_bundle_block_message(item)
      end
      if linked_space_record?(item)
        source = canonical_space_record(state, item)
        raise '该联动空间的来源已缺失，请刷新协同清单。' unless source
        source_entity = space_model_entity(source['id'], model)
        unless source_entity && source_entity.valid?
          show_status("正在载入来源空间 #{source['number']}:#{source['name']}；完成后自动恢复联动。", 'info') if notify
          return update_space_model(source['id'], notify: notify, completion_callback: completion_callback, consistency_token: consistency_token)
        end
        operation_open = false
        model.start_operation("恢复联动空间 #{item['number']}:#{item['name']}", true)
        operation_open = true
        sync_linked_space_instances_for_source!(state, source, source_entity, model)
        save_state(state, model, write_manifest: false)
        model.commit_operation
        operation_open = false
        refresh_dialog
        refresh_workspace_toolbar(model)
        show_status("#{item['number']}:#{item['name']} 已恢复与 #{source['name']} 的联动。", 'success') if notify
        return true
      end
      clear_orphan_background_publish_state!(item, model, state)
      item = space_model_record(state, item['id']) || item
      raise '该空间正在后台发布；发布完成并自动收尾前禁止更新/载入，以免把正在替换的共享文件误判为缺失或待更新。你仍可继续操作其他空间。' if background_publish_active_state?(item)
      if initial_space_publish_pending?(item)
        raise '该空间尚未完成首次发布，协同端还没有可载入的正式版本。请点击“重试/发布”，不要使用更新/载入。'
      end
      raise '该空间正处于强制解锁历史取物模式。请先退出并恢复进入前状态，再执行更新。' if space_force_recovery_active?(item, state)
      entity = space_model_entity(space_id, model)
      active_lock = space_lock_info(item, model, state: state)
      lock_active = active_lock['exists'] && !active_lock['stale']
      other_editor = ''
      if lock_active && !active_lock['owned']
        role = active_lock['actor_role_name'].to_s
        who = [active_lock['owner'], active_lock['host']].reject(&:empty?).join('@')
        detail = role.empty? ? who : "#{who.empty? ? '另一会话' : who}（#{role}工作区）"
        detail = '另一成员' if detail.to_s.empty?
        prompt = <<~TEXT
          #{item['number']}:#{item['name']} 当前由 #{detail} 修改。

          共享 SKP 仍然是对方开始修改前的上一发布版。
          本次“更新”只会把这一已发布版本载入当前 SU，不会中断对方，也不会删除对方未发布内容。

          是否继续载入上一发布版？
        TEXT
        return false unless native_confirm_yes?(prompt)
        other_editor = detail
      end

      local_editing = local_space_edit_session?(item, state, model)
      if local_editing
        return false unless native_confirm_yes?("#{item['number']}:#{item['name']} 正在本机修改。\n\n更新会放弃当前 SU 中未发布的修改并重新载入共享上一发布版，是否继续？")
      end

      source_path = auto_relocate(item['model_path'].to_s, model)
      raise '空间模型文件不存在。' unless File.file?(source_path)
      assert_space_update_direction!(item, entity, source_path, allow_unknown: false)
      revision = space_authoritative_revision(item, source_path)
      revision = "space-file|#{fast_file_signature(source_path)}" if revision.empty?
      source_snapshot = space_source_snapshot_signature(source_path)
      raise '无法验证共享空间文件内容，请检查网络盘后重试。' if source_snapshot.empty?
      close_space_publish_dialog(item['id'], :update)
      clear_space_publish_pending!(item)

      token = SecureRandom.hex(8)
      context = {
        token: token,
        model: model,
        space_id: item['id'].to_s,
        revision: revision.to_s,
        source_signature: fast_file_signature(source_path),
        source_snapshot: source_snapshot,
        notify: notify,
        other_editor: other_editor,
        clear_local_session: local_editing || active_lock['stale'] || active_lock['same_user_recoverable'],
        completion_callback: completion_callback,
        consistency_token: consistency_token.to_s
      }
      @single_space_update_job = context
      @updating = true
      begin_soft_heavy_interaction(:space_single_update)
      Sketchup.set_status_text("LinkHub 正在后台准备 #{item['number']}:#{item['name']} 的本地镜像…") rescue nil
      show_status("正在准备 #{item['number']}:#{item['name']} 的上一发布版；完成后自动载入。", 'info') if notify
      jobs = [{
        id: item['id'].to_s,
        key: space_mirror_key(item),
        source: source_path,
        revision: revision.to_s,
        source_signature: context[:source_signature].to_s,
        source_snapshot: context[:source_snapshot].to_s
      }]
      started = prefetch_space_batch_mirrors_async!(jobs, workers: 1, model: model) do |results, error|
        schedule_complete_single_space_update!(context, results, prefetch_error: error)
      end
      unless started
        finish_single_space_update_interaction!(model)
        raise '无法启动空间本地镜像任务。'
      end
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      finish_single_space_update_interaction!(model) if @single_space_update_job
      raise
    end

    def bake_space_outer_transformation!(entity)
      return false unless entity && entity.valid? && entity.respond_to?(:definition)
      transformation = entity.transformation
      values = transformation.respond_to?(:to_a) ? transformation.to_a.map(&:to_f) : []
      identity = identity_transformation_array.map(&:to_f)
      is_identity = values.length == 16 && values.each_with_index.all? { |value, index| (value - identity[index]).abs < 1.0e-9 }
      return false if is_identity
      contents = entity.definition.entities.to_a
      entity.definition.entities.transform_entities(transformation, contents) unless contents.empty?
      entity.transformation = identity_transformation
      soft_invalidate_definition_bounds!(entity.definition)
      true
    end

    # v0.13.6.170：空间异步发布队列独立模块。
    Kernel.load(File.expand_path('publish.rb', __dir__))

    # -------------------------
    # 景观模型库
    # -------------------------

    # -------------------------
    # 建筑：多模型集合（v0.11.0）
