    def default_architecture_model(number = 1, name = '未命名建筑', stored_path = '')
      default_space_model(number, name, stored_path).merge(
        'collection_key' => 'architecture',
        'legacy_source' => '',
        'status' => '未载入'
      )
    end

    def normalize_architecture_models_state!(state, model = Sketchup.active_model)
      records = Array(state['architecture_models'])
      seen_ids = {}
      seen_numbers = {}
      normalized = records.each_with_index.map do |raw, index|
        item = raw.is_a?(Hash) ? raw.dup : {}
        number = item['number'].to_i
        number = index + 1 unless number.positive?
        number += 1 while seen_numbers[number]
        seen_numbers[number] = true
        id = item['id'].to_s.strip
        id = SecureRandom.uuid if id.empty? || seen_ids[id]
        seen_ids[id] = true
        defaults = default_architecture_model(number, item['name'], item['model_path'])
        defaults.each { |key, value| item[key] = value unless item.key?(key) }
        item['id'] = id
        item['number'] = number
        item['name'] = normalize_space_name(item['name'])
        item['name'] = '未命名建筑' if item['name'].empty?
        item['model_path'] = item['model_path'].to_s
        item['group_id'] = item['group_id'].to_s
        item['group_order'] = item['group_order'].to_i
        item['collection_key'] = 'architecture'
        item['legacy_source'] = item['legacy_source'].to_s
        item['last_signature'] = item['last_signature'].to_s
        item['source_revision'] = item['source_revision'].to_s
        item['last_publish_at'] = item['last_publish_at'].to_s
        item['last_update'] = item['last_update'].to_s
        item['status'] = item['status'].to_s
        item['editing'] = !!item['editing']
        item['edit_lock_token'] = item['edit_lock_token'].to_s
        item['edit_actor_role'] = item['edit_actor_role'].to_s.empty? ? 'architecture' : item['edit_actor_role'].to_s
        item['edit_lock_owner'] = item['edit_lock_owner'].to_s
        item['edit_lock_host'] = item['edit_lock_host'].to_s
        item['edit_lock_started_at'] = item['edit_lock_started_at'].to_s
        item['publish_pending'] = !!item['publish_pending']
        item['edit_safe_paused'] = !!item['edit_safe_paused']
        item['edit_safe_paused_at'] = item['edit_safe_paused_at'].to_s
        item['edit_safe_pause_reason'] = item['edit_safe_pause_reason'].to_s
        item['isolation_snapshot'] = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
        item
      end

      groups = Array(state['architecture_groups']).each_with_index.map do |raw, index|
        group = raw.is_a?(Hash) ? raw.dup : {}
        group['id'] = SecureRandom.uuid if group['id'].to_s.empty?
        group['name'] = normalize_space_name(group['name'])
        group['name'] = "建筑组#{index + 1}" if group['name'].empty?
        group['order'] = group['order'].to_i
        group['collapsed'] = group.key?('collapsed') ? !!group['collapsed'] : true
        group['visibility_suspended'] = !!group['visibility_suspended']
        group['visibility_restore_ids'] = Array(group['visibility_restore_ids']).map(&:to_s).reject(&:empty?).uniq
        group
      end
      groups = groups.uniq { |group| group['id'].to_s }.sort_by { |group| [group['order'].to_i, group['name'].to_s] }
      groups.each_with_index { |group, index| group['order'] = index }
      valid_group_ids = groups.each_with_object({}) { |group, memo| memo[group['id'].to_s] = true }
      normalized.each { |item| item['group_id'] = '' unless valid_group_ids[item['group_id'].to_s] }
      state['architecture_groups'] = groups
      state['architecture_models'] = normalized.sort_by do |item|
        group = groups.find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
        [group ? group['order'].to_i : 9_999_999, item['group_order'].to_i, item['number'].to_i]
      end
      state['architecture_next_number'] = smallest_available_space_number(state['architecture_models'])
      state['architecture_editing_id'] = state['architecture_editing_id'].to_s
      state['architecture_collection_hidden'] = !!state['architecture_collection_hidden']
      state['architecture_collection_visibility_snapshot'] = state['architecture_collection_visibility_snapshot'].is_a?(Hash) ? state['architecture_collection_visibility_snapshot'] : {}
      state['architecture_legacy_migrated'] = !!state['architecture_legacy_migrated']
      state
    end

    def architecture_model_record(state, architecture_id)
      Array(state['architecture_models']).find { |item| item.is_a?(Hash) && item['id'].to_s == architecture_id.to_s }
    end

    # v0.12.0 起，多建筑集合是建筑专业的唯一运行主线。旧单建筑 FULL 只作为
    # 迁移来源/只读兼容文件存在，不能再抢占双击、快捷操作、结构自检或编辑锁路由。
    # v0.12.0：旧单建筑运行链永久退役。建筑只使用 architecture_models 集合。
    # 保留 links[architecture] 这个空壳仅为避免旧通用 UI 读取 nil；它不再保存路径、
    # 锁、编辑或发布状态，也不能参与任何按钮路由。
    def retire_legacy_architecture_runtime_state!(state, model = Sketchup.active_model)
      state['links'] = {} unless state['links'].is_a?(Hash)
      link = state['links']['architecture'] = {} unless state['links']['architecture'].is_a?(Hash)
      link ||= state['links']['architecture']
      link['enabled'] = false
      link['status'] = '旧单建筑运行链已退役；建筑由多模型集合统一管理'
      link['status_label'] = link['status']
      link['status_code'] = 'disabled'
      link['model_path'] = ''
      link['collab_full_path'] = ''
      link['collab_revision_id'] = ''
      link['collab_last_publish_at'] = ''
      link['architecture_collab_managed'] = false
      link['architecture_collaboration_available'] = false
      link['architecture_update_required'] = false
      link['source_locked_by_other'] = false
      link['source_lock_owned'] = false
      link['source_lock_owner'] = ''
      link['source_lock_host'] = ''
      link['source_lock_token'] = ''
      link['edit_session_active'] = false
      link['preview_edit_active'] = false
      link['preview_pending_publish'] = false
      link['native_editing'] = false
      link['edit_lock_token'] = ''
      link['edit_safe_paused'] = false
      state['architecture_runtime_schema'] = 2
      state.delete('architecture_legacy_migrated')
      true
    rescue StandardError => e
      log_exception('退役旧单建筑运行状态失败', e)
      false
    end

    def architecture_collection_local_edit_record(state, model = Sketchup.active_model)
      active_id = state['architecture_editing_id'].to_s
      candidates = Array(state['architecture_models'])
      ordered = active_id.empty? ? candidates : candidates.sort_by { |item| item['id'].to_s == active_id ? 0 : 1 }
      ordered.find do |item|
        entity = architecture_model_entity(item['id'], model)
        source = auto_relocate(item['model_path'].to_s, model)
        lock = source.to_s.empty? ? { 'exists' => false } : space_lock_info(item, model, source_path: source, state: state)
        local_hint = item['editing'] || space_edit_safe_paused?(item) ||
                     active_id == item['id'].to_s ||
                     (entity && entity.valid? && (entity.get_attribute(ENTITY_DICT, 'editing', false) || !entity_native_locked?(entity)))
        lock['exists'] && !lock['stale'] && lock['owned'] && local_hint
      end
    rescue StandardError
      nil
    end

    def architecture_collection_remote_pending?(state, model = Sketchup.active_model)
      Array(state['architecture_models']).any? do |item|
        source = auto_relocate(item['model_path'].to_s, model)
        next false unless File.file?(source)
        architecture_model_update_direction(item, architecture_model_entity(item['id'], model), model) != :same
      end
    rescue StandardError
      false
    end

    def architecture_collection_active?(state = nil, model = Sketchup.active_model)
      state ||= load_state(model)
      return false unless state.is_a?(Hash)
      project_dir = architecture_models_project_dir(state, model)
      return false if project_dir.to_s.empty?
      # 一旦连接项目，建筑专业永远走新集合；即使集合尚为空，也只显示“新增建筑”，
      # 绝不回退到旧 FULL/links[architecture]。
      true
    rescue StandardError
      false
    end

    def architecture_models_project_dir(state, model = Sketchup.active_model)
      collab_project_dir_for_model(model, state)
    rescue StandardError
      ''
    end

    def architecture_models_root(state, model = Sketchup.active_model)
      project_dir = architecture_models_project_dir(state, model)
      project_dir.to_s.empty? ? '' : File.join(project_dir, COLLAB_FOLDER_NAME, ARCHITECTURE_MODELS_FOLDER)
    end

    def architecture_models_assets_dir(state, model = Sketchup.active_model)
      root = architecture_models_root(state, model)
      root.empty? ? '' : File.join(root, '模型')
    end

    def architecture_models_manifest_path(state, model = Sketchup.active_model)
      root = architecture_models_root(state, model)
      root.empty? ? '' : File.join(root, ARCHITECTURE_MODELS_MANIFEST)
    end

    def architecture_groups_manifest_path(state, model = Sketchup.active_model)
      root = architecture_models_root(state, model)
      root.empty? ? '' : File.join(root, ARCHITECTURE_GROUPS_MANIFEST)
    end

    def safe_architecture_filename(number, name)
      "##{number.to_i}.#{safe_space_filename(name)}.skp"
    end

    def architecture_model_entities(model = Sketchup.active_model)
      Array(managed_root_index(model).dig(:by_kind, 'architecture_model')).select do |entity|
        entity && entity.valid? && entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s == 'architecture'
      end
    rescue StandardError
      []
    end

    def architecture_model_entity(architecture_id, model = Sketchup.active_model)
      entity = managed_root_index(model).dig(:architecture_models_by_id, architecture_id.to_s)
      entity && entity.valid? ? entity : nil
    rescue StandardError
      nil
    end

    def mark_architecture_model_entity!(entity, item, stored_path, signature, model = Sketchup.active_model, revision: '', invalidate_index: true)
      structure = ensure_professional_structure('architecture', model)
      mark_entity(
        entity,
        discipline: 'architecture',
        kind: 'architecture_model',
        source: stored_path,
        display_name: safe_architecture_filename(item['number'], item['name']),
        tag: structure[:model_tag],
        mode: 'absolute_world',
        signature: signature,
        locked: true,
        editing: false
      )
      entity.set_attribute(ENTITY_DICT, 'architecture_id', item['id'].to_s)
      entity.set_attribute(ENTITY_DICT, 'architecture_number', item['number'].to_i)
      entity.set_attribute(ENTITY_DICT, 'source_file_signature', signature.to_s)
      entity.set_attribute(ENTITY_DICT, 'source_revision', revision.to_s) unless revision.to_s.empty?
      entity.set_attribute(ENTITY_DICT, 'source_load_verified_schema', SPACE_LOAD_VERIFIED_SCHEMA)
      entity.set_attribute(ENTITY_DICT, 'source_verified_signature', signature.to_s)
      entity.set_attribute(ENTITY_DICT, 'source_package_revision', revision.to_s)
      entity.set_attribute(ENTITY_DICT, 'source_package_identity', 'architecture-model')
      entity.set_attribute(ENTITY_DICT, 'load_asset_path', stored_path.to_s)
      entity.set_attribute(ENTITY_DICT, 'absolute_world', true)
      entity.transformation = identity_transformation if entity.respond_to?(:transformation=)
      invalidate_managed_root_index(model, reason: 'mark_architecture_model') if invalidate_index
      entity
    end

    def with_architecture_manifest_write_lock(path, timeout: 4.0)
      lock_path = "#{path}.sulink-write.lock"
      deadline = monotonic_time + timeout.to_f
      acquired = false
      loop do
        begin
          File.open(lock_path, File::WRONLY | File::CREAT | File::EXCL) do |io|
            io.write(JSON.generate({
              'pid' => Process.pid,
              'host' => current_host_name,
              'user' => current_user_name,
              'created_at' => Time.now.iso8601(6)
            }))
          end
          acquired = true
          break
        rescue Errno::EEXIST
          begin
            age = Time.now.to_f - File.mtime(lock_path).to_f
            File.delete(lock_path) if age > 20.0
          rescue StandardError
            nil
          end
          raise '建筑模型清单正由其他成员写入，请稍后重试。' if monotonic_time >= deadline
          sleep(0.06)
        end
      end
      yield
    ensure
      File.delete(lock_path) if acquired && File.file?(lock_path)
    end

    def write_architecture_groups_manifest!(state, model = Sketchup.active_model)
      path = architecture_groups_manifest_path(state, model)
      return false if path.empty?
      FileUtils.mkdir_p(File.dirname(path))
      published_models = Array(state['architecture_models']).reject { |item| item['initial_publish_pending'] == true }
      published_group_ids = published_models.map { |item| item['group_id'].to_s }.reject(&:empty?).uniq
      with_architecture_manifest_write_lock(path) do
        payload = {
          'schema' => ARCHITECTURE_GROUPS_SCHEMA,
          'kind' => 'sulink_architecture_groups',
          'plugin_version' => EXTENSION_VERSION,
          'layout_revision' => state['architecture_layout_revision'].to_s,
          'updated_at' => Time.now.iso8601,
          'updated_by' => current_user_name,
          'updated_host' => current_host_name,
          'groups' => Array(state['architecture_groups']).select { |group| published_group_ids.include?(group['id'].to_s) }.sort_by { |group| group['order'].to_i }.map do |group|
            { 'id' => group['id'].to_s, 'name' => group['name'].to_s, 'order' => group['order'].to_i }
          end,
          'models' => published_models.map do |item|
            { 'id' => item['id'].to_s, 'group_id' => item['group_id'].to_s, 'group_order' => item['group_order'].to_i }
          end
        }
        temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
        linkhub_mv(temp, path)
      ensure
        File.delete(temp) if defined?(temp) && temp && File.file?(temp)
      end
      true
    end

    def write_architecture_models_manifest!(state, model = Sketchup.active_model, local_model_ids: nil, deleted_model_ids: [])
      path = architecture_models_manifest_path(state, model)
      return false if path.empty?
      FileUtils.mkdir_p(File.dirname(path))
      project_dir = architecture_models_project_dir(state, model)
      explicit = Array(local_model_ids).map(&:to_s).reject(&:empty?).uniq
      deleted = Array(deleted_model_ids).map(&:to_s).reject(&:empty?).uniq
      with_architecture_manifest_write_lock(path) do
        remote = if File.file?(path)
                   JSON.parse(File.read(path, mode: 'r:UTF-8')) rescue {}
                 else
                   {}
                 end
        remote_models = Array(remote['models']).each_with_object({}) { |raw, memo| memo[raw['id'].to_s] = raw if raw.is_a?(Hash) && !raw['id'].to_s.empty? }
        local_by_id = Array(state['architecture_models']).each_with_object({}) { |item, memo| memo[item['id'].to_s] = item if item.is_a?(Hash) }

        # 把其他成员刚新增的建筑合并回本地状态，避免本机一次分组/重命名整份覆盖。
        remote_models.each do |id, raw|
          next if deleted.include?(id) || local_by_id.key?(id)
          resolved = resolve_space_manifest_file(project_dir, raw['file'])
          item = default_architecture_model(raw['number'], raw['name'], resolved.empty? ? '' : store_path(resolved, model))
          item['id'] = id
          item['group_id'] = raw['group_id'].to_s
          item['group_order'] = raw['group_order'].to_i
          item['last_signature'] = raw['signature'].to_s
          item['source_revision'] = raw['revision'].to_s
          item['last_publish_at'] = raw['published_at'].to_s
          item['last_publish_by'] = raw['published_by'].to_s
          item['last_publish_host'] = raw['published_host'].to_s
          item['last_publish_plugin_version'] = raw['publish_plugin_version'].to_s
          item['status'] = File.file?(resolved) ? '协同建筑已发现 · 请点击更新' : '协同建筑文件缺失'
          state['architecture_models'] << item
          local_by_id[id] = item
        end
        state['architecture_models'].delete_if { |item| deleted.include?(item['id'].to_s) }

        # 非本次明确修改的模型保留远端更新后的版本真相。
        Array(state['architecture_models']).each do |item|
          id = item['id'].to_s
          raw = remote_models[id]
          next unless raw && !explicit.include?(id)
          remote_time = parse_time_value(raw['published_at'])
          local_time = parse_time_value(item['last_publish_at'])
          remote_newer = remote_time && (!local_time || remote_time > local_time)
          if remote_newer || item['source_revision'].to_s.empty?
            resolved = resolve_space_manifest_file(project_dir, raw['file'])
            item['model_path'] = store_path(resolved, model) unless resolved.to_s.empty?
            item['last_signature'] = raw['signature'].to_s unless raw['signature'].to_s.empty?
            item['source_revision'] = raw['revision'].to_s unless raw['revision'].to_s.empty?
            item['last_publish_at'] = raw['published_at'].to_s unless raw['published_at'].to_s.empty?
            item['last_publish_by'] = raw['published_by'].to_s unless raw['published_by'].to_s.empty?
            item['last_publish_host'] = raw['published_host'].to_s unless raw['published_host'].to_s.empty?
            item['last_publish_plugin_version'] = raw['publish_plugin_version'].to_s unless raw['publish_plugin_version'].to_s.empty?
          end
        end
        normalize_architecture_models_state!(state, model)
        published_models = Array(state['architecture_models']).reject { |item| item['initial_publish_pending'] == true }
        published_group_ids = published_models.map { |item| item['group_id'].to_s }.reject(&:empty?).uniq

        payload = {
          'schema' => ARCHITECTURE_MODELS_SCHEMA,
          'kind' => 'sulink_architecture_models',
          'plugin_version' => EXTENSION_VERSION,
          'collection' => '建筑',
          'updated_at' => Time.now.iso8601,
          'layout_revision' => state['architecture_layout_revision'].to_s,
          'groups' => Array(state['architecture_groups']).select { |group| published_group_ids.include?(group['id'].to_s) }.sort_by { |group| group['order'].to_i }.map do |group|
            { 'id' => group['id'].to_s, 'name' => group['name'].to_s, 'order' => group['order'].to_i }
          end,
          'models' => published_models.sort_by { |item| [item['group_id'].to_s, item['group_order'].to_i, item['number'].to_i] }.map do |item|
            resolved = resolve_path(item['model_path'].to_s, model)
            {
              'id' => item['id'].to_s, 'number' => item['number'].to_i, 'name' => item['name'].to_s,
              'group_id' => item['group_id'].to_s, 'group_order' => item['group_order'].to_i,
              'file' => resolved.to_s.empty? ? '' : manifest_space_path(project_dir, resolved),
              'signature' => item['last_signature'].to_s.empty? && File.file?(resolved) ? fast_file_signature(resolved) : item['last_signature'].to_s,
              'revision' => item['source_revision'].to_s, 'published_at' => item['last_publish_at'].to_s,
              'published_by' => item['last_publish_by'].to_s,
              'published_host' => item['last_publish_host'].to_s,
              'publish_plugin_version' => item['last_publish_plugin_version'].to_s
            }
          end
        }
        temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
        linkhub_mv(temp, path)
      ensure
        File.delete(temp) if defined?(temp) && temp && File.file?(temp)
      end
      write_architecture_groups_manifest!(state, model)
      true
    end

    def sync_architecture_groups_from_manifest!(state, model = Sketchup.active_model)
      path = architecture_groups_manifest_path(state, model)
      return false unless File.file?(path)
      data = JSON.parse(File.read(path, mode: 'r:UTF-8'))
      return false unless data['kind'].to_s == 'sulink_architecture_groups'
      local_preferences = Array(state['architecture_groups']).each_with_object({}) do |group, memo|
        memo[group['id'].to_s] = group if group.is_a?(Hash)
      end
      groups = Array(data['groups']).filter_map do |raw|
        next unless raw.is_a?(Hash) && !raw['id'].to_s.empty?
        local = local_preferences[raw['id'].to_s] || {}
        {
          'id' => raw['id'].to_s,
          'name' => normalize_space_name(raw['name']),
          'order' => raw['order'].to_i,
          'collapsed' => local.key?('collapsed') ? !!local['collapsed'] : true,
          'visibility_suspended' => !!local['visibility_suspended'],
          'visibility_restore_ids' => Array(local['visibility_restore_ids']).map(&:to_s)
        }
      end
      layout = Array(data['models']).each_with_object({}) { |raw, memo| memo[raw['id'].to_s] = raw if raw.is_a?(Hash) }
      state['architecture_groups'] = groups
      Array(state['architecture_models']).each do |item|
        raw = layout[item['id'].to_s]
        next unless raw
        item['group_id'] = raw['group_id'].to_s
        item['group_order'] = raw['group_order'].to_i
      end
      state['architecture_layout_revision'] = data['layout_revision'].to_s if data.key?('layout_revision')
      normalize_architecture_models_state!(state, model)
      true
    rescue StandardError => e
      log_exception('同步建筑分组失败', e)
      false
    end

    def sync_architecture_models_from_manifest!(state, model = Sketchup.active_model)
      path = architecture_models_manifest_path(state, model)
      return false unless File.file?(path)
      data = JSON.parse(File.read(path, mode: 'r:UTF-8'))
      return false unless data['kind'].to_s == 'sulink_architecture_models'
      project_dir = architecture_models_project_dir(state, model)
      local = Array(state['architecture_models']).each_with_object({}) { |item, memo| memo[item['id'].to_s] = item if item.is_a?(Hash) }
      local_group_preferences = Array(state['architecture_groups']).each_with_object({}) { |group, memo| memo[group['id'].to_s] = group if group.is_a?(Hash) }
      if data.key?('groups')
        state['architecture_groups'] = Array(data['groups']).filter_map do |raw|
          next unless raw.is_a?(Hash) && !raw['id'].to_s.empty?
          pref = local_group_preferences[raw['id'].to_s] || {}
          {
            'id' => raw['id'].to_s,
            'name' => normalize_space_name(raw['name']),
            'order' => raw['order'].to_i,
            'collapsed' => pref.key?('collapsed') ? !!pref['collapsed'] : true,
            'visibility_suspended' => !!pref['visibility_suspended'],
            'visibility_restore_ids' => Array(pref['visibility_restore_ids']).map(&:to_s)
          }
        end
      end
      imported = Array(data['models']).filter_map do |raw|
        next unless raw.is_a?(Hash)
        id = raw['id'].to_s
        next if id.empty?
        existing = local[id] || {}
        resolved = resolve_space_manifest_file(project_dir, raw['file'])
        item = default_architecture_model(raw['number'], raw['name'], resolved.empty? ? '' : store_path(resolved, model))
        item.merge!(existing)
        item['id'] = id
        item['number'] = [raw['number'].to_i, 1].max
        item['name'] = normalize_space_name(raw['name'])
        item['group_id'] = raw['group_id'].to_s
        item['group_order'] = raw['group_order'].to_i
        item['model_path'] = resolved.empty? ? '' : store_path(resolved, model)
        item['last_signature'] = raw['signature'].to_s unless raw['signature'].to_s.empty?
        item['source_revision'] = raw['revision'].to_s
        item['last_publish_at'] = raw['published_at'].to_s unless raw['published_at'].to_s.empty?
        item['last_publish_by'] = raw['published_by'].to_s unless raw['published_by'].to_s.empty?
        item['last_publish_host'] = raw['published_host'].to_s unless raw['published_host'].to_s.empty?
        item['last_publish_plugin_version'] = raw['publish_plugin_version'].to_s unless raw['publish_plugin_version'].to_s.empty?
        item['status'] = File.file?(resolved) ? (existing.empty? ? '协同建筑已发现 · 请点击更新' : item['status'].to_s) : '协同建筑文件缺失'
        item
      end
      preserved_local = local.values.select do |item|
        item['initial_publish_pending'] == true || architecture_background_publish_active?(item['id'])
      end
      imported_ids = imported.map { |item| item['id'].to_s }
      preserved_local.each { |item| imported << item unless imported_ids.include?(item['id'].to_s) }
      state['architecture_models'] = imported
      state['architecture_layout_revision'] = data['layout_revision'].to_s if data.key?('layout_revision')
      normalize_architecture_models_state!(state, model)
      sync_architecture_groups_from_manifest!(state, model)
      true
    rescue StandardError => e
      log_exception('同步建筑模型清单失败', e)
      false
    end

    def migrate_legacy_architecture_to_collection!(state, model = Sketchup.active_model)
      # v0.12.0 为破坏性清理版本：不再读取、迁移或激活旧建筑_FULL.skp 索引。
      # 已经由 v0.11.x 建立的 architecture_models 清单继续使用；没有新清单的项目
      # 需要在建筑板块通过“+”重新登记建筑模型。
      retire_legacy_architecture_runtime_state!(state, model)
      false
    end

    def ensure_architecture_models_ready!(model = Sketchup.active_model)
      state = load_state(model)
      retire_legacy_architecture_runtime_state!(state, model)
      sync_architecture_models_from_manifest!(state, model)
      clear_orphan_architecture_background_publish_states!(state, model)
      normalize_architecture_models_state!(state, model)

      # 从真实锁文件和根组件恢复本机编辑状态。热重载、抽屉轻量刷新或状态文件
      # 丢失时，不能因为 architecture_editing_id 暂时为空就把“修改中”消掉。
      recovered = nil
      Array(state['architecture_models']).each do |item|
        entity = architecture_model_entity(item['id'], model)
        source = auto_relocate(item['model_path'].to_s, model)
        next if source.to_s.empty?
        lock = space_lock_info(item, model, source_path: source, state: state)
        local_hint = item['editing'] || space_edit_safe_paused?(item) ||
                     state['architecture_editing_id'].to_s == item['id'].to_s ||
                     (entity && entity.valid? && (entity.get_attribute(ENTITY_DICT, 'editing', false) || !entity_native_locked?(entity)))
        if lock['exists'] && !lock['stale'] && lock['owned'] && (local_hint || lock['process_owned'])
          item['editing'] = true
          item['edit_lock_token'] = lock['token'].to_s unless lock['token'].to_s.empty?
          item['edit_actor_role'] = current_workspace_role(model, state)
          item['edit_lock_owner'] = lock['owner'].to_s
          item['edit_lock_host'] = lock['host'].to_s
          item['edit_lock_started_at'] = lock['started_at'].to_s
          item['status'] = space_edit_safe_paused?(item) ? '未发布修改已安全暂存' : '待发布 · 修改中'
          entity.set_attribute(ENTITY_DICT, 'editing', true) if entity && entity.valid?
          recovered ||= item['id'].to_s
        elsif item['editing'] && (!lock['exists'] || lock['stale'])
          # 锁已真实消失时才清除本地“修改中”；不再根据旧单建筑索引判断。
          item['editing'] = false
          entity.set_attribute(ENTITY_DICT, 'editing', false) if entity && entity.valid? && entity_native_locked?(entity)
        end
      end
      state['architecture_editing_id'] = recovered.to_s unless recovered.to_s.empty?
      active_id = state['architecture_editing_id'].to_s
      unless active_id.empty?
        active = architecture_model_record(state, active_id)
        state['architecture_editing_id'] = '' unless active && active['editing']
      end
      save_state(state, model, write_manifest: false)
      state
    rescue StandardError => e
      log_exception('准备建筑多模型失败', e)
      load_state(model)
    end

    def architecture_display_name(item, state = nil)
      state ||= load_state(Sketchup.active_model)
      group = Array(state['architecture_groups']).find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
      group ? "#{group['name']}:#{item['name']}" : "##{item['number']}.#{item['name']}"
    end

    def add_architecture_model_from_selection(selected: nil, parsed_input: nil, allow_cross_workspace: false)
      publish_guard_acquired = false
      publish_error = nil
      operation_open = false
      enqueued = false
      model = Sketchup.active_model
      raise '请先退出组件编辑层级，在模型根层级选择要发布的建筑组件或群组。' unless model.active_path.nil?
      selected = Array(selected).select { |entity| entity && entity.valid? }
      selected = selected_space_source_entities(model) if selected.empty?
      raise '请先选择一个或多个普通组件/群组。' if selected.empty?
      state = ensure_architecture_models_ready!(model)
      raise '请切换到建筑工作区后新增建筑模型。' unless allow_cross_workspace || host_discipline_for(state) == 'architecture'
      project_dir = ensure_collab_project_ready!(state, model, interactive: true)
      return false if project_dir.to_s.empty?
      parsed = parsed_input.is_a?(Hash) ? parsed_input : nil
      unless parsed
        response = UI.inputbox(["建筑名称
支持：B1-主楼-建筑；首段 B1/1F 可自动成组。
已选择 #{selected.length} 个对象；将写出独立建筑 SKP。"], [''], '新增建筑模型')
        return false unless response
        parsed = parse_structured_space_name(response[0], default_collection: SPACE_COLLECTION_KEY)
      end
      name = parsed['name'].to_s
      raise '建筑名称不能为空。' if name.empty?
      raise "建筑名称“#{name}”已经存在。" if Array(state['architecture_models']).any? { |item| item['name'].to_s.casecmp(name).zero? }
      number = smallest_available_space_number(state['architecture_models'])
      item = default_architecture_model(number, name)
      item['group_id'] = ensure_named_architecture_group!(state, parsed['group_name']) unless parsed['group_name'].to_s.empty?
      assets_dir = architecture_models_assets_dir(state, model)
      FileUtils.mkdir_p(assets_dir)
      target = File.join(assets_dir, safe_architecture_filename(number, name))
      raise '同名建筑共享文件已经存在；请先刷新建筑清单后再新增。' if File.exist?(target)
      stored = store_path(target, model)
      label = "##{number}.#{name}"
      job_id = "bgarch-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      revision = new_publish_revision("architecture-model-#{item['id']}")

      publish_guard_acquired = enter_publish_critical_section!(
        kind: 'new_architecture_model', subject: "新增建筑模型 #{label} 候选封装", target: target, model: model
      )
      publish_breadcrumb!('architecture_initial_publish_preflight', architecture_id: item['id'].to_s, target: target, background_queue: true)
      model.start_operation("新增建筑模型 #{label}", true)
      operation_open = true
      definition = model.definitions.add("LH_ARCH_MODEL_#{number}_#{SecureRandom.hex(5)}")
      selected.each do |source_entity|
        copied = definition.entities.add_instance(source_entity.definition, absolute_transformation_for_selected_entity(source_entity, model))
        copy_instance_visual_properties!(source_entity, copied)
      end
      instance = model.entities.add_instance(definition, identity_transformation)
      wrapper, = build_space_publish_wrapper!(instance, model, representation: 'full', package_revision: revision, space_id: "architecture:#{item['id']}")
      prepared = serialize_publish_definition_candidate!(wrapper, target, "architecture_model_#{item['id']}", defer_content_signature: true)
      defer_publish_definition_cleanup!(wrapper, model)
      selected.each { |source_entity| source_entity.erase! if source_entity.valid? }
      mark_architecture_model_entity!(instance, item, stored, '', model, revision: revision)
      instance.locked = true if instance.respond_to?(:locked=)
      item['model_path'] = stored
      item['source_revision'] = revision
      item['initial_publish_pending'] = true
      item['initial_publish_candidate'] = prepared[:path].to_s
      item['initial_publish_error'] = ''
      item['background_publish_state'] = 'queued'
      item['background_publish_job_id'] = job_id
      item['background_publish_candidate'] = prepared[:path].to_s
      item['background_publish_error'] = ''
      item['status'] = '首次发布已加入队列 · 本地建筑已保留'
      state['architecture_models'] << item
      normalize_architecture_models_state!(state, model)
      save_state(state, model, write_manifest: false)
      model.selection.clear
      model.selection.add(instance)
      model.commit_operation
      operation_open = false

      enqueue_space_publish_job!({
        job_id: job_id,
        job_kind: 'architecture_model',
        space_id: "architecture_model:#{item['id']}",
        architecture_id: item['id'].to_s,
        label: "建筑 #{label}",
        target: target.to_s,
        publish_key: "architecture_model_#{item['id']}",
        expected_signature: '',
        baseline_path: '',
        baseline_signature: '',
        source_revision: revision.to_s,
        source_model_path: model.path.to_s,
        model_object_id: model.object_id,
        prepared: prepared,
        initial_publish: true,
        proxy_layout: false
      }, model)
      enqueued = true
      show_status("建筑 #{label} 已加入发布队列；现在可以继续操作其它空间/建筑/景观。", 'success')
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      true
    rescue StandardError => e
      publish_error = e
      model.abort_operation rescue nil if operation_open
      if defined?(item) && item && !enqueued
        begin
          recovery_state = ensure_architecture_models_ready!(model)
          recovery_item = architecture_model_record(recovery_state, item['id'])
          if recovery_item
            recovery_item['initial_publish_pending'] = true
            recovery_item['initial_publish_candidate'] = defined?(prepared) && prepared.is_a?(Hash) ? prepared[:path].to_s : recovery_item['initial_publish_candidate'].to_s
            recovery_item['initial_publish_error'] = e.message.to_s
            recovery_item['background_publish_state'] = 'failed'
            recovery_item['background_publish_job_id'] = ''
            recovery_item['status'] = '首次发布入队失败 · 本地建筑已保留 · 可重试'
            save_state(recovery_state, model, write_manifest: false)
          end
        rescue StandardError => recovery_error
          log_exception('新增建筑首次后台发布失败后保存本地状态失败', recovery_error)
        end
      end
      raise
    ensure
      leave_publish_critical_section!(success: !!enqueued, error: publish_error, model: model) if publish_guard_acquired
    end

    def load_architecture_model_instance!(item, model = Sketchup.active_model, state: nil, force_visible: false)
      state ||= load_state(model)
      source = auto_relocate(item['model_path'].to_s, model)
      raise '建筑模型文件不存在。' unless File.file?(source)
      signature = fast_file_signature(source)
      revision = item['source_revision'].to_s
      revision = "architecture-file|#{signature}" if revision.empty?
      path = preferred_space_load_path(item, source, signature, model)
      previous = architecture_model_entity(item['id'], model)
      hidden = force_visible ? false : (previous && previous.respond_to?(:hidden?) ? previous.hidden? : false)
      previous.erase! if previous && previous.valid?
      pseudo_item = item.merge('name' => "建筑_#{item['name']}")
      definition, = load_space_definition_collision_safe!(path, pseudo_item, revision, model)
      candidate = model.entities.add_instance(definition, identity_transformation)
      candidate = normalize_loaded_space_instance!(candidate, definition, model)
      repair_redundant_empty_shells!(candidate, model, context: "建筑 #{item['number']}:#{item['name']} 更新载入")
      package_id = candidate.get_attribute(ENTITY_DICT, 'space_package_space_id_hint', '').to_s
      expected_id = "architecture:#{item['id']}"
      if !package_id.empty? && package_id != expected_id
        raise '载入包属于其他建筑模型，已阻止错误替换。'
      end
      stored = store_path(source, model)
      mark_architecture_model_entity!(candidate, item, stored, signature, model, revision: revision)
      candidate.hidden = hidden if candidate.respond_to?(:hidden=)
      architecture_model_entities(model).each do |other|
        next if other == candidate
        next unless other.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s == item['id'].to_s
        other.erase! if other.valid?
      end
      item['model_path'] = stored
      item['last_signature'] = signature
      item['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['status'] = '建筑模型已载入'
      item['editing'] = false
      candidate
    end

    def update_architecture_model(architecture_id, notify: true, model: Sketchup.active_model, state: nil, refresh_ui: true)
      raise '该建筑正在后台发布，完成前不能更新/载入。' if architecture_background_publish_active?(architecture_id)
      raise '请先退出组件编辑层级，再更新建筑模型。' unless model.active_path.nil?
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再更新建筑模型。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再更新建筑模型。' if @updating || @single_space_update_job || @space_batch_update_job
      raise '模型库批量任务正在执行，请等待完成后再更新建筑模型。' if @soft_model_batch_job
      state = ensure_architecture_models_ready!(model) unless state.is_a?(Hash)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      if state['architecture_editing_id'].to_s == item['id'].to_s || item['editing']
        return false unless native_confirm_yes?("#{architecture_display_name(item, state)} 当前有未发布修改。\n继续更新会放弃本机未发布内容，是否继续？")
        release_space_lock!(item, auto_relocate(item['model_path'].to_s, model), model: model, state: state)
        clear_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), model)
        restore_architecture_model_isolation!(item, model)
        clear_space_safe_pause!(item)
        item['editing'] = false
        state['architecture_editing_id'] = ''
      end
      model.start_operation("更新建筑模型 #{architecture_display_name(item, state)}", true)
      load_architecture_model_instance!(item, model, state: state, force_visible: true)
      save_state(state, model, write_manifest: false)
      model.commit_operation
      refresh_dialog if refresh_ui
      show_status("#{architecture_display_name(item, state)} 已更新。", 'success') if notify
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    # 建筑已经是多模型集合。进入某个建筑编辑时，只隔离“其他专业”的参考，
    # 不能把 #2/#3 等同专业建筑一起隐藏。否则顶部小眼睛即使只切换其他专业，
    # 同专业建筑也会因为进入编辑时的旧隔离快照一直保持隐藏。
    def isolate_architecture_model_for_edit!(item, entity, state, model = Sketchup.active_model)
      snapshot = {}
      references_visible = workspace_references_visible?(state, model)
      managed_root_index(model)[:all].each do |other|
        next unless other && other.valid? && other != entity
        key = entity_persistent_key(other).to_s
        original_hidden = other.respond_to?(:hidden?) ? !!other.hidden? : false
        snapshot[key] = original_hidden
        next unless other.respond_to?(:hidden=)

        # 同专业建筑完全保留进入编辑前的显隐状态；组眼睛/单卡片眼睛优先。
        # 只有室内、景观等跨专业根模型才受顶部“其他专业参考”小眼睛控制。
        if managed_root_effective_discipline(other) == 'architecture'
          other.hidden = original_hidden
        else
          other.hidden = references_visible ? original_hidden : true
        end
      rescue StandardError
        next
      end
      item['isolation_snapshot'] = snapshot
      entity.hidden = false if entity.respond_to?(:hidden=)
      true
    end

    def restore_architecture_model_isolation!(item, model = Sketchup.active_model)
      snapshot = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
      managed_root_index(model)[:all].each do |entity|
        next unless entity && entity.valid?
        key = entity_persistent_key(entity).to_s
        entity.hidden = snapshot[key] if snapshot.key?(key) && entity.respond_to?(:hidden=)
      end
      item['isolation_snapshot'] = {}
      true
    end

    def edit_architecture_model(architecture_id, model = Sketchup.active_model)
      raise '该建筑正在后台发布，完成前不能重新进入修改。' if architecture_background_publish_active?(architecture_id)
      state = ensure_architecture_models_ready!(model)
      # v0.13.1：建筑多模型与室内空间统一为同一套编辑逻辑。跨专业工作区选中建筑后也可直接修改，
      # 协作锁记录实际 actor_role；名称栏会用（建筑）前缀提示当前操作对象。
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      preflight_source = auto_relocate(item['model_path'].to_s, model)
      raise '建筑模型源文件不存在。' unless File.file?(preflight_source)
      assert_latest_safe_checkpoint_consistent!(preflight_source, "architecture_model_#{item['id']}", "建筑 #{architecture_display_name(item, state)}")
      switched_focus = prepare_edit_focus_switch!(edit_root_key_for_architecture_model(item['id']), model)
      raise '当前仍在与 LinkHub 无关的组件层级中，请先退出后再修改建筑。' unless model.active_path.nil?
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      entity = architecture_model_entity(item['id'], model)
      update_architecture_model(item['id'], notify: false, model: model) unless entity && entity.valid?
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      entity = architecture_model_entity(item['id'], model)
      raise '建筑模型根组件不可用，无法进入修改。' unless entity && entity.valid?
      safe_resume = space_edit_safe_paused?(item)
      source = auto_relocate(item['model_path'].to_s, model)
      raise '建筑模型源文件不存在。' unless File.file?(source)
      assert_latest_safe_checkpoint_consistent!(source, "architecture_model_#{item['id']}", "建筑 #{architecture_display_name(item, state)}")
      acquired_here = false
      lock = space_lock_info(item, model, source_path: source, state: state)
      unless lock['exists'] && !lock['stale'] && lock['owned']
        acquire_space_lock!(item, source, state)
        acquired_here = true
      end
      clear_space_safe_pause!(item) if safe_resume
      model.start_operation("修改建筑模型 #{architecture_display_name(item, state)}", true)
      isolate_architecture_model_for_edit!(item, entity, state, model) unless item['editing'] && item['isolation_snapshot'].is_a?(Hash) && !item['isolation_snapshot'].empty?
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      item['editing'] = true
      item['edit_actor_role'] = 'architecture'
      item['status'] = '待发布 · 修改中'
      state['architecture_editing_id'] = item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.selection.clear
      model.selection.add(entity)
      model.commit_operation
      capture_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), entity, model)
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, edit_root_key_for_architecture_model(item['id'])]] = false
      entered = enter_architecture_model_edit_context!(item, entity, model)
      refresh_dialog
      if entered
        if safe_resume
          show_status("#{architecture_display_name(item, state)} 已继续未发布修改。", 'success')
        elsif switched_focus
          show_status("已安全暂存上一协同单元，并进入 #{architecture_display_name(item, state)}。", 'success')
        else
          show_status("已进入 #{architecture_display_name(item, state)}；ESC 可退出到全模，双击可再次进入。", 'success')
        end
      else
        show_status('建筑已解锁，但 SketchUp 未能自动进入；请双击建筑根组件继续。', 'error')
      end
      true
    rescue StandardError
      model.abort_operation rescue nil
      release_space_lock!(item, source, model: model, state: state) if defined?(acquired_here) && acquired_here && defined?(item) && item && !source.to_s.empty?
      raise
    end

    def retry_initial_architecture_publish!(item, state, model = Sketchup.active_model)
      raise '建筑首次发布已经在后台队列中。' if architecture_background_publish_active?(item['id'])
      target = resolve_path(item['model_path'].to_s, model)
      raise '建筑首次发布目标路径无效。' if target.to_s.empty?
      raise '共享端已经出现同名建筑文件；为避免覆盖，不能直接重试首次发布。请先刷新建筑清单核对。' if File.exist?(target)
      candidate = item['initial_publish_candidate'].to_s
      raise '首次发布候选已经丢失，请删除该本地待发布建筑后重新新增。' unless File.file?(candidate) && File.size(candidate).positive?
      job_id = "bgarch-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      revision = item['source_revision'].to_s
      revision = new_publish_revision("architecture-model-#{item['id']}") if revision.empty?
      item['source_revision'] = revision
      item['initial_publish_error'] = ''
      item['background_publish_state'] = 'queued'
      item['background_publish_job_id'] = job_id
      item['background_publish_candidate'] = candidate
      item['background_publish_error'] = ''
      item['status'] = '首次发布重试已加入队列'
      save_state(state, model, write_manifest: false)
      enqueue_space_publish_job!({
        job_id: job_id, job_kind: 'architecture_model', space_id: "architecture_model:#{item['id']}",
        architecture_id: item['id'].to_s, label: "建筑 #{architecture_display_name(item, state)}",
        target: target.to_s, publish_key: "architecture_model_#{item['id']}", expected_signature: '',
        source_revision: revision, source_model_path: model.path.to_s, model_object_id: model.object_id,
        prepared: { path: candidate, size: File.size(candidate), content_signature: '' },
        initial_publish: true, proxy_layout: false
      }, model)
      show_status("#{architecture_display_name(item, state)} 首次发布已重新加入队列。", 'success')
      true
    rescue StandardError => e
      item['background_publish_state'] = 'failed' if item
      item['background_publish_job_id'] = '' if item
      item['initial_publish_error'] = e.message.to_s if item
      save_state(state, model, write_manifest: false) rescue nil
      raise
    end

    def publish_architecture_model(architecture_id, model = Sketchup.active_model)
      explicit_guard_acquired = false
      publish_guard_acquired = false
      publish_error = nil
      candidate_operation_open = false
      queue_operation_open = false
      enqueued = false
      raise '建筑发布正在进行，请稍候。' if @architecture_explicit_publish_in_progress
      raise '模型正在更新或恢复上一发布版，请等待完成后再发布。' if @updating || @single_space_update_job || @space_batch_update_job
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      return retry_initial_architecture_publish!(item, state, model) if item['initial_publish_pending'] == true
      raise '该建筑模型已经在后台发布队列中。' if architecture_background_publish_active?(item['id'])

      @architecture_explicit_publish_in_progress = true
      explicit_guard_acquired = true
      entity = architecture_model_entity(item['id'], model)
      raise '建筑模型尚未载入。' unless entity && entity.valid?
      source = auto_relocate(item['model_path'].to_s, model)
      lock = space_lock_info(item, model, source_path: source, state: state)
      if lock['exists'] && !lock['stale'] && lock['process_owned'] && !lock['owned'] &&
         lock['token'].to_s == item['edit_lock_token'].to_s && !item['edit_lock_token'].to_s.empty?
        lock = force_takeover_same_user_space_lock!(item, source, state, model, allow_current_process: true)
      end
      unless lock && lock['exists'] && !lock['stale'] && lock['owned'] &&
             (item['editing'] || entity.get_attribute(ENTITY_DICT, 'editing', false) || !entity_native_locked?(entity))
        raise '请先点击该建筑模型的“修改”并取得占用。'
      end
      prepare_explicit_publish_root_context!('architecture_model', item['id'], state, model)
      validate_architecture_model_edit_structure!(item, entity, model, interactive_definition_rebind: true)
      assets_dir = architecture_models_assets_dir(state, model)
      FileUtils.mkdir_p(assets_dir)
      target = File.join(assets_dir, safe_architecture_filename(item['number'], item['name']))
      expected = File.file?(source) ? fast_file_signature(source) : item['last_signature'].to_s
      publish_guard_acquired = enter_publish_critical_section!(
        kind: 'architecture_model', subject: "建筑模型 #{architecture_display_name(item, state)} 发布候选封装", target: target, model: model
      )
      publish_breadcrumb!('architecture_model_publish_preflight', architecture_id: item['id'].to_s, target: target, background_queue: true)
      publish_breadcrumb!(
        'work_model_recovery_deferred_to_candidate',
        context: "建筑模型 #{architecture_display_name(item, state)} 发布",
        reason: '统一异步发布：本机发布候选即为未发布内容恢复点，不再额外保存整份工作 SU'
      )

      revision = new_publish_revision("architecture-model-#{item['id']}")
      label = "建筑 #{architecture_display_name(item, state)}"
      job_id = "bgarch-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      model.start_operation("生成建筑后台发布候选 #{architecture_display_name(item, state)}", true)
      candidate_operation_open = true
      entity.locked = false if entity.respond_to?(:locked=)
      bake_space_outer_transformation!(entity)
      wrapper, = build_space_publish_wrapper!(entity, model, representation: 'full', package_revision: revision, space_id: "architecture:#{item['id']}")
      prepared = serialize_publish_definition_candidate!(wrapper, target, "architecture_model_#{item['id']}", defer_content_signature: true)
      publish_breadcrumb!('architecture_candidate_prepared', candidate: prepared[:path].to_s, size: prepared[:size].to_i)
      model.abort_operation
      candidate_operation_open = false
      entity = architecture_model_entity(item['id'], model)
      raise '建筑候选生成后未能恢复根实例。' unless entity && entity.valid?

      model.start_operation("加入建筑后台发布队列 #{architecture_display_name(item, state)}", true, false, true)
      queue_operation_open = true
      restore_architecture_model_isolation!(item, model)
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      item['editing'] = false
      item['publish_pending'] = false
      item['background_publish_state'] = 'queued'
      item['background_publish_job_id'] = job_id
      item['background_publish_candidate'] = prepared[:path].to_s
      item['background_publish_error'] = ''
      item['status'] = '已加入发布队列 · 后台等待发布 · 协作占用保留'
      state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      queue_operation_open = false
      clear_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), model)

      enqueue_space_publish_job!({
        job_id: job_id, job_kind: 'architecture_model', space_id: "architecture_model:#{item['id']}",
        architecture_id: item['id'].to_s, label: label, target: target.to_s,
        publish_key: "architecture_model_#{item['id']}", expected_signature: expected.to_s,
        baseline_path: source.to_s, baseline_signature: expected.to_s, force_overwrite: false,
        source_revision: revision, source_model_path: model.path.to_s, model_object_id: model.object_id,
        prepared: prepared, initial_publish: false, proxy_layout: false
      }, model)
      enqueued = true
      show_status("#{label} 已加入发布队列；现在可以继续操作其它模型。", 'success')
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      true
    rescue StandardError => e
      publish_error = e
      model.abort_operation rescue nil if candidate_operation_open
      model.abort_operation rescue nil if queue_operation_open
      if defined?(item) && item && !enqueued
        begin
          recovery_state = ensure_architecture_models_ready!(model)
          recovery_item = architecture_model_record(recovery_state, item['id'])
          recovery_entity = recovery_item ? architecture_model_entity(recovery_item['id'], model) : nil
          if recovery_item
            recovery_item['editing'] = true
            recovery_item['edit_safe_paused'] = true
            recovery_item['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
            recovery_item['edit_safe_pause_reason'] = '建筑后台发布入队失败'
            recovery_item['background_publish_state'] = ''
            recovery_item['background_publish_job_id'] = ''
            recovery_item['status'] = '发布队列加入失败 · 未发布建筑修改已安全暂存'
            if recovery_entity && recovery_entity.valid?
              recovery_entity.locked = true if recovery_entity.respond_to?(:locked=)
              recovery_entity.set_attribute(ENTITY_DICT, 'editing', true)
              recovery_entity.set_attribute(ENTITY_DICT, 'safe_paused', true)
            end
            save_state(recovery_state, model, write_manifest: false)
          end
        rescue StandardError => recovery_error
          log_exception('建筑后台发布入队失败后恢复暂存失败', recovery_error)
        end
      end
      raise
    ensure
      @architecture_explicit_publish_in_progress = false if explicit_guard_acquired
      leave_publish_critical_section!(success: !!enqueued, error: publish_error, model: model) if publish_guard_acquired
    end

    # 建筑与室内统一：取消修改会恢复共享上一发布版，成功后才释放占用。
    def cancel_architecture_modifications!(architecture_id, model = Sketchup.active_model)
      raise '已有发布或更新任务正在执行，请等待完成后再取消修改。' if publish_critical_section? || @updating || @single_space_update_job
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      entity = architecture_model_entity(item['id'], model)
      raise '该建筑模型尚未载入。' unless entity && entity.valid?
      raise '该建筑当前不是本机待发布状态。' unless explicit_local_pending_architecture?(item, state, model)

      source = auto_relocate(item['model_path'].to_s, model)
      raise '建筑上一发布版文件不存在，不能安全取消修改。' unless File.file?(source)
      lock = space_lock_info(item, model, source_path: source, state: state)
      unless lock['exists'] && !lock['stale'] && (lock['owned'] || lock['process_owned'])
        raise '当前会话已经不再持有该建筑占用；为避免覆盖本地内容，未执行取消修改。'
      end

      baseline = normalize_fast_signature(item['last_signature'].to_s)
      current_source_signature = normalize_fast_signature(fast_file_signature(source))
      if !baseline.empty? && !current_source_signature.empty? && baseline != current_source_signature
        raise '建筑共享上一发布版在你修改期间发生了变化。为避免恢复到错误版本，已停止取消修改；请先使用“检查”确认版本状态。'
      end

      label = architecture_display_name(item, state)
      prompt = <<~TEXT
        取消修改“#{label}”？

        将放弃当前 SketchUp 中该建筑所有未发布修改，恢复到开始修改前的上一发布版，并释放协作占用。
        其他仍在待发布的建筑/空间不会受影响。

        确定继续吗？
      TEXT
      return false unless native_confirm_yes?(prompt)

      prepare_explicit_publish_root_context!('architecture_model', item['id'], state, model)
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      entity = architecture_model_entity(item['id'], model)
      raise '取消修改前目标建筑已失效。' unless item && entity && entity.valid?

      operation_open = false
      model.start_operation("取消建筑修改 #{label}", true)
      operation_open = true
      restore_architecture_model_isolation!(item, model)
      entity.locked = true if entity.respond_to?(:locked=)
      loaded = load_architecture_model_instance!(item, model, state: state, force_visible: true)
      raise '上一发布版载入失败。' unless loaded && loaded.valid?

      release_space_lock!(item, source, model: model, state: state)
      clear_space_lock_state!(item)
      clear_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), model)
      clear_space_safe_pause!(item)
      item['editing'] = false
      item['status'] = '已取消修改 · 已恢复上一发布版'
      state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
      @architecture_model_edit_contexts&.delete(model.object_id)
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, edit_root_key_for_architecture_model(item['id'])]] = true
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      refresh_dialog
      show_status("#{label} 已取消修改并恢复到上次发布版；占用已释放。", 'success')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      log_exception('取消建筑修改失败', e)
      raise
    ensure
      refresh_workspace_toolbar(model) rescue nil
    end

    def release_same_user_architecture_occupancy!(architecture_id, model = Sketchup.active_model)
      raise '该建筑正在后台发布，正式发布完成前不能解除协作占用。' if architecture_background_publish_active?(architecture_id)
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到该建筑模型。' unless item
      source = auto_relocate(item['model_path'].to_s, model)
      record = read_lock_record(edit_lock_path_for(source))
      raise '该建筑模型当前没有占用。' unless record
      owner = record['owner'].to_s
      raise '当前用户无权回收其他成员的占用。' unless !owner.empty? && normalize_lock_identity(owner) == normalize_lock_identity(current_user_name)
      entity = architecture_model_entity(item['id'], model)
      local_session = lock_record_from_current_process?(record) || local_architecture_model_edit_session?(item, state, model) ||
                      state['architecture_editing_id'].to_s == item['id'].to_s
      if local_session
        raise '当前 SketchUp 正在修改这个建筑模型，不能单独解除占用。请使用“发布”或“取消修改”结束协同编辑。'
      end
      lock_path = edit_lock_path_for(source)
      unless same_user_lock_recoverable?(record) || space_lock_record_stale?(record, lock_path)
        raise '同名用户的另一个活动 SketchUp 会话仍在持有该建筑占用。请回到原会话发布/取消，或关闭原会话后再回收遗留占用。'
      end
      return false unless native_confirm_yes?("回收 #{architecture_display_name(item, state)} 的本人遗留占用？\n只处理已经中断的旧会话，不发布、不覆盖模型，也不会退出你当前正在编辑的其他组件。")
      current_record = read_lock_record(lock_path)
      unless current_record && current_record['token'].to_s == record['token'].to_s &&
             !current_record['owner'].to_s.empty? &&
             normalize_lock_identity(current_record['owner']) == normalize_lock_identity(current_user_name)
        raise '占用状态刚刚发生变化，未执行回收；请刷新后重试。'
      end
      annotated = current_record.dup
      annotated['released_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      annotated['released_reason'] = 'same_user_architecture_manual_release'
      annotated['released_by_owner'] = current_user_name
      annotated['released_by_host'] = current_host_name
      annotated['released_by_pid'] = Process.pid
      annotated['released_by_session_id'] = current_runtime_session_id
      write_lock_record(lock_path, annotated, expected_token: current_record['token'])
      verified = read_lock_record(lock_path)
      raise '回收前锁文件校验失败，未修改占用。' unless verified && verified['token'].to_s == current_record['token'].to_s

      entity.locked = true if entity && entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', false) if entity
      restore_architecture_model_isolation!(item, model)
      archived = archive_lock_file(lock_path, source, 'same_user_architecture_manual_release')
      File.delete(lock_path) if !archived && File.file?(lock_path)
      raise '无法归档或删除占用锁，请检查协同文件夹权限。' if File.file?(lock_path)
      clear_space_lock_state!(item)
      clear_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), model)
      clear_space_safe_pause!(item)
      item['editing'] = false
      item['status'] = '已回收本人遗留占用'
      state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def toggle_architecture_model_visibility(architecture_id, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      entity = item ? architecture_model_entity(item['id'], model) : nil
      raise '该建筑模型尚未载入。' unless entity && entity.valid?
      entity.hidden = !entity.hidden? if entity.respond_to?(:hidden=)
      refresh_dialog
      true
    end

    def toggle_architecture_collection_visibility(model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      entities = architecture_model_entities(model)
      if state['architecture_collection_hidden']
        snapshot = state['architecture_collection_visibility_snapshot'].is_a?(Hash) ? state['architecture_collection_visibility_snapshot'] : {}
        entities.each do |entity|
          key = entity_persistent_key(entity).to_s
          entity.hidden = snapshot[key] if snapshot.key?(key) && entity.respond_to?(:hidden=)
        end
        state['architecture_collection_hidden'] = false
        state['architecture_collection_visibility_snapshot'] = {}
      else
        snapshot = {}
        entities.each do |entity|
          key = entity_persistent_key(entity).to_s
          snapshot[key] = entity.respond_to?(:hidden?) ? entity.hidden? : false
          entity.hidden = true if entity.respond_to?(:hidden=)
        end
        state['architecture_collection_hidden'] = true
        state['architecture_collection_visibility_snapshot'] = snapshot
      end
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def architecture_group_record(state, group_id)
      Array(state['architecture_groups']).find { |group| group['id'].to_s == group_id.to_s }
    end

    def persist_architecture_layout!(state, model = Sketchup.active_model)
      raise '有建筑模型正在后台发布；为避免共享清单竞态，请等待正式文件完成后再调整建筑分组/排序。' if architecture_collection_background_publish_active?(state)
      state['architecture_layout_revision'] = SecureRandom.uuid
      state['architecture_layout_updated_at'] = Time.now.iso8601(6)
      state['architecture_layout_updated_by'] = current_user_name
      state['architecture_layout_updated_host'] = current_host_name
      normalize_architecture_models_state!(state, model)
      write_architecture_models_manifest!(state, model)
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def create_architecture_group(model_ids, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      records = Array(model_ids).map { |id| architecture_model_record(state, id) }.compact
      raise '请先选择要成组的建筑模型。' if records.empty?
      response = UI.inputbox(['组名称'], [''], '新建建筑组')
      return false unless response
      name = normalize_space_name(response[0])
      raise '组名称不能为空。' if name.empty?
      group = { 'id' => SecureRandom.uuid, 'name' => name, 'order' => Array(state['architecture_groups']).length, 'collapsed' => false, 'visibility_suspended' => false, 'visibility_restore_ids' => [] }
      state['architecture_groups'] << group
      records.each_with_index { |item, index| item['group_id'] = group['id']; item['group_order'] = index }
      persist_architecture_layout!(state, model)
    end

    def rename_architecture_group(group_id, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      group = architecture_group_record(state, group_id)
      raise '找不到建筑组。' unless group
      response = UI.inputbox(['组名称'], [group['name'].to_s], '修改建筑组名称')
      return false unless response
      name = normalize_space_name(response[0])
      raise '组名称不能为空。' if name.empty?
      group['name'] = name
      persist_architecture_layout!(state, model)
    end

    def toggle_architecture_group_collapsed(group_id, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      group = architecture_group_record(state, group_id)
      raise '找不到建筑组。' unless group
      group['collapsed'] = !group['collapsed']
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def toggle_architecture_group_visibility(group_id, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      group = architecture_group_record(state, group_id)
      raise '找不到建筑组。' unless group
      members = Array(state['architecture_models']).select { |item| item['group_id'].to_s == group['id'].to_s }
      entities = members.filter_map { |item| architecture_model_entity(item['id'], model) }
      if group['visibility_suspended']
        restore = Array(group['visibility_restore_ids']).map(&:to_s)
        entities.each do |entity|
          id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
          entity.hidden = false if restore.include?(id) && entity.respond_to?(:hidden=)
        end
        group['visibility_suspended'] = false
        group['visibility_restore_ids'] = []
      else
        visible_ids = entities.reject { |entity| entity.hidden? }.map { |entity| entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s }
        entities.each { |entity| entity.hidden = true if entity.respond_to?(:hidden=) }
        group['visibility_suspended'] = true
        group['visibility_restore_ids'] = visible_ids
      end
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def rename_architecture_model(architecture_id, model = Sketchup.active_model)
      raise '该建筑正在后台发布，完成前不能重命名。' if architecture_background_publish_active?(architecture_id)
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到建筑模型。' unless item
      raise '首次发布尚未完成的建筑不能重命名；请先发布成功或删除后重新新增。' if item['initial_publish_pending'] == true
      raise '修改中的建筑模型不能重命名。' if item['editing']
      response = UI.inputbox(['建筑名称'], [item['name'].to_s], '修改建筑模型名称')
      return false unless response
      name = normalize_space_name(response[0])
      raise '建筑名称不能为空。' if name.empty?
      old_path = auto_relocate(item['model_path'].to_s, model)
      new_path = File.join(architecture_models_assets_dir(state, model), safe_architecture_filename(item['number'], name))
      if File.file?(old_path) && !same_file_path?(old_path, new_path)
        FileUtils.mkdir_p(File.dirname(new_path))
        FileUtils.mv(old_path, new_path)
        old_lock = edit_lock_path_for(old_path)
        FileUtils.mv(old_lock, edit_lock_path_for(new_path)) if File.file?(old_lock)
      end
      item['name'] = name
      item['model_path'] = store_path(new_path, model)
      entity = architecture_model_entity(item['id'], model)
      entity.name = safe_architecture_filename(item['number'], name) if entity && entity.respond_to?(:name=)
      persist_architecture_layout!(state, model)
    end

    def delete_architecture_model(architecture_id, model = Sketchup.active_model, confirm: true)
      raise '该建筑正在后台发布，完成前不能删除。' if architecture_background_publish_active?(architecture_id)
      state = ensure_architecture_models_ready!(model)
      item = architecture_model_record(state, architecture_id)
      raise '找不到建筑模型。' unless item
      initial_pending = item['initial_publish_pending'] == true
      lock = space_lock_info(item, model, state: state)
      raise '修改中或占用中的建筑模型不能删除。' if item['editing'] || (lock['exists'] && !lock['stale'])
      prompt = if initial_pending
                 "删除 #{architecture_display_name(item, state)}？\n该建筑尚未完成首次共享发布，只会删除本地受管实例和本地首次发布候选；绝不会删除后来出现的同名共享 SKP。"
               else
                 "删除 #{architecture_display_name(item, state)}？\n将删除协同 SKP 和当前模型中的受管实例。"
               end
      return false if confirm && !native_confirm_yes?(prompt)
      entity = architecture_model_entity(item['id'], model)
      entity.erase! if entity && entity.valid?
      clear_edit_root_protection!(edit_root_key_for_architecture_model(item['id']), model)
      source = initial_pending ? resolve_path(item['model_path'].to_s, model) : auto_relocate(item['model_path'].to_s, model)
      candidate = item['initial_publish_candidate'].to_s
      File.delete(source) if !initial_pending && File.file?(source)
      File.delete(candidate) if initial_pending && !candidate.empty? && File.file?(candidate)
      state['architecture_models'].delete_if { |candidate_item| candidate_item['id'].to_s == item['id'].to_s }
      state['architecture_layout_revision'] = SecureRandom.uuid
      normalize_architecture_models_state!(state, model)
      unless initial_pending
        write_architecture_models_manifest!(state, model, deleted_model_ids: [item['id']])
      end
      save_state(state, model, write_manifest: false)
      refresh_dialog
      true
    end

    def update_all_architecture_models(notify: true, model: Sketchup.active_model, state: nil)
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再批量更新建筑模型。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再批量更新建筑模型。' if @updating || @single_space_update_job || @space_batch_update_job
      raise '模型库批量任务正在执行，请等待完成后再批量更新建筑模型。' if @soft_model_batch_job
      state = ensure_architecture_models_ready!(model) unless state.is_a?(Hash)
      candidates = Array(state['architecture_models']).select do |item|
        next false if architecture_background_publish_active?(item['id']) || item['initial_publish_pending'] == true
        next false if state['architecture_editing_id'].to_s == item['id'].to_s || local_architecture_model_edit_session?(item, state, model)
        entity = architecture_model_entity(item['id'], model)
        source = auto_relocate(item['model_path'].to_s, model)
        File.file?(source) && architecture_model_update_direction(item, entity, model) != :same
      end
      if candidates.empty?
        show_status('建筑模型均已是当前发布版。', 'success') if notify
        return true
      end
      updated = 0
      failed = []
      candidates.each do |item|
        begin
          updated += 1 if update_architecture_model(
            item['id'], notify: false, model: model, state: state, refresh_ui: false
          )
        rescue StandardError => e
          failed << "#{architecture_display_name(item, state)}：#{e.message}"
          log_exception("批量更新建筑模型失败：#{item['id']}", e)
        end
      end
      if notify
        if failed.empty?
          show_status("已更新 #{updated} 个建筑模型。", 'success')
        else
          show_status("建筑模型更新完成 #{updated}/#{candidates.length}；#{failed.first}", 'error')
        end
      end
      refresh_dialog
      failed.empty?
    end

    def selected_architecture_model_record(state, model = Sketchup.active_model)
      return nil unless model && model.active_path.nil?
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      architecture_id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s rescue ''
      architecture_id.empty? ? nil : architecture_model_record(state, architecture_id)
    rescue StandardError
      nil
    end

    def architecture_collection_quick_action(model = Sketchup.active_model, state: nil)
      state = ensure_architecture_models_ready!(model) unless state.is_a?(Hash)
      selected = selected_architecture_model_record(state, model)
      if selected
        if architecture_background_publish_active?(selected['id'])
          job = background_publish_job_snapshot("architecture_model:#{selected['id']}")
          show_status("#{architecture_display_name(selected, state)} 正在后台发布 #{job['progress'].to_i}% · #{job['stage_label']}", 'info')
          return true
        end
        return retry_initial_architecture_publish!(selected, state, model) if selected['initial_publish_pending'] == true
        return publish_architecture_model(selected['id'], model) if local_pending_architecture?(selected, state, model)
        entity = architecture_model_entity(selected['id'], model)
        direction = architecture_model_update_direction(selected, entity, model)
        return update_architecture_model(selected['id'], notify: true, model: model, state: state) if direction != :same || !entity
        return edit_architecture_model(selected['id'], model)
      end
      initial_pending = Array(state['architecture_models']).select { |row| row['initial_publish_pending'] == true && !architecture_background_publish_active?(row['id']) }
      return retry_initial_architecture_publish!(initial_pending.first, state, model) if initial_pending.length == 1
      raise "当前有 #{initial_pending.length} 个建筑首次发布待重试，请先选中目标建筑。" if initial_pending.length > 1
      pending = local_pending_architecture_records(state, model)
      return publish_architecture_model(pending.first['id'], model) if pending.length == 1
      raise "当前有 #{pending.length} 个建筑模型待发布，请先选中目标建筑。" if pending.length > 1
      update_all_architecture_models(notify: true, model: model, state: state)
    end

    def request_delete_selected_architecture_models(ids, model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      records = Array(ids).map { |id| architecture_model_record(state, id) }.compact
      raise '请先勾选要删除的建筑模型。' if records.empty?
      busy = records.select do |item|
        source = item['initial_publish_pending'] == true ? resolve_path(item['model_path'].to_s, model) : auto_relocate(item['model_path'].to_s, model)
        architecture_background_publish_active?(item['id']) || item['editing'] || space_lock_info(item, model, source_path: source, state: state)['exists']
      end
      raise '修改中或被占用的建筑模型不能删除。' unless busy.empty?
      names = records.first(4).map { |item| architecture_display_name(item, state) }.join('、')
      names += " 等 #{records.length} 个" if records.length > 4
      return false unless native_confirm_yes?("删除 #{names}？\n会删除对应协同 SKP 和当前模型实例。")
      records.each { |item| delete_architecture_model(item['id'], model, confirm: false) }
      true
    end

    def landscape_library_root
      return @landscape_library_root_session.to_s if defined?(@landscape_library_root_session) && !@landscape_library_root_session.nil?
      path = Sketchup.read_default(LANDSCAPE_LIBRARY_PREF_SECTION, LANDSCAPE_LIBRARY_ROOT_PREF_KEY, '').to_s
      @landscape_library_root_session = path.empty? ? '' : FastPath.expand(path)
    rescue StandardError
      @landscape_library_root_session = ''
    end

    def landscape_library_manager_dir(root = landscape_library_root)
      root.to_s.empty? ? '' : File.join(root, LANDSCAPE_LIBRARY_MANAGER_DIR)
    end

    def landscape_library_thumbnail_dir(root = landscape_library_root)
      dir = landscape_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, LANDSCAPE_LIBRARY_THUMB_DIR)
    end

    def landscape_library_thumbnail_meta_path(root = landscape_library_root)
      dir = landscape_library_thumbnail_dir(root)
      dir.empty? ? '' : File.join(dir, LANDSCAPE_LIBRARY_THUMB_META_FILE)
    end

    def landscape_library_catalog_path(root = landscape_library_root)
      dir = landscape_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, LANDSCAPE_LIBRARY_CATALOG_FILE)
    end

    def ensure_landscape_library_structure!(root = landscape_library_root)
      raise '尚未设置景观模型库路径。' if root.to_s.empty?
      FileUtils.mkdir_p(root)
      FileUtils.mkdir_p(landscape_library_manager_dir(root))
      FileUtils.mkdir_p(landscape_library_thumbnail_dir(root))
      meta = landscape_library_thumbnail_meta_path(root)
      write_json_atomic(meta, { 'schema' => 1, 'models' => {} }) unless File.file?(meta)
      true
    end

    def set_landscape_library_root(path, persist_project: true)
      root = path.to_s.empty? ? '' : FastPath.expand(path.to_s)
      raise '请选择有效的景观模型库文件夹。' if root.empty? || !Dir.exist?(root)
      Sketchup.write_default(LANDSCAPE_LIBRARY_PREF_SECTION, LANDSCAPE_LIBRARY_ROOT_PREF_KEY, root)
      @landscape_library_root_session = root
      ensure_landscape_library_structure!(root)
      @landscape_library_cache = nil
      @landscape_thumbnail_meta_cache = nil
      persist_project_path_setting!('landscape_model_root', root) if persist_project
      root
    end

    def choose_landscape_library_root
      options = { title: '选择景观模型库文件夹' }
      current = landscape_library_root
      options[:directory] = current unless current.empty?
      path = UI.select_directory(options)
      return false if path.nil? || path.to_s.empty?
      root = set_landscape_library_root(path)
      refresh_landscape_library_dialog(refresh_library: true)
      show_status("景观模型库已设置：#{root}", 'success')
      true
    end

    def landscape_thumbnail_meta(root = landscape_library_root)
      return { 'schema' => 1, 'models' => {} } if root.to_s.empty?
      ensure_landscape_library_structure!(root)
      path = landscape_library_thumbnail_meta_path(root)
      signature = fast_file_signature(path)
      cached = @landscape_thumbnail_meta_cache
      if cached.is_a?(Hash) && cached[:root] == normalize_soft_library_key(root) && cached[:signature] == signature
        return cached[:data]
      end
      data = JSON.parse(File.read(path, encoding: 'UTF-8'))
      data = {} unless data.is_a?(Hash)
      data['schema'] = 1
      data['models'] = {} unless data['models'].is_a?(Hash)
      @landscape_thumbnail_meta_cache = {
        root: normalize_soft_library_key(root), signature: signature, data: data
      }
      data
    rescue StandardError => e
      log_exception('读取景观缩略图索引失败', e)
      { 'schema' => 1, 'models' => {} }
    end

    def write_landscape_thumbnail_meta!(data, root = landscape_library_root)
      ensure_landscape_library_structure!(root)
      payload = data.is_a?(Hash) ? data : {}
      payload['schema'] = 1
      payload['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      payload['models'] = {} unless payload['models'].is_a?(Hash)
      path = landscape_library_thumbnail_meta_path(root)
      write_json_atomic(path, payload)
      @landscape_thumbnail_meta_cache = {
        root: normalize_soft_library_key(root), signature: fast_file_signature(path), data: payload
      }
      true
    end

    def landscape_model_thumbnail_path(path, root = landscape_library_root)
      File.join(landscape_library_thumbnail_dir(root), "#{soft_model_id_for_path(path)}.png")
    end

    def landscape_thumbnail_signature(path)
      "landscape-source-embedded-v1|#{fast_file_signature(path)}"
    rescue StandardError
      ''
    end

    def landscape_thumbnail_current?(path, thumb = nil, root = landscape_library_root)
      return false unless File.file?(path)
      thumb ||= landscape_model_thumbnail_path(path, root)
      return false unless File.file?(thumb) && File.size(thumb).positive?
      record = landscape_thumbnail_meta(root).dig('models', soft_model_id_for_path(path))
      record.is_a?(Hash) && record['signature'].to_s == landscape_thumbnail_signature(path)
    rescue StandardError
      false
    end

    def record_landscape_thumbnail!(source, thumb, root = landscape_library_root)
      return false unless File.file?(source) && File.file?(thumb) && File.size(thumb).positive?
      data = landscape_thumbnail_meta(root)
      data['models'] ||= {}
      data['models'][soft_model_id_for_path(source)] = {
        'signature' => landscape_thumbnail_signature(source),
        'thumbnail' => File.basename(thumb),
        'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S')
      }
      write_landscape_thumbnail_meta!(data, root)
      true
    end

    def ensure_landscape_model_thumbnail(path, root = landscape_library_root, force: false)
      return '' unless File.file?(path)
      ensure_landscape_library_structure!(root)
      thumb = landscape_model_thumbnail_path(path, root)
      return thumb if !force && landscape_thumbnail_current?(path, thumb, root)
      temp = "#{thumb}.tmp-#{Process.pid}-#{SecureRandom.hex(4)}.png"
      File.delete(temp) if File.file?(temp)
      ok = Sketchup.save_thumbnail(path, temp)
      raise '源景观模型没有可读取的内置缩略图。' unless ok != false && File.file?(temp) && File.size(temp).positive?
      linkhub_mv(temp, thumb)
      record_landscape_thumbnail!(path, thumb, root)
      thumb
    rescue StandardError => e
      log_exception("读取景观模型内置缩略图失败：#{path}", e)
      ''
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def landscape_library_folder_for(path, root)
      relative = Pathname.new(File.dirname(path)).relative_path_from(Pathname.new(root)).to_s.tr('\\', '/')
      relative == '.' ? '' : relative
    rescue StandardError
      ''
    end

    def read_landscape_library_catalog(root = landscape_library_root)
      path = landscape_library_catalog_path(root)
      return nil if path.to_s.empty? || !File.file?(path)
      data = JSON.parse(File.read(path, encoding: 'UTF-8'))
      return nil unless data.is_a?(Hash) && [1, 2].include?(data['schema'].to_i)
      return nil unless normalize_soft_library_key(data['root']) == normalize_soft_library_key(root)
      items = data['items']
      items.is_a?(Array) ? items : nil
    rescue StandardError
      nil
    end

    def write_landscape_library_catalog!(items, root = landscape_library_root)
      path = landscape_library_catalog_path(root)
      return false if path.to_s.empty?
      snapshot = begin
        Marshal.load(Marshal.dump(Array(items)))
      rescue StandardError
        JSON.parse(JSON.generate(Array(items)))
      end
      enqueue_background_io_task(
        'json_write', key: "landscape_catalog|#{normalize_soft_library_key(root)}",
        data: { path: path, payload: {
          'schema' => 2, 'root' => FastPath.expand(root.to_s),
          'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S'), 'items' => snapshot
        } }, label: '景观模型库目录缓存'
      )
    rescue StandardError => e
      log_exception('写入景观目录缓存失败', e)
      false
    end

    def hydrate_landscape_library_cache!(root, items)
      list = Array(items).select { |item| item.is_a?(Hash) }.map(&:dup)
      by_id = {}
      list.each { |item| by_id[item['id'].to_s] = item }
      @landscape_library_cache = {
        root: normalize_soft_library_key(root), signature: 'catalog',
        items: list, by_id: by_id, warmed_at: monotonic_time
      }
      list
    end

    def landscape_library_cache_ready?(root = landscape_library_root)
      cache = @landscape_library_cache
      cache.is_a?(Hash) && cache[:root] == normalize_soft_library_key(root) && cache[:items].is_a?(Array)
    rescue StandardError
      false
    end

    # 纯文件 I/O 版本的景观目录扫描，专供 background_io worker。
    def background_scan_landscape_library_data(root)
      raise '景观模型库路径不可用。' if root.to_s.empty? || !Dir.exist?(root.to_s)
      root = FastPath.expand(root.to_s)
      manager_key = normalize_soft_library_key(landscape_library_manager_dir(root))
      meta = begin
        path = landscape_library_thumbnail_meta_path(root)
        File.file?(path) ? JSON.parse(File.read(path, encoding: 'UTF-8')) : {}
      rescue StandardError
        {}
      end
      meta_models = meta.is_a?(Hash) && meta['models'].is_a?(Hash) ? meta['models'] : {}
      files = Dir.glob(File.join(root, '**', '*')).select do |path|
        File.file?(path) && File.extname(path).casecmp('.skp').zero?
      end
      files.reject! { |path| normalize_soft_library_key(path).start_with?(manager_key + '/') }
      files.sort_by! { |path| normalize_soft_library_key(path) }
      files = files.first(LANDSCAPE_LIBRARY_SCAN_LIMIT)
      signatures = {}
      files.each { |path| signatures[path] = fast_file_signature(path).to_s }
      signature = Digest::SHA1.hexdigest(files.map { |path| "#{normalize_soft_library_key(path)}|#{signatures[path]}" }.join("\n"))
      items = files.map do |path|
        id = soft_model_id_for_path(path)
        thumb = landscape_model_thumbnail_path(path, root)
        expected_thumb_signature = "landscape-source-embedded-v1|#{signatures[path]}"
        thumb_record = meta_models[id]
        ready = File.file?(thumb) && File.size(thumb).to_i.positive? &&
                thumb_record.is_a?(Hash) && thumb_record['signature'].to_s == expected_thumb_signature
        {
          'id' => id,
          'name' => File.basename(path, File.extname(path)),
          'path' => FastPath.expand(path),
          'folder' => landscape_library_folder_for(path, root),
          'thumbnail_url' => ready ? soft_thumbnail_url(thumb) : '',
          'thumbnail_ready' => ready,
          'source_size_mb' => ((File.size(path).to_f / 1024.0 / 1024.0).round(1) rescue 0.0)
        }
      end
      { root: root, signature: signature, items: items }
    end

    def schedule_landscape_library_scan_background!(root = landscape_library_root, label: '景观模型库后台刷新')
      return false if root.to_s.empty? || !Dir.exist?(root.to_s)
      enqueue_background_io_task(
        'landscape_library_scan',
        key: normalize_soft_library_key(root),
        data: { root: FastPath.expand(root.to_s) },
        label: label
      )
    end

    def scan_landscape_library!(force: false)
      root = landscape_library_root
      return [] if root.empty? || !Dir.exist?(root)
      invalidate_soft_library_file_signature! if force
      ensure_landscape_library_structure!(root)
      cache = @landscape_library_cache
      if !force && cache.is_a?(Hash) && cache[:root] == normalize_soft_library_key(root)
        return cache[:items]
      end
      unless force
        cached_items = read_landscape_library_catalog(root)
        return hydrate_landscape_library_cache!(root, cached_items) if cached_items
      end
      started = monotonic_time
      files = Dir.glob(File.join(root, '**', '*')).select do |path|
        File.file?(path) && File.extname(path).casecmp('.skp').zero?
      end
      manager_key = normalize_soft_library_key(landscape_library_manager_dir(root))
      files.reject! { |path| normalize_soft_library_key(path).start_with?(manager_key + '/') }
      files.sort_by! { |path| normalize_soft_library_key(path) }
      files = files.first(LANDSCAPE_LIBRARY_SCAN_LIMIT)
      signature = Digest::SHA1.hexdigest(files.map { |path| "#{normalize_soft_library_key(path)}|#{fast_file_signature(path)}" }.join('\n'))
      items = files.map do |path|
        thumb = landscape_model_thumbnail_path(path, root)
        ready = landscape_thumbnail_current?(path, thumb, root)
        {
          'id' => soft_model_id_for_path(path),
          'name' => File.basename(path, File.extname(path)),
          'path' => FastPath.expand(path),
          'folder' => landscape_library_folder_for(path, root),
          'thumbnail_url' => ready ? soft_thumbnail_url(thumb) : '',
          'thumbnail_ready' => ready,
          'source_size_mb' => ((File.size(path).to_f / 1024.0 / 1024.0).round(1) rescue 0.0)
        }
      end
      @landscape_library_cache = {
        root: normalize_soft_library_key(root), signature: signature,
        items: items, by_id: items.to_h { |item| [item['id'].to_s, item] }
      }
      write_landscape_library_catalog!(items, root)
      log_slow_operation('景观模型库完整扫描', started, 100.0, "#{items.length} 个模型")
      items
    rescue StandardError => e
      log_exception('扫描景观模型库失败', e)
      []
    end

    def landscape_library_item(model_id, force: false)
      scan_landscape_library!(force: force)
      cache = @landscape_library_cache
      cache.is_a?(Hash) && cache[:by_id].is_a?(Hash) ? cache[:by_id][model_id.to_s] : nil
    rescue StandardError
      nil
    end

    def landscape_library_edit_context(model = Sketchup.active_model)
      state = load_state(model)
      return [state, nil, nil] unless host_discipline_for(state) == 'landscape'
      outer = native_edit_entity('landscape', model)
      source = landscape_edit_source_entity(outer)
      active = outer && outer.valid? && source && source.valid? &&
               landscape_local_edit_active?(state, model) && active_path_inside_landscape?(outer, source, model)
      active ? [state, outer, source] : [state, nil, nil]
    rescue StandardError
      [nil, nil, nil]
    end

    # 模型库和材质库的收藏 / 最近使用属于当前用户偏好，不写入共享模型库，
    # 避免多人之间互相覆盖收藏顺序。以库类型、专业和根目录生成独立桶，
    # SketchUp 重启后仍可恢复。
    def library_usage_data
      return @library_usage_data if @library_usage_data.is_a?(Hash)
      raw = Sketchup.read_default(LIBRARY_USAGE_PREF_SECTION, LIBRARY_USAGE_PREF_KEY, '').to_s
      parsed = raw.empty? ? {} : JSON.parse(raw)
      parsed = {} unless parsed.is_a?(Hash)
      parsed['schema'] = LIBRARY_USAGE_SCHEMA
      parsed['buckets'] = {} unless parsed['buckets'].is_a?(Hash)
      @library_usage_data = parsed
    rescue StandardError => e
      log_exception('读取库收藏与最近使用失败', e)
      @library_usage_data = { 'schema' => LIBRARY_USAGE_SCHEMA, 'buckets' => {} }
    end

    def save_library_usage_data!
      data = library_usage_data
      Sketchup.write_default(LIBRARY_USAGE_PREF_SECTION, LIBRARY_USAGE_PREF_KEY, JSON.generate(data))
      true
    rescue StandardError => e
      log_exception('保存库收藏与最近使用失败', e)
      false
    end

    def library_usage_bucket_key(kind, discipline, root)
      root_key = normalize_soft_library_key(root.to_s)
      Digest::SHA1.hexdigest([kind.to_s, discipline.to_s, root_key].join('|'))
    rescue StandardError
      Digest::SHA1.hexdigest([kind.to_s, discipline.to_s, root.to_s].join('|'))
    end

    def library_usage_bucket(kind, discipline, root)
      data = library_usage_data
      key = library_usage_bucket_key(kind, discipline, root)
      bucket = data['buckets'][key]
      unless bucket.is_a?(Hash)
        bucket = {
          'kind' => kind.to_s,
          'discipline' => discipline.to_s,
          'root' => root.to_s,
          'favorites' => [],
          'recent' => []
        }
        data['buckets'][key] = bucket
      end
      bucket['favorites'] = Array(bucket['favorites']).map(&:to_s).reject(&:empty?).uniq
      bucket['recent'] = Array(bucket['recent']).filter_map do |row|
        next unless row.is_a?(Hash)
        id = row['id'].to_s
        next if id.empty?
        { 'id' => id, 'used_at' => row['used_at'].to_i }
      end
      bucket
    end

    def decorate_library_usage(items, kind, discipline, root)
      bucket = library_usage_bucket(kind, discipline, root)
      favorites = bucket['favorites'].to_h { |id| [id.to_s, true] }
      recent = bucket['recent'].to_h { |row| [row['id'].to_s, row['used_at'].to_i] }
      Array(items).map do |item|
        row = item.is_a?(Hash) ? item.dup : {}
        id = row['id'].to_s
        row['favorite'] = favorites[id] == true
        row['recent_at'] = recent[id].to_i
        row
      end
    rescue StandardError => e
      log_exception('附加库收藏状态失败', e)
      Array(items)
    end

    def toggle_library_favorite(kind, discipline, item_id, root)
      id = item_id.to_s
      raise '找不到需要收藏的库项目。' if id.empty?
      bucket = library_usage_bucket(kind, discipline, root)
      favorites = bucket['favorites']
      if favorites.include?(id)
        favorites.delete(id)
        active = false
      else
        favorites.unshift(id)
        favorites.uniq!
        active = true
      end
      save_library_usage_data!
      active
    end

    def record_library_recent(kind, discipline, item_id, root)
      id = item_id.to_s
      return false if id.empty?
      bucket = library_usage_bucket(kind, discipline, root)
      rows = bucket['recent']
      rows.reject! { |row| row['id'].to_s == id }
      rows.unshift({ 'id' => id, 'used_at' => Time.now.to_i })
      bucket['recent'] = rows.first(LIBRARY_USAGE_RECENT_LIMIT)
      save_library_usage_data!
      true
    rescue StandardError => e
      log_exception('记录库最近使用失败', e)
      false
    end

    def landscape_library_payload(refresh_library: false, include_models: true, include_materials: false)
      model = Sketchup.active_model
      state, outer, source = landscape_library_edit_context(model)
      state ||= load_state(model)
      available = !!(outer && source)
      can_place = host_discipline_for(state) == 'landscape'
      root = landscape_library_root
      link = state.dig('links', 'landscape') || {}
      payload = {
        'plugin_version' => EXTENSION_VERSION,
        'available' => available,
        'can_place' => can_place,
        'workspace_name' => '景观工作区',
        'context_name' => available ? '景观模型编辑中' : '当前层级可临时放置',
        'library_root' => root,
        'library_ready' => !root.empty? && Dir.exist?(root),
        'schedule' => {
          'status' => link['status_label'].to_s.empty? ? link['status'].to_s : link['status_label'].to_s,
          'local_path' => link['model_path'].to_s,
          'shared_path' => link['collab_full_path'].to_s,
          'editing' => landscape_local_edit_active?(state, model),
          'locked_by_other' => link['source_locked_by_other'] == true,
          'owner' => link['source_lock_owner'].to_s
        },
        'material_library' => material_library_payload('landscape', force: false, include_materials: include_materials)
      }
      if include_models
        rows = []
        if !root.empty? && Dir.exist?(root)
          if refresh_library
            schedule_landscape_library_scan_background!(root)
          elsif landscape_library_cache_ready?(root)
            rows = scan_landscape_library!(force: false)
          else
            cached_items = read_landscape_library_catalog(root)
            if cached_items
              rows = hydrate_landscape_library_cache!(root, cached_items)
            else
              schedule_landscape_library_scan_background!(root, label: '景观模型库冷启动扫描')
            end
          end
        end
        payload['models'] = decorate_library_usage(rows, 'model', 'landscape', root)
        payload['library_scanning'] = !root.empty? && Dir.exist?(root) && rows.empty? && !landscape_library_cache_ready?(root)
      end
      payload
    rescue StandardError => e
      log_exception('生成景观模型库状态失败', e)
      { 'plugin_version' => EXTENSION_VERSION, 'available' => false, 'workspace_name' => '景观工作区', 'library_root' => landscape_library_root, 'library_ready' => false, 'error' => e.message.to_s }
    end

    def landscape_library_dialog_file
      File.join(__dir__, 'ui', 'landscape_library.html')
    end

    def refresh_landscape_library_dialog(refresh_library: false, include_models: true, include_materials: false)
      return false unless @landscape_library_dialog && @landscape_library_dialog.visible?
      payload = JSON.generate(landscape_library_payload(refresh_library: refresh_library, include_models: include_models, include_materials: include_materials))
      @landscape_library_dialog.execute_script("window.LandscapeLibrary && window.LandscapeLibrary.receiveState(#{payload});")
      true
    rescue StandardError => e
      log_exception('刷新景观模型库失败', e)
      false
    end

    def send_landscape_thumbnail_updates(updates)
      return false unless @landscape_library_dialog && @landscape_library_dialog.visible?
      payload = JSON.generate(Array(updates))
      @landscape_library_dialog.execute_script("window.LandscapeLibrary && window.LandscapeLibrary.receiveThumbnails(#{payload});")
      true
    rescue StandardError => e
      log_exception('发送景观缩略图失败', e)
      false
    end

    def request_landscape_model_thumbnails(json)
      ids = JSON.parse(json.to_s)
      ids = Array(ids).map(&:to_s).reject(&:empty?).uniq.first(6)
      updates = ids.filter_map do |model_id|
        item = landscape_library_item(model_id, force: false)
        next unless item && File.file?(item['path'].to_s)
        thumb = ensure_landscape_model_thumbnail(item['path'].to_s, landscape_library_root, force: false)
        ready = !thumb.empty? && landscape_thumbnail_current?(item['path'].to_s, thumb, landscape_library_root)
        item['thumbnail_url'] = thumb.empty? ? '' : soft_thumbnail_url(thumb)
        item['thumbnail_ready'] = ready
        { 'id' => item['id'], 'thumbnail_url' => item['thumbnail_url'], 'thumbnail_ready' => ready, 'thumbnail_finished' => true }
      end
      unless updates.empty?
        send_landscape_thumbnail_updates(updates)
        write_landscape_library_catalog!(@landscape_library_cache[:items], landscape_library_root) if @landscape_library_cache.is_a?(Hash)
      end
      true
    rescue StandardError => e
      log_exception('读取景观缩略图失败', e)
      false
    end

    def refresh_landscape_model_thumbnail(model_id)
      item = landscape_library_item(model_id, force: false)
      raise '找不到需要刷新缩略图的景观模型。' unless item && File.file?(item['path'].to_s)
      show_status("正在把统一轴测缩略图写入景观源模型“#{item['name']}”…", 'info')
      write_standard_thumbnail_into_source_skp!(
        item['path'].to_s,
        landscape_library_root,
        backup_source: true,
        backup_manager_dir: landscape_library_manager_dir(landscape_library_root)
      )
      invalidate_soft_library_file_signature!(item['path'])
      thumb = landscape_model_thumbnail_path(item['path'], landscape_library_root)
      File.delete(thumb) if File.file?(thumb)
      data = landscape_thumbnail_meta(landscape_library_root)
      data['models'].delete(item['id'].to_s) if data['models'].is_a?(Hash)
      write_landscape_thumbnail_meta!(data, landscape_library_root)
      thumb = ensure_landscape_model_thumbnail(item['path'], landscape_library_root, force: true)
      raise '源景观模型已更新，但未能重新提取内置缩略图。' if thumb.empty?
      item['thumbnail_url'] = soft_thumbnail_url(thumb)
      item['thumbnail_ready'] = true
      send_landscape_thumbnail_updates([{ 'id' => item['id'], 'thumbnail_url' => item['thumbnail_url'], 'thumbnail_ready' => true, 'thumbnail_finished' => true }])
      write_landscape_library_catalog!(@landscape_library_cache[:items], landscape_library_root) if @landscape_library_cache.is_a?(Hash)
      show_status("“#{item['name']}”的统一轴测缩略图已写入源 SKP。", 'success')
      true
    end

    def landscape_loaded_definition_cache(model = Sketchup.active_model)
      @landscape_loaded_definition_caches ||= {}
      @landscape_loaded_definition_caches[model.object_id] ||= {}
    end

    def landscape_library_definition_cache_key(item)
      path = FastPath.expand(item['path'].to_s)
      [normalize_soft_library_key(path), soft_library_file_signature(path)]
    end

    def stamp_landscape_library_definition!(definition, item)
      return false unless definition && definition.valid? && item
      name = item['name'].to_s.strip
      name = File.basename(item['path'].to_s, File.extname(item['path'].to_s)) if name.empty?
      soft_set_attribute_if_changed(definition, LANDSCAPE_MODEL_DICT, 'model_id', item['id'].to_s)
      soft_set_attribute_if_changed(definition, LANDSCAPE_MODEL_DICT, 'source_path', item['path'].to_s)
      soft_set_attribute_if_changed(definition, LANDSCAPE_MODEL_DICT, 'model_name', name)
      soft_set_attribute_if_changed(definition, LANDSCAPE_MODEL_DICT, 'source_signature', soft_library_file_signature(item['path'].to_s))
      definition.name = name unless name.empty? || definition.name.to_s == name
      true
    rescue StandardError => e
      log_exception('登记景观模型定义失败', e)
      false
    end

    def stamp_landscape_library_instance!(instance, item, _model = Sketchup.active_model)
      return false unless instance && instance.valid? && item
      name = item['name'].to_s.strip
      name = File.basename(item['path'].to_s, File.extname(item['path'].to_s)) if name.empty?
      soft_set_attribute_if_changed(instance, LANDSCAPE_MODEL_DICT, 'model_id', item['id'].to_s)
      soft_set_attribute_if_changed(instance, LANDSCAPE_MODEL_DICT, 'source_path', item['path'].to_s)
      soft_set_attribute_if_changed(instance, LANDSCAPE_MODEL_DICT, 'model_name', name)
      instance.name = name if instance.respond_to?(:name=) && instance.name.to_s != name
      stamp_landscape_library_definition!(instance.definition, item) if instance.respond_to?(:definition)
      true
    rescue StandardError => e
      log_exception('登记景观模型实例失败', e)
      false
    end

    def load_landscape_library_definition(item, model = Sketchup.active_model)
      raise '景观模型库中找不到所选模型，请刷新模型库。' unless item && File.file?(item['path'].to_s)
      key = landscape_library_definition_cache_key(item)
      cache = landscape_loaded_definition_cache(model)
      definition = cache[key]
      unless definition && definition.valid?
        path_key, signature = key
        definition = model.definitions.to_a.find do |candidate|
          next false unless candidate.valid?
          source = candidate.get_attribute(LANDSCAPE_MODEL_DICT, 'source_path', '').to_s
          stored_signature = candidate.get_attribute(LANDSCAPE_MODEL_DICT, 'source_signature', '').to_s
          normalize_soft_library_key(source) == path_key && stored_signature == signature
        end
      end
      unless definition && definition.valid?
        definition = load_definition_compat(model.definitions, item['path'].to_s)
        raise '景观模型库 SKP 无法载入。' unless definition && definition.valid?
      end
      stamp_landscape_library_definition!(definition, item)
      cache.delete_if { |stored_key, _value| stored_key[0] == key[0] && stored_key != key }
      cache[key] = definition
      definition
    end

    def schedule_prepare_landscape_library_model(model_id)
      @landscape_prepare_model_token = SecureRandom.hex(6)
      token = @landscape_prepare_model_token
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.18, false) do
        next unless @landscape_prepare_model_token == token
        next unless @landscape_library_dialog && @landscape_library_dialog.visible?
        item = landscape_library_item(model_id, force: false)
        next unless item && File.file?(item['path'].to_s)
        definition = load_landscape_library_definition(item, Sketchup.active_model)
        soft_definition_bounds_values(definition) if definition && definition.valid?
      rescue StandardError => e
        log_exception('预载景观模型失败', e)
      end
      true
    rescue StandardError
      false
    end

    def place_landscape_library_model(model_id)
      model = Sketchup.active_model
      state = load_state(model)
      raise '景观模型库只在景观工作区提供。' unless host_discipline_for(state) == 'landscape'

      item = landscape_library_item(model_id, force: false)
      definition = load_landscape_library_definition(item, model)
      target_entities, target_to_model, context_label = current_library_placement_context(model)
      raise '当前 SketchUp 编辑层级不可写入。' unless target_entities
      @landscape_placement_tool = SoftPlacementTool.new(
        self, model, definition, item, target_entities, target_to_model, 'full', 'landscape'
      )
      model.select_tool(@landscape_placement_tool)
      record_library_recent('model', 'landscape', item['id'], landscape_library_root)
      refresh_landscape_library_dialog(refresh_library: false, include_models: true)
      show_status("已启动景观模型放置 · #{context_label}；默认底部中心，Tab 切换底/中/顶。", 'success')
      true
    end

    def bind_landscape_library_callbacks(dialog)
      dialog.add_action_callback('ready') do |_ctx|
        safe_callback('打开景观模型库') { refresh_landscape_library_dialog(refresh_library: false, include_models: true) }
      end
      dialog.add_action_callback('choose_library') { |_ctx| safe_callback('设置景观模型库') { choose_landscape_library_root } }
      dialog.add_action_callback('refresh_library') do |_ctx|
        safe_callback('刷新景观模型库') do
          @landscape_library_cache = nil
          root = landscape_library_root
          schedule_landscape_library_scan_background!(root)
          refresh_landscape_library_dialog(refresh_library: false, include_models: false)
          show_status('景观模型库已加入后台刷新；可继续操作 SketchUp。', 'info')
        end
      end
      dialog.add_action_callback('request_thumbnails') { |_ctx, json| safe_callback('读取景观缩略图') { request_landscape_model_thumbnails(json) } }
      dialog.add_action_callback('refresh_thumbnail') { |_ctx, model_id| safe_callback('刷新景观缩略图') { refresh_landscape_model_thumbnail(model_id) } }
      dialog.add_action_callback('prepare_model') { |_ctx, model_id| safe_callback('预载景观模型') { schedule_prepare_landscape_library_model(model_id) } }
      dialog.add_action_callback('place_model') { |_ctx, model_id| safe_callback('放置景观模型') { place_landscape_library_model(model_id) } }
      dialog.add_action_callback('request_materials') do |_ctx|
        safe_callback('读取景观材质库') { send_integrated_material_state(dialog, 'LandscapeLibrary', 'landscape', force: false) }
      end
      dialog.add_action_callback('choose_material_library') do |_ctx|
        safe_callback('设置景观材质库') { choose_material_library_root('landscape') }
      end
      dialog.add_action_callback('refresh_material_library') do |_ctx|
        safe_callback('刷新景观材质库') do
          @material_library_caches ||= {}
          @material_library_caches.delete('landscape')
          send_integrated_material_state(dialog, 'LandscapeLibrary', 'landscape', force: true)
        end
      end
      dialog.add_action_callback('use_material') do |_ctx, material_id|
        safe_callback('使用景观材质') { use_material_library_item(material_id, 'landscape') }
      end
      dialog.add_action_callback('toggle_model_favorite') do |_ctx, model_id|
        safe_callback('收藏景观模型') do
          toggle_library_favorite('model', 'landscape', model_id, landscape_library_root)
          refresh_landscape_library_dialog(refresh_library: false, include_models: true)
        end
      end
      dialog.add_action_callback('toggle_material_favorite') do |_ctx, material_id|
        safe_callback('收藏景观材质') do
          toggle_library_favorite('material', 'landscape', material_id, material_library_root('landscape'))
          send_integrated_material_state(dialog, 'LandscapeLibrary', 'landscape', force: false)
        end
      end
    end

    def show_landscape_library_dialog
      require_workspace_ready!
      state = load_state(Sketchup.active_model)
      raise '景观模型库只在景观工作区提供。' unless host_discipline_for(state) == 'landscape'
      if @landscape_library_dialog && @landscape_library_dialog.visible?
        @landscape_library_dialog.bring_to_front
        refresh_landscape_library_dialog
        return true
      end
      @landscape_library_dialog = UI::HtmlDialog.new(
        dialog_title: '景观库',
        preferences_key: 'GavinTools_SULinkHubMultiSpace_LandscapeLibrary',
        scrollable: true,
        resizable: true,
        width: 920,
        height: 680,
        min_width: 680,
        min_height: 480,
        style: UI::HtmlDialog::STYLE_DIALOG
      )
      @landscape_library_dialog.set_file(landscape_library_dialog_file)
      bind_landscape_library_callbacks(@landscape_library_dialog)
      @landscape_library_dialog.set_on_closed do
        @landscape_library_dialog = nil
        @landscape_prepare_model_token = nil
        GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { refresh_workspace_toolbar }
      end
      @landscape_library_dialog.show
      true
    end

    def toggle_landscape_library_dialog
      if @landscape_library_dialog && @landscape_library_dialog.visible?
        @landscape_library_dialog.close
        refresh_workspace_toolbar
        false
      else
        show_landscape_library_dialog
        refresh_workspace_toolbar
        true
      end
    end

