    def architecture_library_payload(include_materials: false)
      model = Sketchup.active_model
      state = load_state(model)
      link = state.dig('links', 'architecture') || {}
      {
        'plugin_version' => EXTENSION_VERSION,
        'workspace_name' => '建筑工作区',
        'available' => architecture_local_edit_active?(state, model),
        'model_library_enabled' => false,
        'material_library' => material_library_payload('architecture', force: false, include_materials: include_materials),
        'schedule' => {
          'status' => link['status_label'].to_s.empty? ? link['status'].to_s : link['status_label'].to_s,
          'local_path' => link['model_path'].to_s,
          'shared_path' => link['collab_full_path'].to_s,
          'editing' => architecture_local_edit_active?(state, model),
          'locked_by_other' => link['source_locked_by_other'] == true,
          'owner' => link['source_lock_owner'].to_s,
          'loaded' => link['loaded'] == true,
          'visible' => link['visible'] == true
        }
      }
    rescue StandardError => e
      log_exception('生成建筑库状态失败', e)
      {
        'plugin_version' => EXTENSION_VERSION,
        'workspace_name' => '建筑工作区',
        'available' => false,
        'model_library_enabled' => false,
        'material_library' => material_library_payload('architecture', force: false, include_materials: false),
