    # -------------------------
    # 建筑 / 室内 / 景观材质库
    # -------------------------

    def material_library_supported_discipline?(discipline)
      MATERIAL_LIBRARY_ROOT_PREF_KEYS.key?(discipline.to_s)
    rescue StandardError
      false
    end

    def material_library_discipline_name(discipline)
      case discipline.to_s
      when 'architecture' then '建筑'
      when SPACE_COLLECTION_KEY then '硬装'
      when SOFT_SPACE_COLLECTION_KEY then '软装'
      when 'landscape' then '景观'
      else '专业'
      end
    end

    def material_library_theme(discipline)
      case discipline.to_s
      when 'architecture'
        { 'color' => '#5279a8', 'soft' => '#eaf0f7', 'rgb' => [77, 114, 163] }
      when 'landscape'
        { 'color' => '#4d8b5d', 'soft' => '#e9f3eb', 'rgb' => [72, 139, 91] }
      else
        { 'color' => '#b97843', 'soft' => '#f7eee6', 'rgb' => [187, 119, 70] }
      end
    end

    def material_library_explicit_root(discipline)
      key = MATERIAL_LIBRARY_ROOT_PREF_KEYS[discipline.to_s]
      return '' if key.to_s.empty?
      value = Sketchup.read_default(MATERIAL_LIBRARY_PREF_SECTION, key, '').to_s.strip
      value.empty? ? '' : FastPath.expand(value)
    rescue StandardError
      ''
    end

    # 室内和景观已经有模型库时，材质库默认放在其模型库根目录下的“材质库”。
    # 建筑没有模型库，因此首次打开时由用户选择独立目录。
    def material_library_default_root(discipline)
      case discipline.to_s
      when SPACE_COLLECTION_KEY
        # 硬装不再借用软装模型库目录；旧用户若已有 interior_root 显式设置仍直接沿用。
        ''
      when SOFT_SPACE_COLLECTION_KEY
        base = soft_library_root
        base.to_s.empty? ? '' : File.join(base, '材质库')
      when 'landscape'
        base = landscape_library_root
        base.to_s.empty? ? '' : File.join(base, '材质库')
      else
        ''
      end
    rescue StandardError
      ''
    end

    def material_library_root(discipline)
      explicit = material_library_explicit_root(discipline)
      return explicit unless explicit.empty?
      default = material_library_default_root(discipline)
      default.to_s.empty? ? '' : FastPath.expand(default)
    rescue StandardError
      ''
    end

    def material_library_manager_dir(discipline, root = nil)
      root = material_library_root(discipline) if root.nil?
      root.to_s.empty? ? '' : File.join(root.to_s, MATERIAL_LIBRARY_MANAGER_DIR)
    end

    def material_library_index_path(discipline, root = nil)
      dir = material_library_manager_dir(discipline, root)
      dir.empty? ? '' : File.join(dir, MATERIAL_LIBRARY_INDEX_FILE)
    end

    def ensure_material_library_structure!(discipline, root = nil)
      discipline = discipline.to_s
      raise '当前工作区不支持材质库。' unless material_library_supported_discipline?(discipline)
      root = material_library_root(discipline) if root.nil?
      raise '尚未设置材质库路径。' if root.to_s.empty?
      FileUtils.mkdir_p(root)
      FileUtils.mkdir_p(material_library_manager_dir(discipline, root))
      index_path = material_library_index_path(discipline, root)
      unless File.file?(index_path)
        write_json_atomic(index_path, {
          'schema' => MATERIAL_LIBRARY_SCHEMA,
          'discipline' => discipline,
          'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S'),
          'materials' => {}
        })
      end
      true
    end

    def set_material_library_root(discipline, path, persist_project: true)
      discipline = discipline.to_s
      raise '当前工作区不支持材质库。' unless material_library_supported_discipline?(discipline)
      root = path.to_s.empty? ? '' : FastPath.expand(path.to_s)
      raise '请选择有效的材质库文件夹。' if root.empty? || !Dir.exist?(root)
      key = MATERIAL_LIBRARY_ROOT_PREF_KEYS[discipline]
      Sketchup.write_default(MATERIAL_LIBRARY_PREF_SECTION, key, root)
      ensure_material_library_structure!(discipline, root)
      @material_library_caches ||= {}
      @material_library_caches.delete(discipline)
      if persist_project
        project_key = case discipline
                      when SPACE_COLLECTION_KEY then 'hard_material_root'
                      when SOFT_SPACE_COLLECTION_KEY then 'soft_material_root'
                      when 'architecture' then 'architecture_material_root'
                      when 'landscape' then 'landscape_material_root'
                      end
        persist_project_path_setting!(project_key, root) unless project_key.to_s.empty?
      end
      root
    end

    def choose_material_library_root(discipline)
      discipline = discipline.to_s
      title = "选择#{material_library_discipline_name(discipline)}材质库文件夹"
      options = { title: title }
      current = material_library_root(discipline)
      options[:directory] = current if !current.empty? && Dir.exist?(current)
      path = UI.select_directory(options)
      return false if path.nil? || path.to_s.empty?
      root = set_material_library_root(discipline, path)
      refresh_material_library_dialog(force: true)
      refresh_integrated_material_dialogs(discipline, force: true)
      refresh_workspace_toolbar
      show_status("#{material_library_discipline_name(discipline)}材质库已设置：#{root}", 'success')
      true
    end

    def read_material_library_index(discipline, root = nil)
      root = material_library_root(discipline) if root.nil?
      return { 'schema' => MATERIAL_LIBRARY_SCHEMA, 'discipline' => discipline.to_s, 'materials' => {} } if root.to_s.empty?
      ensure_material_library_structure!(discipline, root)
      path = material_library_index_path(discipline, root)
      data = JSON.parse(File.read(path, mode: 'r:UTF-8'))
      data = {} unless data.is_a?(Hash)
      data['schema'] = MATERIAL_LIBRARY_SCHEMA
      data['discipline'] = discipline.to_s
      data['materials'] = {} unless data['materials'].is_a?(Hash)
      data
    rescue StandardError => e
      log_exception("读取#{material_library_discipline_name(discipline)}材质索引失败", e)
      { 'schema' => MATERIAL_LIBRARY_SCHEMA, 'discipline' => discipline.to_s, 'materials' => {} }
    end

    def write_material_library_index!(discipline, data, root = nil)
      root = material_library_root(discipline) if root.nil?
      raise '材质库路径不可用。' if root.to_s.empty?
      payload = data.is_a?(Hash) ? data : {}
      payload['schema'] = MATERIAL_LIBRARY_SCHEMA
      payload['discipline'] = discipline.to_s
      payload['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      payload['materials'] = {} unless payload['materials'].is_a?(Hash)
      write_json_atomic(material_library_index_path(discipline, root), payload)
    end

    def material_library_id_for_path(path)
      Digest::SHA1.hexdigest(normalize_soft_library_key(path))[0, 24]
    rescue StandardError
      Digest::SHA1.hexdigest(path.to_s)[0, 24]
    end

    def material_library_relative_folder(path, root)
      relative = Pathname.new(FastPath.expand(path.to_s)).relative_path_from(Pathname.new(FastPath.expand(root.to_s))).to_s
      directory = File.dirname(relative).tr('\\', '/')
      directory == '.' ? '' : directory
    rescue StandardError
      ''
    end

    def material_library_file_signature(path)
      fast_file_signature(path).to_s
    rescue StandardError
      ''
    end

    def default_material_library_metadata(path, root)
      folder = material_library_relative_folder(path, root)
      {
        'material_id' => material_library_id_for_path(path),
        'name' => File.basename(path.to_s, File.extname(path.to_s)),
        'category' => folder,
        'folder' => folder,
        'textured' => true,
        'color' => [255, 255, 255],
        'alpha' => 1.0,
        'texture_width' => 0.0,
        'texture_height' => 0.0,
        'created_at' => '',
        'updated_at' => ''
      }
    end

    # 纯文件 I/O 材质目录扫描。PNG 枚举、索引 JSON 和文件签名均可后台完成；
    # 真正把材质载入 SketchUp / 应用到面仍必须留在主线程。
    def background_scan_material_library_data(discipline, root)
      discipline = discipline.to_s
      raise '材质库路径不可用。' if root.to_s.empty? || !Dir.exist?(root.to_s)
      root = FastPath.expand(root.to_s)
      manager_key = normalize_soft_library_key(material_library_manager_dir(discipline, root))
      files = Dir.glob(File.join(root, '**', '*.{png,PNG}'), File::FNM_EXTGLOB)
      files.reject! { |path| normalize_soft_library_key(path).start_with?(manager_key + '/') }
      files.sort_by! { |path| normalize_soft_library_key(path) }
      files = files.first(MATERIAL_LIBRARY_SCAN_LIMIT)
      signatures = {}
      files.each { |path| signatures[path] = material_library_file_signature(path).to_s }
      signature = Digest::SHA1.hexdigest(files.map { |path| "#{normalize_soft_library_key(path)}|#{signatures[path]}" }.join("\n"))
      index_data = begin
        path = material_library_index_path(discipline, root)
        File.file?(path) ? JSON.parse(File.read(path, mode: 'r:UTF-8')) : {}
      rescue StandardError
        {}
      end
      records = index_data.is_a?(Hash) && index_data['materials'].is_a?(Hash) ? index_data['materials'] : {}
      items = files.map do |path|
        key = normalize_soft_library_key(path)
        metadata = default_material_library_metadata(path, root).merge(records[key].is_a?(Hash) ? records[key] : {})
        folder = material_library_relative_folder(path, root)
        metadata['folder'] = folder
        metadata['category'] = folder if metadata['category'].to_s.empty?
        metadata['name'] = File.basename(path, File.extname(path)) if metadata['name'].to_s.empty?
        metadata['material_id'] = material_library_id_for_path(path) if metadata['material_id'].to_s.empty?
        {
          'id' => metadata['material_id'].to_s,
          'name' => metadata['name'].to_s,
          'folder' => folder,
          'category' => metadata['category'].to_s,
          'path' => FastPath.expand(path),
          'preview_url' => "#{local_file_url(path)}?v=#{File.mtime(path).to_i}-#{File.size(path)}",
          'textured' => metadata['textured'] != false,
          'metadata' => metadata,
          'signature' => signatures[path]
        }
      end
      { discipline: discipline, root: root, signature: signature, items: items }
    end

    def schedule_material_library_scan_background!(discipline, root = nil, label: nil)
      discipline = discipline.to_s
      root ||= material_library_root(discipline)
      return false if root.to_s.empty? || !Dir.exist?(root.to_s)
      enqueue_background_io_task(
        'material_library_scan',
        key: "#{discipline}|#{normalize_soft_library_key(root)}",
        data: { discipline: discipline, root: FastPath.expand(root.to_s) },
        label: (label.to_s.empty? ? "#{material_library_discipline_name(discipline)}材质库后台刷新" : label.to_s)
      )
    end

    def scan_material_library!(discipline, force: false)
      discipline = discipline.to_s
      root = material_library_root(discipline)
      return [] if root.empty? || !Dir.exist?(root)
      ensure_material_library_structure!(discipline, root)
      @material_library_caches ||= {}
      cached = @material_library_caches[discipline]
      if !force && cached.is_a?(Hash) && cached[:root] == normalize_soft_library_key(root)
        return cached[:items]
      end
      started = monotonic_time
      manager_key = normalize_soft_library_key(material_library_manager_dir(discipline, root))
      files = Dir.glob(File.join(root, '**', '*.{png,PNG}'), File::FNM_EXTGLOB)
      files.reject! { |path| normalize_soft_library_key(path).start_with?(manager_key + '/') }
      files.sort_by! { |path| normalize_soft_library_key(path) }
      files = files.first(MATERIAL_LIBRARY_SCAN_LIMIT)
      signature = Digest::SHA1.hexdigest(files.map { |path| "#{normalize_soft_library_key(path)}|#{material_library_file_signature(path)}" }.join('\n'))
      index = read_material_library_index(discipline, root)
      records = index['materials']
      items = files.map do |path|
        key = normalize_soft_library_key(path)
        metadata = default_material_library_metadata(path, root).merge(records[key].is_a?(Hash) ? records[key] : {})
        folder = material_library_relative_folder(path, root)
        metadata['folder'] = folder
        metadata['category'] = folder if metadata['category'].to_s.empty?
        metadata['name'] = File.basename(path, File.extname(path)) if metadata['name'].to_s.empty?
        metadata['material_id'] = material_library_id_for_path(path) if metadata['material_id'].to_s.empty?
        {
          'id' => metadata['material_id'].to_s,
          'name' => metadata['name'].to_s,
          'folder' => folder,
          'category' => metadata['category'].to_s,
          'path' => FastPath.expand(path),
          'preview_url' => "#{local_file_url(path)}?v=#{File.mtime(path).to_i}-#{File.size(path)}",
          'textured' => metadata['textured'] != false,
          'metadata' => metadata,
          'signature' => material_library_file_signature(path)
        }
      end
      by_id = {}
      items.each { |item| by_id[item['id']] = item }
      @material_library_caches[discipline] = {
        root: normalize_soft_library_key(root), signature: signature,
        items: items, by_id: by_id
      }
      log_slow_operation("#{material_library_discipline_name(discipline)}材质库完整扫描", started, 100.0, "#{items.length} 个材质")
      items
    rescue StandardError => e
      log_exception("扫描#{material_library_discipline_name(discipline)}材质库失败", e)
      []
    end

    # 材质吸管新增一张 PNG 后，只增量更新这一条缓存。旧版会清空缓存并
    # 强制递归扫描整个材质库，再把全部卡片重复发送给所有窗口；大型材质库中
    # 一次吸取也会明显停顿。这里保留现有缓存并原位插入新材质。
    def upsert_material_library_cache_path!(discipline, path, metadata = nil, root = nil)
      discipline = discipline.to_s
      root ||= material_library_root(discipline)
      expanded = FastPath.expand(path.to_s)
      return false unless File.file?(expanded) && !root.to_s.empty?
      @material_library_caches ||= {}
      cache = @material_library_caches[discipline]
      return false unless cache.is_a?(Hash) && cache[:root] == normalize_soft_library_key(root)

      index = read_material_library_index(discipline, root)
      key = normalize_soft_library_key(expanded)
      metadata = default_material_library_metadata(expanded, root).merge(
        index['materials'][key].is_a?(Hash) ? index['materials'][key] : {}
      ).merge(metadata.is_a?(Hash) ? metadata : {})
      folder = material_library_relative_folder(expanded, root)
      metadata['folder'] = folder
      metadata['category'] = folder if metadata['category'].to_s.empty?
      metadata['name'] = File.basename(expanded, File.extname(expanded)) if metadata['name'].to_s.empty?
      metadata['material_id'] = material_library_id_for_path(expanded) if metadata['material_id'].to_s.empty?
      signature = material_library_file_signature(expanded)
      item = {
        'id' => metadata['material_id'].to_s,
        'name' => metadata['name'].to_s,
        'folder' => folder,
        'category' => metadata['category'].to_s,
        'path' => expanded,
        'preview_url' => "#{local_file_url(expanded)}?v=#{File.mtime(expanded).to_i}-#{File.size(expanded)}",
        'textured' => metadata['textured'] != false,
        'metadata' => metadata,
        'signature' => signature
      }

      items = Array(cache[:items]).dup
      replaced = false
      items.map! do |existing|
        if existing.is_a?(Hash) && normalize_soft_library_key(existing['path']) == key
          replaced = true
          item
        else
          existing
        end
      end
      items << item unless replaced
      items.select! { |entry| entry.is_a?(Hash) && File.file?(entry['path'].to_s) }
      items.sort_by! { |entry| normalize_soft_library_key(entry['path']) }
      items = items.first(MATERIAL_LIBRARY_SCAN_LIMIT)
      by_id = {}
      items.each { |entry| by_id[entry['id'].to_s] = entry }
      aggregate = Digest::SHA1.hexdigest(items.map { |entry| "#{normalize_soft_library_key(entry['path'])}|#{entry['signature']}" }.join("\n"))
      @material_library_caches[discipline] = {
        root: normalize_soft_library_key(root), signature: aggregate,
        items: items, by_id: by_id
      }
      true
    rescue StandardError => e
      log_exception("增量更新#{material_library_discipline_name(discipline)}材质库缓存失败：#{path}", e)
      false
    end

    def material_library_item(discipline, material_id, force: false)
      scan_material_library!(discipline, force: force)
      cache = (@material_library_caches || {})[discipline.to_s]
      cache.is_a?(Hash) ? cache[:by_id].to_h[material_id.to_s] : nil
    rescue StandardError
      nil
    end

    def material_library_context_active?(discipline, model = Sketchup.active_model, state = nil)
      discipline = discipline.to_s
      state = load_state(model) unless state.is_a?(Hash)
      return false unless host_discipline_for(state) == discipline
      case discipline
      when SPACE_COLLECTION_KEY, SOFT_SPACE_COLLECTION_KEY
        item = current_soft_designer_fab_space(model)
        !!(item && space_edit_context_active?(item, model))
      when 'architecture'
        outer = native_edit_entity('architecture', model)
        source = architecture_edit_source_entity(outer)
        !!(outer && source && architecture_local_edit_active?(state, model) && active_path_inside_architecture?(outer, source, model))
      when 'landscape'
        outer = native_edit_entity('landscape', model)
        source = landscape_edit_source_entity(outer)
        !!(outer && source && landscape_local_edit_active?(state, model) && active_path_inside_landscape?(outer, source, model))
      else
        false
      end
    rescue StandardError
      false
    end

    def selected_material_faces(model = Sketchup.active_model)
      model.selection.to_a.select { |entity| entity.is_a?(Sketchup::Face) && entity.valid? }
    rescue StandardError
      []
    end

    def material_library_payload(discipline = nil, force: false, include_materials: true)
      discipline = (discipline || @material_library_discipline).to_s
      state = load_state(Sketchup.active_model)
      root = material_library_root(discipline)
      if !root.empty? && !Dir.exist?(root)
        # 默认子目录可以自动创建；用户显式配置但目录被移动时保持“未就绪”。
        explicit = material_library_explicit_root(discipline)
        FileUtils.mkdir_p(root) if explicit.empty?
      end
      ready = !root.empty? && Dir.exist?(root)
      items = []
      material_scanning = false
      if ready && include_materials
        @material_library_caches ||= {}
        cache = @material_library_caches[discipline]
        cache_ready = cache.is_a?(Hash) && cache[:root] == normalize_soft_library_key(root) && cache[:items].is_a?(Array)
        if force
          schedule_material_library_scan_background!(discipline, root)
          material_scanning = true
          items = cache_ready ? decorate_library_usage(cache[:items], 'material', discipline, root) : []
        elsif cache_ready
          items = decorate_library_usage(cache[:items], 'material', discipline, root)
        else
          schedule_material_library_scan_background!(discipline, root, label: "#{material_library_discipline_name(discipline)}材质库冷启动扫描")
          material_scanning = true
        end
      end
      faces = selected_material_faces(Sketchup.active_model)
      can_use = material_library_context_active?(discipline, Sketchup.active_model, state)
      context_message = if can_use
                          if faces.empty?
                            '当前正在编辑本专业模型；点击材质可载入并启用油漆桶。'
                          else
                            "已选择 #{faces.length} 个面；点击材质可直接应用。"
                          end
                        else
                          "可浏览#{material_library_discipline_name(discipline)}材质库；进入本专业模型编辑后才可使用。"
                        end
      theme = material_library_theme(discipline)
      payload = {
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => discipline,
        'discipline_name' => material_library_discipline_name(discipline),
        'theme_color' => theme['color'],
        'theme_soft' => theme['soft'],
        'library_root' => root,
        'library_ready' => ready,
        'can_use' => can_use,
        'selected_face_count' => faces.length,
        'context_message' => context_message,
        'library_scanning' => material_scanning
      }
      if include_materials
        payload['materials'] = items.map do |item|
          {
            'id' => item['id'], 'name' => item['name'], 'folder' => item['folder'],
            'category' => item['category'], 'preview_url' => item['preview_url'],
            'textured' => item['textured'], 'favorite' => item['favorite'] == true,
            'recent_at' => item['recent_at'].to_i
          }
        end
      end
      payload
    rescue StandardError => e
      log_exception('生成材质库状态失败', e)
      {
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => discipline.to_s,
        'discipline_name' => material_library_discipline_name(discipline),
        'library_root' => material_library_root(discipline),
        'library_ready' => false, 'can_use' => false,
        'selected_face_count' => 0, 'materials' => [],
        'context_message' => "材质库状态读取失败：#{e.message}"
      }
    end

    def material_library_dialog_file
      File.join(__dir__, 'ui', 'material_library.html')
    end

    def refresh_material_library_dialog(force: false)
      return false unless @material_library_dialog && @material_library_dialog.visible?
      payload = JSON.generate(material_library_payload(@material_library_discipline, force: force))
      @material_library_dialog.execute_script("window.MaterialLibrary && window.MaterialLibrary.receiveState(#{payload});")
      true
    rescue StandardError => e
      log_exception('刷新材质库窗口失败', e)
      false
    end

    def send_integrated_material_state(dialog, namespace, discipline, force: false)
      return false unless dialog && dialog.visible?
      payload = JSON.generate(material_library_payload(discipline, force: force, include_materials: true))
      dialog.execute_script("window.#{namespace} && window.#{namespace}.receiveMaterialState(#{payload});")
      true
    rescue StandardError => e
      log_exception("刷新#{material_library_discipline_name(discipline)}整合材质库失败", e)
      false
    end

    def refresh_integrated_material_dialogs(discipline, force: false)
      discipline = discipline.to_s
      case discipline
      when SOFT_SPACE_COLLECTION_KEY
        send_integrated_material_state(@soft_designer_dialog, 'SoftDesigner', discipline, force: force) if @soft_designer_dialog && @soft_designer_dialog.visible?
      when 'landscape'
        send_integrated_material_state(@landscape_library_dialog, 'LandscapeLibrary', discipline, force: force) if @landscape_library_dialog && @landscape_library_dialog.visible?
      when 'architecture'
        send_integrated_material_state(@architecture_library_dialog, 'ArchitectureLibrary', discipline, force: force) if @architecture_library_dialog && @architecture_library_dialog.visible?
      end
      true
    rescue StandardError => e
      log_exception('刷新整合材质库失败', e)
      false
    end

    def material_library_png_chunk(type, data)
      payload = type.to_s.b + data.to_s.b
      [data.to_s.bytesize].pack('N') + payload + [Zlib.crc32(payload)].pack('N')
    end

    def write_solid_material_png!(path, color, alpha = 1.0, size = MATERIAL_LIBRARY_SOLID_IMAGE_SIZE)
      width = [size.to_i, 16].max
      height = width
      red = [[color.respond_to?(:red) ? color.red.to_i : 255, 0].max, 255].min
      green = [[color.respond_to?(:green) ? color.green.to_i : 255, 0].max, 255].min
      blue = [[color.respond_to?(:blue) ? color.blue.to_i : 255, 0].max, 255].min
      alpha_byte = [[(alpha.to_f * 255.0).round, 0].max, 255].min
      pixel = [red, green, blue, alpha_byte].pack('C4')
      row = "\x00".b + pixel * width
      raw = row * height
      png = "\x89PNG\r\n\x1a\n".b
      png << material_library_png_chunk('IHDR', [width, height, 8, 6, 0, 0, 0].pack('NNCCCCC'))
      png << material_library_png_chunk('IDAT', Zlib::Deflate.deflate(raw, Zlib::BEST_SPEED))
      png << material_library_png_chunk('IEND', ''.b)
      FileUtils.mkdir_p(File.dirname(path))
      File.binwrite(path, png)
      File.file?(path) && File.size(path).positive?
    end

    def png_image_file?(path)
      return false unless File.file?(path) && File.size(path).to_i >= 8
      File.binread(path, 8) == "\x89PNG\r\n\x1a\n".b
    rescue StandardError
      false
    end

    def convert_image_file_to_png!(source, target)
      return false unless defined?(Sketchup::ImageRep) && File.file?(source)
      temp = "#{target}.convert-#{SecureRandom.hex(3)}.png"
      rep = Sketchup::ImageRep.new
      loaded = rep.load_file(source)
      return false unless loaded && rep.respond_to?(:save_file)
      rep.save_file(temp)
      return false unless png_image_file?(temp)
      linkhub_mv(temp, target)
      true
    rescue StandardError
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def write_texture_png!(texture, target)
      FileUtils.mkdir_p(File.dirname(target))
      File.delete(target) if File.file?(target)
      if texture.respond_to?(:image_rep)
        begin
          rep = texture.image_rep
          rep.save_file(target) if rep && rep.respond_to?(:save_file)
        rescue StandardError
          nil
        end
      end
      return true if png_image_file?(target)

      if texture.respond_to?(:write)
        begin
          texture.write(target)
        rescue StandardError
          nil
        end
      end
      return true if png_image_file?(target)
      convert_image_file_to_png!(target, target) if File.file?(target)
      return true if png_image_file?(target)

      if texture.respond_to?(:filename)
        source = texture.filename.to_s
        if File.file?(source)
          if png_image_file?(source)
            FileUtils.cp(source, target)
          else
            convert_image_file_to_png!(source, target)
          end
        end
      end
      png_image_file?(target)
    end

    def material_color_components(material)
      color = material.respond_to?(:color) ? material.color : nil
      [
        color && color.respond_to?(:red) ? color.red.to_i : 255,
        color && color.respond_to?(:green) ? color.green.to_i : 255,
        color && color.respond_to?(:blue) ? color.blue.to_i : 255
      ]
    rescue StandardError
      [255, 255, 255]
    end

    def material_alpha_value(material)
      value = material.respond_to?(:alpha) ? material.alpha.to_f : 1.0
      [[value, 0.0].max, 1.0].min
    rescue StandardError
      1.0
    end

    def export_material_png!(material, target)
      texture = material.respond_to?(:texture) ? material.texture : nil
      if texture
        ok = write_texture_png!(texture, target)
        raise '无法把当前材质纹理转换为 PNG。' unless ok
        true
      else
        color = material.respond_to?(:color) ? material.color : Sketchup::Color.new(255, 255, 255)
        raise '无法生成纯色材质 PNG。' unless write_solid_material_png!(target, color, material_alpha_value(material))
        true
      end
    end

    def safe_material_library_name(value, fallback = '未命名材质')
      text = value.to_s.strip.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ')
      text = fallback if text.empty?
      text[0, 80]
    end

    def unique_material_png_path(dir, basename)
      safe = safe_material_library_name(basename)
      candidate = File.join(dir, "#{safe}.png")
      return candidate unless File.exist?(candidate)
      index = 2
      loop do
        candidate = File.join(dir, "#{safe}_#{index}.png")
        return candidate unless File.exist?(candidate)
        index += 1
      end
    end

    def effective_material_for_face(face, model = Sketchup.active_model)
      return [face.material, 'front'] if face.respond_to?(:material) && face.material
      return [face.back_material, 'back'] if face.respond_to?(:back_material) && face.back_material
      Array(model.active_path).reverse_each do |instance|
        material = instance.respond_to?(:material) ? instance.material : nil
        return [material, 'inherited'] if material
      end
      [nil, '']
    rescue StandardError
      [nil, '']
    end

    def library_pipette_cursor_id
      return @library_pipette_cursor_id if @library_pipette_cursor_id
      path = File.join(__dir__, 'ui', 'icons', 'linkhub_pipette_cursor.png')
      return nil unless File.file?(path)
      @library_pipette_cursor_id = UI.create_cursor(path, 5, 27)
    rescue StandardError => e
      log_exception('建立吸管光标失败', e)
      nil
    end

    def start_library_pipette_tool(model = Sketchup.active_model, discipline = nil)
      return false unless model
      state = ensure_space_models_ready!(model)
      discipline = host_discipline_for(state) if discipline.to_s.empty?
      raise '当前工作区不支持吸管入库。' unless material_library_supported_discipline?(discipline)
      @library_pipette_tool = LibraryPipetteTool.new(self, model, discipline)
      model.select_tool(@library_pipette_tool)
      true
    end

    def library_pipette_tool_finished(tool)
      @library_pipette_tool = nil if @library_pipette_tool.equal?(tool)
      schedule_restore_default_select_tool(Sketchup.active_model, delay: 0.08, reason: '吸管完成')
      true
    rescue StandardError
      false
    end

    def selected_material_face_for_library!(model = Sketchup.active_model)
      state = ensure_space_models_ready!(model)
      discipline = host_discipline_for(state)
      raise '当前工作区不支持材质库。' unless material_library_supported_discipline?(discipline)
      selection = model.selection.to_a
      raise '请只选择一个有材质的面。' unless selection.length == 1 && selection.first.is_a?(Sketchup::Face)
      face = selection.first
      material, source_side = effective_material_for_face(face, model)
      raise '所选面及其上层组件都没有材质，无法吸取。' unless material
      [discipline, face, material, source_side]
    end

    def ingest_selected_material_into_library(model = Sketchup.active_model)
      discipline, _face, material, source_side = selected_material_face_for_library!(model)
      root = material_library_root(discipline)
      if root.empty? || !Dir.exist?(root)
        chosen = choose_material_library_root(discipline)
        return false unless chosen
        root = material_library_root(discipline)
      end
      ensure_material_library_structure!(discipline, root)
      default_name = safe_material_library_name(material.respond_to?(:display_name) ? material.display_name : material.name, '未命名材质')
      category_key = MATERIAL_LIBRARY_LAST_CATEGORY_PREF_KEYS[discipline]
      default_category = Sketchup.read_default(MATERIAL_LIBRARY_PREF_SECTION, category_key, '').to_s
      response = UI.inputbox(['材质名称', '分类名称'], [default_name, default_category], "#{material_library_discipline_name(discipline)}材质入库")
      return false unless response
      material_name = safe_material_library_name(response[0], default_name)
      category = safe_soft_library_category_name(response[1])
      Sketchup.write_default(MATERIAL_LIBRARY_PREF_SECTION, category_key, category)
      category_dir = File.join(root, category)
      FileUtils.mkdir_p(category_dir)
      target = unique_material_png_path(category_dir, material_name)
      export_material_png!(material, target)

      texture = material.respond_to?(:texture) ? material.texture : nil
      width = texture && texture.respond_to?(:width) ? texture.width.to_f : 0.0
      height = texture && texture.respond_to?(:height) ? texture.height.to_f : 0.0
      timestamp = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      metadata = {
        'material_id' => material_library_id_for_path(target),
        'name' => material_name,
        'category' => category,
        'folder' => category,
        'textured' => !texture.nil?,
        'color' => material_color_components(material),
        'alpha' => material_alpha_value(material),
        'texture_width' => width,
        'texture_height' => height,
        'source_material_name' => material.respond_to?(:name) ? material.name.to_s : material_name,
        'source_side' => source_side,
        'created_at' => timestamp,
        'updated_at' => timestamp
      }
      index = read_material_library_index(discipline, root)
      index['materials'][normalize_soft_library_key(target)] = metadata
      write_material_library_index!(discipline, index, root)
      cache_updated = upsert_material_library_cache_path!(discipline, target, metadata, root)
      # force:false 会直接命中上面的增量缓存；只有首次打开、缓存不存在时才扫描一次。
      refresh_material_library_dialog(force: false) if @material_library_dialog && @material_library_dialog.visible? && @material_library_discipline.to_s == discipline
      refresh_integrated_material_dialogs(discipline, force: false)
      log("材质吸管增量入库：#{material_name} / 缓存#{cache_updated ? '已增量更新' : '按需重建'}")
      refresh_workspace_toolbar(model)
      show_status("“#{material_name}”已保存到#{material_library_discipline_name(discipline)}材质库：#{target}", 'success')
      true
    end

    def library_pipette_selection_status(model = Sketchup.active_model, state = nil, fast: false)
      state = load_state(model) unless state.is_a?(Hash)
      discipline = host_discipline_for(state)
      unless material_library_supported_discipline?(discipline)
        return { 'enabled' => false, 'tooltip' => '当前工作区不支持吸管入库' }
      end
      selection = model.selection.to_a
      if selection.length == 1 && selection.first.is_a?(Sketchup::Face)
        face = selection.first
        material, _source_side = effective_material_for_face(face, model)
        return { 'enabled' => false, 'tooltip' => '所选面及其上层组件没有材质，无法吸取' } unless material
        name = material.respond_to?(:display_name) ? material.display_name.to_s : material.name.to_s
        name = '当前材质' if name.empty?
        return { 'enabled' => true, 'mode' => 'material', 'tooltip' => "吸取“#{name}”并保存为 PNG 材质" }
      end
      if discipline == SOFT_SPACE_COLLECTION_KEY && selection.length == 1 &&
         (selection.first.is_a?(Sketchup::ComponentInstance) || selection.first.is_a?(Sketchup::Group))
        status = fast ? soft_library_ingest_selection_status_fast(model, state) : soft_library_ingest_selection_status(model, state)
        return status.merge('mode' => 'furniture')
      end
      if selection.empty?
        hint = discipline == SOFT_SPACE_COLLECTION_KEY ? '吸管取样：点击家具组件入软装模型库；点击裸面吸取材质' : '材质吸管：点击有材质的面直接入库'
        return { 'enabled' => true, 'mode' => 'pick', 'tooltip' => hint }
      end
      hint = discipline == SOFT_SPACE_COLLECTION_KEY ? '吸管一次只处理一个家具组件或一个有材质的面' : '材质吸管一次只能选择一个有材质的面'
      { 'enabled' => false, 'tooltip' => hint }
    rescue StandardError => e
      { 'enabled' => false, 'tooltip' => "当前选择不能入库：#{e.message}" }
    end

    def handle_library_pipette(model = Sketchup.active_model, picked_kind: '')
      state = ensure_space_models_ready!(model)
      status = library_pipette_selection_status(model, state)
      raise status['tooltip'].to_s unless status['enabled'] == true
      mode = picked_kind.to_s
      mode = status['mode'].to_s if mode.empty?
      if mode == 'pick'
        return start_library_pipette_tool(model, host_discipline_for(state))
      elsif mode == 'furniture'
        ingest_selected_furniture_into_library(model)
      else
        ingest_selected_material_into_library(model)
      end
    end

    def material_library_unique_model_name(model, base)
      names = model.materials.to_a.map { |material| material.name.to_s }
      candidate = base.to_s.empty? ? '库材质' : base.to_s
      return candidate unless names.include?(candidate)
      index = 2
      loop do
        value = "#{candidate}_#{index}"
        return value unless names.include?(value)
        index += 1
      end
    rescue StandardError
      "库材质_#{SecureRandom.hex(3)}"
    end

    def apply_material_metadata!(material, item, discipline = nil)
      metadata = item['metadata'].is_a?(Hash) ? item['metadata'] : {}
      path = item['path'].to_s
      textured = metadata['textured'] != false
      if textured
        material.texture = path
        texture = material.texture
        width = metadata['texture_width'].to_f
        height = metadata['texture_height'].to_f
        if texture && texture.respond_to?(:size=) && width.positive? && height.positive?
          begin
            texture.size = [width, height]
          rescue StandardError
            nil
          end
        end
      end
      color = Array(metadata['color'])
      if color.length >= 3 && material.respond_to?(:color=)
        material.color = Sketchup::Color.new(color[0].to_i, color[1].to_i, color[2].to_i)
      end
      material.alpha = metadata['alpha'].to_f if material.respond_to?(:alpha=) && metadata.key?('alpha')
      if material.respond_to?(:set_attribute)
        material.set_attribute(MATERIAL_LIBRARY_DICT, 'source_path', path)
        material.set_attribute(MATERIAL_LIBRARY_DICT, 'source_signature', item['signature'].to_s)
        material.set_attribute(MATERIAL_LIBRARY_DICT, 'material_id', item['id'].to_s)
        material.set_attribute(MATERIAL_LIBRARY_DICT, 'discipline', (discipline || @material_library_discipline).to_s)
      end
      material
    end

    def material_library_material_valid?(material)
      material && (!material.respond_to?(:valid?) || material.valid?)
    rescue StandardError
      false
    end

    def load_material_library_material(item, model = Sketchup.active_model, discipline = nil)
      raise '材质 PNG 不存在，请刷新材质库。' unless item && File.file?(item['path'].to_s)
      @material_library_loaded_caches ||= {}
      cache = (@material_library_loaded_caches[model.object_id] ||= {})
      key = [normalize_soft_library_key(item['path']), item['signature'].to_s]
      material = cache[key]
      return material if material_library_material_valid?(material)
      material = model.materials.to_a.find do |candidate|
        next false unless candidate.respond_to?(:get_attribute)
        normalize_soft_library_key(candidate.get_attribute(MATERIAL_LIBRARY_DICT, 'source_path', '').to_s) == key[0] &&
          candidate.get_attribute(MATERIAL_LIBRARY_DICT, 'source_signature', '').to_s == key[1]
      end
      unless material_library_material_valid?(material)
        name = material_library_unique_model_name(model, item['name'].to_s)
        material = model.materials.add(name)
        raise '无法在当前模型中创建材质。' unless material
        apply_material_metadata!(material, item, discipline)
      end
      cache.delete_if { |stored_key, _value| stored_key[0] == key[0] && stored_key != key }
      cache[key] = material
      material
    end

    def use_material_library_item(material_id, discipline = nil, model = Sketchup.active_model)
      discipline = (discipline || @material_library_discipline).to_s
      state = ensure_space_models_ready!(model)
      raise '请在对应专业工作区打开材质库。' unless host_discipline_for(state) == discipline
      raise '请先进入当前专业模型编辑状态，再使用材质。' unless material_library_context_active?(discipline, model, state)
      item = material_library_item(discipline, material_id, force: false)
      raise '材质库中找不到该材质，请刷新。' unless item
      material = load_material_library_material(item, model, discipline)
      faces = selected_material_faces(model)
      if faces.empty?
        model.materials.current = material if model.materials.respond_to?(:current=)
        Sketchup.send_action('selectPaintTool:')
        show_status("已载入“#{item['name']}”并启用油漆桶。", 'success')
      else
        operation_started = false
        model.start_operation("应用材质 #{item['name']}", true, false, true)
        operation_started = true
        faces.each { |face| face.material = material if face && face.valid? }
        model.commit_operation
        operation_started = false
        show_status("已把“#{item['name']}”应用到 #{faces.length} 个面。", 'success')
      end
      record_library_recent('material', discipline, item['id'], material_library_root(discipline))
      refresh_material_library_dialog(force: false)
      refresh_integrated_material_dialogs(discipline, force: false)
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      raise
    end

    def bind_material_library_callbacks(dialog)
      dialog.add_action_callback('ready') do |_ctx|
        safe_callback('打开材质库') { refresh_material_library_dialog(force: false) }
      end
      dialog.add_action_callback('choose_library') do |_ctx|
        safe_callback('设置材质库') { choose_material_library_root(@material_library_discipline) }
      end
      dialog.add_action_callback('refresh_library') do |_ctx|
        safe_callback('刷新材质库') do
          @material_library_caches ||= {}
          @material_library_caches.delete(@material_library_discipline.to_s)
          refresh_material_library_dialog(force: true)
        end
      end
      dialog.add_action_callback('use_material') do |_ctx, material_id|
        safe_callback('使用材质') { use_material_library_item(material_id, @material_library_discipline) }
      end
    end

    def show_material_library_dialog(discipline)
      require_workspace_ready!
      discipline = discipline.to_s
      state = load_state(Sketchup.active_model)
      raise '材质库只能在建筑、硬装、软装或景观工作区使用。' unless material_library_supported_discipline?(discipline)
      raise '请在当前工作区打开对应的材质库。' unless host_discipline_for(state) == discipline
      if @material_library_dialog && @material_library_dialog.visible?
        if @material_library_discipline.to_s == discipline
          @material_library_dialog.bring_to_front
          refresh_material_library_dialog
          return true
        end
        @material_library_dialog.close
        @material_library_dialog = nil
      end
      @material_library_discipline = discipline
      @material_library_dialog = UI::HtmlDialog.new(
        dialog_title: "#{material_library_discipline_name(discipline)}材质库",
        preferences_key: "GavinTools_SULinkHubMultiSpace_MaterialLibrary_#{discipline}",
        scrollable: true,
        resizable: true,
        width: 920,
        height: 680,
        min_width: 680,
        min_height: 480,
        style: UI::HtmlDialog::STYLE_DIALOG
      )
      @material_library_dialog.set_file(material_library_dialog_file)
      bind_material_library_callbacks(@material_library_dialog)
      @material_library_dialog.set_on_closed do
        @material_library_dialog = nil
        @material_library_discipline = ''
        GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { refresh_workspace_toolbar }
      end
      @material_library_dialog.show
      true
    end

    def toggle_material_library_dialog(discipline)
      discipline = discipline.to_s
      if @material_library_dialog && @material_library_dialog.visible? && @material_library_discipline.to_s == discipline
        @material_library_dialog.close
        refresh_workspace_toolbar
        false
      else
        show_material_library_dialog(discipline)
        refresh_workspace_toolbar
        true
      end
    end

    # -------------------------
    # 软装模型库与当前空间清单
    # -------------------------

    def soft_library_root
      # 项目协同 JSON 中固定的软装模型库路径优先级最高。这样同一项目重新打开、
      # 热重载或换一台 SU 实例时，不会因为本机会话偏好尚未恢复而出现
      # “代理→真能用，真→代理却突然说找不到模型库”的不对称状态。
      begin
        model = Sketchup.active_model
        project_root = current_project_path_settings(model)['soft_model_root'].to_s.strip if model
        unless project_root.to_s.empty?
          resolved = FastPath.expand(project_root.to_s)
          if !defined?(@soft_library_root_session) || @soft_library_root_session.to_s != resolved
            @soft_library_root_session = resolved
            @soft_library_structure_cache = {}
            @soft_library_cache = nil
            @soft_schedule_metadata_context_caches = {}
          end
          return @soft_library_root_session.to_s
        end
      rescue StandardError
        nil
      end
      return @soft_library_root_session.to_s if defined?(@soft_library_root_session) && !@soft_library_root_session.nil?
      path = Sketchup.read_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_ROOT_PREF_KEY, '').to_s
      @soft_library_root_session = path.empty? ? '' : FastPath.expand(path)
    rescue StandardError
      @soft_library_root_session = ''
    end

    def set_soft_library_root(path, persist_project: true)
      root = path.to_s.empty? ? '' : FastPath.expand(path.to_s)
      raise '请选择有效的模型库文件夹。' if root.empty? || !Dir.exist?(root)
      Sketchup.write_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_ROOT_PREF_KEY, root)
      @soft_library_root_session = root
      @soft_library_structure_cache = {}
      @soft_schedule_metadata_context_caches = {}
      ensure_soft_library_structure!(root)
      @soft_library_cache = nil
      @soft_library_warmup_token = nil
      persist_project_path_setting!('soft_model_root', root) if persist_project
      root
    end

    def choose_soft_library_root
      options = { title: '选择软装模型库文件夹' }
      current = soft_library_root
      options[:directory] = current unless current.empty?
      path = UI.select_directory(options)
      return false if path.nil? || path.to_s.empty?
      root = set_soft_library_root(path)
      schedule_soft_library_dialog_load(force: true)
      show_status("软装模型库已设置：#{root}", 'success')
      true
    end

    def soft_library_manager_dir(root = soft_library_root)
      root.to_s.empty? ? '' : File.join(root, SOFT_LIBRARY_MANAGER_DIR)
    end

    def soft_library_index_path(root = soft_library_root)
      dir = soft_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_INDEX_FILE)
    end

    def soft_library_catalog_path(root = soft_library_root)
      dir = soft_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_CATALOG_FILE)
    end

    def soft_library_thumbnail_dir(root = soft_library_root)
      dir = soft_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_THUMB_DIR)
    end

    def soft_library_thumbnail_meta_path(root = soft_library_root)
      dir = soft_library_thumbnail_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_THUMB_META_FILE)
    end

    # 用户仍可以把“0000共享ADR素材库”作为模型库根目录；
    # 真正可见的软装文件只放到下属“软装模型库”中。若用户
    # 直接选中了“软装模型库”，则不再重复嵌套一层同名目录。
    def soft_library_container_dir(root = soft_library_root)
      return '' if root.to_s.empty?
      expanded = FastPath.expand(root.to_s)
      basename = File.basename(expanded)
      return expanded if basename == SOFT_LIBRARY_CONTAINER_DIR
      return File.dirname(expanded) if basename == SOFT_LIBRARY_ORGANIZED_DIR
      return File.join(File.dirname(expanded), SOFT_LIBRARY_CONTAINER_DIR) if SOFT_LIBRARY_LEGACY_ORGANIZED_DIRS.include?(basename)
      File.join(expanded, SOFT_LIBRARY_CONTAINER_DIR)
    rescue StandardError
      root.to_s.empty? ? '' : File.join(root.to_s, SOFT_LIBRARY_CONTAINER_DIR)
    end

    def soft_library_organized_dir(root = soft_library_root)
      container = soft_library_container_dir(root)
      container.empty? ? '' : File.join(container, SOFT_LIBRARY_ORGANIZED_DIR)
    end

    def soft_library_legacy_organized_dirs(root = soft_library_root)
      return [] if root.to_s.empty?
      expanded_root = FastPath.expand(root.to_s)
      container = soft_library_container_dir(root)
      current_key = normalize_soft_library_key(soft_library_organized_dir(root))
      candidates = []
      candidates << expanded_root if SOFT_LIBRARY_LEGACY_ORGANIZED_DIRS.include?(File.basename(expanded_root))
      SOFT_LIBRARY_LEGACY_ORGANIZED_DIRS.each do |name|
        candidates << File.join(expanded_root, name)
        candidates << File.join(container, name) unless container.to_s.empty?
      end
      candidates.map { |path| FastPath.expand(path) }
                .uniq { |path| normalize_soft_library_key(path) }
                .reject { |path| normalize_soft_library_key(path) == current_key }
    rescue StandardError
      []
    end

    def soft_library_organized_folder_name?(value)
      ([SOFT_LIBRARY_ORGANIZED_DIR] + SOFT_LIBRARY_LEGACY_ORGANIZED_DIRS).include?(value.to_s)
    end

    def soft_library_proxy_dir(root = soft_library_root)
      dir = soft_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_PROXY_DIR)
    end

    def soft_library_trash_dir(root = soft_library_root)
      dir = soft_library_manager_dir(root)
      dir.empty? ? '' : File.join(dir, SOFT_LIBRARY_TRASH_DIR)
    end

    def write_json_atomic(path, payload)
      FileUtils.mkdir_p(File.dirname(path))
      temp = "#{path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(temp, path)
      true
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def write_json_create_if_absent(path, payload)
      FileUtils.mkdir_p(File.dirname(path))
      begin
        File.open(path, File::WRONLY | File::CREAT | File::EXCL, 0o666) do |file|
          file.write(JSON.pretty_generate(payload))
          file.flush
          file.fsync rescue nil
        end
        true
      rescue Errno::EEXIST
        false
      end
    end

    def json_deep_copy(value)
      JSON.parse(JSON.generate(value))
    rescue StandardError
      value.is_a?(Hash) ? value.dup : value
    end

    def with_soft_library_index_lock(root = soft_library_root)
      # SMB/NAS 上 File#flock 的跨机器语义并不在所有系统组合中一致。目录创建的
      # create-if-absent 由文件服务器完成，作为跨机器短租约更可靠；索引写入本身
      # 只需几十毫秒，120 秒 stale 阈值仅用于 SketchUp/电脑崩溃后的遗留锁恢复。
      lock_dir = "#{soft_library_index_path(root)}.write-lock"
      owner_file = File.join(lock_dir, 'owner.json')
      token = "#{current_host_name}:#{Process.pid}:#{SecureRandom.hex(6)}"
      acquired = false
      deadline = monotonic_time + 12.0
      loop do
        begin
          Dir.mkdir(lock_dir)
          acquired = true
          File.write(owner_file, JSON.generate({
            'token' => token, 'owner' => current_user_name, 'host' => current_host_name,
            'pid' => Process.pid, 'created_at' => Time.now.iso8601(6)
          }), mode: 'w:UTF-8') rescue nil
          break
        rescue Errno::EEXIST
          begin
            age = Time.now.to_f - File.mtime(lock_dir).to_f
            if age > 120.0
              stale = "#{lock_dir}.stale-#{Process.pid}-#{SecureRandom.hex(3)}"
              File.rename(lock_dir, stale)
              FileUtils.rm_rf(stale)
              next
            end
          rescue Errno::ENOENT
            next
          rescue StandardError
            nil
          end
          raise '软装模型库索引正在被另一位协作者写入，请稍后重试。' if monotonic_time >= deadline
          sleep(0.08)
        end
      end
      yield
    ensure
      if acquired && Dir.exist?(lock_dir.to_s)
        begin
          owner = File.file?(owner_file.to_s) ? JSON.parse(File.read(owner_file, encoding: 'UTF-8')) : {}
          FileUtils.rm_rf(lock_dir) if owner.is_a?(Hash) && owner['token'].to_s == token.to_s
        rescue StandardError
          nil
        end
      end
    end

    def merge_soft_library_index_values(base, yours, latest, path = [])
      return json_deep_copy(latest) if yours == base
      return json_deep_copy(yours) if latest == base || yours == latest
      if base.is_a?(Hash) && yours.is_a?(Hash) && latest.is_a?(Hash)
        merged = {}
        (base.keys + yours.keys + latest.keys).uniq.each do |key|
          if key.to_s == 'updated_at'
            merged[key] = [base[key], yours[key], latest[key]].map(&:to_s).max
            next
          end
          bp, yp, lp = base.key?(key), yours.key?(key), latest.key?(key)
          if yp == bp && (!yp || yours[key] == base[key])
            merged[key] = json_deep_copy(latest[key]) if lp
          elsif lp == bp && (!lp || latest[key] == base[key])
            merged[key] = json_deep_copy(yours[key]) if yp
          elsif yp == lp && (!yp || yours[key] == latest[key])
            merged[key] = json_deep_copy(yours[key]) if yp
          elsif bp && yp && lp && base[key].is_a?(Hash) && yours[key].is_a?(Hash) && latest[key].is_a?(Hash)
            merged[key] = merge_soft_library_index_values(base[key], yours[key], latest[key], path + [key.to_s])
          else
            raise "软装模型库索引并发冲突：#{(path + [key.to_s]).join(' / ')} 已被另一位协作者同时修改；已停止写入以避免覆盖。"
          end
        end
        return merged
      end
      raise "软装模型库索引并发冲突：#{path.join(' / ')}"
    end

    def ensure_soft_library_structure!(root = soft_library_root)
      raise '尚未设置软装模型库路径。' if root.to_s.empty?
      cache_key = normalize_soft_library_key(root)
      @soft_library_structure_cache ||= {}
      cached_at = @soft_library_structure_cache[cache_key].to_f
      return true if cached_at.positive? && (monotonic_time - cached_at) <= SOFT_LIBRARY_STRUCTURE_CACHE_TTL
      FileUtils.mkdir_p(root)
      FileUtils.mkdir_p(soft_library_manager_dir(root))
      FileUtils.mkdir_p(soft_library_thumbnail_dir(root))
      FileUtils.mkdir_p(soft_library_proxy_dir(root))
      FileUtils.mkdir_p(soft_library_trash_dir(root))
      FileUtils.mkdir_p(soft_library_container_dir(root))
      FileUtils.mkdir_p(soft_library_organized_dir(root))
      SOFT_LIBRARY_CATEGORIES.each do |category|
        FileUtils.mkdir_p(File.join(soft_library_organized_dir(root), category))
      end
      index = soft_library_index_path(root)
      unless File.file?(index)
        write_json_create_if_absent(index, {
          'schema' => SOFT_LIBRARY_SCHEMA,
          'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S'),
          'models' => {}
        })
      end
      @soft_library_structure_cache[cache_key] = monotonic_time
      true
    rescue StandardError
      @soft_library_structure_cache&.delete(cache_key) if defined?(cache_key)
      raise
    end

    def normalize_soft_library_key(path)
      expanded = FastPath.expand(path.to_s).tr('\\', '/')
      RUBY_PLATFORM.to_s.match?(/mswin|mingw|cygwin/i) ? expanded.downcase : expanded
    rescue StandardError
      path.to_s.tr('\\', '/')
    end

    def default_soft_model_metadata(path)
      {
        'model_id' => soft_model_id_for_path(path),
        'name' => File.basename(path.to_s, File.extname(path.to_s)),
        'manufacturer' => '',
        'price' => '',
        'contact' => '',
        'material_description' => '',
        'remark' => '',
        'category' => '',
        'subcategory' => '',
        'extra_fields' => {},
        'proxy_model_id' => '',
        'proxy_path' => '',
        'proxy_relative_path' => '',
        'proxy_name' => '',
        'proxy_updated_at' => '',
        'proxy_kind' => '',
        'proxy_visual_version' => 0,
        'proxy_auto_generated' => false,
        'proxy_source_signature' => '',
        'proxy_render_mode' => '',
        'planar_reference' => false,
        'proxy_passthrough' => false,
        'organized' => false,
        # 模型自身局部有效几何外包盒。只用于放置锚点/代理，不参与项目清单的
        # 实例尺寸统计；源 SKP 签名变化后自动失效。
        'bounds_values' => [],
        'bounds_source_signature' => '',
        'updated_at' => ''
      }
    end

    def prune_soft_library_index_read_bases!
      @soft_library_index_read_bases ||= {}
      now = monotonic_time
      @soft_library_index_read_bases.delete_if do |_object_id, record|
        !record.is_a?(Hash) || (record[:created_at].to_f.positive? && (now - record[:created_at].to_f) > SOFT_LIBRARY_INDEX_BASE_TTL)
      end
      overflow = @soft_library_index_read_bases.length - SOFT_LIBRARY_INDEX_BASE_MAX
      if overflow.positive?
        @soft_library_index_read_bases
          .sort_by { |_object_id, record| record.is_a?(Hash) ? record[:created_at].to_f : 0.0 }
          .first(overflow)
          .each { |object_id, _record| @soft_library_index_read_bases.delete(object_id) }
      end
      true
    rescue StandardError
      false
    end

    # 批量提交必须把“读取时基线”固定在批处理上下文中，不能只依赖按 object_id
    # 保存的短缓存。旧实现最多保留 24 份读取记录；清单超过 24 项时，每项身份
    # 解析产生的新读取会挤掉批次最初的基线，最终统一写入便会误报“缺少可靠基线”。
    def soft_library_index_read_base_snapshot(data, root = soft_library_root)
      return nil unless data.is_a?(Hash)
      record = @soft_library_index_read_bases && @soft_library_index_read_bases[data.object_id]
      return nil unless record.is_a?(Hash)
      return nil if record[:unreadable]
      return nil unless record[:root].to_s == normalize_soft_library_key(root)
      if record[:base_json].is_a?(String) && !record[:base_json].empty?
        JSON.parse(record[:base_json])
      elsif record[:base].is_a?(Hash)
        json_deep_copy(record[:base])
      end
    rescue StandardError
      nil
    end

    def backup_soft_library_index_before_write(path, root = soft_library_root)
      return '' unless File.file?(path.to_s) && File.size(path.to_s).positive?
      directory = File.join(soft_library_trash_dir(root), '索引备份')
      FileUtils.mkdir_p(directory)
      stamp = Time.now.strftime('%Y%m%d-%H%M%S-%6N')
      backup = File.join(directory, "#{stamp}-#{Process.pid}-模型记录.json")
      FileUtils.cp(path, backup)
      # 目录枚举在大型 SMB/NAS 上可能比复制这份小索引还慢。保留每次提交的备份，
      # 但只每 10 次写入整理一次历史；单条资料提交不再为“数一遍所有备份”阻塞。
      @soft_library_index_backup_write_counts ||= {}
      root_key = normalize_soft_library_key(root)
      count = @soft_library_index_backup_write_counts[root_key].to_i + 1
      @soft_library_index_backup_write_counts[root_key] = count
      if (count % 10).zero?
        backups = Dir.glob(File.join(directory, '*-模型记录.json')).sort_by do |candidate|
          File.mtime(candidate).to_f rescue 0.0
        end.reverse
        backups.drop(30).each { |candidate| File.delete(candidate) rescue nil }
      end
      backup
    rescue StandardError => e
      # 原索引仍由同目录临时文件 + 原子替换保护。备份目录偶发不可写时记录日志，
      # 不把一次本可安全完成的资料提交再次变成阻断性错误。
      log_exception('备份软装模型库索引失败', e)
      ''
    end

    def read_soft_library_index(root = soft_library_root)
      empty = { 'schema' => SOFT_LIBRARY_SCHEMA, 'models' => {} }
      return empty if root.to_s.empty?
      ensure_soft_library_structure!(root)
      path = soft_library_index_path(root)
      data = JSON.parse(File.read(path, encoding: 'UTF-8'))
      data = {} unless data.is_a?(Hash)
      data['schema'] = SOFT_LIBRARY_SCHEMA
      data['models'] = {} unless data['models'].is_a?(Hash)
      prune_soft_library_index_read_bases!
      @soft_library_index_read_bases ||= {}
      @soft_library_index_read_bases[data.object_id] = {
        root: normalize_soft_library_key(root),
        # 并发写保护只需要“读取时快照”，不需要长期保留第二整套 Hash/Array 对象图。
        # 这里直接保存新解析对象的序列化基线并返回对象本身，不再先做一次完整
        # JSON 深拷贝。调用方后续即使修改 data，基线字符串也不会改变。
        base_json: JSON.generate(data),
        created_at: monotonic_time
      }
      data
    rescue StandardError => e
      log_exception('读取软装模型库记录失败', e)
      fallback = empty || { 'schema' => SOFT_LIBRARY_SCHEMA, 'models' => {} }
      copy = json_deep_copy(fallback)
      prune_soft_library_index_read_bases!
      @soft_library_index_read_bases ||= {}
      @soft_library_index_read_bases[copy.object_id] = {
        root: normalize_soft_library_key(root),
        base: nil,
        unreadable: true,
        created_at: monotonic_time
      }
      copy
    end

    def write_soft_library_index!(data, root = soft_library_root, base_snapshot: nil, trusted_input: false)
      ensure_soft_library_structure!(root)
      yours = if data.is_a?(Hash)
                trusted_input ? data : json_deep_copy(data)
              else
                {}
              end
      yours['schema'] = SOFT_LIBRARY_SCHEMA
      yours['models'] = {} unless yours['models'].is_a?(Hash)
      prune_soft_library_index_read_bases!
      base_record = @soft_library_index_read_bases && @soft_library_index_read_bases.delete(data.object_id)
      normalized_root = normalize_soft_library_key(root)
      base = if base_snapshot.is_a?(Hash)
               trusted_input ? base_snapshot : json_deep_copy(base_snapshot)
             elsif base_snapshot.is_a?(String) && !base_snapshot.empty?
               JSON.parse(base_snapshot) rescue nil
             end
      if !base.is_a?(Hash) && base_record && base_record[:root].to_s == normalized_root && !base_record[:unreadable]
        if base_record[:base_json].is_a?(String) && !base_record[:base_json].empty?
          base = JSON.parse(base_record[:base_json]) rescue nil
        elsif base_record[:base].is_a?(Hash)
          # 兼容热重载接回的旧版记录。
          base = json_deep_copy(base_record[:base])
        end
      end
      unless base.is_a?(Hash)
        raise '软装模型库索引缺少可靠的读取基线，已拒绝写入；请重新读取/刷新模型库后再操作，避免用空索引覆盖共享记录。'
      end
      path = soft_library_index_path(root)
      merged = nil
      with_soft_library_index_lock(root) do
        latest = JSON.parse(File.read(path, encoding: 'UTF-8'))
        latest = {} unless latest.is_a?(Hash)
        latest['schema'] = SOFT_LIBRARY_SCHEMA
        latest['models'] = {} unless latest['models'].is_a?(Hash)
        # 绝大多数单人提交期间索引没有并发变化。完全相同时直接采用本批数据，
        # 避免为整个模型库递归三方合并并逐字段 JSON 深拷贝；真正有并发变化时
        # 仍走原来的严格三方合并与冲突拒绝。
        merged = latest == base ? yours.dup : merge_soft_library_index_values(base, yours, latest)
        merged['schema'] = SOFT_LIBRARY_SCHEMA
        merged['models'] = {} unless merged['models'].is_a?(Hash)
        merged['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        backup_soft_library_index_before_write(path, root)
        write_json_atomic(path, merged)
        verify = JSON.parse(File.read(path, encoding: 'UTF-8'))
        raise '模型库索引写入后复核失败。' unless verify == merged
      end
      @soft_library_index_cache = nil
      @soft_schedule_metadata_context_caches = {}
      true
    end

    def soft_model_id_for_path(path)
      Digest::SHA1.hexdigest(normalize_soft_library_key(path))[0, 20]
    end

    def soft_model_thumbnail_path(path, root = soft_library_root)
      File.join(soft_library_thumbnail_dir(root), "#{soft_model_id_for_path(path)}.png")
    end

    # 标准等轴测缩略图尚未生成时，先提取 SKP 文件内自带的小图作为即时预览。
    # 它不写入统一缩略图索引，也不会被误认为已经完成标准取景。
    def soft_model_quick_thumbnail_path(path, root = soft_library_root)
      File.join(soft_library_thumbnail_dir(root), "#{soft_model_id_for_path(path)}.quick.png")
    end

    def soft_quick_thumbnail_current?(path, quick = nil, root = soft_library_root)
      return false unless File.file?(path)
      quick ||= soft_model_quick_thumbnail_path(path, root)
      return false unless File.file?(quick) && File.size(quick).positive?
      File.mtime(quick).to_f >= File.mtime(path).to_f
    rescue StandardError
      false
    end

    def ensure_soft_model_quick_thumbnail(path, root = soft_library_root)
      return '' unless File.file?(path) && Sketchup.respond_to?(:save_thumbnail)
      ensure_soft_library_structure!(root)
      quick = soft_model_quick_thumbnail_path(path, root)
      return quick if soft_quick_thumbnail_current?(path, quick, root)
      temp = "#{quick}.tmp-#{Process.pid}-#{SecureRandom.hex(4)}.png"
      File.delete(quick) if File.file?(quick)
      ok = Sketchup.save_thumbnail(path, temp)
      if ok != false && File.file?(temp) && File.size(temp).positive?
        linkhub_mv(temp, quick)
        normalize_soft_thumbnail_white_background!(quick)
        return quick
      end
      ''
    rescue StandardError => e
      log_exception("读取模型内置缩略图失败：#{path}", e)
      ''
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def soft_model_sidecar_path(path)
      "#{path}.soft.json"
    end

    def read_soft_model_sidecar(path)
      sidecar = soft_model_sidecar_path(path)
      return {} unless File.file?(sidecar)
      data = JSON.parse(File.read(sidecar, encoding: 'UTF-8'))
      data.is_a?(Hash) ? data : {}
    rescue StandardError
      {}
    end

    def local_file_url(path)
      normalized = FastPath.expand(path.to_s).tr('\\', '/')
      return '' if normalized.empty?
      # Windows UNC 路径必须使用 file://server/share/...；旧实现固定拼 file:///，
      # 对 //server/share 会得到多余斜杠，Chromium HtmlDialog 经常直接拒绝加载，
      # 表现为模型库/批量入库缩略图偶发空白。
      encoded = normalized.gsub('%', '%25').gsub('#', '%23').gsub('?', '%3F').gsub(' ', '%20')
      normalized.start_with?('//') ? "file:#{encoded}" : "file:///#{encoded.sub(%r{\A/+}, '')}"
    rescue StandardError
      ''
    end

    def soft_thumbnail_source_signature(path)
      "#{SOFT_LIBRARY_THUMBNAIL_MODE}|v#{SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION}|#{fast_file_signature(path)}"
    rescue StandardError
      ''
    end

    def read_soft_thumbnail_meta(root = soft_library_root)
      path = soft_library_thumbnail_meta_path(root)
      return { 'schema' => 2, 'renderer_version' => SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION, 'mode' => SOFT_LIBRARY_THUMBNAIL_MODE, 'models' => {} } if path.to_s.empty? || !File.file?(path)
      signature = fast_file_signature(path)
      @soft_thumbnail_meta_cache ||= {}
      key = normalize_soft_library_key(root)
      cached = @soft_thumbnail_meta_cache[key]
      return cached[:data] if cached && cached[:signature] == signature
      data = JSON.parse(File.read(path, encoding: 'UTF-8'))
      data = {} unless data.is_a?(Hash)
      data['schema'] = 2
      data['renderer_version'] = SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION
      data['mode'] = SOFT_LIBRARY_THUMBNAIL_MODE
      data['models'] = {} unless data['models'].is_a?(Hash)
      @soft_thumbnail_meta_cache[key] = { signature: signature, data: data }
      data
    rescue StandardError => e
      log_exception('读取缩略图索引失败', e)
      { 'schema' => 2, 'renderer_version' => SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION, 'mode' => SOFT_LIBRARY_THUMBNAIL_MODE, 'models' => {} }
    end

    def write_soft_thumbnail_meta!(data, root = soft_library_root)
      path = soft_library_thumbnail_meta_path(root)
      return false if path.to_s.empty?
      payload = data.is_a?(Hash) ? data : {}
      payload['schema'] = 2
      payload['renderer_version'] = SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION
      payload['mode'] = SOFT_LIBRARY_THUMBNAIL_MODE
      payload['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      payload['models'] = {} unless payload['models'].is_a?(Hash)
      write_json_atomic(path, payload)
      @soft_thumbnail_meta_cache ||= {}
      @soft_thumbnail_meta_cache[normalize_soft_library_key(root)] = {
        signature: fast_file_signature(path), data: payload
      }
      true
    rescue StandardError => e
      log_exception('写入缩略图索引失败', e)
      false
    end

    def soft_thumbnail_current?(path, thumb = nil, root = soft_library_root)
      return false unless File.file?(path)
      thumb ||= soft_model_thumbnail_path(path, root)
      return false unless File.file?(thumb) && File.size(thumb).positive?
      record = read_soft_thumbnail_meta(root).dig('models', soft_model_id_for_path(path))
      record.is_a?(Hash) &&
        record['mode'].to_s == SOFT_LIBRARY_THUMBNAIL_MODE &&
        record['signature'].to_s == soft_thumbnail_source_signature(path)
    rescue StandardError
      false
    end

    def soft_thumbnail_url(path)
      # v0.13.6.188：一次 stat 取代 file?/mtime/size 三次 NAS 访问；取景过小/偏移的
      # 模型库缩略图改用“显示适配”派生图（image_media.rb，源 SKP 与原缩略图不变）。
      stat = File.stat(path.to_s)
      return '' unless stat.file?
      variant = soft_thumbnail_display_variant(path.to_s, stat)
      return "#{local_file_url(variant[:path])}?v=#{variant[:stamp]}" if variant
      stamp = "#{stat.mtime.to_f}-#{stat.size}"
      "#{local_file_url(path)}?v=#{Digest::SHA1.hexdigest(stamp)[0, 10]}"
    rescue SystemCallError
      ''
    rescue StandardError
      local_file_url(path)
    end

    # v0.13.6.188：图片格式识别/结构校验 + 缩略图显示适配，独立模块。
    Kernel.load(File.expand_path('image_media.rb', __dir__))
    # v0.13.7.3：双轴测缩略图视图 + 刷新/反转（thumbnail_views.rb）。
    Kernel.load(File.expand_path('thumbnail_views.rb', __dir__))
    # v0.13.7.7：组件外包盒一致性（bounds_integrity.rb）。
    Kernel.load(File.expand_path('bounds_integrity.rb', __dir__))

    def record_soft_thumbnail!(source_path, thumb_path, root = soft_library_root, defer: false, apply_views: true)
      return false unless File.file?(source_path) && File.file?(thumb_path) && File.size(thumb_path).positive?
      # v0.13.7.3：任何流程（内嵌缩略图提取、入库校准、旧刷新）写出标准缩略图后，若已有
      # 有效的轴测视图，立即换成用户选定的那一张，避免“刷新后又变回背面/乱图”。
      if apply_views && normalize_soft_library_key(thumb_path) == normalize_soft_library_key(soft_model_thumbnail_path(source_path, root))
        apply_soft_thumbnail_preferred_view!(source_path, root, thumb_path: thumb_path, record: false) rescue nil
      end
      data = read_soft_thumbnail_meta(root)
      data['models'] ||= {}
      data['models'][soft_model_id_for_path(source_path)] = {
        'signature' => soft_thumbnail_source_signature(source_path),
        'renderer_version' => SOFT_LIBRARY_THUMBNAIL_RENDER_VERSION,
        'mode' => SOFT_LIBRARY_THUMBNAIL_MODE,
        'thumbnail' => File.basename(thumb_path),
        'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S')
      }
      if defer
        # 批量刷新时把数十次小 JSON 写盘合并为一次，源 SKP 与图片仍逐个验证，
        # 只减少管理索引的网络 I/O，不降低任何模型文件安全校验。
        @soft_thumbnail_meta_dirty_root = root
        @soft_thumbnail_meta_pending_count = @soft_thumbnail_meta_pending_count.to_i + 1
      else
        write_soft_thumbnail_meta!(data, root)
        @soft_thumbnail_meta_dirty_root = nil
        @soft_thumbnail_meta_pending_count = 0
      end
      true
    end

    def flush_soft_thumbnail_meta!(root = nil)
      root = root.to_s.empty? ? @soft_thumbnail_meta_dirty_root.to_s : root.to_s
      return false if root.empty?
      key = normalize_soft_library_key(root)
      cached = (@soft_thumbnail_meta_cache || {})[key]
      return false unless cached && cached[:data].is_a?(Hash)
      write_soft_thumbnail_meta!(cached[:data], root)
      @soft_thumbnail_meta_dirty_root = nil
      @soft_thumbnail_meta_pending_count = 0
      true
    rescue StandardError => e
      log_exception('提交缩略图索引失败', e)
      false
    end

    def invalidate_soft_model_thumbnail!(path, root = soft_library_root, delete_file: true)
      thumb = soft_model_thumbnail_path(path, root)
      quick = soft_model_quick_thumbnail_path(path, root)
      File.delete(thumb) if delete_file && File.file?(thumb)
      File.delete(quick) if File.file?(quick)
      data = read_soft_thumbnail_meta(root)
      removed = data['models'].is_a?(Hash) ? data['models'].delete(soft_model_id_for_path(path)) : nil
      write_soft_thumbnail_meta!(data, root) if removed
      true
    rescue StandardError => e
      log_exception("清理软装缩略图失败：#{path}", e)
      false
    end

    # SketchUp 2024/2025/2026 的 meta/model_thumbnail.png 条目虽然扩展名是
    # .png，原生负载通常实际为 JPEG。ImageRep 按路径扩展名保存时会把它转换成
    # 真 PNG，而部分 SketchUp 版本随后无法从 SKP 中读取该缩略图，表现为
    # “本地缩略图候选验证失败”。因此所有像素修复必须保留输入文件的真实编码。
    def soft_thumbnail_binary_format(path)
      return :unknown unless File.file?(path) && File.size(path).positive?
      header = File.binread(path, 16).to_s.b
      return :jpeg if header.start_with?("\xFF\xD8".b)
      return :png if header.start_with?("\x89PNG\r\n\x1A\n".b)
      :unknown
    rescue StandardError
      :unknown
    end


    # 读取 SKP 容器内真正的 meta/model_thumbnail.png 负载。该条目名称固定为
    # .png，但 SketchUp 2024~2026 通常实际写入 JPEG/JFIF。不能根据文件名猜测，
    # 否则会把校正图写成真 PNG，SketchUp 随后拒绝读取候选 SKP。
    def read_skp_embedded_thumbnail_payload(skp_path)
      return nil unless File.file?(skp_path) && File.size(skp_path).positive?
      target_name = 'meta/model_thumbnail.png'.b
      File.open(skp_path, 'rb') do |source|
        size = source.stat.size
        scan_size = [size, 131_072].min
        source.seek(size - scan_size)
        tail = source.read(scan_size).to_s.b
        eocd_index = tail.rindex("PK\x05\x06".b)
        return nil unless eocd_index
        eocd_abs = size - scan_size + eocd_index
        fixed = tail.byteslice(eocd_index, 22)
        return nil unless fixed && fixed.bytesize == 22
        signature, disk_no, cd_disk, entries_disk, entries_total, cd_size, cd_offset, _comment_length = fixed.unpack('VvvvvVVv')
        return nil unless signature == 0x06054b50
        return nil unless disk_no.zero? && cd_disk.zero? && entries_disk == entries_total
        return nil if [entries_total, cd_size, cd_offset].include?(0xffff) || [cd_size, cd_offset].include?(0xffffffff)
        cd_abs = eocd_abs - cd_size
        prefix_size = cd_abs - cd_offset
        return nil if prefix_size.negative?

        source.seek(cd_abs)
        entries_total.times do
          central_fixed = source.read(46)
          return nil unless central_fixed && central_fixed.bytesize == 46
          fields = central_fixed.unpack('VvvvvvvVVVvvvvvVV')
          return nil unless fields[0] == 0x02014b50
          name_length = fields[10]
          extra_length = fields[11]
          comment_length = fields[12]
          name = source.read(name_length).to_s.b
          source.seek(extra_length + comment_length, IO::SEEK_CUR)
          next unless name == target_name

          local_abs = prefix_size + fields[16]
          source.seek(local_abs)
          local_fixed = source.read(30)
          return nil unless local_fixed && local_fixed.bytesize == 30
          local_fields = local_fixed.unpack('VvvvvvVVVvv')
          return nil unless local_fields[0] == 0x04034b50
          source.seek(local_fields[9] + local_fields[10], IO::SEEK_CUR)
          compressed = source.read(fields[8]).to_s.b
          return nil unless compressed.bytesize == fields[8]
          payload = case fields[4]
                    when 0
                      compressed
                    when 8
                      inflater = nil
                      begin
                        inflater = Zlib::Inflate.new(-Zlib::MAX_WBITS)
                        inflater.inflate(compressed) + inflater.finish
                      ensure
                        inflater.close rescue nil if inflater
                      end
                    else
                      nil
                    end
          return nil unless payload && payload.bytesize == fields[9]
          return nil unless Zlib.crc32(payload) == fields[7]
          return payload
        end
      end
      nil
    rescue StandardError => e
      log_exception("读取 SKP 原生缩略图负载失败：#{skp_path}", e)
      nil
    end

    def soft_skp_embedded_thumbnail_format(skp_path)
      payload = read_skp_embedded_thumbnail_payload(skp_path)
      return :unknown unless payload && !payload.empty?
      return :jpeg if payload.start_with?("\xFF\xD8".b)
      return :png if payload.start_with?("\x89PNG\r\n\x1A\n".b)
      :unknown
    rescue StandardError
      :unknown
    end

    # 将 SketchUp 生成的缩略图统一恢复为“原生白底、正常曝光”。
    #
    # 部分 SketchUp 2024/2025/2026 会把 ComponentDefinition#refresh_thumbnail
    # 按当前活动样式的暗色曝光写入源 SKP：不仅背景变成约 50~80 灰度，家具本体
    # 也被同一个暗化系数整体压暗。只把背景抠白会留下“黑家具”，所以这里先根据
    # 与画布边缘连通的中性背景估算全图暗化系数，把整张图按同一比例恢复曝光，
    # 再把边缘连通背景设为纯白。黑色家具仍保持黑色，只撤销系统施加的灰黑蒙层。
    def normalize_soft_thumbnail_white_background!(path)
      return false unless File.file?(path) && File.size(path).positive?
      return true unless defined?(Sketchup::ImageRep)

      image = Sketchup::ImageRep.new
      image.load_file(path)
      width = image.width.to_i
      height = image.height.to_i
      bits = image.bits_per_pixel.to_i
      padding = image.row_padding.to_i
      return true unless width.positive? && height.positive? && [24, 32].include?(bits)

      channels = bits / 8
      stride = width * channels + padding
      pixels = image.data.to_s.b
      return true if pixels.bytesize < stride * height

      windows = if Sketchup.respond_to?(:platform)
                  Sketchup.platform == :platform_win
                else
                  RUBY_PLATFORM.to_s.downcase.include?('win')
                end
      red_offset = windows ? 2 : 0
      green_offset = 1
      blue_offset = windows ? 0 : 2
      alpha_offset = channels == 4 ? 3 : nil
      changed = 0

      # 先把透明/半透明像素正确合成到白底，避免 Chromium 或系统缩略图再次乘 alpha。
      if alpha_offset
        alpha_samples = 0
        premultiplied_votes = 0
        height.times do |y|
          row = y * stride
          width.times do |x|
            offset = row + x * channels
            alpha = pixels.getbyte(offset + alpha_offset).to_i
            next unless alpha > 8 && alpha < 247
            alpha_samples += 1
            red = pixels.getbyte(offset + red_offset).to_i
            green = pixels.getbyte(offset + green_offset).to_i
            blue = pixels.getbyte(offset + blue_offset).to_i
            premultiplied_votes += 1 if [red, green, blue].max <= alpha + 3
          end
        end
        premultiplied = alpha_samples.positive? && premultiplied_votes.to_f / alpha_samples.to_f >= 0.82

        height.times do |y|
          row = y * stride
          width.times do |x|
            offset = row + x * channels
            alpha = pixels.getbyte(offset + alpha_offset).to_i
            next if alpha >= 255
            [red_offset, green_offset, blue_offset].each do |channel_offset|
              value = pixels.getbyte(offset + channel_offset).to_i
              opaque = if premultiplied
                         value + (255 - alpha)
                       else
                         ((value * alpha) + (255 * (255 - alpha)) + 127) / 255
                       end
              pixels.setbyte(offset + channel_offset, [[opaque, 0].max, 255].min)
            end
            pixels.setbyte(offset + alpha_offset, 255)
            changed += 1
          end
        end
      end

      edge_indices = []
      width.times do |x|
        edge_indices << x
        edge_indices << ((height - 1) * width + x) if height > 1
      end
      if height > 2
        (1...(height - 1)).each do |y|
          edge_indices << (y * width)
          edge_indices << (y * width + width - 1) if width > 1
        end
      end
      edge_indices.uniq!

      histogram = Hash.new(0)
      edge_indices.each do |pixel_index|
        y = pixel_index / width
        x = pixel_index - y * width
        offset = y * stride + x * channels
        red = pixels.getbyte(offset + red_offset).to_i
        green = pixels.getbyte(offset + green_offset).to_i
        blue = pixels.getbyte(offset + blue_offset).to_i
        histogram[[red / 8, green / 8, blue / 8]] += 1
      end

      dominant = histogram.max_by { |_key, count| count }
      if dominant
        quantized, count = dominant
        if count >= [edge_indices.length * 0.30, 8].max
          background = quantized.map { |value| value * 8 + 4 }
          neutral = (background.max - background.min) <= 30

          if neutral
            background_luma = (background[0] * 0.2126) + (background[1] * 0.7152) + (background[2] * 0.0722)

            # 标准缩略图的背景目标是白色。若边缘背景只有 40~220 灰度，说明整图
            # 被 SketchUp 样式或缩略图管线统一压暗；用同一增益恢复全部像素，不能
            # 只抬家具阴影或单独改背景。增益封顶防止极端坏图产生噪点爆白。
            if background_luma > 8.0 && background_luma < 238.0
              gain = [[252.0 / background_luma, 1.0].max, 5.0].min
              height.times do |y|
                row = y * stride
                width.times do |x|
                  offset = row + x * channels
                  [red_offset, green_offset, blue_offset].each do |channel_offset|
                    value = pixels.getbyte(offset + channel_offset).to_i
                    corrected = [[(value * gain).round, 0].max, 255].min
                    pixels.setbyte(offset + channel_offset, corrected)
                  end
                end
              end
              background = background.map { |value| [[(value * gain).round, 0].max, 255].min }
              changed += width * height
            end

            tolerance = 34
            tolerance_sq = tolerance * tolerance
            visited = Array.new(width * height, false)
            queue = []
            edge_indices.each do |pixel_index|
              y = pixel_index / width
              x = pixel_index - y * width
              offset = y * stride + x * channels
              red = pixels.getbyte(offset + red_offset).to_i
              green = pixels.getbyte(offset + green_offset).to_i
              blue = pixels.getbyte(offset + blue_offset).to_i
              distance = (red - background[0])**2 + (green - background[1])**2 + (blue - background[2])**2
              next unless distance <= tolerance_sq
              visited[pixel_index] = true
              queue << pixel_index
            end

            head = 0
            while head < queue.length
              pixel_index = queue[head]
              head += 1
              y = pixel_index / width
              x = pixel_index - y * width
              offset = y * stride + x * channels
              pixels.setbyte(offset + red_offset, 255)
              pixels.setbyte(offset + green_offset, 255)
              pixels.setbyte(offset + blue_offset, 255)
              pixels.setbyte(offset + alpha_offset, 255) if alpha_offset
              changed += 1

              neighbors = []
              neighbors << pixel_index - 1 if x.positive?
              neighbors << pixel_index + 1 if x + 1 < width
              neighbors << pixel_index - width if y.positive?
              neighbors << pixel_index + width if y + 1 < height
              neighbors.each do |neighbor|
                next if visited[neighbor]
                neighbor_y = neighbor / width
                neighbor_x = neighbor - neighbor_y * width
                neighbor_offset = neighbor_y * stride + neighbor_x * channels
                red = pixels.getbyte(neighbor_offset + red_offset).to_i
                green = pixels.getbyte(neighbor_offset + green_offset).to_i
                blue = pixels.getbyte(neighbor_offset + blue_offset).to_i
                distance = (red - background[0])**2 + (green - background[1])**2 + (blue - background[2])**2
                next unless distance <= tolerance_sq
                visited[neighbor] = true
                queue << neighbor
              end
            end
          end
        end
      end
      return true if changed.zero?

      # 必须按文件内容而不是文件名决定编码。Sketchup.save_thumbnail 写出的
      # 文件常常名为 .png、内容却是 JPEG；若在这里按扩展名转成真 PNG，再塞回
      # meta/model_thumbnail.png，SketchUp 2024 会直接拒绝读取该 SKP 缩略图。
      source_format = soft_thumbnail_binary_format(path)
      extension = case source_format
                  when :jpeg then '.jpg'
                  when :png then '.png'
                  else
                    ext = File.extname(path).downcase
                    %w[.jpg .jpeg].include?(ext) ? '.jpg' : '.png'
                  end
      temp = "#{path}.bright-#{Process.pid}-#{SecureRandom.hex(4)}#{extension}"
      output = Sketchup::ImageRep.new
      output.set_data(width, height, bits, padding, pixels)
      output.save_file(temp)
      written_format = soft_thumbnail_binary_format(temp)
      if source_format != :unknown && written_format != source_format
        raise "缩略图编码保持失败：原格式 #{source_format}，写出格式 #{written_format}。"
      end
      raise '明亮白底缩略图写出失败。' unless File.file?(temp) && File.size(temp).positive?
      linkhub_mv(temp, path)
      true
    rescue StandardError => e
      log_exception("缩略图明亮白底标准化失败，已保留源图：#{path}", e)
      File.file?(path) && File.size(path).positive?
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    # 严格验证缩略图四角确实已经恢复为明亮白底。刷新流程不能只验证
    # “文件能读取”，否则图像处理失败时仍会把原来的深灰缩略图当作成功写回。
    def soft_thumbnail_corner_luminance(path)
      return 0.0 unless File.file?(path) && File.size(path).positive?
      return 255.0 unless defined?(Sketchup::ImageRep)
      image = Sketchup::ImageRep.new
      image.load_file(path)
      width = image.width.to_i
      height = image.height.to_i
      bits = image.bits_per_pixel.to_i
      padding = image.row_padding.to_i
      return 0.0 unless width.positive? && height.positive? && [24, 32].include?(bits)

      channels = bits / 8
      stride = width * channels + padding
      pixels = image.data.to_s.b
      return 0.0 if pixels.bytesize < stride * height
      windows = if Sketchup.respond_to?(:platform)
                  Sketchup.platform == :platform_win
                else
                  RUBY_PLATFORM.to_s.downcase.include?('win')
                end
      red_offset = windows ? 2 : 0
      green_offset = 1
      blue_offset = windows ? 0 : 2
      alpha_offset = channels == 4 ? 3 : nil
      patch = [[([width, height].min / 32.0).round, 2].max, 8].min
      starts = [[0, 0], [width - patch, 0], [0, height - patch], [width - patch, height - patch]]
      samples = []
      starts.each do |start_x, start_y|
        patch.times do |dy|
          patch.times do |dx|
            x = [[start_x + dx, 0].max, width - 1].min
            y = [[start_y + dy, 0].max, height - 1].min
            offset = y * stride + x * channels
            red = pixels.getbyte(offset + red_offset).to_i
            green = pixels.getbyte(offset + green_offset).to_i
            blue = pixels.getbyte(offset + blue_offset).to_i
            if alpha_offset
              alpha = pixels.getbyte(offset + alpha_offset).to_i
              red = ((red * alpha) + (255 * (255 - alpha)) + 127) / 255
              green = ((green * alpha) + (255 * (255 - alpha)) + 127) / 255
              blue = ((blue * alpha) + (255 * (255 - alpha)) + 127) / 255
            end
            samples << (red * 0.2126) + (green * 0.7152) + (blue * 0.0722)
          end
        end
      end
      values = samples.sort
      values.empty? ? 0.0 : values[values.length / 2].to_f
    rescue StandardError => e
      log_exception("验证缩略图白底亮度失败：#{path}", e)
      0.0
    end

    def soft_thumbnail_white_background?(path, minimum = 225.0)
      soft_thumbnail_corner_luminance(path) >= minimum.to_f
    end

    # SketchUp 2024+ 的 SKP 是带固定前缀的 ZIP 容器。系统/资源管理器读取的原生
    # 缩略图正是 meta/model_thumbnail.png。只修改模型库缓存不能解决源 SKP 仍发灰，
    # 因此手动刷新后要把校正过的图像写回这个条目。这里不解压/重压 model.dat，
    # 未修改条目的压缩数据原样流式复制，避免大型家具模型重编码和内存暴涨。
    # 禁止直接改写现代 SKP 的 VFF/ZIP 容器。SketchUp 生成的 SKP 可能还带有
    # 通用 ZIP 工具看不到的原生一致性信息；任何手工替换内部缩略图都可能让
    # SketchUp 拒绝文件。保留方法名仅用于热重载兼容，始终返回 false。
    def replace_skp_embedded_thumbnail!(_skp_path, _image_path, log_failure: true)
      log('已阻止直接改写 SKP 内部缩略图；改用 SketchUp 原生 save_copy。') if log_failure
      false
    end

    def repair_source_skp_native_thumbnail!(_skp_path)
      raise '已禁用直接改写 SKP 内部缩略图；请使用原生刷新流程。'
    end

    def soft_thumbnail_bounds_points(values, transform = identity_transformation)
      x0, y0, z0, x1, y1, z1 = Array(values).map(&:to_f)
      [
        Geom::Point3d.new(x0, y0, z0), Geom::Point3d.new(x1, y0, z0),
        Geom::Point3d.new(x1, y1, z0), Geom::Point3d.new(x0, y1, z0),
        Geom::Point3d.new(x0, y0, z1), Geom::Point3d.new(x1, y0, z1),
        Geom::Point3d.new(x1, y1, z1), Geom::Point3d.new(x0, y1, z1)
      ].map { |point| point.transform(transform) }
    end

    def soft_thumbnail_render_option_snapshot(model = Sketchup.active_model)
      options = model.rendering_options
      keys = %w[
        InactiveHidden InactiveFade DrawGround DrawHorizon DrawHidden DrawBackEdges
        DrawDepthQue DrawLineEnds DrawProfilesOnly DisplaySketchAxes DisplayInstanceAxes
        DisplayFog DisplayColorByLayer DisplayWatermarks ModelTransparency DrawSilhouettes
        Texture RenderMode FaceFrontColor FaceBackColor BackgroundColor SkyColor GroundColor
        AmbientOcclusion AmbientOcclusionDistance AmbientOcclusionIntensity
        AmbientOcclusionColor AmbientOcclusionMultiplier
      ]
      keys.each_with_object({}) do |key, memo|
        memo[key] = options[key] if options.respond_to?(:keys) && options.keys.include?(key)
      rescue StandardError
        nil
      end
    rescue StandardError
      {}
    end

    def apply_soft_thumbnail_render_options!(model = Sketchup.active_model)
      options = model.rendering_options
      values = {
        # 不能使用 RenderMode=3；该值在多个 SketchUp 版本中不是稳定的“纹理模式”，
        # 会出现暗面或错误显示。标准纹理着色应使用 RenderMode=2 + Texture=true。
        'RenderMode' => 2,
        'Texture' => true,
        'InactiveHidden' => false,
        'InactiveFade' => 0.0,
        'DrawGround' => false,
        'DrawHorizon' => false,
        'DrawHidden' => false,
        'DrawBackEdges' => false,
        'DrawDepthQue' => false,
        'DrawLineEnds' => false,
        'DrawProfilesOnly' => false,
        'DisplaySketchAxes' => false,
        'DisplayInstanceAxes' => false,
        'DisplayFog' => false,
        'DisplayColorByLayer' => false,
        'DisplayWatermarks' => false,
        'ModelTransparency' => false,
        'DrawSilhouettes' => false,
        'FaceFrontColor' => Sketchup::Color.new(238, 238, 238),
        'FaceBackColor' => Sketchup::Color.new(222, 222, 222),
        'AmbientOcclusion' => false,
        'BackgroundColor' => Sketchup::Color.new(255, 255, 255),
        'SkyColor' => Sketchup::Color.new(255, 255, 255),
        'GroundColor' => Sketchup::Color.new(255, 255, 255)
      }
      available = options.respond_to?(:keys) ? options.keys : []
      values.each { |key, value| options[key] = value if available.include?(key) }
      true
    rescue StandardError => e
      log_exception('应用明亮缩略图显示设置失败', e)
      false
    end

    def restore_soft_thumbnail_render_options!(snapshot, model = Sketchup.active_model)
      options = model.rendering_options
      snapshot.each { |key, value| options[key] = value }
      true
    rescue StandardError
      false
    end


    def soft_thumbnail_default_style_path
      candidates = [
        ['00Default Style.style', 'Styles/Default Styles'],
        ['Simple Style.style', 'Styles/Default Styles'],
        ['00Default Style.style', 'Styles']
      ]
      candidates.each do |filename, directory|
        path = Sketchup.find_support_file(filename, directory) rescue nil
        return path if path && File.file?(path)
      end
      ''
    rescue StandardError
      ''
    end

    # ComponentDefinition#refresh_thumbnail 会受当前模型样式影响。旧项目若正在使用
    # 深色、单色、X-Ray 或特殊边线样式，即使相机正确也会把源 SKP 的内置缩略图
    # 写成一块黑色。这里在同一个可回滚 operation 内临时选用 SketchUp 自带默认
    # 样式，明确切到“着色+纹理”，保存缩略图后立即恢复用户原样式。
    def with_soft_bright_thumbnail_style(model = Sketchup.active_model, refresh_view: true)
      styles = model.styles
      original_style = styles.selected_style rescue nil
      original_options = soft_thumbnail_render_option_snapshot(model)
      original_style_changed = styles.active_style_changed rescue false
      original_style_ids = styles.to_a.map(&:object_id) rescue []
      shadow = model.shadow_info rescue nil
      original_shadow = {}
      %w[DisplayShadows UseSunForAllShading Light Dark].each do |key|
        original_shadow[key] = shadow[key] if shadow && shadow.respond_to?(:keys) && shadow.keys.include?(key)
      rescue StandardError
        nil
      end
      bright_style = nil
      begin
        # 旧实现为了保护“未保存的活动样式”而跳过默认样式切换，但这正是所有
        # refresh_thumbnail 被写成深灰色的根因。该函数始终运行在可 abort 的
        # SketchUp operation 内，因此可以放心临时切到系统默认样式；结束后恢复
        # 原选中样式与全部 RenderingOptions，外层 abort 再完整回滚样式集合。
        style_path = soft_thumbnail_default_style_path
        unless style_path.to_s.empty?
          styles.add_style(style_path, true)
          bright_style = styles.selected_style rescue nil
        end
        apply_soft_thumbnail_render_options!(model)
        if shadow && shadow.respond_to?(:keys)
          shadow['DisplayShadows'] = false if shadow.keys.include?('DisplayShadows')
          shadow['UseSunForAllShading'] = false if shadow.keys.include?('UseSunForAllShading')
          shadow['Light'] = 80 if shadow.keys.include?('Light')
          shadow['Dark'] = 20 if shadow.keys.include?('Dark')
        end
        # refresh_thumbnail 读取的是已提交到 selected_style 的属性，而不是仅存在
        # 于 active_style 的临时 RenderingOptions。必须提交临时默认样式，否则即便
        # BackgroundColor 已设为白色，源 SKP 中仍会保留旧暗色样式的缩略图。
        styles.update_selected_style if styles.respond_to?(:update_selected_style)
        if refresh_view
          model.active_view.invalidate rescue nil
          model.active_view.refresh rescue nil
        end
        yield
      ensure
        begin
          styles.selected_style = original_style if original_style && original_style.valid?
        rescue StandardError
          nil
        end
        restore_soft_thumbnail_render_options!(original_options, model)
        original_shadow.each { |key, value| shadow[key] = value } if shadow
        # 在 2026+ 可立即移除临时样式；旧版由外层 abort_operation 回滚。
        begin
          if bright_style && bright_style.valid? && !original_style_ids.include?(bright_style.object_id) && styles.respond_to?(:remove_style)
            styles.remove_style(bright_style)
          end
        rescue StandardError
          nil
        end
        # 恢复 RenderingOptions 后不调用 update_selected_style，避免覆盖用户原样式；
        # 若用户原本有未保存样式改动，外层 abort_operation 会恢复完整 active_style。
        log('缩略图刷新前检测到活动样式有未保存改动，已通过事务回滚保护。') if original_style_changed
        model.active_view.invalidate rescue nil if refresh_view
      end
    end

    def with_soft_thumbnail_render_environment(model = Sketchup.active_model)
      render_options = soft_thumbnail_render_option_snapshot(model)
      layer_visibility = model.layers.to_a.map { |layer| [layer, layer.visible?] }
      shadow_visible = begin
        model.shadow_info['DisplayShadows']
      rescue StandardError
        nil
      end
      begin
        model.layers.each { |layer| layer.visible = true rescue nil }
        apply_soft_thumbnail_render_options!(model)
        model.shadow_info['DisplayShadows'] = false unless shadow_visible.nil? rescue nil
        yield
      ensure
        layer_visibility.each do |layer, visible|
          layer.visible = visible if layer
        rescue StandardError
          nil
        end
        restore_soft_thumbnail_render_options!(render_options, model)
        model.shadow_info['DisplayShadows'] = shadow_visible unless shadow_visible.nil? rescue nil
      end
    end

    def cleanup_soft_thumbnail_definitions!(model, original_ids)
      known = Array(original_ids).to_h { |object_id| [object_id, true] }
      4.times do
        removed = 0
        model.definitions.to_a.reverse_each do |definition|
          next unless definition && definition.valid?
          next if known[definition.object_id]
          next unless definition.respond_to?(:instances) && definition.instances.empty?
          if remove_unused_definition!(definition, model)
            removed += 1
          end
        rescue StandardError
          next
        end
        break if removed.zero?
      end
      true
    rescue StandardError
      false
    end

    def soft_source_thumbnail_camera(definition)
      values = soft_definition_bounds_values(definition)
      raise '模型没有可用于缩略图的有效几何。' unless soft_bounds_values_valid?(values)
      points = soft_thumbnail_bounds_points(values)
      box = Geom::BoundingBox.new
      points.each { |point| box.add(point) }
      center = box.center
      max_extent = [box.width.to_f, box.height.to_f, box.depth.to_f, 1.0].max
      eye_direction = Geom::Vector3d.new(1.0, -1.0, 1.0)
      eye_direction.normalize!
      eye = center.offset(eye_direction, max_extent * 4.0 + 10.0)
      forward = eye.vector_to(center)
      forward.normalize!
      up_hint = Geom::Vector3d.new(0.0, 0.0, 1.0)
      right = up_hint.cross(forward)
      right = Geom::Vector3d.new(1.0, 0.0, 0.0) if right.length.to_f < 1.0e-9
      right.normalize!
      screen_up = forward.cross(right)
      screen_up.normalize!
      horizontal = points.map { |point| center.vector_to(point).dot(right).abs }.max.to_f * 2.0
      vertical = points.map { |point| center.vector_to(point).dot(screen_up).abs }.max.to_f * 2.0
      frame_height = [vertical, horizontal, 1.0].max * SOFT_LIBRARY_THUMBNAIL_MARGIN
      camera = Sketchup::Camera.new(eye, center, screen_up, false)
      camera.height = frame_height if camera.respond_to?(:height=)
      camera.aspect_ratio = 1.0 if camera.respond_to?(:aspect_ratio=)
      camera
    end

    # 使用组件定义自身的红、绿、蓝轴生成缩略图相机。相机坐标全部位于
    # definition 的局部坐标系，不读取当前项目相机或世界旋转，因此无论家具在
    # 项目中如何旋转，模型库卡片始终按其组件轴显示标准轴测角度。
    def prepare_soft_definition_embedded_thumbnail!(definition, model = Sketchup.active_model)
      return false unless definition && definition.valid?
      return false unless Sketchup.version.to_i >= 23
      return false unless definition.respond_to?(:thumbnail_camera=) && definition.respond_to?(:refresh_thumbnail)
      definition.thumbnail_camera = soft_source_thumbnail_camera(definition)
      definition.refresh_thumbnail
      true
    rescue StandardError => e
      log_exception('设置组件轴缩略图相机失败', e)
      false
    end

    def soft_thumbnail_source_backup_path(path, root = soft_library_root, manager_dir = nil)
      folder = File.join(manager_dir.to_s.empty? ? soft_library_manager_dir(root) : manager_dir.to_s, '缩略图源文件备份')
      FileUtils.mkdir_p(folder)
      "#{File.join(folder, soft_model_id_for_path(path))}_#{File.basename(path)}"
    end

    # 手动刷新真正重写源 SKP 内置缩略图：相机算法完全沿用 v0.9.63，
    # 只把渲染环境改为可回滚的明亮默认样式，分别解决“角度错”和“整图发黑”。
    # 手动刷新只允许 SketchUp 自己生成和保存 SKP。此前 v0.9.73-v0.9.76
    # 为了把白底校正图强行写回 meta/model_thumbnail.png，直接改写了 VFF/ZIP
    # 容器。压缩包虽然能被通用 ZIP 工具读取，但 SketchUp 会拒绝这个候选文件。
    # 这里彻底删除该危险路径：相机沿用 v0.9.63，显示环境临时切为白底明亮样式，
    # 然后直接采用 ComponentDefinition#save_copy 生成的原生候选文件。
    def write_standard_thumbnail_into_source_skp!(path, root = soft_library_root, backup_source: true, backup_manager_dir: nil, cache_thumbnail_path: nil, defer_thumbnail_meta: false)
      raise '找不到源模型文件。' unless File.file?(path)
      raise '源模型文件为只读，不能写入内置缩略图。' unless File.writable?(path)
      model = Sketchup.active_model
      raise '当前 SketchUp 不支持写入组件缩略图相机。' unless
        Sketchup.version.to_i >= 23 &&
        Sketchup::ComponentDefinition.instance_methods.include?(:thumbnail_camera=) &&
        Sketchup::ComponentDefinition.instance_methods.include?(:refresh_thumbnail)
      raise '发布正在进行，不能同时刷新源模型缩略图。' if publish_critical_section?
      source_snapshot = stable_full_file_snapshot_signature(path)
      raise '无法稳定读取源模型版本；为避免缩略图刷新覆盖他人新模型，已取消。' if source_snapshot.empty?

      original_definition_ids = model.definitions.to_a.map(&:object_id)
      operation_started = false
      token = "#{Process.pid}-#{SecureRandom.hex(4)}"
      local_temp = File.join(TEMP_WORK_DIR, "SU_LinkHub-thumbnail-native-#{token}.skp")
      native_preview = File.join(TEMP_WORK_DIR, "SU_LinkHub-thumbnail-native-preview-#{token}.png")
      remote_stage = File.join(File.dirname(path), ".#{File.basename(path)}.thumbnail-ready-#{token}.skp")
      rollback = File.join(File.dirname(path), ".#{File.basename(path)}.thumbnail-rollback-#{token}.skp")
      backup = soft_thumbnail_source_backup_path(path, root, backup_manager_dir)
      cache_temp = cache_thumbnail_path.to_s.empty? ? nil : "#{cache_thumbnail_path}.tmp-#{Process.pid}-#{SecureRandom.hex(4)}"
      @soft_thumbnail_rendering = true
      begin_soft_heavy_interaction(:thumbnail)

      begin
        model.start_operation('写入模型库源缩略图', true, false, false)
        operation_started = true
        source_guid = if defined?(Sketchup::Skp) && Sketchup::Skp.respond_to?(:read_guid)
                        Sketchup::Skp.read_guid(path).to_s
                      else
                        ''
                      end
        definition = load_definition_compat(model.definitions, path)
        raise '源模型定义载入失败。' unless definition && definition.valid?
        if !source_guid.empty? && definition.guid.to_s != source_guid
          raise '当前 SketchUp 会话中的同源组件定义已被修改，已停止写回以避免覆盖源模型几何。请保存工作后重启 SketchUp，再单独刷新该缩略图。'
        end

        saved = nil
        with_soft_bright_thumbnail_style(model) do
          # 角度严格沿用 v0.9.63 的组件局部坐标轴相机。
          definition.thumbnail_camera = soft_source_thumbnail_camera(definition)
          # 先让默认白底样式真正刷新到视口，再刷新组件原生缩略图。
          model.active_view.invalidate rescue nil
          model.active_view.refresh rescue nil
          definition.refresh_thumbnail
          model.active_view.invalidate rescue nil
          model.active_view.refresh rescue nil
          # 第二次刷新用于规避 SU2024 首次刷新仍读取旧活动样式的情况。
          definition.refresh_thumbnail
          saved = if definition.respond_to?(:save_copy)
                    definition.save_copy(local_temp)
                  else
                    definition.save_as(local_temp)
                  end
        end

        raise 'SketchUp 未能写出带新缩略图的本地模型副本。' unless saved || File.file?(local_temp)
        raise '写出的本地模型副本为空。' unless File.file?(local_temp) && File.size(local_temp).positive?
        candidate_content_signature = full_file_content_signature(local_temp)
        raise '缩略图本地候选完整校验失败。' if candidate_content_signature.empty?

        # 只验证 SketchUp 自己生成的候选；不再修改其内部 ZIP/VFF 条目。
        preview_ok = Sketchup.save_thumbnail(local_temp, native_preview)
        raise 'SketchUp 生成的本地候选无法读取原生缩略图。' unless
          preview_ok != false && File.file?(native_preview) && File.size(native_preview).positive?
        luminance = soft_thumbnail_corner_luminance(native_preview)
        log(format('原生缩略图候选验证通过：角点亮度 %.1f；候选文件由 SketchUp 原生 save_copy 生成。', luminance))
        if luminance < 225.0
          # 不再把图像强行塞回 SKP。模型库卡片会在后续提取阶段单独做白底校正；
          # 源 SKP 始终保持 SketchUp 原生可读，绝不因缩略图而损坏。
          log(format('SketchUp 原生缩略图仍偏暗（%.1f），源 SKP 保持原生格式；模型库缓存将单独校正为白底。', luminance))
        end

        FileUtils.cp(path, backup) if backup_source && !File.file?(backup)
        raise '源模型在缩略图生成期间已被其他人更新；本次未覆盖。' unless stable_full_file_snapshot_signature(path) == source_snapshot
        file_operation_with_retry { linkhub_copy_file(local_temp, remote_stage) }
        raise '缩略图模型传输到源目录失败。' unless File.file?(remote_stage) && full_file_content_signature(remote_stage) == candidate_content_signature
        raise '源模型在缩略图候选传输期间已被其他人更新；本次未覆盖。' unless stable_full_file_snapshot_signature(path) == source_snapshot

        linkhub_mv(path, rollback)
        unless stable_full_file_snapshot_signature(rollback) == source_snapshot
          promote_file_create_only!(rollback, path) unless File.exist?(path)
          raise '源模型在最终替换窗口发生变化；实际移走版本与基线不一致，已停止刷新。'
        end
        begin
          promote_file_create_only!(remote_stage, path)
          raise '新源模型文件验证失败。' unless File.file?(path) && File.size(path).positive?
          verify = File.join(TEMP_WORK_DIR, "SU_LinkHub-thumbnail-final-#{token}.png")
          verify_ok = Sketchup.save_thumbnail(path, verify)
          raise '新源模型的原生缩略图无法由 SketchUp 读取，已恢复原文件。' unless
            verify_ok != false && File.file?(verify) && File.size(verify).positive?
          final_luminance = soft_thumbnail_corner_luminance(verify)
          log(format('源 SKP 原生验证完成：角点亮度 %.1f，文件大小 %d。', final_luminance, File.size(path)))
          unless cache_thumbnail_path.to_s.empty?
            FileUtils.mkdir_p(File.dirname(cache_thumbnail_path))
            linkhub_copy_file(verify, cache_temp)
            raise '新缩略图缓存白底校正失败。' unless normalize_soft_thumbnail_white_background!(cache_temp)
            raise '新缩略图缓存仍为灰暗背景。' unless soft_thumbnail_white_background?(cache_temp)
            linkhub_mv(cache_temp, cache_thumbnail_path)
            record_soft_thumbnail!(path, cache_thumbnail_path, root, defer: defer_thumbnail_meta)
          end
        rescue StandardError
          if File.file?(path) && defined?(candidate_content_signature) && !candidate_content_signature.to_s.empty?
            remove_file_if_content_matches!(path, candidate_content_signature)
          end
          promote_file_create_only!(rollback, path) if File.file?(rollback) && !File.exist?(path)
          raise
        ensure
          File.delete(verify) if defined?(verify) && verify && File.file?(verify)
        end
        File.delete(rollback) if File.file?(rollback)
        true
      ensure
        model.abort_operation rescue nil if operation_started
        cleanup_soft_thumbnail_definitions!(model, original_definition_ids)
        @soft_thumbnail_rendering = false
        end_soft_heavy_interaction(:thumbnail)
      end
    rescue StandardError
      if defined?(rollback) && rollback && File.file?(rollback) && !File.file?(path)
        promote_file_create_only!(rollback, path) rescue nil
      end
      raise
    ensure
      File.delete(local_temp) if defined?(local_temp) && local_temp && File.file?(local_temp)
      File.delete(native_preview) if defined?(native_preview) && native_preview && File.file?(native_preview)
      File.delete(remote_stage) if defined?(remote_stage) && remote_stage && File.file?(remote_stage)
      File.delete(cache_temp) if defined?(cache_temp) && cache_temp && File.file?(cache_temp)
      @soft_thumbnail_rendering = false
      end_soft_heavy_interaction(:thumbnail) if (@soft_heavy_interactions || {})[:thumbnail].to_i.positive?
    end

    def extract_soft_model_embedded_thumbnail(path, thumb, root = soft_library_root)
      return false unless File.file?(path) && Sketchup.respond_to?(:save_thumbnail)
      temp = "#{thumb}.extract-#{Process.pid}-#{SecureRandom.hex(4)}.png"
      FileUtils.mkdir_p(File.dirname(thumb))
      ok = Sketchup.save_thumbnail(path, temp)
      unless ok != false && File.file?(temp) && File.size(temp).positive?
        # “没有内置缩略图”不是插件异常，也不应每次打开模型库都打印堆栈。
        # 不自动载入高模或改写源文件；卡片保留占位图，用户点击刷新时再一次性生成。
        log("源模型没有内置缩略图，已跳过后台提取；可在卡片右上角点击刷新生成：#{path}")
        return false
      end
      linkhub_mv(temp, thumb)
      raise '源模型缩略图白底校正失败。' unless normalize_soft_thumbnail_white_background!(thumb)
      raise '源模型缩略图仍为灰暗背景。' unless soft_thumbnail_white_background?(thumb)
      record_soft_thumbnail!(path, thumb, root)
      true
    rescue StandardError => e
      log_exception("提取源模型内置缩略图失败：#{path}", e)
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    # 旧版临时舞台渲染器保留用于兼容热重载中的旧调用，但 v0.9.53 的模型库
    # 打开与可见卡片请求均不会再调用它；只有源 SKP 自带缩略图会被读取。
    def render_standard_soft_model_thumbnail(path, thumb, model = Sketchup.active_model)
      return false unless model && File.file?(path)
      view = model.active_view
      return false unless view && view.respond_to?(:write_image)

      original_path = Array(model.active_path)
      original_selection = model.selection.to_a
      original_context_transform = active_context_world_transformation(model)
      original_view = capture_active_view_state(model)
      render_options = soft_thumbnail_render_option_snapshot(model)
      layer_visibility = model.layers.to_a.map { |layer| [layer, layer.visible?] }
      shadow_visible = begin
        model.shadow_info['DisplayShadows']
      rescue StandardError
        nil
      end
      definition_ids = model.definitions.to_a.map(&:object_id)
      operation_started = false
      stage = nil
      temp_file = "#{thumb}.render-#{Process.pid}-#{SecureRandom.hex(4)}.png"
      ok = false

      @soft_thumbnail_rendering = true
      begin_soft_heavy_interaction(:thumbnail)
      with_soft_selection_refresh_suspended do
        model.start_operation('生成统一模型缩略图', true, false, false)
        operation_started = true
        model.selection.clear
        model.active_path = nil if model.respond_to?(:active_path=)
        existing_root_entities = model.entities.to_a
        existing_root_visibility = existing_root_entities.map { |entity| [entity, entity.hidden?] }
        existing_root_entities.each { |entity| entity.hidden = true rescue nil }
        stage = model.entities.add_group
        definition = load_definition_compat(model.definitions, path)
        raise '缩略图模型定义载入失败。' unless definition && definition.valid?
        stage.entities.add_instance(definition, identity_transformation)
        values = soft_definition_bounds_values(definition)
        raise '模型没有可用于缩略图的有效几何。' unless soft_bounds_values_valid?(values)

        model.layers.each { |layer| layer.visible = true rescue nil }
        apply_soft_thumbnail_render_options!(model)
        model.shadow_info['DisplayShadows'] = false if !shadow_visible.nil?

        points = soft_thumbnail_bounds_points(values)
        box = Geom::BoundingBox.new
        points.each { |point| box.add(point) }
        center = box.center
        max_extent = [box.width.to_f, box.height.to_f, box.depth.to_f, 1.0].max
        eye_direction = Geom::Vector3d.new(1.0, -1.0, 1.0)
        eye_direction.normalize!
        eye = center.offset(eye_direction, max_extent * 4.0 + 10.0)
        forward = eye.vector_to(center)
        forward.normalize!
        up_hint = Geom::Vector3d.new(0.0, 0.0, 1.0)
        right = up_hint.cross(forward)
        right = Geom::Vector3d.new(1.0, 0.0, 0.0) if right.length.to_f < 1.0e-9
        right.normalize!
        screen_up = forward.cross(right)
        screen_up.normalize!
        horizontal = points.map { |point| center.vector_to(point).dot(right).abs }.max.to_f * 2.0
        vertical = points.map { |point| center.vector_to(point).dot(screen_up).abs }.max.to_f * 2.0
        frame_height = [vertical, horizontal, 1.0].max * SOFT_LIBRARY_THUMBNAIL_MARGIN

        camera = Sketchup::Camera.new(eye, center, screen_up, false)
        camera.height = frame_height if camera.respond_to?(:height=)
        camera.aspect_ratio = 1.0 if camera.respond_to?(:aspect_ratio=)
        view.camera = camera
        view.invalidate
        view.refresh if view.respond_to?(:refresh)

        FileUtils.mkdir_p(File.dirname(thumb))
        options = {
          filename: temp_file,
          width: SOFT_LIBRARY_THUMBNAIL_SIZE,
          height: SOFT_LIBRARY_THUMBNAIL_SIZE,
          antialias: true,
          compression: 0.92
        }
        ok = view.write_image(options)
        unless ok && File.file?(temp_file) && File.size(temp_file).positive?
          ok = view.write_image(options)
        end
        raise '统一缩略图图像未能写出。' unless ok && File.file?(temp_file) && File.size(temp_file).positive?
        linkhub_mv(temp_file, thumb)
        normalize_soft_thumbnail_white_background!(thumb)
        ok = true
      ensure
        if defined?(existing_root_visibility) && existing_root_visibility
          existing_root_visibility.each do |entity, was_hidden|
            entity.hidden = was_hidden if entity && entity.valid?
          rescue StandardError
            nil
          end
        end
        begin
          model.active_path = (original_path.empty? ? nil : original_path) if model.respond_to?(:active_path=)
        rescue StandardError
          model.active_path = nil rescue nil
        end
        if operation_started
          model.abort_operation rescue nil
          operation_started = false
        end
        restore_active_view_state(original_view, model) if original_view
        layer_visibility.each do |layer, visible|
          layer.visible = visible if layer
        rescue StandardError
          nil
        end
        restore_soft_thumbnail_render_options!(render_options, model)
        model.shadow_info['DisplayShadows'] = shadow_visible unless shadow_visible.nil? rescue nil
        begin
          model.selection.clear
          original_selection.each { |entity| model.selection.add(entity) if entity && entity.valid? }
        rescue StandardError
          nil
        end
        cleanup_soft_thumbnail_definitions!(model, definition_ids)
        File.delete(temp_file) if File.file?(temp_file)
        @soft_thumbnail_rendering = false
        end_soft_heavy_interaction(:thumbnail)
      end
      ok
    rescue StandardError => e
      log_exception("统一生成软装模型缩略图失败：#{path}", e)
      false
    ensure
      @soft_thumbnail_rendering = false
      end_soft_heavy_interaction(:thumbnail) if (@soft_heavy_interactions || {})[:thumbnail].to_i.positive?
      File.delete(temp_file) if defined?(temp_file) && temp_file && File.file?(temp_file)
    end

    def ensure_soft_model_thumbnail(path, root = soft_library_root, force: false)
      return '' unless File.file?(path)
      ensure_soft_library_structure!(root)
      thumb = soft_model_thumbnail_path(path, root)
      unless !force && soft_thumbnail_current?(path, thumb, root)
        File.delete(thumb) if File.file?(thumb)
        return '' unless extract_soft_model_embedded_thumbnail(path, thumb, root)
      end
      File.file?(thumb) ? thumb : ''
    rescue StandardError => e
      log_exception("读取软装源模型缩略图失败：#{path}", e)
      ''
    end

    def rebuild_soft_library_identity_maps!(cache = @soft_library_cache, log_conflicts: false)
      return false unless cache.is_a?(Hash)
      groups = Hash.new { |hash, key| hash[key] = [] }
      Array(cache[:items]).each do |item|
        next unless item.is_a?(Hash)
        id = item['id'].to_s.strip
        groups[id] << item unless id.empty?
      end
      by_id = {}
      conflicts = {}
      groups.each do |id, rows|
        if rows.length == 1
          by_id[id] = rows.first
        else
          conflicts[id] = rows
        end
      end
      cache[:by_id] = by_id
      cache[:by_id_conflicts] = conflicts

      if log_conflicts && !conflicts.empty?
        signature = conflicts.keys.sort.join('|')
        if @soft_library_identity_conflict_signature.to_s != signature
          details = conflicts.map do |id, rows|
            names = rows.map { |row| row['name'].to_s }.reject(&:empty?).uniq.join(' / ')
            "#{id}=#{names}"
          end.join('；')
          log("软装模型库身份冲突：#{conflicts.length} 个 model_id 对应多个当前模型；已禁用按 ID 猜测替换。#{details}")
          @soft_library_identity_conflict_signature = signature
        end
      end
      true
    rescue StandardError => e
      log_exception('重建软装模型库身份索引失败', e)
      false
    end

    def soft_library_id_conflict_items(model_id, cache = @soft_library_cache)
      return [] unless cache.is_a?(Hash)
      conflicts = cache[:by_id_conflicts]
      unless conflicts.is_a?(Hash)
        rebuild_soft_library_identity_maps!(cache)
        conflicts = cache[:by_id_conflicts]
      end
      Array(conflicts && conflicts[model_id.to_s.strip]).select { |item| item.is_a?(Hash) }
    rescue StandardError
      []
    end

    def soft_library_id_ambiguous?(model_id, cache = @soft_library_cache)
      soft_library_id_conflict_items(model_id, cache).length > 1
    rescue StandardError
      false
    end

    def hydrate_soft_library_cache!(root, items, verify_thumbnails: true)
      list = Array(items).select { |item| item.is_a?(Hash) }.map(&:dup)
      list.each do |item|
        source = item['path'].to_s
        if verify_thumbnails
          thumb = soft_model_thumbnail_path(source, root)
          ready = soft_thumbnail_current?(source, thumb, root)
          item['thumbnail_path'] = ready ? thumb : ''
          item['thumbnail_url'] = ready ? soft_thumbnail_url(thumb) : ''
          item['thumbnail_ready'] = ready
        else
          # 启动预热优先相信上一次持久目录缓存，不逐卡片访问源 SKP/NAS。
          # 后续用户主动刷新或单卡缩略图请求会重新验证对应文件。
          thumb = item['thumbnail_path'].to_s
          if thumb.empty? && item['thumbnail_ready'] == true
            thumb = soft_model_thumbnail_path(source, root)
            item['thumbnail_path'] = thumb
          end
          item['thumbnail_url'] = local_file_url(thumb) if item['thumbnail_url'].to_s.empty? && !thumb.empty?
        end
      end
      @soft_library_cache = { root: root, items: list, by_id: {}, by_id_conflicts: {}, warmed_at: monotonic_time }
      rebuild_soft_library_identity_maps!(@soft_library_cache, log_conflicts: true)
      list
    end

    def read_soft_library_catalog(root = soft_library_root)
      path = soft_library_catalog_path(root)
      return nil if path.to_s.empty? || !File.file?(path)
      data = JSON.parse(File.read(path, encoding: 'UTF-8'))
      return nil unless data.is_a?(Hash) && data['schema'].to_i == SOFT_LIBRARY_CATALOG_SCHEMA
      return nil unless normalize_soft_library_key(data['root']) == normalize_soft_library_key(root)
      organized_root = soft_library_organized_dir(root)
      return nil unless normalize_soft_library_key(data['organized_root']) == normalize_soft_library_key(organized_root)
      items = data['items']
      return nil unless items.is_a?(Array)
      # 目录缓存只允许恢复最终已整理树中的卡片。这一步只比较字符串，
      # 不对 NAS 上每个 SKP 执行 File.file?，保持二次打开秒开。
      items = items.select do |item|
        item.is_a?(Hash) && soft_library_path_inside?(item['path'].to_s, organized_root)
      end
      # 目录缓存追求秒开，外包盒缓存则写在模型索引中。读取目录时只合并两个
      # 小字段，不递归扫描文件，也不让旧目录缓存挡住后来生成的快速代理数据。
      records = read_soft_library_index(root)['models'].to_h
      items.each do |item|
        next unless item.is_a?(Hash)
        metadata = records[normalize_soft_library_key(item['path'])]
        next unless metadata.is_a?(Hash)
        item['bounds_values'] = Array(metadata['bounds_values']).map(&:to_f) if soft_bounds_values_valid?(metadata['bounds_values'])
        item['bounds_source_signature'] = metadata['bounds_source_signature'].to_s
        if metadata.key?('planar_reference') || metadata.key?('proxy_passthrough') || metadata.key?('bounds_values')
          planar = soft_metadata_planar_reference?(metadata)
          item['planar_reference'] = planar
          item['proxy_passthrough'] = planar
        end
        %w[name manufacturer price contact material_description remark category subcategory updated_at].each do |field|
          item[field] = metadata[field].to_s if metadata.key?(field)
        end
        item['extra_fields'] = metadata['extra_fields'].dup if metadata['extra_fields'].is_a?(Hash)
        normalize_soft_library_item_category!(item, root, metadata)
      end
      # 即使某条旧目录缓存没有对应索引记录，也按真实路径重新计算逻辑文件夹，
      # 这样升级后无需手动“刷新目录”即可立即合并历史分类。
      items.each { |item| normalize_soft_library_item_category!(item, root, nil) if item.is_a?(Hash) }
      items
    rescue StandardError
      nil
    end

    def write_soft_library_catalog!(items, root = soft_library_root)
      path = soft_library_catalog_path(root)
      return false if path.to_s.empty?
      snapshot = begin
        Marshal.load(Marshal.dump(Array(items)))
      rescue StandardError
        JSON.parse(JSON.generate(Array(items)))
      end
      payload = {
        'schema' => SOFT_LIBRARY_CATALOG_SCHEMA,
        'root' => FastPath.expand(root.to_s),
        'organized_root' => FastPath.expand(soft_library_organized_dir(root).to_s),
        'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S'),
        'items' => snapshot
      }
      enqueue_background_io_task(
        'json_write', key: "soft_library_catalog|#{normalize_soft_library_key(root)}",
        data: { path: path, payload: payload }, label: '软装模型库目录缓存'
      )
    rescue StandardError => e
      log_exception('写入软装目录缓存失败', e)
      false
    end

    def persist_soft_library_cache!
      cache = @soft_library_cache
      return false unless cache.is_a?(Hash) && cache[:root]
      write_soft_library_catalog!(cache[:items], cache[:root])
    end

    # 模型文件发生重命名/跨分类移动后，旧目录缓存中的 path、filename、folder 都已失效。
    # 只清 Ruby 内存缓存不够：下次打开模型库仍可能从“目录缓存.json”复活旧路径。
    # 因此路径级变更必须同时作废持久目录缓存，让下一次打开重新扫描真实文件树。
    def invalidate_soft_library_catalog_cache!(root = soft_library_root)
      @soft_library_cache = nil
      path = soft_library_catalog_path(root)
      File.delete(path) if !path.to_s.empty? && File.file?(path)
      true
    rescue StandardError => e
      log_exception('作废软装目录缓存失败', e)
      @soft_library_cache = nil
      false
    end

    def soft_library_path_inside?(path, directory)
      return false if path.to_s.empty? || directory.to_s.empty?
      path_key = normalize_soft_library_key(FastPath.expand(path.to_s))
      dir_key = normalize_soft_library_key(FastPath.expand(directory.to_s))
      path_key == dir_key || path_key.start_with?("#{dir_key}/")
    rescue StandardError
      false
    end

    # #1/#2 是清单中用来区分同组件不同尺寸的显示序号，不应继续
    # 传播到物理库文件名。真正的同名不同模型仍由目标路径冲突规则
    # 赋予独立名称，但同一 stable model_id 在库中只保留一份。
    def soft_library_storage_model_name(value)
      safe_soft_library_filename(value).sub(/#\d+\z/, '')
    rescue StandardError
      value.to_s.sub(/#\d+\z/, '')
    end

    def soft_library_duplicate_archive_path(source_path, root = soft_library_root)
      source = FastPath.expand(source_path.to_s)
      folder = File.join(soft_library_trash_dir(root), '重复模型归档', Time.now.strftime('%Y%m%d'))
      FileUtils.mkdir_p(folder)
      basename = File.basename(source, File.extname(source))
      extension = File.extname(source)
      candidate = File.join(folder, "#{basename}#{extension}")
      return candidate unless File.exist?(candidate)
      index = 1
      loop do
        candidate = File.join(folder, "#{basename}_#{index}#{extension}")
        return candidate unless File.exist?(candidate)
        index += 1
      end
    end

    def prune_empty_soft_legacy_directories!(roots)
      Array(roots).each do |root|
        next unless Dir.exist?(root)
        directories = Dir.glob(File.join(root, '**', '*'), File::FNM_DOTMATCH)
                         .select { |path| Dir.exist?(path) }
                         .reject { |path| %w[. ..].include?(File.basename(path)) }
                         .sort_by { |path| -path.count('/\\') }
        directories.each { |path| Dir.rmdir(path) if Dir.exist?(path) && Dir.children(path).empty? }
        Dir.rmdir(root) if Dir.exist?(root) && Dir.children(root).empty?
      rescue StandardError
        nil
      end
      true
    rescue StandardError
      false
    end

    # 旧版的“已入库整理模型库”本身就是用户已确认的库，因此升级时
    # 只扫描这些明确的旧整理目录，不再递归整个 ADR 共享根目录。
    # 迁移采用移动而非复制；同 stable model_id 的多份文件将放入可恢复
    # 的回收站归档，最终库中只保留一份。
    def migrate_legacy_soft_library_organized_tree!(root = soft_library_root)
      legacy_roots = soft_library_legacy_organized_dirs(root).select { |path| Dir.exist?(path) }
      return { moved: 0, archived: 0 } if legacy_roots.empty?

      files = legacy_roots.flat_map do |directory|
        Dir.glob(File.join(directory, '**', '*.skp'), File::FNM_CASEFOLD)
      end.reject { |path| soft_library_path_inside?(path, soft_library_manager_dir(root)) }
         .uniq { |path| normalize_soft_library_key(path) }
      return { moved: 0, archived: 0 } if files.empty?

      index = read_soft_library_index(root)
      records = index['models'].is_a?(Hash) ? index['models'] : {}
      organized_root = soft_library_organized_dir(root)
      canonical_by_id = {}
      records.each do |record_path, record|
        next unless record.is_a?(Hash) && File.file?(record_path.to_s)
        next unless soft_library_path_inside?(record_path, organized_root)
        stable_id = record['model_id'].to_s.strip
        canonical_by_id[stable_id] ||= FastPath.expand(record_path.to_s) unless stable_id.empty?
      end

      moved = 0
      archived = 0
      primary_relocations = {}
      reference_relocations = {}
      files.sort_by { |path| normalize_soft_library_key(path) }.each do |source|
        source = FastPath.expand(source)
        source_key = normalize_soft_library_key(source)
        metadata = default_soft_model_metadata(source)
        metadata.merge!(read_soft_model_sidecar(source))
        metadata.merge!(records[source_key]) if records[source_key].is_a?(Hash)
        stable_id = metadata['model_id'].to_s.strip
        stable_id = soft_model_id_for_path(source) if stable_id.empty?
        model_name = metadata['name'].to_s.strip
        model_name = File.basename(source, File.extname(source)) if model_name.empty?
        category = soft_library_canonical_category(metadata, source, root, model_name)
        category = soft_library_canonical_top_category(category)
        subcategory = soft_library_canonical_subcategory(metadata, source, root, category, model_name)
        subcategory = safe_soft_library_subcategory_name(subcategory, category)
        model_name = soft_library_model_name_without_category(model_name, category)
        model_name = soft_library_model_name_without_category(model_name, subcategory)
        model_name = soft_library_storage_model_name(model_name)

        canonical = canonical_by_id[stable_id]
        if canonical && File.file?(canonical)
          archive_path = soft_library_duplicate_archive_path(source, root)
          move_soft_library_file_to_path!(source, archive_path, root)
          records.delete(source_key)
          reference_relocations[source_key] = canonical
          archived += 1
          next
        end

        destination_dir = File.join(organized_root, category, subcategory)
        FileUtils.mkdir_p(destination_dir)
        target = File.join(destination_dir, "#{model_name}.skp")
        if File.file?(target)
          target_key = normalize_soft_library_key(target)
          target_record = records[target_key].is_a?(Hash) ? records[target_key] : read_soft_model_sidecar(target)
          if target_record.is_a?(Hash) && target_record['model_id'].to_s == stable_id
            archive_path = soft_library_duplicate_archive_path(source, root)
            move_soft_library_file_to_path!(source, archive_path, root)
            records.delete(source_key)
            canonical_by_id[stable_id] = target
            reference_relocations[source_key] = target
            archived += 1
            next
          end
          target = unique_organized_model_path(destination_dir, model_name)
          model_name = File.basename(target, File.extname(target))
        end

        moved_path = move_soft_library_file_to_path!(source, target, root)
        moved_key = normalize_soft_library_key(moved_path)
        record = records.delete(source_key)
        record = metadata unless record.is_a?(Hash)
        record = record.dup
        record['model_id'] = stable_id
        record['name'] = model_name
        record['category'] = category
        record['subcategory'] = subcategory
        record['organized'] = true
        record['organized_copy'] = moved_path
        record['source_original'] = ''
        record['organized_relative_dir'] = [category, subcategory].join('/')
        record['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        records[moved_key] = (records[moved_key].is_a?(Hash) ? records[moved_key] : {}).merge(record)
        canonical_by_id[stable_id] = moved_path
        primary_relocations[source_key] = moved_path
        reference_relocations[source_key] = moved_path
        write_json_atomic(soft_model_sidecar_path(moved_path), records[moved_key].merge('schema' => SOFT_LIBRARY_SCHEMA))
        moved += 1
      end

      records.each_value do |record|
        next unless record.is_a?(Hash)
        %w[organized_copy source_original proxy_path].each do |field|
          old_value = record[field].to_s
          replacement = reference_relocations[normalize_soft_library_key(old_value)] unless old_value.empty?
          record[field] = replacement if replacement
        end
      end
      index['models'] = records
      write_soft_library_index!(index, root)
      rewrite_soft_thumbnail_meta_paths!(primary_relocations, root) unless primary_relocations.empty?
      prune_empty_soft_legacy_directories!(legacy_roots)
      invalidate_soft_library_catalog_cache!(root)
      log("旧软装整理库迁移完成：移动 #{moved} / 重复归档 #{archived} / 目标=#{organized_root}")
      { moved: moved, archived: archived }
    rescue StandardError => e
      log_exception('迁移旧软装整理库失败', e)
      begin
        if defined?(index) && index.is_a?(Hash) && defined?(records) && records.is_a?(Hash)
          index['models'] = records
          write_soft_library_index!(index, root)
          invalidate_soft_library_catalog_cache!(root)
        end
      rescue StandardError => persist_error
        log_exception('保存软装整理库局部迁移结果失败', persist_error)
      end
      { moved: 0, archived: 0, error: e.message.to_s }
    end

    def deduplicate_soft_library_organized_files!(files, root = soft_library_root)
      list = Array(files).map { |path| FastPath.expand(path.to_s) }
      return list if list.length < 2
      index = read_soft_library_index(root)
      records = index['models'].is_a?(Hash) ? index['models'] : {}
      groups = Hash.new { |hash, key| hash[key] = [] }
      list.each do |path|
        record = records[normalize_soft_library_key(path)]
        stable_id = record.is_a?(Hash) ? record['model_id'].to_s.strip : ''
        stable_id = soft_model_id_for_path(path) if stable_id.empty?
        groups[stable_id] << path
      end
      duplicates = groups.values.select { |paths| paths.length > 1 }
      return list if duplicates.empty?

      removed = {}
      duplicates.each do |paths|
        canonical = paths.sort_by do |path|
          basename = File.basename(path, File.extname(path))
          [basename.match?(/#\d+\z/) ? 1 : 0, path.count('/\\'), normalize_soft_library_key(path)]
        end.first
        paths.each do |duplicate|
          next if normalize_soft_library_key(duplicate) == normalize_soft_library_key(canonical)
          old_key = normalize_soft_library_key(duplicate)
          archive_soft_library_duplicate!(duplicate, canonical, index, root)
          removed[old_key] = true
        end
      end
      write_soft_library_index!(index, root)
      invalidate_soft_library_catalog_cache!(root)
      log("已整理模型库去重：归档 #{removed.length} 个同 model_id 副本")
      list.reject { |path| removed[normalize_soft_library_key(path)] }
    rescue StandardError => e
      log_exception('已整理模型库去重失败', e)
      Array(files)
    end

    # 历史模型库曾把“分类-模型名”整串当作物理文件夹名，例如：
    # “摆件-茶杯 / 摆件-茶壶 / 摆件-花艺”。这些目录一旦已经被项目实例引用，
    # 不能为了整理 UI 直接搬文件：软装 model_id、source_path、索引 key 与代理缓存
    # 都和真实路径绑定。这里建立“逻辑分类层”，只统一显示/清单分类，不改真实文件路径。
    # 规则服从当前入库约定：第一个横线（兼容全角/长横线）之前就是分类。
    def soft_library_category_prefix(value)
      text = value.to_s.strip.gsub(/\s+/, ' ')
      return '' if text.empty?
      match = /\A(.+?)[\-－—–﹣‐‑‒](.+)\z/.match(text)
      text = match[1].to_s.strip if match && !match[1].to_s.strip.empty?
      text.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ').strip[0, 48].to_s
    rescue StandardError
      ''
    end

    def soft_library_canonical_top_category(value)
      source = value.to_s.strip.sub(/\A软装[\-－—–﹣‐‑‒]+/, '')
      raw = soft_library_category_prefix(source)
      return '其他' if raw.empty?
      return raw if SOFT_LIBRARY_CATEGORIES.include?(raw)
      direct = SOFT_LIBRARY_CATEGORY_ALIASES[raw]
      return direct if direct
      keyword = SOFT_LIBRARY_CATEGORY_ALIASES.keys.sort_by { |item| -item.length }.find do |item|
        !item.empty? && raw.include?(item)
      end
      SOFT_LIBRARY_CATEGORY_ALIASES[keyword].to_s.empty? ? '其他' : SOFT_LIBRARY_CATEGORY_ALIASES[keyword]
    rescue StandardError
      '其他'
    end

    def soft_library_default_subcategory(category)
      top = soft_library_canonical_top_category(category)
      defaults = {
        '家具' => '其他家具', '灯具' => '其他灯具', '窗帘' => '其他窗帘',
        '地毯' => '其他地毯', '挂画' => '其他挂画', '摆件' => '其他摆件', '其他' => '其他'
      }
      defaults[top] || '其他'
    end

    def safe_soft_library_subcategory_name(value, category = '其他')
      text = value.to_s.strip.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ')
      text = text.gsub(/\A\.+|\.+\z/, '').strip
      text = soft_library_default_subcategory(category) if text.empty?
      text[0, 48]
    rescue StandardError
      soft_library_default_subcategory(category)
    end

    def soft_library_canonical_subcategory(metadata = nil, path = '', root = soft_library_root, category = '', fallback_name = '')
      data = metadata.is_a?(Hash) ? metadata : {}
      top = soft_library_canonical_top_category(category.to_s.empty? ? data['category'] : category)
      explicit = data['subcategory'].to_s.strip
      return safe_soft_library_subcategory_name(explicit, top) unless explicit.empty?

      category_text = data['category'].to_s.strip.sub(/\A软装[\-－—–﹣‐‑‒]+/, '')
      category_parts = category_text.split(/[\-－—–﹣‐‑‒]+/).map(&:strip).reject(&:empty?)
      if category_parts.length > 1 && soft_library_canonical_top_category(category_parts.first) == top
        return safe_soft_library_subcategory_name(category_parts[1], top)
      end

      relative_dir = data['organized_relative_dir'].to_s.tr('\\', '/').sub(%r{^/+}, '').sub(%r{/+$}, '')
      unless relative_dir.empty?
        parts = relative_dir.split('/').reject { |part| part.to_s.empty? || soft_library_organized_folder_name?(part) }
        return safe_soft_library_subcategory_name(parts[1], top) if parts.length > 1
        legacy = /\A(.+?)[\-－—–﹣‐‑‒](.+)\z/.match(parts.first.to_s)
        if legacy && soft_library_canonical_top_category(legacy[1]) == top
          return safe_soft_library_subcategory_name(legacy[2], top)
        end
      end

      explicit_category = soft_library_category_prefix(category_text)
      if !explicit_category.empty? && !SOFT_LIBRARY_CATEGORIES.include?(explicit_category) &&
         soft_library_canonical_top_category(explicit_category) == top
        return safe_soft_library_subcategory_name(explicit_category, top)
      end

      unless path.to_s.empty? || root.to_s.empty?
        begin
          organized_root = FastPath.expand(soft_library_organized_dir(root))
          expanded = FastPath.expand(path.to_s)
          if normalize_soft_library_key(expanded).start_with?("#{normalize_soft_library_key(organized_root)}/")
            relative = Pathname.new(expanded).relative_path_from(Pathname.new(organized_root)).to_s.tr('\\', '/')
            folders = File.dirname(relative).split('/').reject { |part| part.to_s.empty? || part == '.' }
            return safe_soft_library_subcategory_name(folders[1], top) if folders.length > 1
            legacy = /\A(.+?)[\-－—–﹣‐‑‒](.+)\z/.match(folders.first.to_s)
            if legacy && soft_library_canonical_top_category(legacy[1]) == top
              return safe_soft_library_subcategory_name(legacy[2], top)
            end
          end

          relative = Pathname.new(expanded).relative_path_from(Pathname.new(FastPath.expand(root.to_s))).to_s.tr('\\', '/')
          folders = File.dirname(relative).split('/').reject do |part|
            part.to_s.empty? || part == '.' || soft_library_organized_folder_name?(part) ||
              part == SOFT_LIBRARY_MANAGER_DIR || part == SOFT_LIBRARY_CONTAINER_DIR
          end
          unless folders.empty?
            folder = folders.last.to_s.strip
            folder_parts = folder.split(/[\-－—–﹣‐‑‒]+/).map(&:strip).reject(&:empty?)
            if folder_parts.length > 1 && soft_library_canonical_top_category(folder_parts.first) == top
              return safe_soft_library_subcategory_name(folder_parts[1], top)
            end
            if !SOFT_LIBRARY_CATEGORIES.include?(folder) && soft_library_canonical_top_category(folder) == top
              return safe_soft_library_subcategory_name(folder, top)
            end
          end
        rescue StandardError
          nil
        end
      end

      name = fallback_name.to_s.strip
      name = data['name'].to_s.strip if name.empty?
      name = name.sub(/\A软装[\-－—–﹣‐‑‒]+/, '')
      name_parts = name.split(/[\-－—–﹣‐‑‒]+/).map(&:strip).reject(&:empty?)
      if name_parts.length > 1 && soft_library_canonical_top_category(name_parts.first) == top
        candidate = name_parts[1].to_s.sub(/[（(].*\z/, '').strip
        return safe_soft_library_subcategory_name(candidate, top) if Array(SOFT_LIBRARY_SUBCATEGORIES[top]).include?(candidate)
      end
      prefix = soft_library_category_prefix(name)
      if !prefix.empty? && !SOFT_LIBRARY_CATEGORIES.include?(prefix) && soft_library_canonical_top_category(prefix) == top
        return safe_soft_library_subcategory_name(prefix, top)
      end
      soft_library_default_subcategory(top)
    rescue StandardError
      soft_library_default_subcategory(category)
    end

