    def xlsx_xml_escape(value)
      value.to_s.encode('UTF-8', invalid: :replace, undef: :replace, replace: '�')
           .gsub(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\uFFFE\uFFFF]/, '')
           .gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;').gsub('"', '&quot;').gsub("'", '&apos;')
    end

    def xlsx_column_name(index)
      value = index.to_i + 1
      name = +''
      while value.positive?
        value -= 1
        name.prepend((65 + (value % 26)).chr)
        value /= 26
      end
      name
    end

    def xlsx_sheet_name(value, used)
      base = value.to_s.gsub(/[\\\/?*\[\]:]/, '_').strip
      base = '清单' if base.empty?
      base = base[0, 31]
      candidate = base
      index = 2
      while used[candidate.downcase]
        suffix = "_#{index}"
        candidate = "#{base[0, 31 - suffix.length]}#{suffix}"
        index += 1
      end
      used[candidate.downcase] = true
      candidate
    end

    def xlsx_image_cell?(value)
      value.is_a?(Hash) && value.key?('image_path')
    end

    def xlsx_image_file_type(path, strict: false)
      if strict
        # v0.13.6.188：严格模式改为结构校验（image_media.rb）。旧版要求“最后 2 字节必须是
        # FFD9 / 最后 12 字节必须是 IEND”，把末尾带附加数据的正常照片当成损坏：实物图
        # 导入失败、导出时静默缺图。现在 SOI→SOF→SOS→EOI / IHDR→IDAT→IEND 完整即可。
        report = image_media_embeddable_info(path)
        return report ? { extension: report[:extension], content_type: report[:content_type] } : nil
      end
      return nil unless File.file?(path) && File.size(path).positive?
      header = File.open(path, 'rb') { |file| file.read(16).to_s.b }
      if header.start_with?("\x89PNG\r\n\x1A\n".b)
        { extension: 'png', content_type: 'image/png' }
      elsif header.start_with?("\xFF\xD8".b)
        { extension: 'jpg', content_type: 'image/jpeg' }
      end
    rescue StandardError
      nil
    end

    def xlsx_image_dimensions(path)
      return nil unless File.file?(path) && File.size(path).positive?
      File.open(path, 'rb') do |file|
        signature = file.read(24).to_s.b
        if signature.start_with?("\x89PNG\r\n\x1A\n".b) && signature.bytesize >= 24
          width, height = signature.byteslice(16, 8).unpack('N2')
          return [width, height] if width.to_i.positive? && height.to_i.positive?
        end
        file.rewind
        return nil unless file.read(2).to_s.b == "\xFF\xD8".b
        sof_markers = [0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF]
        loop do
          byte = file.read(1)
          break unless byte
          next unless byte.getbyte(0) == 0xFF
          marker_byte = file.read(1)
          break unless marker_byte
          marker = marker_byte.getbyte(0)
          while marker == 0xFF
            marker_byte = file.read(1)
            break unless marker_byte
            marker = marker_byte.getbyte(0)
          end
          break unless marker
          next if marker == 0xD8 || marker == 0x01
          break if marker == 0xD9 || marker == 0xDA
          length_raw = file.read(2)
          break unless length_raw && length_raw.bytesize == 2
          length = length_raw.unpack1('n').to_i
          break if length < 2
          if sof_markers.include?(marker)
            data = file.read(5)
            break unless data && data.bytesize == 5
            _precision, height, width = data.unpack('Cnn')
            return [width, height] if width.to_i.positive? && height.to_i.positive?
            break
          end
          file.seek(length - 2, IO::SEEK_CUR)
        end
      end
      nil
    rescue StandardError
      nil
    end

    def xlsx_cell_xml(value, row_index, column_index, style = 0)
      reference = "#{xlsx_column_name(column_index)}#{row_index}"
      style_attr = style.to_i.positive? ? " s=\"#{style.to_i}\"" : ''
      if xlsx_image_cell?(value)
        "<c r=\"#{reference}\"#{style_attr} t=\"inlineStr\"><is><t></t></is></c>"
      elsif value.is_a?(Numeric)
        if value.respond_to?(:finite?) && !value.finite?
          "<c r=\"#{reference}\"#{style_attr} t=\"inlineStr\"><is><t></t></is></c>"
        else
          "<c r=\"#{reference}\"#{style_attr} t=\"n\"><v>#{value}</v></c>"
        end
      else
        text = xlsx_xml_escape(value)
        "<c r=\"#{reference}\"#{style_attr} t=\"inlineStr\"><is><t xml:space=\"preserve\">#{text}</t></is></c>"
      end
    end

    def xlsx_sheet_images(rows)
      images = []
      Array(rows).each_with_index do |row, body_index|
        Array(row).each_with_index do |value, column_index|
          next unless xlsx_image_cell?(value)
          path = value['image_path'].to_s
          # SketchUp 2024~2026 的原生缩略图经常“文件名为 .png、实际负载为 JPEG”。
          # 旧导出只接受 PNG 签名，因此网页能显示、Excel 却静默缺图。这里按二进制
          # 内容识别真实媒体类型，并让 OOXML 文件名/Content-Type 与内容一致。
          image_type = xlsx_image_file_type(path, strict: true)
          next unless image_type
          # Drawing anchors are zero-based. Row 0 is the merged title, row 1 is the header.
          dimensions = xlsx_image_dimensions(path)
          images << {
            row: body_index + 2, column: column_index, path: path, image_type: image_type,
            role: value['image_role'].to_s, pixel_width: dimensions && dimensions[0], pixel_height: dimensions && dimensions[1]
          }
        end
      end
      images
    rescue StandardError
      []
    end

    # v0.13.7.1：Excel 排版。
    # - 所有单元格默认细边框；表头灰底；标题行加大加粗。
    # - 每个空间一段，交替淡色底（相邻空间颜色一定不同）；空间列字号略大、加粗。
    # - 正文行高统一（有图 66pt / 含实物图 84pt / 无图 30pt），不再因为缺图或图片类型而参差。
    # - 图片以 twoCellAnchor editAs="twoCell" 锚定在单元格内（“随单元格移动和缩放”），
    #   WPS 与 Excel 都能正常显示，排序/筛选/调行高时图片跟着单元格走。
    XLSX_SPACE_FILLS = %w[FFEAF2FB FFFDF0E3 FFE8F5EA FFF2ECF8 FFFCF6DA FFE5F4F4 FFFBEAF0].freeze
    XLSX_LEFT_ALIGNED_HEADER = /备注|材质|描述|要求|面料|说明/.freeze
    XLSX_STYLE_DEFAULT = 0
    XLSX_STYLE_TITLE = 1
    XLSX_STYLE_HEADER = 2
    XLSX_STYLE_BODY_BASE = 3 # 3=居中 4=左对齐 5=空间列；之后每种底色各 3 个

    def xlsx_body_style(group, kind)
      offset = { center: 0, left: 1, space: 2 }.fetch(kind, 0)
      return XLSX_STYLE_BODY_BASE + offset if group.nil?
      XLSX_STYLE_BODY_BASE + 3 + ((group.to_i % XLSX_SPACE_FILLS.length) * 3) + offset
    end

    def xlsx_styles_xml
      font = lambda do |size, bold = false|
        "<font>#{bold ? '<b/>' : ''}<sz val=\"#{size}\"/><name val=\"微软雅黑\"/><family val=\"2\"/><charset val=\"134\"/></font>"
      end
      fonts = [font.call(10), font.call(16, true), font.call(10, true), font.call(11, true)]
      fills = ['<fill><patternFill patternType="none"/></fill>', '<fill><patternFill patternType="gray125"/></fill>',
               '<fill><patternFill patternType="solid"><fgColor rgb="FFE4E8EF"/><bgColor indexed="64"/></patternFill></fill>']
      XLSX_SPACE_FILLS.each do |rgb|
        fills << "<fill><patternFill patternType=\"solid\"><fgColor rgb=\"#{rgb}\"/><bgColor indexed=\"64\"/></patternFill></fill>"
      end
      side = ->(name) { "<#{name} style=\"thin\"><color rgb=\"FFB8BFCC\"/></#{name}>" }
      borders = ['<border/>', "<border>#{side.call('left')}#{side.call('right')}#{side.call('top')}#{side.call('bottom')}<diagonal/></border>"]
      xf = lambda do |font_id, fill_id, horizontal|
        "<xf numFmtId=\"0\" fontId=\"#{font_id}\" fillId=\"#{fill_id}\" borderId=\"1\" xfId=\"0\" applyFont=\"1\" applyFill=\"1\" applyBorder=\"1\" applyAlignment=\"1\"><alignment horizontal=\"#{horizontal}\" vertical=\"center\" wrapText=\"1\"/></xf>"
      end
      xfs = [xf.call(0, 0, 'general'), xf.call(1, 0, 'center'), xf.call(2, 2, 'center'),
             xf.call(0, 0, 'center'), xf.call(0, 0, 'left'), xf.call(3, 0, 'center')]
      XLSX_SPACE_FILLS.each_index do |index|
        fill_id = 3 + index
        xfs << xf.call(0, fill_id, 'center') << xf.call(0, fill_id, 'left') << xf.call(3, fill_id, 'center')
      end
      "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">" \
        "<fonts count=\"#{fonts.length}\">#{fonts.join}</fonts><fills count=\"#{fills.length}\">#{fills.join}</fills>" \
        "<borders count=\"#{borders.length}\">#{borders.join}</borders>" \
        '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>' \
        "<cellXfs count=\"#{xfs.length}\">#{xfs.join}</cellXfs>" \
        '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'
    end

    def xlsx_text_display_width(value)
      value.to_s.split(/\r?\n/).map { |line| line.each_char.sum { |char| char.ord < 0x2E80 ? 1.0 : 2.0 } }.max.to_f
    end

    def xlsx_image_header?(header)
      text = header.to_s
      %w[模型图片 产品图].include?(text) || text.start_with?('实物/细节图')
    end

    def xlsx_sheet_layout(headers, rows)
      body = Array(rows)
      image_rows = body.select { |row| Array(row).any? { |value| xlsx_image_cell?(value) } }
      supplemental = image_rows.any? { |row| Array(row).any? { |value| xlsx_image_cell?(value) && value['image_role'].to_s == 'supplemental' } }
      body_height = if supplemental
                      84.0
                    elsif !image_rows.empty? || Array(headers).any? { |header| xlsx_image_header?(header) }
                      66.0
                    else
                      30.0
                    end
      row_px = body_height * 96.0 / 72.0
      widths = Array(headers).each_index.map do |index|
        header = headers[index].to_s
        if xlsx_image_header?(header)
          ((row_px + 8.0) / 7.0).round(1)
        else
          longest = ([header] + body.map { |row| value = Array(row)[index]; xlsx_image_cell?(value) ? '' : value })
                    .map { |value| xlsx_text_display_width(value) }.max.to_f
          [[(longest * 1.05 + 3.0).round(1), 8.0].max, 34.0].min
        end
      end
      { widths: widths, body_height: body_height, row_px: row_px }
    end

    def xlsx_worksheet_xml(title, headers, rows, drawing_rel_id: nil, row_groups: nil, layout: nil)
      layout ||= xlsx_sheet_layout(headers, rows)
      groups = Array(row_groups)
      title_row = [title.to_s] + Array.new([headers.length - 1, 0].max, '')
      all_rows = [title_row, headers] + Array(rows)
      space_column = headers.index('空间区域')
      left_columns = headers.each_index.select { |index| headers[index].to_s.match?(XLSX_LEFT_ALIGNED_HEADER) }
      columns = layout[:widths].each_with_index.map do |width, index|
        "<col min=\"#{index + 1}\" max=\"#{index + 1}\" width=\"#{width}\" customWidth=\"1\"/>"
      end.join
      body_height = format('%.1f', layout[:body_height].to_f)
      row_xml = all_rows.each_with_index.map do |row, index|
        row_index = index + 1
        group = index > 1 ? groups[index - 2] : nil
        cells = Array(row).each_with_index.map do |value, column|
          style = if index.zero?
                    XLSX_STYLE_TITLE
                  elsif index == 1
                    XLSX_STYLE_HEADER
                  elsif column == space_column
                    xlsx_body_style(group, :space)
                  elsif left_columns.include?(column)
                    xlsx_body_style(group, :left)
                  else
                    xlsx_body_style(group, :center)
                  end
          xlsx_cell_xml(value, row_index, column, style)
        end.join
        height = index.zero? ? '36' : (index == 1 ? '30' : body_height)
        "<row r=\"#{row_index}\" ht=\"#{height}\" customHeight=\"1\">#{cells}</row>"
      end.join
      last_column = xlsx_column_name([headers.length - 1, 0].max)
      last_cell = "#{last_column}#{[all_rows.length, 1].max}"
      rel_ns = drawing_rel_id ? ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"' : ''
      drawing = drawing_rel_id ? "<drawing r:id=\"#{drawing_rel_id}\"/>" : ''
      <<~XML.delete("\n")
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"#{rel_ns}>
          <sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>
          <dimension ref="A1:#{last_cell}"/>
          <sheetViews><sheetView workbookViewId="0"><pane ySplit="2" topLeftCell="A3" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>
          <sheetFormatPr defaultRowHeight="15"/><cols>#{columns}</cols><sheetData>#{row_xml}</sheetData>
          <autoFilter ref="A2:#{last_cell}"/><mergeCells count="1"><mergeCell ref="A1:#{last_column}1"/></mergeCells>
          <printOptions horizontalCentered="1"/>
          <pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/>
          <pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>#{drawing}
        </worksheet>
      XML
    end

    def xlsx_drawing_xml(images, layout = nil)
      widths = layout ? Array(layout[:widths]) : []
      row_px = layout ? layout[:row_px].to_f : 64.0
      anchors = Array(images).each_with_index.map do |image, index|
        col = image[:column].to_i
        row = image[:row].to_i
        rel_id = "rId#{index + 1}"
        pic_id = index + 1
        supplemental = image[:role].to_s == 'supplemental'
        # 列宽(字符) → 像素按保守的 7px/字符估算，保证图片始终落在单元格内部。
        col_px = widths[col] ? widths[col].to_f * 7.0 : (supplemental ? 98.0 : 77.0)
        box_px = [[col_px, row_px].min - 10.0, 16.0].max
        pixel_width = image[:pixel_width].to_f
        pixel_height = image[:pixel_height].to_f
        if pixel_width.positive? && pixel_height.positive?
          scale = [box_px / pixel_width, box_px / pixel_height].min
          display_width = [(pixel_width * scale).round, 8].max
          display_height = [(pixel_height * scale).round, 8].max
        else
          display_width = box_px.round
          display_height = box_px.round
        end
        offset_x = [((col_px - display_width) / 2.0).round, 0].max
        offset_y = [((row_px - display_height) / 2.0).round, 0].max
        emu = 9525
        label = supplemental ? "实物/细节图 #{pic_id}" : "模型图片 #{pic_id}"
        <<~XML.delete("\n")
          <xdr:twoCellAnchor editAs="twoCell">
          <xdr:from><xdr:col>#{col}</xdr:col><xdr:colOff>#{offset_x * emu}</xdr:colOff><xdr:row>#{row}</xdr:row><xdr:rowOff>#{offset_y * emu}</xdr:rowOff></xdr:from>
          <xdr:to><xdr:col>#{col}</xdr:col><xdr:colOff>#{(offset_x + display_width) * emu}</xdr:colOff><xdr:row>#{row}</xdr:row><xdr:rowOff>#{(offset_y + display_height) * emu}</xdr:rowOff></xdr:to>
          <xdr:pic><xdr:nvPicPr><xdr:cNvPr id="#{pic_id + 1}" name="#{xlsx_xml_escape(label)}"/><xdr:cNvPicPr><a:picLocks noChangeAspect="1"/></xdr:cNvPicPr></xdr:nvPicPr>
          <xdr:blipFill><a:blip r:embed="#{rel_id}"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill>
          <xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="#{display_width * emu}" cy="#{display_height * emu}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic>
          <xdr:clientData/></xdr:twoCellAnchor>
        XML
      end.join
      "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><xdr:wsDr xmlns:xdr=\"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">#{anchors}</xdr:wsDr>"
    end

    def xlsx_zip_time(time = Time.now)
      year = [[time.year, 1980].max, 2107].min
      dos_time = (time.hour << 11) | (time.min << 5) | (time.sec / 2)
      dos_date = ((year - 1980) << 9) | (time.month << 5) | time.day
      [dos_time, dos_date]
    end

    def write_stored_zip!(target, entries, progress: nil, progress_start: 62, progress_end: 90)
      central_parts = []
      dos_time, dos_date = xlsx_zip_time
      File.open(target, 'wb') do |file|
        total_entries = [entries.length, 1].max
        entries.each_with_index do |(name, content), entry_index|
          if progress
            pct = progress_start.to_f + (progress_end.to_f - progress_start.to_f) * entry_index.to_f / total_entries.to_f
            progress.call(pct.round, '写入 Excel 文件包', "#{entry_index + 1}/#{total_entries} · #{name}")
          end
          filename = name.to_s.encode('UTF-8')
          filename.force_encoding(Encoding::BINARY)
          source_path = content.is_a?(Hash) ? content[:file_path].to_s : ''
          data = nil
          if source_path.empty?
            raw = content.to_s
            data = raw.encoding == Encoding::BINARY ? raw : raw.encode('UTF-8')
            data = data.dup if data.frozen?
            data.force_encoding(Encoding::BINARY)
            size = data.bytesize
            crc = Zlib.crc32(data)
          else
            raise "Excel 媒体文件已失效：#{source_path}" unless File.file?(source_path)
            size = File.size(source_path)
            crc = 0
            File.open(source_path, 'rb') do |source|
              while (chunk = source.read(1024 * 1024))
                crc = Zlib.crc32(chunk, crc)
              end
            end
          end

          offset = file.pos
          local_header = [0x04034b50, 20, 0x0800, 0, dos_time, dos_date, crc, size, size, filename.bytesize, 0].pack('VvvvvvVVVvv')
          file.write(local_header)
          file.write(filename)
          if source_path.empty?
            file.write(data)
          else
            written = 0
            written_crc = 0
            File.open(source_path, 'rb') do |source|
              while (chunk = source.read(1024 * 1024))
                file.write(chunk)
                written += chunk.bytesize
                written_crc = Zlib.crc32(chunk, written_crc)
              end
            end
            raise "Excel 媒体文件写入期间发生变化：#{source_path}" unless written == size && written_crc == crc
          end
          central_header = [
            0x02014b50, 20, 20, 0x0800, 0, dos_time, dos_date,
            crc, size, size, filename.bytesize, 0, 0, 0, 0, 0, offset
          ].pack('VvvvvvvVVVvvvvvVV')
          central_parts << central_header << filename
        end
        central_offset = file.pos
        central_parts.each { |part| file.write(part) }
        central_size = file.pos - central_offset
        finish = [0x06054b50, 0, 0, entries.length, entries.length, central_size, central_offset, 0].pack('VvvvvVVv')
        file.write(finish)
        file.flush
        file.fsync rescue nil
      end
      true
    end

    def validate_xlsx_package_entries!(entries)
      keys = entries.keys.map(&:to_s)
      raise 'Excel 工作簿缺少 [Content_Types].xml。' unless keys.include?('[Content_Types].xml')
      raise 'Excel 工作簿缺少 workbook.xml。' unless keys.include?('xl/workbook.xml')
      entries.each do |name, content|
        next if content.is_a?(Hash)
        key = name.to_s
        next unless key.end_with?('.xml') || key.end_with?('.rels') || key == '[Content_Types].xml'
        raw = content.to_s.encode('UTF-8', invalid: :replace, undef: :replace, replace: '�')
        begin
          REXML::Document.new(raw)
        rescue StandardError => e
          raise "Excel XML 部件无效：#{key} · #{e.message}"
        end
        next unless key.end_with?('.rels')
        source_dir = if key == '_rels/.rels'
                       ''
                     elsif key.include?('/_rels/')
                       left, file = key.split('/_rels/', 2)
                       rel_source = file.sub(/\.rels\z/, '')
                       File.dirname(File.join(left, rel_source))
                     else
                       File.dirname(key)
                     end
        raw.scan(/<Relationship\b[^>]*>/i).each do |tag|
          next if tag.match?(/TargetMode\s*=\s*["']External["']/i)
          match = tag.match(/Target\s*=\s*["']([^"']+)["']/i)
          next unless match
          target = match[1].to_s
          next if target.empty? || target.start_with?('/')
          resolved = Pathname.new(source_dir.to_s.empty? ? target : File.join(source_dir, target)).cleanpath.to_s.tr('\\', '/')
          raise "Excel 关系目标缺失：#{key} -> #{target}" unless keys.include?(resolved)
        end
      end
      true
    end

    def validate_soft_schedule_xlsx_file!(path)
      raise 'Excel 文件不存在或为空。' unless File.file?(path) && File.size(path) >= 256
      local_signature = [0x04034b50].pack('V')
      eocd_signature = [0x06054b50].pack('V')
      File.open(path, 'rb') do |file|
        raise 'Excel ZIP 文件头无效。' unless file.read(4) == local_signature
        tail_size = [File.size(path), 65_557].min
        file.seek(-tail_size, IO::SEEK_END)
        tail = file.read(tail_size)
        position = tail.rindex(eocd_signature)
        raise 'Excel ZIP 中央目录不完整。' unless position
        record = tail.byteslice(position, 22)
        raise 'Excel ZIP 结束记录不完整。' unless record && record.bytesize == 22
        _signature, _disk, _start_disk, disk_entries, total_entries, central_size, central_offset, comment_length = record.unpack('VvvvvVVv')
        raise 'Excel ZIP 没有任何部件。' unless total_entries.to_i.positive? && disk_entries == total_entries
        raise 'Excel ZIP 中央目录范围无效。' unless central_size.to_i.positive? && central_offset.to_i.positive? &&
                                                    central_offset.to_i + central_size.to_i <= File.size(path) - 22 - comment_length.to_i
      end
      true
    end

    def write_soft_schedule_xlsx!(target, sheets, progress: nil)
      progress.call(54, '构建 Excel 工作簿', '准备工作表、样式与图片关系') if progress
      used = {}
      normalized = Array(sheets).map do |sheet|
        rows = sheet[:rows]
        [xlsx_sheet_name(sheet[:name], used), sheet[:title].to_s, sheet[:headers], rows, xlsx_sheet_images(rows),
         sheet[:row_groups], xlsx_sheet_layout(sheet[:headers], rows)]
      end
      sheet_overrides = normalized.each_index.map do |index|
        "<Override PartName=\"/xl/worksheets/sheet#{index + 1}.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>"
      end.join
      drawing_overrides = normalized.each_with_index.map do |sheet, index|
        next '' if sheet[4].empty?
        "<Override PartName=\"/xl/drawings/drawing#{index + 1}.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.drawing+xml\"/>"
      end.join
      workbook_sheets = normalized.each_with_index.map do |sheet, index|
        "<sheet name=\"#{xlsx_xml_escape(sheet[0])}\" sheetId=\"#{index + 1}\" r:id=\"rId#{index + 1}\"/>"
      end.join
      workbook_rels = normalized.each_index.map do |index|
        "<Relationship Id=\"rId#{index + 1}\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet#{index + 1}.xml\"/>"
      end.join
      # v0.13.7.1：每张表打印时重复标题+表头两行，并登记筛选区域（WPS/Excel 都识别）。
      defined_names = normalized.each_with_index.map do |sheet, index|
        quoted = "'#{sheet[0].to_s.gsub("'", "''")}'"
        last_column = xlsx_column_name([Array(sheet[2]).length - 1, 0].max)
        last_row = [Array(sheet[3]).length + 2, 2].max
        "<definedName name=\"_xlnm._FilterDatabase\" localSheetId=\"#{index}\" hidden=\"1\">#{xlsx_xml_escape(quoted)}!$A$2:$#{last_column}$#{last_row}</definedName>" \
          "<definedName name=\"_xlnm.Print_Titles\" localSheetId=\"#{index}\">#{xlsx_xml_escape(quoted)}!$1:$2</definedName>"
      end.join
      styles_id = normalized.length + 1
      created_at = Time.now.utc.strftime('%Y-%m-%dT%H:%M:%SZ')
      entries = {
        '[Content_Types].xml' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Default Extension=\"png\" ContentType=\"image/png\"/><Default Extension=\"jpg\" ContentType=\"image/jpeg\"/><Default Extension=\"jpeg\" ContentType=\"image/jpeg\"/><Override PartName=\"/docProps/core.xml\" ContentType=\"application/vnd.openxmlformats-package.core-properties+xml\"/><Override PartName=\"/docProps/app.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.extended-properties+xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>#{sheet_overrides}#{drawing_overrides}</Types>",
        '_rels/.rels' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties\" Target=\"docProps/core.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties\" Target=\"docProps/app.xml\"/></Relationships>",
        'docProps/core.xml' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><cp:coreProperties xmlns:cp=\"http://schemas.openxmlformats.org/package/2006/metadata/core-properties\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:dcterms=\"http://purl.org/dc/terms/\" xmlns:dcmitype=\"http://purl.org/dc/dcmitype/\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"><dc:creator>SU LinkHub</dc:creator><cp:lastModifiedBy>SU LinkHub</cp:lastModifiedBy><dcterms:created xsi:type=\"dcterms:W3CDTF\">#{created_at}</dcterms:created><dcterms:modified xsi:type=\"dcterms:W3CDTF\">#{created_at}</dcterms:modified></cp:coreProperties>",
        'docProps/app.xml' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Properties xmlns=\"http://schemas.openxmlformats.org/officeDocument/2006/extended-properties\" xmlns:vt=\"http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes\"><Application>SU LinkHub</Application><AppVersion>#{xlsx_xml_escape(EXTENSION_VERSION)}</AppVersion></Properties>",
        'xl/workbook.xml' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><bookViews><workbookView xWindow=\"0\" yWindow=\"0\" windowWidth=\"24000\" windowHeight=\"12000\"/></bookViews><sheets>#{workbook_sheets}</sheets><definedNames>#{defined_names}</definedNames><calcPr calcId=\"191029\"/></workbook>",
        'xl/_rels/workbook.xml.rels' => "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">#{workbook_rels}<Relationship Id=\"rId#{styles_id}\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>",
        'xl/styles.xml' => xlsx_styles_xml
      }

      media_index = 0
      media_by_path = {}
      normalized.each_with_index do |sheet, index|
        sheet_no = index + 1
        images = sheet[4]
        if images.empty?
          entries["xl/worksheets/sheet#{sheet_no}.xml"] = xlsx_worksheet_xml(sheet[1], sheet[2], sheet[3], row_groups: sheet[5], layout: sheet[6])
          next
        end

        entries["xl/worksheets/sheet#{sheet_no}.xml"] = xlsx_worksheet_xml(sheet[1], sheet[2], sheet[3], drawing_rel_id: 'rId1', row_groups: sheet[5], layout: sheet[6])
        entries["xl/worksheets/_rels/sheet#{sheet_no}.xml.rels"] = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing\" Target=\"../drawings/drawing#{sheet_no}.xml\"/></Relationships>"
        entries["xl/drawings/drawing#{sheet_no}.xml"] = xlsx_drawing_xml(images, sheet[6])
        image_rels = []
        images.each_with_index do |image, image_index|
          path_key = FastPath.expand(image[:path].to_s)
          image_type = image[:image_type].is_a?(Hash) ? image[:image_type] : xlsx_image_file_type(image[:path], strict: true)
          raise "写入 Excel 时缩略图已失效：#{image[:path]}" unless image_type
          media_key = [path_key, image_type[:extension].to_s].join('|')
          media_name = media_by_path[media_key]
          unless media_name
            media_index += 1
            media_name = "image#{media_index}.#{image_type[:extension]}"
            media_by_path[media_key] = media_name
            # 同一家具会同时出现在总表与分类表。媒体只读取、写入 ZIP 一次，
            # 各 drawing relationship 可以安全复用同一 xl/media 部件。
            # 原图以文件引用进入 ZIP 写入器，按 1 MiB 分块流式复制。即使一次导出
            # 数十张大图，也不会先把全部原图堆进 SketchUp 的 Ruby 内存。
            entries["xl/media/#{media_name}"] = { file_path: FastPath.expand(image[:path].to_s) }
          end
          image_rels << "<Relationship Id=\"rId#{image_index + 1}\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"../media/#{media_name}\"/>"
        end
        entries["xl/drawings/_rels/drawing#{sheet_no}.xml.rels"] = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">#{image_rels.join}</Relationships>"
      end
      progress.call(60, '校验 Excel 内部结构', "#{entries.length} 个 OOXML 部件") if progress
      validate_xlsx_package_entries!(entries)
      temp_target = File.join(File.dirname(target), ".#{File.basename(target)}.tmp-#{Process.pid}-#{SecureRandom.hex(4)}.xlsx")
      write_stored_zip!(temp_target, entries, progress: progress, progress_start: 62, progress_end: 90)
      progress.call(92, '校验 Excel ZIP 完整性', File.basename(temp_target)) if progress
      validate_soft_schedule_xlsx_file!(temp_target)
      progress.call(95, '替换正式 Excel 文件', File.basename(target)) if progress
      linkhub_mv(temp_target, target)
      validate_soft_schedule_xlsx_file!(target)
      progress.call(99, 'Excel 文件校验完成', "#{File.size(target)} bytes") if progress
      true
    ensure
      File.delete(temp_target) if defined?(temp_target) && temp_target && File.file?(temp_target)
    end

    def safe_export_filename(value)
      text = value.to_s.strip.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ')
      text.empty? ? '未命名项目' : text[0, 80]
    end

    def prepare_soft_schedule_export_images!(rows, root = soft_library_root)
      prepared = {}
      index = read_soft_library_index(root)
      paths_by_id = Hash.new { |hash, key| hash[key] = [] }
      Hash(index['models']).each do |record_path, record|
        next unless record.is_a?(Hash)
        model_id = record['model_id'].to_s.strip
        paths_by_id[model_id] << record_path.to_s unless model_id.empty?
      end
      Array(rows).each do |row|
        source_path = row['source_path'].to_s
        unless !source_path.empty? && File.file?(source_path)
          model_id = row['model_id'].to_s.strip
          source_path = Array(paths_by_id[model_id]).select { |candidate| File.file?(candidate) }.min_by do |candidate|
            [soft_library_path_inside?(candidate, soft_library_organized_dir(root)) ? 0 : 1,
             normalize_soft_library_key(candidate)]
          end.to_s
        end
        unless !source_path.empty? && File.file?(source_path)
          row['thumbnail_path'] = ''
          row['thumbnail_url'] = ''
          next
        end
        row['source_path'] = source_path
        key = normalize_soft_library_key(source_path)
        if prepared.key?(key)
          thumb = prepared[key].to_s
        else
          standard = soft_model_thumbnail_path(source_path, root)
          quick = soft_model_quick_thumbnail_path(source_path, root)
          current = row['thumbnail_path'].to_s
          thumb = if xlsx_image_file_type(current, strict: true)
                    current
                  elsif xlsx_image_file_type(standard, strict: true)
                    standard
                  elsif xlsx_image_file_type(quick, strict: true)
                    quick
                  else
                    candidate = ensure_soft_model_quick_thumbnail(source_path, root).to_s
                    xlsx_image_file_type(candidate, strict: true) ? candidate : ''
                  end
          prepared[key] = thumb
        end
        # v0.13.7.3：有 1024px 高清视图时 Excel 用高清图（点开查看更清楚）。
        hd = soft_thumbnail_hd_path(source_path, root)
        if !hd.empty? && xlsx_image_file_type(hd, strict: true)
          row['thumbnail_path'] = hd
          row['thumbnail_url'] = ''
        elsif xlsx_image_file_type(thumb, strict: true)
          row['thumbnail_path'] = thumb
          row['thumbnail_url'] = soft_thumbnail_url(thumb)
        else
          row['thumbnail_path'] = ''
          row['thumbnail_url'] = ''
        end
      rescue StandardError => e
        log_exception("准备采购清单模型图片失败：#{source_path}", e)
      end
      rows
    end

    # v0.13.6.31：Excel 导出与“写回模型”彻底解耦。
    # HtmlDialog 中的名称/分类/价格/备注/规格草稿可以只用于本次 Excel，
    # 不需要先执行采购清单提交，也绝不会因此缩放组件或修改组件轴。
    def parse_soft_schedule_export_drafts(json)
      return {} if json.to_s.strip.empty?
      data = JSON.parse(json.to_s)
      data.is_a?(Hash) ? data : {}
    rescue StandardError => e
      log_exception('解析采购清单导出草稿失败', e)
      {}
    end

    def soft_schedule_export_draft_identity_match?(row, draft)
      return false unless row.is_a?(Hash) && draft.is_a?(Hash)
      row_model_id = row['model_id'].to_s.strip
      draft_model_id = draft['model_id'].to_s.strip
      return row_model_id == draft_model_id unless row_model_id.empty? || draft_model_id.empty?
      row_path = row['source_path'].to_s.strip
      draft_path = draft['source_path'].to_s.strip
      return false if row_path.empty? || draft_path.empty?
      normalize_soft_library_key(row_path) == normalize_soft_library_key(draft_path)
    rescue StandardError
      row['source_path'].to_s.downcase == draft['source_path'].to_s.downcase
    end

    def soft_schedule_apply_export_drafts(rows, draft_json)
      payload = parse_soft_schedule_export_drafts(draft_json)
      model_drafts = payload['model_drafts'].is_a?(Hash) ? payload['model_drafts'] : {}
      dimension_drafts = payload['dimension_drafts'].is_a?(Hash) ? payload['dimension_drafts'] : {}
      applied_ids = {}
      result = Array(rows).map do |source_row|
        row = source_row.is_a?(Hash) ? source_row.dup : {}
        row['extra_fields'] = Hash(source_row['extra_fields']).dup if source_row.is_a?(Hash)

        model_drafts.each do |draft_key, draft|
          next unless soft_schedule_export_draft_identity_match?(row, draft)
          values = draft['values'].is_a?(Hash) ? draft['values'] : {}
          changed = draft['changed'].is_a?(Hash) ? draft['changed'] : {}
          %w[name category subcategory manufacturer contact material_description price remark].each do |field|
            next unless changed[field] == true && values.key?(field)
            value = values[field].to_s
            if field == 'name'
              suffix = row['display_name'].to_s[/#\d+$/].to_s
              row['name'] = value
              row['base_name'] = value
              row['library_name'] = value
              row['display_name'] = "#{value}#{suffix}"
            else
              row[field] = value
              row['remark_display'] = value if field == 'remark'
            end
          end
          extra_changed = changed['extra_fields'].is_a?(Hash) ? changed['extra_fields'] : {}
          extra_values = values['extra_fields'].is_a?(Hash) ? values['extra_fields'] : {}
          extra_changed.each do |field, dirty|
            next unless dirty == true
            row['extra_fields'][field.to_s] = extra_values[field].to_s
          end
          applied_ids["m:#{draft_key}"] = true
          break
        end

        dimension_drafts.each do |draft_key, draft|
          next unless soft_schedule_export_draft_identity_match?(row, draft)
          draft_variant = draft['variant_key'].to_s
          row_variant = row['variant_key'].to_s
          next unless draft_variant.empty? || row_variant.empty? || draft_variant == row_variant
          values = draft['values'].is_a?(Hash) ? draft['values'] : {}
          %w[length_mm width_mm height_mm].each do |field|
            next unless values.key?(field)
            value = values[field].to_f
            row[field] = value if value.finite?
          end
          applied_ids["d:#{draft_key}"] = true
          break
        end
        row
      end
      [result, applied_ids.length]
    rescue StandardError => e
      log_exception('合并采购清单 Excel 草稿失败', e)
      [Array(rows).map { |row| row.is_a?(Hash) ? row.dup : row }, 0]
    end

    def soft_schedule_rows_missing_dimensions(rows, category_filter = 'all')
      requested = category_filter.to_s
      Array(rows).select do |row|
        next false unless row.is_a?(Hash)
        if requested != 'all'
          category = soft_library_canonical_top_category(row['category'].to_s)
          next false unless category == requested
        end
        values = %w[length_mm width_mm height_mm].map { |field| row[field].to_f }
        values.any? { |value| !value.finite? || value <= 0.01 }
      end
    rescue StandardError
      []
    end

    def soft_schedule_export_snapshot(model = Sketchup.active_model)
      return soft_project_schedule_data(model) unless model
      key = model.object_id
      context = soft_schedule_build_context(model)
      signature = [soft_measurement_revision(model), soft_schedule_structure_signature(model, context: context)].join('|')
      cached = (@soft_schedule_last_payloads || {})[key]
      cached_signature = (@soft_schedule_last_signatures || {})[key].to_s
      return json_deep_copy(cached) if cached.is_a?(Hash) && cached_signature == signature

      # v0.13.6.75：导出按钮不再要求用户“先刷新、再点一次导出”。正常 HtmlDialog
      # 入口会由 request_soft_schedule_export 自动刷新后续跑到这里；若历史入口直接调用，
      # 也直接构建当前同一快照，不再人为中断一次导出。
      payload = soft_project_schedule_data(model, context: context)
      @soft_schedule_last_payloads ||= {}
      @soft_schedule_last_signatures ||= {}
      @soft_schedule_last_payloads[key] = payload
      @soft_schedule_last_signatures[key] = signature
      json_deep_copy(payload)
    end

    def export_soft_schedule_xlsx(scope = :project, model = Sketchup.active_model, category_filter = 'all', draft_json = nil, task_id: nil)
      update_task_center_job!(task_id, progress: 34, stage: '准备 Excel 数据', detail: '读取最新清单快照', status: 'running') unless task_id.to_s.empty?
      data = scope.to_sym == :project ? soft_schedule_export_snapshot(model) : soft_project_schedule_data(model)
      sheets = []
      requested = category_filter.to_s.strip
      requested = 'all' if requested.empty? || requested == '全部分类'
      requested = soft_library_canonical_top_category(requested) unless requested == 'all'
      project_label = data['project_name'].to_s
      if scope.to_sym == :current_space
        _state, item, entity = current_local_editing_space(nil, model, required: true)
        label = "#{item['number']}:#{item['name']}"
        source_rows = soft_measurement_rows(entity, label)
        attach_soft_schedule_photos!(source_rows, model)
        project_label = label
        suggested = "#{safe_export_filename(label)}_软装清单.xlsx"
      else
        source_rows = data['total_rows']
        suggested = "#{safe_export_filename(data['project_name'])}_软装采购清单.xlsx"
      end

      source_rows, export_draft_count = soft_schedule_apply_export_drafts(source_rows, draft_json)

      missing_dimensions = soft_schedule_rows_missing_dimensions(source_rows, requested)
      unless missing_dimensions.empty?
        names = missing_dimensions.first(5).map do |row|
          row['display_name'].to_s.empty? ? row['name'].to_s : row['display_name'].to_s
        end.reject(&:empty?)
        detail = names.empty? ? '' : "：#{names.join('、')}#{missing_dimensions.length > names.length ? '等' : ''}"
        raise "当前导出范围有 #{missing_dimensions.length} 项长/宽/高仍含 0 mm#{detail}。请在清单中补齐红色规格后再导出。"
      end
      update_task_center_job!(task_id, progress: 38, stage: '准备产品图与实物图', detail: "#{source_rows.length} 个清单条目", status: 'running') unless task_id.to_s.empty?
      prepare_soft_schedule_export_images!(source_rows)
      update_task_center_job!(task_id, progress: 44, stage: '图片准备完成', detail: '开始组织工作表', status: 'running') unless task_id.to_s.empty?
      export_scope_rows = if requested == 'all'
                            source_rows
                          else
                            source_rows.select { |row| soft_library_canonical_top_category(row['category']) == requested }
                          end
      export_image_count = export_scope_rows.count { |row| xlsx_image_file_type(row['thumbnail_path'].to_s, strict: true) }
      export_missing_image_count = export_scope_rows.length - export_image_count
      export_supplemental_image_count = export_scope_rows.sum do |row|
        Array(row['supplemental_photos']).count { |photo| photo.is_a?(Hash) && xlsx_image_file_type(photo['path'].to_s, strict: true) }
      end
      export_supplemental_missing_count = export_scope_rows.sum do |row|
        Array(row['supplemental_photos']).count { |photo| !photo.is_a?(Hash) || !xlsx_image_file_type(photo['path'].to_s, strict: true) }
      end

      # v0.13.7.1：总表与分类表按空间分区（每个空间一段，交替淡色底）；
      # 原来的“跨空间合并数量”保留在最后的“按款汇总”表，采购总数不丢失。
      space_rows = if scope.to_sym == :current_space
                     source_rows.map { |row| row.merge('_export_group' => 0) }
                   else
                     soft_schedule_expand_rows_by_space(source_rows, data['spaces'])
                   end
      if requested == 'all'
        title, headers, rows, groups = soft_schedule_summary_table(space_rows, project_name: project_label)
        sheets << { name: '总表', title: title, headers: headers, rows: rows, row_groups: groups }
        SOFT_LIBRARY_CATEGORIES.each do |category|
          category_title, category_headers, category_rows, category_groups = soft_schedule_category_table(space_rows, category, project_name: project_label)
          sheets << { name: category, title: category_title, headers: category_headers, rows: category_rows, row_groups: category_groups }
        end
        if scope.to_sym != :current_space
          summary_title = project_label.to_s.strip.empty? ? '软装按款汇总（跨空间合并数量）' : "软装按款汇总（#{project_label}，跨空间合并数量）"
          merged_title, merged_headers, merged_rows, = soft_schedule_summary_table(source_rows, project_name: project_label, title_override: summary_title)
          sheets << { name: '按款汇总', title: merged_title, headers: merged_headers, rows: merged_rows }
        end
      else
        category_title, category_headers, category_rows, category_groups = soft_schedule_category_table(space_rows, requested, project_name: project_label)
        sheets << { name: requested, title: category_title, headers: category_headers, rows: category_rows, row_groups: category_groups }
        suggested = "#{File.basename(suggested, '.xlsx')}_#{safe_export_filename(requested)}.xlsx"
      end
      default_dir = selected_collab_project_dir_for_state(load_state(model), model)
      default_dir = File.dirname(model.path) if default_dir.to_s.empty? && !model.path.to_s.empty?
      update_task_center_job!(task_id, progress: 48, stage: '等待选择 Excel 保存位置', detail: suggested, status: 'running') unless task_id.to_s.empty?
      path = UI.savepanel('导出软装清单 Excel', default_dir.to_s.empty? ? nil : default_dir, suggested)
      if path.nil? || path.to_s.empty?
        finish_task_center_job!(task_id, success: true, cancelled: true, stage: '已取消 Excel 导出', detail: '没有写入文件') unless task_id.to_s.empty?
        return false
      end
      path = "#{path}.xlsx" unless File.extname(path).casecmp('.xlsx').zero?
      target = FastPath.expand(path)
      message = "软装清单已导出：#{target}"
      message += "（已嵌入 #{export_image_count} 项产品图"
      message += "；#{export_missing_image_count} 项源模型确实没有可读取缩略图，Excel 已明确标注" if export_missing_image_count.positive?
      message += '）'
      message += "；已无损嵌入 #{export_supplemental_image_count} 张实物/细节原图" if export_supplemental_image_count.positive?
      message += "；#{export_supplemental_missing_count} 张实物/细节图文件已失效并在表格中标注" if export_supplemental_missing_count.positive?
      if export_draft_count.to_i.positive?
        message += "（#{export_draft_count.to_i} 项当前清单草稿仅用于本次 Excel，未提交、未缩放模型、未修改组件轴）"
      end
      sheets_snapshot = begin
        Marshal.load(Marshal.dump(sheets))
      rescue StandardError
        JSON.parse(JSON.generate(sheets), symbolize_names: true)
      end
      update_task_center_job!(task_id, progress: 52, stage: 'Excel 已进入后台写盘', detail: File.basename(target), status: 'running') unless task_id.to_s.empty?
      queued = enqueue_background_io_task(
        'xlsx_write',
        key: "xlsx|#{normalize_soft_library_key(target)}|#{task_id}",
        data: {
          target: target, sheets: sheets_snapshot, success_message: message, task_id: task_id.to_s,
          success_severity: (export_missing_image_count.positive? ? 'warning' : 'success')
        },
        label: "Excel 导出 · #{File.basename(target)}"
      )
      raise 'Excel 后台导出任务无法启动。' unless queued
      show_status("Excel 已加入任务队列：#{File.basename(target)}；可继续操作 SketchUp，左上角可查看实时进度。", 'info')
      sync_task_center_overlay_ui!(model) rescue nil
      true
    rescue StandardError => e
      finish_task_center_job!(task_id, success: false, stage: 'Excel 导出失败', detail: e.message, error: e) unless task_id.to_s.empty?
      sync_task_center_overlay_ui!(model) rescue nil
      raise
    end

    def soft_selection_snapshot(model = Sketchup.active_model)
      state = cached_project_state_readonly(model) || load_state(model)
      item = space_model_record(state, state['space_editing_id'].to_s)
      space_entity = item ? space_model_entity(item['id'], model) : nil
      inside_editing_space = item && space_entity && space_entity.valid? &&
                             local_space_edit_session?(item, state, model) &&
                             active_path_inside_space?(space_entity, model)
      selected = model.selection.to_a.select do |entity|
        entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
      end
      label = if selected.empty?
                'SU 未选择对象'
              elsif selected.length == 1
                entity = selected.first
                name = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
                name = entity.definition.name.to_s.strip if name.empty? && entity.respond_to?(:definition)
                name = '未命名对象' if name.empty?
                "SU 已选：#{name}"
              else
                "SU 已选择 #{selected.length} 个对象"
              end
      replacement_count = 0
      if inside_editing_space && selected.length == 1 && selected.first != space_entity
        # 这里只表达“当前选择可执行同定义替换”。旧版为了显示预计数量，每次点选
        # 都递归扫描整个空间 Definition 图；7_scdkf 约 4190 个定义，单次就可能卡住
        # 数秒。实际替换按钮被点击时仍由 replace_soft_instances_from_selection 完整收集
        # 并校验目标，普通选择不再支付这笔代价。
        replacement_count = 1
      end
      {
        'selection_count' => selected.length,
        'selection_label' => label,
        'replacement_count' => replacement_count
      }
    rescue StandardError
      { 'selection_count' => 0, 'selection_label' => 'SU 选择状态不可用', 'replacement_count' => 0 }
    end

    def send_soft_selection_snapshot(model = Sketchup.active_model)
      return false unless @soft_designer_dialog && @soft_designer_dialog.visible?
      payload = JSON.generate(soft_selection_snapshot(model))
      @soft_designer_dialog.execute_script("window.SoftDesigner && window.SoftDesigner.receiveState(#{payload});")
      true
    rescue StandardError => e
      log_exception('刷新 SketchUp 选择状态失败', e)
      false
    end

    def soft_selection_changed(model = Sketchup.active_model)
      return if soft_commit_world_context_active?(model)
      return false if soft_selection_refresh_suspended?
      return false unless model && @soft_designer_dialog && @soft_designer_dialog.visible?
      schedule_soft_selection_refresh(model, 0.06)
    rescue StandardError
      false
    end

    def attach_soft_selection_observer(model = Sketchup.active_model)
      return false unless model && model.respond_to?(:selection)
      detach_soft_selection_observer if @soft_selection_observer_model && @soft_selection_observer_model != model
      @soft_selection_observer ||= SoftSelectionObserver.new
      return true if @soft_selection_observer_model == model
      model.selection.add_observer(@soft_selection_observer)
      @soft_selection_observer_model = model
      true
    rescue StandardError => e
      log_exception('挂接软装选择观察器失败', e)
      false
    end

    def detach_soft_selection_observer
      model = @soft_selection_observer_model
      if model && @soft_selection_observer && model.respond_to?(:selection)
        model.selection.remove_observer(@soft_selection_observer)
      end
      @soft_selection_observer_model = nil
      true
    rescue StandardError
      @soft_selection_observer_model = nil
      false
    end

    def soft_designer_payload(refresh_library: false, include_library: true, include_measurements: false, include_materials: false)
      model = Sketchup.active_model
      state, item, entity = current_local_editing_space(nil, model, required: false)
      state = load_state(model) unless state.is_a?(Hash)
      inside_space = !!(item && entity && entity.valid? && active_path_inside_space?(entity, model))
      library_available = workspace_ready?(state, model) && host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
      root = soft_library_root
      payload = {
        'plugin_version' => EXTENSION_VERSION,
        'available' => inside_space,
        'can_place' => library_available,
        'library_available' => library_available,
        'space_id' => inside_space && item ? item['id'].to_s : '',
        'space_name' => inside_space && item ? space_ui_label(item) : '',
        'workspace_name' => library_available ? '软装工作区' : '',
        'library_root' => root,
        'library_ready' => !root.empty? && Dir.exist?(root),
        'library_scanning' => !!@soft_library_scanning,
        'organized_dir' => root.empty? ? '' : soft_library_organized_dir(root),
        'measurement_revision' => soft_measurement_revision(model),
        'material_library' => material_library_payload(SOFT_SPACE_COLLECTION_KEY, force: false, include_materials: include_materials)
      }
      payload.merge!(soft_selection_snapshot(model))
      if include_library
        rows = !root.empty? && Dir.exist?(root) ? scan_soft_library!(force: refresh_library) : []
        payload['models'] = decorate_library_usage(rows, 'model', SOFT_SPACE_COLLECTION_KEY, root)
      end
      if include_measurements
        label = inside_space && item ? "#{item['number']}:#{item['name']}" : ''
        payload['measurements'] = inside_space && item && entity ? soft_measurement_rows_cached(
          entity, label, space_id: item['id'], model: model
        ) : []
        payload['measurement_revision'] = soft_measurement_revision(model)
      end
      payload
    rescue StandardError => e
      log_exception('生成软装设计师状态失败', e)
      {
        'plugin_version' => EXTENSION_VERSION,
        'available' => false,
        'space_name' => '',
        'library_root' => soft_library_root,
        'library_ready' => false,
        'error' => e.message.to_s
      }
    end

    def soft_designer_dialog_file
      File.join(__dir__, 'ui', 'soft_designer.html')
    end

    # v0.13.6.146：选择变化只需要知道“当前是否有本机软装编辑会话”，
    # 不能为了画一个顶部按钮去读取共享锁文件。完整锁 ownership/stale 校验仍由
    # 模型库实际操作、发布、更新入口执行。
    def current_soft_designer_fab_space_fast(state = nil, model = Sketchup.active_model)
      state = cached_project_state_readonly(model) || load_state(model) unless state.is_a?(Hash)
      item = space_model_record(state, state['space_editing_id'].to_s)
      return nil unless item && local_space_edit_session?(item, state, model)
      entity = space_model_entity(item['id'], model)
      return nil unless entity && entity.valid? && !entity_native_locked?(entity)
      item
    rescue StandardError
      nil
    end

    def current_soft_designer_fab_space(model = Sketchup.active_model)
      state = load_state(model)
      item = space_model_record(state, state['space_editing_id'].to_s)
      return nil unless item
      entity = space_model_entity(item['id'], model)
      return nil unless entity && entity.valid? && !entity_native_locked?(entity)
      lock = space_lock_info(item, model)
      return nil unless lock['exists'] && !lock['stale'] && lock['owned']
      item
    rescue StandardError
      nil
    end

    # “正在修改”与“当前位于空间组件内”是两个独立状态。ESC 后前者继续为真，
    # 后者为假；发布按钮仍可用，但模型库、代真和空间参考眼睛只在组件内可用。
    def space_edit_context_active?(item, model = Sketchup.active_model)
      return false unless item && model
      entity = space_model_entity(item['id'], model)
      !!(entity && entity.valid? && active_path_inside_space?(entity, model))
    rescue StandardError
      false
    end

    def read_linkhub_enabled_preference
      raw = Sketchup.read_default(HUD_PREF_SECTION, LINKHUB_ENABLED_PREF_KEY, true)
      return false if raw == false || raw == 0
      value = raw.to_s.strip.downcase
      !%w[false 0 off disabled].include?(value)
    rescue StandardError
      true
    end

    def linkhub_enabled?
      @linkhub_enabled != false
    end

    def set_linkhub_enabled(enabled, notify: true)
      @linkhub_enabled = !!enabled
      Sketchup.write_default(HUD_PREF_SECTION, LINKHUB_ENABLED_PREF_KEY, @linkhub_enabled)
      if @linkhub_enabled
        handle_active_model_for_workspace_toolbar(Sketchup.active_model)
        show_status('SU LinkHub 已启动，悬浮按钮和左侧抽屉已恢复。', 'success') if notify
      else
        shutdown_workspace_toolbars!
        stop_space_presence_monitor
        show_status('SU LinkHub 已关闭悬浮界面；当前协作锁和项目数据保持不变。', 'success') if notify
      end
      begin
        GavinTools::SULinkHubMultiSpace.refresh_toolbar_command_state!
      rescue StandardError
        nil
      end
      @linkhub_enabled
    rescue StandardError => e
      log_exception('切换 LinkHub 启停状态失败', e)
      false
    end

    def toggle_linkhub_enabled
      set_linkhub_enabled(!linkhub_enabled?)
    end

    def workspace_toolbar_supported?
      return false unless linkhub_enabled?
      defined?(Sketchup::Overlay) && Sketchup.active_model.respond_to?(:overlays) && defined?(WorkspaceToolbarOverlay)
    rescue StandardError
      false
    end

    def ensure_workspace_toolbar_click_tool(model, overlay)
      return false unless defined?(WorkspaceToolbarClickTool)
      return false unless model && model == Sketchup.active_model
      return false if workspace_escape_transition_active?(model)
      return false unless overlay && overlay.valid?
      @workspace_toolbar_click_tools ||= {}
      @workspace_toolbar_click_tool_pending ||= {}
      key = model.object_id
      record = @workspace_toolbar_click_tools[key]
      return true if record && record[:tool]
      return true if @workspace_toolbar_click_tool_pending[key]

      @workspace_toolbar_click_tool_pending[key] = true
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) do
        @workspace_toolbar_click_tool_pending.delete(key)
        next unless model == Sketchup.active_model
        next if workspace_escape_transition_active?(model)
        # pointer_in_interactive_area? 本身已经包含 Overlay 可见性判断，而且是公开桥接接口。
        # toolbar_visible? 是 Overlay 的私有绘制方法，不能从 Runtime 直接调用；直接调用会
        # 让统一点击 Tool 永远无法压入，表现为固定钉、更新、修改、发布等所有按钮失效。
        next unless overlay.valid? && overlay.pointer_in_interactive_area?
        current = @workspace_toolbar_click_tools[key]
        next if current && current[:tool]
        tool = WorkspaceToolbarClickTool.new(self, model, overlay)
        @workspace_toolbar_click_tools[key] = { model: model, overlay: overlay, tool: tool }
        pushed = model.tools.push_tool(tool)
        @workspace_toolbar_click_tools.delete(key) unless pushed
      end
      true
    rescue StandardError => e
      @workspace_toolbar_click_tool_pending.delete(model.object_id) if model && @workspace_toolbar_click_tool_pending
      log_exception('启用工作空间工具条点击层失败', e)
      false
    end

    def workspace_toolbar_click_tool_activated(model, tool)
      @workspace_toolbar_click_tools ||= {}
      key = model.object_id
      record = @workspace_toolbar_click_tools[key]
      if record && record[:tool].equal?(tool)
        record[:active] = true
      else
        @workspace_toolbar_click_tools[key] = { model: model, tool: tool, active: true }
      end
      true
    rescue StandardError
      false
    end

    def workspace_toolbar_click_tool_deactivated(model, tool)
      records = @workspace_toolbar_click_tools || {}
      key = model.object_id
      record = records[key]
      records.delete(key) if record && record[:tool].equal?(tool)
      true
    rescue StandardError
      false
    end

    def release_workspace_toolbar_click_tool(model, tool)
      records = @workspace_toolbar_click_tools || {}
      key = model.object_id
      record = records[key]
      records.delete(key) if record && record[:tool].equal?(tool)
      begin
        active_tool = model.tools.active_tool if model && model.respond_to?(:tools)
        model.tools.pop_tool if active_tool && active_tool.equal?(tool)
      rescue StandardError
        # 工具可能已被 SketchUp 或另一个命令自动弹出。
        nil
      end
      true
    rescue StandardError
      false
    end

    def shutdown_workspace_toolbar_click_tools!
      records = (@workspace_toolbar_click_tools || {}).values
      @workspace_toolbar_click_tools = {}
      @workspace_toolbar_click_tool_pending = {}
      records.each do |record|
        next unless record.is_a?(Hash)
        model = record[:model]
        tool = record[:tool]
        begin
          active_tool = model.tools.active_tool if model && model.respond_to?(:tools)
          model.tools.pop_tool if active_tool && tool && active_tool.equal?(tool)
        rescue StandardError
          nil
        end
      end
      true
    rescue StandardError
      @workspace_toolbar_click_tools = {}
      @workspace_toolbar_click_tool_pending = {}
      false
    end

    def remove_workspace_toolbar_from_manager(model, overlay)
      return false unless model && overlay
      begin
        overlay.deactivate! if overlay.respond_to?(:deactivate!)
        overlay.enabled = false if overlay.respond_to?(:enabled=)
      rescue StandardError
        nil
      end
      begin
        model.overlays.remove(overlay) if model.respond_to?(:overlays)
      rescue StandardError
        nil
      end
      true
    end

    def remove_duplicate_workspace_toolbars(model)
      return false unless model && model.respond_to?(:overlays)
      duplicates = []
      model.overlays.each do |overlay|
        overlay_id = overlay.respond_to?(:overlay_id) ? overlay.overlay_id.to_s : ''
        duplicates << overlay if overlay_id == WORKSPACE_OVERLAY_ID
      end
      duplicates.each { |overlay| remove_workspace_toolbar_from_manager(model, overlay) }
      true
    rescue StandardError
      false
    end

    # 热重载会替换 Runtime 模块，但 SketchUp Overlay 对象可能仍留在模型的
    # overlays 管理器中。此时新运行代的 @workspace_toolbar_records 是空的，旧版
    # 只查询运行时记录，导致抽屉明明可见，组展开却报“空间组抽屉不可用”。
    #
    # 这里统一完成三件事：
    # 1. 优先接回当前运行代已经登记的 Overlay；
    # 2. 运行代记录丢失时，从 SketchUp overlays 管理器重新认领兼容对象；
    # 3. 对象来自旧代码代且缺少本次操作所需方法时，安全移除并创建新 Overlay。
    def export_runtime_hot_reload_state(model = Sketchup.active_model)
      record = model && (@workspace_toolbar_records || {})[model.object_id]
      overlay = record.is_a?(Hash) ? record[:overlay] : nil
      {
        'workspace_toolbar' => workspace_toolbar_hot_reload_snapshot(overlay),
        'linkhub_enabled' => linkhub_enabled?
      }
    rescue StandardError
      {}
    end

    def import_runtime_hot_reload_state!(snapshot, model = Sketchup.active_model)
      data = snapshot.is_a?(Hash) ? snapshot : {}
      return true if data.empty?
      return true unless model && linkhub_enabled?
      overlay_state = data['workspace_toolbar']
      return true unless overlay_state.is_a?(Hash) && !overlay_state.empty?
      overlay = ensure_workspace_toolbar_for_model(model)
      return false unless overlay
      overlay.import_hot_reload_state!(overlay_state) if overlay.respond_to?(:import_hot_reload_state!)
      refresh_workspace_toolbar(model, detailed: true)
      true
    rescue StandardError => e
      log_exception('恢复热重载前的抽屉状态失败', e)
      false
    end

    def workspace_toolbar_hot_reload_snapshot(overlay)
      return {} unless overlay
      return overlay.export_hot_reload_state if overlay.respond_to?(:export_hot_reload_state)
      {
        'drawer_open' => (overlay.respond_to?(:drawer_open?) ? !!overlay.drawer_open? : !!overlay.instance_variable_get(:@drawer_open)),
        'drawer_pinned' => !!overlay.instance_variable_get(:@drawer_pinned),
        'drawer_progress' => overlay.instance_variable_get(:@drawer_progress).to_f,
        'space_scroll_index' => overlay.instance_variable_get(:@space_scroll_index).to_i,
        'architecture_scroll_index' => overlay.instance_variable_get(:@architecture_scroll_index).to_i,
        'professional_section_collapsed_overrides' => (overlay.instance_variable_get(:@professional_section_collapsed_overrides) || {}).dup,
        'architecture_manage_mode' => !!overlay.instance_variable_get(:@architecture_manage_mode),
        'architecture_manage_selected' => (overlay.instance_variable_get(:@architecture_manage_selected) || {}).dup,
        'drawer_tools_mode' => !!overlay.instance_variable_get(:@drawer_tools_mode),
        'drawer_workspace_picker' => !!overlay.instance_variable_get(:@drawer_workspace_picker),
        'space_manage_mode' => !!overlay.instance_variable_get(:@space_manage_mode),
        'space_manage_selected' => (overlay.instance_variable_get(:@space_manage_selected) || {}).dup,
        'state' => begin
          state = overlay.instance_variable_get(:@state)
          Marshal.load(Marshal.dump(state))
        rescue StandardError
          {}
        end
      }
    rescue StandardError
      {}
    end

    # 热重载后只允许复用“当前类对象”。旧 Runtime 的 Overlay 即便恰好拥有同名
    # 方法，也仍会执行旧方法体，导致安装了新版本却继续出现旧交互 bug。旧对象仅
    # 导出纯 UI 状态，随后统一移除并以当前运行代的类重建。
    def ensure_workspace_toolbar_for_model(model = Sketchup.active_model, required_methods: [])
      return nil unless workspace_toolbar_supported?
      return nil unless model
      required = Array(required_methods).map(&:to_sym)
      compatible = lambda do |overlay|
        overlay && overlay.class.equal?(WorkspaceToolbarOverlay) && required.all? { |method_name| overlay.respond_to?(method_name) }
      end

      @workspace_toolbar_records ||= {}
      key = model.object_id
      record = @workspace_toolbar_records[key]
      preserved_state = {}
      if record && record[:overlay]
        overlay = record[:overlay]
        if compatible.call(overlay)
          begin
            overlay.activate! if overlay.respond_to?(:activate!)
            overlay.enabled = true if overlay.respond_to?(:enabled=)
            return overlay
          rescue StandardError
            # 记录对象失效，下面统一重建。
          end
        else
          preserved_state = workspace_toolbar_hot_reload_snapshot(overlay)
        end
        @workspace_toolbar_records.delete(key)
      end

      candidates = []
      if model.respond_to?(:overlays)
        begin
          model.overlays.each do |overlay|
            overlay_id = overlay.respond_to?(:overlay_id) ? overlay.overlay_id.to_s : ''
            candidates << overlay if overlay_id == WORKSPACE_OVERLAY_ID
          end
        rescue StandardError
          candidates = []
        end
      end

      current = candidates.reverse.find { |overlay| compatible.call(overlay) }
      if current
        begin
          current.enabled = true if current.respond_to?(:enabled=)
          current.activate! if current.respond_to?(:activate!)
          @workspace_toolbar_records[key] = { model: model, overlay: current }
          candidates.each { |candidate| remove_workspace_toolbar_from_manager(model, candidate) unless candidate.equal?(current) }
          return current
        rescue StandardError
          preserved_state = workspace_toolbar_hot_reload_snapshot(current) if preserved_state.empty?
        end
      end

      old_candidate = candidates.reverse.find { |overlay| !overlay.class.equal?(WorkspaceToolbarOverlay) }
      preserved_state = workspace_toolbar_hot_reload_snapshot(old_candidate) if preserved_state.empty? && old_candidate
      candidates.each { |overlay| remove_workspace_toolbar_from_manager(model, overlay) }

      overlay = WorkspaceToolbarOverlay.new(model)
      model.overlays.add(overlay)
      overlay.import_hot_reload_state!(preserved_state) if !preserved_state.empty? && overlay.respond_to?(:import_hot_reload_state!)
      overlay.enabled = true if overlay.respond_to?(:enabled=)
      overlay.activate! if overlay.respond_to?(:activate!)
      @workspace_toolbar_records[key] = { model: model, overlay: overlay }
      log('已使用当前运行代重建工作空间抽屉 Overlay。') if old_candidate
      overlay
    rescue StandardError => e
      log_exception('创建或恢复工作空间工具条失败', e)
      nil
    end

    def shutdown_workspace_toolbars!
      restore_workspace_locked_selection_colors!
      shutdown_workspace_toolbar_click_tools!
      records = @workspace_toolbar_records || {}
      records.each_value do |record|
        remove_workspace_toolbar_from_manager(record[:model], record[:overlay]) if record.is_a?(Hash)
      end
      @workspace_toolbar_records = {}
      true
    rescue StandardError
      @workspace_toolbar_records = {}
      false
    end

    # 统一判断一个 LinkHub 根模型真正所属专业。多建筑根组件的 kind 已经从旧
    # model/skp 升级为 architecture_model，因此不能只依赖旧 kind 白名单。
    # 同时用 kind 兜底 discipline，避免旧缓存属性缺失时把同专业建筑误判为“其他专业”。
    def managed_root_effective_discipline(entity)
      return '' unless entity && entity.valid? && entity.respond_to?(:get_attribute)
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
      discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
      return 'architecture' if kind == 'architecture_model'
      return normalize_space_collection_key(discipline) if kind == 'space_model'
      discipline
    rescue StandardError
      ''
    end

    def workspace_other_reference_entities(state, model = Sketchup.active_model)
      owner = host_discipline_for(state)
      return [] if owner == 'coordination'
      managed_root_index(model)[:all].select do |entity|
        next false unless entity && entity.valid? && entity.respond_to?(:get_attribute)
        discipline = managed_root_effective_discipline(entity)
        next false if discipline.empty?
        discipline != owner
      rescue StandardError
        false
      end
    rescue StandardError
      []
    end

    # 修复由 v0.12.0 进入建筑编辑时产生的旧隔离状态：热重载升级后如果当前仍
    # 在建筑组件内，不要求用户先退出再进入，第一次点击小眼睛就恢复同专业建筑
    # 到进入编辑前的显隐状态。手工隐藏/组隐藏的建筑仍保持隐藏。
    def restore_architecture_peer_visibility_during_edit!(state, model = Sketchup.active_model)
      architecture_id = state['architecture_editing_id'].to_s
      return false if architecture_id.empty?
      item = architecture_model_record(state, architecture_id)
      entity = item ? architecture_model_entity(architecture_id, model) : nil
      return false unless item && entity && entity.valid? && active_path_inside_architecture_model?(entity, model)
      snapshot = item['isolation_snapshot'].is_a?(Hash) ? item['isolation_snapshot'] : {}
      architecture_model_entities(model).each do |other|
        next unless other && other.valid? && other != entity && other.respond_to?(:hidden=)
        key = entity_persistent_key(other).to_s
        other.hidden = !!snapshot[key] if snapshot.key?(key)
      rescue StandardError
        next
      end
      entity.hidden = false if entity.respond_to?(:hidden=)
      true
    rescue StandardError => e
      log_exception('恢复同专业建筑参考显示失败', e)
      false
    end

    def workspace_references_visible?(state, model = Sketchup.active_model)
      return true if host_discipline_for(state) == 'coordination'
      return false if state['workspace_references_visible'] == false
      entities = workspace_other_reference_entities(state, model)
      entities.empty? || entities.any? { |entity| !entity.respond_to?(:hidden?) || !entity.hidden? }
    rescue StandardError
      state['workspace_references_visible'] != false
    end

    def set_workspace_references_visible!(visible, model = Sketchup.active_model, notify: true)
      state = load_state(model)
      owner = host_discipline_for(state)
      raise '协调总模没有“只显示本专业”状态。' if owner == 'coordination'
      entities = workspace_other_reference_entities(state, model)
      snapshot = state['workspace_reference_visibility_snapshot'].is_a?(Hash) ? state['workspace_reference_visibility_snapshot'] : {}
      operation_open = false
      model.start_operation(visible ? '显示其他专业参考' : '只显示当前专业', true, false, true)
      operation_open = true
      # 多建筑编辑期间，同专业建筑永远不属于“其他专业参考”。这一步同时兼容
      # v0.12.0 已经建立的旧隔离快照，避免热重载后其他建筑继续莫名隐藏。
      restore_architecture_peer_visibility_during_edit!(state, model) if owner == 'architecture'
      if visible
        entities.each do |entity|
          next unless entity.respond_to?(:hidden=)
          key = entity_snapshot_id(entity)
          entity.hidden = snapshot.key?(key) ? !!snapshot[key] : false
        rescue StandardError
          next
        end
        state['workspace_reference_visibility_snapshot'] = {}
        state['workspace_reference_focus_owner'] = ''
      else
        snapshot = {}
        entities.each do |entity|
          next unless entity.respond_to?(:hidden=)
          snapshot[entity_snapshot_id(entity)] = !!entity.hidden?
          entity.hidden = true
        rescue StandardError
          next
        end
        state['workspace_reference_visibility_snapshot'] = snapshot
        state['workspace_reference_focus_owner'] = owner
      end
      state['workspace_references_visible'] = !!visible
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      model.active_view.invalidate if model.respond_to?(:active_view)
      refresh_dialog
      if notify
        label = DISCIPLINES.dig(owner, 'name').to_s
        label = '当前专业' if label.empty?
        show_status(visible ? '已恢复其他专业参考显示。' : "当前只显示#{label}；再次点击眼睛可恢复其他参考。", 'success')
      end
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise e
    end

    def toggle_workspace_references(model = Sketchup.active_model)
      item = current_soft_designer_fab_space(model)
      return toggle_space_edit_references(item['id']) if item && space_edit_context_active?(item, model)
      state = load_state(model)
      set_workspace_references_visible!(!workspace_references_visible?(state, model), model)
    end

    # v0.9.88: 批量更新不能再为每个空间重复读取共享清单、重建根索引、
    # 刷新抽屉和保存状态。对几十个空间，这些固定开销会被放大数十倍。
    def space_model_needs_update_in_state?(item, state, entity, model = Sketchup.active_model)
      return false if background_publish_active_state?(item)
      actual = entity && entity.valid? ? entity.get_attribute(ENTITY_DICT, 'space_representation', state['space_display_mode']).to_s : state['space_display_mode'].to_s
      asset = space_asset_for(item, state, model, representation: actual)
      path = asset[:path]
      return false unless File.file?(path)
      return true unless entity && entity.valid?
      return true if entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i < SPACE_LOAD_VERIFIED_SCHEMA
      space_update_direction(item, entity, path) == :newer
    rescue StandardError
      true
    end

    # 只在线程中做文件复制，不调用任何 SketchUp API。旧版虽然开了两个线程，
    # 但随后仍在 SketchUp 主线程等待全部线程结束，界面会完整冻结。新版由一个
    # 轻量 UI 定时器轮询完成状态；线程只碰普通文件，完成后才回到主线程载入 SKP。
    def prefetch_space_batch_mirrors_async!(jobs, workers: SPACE_BATCH_PREFETCH_WORKERS, model: Sketchup.active_model, &callback)
      rows = Array(jobs).select { |job| job.is_a?(Hash) && File.file?(job[:source].to_s) }
      unless rows.any?
        runtime_start_timer(0.0, false, label: 'space_batch_prefetch_empty') { callback.call({}, nil) if callback }
        return true
      end

      queue = Queue.new
      rows.each { |job| queue << job }
      results = {}
      mutex = Mutex.new
      remaining = rows.length
      count = [[workers.to_i, 1].max, rows.length].min
      token = SecureRandom.hex(8)
      @space_batch_prefetch_jobs ||= {}
      job_state = {
        token: token,
        model: model,
        results: results,
        mutex: mutex,
        remaining: remaining,
        started_at: monotonic_time,
        generation: @runtime_generation.to_i,
        cancelled: false,
        threads: []
      }
      @space_batch_prefetch_jobs[token] = job_state

      count.times do
        thread = Thread.new do
          loop do
            break if @shutting_down || job_state[:cancelled] || job_state[:generation].to_i != @runtime_generation.to_i
            job = begin
              queue.pop(true)
            rescue ThreadError
              nil
            end
            break unless job
            begin
              # 始终经过 stage_source_mirror 的内容采样校验；命中缓存时只读取
              # 文件头尾样本，不会重新复制整个 SKP。
              ready = stage_source_mirror(job[:key], job[:source], job[:revision])
              mutex.synchronize do
                results[job[:id]] = {
                  ok: true,
                  path: ready,
                  revision: job[:revision].to_s,
                  source_signature: job[:source_signature].to_s,
                  source_snapshot: job[:source_snapshot].to_s
                }
              end
            rescue StandardError => e
              mutex.synchronize { results[job[:id]] = { ok: false, error: e.message.to_s } }
            ensure
              mutex.synchronize do
                job_state[:remaining] = [job_state[:remaining].to_i - 1, 0].max
              end
            end
          end
        end
        thread.abort_on_exception = false if thread.respond_to?(:abort_on_exception=)
        job_state[:threads] << thread
        register_background_gvl_thread!(thread)
      end

      timer_id = nil
      timer_id = runtime_start_timer(SPACE_BATCH_PREFETCH_POLL_INTERVAL, true, label: 'space_batch_prefetch_poll') do
        current = @space_batch_prefetch_jobs && @space_batch_prefetch_jobs[token]
        unless current
          runtime_stop_timer(timer_id) if timer_id
          next
        end
        if current[:cancelled] || current[:generation].to_i != @runtime_generation.to_i
          runtime_stop_timer(timer_id) if timer_id
          @space_batch_prefetch_jobs.delete(token)
          next
        end
        done = current[:mutex].synchronize { current[:remaining].to_i <= 0 }
        next unless done
        runtime_stop_timer(timer_id) if timer_id
        @space_batch_prefetch_jobs.delete(token)
        snapshot = current[:mutex].synchronize { current[:results].dup }
        error = Sketchup.active_model == model ? nil : '活动 SketchUp 模型已经切换，空间更新已取消。'
        callback.call(snapshot, error) if callback
      end
      job_state[:timer_id] = timer_id
      token
    rescue StandardError => e
      log_exception('启动批量空间镜像后台准备失败', e)
      callback.call({}, e.message.to_s) if callback
      false
    end

    def cancel_space_batch_prefetch_jobs!
      jobs = (@space_batch_prefetch_jobs || {}).values
      jobs.each do |job|
        next unless job.is_a?(Hash)
        job[:cancelled] = true
        runtime_stop_timer(job[:timer_id]) if job[:timer_id]
      rescue StandardError
        nil
      end
      @space_batch_prefetch_jobs = {}
      jobs.length
    rescue StandardError => e
      log_exception('取消空间批量镜像任务失败', e)
      @space_batch_prefetch_jobs = {}
      0
    end

    def finish_space_batch_update_interaction!(model = Sketchup.active_model)
      Sketchup.set_status_text('') rescue nil
      @space_batch_update_job = nil
      @updating = false
      end_soft_heavy_interaction(:space_batch_update)
      true
    rescue StandardError
      @space_batch_update_job = nil
      @updating = false
      end_soft_heavy_interaction(:space_batch_update)
      false
    end

    def invoke_space_batch_completion(completion, result)
      completion.call(result) if completion.respond_to?(:call)
      true
    rescue StandardError => e
      log_exception('空间批量更新完成回调失败', e)
      false
    end

    # 文件线程完成后，不一定正好处于可安全写 SketchUp 模型的时机。若用户进入了
    # 组件层级或正在发布，就保留已完成的本地镜像，等回到顶层空闲帧再载入。
    def schedule_complete_space_models_batch_update!(context, mirror_results, prefetch_error: nil, attempt: 0)
      model = context[:model]
      return false unless @space_batch_update_job && @space_batch_update_job[:token].to_s == context[:token].to_s
      return complete_space_models_batch_update!(context, mirror_results, prefetch_error: '活动 SketchUp 模型已经切换，空间更新已取消。') unless Sketchup.active_model == model

      blocked = publish_critical_section? || (model.respond_to?(:active_path) && !model.active_path.nil?)
      unless blocked
        return complete_space_models_batch_update!(context, mirror_results, prefetch_error: prefetch_error)
      end

      if attempt.to_i.zero? && context[:notify] == true
        show_status('空间本地镜像已准备完成；退出当前组件编辑层级后将自动载入更新。', 'info')
      end
      if attempt.to_i >= 1200
        return complete_space_models_batch_update!(context, mirror_results, prefetch_error: '等待安全载入超时，空间更新已取消；请退出组件层级后重新更新。')
      end
      runtime_start_timer(0.5, false, label: 'space_batch_wait_safe_load') do
        schedule_complete_space_models_batch_update!(
          context, mirror_results,
          prefetch_error: prefetch_error,
          attempt: attempt.to_i + 1
        )
      end
      true
    rescue StandardError => e
      log_exception('等待空间批量更新安全载入失败', e)
      complete_space_models_batch_update!(context, mirror_results, prefetch_error: e.message.to_s)
    end

    def complete_space_models_batch_update!(context, mirror_results, prefetch_error: nil)
      model = context[:model]
      state = context[:state]
      candidates = context[:candidates]
      failed = context[:failed]
      skipped = context[:skipped].to_i
      notify = context[:notify] == true
      completion = context[:completion]
      started = context[:started]
      updated = 0
      updated_previous_while_editing = 0
      recovered_manifest_ids = []

      unless @space_batch_update_job && @space_batch_update_job[:token].to_s == context[:token].to_s
        return false
      end
      if prefetch_error && !prefetch_error.to_s.empty?
        failed << prefetch_error.to_s
        result = { ok: false, pending: false, updated: 0, failed: failed }
        show_status("空间批量更新已取消：#{prefetch_error}", 'error') if notify
        invoke_space_batch_completion(completion, result)
        return result
      end

      mirror_failures = mirror_results.count { |_id, result| !result[:ok] }
      log("批量空间镜像后台准备完成：#{candidates.length - mirror_failures}/#{candidates.length}，失败#{mirror_failures}")
      sync_space_models_from_manifest!(state, model)
      structure = ensure_professional_structure(SPACE_COLLECTION_KEY, model)
      entities_by_id = context[:entities_by_id]

      candidates.each_with_index do |row, index|
        item = space_model_record(state, row[:item]['id'].to_s) || row[:item]
        id = item['id'].to_s
        label = "#{item['number']}:#{item['name']}"
        mirror = mirror_results[id]
        unless mirror && mirror[:ok]
          detail = mirror && mirror[:error].to_s
          detail = '本地镜像准备失败' if detail.empty?
          failed << "#{label}（#{detail}）"
          next
        end
        unless mirror[:revision].to_s == row[:revision].to_s &&
               mirror[:source_signature].to_s == row[:source_signature].to_s &&
               mirror[:source_snapshot].to_s == row[:source_snapshot].to_s
          failed << "#{label}（后台镜像快照与本次更新不一致）"
          next
        end

        Sketchup.set_status_text("LinkHub 更新空间 #{index + 1}/#{candidates.length}：#{label}") rescue nil
        operation_open = false
        begin
          current_source = auto_relocate(item['model_path'].to_s, model)
          raise '共享 SKP 不存在' unless File.file?(current_source)
          current_signature = fast_file_signature(current_source)
          current_revision = space_authoritative_revision(item, current_source, actual_signature: current_signature)
          unless current_revision.to_s == row[:revision].to_s &&
                 normalize_fast_signature(current_signature) == normalize_fast_signature(row[:source_signature]) &&
                 space_source_snapshot_signature(current_source) == row[:source_snapshot].to_s
            raise '镜像准备期间发布了新版本或文件内容变化，已跳过过渡版；请再次更新'
          end
          assert_space_update_direction!(item, row[:entity], current_source, allow_unknown: false)
          model.start_operation("批量更新空间 #{label}", true)
          operation_open = true
          entity = row[:entity]
          entity.locked = true if entity && entity.valid? && entity.respond_to?(:locked=)
          loaded = load_space_model_instance!(
            item, model,
            representation: state['space_display_mode'], purge: false,
            state: state, existing_entity: entity, dedupe: false,
            invalidate_index: false, structure: structure, force_visible: true,
            load_path_override: mirror[:path].to_s,
            expected_revision: row[:revision].to_s,
            expected_source_signature: row[:source_signature].to_s,
            expected_source_snapshot: row[:source_snapshot].to_s
          )
          item_collection = space_record_collection_key(item)
          unless space_collection_hidden_for(state, item_collection)
            loaded.hidden = false if loaded && loaded.valid? && loaded.respond_to?(:hidden=)
            group = item['group_id'].to_s.empty? ? nil : space_group_record(state, item['group_id'].to_s)
            if group
              visibility_state = group_collection_visibility_state(group, item_collection)
              if visibility_state['suspended']
                restore_ids = Array(visibility_state['restore_ids']).map(&:to_s).reject { |candidate| candidate == id }
                visibility_state['restore_ids'] = restore_ids
                visibility_state['suspended'] = false if restore_ids.empty?
                sync_legacy_group_visibility_from_collection!(group) if item_collection == SPACE_COLLECTION_KEY
              end
            end
          end
          if space_collection_hidden_for(state, item_collection) && loaded && loaded.valid?
            snapshot = space_collection_visibility_snapshot_for(state, item_collection)
            key = space_collection_entity_visibility_key(loaded)
            snapshot['entities'][key] = false unless snapshot['entities'].key?(key)
            set_space_collection_visibility_snapshot_for!(state, item_collection, snapshot)
            loaded.hidden = true if loaded.respond_to?(:hidden=)
          end
          @native_lock_state_cache ||= {}
          @native_lock_state_cache[space_native_cache_key(model, id)] = true
          entities_by_id[id] = loaded
          recovered_manifest_ids << id if item.delete('_manifest_package_recovery_pending') == true
          model.commit_operation
          operation_open = false
          overlay = workspace_toolbar_overlay(model)
          if overlay && !space_collection_hidden_for(state, item_collection)
            overlay.mark_space_loaded_visible_local!(id) if overlay.respond_to?(:mark_space_loaded_visible_local!)
            if defined?(group) && group && overlay.respond_to?(:set_space_group_visibility_local!)
              visibility_state = group_collection_visibility_state(group, item_collection)
              overlay.set_space_group_visibility_local!(group['id'], visibility_state['suspended'], visibility_state['restore_ids'])
            end
          end
          updated += 1
          updated_previous_while_editing += 1 unless row[:other_editor].to_s.empty?
          save_state(state, model, write_manifest: false) if (updated % SPACE_BATCH_CHECKPOINT_EVERY).zero?
        rescue StandardError => e
          model.abort_operation rescue nil if operation_open
          failed << "#{label}（#{e.message}）"
          log_exception("批量更新空间失败：#{label}", e)
        end
      end

      invalidate_managed_root_index(model, reason: 'space_batch_update_complete')
      unless recovered_manifest_ids.empty?
        write_space_models_manifest!(
          state, model,
          preserve_remote_layout: true,
          local_space_ids: recovered_manifest_ids
        )
        recovered_manifest_ids.each do |recovered_id|
          recovered_item = space_model_record(state, recovered_id)
          recovered_entity = entities_by_id[recovered_id]
          next unless recovered_item && recovered_entity && recovered_entity.valid?
          recovered_source = auto_relocate(recovered_item['model_path'].to_s, model)
          repair_verified_space_safe_checkpoint_gap!(
            recovered_item, recovered_entity, recovered_source,
            recovered_item['source_revision'].to_s, recovered_item['last_signature'].to_s
          )
        end
        log("批量更新已补写 #{recovered_manifest_ids.length} 个中断发布的空间清单版本")
      end
      save_state(state, model, write_manifest: false)
      schedule_soft_full_definition_cleanup(model, delay: 2.4)
      refresh_dialog
      elapsed = elapsed_ms(started)
      log("空间后台镜像批量更新完成：更新#{updated}，失败#{failed.length}，跳过#{skipped}，总计#{elapsed}ms")
      if notify
        message = "空间批量更新完成：已更新 #{updated} 个"
        message += "，其中 #{updated_previous_while_editing} 个载入了他人修改前的上一发布版" if updated_previous_while_editing.positive?
        message += "，跳过 #{skipped} 个本机正在修改/暂存空间" if skipped.positive?
        message += "；失败：#{failed.join('；')}" unless failed.empty?
        show_status(message, failed.empty? ? 'success' : 'error')
      end
      result = { ok: failed.empty?, pending: false, updated: updated, failed: failed }
      invoke_space_batch_completion(completion, result)
      result
    rescue StandardError => e
      log_exception('完成空间批量更新失败', e)
      failed ||= []
      failed << e.message.to_s
      result = { ok: false, pending: false, updated: updated.to_i, failed: failed }
      show_status("空间批量更新失败：#{e.message}", 'error') if notify
      invoke_space_batch_completion(completion, result)
      result
    ensure
      if defined?(model) && model && @space_batch_update_job &&
         @space_batch_update_job[:token].to_s == context[:token].to_s
        finish_space_batch_update_interaction!(model)
      end
    end

    def update_space_models_batch(notify: true, model: Sketchup.active_model, completion: nil, collection_key: nil)
      raise '请先退出其他组件编辑层级，再更新空间模型。' unless model.active_path.nil?
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再批量更新空间模型。' if publish_critical_section? || publish_post_quiet?
      raise '模型库批量任务正在执行，请等待完成后再批量更新空间模型。' if @soft_model_batch_job
      return { ok: false, pending: false, updated: 0, failed: ['另一个更新任务正在进行'] } if @updating || @shared_component_batch_update_job || @consistency_update_job

      @updating = true
      begin_soft_heavy_interaction(:space_batch_update)
      started = monotonic_time
      failed = []
      skipped = 0
      async_started = false
      begin
        state = ensure_space_models_ready!(model)
        spaces = collection_key.to_s.empty? ? Array(state['space_models']) : spaces_for_collection(state, collection_key)
        if spaces.empty?
          show_status('当前项目还没有软装＋硬装空间模型。', 'info') if notify
          result = { ok: true, pending: false, updated: 0, failed: [] }
          invoke_space_batch_completion(completion, result)
          finish_space_batch_update_interaction!(model)
          return result
        end

        root_index = managed_root_index(model)
        entities_by_id = (root_index[:spaces_by_id] || {}).dup
        candidates = []
        spaces.each do |item|
          id = item['id'].to_s
          if item['editing'] || space_edit_safe_paused?(item) || space_force_recovery_active?(item) || state['space_editing_id'].to_s == id
            skipped += 1
            next
          end
          entity = entities_by_id[id]
          source = auto_relocate(item['model_path'].to_s, model)
          unless File.file?(source)
            failed << "#{item['number']}:#{item['name']}（共享 SKP 不存在）"
            next
          end
          verified_schema = entity && entity.valid? ? entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i : 0
          direction = verified_schema < SPACE_LOAD_VERIFIED_SCHEMA ? :newer : space_update_direction(item, entity, source)
          next if direction == :same
          if direction == :older
            failed << "#{item['number']}:#{item['name']}（共享版本更旧，已阻止降级）"
            next
          elsif direction == :unknown
            failed << "#{item['number']}:#{item['name']}（版本先后无法确认，未自动替换）"
            next
          end
          lock = space_lock_info(item, model, source_path: source, state: state)
          other_editor = ''
          if lock['exists'] && !lock['stale'] && !lock['owned']
            who = [lock['owner'], lock['host']].reject(&:empty?).join('@')
            other_editor = who.empty? ? '其他成员' : who
          end
          source_signature = fast_file_signature(source)
          source_snapshot = space_source_snapshot_signature(source)
          if source_snapshot.empty?
            failed << "#{item['number']}:#{item['name']}（无法验证共享 SKP 内容）"
            next
          end
          revision = space_authoritative_revision(item, source, actual_signature: source_signature)
          revision = "space-file|#{source_signature}" if revision.empty?
          candidates << {
            item: item, entity: entity, source: source, revision: revision,
            source_signature: source_signature, source_snapshot: source_snapshot,
            other_editor: other_editor
          }
        end

        if candidates.empty?
          refresh_dialog
          if notify
            message = failed.empty? ? '全部空间均已是最新。' : "没有可更新空间；#{failed.join('；')}"
            show_status(message, failed.empty? ? 'success' : 'error')
          end
          result = { ok: failed.empty?, pending: false, updated: 0, failed: failed }
          invoke_space_batch_completion(completion, result)
          finish_space_batch_update_interaction!(model)
          return result
        end

        token = SecureRandom.hex(8)
        context = {
          token: token,
          model: model,
          state: state,
          candidates: candidates,
          entities_by_id: entities_by_id,
          failed: failed,
          skipped: skipped,
          notify: notify,
          completion: completion,
          started: started
        }
        @space_batch_update_job = context
        Sketchup.set_status_text("LinkHub 正在后台准备 #{candidates.length} 个空间的本地镜像…") rescue nil
        show_status("正在后台准备 #{candidates.length} 个空间的本地镜像；复制期间 SketchUp 界面可继续响应。", 'info') if notify
        mirror_jobs = candidates.map do |row|
          {
            id: row[:item]['id'].to_s,
            key: space_mirror_key(row[:item]),
            source: row[:source],
            revision: row[:revision],
            source_signature: row[:source_signature],
            source_snapshot: row[:source_snapshot]
          }
        end
        started_token = prefetch_space_batch_mirrors_async!(mirror_jobs, model: model) do |mirror_results, prefetch_error|
          schedule_complete_space_models_batch_update!(context, mirror_results, prefetch_error: prefetch_error)
        end
        raise '无法启动空间本地镜像后台任务。' unless started_token
        async_started = true
        { ok: true, pending: true, updated: 0, failed: failed }
      rescue StandardError => e
        finish_space_batch_update_interaction!(model) unless async_started
        raise e
      end
    end

    def update_all_space_models(notify: true, model: Sketchup.active_model, collection_key: nil)
      result = update_space_models_batch(notify: notify, model: model, collection_key: collection_key)
      result[:ok] == true
    end

    def hard_finish_quick_action(model = Sketchup.active_model)
      state = load_state(model)
      host_key = host_discipline_for(state)
      raise '请先切换到硬装或软装工作区。' unless space_workspace_role?(host_key)
      # 顶部主按钮在状态层显示“发布当前空间”时，执行层也必须锁定到同一个当前编辑空间。
      # 否则退出到世界根后若选中了另一个空间，或本机同时保留多个未发布会话，旧逻辑会
      # 改去编辑选中空间/要求重新选择，出现“按钮写发布 A，点击却处理 B”的交叉状态错位。
      active_item = current_soft_designer_fab_space(model)
      return publish_space_now(active_item['id'], model) if active_item && space_record_collection_key(active_item) == host_key
      selected = selected_managed_space_record(state, model)
      if selected
        return publish_space_now(selected['id'], model) if local_pending_space?(selected, state, model)
        return edit_space_model_with_workspace_prompt(selected['id'], model)
      end
      pending = local_pending_space_records(state, model).select { |row| space_record_collection_key(row) == host_key }
      return publish_space_now(pending.first['id'], model) if pending.length == 1
      raise "当前#{space_collection_label(host_key)}工作区有 #{pending.length} 个空间待发布，请先在视口中选中目标空间。" if pending.length > 1
      paused = paused_space_edit_records(state).select { |row| space_record_collection_key(row) == host_key }.sort_by { |row| row['edit_safe_paused_at'].to_s }.last
      return edit_space_model(paused['id']) if paused
      update_all_space_models(notify: true, model: model, collection_key: host_key)
    end

    def collaboration_connection_info(state = nil, model = Sketchup.active_model)
      state = load_state(model) unless state.is_a?(Hash)
      raw_dir = state['collab_project_dir'].to_s.strip
      raw_json = state['collab_project_json'].to_s.strip
      if raw_dir.empty? && raw_json.empty?
        return {
          'connected' => false, 'valid' => false, 'stage' => 'connect',
          'project_dir' => '', 'json_path' => '',
          'message' => '请连接项目协同.json，或者新建项目', 'error' => ''
        }
      end

      json_path = resolve_collab_json_value(raw_json, model)
      if json_path.empty?
        dir = resolve_collab_dir_value(raw_dir, model)
        json_path = project_collab_json_for_dir(dir) unless dir.empty?
      end
      project_dir = json_path.empty? ? resolve_collab_dir_value(raw_dir, model) : File.dirname(json_path)
      unless !json_path.empty? && File.file?(json_path)
        return {
          'connected' => false, 'valid' => false, 'stage' => 'connect',
          'project_dir' => project_dir.to_s, 'json_path' => json_path.to_s,
          'message' => '项目连接已失效，请重新连接协同.json', 'error' => '协同.json 不存在或网络位置不可用'
        }
      end

      signature = [FastPath.expand(json_path), File.size(json_path), File.mtime(json_path).to_f]
      @collab_connection_validation_cache ||= {}
      cached = @collab_connection_validation_cache[signature]
      valid = cached == true ? true : project_collab_manifest_file?(json_path)
      # 只缓存成功校验。网络盘瞬时读失败不能永久把一个正确项目记成无效；
      # 失败状态会在下一次低频连接检查时自动重试。
      @collab_connection_validation_cache = valid ? { signature => true } : {}
      unless valid
        return {
          'connected' => false, 'valid' => false, 'stage' => 'connect',
          'project_dir' => project_dir.to_s, 'json_path' => json_path.to_s,
          'message' => '当前 JSON 不是有效的 LinkHub 项目', 'error' => '请选择项目根目录中的协同.json'
        }
      end

      role = state['host_discipline'].to_s
      configured = state['workspace_configured'] == true && WORKSPACE_ROLES.include?(role)
      {
        'connected' => true, 'valid' => true,
        'stage' => configured ? 'ready' : 'workspace',
        'workspace_configured' => configured,
        'workspace_role' => configured ? role : '',
        'project_dir' => FastPath.expand(project_dir),
        'json_path' => FastPath.expand(json_path),
        'message' => configured ? '项目与工作区已就绪' : '请选择当前文件所属工作区',
        'error' => ''
      }
    rescue StandardError => e
      {
        'connected' => false, 'valid' => false, 'stage' => 'connect',
        'project_dir' => '', 'json_path' => '',
        'message' => '无法验证项目连接，请重新连接协同.json', 'error' => e.message.to_s
      }
    end

    # v0.13.6.146：纯本机选择帧专用连接快照。它不碰 File.file?/mtime/size，
    # 因为 SMB/NAS 一次状态查询就可能把 SketchUp 主线程阻塞数秒。真正执行发布、更新、
    # 载入、连接设置时仍走 collaboration_connection_info 的完整权威校验。
    def collaboration_connection_info_fast(state = nil, model = Sketchup.active_model)
      state = cached_project_state_readonly(model) || load_state(model) unless state.is_a?(Hash)
      raw_dir = state['collab_project_dir'].to_s.strip
      raw_json = state['collab_project_json'].to_s.strip
      if raw_dir.empty? && raw_json.empty?
        return {
          'connected' => false, 'valid' => false, 'stage' => 'connect',
          'project_dir' => '', 'json_path' => '',
          'message' => '请连接项目协同.json，或者新建项目', 'error' => ''
        }
      end
      project_dir = begin
        if !raw_dir.empty?
          resolve_collab_dir_value(raw_dir, model).to_s
        elsif !raw_json.empty?
          resolved = resolve_collab_json_value(raw_json, model).to_s
          resolved.empty? ? '' : File.dirname(resolved)
        else
          ''
        end
      rescue StandardError
        raw_dir
      end
      role = state['host_discipline'].to_s
      configured = state['workspace_configured'] == true && WORKSPACE_ROLES.include?(role)
      {
        'connected' => true, 'valid' => true,
        'stage' => configured ? 'ready' : 'workspace',
        'workspace_configured' => configured,
        'workspace_role' => configured ? role : '',
        'project_dir' => project_dir.to_s,
        'json_path' => raw_json,
        'message' => configured ? '项目与工作区已就绪' : '请选择当前文件所属工作区',
        'error' => ''
      }
    rescue StandardError
      { 'connected' => true, 'valid' => true, 'stage' => 'ready', 'project_dir' => '', 'json_path' => '', 'message' => '', 'error' => '' }
    end

    def workspace_ready?(state = nil, model = Sketchup.active_model)
      collaboration_connection_info(state, model)['stage'] == 'ready'
    rescue StandardError
      false
    end

    # 高频模型观察器只检查保存在当前 SKP 内的选择结果，绝不在每次移动、缩放、
    # Undo 或 0.55 秒锁定轮询时访问网络盘。真正的 JSON 存在性和格式校验由
    # 抽屉刷新及 3 秒协同监视器承担。
    def workspace_selection_configured?(state = nil, model = Sketchup.active_model)
      state = cached_project_state_readonly(model) || load_state(model) unless state.is_a?(Hash)
      role = state['host_discipline'].to_s
      location_present = !state['collab_project_json'].to_s.strip.empty? || !state['collab_project_dir'].to_s.strip.empty?
      state['workspace_configured'] == true && WORKSPACE_ROLES.include?(role) && location_present
    rescue StandardError
      false
    end

    # 原生锁定监视器每 0.55 秒运行，但项目 JSON 只允许最多每 3 秒验证一次。
    # 这样网络盘断开后会在数秒内停用业务监视，同时不会把网络 I/O 塞进建模帧。
    def workspace_connection_valid_cached?(model = Sketchup.active_model, max_age: 3.0)
      return false unless model
      @workspace_connection_ready_cache ||= {}
      key = model.object_id
      now = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      record = @workspace_connection_ready_cache[key]
      if record.is_a?(Hash) && now - record[:checked_at].to_f < [max_age.to_f, 0.0].max
        return record[:valid] == true
      end
      valid = workspace_ready?(nil, model)
      @workspace_connection_ready_cache[key] = { checked_at: now, valid: valid }
      valid
    rescue StandardError
      false
    end

    def invalidate_workspace_connection_cache!(model = nil)
      @workspace_connection_ready_cache ||= {}
      if model
        @workspace_connection_ready_cache.delete(model.object_id)
      else
        @workspace_connection_ready_cache.clear
      end
      true
    rescue StandardError
      false
    end

    def require_workspace_ready!(state = nil, model = Sketchup.active_model)
      info = collaboration_connection_info(state, model)
      case info['stage']
      when 'ready'
        true
      when 'workspace'
        raise '项目已连接，请先选择当前工作区：建筑、硬装、软装或景观。'
      else
        detail = info['error'].to_s.empty? ? info['message'].to_s : "#{info['message']}（#{info['error']}）"
        raise detail
      end
    end

    def reset_workspace_selection!(state)
      state['host_discipline'] = 'coordination'
      state['workspace_configured'] = false
      invalidate_workspace_connection_cache!
      state
    end

    def workspace_drawer_status_color(code)
      case code.to_s
      when 'current' then [35, 174, 102]
      when 'pending', 'waiting' then [230, 145, 38]
      when 'editing', 'locked' then [135, 86, 214]
      when 'syncing' then [67, 126, 235]
      when 'error' then [222, 77, 77]
      else [112, 122, 138]
      end
    end

    def selected_workspace_space_record(state, model = Sketchup.active_model)
      return nil unless state.is_a?(Hash) && model
      return nil unless model.active_path.nil?
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      host_role = host_discipline_for(state)
      Array(state['space_models']).find do |space|
        next false if space_workspace_role?(host_role) && space_record_collection_key(space) != host_role
        root = space_model_entity(space['id'], model)
        root && root.valid? && root == entity
      end
    rescue StandardError
      nil
    end

    # 精确识别根层级唯一选中的任意受管硬装/软装空间，不按当前工作区过滤。
    # 只用于“跨工作区导航/发布”入口；代真切换等专业内功能继续使用
    # selected_workspace_space_record，避免扩大既有作用域。
    def selected_managed_space_record(state, model = Sketchup.active_model)
      return nil unless state.is_a?(Hash) && model
      return nil unless model.active_path.nil?
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      Array(state['space_models']).find do |space|
        role = space_record_collection_key(space)
        next false unless space_workspace_role?(role)
        root = space_model_entity(space['id'], model)
        root && root.valid? && root == entity
      end
    rescue StandardError
      nil
    end

    def architecture_model_update_direction(item, entity, model = Sketchup.active_model)
      source = auto_relocate(item['model_path'].to_s, model)
      return :missing unless File.file?(source)
      return :newer unless entity && entity.valid?
      remote = fast_file_signature(source)
      local = entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s
      local = item['last_signature'].to_s if local.empty?
      return :same if !remote.empty? && normalize_fast_signature(remote) == normalize_fast_signature(local)
      :newer
    rescue StandardError
      :unknown
    end

    def architecture_drawer_collection_state(state, model = Sketchup.active_model, detailed: true)
      return [[], []] unless detailed
      sync_architecture_models_from_manifest!(state, model)
      retire_legacy_architecture_runtime_state!(state, model)
      clear_orphan_architecture_background_publish_states!(state, model)
      rows = Array(state['architecture_models']).map do |item|
        entity = architecture_model_entity(item['id'], model)
        source = auto_relocate(item['model_path'].to_s, model)
        exists = File.file?(source)
        loaded = !!(entity && entity.valid?)
        background_publish = architecture_background_publish_active?(item['id'])
        background_job = background_publish_job_snapshot("architecture_model:#{item['id']}")
        initial_publish_pending = item['initial_publish_pending'] == true
        lock = exists ? space_lock_info(item, model, source_path: source, state: state) : { 'exists' => false, 'owned' => false, 'same_user' => false, 'stale' => false }
        local_hint = item['editing'] || space_edit_safe_paused?(item) ||
                     state['architecture_editing_id'].to_s == item['id'].to_s ||
                     (entity && entity.valid? && (entity.get_attribute(ENTITY_DICT, 'editing', false) || !entity_native_locked?(entity)))
        editing_self = lock['exists'] && !lock['stale'] && lock['owned'] && (local_hint || lock['process_owned'])
        recoverable_self_lock = lock['exists'] && !lock['stale'] && !lock['owned'] && lock['same_user_recoverable'] == true
        editing_other = lock['exists'] && !lock['stale'] && !lock['owned'] && !recoverable_self_lock
        direction = architecture_model_update_direction(item, entity, model)
        status_code = if background_publish
                        'waiting'
                      elsif initial_publish_pending
                        item['initial_publish_error'].to_s.empty? ? 'waiting' : 'error'
                      elsif editing_self || editing_other
                        'editing'
                      elsif recoverable_self_lock
                        'waiting'
                      elsif !exists || direction == :unknown
                        'error'
                      elsif direction == :newer || !loaded
                        'pending'
                      else
                        'current'
                      end
        status = if background_publish
                   "发布 #{background_job['progress'].to_i}% · #{background_job['stage_label']}"
                 elsif initial_publish_pending
                   item['initial_publish_error'].to_s.empty? ? '首次发布待完成' : '首次发布失败 · 可重试'
                 elsif editing_self
                   '待发布 · 修改中'
                 elsif recoverable_self_lock
                   '本人遗留占用'
                 elsif editing_other
                   owner = [lock['owner'], lock['host']].reject(&:empty?).join('@')
                   "修改中 · #{owner.empty? ? '其他成员' : owner}"
                 elsif !exists
                   '协同建筑文件缺失'
                 elsif !loaded
                   '待载入'
                 elsif direction == :newer
                   '待更新'
                 else
                   '已更新'
                 end
        action = if background_publish
                   "drawer_architecture_model_disabled:#{item['id']}"
                 elsif initial_publish_pending
                   "drawer_architecture_model_publish:#{item['id']}"
                 elsif editing_self
                   "drawer_architecture_model_publish:#{item['id']}"
                 elsif recoverable_self_lock
                   "drawer_architecture_model_edit:#{item['id']}"
                 elsif editing_other
                   "drawer_architecture_model_update:#{item['id']}"
                 elsif !exists
                   "drawer_architecture_model_disabled:#{item['id']}"
                 elsif !loaded
                   "drawer_architecture_model_update:#{item['id']}"
                 elsif direction == :newer
                   "drawer_architecture_model_update:#{item['id']}"
                 else
                   "drawer_architecture_model_edit:#{item['id']}"
                 end
        label = if background_publish
                  '队列'
                elsif initial_publish_pending
                  item['initial_publish_error'].to_s.empty? ? '发布' : '重试'
                elsif editing_self
                  '发布'
                elsif recoverable_self_lock
                  '恢复'
                elsif editing_other
                  '上版'
                elsif !exists
                  '缺失'
                elsif !loaded
                  '载入'
                elsif direction == :newer
                  '更新'
                else
                  '修改'
                end
        group = Array(state['architecture_groups']).find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
        display_name = group ? "#{group['name']}:#{item['name']}" : "##{item['number']}.#{item['name']}"
        visible = loaded && !entity.hidden? && state['architecture_collection_hidden'] != true
        {
          'kind' => 'architecture_model',
          'id' => item['id'].to_s,
          'number' => item['number'].to_i,
          'raw_name' => item['name'].to_s,
          'name' => display_name,
          'group_id' => item['group_id'].to_s,
          'group_order' => item['group_order'].to_i,
          'status_code' => status_code,
          'status' => status,
          'last_update' => item['last_update'].to_s,
          'loaded' => loaded,
          'editing' => editing_self || editing_other || recoverable_self_lock,
          'editing_by_self' => editing_self,
          'editing_by_other' => editing_other,
          'edit_same_user' => lock['same_user'] == true,
          'edit_self_recoverable' => recoverable_self_lock,
          'color' => workspace_drawer_status_color(status_code),
          'action' => action,
          'action_label' => label,
          'tooltip' => editing_self ? '发布当前建筑模型' : (recoverable_self_lock ? '恢复本人上次中断的建筑协作编辑' : (editing_other ? '载入对方修改前的上一发布版' : (label == '修改' ? '取得占用并进入建筑模型' : (label == '载入' ? '将这个建筑模型载入当前工作 SU' : '载入建筑模型当前发布版')))),
          'enabled' => !background_publish && (exists || editing_self || recoverable_self_lock || initial_publish_pending),
          'release_occupancy_action' => (recoverable_self_lock ? "drawer_architecture_model_release:#{item['id']}" : ''),
          'release_occupancy_tooltip' => '仅回收已经中断的本人建筑遗留占用；当前活动编辑请使用发布或取消修改结束',
          'resident_action' => (loaded ? "drawer_architecture_model_unload:#{item['id']}" : ''),
          'resident_tooltip' => (loaded ? '卸载这个建筑模型；点击后会再次确认。只影响当前工作 SU，不删除共享文件、不影响其他成员' : ''),
          'resident_enabled' => !editing_self && !background_publish,
          'resident_loaded' => loaded,
          'visibility_action' => "drawer_architecture_model_visibility:#{item['id']}",
          'visibility_enabled' => loaded && !editing_self && !background_publish,
          'visibility_tooltip' => visible ? '隐藏这个建筑模型' : '显示这个建筑模型',
          'visible' => visible,
          'manage_selectable' => !(editing_self || editing_other || background_publish || initial_publish_pending),
          'manage_can_rename' => !(editing_self || editing_other || background_publish || initial_publish_pending),
          'manage_can_delete' => !(editing_self || editing_other || background_publish),
          'manage_can_group' => !(editing_self || editing_other || background_publish || initial_publish_pending)
        }
      end
      groups = Array(state['architecture_groups']).sort_by { |group| group['order'].to_i }.map do |group|
        members = rows.select { |row| row['group_id'].to_s == group['id'].to_s }
        loaded_members = members.select { |row| row['loaded'] == true }
        visible_count = loaded_members.count { |row| row['visible'] == true }
        suspended = !!group['visibility_suspended']
        group.merge(
          'kind' => 'architecture_group',
          'count' => members.length,
          'member_statuses' => members.map { |row| row['status_code'].to_s },
          'visible' => !suspended && visible_count.positive?,
          'visibility_enabled' => !loaded_members.empty?,
          'visibility_tooltip' => suspended ? '恢复组内上次可见的建筑模型' : '隐藏组内当前可见建筑模型',
          'visible_count' => visible_count,
          'loaded_count' => loaded_members.length
        )
      end
      [rows, groups]
    rescue StandardError => e
      log_exception('构建建筑多模型抽屉状态失败', e)
      [[], []]
    end

    # v0.13.1：顶部“发布”只能由明确的本机修改会话驱动。仅选中、仅存在同用户名锁、
    # 或根组件偶然处于解锁状态都不能被推断为待发布，避免跨专业选择后定时刷新把铅笔误变成上传。
    def explicit_local_pending_space?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      return false unless item['editing'] == true || space_edit_safe_paused?(item)
      entity = space_model_entity(item['id'], model)
      return false unless entity && entity.valid?
      return false if entity_native_locked?(entity) && !space_edit_safe_paused?(item)
      token = item['edit_lock_token'].to_s
      return false if token.empty?
      source = auto_relocate(item['model_path'].to_s, model)
      lock = source.to_s.empty? ? { 'exists' => false } : space_lock_info(item, model, source_path: source, state: state)
      return false unless lock['exists'] && !lock['stale'] && lock['process_owned']
      return false unless lock['token'].to_s == token
      local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) || entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      local_attribute || space_edit_safe_paused?(item)
    rescue StandardError
      false
    end

    def explicit_local_pending_architecture?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      return false unless item['editing'] == true || space_edit_safe_paused?(item)
      entity = architecture_model_entity(item['id'], model)
      return false unless entity && entity.valid?
      return false if entity_native_locked?(entity) && !space_edit_safe_paused?(item)
      token = item['edit_lock_token'].to_s
      return false if token.empty?
      source = auto_relocate(item['model_path'].to_s, model)
      lock = source.to_s.empty? ? { 'exists' => false } : space_lock_info(item, model, source_path: source, state: state)
      return false unless lock['exists'] && !lock['stale'] && lock['process_owned']
      return false unless lock['token'].to_s == token
      local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) || entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      local_attribute || space_edit_safe_paused?(item)
    rescue StandardError
      false
    end

    # v0.13.6.146：选择热路径只做当前 SKP 内的会话判断，不读取共享锁文件。
    # 顶部名称只是提示“本会话有哪些待发布对象”；真正发布/继续编辑仍会执行完整锁校验。
    def explicit_local_pending_space_fast?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      return false unless item['editing'] == true || space_edit_safe_paused?(item) || item['publish_pending'] == true
      return false if item['edit_lock_token'].to_s.empty? && !space_edit_safe_paused?(item)
      local_space_edit_session?(item, state, model)
    rescue StandardError
      false
    end

    def explicit_local_pending_architecture_fast?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      return false unless item['editing'] == true || space_edit_safe_paused?(item) || item['publish_pending'] == true
      return false if item['edit_lock_token'].to_s.empty? && !space_edit_safe_paused?(item)
      local_architecture_model_edit_session?(item, state, model)
    rescue StandardError
      false
    end

    def local_pending_space_records_fast(state, model = Sketchup.active_model)
      Array(state['space_models']).select { |item| explicit_local_pending_space_fast?(item, state, model) }
    rescue StandardError
      []
    end

    def local_pending_architecture_records_fast(state, model = Sketchup.active_model)
      Array(state['architecture_models']).select { |item| explicit_local_pending_architecture_fast?(item, state, model) }
    rescue StandardError
      []
    end

    def local_pending_space_records(state, model = Sketchup.active_model)
      Array(state['space_models']).select { |item| explicit_local_pending_space?(item, state, model) }
    rescue StandardError
      []
    end

    def local_pending_architecture_records(state, model = Sketchup.active_model)
      Array(state['architecture_models']).select { |item| explicit_local_pending_architecture?(item, state, model) }
    rescue StandardError
      []
    end

    def local_pending_space?(item, state, model = Sketchup.active_model)
      explicit_local_pending_space?(item, state, model)
    rescue StandardError
      false
    end

    def local_pending_architecture?(item, state, model = Sketchup.active_model)
      explicit_local_pending_architecture?(item, state, model)
    rescue StandardError
      false
    end

    # 顶部名称用于“当前操作对象/待发布对象”的轻量提示。
    # 属于分组时显示“组名:空间名”（例如 B1:一层大厅），这样既能知道楼层/组，
    # 又不会丢失当前具体空间；没有分组时仍显示“序号:空间名”。
    def quick_unit_display_name(item, kind, state)
      return '' unless item.is_a?(Hash)
      raw_name = item['name'].to_s.strip
      case kind.to_s
      when SPACE_COLLECTION_KEY, SOFT_SPACE_COLLECTION_KEY, 'interior', 'space'
        group = Array(state['space_groups']).find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
        group_name = group && !group['name'].to_s.strip.empty? ? group['name'].to_s.strip : ''
        group_name.empty? ? "#{item['number']}:#{raw_name}" : "#{group_name}:#{raw_name}"
      when 'architecture'
        group = Array(state['architecture_groups']).find { |candidate| candidate['id'].to_s == item['group_id'].to_s }
        group_name = group && !group['name'].to_s.strip.empty? ? group['name'].to_s.strip : ''
        group_name.empty? ? "#{item['number']}:#{raw_name}" : "#{group_name}:#{raw_name}"
      else
        raw_name
      end
    rescue StandardError
      item['name'].to_s
    end

    def quick_unit_actual_name(item, kind)
      return '' unless item.is_a?(Hash)
      case kind.to_s
      when SPACE_COLLECTION_KEY, SOFT_SPACE_COLLECTION_KEY, 'interior', 'space'
        "#{item['number']}:#{item['name']}"
      when 'architecture'
        "#{item['number']}:#{item['name']}"
      else
        item['name'].to_s
      end
    rescue StandardError
      item['name'].to_s
    end

    def quick_profession_prefix(kind, host_key)
      discipline = kind.to_s
      discipline = SPACE_COLLECTION_KEY if %w[space interior].include?(discipline)
      return '' if discipline == host_key.to_s
      case discipline
      when 'architecture' then '(建筑)'
      when SPACE_COLLECTION_KEY then '(硬装)'
      when SOFT_SPACE_COLLECTION_KEY then '(软装)'
      when 'landscape' then '(景观)'
      else ''
      end
    end

    def quick_context_status(state, host_key, selected_space, selected_architecture, model = Sketchup.active_model, fast: false)
      rows = []
      details = []
      seen = {}

      add_row = lambda do |item, kind, pending, selected = false|
        next unless item.is_a?(Hash)
        display = quick_unit_display_name(item, kind, state)
        next if display.to_s.empty?
        prefix = quick_profession_prefix(kind, host_key)
        text = "#{prefix}#{display}"
        text += ' · 待发布' if pending
        # 组名与具体空间名一起显示，因此同组多个待发布空间也分别保留，不再合并成一个组名。
        key = [kind.to_s, text].join('|')
        unless seen[key]
          rows << text
          seen[key] = true
        end
        actual = quick_unit_actual_name(item, kind)
        detail_prefix = quick_profession_prefix(kind, host_key)
        detail = "#{detail_prefix}#{actual}"
        detail += ' · 待发布' if pending
        details << detail unless details.include?(detail)
      end

      selected_kind = nil
      selected_item = nil
      if selected_space
        selected_kind = space_record_collection_key(selected_space)
        selected_item = selected_space
      elsif selected_architecture
        selected_kind = 'architecture'
        selected_item = selected_architecture
      end

      if selected_item
        selected_pending = if space_workspace_role?(selected_kind)
                             fast ? explicit_local_pending_space_fast?(selected_item, state, model) : local_pending_space?(selected_item, state, model)
                           else
                             fast ? explicit_local_pending_architecture_fast?(selected_item, state, model) : local_pending_architecture?(selected_item, state, model)
                           end
        add_row.call(selected_item, selected_kind, selected_pending, true)
      end

      space_pending = fast ? local_pending_space_records_fast(state, model) : local_pending_space_records(state, model)
      architecture_pending = fast ? local_pending_architecture_records_fast(state, model) : local_pending_architecture_records(state, model)
      space_selected_id = selected_space ? selected_space['id'].to_s : ''
      architecture_selected_id = selected_architecture ? selected_architecture['id'].to_s : ''
      space_focus_id = state['space_editing_id'].to_s
      architecture_focus_id = state['architecture_editing_id'].to_s
      space_pending.sort_by! { |item| [item['id'].to_s == space_selected_id ? 0 : (item['id'].to_s == space_focus_id ? 1 : 2), item['number'].to_i, item['name'].to_s] }
      architecture_pending.sort_by! { |item| [item['id'].to_s == architecture_selected_id ? 0 : (item['id'].to_s == architecture_focus_id ? 1 : 2), item['number'].to_i, item['name'].to_s] }
      hard_pending = space_pending.select { |pending_item| space_record_collection_key(pending_item) == SPACE_COLLECTION_KEY }
      soft_pending = space_pending.select { |pending_item| space_record_collection_key(pending_item) == SOFT_SPACE_COLLECTION_KEY }
      ordered_sets = if host_key.to_s == 'architecture'
                       [['architecture', architecture_pending], [SPACE_COLLECTION_KEY, hard_pending], [SOFT_SPACE_COLLECTION_KEY, soft_pending]]
                     elsif host_key.to_s == SOFT_SPACE_COLLECTION_KEY
                       [[SOFT_SPACE_COLLECTION_KEY, soft_pending], [SPACE_COLLECTION_KEY, hard_pending], ['architecture', architecture_pending]]
                     else
                       [[SPACE_COLLECTION_KEY, hard_pending], [SOFT_SPACE_COLLECTION_KEY, soft_pending], ['architecture', architecture_pending]]
                     end
      ordered_sets.each do |kind, items|
        items.each { |pending_item| add_row.call(pending_item, kind, true) }
      end

      return ['', '', 0.0] if rows.empty?
      shown = rows.length > 3 ? rows.first(3).join('　') + "　+#{rows.length - 3}" : rows.join('　')
      tooltip = details.empty? ? rows.join('　') : details.join('　')
      # 顶部名称胶囊按实际文字长度收缩；只保留约 8px 的左右呼吸边距。
      # 中文按微软雅黑 11px 的视觉宽度估算，ASCII 单独收窄，避免短名称留下大片灰底。
      width = 16.0 + shown.each_char.sum { |ch| ch.ascii_only? ? 5.8 : 10.4 }
      [shown, tooltip, [[width, 34.0].max, 390.0].min]
    rescue StandardError
      ['', '', 0.0]
    end

    def workspace_toolbar_state(model = Sketchup.active_model, detailed: false, state: nil, selection_fast: false)
      state = state.is_a?(Hash) ? state : (detailed ? public_state : (selection_fast ? (cached_project_state_readonly(model) || load_state(model)) : load_state(model)))
      # v0.13.6.146：SelectionObserver 是建模热路径。单击对象时绝不能为了重绘顶部按钮
      # 去 File.stat 协同.json / 插件更新清单 / NAS。完整连接校验由 20 秒 presence monitor、
      # 抽屉刷新和真正的发布/更新动作承担；选择帧只相信当前 SKP 已保存的工作区配置。
      onboarding = selection_fast ? collaboration_connection_info_fast(state, model) : collaboration_connection_info(state, model)
      project_label = onboarding['connected'] ? File.basename(onboarding['project_dir'].to_s.tr('\\', '/')) : ''
      if selection_fast
        previous_toolbar = (@workspace_toolbar_last_good_state || {})[model.object_id]
        plugin_update = {
          available: previous_toolbar.is_a?(Hash) && previous_toolbar['drawer_plugin_update_available'] == true,
          version: previous_toolbar.is_a?(Hash) ? previous_toolbar['drawer_plugin_update_version'].to_s : '',
          error: previous_toolbar.is_a?(Hash) ? previous_toolbar['drawer_plugin_update_error'].to_s : ''
        }
      else
        plugin_update = onboarding['connected'] ? plugin_update_status(model) : { available: false, version: '', error: '' }
      end
      backup_dir = if selection_fast && previous_toolbar.is_a?(Hash)
                     previous_toolbar['drawer_backup_dir'].to_s
                   else
                     architecture_backup_directory
                   end
      backup_dir_exists = if selection_fast
                            previous_toolbar.is_a?(Hash) ? previous_toolbar['drawer_backup_dir_exists'] == true : false
                          else
                            Dir.exist?(backup_dir)
                          end
      backup_interval = if selection_fast && previous_toolbar.is_a?(Hash)
                          previous_toolbar['drawer_backup_interval_minutes'].to_i
                        else
                          architecture_backup_interval_minutes
                        end
      unless onboarding['stage'] == 'ready'
        return {
          'visible' => true,
          'quick_toolbar_visible' => false,
          'publish_queue_jobs' => task_center_snapshot,
          'publish_queue_active_count' => task_center_active_count,
          'drawer_stage' => onboarding['stage'],
          'drawer_message' => onboarding['message'].to_s,
          'drawer_error' => onboarding['error'].to_s,
          'drawer_context' => onboarding['stage'] == 'workspace' ? '请选择工作区' : '尚未连接项目',
          'drawer_items' => [],
          'drawer_architecture_groups' => [],
          'drawer_architecture_models' => [],
          'drawer_groups' => [],
          'drawer_spaces' => [],
          'professional_section_collapsed' => {},
          'drawer_project_connected' => onboarding['connected'] == true,
          'drawer_workspace_configured' => false,
          'drawer_project_label' => project_label,
          'drawer_selection_count' => model.selection.length,
          'drawer_space_loaded_count' => 0,
          'drawer_space_hidden' => false,
          'display_mode' => 'proxy',
          'drawer_backup_dir' => backup_dir.to_s,
          'drawer_backup_dir_exists' => backup_dir_exists == true,
          'drawer_backup_interval_minutes' => backup_interval.to_i,
          'drawer_project_dir' => onboarding['project_dir'].to_s,
          'drawer_model_path' => model.path.to_s,
          'drawer_plugin_update_available' => plugin_update[:available] == true,
          'drawer_plugin_update_version' => plugin_update[:version].to_s,
          'drawer_plugin_update_error' => plugin_update[:error].to_s,
          'drawer_log_path' => LOG_PATH
        }
      end
      unless selection_fast
        clear_orphan_managed_discipline_background_publish_state!(state, 'architecture', model)
        clear_orphan_managed_discipline_background_publish_state!(state, 'landscape', model)
      end
      item = selection_fast ? current_soft_designer_fab_space_fast(state, model) : current_soft_designer_fab_space(model)
      space_inside = !!(item && space_edit_context_active?(item, model))
      unless detailed || selection_fast
        refresh_landscape_collab_entry!(state, model)
      end
      architecture_link = state.dig('links', 'architecture') || {}
      architecture_paused = managed_edit_safe_paused?(architecture_link)
      architecture_editing = if selection_fast
                               Array(state['architecture_models']).any? { |row| local_architecture_model_edit_session?(row, state, model) }
                             else
                               architecture_local_edit_active?(state, model)
                             end
      if detailed || selection_fast
        architecture_pending = architecture_link['architecture_update_required'] == true
        landscape_link_for_pending = state.dig('links', 'landscape') || {}
        landscape_pending = landscape_link_for_pending['landscape_update_required'] == true
      else
        architecture_pending = architecture_remote_pending?(state, model)
        landscape_pending = landscape_remote_pending?(state, model)
      end
      architecture_path = resolve_path(
        architecture_link['collab_full_path'].to_s.empty? ? architecture_link['model_path'].to_s : architecture_link['collab_full_path'].to_s,
        model
      )
      architecture_source_ready = selection_fast ? (architecture_link['model_exists'] == true || !architecture_link['last_signature'].to_s.empty? || !architecture_link['source_signature'].to_s.empty?) : File.file?(architecture_path)
      architecture_managed_instance = managed_model_instance_for('architecture', model)
      # 对本专业而言，“共享 FULL 已存在”不等于“本机首次发布接管已经完成”。
      # 只有受管标记或受管根实例真实存在，才切换到下载/修改流程。
      architecture_takeover_complete = architecture_link['architecture_collab_managed'] == true ||
                                       !!architecture_managed_instance
      # 重新连接协同.json 时，只要共享端已有建筑 FULL，就必须先下载接管，
      # 不能把空白工作文件误判为“首次发布”。只有共享端确实没有建筑模型时，
      # 才允许当前建筑工作区进入首次发布流程。
      architecture_remote_bootstrap = host_discipline_for(state) == 'architecture' && !architecture_takeover_complete && architecture_source_ready
      architecture_publish_source = host_discipline_for(state) == 'architecture' && !architecture_takeover_complete && !architecture_source_ready
      architecture_work_model = host_work_model_entity(state, 'architecture', model)
      architecture_selected_work_model = strict_selected_host_work_model_entity(model)
      architecture_publish_ready = !!architecture_work_model || !!architecture_selected_work_model
      architecture_action = if architecture_paused
                              'resume'
                            elsif architecture_editing
                              'publish'
                            elsif architecture_publish_source
                              'publish'
                            elsif architecture_pending
                              'update'
                            else
                              'update'
                            end
      architecture_enabled = architecture_editing || (architecture_publish_source && architecture_publish_ready) || architecture_pending || architecture_source_ready
      paused_space = paused_space_edit_record(state)
      hard_action = item ? 'publish' : (paused_space ? 'resume' : 'update')
      hard_enabled = !!item || !!paused_space || !Array(state['space_models']).empty?
      project_dir = selected_collab_project_dir_for_state(state, model)
      relevant = !!item || architecture_editing || !managed_model_entities(model).empty? || !Array(state['space_models']).empty? ||
                 (!project_dir.to_s.empty? && (selection_fast || File.file?(project_collab_json_for_dir(project_dir))))
      references_supported = host_discipline_for(state) != 'coordination' &&
                             (space_inside || !workspace_other_reference_entities(state, model).empty?)
      host_key = host_discipline_for(state)
      relevant = true if space_workspace_role?(host_key)
      host_label = host_key == 'coordination' ? '协调总模' : DISCIPLINES.dig(host_key, 'name').to_s
      host_label = '硬装' if host_key == SPACE_COLLECTION_KEY
      host_label = '软装' if host_key == SOFT_SPACE_COLLECTION_KEY
      host_label = '未选择工作区' if host_label.empty?
      active_space_collection_key = space_workspace_role?(host_key) ? host_key : SPACE_COLLECTION_KEY
      active_space_collection_label = space_collection_label(active_space_collection_key)
      spaces = spaces_for_collection(state, active_space_collection_key)
      architecture_status = if architecture_paused
                              '未发布修改已暂存'
                            elsif detailed && !architecture_link['status_label'].to_s.empty?
                              architecture_link['status_label'].to_s
                            elsif architecture_editing
                              '我在修改'
                            elsif architecture_link['source_locked_by_other']
                              '其他成员占用'
                            elsif architecture_remote_bootstrap
                              '待获取最新建筑'
                            elsif architecture_publish_source
                              '待首次发布'
                            elsif architecture_pending
                              '有更新'
                            elsif architecture_source_ready
                              '已连接'
                            else
                              '未连接'
                            end
      architecture_color = detailed ? workspace_drawer_status_color(architecture_link['status_code']) : if architecture_editing
                                                                                                          [135, 86, 214]
                                                                                                        elsif architecture_publish_source
                                                                                                          [190, 91, 65]
                                                                                                        elsif architecture_remote_bootstrap
                                                                                                          [47, 111, 205]
                                                                                                        elsif architecture_link['source_locked_by_other'] || architecture_pending
                                                                                                          [230, 145, 38]
                                                                                                        elsif architecture_source_ready
                                                                                                          [35, 174, 102]
                                                                                                        else
                                                                                                          [112, 122, 138]
                                                                                                        end
      hard_status = if item
                      space_inside ? "#{space_ui_label(item)} · 空间内" : "#{space_ui_label(item)} · 编辑中"
                    elsif paused_space
                      "#{paused_space['number']}:#{paused_space['name']} · 未发布修改已暂存"
                    elsif spaces.empty?
                      '待新增空间'
                    else
                      "#{spaces.length} 个空间"
                    end
      hard_color = (item || paused_space) ? [135, 86, 214] : (spaces.empty? ? [112, 122, 138] : [35, 174, 102])
      collection_summary = lambda do |collection_key|
        rows = spaces_for_collection(state, collection_key)
        editing_row = rows.find { |row| row['editing_by_self'] == true || row['editing'] == true }
        paused_row = paused_space_edit_records(state).find { |row| space_record_collection_key(row) == collection_key }
        # “待载入”不等于“有更新”。专业顶栏/收起把手只显示真实协同更新健康度。
        error_count = rows.count { |row| row['status_code'].to_s == 'error' }
        # 顶部黄色只表示“共享端确有新版需要更新”。waiting/locked 属于编辑/占用生命周期，
        # 不能再被误画成“有更新”，否则四专业会在完全同步时长期一起发黄。
        pending_count = rows.count do |row|
          row['status_code'].to_s == 'pending' && row['status_label'].to_s != '待载入'
        end
        lifecycle_count = rows.count { |row| %w[waiting locked editing].include?(row['status_code'].to_s) }
        status = if editing_row
                   "#{editing_row['number']}:#{editing_row['name']} · 修改中"
                 elsif paused_row
                   "#{paused_row['number']}:#{paused_row['name']} · 未发布修改已暂存"
                 elsif error_count.positive?
                   "#{error_count} 个异常 · 共 #{rows.length} 个"
                 elsif pending_count.positive?
                   "#{pending_count} 个待更新 · 共 #{rows.length} 个"
                 elsif lifecycle_count.positive?
                   "#{lifecycle_count} 个编辑/占用状态 · 共 #{rows.length} 个"
                 elsif rows.empty?
                   '待新增空间'
                 else
                   "#{rows.length} 个空间 · 已同步"
                 end
        color = if editing_row || paused_row || lifecycle_count.positive?
                  [135, 86, 214]
                elsif error_count.positive?
                  [222, 77, 77]
                elsif pending_count.positive?
                  [230, 145, 38]
                elsif rows.empty?
                  [112, 122, 138]
                else
                  [35, 174, 102]
                end
        [rows, status, color]
      end
      hard_spaces_summary, hard_collection_status, hard_collection_color = collection_summary.call(SPACE_COLLECTION_KEY)
      soft_spaces_summary, soft_collection_status, soft_collection_color = collection_summary.call(SOFT_SPACE_COLLECTION_KEY)
      landscape_link = state.dig('links', 'landscape') || {}
      landscape_paused = managed_edit_safe_paused?(landscape_link)
      landscape_path = resolve_path(
        landscape_link['collab_full_path'].to_s.empty? ? landscape_link['model_path'].to_s : landscape_link['collab_full_path'].to_s,
        model
      )
      landscape_source_ready = selection_fast ? (landscape_link['model_exists'] == true || !landscape_link['last_signature'].to_s.empty? || !landscape_link['source_signature'].to_s.empty?) : File.file?(landscape_path)
      landscape_editing = landscape_local_edit_active?(state, model)
      # detailed 模式的 public_state 已经计算出唯一 authoritative pending。
      # 旧代码在这里又用轻量文件签名重算一次并覆盖结果，正是“状态有更新，
      # 按钮却显示修改”的直接原因。状态和动作必须共享同一个布尔值。
      landscape_pending = if detailed || selection_fast
                            landscape_link['landscape_update_required'] == true
                          else
                            landscape_remote_pending?(state, model)
                          end
      landscape_managed_instance = managed_model_instance_for('landscape', model)
      landscape_takeover_complete = landscape_link['landscape_collab_managed'] == true ||
                                    !!landscape_managed_instance
      # 景观与建筑保持同一重连规则：共享 FULL 已存在而本机尚未接管时，
      # 显示“获取最新”，而不是首次发布。共享端确实没有景观 FULL 时才是本机原生首次发布。
      landscape_remote_bootstrap = host_key == 'landscape' && !landscape_takeover_complete && landscape_source_ready
      landscape_managed = landscape_takeover_complete || landscape_remote_bootstrap ||
                          (host_key != 'landscape' && !landscape_link['collab_full_path'].to_s.empty? && landscape_source_ready)
      landscape_host_native = host_key == 'landscape' && !landscape_takeover_complete && !landscape_source_ready
      landscape_work_model = host_work_model_entity(state, 'landscape', model)
      landscape_enabled = landscape_link['enabled'] != false && landscape_source_ready && !landscape_host_native
      landscape_raw = landscape_link['status'].to_s
      landscape_status = if landscape_paused
                           '未发布修改已暂存'
                         elsif landscape_editing
                           '我在修改'
                         elsif landscape_link['source_locked_by_other']
                           '其他成员占用'
                         elsif landscape_remote_bootstrap
                           '待获取最新景观'
                         elsif landscape_host_native
                           '待首次发布'
                         elsif landscape_pending
                           '有更新'
                         elsif landscape_link['enabled'] == false
                           '已断开'
                         elsif landscape_link['model_path'].to_s.empty? && landscape_link['collab_full_path'].to_s.empty?
                           '未连接'
                         elsif !landscape_source_ready
                           '文件缺失'
                         elsif landscape_raw.match?(/失败|异常|报错/)
                           '异常'
                         else
                           '已连接'
                         end
      landscape_color = case landscape_status
                        when '异常', '文件缺失' then [222, 77, 77]
                        when '首次发布待完成', '待首次发布' then [190, 91, 65]
                        when '待获取最新景观' then [45, 145, 82]
                        when '待更新', '有更新' then [230, 145, 38]
                        when '已连接' then [35, 174, 102]
                        else [112, 122, 138]
                        end

      if detailed
        landscape_status = landscape_link['status_label'].to_s unless landscape_link['status_label'].to_s.empty?
        landscape_code = landscape_link['status_code'].to_s
        landscape_color = workspace_drawer_status_color(landscape_code)
        if landscape_code == 'waiting'
          landscape_color = landscape_status.match?(/版本|待更新|更新|核对/) ? [230, 145, 38] : [135, 86, 214]
        end
        if landscape_remote_bootstrap
          landscape_status = '待获取最新景观'
          landscape_color = [45, 145, 82]
        elsif landscape_host_native
          landscape_status = '待首次发布'
          landscape_color = [190, 91, 65]
        end
      end

      # public_state 会补充 architecture_collaboration_available / is_host_discipline，
      # 但顶部悬浮条在抽屉收起时使用轻量 load_state。这里必须同时识别持久化字段与
      # 已载入的受管建筑根组件，否则建筑专业在面板关闭时会误判成“未就绪”，铅笔按钮失效。
      architecture_managed = if host_key == 'architecture'
                               architecture_takeover_complete || architecture_remote_bootstrap
                             else
                               architecture_takeover_complete ||
                                 architecture_link['architecture_collaboration_available'] == true ||
                                 (!architecture_link['collab_full_path'].to_s.empty? && architecture_source_ready)
                             end
      architecture_host_native = architecture_publish_source
      if detailed && architecture_remote_bootstrap
        architecture_status = '待获取最新建筑'
        architecture_color = [47, 111, 205]
      elsif detailed && architecture_host_native
        architecture_status = '待首次发布'
        architecture_color = [190, 91, 65]
      end
      architecture_edit_flags = architecture_link['native_editing'] || architecture_link['preview_edit_active'] ||
                                architecture_link['preview_pending_publish'] || architecture_link['edit_session_active']
      architecture_owned_edit = architecture_managed && architecture_link['source_lock_owned'] && architecture_edit_flags
      architecture_interrupted = architecture_managed && !architecture_link['source_locked_by_other'] &&
                                 !architecture_link['source_lock_owned'] && architecture_edit_flags
      architecture_publish_warning = detailed && architecture_action.to_s == 'publish' && architecture_editing && !architecture_paused
      if architecture_publish_warning
        architecture_status = '待发布 · 修改中'
        architecture_color = [205, 78, 82]
      end
      architecture_primary_action = 'drawer_architecture_quick'
      architecture_primary_label = architecture_action == 'publish' ? '发布' : '更新'
      architecture_primary_enabled = architecture_enabled
      architecture_secondary_action = ''
      architecture_secondary_label = ''
      if detailed
        if architecture_link['source_locked_by_other']
          architecture_primary_action = ''
          architecture_primary_label = '占用中'
          architecture_primary_enabled = false
          if architecture_link['model_exists']
            architecture_secondary_action = 'drawer_architecture_previous'
            architecture_secondary_label = '更新上版'
          end
        elsif architecture_paused
          architecture_primary_action = 'drawer_begin_edit:architecture'
          architecture_primary_label = '继续'
          architecture_primary_enabled = true
        elsif architecture_owned_edit
          architecture_primary_action = 'drawer_architecture_quick'
          architecture_primary_label = '发布'
          architecture_primary_enabled = true
        elsif architecture_interrupted
          architecture_primary_action = 'drawer_begin_edit:architecture'
          architecture_primary_label = '恢复'
          architecture_primary_enabled = true
        elsif architecture_host_native
          architecture_primary_action = 'drawer_architecture_quick'
          architecture_primary_label = '发布'
          architecture_primary_enabled = architecture_publish_ready
        elsif architecture_managed && !architecture_link['model_path'].to_s.empty?
          if architecture_link['architecture_update_required'] || !architecture_link['loaded']
            architecture_primary_action = 'drawer_architecture_quick'
            architecture_primary_label = '更新'
          else
            architecture_primary_action = 'drawer_begin_edit:architecture'
            architecture_primary_label = '修改'
          end
          architecture_primary_enabled = true
        elsif architecture_source_ready
          architecture_primary_action = 'drawer_architecture_quick'
          architecture_primary_label = '更新'
          architecture_primary_enabled = true
        else
          architecture_primary_action = ''
          architecture_primary_label = '未连接'
          architecture_primary_enabled = false
        end
      end
      architecture_primary_action = 'drawer_architecture_disabled' if architecture_primary_action.to_s.empty?
      architecture_primary_tooltip = case architecture_primary_label
                                     when '发布'
                                       if architecture_host_native
                                         architecture_source_ready && architecture_work_model ? '共享 FULL 已写出；点击继续完成首次发布接管并直接进入建筑修改' : '首次发布建筑工作模型；成功后保持解锁并直接进入修改'
                                       else
                                         '上传并发布当前建筑修改，完成后释放协作占用'
                                       end
                                     when '继续' then '继续未发布的建筑修改；协作占用和本地内容均保留'
                                     when '修改' then '取得建筑协作占用并自动进入建筑组件'
                                     when '恢复' then '重新取得占用并继续上次中断的建筑修改'
                                     when '更新' then '下载并载入共享建筑的最新发布版本'
                                     when '占用中' then '建筑正由其他成员修改；可使用旁边的历史图标读取上一发布版'
                                     else '建筑尚未连接协同项目'
                                     end

      architecture_instance = architecture_managed_instance
      architecture_visible = if detailed
                               architecture_link['visible'] == true
                             else
                               !!(architecture_instance && (!architecture_instance.respond_to?(:hidden?) || !architecture_instance.hidden?))
                             end
      architecture_visibility_allowed = detailed && architecture_link['loaded'] && !architecture_host_native

      landscape_selected_work_model = strict_selected_host_work_model_entity(model)
      landscape_publish_ready = !!landscape_work_model || !!landscape_selected_work_model
      landscape_edit_flags = landscape_link['native_editing'] || landscape_link['preview_edit_active'] ||
                             landscape_link['preview_pending_publish'] || landscape_link['edit_session_active'] || landscape_editing
      landscape_owned_edit = landscape_managed && landscape_link['source_lock_owned'] && landscape_edit_flags
      landscape_interrupted = landscape_managed && !landscape_link['source_locked_by_other'] &&
                              !landscape_link['source_lock_owned'] && landscape_edit_flags
      landscape_primary_action = 'drawer_landscape_quick'
      landscape_primary_label = if landscape_editing || landscape_host_native
                                  '发布'
                                elsif landscape_pending
                                  '更新'
                                else
                                  '修改'
                                end
      landscape_primary_enabled = landscape_enabled || landscape_editing || (landscape_host_native && landscape_publish_ready)
      if detailed
        if landscape_link['source_locked_by_other']
          landscape_primary_action = 'drawer_landscape_disabled'
          landscape_primary_label = '占用中'
          landscape_primary_enabled = false
        elsif landscape_paused
          landscape_primary_action = 'drawer_begin_edit:landscape'
          landscape_primary_label = '继续'
          landscape_primary_enabled = true
        elsif landscape_owned_edit || landscape_editing
          landscape_primary_action = 'drawer_landscape_quick'
          landscape_primary_label = '发布'
          landscape_primary_enabled = true
        elsif landscape_interrupted
          landscape_primary_action = 'drawer_begin_edit:landscape'
          landscape_primary_label = '恢复'
          landscape_primary_enabled = true
        elsif landscape_host_native
          landscape_primary_action = 'drawer_landscape_quick'
          landscape_primary_label = '发布'
          landscape_primary_enabled = landscape_publish_ready
        elsif landscape_managed && (!landscape_link['loaded'] || landscape_pending)
          landscape_primary_action = 'drawer_landscape_quick'
          landscape_primary_label = '更新'
          landscape_primary_enabled = landscape_source_ready
        elsif landscape_managed && landscape_link['loaded']
          landscape_primary_action = 'drawer_begin_edit:landscape'
          landscape_primary_label = '修改'
          landscape_primary_enabled = true
        elsif landscape_source_ready
          landscape_primary_action = 'drawer_landscape_quick'
          landscape_primary_label = '更新'
          landscape_primary_enabled = true
        else
          landscape_primary_action = 'drawer_landscape_disabled'
          landscape_primary_label = '未连接'
          landscape_primary_enabled = false
        end
      end
      if managed_discipline_background_publish_active?('landscape')
        landscape_job = background_publish_job_snapshot('discipline:landscape')
        landscape_status = "发布 #{landscape_job['progress'].to_i}% · #{landscape_job['stage_label']}"
        landscape_color = [190, 145, 65]
        landscape_primary_action = 'drawer_landscape_disabled'
        landscape_primary_label = '队列'
        landscape_primary_enabled = false
      end
      landscape_primary_tooltip = case landscape_primary_label
                                  when '发布'
                                    if landscape_host_native
                                      landscape_source_ready && landscape_work_model ? '共享 FULL 已写出；点击继续完成首次发布接管并直接进入景观修改' : '首次发布景观工作模型；成功后保持解锁并直接进入修改'
                                    else
                                      '上传并发布当前景观修改，完成后重新锁定并释放协作占用'
                                    end
                                  when '继续' then '继续未发布的景观修改；协作占用和本地内容均保留'
                                  when '修改' then '取得景观协作占用并自动进入景观组件'
                                  when '恢复' then '重新取得占用并继续上次中断的景观修改'
                                  when '更新' then '下载并载入共享景观的最新发布版本'
                                  when '占用中' then '景观正由其他成员修改'
                                  when '队列' then '景观正在统一后台发布队列中；可点击顶部队列按钮查看实时阶段与历史'
                                  else '景观尚未连接协同项目'
                                  end
      landscape_visible = detailed && landscape_link['visible'] == true
      landscape_visibility_allowed = detailed && landscape_link['loaded'] && !landscape_host_native

      drawer_spaces = if detailed
        spaces.map do |space|
        status_code = space['status_code'].to_s
        editing_self = space['editing_by_self'] == true
        editing_other = space['editing_by_other'] == true
        editing_any = space['editing'] == true
        inside = space['edit_context_inside'] == true
        exists = space['model_exists'] != false
        loaded = space['loaded'] == true
        publish_warning = editing_self
        background_publish = space['background_publish_active'] == true
        force_recovery = space['force_recovery_active'] == true
        linked_space = linked_space_record?(space)
        primary_action = ''
        primary_label = ''
        primary_tooltip = ''
        initial_publish_pending = space['initial_publish_pending'] == true
        if linked_space
          source = canonical_space_record(state, space)
          source_name = source ? source['name'].to_s : space['linked_source_name'].to_s
          if !loaded && source
            primary_action = "drawer_space_update:#{space['id']}"
            primary_label = '载入'
            primary_tooltip = "载入来源空间并恢复这个联动放置"
          else
            primary_action = "drawer_space_disabled:#{space['id']}"
            primary_label = '联动'
            primary_tooltip = source ? "内容联动于（#{source_name}）；请修改来源空间" : '联动来源已缺失，请刷新协同清单'
          end
        elsif background_publish
          primary_action = "drawer_space_disabled:#{space['id']}"
          bg_status = space['background_publish_status'].to_s
          primary_label = bg_status == 'queued' ? '队列' : (bg_status == 'success' ? '收尾' : '发布中')
          primary_tooltip = "#{space['background_publish_stage']} #{space['background_publish_progress'].to_i}% · 当前空间发布完成前暂时不可编辑/更新，其他空间可正常操作"
        elsif initial_publish_pending
          primary_action = "drawer_space_publish:#{space['id']}"
          primary_label = space['initial_publish_error'].to_s.empty? ? '发布' : '重试'
          primary_tooltip = '首次共享发布尚未完成；本地空间已保留。点击后进入同一个后台发布队列，且绝不会覆盖已经存在的共享目标。'
        elsif force_recovery
          primary_action = "quick_force_restore_space:#{space['id']}"
          primary_label = '恢复'
          primary_tooltip = '结束强制解锁并恢复进入前快照；恢复模式中的空间内部修改不会保留'
        elsif editing_self && space['edit_safe_paused']
          primary_action = "drawer_space_edit:#{space['id']}"
          primary_label = '继续'
          primary_tooltip = '继续该空间未发布修改；协作占用和本地内容均保留'
        elsif editing_self
          primary_action = "drawer_space_publish:#{space['id']}"
          primary_label = '发布'
          primary_tooltip = '立即发布当前空间并结束占用'
        elsif editing_other
          primary_action = "drawer_space_update:#{space['id']}"
          primary_label = '上版'
          primary_tooltip = '读取该空间最近一次已发布版本，不影响对方修改'
        elsif !exists
          primary_label = '缺失'
        elsif !loaded
          primary_action = "drawer_space_update:#{space['id']}"
          primary_label = '载入'
          primary_tooltip = '将这个空间载入当前工作 SU'
        elsif %w[pending waiting error].include?(status_code)
          primary_action = "drawer_space_update:#{space['id']}"
          primary_label = '更新'
          primary_tooltip = '从协同目录载入该空间当前发布版'
        else
          primary_action = "drawer_space_edit:#{space['id']}"
          primary_label = '修改'
          primary_tooltip = '取得空间占用并自动进入组件'
        end
        primary_action = "drawer_space_disabled:#{space['id']}" if primary_action.empty?
        space_visible = loaded && space['hidden'] != true && !space_collection_hidden_for(state, space_record_collection_key(space))
        visibility_enabled = loaded && !background_publish && !(editing_self && inside)
        visibility_tooltip = if !loaded
                               "该#{active_space_collection_label}空间尚未载入"
                             elsif editing_self && inside
                               '当前空间正在组件内修改；ESC 退出到全模后可隐藏'
                             elsif space_visible
                               "隐藏这个#{active_space_collection_label}空间"
                             else
                               "显示这个#{active_space_collection_label}空间"
                             end
        linked_source = linked_space ? canonical_space_record(state, space) : nil
        linked_source_name = linked_source ? linked_source['name'].to_s : space['linked_source_name'].to_s
        display_status = if linked_space
                           linked_source_name.empty? ? '联动来源已缺失' : "联动于（#{linked_source_name}）"
                         elsif publish_warning
                           space['publish_pending'] ? '待发布' : '待发布 · 修改中'
                         else
                           space['status_label'].to_s.empty? ? space['status'].to_s : space['status_label'].to_s
                         end
        display_color = linked_space ? [52, 137, 218] : (publish_warning ? [205, 78, 82] : workspace_drawer_status_color(status_code))
        group = Array(state['space_groups']).find { |candidate| candidate['id'].to_s == space['group_id'].to_s }
        display_name = group ? "#{group['name']} · #{space_ui_label(space)}" : space_ui_label(space)
        {
          'id' => space['id'].to_s,
          'number' => space['number'].to_i,
          'collection_key' => space_record_collection_key(space),
          'raw_name' => space['name'].to_s,
          'group_id' => space['group_id'].to_s,
          'group_order' => space['group_order'].to_i,
          'name' => display_name,
          'status_code' => status_code,
          'status' => display_status,
          'last_update' => space['last_update'].to_s,
          'loaded' => loaded,
          'manage_selectable' => !editing_any && !background_publish,
          # 首次发布尚未进入共享真相源前，禁止改名/分组，避免把仅本机记录提前写进共享布局。
          # 首次发布失败且 worker 已停止时允许删除；worker 正在发布时任何管理操作都禁止。
          'manage_can_rename' => !editing_any && !background_publish && !initial_publish_pending,
          'manage_can_delete' => !editing_any && !background_publish,
          'manage_can_group' => !editing_any && !background_publish && !initial_publish_pending,
          'color' => display_color,
          'publish_warning' => publish_warning,
          'linked_space' => linked_space,
          'linked_source_space_id' => space['linked_source_space_id'].to_s,
          'linked_source_name' => linked_source_name,
          'action' => primary_action, 'action_label' => primary_label,
          'tooltip' => primary_tooltip, 'enabled' => !background_publish && (exists || initial_publish_pending) && !primary_action.start_with?('drawer_space_disabled:'),
          # 只在“当前确有修改占用，并且锁用户名与当前用户严格一致”时提供解除按钮。
          'release_occupancy_action' => (space['edit_self_recoverable'] == true ? "drawer_space_release_occupancy:#{space['id']}" : ''),
          'release_occupancy_tooltip' => '仅回收已经中断的本人遗留占用；当前活动编辑请使用发布或取消修改结束',
          'resident_action' => (loaded ? "drawer_space_unload:#{space['id']}" : ''),
          'resident_tooltip' => (loaded ? '卸载这个空间；点击后会再次确认。只影响当前工作 SU，不删除共享文件、不影响其他成员' : ''),
          'resident_enabled' => !editing_self && !background_publish && !initial_publish_pending,
          'resident_loaded' => loaded,
          'visibility_action' => "drawer_space_visibility:#{space['id']}",
          'visibility_tooltip' => visibility_tooltip,
          'visibility_enabled' => visibility_enabled,
          'visible' => space_visible
          }
        end
      else
        []
      end

      drawer_spaces.concat(pending_linked_space_drawer_rows(state, active_space_collection_key, model)) if detailed

      drawer_groups = if detailed
        Array(state['space_groups']).sort_by { |group| group['order'].to_i }.map do |group|
          members = drawer_spaces.select { |space| space['group_id'].to_s == group['id'].to_s }
          loaded_members = members.select { |space| space['loaded'] == true }
          visibility_state = group_collection_visibility_state(group, active_space_collection_key)
          suspended = !!visibility_state['suspended']
          restore_ids = Array(visibility_state['restore_ids'])
          visible_count = loaded_members.count { |space| space['visible'] == true }
          visibility_enabled = !loaded_members.empty? && loaded_members.all? { |space| space['visibility_enabled'] != false }
          tooltip = if loaded_members.empty?
                      '组内空间尚未载入，无法切换显示'
                    elsif !visibility_enabled
                      '组内有空间正在组件内修改；ESC 退出到全模后可切换组显隐'
                    elsif suspended
                      "显示组内上次被组按钮隐藏的 #{restore_ids.length} 个空间；原本单独隐藏的空间保持隐藏"
                    elsif visible_count.positive?
                      "隐藏组内当前显示的 #{visible_count} 个空间；再次显示时只恢复这些空间"
                    else
                      '组内当前没有显示中的空间；原本单独隐藏的状态不会被组按钮改动'
                    end
          group.merge(
            'visibility_suspended' => suspended,
            'visibility_restore_ids' => restore_ids,
            'visible' => !suspended && visible_count.positive?,
            'visibility_enabled' => visibility_enabled && (suspended || visible_count.positive?),
            'visibility_tooltip' => tooltip,
            'visible_count' => visible_count,
            'loaded_count' => loaded_members.length
          )
        end
      else
        []
      end

      architecture_drawer_models, architecture_drawer_groups = architecture_drawer_collection_state(state, model, detailed: detailed)
      architecture_model_count = architecture_drawer_models.length
      architecture_loaded_count = architecture_drawer_models.count { |row| row['loaded'] == true }
      architecture_edit_count = architecture_drawer_models.count { |row| row['status_code'].to_s == 'editing' }
      architecture_error_count = architecture_drawer_models.count { |row| row['status_code'].to_s == 'error' }
      architecture_waiting_count = architecture_drawer_models.count { |row| row['status_code'].to_s == 'waiting' }
      # v0.13.6.29：专业状态点表达“共享端是否有新版本/异常/修改”，而不是“当前 SU 是否已把每个模型载入”。
      # “待载入”只是驻留状态，不应把建筑专业永久染成黄色。
      architecture_pending_count = architecture_drawer_models.count do |row|
        row['status_code'].to_s == 'pending' && row['status'].to_s != '待载入'
      end
      architecture_current_count = architecture_drawer_models.count do |row|
        !%w[editing waiting error].include?(row['status_code'].to_s) &&
          !(row['status_code'].to_s == 'pending' && row['status'].to_s != '待载入')
      end
      # 从这里开始，顶部工具条和跨专业按钮也只使用新建筑集合状态。
      architecture_editing = architecture_edit_count.positive?
      architecture_pending = architecture_pending_count.positive?
      architecture_paused = Array(state['architecture_models']).any? { |record| space_edit_safe_paused?(record) }
      architecture_source_ready = architecture_drawer_models.any? { |row| row['enabled'] == true || row['loaded'] == true }
      architecture_enabled = architecture_model_count.positive?
      architecture_managed = architecture_model_count.positive?
      architecture_remote_bootstrap = false
      architecture_publish_source = false
      architecture_host_native = false
      architecture_takeover_complete = architecture_model_count.positive?
      architecture_managed_instance = architecture_model_entities(model).first
      architecture_work_model = nil
      architecture_selected_work_model = nil
      architecture_publish_ready = false
      collection_locked_other = architecture_drawer_models.find { |row| row['editing_by_other'] == true }
      architecture_link = {
        'source_locked_by_other' => !collection_locked_other.nil?,
        'source_lock_owner' => collection_locked_other ? collection_locked_other['status'].to_s.sub(/.*修改中 · /, '') : '',
        'architecture_update_required' => architecture_pending,
        'model_exists' => architecture_source_ready,
        'loaded' => architecture_loaded_count.positive?,
        'status_code' => architecture_editing ? 'editing' : (architecture_pending ? 'pending' : (architecture_model_count.zero? ? 'empty' : 'current')),
        'status_label' => architecture_editing ? '待发布 · 修改中' : (architecture_pending ? '有建筑待更新' : (architecture_model_count.zero? ? '待新增建筑模型' : '建筑模型已更新'))
      }
      architecture_collection_status = if architecture_edit_count.positive?
                                         "#{architecture_edit_count} 个修改中"
                                       elsif architecture_error_count.positive?
                                         "#{architecture_error_count} 个异常"
                                       elsif architecture_pending_count.positive?
                                         "#{architecture_pending_count} 个待更新"
                                       elsif architecture_waiting_count.positive?
                                         "#{architecture_waiting_count} 个待恢复/占用"
                                       elsif architecture_model_count.zero?
                                         '待新增建筑模型'
                                       else
                                         "#{architecture_current_count}/#{architecture_model_count} 已同步"
                                       end
      architecture_collection_color = if architecture_edit_count.positive? || architecture_waiting_count.positive?
                                        [135, 86, 214]
                                      elsif architecture_error_count.positive?
                                        [222, 77, 77]
                                      elsif architecture_pending_count.positive?
                                        [230, 145, 38]
                                      elsif architecture_model_count.positive?
                                        [35, 174, 102]
                                      else
                                        [112, 122, 138]
                                      end


      drawer_items = [
        {
          'key' => 'architecture', 'name' => '建筑', 'status' => architecture_collection_status,
          'color' => architecture_collection_color, 'action' => 'drawer_toggle_section:architecture',
          'action_label' => '展开', 'enabled' => true,
          'publish_warning' => architecture_edit_count.positive?,
          'tooltip' => '展开或收纳建筑模型板块',
          'secondary_action' => '', 'secondary_label' => '',
          'secondary_tooltip' => '', 'secondary_enabled' => false,
          'visibility_action' => architecture_loaded_count.positive? ? 'drawer_toggle_architecture_collection_visibility' : '',
          'visibility_tooltip' => state['architecture_collection_hidden'] ? '显示全部建筑模型' : '隐藏全部建筑模型',
          'visibility_enabled' => architecture_loaded_count.positive?, 'visible' => state['architecture_collection_hidden'] != true,
          'refresh_action' => '',
          'refresh_tooltip' => '', 'refresh_enabled' => false,
          'model_count' => architecture_model_count,
          'loaded_count' => architecture_loaded_count
        },
        {
          'key' => SPACE_COLLECTION_KEY, 'name' => '硬装', 'status' => hard_collection_status,
          'color' => hard_collection_color, 'action' => "drawer_set_workspace:#{SPACE_COLLECTION_KEY}",
          'action_label' => '进入', 'enabled' => true, 'tooltip' => '切换到硬装工作区'
        },
        {
          'key' => SOFT_SPACE_COLLECTION_KEY, 'name' => '软装', 'status' => soft_collection_status,
          'color' => soft_collection_color, 'action' => "drawer_set_workspace:#{SOFT_SPACE_COLLECTION_KEY}",
          'action_label' => '进入', 'enabled' => true, 'tooltip' => '切换到软装工作区'
        },
        {
          'key' => 'landscape', 'name' => '景观', 'status' => landscape_status,
          'color' => landscape_color, 'action' => landscape_primary_action, 'action_label' => landscape_primary_label,
          'enabled' => landscape_primary_enabled,
          'tooltip' => if landscape_host_native && landscape_primary_label == '发布'
                         if landscape_work_model
                           landscape_link['native_work_entity_name'].to_s.empty? ? '发布已指定的景观工作模型' : "发布景观工作模型：#{landscape_link['native_work_entity_name']}"
                         elsif landscape_selected_work_model
                           '将当前选中的群组/组件设为景观工作模型并首次发布；成功后直接保持修改状态'
                         else
                           '首次发布前，请先在根层级只选中一个景观群组或组件'
                         end
                       else
                         landscape_primary_tooltip
                       end,
          'visibility_action' => landscape_visibility_allowed ? 'drawer_visibility:landscape' : '',
          'visibility_tooltip' => landscape_visible ? '隐藏景观参考' : '显示景观参考',
          'visibility_enabled' => landscape_visibility_allowed, 'visible' => landscape_visible
        }
      ]
      selected_space = selected_managed_space_record(state, model)
      selected_architecture = selected_architecture_model_record(state, model)
      selected_space_entity = selected_space ? space_model_entity(selected_space['id'], model) : nil
      selected_space_source = selected_space ? auto_relocate(selected_space['model_path'].to_s, model) : ''
      selected_space_ready = !!(selected_space && selected_space_entity && selected_space_entity.valid? &&
                               (selection_fast ? space_ready_for_normal_edit_cached?(selected_space, selected_space_entity, model) : space_ready_for_normal_edit?(selected_space, selected_space_entity, model)))

      quick_primary_action = ''
      quick_primary_label = ''
      quick_primary_icon = 'pencil'
      quick_primary_tooltip = ''
      quick_primary_enabled = false
      quick_primary_active = false
      quick_primary_color = [58, 119, 225]
      # v0.13.6.136：协同组件拆成两条完全不同的轻量入口：
      # 1) 选中普通组件时，仅显示绿色“定义组件”按钮；
      # 2) 共享端存在组件新版时，始终显示独立黄色圆形“更新全部组件”按钮。
      # 本机组件修改不再出现单独上传按钮，而是缓存为 dirty，随包含它的空间发布一并提交。
      quick_component_action = ''
      quick_component_icon = ''
      quick_component_tooltip = ''
      quick_component_enabled = false
      quick_component_active = false
      quick_component_color = [49, 145, 111]
      quick_component_update_action = ''
      quick_component_update_icon = 'download'
      quick_component_update_tooltip = ''
      quick_component_update_enabled = false
      quick_component_update_active = false
      quick_component_update_color = [214, 164, 45]
      quick_aux_buttons = []
      quick_library_buttons = []
      if material_library_supported_discipline?(host_key)
        pipette_status = library_pipette_selection_status(model, state, fast: selection_fast)
        case host_key
        when 'architecture'
          quick_library_buttons << {
            'action' => 'architecture_library', 'icon' => 'building',
            'tooltip' => (@architecture_library_dialog && @architecture_library_dialog.visible?) ? '关闭建筑库' : '打开建筑模型库 / 建筑材质库 / 建筑清单',
            'enabled' => true, 'active' => !!(@architecture_library_dialog && @architecture_library_dialog.visible?),
            'color' => [58, 111, 178]
          }
          quick_library_buttons << {
            'action' => 'library_pipette', 'icon' => 'pipette',
            'tooltip' => pipette_status['tooltip'].to_s,
            'enabled' => pipette_status['enabled'] == true, 'active' => false,
            'color' => [60, 139, 130]
          }
        when SPACE_COLLECTION_KEY
          # 硬装工作区只保留硬装材质能力；软装模型库/采购清单已彻底迁到软装工作区。
          quick_library_buttons << {
            'action' => 'library_pipette', 'icon' => 'pipette',
            'tooltip' => pipette_status['tooltip'].to_s.empty? ? '硬装材质吸管' : pipette_status['tooltip'].to_s,
            'enabled' => pipette_status['enabled'] == true, 'active' => false,
            'color' => [188, 128, 44]
          }
        when SOFT_SPACE_COLLECTION_KEY
          quick_library_buttons << {
            'action' => 'workbench', 'icon' => 'grid',
            'tooltip' => (@soft_designer_dialog && @soft_designer_dialog.visible?) ? '关闭软装库' : '打开软装模型库 / 软装材质库 / 软装清单',
            'enabled' => true, 'active' => !!(@soft_designer_dialog && @soft_designer_dialog.visible?),
            'color' => [116, 75, 202]
          }
          quick_library_buttons << {
            'action' => 'soft_schedule', 'icon' => 'note',
            'tooltip' => (@soft_schedule_dialog && @soft_schedule_dialog.visible?) ? '项目软装清单已打开' : '打开项目软装清单与分类 Excel 导出',
            'enabled' => true, 'active' => !!(@soft_schedule_dialog && @soft_schedule_dialog.visible?),
            'color' => [105, 72, 174]
          }
          # 软装工作区把原“家具吸管”改成批量家具入库；选中裸面时仍可作为材质吸管。
          selected_face = begin
            selected_entities = model.selection.to_a
            selected_entities.length == 1 && selected_entities.first.is_a?(Sketchup::Face)
          rescue StandardError
            false
          end
          if selected_face
            quick_library_buttons << {
              'action' => 'library_pipette', 'icon' => 'pipette',
              'tooltip' => pipette_status['tooltip'].to_s,
              'enabled' => pipette_status['enabled'] == true, 'active' => false,
              'color' => [60, 139, 130]
            }
          else
            ingest_status = soft_batch_ingest_button_status(model, state, fast: selection_fast)
            quick_library_buttons << {
              'action' => 'soft_batch_ingest', 'icon' => 'sofa',
              'tooltip' => ingest_status['tooltip'].to_s,
              'enabled' => ingest_status['enabled'] == true, 'active' => !!@soft_ingest_batch_job,
              'color' => [129, 91, 180]
            }
          end
        when 'landscape'
          quick_library_buttons << {
            'action' => 'landscape_library', 'icon' => 'plant',
            'tooltip' => (@landscape_library_dialog && @landscape_library_dialog.visible?) ? '关闭景观库' : '打开景观模型库 / 景观材质库 / 景观清单',
            'enabled' => true, 'active' => !!(@landscape_library_dialog && @landscape_library_dialog.visible?),
            'color' => [45, 145, 82]
          }
          quick_library_buttons << {
            'action' => 'library_pipette', 'icon' => 'pipette',
            'tooltip' => pipette_status['tooltip'].to_s,
            'enabled' => pipette_status['enabled'] == true, 'active' => false,
            'color' => [55, 143, 92]
          }
        end
      end
      landscape_connected_for_quick = landscape_link['enabled'] != false && landscape_source_ready
      references_button_visible = host_key != 'coordination'
      # 建筑、室内、景观工作区都可控制已载入室内参考中的家具代理/真模型。
      # 在本专业根组件内修改时仍允许切换，进入其它无关组件则禁用，避免误操作。
      representation_selection_scope = resolve_soft_representation_selection_scope(model, state)
      selected_external_soft = Array(representation_selection_scope[:targets])
      selected_external_soft_count = [representation_selection_scope[:occurrence_count].to_i, selected_external_soft.length].max
      selected_external_soft_mode = selected_soft_instances_display_mode(selected_external_soft)
      selected_external_soft_mixed = selected_soft_instances_mixed?(selected_external_soft)
      representation_selection_label = representation_selection_scope[:label].to_s
      representation_supported = if space_workspace_role?(host_key)
                                   selected_external_soft_count.positive? || !!item || !spaces.empty?
                                 elsif %w[architecture landscape].include?(host_key)
                                   selected_external_soft_count.positive? || !spaces.empty?
                                 else
                                   false
                                 end
      representation_enabled = if representation_selection_scope[:kind] == :empty_container
                                 false
                               elsif selected_external_soft_count.positive?
                                 representation_supported
                               elsif space_workspace_role?(host_key)
                                 representation_supported && (model.active_path.nil? || space_inside)
                               elsif host_key == 'architecture'
                                 representation_supported && (model.active_path.nil? || architecture_editing)
                               elsif host_key == 'landscape'
                                 representation_supported && (model.active_path.nil? || landscape_editing)
                               else
                                 false
                               end

      case host_key
      when 'architecture'
        if architecture_editing && architecture_paused
          quick_primary_action = 'drawer_begin_edit:architecture'
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = '继续未发布的建筑修改'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [135, 86, 214]
        elsif architecture_editing
          quick_primary_action = 'architecture_sync'
          quick_primary_icon = 'upload'
          quick_primary_tooltip = '发布当前建筑修改并释放协作占用'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif architecture_link['source_locked_by_other']
          quick_primary_icon = 'lock'
          owner = architecture_link['source_lock_owner'].to_s
          owner = '其他成员' if owner.empty?
          quick_primary_tooltip = "#{owner} 正在修改建筑"
          quick_primary_color = [112, 122, 138]
        elsif architecture_remote_bootstrap
          quick_primary_action = 'quick_update_architecture'
          quick_primary_icon = 'download'
          quick_primary_tooltip = '协同中已有建筑模型；点击获取最新建筑并接管为当前工作模型'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [47, 111, 205]
        elsif architecture_publish_source
          quick_primary_action = 'architecture_sync'
          quick_primary_icon = 'upload'
          if architecture_work_model
            work_name = architecture_link['native_work_entity_name'].to_s
            quick_primary_tooltip = if architecture_source_ready
                                      '共享 FULL 已写出；再次发布会完成本机接管并直接进入建筑修改'
                                    else
                                      work_name.empty? ? '发布已指定的建筑工作模型' : "发布建筑工作模型：#{work_name}"
                                    end
            quick_primary_enabled = true
          elsif architecture_selected_work_model
            quick_primary_tooltip = '将当前选中的群组/组件设为建筑工作模型并首次发布；成功后直接进入修改'
            quick_primary_enabled = true
          else
            quick_primary_tooltip = model.selection.empty? ? '首次发布前，请先在根层级选中一个建筑群组或组件' : '首次发布只能选中一个普通根群组或组件'
            quick_primary_enabled = false
            quick_primary_color = [112, 122, 138]
          end
          quick_primary_color = [190, 91, 65] if quick_primary_enabled
        elsif architecture_pending
          quick_primary_action = 'quick_update_architecture'
          quick_primary_icon = 'download'
          quick_primary_tooltip = '建筑有新发布版本；先更新后才能继续修改'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [47, 111, 205]
        elsif architecture_managed && architecture_source_ready
          quick_primary_action = 'drawer_begin_edit:architecture'
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = '修改建筑：取得协作占用并直接进入建筑组件'
          quick_primary_enabled = true
          quick_primary_color = [135, 86, 214]
        else
          quick_primary_tooltip = '建筑协同模型尚未就绪'
        end
        quick_aux_buttons << {
          'action' => 'quick_update_spaces', 'icon' => 'sofa', 'kind' => 'discipline_refresh',
          'tooltip' => '检查并更新全部发生变化的硬装/软装空间', 'enabled' => !spaces.empty?,
          'active' => false, 'color' => [47, 137, 123]
        }
        if landscape_connected_for_quick
          quick_aux_buttons << {
            'action' => 'landscape_sync', 'icon' => 'mountain', 'kind' => 'discipline_refresh',
            'tooltip' => landscape_pending ? '景观有新版本，点击更新' : '检查并更新景观参考',
            'enabled' => true, 'active' => landscape_pending, 'color' => [78, 126, 88]
          }
        end
      when SPACE_COLLECTION_KEY, SOFT_SPACE_COLLECTION_KEY
        paused_space = paused_space_edit_records(state).find { |row| space_record_collection_key(row) == host_key }
        # 当前仍保持解锁编辑态的空间优先级必须最高。切换过多个空间后，旧焦点可能
        # 仍以 safe_paused 形式保留；若先命中 paused_space，顶部按钮会显示“继续旧空间”，
        # 抢走当前空间本应显示的“发布”动作，造成 UI 与真实编辑焦点打架。
        if item
          quick_primary_action = 'hard_sync'
          quick_primary_icon = 'upload'
          quick_primary_tooltip = "发布当前空间 #{item['number']}:#{item['name']}"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif paused_space
          quick_primary_action = "drawer_space_edit:#{paused_space['id']}"
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = "继续空间 #{paused_space['number']}:#{paused_space['name']} 的未发布修改"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [135, 86, 214]
        elsif selected_space && selected_space['background_publish_active'] == true
          quick_primary_icon = 'upload'
          quick_primary_tooltip = "#{selected_space['number']}:#{selected_space['name']} 正在后台发布（#{selected_space['background_publish_progress'].to_i}%）；可继续选择并修改其他空间"
          quick_primary_enabled = false
          quick_primary_active = true
          quick_primary_color = [190, 145, 65]
        elsif selected_space_ready
          quick_primary_action = "drawer_space_edit:#{selected_space['id']}"
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = "修改选中空间 #{selected_space['number']}:#{selected_space['name']}"
          quick_primary_enabled = true
          quick_primary_color = [135, 86, 214]
        else
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = selected_space ? '选中空间尚未载入最新发布版；必须先更新/载入最新模型后才能修改。若只需从历史模型取物，请使用右侧“强制解锁”。' : "请先在视口中选中一个#{space_collection_label(host_key)}空间，再点击修改"
          quick_primary_color = [112, 122, 138]
        end
        unless space_inside
          quick_aux_buttons << {
            'action' => 'quick_update_architecture', 'icon' => 'building', 'kind' => 'discipline_refresh',
            'tooltip' => architecture_pending ? '建筑有新版本，点击更新' : '检查并更新建筑参考',
            'enabled' => architecture_enabled, 'active' => architecture_pending,
            'color' => [47, 111, 205]
          }
          if landscape_connected_for_quick
            quick_aux_buttons << {
              'action' => 'landscape_sync', 'icon' => 'mountain', 'kind' => 'discipline_refresh',
              'tooltip' => landscape_pending ? '景观有新版本，点击更新' : '检查并更新景观参考',
              'enabled' => true, 'active' => landscape_pending,
              'color' => [78, 126, 88]
            }
          end
        end
      when 'landscape'
        if landscape_editing && landscape_paused
          quick_primary_action = 'drawer_begin_edit:landscape'
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = '继续未发布的景观修改'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [135, 86, 214]
        elsif landscape_editing
          quick_primary_action = 'drawer_landscape_quick'
          quick_primary_icon = 'upload'
          quick_primary_tooltip = '发布当前景观修改并释放协作占用'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif landscape_link['source_locked_by_other']
          quick_primary_icon = 'lock'
          owner = landscape_link['source_lock_owner'].to_s
          owner = '其他成员' if owner.empty?
          quick_primary_tooltip = "#{owner} 正在修改景观"
          quick_primary_color = [112, 122, 138]
        elsif landscape_remote_bootstrap
          quick_primary_action = 'drawer_landscape_quick'
          quick_primary_icon = 'download'
          quick_primary_tooltip = '协同中已有景观模型；点击获取最新景观并接管为当前工作模型'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [45, 145, 82]
        elsif landscape_host_native
          quick_primary_action = 'drawer_landscape_quick'
          quick_primary_icon = 'upload'
          if landscape_work_model
            work_name = landscape_link['native_work_entity_name'].to_s
            quick_primary_tooltip = if landscape_source_ready
                                      '共享 FULL 已写出；再次发布会完成本机接管并直接进入景观修改'
                                    else
                                      work_name.empty? ? '发布已指定的景观工作模型' : "发布景观工作模型：#{work_name}"
                                    end
            quick_primary_enabled = true
          elsif landscape_selected_work_model
            quick_primary_tooltip = '将当前选中的群组/组件设为景观工作模型并首次发布；成功后直接进入修改'
            quick_primary_enabled = true
          else
            quick_primary_tooltip = model.selection.empty? ? '首次发布前，请先在根层级选中一个景观群组或组件' : '首次发布只能选中一个普通根群组或组件'
            quick_primary_enabled = false
            quick_primary_color = [112, 122, 138]
          end
          quick_primary_color = [190, 91, 65] if quick_primary_enabled
        elsif landscape_pending
          quick_primary_action = 'drawer_landscape_quick'
          quick_primary_icon = 'download'
          quick_primary_tooltip = '景观有新发布版本；先更新后才能继续修改'
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [78, 126, 88]
        elsif landscape_managed && landscape_source_ready
          quick_primary_action = 'drawer_begin_edit:landscape'
          quick_primary_icon = 'pencil'
          quick_primary_tooltip = '修改景观：取得协作占用并直接进入景观组件'
          quick_primary_enabled = true
          quick_primary_color = [135, 86, 214]
        else
          quick_primary_tooltip = '景观协同模型尚未就绪'
          quick_primary_color = [112, 122, 138]
        end
        quick_aux_buttons << {
          'action' => 'quick_update_architecture', 'icon' => 'building', 'kind' => 'discipline_refresh',
          'tooltip' => architecture_pending ? '建筑有新版本，点击更新' : '检查并更新建筑参考',
          'enabled' => architecture_enabled, 'active' => architecture_pending,
          'color' => [47, 111, 205]
        }
        quick_aux_buttons << {
          'action' => 'quick_update_spaces', 'icon' => 'sofa', 'kind' => 'discipline_refresh',
          'tooltip' => '检查并更新全部发生变化的硬装/软装空间', 'enabled' => !spaces.empty?,
          'active' => false, 'color' => [47, 137, 123]
        }
      else
        quick_primary_action = 'quick_update_architecture'
        quick_primary_icon = 'building'
        quick_primary_tooltip = '检查并更新建筑参考'
        quick_primary_enabled = architecture_enabled
        quick_aux_buttons << {
          'action' => 'quick_update_spaces', 'icon' => 'sofa', 'kind' => 'discipline_refresh',
          'tooltip' => '检查并更新全部发生变化的硬装/软装空间', 'enabled' => !spaces.empty?,
          'active' => false, 'color' => [47, 137, 123]
        }
        if landscape_connected_for_quick
          quick_aux_buttons << {
            'action' => 'landscape_sync', 'icon' => 'mountain', 'kind' => 'discipline_refresh',
            'tooltip' => '检查并更新景观参考', 'enabled' => true,
            'active' => landscape_pending, 'color' => [78, 126, 88]
          }
        end
      end

      # v0.13.1：顶部主按钮以“当前明确选中的受管根”为最高优先级，且“发布”只认
      # explicit_local_pending_*? 的真实本机修改会话。选择一个未编辑的跨专业模型，只会显示修改/更新，
      # 定时刷新绝不能凭锁文件、历史 editing_id 或偶然解锁状态自己跳成上传。
      pending_spaces = selection_fast ? local_pending_space_records_fast(state, model) : local_pending_space_records(state, model)
      pending_architecture = selection_fast ? local_pending_architecture_records_fast(state, model) : local_pending_architecture_records(state, model)

      if selected_space
        selected_kind = space_record_collection_key(selected_space)
        selected_name = quick_unit_display_name(selected_space, selected_kind, state)
        selected_prefix = quick_profession_prefix(selected_kind, host_key)
        if linked_space_record?(selected_space)
          linked_source = canonical_space_record(state, selected_space)
          linked_source_name = linked_source ? linked_source['name'].to_s : selected_space['linked_source_name'].to_s
          # v0.13.6.190：联动空间主按钮 = “调整位置”。不再只能依赖双击进入实例调整。
          # 选中的是“原生复制出来的重复实例”时，索引里的同 id 实体是另一个，不能让主按钮去解锁它；
          # 这种情况交给橙色对勾“登记为联动副本”。
          linked_selected_duplicate = !selected_duplicate_space_root_info(model).nil?
          linked_adjust_blocked = linked_source.nil? || !model.active_path.nil? || linked_space_copy_active?(model) ||
                                  publish_critical_section? || publish_post_quiet? || @updating ||
                                  @single_space_update_job || @space_batch_update_job || linked_selected_duplicate
          quick_primary_action = linked_adjust_blocked ? '' : "linked_space_transform_begin:#{selected_space['id']}"
          quick_primary_icon = 'unlock'
          quick_primary_label = ''
          quick_primary_tooltip = if linked_source.nil?
                                    "#{selected_name} 的联动来源已缺失"
                                  elsif linked_selected_duplicate
                                    "这是 #{selected_name} 的原生复制实例，请先点顶部橙色对勾登记为联动副本"
                                  elsif linked_adjust_blocked
                                    "#{selected_name} 联动于（#{linked_source_name}）；发布/更新或其它联动操作进行中，稍后再调整位置"
                                  else
                                    "调整 #{selected_name} 的位置：解锁后用 SU 原生移动/旋转/缩放/镜像，完成后点顶部绿色对勾（内容请在来源“#{linked_source_name}”中修改）"
                                  end
          quick_primary_enabled = !linked_adjust_blocked
          quick_primary_active = false
          quick_primary_color = [52, 137, 218]
        elsif space_background_publish_active?(selected_space['id'])
          job = background_publish_job_snapshot(selected_space['id'])
          quick_primary_action = ''
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "#{selected_prefix}#{selected_name} 正在后台发布 #{job['progress'].to_i}% · #{job['stage_label']}；可继续操作其它模型"
          quick_primary_enabled = false
          quick_primary_active = true
          quick_primary_color = [190, 145, 65]
        elsif initial_space_publish_pending?(selected_space)
          quick_primary_action = "drawer_space_publish:#{selected_space['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "首次发布 #{selected_prefix}#{selected_name}；本地空间已创建，点击后进入后台 create-only 发布队列"
          quick_primary_enabled = !space_background_publish_active?(selected_space['id'])
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif (selection_fast ? explicit_local_pending_space_fast?(selected_space, state, model) : local_pending_space?(selected_space, state, model))
          quick_primary_action = "drawer_space_publish:#{selected_space['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "发布 #{selected_prefix}#{selected_name}；自动退出当前嵌套层级并锁定正确空间根"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif selected_space_ready
          quick_primary_action = "drawer_space_edit:#{selected_space['id']}"
          quick_primary_icon = 'pencil'
          quick_primary_label = ''
          quick_primary_tooltip = "修改 #{selected_prefix}#{selected_name}；其它待发布模型继续保持解锁"
          quick_primary_enabled = true
          quick_primary_active = false
          quick_primary_color = [135, 86, 214]
        else
          quick_primary_action = "drawer_space_update:#{selected_space['id']}"
          quick_primary_icon = 'download'
          quick_primary_label = ''
          quick_primary_tooltip = "#{selected_prefix}#{selected_name} 尚未载入最新发布版；先更新后才能修改。历史取物请用强制解锁"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [47, 111, 205]
        end
      elsif selected_architecture
        selected_name = quick_unit_display_name(selected_architecture, 'architecture', state)
        selected_prefix = quick_profession_prefix('architecture', host_key)
        if architecture_background_publish_active?(selected_architecture['id'])
          job = background_publish_job_snapshot("architecture_model:#{selected_architecture['id']}")
          quick_primary_action = ''
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "#{selected_prefix}#{selected_name} 正在后台发布 #{job['progress'].to_i}% · #{job['stage_label']}；可继续操作其它模型"
          quick_primary_enabled = false
          quick_primary_active = true
          quick_primary_color = [190, 145, 65]
        elsif selected_architecture['initial_publish_pending'] == true
          quick_primary_action = "drawer_architecture_model_publish:#{selected_architecture['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "首次发布 #{selected_prefix}#{selected_name}；本地建筑已保留，点击后进入后台 create-only 发布队列"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif (selection_fast ? explicit_local_pending_architecture_fast?(selected_architecture, state, model) : local_pending_architecture?(selected_architecture, state, model))
          quick_primary_action = "drawer_architecture_model_publish:#{selected_architecture['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "发布 #{selected_prefix}#{selected_name}；自动退出当前嵌套层级并锁定正确建筑根"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        else
          selected_entity = architecture_model_entity(selected_architecture['id'], model)
          direction = if selection_fast
                        selected_architecture['status_code'].to_s == 'pending' || selected_architecture['update_required'] == true ? :newer : (selected_entity ? :same : :newer)
                      else
                        architecture_model_update_direction(selected_architecture, selected_entity, model)
                      end
          if direction != :same || !selected_entity
            quick_primary_action = "drawer_architecture_model_update:#{selected_architecture['id']}"
            quick_primary_icon = 'download'
            quick_primary_tooltip = "更新 #{selected_prefix}#{selected_name}"
            quick_primary_color = [47, 111, 205]
            quick_primary_active = true
          else
            quick_primary_action = "drawer_architecture_model_edit:#{selected_architecture['id']}"
            quick_primary_icon = 'pencil'
            quick_primary_tooltip = "修改 #{selected_prefix}#{selected_name}；其它待发布模型继续保持解锁"
            quick_primary_color = [135, 86, 214]
            quick_primary_active = false
          end
          quick_primary_label = ''
          quick_primary_enabled = true
        end
      else
        # 没有根层级选择时，只允许对“当前明确焦点”或唯一待发布单元给出上传按钮；
        # 多项待发布时不猜目标，要求用户选中对应空间/建筑。
        focused_space = nil
        focused_architecture = nil
        if item && (selection_fast ? explicit_local_pending_space_fast?(item, state, model) : explicit_local_pending_space?(item, state, model))
          focused_space = item
        elsif !state['space_editing_id'].to_s.empty?
          focused_space = pending_spaces.find { |row| row['id'].to_s == state['space_editing_id'].to_s }
        end
        unless focused_space
          if !state['architecture_editing_id'].to_s.empty?
            focused_architecture = pending_architecture.find { |row| row['id'].to_s == state['architecture_editing_id'].to_s }
          end
        end

        if focused_space
          focused_kind = space_record_collection_key(focused_space)
          name = quick_unit_display_name(focused_space, focused_kind, state)
          quick_primary_action = "drawer_space_publish:#{focused_space['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "发布当前空间 #{name}；无需手动退出嵌套组件"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        elsif focused_architecture
          name = quick_unit_display_name(focused_architecture, 'architecture', state)
          quick_primary_action = "drawer_architecture_model_publish:#{focused_architecture['id']}"
          quick_primary_icon = 'upload'
          quick_primary_label = ''
          quick_primary_tooltip = "发布当前建筑 #{name}；无需手动退出嵌套组件"
          quick_primary_enabled = true
          quick_primary_active = true
          quick_primary_color = [190, 91, 65]
        else
          all_pending = pending_spaces.map { |row| [space_record_collection_key(row), row] } + pending_architecture.map { |row| ['architecture', row] }
          if all_pending.length == 1
            kind, pending = all_pending.first
            name = quick_unit_display_name(pending, kind, state)
            if SPACE_COLLECTION_KEYS.include?(kind)
              quick_primary_action = "drawer_space_publish:#{pending['id']}"
            else
              quick_primary_action = "drawer_architecture_model_publish:#{pending['id']}"
            end
            quick_primary_icon = 'upload'
            quick_primary_label = ''
            quick_primary_tooltip = "发布待发布模型 #{quick_profession_prefix(kind, host_key)}#{name}"
            quick_primary_enabled = true
            quick_primary_active = true
            quick_primary_color = [190, 91, 65]
          elsif all_pending.length > 1
            quick_primary_action = ''
            quick_primary_icon = 'upload'
            quick_primary_label = ''
            quick_primary_tooltip = "当前有 #{all_pending.length} 个模型待发布；请在视口中选中目标空间/建筑"
            quick_primary_enabled = false
            quick_primary_active = true
            quick_primary_color = [190, 91, 65]
          elsif landscape_editing && !landscape_paused && host_key != 'landscape'
            quick_primary_action = 'drawer_landscape_quick'
            quick_primary_label = ''
            quick_primary_icon = 'upload'
            quick_primary_tooltip = '发布当前跨专业景观修改并释放景观协作占用'
            quick_primary_enabled = true
            quick_primary_active = true
            quick_primary_color = [190, 91, 65]
          end
        end
      end

      # v0.13.6.69：整专业建筑/景观首次发布或景观后续发布也占用同一个顶部队列。
      # 当前工作专业本身正在队列中时，主按钮只显示实时队列状态；不允许旧 UI 绕进去再次发布/修改。
      if %w[architecture landscape].include?(host_key.to_s) && managed_discipline_background_publish_active?(host_key.to_s)
        discipline_job = background_publish_job_snapshot("discipline:#{host_key}")
        quick_primary_action = ''
        quick_primary_label = ''
        quick_primary_icon = 'upload'
        quick_primary_tooltip = "#{DISCIPLINES.dig(host_key, 'name')}正在后台发布 #{discipline_job['progress'].to_i}% · #{discipline_job['stage_label']}；发布完成前该专业保持冻结，其他专业/空间可继续操作"
        quick_primary_enabled = false
        quick_primary_active = true
        quick_primary_color = [190, 145, 65]
      end

      # 只有主按钮当前明确指向“本机待发布的室内/建筑单元”时，才在其右侧显示取消修改。
      # 取消按钮不靠 selection 猜测目标，直接复用已经过严格 pending 判定的发布 action。
      quick_cancel_action = ''
      quick_cancel_tooltip = ''
      quick_cancel_enabled = false
      quick_cancel_color = [190, 82, 64]
      case quick_primary_action.to_s
      when /\Adrawer_space_publish:(.+)\z/
        cancel_id = Regexp.last_match(1).to_s
        cancel_item = space_model_record(state, cancel_id)
        if cancel_item && (selection_fast ? explicit_local_pending_space_fast?(cancel_item, state, model) : explicit_local_pending_space?(cancel_item, state, model))
          cancel_kind = space_record_collection_key(cancel_item)
          cancel_name = quick_unit_display_name(cancel_item, cancel_kind, state)
          quick_cancel_action = "quick_cancel_space:#{cancel_id}"
          quick_cancel_tooltip = "取消 #{quick_profession_prefix(cancel_kind, host_key)}#{cancel_name} 的未发布修改，恢复上一发布版并释放占用"
          quick_cancel_enabled = !@updating && !publish_critical_section?
        end
      when /\Adrawer_architecture_model_publish:(.+)\z/
        cancel_id = Regexp.last_match(1).to_s
        cancel_item = architecture_model_record(state, cancel_id)
        if cancel_item && (selection_fast ? explicit_local_pending_architecture_fast?(cancel_item, state, model) : explicit_local_pending_architecture?(cancel_item, state, model))
          cancel_name = quick_unit_display_name(cancel_item, 'architecture', state)
          quick_cancel_action = "quick_cancel_architecture:#{cancel_id}"
          quick_cancel_tooltip = "取消 #{quick_profession_prefix('architecture', host_key)}#{cancel_name} 的未发布修改，恢复上一发布版并释放占用"
          quick_cancel_enabled = !@updating && !publish_critical_section?
        end
      end

      if @single_space_update_job.is_a?(Hash) && @single_space_update_job[:cancel_edit] == true
        quick_cancel_enabled = false
        quick_cancel_tooltip = '正在恢复上一发布版，请等待完成…' unless quick_cancel_action.empty?
      end

      quick_force_unlock_action = ''
      quick_force_unlock_tooltip = ''
      quick_force_unlock_enabled = false
      quick_force_unlock_active = false
      quick_force_unlock_color = [195, 74, 65]
      force_record = space_force_recovery_record(state)
      if force_record
        quick_force_unlock_action = "quick_force_restore_space:#{force_record['id']}"
        quick_force_unlock_tooltip = "结束强制解锁并恢复 #{force_record['number']}:#{force_record['name']} 到进入前快照；恢复模式中的空间修改不会保留"
        quick_force_unlock_enabled = !publish_critical_section? && !@updating
        quick_force_unlock_active = true
        quick_force_unlock_color = [205, 75, 67]
      elsif selected_space && !linked_space_record?(selected_space) && selected_space_entity && selected_space_entity.valid?
        any_normal_pending = pending_spaces.any? || pending_architecture.any?
        selected_initial_pending = initial_space_publish_pending?(selected_space)
        selected_background_publish = background_publish_active_state?(selected_space)
        quick_force_unlock_action = "quick_force_unlock_space:#{selected_space['id']}"
        quick_force_unlock_tooltip = if selected_background_publish
                                       '该空间正在后台发布，不能强制解锁；可继续操作其他空间'
                                     elsif selected_initial_pending
                                       '该空间尚未完成首次发布，没有历史已发布版可供强制解锁恢复；请先重试发布或删除本地待发布空间'
                                     elsif any_normal_pending
                                       '当前已有未发布修改，不能同时进入强制解锁恢复模式'
                                     elsif !model.active_path.nil?
                                       '请先退出当前组件层级，再使用强制解锁'
                                     else
                                       '强制解锁：仅用于从当前已载入的历史/旧空间中复制取物；不取得协作锁、禁止发布，退出后自动恢复进入前状态'
                                     end
        quick_force_unlock_enabled = !selected_background_publish && !selected_initial_pending && !any_normal_pending && model.active_path.nil? && !publish_critical_section? && !@updating
      end

      quick_copy_action = ''
      quick_copy_tooltip = ''
      quick_copy_enabled = false
      quick_copy_active = false
      quick_copy_confirm = false
      quick_copy_color = [48, 132, 218]
      placement = linked_space_copy_record(model)
      pending_selected_rows = selected_pending_linked_space_clones(model)
      if placement
        quick_copy_action = 'linked_space_copy_finish'
        quick_copy_confirm = true
        quick_copy_active = true
        phase = placement[:phase].to_s
        mode = placement[:mode].to_s
        quick_copy_enabled = phase == 'adjusting'
        quick_copy_color = [42, 154, 104]
        quick_copy_tooltip = if quick_copy_enabled && mode == 'transform'
                               '完成联动空间的移动、旋转、缩放或镜像调整并锁回'
                             elsif quick_copy_enabled
                               '完成复制、锁定联动空间并输入名称'
                             elsif phase == 'target_point'
                               '已选择基准点，请在视口中单击目标点'
                             else
                               '请先在视口中单击选择复制基准点'
                             end
        # 放置/变换事务中顶部只保留当前联动实例上下文和完成按钮，避免误触发布/更新/入库。
        quick_primary_action = ''
        quick_primary_enabled = false
        quick_primary_active = false
        quick_primary_icon = 'lock'
        quick_primary_tooltip = if mode == 'transform'
                                  '联动空间实例调整中：可直接用 SU 原生移动、旋转、缩放/镜像；Move+Ctrl 可连续复制'
                                else
                                  quick_copy_enabled ? '联动空间复制中：可移动、旋转、缩放或镜像，不可进入内部' : '联动空间复制中：请完成基准点与目标点'
                                end
        quick_cancel_action = ''
        quick_force_unlock_action = ''
        quick_library_buttons = []
      elsif pending_selected_rows.any?
        single_pending = model.selection.length == 1 && pending_selected_rows.length == 1
        quick_copy_action = single_pending ? 'linked_space_pending_finish' : 'linked_space_pending_select_one'
        quick_copy_confirm = true
        quick_copy_active = true
        quick_copy_enabled = single_pending
        quick_copy_color = [42, 154, 104]
        quick_copy_tooltip = single_pending ? '登记这个原生复制出来的联动空间并输入独立名称' : '请只选中一个待登记联动空间副本，再点顶部对勾'
        quick_primary_action = ''
        quick_primary_enabled = false
        quick_primary_active = false
        quick_primary_icon = 'lock'
        quick_primary_tooltip = single_pending ? '待登记联动空间：位置/旋转/缩放/镜像已保留，命名后锁定' : '一次只能登记一个联动空间副本'
        quick_cancel_action = ''
        quick_force_unlock_action = ''
        quick_library_buttons = []
      elsif (duplicate_root = selected_duplicate_space_root_info(model))
        # v0.13.6.190：原生复制产生的重复空间根 → 橙色对勾“登记为联动副本”。
        quick_copy_action = 'linked_space_adopt_duplicate'
        quick_copy_confirm = true
        quick_copy_active = true
        quick_copy_enabled = !(publish_critical_section? || publish_post_quiet? || @updating)
        quick_copy_color = [214, 132, 38]
        quick_copy_tooltip = "这是“#{duplicate_root[:item_label]}”的原生复制实例（无法双击/解锁）；点击登记为联动副本后即可移动并命名"
      elsif selected_space && selected_space_entity && selected_space_entity.valid? && model.active_path.nil?
        canonical = canonical_space_record(state, selected_space)
        copy_blocked = canonical.nil? || initial_space_publish_pending?(canonical) ||
                       background_publish_active_state?(canonical) || local_space_edit_session?(canonical, state, model) ||
                       publish_critical_section? || publish_post_quiet? || @updating || @single_space_update_job ||
                       @space_batch_update_job || @soft_ingest_batch_job
        quick_copy_action = "linked_space_copy_begin:#{selected_space['id']}"
        quick_copy_enabled = !copy_blocked && entity_native_locked?(selected_space_entity)
        quick_copy_active = false
        quick_copy_tooltip = if canonical.nil?
                               '联动来源已缺失，请先刷新协同清单'
                             elsif copy_blocked
                               '该空间正在修改、发布或等待任务，完成后才能建立联动副本'
                             elsif !entity_native_locked?(selected_space_entity)
                               '请先结束当前修改并锁定空间根'
                             else
                               "复制 #{space_ui_label(selected_space)} 为联动空间"
                             end
      end

      # v0.13.6.136：顶部不再提供“发布组件”入口。
      # 选中一个尚未定义、且无法与共享清单可靠匹配的普通组件时，只显示绿色定义按钮。
      # 组件本机修改仅缓存 dirty；真正上传由“发布包含它的空间”触发。
      # 对方共享端只要存在任意可安全更新的协同组件，新版统一汇总成一个黄色圆形按钮，
      # 点击后一次确认、一次进度流程更新当前模型内所有对应组件。
      unless placement || pending_selected_rows.any?
        selected_component = selected_shared_component_instance(model, allow_unmanaged: true)
        if selected_component && selected_component.valid?
          definition = selected_component.definition rescue nil
          if definition && definition.valid? && shared_component_definition_id(definition).empty?
            matched_record = selection_fast ? matching_shared_component_record_for_definition_fast(definition, state, model) : matching_shared_component_record_for_definition(definition, state, model)
            unless matched_record
              quick_component_action = 'shared_component_define'
              quick_component_icon = 'plus'
              quick_component_tooltip = '定义协同组件；之后修改会缓存，发布包含它的空间时一并上传'
              quick_component_enabled = !publish_critical_section? && !publish_post_quiet? && !@updating
              quick_component_active = false
              quick_component_color = [49, 145, 111]
            end
          end
        end

        plan_cache_available = (@shared_component_bulk_plan_cache || {}).key?(model.object_id)
        update_plan = selection_fast ? shared_component_bulk_update_plan_snapshot(model) : shared_component_bulk_update_plan(model, state, force: false)
        available_updates = Array(update_plan[:rows])
        blocked_updates = Array(update_plan[:blocked])
        unless available_updates.empty? && blocked_updates.empty?
          quick_component_update_action = 'shared_component_update_all'
          quick_component_update_icon = 'download'
          instance_count = available_updates.sum { |row| row[:instance_count].to_i }
          if available_updates.empty?
            quick_component_update_tooltip = "#{blocked_updates.length} 个协同组件有新版；当前 SU 会话有未发布修改，点击查看处理提示"
          else
            source_space_count = available_updates.map { |row| row[:source_space_id].to_s }.reject(&:empty?).uniq.length
            space_hint = source_space_count.positive? ? " · 关联 #{source_space_count} 个发布空间" : ''
            quick_component_update_tooltip = "一致更新空间与组件 · #{available_updates.length} 个组件 / #{instance_count} 个实例#{space_hint}"
            quick_component_update_tooltip += "；另有 #{blocked_updates.length} 个当前会话修改暂不覆盖" unless blocked_updates.empty?
          end
          quick_component_update_enabled = !publish_critical_section? && !@updating && !@shared_component_batch_update_job && !@consistency_update_job
          quick_component_update_active = true
          quick_component_update_color = [214, 164, 45]
        end
      end

      if selection_fast && defined?(plan_cache_available) && !plan_cache_available && defined?(previous_toolbar) && previous_toolbar.is_a?(Hash)
        quick_component_update_action = previous_toolbar['quick_component_update_action'].to_s
        quick_component_update_icon = previous_toolbar['quick_component_update_icon'].to_s unless previous_toolbar['quick_component_update_icon'].to_s.empty?
        quick_component_update_tooltip = previous_toolbar['quick_component_update_tooltip'].to_s
        quick_component_update_enabled = previous_toolbar['quick_component_update_enabled'] == true
        quick_component_update_active = previous_toolbar['quick_component_update_active'] == true
        quick_component_update_color = Array(previous_toolbar['quick_component_update_color']) unless Array(previous_toolbar['quick_component_update_color']).empty?
      end

      if @consistency_update_job
        quick_primary_enabled = false unless quick_primary_action.to_s.empty?
        quick_primary_tooltip = '空间与协同组件正在一致性更新，请等待完成' unless quick_primary_action.to_s.empty?
        quick_component_enabled = false
        quick_component_update_enabled = false
        quick_cancel_enabled = false
        quick_force_unlock_enabled = false
        quick_copy_enabled = false
      end

      quick_context_text, quick_context_tooltip, quick_context_width = quick_context_status(
        state, host_key, selected_space, selected_architecture, model, fast: selection_fast
      )

      project_connected = onboarding['connected'] == true
      project_label = project_connected ? File.basename(project_dir.to_s.tr('\\', '/')) : ''
      publish_queue_jobs = task_center_snapshot
      publish_queue_active_count = task_center_active_count
      toolbar_display_mode = if selected_external_soft_count.positive?
                               selected_external_soft_mode
                             elsif selection_fast
                               previous_mode = previous_toolbar.is_a?(Hash) ? previous_toolbar['display_mode'].to_s : ''
                               %w[proxy full].include?(previous_mode) ? previous_mode : effective_space_display_mode(state)
                             else
                               displayed_space_display_mode(state, model)
                             end
      {
        'visible' => true,
        'quick_toolbar_visible' => relevant,
        'publish_queue_jobs' => publish_queue_jobs,
        'publish_queue_active_count' => publish_queue_active_count,
        'drawer_stage' => 'ready',
        # 轻量刷新只更新锁、按钮等高频状态，不应把已经展开抽屉中的空间组和空间卡片清空。
        'drawer_detailed' => detailed == true,
        'drawer_message' => onboarding['message'].to_s,
        'drawer_error' => '',
        'space_editing' => !!item,
        'space_inside' => space_inside,
        'space_id' => item ? item['id'].to_s : '',
        'space_name' => item ? space_ui_label(item) : '',
        'architecture_action' => architecture_action,
        'architecture_pending' => architecture_pending,
        'architecture_enabled' => architecture_enabled,
        'hard_action' => hard_action,
        'hard_enabled' => hard_enabled,
        'quick_primary_action' => quick_primary_action,
        'quick_primary_label' => quick_primary_label,
        'quick_primary_icon' => quick_primary_icon,
        'quick_primary_tooltip' => quick_primary_tooltip,
        'quick_primary_enabled' => quick_primary_enabled,
        'quick_primary_active' => quick_primary_active,
        'quick_primary_color' => quick_primary_color,
        'quick_component_action' => quick_component_action,
        'quick_component_icon' => quick_component_icon,
        'quick_component_tooltip' => quick_component_tooltip,
        'quick_component_enabled' => quick_component_enabled,
        'quick_component_active' => quick_component_active,
        'quick_component_color' => quick_component_color,
        'quick_component_update_action' => quick_component_update_action,
        'quick_component_update_icon' => quick_component_update_icon,
        'quick_component_update_tooltip' => quick_component_update_tooltip,
        'quick_component_update_enabled' => quick_component_update_enabled,
        'quick_component_update_active' => quick_component_update_active,
        'quick_component_update_color' => quick_component_update_color,
        'quick_copy_action' => quick_copy_action,
        'quick_copy_tooltip' => quick_copy_tooltip,
        'quick_copy_enabled' => quick_copy_enabled,
        'quick_copy_active' => quick_copy_active,
        'quick_copy_confirm' => quick_copy_confirm,
        'quick_copy_color' => quick_copy_color,
        'quick_cancel_action' => quick_cancel_action,
        'quick_cancel_tooltip' => quick_cancel_tooltip,
        'quick_cancel_enabled' => quick_cancel_enabled,
        'quick_cancel_color' => quick_cancel_color,
        'quick_force_unlock_action' => quick_force_unlock_action,
        'quick_force_unlock_tooltip' => quick_force_unlock_tooltip,
        'quick_force_unlock_enabled' => quick_force_unlock_enabled,
        'quick_force_unlock_active' => quick_force_unlock_active,
        'quick_force_unlock_color' => quick_force_unlock_color,
        'quick_context_text' => quick_context_text,
        'quick_context_tooltip' => quick_context_tooltip,
        'quick_context_width' => quick_context_width,
        'quick_library_buttons' => quick_library_buttons,
        'quick_aux_buttons' => quick_aux_buttons,
        'selected_space_id' => selected_space ? selected_space['id'].to_s : '',
        'references_supported' => references_supported,
        'references_button_visible' => references_button_visible,
        'references_enabled' => references_supported,
        'references_visible' => space_inside ? item['edit_references_visible'] == true : workspace_references_visible?(state, model),
        'representation_supported' => representation_supported,
        'representation_enabled' => representation_enabled,
        'display_mode' => toolbar_display_mode,
