        'drawer_space_collection_label' => active_space_collection_label,
        'drawer_architecture_loaded_count' => architecture_loaded_count,
        'drawer_architecture_hidden' => state['architecture_collection_hidden'] == true,
        'professional_section_collapsed' => state['professional_section_collapsed'],
        'drawer_project_connected' => project_connected,
