        'drawer_selection_count' => model.selection.length,
        'drawer_space_loaded_count' => detailed ? state['space_collection_loaded_count'].to_i : 0,
        'drawer_space_hidden' => detailed && space_collection_hidden_active?(state, model, active_space_collection_key),
        'drawer_backup_dir' => backup_dir.to_s,
