      }
    rescue StandardError => e
      log_exception('构建工作空间工具条状态失败', e)
      @workspace_toolbar_last_good_state ||= {}
      previous = @workspace_toolbar_last_good_state[model.object_id]
      if previous.is_a?(Hash)
        fallback = previous.dup
        fallback['visible'] = true
        fallback['drawer_error'] = "工具条状态刷新失败：#{e.message}"
        fallback
      else
        {
