    def schedule_proxy_first_enforcement(model = Sketchup.active_model, force: false)
      return false unless model
      @proxy_first_policy_checked ||= {}
      @proxy_first_policy_pending ||= {}
      key = model.object_id
      return true if @proxy_first_policy_pending[key]
      return true if @proxy_first_policy_checked[key] && !force
      @proxy_first_policy_checked[key] = true
      @proxy_first_policy_pending[key] = true
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.08, false) do
        begin
          active = Sketchup.active_model
          next unless active == model
          state = ensure_space_models_ready!(model)
          host_key = host_discipline_for(state)
          next unless SOFT_PROXY_FIRST_HOSTS.include?(host_key)
          next unless state['space_preview_full_id'].to_s.empty?
          next if Array(state['space_models']).empty?
          actual = actual_space_display_mode(state, model)
          if state['space_display_mode'].to_s != 'proxy' || actual == 'full'
            set_space_display_mode(
              'proxy', model,
              allow_architecture_context: host_key == 'architecture',
              allow_landscape_context: host_key == 'landscape',
              silent: true,
              purge_full_after_proxy: true,
              state: state
            )
            log("代理优先策略已自动恢复：#{host_key}")
          end
        rescue StandardError => e
          log_exception('执行代理优先策略失败', e)
        ensure
          @proxy_first_policy_pending.delete(key)
        end
      end
      true
    rescue StandardError
      @proxy_first_policy_pending&.delete(model.object_id) if model
      false
    end

    def refresh_workspace_toolbar(model = Sketchup.active_model, detailed: nil, state: nil, selection_fast: false)
      unless linkhub_enabled?
        shutdown_workspace_toolbars! unless (@workspace_toolbar_records || {}).empty?
        return false
      end
      return false unless workspace_toolbar_supported?
      overlay = ensure_workspace_toolbar_for_model(model)
      return false unless overlay
      detailed = overlay.drawer_open? if detailed.nil? && overlay.respond_to?(:drawer_open?)
      payload = workspace_toolbar_state(model, detailed: detailed == true, state: state, selection_fast: selection_fast)
      @workspace_toolbar_last_good_state ||= {}
      @workspace_toolbar_last_good_state[model.object_id] = payload if payload.is_a?(Hash) && payload['visible'] != false && payload['drawer_error'].to_s.empty?
      overlay.update_state(payload)
      schedule_proxy_first_enforcement(model)
      model.active_view.invalidate if model == Sketchup.active_model
      true
    rescue StandardError => e
      log_exception('刷新工作空间工具条失败', e)
      false
    end

    # 队列进度变化只更新已经存在的 Overlay，不创建工具条、不读取模型状态，
    # 也不刷新任何 HtmlDialog。任务完成时仍由收尾逻辑做一次正常完整刷新。
    def refresh_publish_queue_overlay_only!(model = Sketchup.active_model, jobs = nil)
      return false unless model
      record = (@workspace_toolbar_records || {})[model.object_id]
      overlay = record.is_a?(Hash) ? record[:overlay] : nil
      return false unless overlay && overlay.respond_to?(:update_publish_queue_state!)
      snapshot = jobs || task_center_snapshot
      active_count = Array(snapshot).count do |row|
        %w[queued running success].include?(row['status'].to_s) || row['main_finalize_pending'] == true
      end
      overlay.update_publish_queue_state!(snapshot, active_count)
    rescue StandardError => e
      log_exception('轻量刷新任务中心失败', e)
      false
    end

    def set_professional_section_collapsed!(section_key, collapsed, model = Sketchup.active_model)
      state = load_state(model)
      state['professional_section_collapsed'] = {} unless state['professional_section_collapsed'].is_a?(Hash)
      state['professional_section_collapsed'][section_key.to_s] = !!collapsed
      save_state(state, model, write_manifest: false)
      true
    rescue StandardError => e
      log_exception('保存专业板块展开状态失败', e)
      false
    end

    def workspace_toolbar_overlay(model = Sketchup.active_model)
      return nil unless model
      record = (@workspace_toolbar_records || {})[model.object_id]
      overlay = record.is_a?(Hash) ? record[:overlay] : nil
      return overlay if overlay
      # 后台热重载会清空当前运行代的记录，但旧抽屉可能仍在视口中。所有抽屉
      # 动作统一走恢复入口，避免管理、显隐、展开等按钮分别出现“工具条不可用”。
      return nil if @shutting_down || !linkhub_enabled?
      ensure_workspace_toolbar_for_model(model)
    rescue StandardError
      nil
    end

    def workspace_toolbar_open?(model = Sketchup.active_model)
      overlay = workspace_toolbar_overlay(model)
      !!(overlay && overlay.respond_to?(:drawer_open?) && overlay.drawer_open?)
    rescue StandardError
      false
    end

    # 抽屉展开后启动完整状态刷新；原生锁定轻量监视在工作区就绪后常驻，
    # 防止右键解锁因抽屉收起而无人处理。空间远端状态监视仍按需启停。
    def activate_workspace_toolbar_live_refresh(model = Sketchup.active_model)
      return false unless model == Sketchup.active_model
      unless workspace_ready?(nil, model)
        stop_native_lock_monitor
        stop_space_presence_monitor
        stop_space_mirror_prefetch_worker!
        refresh_workspace_toolbar(model, detailed: true)
        return true
      end
      start_native_lock_monitor
      start_space_presence_monitor
      sync_native_preview_state(model)
      refresh_workspace_toolbar(model, detailed: true)
      true
    rescue StandardError => e
      log_exception('启动快速抽屉实时状态失败', e)
      false
    end

    def toggle_soft_designer_dialog
      if @soft_designer_dialog && @soft_designer_dialog.visible?
        @soft_designer_dialog.close
        refresh_workspace_toolbar
        false
      else
        show_soft_designer_dialog
        refresh_workspace_toolbar
        true
      end
    end

    def mark_workspace_toolbar_fast_interaction!(model = Sketchup.active_model, duration: 0.85)
      @workspace_toolbar_fast_interaction_until ||= {}
      @workspace_toolbar_fast_interaction_until[model.object_id] =
        Process.clock_gettime(Process::CLOCK_MONOTONIC) + duration.to_f
      true
    rescue StandardError
      false
    end

    def workspace_toolbar_fast_interaction_active?(model = Sketchup.active_model)
      deadline = (@workspace_toolbar_fast_interaction_until || {})[model.object_id].to_f
      active = deadline > Process.clock_gettime(Process::CLOCK_MONOTONIC)
      (@workspace_toolbar_fast_interaction_until || {}).delete(model.object_id) unless active
      active
    rescue StandardError
      false
    end

    def workspace_toolbar_immediate_local_action?(action_name)
      name = action_name.to_s
      return true if name.start_with?('drawer_space_group_toggle:')
      return true if name.start_with?('drawer_space_group_visibility:')
      return true if name.start_with?('drawer_space_manage_toggle:')
      return true if name.start_with?('drawer_space_visibility:')
      return true if name.start_with?('drawer_space_unload:')
      return true if name.start_with?('drawer_architecture_group_toggle:')
      return true if name.start_with?('drawer_architecture_group_visibility:')
      return true if name.start_with?('drawer_architecture_manage_toggle:')
      return true if name.start_with?('drawer_architecture_model_visibility:')
      return true if name.start_with?('drawer_architecture_model_unload:')
      return true if name.start_with?('drawer_toggle_section:')
      return true if name.start_with?('drawer_set_workspace:')
      %w[
        publish_queue_toggle publish_queue_open_logs publish_queue_clear_completed
        drawer_pin_open drawer_pin drawer_collapse drawer_copy_version drawer_tools drawer_tools_done
        drawer_choose_workspace drawer_cancel_workspace drawer_manage_spaces drawer_manage_architecture drawer_space_manage_done drawer_architecture_manage_done drawer_toggle_space_visibility drawer_toggle_space_visibility_header drawer_toggle_architecture_visibility drawer_toggle_architecture_visibility_header
      ].include?(name)
    end

    def workspace_toolbar_local_action?(action_name)
      name = action_name.to_s
      return true if name.start_with?('drawer_space_manage_toggle:')
      return true if name.start_with?('drawer_space_manage_locate:')
      return true if name.start_with?('drawer_space_manage_rename:')
      return true if name.start_with?('drawer_space_group_')
      return true if name.start_with?('drawer_space_visibility:')
      return true if name.start_with?('drawer_space_unload:')
      return true if name.start_with?('drawer_architecture_group_')
      return true if name.start_with?('drawer_architecture_manage_toggle:')
      return true if name.start_with?('drawer_architecture_model_visibility:')
      return true if name.start_with?('drawer_architecture_model_unload:')
      return true if name.start_with?('drawer_toggle_section:')
      return true if name.start_with?('drawer_set_workspace:')
      return true if %w[
        publish_queue_toggle publish_queue_open_logs publish_queue_clear_completed
        drawer_tool_open_project_folder drawer_tool_open_data_folder
        drawer_tool_open_log_folder drawer_tool_open_panel
      ].include?(name)
      %w[
        drawer_pin_open drawer_pin drawer_collapse drawer_copy_version drawer_reload_plugin drawer_project_settings drawer_refresh_status
        drawer_tools drawer_tools_done drawer_choose_workspace drawer_cancel_workspace drawer_manage_spaces drawer_manage_architecture
        drawer_open_schedule drawer_space_manage_group_selected drawer_space_manage_done
        drawer_architecture_manage_group_selected drawer_architecture_manage_done
        drawer_toggle_space_visibility drawer_toggle_space_visibility_header
        drawer_toggle_architecture_visibility drawer_toggle_architecture_visibility_header
      ].include?(name)
    end

    # 只有纯 Overlay 展开、折叠和勾选动作免占用锁。显隐、卸载、重命名、更新、
    # 发布、切换与热重载即使响应很快也要经过冷却，避免双击把操作执行两次。
    def workspace_toolbar_guard_exempt_action?(action_name)
      name = action_name.to_s
      return true if name.start_with?('drawer_space_group_toggle:')
      return true if name.start_with?('drawer_space_group_visibility:')
      return true if name.start_with?('drawer_space_visibility:')
      return true if name.start_with?('drawer_space_manage_toggle:')
      return true if name.start_with?('drawer_architecture_group_toggle:')
      return true if name.start_with?('drawer_architecture_group_visibility:')
      return true if name.start_with?('drawer_architecture_model_visibility:')
      return true if name.start_with?('drawer_architecture_manage_toggle:')
      return true if name.start_with?('drawer_toggle_section:')
      return true if name.start_with?('drawer_set_workspace:')
      %w[
        publish_queue_toggle publish_queue_open_logs publish_queue_clear_completed
        drawer_pin_open drawer_pin drawer_collapse drawer_copy_version drawer_tools drawer_tools_done
        drawer_choose_workspace drawer_cancel_workspace drawer_manage_spaces
        drawer_manage_architecture drawer_space_manage_done drawer_architecture_manage_done
        drawer_toggle_space_visibility drawer_toggle_space_visibility_header
        drawer_toggle_architecture_visibility drawer_toggle_architecture_visibility_header
      ].include?(name)
    end

    # v0.13.6.29：代理/真模型不再是“反向切换”按钮，而是显式目标状态。
    # 选择混合状态时，点击代理就全部代理；点击真模型就全部真模型。
    def apply_workspace_representation_direction!(desired, model = Sketchup.active_model)
      desired = desired.to_s == 'full' ? 'full' : 'proxy'
      state = ensure_space_models_ready!(model)
      host_key = host_discipline_for(state)
      unless [SPACE_COLLECTION_KEY, SOFT_SPACE_COLLECTION_KEY, 'architecture', 'landscape'].include?(host_key)
        raise '只有硬装、软装、建筑或景观工作区可以切换家具代理与真模型。'
      end
      raw_ingest_selection = model.selection.to_a
      raw_ingest_submitted = []
      if raw_ingest_selection.any?
        raw_ingest_submitted = request_soft_ingest_commit_from_button!(raw_ingest_selection, desired, model)
      end
      selection_scope = resolve_soft_representation_selection_scope(model, state, allow_recent: true)
      selected_external_soft = Array(selection_scope[:targets])
      unless selected_external_soft.empty?
        set_selected_external_soft_display_mode(
          desired, selected_external_soft, model, selection_scope: selection_scope
        )
        overlay = workspace_toolbar_overlay(model)
        if soft_pending_proxy_records_for_targets(selected_external_soft, model).empty? && !@soft_ingest_batch_job
          overlay.set_representation_mode_local!(desired) if overlay && overlay.respond_to?(:set_representation_mode_local!)
        end
        return true
      end
      return true unless raw_ingest_submitted.empty?
      if selection_scope[:explicit] && selection_scope[:kind] == :empty_container
        raise '当前选中的组/组件内没有可切换的 LinkHub 家具；不会回退为整个空间切换。'
      end
      current_ingest_item = current_soft_designer_fab_space(model) rescue nil
      if current_ingest_item && @soft_ingest_batch_job.is_a?(Hash) && @soft_ingest_batch_job[:space_id].to_s == current_ingest_item['id'].to_s
        requested_ingest = request_soft_ingest_commit_from_button!([], desired, model, all_in_scope: true)
        return true unless requested_ingest.empty?
      end
      if soft_pending_proxy_rebuild_records(model).any?
        # v0.13.6.177：没有明确选择时点击“代理”，也不再因为少数 pending 家具
        # 锁死整个空间。普通家具立即切代理；当前空间内真正待刷新那几款直接提升为
        # allow_inside_space 的高优先级代理任务，完成后自动补齐，不需要退出/发布。
        current_item = current_soft_designer_fab_space(model) rescue nil
        current_entity = current_item ? space_model_entity(current_item['id'], model) : nil
        scoped_pending = if current_item && current_entity && current_entity.valid?
                           soft_pending_proxy_records_for_space(current_item, current_entity, model)
                         else
                           soft_pending_proxy_rebuild_records(model)
                         end
        if desired == 'full' && !scoped_pending.empty?
          full_targets = scoped_pending.map { |row| row[:entity] }.select { |node| node && node.valid? }
          set_selected_external_soft_display_mode('full', full_targets, model)
          scoped_pending = []
        end
        unless scoped_pending.empty?
          pending_entities = scoped_pending.filter_map do |record|
            entity = record[:entity]
            entity if entity && entity.valid?
          end.uniq
          if current_entity && current_entity.valid?
            pending_ids = pending_entities.each_with_object({}) { |entity, memo| memo[entity.object_id] = true }
            ordinary = soft_instances_for_space(current_entity, model, force: true).select do |entity|
              entity && entity.valid? && !pending_ids[entity.object_id]
            end
            set_selected_external_soft_display_mode('proxy', ordinary, model, silent: true) unless ordinary.empty?
          end
          set_soft_pending_proxy_display_intent!(pending_entities, 'proxy', model)
          started_count = request_immediate_soft_proxy_refresh_for_records!(scoped_pending, model)
          raise '部分代理提交未启动；当前模型保留，请查看任务中心。' if started_count < scoped_pending.map { |row| row[:model_id].to_s }.uniq.length
          show_status("其它家具已正常切换为代理；#{pending_entities.length} 个修改后家具正在立即更新最新代理，完成后自动切换。", 'info')
          show_workspace_floating_notice("代理立即更新 · #{pending_entities.length} 件", 'info', duration: 3.5, model: model)
          schedule_coalesced_refresh_dialog(0.12)
          return true
        end
      end
      raise '当前项目还没有可切换的硬装/软装空间模型；若要切换单件家具，请先选中该家具。' if Array(state['space_models']).empty?
      allow_architecture_context = host_key == 'architecture'
      allow_landscape_context = host_key == 'landscape'
      item = current_soft_designer_fab_space(model)
      if space_workspace_role?(host_key) && !model.active_path.nil? && !(item && space_edit_context_active?(item, model))
        raise '请先退出当前组件编辑层级，再切换空间的代/真模型。'
      end
      scope_space_id = ''
      if SOFT_PROXY_FIRST_HOSTS.include?(host_key)
        preview_id = state['space_preview_full_id'].to_s
        if desired == 'proxy' && !preview_id.empty?
          scope_space_id = preview_id
        elsif desired == 'full'
          selected_space = selected_workspace_space_record(state, model)
          raise '建筑和景观工作区坚持代理优先。请先选中一个硬装/软装空间根组件，再点击真模型。' unless selected_space
          scope_space_id = selected_space['id'].to_s
        end
      elsif space_workspace_role?(host_key) && desired == 'full' && state['space_editing_id'].to_s.empty?
        selected_space = selected_workspace_space_record(state, model)
        raise '为避免一次载入全部空间高模，请先选中一个硬装/软装空间根组件；插件只展开该空间。' unless selected_space
        scope_space_id = selected_space['id'].to_s
      end
      set_space_display_mode(
        desired, model,
        allow_architecture_context: allow_architecture_context,
        allow_landscape_context: allow_landscape_context,
        scope_space_id: scope_space_id, state: state
      )
      true
    end

    def workspace_action_feedback_message(action)
      name = action.to_s
      case name
      when 'representation_proxy' then '已接收 · 正在切换代理显示'
      when 'representation_full' then '已接收 · 正在切换真模型显示'
      when /\Alinked_space_copy_begin:/ then '已接收 · 正在准备复制空间'
      when 'linked_space_copy_finish' then '已接收 · 正在确认联动空间'
      when 'linked_space_pending_finish' then '已接收 · 正在登记联动副本'
      when /\Alinked_space_transform_begin:/ then '已接收 · 正在进入联动空间位置调整'
      when 'linked_space_adopt_duplicate' then '已接收 · 正在识别原生复制的空间'
      when /force_unlock/ then '已接收 · 正在准备强制解锁'
      when /force_restore/ then '已接收 · 正在恢复空间'
      when /release_occupancy/ then '已接收 · 正在解除协作占用'
      when /(?:\Aquick_cancel_|discard|cancel_edit)/ then '已接收 · 正在取消本地修改'
      when /(?:_unload:|\Aunload_)/ then '已接收 · 正在卸载模型'
      when 'shared_component_define' then '已接收 · 正在定义协同组件'
      when /shared_component_publish:/ then '已接收 · 正在发布协同组件'
      when 'shared_component_update_all' then '已接收 · 正在汇总空间与组件更新'
      when /shared_component_(?:adopt_)?update:/ then '已接收 · 正在更新协同组件'
      when /(?:_publish:|publish_collab|\Apublish_)/ then '已接收 · 正在检查并提交发布'
      when /(?:_edit:|begin_edit)/ then '已接收 · 正在进入编辑'
      when /(?:_update:|_load:|\Aquick_update_|landscape_update)/ then '已接收 · 正在检查更新'
      when 'drawer_reload_plugin' then '已接收 · 正在重新载入插件'
      else ''
      end
    rescue StandardError
      ''
    end

    def handle_workspace_toolbar_action(action, model = Sketchup.active_model)
      action_claimed = false
      action_key = ''
      skip_post_toolbar_refresh = false
      return false unless model == Sketchup.active_model
      action_name = action.to_s
      local_overlay_action = workspace_toolbar_local_action?(action_name)
      unless workspace_toolbar_guard_exempt_action?(action_name)
        @workspace_action_active ||= {}
        @workspace_action_active_started_at ||= {}
        @workspace_action_cooldown_until ||= {}
        model_key = model.object_id
        active_action = @workspace_action_active[model_key].to_s
        unless active_action.empty?
          active_started = @workspace_action_active_started_at[model_key].to_f
          active_age = active_started.positive? ? monotonic_time - active_started : Float::INFINITY
          # Overlay 动作都在 SketchUp 主线程同步执行；正常动作一定会经过 ensure 清理。
          # 没有起始时间或已超过恢复窗的记录，只可能来自异常中断/旧运行代，直接自愈。
          if active_age > 2.5
            log("已清理抽屉残留操作门禁：#{active_action} / #{active_age.finite? ? active_age.round(2) : '旧运行代'}秒")
            @workspace_action_active.delete(model_key)
            @workspace_action_active_started_at.delete(model_key)
          else
            raise "“#{active_action}”正在处理中，请勿重复点击。"
          end
        end
        action_key = "#{model_key}|#{action_name}"
        return false if monotonic_time < @workspace_action_cooldown_until[action_key].to_f
        @workspace_action_active[model_key] = action_name
        @workspace_action_active_started_at[model_key] = monotonic_time
        action_claimed = true
      end
      # 任何抽屉本地按钮都先恢复/认领 Overlay。这样即使用户刚点击后台重载，
      # 仍可立即继续展开、显隐、管理和复选，不会因为运行代记录清空而失效。
      overlay = workspace_toolbar_overlay(model)
      feedback = workspace_action_feedback_message(action_name)
      overlay.show_floating_notice(feedback, 'info', duration: 2.2) if !feedback.empty? && overlay && overlay.respond_to?(:show_floating_notice)
      mark_workspace_toolbar_fast_interaction!(model) if local_overlay_action
      # 展开、管理、分组、显隐和工具页都只操作已经绘制在本机 Overlay 中的状态。
      # 旧版每次点击前都重新读取协同 JSON/共享目录，局域网稍有延迟就让按钮像“慢半拍”。
      # 这些本地动作跳过连接探测；真正的更新、发布、连接动作仍保留完整检查。
      connection_free = local_overlay_action || action_name.start_with?('drawer_tool_') ||
                        %w[drawer_pin_open drawer_pin drawer_collapse drawer_reload_plugin drawer_tools drawer_tools_done
                           drawer_choose_workspace drawer_cancel_workspace drawer_manage_spaces drawer_manage_architecture drawer_open_schedule drawer_project_settings drawer_refresh_status].include?(action_name)
      onboarding = connection_free ? { 'stage' => 'ready', 'message' => '' } : collaboration_connection_info(nil, model)
      always_allowed = %w[drawer_pin_open drawer_pin drawer_collapse drawer_create_project drawer_connect_project drawer_reload_plugin drawer_refresh_status]
      workspace_allowed = action_name.start_with?('drawer_set_workspace:')
      unless onboarding['stage'] == 'ready' || always_allowed.include?(action_name) || (onboarding['stage'] == 'workspace' && workspace_allowed)
        raise(onboarding['stage'] == 'workspace' ? '请先选择建筑、硬装、软装或景观工作区。' : onboarding['message'].to_s)
      end
      item = (!connection_free && onboarding['stage'] == 'ready') ? current_soft_designer_fab_space(model) : nil
      case action_name
      when 'shared_component_define'
        define_selected_shared_component(model)
      when 'shared_component_update_all'
        request_consistency_component_update!(model)
      when /\Ashared_component_publish:(.+)\z/
        publish_shared_component_by_id(Regexp.last_match(1).to_s, model)
      when /\Ashared_component_adopt_update:(.+)\z/
        adopt_and_update_shared_component!(Regexp.last_match(1).to_s, model)
      when /\Ashared_component_update:(.+)\z/
        update_shared_component_by_id(Regexp.last_match(1).to_s, model)
      when 'architecture_sync'
        state = ensure_architecture_models_ready!(model)
        architecture_collection_quick_action(model, state: state)
      when 'hard_sync'
        hard_finish_quick_action(model)
      when /\Alinked_space_copy_begin:(.+)\z/
        begin_linked_space_copy!(Regexp.last_match(1).to_s, model)
      when 'linked_space_copy_finish'
        finish_linked_space_copy!(model)
      when 'linked_space_pending_finish'
        finish_pending_linked_space_clone!(model)
      when /\Alinked_space_transform_begin:(.+)\z/
        begin_linked_space_transform!(Regexp.last_match(1).to_s, nil, model)
      when 'linked_space_adopt_duplicate'
        adopt_duplicate_space_root_as_linked_pending!(model)
      when /\Adrawer_linked_pending_finish:(.+)\z/
        select_and_finish_pending_linked_space_clone!(Regexp.last_match(1).to_s, model)
      when 'quick_update_spaces'
        state = ensure_space_models_ready!(model)
        role = host_discipline_for(state)
        update_all_space_models(notify: true, model: model, collection_key: (space_workspace_role?(role) ? role : nil))
      when 'quick_update_architecture'
        state = ensure_architecture_models_ready!(model)
        update_all_architecture_models(notify: true, model: model, state: state)
      when 'landscape_sync'
        update_landscape_safely(notify: true)
      when 'architecture_library'
        state = ensure_space_models_ready!(model)
        raise '建筑库只在建筑工作区提供。' unless host_discipline_for(state) == 'architecture'
        toggle_architecture_library_dialog
      when 'workbench'
        state = ensure_space_models_ready!(model)
        raise '软装库只在软装工作区提供。' unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
        toggle_soft_designer_dialog
      when 'landscape_library'
        state = ensure_space_models_ready!(model)
        raise '景观模型库只在景观工作区提供。' unless host_discipline_for(state) == 'landscape'
        toggle_landscape_library_dialog
      when /\Amaterial_library:(.+)\z/
        discipline = Regexp.last_match(1).to_s
        state = ensure_space_models_ready!(model)
        raise '请在当前工作区打开对应的材质库。' unless host_discipline_for(state) == discipline
        toggle_material_library_dialog(discipline)
      when 'library_pipette', 'library_ingest'
        handle_library_pipette(model)
      when 'soft_batch_ingest'
        open_soft_batch_ingest_dialog(model)
      when 'soft_schedule'
        state = ensure_space_models_ready!(model)
        raise '项目软装清单只在软装工作区提供。' unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
        show_project_soft_schedule_dialog
      when 'references'
        toggle_workspace_references(model)
      when 'representation_proxy'
        skip_post_toolbar_refresh = true
        apply_workspace_representation_direction!('proxy', model)
      when 'representation_full'
        skip_post_toolbar_refresh = true
        apply_workspace_representation_direction!('full', model)
      when 'representation'
        skip_post_toolbar_refresh = true
        state = ensure_space_models_ready!(model)
        scope = resolve_soft_representation_selection_scope(model, state, allow_recent: true)
        targets = Array(scope[:targets])
        current = targets.empty? ? displayed_space_display_mode(state, model) : selected_soft_instances_display_mode(targets)
        apply_workspace_representation_direction!(current == 'proxy' ? 'full' : 'proxy', model)
      when 'publish_queue_toggle'
        overlay.toggle_publish_queue_panel! if overlay && overlay.respond_to?(:toggle_publish_queue_panel!)
      when 'publish_queue_open_logs'
        open_linkhub_log_directory
      when 'publish_queue_clear_completed'
        clear_completed_task_center_history!
      when 'drawer_pin_open'
        overlay.expand_drawer!(pin: true) if overlay && overlay.respond_to?(:expand_drawer!)
      when 'drawer_pin'
        overlay.toggle_drawer_pin! if overlay && overlay.respond_to?(:toggle_drawer_pin!)
      when 'drawer_collapse'
        overlay.collapse_drawer!(force: true) if overlay && overlay.respond_to?(:collapse_drawer!)
      when 'drawer_copy_version'
        version_text = "SU LinkHub v#{EXTENSION_VERSION}"
        copied = UI.respond_to?(:set_clipboard_data) && UI.set_clipboard_data(version_text)
        raise '当前 SketchUp 无法写入剪贴板。' unless copied
        overlay.show_floating_notice("#{version_text} 已复制", 'success') if overlay && overlay.respond_to?(:show_floating_notice)
      when 'drawer_reload_plugin'
        reload_or_update_plugin!(model)
      when 'drawer_project_settings'
        show_project_settings_dialog(model)
      when 'drawer_tools'
        raise 'LinkHub 工具页不可用。' unless overlay && overlay.respond_to?(:toggle_drawer_tools_mode!)
        overlay.toggle_drawer_tools_mode!
      when 'drawer_tools_done'
        overlay.finish_drawer_tools_mode! if overlay && overlay.respond_to?(:finish_drawer_tools_mode!)
      when 'drawer_tool_save_model'
        save_active_model
      when 'drawer_tool_save_backup_now'
        save_working_copy_now
      when 'drawer_tool_open_backup_folder'
        open_or_choose_architecture_backup_directory(model)
      when 'drawer_tool_choose_backup_folder'
        choose_architecture_backup_directory(model)
      when 'drawer_tool_backup_interval'
        edit_architecture_backup_interval_from_drawer(model)
      when 'drawer_tool_open_project_folder'
        open_collaboration_project_directory(model)
      when 'drawer_tool_open_data_folder'
        open_project_metadata_folder
      when 'drawer_tool_open_log_folder'
        open_linkhub_log_directory
      when 'drawer_tool_open_panel', 'drawer_open_panel'
        # 兼容热重载前残留的旧按钮；主面板已移除，统一回到抽屉。
        show_dialog
      when 'drawer_create_project'
        create_collab_project
      when 'drawer_connect_project'
        connect_existing_collab_project
      when 'drawer_refresh_status'
        run_linkhub_full_check(model, repair: true, notify: true)
      when 'drawer_choose_workspace'
        overlay = workspace_toolbar_overlay(model)
        raise 'LinkHub 抽屉不可用。' unless overlay && overlay.respond_to?(:open_workspace_picker!)
        overlay.open_workspace_picker!
      when 'drawer_cancel_workspace'
        overlay = workspace_toolbar_overlay(model)
        overlay.close_workspace_picker! if overlay && overlay.respond_to?(:close_workspace_picker!)
      when 'drawer_update_all'
        update_all_with_spaces
      when 'drawer_update_all_architecture'
        update_all_architecture_models(notify: true, model: model)
      when /\Adrawer_toggle_section:(architecture|#{Regexp.escape(SPACE_COLLECTION_KEY)}|#{Regexp.escape(SOFT_SPACE_COLLECTION_KEY)})\z/
        overlay = workspace_toolbar_overlay(model)
        raise 'LinkHub 抽屉不可用。' unless overlay && overlay.respond_to?(:toggle_professional_section!)
        overlay.toggle_professional_section!(Regexp.last_match(1).to_s)
      when 'drawer_manage_architecture'
        overlay = workspace_toolbar_overlay(model)
        raise '建筑模型管理工具条不可用。' unless overlay && overlay.respond_to?(:toggle_architecture_manage_mode!)
        state = ensure_architecture_models_ready!(model)
        raise '请切换到建筑工作区后管理建筑模型。' unless host_discipline_for(state) == 'architecture'
        raise '请先退出所有组件编辑层级，再进入建筑模型管理。' unless model.active_path.nil?
        overlay.toggle_architecture_manage_mode!
      when 'drawer_add_architecture'
        add_architecture_model_from_selection
      when 'drawer_toggle_architecture_visibility', 'drawer_toggle_architecture_visibility_header'
        toggle_architecture_collection_visibility(model)
      when 'drawer_architecture_library'
        state = ensure_architecture_models_ready!(model)
        raise '建筑库只在建筑工作区提供。' unless host_discipline_for(state) == 'architecture'
        toggle_architecture_library_dialog
      when /\Adrawer_architecture_model_edit:(.+)\z/
        edit_architecture_model(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_model_publish:(.+)\z/
        publish_architecture_model(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_model_update:(.+)\z/
        update_architecture_model(Regexp.last_match(1).to_s, notify: true, model: model)
      when /\Adrawer_architecture_model_load:(.+)\z/
        update_architecture_model(Regexp.last_match(1).to_s, notify: true, model: model)
      when /\Adrawer_architecture_model_unload:(.+)\z/
        unload_architecture_model_from_current_model!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_model_release:(.+)\z/
        release_same_user_architecture_occupancy!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_model_visibility:(.+)\z/
        toggle_architecture_model_visibility(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_manage_toggle:(.+)\z/
        overlay = workspace_toolbar_overlay(model)
        overlay.toggle_architecture_manage_selection!(Regexp.last_match(1).to_s) if overlay && overlay.respond_to?(:toggle_architecture_manage_selection!)
      when /\Adrawer_architecture_manage_rename:(.+)\z/
        rename_architecture_model(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_group_visibility:(.+)\z/
        toggle_architecture_group_visibility(Regexp.last_match(1).to_s, model)
      when /\Adrawer_architecture_group_toggle:(.*)\z/
        group_id = Regexp.last_match(1).to_s
        toggle_architecture_group_collapsed(group_id, model) unless group_id.empty?
      when /\Adrawer_architecture_group_rename:(.+)\z/
        rename_architecture_group(Regexp.last_match(1).to_s, model)
      when 'drawer_architecture_manage_delete_selected'
        overlay = workspace_toolbar_overlay(model)
        ids = overlay && overlay.respond_to?(:architecture_manage_selected_ids) ? overlay.architecture_manage_selected_ids : []
        request_delete_selected_architecture_models(ids, model)
      when 'drawer_architecture_manage_group_selected'
        overlay = workspace_toolbar_overlay(model)
        ids = overlay && overlay.respond_to?(:architecture_manage_selected_ids) ? overlay.architecture_manage_selected_ids : []
        create_architecture_group(ids, model)
      when 'drawer_architecture_manage_done'
        overlay = workspace_toolbar_overlay(model)
        overlay.finish_architecture_manage_mode! if overlay && overlay.respond_to?(:finish_architecture_manage_mode!)
      when 'drawer_architecture_quick'
        architecture_collection_quick_action(model)
      when 'drawer_architecture_previous'
        update_architecture_previous_published(model)
      when 'drawer_landscape_update'
        update_landscape_safely(notify: true)
      when 'drawer_landscape_quick'
        landscape_quick_action(model)
      when 'drawer_publish_collab'
        publish_collab_cache
      when 'drawer_open_schedule'
        show_project_soft_schedule_dialog
      when 'drawer_manage_spaces'
        overlay = workspace_toolbar_overlay(model)
        raise '空间管理工具条不可用。' unless overlay && overlay.respond_to?(:toggle_space_manage_mode!)
        if overlay.respond_to?(:space_manage_mode?) && !overlay.space_manage_mode? && !model.active_path.nil?
          raise '请先退出所有组件编辑层级，再进入空间管理。'
        end
        overlay.toggle_space_manage_mode!
      when 'drawer_add_space'
        add_space_model_from_selection
      when 'drawer_toggle_space_mode'
        skip_post_toolbar_refresh = true
        state = ensure_space_models_ready!(model)
        desired = toggled_space_display_mode(state, model)
        set_space_display_mode(desired, model, state: state)
      when 'drawer_toggle_space_visibility', 'drawer_toggle_space_visibility_header'
        toggle_space_collection_visibility
      when /\Adrawer_begin_edit:(.+)\z/
        discipline = Regexp.last_match(1).to_s
        begin_edit_session(discipline) if DISCIPLINES.key?(discipline)
      when /\Adrawer_visibility:(.+)\z/
        discipline = Regexp.last_match(1).to_s
        toggle_professional_visibility(discipline) if DISCIPLINES.key?(discipline)
      when /\Adrawer_refresh_reset:(.+)\z/
        discipline = Regexp.last_match(1).to_s
        refresh_and_reset_link(discipline) if DISCIPLINES.key?(discipline)
      when /\Aquick_force_unlock_space:(.+)\z/
        begin_space_force_recovery!(Regexp.last_match(1).to_s, model)
      when /\Aquick_force_restore_space:(.+)\z/
        finish_space_force_recovery!(Regexp.last_match(1).to_s, model, reason: '手动结束强制解锁')
      when /\Adrawer_space_edit:(.+)\z/
        edit_space_model_with_workspace_prompt(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_publish:(.+)\z/
        publish_space_now(Regexp.last_match(1).to_s, model)
      when /\Aquick_cancel_space:(.+)\z/
        cancel_space_modifications!(Regexp.last_match(1).to_s, model)
      when /\Aquick_cancel_architecture:(.+)\z/
        cancel_architecture_modifications!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_update:(.+)\z/
        request_space_update_with_shared_components!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_load:(.+)\z/
        request_space_update_with_shared_components!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_unload:(.+)\z/
        unload_space_model_from_current_model!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_release_occupancy:(.+)\z/
        release_same_user_space_occupancy!(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_visibility:(.+)\z/
        toggle_single_space_visibility(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_manage_toggle:(.+)\z/
        overlay = workspace_toolbar_overlay(model)
        overlay.toggle_space_manage_selection!(Regexp.last_match(1).to_s) if overlay && overlay.respond_to?(:toggle_space_manage_selection!)
      when /\Adrawer_space_manage_locate:(.+)\z/
        focus_space_model_from_manager(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_manage_rename:(.+)\z/
        rename_space_model(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_group_visibility:(.+)\z/
        toggle_space_group_visibility(Regexp.last_match(1).to_s, model)
      when /\Adrawer_space_group_toggle:(.*)\z/
        group_id = Regexp.last_match(1).to_s
        toggle_space_group_collapsed(group_id, model) unless group_id.empty?
      when /\Adrawer_space_group_rename:(.+)\z/
        rename_space_group(Regexp.last_match(1).to_s, model)
      when 'drawer_space_manage_delete_selected'
        overlay = workspace_toolbar_overlay(model)
        ids = overlay && overlay.respond_to?(:space_manage_selected_ids) ? overlay.space_manage_selected_ids : []
        request_delete_selected_space_models(ids, model)
      when 'drawer_space_manage_group_selected'
        overlay = workspace_toolbar_overlay(model)
        ids = overlay && overlay.respond_to?(:space_manage_selected_ids) ? overlay.space_manage_selected_ids : []
        request_group_selected_space_models(ids, model)
      when 'drawer_space_manage_done'
        overlay = workspace_toolbar_overlay(model)
        overlay.finish_space_manage_mode! if overlay && overlay.respond_to?(:finish_space_manage_mode!)
      when /\Adrawer_set_workspace:(.+)\z/
        requested_role = Regexp.last_match(1).to_s
        current_state = load_state(model)
        if current_state['workspace_configured'] == true && (!current_state['collab_project_json'].to_s.empty? || !current_state['collab_project_dir'].to_s.empty?)
          set_host_discipline_value_fast(requested_role, model)
        else
          set_host_discipline_value(requested_role, model)
        end
        overlay = workspace_toolbar_overlay(model)
        overlay.close_workspace_picker! if overlay && overlay.respond_to?(:close_workspace_picker!)
      when /\Adrawer_space_references:(.+)\z/
        toggle_space_edit_references(Regexp.last_match(1).to_s)
      else
        return false
      end
      # 轻量抽屉动作已经直接修改本地 Overlay；这里若再做一次完整详细刷新，
      # 会重新查询锁、共享文件和空间状态，正是旧版按钮“慢半拍”的主要来源。
      refresh_workspace_toolbar(model) unless local_overlay_action || skip_post_toolbar_refresh
      true
    rescue StandardError => e
      log_exception('执行工作空间工具条操作失败', e)
      show_status("操作失败：#{e.message}", 'error')
      schedule_coalesced_refresh_dialog(0.12) rescue nil
      false
    ensure
      if action_claimed && defined?(model) && model
        @workspace_action_active&.delete(model.object_id)
        @workspace_action_active_started_at&.delete(model.object_id)
        @workspace_action_cooldown_until ||= {}
        @workspace_action_cooldown_until[action_key] = monotonic_time + WORKSPACE_ACTION_COOLDOWN_SECONDS unless action_key.to_s.empty?
      end
      if defined?(action_name) && defined?(model) && model
        persistent_tool_action = %w[library_pipette library_ingest].include?(action_name.to_s) || action_name.to_s.start_with?('linked_space_copy_begin:')
        lightweight_overlay_action = defined?(local_overlay_action) && local_overlay_action
        schedule_restore_default_select_tool(model, delay: 0.06, reason: action_name.to_s) unless persistent_tool_action || lightweight_overlay_action
      end
    end

    def soft_designer_fab_html(item)
      label = "#{item['number']}:#{item['name']}"
      safe_label = label.to_s.gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;').gsub('"', '&quot;')
      <<~HTML
        <!doctype html><html><head><meta charset="utf-8"><style>
        *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:transparent;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}
        body{padding:4px}button{width:100%;height:100%;border:0;border-radius:14px;background:linear-gradient(135deg,#7d59ce,#56349e);color:#fff;display:grid;place-items:center;cursor:pointer;box-shadow:0 7px 19px rgba(63,38,110,.30);font-size:15px;font-weight:900;transition:.14s}button:hover{transform:translateY(-1px);box-shadow:0 9px 22px rgba(63,38,110,.36)}button:active{transform:translateY(0)}
        </style></head><body><button title="打开软装模型库与 #{safe_label} 空间清单" onclick="sketchup.open_designer()">库</button></body></html>
      HTML
    end

    def close_soft_designer_fab(clear_dismissed: false)
      dialog = @soft_designer_fab
      @soft_designer_fab_closing = true
      dialog.close if dialog && dialog.visible?
      @soft_designer_fab = nil
      @soft_designer_fab_space_id = ''
      @soft_designer_fab_dismissed_space_id = '' if clear_dismissed
      true
    rescue StandardError
      @soft_designer_fab = nil
      @soft_designer_fab_space_id = ''
      false
    ensure
      @soft_designer_fab_closing = false
    end

    def refresh_soft_designer_fab(model = Sketchup.active_model)
      unless workspace_ready?(nil, model)
        close_soft_designer_fab(clear_dismissed: true) if @soft_designer_fab
        return refresh_workspace_toolbar(model) if workspace_toolbar_supported?
        return false
      end
      if workspace_toolbar_supported?
        close_soft_designer_fab(clear_dismissed: true) if @soft_designer_fab
        return refresh_workspace_toolbar(model)
      end
      item = current_soft_designer_fab_space(model)
      unless item
        close_soft_designer_fab(clear_dismissed: true) if @soft_designer_fab
        @soft_designer_fab_dismissed_space_id = ''
        return false
      end
      key = item['id'].to_s
      if @soft_designer_fab && @soft_designer_fab.visible?
        if @soft_designer_fab_space_id.to_s != key
          close_soft_designer_fab(clear_dismissed: false)
        else
          return true
        end
      end
      return false if @soft_designer_fab_dismissed_space_id.to_s == key
      style = defined?(UI::HtmlDialog::STYLE_UTILITY) ? UI::HtmlDialog::STYLE_UTILITY : UI::HtmlDialog::STYLE_DIALOG
      dialog = UI::HtmlDialog.new(
        dialog_title: '库',
        preferences_key: 'GavinTools_SULinkHubMultiSpace_SoftDesignerFab',
        scrollable: false,
        resizable: false,
        width: 58,
        height: 58,
        min_width: 58,
        min_height: 58,
        style: style
      )
      @soft_designer_fab = dialog
      @soft_designer_fab_space_id = key
      dialog.set_html(soft_designer_fab_html(item))
      dialog.add_action_callback('open_designer') do |_ctx|
        safe_callback('打开软装模型库') { show_soft_designer_dialog }
      end
      dialog.set_on_closed do
        unless @soft_designer_fab_closing
          @soft_designer_fab_dismissed_space_id = key
        end
        @soft_designer_fab = nil
        @soft_designer_fab_space_id = ''
      end
      dialog.show
      true
    rescue StandardError => e
      log_exception('显示软装管理悬浮按钮失败', e)
      false
    end

    def schedule_soft_library_dialog_load(force: false)
      return false unless @soft_designer_dialog && @soft_designer_dialog.visible?
      return true if @soft_library_scanning
      root = soft_library_root
      if !force && soft_library_cache_ready?(root)
        @soft_library_scanning = false
        refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
        return true
      end
      @soft_library_dialog_load_token = SecureRandom.hex(6)
      token = @soft_library_dialog_load_token
      @soft_library_scanning = true
      refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: false)

      # 手工“刷新目录”最容易卡在 NAS 的递归目录枚举。这一步完全不访问
      # SketchUp API，可安全放入 Ruby I/O 线程；枚举结果回到主线程后，才执行
      # 缓存合并、界面更新和任何可能关联模型状态的逻辑。
      if force && !root.to_s.empty? && Dir.exist?(root)
        organized_root = soft_library_organized_dir(root)
        queued = enqueue_background_io_task(
          'soft_library_directory_scan',
          key: normalize_soft_library_key(root),
          data: { root: root.to_s, organized_root: organized_root.to_s, token: token },
          label: '软装模型库目录后台刷新'
        )
        unless queued
          @soft_library_scanning = false
          raise '无法启动软装模型库后台目录刷新。'
        end
        return true
      end

      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.06, false) do
        next unless @soft_library_dialog_load_token == token
        scan_started = monotonic_time
        begin_soft_heavy_interaction(:library_scan)
        begin
          scan_soft_library!(force: force)
        ensure
          @soft_library_scanning = false
          end_soft_heavy_interaction(:library_scan)
        end
        log("软装模型库载入：#{elapsed_ms(scan_started)}ms，#{Array(@soft_library_cache && @soft_library_cache[:items]).length} 个模型，force=#{force}")
        next unless @soft_designer_dialog && @soft_designer_dialog.visible?
        refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
      rescue StandardError => e
        @soft_library_scanning = false
        log_exception('延迟载入软装模型库失败', e)
        refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: false)
      end
      true
    rescue StandardError => e
      @soft_library_scanning = false
      log_exception('安排软装模型库载入失败', e)
      false
    end

    def refresh_soft_designer_dialog(refresh_library: false, include_library: false, include_measurements: false, include_materials: false)
      return false unless @soft_designer_dialog && @soft_designer_dialog.visible?
      return false unless workspace_ready?(nil, Sketchup.active_model)
      payload = JSON.generate(soft_designer_payload(
        refresh_library: refresh_library,
        include_library: include_library,
        include_measurements: include_measurements,
        include_materials: include_materials
      ))
      @soft_designer_dialog.execute_script("window.SoftDesigner && window.SoftDesigner.receiveState(#{payload});")
      true
    rescue StandardError => e
      log_exception('刷新软装模型库失败', e)
      false
    end

