    def show_soft_designer_dialog
      require_workspace_ready!
      model = Sketchup.active_model
      state = ensure_space_models_ready!(model)
      raise '软装模型库只在软装工作区提供。' unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
      _editing_state, item, entity = current_local_editing_space(nil, model, required: false)
      inside_space = !!(item && entity && entity.valid? && active_path_inside_space?(entity, model))
      if @soft_designer_dialog && @soft_designer_dialog.visible?
        @soft_designer_dialog.bring_to_front
        refresh_soft_designer_dialog
        return true
      end
      @soft_designer_dialog = UI::HtmlDialog.new(
        dialog_title: inside_space ? "软装库 · #{space_ui_label(item)}" : '软装库 · 软装工作区',
        preferences_key: 'GavinTools_SULinkHubMultiSpace_SoftDesigner',
        scrollable: true,
        resizable: true,
        width: 980,
        height: 720,
        min_width: 760,
        min_height: 520,
        style: UI::HtmlDialog::STYLE_DIALOG
      )
      @soft_designer_dialog.set_file(soft_designer_dialog_file)
      bind_soft_designer_callbacks(@soft_designer_dialog)
      @soft_designer_dialog.set_on_closed do
        @soft_measurement_view_active = false
        @soft_library_dialog_load_token = nil
        @soft_library_scanning = false
        stop_soft_measurement_poll_timer
        detach_soft_measurement_entity_observers
        detach_soft_selection_observer
        @soft_designer_dialog = nil
        GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.01, false) { refresh_workspace_toolbar }
      end
      attach_soft_selection_observer(Sketchup.active_model)
      @soft_designer_dialog.show
      true
    end

    def parse_soft_metadata_payload(json)
      data = JSON.parse(json.to_s)
      raise '模型资料格式无效。' unless data.is_a?(Hash)
      data
    rescue JSON::ParserError
      raise '模型资料格式无效。'
    end

    def soft_library_selected_entity_name(entity)
      name = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
      name = entity.definition.name.to_s.strip if name.empty? && entity.respond_to?(:definition) && entity.definition
      name = name.sub(/#[0-9]+\z/, '').strip
      safe_soft_library_filename(name.empty? ? '未命名家具' : name)
    rescue StandardError
      '未命名家具'
    end

    def soft_library_managed_root_entity?(entity, model = Sketchup.active_model, state = nil)
      return true unless entity && entity.valid?
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s rescue ''
      return true unless kind.empty?
      state = load_state(model) unless state.is_a?(Hash)
      return true if %w[architecture landscape].any? do |discipline|
        candidate = managed_model_instance_for(discipline, model)
        candidate && candidate.valid? && candidate == entity
      end
      Array(state['space_models']).any? do |space|
        candidate = space_model_entity(space['id'], model)
        candidate && candidate.valid? && candidate == entity
      end
    rescue StandardError
      true
    end

    def soft_library_selected_representation(entity)
      # 平面图片在“代”模式中仍使用自身定义，属于可写回的原模型，不应被
      # “当前选中的是代理”这条普通代理保护规则拦住。
      return 'full' if soft_instance_planar_reference?(entity)
      value = entity.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s rescue ''
      value = entity.definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s if value.empty? && entity.respond_to?(:definition) && entity.definition
      value
    rescue StandardError
      ''
    end

    # 已经由 LinkHub 模型库接管的家具不能再次通过吸管重复入库。
    # 同时读取实例与定义属性，兼容代理实例、热重载以及旧项目迁移状态。
    def existing_soft_library_item_for_entity(entity, model = Sketchup.active_model)
      return nil unless entity && entity.valid?
      info = soft_instance_metadata(entity)
      # 这是入库“更新已有模型”的安全闸门。没有 LinkHub 身份证据的普通组件
      # 必须被视为新/普通对象，绝不能靠名称反查后进入 :update/:repair 写库路径。
      return nil unless soft_entity_managed_identity_evidence?(entity, info)
      model_id = info['model_id'].to_s.strip
      source_path = info['source_path'].to_s.strip

      # v0.13.6.13：历史白盒不能继续“旧 source_path 存在就立刻认定它是当前身份”。
      # 很多旧项目在整理模型库后仍保留一个可访问的素材/旧库路径，但真正应绑定的是
      # 已整理库中的 stable model_id。先走完整恢复器，让 marker / 名称 / 尺寸 / 当前库路径
      # 一起参与判断；只有找不到当前库身份时，恢复器自己才会把仍可读的旧源作为兜底。
      if soft_legacy_proxy_entity?(entity)
        recovered = full_soft_library_item_for(info, model)
        return recovered if recovered && File.file?(recovered['path'].to_s)
        return nil
      end

      # 普通已入库家具仍保留快路径，避免工具条每次刷新都扫描整个模型库。
      if !source_path.empty? && File.file?(source_path)
        name = info['model_name'].to_s.strip
        name = File.basename(source_path, File.extname(source_path)) if name.empty?
        return {
          'id' => soft_stable_model_id?(model_id) ? model_id : soft_model_id_for_path(source_path),
          'path' => FastPath.expand(source_path),
          'name' => name
        }
      end
      item = nil
      item = soft_library_item(model_id, force: false) if soft_stable_model_id?(model_id)
      return item if item && File.file?(item['path'].to_s)

      recovered = full_soft_library_item_for(info, model)
      return recovered if recovered && File.file?(recovered['path'].to_s)
      nil
    rescue StandardError => e
      log_exception('识别已入库家具失败', e)
      nil
    end

    # v0.13.6.146：顶部工具条只是显示按钮状态，不能因为选中一件家具就去
    # File.file? 模型库/NAS 或执行历史身份恢复扫描。真正点击入库时仍由完整版状态函数
    # 重新验证。这里仅依据当前实体已有 metadata 做 O(1) 判断。
    def soft_library_ingest_selection_status_fast(model = Sketchup.active_model, state = nil)
      state = cached_project_state_readonly(model) || load_state(model) unless state.is_a?(Hash)
      return { 'enabled' => false, 'tooltip' => '家具入库只在软装工作区提供' } unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
      selected = model.selection.to_a.select { |entity| entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) }
      return { 'enabled' => false, 'tooltip' => '先选择一个家具组件或群组，再点击吸管入库' } if selected.empty?
      return { 'enabled' => false, 'tooltip' => '家具入库一次只能选择一个组件或群组' } unless selected.length == 1
      entity = selected.first
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s rescue ''
      if kind == 'space_model'
        return { 'enabled' => false, 'tooltip' => '空间根模型不能作为家具入库' }
      end
      # 根层受管专业模型也不允许入库；只检查当前 state 中已知根实例，不访问共享盘。
      if model.active_path.nil?
        is_space_root = Array(state['space_models']).any? do |item|
          root = space_model_entity(item['id'], model)
          root && root.valid? && root == entity
        rescue StandardError
          false
        end
        return { 'enabled' => false, 'tooltip' => '建筑、景观或空间根模型不能作为家具入库' } if is_space_root
      end
      info = soft_instance_metadata(entity)
      model_id = info['model_id'].to_s
      source_path = info['source_path'].to_s
      if !model_id.empty? || !source_path.empty? || soft_legacy_proxy_entity?(entity)
        name = info['model_name'].to_s.strip
        name = soft_library_selected_entity_name(entity) if name.empty?
        name = '当前家具' if name.to_s.empty?
        return { 'enabled' => false, 'tooltip' => "“#{name}”已由 LinkHub 管理，不会重复入库" }
      end
      if soft_library_selected_representation(entity) == 'proxy'
        return { 'enabled' => false, 'tooltip' => '当前选中的是代理模型；请先切换真模型再入库' }
      end
      name = soft_library_selected_entity_name(entity)
      { 'enabled' => true, 'tooltip' => "将“#{name}”入库；点击后再执行完整身份校验" }
    rescue StandardError => e
      { 'enabled' => false, 'tooltip' => "当前选择不能入库：#{e.message}" }
    end

    def soft_library_ingest_selection_status(model = Sketchup.active_model, state = nil)
      state = load_state(model) unless state.is_a?(Hash)
      unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
        return { 'enabled' => false, 'tooltip' => '家具入库只在软装工作区提供' }
      end
      selected = model.selection.to_a.select { |entity| entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) }
      if selected.empty?
        return { 'enabled' => false, 'tooltip' => '先选择一个家具组件或群组，再点击吸管入库' }
      end
      if selected.length != 1
        return { 'enabled' => false, 'tooltip' => '家具入库一次只能选择一个组件或群组' }
      end
      entity = selected.first
      if soft_library_managed_root_entity?(entity, model, state)
        return { 'enabled' => false, 'tooltip' => '建筑、景观或空间根模型不能作为家具入库' }
      end
      existing = existing_soft_library_item_for_entity(entity, model)
      if existing
        return { 'enabled' => false, 'tooltip' => "“#{existing['name']}”已经在模型库中，不会重复入库" }
      end
      if soft_library_selected_representation(entity) == 'proxy'
        return { 'enabled' => false, 'tooltip' => '当前选中的是代理模型；请先切换真模型再入库' }
      end
      name = soft_library_selected_entity_name(entity)
      { 'enabled' => true, 'tooltip' => "将“#{name}”入库，并接管当前空间中的一致实例" }
    rescue StandardError => e
      { 'enabled' => false, 'tooltip' => "当前选择不能入库：#{e.message}" }
    end

    def selected_furniture_entity_for_library!(model = Sketchup.active_model)
      state = ensure_space_models_ready!(model)
      raise '家具入库只在软装工作区提供。' unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
      selected = model.selection.to_a.select { |entity| entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) }
      raise '请只选择一个家具组件或群组。' unless selected.length == 1
      entity = selected.first
      raise '建筑、景观或空间根模型不能作为家具入库。' if soft_library_managed_root_entity?(entity, model, state)
      existing = existing_soft_library_item_for_entity(entity, model)
      raise "“#{existing['name']}”已经在模型库中，无需再次入库。" if existing
      raise '当前选中的是代理模型，请先切换为真模型再入库。' if soft_library_selected_representation(entity) == 'proxy'
      entity
    end

    def safe_soft_library_category_name(value)
      text = value.to_s.strip.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ')
      text = text.gsub(/\A\.+|\.+\z/, '').strip
      raise '分类名称不能为空。' if text.empty?
      text[0, 48]
    end

    # 找到当前被吸取家具所属的室内空间，并只在这个空间内收集同一定义的实例。
    # 这样不会因为同一个组件定义恰好也被其他空间引用，就把跨空间对象一起接管。
    def soft_library_ingest_space_scope(entity, model = Sketchup.active_model, state = nil)
      return [nil, nil] unless entity && entity.valid?
      state = load_state(model) unless state.is_a?(Hash)

      # 正在空间内编辑时，active_path 已直接给出所属根组件；先走 O(路径深度)
      # 快路径，避免每次入库都递归检查全部已载入空间的定义树。
      active_root = Array(model.active_path).find do |node|
        node && node.valid? && !node.get_attribute(ENTITY_DICT, 'space_id', '').to_s.empty?
      rescue StandardError
        false
      end
      if active_root
        active_space_id = active_root.get_attribute(ENTITY_DICT, 'space_id', '').to_s
        active_item = space_model_record(state, active_space_id)
        active_entity = active_item ? space_model_entity(active_item['id'], model) : nil
        if active_entity && active_entity.valid?
          return [active_item, active_entity]
        end
      end

      editing_item = space_model_record(state, state['space_editing_id'].to_s)
      editing_entity = editing_item ? space_model_entity(editing_item['id'], model) : nil
      if editing_entity && editing_entity.valid? && entity_inside_definition_tree?(entity, editing_entity.definition)
        return [editing_item, editing_entity]
      end

      Array(state['space_models']).each do |item|
        space_entity = space_model_entity(item['id'], model)
        next unless space_entity && space_entity.valid?
        return [item, space_entity] if entity_inside_definition_tree?(entity, space_entity.definition)
      end
      [nil, nil]
    rescue StandardError => e
      log_exception('识别家具入库所属空间失败', e)
      [nil, nil]
    end

    def soft_library_ingest_matching_instances(entity, model = Sketchup.active_model, state = nil)
      item, space_entity = soft_library_ingest_space_scope(entity, model, state)
      targets = if space_entity && space_entity.valid?
                  collect_matching_instances_in_definition(space_entity.definition, entity.definition)
                else
                  [entity]
                end
      targets = Array(targets).select { |candidate| candidate && candidate.valid? }
      targets << entity unless targets.include?(entity)
      [targets.uniq, item, space_entity]
    rescue StandardError => e
      log_exception('收集家具入库一致实例失败', e)
      [[entity].compact, nil, nil]
    end

    # 吸管入库必须服从视口中当前真实显示的代/真状态，而不能只读取可能滞后的
    # state 字段。尤其热重载、跨空间切换或旧模型迁移后，开关已经显示“代理”，
    # space_edit_display_mode 仍可能残留为 full。优先读取所属空间内现有受管家具的
    # 实际表示；没有可参考家具时，再读取顶部开关对应的显示状态。
    def ingested_soft_target_display_mode(state, model = Sketchup.active_model, space_entity: nil)
      # 直接使用悬浮开关当前展示的状态。displayed_space_display_mode 会在
      # “state 字段滞后但视口已经全部是代理”的旧项目中读取实际实例，因此它
      # 比单独读取 space_edit_display_mode 更接近用户眼前看到的开关。
      displayed = displayed_space_display_mode(state, model).to_s
      return displayed if %w[proxy full].include?(displayed)

      explicit = effective_space_display_mode(state).to_s
      return explicit if %w[proxy full].include?(explicit)

      if space_entity && space_entity.valid?
        root_mode = space_entity.get_attribute(ENTITY_DICT, 'space_representation', '').to_s
        return root_mode if %w[proxy full].include?(root_mode)
        representations = soft_instances_for_space(space_entity, model, force: true).filter_map do |instance|
          next unless instance && instance.valid?
          value = instance.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s
          if !%w[proxy full].include?(value)
            value = instance.definition.get_attribute(SOFT_MODEL_DICT, 'representation', '').to_s rescue ''
          end
          %w[proxy full].include?(value) ? value : nil
        end
        return 'proxy' if !representations.empty? && representations.all? { |value| value == 'proxy' }
        return 'full' if !representations.empty? && representations.all? { |value| value == 'full' }
      end
      'proxy'
    rescue StandardError => e
      log_exception('判断家具入库后的代真显示状态失败', e)
      effective_space_display_mode(state)
    end

    def soft_instance_proxy_ready?(instance)
      soft_instance_representation_ready?(instance, 'proxy')
    end

    # 家具完成入库后，当前空间中所有与被吸取对象共享原始定义的实例，都会
    # 立即切换为新库文件对应的受管定义。每个实例先记录实际三轴尺寸、底部
    # 中心、方向、镜像及非等比缩放，再分别重建变换，因此不同拉伸尺寸不会
    # 被归一成同一大小。当前视口若处于代理模式，则接管后立即生成标准代理。
    def adopt_ingested_soft_library_instances!(targets, library_item, model = Sketchup.active_model, state: nil, space_item: nil, space_entity: nil, full_definition: nil, manage_operation: true, desired_representation: nil)
      targets = Array(targets).select { |candidate| candidate && candidate.valid? }
      return { changed: 0, representation: 'full', instances: [] } if targets.empty?
      state = load_state(model) unless state.is_a?(Hash)
      full_definition ||= load_soft_library_definition(library_item, model)
      raise '新入库模型已经写出，但无法重新载入并接管当前家具。' unless full_definition && full_definition.valid?
      remember_soft_full_definition_tree!(full_definition, model)

      requested = desired_representation.to_s
      requested = ingested_soft_target_display_mode(state, model, space_entity: space_entity).to_s unless %w[proxy full].include?(requested)
      desired = requested == 'proxy' ? 'proxy' : 'full'
      # 同步权威开关状态，避免本次接管结束后旧观察器又按过期字段把家具恢复成真模型。
      if state['space_editing_id'].to_s.empty?
        state['space_display_mode'] = desired
      else
        state['space_edit_display_mode'] = desired
      end
      log("家具入库接管开始：#{library_item['name']} / 一致实例 #{targets.length} / 目标显示 #{desired}")
      changed = []
      adopt_proxy_pending = []
      operation_started = false
      if manage_operation
        # 必须是独立、非透明事务。透明事务会并入用户上一条移动/建模操作，
        # 一旦 abort 就可能把用户前面的操作一起撤回。
        model.start_operation("家具入库接管 #{library_item['name']}", true, false, false)
        operation_started = true
      end
      with_soft_representation_switch(model) do
        targets.each do |original|
          next unless original && original.valid?
          instance = original
          instance = instance.to_component if instance.is_a?(Sketchup::Group)
          next unless instance && instance.valid?
          was_locked = instance.respond_to?(:locked?) ? instance.locked? : false
          instance.locked = false if was_locked && instance.respond_to?(:locked=)
          preserved_by_payload = replace_instance_definition_preserving_library_payload!(instance, full_definition)
          replace_instance_definition_preserving_box!(instance, full_definition) unless preserved_by_payload
          stamp_soft_library_instance!(instance, library_item, model)
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'representation', 'full')
          instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
          instance.locked = true if was_locked && instance.respond_to?(:locked=)
          changed << instance
        end

        if desired == 'proxy' && !changed.empty?
          swaps = apply_space_soft_proxies!(space_entity, model, instances: changed, strict: false)
          failed = changed.select do |instance|
            next true unless instance && instance.valid?
            !soft_instance_proxy_ready?(instance)
          end
          unless failed.empty?
            bump_soft_instance_registry_revision(model)
            swaps.concat(apply_space_soft_proxies!(space_entity, model, instances: failed, strict: false))
            failed = failed.select do |instance|
              next true unless instance && instance.valid?
              !soft_instance_proxy_ready?(instance)
            end
          end
          if failed.empty?
            soft_set_attribute_if_changed(space_entity, ENTITY_DICT, 'space_representation', 'proxy') if space_entity && space_entity.valid?
            log("家具入库即时代理完成：#{library_item['name']} / 代理替换 #{swaps.length} / 接管 #{changed.length}")
          else
            # v0.13.6.190：新入库家具暂时切不到代理不再让整次入库回滚（源模型已写入模型库）。
            # 这些实例保持真模型，空间标记 mixed；代理由入库后续队列/发布前准备补齐。
            soft_set_attribute_if_changed(space_entity, ENTITY_DICT, 'space_representation', 'mixed') if space_entity && space_entity.valid?
            adopt_proxy_pending = failed.select { |instance| instance && instance.valid? }
            desired = 'mixed'
            log("家具入库即时代理部分未完成：#{library_item['name']} / 代理替换 #{swaps.length} / 接管 #{changed.length} / 保持真模型 #{adopt_proxy_pending.length}")
          end
        elsif space_entity && space_entity.valid?
          soft_set_attribute_if_changed(space_entity, ENTITY_DICT, 'space_representation', 'full')
        end
      end

      bump_soft_instance_registry_revision(model)
      if space_item
        space_item['status'] = "修改中 · 已入库并接管 #{changed.length} 个一致家具"
        save_state(state, model, write_manifest: false)
      end
      model.selection.clear
      changed.each { |instance| model.selection.add(instance) if instance && instance.valid? }
      if manage_operation
        model.commit_operation
        operation_started = false
      end
      log("家具入库接管完成：#{library_item['name']} / 已接管 #{changed.length} / 显示 #{desired}")
      unless adopt_proxy_pending.empty?
        scope_id = space_item.is_a?(Hash) ? space_item['id'].to_s : ''
        runtime_start_timer(0.6, false, label: 'soft:ingest_adopt_proxy_followup', key: "soft:ingest_adopt_proxy_followup:#{model.object_id}", model: model) do
          begin
            targets = adopt_proxy_pending.select { |instance| instance && instance.valid? }
            request_immediate_soft_proxy_refresh_for_instances!(targets, model, scope_space_id: scope_id) unless targets.empty?
          rescue StandardError => e
            log_exception('入库后补齐代理排队失败', e)
          end
        end
      end
      { changed: changed.length, representation: desired, instances: changed }
    rescue StandardError
      model.abort_operation rescue nil if manage_operation && operation_started
      raise
    end

    def parse_soft_classified_model_name(value, default_category: '', default_subcategory: '', default_name: '', tagged: false)
      text = value.to_s.strip.gsub(/\s+/, ' ')
      text = text.sub(/\A软装[\-－—–﹣‐‑‒]+/, '') if tagged || soft_batch_ingest_tagged_name?(text)
      raise '请输入“大类-子类（名称）”，例如：家具-椅子（狩猎椅）。' if text.empty?
      separators = /[\-－—–﹣‐‑‒]+/
      unless separators.match?(text)
        top = soft_library_canonical_top_category(default_category)
        top = '其他' if default_category.to_s.strip.empty?
        subcategory = safe_soft_library_subcategory_name(default_subcategory, top)
        return [top, subcategory, safe_soft_library_filename(text)]
      end
      parts = text.split(separators).map(&:strip).reject(&:empty?)
      first = parts.shift.to_s
      top = if first.empty?
              soft_library_canonical_top_category(default_category)
            else
              soft_library_canonical_top_category(first)
            end
      legacy_subcategory = if !first.empty? && !SOFT_LIBRARY_CATEGORIES.include?(first) &&
                              soft_library_canonical_top_category(first) == top
                             first
                           else
                             ''
                           end
      remainder = parts.join('-')
      remainder = default_name.to_s if remainder.empty?
      bracket = /\A(.+?)[（(](.+?)[）)]\z/.match(remainder)
      if bracket
        subcategory = bracket[1].to_s.strip
        model_name = bracket[2].to_s.strip
      elsif parts.length >= 2 && Array(SOFT_LIBRARY_SUBCATEGORIES[top]).include?(parts.first.to_s)
        subcategory = parts.shift.to_s
        model_name = parts.join('-')
      else
        subcategory = legacy_subcategory
        subcategory = default_subcategory.to_s if subcategory.empty?
        subcategory = soft_library_default_subcategory(top) if subcategory.empty?
        model_name = remainder
      end
      subcategory = safe_soft_library_subcategory_name(subcategory, top)
      model_name = safe_soft_library_filename(model_name)
      raise '模型名称不能为空。' if model_name.to_s.strip.empty?
      [top, subcategory, model_name]
    end

    # 单字段完成“大类 + 子类 + 模型名”。推荐“家具-椅子（狩猎椅）”；
    # 旧“摆件-茶杯”仍兼容，并自动落入“摆件/其他摆件/茶杯”。
    def parse_ingested_soft_library_name(value, default_category: '', default_name: '')
      parse_soft_classified_model_name(
        value, default_category: default_category, default_name: default_name, tagged: false
      )
    end

    # v0.13.5.12：家具批量入库不再依赖逐个“吸管 + 输入框”。
    # 用户只需要在 SketchUp 图元信息中给实例命名：
    #   软装-家具-椅子
    #   软装-摆件-泡池长条桌-1
    # 固定“软装”前缀只作为待入库标记；第二段是分类，后续全部内容都是模型名。
    # 只切前两个分隔符，因此模型名本身可以继续包含“-”。
    def soft_batch_ingest_tagged_name?(value)
      text = value.to_s.strip
      !!(/\A软装[\-－—–﹣‐‑‒]/.match(text))
    rescue StandardError
      false
    end

    def parse_soft_batch_ingest_instance_name(value)
      text = value.to_s.strip.gsub(/\s+/, ' ')
      return nil unless soft_batch_ingest_tagged_name?(text)
      parse_soft_classified_model_name(text, tagged: true)
    rescue StandardError
      nil
    end

    # 只扫描当前 LinkHub 空间根 Definition 内部，永远不扫描整个工作 SKP 根层级。
    # 这样批量入库天然服从“空间根以上禁止空间数据”的协同边界。
    # 若一个已标记父组件里又存在已标记子组件，只处理父组件并记录冲突，避免
    # 父级接管后子级对象失效导致半批次状态。
    def collect_soft_batch_ingest_candidates(space_entity, model = Sketchup.active_model)
      return [[], []] unless space_entity && space_entity.valid? && space_entity.respond_to?(:definition)
      raw = []
      repair_candidates = []
      issues = []
      visited = {}
      # 每个历史白盒 Definition 只做一次模型库身份解析，但实例收集跟随本次
      # 单趟树遍历完成。旧版在这里每找到一款可恢复白盒，又从空间根递归全树
      # collect_matching_instances_in_definition，一旦空间复杂会形成 N×整树扫描。
      # 这不仅慢，也会在 SketchUp 编辑上下文里制造大量原生 Entity 枚举压力。
      repair_resolution_by_definition = {}
      repair_issue_by_definition = {}
      repair_by_model_id = {}
      walk = lambda do |definition, tagged_ancestor|
        return unless definition && definition.valid?
        oid = definition.object_id
        return if visited[oid]
        visited[oid] = true
        definition.entities.each do |entity|
          next unless entity && entity.valid?
          next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
          instance_name = entity.respond_to?(:name) ? entity.name.to_s.strip : ''

          # v0.13.6.13：无选择点击“家具入库”时，先救当前空间的历史白盒。
          # 只扫描明确带 fallback 标记的代理，不会拿普通嵌套组件去猜模型库身份。
          if soft_legacy_proxy_entity?(entity)
            def_key = entity.definition.object_id
            unless repair_resolution_by_definition.key?(def_key)
              existing = existing_soft_library_item_for_entity(entity, model)
              existing = nil unless existing && File.file?(existing['path'].to_s)
              repair_resolution_by_definition[def_key] = existing
              unless existing
                label = soft_identity_display_name(entity.definition.name.to_s)
                label = soft_identity_display_name(instance_name) if label.empty?
                label = '未命名历史白盒' if label.empty?
                repair_issue_by_definition[def_key] = "历史白盒“#{label}”：未找到唯一可信的真模型源，已保持原位，不会误绑定"
                issues << repair_issue_by_definition[def_key]
              end
            end
            existing = repair_resolution_by_definition[def_key]
            if existing
              bucket = repair_by_model_id[existing['id'].to_s]
              unless bucket
                bucket = {
                  action: :repair,
                  entity: entity,
                  entities: [],
                  model_id: existing['id'].to_s,
                  model_name: existing['name'].to_s,
                  source_path: existing['path'].to_s,
                  dedupe_key: "legacy-repair:#{existing['id']}"
                }
                repair_by_model_id[existing['id'].to_s] = bucket
                repair_candidates << bucket
              end
              bucket[:entities] << entity unless bucket[:entities].include?(entity)
            end
            next
          end

          tagged = soft_batch_ingest_tagged_name?(instance_name)
          if tagged
            if tagged_ancestor
              issues << "#{instance_name}: 位于另一个已标记软装组件内部，已跳过嵌套标记"
              next
            end
            parsed = parse_soft_batch_ingest_instance_name(instance_name)
            unless parsed
              issues << "#{instance_name}: 命名格式无效，应为“软装-大类-子类（名称）”"
              next
            end
            existing = existing_soft_library_item_for_entity(entity, model)
            if existing
              issues << "#{instance_name}: 已经由模型库接管，未重复入库"
              next
            end
            if soft_library_selected_representation(entity) == 'proxy'
              issues << "#{instance_name}: 当前已经是代理表示，未重复入库"
              next
            end
            category, subcategory, model_name = parsed
            raw << {
              entity: entity,
              definition: entity.definition,
              category: category,
              subcategory: subcategory,
              requested_name: model_name,
              marker_name: instance_name
            }
            next
          end
          child = entity.respond_to?(:definition) ? entity.definition : nil
          walk.call(child, tagged_ancestor) if child && child.valid?
        end
      end
      walk.call(space_entity.definition, false)

      # 同一个原始 Definition 只需要入库一次；当前空间内其它一致实例由现有
      # “接管同定义实例”逻辑一次性转换。若同一定义被写成两个不同目标名称，
      # 不猜用户意图，整组跳过并要求先统一实例名。
      candidates = repair_candidates
      raw.group_by { |item| item[:definition] ? item[:definition].object_id : item[:entity].object_id }.each_value do |group|
        specs = group.map { |item| [item[:category].to_s, item[:subcategory].to_s, item[:requested_name].to_s] }.uniq
        if specs.length > 1
          labels = group.map { |item| item[:marker_name].to_s }.uniq.join(' / ')
          issues << "#{labels}: 同一个组件定义存在多个“大类/子类/名称”，请先统一实例名称"
          next
        end
        candidate = group.first.dup
        candidate[:marker_count] = group.length
        candidate[:marked_entities] = group.map { |item| item[:entity] }
        candidates << candidate
      end
      [candidates, issues]
    rescue StandardError => e
      log_exception('扫描软装批量入库标记/历史白盒失败', e)
      [[], ["扫描失败：#{e.message}"]]
    end

    def soft_batch_ingest_button_status(model = Sketchup.active_model, state = nil, fast: false)
      state = (fast ? (cached_project_state_readonly(model) || load_state(model)) : load_state(model)) unless state.is_a?(Hash)
      return { 'enabled' => false, 'tooltip' => '家具入库只在软装工作区提供' } unless host_discipline_for(state) == SOFT_SPACE_COLLECTION_KEY
      if fast
        item = space_model_record(state, state['space_editing_id'].to_s)
        entity = item ? space_model_entity(item['id'], model) : nil
        valid = item && entity && entity.valid? && local_space_edit_session?(item, state, model)
        item = nil unless valid
        entity = nil unless valid
      else
        _s, item, entity = current_local_editing_space(state, model, required: false)
      end
      return { 'enabled' => false, 'tooltip' => '请先点击空间“修改”取得协作占用' } unless item && entity && entity.valid?
      return { 'enabled' => false, 'tooltip' => '当前处于安全暂存/全模审阅；请先点击“继续”进入空间' } unless active_path_inside_space?(entity, model)

      if @soft_ingest_batch_job
        job = @soft_ingest_batch_job
        if soft_ingest_batch_accepting_more?(job, model, space_id: item['id'].to_s)
          summary = soft_ingest_batch_queue_summary(job)
          if soft_ingest_batch_processing?(job)
            return { 'enabled' => true, 'tooltip' => "家具入库正在执行（#{job[:done]}/#{job[:total]}，剩余：#{summary}）；可继续加入下一批，退出空间后接着处理" }
          end
          return { 'enabled' => true, 'tooltip' => "待入库队列：#{summary}；可继续打开面板加入下一批，最后退出空间一次统一处理" }
        end
        return { 'enabled' => false, 'tooltip' => "家具入库队列属于空间“#{job[:space_name]}”（剩余：#{soft_ingest_batch_queue_summary(job)}），结束后当前空间即可入库" }
      end

      selected = model.selection.to_a.select { |node| node.is_a?(Sketchup::ComponentInstance) || node.is_a?(Sketchup::Group) }
      tooltip = if selected.empty?
                  '家具批量入库：打开面板后点“＋加选”选择组件/群组；提交后仍可继续加入下一批，最后退出空间统一处理'
                else
                  "家具批量入库：把当前选择的 #{selected.length} 个对象做成独立卡片；提交后仍可继续加入下一批"
                end
      { 'enabled' => true, 'tooltip' => tooltip }
    rescue StandardError => e
      { 'enabled' => false, 'tooltip' => "家具入库不可用：#{e.message}" }
    end

    def unique_ingested_soft_model_path(model_name, category_dir)
      base = safe_soft_library_filename(model_name).sub(/#\d+\z/, '')
      candidate = File.join(category_dir, "#{base}.skp")
      return [base, candidate] unless File.exist?(candidate)
      index = 1
      loop do
        name = safe_soft_library_filename("#{base}##{index}")
        path = File.join(category_dir, "#{name}.skp")
        return [name, path] unless File.exist?(path)
        index += 1
      end
    end

    # 入库名称完全由分类生成：抱枕-1、抱枕-2……。
    # 使用当前分类中的最大序号递增，避免删除旧文件后又复用名称造成引用混乱。
    def next_ingested_soft_model_name(category, category_dir)
      prefix = safe_soft_library_filename(category)
      pattern = /\A#{Regexp.escape(prefix)}-(\d+)\.skp\z/i
      max_index = 0
      if Dir.exist?(category_dir)
        Dir.children(category_dir).each do |entry|
          match = pattern.match(entry.to_s)
          max_index = [max_index, match[1].to_i].max if match
        end
      end
      index = max_index + 1
      loop do
        name = safe_soft_library_filename("#{prefix}-#{index}")
        path = File.join(category_dir, "#{name}.skp")
        return [name, path] unless File.exist?(path)
        index += 1
      end
    rescue StandardError
      token = Time.now.strftime('%Y%m%d-%H%M%S')
      name = safe_soft_library_filename("#{category}-#{token}")
      [name, File.join(category_dir, "#{name}.skp")]
    end

    def schedule_ingested_soft_thumbnail_calibration(model_id, model_name = '', delay: 0.18)
      id = model_id.to_s
      return false if id.empty?
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(
        delay.to_f, false, label: 'library:ingest_thumbnail_extract', key: "library:ingest_thumbnail:#{id}"
      ) do
        begin
          # v0.13.6.39 PERFORMANCE PASS 1：入库/更新时 wrapper 在正式写 SKP 之前已经设置
          # 统一组件轴缩略图相机并 refresh_thumbnail。旧版落盘后又重新 definitions.load、
          # 两次 refresh_thumbnail、save_copy，再把整份源 SKP 写回 NAS 一遍；这会与随后
          # 的六面代理任务叠加，单款家具也可能额外等很久。
          # 现在自动流程只“提取刚写入 SKP 的内嵌缩略图 -> 本地/模型库缩略图缓存”，
          # 不再次改写源 SKP。若提取/白底校正失败，只留下占位图；用户需要时可在
          # 模型库显式点刷新，继续使用原来的强标准化写回链路。
          if publish_critical_section? || soft_heavy_interaction? || @soft_model_batch_job ||
             @soft_ingest_batch_job || @updating || @single_space_update_job || @space_batch_update_job ||
             !soft_thumbnail_idle?
            schedule_ingested_soft_thumbnail_calibration(id, model_name, delay: 0.45)
            next
          end
          item = soft_library_item(id, force: false)
          next unless item && File.file?(item['path'].to_s)
          started = monotonic_time
          # v0.13.7.3：入库/更新后空闲时按组件轴生成正反两张轴测图（不改源 SKP）。
          enqueue_soft_thumbnail_views!(id, reason: '入库/更新') rescue nil
          thumb = ensure_soft_model_thumbnail(item['path'].to_s, soft_library_root, force: true)
          if !thumb.to_s.empty? && File.file?(thumb)
            item['thumbnail_path'] = thumb
            item['thumbnail_url'] = soft_thumbnail_url(thumb)
            item['thumbnail_ready'] = true
            # soft_library_item 会叠加六面代理权威映射并返回副本，不能只改这个副本后
            # 误以为目录缓存已经同步。直接更新 by_id 指向的真实缓存条目；这只是本地
            # 缩略图路径，不触碰源 SKP，也不重新扫描 NAS。
            cache = @soft_library_cache
            if cache.is_a?(Hash)
              cached = cache[:by_id].is_a?(Hash) ? cache[:by_id][id] : nil
              cached ||= Array(cache[:items]).find { |row| row.is_a?(Hash) && row['id'].to_s == id }
              if cached.is_a?(Hash)
                cached['thumbnail_path'] = item['thumbnail_path']
                cached['thumbnail_url'] = item['thumbnail_url']
                cached['thumbnail_ready'] = true
              end
              persist_soft_library_cache!
            end
            send_soft_thumbnail_updates([{
              'id' => item['id'].to_s, 'thumbnail_url' => item['thumbnail_url'].to_s,
              'thumbnail_ready' => true, 'thumbnail_finished' => true, 'thumbnail_error' => ''
            }])
            log("家具入库缩略图轻量提取完成：#{model_name.to_s.empty? ? item['name'] : model_name} / #{elapsed_ms(started)}ms")
          else
            log("家具入库缩略图轻量提取未得到可用缓存：#{model_name.to_s.empty? ? item['name'] : model_name}；已跳过自动重写源 SKP，可在模型库手动刷新。")
          end
        rescue StandardError => e
          log_exception("家具入库缩略图轻量提取失败：#{model_name}", e)
          # 缩略图失败只影响卡片预览，绝不为了自动补图阻塞家具入库/六面代理。
        end
      end
      true
    end

    def ingest_selected_furniture_into_library(model = Sketchup.active_model)
      total_started = monotonic_time
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再入库。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再入库。' if @updating || @single_space_update_job || @space_batch_update_job
      raise '模型库批量任务正在执行，请等待完成后再入库。' if @soft_model_batch_job
      ensure_soft_ingest_batch_not_writing!('单件入库')
      entity = selected_furniture_entity_for_library!(model)
      ingest_state = ensure_space_models_ready!(model)
      root = soft_library_root
      if root.empty? || !Dir.exist?(root)
        chosen = choose_soft_library_root
        return false unless chosen
        root = soft_library_root
      end
      ensure_soft_library_structure!(root)

      default_category = Sketchup.read_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_LAST_CATEGORY_PREF_KEY, '').to_s
      default_name = soft_library_selected_entity_name(entity)
      default_category = soft_library_canonical_top_category(default_category)
      default_subcategory = soft_library_default_subcategory(default_category)
      default_input = "#{default_category}-#{default_subcategory}（#{default_name}）"
      response = UI.inputbox(['大类-子类（名称）'], [default_input], '软装入库 · 分类、子类与名称')
      return false unless response
      category, subcategory, requested_name = parse_ingested_soft_library_name(
        response[0], default_category: default_category, default_name: default_name
      )
      Sketchup.write_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_LAST_CATEGORY_PREF_KEY, category)
      category_dir = File.join(soft_library_organized_dir(root), category, subcategory)
      FileUtils.mkdir_p(category_dir)
      model_name, target = unique_ingested_soft_model_path(requested_name, category_dir)
      model_id = soft_model_id_for_path(target)
      library_item = { 'id' => model_id, 'path' => FastPath.expand(target), 'name' => model_name }

      wrapper = nil
      operation_started = false
      operation_committed = false
      target_written = false
      target_write_result = nil
      adoption = nil
      matching_targets = []
      owning_space_item = nil
      owning_space_entity = nil
      planar_reference = false
      desired_ingest_representation = 'full'

      begin
        # “群组 -> 组件、导出、接管、代理化”保持在同一个撤回事务里，用户一次 Ctrl+Z
        # 即可完整撤销，不再出现自动转组件后还要额外撤回一步。
        model.start_operation("家具入库 #{model_name}", true, false, false)
        operation_started = true
        if entity.is_a?(Sketchup::Group)
          entity = entity.to_component
          raise '群组未能自动转换为组件实例。' unless entity && entity.valid? && entity.is_a?(Sketchup::ComponentInstance)
        end

        matching_targets, owning_space_item, owning_space_entity = soft_library_ingest_matching_instances(entity, model, ingest_state)
        desired_ingest_representation = 'full'

        export_started = monotonic_time
        wrapper = build_soft_library_update_definition!(entity, { 'name' => model_name }, model)
        planar_reference = soft_definition_planar_reference?(wrapper)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_id', model_id)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'source_path', target)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_name', model_name)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'representation', 'full')
        # 自动入库不在当前项目里切换全部图层/渲染设置或强制 refresh_thumbnail。
        # 复杂贴图组件连续刷新时可能触发 SketchUp 原生退出；写库后由轻量缓存提取缩略图。
        target_write_result = write_soft_library_definition_atomic!(wrapper, target, root)
        target_written = true
        stamp_soft_library_definition!(wrapper, library_item)
        remember_soft_library_definition!(wrapper, library_item, model)
        log("家具入库文件写出：#{model_name} / #{elapsed_ms(export_started)}ms")

        adopt_started = monotonic_time
        adoption = adopt_ingested_soft_library_instances!(
          matching_targets,
          library_item,
          model,
          state: ingest_state,
          space_item: owning_space_item,
          space_entity: owning_space_entity,
          full_definition: wrapper,
          manage_operation: false,
          desired_representation: desired_ingest_representation
        )
        log("家具入库实例接管：#{model_name} / #{elapsed_ms(adopt_started)}ms")
        model.commit_operation
        operation_started = false
        operation_committed = true
        schedule_soft_full_definition_cleanup(model, delay: 1.4) if adoption && adoption[:representation].to_s == 'proxy'
      rescue StandardError
        model.abort_operation rescue nil if operation_started
        operation_started = false
        unless operation_committed
          rollback_soft_library_definition_write!(target_write_result) if target_written && target_write_result
          remove_unused_definition!(wrapper, model) if wrapper && wrapper.valid? && wrapper.instances.empty? rescue nil
        end
        raise
      end

      metadata_error = nil
      begin
        timestamp = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        stored_bounds = soft_definition_bounds_values(wrapper)
        stored_actual_axis_mm = soft_definition_axis_extents(wrapper).map { |value| (value.to_f.abs * 25.4).round(4) }
        metadata = default_soft_model_metadata(target).merge(
          'model_id' => model_id,
          'name' => model_name,
          'organized' => true,
          'category' => category,
          'subcategory' => subcategory,
          'organized_relative_dir' => [category, subcategory].join('/'),
          'bounds_values' => (soft_bounds_values_valid?(stored_bounds) ? stored_bounds.map(&:to_f) : []),
          'ingested_actual_axis_mm' => stored_actual_axis_mm,
          'planar_reference' => planar_reference,
          'proxy_passthrough' => planar_reference,
          'proxy_kind' => (planar_reference ? SOFT_PLANAR_PROXY_KIND : ''),
          'proxy_name' => (planar_reference ? '原平面组件（直接作为代理）' : ''),
          'proxy_render_mode' => (planar_reference ? 'native_passthrough' : ''),
          'bounds_source_signature' => fast_file_signature(target).to_s,
          'created_at' => timestamp,
          'updated_at' => timestamp
        )
        index = read_soft_library_index(root)
        index['models'][normalize_soft_library_key(target)] = metadata
        write_soft_library_index!(index, root)
        write_json_atomic(soft_model_sidecar_path(target), metadata.merge('schema' => SOFT_LIBRARY_SCHEMA))
      rescue StandardError => e
        metadata_error = e
        log_exception("家具入库资料写入失败：#{target}", e)
      end

      invalidate_soft_model_thumbnail!(target, root, delete_file: true)
      cache_updated = upsert_soft_library_cache_path!(target, root)
      if @soft_designer_dialog && @soft_designer_dialog.visible?
        if cache_updated
          refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
        else
          schedule_soft_library_dialog_load(force: false)
        end
      end
      schedule_ingested_soft_thumbnail_calibration(model_id, model_name)
      unless planar_reference
        seed = {
          model_id: model_id.to_s, model_name: model_name.to_s, source_path: target.to_s,
          scope_space_id: owning_space_item ? owning_space_item['id'].to_s : '',
          replace_instances: Array(adoption && adoption[:instances]).select { |instance| instance && instance.valid? },
          source_definition: (wrapper if wrapper && wrapper.valid?)
        }
        defer_soft_visual_proxy_seeds_until_publish!([seed], model)
      end
      refresh_workspace_toolbar(model)
      adopted_count = adoption ? adoption[:changed].to_i : 0
      representation_label = if planar_reference
                               '平面图片原组件直接作为代理'
                             elsif adoption && adoption[:representation].to_s == 'proxy'
                               '当前按代理显示'
                             else
                               '当前按真模型显示'
                             end
      log("家具入库完成：#{category}/#{subcategory}/#{model_name} / 总计 #{elapsed_ms(total_started)}ms / 接管 #{adopted_count}")
      if metadata_error
        show_status("“#{category}/#{subcategory}/#{model_name}”已入库并接管 #{adopted_count} 个一致实例（#{representation_label}）；资料索引暂未写入，下次刷新会自动识别。", 'warning')
      else
        show_status("“#{category}/#{subcategory}/#{model_name}”已入库，并接管 #{adopted_count} 个一致实例（#{representation_label}）。", 'success')
      end
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      raise
    end

    # 单个“软装-大类-子类（模型名）”标记实体的无交互入库核心。
    # 与原吸管入库共用同一套：实际实例尺寸固化 -> 写 SKP -> 接管同定义实例 ->
    # 自动代理；六面可视图在后台补建，批量模式只把高频索引/UI/缩略图收尾延迟到整批结束。
    def ingest_tagged_furniture_entity_into_library!(entity, category:, subcategory:, requested_name:, model: Sketchup.active_model,
                                                      ingest_state: nil, shared_index: nil, batch_mode: false,
                                                      force_proxy: false, target_instances: nil, expected_axis_mm: nil)
      total_started = monotonic_time
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再入库。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再入库。' if @updating || @single_space_update_job || @space_batch_update_job
      raise '待入库实例已经失效，请重新扫描。' unless entity && entity.valid?
      existing = existing_soft_library_item_for_entity(entity, model)
      raise "“#{existing['name']}”已经在模型库中，无需再次入库。" if existing
      raise '当前待入库对象已经是代理模型。' if soft_library_selected_representation(entity) == 'proxy'

      ingest_state ||= ensure_space_models_ready!(model)
      root = soft_library_root
      raise '请先设置软装模型库目录。' if root.empty? || !Dir.exist?(root)
      ensure_soft_library_structure!(root)
      category = soft_library_canonical_top_category(category)
      subcategory = safe_soft_library_subcategory_name(subcategory, category)
      requested_name = safe_soft_library_filename(requested_name)
      category_dir = File.join(soft_library_organized_dir(root), category, subcategory)
      FileUtils.mkdir_p(category_dir)
      model_name, target = unique_ingested_soft_model_path(requested_name, category_dir)
      model_id = soft_model_id_for_path(target)
      library_item = { 'id' => model_id, 'path' => FastPath.expand(target), 'name' => model_name }

      wrapper = nil
      operation_started = false
      operation_committed = false
      target_written = false
      target_write_result = nil
      adoption = nil
      matching_targets = []
      owning_space_item = nil
      owning_space_entity = nil
      planar_reference = false

      begin
        owning_space_item, owning_space_entity = soft_library_ingest_space_scope(entity, model, ingest_state)
        raise '待入库对象不属于当前可识别的空间。' unless owning_space_entity && owning_space_entity.valid?
        explicit_targets = Array(target_instances).select { |candidate| candidate && candidate.valid? }
        if explicit_targets.empty?
          matching_targets = collect_matching_instances_in_definition(owning_space_entity.definition, entity.definition)
          matching_targets = [entity] if matching_targets.empty?
        else
          matching_targets = explicit_targets
        end

        # 先用短事务构建候选定义；共享目录传输和完整指纹校验在事务外完成。
        # 这样大模型或慢网络不会让一个开放的 SketchUp 事务横跨数秒。
        model.start_operation("准备批量家具入库 #{model_name}", true, false, false)
        operation_started = true
        export_started = monotonic_time
        wrapper = build_soft_library_update_definition!(entity, { 'name' => model_name }, model, expected_axis_mm: expected_axis_mm)
        planar_reference = soft_definition_planar_reference?(wrapper)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_id', model_id)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'source_path', target)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_name', model_name)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'representation', 'full')
        # 自动入库不强制刷新内嵌缩略图，避免复杂贴图 Definition 的原生渲染崩溃。
        stamp_soft_library_definition!(wrapper, library_item)
        model.commit_operation
        operation_started = false

        target_write_result = write_soft_library_definition_atomic!(wrapper, target, root)
        target_written = true
        log("家具批量入库文件安全写出：#{category}/#{subcategory}/#{model_name} / #{elapsed_ms(export_started)}ms / 模型事务未占用")

        target_representation = if planar_reference
                                  ingested_soft_target_display_mode(ingest_state, model, space_entity: owning_space_entity)
                                else
                                  force_proxy ? 'proxy' : 'full'
                                end
        model.start_operation("批量家具入库接管 #{model_name}", true, false, false)
        operation_started = true
        adoption = adopt_ingested_soft_library_instances!(
          matching_targets,
          library_item,
          model,
          state: ingest_state,
          space_item: owning_space_item,
          space_entity: owning_space_entity,
          full_definition: wrapper,
          manage_operation: false,
          desired_representation: target_representation
        )

        # “软装-...”只是一次性的待处理标记。成功接管以后自动去掉前缀，
        # 防止下一次点击家具入库又把已经完成的实例扫进待处理列表。
        Array(adoption && adoption[:instances]).each do |instance|
          next unless instance && instance.valid? && instance.respond_to?(:name=)
          current_name = instance.respond_to?(:name) ? instance.name.to_s : ''
          instance.name = model_name if soft_batch_ingest_tagged_name?(current_name)
        rescue StandardError
          nil
        end

        remember_soft_library_definition!(wrapper, library_item, model)

        model.commit_operation
        operation_started = false
        operation_committed = true
        schedule_soft_full_definition_cleanup(model, delay: 1.4) if !batch_mode && adoption && adoption[:representation].to_s == 'proxy'
      rescue StandardError
        model.abort_operation rescue nil if operation_started
        operation_started = false
        unless operation_committed
          rollback_soft_library_definition_write!(target_write_result) if target_written && target_write_result
        end
        remove_unused_definition!(wrapper, model) if !operation_committed && wrapper && wrapper.valid? && wrapper.instances.empty? rescue nil
        raise
      end

      metadata_error = nil
      metadata = nil
      begin
        timestamp = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        stored_bounds = soft_definition_bounds_values(wrapper)
        stored_actual_axis_mm = soft_definition_axis_extents(wrapper).map { |value| (value.to_f.abs * 25.4).round(4) }
        metadata = default_soft_model_metadata(target).merge(
          'model_id' => model_id,
          'name' => model_name,
          'organized' => true,
          'category' => category,
          'subcategory' => subcategory,
          'organized_relative_dir' => [category, subcategory].join('/'),
          'bounds_values' => (soft_bounds_values_valid?(stored_bounds) ? stored_bounds.map(&:to_f) : []),
          'ingested_actual_axis_mm' => stored_actual_axis_mm,
          'planar_reference' => planar_reference,
          'proxy_passthrough' => planar_reference,
          'proxy_kind' => (planar_reference ? SOFT_PLANAR_PROXY_KIND : ''),
          'proxy_name' => (planar_reference ? '原平面组件（直接作为代理）' : ''),
          'proxy_render_mode' => (planar_reference ? 'native_passthrough' : ''),
          'bounds_source_signature' => fast_file_signature(target).to_s,
          'created_at' => timestamp,
          'updated_at' => timestamp
        )
        index = shared_index || read_soft_library_index(root)
        index['models'][normalize_soft_library_key(target)] = metadata
        write_soft_library_index!(index, root) unless batch_mode
        write_json_atomic(soft_model_sidecar_path(target), metadata.merge('schema' => SOFT_LIBRARY_SCHEMA))
      rescue StandardError => e
        metadata_error = e
        log_exception("家具批量入库资料写入失败：#{target}", e)
      end

      invalidate_soft_model_thumbnail!(target, root, delete_file: true)
      cache_updated = upsert_soft_library_cache_path!(target, root, persist: !batch_mode)
      unless batch_mode
        if @soft_designer_dialog && @soft_designer_dialog.visible?
          if cache_updated
            refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
          else
            schedule_soft_library_dialog_load(force: false)
          end
        end
        schedule_ingested_soft_thumbnail_calibration(model_id, model_name)
        refresh_workspace_toolbar(model)
      end
      adopted_count = adoption ? adoption[:changed].to_i : 0
      log("家具批量入库单项完成：#{category}/#{subcategory}/#{model_name} / #{elapsed_ms(total_started)}ms / 接管 #{adopted_count}")
      {
        category: category,
        subcategory: subcategory,
        model_name: model_name,
        model_id: model_id,
        target: target,
        adopted_count: adopted_count,
        representation: adoption ? adoption[:representation].to_s : 'proxy',
        planar_reference: planar_reference,
        metadata_error: metadata_error,
        cache_updated: cache_updated,
        instances: Array(adoption && adoption[:instances]).select { |instance| instance && instance.valid? },
        source_definition: (wrapper if wrapper && wrapper.valid?)
      }
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      raise
    end

    # 选择范围模式：只处理用户当前明确选中的对象。直接选中的受管真模型表示
    # “把我刚才编辑的这款写回模型库”；直接选中的代理只做六面代理校对；
    # “软装-分类-名称”则作为新模型入库。未受管的普通组合只递归寻找其中的标记家具/旧代理，
    # 不会把整个组合误写成某个已有模型。
    def collect_selected_soft_ingest_candidates(selection, space_entity, model = Sketchup.active_model)
      selected = Array(selection).select { |entity| entity && entity.valid? && (entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)) }
      candidates = []
      issues = []
      seen = {}
      visited_definitions = {}
      walk_descendants = lambda do |definition|
        return unless definition && definition.valid?
        definition_key = definition.object_id
        return if visited_definitions[definition_key]
        visited_definitions[definition_key] = true
        definition.entities.each do |child|
          next unless child && child.valid?
          next unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)
          info = soft_instance_metadata(child)
          existing = existing_soft_library_item_for_entity(child, model)
          if existing
            key = "repair:#{existing['id']}"
            unless seen[key]
              seen[key] = true
              candidates << { action: :repair, entity: child, entities: [child], model_id: existing['id'].to_s, model_name: existing['name'].to_s, source_path: existing['path'].to_s }
            end
            next
          end
          if soft_legacy_proxy_entity?(child)
            label = soft_identity_display_name(child.definition.name.to_s)
            label = '未命名历史白盒' if label.empty?
            issues << "历史白盒“#{label}”：未找到唯一可信的真模型源，已保持原位"
            next
          end
          if soft_batch_ingest_tagged_name?(child.respond_to?(:name) ? child.name.to_s : '')
            parsed = parse_soft_batch_ingest_instance_name(child.name.to_s)
            if parsed
              key = "new:#{child.definition.object_id}:#{parsed.join('|')}"
              unless seen[key]
                seen[key] = true
                candidates << { action: :new, entity: child, definition: child.definition, category: parsed[0], subcategory: parsed[1], requested_name: parsed[2], marker_name: child.name.to_s, marker_count: 1, marked_entities: [child] }
              end
            end
            next
          end
          walk_descendants.call(child.definition)
        end
      end

      selected.each do |entity|
        if entity == space_entity || soft_library_managed_root_entity?(entity, model)
          issues << '空间/建筑根组件不能作为家具入库对象'
          next
        end
        unless entity_inside_definition_tree?(entity, space_entity.definition)
          issues << "#{soft_library_selected_entity_name(entity)}: 不属于当前正在修改的空间"
          next
        end
        existing = existing_soft_library_item_for_entity(entity, model)
        if existing
          key = "managed:#{existing['id']}"
          bucket = candidates.find { |row| row[:dedupe_key].to_s == key }
          unless bucket
            action = soft_library_selected_representation(entity) == 'full' ? :update : :repair
            bucket = {
              action: action, entity: entity, entities: [], model_id: existing['id'].to_s,
              model_name: existing['name'].to_s, source_path: existing['path'].to_s, dedupe_key: key
            }
            candidates << bucket
          end
          bucket[:entities] << entity unless bucket[:entities].include?(entity)
          # 同一款只要有一个明确选中的真模型，就按“更新源模型”处理。
          bucket[:action] = :update if soft_library_selected_representation(entity) == 'full'
          next
        end
        if soft_legacy_proxy_entity?(entity)
          label = soft_identity_display_name(entity.definition.name.to_s)
          label = soft_identity_display_name(entity.name.to_s) if label.empty? && entity.respond_to?(:name)
          label = '未命名历史白盒' if label.empty?
          issues << "历史白盒“#{label}”：链接已失效且无法从模型库唯一反查，请先保留它；其它可恢复白盒仍会继续处理"
          next
        end
        instance_name = entity.respond_to?(:name) ? entity.name.to_s : ''
        if soft_batch_ingest_tagged_name?(instance_name)
          parsed = parse_soft_batch_ingest_instance_name(instance_name)
          if parsed
            key = "new:#{entity.definition.object_id}:#{parsed.join('|')}"
            existing_candidate = candidates.find { |row| row[:dedupe_key].to_s == key }
            if existing_candidate
              existing_candidate[:marked_entities] << entity unless existing_candidate[:marked_entities].include?(entity)
              existing_candidate[:marker_count] = existing_candidate[:marked_entities].length
            else
              seen[key] = true
              candidates << { action: :new, entity: entity, definition: entity.definition, category: parsed[0], subcategory: parsed[1], requested_name: parsed[2], marker_name: instance_name, marker_count: 1, marked_entities: [entity], dedupe_key: key }
            end
          else
            issues << "#{instance_name}: 命名格式无效，应为“软装-大类-子类（名称）”"
          end
          next
        end
        walk_descendants.call(entity.definition)
      end
      [candidates, issues]
    rescue StandardError => e
      log_exception('收集选择范围家具入库对象失败', e)
      [[], ["选择范围扫描失败：#{e.message}"]]
    end

    def update_existing_soft_library_from_entity!(entity, model_id:, source_path:, model_name:, model: Sketchup.active_model, shared_index: nil, expected_source_signature: '', expected_axis_mm: nil)
      raise '待更新家具实例已失效。' unless entity && entity.valid?
      raise '只有真模型才能写回模型库；代理只做六面代理校对。' if soft_library_selected_representation(entity) == 'proxy'
      root = soft_library_root
      raise '软装模型库目录无效。' if root.to_s.empty? || !Dir.exist?(root)
      item = soft_library_item(model_id.to_s, force: false) unless model_id.to_s.empty?
      path = source_path.to_s
      path = item['path'].to_s if path.empty? && item
      path = auto_relocate(path, model) unless path.empty?
      raise '找不到该家具对应的模型库源文件。' if path.empty? || !File.file?(path)
      item ||= { 'id' => (model_id.to_s.empty? ? soft_model_id_for_path(path) : model_id.to_s), 'path' => FastPath.expand(path), 'name' => model_name.to_s }
      item['name'] = File.basename(path, File.extname(path)) if item['name'].to_s.empty?

      wrapper = nil
      written_bounds = nil
      written_axis_mm = nil
      planar_reference = false
      operation_started = false
      result = nil
      adopted_instances = []
      baseline_started = monotonic_time
      source_signature_before = stable_full_file_snapshot_signature(path)
      log_slow_operation('家具入库源模型完整基线校验', baseline_started, 120.0, File.basename(path.to_s))
      if source_signature_before.to_s.empty?
        raise '无法稳定读取模型库源文件版本签名；为避免在共享目录中盲目覆盖，已取消本次更新。'
      end
      expected_edit_signature = expected_source_signature.to_s
      if !expected_edit_signature.empty?
        expected_fast_signature = normalize_fast_signature(expected_edit_signature)
        current_fast_signature = normalize_fast_signature(source_signature_before)
        if expected_fast_signature.empty? || current_fast_signature.empty? || current_fast_signature != expected_fast_signature
          raise '这款模型在你进入编辑后已被其他用户更新；LinkHub 已拒绝覆盖对方版本。当前本地真模型修改会保留，请先协调/刷新模型库后再处理。'
        end
      end
      matching_started = monotonic_time
      matching_targets, _owning_space_item, _owning_space_entity = soft_library_ingest_matching_instances(entity, model, load_state(model))
      log_slow_operation('家具入库当前空间同定义实例匹配', matching_started, 120.0, "#{item['name']} / #{Array(matching_targets).length} 实例")
      begin
        # 分成“准备定义”和“接管实例”两个短事务。共享目录传输与完整校验可能持续数秒，
        # 期间绝不保持 SketchUp Operation 打开；否则观察器、自动透明事务和原生保存线程
        # 会在同一事务边界相撞，大模型实测可能无响应或直接退出。
        model.start_operation("准备家具入库更新 #{item['name']}", true, false, false)
        operation_started = true
        wrapper_started = monotonic_time
        # 已入库家具的外层移动、旋转、缩放和镜像属于当前摆放实例，不属于库模型内容。
        # 尤其不能把负缩放统一烘焙到库模型 X 轴：那会改变其它空间/下次载入时的朝向语义。
        # 这里只保存 Definition 内部真实编辑，并让接管后的实例完整保留原矩阵及镜像轴。
        wrapper = build_soft_library_update_definition!(
          entity, item, model,
          normalize_axes: false,
          preserve_instance_reflection: false,
          expected_axis_mm: expected_axis_mm
        )
        log_slow_operation('家具入库本机候选定义构建', wrapper_started, 120.0, item['name'])
        planar_reference = soft_definition_planar_reference?(wrapper)
        soft_clear_definition_bounds_cache!(wrapper)
        written_bounds = soft_definition_bounds_values(wrapper)
        written_axis_mm = soft_definition_axis_extents(wrapper).map { |value| value.to_f.abs * 25.4 }
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_id', item['id'].to_s)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'source_path', FastPath.expand(path))
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'model_name', item['name'].to_s)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'representation', 'full')
        # 更新源模型同样不在批处理事务中触发 thumbnail_camera/refresh_thumbnail。

        # 写盘前先完成所有需要持久化到源 SKP 的定义属性；写盘后不再改这个定义，
        # 避免大型 Definition#save_copy 返回后立刻触发名称/属性重建。
        stamp_soft_library_definition!(wrapper, item)
        model.commit_operation
        operation_started = false

        transfer_started = monotonic_time
        result = write_soft_library_definition_atomic!(wrapper, path, root, expected_signature: source_signature_before)
        log("家具入库源文件安全写入完成：#{item['name']} / #{elapsed_ms(transfer_started)}ms / 模型事务未占用")

        # 外部文件确认原子写入后，再用独立短事务无损接管当前空间同定义实例。
        # wrapper 内持久化的 payload 变换 P 表示“旧定义 -> 新库定义”的精确关系，
        # 因而 T_new = T_old * P^-1，世界几何完全不动；绝不通过长宽高重新猜缩放。
        model.start_operation("家具入库接管更新 #{item['name']}", true, false, false)
        operation_started = true
        Array(matching_targets).each do |target_instance|
          next unless target_instance && target_instance.valid?
          target_instance = target_instance.to_component if target_instance.is_a?(Sketchup::Group)
          next unless target_instance && target_instance.valid?
          was_locked = target_instance.respond_to?(:locked?) ? target_instance.locked? : false
          target_instance.locked = false if was_locked && target_instance.respond_to?(:locked=)
          replaced = replace_instance_definition_preserving_library_payload!(target_instance, wrapper)
          raise "#{item['name']} 当前实例无法按精确补偿接管新轴定义，已取消本次模型库更新。" unless replaced
          stamp_soft_library_instance!(target_instance, item, model, stamp_definition: false, bump_registry: false)
          soft_set_attribute_if_changed(target_instance, SOFT_MODEL_DICT, 'representation', 'full')
          target_instance.delete_attribute(SOFT_MODEL_DICT, 'proxy_source_path') rescue nil
          clear_soft_individual_edit_save_failed_marker!(target_instance)
          target_instance.locked = true if was_locked && target_instance.respond_to?(:locked=)
          adopted_instances << target_instance
        end
        bump_soft_instance_registry_revision(model) unless adopted_instances.empty?
        remember_soft_library_definition!(wrapper, item, model)

        model.commit_operation
        operation_started = false
      rescue StandardError
        # 如果外部文件已经成功换新，但随后本地 SketchUp 事务没能提交，则只在
        # 正式文件仍等于“我们刚写入的版本”时恢复备份，避免回滚反过来覆盖别人。
        rollback_soft_library_definition_write!(result) if result
        model.abort_operation rescue nil if operation_started
        raise
      ensure
        remove_unused_definition!(wrapper, model) if wrapper && wrapper.valid? && wrapper.instances.empty? rescue nil
      end

      index = shared_index || read_soft_library_index(root)
      key = normalize_soft_library_key(path)
      metadata = default_soft_model_metadata(path)
      metadata.merge!(index['models'][key]) if index['models'][key].is_a?(Hash)
      metadata['model_id'] = item['id'].to_s
      metadata['name'] = item['name'].to_s
      metadata['bounds_values'] = written_bounds.map(&:to_f) if soft_bounds_values_valid?(written_bounds)
      metadata['planar_reference'] = planar_reference
      metadata['proxy_passthrough'] = planar_reference
      if planar_reference
        metadata['proxy_kind'] = SOFT_PLANAR_PROXY_KIND
        metadata['proxy_model_id'] = item['id'].to_s
        metadata['proxy_path'] = ''
        metadata['proxy_relative_path'] = ''
        metadata['proxy_name'] = '原平面组件（直接作为代理）'
        metadata['proxy_visual_version'] = 0
        metadata['proxy_auto_generated'] = false
        metadata['proxy_render_mode'] = 'native_passthrough'
      elsif metadata['proxy_kind'].to_s == SOFT_PLANAR_PROXY_KIND
        %w[proxy_model_id proxy_path proxy_relative_path proxy_name proxy_source_signature proxy_render_mode].each { |field| metadata[field] = '' }
        metadata['proxy_kind'] = ''
        metadata['proxy_visual_version'] = 0
        metadata['proxy_auto_generated'] = false
      end
      if Array(written_axis_mm).length == 3
        horizontal = written_axis_mm.first(2).map { |value| value.to_f.abs }.sort.reverse
        metadata['length_mm'] = horizontal[0].round(4)
        metadata['width_mm'] = horizontal[1].round(4)
        metadata['height_mm'] = written_axis_mm[2].to_f.abs.round(4)
        metadata['dimensions_cached'] = true
        # v0.13.6.192：源模型更新时同步刷新入库实测轴，避免过期的“平面”轴长期残留。
        metadata['ingested_actual_axis_mm'] = written_axis_mm.map { |value| value.to_f.abs.round(4) }
      end
      metadata['bounds_source_signature'] = fast_file_signature(path).to_s
      metadata['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      # 不删除旧六面映射；源签名变化后它自然变成“待重建”。新代理完成前旧映射
      # 仅作为方向参考，重建完成后再原子切换权威映射。
      index['models'][key] = metadata
      write_soft_library_index!(index, root) unless shared_index
      write_json_atomic(soft_model_sidecar_path(path), metadata.merge('schema' => SOFT_LIBRARY_SCHEMA)) if metadata['organized'] || normalize_soft_library_key(path).start_with?(normalize_soft_library_key(soft_library_organized_dir(root)))
      update_soft_library_cache_item!(path, metadata)
      invalidate_soft_model_thumbnail!(path, root, delete_file: true)
      schedule_ingested_soft_thumbnail_calibration(item['id'].to_s, item['name'].to_s, delay: 0.16)
      if planar_reference
        Array(adopted_instances).each do |node|
          next unless node && node.valid?
          mark_soft_planar_reference!(node.definition, true) if node.respond_to?(:definition)
          soft_set_attribute_if_changed(node, SOFT_MODEL_DICT, 'planar_reference', true)
        end
      else
        # 源 SKP 已经换新：当前会话里同 model_id 的旧六视图 Definition 必须立即
        # 标记为 stale，并清掉 session/index 快路径。旧代理仍可暂时显示，直到新的
        # 六视图文件原子生成成功后再统一替换，避免更新过程中闪成白盒/空模型。
        invalidate_soft_visual_proxy_runtime_for_model!(
          item['id'].to_s, model, source_path: FastPath.expand(path), mark_loaded_stale: true
        )
      end
      payload = {
        model_id: item['id'].to_s,
        model_name: item['name'].to_s,
        source_path: FastPath.expand(path),
        planar_reference: planar_reference,
        backup: result.is_a?(Hash) ? result['backup'].to_s : '',
        instances: adopted_instances,
        source_definition: (wrapper if wrapper && wrapper.valid?)
      }
      # 只有用户显式“家具入库/更新源模型”调用（没有 expected edit baseline）才可能
      # 退休上一轮 save_failed。单件自动保存自身仍由 finalize 的正常状态机收尾。
      if expected_source_signature.to_s.empty?
        retire_soft_save_failed_session_after_explicit_repair!(item['id'].to_s, model, source_updated: true)
      end
      payload
    end

    Kernel.load(File.expand_path('ingest_preview.rb', __dir__))

    # ---------- v0.13.6.100 家具批量入库面板 ----------
    def soft_batch_ingest_draft_entity_key(entity)
      return '' unless entity && entity.valid?
      if entity.respond_to?(:persistent_id) && entity.persistent_id.to_i.positive?
        "pid:#{entity.persistent_id.to_i}"
      else
        "oid:#{entity.object_id}"
      end
    rescue StandardError
      ''
    end

    def soft_batch_ingest_placeholder_thumbnail(label = '家具')
      text = label.to_s.gsub(/[<>&\"']/, '')[0, 18]
      svg = %Q(<svg xmlns="http://www.w3.org/2000/svg" width="220" height="160" viewBox="0 0 220 160"><rect width="220" height="160" rx="12" fill="#eef0f2"/><rect x="22" y="24" width="176" height="92" rx="10" fill="#d8dde2"/><path d="M58 103 L86 70 L108 91 L132 57 L166 103 Z" fill="#aab4bd"/><circle cx="75" cy="54" r="10" fill="#aab4bd"/><text x="110" y="142" text-anchor="middle" font-family="Arial,sans-serif" font-size="15" fill="#59636c">#{text}</text></svg>)
      "data:image/svg+xml;base64,#{Base64.strict_encode64(svg)}"
    rescue StandardError
      ''
    end

    # v0.13.6.177：批量入库面板统一以“真模型”作为语义和预览来源。
    # HtmlDialog 对网络盘/UNC 的 file:// 图片兼容性并不稳定，因此批量面板不再直接
    # 让 Chromium 去读模型库缩略图文件，而是把已存在的小图转成 data URI。这样无论
    # 模型库在本机盘、映射盘还是 \\server\share，卡片都能稳定显示。
    def soft_batch_ingest_thumbnail_data_url(path)
      source = path.to_s
      return '' unless File.file?(source) && File.size(source).positive?
      signature = begin
        "#{FastPath.expand(source)}|#{File.mtime(source).to_f}|#{File.size(source)}"
      rescue StandardError
        FastPath.expand(source) rescue source
      end
      @soft_batch_ingest_draft_thumbnail_cache ||= {}
      cached = @soft_batch_ingest_draft_thumbnail_cache[signature]
      return cached.to_s unless cached.to_s.empty?
      format = soft_thumbnail_binary_format(source)
      mime = format == :jpeg ? 'image/jpeg' : (format == :png ? 'image/png' : 'application/octet-stream')
      bytes = File.binread(source)
      return '' if bytes.empty?
      url = "data:#{mime};base64,#{Base64.strict_encode64(bytes)}"
      # 面板通常只有几十张卡；限制缓存数量，避免用户长时间连续加选时常驻过多 Base64。
      @soft_batch_ingest_draft_thumbnail_cache.clear if @soft_batch_ingest_draft_thumbnail_cache.length >= 96
      @soft_batch_ingest_draft_thumbnail_cache[signature] = url
      url
    rescue StandardError => e
      log_exception('读取家具入库面板缩略图失败', e)
      ''
    end

    # 186：现成模型库标准图仍优先；缺图交给 HtmlDialog 的只读几何轴测渲染。
    # 不再 save_copy/save_as 项目定义或提取任意旧视角的 SKP 内置小图。
    def soft_batch_ingest_true_model_thumbnail_url(row, root = soft_library_root)
      return '' unless row.is_a?(Hash) && row[:managed]
      cached = row[:thumbnail_url].to_s
      return cached if cached.start_with?('data:image/png;base64,', 'data:image/jpeg;base64,')
      source = row[:source_path].to_s
      return '' if source.empty?
      standard = soft_model_thumbnail_path(source, root)
      soft_batch_ingest_thumbnail_data_url(standard)
    rescue StandardError => e
      log_exception('读取入库标准缩略图失败', e)
      ''
    end

    # 入库流程不再把“当前显示为代理”解释成“用代理做入库”。只要该家具已经有
    # LinkHub 模型库身份，就先把本次目标实例安全切回真模型；面板、尺寸捕获和后续
    # 更新/校验全部以真模型为准。等待退出空间的多批次队列仍允许继续这样加选。
    def ensure_soft_batch_ingest_entity_full!(entity, model = Sketchup.active_model, existing: nil, allow_processing: false)
      return entity unless entity && entity.valid?
      existing ||= existing_soft_library_item_for_entity(entity, model)
      return entity unless existing.is_a?(Hash)

      # 入库面板/真正写库都明确以真模型为显示意图。如果该家具刚好还有一条代理
      # 刷新任务在跑，先从 replace_instances 中剔除，避免我们刚切回真模型，后台
      # 代理完成又把实例自动弹回代理，导致尺寸捕获与用户看到的状态再次漂移。
      set_soft_pending_proxy_display_intent!([entity], 'full', model)
      return entity if soft_instance_representation_ready?(entity, 'full')

      if !allow_processing && @soft_ingest_batch_job.is_a?(Hash) && @soft_ingest_batch_job[:active_candidate].is_a?(Hash) &&
         @soft_ingest_batch_job[:active_candidate][:model_id].to_s == existing['id'].to_s
        raise "“#{existing['name']}”此刻正在写库，请稍后再切换这一件；其它家具不受影响。"
      end
      cancel_soft_full_definition_cleanup!(model)
      operation_started = false
      failure_reason = ''
      with_soft_representation_switch(model) do
        model.start_operation('家具入库显示真模型', true)
        operation_started = true
        apply_space_soft_full_models!(nil, model, instances: [entity])
        unless soft_instance_representation_ready?(entity, 'full')
          failure_reason = soft_full_switch_failure_reason(entity, model).to_s
          failure_reason = '无法解析对应真模型源文件' if failure_reason.empty?
          raise "无法以真模型入库：#{failure_reason}"
        end
        model.commit_operation
        operation_started = false
      end
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      entity
    rescue StandardError
      model.abort_operation rescue nil if operation_started
      raise
    end

    def soft_batch_ingest_default_name(entity)
      text = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
      if text.empty? && entity.respond_to?(:definition) && entity.definition && entity.definition.valid?
        text = entity.definition.name.to_s.strip
      end
      text = soft_identity_display_name(text) rescue text
      text = '家具' if text.to_s.strip.empty?
      safe_soft_library_filename(text)
    rescue StandardError
      '家具'
    end

    # v0.13.6.180：批量入库面板按“款”而不是按“实例”建卡。
    # 已入库家具按 model_id + source_path 归并；新家具的组件实例按同一个
    # ComponentDefinition 归并。这样同一组件复制 20 个，面板只出现 1 张卡，
    # 卡片显示 ×20，提交时仍只写一次模型库并接管本次选中的全部实例。
    def soft_batch_ingest_draft_group_key(entity, existing = nil)
      return '' unless entity && entity.valid?
      if existing.is_a?(Hash)
        model_id = existing['id'].to_s
        source_path = existing['path'].to_s
        source_key = source_path.empty? ? '' : normalize_soft_library_key(source_path)
        return "managed:#{model_id}|#{source_key}" unless model_id.empty? && source_key.empty?
      end
      if entity.is_a?(Sketchup::ComponentInstance) && entity.respond_to?(:definition)
        definition = entity.definition
        if definition && definition.valid?
          guid = definition.respond_to?(:guid) ? definition.guid.to_s : ''
          token = guid.empty? ? "oid:#{definition.object_id}" : "guid:#{guid}"
          return "new-definition:#{token}"
        end
      end
      "new-entity:#{soft_batch_ingest_draft_entity_key(entity)}"
    rescue StandardError
      "new-entity:#{soft_batch_ingest_draft_entity_key(entity)}"
    end

    def soft_batch_ingest_build_draft_row(entity, model = Sketchup.active_model)
      return nil unless entity && entity.valid?
      return nil unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
      existing = existing_soft_library_item_for_entity(entity, model)
      key = soft_batch_ingest_draft_group_key(entity, existing)
      return nil if key.empty?
      # 面板里的“代理/真模型”只属于视口显示状态，不再决定入库动作。已入库家具
      # 一律先切到真模型，再按真模型源执行更新/校验。
      ensure_soft_batch_ingest_entity_full!(entity, model, existing: existing) if existing
      default_category = Sketchup.read_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_LAST_CATEGORY_PREF_KEY, '家具').to_s
      default_category = soft_library_canonical_top_category(default_category)
      default_subcategory = soft_library_default_subcategory(default_category)
      source_label = soft_batch_ingest_default_name(entity)
      if existing
        category = existing['category'].to_s
        category = default_category if category.empty?
        category = soft_library_canonical_top_category(category)
        subcategory = existing['subcategory'].to_s
        subcategory = soft_library_default_subcategory(category) if subcategory.empty?
        name = existing['name'].to_s
        name = source_label if name.empty?
        action = 'update'
        note = '真模型 · 更新 / 校验源模型'
        name_auto = false
      else
        category = default_category
        subcategory = default_subcategory
        # 新入库模型的默认“名称”属于资料字段，不应该继承杂乱的 SU 组件名。
        # 默认直接跟随子类；例如 大类=灯具、子类=壁灯，则名称自动为“壁灯”。
        # 前端只有在用户没有手改名称时才继续跟随子类变化。
        name = safe_soft_library_filename(subcategory.to_s)
        name = source_label if name.to_s.empty?
        action = 'new'
        note = "真模型 · 新家具独立入库 · 来源：#{source_label}"
        name_auto = true
      end
      # v0.13.6.149：批量入库面板预览必须是纯只读。
      # 旧版为了给“新家具”生成即时白底缩略图，会在当前项目模型里开启 transparent
      # operation、临时改样式/组件 thumbnail_camera、save_copy 后再 abort_operation。
      # 这条链在组件编辑上下文里会触发原生 active_path/事务回滚副作用，极端情况下
      # 甚至把刚建立的 LinkHub 编辑/协作状态一并回滚，表现为“点开入库窗口后自动退层、
      # 占用失效、抽屉全部失效”。面板只负责分类/命名，不值得为预览碰实时模型。
      # 已入库家具复用模型库已有图；186 的新家具先显示占位图，再只读提取几何，
      # 在独立 HtmlDialog 画布生成轴测识别图，不接回上述原生事务刷新链。
      thumb = ''
      if existing
        # 优先把已经生成的真模型标准缩略图直接内嵌给 HtmlDialog，避免 UNC file://
        # 兼容问题。没有现成缩略图时先显示占位图，面板 ready 后异步只读提取源 SKP。
        thumb_path = existing['thumbnail_path'].to_s
        if thumb_path.empty?
          candidate_thumb = soft_model_thumbnail_path(existing['path'].to_s, soft_library_root)
          thumb_path = candidate_thumb if File.file?(candidate_thumb) && File.size(candidate_thumb).positive?
        end
        thumb = soft_batch_ingest_thumbnail_data_url(thumb_path) unless thumb_path.empty?
      end
      thumb = soft_batch_ingest_placeholder_thumbnail(name) if thumb.empty?
      {
        key: key, entity: entity, entities: [entity], quantity: 1, action: action, managed: !!existing,
        model_id: existing ? existing['id'].to_s : '',
        source_path: existing ? existing['path'].to_s : '',
        category: category, subcategory: subcategory, name: name, name_auto: name_auto,
        source_label: source_label, label: source_label, note: note,
        display_representation: 'full', thumbnail_url: thumb
      }
    rescue StandardError => e
      log_exception('建立家具批量入库卡片失败', e)
      nil
    end

    def soft_batch_ingest_dialog_row_payload(row)
      {
        'key' => row[:key].to_s, 'action' => row[:action].to_s, 'managed' => !!row[:managed],
        'category' => row[:category].to_s, 'subcategory' => row[:subcategory].to_s,
        'name' => row[:name].to_s, 'name_auto' => row[:name_auto] != false,
        'source_label' => row[:source_label].to_s, 'label' => row[:label].to_s, 'note' => row[:note].to_s,
        'quantity' => [row[:quantity].to_i, 1].max,
        'display_representation' => (row[:display_representation].to_s.empty? ? 'full' : row[:display_representation].to_s),
        'thumbnail_url' => row[:thumbnail_url].to_s
      }
    rescue StandardError
      {}
    end

    def soft_batch_ingest_dialog_rows
      draft = @soft_batch_ingest_draft
      return [] unless draft.is_a?(Hash)
      Array(draft[:order]).filter_map do |key|
        row = draft[:rows].is_a?(Hash) ? draft[:rows][key.to_s] : nil
        soft_batch_ingest_dialog_row_payload(row) if row.is_a?(Hash)
      end
    rescue StandardError
      []
    end

    def soft_batch_ingest_dialog_html
      html = File.read(File.join(__dir__, 'ui', 'soft_batch_ingest.html'), encoding: 'UTF-8')
      values = { '__CATS__' => SOFT_LIBRARY_CATEGORIES, '__SUBS__' => SOFT_LIBRARY_SUBCATEGORIES,
                 '__ROWS__' => soft_batch_ingest_dialog_rows }
      # 单次替换并转义 <：家具名称中的 </script> 或模板标记不能破坏脚本。
      html = html.gsub(/__CATS__|__SUBS__|__ROWS__/) { |key| JSON.generate(values.fetch(key)).gsub('<', '\\u003c') }
      preview_js = File.read(File.join(__dir__, 'ui', 'ingest_preview.js'), encoding: 'UTF-8')
      html.sub('/*__INGEST_PREVIEW_JS__*/') { preview_js }
    end

    def soft_batch_ingest_set_adding(adding)
      dialog = @soft_batch_ingest_dialog
      dialog.execute_script("window.setAdding(#{adding ? 'true' : 'false'})") if dialog && dialog.visible?
      true
    rescue StandardError
      false
    end

    def soft_batch_ingest_dialog_error(message)
      dialog = @soft_batch_ingest_dialog
      dialog.execute_script("window.setSubmitting(false,#{JSON.generate(message.to_s)})") if dialog && dialog.visible?
    rescue StandardError
      nil
    end

    def soft_batch_ingest_draft_includes?(entity)
      draft = @soft_batch_ingest_draft
      return false unless draft.is_a?(Hash) && entity && entity.valid?
      draft[:rows].to_h.values.any? do |row|
        row.is_a?(Hash) && (row[:entity].equal?(entity) || Array(row[:entities]).any? { |node| node.equal?(entity) })
      end
    rescue StandardError
      false
    end

    def soft_batch_ingest_remove_draft_row(key)
      draft = @soft_batch_ingest_draft
      return false unless draft.is_a?(Hash)
      draft[:rows].delete(key.to_s)
      draft[:order].delete(key.to_s)
      true
    end

    def soft_batch_ingest_push_dialog_state
      dialog = @soft_batch_ingest_dialog
      return false unless dialog && dialog.visible?
      dialog.execute_script("window.setRows(#{JSON.generate(soft_batch_ingest_dialog_rows)})")
      true
    rescue StandardError
      false
    end

    def soft_batch_ingest_append_entity!(entity, model = Sketchup.active_model, push: true)
      draft = @soft_batch_ingest_draft
      raise '家具批量面板已经关闭。' unless draft.is_a?(Hash) && draft[:model].equal?(model)
      state, item, space_entity = current_local_editing_space(nil, model, required: false)
      raise '当前已经离开原来的软装空间。' unless item && space_entity && space_entity.valid? && item['id'].to_s == draft[:space_id].to_s
      raise '只能加选当前空间中的组件或群组。' unless entity && entity.valid? && (entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group))
      raise '空间根/建筑根不能作为家具入库。' if soft_library_managed_root_entity?(entity, model, state)
      raise '该对象不属于当前空间。' unless entity_inside_definition_tree?(entity, space_entity.definition)
      row = soft_batch_ingest_build_draft_row(entity, model)
      raise '无法识别该家具。' unless row
      draft[:rows] ||= {}
      draft[:order] ||= []
      current = draft[:rows][row[:key]]
      if current.is_a?(Hash)
        current[:entities] ||= [current[:entity]].compact
        unless current[:entities].any? { |node| node.equal?(entity) }
          current[:entities] << entity
          current[:quantity] = current[:entities].count { |node| node && node.valid? }
        end
      else
        current = row
        draft[:rows][row[:key]] = current
        draft[:order] << row[:key]
        schedule_soft_batch_ingest_draft_thumbnail(row[:key], model, delay: 0.05) if push
      end
      if push && @soft_batch_ingest_dialog && @soft_batch_ingest_dialog.visible?
        payload = JSON.generate(soft_batch_ingest_dialog_row_payload(current))
        @soft_batch_ingest_dialog.execute_script("window.appendRow(#{payload})")
      end
      current
    end

    def soft_batch_ingest_pick_entity(model, view, x, y)
      draft = @soft_batch_ingest_draft
      return nil unless draft.is_a?(Hash) && draft[:model].equal?(model) && model.equal?(Sketchup.active_model)
      return nil unless Array(model.active_path) == draft[:active_path]
      helper = view.pick_helper
      helper.do_pick(x, y)
      # best_picked 属于 active_entities；不拿 path_at(0) 的另一条命中路径，
      # 避免在重叠家具处高亮一件、实际加入另一件，也不选中内部螺丝/坐垫。
      entity = helper.best_picked
      return nil unless entity && entity.valid? && (entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group))
      # 鼠标在同一对象内移动时不反复遍历项目根；点击加入时仍做完整校验。
      unless draft[:pick_checked_entity].equal?(entity)
        draft[:pick_checked_entity] = entity
        draft[:pick_allowed] = !soft_library_managed_root_entity?(entity, model)
      end
      return nil unless draft[:pick_allowed]
      entity
    rescue StandardError
      nil
    end

    def soft_batch_ingest_add_entity_from_view(model, view, x, y)
      entity = soft_batch_ingest_pick_entity(model, view, x, y)
      return false unless entity
      already_added = soft_batch_ingest_draft_includes?(entity)
      row = soft_batch_ingest_append_entity!(entity, model, push: true)
      message = if already_added
                  '该家具实例已在列表中'
                elsif row[:quantity].to_i > 1
                  "已合并同款 · #{row[:source_label]} ×#{row[:quantity]}"
                else
                  "已加入 · #{row[:source_label].to_s.empty? ? row[:name] : row[:source_label]}"
                end
      show_workspace_floating_notice(message, 'success', duration: 1.4, model: model)
      true
    end

    def soft_batch_ingest_add_selection_tool_deactivated(model, tool)
      record = @soft_batch_ingest_add_tool
      if record.is_a?(Hash) && record[:model].equal?(model) && record[:tool].equal?(tool)
        @soft_batch_ingest_add_tool = nil
        soft_batch_ingest_set_adding(false)
      end
      true
    rescue StandardError
      false
    end

    def start_soft_batch_ingest_add_selection(model = Sketchup.active_model)
      draft = @soft_batch_ingest_draft
      raise '请先打开家具批量入库面板。' unless draft.is_a?(Hash) && draft[:model].equal?(model)
      raise '编辑层级已变化，请在当前空间重新打开家具入库。' unless model.equal?(Sketchup.active_model) && draft[:active_path] == Array(model.active_path)
      record = @soft_batch_ingest_add_tool
      return true if record.is_a?(Hash) && record[:model].equal?(model)
      tool = SoftBatchIngestAddSelectionTool.new(self, model)
      @soft_batch_ingest_add_tool = { model: model, tool: tool }
      model.tools.push_tool(tool)
      true
    rescue StandardError => e
      @soft_batch_ingest_add_tool = nil
      log_exception('启动家具批量加选失败', e)
      soft_batch_ingest_set_adding(false)
      soft_batch_ingest_dialog_error(e.message)
      show_status("家具加选未启动：#{e.message}", 'warning')
      false
    end

    def stop_soft_batch_ingest_add_selection(model = Sketchup.active_model)
      record = @soft_batch_ingest_add_tool
      if record.is_a?(Hash) && record[:model].equal?(model)
        record[:tool].finish if record[:tool].respond_to?(:finish)
      end
      @soft_batch_ingest_add_tool = nil
      soft_batch_ingest_set_adding(false)
      true
    rescue StandardError
      false
    end

    # 186：单队列分片读取当前真模型几何，由面板生成轴测图；不借用 SketchUp 视口。
    def schedule_soft_batch_ingest_draft_thumbnail(row_key, model = Sketchup.active_model, delay: 0.05)
      enqueue_ingest_preview186(row_key, model, delay: [delay.to_f, 0.01].max)
    end

    def open_soft_batch_ingest_dialog(model = Sketchup.active_model)
      raise '模型库还有其它批量任务正在执行，请等待完成。' if @soft_model_batch_job
      raise '发布正在进行，请稍后再入库。' if publish_critical_section? || publish_post_quiet?
      state, item, space_entity = current_local_editing_space(nil, model, required: true)
      raise '请先进入软装空间后再打开家具入库。' unless active_path_inside_space?(space_entity, model)
      if @soft_ingest_batch_job && !soft_ingest_batch_accepting_more?(@soft_ingest_batch_job, model, space_id: item['id'].to_s)
        raise "家具入库队列属于空间“#{@soft_ingest_batch_job[:space_name]}”（剩余：#{soft_ingest_batch_queue_summary(@soft_ingest_batch_job)}）；请等它结束后再入库当前空间。"
      end
      root = soft_library_root
      if root.empty? || !Dir.exist?(root)
        chosen = choose_soft_library_root
        return false unless chosen
      end

      if @soft_batch_ingest_dialog && @soft_batch_ingest_dialog.visible? && @soft_batch_ingest_draft.is_a?(Hash)
        draft = @soft_batch_ingest_draft
        if draft[:model].equal?(model) && draft[:space_id] == item['id'].to_s && draft[:active_path] == Array(model.active_path)
          @soft_batch_ingest_dialog.bring_to_front
          return true
        end
        @soft_batch_ingest_dialog.close
      end
      stop_soft_batch_ingest_add_selection(model)
      cancel_ingest_previews186!
      @soft_batch_ingest_draft_thumbnail_cache = {}
      @soft_batch_ingest_draft = { model: model, space_id: item['id'].to_s, active_path: Array(model.active_path).dup, rows: {}, order: [], opened_at: monotonic_seconds }
      selected = model.selection.to_a.select { |e| e.is_a?(Sketchup::ComponentInstance) || e.is_a?(Sketchup::Group) }
      selected.each { |entity| soft_batch_ingest_append_entity!(entity, model, push: false) rescue nil }

      dialog = @soft_batch_ingest_dialog
      unless dialog
        dialog = UI::HtmlDialog.new(
          dialog_title: 'SU LinkHub · 家具批量入库', preferences_key: 'SU_LinkHub_SoftBatchIngest',
          scrollable: false, resizable: true, width: 820, height: 620, min_width: 380, min_height: 380, style: UI::HtmlDialog::STYLE_DIALOG
        )
        dialog.add_action_callback('soft_batch_ingest_ready') do |_ctx|
          next unless @soft_batch_ingest_dialog.equal?(dialog) && @soft_batch_ingest_draft.is_a?(Hash)
          soft_batch_ingest_push_dialog_state
          # 初始选择的卡片 push=false，旧版因此永远不会触发缩略图补载。现在在面板
          # ready 后进入单条分片预览队列，不碰当前项目事务/相机，不写源 SKP。
          draft = @soft_batch_ingest_draft
          Array(draft[:order]).each_with_index do |row_key, index|
            row = draft[:rows][row_key.to_s] rescue nil
            schedule_soft_batch_ingest_draft_thumbnail(row_key, model, delay: 0.04 + index * 0.05) if row.is_a?(Hash)
          end
        end
        dialog.add_action_callback('soft_batch_ingest_preview_ready') do |_ctx, key, token, url, error|
          next unless @soft_batch_ingest_dialog.equal?(dialog)
          accept_ingest_preview186(key, token, url, error)
        end
        dialog.add_action_callback('soft_batch_ingest_add_selection') { |_ctx| start_soft_batch_ingest_add_selection(model) }
        dialog.add_action_callback('soft_batch_ingest_remove') { |_ctx, key| soft_batch_ingest_remove_draft_row(key) }
        dialog.add_action_callback('soft_batch_ingest_stop_add_selection') { |_ctx| stop_soft_batch_ingest_add_selection(model) }
        dialog.add_action_callback('soft_batch_ingest_close') do |_ctx|
          stop_soft_batch_ingest_add_selection(model)
          dialog.close
        end
        dialog.add_action_callback('soft_batch_ingest_submit') do |_ctx, json|
          safe_callback('提交家具批量入库面板') { submit_soft_batch_ingest_draft(json, model) }
        end
        dialog.set_on_closed do
          stop_soft_batch_ingest_add_selection(model) rescue nil
          cancel_ingest_previews186!
          @soft_batch_ingest_dialog = nil
          @soft_batch_ingest_draft = nil unless @soft_ingest_batch_job
        end if dialog.respond_to?(:set_on_closed)
        @soft_batch_ingest_dialog = dialog
      end
      dialog.set_html(soft_batch_ingest_dialog_html)
      dialog.show
      true
    rescue StandardError => e
      log_exception('打开家具批量入库面板失败', e)
      show_status("家具入库面板未打开：#{e.message}", 'error')
      false
    end

    # v0.13.6.182：入库队列是“可追加队列”，不再在第一批开始写库后就锁死。
    # 队列逐件处理（每 tick 一件），追加只是往 job[:queue] 尾部放候选；正在写库的那一件
    # 由 job[:active_candidate] 持有，不受影响。仅要求同一模型、同一空间。
    def soft_ingest_batch_accepting_more?(job = @soft_ingest_batch_job, model = Sketchup.active_model, space_id: '')
      return false unless job.is_a?(Hash)
      return false if job[:finishing]
      return false unless job[:model].equal?(model)
      wanted_space_id = space_id.to_s
      return false if !wanted_space_id.empty? && job[:space_id].to_s != wanted_space_id
      true
    rescue StandardError
      false
    end

    def soft_ingest_batch_processing?(job = @soft_ingest_batch_job)
      job.is_a?(Hash) && !job[:waiting_workspace_exit] && !job[:finishing]
    rescue StandardError
      false
    end

    def soft_ingest_candidate_display_name(candidate)
      return '' unless candidate.is_a?(Hash)
      name = candidate[:model_name].to_s
      name = candidate[:requested_name].to_s if name.empty?
      name = soft_library_selected_entity_name(candidate[:entity]).to_s if name.empty? && candidate[:entity] && candidate[:entity].valid?
      name
    rescue StandardError
      ''
    end

    def soft_ingest_batch_queue_summary(job = @soft_ingest_batch_job, limit: 4)
      return '' unless job.is_a?(Hash)
      rows = []
      rows << job[:active_candidate] if job[:active_candidate].is_a?(Hash)
      rows.concat(Array(job[:queue]))
      names = rows.map { |candidate| soft_ingest_candidate_display_name(candidate) }.reject(&:empty?)
      names.empty? ? "#{rows.length} 项" : soft_furniture_name_summary(names, limit: limit)
    rescue StandardError
      ''
    end

    # 只有“正在往模型库写文件”的操作才需要与入库互斥（模型库批量、单件入库、缩略图重建、
    # 插件更新等）。空间/建筑/景观更新、发布等前台任务不再被入库队列整体挡住：入库循环
    # 每处理一件前都会检查并给这些任务让路。
    def ensure_soft_ingest_batch_not_writing!(action_label)
      job = @soft_ingest_batch_job
      return true unless soft_ingest_batch_processing?(job)
      summary = soft_ingest_batch_queue_summary(job)
      raise "家具入库正在写库（#{job[:space_name]}：#{summary}）；#{action_label}会在本批写库结束后自动可用，无需退出或重载。"
    end

    def soft_ingest_candidate_queue_key(candidate)
      return '' unless candidate.is_a?(Hash)
      action = (candidate[:action] || :new).to_sym
      if action == :new
        definition = candidate[:definition]
        entity = candidate[:entity]
        definition ||= entity.definition if entity && entity.valid? && entity.respond_to?(:definition)
        if definition && definition.valid?
          guid = definition.respond_to?(:guid) ? definition.guid.to_s : ''
          token = guid.empty? ? "oid:#{definition.object_id}" : "guid:#{guid}"
          return "new-definition:#{token}"
        end
        entity_key = soft_batch_ingest_draft_entity_key(entity)
        return "new:#{entity_key}" unless entity_key.empty?
      else
        model_id = candidate[:model_id].to_s
        source_path = candidate[:source_path].to_s
        source_key = source_path.empty? ? '' : normalize_soft_library_key(source_path)
        return "managed:#{model_id}|#{source_key}" unless model_id.empty? && source_key.empty?
        entity = candidate[:entity] || Array(candidate[:entities]).first
        entity_key = soft_batch_ingest_draft_entity_key(entity)
        return "managed-entity:#{entity_key}" unless entity_key.empty?
      end
      "fallback:#{candidate.object_id}"
    rescue StandardError
      "fallback:#{candidate.object_id}"
    end

    def merge_soft_ingest_candidates_into_waiting_job!(job, candidates, model = Sketchup.active_model)
      unless soft_ingest_batch_accepting_more?(job, model, space_id: job[:space_id])
        raise "家具入库队列属于空间“#{job[:space_name]}”，当前空间的家具请等该队列结束后再提交（剩余：#{soft_ingest_batch_queue_summary(job)}）。"
      end
      prepared = prepare_soft_pending_ingest_candidates!(Array(candidates), model)
      queue = Array(job[:queue])
      by_key = {}
      queue.each { |candidate| by_key[soft_ingest_candidate_queue_key(candidate)] = candidate if candidate.is_a?(Hash) }
      active_key = job[:active_candidate].is_a?(Hash) ? soft_ingest_candidate_queue_key(job[:active_candidate]) : ''
      added = 0
      merged = 0

      prepared.each do |candidate|
        next unless candidate.is_a?(Hash)
        key = soft_ingest_candidate_queue_key(candidate)
        if !active_key.empty? && key == active_key
          # 这一款此刻正在写库：新加的同款实例会由写库完成后的定义接管自然覆盖，
          # 不再重复排队，避免“同一 Definition 出现两张卡/两次写库”。
          merged += 1
          next
        end
        existing = by_key[key]
        if existing
          merged += 1
          action = (candidate[:action] || :new).to_sym
          if action == :new
            # 同一实体再次提交时，以用户最后一次在面板里的分类/名称为准。
            existing[:category] = candidate[:category]
            existing[:subcategory] = candidate[:subcategory]
            existing[:requested_name] = candidate[:requested_name]
            existing[:marked_entities] = (Array(existing[:marked_entities]) + Array(candidate[:marked_entities]) + [candidate[:entity]]).select { |node| node && node.valid? }.uniq
            existing[:marker_count] = existing[:marked_entities].length
            existing[:entity] = candidate[:entity] if candidate[:entity] && candidate[:entity].valid?
          else
            existing[:entities] = (Array(existing[:entities]) + Array(candidate[:entities]) + [candidate[:entity]]).select { |node| node && node.valid? }.uniq
            incoming_full = existing[:entities].find { |node| soft_library_selected_representation(node).to_s == 'full' }
            if incoming_full
              existing[:action] = :update
              existing[:entity] = incoming_full
            elsif existing[:action].to_sym != :update
              existing[:action] = :repair
              existing[:entity] ||= existing[:entities].first
            end
            existing[:model_name] = candidate[:model_name] unless candidate[:model_name].to_s.empty?
            existing[:source_path] = candidate[:source_path] unless candidate[:source_path].to_s.empty?
          end
          prepare_soft_pending_ingest_candidates!([existing], model)
        else
          queue << candidate
          by_key[key] = candidate
          added += 1
        end
      end

      job[:queue] = queue
      job[:total] = queue.length + job[:done].to_i + (job[:active_candidate].is_a?(Hash) ? 1 : 0)
      job[:marked_total] = queue.sum { |candidate| candidate[:marker_count].to_i }
      job[:last_queue_append_at] = monotonic_time
      if soft_ingest_batch_processing?(job)
        log("家具入库队列在处理中追加：新增 #{added} · 合并 #{merged} · 队列共 #{job[:total]}")
      end
      { added: added, merged: merged, total: job[:total].to_i }
    end

    def start_soft_batch_ingest_candidates_job!(candidates, model, item, root)
      raise '没有可提交的家具。' if Array(candidates).empty?
      if @soft_ingest_batch_job
        job = @soft_ingest_batch_job
        unless soft_ingest_batch_accepting_more?(job, model, space_id: item['id'].to_s)
          raise "家具入库队列属于空间“#{job[:space_name]}”（剩余：#{soft_ingest_batch_queue_summary(job)}）；请等它结束后再提交当前空间的家具。"
        end
        names = soft_furniture_name_summary(Array(candidates).map { |candidate| soft_ingest_candidate_display_name(candidate) })
        result = merge_soft_ingest_candidates_into_waiting_job!(job, candidates, model)
        if soft_ingest_batch_processing?(job)
          update_task_center_job!(
            job[:task_id], stage: "正在批量入库 #{job[:done]}/#{job[:total]} · 已追加",
            detail: "新追加：#{names} · 队列共 #{result[:total]} 项", status: 'running'
          )
          show_status("已追加到正在执行的家具入库队列：#{names}；队列共 #{result[:total]} 项，退出空间后继续处理。", 'info')
          show_workspace_floating_notice("已追加待入库 · #{names}", 'info', duration: 4.0, model: model)
        else
          update_task_center_job!(
            job[:task_id], progress: 2, stage: '等待退出工作空间 · 可继续加批次',
            detail: "新追加：#{names} · 队列共 #{result[:total]} 项 · 退出空间后统一入库", status: 'queued'
          )
          show_status("已继续加入家具入库队列：#{names}（新增 #{result[:added]}，合并 #{result[:merged]}）；当前共 #{result[:total]} 项，最后退出空间一次统一处理。", 'info')
          show_workspace_floating_notice("待入库 · #{names} · 队列共 #{result[:total]} 件", 'info', duration: 4.0, model: model)
        end
        refresh_workspace_toolbar(model)
        Sketchup.set_status_text("待入库 #{result[:total]} 项 · 可继续加批次 · 最后退出空间统一处理") if Sketchup.respond_to?(:set_status_text)
        return true
      end
      candidates = prepare_soft_pending_ingest_candidates!(Array(candidates), model)
      task_id = start_task_center_job!(
        'soft_ingest_batch', label: "家具批量入库 · #{item['number']}:#{item['name']}",
        stage: '等待退出工作空间 · 可继续加批次', progress: 2,
        detail: "队列共 #{candidates.length} 项 · 可继续入库下一批 · 最后退出空间统一处理", status: 'queued'
      )
      @soft_ingest_batch_job = {
        token: "#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(3)}",
        model: model, space_id: item['id'].to_s, space_name: "#{item['number']}:#{item['name']}",
        selected_mode: true, audit_current_space: false, queue: Array(candidates).dup,
        total: Array(candidates).length, marked_total: Array(candidates).length,
        done: 0, success: 0, failed: 0, adopted: 0, updated: 0, repaired: 0, legacy_identity_repaired: 0,
        issues: [], errors: [], failed_candidates: [], new_models: [], visual_proxy_seeds: [],
        root: root, index: nil, started_at: monotonic_time, waiting_workspace_exit: true,
        heavy_interaction_started: false, active_candidate: nil, task_id: task_id.to_s
      }
      refresh_workspace_toolbar(model)
      names = soft_furniture_name_summary(Array(candidates).map { |candidate| soft_ingest_candidate_display_name(candidate) })
      show_status("已登记待入库家具：#{names}；模型保持原状并以蓝色标记，你可以继续加入下一批，最后退出当前空间一次统一处理。", 'info')
      show_workspace_floating_notice("待入库 · #{names}", 'info', duration: 4.5, model: model)
      Sketchup.set_status_text("待入库 #{candidates.length} 项 · 可继续加批次 · 最后退出空间统一处理") if Sketchup.respond_to?(:set_status_text)
      runtime_start_timer(0.12, false, label: 'soft:tagged_ingest_wait_workspace_exit') { process_soft_tagged_furniture_ingest_job }
      true
    end

    def submit_soft_batch_ingest_draft(json, model = Sketchup.active_model)
      raise '模型库还有其它批量任务正在执行，请等待完成。' if @soft_model_batch_job
      raise '发布正在进行，请稍后再入库。' if publish_critical_section? || publish_post_quiet?
      draft = @soft_batch_ingest_draft
      raise '家具批量入库面板已经失效，请重新打开。' unless draft.is_a?(Hash) && draft[:model].equal?(model)
      payload = JSON.parse(json.to_s)
      submitted = Array(payload['rows'])
      raise '至少保留一件家具再提交。' if submitted.empty?
      keys = submitted.map { |spec| spec.is_a?(Hash) ? spec['key'].to_s : '' }
      raise '入库列表包含无效或重复对象，请重新打开面板。' if keys.include?('') || keys.uniq.length != keys.length
      state, item, space_entity = current_local_editing_space(nil, model, required: true)
      raise '当前已经离开打开面板时的空间。' unless item['id'].to_s == draft[:space_id].to_s && active_path_inside_space?(space_entity, model)
      if @soft_ingest_batch_job && !soft_ingest_batch_accepting_more?(@soft_ingest_batch_job, model, space_id: item['id'].to_s)
        raise "家具入库队列属于空间“#{@soft_ingest_batch_job[:space_name]}”（剩余：#{soft_ingest_batch_queue_summary(@soft_ingest_batch_job)}）；请等它结束后再入库当前空间。"
      end
      root = soft_library_root
      raise '软装模型库目录不可用。' if root.empty? || !Dir.exist?(root)
      ensure_soft_library_structure!(root)

      candidates = []
      submitted.each do |spec|
        key = spec['key'].to_s
        row = draft[:rows][key] rescue nil
        entity = row.is_a?(Hash) ? row[:entity] : nil
        row_entities = row.is_a?(Hash) ? Array(row[:entities]).select { |node| node && node.valid? } : []
        row_entities << entity if entity && entity.valid? && !row_entities.any? { |node| node.equal?(entity) }
        entity = row_entities.first unless entity && entity.valid?
        raise "有一款待入库家具的实例已经全部失效：#{key}" unless entity && entity.valid? && row_entities.any?
        raise '空间根/建筑根不能作为家具入库。' if soft_library_managed_root_entity?(entity, model, state)
        raise '有一件对象已经不属于当前空间。' unless entity_inside_definition_tree?(entity, space_entity.definition)

        existing = existing_soft_library_item_for_entity(entity, model)
        if existing
          # 用户即使从代理状态打开/加选，提交前也再次确认该实例已经是真模型。
          # 因而批量面板不会再产生 :repair（代理作为入库语义）候选；代理重建属于
          # 真模型更新成功后的发布队列工作。
          ensure_soft_batch_ingest_entity_full!(entity, model, existing: existing)
          candidates << {
            action: :update, entity: entity, entities: row_entities,
            model_id: existing['id'].to_s, model_name: existing['name'].to_s, source_path: existing['path'].to_s,
            marker_count: row_entities.length, draft_ui: true
          }
          next
        end

        # 提交阶段只建立队列，不 make_unique、不写属性、不改变定义；真正接管在退出空间后完成。
        category = soft_library_canonical_top_category(spec['category'].to_s)
        subcategory = safe_soft_library_subcategory_name(spec['subcategory'].to_s, category)
        raise '新家具名称不能为空。' if spec['name'].to_s.strip.empty?
        requested_name = safe_soft_library_filename(spec['name'].to_s)
        raise '新家具名称不能为空。' if requested_name.empty?
        candidates << {
          action: :new, entity: entity, definition: (entity.definition rescue nil),
          category: category, subcategory: subcategory, requested_name: requested_name,
          marker_count: row_entities.length, marked_entities: row_entities, draft_ui: true
        }
      end

      Sketchup.write_default(SOFT_DESIGNER_PREF_SECTION, SOFT_LIBRARY_LAST_CATEGORY_PREF_KEY, candidates.find { |c| c[:action] == :new }.to_h[:category].to_s) rescue nil
      stop_soft_batch_ingest_add_selection(model)
      @soft_batch_ingest_dialog.close if @soft_batch_ingest_dialog && @soft_batch_ingest_dialog.visible?
      # set_on_closed 可能清 draft；任务已经只持有实体/candidate 引用，不再依赖面板。
      start_soft_batch_ingest_candidates_job!(candidates, model, item, root)
      true
    rescue StandardError => e
      log_exception('提交家具批量入库面板失败', e)
      soft_batch_ingest_dialog_error(e.message)
      show_status("家具批量入库未提交：#{e.message}", 'error')
      false
    end

    def start_soft_tagged_furniture_ingest_job(model = Sketchup.active_model)
      individual_edit = soft_individual_edit_session(model)
      if individual_edit && individual_edit[:phase].to_s != 'save_failed'
        raise '当前有单件家具处于真模型编辑/自动收尾中；请先完成或取消该家具，再执行家具入库。'
      end
      raise '模型库还有其它批量任务正在执行，请等待完成。' if @soft_model_batch_job
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再入库。' if publish_critical_section? || publish_post_quiet?
      raise '空间模型正在更新，请等待完成后再入库。' if @updating || @single_space_update_job || @space_batch_update_job

      state, item, space_entity = current_local_editing_space(nil, model, required: true)
      raise '当前处于安全暂存/全模审阅；请先点击“继续”回到空间，再执行家具入库。' unless active_path_inside_space?(space_entity, model)
      # v0.13.6.182：已有入库队列时不再报“正在执行”，同空间直接追加；代理后台队列也不再
      # 挡住入库登记（真正写库时入库循环会与代理截图互相让路）。
      if @soft_ingest_batch_job && !soft_ingest_batch_accepting_more?(@soft_ingest_batch_job, model, space_id: item['id'].to_s)
        job = @soft_ingest_batch_job
        raise "家具入库队列属于空间“#{job[:space_name]}”（剩余：#{soft_ingest_batch_queue_summary(job)}）；请等它结束后再提交当前空间的家具。"
      end
      root = soft_library_root
      if root.empty? || !Dir.exist?(root)
        chosen = choose_soft_library_root
        return false unless chosen
        root = soft_library_root
      end
      ensure_soft_library_structure!(root)

      selected = model.selection.to_a.select { |entity| entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) }
      selected_mode = !selected.empty?
      candidates, issues = if selected_mode
                              collect_selected_soft_ingest_candidates(selected, space_entity, model)
                            else
                              collect_soft_batch_ingest_candidates(space_entity, model)
                            end

      # 无选择且没有可入库/可自动认领候选时，按钮仍承担当前空间六面代理校对。
      # v0.13.6.13：即使空间里还有正常家具可校对，也不能把“历史白盒无法找回”
      # 静默吞掉；正常家具继续处理，失联白盒保持原位，并一次性把名单告诉用户。
      if !selected_mode && candidates.empty?
        unresolved_legacy = Array(issues).select { |text| text.to_s.start_with?('历史白盒') }.uniq

        # v0.13.6.14 崩溃止损：历史救援报告与 definition/代理后台任务绝不并发。
        # 0.13.6.13 会先 start_soft_schedule_visual_proxy_upgrade，再弹模态 messagebox；
        # 用户点击“确定”后 SketchUp timer 立刻恢复并进入 definitions.load/替换路径，
        # 原生层可能直接崩溃，Ruby rescue 无法捕获。只要本轮存在失联白盒且没有
        # 成功恢复候选，本次点击就是“纯只读救援扫描”，不启动任何六面体后台工作。
        if unresolved_legacy.any?
          status = "历史白盒扫描完成：#{unresolved_legacy.length} 项暂时无法唯一确认真模型；本次没有启动全空间六面代理替换，所有对象保持原位。"
          show_status(status, 'warning')
          if defined?(UI) && UI.respond_to?(:messagebox)
            lines = unresolved_legacy.first(40)
            lines << "……另有 #{unresolved_legacy.length - 40} 项，详见 LinkHub 日志。" if unresolved_legacy.length > 40
            UI.messagebox(
              "历史白盒救援结果\n\n本轮只做了只读身份扫描，没有同时启动六面代理生成/替换。下面这些白盒证据不足，保持原位：\n\n#{lines.join("\n")}\n\n其它正常家具本次也没有被改动。",
              MB_OK
            )
          end
          log("历史白盒未自动认领（纯扫描，无后台代理任务）：#{unresolved_legacy.join(' | ')}")
          return true
        end

        seeds = soft_visual_proxy_seeds_for_space(space_entity, model)
        if seeds.empty?
          detail = issues.first(8).join('；')
          raise(detail.empty? ? '当前空间没有识别到可入库、可校对或可自动恢复的家具。' : detail)
        end
        start_soft_schedule_visual_proxy_upgrade(model, reason: '家具入库校对', seeds: seeds, scope_space_id: item['id'].to_s)
        show_status("当前空间没有新的“软装-”标记，已开始校对 #{seeds.length} 款已确认身份家具的六面代理；其它空间不会被修改。", 'info')
        return true
      end

      if selected_mode && candidates.empty?
        detail = issues.first(6).join('；')
        raise(detail.empty? ? '当前选择中没有可入库、可更新或可校对的家具。' : detail)
      end

      if @soft_ingest_batch_job
        # 同空间已有队列：直接追加，沿用同一张任务卡。
        return start_soft_batch_ingest_candidates_job!(candidates, model, item, root)
      end

      candidates = prepare_soft_pending_ingest_candidates!(candidates, model)
      task_id = start_task_center_job!(
        'soft_ingest_batch', label: "家具批量入库 · #{item['number']}:#{item['name']}",
        stage: '等待退出工作空间', progress: 2,
        detail: "#{candidates.length} 项保持原状，退出空间后统一入库", status: 'queued'
      )
      @soft_ingest_batch_job = {
        token: "#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(3)}",
        model: model,
        space_id: item['id'].to_s,
        space_name: "#{item['number']}:#{item['name']}",
        selected_mode: selected_mode,
        audit_current_space: false, # v0.13.6.14：入库/救援收尾只处理本批成功对象，不再隐式全空间扫 definition
        queue: candidates.dup,
        total: candidates.length,
        marked_total: candidates.sum { |candidate| candidate[:marker_count].to_i },
        done: 0, success: 0, failed: 0, adopted: 0, updated: 0, repaired: 0, legacy_identity_repaired: 0,
        issues: issues.dup, errors: [], failed_candidates: [], new_models: [], visual_proxy_seeds: [],
        root: root, index: nil, started_at: monotonic_time, waiting_workspace_exit: true,
        heavy_interaction_started: false, active_candidate: nil, task_id: task_id.to_s
      }
      refresh_workspace_toolbar(model)
      scope_text = selected_mode ? "仅处理当前选择 #{selected.length} 个对象" : '扫描当前空间'
      names = soft_furniture_name_summary(Array(candidates).map { |candidate| soft_ingest_candidate_display_name(candidate) })
      show_status("家具入库已登记：#{scope_text}；#{names} 保持原状并以蓝色标记，退出空间后统一处理，期间可继续追加。", 'info')
      show_workspace_floating_notice("待入库 · #{names} · 退出空间后处理", 'info', duration: 4.5, model: model)
      Sketchup.set_status_text("待入库 #{candidates.length} 项 · 请正常退出当前空间") if Sketchup.respond_to?(:set_status_text)
      runtime_start_timer(0.12, false, label: 'soft:tagged_ingest_wait_workspace_exit') { process_soft_tagged_furniture_ingest_job }
      true
    end

    def finish_soft_tagged_furniture_ingest_job(job, aborted: false, abort_message: '')
      return false unless job
      root = job[:root].to_s
      begin
        if job[:success].to_i.positive? && job[:index].is_a?(Hash) && Array(job[:new_models]).any?
          latest_index = read_soft_library_index(root)
          latest_index['models'] ||= {}
          source_models = job[:index]['models'].is_a?(Hash) ? job[:index]['models'] : {}
          Array(job[:new_models]).each do |entry|
            key = normalize_soft_library_key(entry[:target].to_s)
            latest_index['models'][key] = source_models[key] if source_models[key].is_a?(Hash)
          end
          write_soft_library_index!(latest_index, root)
        end
      rescue StandardError => e
        job[:issues] << "模型库索引最终写入失败：#{e.message}"
        log_exception('家具入库最终索引写入失败', e)
      end

      persist_soft_library_cache! if job[:success].to_i.positive?
      refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false) if @soft_designer_dialog && @soft_designer_dialog.visible?
      Array(job[:new_models]).each_with_index do |entry, index|
        schedule_ingested_soft_thumbnail_calibration(entry[:id], entry[:name], delay: 0.20 + index * 0.06)
      end

      model = job[:model] || Sketchup.active_model
      state = load_state(model)
      space = space_model_record(state, job[:space_id].to_s)
      space_entity = space ? space_model_entity(space['id'], model) : nil
      seeds = Array(job[:visual_proxy_seeds]).dup
      # v184: 源模型写入与代理验收是两阶段；释放写库占用后立即续接代理队列。
      seeds.concat(soft_visual_proxy_seeds_for_space(space_entity, model)) if job[:audit_current_space] && space_entity && space_entity.valid?
      seen = {}
      seeds = seeds.each_with_object([]) do |seed, rows|
        next unless seed.is_a?(Hash)
        key = seed[:model_id].to_s.empty? ? seed[:source_path].to_s : seed[:model_id].to_s
        next if key.empty?
        existing = seen[key]
        if existing
          existing[:replace_instances] = (Array(existing[:replace_instances]) + Array(seed[:replace_instances])).select { |i| i && i.valid? }.uniq
        else
          copy = seed.dup
          copy[:scope_space_id] = job[:space_id].to_s if copy[:scope_space_id].to_s.empty?
          copy[:replace_instances] = Array(copy[:replace_instances]).select { |i| i && i.valid? }
          seen[key] = copy
          rows << copy
        end
      end
      deferred_proxy_count = 0 # queued below, after the source-writer lock is released

      schedule_soft_full_definition_cleanup(model, delay: 1.2) if job[:success].to_i.positive?
      end_soft_heavy_interaction(:soft_ingest_batch) if job[:heavy_interaction_started]
      @soft_ingest_batch_job = nil
      unless aborted
        if job[:inside_commit_tick]
          job[:post_context_seeds] = seeds
          deferred_proxy_count = seeds.sum { |seed| Array(seed[:replace_instances]).length }
        else
          deferred_proxy_count = enqueue_soft_ingest_proxy_followup!(job, seeds, model)
        end
      end
      refresh_workspace_toolbar(model)
      Sketchup.set_status_text('') if Sketchup.respond_to?(:set_status_text)
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)

      elapsed = elapsed_ms(job[:started_at])
      message = if aborted
                  "家具入库已停止：#{abort_message}；此前成功 #{job[:success]} 项。"
                else
                  "家具入库完成：新入库 #{job[:new_models].length} 款 / 更新源模型 #{job[:updated]} 款 / 代理校对 #{job[:repaired]} 款"
                end
      message += " / 历史白盒重新绑定 #{job[:legacy_identity_repaired]} 个" if job[:legacy_identity_repaired].to_i.positive?
      message += "，失败 #{job[:failed]} 项" if job[:failed].to_i.positive?
      if job[:failed].to_i.positive? && Array(job[:errors]).any?
        summaries = Array(job[:errors]).first(3).map { |entry| "#{entry[:name]}：#{entry[:message]}" }
        message += "；失败原因：#{summaries.join('；')}"
        message += "；另有 #{job[:errors].length - 3} 项详见主日志" if job[:errors].length > 3
      end
      unresolved_legacy = Array(job[:issues]).select { |text| text.to_s.start_with?('历史白盒') }.uniq
      message += "；另有 #{unresolved_legacy.length} 个历史白盒证据不足，保持原位" if unresolved_legacy.any?
      unless aborted || seeds.empty?
        seed_names = soft_furniture_name_summary(seeds.map { |seed| seed[:model_name].to_s })
        message += "；#{seed_names} 的源模型已写入，代理已进入更新队列；验收与关联完成前保持真模型"
      end
      message += "（#{elapsed}ms）"
      status_kind = (aborted || job[:failed].to_i.positive? || unresolved_legacy.any?) ? 'warning' : 'success'
      show_status(message, status_kind)
      task_success = !aborted && job[:failed].to_i.zero?
      finish_task_center_job!(
        job[:task_id], success: task_success,
        stage: (task_success ? (seeds.empty? ? '家具批量入库完成' : '源模型写入完成 · 代理另行验收') : '家具批量入库有失败'), detail: message
      ) unless job[:task_id].to_s.empty?
      success_names = soft_furniture_name_summary(
        Array(job[:new_models]).map { |entry| entry[:name].to_s } +
        Array(job[:success_names]).map(&:to_s), limit: 4
      )
      failed_names = soft_furniture_name_summary(Array(job[:errors]).map { |entry| entry[:name].to_s }, limit: 3)
      show_workspace_floating_notice(
        task_success ? (seeds.empty? ? "家具入库完成 · #{success_names}" : "源模型已入库 · 代理待完成：#{success_names}") : "家具入库完成 · 成功 #{job[:success]} · 失败：#{failed_names}",
        task_success ? 'success' : 'warning', duration: 5.0, model: model
      )
      if !aborted && unresolved_legacy.any? && defined?(UI) && UI.respond_to?(:messagebox)
        lines = unresolved_legacy.first(40)
        lines << "……另有 #{unresolved_legacy.length - 40} 项，详见 LinkHub 日志。" if unresolved_legacy.length > 40
        UI.messagebox(
          "历史白盒救援结果\n\n已自动救回能够唯一确认身份的历史白盒。\n下面这些白盒证据不足，所以没有猜模型、没有移动、没有删除：\n\n#{lines.join("\n")}\n\n点击确定后，只会继续处理本批已经成功确认身份的对象，不会启动全空间代理扫描。",
          MB_OK
        )
      end

      log("#{message} / 待发布代理实例 #{deferred_proxy_count} / 详细失败：#{job[:errors].map { |e| "#{e[:name]}=#{e[:message]}" }.join(' | ')} / 未自动认领：#{unresolved_legacy.join(' | ')}")
      true
    rescue StandardError => e
      end_soft_heavy_interaction(:soft_ingest_batch) if job && job[:heavy_interaction_started]
      @soft_ingest_batch_job = nil
      Sketchup.set_status_text('') if Sketchup.respond_to?(:set_status_text)
      finish_task_center_job!(job[:task_id], success: false, stage: '家具批量入库收尾失败', detail: e.message.to_s, error: e) if job && !job[:task_id].to_s.empty?
      log_exception('家具入库收尾失败', e)
      show_status("家具入库收尾失败：#{e.message}", 'error')
      false
    end

    def process_soft_tagged_furniture_ingest_job
      return false if @soft_ingest_driver_processing
      @soft_ingest_driver_processing = true
      owns_ingest_driver = true
      job = @soft_ingest_batch_job
      return false unless job
      model = job[:model] || Sketchup.active_model
      return process_soft_tagged_furniture_ingest_job_at_root unless model && !model.active_path.nil?
      explicit = Array(job[:queue]).any? { |candidate| candidate[:explicit_commit] }
      unless explicit && soft_visual_proxy_inside_space_generation_allowed?(model)
        runtime_start_timer(0.24, false, label: 'soft:ingest_wait_context') { process_soft_tagged_furniture_ingest_job }
        return true
      end
      current = current_soft_designer_fab_space(model)
      unless current && current['id'].to_s == job[:space_id].to_s
        runtime_start_timer(0.24, false, label: 'soft:ingest_wait_owning_space') { process_soft_tagged_furniture_ingest_job }
        return true
      end
      job[:inside_commit_tick] = true
      with_soft_commit_world_context(model) { process_soft_tagged_furniture_ingest_job_at_root }
      if job[:post_context_seeds]
        enqueue_soft_ingest_proxy_followup!(job, job.delete(:post_context_seeds), model)
      end
      # If unselected items remain, let them wait for normal exit. Release the
      # writer lock so just-written selected items can finish their proxy queue.
      if @soft_ingest_batch_job.equal?(job)
        seeds = Array(job[:visual_proxy_seeds]).dup
        job[:visual_proxy_seeds] = []
        end_soft_heavy_interaction(:soft_ingest_batch) if job[:heavy_interaction_started]
        job[:heavy_interaction_started] = false
        job[:waiting_workspace_exit] = true
        enqueue_soft_ingest_proxy_followup!(job, seeds, model) unless seeds.empty?
      end
      true
    rescue StandardError => e
      log_exception('所选家具就地提交失败', e)
      show_workspace_floating_notice("所选家具提交暂停 · #{e.message}", 'warning', duration: 5.0, model: model)
      false
    ensure
      job[:inside_commit_tick] = false if job.is_a?(Hash)
      @soft_ingest_driver_processing = false if owns_ingest_driver
    end

    def process_soft_tagged_furniture_ingest_job_at_root
      job = @soft_ingest_batch_job
      return false unless job
      model = job[:model] || Sketchup.active_model
      if job[:waiting_workspace_exit]
        unless model && model.active_path.nil?
          runtime_start_timer(0.24, false, label: 'soft:tagged_ingest_wait_workspace_exit') { process_soft_tagged_furniture_ingest_job }
          return true
        end
        # 退出收尾和已修改家具的代理任务都可能在同一帧被唤醒。v0.13.6.182：只在代理队列
        # 正处于某一款的截图/构建中途时让路；代理队列在两款之间会主动给入库让路，
        # 不必等整条代理队列跑完才开始写库。
        proxy_mid_candidate = @soft_visual_proxy_upgrade_job.is_a?(Hash) && @soft_visual_proxy_upgrade_job[:active_candidate_state]
        if proxy_mid_candidate || publish_critical_section? || publish_post_quiet? || @updating || @single_space_update_job || @space_batch_update_job
          runtime_start_timer(0.25, false, label: 'soft:tagged_ingest_wait_root_idle') { process_soft_tagged_furniture_ingest_job }
          return true
        end
        state = load_state(model)
        item = space_model_record(state, job[:space_id].to_s)
        space_entity = item ? space_model_entity(item['id'], model) : nil
        unless item && space_entity && space_entity.valid?
          return finish_soft_tagged_furniture_ingest_job(job, aborted: true, abort_message: '退出后找不到原空间或空间实例已失效')
        end
        exit_lock = space_lock_info(item, model)
        exit_context_cleared = !(@space_edit_contexts && @space_edit_contexts[model.object_id])
        exit_finalizing = @space_context_exit_handling && @space_context_exit_handling[model.object_id]
        continuous_preview = item['editing'] == true && !entity_native_locked?(space_entity) &&
                             exit_lock['exists'] && !exit_lock['stale'] && exit_lock['owned'] &&
                             exit_context_cleared && !exit_finalizing
        explicit_ready = job[:inside_commit_tick] && exit_lock['exists'] && !exit_lock['stale'] && exit_lock['owned']
        exit_ready = explicit_ready || continuous_preview || space_edit_safe_paused?(item) || (item['editing'] != true && entity_native_locked?(space_entity))
        unless exit_ready
          # active_path 先变 nil，等待退出收尾把空间确认为连续全局预览或旧版安全暂存。
          runtime_start_timer(0.18, false, label: 'soft:tagged_ingest_wait_space_exit_finalize') { process_soft_tagged_furniture_ingest_job }
          return true
        end
        job[:index] = read_soft_library_index(job[:root].to_s)
        job[:waiting_workspace_exit] = false
        job[:heavy_interaction_started] = true
        begin_soft_heavy_interaction(:soft_ingest_batch)
        update_task_center_job!(job[:task_id], progress: 6, stage: '已退出工作空间 · 开始入库', detail: "共 #{job[:total]} 项", status: 'running')
        show_workspace_floating_notice("家具批量入库 · 0/#{job[:total]}", 'info', progress: 0, persistent: true, model: model)
        Sketchup.set_status_text("家具入库 0 / #{job[:total]} · #{job[:space_name]}") if Sketchup.respond_to?(:set_status_text)
        model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
        log("家具待入库队列开始：已正常退出空间 / #{job[:space_name]} / #{job[:total]} 项")
      end
      if publish_critical_section? || publish_post_quiet? || @updating || @single_space_update_job || @space_batch_update_job
        runtime_start_timer(0.25, false, label: 'soft:tagged_ingest_wait') { process_soft_tagged_furniture_ingest_job }
        return true
      end

      unless model && model.active_path.nil?
        runtime_start_timer(0.24, false, label: 'soft:tagged_ingest_pause_reentered_context') { process_soft_tagged_furniture_ingest_job }
        return true
      end
      state = load_state(model)
      item = space_model_record(state, job[:space_id].to_s)
      space_entity = item ? space_model_entity(item['id'], model) : nil
      unless item && space_entity && space_entity.valid?
        return finish_soft_tagged_furniture_ingest_job(job, aborted: true, abort_message: '原空间或空间实例在处理期间失效')
      end

      candidate = if job[:inside_commit_tick]
                    index = job[:queue].index { |row| row[:explicit_commit] }
                    index ? job[:queue].delete_at(index) : nil
                  else
                    job[:queue].shift
                  end
      return true if !candidate && job[:queue].any?
      unless candidate
        job[:finishing] = true
        return finish_soft_tagged_furniture_ingest_job(job)
      end
      job[:active_candidate] = candidate
      soft_ingest_commit_display_intents(job)
      candidate[:ingest_phase] = :processing
      model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      action = (candidate[:action] || :new).to_sym
      label = case action
              when :update then "更新/#{candidate[:model_name]}"
              when :repair then "校对/#{candidate[:model_name]}"
              else "#{candidate[:category]}/#{candidate[:subcategory]}/#{candidate[:requested_name]}"
              end
      begin
        case action
        when :new
          entity = candidate[:entity]
          raise '待入库实例已经被删除或替换。' unless entity && entity.valid?
          unless candidate[:draft_ui]
            parsed = parse_soft_batch_ingest_instance_name(entity.respond_to?(:name) ? entity.name.to_s : '')
            unchanged = parsed && parsed[0].to_s == candidate[:category].to_s &&
                        parsed[1].to_s == candidate[:subcategory].to_s &&
                        parsed[2].to_s == candidate[:requested_name].to_s
            raise '实例名称在批处理期间已变化，请重新点击家具入库。' unless unchanged
          end
          result = ingest_tagged_furniture_entity_into_library!(
            entity,
            category: candidate[:category], subcategory: candidate[:subcategory],
            requested_name: candidate[:requested_name], model: model,
            ingest_state: state, shared_index: job[:index], batch_mode: true,
            # 新模型保持真模到六面代理真正生成完成，避免短暂显示旧白盒。
            force_proxy: false,
            target_instances: (job[:selected_mode] ? Array(candidate[:marked_entities]) : nil),
            expected_axis_mm: candidate[:captured_axis_mm]
          )
          job[:success] += 1
          job[:adopted] += result[:adopted_count].to_i
          job[:new_models] << { id: result[:model_id].to_s, name: result[:model_name].to_s, target: result[:target].to_s }
          unless result[:planar_reference]
            job[:visual_proxy_seeds] << {
              model_id: result[:model_id].to_s, model_name: result[:model_name].to_s, source_path: result[:target].to_s,
              scope_space_id: job[:space_id].to_s,
              replace_instances: Array(result[:instances]).select { |instance| instance && instance.valid? },
              source_definition: result[:source_definition]
            }
          end
          job[:issues] << "#{label}: 已入库，但资料 sidecar 写入异常：#{result[:metadata_error].message}" if result[:metadata_error]
        when :update
          entities = Array(candidate[:entities]).select { |entity| entity && entity.valid? }
          entities << candidate[:entity] if candidate[:entity] && candidate[:entity].valid? && !entities.include?(candidate[:entity])
          entity = entities.find { |node| soft_library_selected_representation(node) == 'full' }
          unless entity
            # 等待退出期间用户可以自由切代/真。真正写库的这一刻再把本款恢复成真模型，
            # 因而“刚提交后切到代理”不会让整个入库任务失败。
            entity = entities.first
            raise '选择的已入库家具已失效。' unless entity
            existing = {
              'id' => candidate[:model_id].to_s,
              'name' => candidate[:model_name].to_s,
              'path' => candidate[:source_path].to_s
            }
            ensure_soft_batch_ingest_entity_full!(entity, model, existing: existing, allow_processing: true)
          end
          result = update_existing_soft_library_from_entity!(
            entity,
            model_id: candidate[:model_id], source_path: candidate[:source_path], model_name: candidate[:model_name], model: model,
            expected_axis_mm: candidate[:captured_axis_mm]
          )
          job[:success] += 1
          job[:updated] += 1
          (job[:success_names] ||= []) << result[:model_name].to_s
          unless result[:planar_reference]
            repaired_instances = Array(result[:instances]).select { |node| node && node.valid? }
            repaired_instances = entities if repaired_instances.empty?
            job[:visual_proxy_seeds] << {
              model_id: result[:model_id], model_name: result[:model_name], source_path: result[:source_path],
              scope_space_id: job[:space_id].to_s,
              replace_instances: repaired_instances,
              source_definition: result[:source_definition]
            }
          end
        when :repair
          entities = Array(candidate[:entities]).select { |entity| entity && entity.valid? }
          raise '待校对代理实例已经失效。' if entities.empty?
          source_path = candidate[:source_path].to_s
          source_path = auto_relocate(source_path, model) unless source_path.empty?
          raise '已找回模型身份，但当前真模型源文件仍不存在。' if source_path.empty? || !File.file?(source_path)
          library_item = soft_library_item(candidate[:model_id].to_s, force: false) rescue nil
          library_item ||= {
            'id' => candidate[:model_id].to_s,
            'path' => FastPath.expand(source_path),
            'name' => candidate[:model_name].to_s
          }
          repaired_identity_count = 0
          entities.each do |node|
            if soft_legacy_proxy_entity?(node) || soft_instance_metadata(node)['model_id'].to_s.empty?
              repaired_identity_count += 1 if repair_legacy_soft_proxy_identity!(node, library_item, model, bump_registry: false)
            end
          end
          bump_soft_instance_registry_revision(model) if repaired_identity_count.positive?
          job[:success] += 1
          job[:repaired] += 1
          (job[:success_names] ||= []) << library_item['name'].to_s
          job[:legacy_identity_repaired] = job[:legacy_identity_repaired].to_i + repaired_identity_count
          retire_soft_save_failed_session_after_explicit_repair!(library_item['id'].to_s, model, source_updated: false)
          unless entities.any? { |node| soft_instance_planar_reference?(node) }
            job[:visual_proxy_seeds] << {
              model_id: library_item['id'].to_s, model_name: library_item['name'].to_s, source_path: FastPath.expand(source_path),
              scope_space_id: job[:space_id].to_s,
              replace_instances: entities,
              legacy_recovery: repaired_identity_count.positive?
            }
          end
        else
          raise "未知家具入库动作：#{action}"
        end
        if (candidate[:display_intents] || {}).values.uniq.length == 1
          original_members = soft_pending_ingest_candidate_entities(candidate)
          if original_members.empty? || original_members.all? { |node| candidate[:display_intents].key?(node.object_id) }
            mode = candidate[:display_intents].values.first
            Array(job[:visual_proxy_seeds]).each do |seed|
              next unless result.is_a?(Hash) && seed[:model_id].to_s == result[:model_id].to_s
              Array(seed[:replace_instances]).each { |node| job[:commit_display_intents][node.object_id] = mode if node && node.valid? }
            end
          end
        end
        candidate[:ingest_phase] = :completed
      rescue StandardError => e
        candidate[:ingest_phase] = :failed
        job[:failed_candidates] << candidate
        job[:failed] += 1
        job[:errors] << { name: label, message: e.message.to_s }
        job[:last_error] = "#{label}: #{e.message}"
        log_exception("家具入库失败：#{label}", e)
      ensure
        job[:done] += 1
        progress = 6 + ((job[:done].to_f / [job[:total].to_i, 1].max) * 82.0).round
        progress_detail = "成功 #{job[:success]} · 失败 #{job[:failed]}"
        progress_detail += " · 最近失败：#{job[:last_error].to_s[0, 140]}" if job[:failed].to_i.positive? && !job[:last_error].to_s.empty?
        update_task_center_job!(job[:task_id], progress: progress, stage: "正在批量入库 #{job[:done]}/#{job[:total]}", detail: progress_detail, status: 'running')
        show_workspace_floating_notice("家具批量入库 · #{job[:done]}/#{job[:total]} · #{label}", (job[:failed].to_i.positive? ? 'warning' : 'info'), progress: progress, persistent: true, model: model)
        Sketchup.set_status_text("家具入库 #{job[:done]} / #{job[:total]} · 成功 #{job[:success]} · 失败 #{job[:failed]} · #{label}") if Sketchup.respond_to?(:set_status_text)
        job[:active_candidate] = nil
        model.active_view.invalidate if model == Sketchup.active_model && model.respond_to?(:active_view)
      end

      if job[:queue].empty?
        job[:finishing] = true
        finish_soft_tagged_furniture_ingest_job(job)
      else
        # 给上一件 Definition 的原生保存/接管释放一个完整空闲窗口，再处理下一件。
        runtime_start_timer(0.32, false, label: 'soft:tagged_ingest_next') { process_soft_tagged_furniture_ingest_job }
      end
      true
    rescue StandardError => e
      log_exception('处理家具入库队列失败', e)
      finish_soft_tagged_furniture_ingest_job(job, aborted: true, abort_message: e.message.to_s) if job
      false
    end

    def safe_soft_library_filename(name)
      text = name.to_s.strip.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, ' ')
      text = '未命名软装模型' if text.empty?
      text[0, 80]
    end

    def soft_unique_library_model_name(requested_name, index = nil, stable_model_ids = [])
      base = safe_soft_library_filename(requested_name).sub(/#\d+\z/, '')
      records = index.is_a?(Hash) && index['models'].is_a?(Hash) ? index['models'] : {}
      excluded = Array(stable_model_ids).map(&:to_s).reject(&:empty?)
      used = records.each_with_object({}) do |(_path, record), memo|
        next unless record.is_a?(Hash)
        next if excluded.include?(record['model_id'].to_s)
        name = record['name'].to_s.strip
        memo[name.downcase] = true unless name.empty?
      end
      return base unless used[base.downcase]
      number = 1
      loop do
        candidate = safe_soft_library_filename("#{base}##{number}")
        return candidate unless used[candidate.downcase]
        number += 1
      end
    rescue StandardError
      safe_soft_library_filename(requested_name)
    end

    def unique_organized_model_path(dir, basename)
      path = File.join(dir, "#{basename}.skp")
      return path unless File.exist?(path)
      base = basename.to_s.sub(/#\d+\z/, '')
      index = 1
      loop do
        candidate = File.join(dir, "#{base}##{index}.skp")
        return candidate unless File.exist?(candidate)
        index += 1
      end
    end

    def soft_source_relative_directory(source_path, root)
      source = Pathname.new(FastPath.expand(source_path.to_s))
      library_root = Pathname.new(FastPath.expand(root.to_s))
      relative = source.relative_path_from(library_root).to_s
      return '' if relative == '..' || relative.start_with?("..#{File::SEPARATOR}") || relative.start_with?('../') || relative.start_with?('..\\')
      directory = File.dirname(relative)
      directory == '.' ? '' : directory
    rescue StandardError
      ''
    end

    def organized_destination_path(source_path, root, model_name, previous_metadata = {})
      organized_root = soft_library_organized_dir(root)
      # “整理入库”以后统一落到逻辑分类目录，不再复制原始任意子目录结构。
      # 这样未来不会继续产生“摆件-茶杯 / 摆件-茶壶”这种历史分裂文件夹。
      category = soft_library_canonical_category(previous_metadata, source_path, root, model_name)
      category = soft_library_canonical_top_category(category)
      subcategory = soft_library_canonical_subcategory(previous_metadata, source_path, root, category, model_name)
      destination_dir = File.join(organized_root, category, subcategory)
      FileUtils.mkdir_p(destination_dir)

      existing_copy = previous_metadata['organized_copy'].to_s
      basename = soft_library_storage_model_name(model_name)
      if !existing_copy.empty? && File.file?(existing_copy) &&
         normalize_soft_library_key(File.dirname(existing_copy)) == normalize_soft_library_key(destination_dir) &&
         File.basename(existing_copy, File.extname(existing_copy)).to_s == basename
        return existing_copy
      end

      candidate = File.join(destination_dir, "#{basename}.skp")
      if File.file?(candidate)
        sidecar = read_soft_model_sidecar(candidate)
        same_source = normalize_soft_library_key(sidecar['source_original'].to_s) == normalize_soft_library_key(source_path)
        same_model = !previous_metadata['model_id'].to_s.empty? &&
                     sidecar['model_id'].to_s == previous_metadata['model_id'].to_s
        return candidate if same_source || same_model
        return unique_organized_model_path(destination_dir, basename)
      end
      candidate
    end

    def soft_selected_proxy_entity(model = Sketchup.active_model)
      _state, _item, space_entity = current_local_editing_space(nil, model, required: true)
      selected = model.selection.to_a.select do |entity|
        entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
      end
      raise '请在 SketchUp 中只选择一个组件或群组作为代理。' unless selected.length == 1
      entity = selected.first
      raise '不能把空间最外层组件定义为家具代理。' if entity == space_entity
      unless entity_inside_definition_tree?(entity, space_entity.definition)
        raise '所选代理模型不属于当前正在修改的空间。'
      end
      entity
    end

    def definition_contains_soft_model_id?(definition, model_id, trail = {})
      return false unless definition && definition.valid?
      target = model_id.to_s
      return false if target.empty?
      oid = definition.object_id
      return false if trail[oid]
      next_trail = trail.merge(oid => true)
      own = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
      return true if own == target
      definition.entities.any? do |entity|
        entity_id = entity.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s rescue ''
        next true if entity_id == target
        next false unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        definition_contains_soft_model_id?(entity.definition, target, next_trail)
      end
    rescue StandardError
      false
    end

    def soft_proxy_selection_name(entity)
      name = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
      name = entity.definition.name.to_s.strip if name.empty? && entity.respond_to?(:definition) && entity.definition
      name.empty? ? '选中代理模型' : name
    rescue StandardError
      '选中代理模型'
    end

    # 新版定义代理：属性面板对应的库模型是真模型，SketchUp 当前选择的一个
    # 组件/群组直接保存成它的代理 SKP。代理文件位于模型库内部管理目录，
    # 不参与模型卡片扫描，也不会修改或删除用户当前选中的组件。
    def define_soft_model_proxy_from_selection(real_model_id)
      model = Sketchup.active_model
      real_item = soft_library_item(real_model_id, force: false)
      raise '请先打开需要设置代理的真模型属性。' unless real_item && File.file?(real_item['path'])
      selected = soft_selected_proxy_entity(model)
      selected_info = soft_instance_metadata(selected)
      if (!selected_info['model_id'].to_s.empty? && selected_info['model_id'].to_s == real_item['id'].to_s) ||
         definition_contains_soft_model_id?(selected.definition, real_item['id'].to_s)
        raise '所选组件包含当前真模型，不能作为它自己的代理。请选择独立的轻量组件。'
      end

      root = soft_library_root
      ensure_soft_library_structure!(root)
      proxy_name = soft_proxy_selection_name(selected)
      basename = safe_soft_library_filename(real_item['name'].to_s.empty? ? File.basename(real_item['path'], '.skp') : real_item['name'])
      target = File.join(soft_library_proxy_dir(root), "#{real_item['id']}_#{basename}_代理.skp")
      wrapper = nil
      wrapper_cleanup_scheduled = false
      model.start_operation("定义软装代理 #{real_item['name']}", true)
      wrapper = build_soft_library_update_definition!(selected, real_item, model, normalize_axes: false)
      proxy_baseline = File.file?(target) ? stable_full_file_snapshot_signature(target) : ''
      raise '无法稳定读取现有自定义代理版本，已取消覆盖。' if File.file?(target) && proxy_baseline.empty?
      result = write_soft_library_definition_atomic!(wrapper, target, root, expected_signature: proxy_baseline)
      remove_unused_definition!(wrapper, model)
      wrapper = nil
      model.commit_operation

      index = read_soft_library_index(root)
      key = normalize_soft_library_key(real_item['path'])
      metadata = default_soft_model_metadata(real_item['path'])
      metadata.merge!(index['models'][key]) if index['models'][key].is_a?(Hash)
      metadata['proxy_model_id'] = selected_info['model_id'].to_s.empty? ? "selection-#{Digest::SHA1.hexdigest(target)[0, 12]}" : selected_info['model_id'].to_s
      metadata['proxy_path'] = FastPath.expand(target)
      metadata['proxy_relative_path'] = begin
        Pathname.new(metadata['proxy_path']).relative_path_from(Pathname.new(root)).to_s.tr('\\', '/')
      rescue StandardError
        ''
      end
      metadata['proxy_name'] = proxy_name
      metadata['proxy_updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      metadata['updated_at'] = metadata['proxy_updated_at']
      index['models'][key] = metadata
      write_soft_library_index!(index, root)
      if metadata['organized'] || normalize_soft_library_key(real_item['path']).start_with?(normalize_soft_library_key(soft_library_organized_dir(root)))
        write_json_atomic(soft_model_sidecar_path(real_item['path']), metadata.merge('schema' => SOFT_LIBRARY_SCHEMA))
      end
      update_soft_library_cache_item!(real_item['path'], metadata)
      send_soft_model_properties(real_item['id'])
      refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
      backup_tip = result['backup'].to_s.empty? ? '' : '；旧代理已备份'
      show_status("已将 SketchUp 选中的“#{proxy_name}”定义为“#{real_item['name']}”的代理#{backup_tip}。下次切换到“代”或重新载入时生效。", 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    ensure
      remove_unused_definition!(wrapper, model) if defined?(wrapper) && wrapper && defined?(model) && model
    end

    def restore_soft_model_auto_proxy(real_model_id)
      real_item = soft_library_item(real_model_id, force: false)
      raise '找不到需要恢复代理的库模型。' unless real_item && File.file?(real_item['path'])
      root = soft_library_root
      index = read_soft_library_index(root)
      key = normalize_soft_library_key(real_item['path'])
      metadata = default_soft_model_metadata(real_item['path'])
      metadata.merge!(index['models'][key]) if index['models'][key].is_a?(Hash)
      %w[proxy_model_id proxy_path proxy_relative_path proxy_name proxy_updated_at proxy_kind proxy_source_signature proxy_render_mode].each do |field|
        metadata[field] = ''
      end
      metadata['proxy_visual_version'] = 0
      metadata['proxy_auto_generated'] = false
      metadata['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      index['models'][key] = metadata
      write_soft_library_index!(index, root)
      if metadata['organized'] || normalize_soft_library_key(real_item['path']).start_with?(normalize_soft_library_key(soft_library_organized_dir(root)))
        write_json_atomic(soft_model_sidecar_path(real_item['path']), metadata.merge('schema' => SOFT_LIBRARY_SCHEMA))
      end
      update_soft_library_cache_item!(real_item['path'], metadata)
      send_soft_model_properties(real_item['id'])
      refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
      show_status("“#{real_item['name']}”已恢复自动六视图代理；六面可视代理会在后台重建，若生成失败将保留当前模型并提示，不使用白盒兜底。", 'success')
      runtime_start_timer(0.25, false, label: 'soft:visual_proxy_rebuild_after_restore') do
        seed = { model_id: real_item['id'].to_s, model_name: real_item['name'].to_s, source_path: real_item['path'].to_s }
        start_soft_schedule_visual_proxy_upgrade(Sketchup.active_model, reason: '恢复自动代理', seeds: [seed])
      end
      true
    end

    def refresh_soft_library_model(model_id)
      item = soft_library_item(model_id, force: false)
      raise '找不到该模型文件，请刷新模型库。' unless item && File.file?(item['path'])
      invalidate_soft_model_thumbnail!(item['path'], soft_library_root, delete_file: true)
      @soft_library_cache = nil
      scan_soft_library!(force: true)
      refreshed = soft_library_item(model_id, force: false)
      if refreshed
        generated = ensure_soft_model_thumbnail(refreshed['path'])
        unless generated.to_s.empty?
          refreshed['thumbnail_path'] = generated
          refreshed['thumbnail_url'] = soft_thumbnail_url(generated)
          refreshed['thumbnail_ready'] = true
          send_soft_thumbnail_updates([{
            'id' => refreshed['id'].to_s, 'thumbnail_path' => generated.to_s,
            'thumbnail_url' => refreshed['thumbnail_url'].to_s, 'thumbnail_ready' => true,
            'thumbnail_finished' => true, 'thumbnail_error' => ''
          }])
        end
      end
      refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
      send_soft_model_properties(model_id)
      show_status('模型资料和缩略图已刷新。', 'success')
      true
    end

    def soft_selected_update_entity(model = Sketchup.active_model)
      _state, _item, space_entity = current_local_editing_space(nil, model, required: true)
      selected = model.selection.to_a.select { |entity| entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) }
      raise '请只选择一个用于更新模型库的组件或群组。' unless selected.length == 1
      entity = selected.first
      raise '不能用空间最外层组件更新模型库，请进入空间内部选择家具。' if entity == space_entity
      unless entity_inside_definition_tree?(entity, space_entity.definition)
        raise '所选模型不属于当前正在修改的空间。'
      end
      entity
    end

    # 入库/更新模型库的尺寸基准必须是“用户此刻在视口中看到的实例实际尺寸”，
    # 而不是 ComponentDefinition 的原始尺寸。这里把当前编辑上下文的父级变换也
    # 乘进去，因此 10m 原定义缩到 100mm、或外面再套缩放群组，入库后都会以
    # 最终可见尺寸作为库模型的 1:1 尺寸。
    def soft_library_actual_axis_dimensions_mm(instance, model = Sketchup.active_model, combined_transform: nil)
      raise '软装实例无效。' unless instance && instance.valid?
      transform = combined_transform || absolute_transformation_for_selected_entity(instance, model)
      values = soft_fresh_definition_bounds_values(instance.definition)
      raise '家具当前真实几何外包盒无效。' unless values && values.length == 6
      x0, y0, z0, x1, y1, z1 = values.map(&:to_f)
      origin = Geom::Point3d.new(x0, y0, z0).transform(transform)
      x_end = Geom::Point3d.new(x1, y0, z0).transform(transform)
      y_end = Geom::Point3d.new(x0, y1, z0).transform(transform)
      z_end = Geom::Point3d.new(x0, y0, z1).transform(transform)
      [origin.distance(x_end), origin.distance(y_end), origin.distance(z_end)].map { |value| value.to_f.abs * 25.4 }
    rescue StandardError => e
      log_exception('计算家具入库当前真实尺寸失败', e)
      raise
    end

    # 保存当前选中实例时移除项目平移/旋转，但把“最终实际尺寸”烘焙为库文件自身
    # 的三轴比例。这样再次从库放置时使用 identity 变换就是吸取时的真实大小。
    def soft_instance_scale_only_transformation(instance, model = Sketchup.active_model, desired_mm: nil, preserve_reflection: true)
      combined = absolute_transformation_for_selected_entity(instance, model)
      basis = soft_transform_basis_vectors(combined)
      desired_mm = soft_library_actual_axis_dimensions_mm(instance, model) unless Array(desired_mm).length == 3
      # 入库比例同样必须使用当前真实几何，禁止使用可能过期的持久化 bounds。
      extents = soft_fresh_definition_axis_extents(instance.definition)
      if extents.any? { |extent| extent.to_f.abs <= 1.0e-12 }
        raise '家具当前真实几何尺寸无效，无法安全计算入库缩放。'
      end
      scales = extents.each_with_index.map do |extent, index|
        source = extent.to_f.abs
        desired_inches = desired_mm[index].to_f.abs / 25.4
        source > 1.0e-12 ? [desired_inches / source, 1.0e-12].max : 1.0
      end
      determinant = basis[0].cross(basis[1]).dot(basis[2])
      scales[0] = -scales[0] if preserve_reflection && determinant.to_f < 0.0
      soft_exact_axes_transformation(
        Geom::Point3d.new(0, 0, 0),
        Geom::Vector3d.new(scales[0], 0, 0),
        Geom::Vector3d.new(0, scales[1], 0),
        Geom::Vector3d.new(0, 0, scales[2])
      )
    rescue StandardError => e
      log_exception('计算软装入库实际尺寸变换失败', e)
      # 旧版这里返回 identity，会把“尺寸计算失败”伪装成“无需缩放”，最后才以
      # 尺寸复核失败暴露。入库属于写库安全路径，计算失败必须直接终止并保留原模型。
      raise
    end

    # LinkHub 旧版软装入库/只改轴会建立“只有一个 payload 的坐标壳”。
    # 如果下一次更新再把这个壳整体作为 payload 保存，就会一层套一层。
    # 这里只识别 LinkHub 自己留下明确标记、且 definition 内确实只有一个实例的纯壳；
    # 用户自己创建的普通单组件容器没有这些标记，绝不会被自动展开。
    def soft_linkhub_pure_wrapper_payload(definition)
      return nil unless definition && definition.valid?
      begin
        return nil if soft_axis_alignment_proxy_definition?(definition)
      rescue StandardError
        nil
      end
      entities = definition.entities.to_a.select { |entity| entity && entity.valid? }
      return nil unless entities.length == 1
      child = entities.first
      return nil unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)

      library_wrapper = definition.get_attribute(SOFT_MODEL_DICT, 'library_update_package', 0).to_i.positive?
      axis_wrapper = definition.get_attribute(SOFT_MODEL_DICT, 'axis_rebase_strategy', '').to_s == 'definition_wrapper_exact_compensation'
      payload_marked = child.get_attribute(SOFT_MODEL_DICT, 'library_update_payload', false) ||
                       child.get_attribute(SOFT_MODEL_DICT, 'axis_rebase_payload', false)
      return nil unless library_wrapper || axis_wrapper || payload_marked
      child
    rescue StandardError
      nil
    end

    def soft_linkhub_pure_wrapper_chain_depth(definition, limit = 24)
      depth = 0
      current = definition
      while depth < limit.to_i
        child = soft_linkhub_pure_wrapper_payload(current)
        break unless child && child.valid? && child.respond_to?(:definition)
        depth += 1
        current = child.definition
      end
      depth
    rescue StandardError
      0
    end

    # 把“临时 payload 实例”直接 explode 到新库 Definition 根层，并继续展开历史遗留的
    # LinkHub 纯外壳。最终保存到 SKP 的 Definition 本身就是实际内容根，不再留一个
    # LH_软装库更新 -> payload -> LH_软装库更新 -> payload 的空白钻层结构。
    def flatten_soft_library_payload_into_root!(wrapper, payload)
      raise '软装入库临时 Definition 无效。' unless wrapper && wrapper.valid?
      raise '软装入库 payload 已失效。' unless payload && payload.valid?
      flattened = 0
      result = payload.explode
      flattened += 1 if result

      24.times do
        entities = wrapper.entities.to_a.select { |entity| entity && entity.valid? }
        break unless entities.length == 1
        child = entities.first
        break unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)
        child_definition = redundant_shell_definition_for(child)
        # v0.13.7.3：朝向相机组件绝不展开，否则会丢掉朝向属性。
        break if child_definition && (child_definition.behavior.always_face_camera? rescue false)
        break unless child_definition && soft_linkhub_pure_wrapper_payload(child_definition)
        exploded = child.explode
        break unless exploded
        flattened += 1
      end

      # LinkHub 旧壳拆完后，再按 v0.13.6.92 的“LinkHub 运输壳 + 无语义单子节点壳”规则继续折叠。
      # 仍然只在新建的临时库 Definition 根层操作，不递归改写用户共享子 Definition。
      flattened += collapse_redundant_empty_shell_chain!(wrapper, Sketchup.active_model, limit: 32)

      # 新版已烘焙为平根；保留补偿矩阵，但清掉“这是一个可继续展开的旧 wrapper”标记。
      wrapper.delete_attribute(SOFT_MODEL_DICT, 'library_update_package') rescue nil
      wrapper.delete_attribute(SOFT_MODEL_DICT, 'axis_rebase_strategy') rescue nil
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_update_flattened_schema', 1)
      flattened
    end

    # 对已经留在项目中的历史软装 wrapper，在进入真模型编辑之前先建立一个几何完全相同
    # 的扁平 Definition，并原位替换实例 Definition。实例 transformation 不变，所以世界
    # 几何不动；随后再执行原有最外层 make_unique，避免用户必须钻很多层空组件。
    def flatten_soft_instance_legacy_wrappers!(instance, model = Sketchup.active_model)
      return { changed: false, depth: 0, definition: (instance.definition rescue nil) } unless instance && instance.valid? && instance.respond_to?(:definition)
      source_definition = instance.definition
      source_name = begin
                      source_definition && source_definition.valid? && source_definition.respond_to?(:name) ? source_definition.name.to_s : ''
                    rescue StandardError
                      ''
                    end
      source_name = '软装家具' if source_name.empty?
      depth = soft_linkhub_pure_wrapper_chain_depth(source_definition)
      return { changed: false, depth: 0, definition: source_definition } if depth <= 0

      flat = model.definitions.add(model.definitions.unique_name("#{source_name}_扁平"))
      copy_soft_definition_attribute_dictionaries!(source_definition, flat)
      flat.description = source_definition.description.to_s if flat.respond_to?(:description=) && source_definition.respond_to?(:description)
      seed = flat.entities.add_instance(source_definition, identity_transformation)
      seed.explode
      24.times do
        entities = flat.entities.to_a.select { |entity| entity && entity.valid? }
        break unless entities.length == 1
        child = entities.first
        break unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)
        child_definition = redundant_shell_definition_for(child)
        break unless child_definition && soft_linkhub_pure_wrapper_payload(child_definition)
        break unless child.explode
      end
      flat.delete_attribute(SOFT_MODEL_DICT, 'library_update_package') rescue nil
      flat.delete_attribute(SOFT_MODEL_DICT, 'axis_rebase_strategy') rescue nil
      soft_set_attribute_if_changed(flat, SOFT_MODEL_DICT, 'library_update_flattened_schema', 1)
      flat.set_attribute(SOFT_MODEL_DICT, 'library_payload_transform_schema', 1)
      flat.set_attribute(SOFT_MODEL_DICT, 'library_payload_transform_json', JSON.generate(identity_transformation.to_a.map(&:to_f)))

      # v0.13.6.181：进入编辑前的“历史壳压平”也必须先证明尺寸完全不变。
      # 某些非等比缩放 + 旋转的旧壳在 explode 后会改变 X/Y 外包尺寸；这种情况
      # 宁可保留一层历史壳，也不能为了少钻一层而改变家具几何。
      source_mm = soft_fresh_definition_axis_extents(source_definition).map { |value| value.to_f.abs * 25.4 }
      flat_mm = soft_fresh_definition_axis_extents(flat).map { |value| value.to_f.abs * 25.4 }
      flatten_invalid = source_mm.each_with_index.any? do |value, index|
        tolerance = [0.5, value.to_f.abs * 0.002].max
        (value.to_f.abs - flat_mm[index].to_f.abs).abs > tolerance
      end
      if flatten_invalid
        remove_unused_definition!(flat, model) if flat && flat.valid? && flat.instances.empty? rescue nil
        log("跳过会改变尺寸的历史软装空壳压平：#{source_name} / 原 #{source_mm.map { |v| v.round(2) }.join(' × ')}mm / 压平 #{flat_mm.map { |v| v.round(2) }.join(' × ')}mm")
        return { changed: false, depth: depth, definition: source_definition, skipped_for_dimensions: true }
      end

      old_definition = instance.definition
      instance.definition = flat
      soft_clear_definition_bounds_cache!(flat)
      remove_unused_definition!(old_definition, model) if old_definition && old_definition.valid? && old_definition.instances.empty?
      log("已自动压平历史软装空壳：#{source_name} / #{depth} 层")
      { changed: true, depth: depth, definition: flat }
    rescue StandardError => e
      log_exception('压平历史软装空壳失败', e)
      { changed: false, depth: 0, definition: (instance.definition rescue nil) }
    end

    def build_soft_library_update_definition!(entity, library_item, model = Sketchup.active_model, normalize_axes: true, preserve_instance_reflection: true, expected_axis_mm: nil)
      expected_mm = Array(expected_axis_mm).map(&:to_f)
      expected_mm = soft_library_actual_axis_dimensions_mm(entity, model) unless expected_mm.length == 3 && expected_mm.all? { |value| value.finite? && value > 1.0e-6 }
      wrapper = model.definitions.add(model.definitions.unique_name("LH_软装库更新_#{library_item['name']}"))
      wrapper.set_attribute(SOFT_MODEL_DICT, 'library_update_package', 1)
      payload = wrapper.entities.add_instance(
        entity.definition,
        soft_instance_scale_only_transformation(
          entity, model,
          desired_mm: expected_mm,
          preserve_reflection: preserve_instance_reflection
        )
      )
      copy_instance_visual_properties!(entity, payload, copy_layer: false, copy_name: false)
      payload.set_attribute(SOFT_MODEL_DICT, 'library_update_payload', true)

      # 写文件前先复核一次。若原定义 10m、当前实例 100mm，这里要求 wrapper
      # 自身的有效几何外包尺寸就是约 100mm，而不是把缩放留给项目实例。
      soft_clear_definition_bounds_cache!(wrapper)
      actual_mm = soft_fresh_definition_axis_extents(wrapper).map { |value| value.to_f.abs * 25.4 }
      errors = expected_mm.each_with_index.map { |value, index| (value.to_f.abs - actual_mm[index].to_f.abs).abs }
      invalid = errors.each_with_index.any? do |error, index|
        tolerance = [0.5, expected_mm[index].to_f.abs * 0.002].max
        error > tolerance
      end
      if invalid
        raise "入库尺寸复核失败：目标 #{expected_mm.map { |v| v.round(2) }.join(' × ')}mm，实际 #{actual_mm.map { |v| v.round(2) }.join(' × ')}mm。"
      end
      # 尺寸确认以后再按源实例的世界朝向归正 wrapper：三个局部轴中与世界 Z
      # 夹角最小者成为库模型的新 Z，且强制朝上。这里只改本机临时定义，随后随
      # 原有一次写库事务落盘，不增加任何额外 NAS 读写或代理重建。
      alignment = if normalize_axes
                    normalize_soft_library_wrapper_axes!(wrapper, entity, model)
                  else
                    { changed: false, vote: { axis: 2, sign: 1, score: 1.0 } }
                  end
      # alignment 之后 payload.transformation 就是“旧项目 Definition -> 新库根 Definition”
      # 的精确补偿矩阵。v0.13.6.180 直接在唯一候选上 explode；当历史嵌套中含有
      # 非等比缩放 + 旋转时，SketchUp 的展开可能改变外包盒，于是整次写库被安全闸门
      # 拦住。v0.13.6.181 改为“旁路扁平候选”：先保留一份尺寸正确的原 wrapper，
      # 只在副本上尝试压平；压平后尺寸不一致就自动退回未压平但几何正确的候选。
      payload_transform_for_compensation = payload.transformation
      dimension_invalid = lambda do |reference, measured|
        reference.each_with_index.any? do |value, index|
          error = (value.to_f.abs - measured[index].to_f.abs).abs
          tolerance = [0.5, value.to_f.abs * 0.002].max
          error > tolerance
        end
      end

      soft_clear_definition_bounds_cache!(wrapper)
      aligned_mm = soft_fresh_definition_axis_extents(wrapper).map { |value| value.to_f.abs * 25.4 }
      if dimension_invalid.call(expected_mm, aligned_mm)
        raise "入库归轴后尺寸复核失败：目标 #{expected_mm.map { |v| v.round(2) }.join(' × ')}mm，实际 #{aligned_mm.map { |v| v.round(2) }.join(' × ')}mm。已停止写库。"
      end

      # v0.13.7.3：朝向相机的片状组件（always_face_camera）压平会丢掉“朝向相机”属性，
      # 因此保留原组件作为子实例，不压平、不转六面代理，尺寸保持不变。
      # 只有被入库的组件“自身”朝向相机时才不压平；若它是旧版本留下的包装（子组件朝向相机），
      # 照常压平一层——子组件实例及其朝向属性会保留下来，避免每次更新多套一层包装。
      source_definition_for_behavior = entity.respond_to?(:definition) ? entity.definition : nil
      source_behavior = source_definition_for_behavior && source_definition_for_behavior.valid? ? (source_definition_for_behavior.behavior rescue nil) : nil
      face_camera_source = !!(source_behavior && source_behavior.respond_to?(:always_face_camera?) && source_behavior.always_face_camera?)
      original_wrapper = wrapper
      flat_candidate = nil
      if face_camera_source
        flattened_layers = 0
        actual_mm = aligned_mm
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'face_camera', true)
        log("朝向相机组件入库：保留原组件与朝向属性，不压平、不转代理：#{library_item['name']}")
      else
      flat_candidate = model.definitions.add(model.definitions.unique_name("LH_软装库扁平候选_#{library_item['name']}"))
      copy_soft_definition_attribute_dictionaries!(wrapper, flat_candidate)
      flat_candidate.description = wrapper.description.to_s if flat_candidate.respond_to?(:description=) && wrapper.respond_to?(:description)
      flat_payload = flat_candidate.entities.add_instance(wrapper, identity_transformation)
      raise '未能建立家具扁平候选。' unless flat_payload && flat_payload.valid?
      flat_payload.set_attribute(SOFT_MODEL_DICT, 'library_update_payload', true)
      flattened_layers = flatten_soft_library_payload_into_root!(flat_candidate, flat_payload)
      soft_clear_definition_bounds_cache!(flat_candidate)
      flat_mm = soft_fresh_definition_axis_extents(flat_candidate).map { |value| value.to_f.abs * 25.4 }

      if dimension_invalid.call(expected_mm, flat_mm)
        # 保留原 wrapper：它已经通过入库尺寸 + 归轴复核，虽然多一层安全容器，
        # 但不会改变用户模型。下一次更新仍可继续尝试压平，不需要用户手工拆组件。
        remove_unused_definition!(flat_candidate, model) if flat_candidate && flat_candidate.valid? && flat_candidate.instances.empty? rescue nil
        flattened_layers = 0
        actual_mm = aligned_mm
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_flatten_skipped_schema', 1)
        soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_flatten_skipped_reason', "尺寸保护：#{flat_mm.map { |v| v.round(2) }.join(' × ')}mm")
        log("家具入库压平会改变尺寸，已自动保留安全壳：#{library_item['name']} / 目标 #{expected_mm.map { |v| v.round(2) }.join(' × ')}mm / 压平 #{flat_mm.map { |v| v.round(2) }.join(' × ')}mm")
      else
        # 压平候选完全一致才采用它，并释放原临时 wrapper。
        actual_mm = flat_mm
        wrapper = flat_candidate
        payload = nil
        remove_unused_definition!(original_wrapper, model) if original_wrapper && original_wrapper.valid? && original_wrapper.instances.empty? rescue nil
      end
      end
      face_camera_result = face_camera_source || soft_definition_face_camera?(wrapper)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'face_camera', true) if face_camera_result
      planar_reference = mark_soft_planar_reference!(wrapper, face_camera_result ? true : nil)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_payload_transform_schema', 1)
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_payload_transform_json', JSON.generate(payload_transform_for_compensation.to_a.map(&:to_f)))
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_actual_axis_mm', JSON.generate(actual_mm.map { |v| v.round(4) }))
      soft_set_attribute_if_changed(wrapper, SOFT_MODEL_DICT, 'library_flattened_layers', flattened_layers.to_i)
      alignment_note = if planar_reference
                         ' / 平面指代模型（原组件直接作为代理）'
                       elsif !normalize_axes
                         ' / 保留现有库轴'
                       elsif alignment[:changed]
                         " / 原#{%w[X Y Z][alignment[:vote][:axis].to_i]}轴→Z"
                       else
                         ' / Z轴已正确'
                       end
      log("软装入库尺寸确认：#{library_item['name']} / #{actual_mm.map { |v| v.round(2) }.join(' × ')}mm#{alignment_note}")
      wrapper
    end

    def soft_library_update_backup_path(target, root = soft_library_root)
      relative = begin
        Pathname.new(target).relative_path_from(Pathname.new(root)).to_s
      rescue StandardError
        File.basename(target)
      end
      folder = File.join(soft_library_manager_dir(root), '模型更新备份', File.dirname(relative))
      FileUtils.mkdir_p(folder)
      basename = File.basename(target, File.extname(target))
      File.join(folder, "#{basename}_#{Time.now.strftime('%Y%m%d_%H%M%S')}_#{SecureRandom.hex(2)}.skp")
    end

    def rollback_soft_library_definition_write!(result)
      return false unless result.is_a?(Hash)
      target = result['path'].to_s
      backup = result['backup'].to_s
      expected_content = result['written_content_signature'].to_s
      return false if target.empty?
      displaced = nil
      if File.file?(target)
        current_content = full_file_content_signature(target)
        unless expected_content.empty? || current_content == expected_content
          log("跳过模型库事务回滚：正式文件已不是本次写入版本，避免覆盖第三方更新：#{target}")
          return false
        end
        displaced = "#{target}.soft-rollback-displaced-#{Process.pid}-#{SecureRandom.hex(3)}"
        linkhub_mv(target, displaced)
        moved_content = full_file_content_signature(displaced)
        unless expected_content.empty? || moved_content == expected_content
          promote_file_create_only!(displaced, target) unless File.exist?(target)
          return false
        end
      end
      if !backup.empty? && File.file?(backup)
        promote_file_create_only!(backup, target) unless File.exist?(target)
      end
      File.delete(displaced) if displaced && File.file?(displaced)
      invalidate_soft_library_file_signature!(target)
      log("模型库事务已安全回滚：#{target}")
      true
    rescue StandardError => e
      begin
        promote_file_create_only!(displaced, target) if defined?(displaced) && displaced && File.file?(displaced) && !File.exist?(target)
      rescue StandardError
        nil
      end
      log_exception('回滚模型库更新失败', e)
      false
    end

    def write_soft_library_definition_atomic!(definition, target, root = soft_library_root, expected_signature: '')
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再写入模型库。' if publish_critical_section? || publish_post_quiet?
      target = FastPath.expand(target.to_s)
      raise '模型库目标路径无效。' unless File.extname(target).casecmp('.skp').zero?
      FileUtils.mkdir_p(File.dirname(target))
      if expected_signature.to_s.empty? && File.file?(target)
        raise '模型库目标文件已经存在，但本次没有可验证的编辑基线；已停止写入以避免覆盖其他协作者版本。请刷新模型库后重试。'
      end
      expected_fast_signature = full_snapshot_fast_signature(expected_signature)
      token = "#{Process.pid}-#{SecureRandom.hex(4)}"
      local_candidate = File.join(TEMP_WORK_DIR, "SU_LinkHub-soft-library-#{token}.skp")
      remote_stage = File.join(File.dirname(target), ".#{File.basename(target)}.soft-update-#{token}.skp")
      backup = nil
      final_replace_completed = false
      candidate_content_signature = ''
      local_started = monotonic_time
      # save_as 会把当前 Definition 绑定到候选路径，并触发额外的原生状态重建。
      # SU 2023+ 优先使用不会改变定义关联的 save_copy；支持 save_copy 时不再失败后
      # 回退 save_as，避免同一个复杂 Definition 连续进入两条原生保存路径。
      save_method = definition.respond_to?(:save_copy) ? :save_copy : :save_as
      log("模型库候选本机序列化开始：#{File.basename(target)} / #{save_method}")
      saved = definition.respond_to?(save_method) ? definition.public_send(save_method, local_candidate) : false
      log("模型库候选原生序列化返回：#{File.basename(target)} / #{save_method} / result=#{saved ? 'true' : 'false'}")
      raise 'SketchUp 未能写出本机模型库候选。' unless saved || File.file?(local_candidate)
      raise '本机模型库候选文件为空。' unless File.file?(local_candidate) && File.size(local_candidate).positive?
      candidate_size = File.size(local_candidate)
      candidate_content_signature = full_file_content_signature(local_candidate)
      raise '本机模型库候选无法生成内容指纹，已取消正式写入。' if candidate_content_signature.empty?
      log("模型库候选本机序列化：#{File.basename(target)} / #{candidate_size} bytes / #{elapsed_ms(local_started)}ms")

      # 候选生成阶段只做 mtime+size 快速并发探测。真正替换之前会把旧 target 移到
      # backup 并对 backup 做完整 SHA-256，与 expected_signature 精确比较；因此这里无需
      # 为同一个 NAS SKP 再完整读取一次。
      if File.file?(target) && !expected_signature.to_s.empty?
        current_fast = fast_file_signature(target)
        unless !expected_fast_signature.empty? && current_fast == expected_fast_signature
          raise '模型库源文件在候选生成期间已被其他人更新；本次未覆盖对方版本，请重新载入真模型后再更新。'
        end
      end

      transfer_started = monotonic_time
      file_operation_with_retry { linkhub_copy_file(local_candidate, remote_stage) }
      unless File.file?(remote_stage) && File.size(remote_stage).to_i == candidate_size && File.size(remote_stage).positive?
        raise '模型库候选传输失败，正式文件未被改动。'
      end
      # 传输完整性只校验一次 remote_stage；后续 create-only 提升会复用这个已验证指纹，
      # 不再把 stage 再从 NAS 完整读一遍。
      remote_content_signature = full_file_content_signature(remote_stage)
      unless !remote_content_signature.empty? && remote_content_signature == candidate_content_signature
        raise '模型库候选传输后的内容指纹与本机候选不一致，正式文件未被改动。'
      end
      log("模型库候选传输：#{File.basename(target)} / #{candidate_size} bytes / #{elapsed_ms(transfer_started)}ms")

      if File.file?(target) && !expected_signature.to_s.empty?
        current_fast = fast_file_signature(target)
        unless !expected_fast_signature.empty? && current_fast == expected_fast_signature
          raise '模型库源文件在候选传输期间已被其他人更新；本次未覆盖对方版本，请重新载入真模型后再更新。'
        end
      end

      if File.file?(target)
        backup = soft_library_update_backup_path(target, root)
        linkhub_mv(target, backup)
        # 这是覆盖前最后一道权威校验：仍然保留完整 SHA-256，不以快速签名代替。
        if !expected_signature.to_s.empty? && stable_full_file_snapshot_signature(backup) != expected_signature.to_s
          promote_file_create_only!(backup, target) unless File.exist?(target)
          raise '模型库源文件在最终替换窗口发生变化；实际移走版本与编辑基线不一致，已停止更新。'
        end
      end
      begin
        promoted = promote_preverified_file_create_only!(remote_stage, target, candidate_content_signature)
        final_replace_completed = true
        unless File.file?(target) && File.size(target).to_i == candidate_size.to_i && File.size(target).positive?
          raise '更新后的模型文件大小验证失败。'
        end
        written_signature = promoted['fast_signature'].to_s
        written_snapshot_signature = promoted['snapshot_signature'].to_s
        # 提升函数刚完成一次稳定全 SHA；这里只做最后一个廉价 stat，捕捉验证后紧接着
        # 被第三方改写的常见情况，避免又进行两次/三次整文件读取。
        unless !written_signature.empty? && fast_file_signature(target) == written_signature
          raise '更新后的模型文件在验证结束后立即变化；未把变化后的文件当成本次写入版本。'
        end
        invalidate_soft_library_file_signature!(target)
        {
          'path' => target,
          'backup' => backup.to_s,
          'written_signature' => written_signature,
          'written_snapshot_signature' => written_snapshot_signature,
          'written_content_signature' => candidate_content_signature.to_s
        }
      rescue StandardError
        begin
          target_exists = File.file?(target)
          target_content = target_exists ? full_file_content_signature(target) : ''
          if backup && File.file?(backup)
            if !target_exists || (final_replace_completed && !candidate_content_signature.empty? && target_content == candidate_content_signature)
              remove_file_if_content_matches!(target, candidate_content_signature) if target_exists && target_content == candidate_content_signature
              promote_file_create_only!(backup, target) unless File.exist?(target)
            else
              log("跳过模型库自动恢复：正式文件已不是本次候选，疑似第三方在最终窗口更新；覆盖前备份保留在 #{backup}")
            end
          elsif final_replace_completed && target_exists && !candidate_content_signature.empty? && target_content == candidate_content_signature
            remove_file_if_content_matches!(target, candidate_content_signature)
          end
        ensure
          invalidate_soft_library_file_signature!(target)
        end
        raise
      end
    ensure
      File.delete(local_candidate) if defined?(local_candidate) && local_candidate && File.file?(local_candidate)
      File.delete(remote_stage) if defined?(remote_stage) && remote_stage && File.file?(remote_stage)
    end

    def update_soft_library_model(model_id)
      model = Sketchup.active_model
      individual_edit = soft_individual_edit_session(model)
      if individual_edit && individual_edit[:phase].to_s != 'save_failed'
        raise '当前单件家具编辑事务尚未结束；请先在退出家具时选择完成/取消，再使用“更新模型库”。'
      end
      library_item = soft_library_item(model_id, force: false)
      raise '找不到需要更新的模型库文件。' unless library_item && File.file?(library_item['path'])
      selected = soft_selected_update_entity(model)

      # 属性面板的“更新模型库”与家具入库的“更新已有模型”必须走同一事务。
      # 旧逻辑只改外部 SKP、随后删除 wrapper，却不让项目实例接管新轴定义，
      # 这是代理重建后出现压扁/躺倒的第二条入口。
      result = update_existing_soft_library_from_entity!(
        selected,
        model_id: library_item['id'].to_s,
        source_path: library_item['path'].to_s,
        model_name: library_item['name'].to_s,
        model: model
      )

      unless result[:planar_reference]
        _state, space_item, _space_entity = current_local_editing_space(nil, model, required: false)
        seed = {
          model_id: result[:model_id].to_s,
          model_name: result[:model_name].to_s,
          source_path: result[:source_path].to_s,
          scope_space_id: space_item ? space_item['id'].to_s : '',
          replace_instances: Array(result[:instances]).select { |instance| instance && instance.valid? }
        }
        defer_soft_visual_proxy_seeds_until_publish!([seed], model)
      end

      refresh_soft_designer_dialog(refresh_library: true, include_library: true, include_measurements: false)
      send_soft_model_properties(model_id)
      backup = result[:backup].to_s
      suffix = backup.empty? ? '' : "；覆盖前备份：#{backup}"
      show_status("模型库已更新；当前同款实例已无损接管新轴定义并保持真模型，六面代理将在空间发布时按新源文件重建#{suffix}。", 'success')
      true
    end

    # 同一模型的历史 source_original / organized_copy 可以形成多条别名，但旧版索引
    # 偶尔会把两个不同 stable model_id 的记录通过陈旧路径串在一起。过去这里做无条件
    # 传递闭包，会把“椅子#1 / 椅子#2”之类不同真实模型误判成一个 family，随后在同目录
    # 统一重命名时撞到同一目标。现在一旦种子记录已有稳定 model_id，传递扩展只跟随
    # 相同 model_id（或完全没有身份的旧记录）；metadata 中明确保存的两条直连路径仍保留。
    def soft_related_model_paths(source_path, metadata, index)
      source = FastPath.expand(source_path.to_s)
      paths = [source]
      data = metadata.is_a?(Hash) ? metadata : {}
      %w[organized_copy source_original].each do |field|
        value = data[field].to_s
        paths << FastPath.expand(value) unless value.empty?
      end
      records = index.is_a?(Hash) && index['models'].is_a?(Hash) ? index['models'] : {}
      source_record = records[normalize_soft_library_key(source)]
      canonical_id = data['model_id'].to_s.strip
      canonical_id = source_record['model_id'].to_s.strip if canonical_id.empty? && source_record.is_a?(Hash)

      changed = true
      while changed
        changed = false
        known = paths.map { |path| normalize_soft_library_key(path) }
        records.each do |record_path, record|
          next unless record.is_a?(Hash)
          record_id = record['model_id'].to_s.strip
          # 有稳定身份时，绝不因为陈旧 organized_copy/source_original 链接跨到另一个模型。
          next if !canonical_id.empty? && !record_id.empty? && record_id != canonical_id
          links = %w[organized_copy source_original].map { |field| record[field].to_s }.reject(&:empty?)
          record_key = normalize_soft_library_key(record_path)
          linked = links.any? { |path| known.include?(normalize_soft_library_key(path)) }
          next unless linked || known.include?(record_key)
          ([record_path] + links).each do |path|
            expanded = FastPath.expand(path.to_s)
            expanded_key = normalize_soft_library_key(expanded)
            next if paths.any? { |existing| normalize_soft_library_key(existing) == expanded_key }
            paths << expanded
            changed = true
          end
        end
      end
      paths.select { |path| File.file?(path) }.uniq { |path| normalize_soft_library_key(path) }
    rescue StandardError
      [FastPath.expand(source_path.to_s)]
    end

    def rename_soft_library_file!(source_path, model_name, root = soft_library_root)
      source = FastPath.expand(source_path.to_s)
      return source unless File.file?(source)
      target = File.join(File.dirname(source), "#{safe_soft_library_filename(model_name)}.skp")
      source_key = normalize_soft_library_key(source)
      target_key = normalize_soft_library_key(target)
      return source if source == target
      if File.exist?(target) && source_key != target_key
        raise "同目录已存在同名模型：#{target}"
      end

      old_sidecar = soft_model_sidecar_path(source)
      new_sidecar = soft_model_sidecar_path(target)
      old_thumb = soft_model_thumbnail_path(source, root)
      new_thumb = soft_model_thumbnail_path(target, root)
      old_quick = soft_model_quick_thumbnail_path(source, root)
      new_quick = soft_model_quick_thumbnail_path(target, root)
      [[old_sidecar, new_sidecar], [old_thumb, new_thumb], [old_quick, new_quick]].each do |old_path, new_path|
        next unless old_path != new_path && File.file?(old_path) && File.exist?(new_path)
        raise "目标伴随文件已存在，为避免覆盖已停止重命名：#{new_path}"
      end
      FileUtils.mkdir_p(File.dirname(target))
      moved = []

      if source_key == target_key
        # Windows 上仅修改大小写时先经过临时文件，避免网络盘拒绝直接重命名。
        temp = File.join(File.dirname(source), ".#{File.basename(source)}.rename-#{Process.pid}-#{SecureRandom.hex(3)}")
        linkhub_mv(source, temp)
        linkhub_mv(temp, target)
      else
        linkhub_mv(source, target)
      end
      moved << [source, target]
      if File.file?(old_sidecar) && old_sidecar != new_sidecar
        linkhub_mv(old_sidecar, new_sidecar)
        moved << [old_sidecar, new_sidecar]
      end
      if File.file?(old_thumb) && old_thumb != new_thumb
        FileUtils.mkdir_p(File.dirname(new_thumb))
        linkhub_mv(old_thumb, new_thumb)
        moved << [old_thumb, new_thumb]
      end
      if File.file?(old_quick) && old_quick != new_quick
        FileUtils.mkdir_p(File.dirname(new_quick))
        linkhub_mv(old_quick, new_quick)
        moved << [old_quick, new_quick]
      end
      moved.each do |old_path, new_path|
        record_soft_schedule_metadata_file_operation!({ type: :move, from: old_path, to: new_path }, root)
      end
      target
    rescue StandardError
      Array(moved).reverse_each do |old_path, new_path|
        next unless File.file?(new_path) && !File.exist?(old_path)
        begin
          FileUtils.mkdir_p(File.dirname(old_path))
          linkhub_mv(new_path, old_path)
        rescue StandardError => rollback_error
          log_exception("回滚软装模型重命名失败：#{new_path}", rollback_error)
        end
      end
      linkhub_mv(temp, source) if defined?(temp) && temp && File.file?(temp) && !File.file?(source)
      raise
    end

    def prune_empty_soft_organized_directories!(directory, root = soft_library_root)
      organized_root = FastPath.expand(soft_library_organized_dir(root))
      organized_key = normalize_soft_library_key(organized_root)
      current = FastPath.expand(directory.to_s)
      loop do
        current_key = normalize_soft_library_key(current)
        break if current_key.empty? || current_key == organized_key || !current_key.start_with?("#{organized_key}/")
        break unless Dir.exist?(current) && Dir.children(current).empty?
        Dir.rmdir(current)
        current = File.dirname(current)
      end
      true
    rescue StandardError
      false
    end

    # 把一个已入库 SKP 安全移动到明确目标路径，并同步 sidecar/缩略图文件。
    # 这里只移动文件；索引、项目实例 source_path 与稳定 model_id 由上层一次性重写。
    def move_soft_library_file_to_path!(source_path, target_path, root = soft_library_root)
      source = FastPath.expand(source_path.to_s)
      target = FastPath.expand(target_path.to_s)
      return source if normalize_soft_library_key(source) == normalize_soft_library_key(target)
      raise "找不到需要整理的模型文件：#{source}" unless File.file?(source)
      raise "目标位置已存在同名模型：#{target}" if File.exist?(target)

      pairs = [
        [source, target],
        [soft_model_sidecar_path(source), soft_model_sidecar_path(target)],
        [soft_model_thumbnail_path(source, root), soft_model_thumbnail_path(target, root)],
        [soft_model_quick_thumbnail_path(source, root), soft_model_quick_thumbnail_path(target, root)]
      ]
      conflict = pairs.find do |old_path, new_path|
        old_path != new_path && File.file?(old_path) && File.exist?(new_path)
      end
      raise "目标伴随文件已存在，为避免覆盖已停止整理：#{conflict[1]}" if conflict
      moved = []
      FileUtils.mkdir_p(File.dirname(target))
      pairs.each do |old_path, new_path|
        next unless File.file?(old_path)
        FileUtils.mkdir_p(File.dirname(new_path))
        linkhub_mv(old_path, new_path)
        moved << [old_path, new_path]
      end
      moved.each do |old_path, new_path|
        record_soft_schedule_metadata_file_operation!({ type: :move, from: old_path, to: new_path }, root)
      end
      prune_empty_soft_organized_directories!(File.dirname(source), root)
      target
    rescue StandardError
      Array(moved).reverse_each do |old_path, new_path|
        next unless File.file?(new_path) && !File.exist?(old_path)
        begin
          FileUtils.mkdir_p(File.dirname(old_path))
          linkhub_mv(new_path, old_path)
        rescue StandardError => rollback_error
          log_exception("回滚软装模型整理失败：#{new_path}", rollback_error)
        end
      end
      raise
    end

    # 同 stable model_id 已有最终库文件时，多出的尺寸副本不再继续
    # 占用可见库。文件会移入可恢复归档，项目引用则指向保留的唯一文件。
    def archive_soft_library_duplicate!(source_path, canonical_path, index, root = soft_library_root)
      source = FastPath.expand(source_path.to_s)
      canonical = FastPath.expand(canonical_path.to_s)
      return canonical if normalize_soft_library_key(source) == normalize_soft_library_key(canonical)
      raise "找不到需要归档的重复模型：#{source}" unless File.file?(source)
      archive_path = soft_library_duplicate_archive_path(source, root)
      move_soft_library_file_to_path!(source, archive_path, root)
      source_key = normalize_soft_library_key(source)
      records = index.is_a?(Hash) && index['models'].is_a?(Hash) ? index['models'] : {}
      records.delete(source_key)
      records.each_value do |record|
        next unless record.is_a?(Hash)
        %w[organized_copy source_original].each do |field|
          value = record[field].to_s
          record[field] = canonical if !value.empty? && normalize_soft_library_key(value) == source_key
        end
      end
      index['models'] = records
      canonical
    end

    # 文件路径改变后，缩略图索引的 key 也必须跟着从旧路径哈希切到新路径哈希；
    # 否则图片文件虽然已经移动，目录卡片仍会把它判断成“过期缩略图”。
    def rewrite_soft_thumbnail_meta_paths!(path_map, root = soft_library_root)
      return true if path_map.nil? || path_map.empty?
      data = read_soft_thumbnail_meta(root)
      models = data['models'].is_a?(Hash) ? data['models'] : {}
      changed = false
      path_map.each do |old_key, new_path|
        old_path = FastPath.expand(old_key.to_s)
        new_path = FastPath.expand(new_path.to_s)
        old_id = soft_model_id_for_path(old_path)
        new_id = soft_model_id_for_path(new_path)
        record = models.delete(old_id)
        next unless record.is_a?(Hash)
        record = record.dup
        record['signature'] = soft_thumbnail_source_signature(new_path) if File.file?(new_path)
        record['thumbnail'] = File.basename(soft_model_thumbnail_path(new_path, root))
        record['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        models[new_id] = record
        changed = true
      end
      data['models'] = models
      write_soft_thumbnail_meta!(data, root) if changed
      true
    rescue StandardError => e
      log_exception('重写软装缩略图路径索引失败', e)
      false
    end

    def rewrite_soft_library_index_paths!(index, path_map, root = soft_library_root)
      records = index['models'].is_a?(Hash) ? index['models'] : {}
      rewritten = {}
      records.each do |record_path, raw_record|
        record = raw_record.is_a?(Hash) ? raw_record.dup : {}
        old_path = FastPath.expand(record_path.to_s)
        old_key = normalize_soft_library_key(old_path)
        new_path = path_map[old_key] || old_path
        record['model_id'] = soft_model_id_for_path(old_path) if record['model_id'].to_s.empty?
        %w[organized_copy source_original proxy_path].each do |field|
          value = record[field].to_s
          next if value.empty?
          replacement = path_map[normalize_soft_library_key(value)]
          record[field] = replacement if replacement
        end
        unless record['proxy_path'].to_s.empty?
          record['proxy_relative_path'] = begin
            Pathname.new(record['proxy_path']).relative_path_from(Pathname.new(root)).to_s.tr('\\', '/')
          rescue StandardError
            record['proxy_relative_path'].to_s
          end
        end
        new_key = normalize_soft_library_key(new_path)
        rewritten[new_key] = (rewritten[new_key] || {}).merge(record)
      end
      index['models'] = rewritten
      index
    end

    def soft_library_live_record_for_path(path, index = nil)
      expanded = FastPath.expand(path.to_s)
      key = normalize_soft_library_key(expanded)
      record = default_soft_model_metadata(expanded)
      sidecar = read_soft_model_sidecar(expanded)
      record.merge!(sidecar) if sidecar.is_a?(Hash)
      records = index.is_a?(Hash) && index['models'].is_a?(Hash) ? index['models'] : {}
      record.merge!(records[key]) if records[key].is_a?(Hash)
      record
    rescue StandardError
      {}
    end

    def soft_library_live_model_id_for_path(path, index = nil)
      soft_library_live_record_for_path(path, index)['model_id'].to_s.strip
    rescue StandardError
      ''
    end

    # 结构修改的重命名必须同时处理两类历史脏数据：
    # 1) 同一 stable model_id 在同一目录残留了两份真实 SKP；
    # 2) 索引没有登记目标文件，但磁盘上已经存在另一个同名模型。
    # 前者安全归档重复副本，后者自动换用 #N 名称，绝不覆盖未知文件。
    def rename_soft_model_family!(source_path, model_name, metadata, index, root = soft_library_root)
      source = FastPath.expand(source_path.to_s)
      records = index.is_a?(Hash) && index['models'].is_a?(Hash) ? index['models'] : {}
      source_record = soft_library_live_record_for_path(source, index)
      canonical_id = source_record['model_id'].to_s.strip
      canonical_id = metadata['model_id'].to_s.strip if canonical_id.empty? && metadata.is_a?(Hash)

      related_paths = soft_related_model_paths(source, metadata, index)
      related_paths << source unless related_paths.any? { |path| normalize_soft_library_key(path) == normalize_soft_library_key(source) }
      # 二次保险：即使旧索引链接异常，只允许相同 stable model_id 的真实文件进入同一重命名事务。
      related_paths = related_paths.select do |path|
        path = FastPath.expand(path.to_s)
        next true if normalize_soft_library_key(path) == normalize_soft_library_key(source)
        path_id = soft_library_live_model_id_for_path(path, index)
        canonical_id.empty? || path_id.empty? || path_id == canonical_id
      end
      related_paths = related_paths.select { |path| File.file?(path) }.uniq { |path| normalize_soft_library_key(path) }
      raise '找不到需要重命名的模型文件。' if related_paths.empty?

      requested_name = safe_soft_library_filename(model_name)
      base_name = requested_name.sub(/#\d+\z/, '')
      candidate_name = requested_name
      suffix_index = begin
        match = /#(\d+)\z/.match(requested_name)
        match ? match[1].to_i + 1 : 1
      rescue StandardError
        1
      end

      # 如果目标已被“同一 stable id 的另一份历史副本”占用，把它纳入 family；
      # 如果属于别的模型/身份未知，则找下一个未占用的 #N，不再让整条提交失败。
      500.times do
        old_keys_now = related_paths.map { |path| normalize_soft_library_key(path) }
        same_identity_targets = []
        foreign_conflict = false
        related_paths.each do |old_path|
          target = File.join(File.dirname(old_path), "#{candidate_name}.skp")
          target_key = normalize_soft_library_key(target)
          next unless File.file?(target) && !old_keys_now.include?(target_key)
          target_id = soft_library_live_model_id_for_path(target, index)
          if !canonical_id.empty? && !target_id.empty? && target_id == canonical_id
            same_identity_targets << FastPath.expand(target)
          else
            foreign_conflict = true
            break
          end
        end
        if !same_identity_targets.empty?
          related_paths.concat(same_identity_targets)
          related_paths.uniq! { |path| normalize_soft_library_key(path) }
          next
        end
        break unless foreign_conflict
        candidate_name = safe_soft_library_filename("#{base_name}##{suffix_index}")
        suffix_index += 1
      end

      plan = related_paths.map do |old_path|
        target = File.join(File.dirname(old_path), "#{candidate_name}.skp")
        [FastPath.expand(old_path), FastPath.expand(target)]
      end

      # 同一目录有多份同 stable id 时，不再报“多个关联模型”。优先保留已经位于
      # 最终目标名的文件，其次保留本次 source；其它副本移入可恢复归档。
      alias_to_keeper = {}
      target_groups = plan.group_by { |_old_path, target| normalize_soft_library_key(target) }
      target_groups.each_value do |pairs|
        unique_pairs = pairs.uniq { |old_path, _target| normalize_soft_library_key(old_path) }
        next if unique_pairs.length <= 1
        ids = unique_pairs.map { |old_path, _target| soft_library_live_model_id_for_path(old_path, index) }.reject(&:empty?).uniq
        if canonical_id.empty? || ids.any? { |id| id != canonical_id }
          raise "同一目录存在多个身份不一致的关联模型，已停止自动合并：#{candidate_name}"
        end
        keeper = unique_pairs.find { |old_path, target| normalize_soft_library_key(old_path) == normalize_soft_library_key(target) } ||
                 unique_pairs.find { |old_path, _target| normalize_soft_library_key(old_path) == normalize_soft_library_key(source) } ||
                 unique_pairs.first
        keeper_path = keeper[0]
        unique_pairs.each do |old_path, _target|
          next if normalize_soft_library_key(old_path) == normalize_soft_library_key(keeper_path)
          archive_soft_library_duplicate!(old_path, keeper_path, index, root)
          alias_to_keeper[normalize_soft_library_key(old_path)] = keeper_path
        end
      end

      plan = plan.select { |old_path, _target| File.file?(old_path) }
      # 归档后重新去重；此时每个目录最多只剩一份需要处理的真实文件。
      plan = plan.uniq { |_old_path, target| normalize_soft_library_key(target) }
      current_old_keys = plan.map { |old_path, _target| normalize_soft_library_key(old_path) }
      plan.each do |old_path, target|
        old_key = normalize_soft_library_key(old_path)
        target_key = normalize_soft_library_key(target)
        next if old_key == target_key
        next unless File.exist?(target)
        next if current_old_keys.include?(target_key)
        raise "同目录已存在无法确认身份的同名模型：#{target}"
      end

      path_map = {}
      model_ids = []
      processed = []
      plan.each do |old_path, _target|
        old_key = normalize_soft_library_key(old_path)
        record = records[old_key].is_a?(Hash) ? records[old_key] : soft_library_live_record_for_path(old_path, index)
        record_id = record['model_id'].to_s.strip
        model_ids << (record_id.empty? ? soft_model_id_for_path(old_path) : record_id)
        new_path = rename_soft_library_file!(old_path, candidate_name, root)
        path_map[old_key] = new_path
        processed << [old_path, new_path]
      end
      alias_to_keeper.each do |old_key, keeper_path|
        keeper_key = normalize_soft_library_key(keeper_path)
        path_map[old_key] = path_map[keeper_key] || keeper_path
      end
      rewrite_soft_library_index_paths!(index, path_map, root)
      [path_map, model_ids.reject(&:empty?).uniq, candidate_name]
    rescue StandardError
      # 网络盘中途失败时尽可能按逆序恢复已经移动的文件、伴随资料和缩略图。
      Array(processed).reverse_each do |old_path, new_path|
        next unless File.file?(new_path)
        begin
          rename_soft_library_file!(new_path, File.basename(old_path, File.extname(old_path)), root)
        rescue StandardError => rollback_error
          log_exception("回滚软装模型重命名失败：#{new_path}", rollback_error)
        end
      end
      raise
    end

    def soft_reference_matches?(object, model_ids, path_keys)
      return false unless object && object.respond_to?(:get_attribute)
      model_id = object.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
      source_path = object.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
      model_ids.include?(model_id) || (!source_path.empty? && path_keys.include?(normalize_soft_library_key(source_path)))
    rescue StandardError
      false
    end

    def synchronize_soft_entity_names!(entities, model_ids, path_map, model_name, model, trail = {})
      entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        definition = entity.definition
        match = soft_reference_matches?(entity, model_ids, path_map.keys) || soft_reference_matches?(definition, model_ids, path_map.keys)
        if match
          current_id = entity.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
          current_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s if current_id.empty?
          current_id = model_ids.first.to_s if current_id.empty?
          current_path = entity.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
          current_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s if current_path.empty?
          new_path = path_map[normalize_soft_library_key(current_path)] || current_path
          item = { 'id' => current_id, 'path' => new_path, 'name' => model_name }
          stamp_soft_library_instance!(entity, item, model)
        end
        next unless definition && definition.valid?
        oid = definition.object_id
        next if trail[oid]
        next_trail = trail.merge(oid => true)
        synchronize_soft_entity_names!(definition.entities, model_ids, path_map, model_name, model, next_trail)
      end
      true
    rescue StandardError => e
      log_exception('同步项目软装实例名称失败', e)
      false
    end

    def synchronize_soft_model_project_references!(model_ids, path_map, model_name, model = Sketchup.active_model)
      ids = Array(model_ids).map(&:to_s).reject(&:empty?).uniq
      paths = path_map.is_a?(Hash) ? path_map : {}
      return false unless model && (!ids.empty? || !paths.empty?)
      started = monotonic_time
      path_keys = paths.keys

      # 根因优化：旧版为了找一个被改名的家具，会递归遍历 model.entities，随后又把
      # model.definitions 中每个定义的 entities 再递归一遍；大型室内模型等价于把全项目
      # 几何树扫两次。这里改为：先按定义元数据直接命中，再只查看已经登记的受管软装
      # 实例。完全不遍历普通建筑/硬装的深层几何。
      matching_definitions = []
      model.definitions.each do |definition|
        next unless definition && definition.valid?
        matching_definitions << definition if soft_reference_matches?(definition, ids, path_keys)
      rescue StandardError
        nil
      end

      candidate_instances = []
      matching_definitions.each do |definition|
        candidate_instances.concat(Array(definition.instances))
      rescue StandardError
        nil
      end

      # 兼容历史版本只把 model_id/source_path 写在实例、没写到 definition 的情况。
      # 只扫描 LinkHub 已载入空间里的“受管软装注册表”，不会进入普通组件细节。
      begin
        state = load_state(model)
        Array(state['space_models']).each do |item|
          root = space_model_entity(item['id'], model)
          next unless root && root.valid?
          soft_instances_for_space(root, model, force: false).each do |instance|
            next unless instance && instance.valid?
            if soft_reference_matches?(instance, ids, path_keys) || soft_reference_matches?(instance.definition, ids, path_keys)
              candidate_instances << instance
              matching_definitions << instance.definition if instance.definition && instance.definition.valid?
            end
          end
        end
      rescue StandardError => e
        log_exception('读取受管软装实例注册表失败', e)
      end

      # 再补一层模型根部的历史遗留受管实例；这里只看第一层，不递归。
      begin
        model.entities.each do |entity|
          next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
          if soft_reference_matches?(entity, ids, path_keys) || soft_reference_matches?(entity.definition, ids, path_keys)
            candidate_instances << entity
            matching_definitions << entity.definition if entity.definition && entity.definition.valid?
          end
        end
      rescue StandardError
        nil
      end

      matching_definitions = matching_definitions.compact.select(&:valid?).uniq
      candidate_instances = candidate_instances.compact.select(&:valid?).uniq

      with_soft_metadata_sync(model) do
        model.start_operation("同步软装名称 #{model_name}", true)
        matching_definitions.each do |definition|
          current_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
          current_id = ids.first.to_s if current_id.empty?
          current_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
          new_path = paths[normalize_soft_library_key(current_path)] || current_path
          definition.name = model_name unless model_name.to_s.empty? || definition.name.to_s == model_name.to_s
          soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_id', current_id)
          soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'source_path', new_path)
          soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_name', model_name)
        rescue StandardError
          nil
        end

        candidate_instances.each do |instance|
          definition = instance.definition
          current_id = instance.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
          current_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s if current_id.empty? && definition
          current_id = ids.first.to_s if current_id.empty?
          current_path = instance.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
          current_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s if current_path.empty? && definition
          new_path = paths[normalize_soft_library_key(current_path)] || current_path
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'model_id', current_id)
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'source_path', new_path)
          soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'model_name', model_name)
          instance.name = model_name if instance.respond_to?(:name=) && !model_name.to_s.empty? && instance.name.to_s != model_name.to_s
        rescue StandardError
          nil
        end
        model.commit_operation
      end
      log("采购清单名称定向同步：定义 #{matching_definitions.length} / 实例 #{candidate_instances.length} / #{elapsed_ms(started)}ms")
      true
    rescue StandardError => e
      model.abort_operation rescue nil
      log_exception('同步软装库、组件和清单名称失败', e)
      false
    end

    # 采购清单一次提交可能同时修改多件家具。旧版每件家具都重新遍历 definitions、
    # 所有空间受管实例并各开一次 SketchUp operation；这里把查找和写入合并为一轮。
    def synchronize_soft_model_project_references_batch!(jobs, model = Sketchup.active_model)
      return false unless model
      normalized_jobs = Array(jobs).filter_map do |job|
        next unless job.is_a?(Hash)
        ids = Array(job[:model_ids] || job['model_ids']).map(&:to_s).reject(&:empty?).uniq
        paths = job[:path_map] || job['path_map']
        paths = paths.is_a?(Hash) ? paths : {}
        name = (job[:model_name] || job['model_name']).to_s
        canonical_id = (job[:canonical_model_id] || job['canonical_model_id']).to_s.strip
        canonical_id = ids.first.to_s if canonical_id.empty?
        next if ids.empty? && paths.empty?
        { ids: ids, canonical_id: canonical_id, paths: paths, path_keys: paths.keys, name: name, definitions: [], instances: [] }
      end
      return true if normalized_jobs.empty?
      started = monotonic_time
      jobs_by_id = {}
      jobs_by_path = {}
      normalized_jobs.each do |job|
        job[:ids].each { |model_id| jobs_by_id[model_id] ||= job }
        job[:path_keys].each { |path_key| jobs_by_path[path_key] ||= job }
      end
      match_job = lambda do |object|
        next nil unless object && object.respond_to?(:get_attribute)
        model_id = object.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
        job = jobs_by_id[model_id] unless model_id.empty?
        next job if job
        source_path = object.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
        source_path.empty? ? nil : jobs_by_path[normalize_soft_library_key(source_path)]
      rescue StandardError
        nil
      end

      model.definitions.each do |definition|
        next unless definition && definition.valid?
        job = match_job.call(definition)
        if job
          job[:definitions] << definition
          # 已命中的定义可以直接给出其全部实例，不必再逐空间遍历受管软装树。
          job[:instances].concat(Array(definition.instances))
        end
      rescue StandardError
        next
      end

      unresolved_jobs = normalized_jobs.select { |job| job[:definitions].empty? && job[:instances].empty? }
      unless unresolved_jobs.empty?
        unresolved_ids = unresolved_jobs.each_with_object({}) { |job, memo| memo[job.object_id] = true }
        begin
          state = load_state(model)
          Array(state['space_models']).each do |item|
            root = space_model_entity(item['id'], model)
            next unless root && root.valid?
            soft_instances_for_space(root, model, force: false).each do |instance|
              next unless instance && instance.valid?
              job = match_job.call(instance) || match_job.call(instance.definition)
              next unless job && unresolved_ids[job.object_id]
              job[:instances] << instance
              job[:definitions] << instance.definition if instance.definition && instance.definition.valid?
            end
          end
        rescue StandardError => e
          log_exception('批量读取受管软装实例注册表失败', e)
        end
      end

      unresolved_jobs = normalized_jobs.select { |job| job[:definitions].empty? && job[:instances].empty? }
      unless unresolved_jobs.empty?
        unresolved_ids = unresolved_jobs.each_with_object({}) { |job, memo| memo[job.object_id] = true }
        begin
          model.entities.each do |entity|
            next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
            job = match_job.call(entity) || match_job.call(entity.definition)
            next unless job && unresolved_ids[job.object_id]
            job[:instances] << entity
            job[:definitions] << entity.definition if entity.definition && entity.definition.valid?
          end
        rescue StandardError
          nil
        end
      end

      normalized_jobs.each do |job|
        job[:definitions] = job[:definitions].compact.select(&:valid?).uniq
        job[:instances] = job[:instances].compact.select(&:valid?).uniq
      end
      return true unless normalized_jobs.any? { |job| !job[:definitions].empty? || !job[:instances].empty? }

      with_soft_metadata_sync(model) do
        model.start_operation('同步软装批量资料', true)
        normalized_jobs.each do |job|
          job[:definitions].each do |definition|
            current_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
            current_id = job[:canonical_id] if current_id.empty? || job[:ids].include?(current_id)
            current_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
            new_path = job[:paths][normalize_soft_library_key(current_path)] || current_path
            definition.name = job[:name] unless job[:name].empty? || definition.name.to_s == job[:name]
            soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_id', current_id)
            soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'source_path', new_path)
            soft_set_attribute_if_changed(definition, SOFT_MODEL_DICT, 'model_name', job[:name])
          rescue StandardError
            next
          end
          job[:instances].each do |instance|
            definition = instance.definition
            current_id = instance.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s
            current_id = definition.get_attribute(SOFT_MODEL_DICT, 'model_id', '').to_s if current_id.empty? && definition
            current_id = job[:canonical_id] if current_id.empty? || job[:ids].include?(current_id)
            current_path = instance.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s
            current_path = definition.get_attribute(SOFT_MODEL_DICT, 'source_path', '').to_s if current_path.empty? && definition
            new_path = job[:paths][normalize_soft_library_key(current_path)] || current_path
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'model_id', current_id)
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'source_path', new_path)
            soft_set_attribute_if_changed(instance, SOFT_MODEL_DICT, 'model_name', job[:name])
            instance.name = job[:name] if instance.respond_to?(:name=) && !job[:name].empty? && instance.name.to_s != job[:name]
          rescue StandardError
            next
          end
        end
        model.commit_operation
      end
      definition_count = normalized_jobs.sum { |job| job[:definitions].length }
      instance_count = normalized_jobs.sum { |job| job[:instances].length }
      log("采购清单批量名称同步：#{normalized_jobs.length} 组 / 定义 #{definition_count} / 实例 #{instance_count} / #{elapsed_ms(started)}ms")
      true
    rescue StandardError => e
      model.abort_operation rescue nil
      log_exception('批量同步软装库、组件和清单名称失败', e)
      false
    end

    def save_soft_model_metadata(json, organize: false, allow_path_changes: true)
      started = monotonic_time
      payload = parse_soft_metadata_payload(json)
      root = soft_library_root
      raise '请先设置软装模型库路径。' if root.empty?
      ensure_soft_library_structure!(root)

      requested_source = payload['source_path'].to_s
      batch_context = @soft_schedule_metadata_batch_context
      batch_context = nil unless batch_context.is_a?(Hash) &&
                                 batch_context[:root_key].to_s == normalize_soft_library_key(root)
      index = batch_context ? batch_context[:index] : read_soft_library_index(root)
      source_path = requested_source
      unless !source_path.to_s.empty? && File.file?(source_path)
        stable_lookup_id = payload['model_id'].to_s.strip
        unless stable_lookup_id.empty?
          matched_paths = index['models'].keys.select do |record_path|
            record = index['models'][record_path]
            record.is_a?(Hash) && record['model_id'].to_s == stable_lookup_id && File.file?(record_path.to_s)
          end
          matched_path = matched_paths.min_by do |record_path|
            [soft_library_path_inside?(record_path, soft_library_organized_dir(root)) ? 0 : 1,
             normalize_soft_library_key(record_path)]
          end
          source_path = matched_path.to_s unless matched_path.to_s.empty?
        end
      end
      source_path = FastPath.expand(source_path.to_s)
      raise '找不到模型源文件。' unless File.file?(source_path)

      old_source_key = normalize_soft_library_key(source_path)
      previous_metadata = default_soft_model_metadata(source_path)
      previous_metadata.merge!(index['models'][old_source_key]) if index['models'][old_source_key].is_a?(Hash)
      stable_id = payload['model_id'].to_s.strip
      stable_id = previous_metadata['model_id'].to_s.strip if stable_id.empty?
      stable_id = soft_model_id_for_path(source_path) if stable_id.empty?
      category_hint = payload['category'].to_s.strip
      category_hint = soft_library_canonical_category(previous_metadata, source_path, root, previous_metadata['name'].to_s) if category_hint.empty?
      category_hint = soft_library_canonical_top_category(category_hint)
      subcategory_hint = payload['subcategory'].to_s.strip
      subcategory_hint = soft_library_canonical_subcategory(previous_metadata, source_path, root, category_hint, previous_metadata['name'].to_s) if subcategory_hint.empty?
      subcategory_hint = safe_soft_library_subcategory_name(subcategory_hint, category_hint)
      requested_model_name = safe_soft_library_filename(payload['name'].to_s)
      requested_model_name = soft_library_model_name_without_category(requested_model_name, category_hint)
      requested_model_name = soft_library_model_name_without_category(requested_model_name, subcategory_hint)
      related_ids_for_name = soft_related_model_paths(source_path, previous_metadata, index).each_with_object([]) do |related_path, ids|
        record = index['models'][normalize_soft_library_key(related_path)]
        ids << record['model_id'].to_s if record.is_a?(Hash)
      end
      related_ids_for_name << stable_id
      model_name = soft_unique_library_model_name(requested_model_name, index, related_ids_for_name)
      previous_name = previous_metadata['name'].to_s.strip
      previous_name = File.basename(source_path, File.extname(source_path)) if previous_name.empty?
      filename_name = File.basename(source_path, File.extname(source_path))
      name_or_path_changed = allow_path_changes && (previous_name != model_name || filename_name != model_name)
      previous_metadata['model_id'] = stable_id
      previous_metadata['name'] = model_name
      index['models'][old_source_key] = previous_metadata

      path_map = {}
      related_model_ids = [stable_id]
      if name_or_path_changed
        path_map, renamed_ids, final_model_name = rename_soft_model_family!(source_path, model_name, previous_metadata, index, root)
        model_name = final_model_name.to_s unless final_model_name.to_s.empty?
        related_model_ids.concat(Array(renamed_ids))
        source_path = path_map[old_source_key] || source_path
      end
      related_model_ids = related_model_ids.reject(&:empty?).uniq
      source_key = normalize_soft_library_key(source_path)

      metadata = default_soft_model_metadata(source_path)
      metadata.merge!(index['models'][source_key]) if index['models'][source_key].is_a?(Hash)
      metadata['model_id'] = stable_id
      %w[name manufacturer price contact material_description remark].each { |key| metadata[key] = payload[key].to_s.strip }
      metadata['extra_fields'] = payload['extra_fields'].each_with_object({}) do |(key, value), memo|
        field = key.to_s.strip[0, 64]
        memo[field] = value.to_s.strip[0, 500] unless field.empty?
      end if payload['extra_fields'].is_a?(Hash)
      metadata['name'] = model_name
      %w[length_mm width_mm height_mm dimensions_cached loaded_from_newer].each { |key| metadata.delete(key) }
      metadata['updated_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      metadata['organized'] = source_key.start_with?(normalize_soft_library_key(soft_library_organized_dir(root)))
      canonical_category = category_hint.to_s.empty? ? soft_library_canonical_category(metadata, source_path, root, model_name) : category_hint
      canonical_category = soft_library_canonical_top_category(canonical_category)
      canonical_subcategory = safe_soft_library_subcategory_name(subcategory_hint, canonical_category)
      metadata['category'] = canonical_category
      metadata['subcategory'] = canonical_subcategory
      index['models'][source_key] = metadata
      touched_keys = { source_key => true }

      # 只更新当前模型及其关联副本，不再每次保存都重写整个库中所有 sidecar。
      index['models'].each do |record_path, record|
        next unless record.is_a?(Hash)
        record_id = record['model_id'].to_s
        record_key = normalize_soft_library_key(record_path)
        if related_model_ids.include?(record_id) || path_map.values.any? { |path| normalize_soft_library_key(path) == record_key }
          record['name'] = model_name
          %w[manufacturer price contact material_description remark].each { |field| record[field] = metadata[field].to_s }
          record['category'] = canonical_category
          record['subcategory'] = canonical_subcategory
          record['extra_fields'] = metadata['extra_fields'].is_a?(Hash) ? metadata['extra_fields'].dup : {}
          record['updated_at'] = metadata['updated_at']
          touched_keys[record_key] = true
        end
        if related_model_ids.include?(record['proxy_model_id'].to_s)
          record['proxy_name'] = model_name
          record['proxy_updated_at'] = metadata['updated_at']
          touched_keys[record_key] = true
        end
      end

      organized_path = nil
      if organize
        organized_dir = soft_library_organized_dir(root)
        FileUtils.mkdir_p(organized_dir)
        desired_path = organized_destination_path(source_path, root, model_name, metadata)
        desired_key = normalize_soft_library_key(desired_path)
        original_source_path = source_path
        previous_copy = metadata['organized_copy'].to_s
        organize_candidates = [source_path]
        organize_candidates << previous_copy if !previous_copy.empty? && File.file?(previous_copy)
        candidate_path = if metadata['organized']
                           source_path
                         elsif !previous_copy.empty? && File.file?(previous_copy)
                           previous_copy
                         else
                           source_path
                         end
        candidate_key = normalize_soft_library_key(candidate_path)

        if candidate_key == desired_key
          organized_path = candidate_path
        elsif File.file?(desired_path)
          # organized_destination_path 只会在 sidecar 确认为同一来源/同一 model_id
          # 时返回已存在的目标。这时直接复用它，不再生成尺寸副本。
          organized_path = desired_path
          path_map[candidate_key] = organized_path
        else
          movable_inside_library = soft_library_path_inside?(candidate_path, root) &&
                                   !soft_library_path_inside?(candidate_path, soft_library_manager_dir(root))
          if movable_inside_library
            relocation_map = { candidate_key => move_soft_library_file_to_path!(candidate_path, desired_path, root) }
            rewrite_soft_library_index_paths!(index, relocation_map, root)
            organized_path = relocation_map[candidate_key]
            path_map.keys.each do |old_key|
              path_map[old_key] = organized_path if normalize_soft_library_key(path_map[old_key]) == candidate_key
            end
            path_map[candidate_key] = organized_path
            touched_keys.delete(candidate_key)
          else
            # 配置根目录之外的源文件可能属于其他资产库，不越界移动；
            # 只把它纳入本软装库，可见库中仍只有这一份。
            FileUtils.mkdir_p(File.dirname(desired_path))
            FileUtils.cp(candidate_path, desired_path)
            record_soft_schedule_metadata_file_operation!({ type: :create, path: desired_path }, root)
            organized_path = desired_path
            path_map[candidate_key] = organized_path
          end
        end

        # 同一条记录历史上可能同时挂着 source_original 和 organized_copy。
        # 位于当前配置库内的多余文件全部移入可恢复归档，只留最终文件。
        organize_candidates.compact.map { |path| FastPath.expand(path.to_s) }
                           .uniq { |path| normalize_soft_library_key(path) }
                           .each do |duplicate_path|
          duplicate_key = normalize_soft_library_key(duplicate_path)
          next if duplicate_key == normalize_soft_library_key(organized_path)
          next unless File.file?(duplicate_path)
          next unless soft_library_path_inside?(duplicate_path, root)
          next if soft_library_path_inside?(duplicate_path, soft_library_manager_dir(root))
          archive_soft_library_duplicate!(duplicate_path, organized_path, index, root)
          path_map[duplicate_key] = organized_path
          touched_keys.delete(duplicate_key)
        end

        organized_path = FastPath.expand(organized_path)
        organized_key = normalize_soft_library_key(organized_path)
        source_path = organized_path
        source_key = organized_key
        existing_at_target = index['models'][organized_key].is_a?(Hash) ? index['models'][organized_key] : {}
        metadata = existing_at_target.merge(metadata)
        metadata['model_id'] = stable_id
        metadata['name'] = model_name
        metadata['organized'] = true
        metadata['organized_copy'] = organized_path
        metadata['source_original'] = soft_library_path_inside?(original_source_path, root) ? '' : original_source_path
        metadata['organized_relative_dir'] = [canonical_category, canonical_subcategory].join('/')
        metadata['category'] = canonical_category
        metadata['subcategory'] = canonical_subcategory

        existing_organized = index['models'][organized_key].is_a?(Hash) ? index['models'][organized_key] : {}
        organized_meta = existing_organized.merge(metadata).merge(
          'model_id' => stable_id,
          'name' => model_name,
          'category' => canonical_category,
          'subcategory' => canonical_subcategory,
          'organized_copy' => organized_path,
          'organized' => true,
          'organized_relative_dir' => [canonical_category, canonical_subcategory].join('/'),
          'updated_at' => Time.now.strftime('%Y-%m-%d %H:%M:%S')
        )
        index['models'][organized_key] = organized_meta
        touched_keys[organized_key] = true
      end

      if batch_context
        touched_keys.each_key { |record_key| batch_context[:touched_keys][record_key] = true }
        batch_context[:thumbnail_path_map].merge!(path_map)
        batch_context[:resolved_path_map].merge!(path_map)
        if name_or_path_changed || !path_map.empty?
          batch_context[:reference_jobs] << {
            model_ids: related_model_ids.dup,
            canonical_model_id: stable_id,
            path_map: path_map.dup,
            model_name: model_name
          }
        end
        batch_context[:catalog_dirty] ||= name_or_path_changed || organize
      else
        rewrite_soft_thumbnail_meta_paths!(path_map, root) unless path_map.empty?
        write_soft_library_index!(index, root)
        touched_keys.each_key do |record_key|
          record = index['models'][record_key]
          next unless record.is_a?(Hash)
          path = FastPath.expand(record_key.to_s)
          write_json_atomic(soft_model_sidecar_path(path), record.merge('schema' => SOFT_LIBRARY_SCHEMA)) if File.file?(path)
        end

        # 厂家、价格、联系方式、材质描述和备注只属于库资料，不需要遍历项目中全部高模定义。
        # 仅在名称或文件路径真的变化时，同步当前项目中的组件名称与引用。
        if name_or_path_changed || !path_map.empty?
          synchronize_soft_model_project_references!(related_model_ids, path_map, model_name, Sketchup.active_model)
        end
      end

      if name_or_path_changed || organize
        unless batch_context
          invalidate_soft_library_catalog_cache!(root)
          schedule_soft_library_dialog_load(force: true) if @soft_designer_dialog && @soft_designer_dialog.visible?
        end
      else
        unless batch_context
          update_soft_library_cache_item!(source_path, metadata)
          refresh_soft_designer_dialog(refresh_library: false, include_library: true, include_measurements: false)
          send_soft_model_properties(stable_id)
        end
      end
      active_model = Sketchup.active_model
      if active_model && !soft_schedule_batch_applying?
        refresh_soft_schedule_cached_metadata!(
          active_model,
          model_ids: related_model_ids,
          source_paths: path_map.keys + path_map.values + [source_path]
        )
        bump_soft_measurement_display_revision(active_model)
        refresh_soft_schedule_dialog(active_model, force: true) if @soft_schedule_dialog && @soft_schedule_dialog.visible?
      end
      log("保存软装模型资料：#{model_name} / #{elapsed_ms(started)}ms / 重命名=#{name_or_path_changed} / 整理=#{organize}")
      unless soft_schedule_batch_applying?
        if organize
          show_status("模型已统一命名并整理到：#{organized_path}", 'success')
        elsif name_or_path_changed
          show_status("模型名称、库文件、组件定义、实例和项目清单已同步为“#{model_name}”。", 'success')
        else
          show_status("“#{model_name}”的属性资料已保存。", 'success')
        end
      end
      true
    end

    # v0.13.6.170：室内空间管理器独立模块。
    Kernel.load(File.expand_path('space_manager.rb', __dir__))
    # v0.13.6.190：联动空间调整入口加固 + 内置只读诊断。
    Kernel.load(File.expand_path('linked_space_tools.rb', __dir__))
    Kernel.load(File.expand_path('diagnostic_center.rb', __dir__))
    Kernel.load(File.expand_path('readonly_diagnostic.rb', __dir__))

    # -------------------------
    def toggle_link_highlight(key, model = Sketchup.active_model)
      discipline = key.to_s
      raise '未知专业。' unless DISCIPLINES.key?(discipline)
      instance = managed_model_instance_for(discipline, model)
      raise "#{DISCIPLINES[discipline]['name']}尚未载入。" unless instance && instance.valid?
      selection = model.selection
      selected = selection.to_a
      currently_selected = selected.length == 1 && selected.first == instance
      selection.clear
      unless currently_selected
        selection.add(instance)
        show_status("已用 SketchUp 原生选择高亮#{DISCIPLINES[discipline]['name']}参考模型。", 'success')
      else
        show_status("已取消#{DISCIPLINES[discipline]['name']}高亮。", 'success')
      end
      model.active_view.invalidate if model.respond_to?(:active_view)
      refresh_dialog
      true
    rescue StandardError => e
      log_exception('高亮参考模型失败', e)
      show_status(e.message.to_s, 'error')
      false
    end

    def model_directory(model = Sketchup.active_model)
      path = model.path.to_s
      path.empty? ? nil : File.dirname(path)
    end

    def store_path(path, model = Sketchup.active_model)
      return '' if path.nil? || path.to_s.empty?
      absolute = FastPath.expand(path.to_s)
      base = model_directory(model)
      return absolute unless base

      begin
        relative = Pathname.new(absolute).relative_path_from(Pathname.new(base)).to_s
        relative.start_with?('..') ? absolute : "./#{relative.tr('\\', '/')}"
      rescue StandardError
        absolute
      end
    end

    def resolve_path(stored_path, model = Sketchup.active_model)
      text = stored_path.to_s
      return '' if text.empty?
      if text.start_with?('./', '../')
        base = model_directory(model)
        return FastPath.expand(text, base) if base
      end
      FastPath.expand(text)
    rescue StandardError
      text
    end

    def auto_relocate(stored_path, model = Sketchup.active_model)
      current = resolve_path(stored_path, model)
      return current if File.file?(current)
      base = model_directory(model)
      return current unless base

      filename = File.basename(current)
      candidates = Dir.glob(File.join(base, '**', filename), File::FNM_CASEFOLD)
      candidates.first || current
    rescue StandardError
      current
    end

    def absolute_file_path?(path)
      text = path.to_s
      text.start_with?('/', '\\') || text.match?(/\A[A-Za-z]:[\\\/]/)
    end

    def resolve_path_from_source(stored_path, source_model_path)
      text = stored_path.to_s
      return '' if text.empty?
      return FastPath.expand(text) if absolute_file_path?(text)
      FastPath.expand(text, File.dirname(source_model_path))
    rescue StandardError
      text
    end

    def legacy_manifest_path_for(model_path)
      legacy_metadata_path(model_path, MANIFEST_SUFFIX)
    end

    def manifest_path_for(model_path)
      filename = "#{File.basename(model_path.to_s)}#{MANIFEST_SUFFIX}"
      metadata_file_path(model_path, 'manifests', filename)
    end

    def tag_visibility_snapshot(model = Sketchup.active_model)
      return {} unless model && model.respond_to?(:layers)
      model.layers.to_a.each_with_object({}) do |tag, memo|
        next unless tag
        name = tag.respond_to?(:name) ? tag.name.to_s : ''
        next if name.empty?
        memo[name] = tag.respond_to?(:visible?) ? !!tag.visible? : true
      rescue StandardError
        next
      end
    rescue StandardError
      {}
    end

    def write_sidecar_manifest(state, model = Sketchup.active_model)
      model_path = model.path.to_s
      return false if model_path.empty?

      payload = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'project_name' => state['project_name'],
        'source_model' => File.basename(model_path),
        'host_discipline' => state['host_discipline'].to_s,
        'collab_project_dir' => state['collab_project_dir'].to_s,
        'collab_project_json' => state['collab_project_json'].to_s,
        'tag_visibility' => tag_visibility_snapshot(model),
        'links' => {}
      }
      DISCIPLINES.keys.each do |key|
        link = state['links'][key] || default_link(key)
        payload['links'][key] = {
          'model_path' => link['model_path'].to_s,
          'sync_mode' => link['sync_strategy'].to_s
        }
      end

      target = manifest_path_for(model_path)
      ensure_metadata_target!(target)
      content = JSON.pretty_generate(payload)
      return true if File.file?(target) && File.read(target, mode: 'rb') == content

      File.write(target, content, mode: 'wb')
      retire_legacy_metadata_file(legacy_manifest_path_for(model_path), target)
      true
    rescue StandardError => e
      puts("SU LinkHub 关联清单写入失败：#{e.message}")
      false
    end

    def dependency_record(discipline, kind, stored_source, source_model_path, origin = 'embedded')
      resolved = resolve_path_from_source(stored_source, source_model_path)
      {
        'discipline' => discipline.to_s,
        'kind' => kind.to_s,
        'source' => stored_source.to_s,
        'resolved_path' => resolved,
        'exists' => File.file?(resolved),
        'origin' => origin,
        'source_model_path' => source_model_path
      }
    end

    def read_sidecar_dependencies(source_model_path)
      target = manifest_path_for(source_model_path)
      target = metadata_read_path(target, legacy_manifest_path_for(source_model_path))
      return [] unless File.file?(target)

      saved = JSON.parse(File.read(target, mode: 'rb'))
      links = saved['links'].is_a?(Hash) ? saved['links'] : {}
      source_owner = saved['host_discipline'].to_s
      dependencies = []
      links.each do |key, item|
        next unless DISCIPLINES.key?(key)
        next unless item.is_a?(Hash)
        model_source = item['model_path'].to_s
        unless model_source.empty?
          item = dependency_record(key, 'model', model_source, source_model_path, 'manifest')
          item['source_owner_discipline'] = source_owner
          dependencies << item
        end
      end
      dependencies
    rescue StandardError => e
      puts("SU LinkHub 关联清单读取失败：#{e.message}")
      []
    end

    def deduplicate_dependencies(dependencies)
      seen = {}
      Array(dependencies).each_with_object([]) do |item, output|
        next unless item.is_a?(Hash)
        kind = item['kind'].to_s
        discipline = item['discipline'].to_s
        resolved = item['resolved_path'].to_s
        key = [discipline, kind, FastPath.expand(resolved).downcase]
        next if seen[key]
        seen[key] = true
        item['kind'] = kind
        output << item
      rescue StandardError
        next
      end
    end

    # -------------------------
    # Tag folders and managed entities
    # -------------------------

    def ensure_tag(name, model = Sketchup.active_model)
      model.layers[name] || model.layers.add(name)
    end

    def tag_folders_supported?(model = Sketchup.active_model)
      # SketchUp 2021+ 官方支持标记文件夹。界面只按版本判断，
      # 不在面板刷新阶段调用 C API 探测，避免某些 Windows 环境不稳定。
      Sketchup.version.to_i >= 21
    rescue StandardError
      false
    end

    def find_tag_folder(name, model = Sketchup.active_model)
      return nil unless Sketchup.version.to_i >= 21
      model.layers.folders.find { |folder| folder.name.to_s == name.to_s }
    rescue StandardError
      nil
    end

    def ensure_tag_folder(name, model = Sketchup.active_model)
      return nil unless Sketchup.version.to_i >= 21
      folder = find_tag_folder(name, model)
      return folder if folder
      model.layers.add_folder(name)
    rescue StandardError => e
      log_exception('创建标记文件夹失败', e)
      nil
    end

    def put_tag_in_folder(tag, folder)
      return tag unless tag && folder
      tag.folder = folder
      tag
    rescue StandardError => e
      log_exception('归入标记文件夹失败', e)
      tag
    end

    def ensure_professional_structure(key, model = Sketchup.active_model)
      info = DISCIPLINES.fetch(key)
      folder = ensure_tag_folder(info['folder'], model)
      model_tag = put_tag_in_folder(ensure_tag(info['model_tag'], model), folder)

      # 将 v0.1 的旧专业主标签也放入文件夹，避免升级后散落在外。
      legacy = model.layers[info['legacy_tag']]
      put_tag_in_folder(legacy, folder) if legacy

      { folder: folder, model_tag: model_tag }
    end

    def layer_identity(layer)
      layer.respond_to?(:persistent_id) ? layer.persistent_id : layer.object_id
    rescue StandardError
      layer.object_id
    end

    def layer_snapshot(model = Sketchup.active_model)
      model.layers.to_a.each_with_object({}) { |layer, memo| memo[layer_identity(layer)] = true }
    end

    def organize_new_tags(before_snapshot, key, model = Sketchup.active_model)
      structure = ensure_professional_structure(key, model)
      folder = structure[:folder]
      return unless folder

      model.layers.each do |layer|
        next if before_snapshot[layer_identity(layer)]
        next if layer == model.layers[0]
        put_tag_in_folder(layer, folder)
      end
    end

    def organize_tags_used_by_entities(entities, key, model = Sketchup.active_model, limit = 200_000)
      structure = ensure_professional_structure(key, model)
      folder = structure[:folder]
      return unless folder

      layers_found = {}
      definitions_seen = {}
      queue = [entities]
      scanned = 0

      until queue.empty? || scanned >= limit
        collection = queue.shift
        collection.each do |entity|
          scanned += 1
          break if scanned >= limit

          if entity.respond_to?(:layer)
            layer = entity.layer
            layers_found[layer_identity(layer)] = layer if layer && layer != model.layers[0]
          end

          next unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
          definition = entity.definition
          definition_id = definition.object_id
          next if definitions_seen[definition_id]
          definitions_seen[definition_id] = true
          queue << definition.entities
        end
      end

      layers_found.each_value { |layer| put_tag_in_folder(layer, folder) }
    rescue StandardError
      nil
    end

    # 根层级受管实体索引。大项目中很多状态刷新会反复询问同一批建筑、景观、
    # 空间根组件；旧版每次都 model.entities.to_a 全扫。现在每个事务后只失效一次，
    # 下一次查询重建一次，此后全部 O(1)/小数组读取。
    def invalidate_managed_root_index(model = Sketchup.active_model, reason: nil)
      return false unless model
      @managed_root_index_revisions ||= {}
      @managed_root_indexes ||= {}
      key = model.object_id
      @managed_root_index_revisions[key] = @managed_root_index_revisions[key].to_i + 1
      @managed_root_indexes.delete(key)
      true
    rescue StandardError
      false
    end

    def build_managed_root_index(model = Sketchup.active_model)
      all = []
      by_discipline = Hash.new { |hash, key| hash[key] = [] }
      by_kind = Hash.new { |hash, key| hash[key] = [] }
      model_by_discipline = Hash.new { |hash, key| hash[key] = [] }
      spaces_by_id = {}
      architecture_models_by_id = {}
      model.entities.each do |entity|
        next unless entity && entity.valid? && entity.respond_to?(:get_attribute)
        next unless entity.get_attribute(ENTITY_DICT, 'managed', false)
        discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
        kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
        all << entity
        by_discipline[discipline] << entity
        by_kind[kind] << entity
        model_by_discipline[discipline] << entity if %w[model skp].include?(kind)
        if kind == 'space_model'
          space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
          spaces_by_id[space_id] ||= entity unless space_id.empty?
        elsif kind == 'architecture_model'
          architecture_id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
          architecture_models_by_id[architecture_id] ||= entity unless architecture_id.empty?
        end
      rescue StandardError
        next
      end
      {
        all: all,
        by_discipline: by_discipline,
        by_kind: by_kind,
        model_by_discipline: model_by_discipline,
        spaces_by_id: spaces_by_id,
        architecture_models_by_id: architecture_models_by_id,
        root_count: (model.entities.length rescue all.length),
        revision: (@managed_root_index_revisions || {})[model.object_id].to_i
      }
    end

    def managed_root_index(model = Sketchup.active_model)
      return { all: [], by_discipline: {}, by_kind: {}, model_by_discipline: {}, spaces_by_id: {}, architecture_models_by_id: {} } unless model
      @managed_root_indexes ||= {}
      @managed_root_index_revisions ||= {}
      key = model.object_id
      revision = @managed_root_index_revisions[key].to_i
      record = @managed_root_indexes[key]
      root_count = model.entities.length rescue nil
      valid = record.is_a?(Hash) && record[:revision].to_i == revision
      valid &&= root_count.nil? || record[:root_count].to_i == root_count.to_i
      valid &&= Array(record[:all]).all? { |entity| entity && entity.valid? }
      unless valid
        record = build_managed_root_index(model)
        @managed_root_indexes[key] = record
      end
      record
    rescue StandardError => e
      log_exception('建立受管根实体索引失败', e)
      { all: [], by_discipline: {}, by_kind: {}, model_by_discipline: {}, spaces_by_id: {}, architecture_models_by_id: {} }
    end

    def managed_entity?(entity, discipline = nil, kind = nil, source = nil)
      return false unless entity.valid?
      return false unless entity.get_attribute(ENTITY_DICT, 'managed', false)
      return false if discipline && entity.get_attribute(ENTITY_DICT, 'discipline', '') != discipline
      return false if kind && entity.get_attribute(ENTITY_DICT, 'kind', '') != kind
      return false if source && entity.get_attribute(ENTITY_DICT, 'source', '') != source
      true
    rescue StandardError
      false
    end

    def managed_entities(model = Sketchup.active_model, discipline: nil, kind: nil, source: nil)
      index = managed_root_index(model)
      candidates = if discipline
                     Array(index.dig(:by_discipline, discipline.to_s))
                   elsif kind
                     Array(index.dig(:by_kind, kind.to_s))
                   else
                     Array(index[:all])
                   end
      candidates.select { |entity| managed_entity?(entity, discipline, kind, source) }
    rescue StandardError
      []
    end

    def managed_model_entities(model = Sketchup.active_model, discipline: nil)
      index = managed_root_index(model)
      candidates = if discipline
                     Array(index.dig(:model_by_discipline, discipline.to_s))
                   else
                     Array(index[:model_by_discipline]&.values).flatten
                   end
      candidates.select { |entity| entity && entity.valid? }
    rescue StandardError
      []
    end

    def mark_entity(entity, discipline:, kind:, source:, display_name:, tag:, mode: nil, signature: nil, locked: true, editing: false)
      entity.set_attribute(ENTITY_DICT, 'managed', true)
      entity.set_attribute(ENTITY_DICT, 'discipline', discipline)
      entity.set_attribute(ENTITY_DICT, 'kind', kind)
      entity.set_attribute(ENTITY_DICT, 'source', source)
      entity.set_attribute(ENTITY_DICT, 'display_mode', mode) if mode
      entity.set_attribute(ENTITY_DICT, 'source_signature', signature) if signature
      entity.set_attribute(ENTITY_DICT, 'editing', !!editing)
      entity.set_attribute(ENTITY_DICT, 'version', EXTENSION_VERSION)
      entity.name = display_name if entity.respond_to?(:name=)
      entity.layer = tag if entity.respond_to?(:layer=)
      entity.locked = !!locked if entity.respond_to?(:locked=)
      invalidate_managed_root_index(entity.model, reason: 'mark_entity') if entity.respond_to?(:model)
      entity
    end

    def editing_entity?(entity)
      entity.respond_to?(:get_attribute) && entity.get_attribute(ENTITY_DICT, 'editing', false)
    rescue StandardError
      false
    end

    def active_edit_entity(key, model = Sketchup.active_model)
      managed_model_entities(model, discipline: key).find { |entity| editing_entity?(entity) }
    rescue StandardError
      nil
    end

    def relock_managed_entities(model = Sketchup.active_model)
      # v0.13.6.190：正在“实例调整”的联动副本、待登记联动副本由各自流程负责锁回，这里不抢先锁上。
      adjusting = linked_space_copy_record(model)
      adjusting_entity = adjusting.is_a?(Hash) && adjusting[:mode].to_s == 'transform' ? adjusting[:entity] : nil
      managed_entities(model).each do |entity|
        next if editing_entity?(entity)
        next if adjusting_entity && entity.equal?(adjusting_entity)
        next if pending_linked_space_clone?(entity)
        entity.locked = true if entity.respond_to?(:locked=) && !entity.locked?
      rescue StandardError
        next
      end
    end

    def tag_folder_descendant?(tag, root_folder)
      return false unless tag && root_folder
      current = tag.respond_to?(:folder) ? tag.folder : nil
      visited = {}
      while current
        return true if current == root_folder
        return true if current.respond_to?(:name) && current.name.to_s == root_folder.name.to_s
        identity = current.respond_to?(:persistent_id) ? current.persistent_id : current.object_id
        break if visited[identity]
        visited[identity] = true
        current = current.respond_to?(:folder) ? current.folder : nil
      end
      false
    rescue StandardError
      false
    end

    def professional_control_tags(key, model = Sketchup.active_model)
      info = DISCIPLINES.fetch(key)
      [
        model.layers[info['model_tag']],
        model.layers[info['legacy_tag']]
      ].compact.uniq
    rescue StandardError
      []
    end

    def professional_tags(key, model = Sketchup.active_model)
      info = DISCIPLINES.fetch(key)
      folder = find_tag_folder(info['folder'], model)
      tags = []
      tags << model.layers[info['model_tag']]
      tags << model.layers[info['legacy_tag']]
      if folder
        model.layers.each do |tag|
          tags << tag if tag_folder_descendant?(tag, folder)
        rescue StandardError
          next
        end
      end
      managed_entities(model, discipline: key).each do |entity|
        tags << entity.layer if entity.respond_to?(:layer)
      rescue StandardError
        next
      end
      tags.compact.uniq
    rescue StandardError
      []
    end

    def visibility_entity_key(entity)
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
      source = entity.get_attribute(ENTITY_DICT, 'source', '').to_s
      name = entity.respond_to?(:name) ? entity.name.to_s : ''
      "#{kind}|#{source}|#{name}"
    rescue StandardError
      entity.object_id.to_s
    end

    def capture_professional_visibility_snapshot!(key, link, model = Sketchup.active_model)
      link['visibility_snapshot'] = professional_control_tags(key, model).each_with_object({}) do |tag, memo|
        memo[tag.name.to_s] = tag.respond_to?(:visible?) ? !!tag.visible? : true
      rescue StandardError
        next
      end
      link['visibility_entity_snapshot'] = managed_entities(model, discipline: key).each_with_object({}) do |entity, memo|
        hidden = entity.respond_to?(:hidden?) ? !!entity.hidden? : false
        memo[visibility_entity_key(entity)] = hidden
      rescue StandardError
        next
      end
      true
    rescue StandardError => e
      log_exception("记录#{DISCIPLINES[key]['name']}隐藏前可见性失败", e)
      false
    end

    def professional_visible?(key, model = Sketchup.active_model)
      info = DISCIPLINES.fetch(key)
      root_tags = [
        model.layers[info['model_tag']],
        model.layers[info['legacy_tag']]
      ].compact
      tag_visible = root_tags.empty? || root_tags.any? { |tag| !tag.respond_to?(:visible?) || tag.visible? }
      entities = managed_entities(model, discipline: key)
      entity_visible = entities.empty? || entities.any? { |entity| !entity.respond_to?(:hidden?) || !entity.hidden? }
      tag_visible && entity_visible
    rescue StandardError
      true
    end

    def professional_visibility_repair_needed?(key, link, model = Sketchup.active_model)
      return false unless link && link['system_hidden']
      professional_control_tags(key, model).any? { |tag| !tag.respond_to?(:visible?) || tag.visible? } ||
        managed_entities(model, discipline: key).any? { |entity| !entity.respond_to?(:hidden?) || !entity.hidden? }
    rescue StandardError
      false
    end

    # 系统级专业显隐：
    # 1) 切换原生 LH_专业_模型控制标记的可见性；
    # 2) 同时设置 LinkHub 受管根组件/群组的 hidden 状态；
    # 3) 不改动源模型内部业务标记，避免同名 wall 等全局标记误伤其他专业；显示时恢复控制标记及根实体原状态。
    def apply_professional_visibility!(key, visible:, state:, model: Sketchup.active_model, capture_snapshot: false)
      link = state['links'].fetch(key)
      ensure_professional_structure(key, model)
      tags = professional_control_tags(key, model)
      entities = managed_entities(model, discipline: key)

      if visible
        snapshot = link['visibility_snapshot'].is_a?(Hash) ? link['visibility_snapshot'] : {}
        tags.each do |tag|
          next unless tag.respond_to?(:visible=)
          desired = snapshot.key?(tag.name.to_s) ? !!snapshot[tag.name.to_s] : true
          tag.visible = desired
        rescue StandardError
          next
        end
        entity_snapshot = link['visibility_entity_snapshot'].is_a?(Hash) ? link['visibility_entity_snapshot'] : {}
        entities.each do |entity|
          next unless entity.respond_to?(:hidden=)
          key_name = visibility_entity_key(entity)
          entity.hidden = entity_snapshot.key?(key_name) ? !!entity_snapshot[key_name] : false
        rescue StandardError
          next
        end
      else
        capture_professional_visibility_snapshot!(key, link, model) if capture_snapshot
        tags.each do |tag|
          tag.visible = false if tag.respond_to?(:visible=)
        rescue StandardError
          next
        end
        entities.each do |entity|
          entity.hidden = true if entity.respond_to?(:hidden=)
        rescue StandardError
          next
        end
      end

      model.active_view.invalidate if model.respond_to?(:active_view) && model.active_view
      true
    rescue StandardError => e
      log_exception("应用#{DISCIPLINES[key]['name']}系统显隐失败", e)
      false
    end

    def reapply_professional_visibility!(key, state, model = Sketchup.active_model)
      link = state['links'][key]
      return true unless link && link['system_hidden']
      apply_professional_visibility!(key, visible: false, state: state, model: model, capture_snapshot: false)
    end

    def toggle_professional_visibility(key)
      model = Sketchup.active_model
      state = load_state(model)
      link = state['links'].fetch(key)
      if host_discipline_for(state) == key
        show_status('当前工作专业是本文件原生内容，无法可靠整体隐藏；请使用原生标记管理。', 'error')
        return false
      end

      target_visible = link['system_hidden'] ? true : !professional_visible?(key, model)
      operation_started = false
      begin
        model.start_operation("#{target_visible ? '显示' : '隐藏'}#{link['name']}专业", true, false, true)
        operation_started = true
        ok = apply_professional_visibility!(
          key,
          visible: target_visible,
          state: state,
          model: model,
          capture_snapshot: !target_visible
        )
        raise '系统显隐应用失败。' unless ok
        link['system_hidden'] = !target_visible
        link['visibility_mode'] = 'system_dual'
        link['visibility_last_changed'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        save_state(state, model, write_manifest: false)
        model.commit_operation
        operation_started = false
        refresh_dialog
        show_status(
          target_visible ? "#{link['name']}已系统显示，并恢复隐藏前的控制标记状态。" : "#{link['name']}已系统隐藏：专业控制标记与受管根模型均已关闭。",
          'success'
        )
        true
      rescue StandardError => e
        model.abort_operation if operation_started
        log_exception("切换#{link['name']}系统显隐失败", e)
        show_status("#{link['name']}显隐失败：#{e.message}", 'error')
        false
      end
    end

    def erase_managed_entities_for_disconnect!(key, model = Sketchup.active_model)
      removed = 0
      old_definitions = []
      managed_entities(model, discipline: key).each do |entity|
        next unless entity && entity.valid?
        old_definitions << entity.definition if entity.is_a?(Sketchup::ComponentInstance) && entity.definition && entity.definition.valid?
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase! if entity.valid?
        removed += 1
      rescue StandardError => e
        log_exception("断开#{key}时移除受管实体失败", e)
        next
      end

      # 删除已经没有实例的受管定义，避免断开后仍在模型定义库里占用大量内存；失败则忽略，下一次打开模型也不会显示。
      remove_unused_managed_definitions(old_definitions, model) rescue nil
      begin
        model.definitions.purge_unused if model.definitions.respond_to?(:purge_unused)
      rescue StandardError
        nil
      end
      removed
    end

    def link_has_unsaved_preview?(link, entity = nil)
      return true if link['preview_pending_publish'] || link['preview_edit_active'] || link['edit_session_active']
      return true if entity && entity.valid? && entity.respond_to?(:locked?) && !entity.locked?
      false
    rescue StandardError
      false
    end

    def disconnect_link_reference!(key, state, model = Sketchup.active_model)
      link = state['links'].fetch(key)
      entity = native_edit_entity(key, model)
      if link_has_unsaved_preview?(link, entity)
        raise '该专业正处于解锁编辑或待提交状态。请先锁定并选择提交/不提交，再断开。'
      end

      removed = 0
      model.start_operation("断开#{link['name']}联动", true)
      removed = erase_managed_entities_for_disconnect!(key, model)
      model.commit_operation

      clear_preview_state!(link, restore_auto: true) rescue nil
      clear_edit_state!(link, restore_previous: false) rescue nil
      link['enabled'] = false
      link['system_hidden'] = false
      link['visibility_snapshot'] = {}
      link['visibility_entity_snapshot'] = {}
      link['disconnected_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      link['disconnect_removed_count'] = removed.to_i
      link['last_commit_result'] = '' unless link['last_commit_result'].to_s == 'success'
      link['status'] = removed.positive? ? "已断开 · 已从当前模型移除#{removed}个联动对象" : '已断开 · 当前模型中没有可移除的联动对象'
      removed
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    def reconnect_link_reference!(key, state, model = Sketchup.active_model)
      link = state['links'].fetch(key)
      link['enabled'] = true
      link['system_hidden'] = false
      link['disconnected_at'] = ''
      link['disconnect_removed_count'] = 0
      link['status'] = '正在启用并重新载入…'
      save_state(state, model, write_manifest: false)
      refresh_dialog

      result = load_linked_model(key, state, force: true)
      if result[:ok]
        link['status'] = result[:skipped] ? '已启用 · 暂无可载入缓存' : '已启用 · 已重新载入'
      else
        link['status'] = "启用失败 · #{result[:message]}"
      end
      result
    end

    def toggle_link_enabled(key)
      model = Sketchup.active_model
      state = load_state(model)
      link = state['links'].fetch(key)
      if host_discipline_for(state) == key
        show_status('当前工作区是本文件原生内容，不需要断开。', 'success')
        return true
      end

      if link['enabled']
        removed = disconnect_link_reference!(key, state, model)
        save_state(state, model, write_manifest: false)
        refresh_dialog
        show_status("#{link['name']}已断开；已从当前模型移除#{removed}个联动对象。再次启用时会从协同缓存重新载入。", 'success')
      else
        result = reconnect_link_reference!(key, state, model)
        save_state(state, model, write_manifest: false)
        refresh_dialog
        if result[:ok]
          show_status("#{link['name']}已启用并重新连接。", 'success')
        else
          show_status("#{link['name']}启用失败：#{result[:message]}", 'error')
        end
      end
      true
    rescue StandardError => e
      log_exception('切换专业连接状态失败', e)
      show_status("切换连接状态失败：#{e.message}", 'error')
      false
    end

    # -------------------------
    # Source signatures and local mirrors
    # -------------------------

    def source_signature(path)
      signature = "#{File.mtime(path).to_f}|#{File.size(path)}"
      manifest = manifest_path_for(path)
      if File.file?(manifest)
        signature = "#{signature}|manifest:#{File.mtime(manifest).to_f}|#{File.size(manifest)}"
      end
      signature
    rescue StandardError
      ''
    end

    # 手动更新使用源文件本体的修改时间和大小作为快速签名。
    # sidecar 清单变化不会触发整模重载。
    def fast_file_signature(path)
      stat = File.stat(path)
      "#{stat.mtime.to_f}|#{stat.size}"
    rescue StandardError
      ''
    end

    def soft_library_file_signature(path, force: false)
      raw = path.to_s
      return '' if raw.empty?
      @soft_library_file_signature_cache ||= {}
      key = normalize_soft_library_key(raw)
      now = monotonic_time
      cached = @soft_library_file_signature_cache[key]
      if !force && cached && (now - cached[:checked_at].to_f) <= SOFT_LIBRARY_FILE_SIGNATURE_TTL
        return cached[:signature].to_s
      end
      signature = fast_file_signature(raw).to_s
      @soft_library_file_signature_cache[key] = { signature: signature, checked_at: now }
      signature
    rescue StandardError
      ''
    end

    def invalidate_soft_library_file_signature!(path = nil)
      @soft_library_file_signature_cache ||= {}
      if path.to_s.empty?
        @soft_library_file_signature_cache.clear
      else
        @soft_library_file_signature_cache.delete(normalize_soft_library_key(path))
      end
      true
    rescue StandardError
      false
    end

    # 共享 JSON 是版本真相源。小文件直接做内容哈希，避免 SMB/NAS 上
    # 修改时间精度低、文件大小恰好不变时继续读取旧缓存。
    def small_file_content_signature(path)
      return '' unless File.file?(path)
      "sha256:#{linkhub_file_sha256_hexdigest(path)}|#{File.size(path)}"
    rescue StandardError
      ''
    end

    def new_publish_revision(prefix = 'publish')
      "#{prefix}-#{Time.now.utc.strftime('%Y%m%dT%H%M%S.%6NZ')}-#{Process.pid}-#{SecureRandom.hex(6)}"
    rescue StandardError
      "#{prefix}-#{Time.now.to_i}-#{Process.pid}-#{SecureRandom.hex(6)}"
    end

    def authoritative_link_revision(link, source_path = '')
      return '' unless link.is_a?(Hash)
      revision = link['collab_revision_id'].to_s
      version = link['collab_cache_version'].to_s
      generated_at = link['collab_last_publish_at'].to_s
      declared_signature = normalize_fast_signature(link['collab_full_signature'].to_s)
      actual_signature = normalize_fast_signature(fast_file_signature(source_path))
      base = if !revision.empty?
               ['collab', revision, version, generated_at, declared_signature].join('|')
             elsif !(generated_at.empty? && version.empty? && declared_signature.empty?)
               ['collab-legacy', generated_at, version, declared_signature].join('|')
             elsif !actual_signature.empty?
               "file|#{actual_signature}"
             else
               ''
             end
      return base if base.empty?
      # JSON 是主版本源，但共享 SKP 本体是完整性护栏。若上一次发布已经替换
      # SKP、随后 JSON 登记失败或被旧客户端覆盖，必须让客户端摆脱旧镜像。
      if !actual_signature.empty? && (declared_signature.empty? || declared_signature != actual_signature)
        return "#{base}|file-recovery:#{actual_signature}"
      end
      base
    rescue StandardError
      ''
    end

    def loaded_entity_source_revision(entity)
      return '' unless entity && entity.valid? && entity.respond_to?(:get_attribute)
      entity.get_attribute(ENTITY_DICT, 'source_revision', '').to_s
    rescue StandardError
      ''
    end

    def revision_time_value(value)
      text = value.to_s
      return 0.0 if text.empty?
      base = text.split('|file-recovery:', 2).first.to_s
      if (match = base.match(/(\d{8}T\d{6}(?:\.\d+)?Z)/))
        return Time.strptime(match[1], '%Y%m%dT%H%M%S.%NZ').to_f
      end
      if base.start_with?('space-legacy|')
        candidate = base.split('|', 3)[1].to_s
        return Time.parse(candidate).to_f unless candidate.empty?
      end
      Time.parse(base).to_f
    rescue StandardError
      0.0
    end

    # 只修复一种可证明的中断状态：新版空间 SKP 已完成正式替换，但进程在把新
    # revision/signature 写回共享 JSON 之前退出。包必须属于同一空间、定义图完整、
    # 清单已明确带 file-recovery，且包内时间严格晚于清单基线；其他不一致继续阻止。
    def recoverable_space_package_manifest_gap?(item, package_revision, package_space_id, manifest_revision, package_graph_verified: false)
      return false unless item.is_a?(Hash) && package_graph_verified == true
      space_id = item['id'].to_s
      package = package_revision.to_s
      manifest = manifest_revision.to_s
      return false if space_id.empty? || package.empty? || package_space_id.to_s != space_id
      return false unless manifest.include?('|file-recovery:')
      return false unless package.start_with?("space-#{space_id}-")
      manifest_base = manifest.split('|file-recovery:', 2).first.to_s
      package_time = revision_time_value(package)
      manifest_time = revision_time_value(manifest_base)
      package_time.positive? && manifest_time.positive? && package_time > manifest_time + 0.001
    rescue StandardError
      false
    end

    def entity_loaded_publish_time(entity)
      return 0.0 unless entity && entity.valid?
      explicit = entity.get_attribute(ENTITY_DICT, 'source_published_at', '').to_s
      value = Time.parse(explicit).to_f unless explicit.empty?
      return value.to_f if value.to_f.positive?
      revision_time_value(loaded_entity_source_revision(entity))
    rescue StandardError
      revision_time_value(loaded_entity_source_revision(entity))
    end

    def entity_loaded_source_mtime(entity)
      return 0.0 unless entity && entity.valid?
      entity.get_attribute(ENTITY_DICT, 'source_file_mtime', 0.0).to_f
    rescue StandardError
      0.0
    end

    # 返回 :same / :newer / :older / :unknown，含义是“共享端相对当前已载入模型”。
    # :older 永远不能自动覆盖；:unknown 也不能进入批量更新。
    def space_update_direction(item, entity, source_path, remote_signature: nil, remote_mtime: nil)
      return :unknown unless space_component_bundle_ready?(item)
      return :newer unless entity && entity.valid?
      remote_signature = normalize_fast_signature(remote_signature.nil? ? fast_file_signature(source_path) : remote_signature)
      remote_revision = space_authoritative_revision(item, source_path, actual_signature: remote_signature)
      loaded_revision = loaded_entity_source_revision(entity)
      loaded_signature = normalize_fast_signature(loaded_entity_source_signature(entity))
      verified_schema = entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i rescue 0
      verified_signature = normalize_fast_signature(entity.get_attribute(ENTITY_DICT, 'source_verified_signature', '').to_s) rescue ''
      package_revision = entity.get_attribute(ENTITY_DICT, 'source_package_revision', '').to_s rescue ''
      package_identity = entity.get_attribute(ENTITY_DICT, 'source_package_identity', '').to_s rescue ''
      snapshot_verified = verified_schema >= SPACE_LOAD_VERIFIED_SCHEMA && !loaded_signature.empty? &&
                          verified_signature == loaded_signature && !package_identity.empty? &&
                          (loaded_revision.empty? || package_revision.empty? || package_revision == loaded_revision)
      # 旧插件可能只改了 revision/signature 属性，却仍复用了旧内层定义。未通过当前
      # 快照验证的实体永远不能直接显示“已更新”，至少需要重新载入一次。
      return :newer unless snapshot_verified
      return :same if !remote_revision.empty? && remote_revision == loaded_revision &&
                      (remote_signature.empty? || remote_signature == loaded_signature)
      return :same if remote_revision.empty? && !remote_signature.empty? && remote_signature == loaded_signature

      remote_time = begin
        explicit = item['last_publish_at'].to_s
        explicit.empty? ? revision_time_value(remote_revision) : Time.parse(explicit).to_f
      rescue StandardError
        revision_time_value(remote_revision)
      end
      loaded_time = entity_loaded_publish_time(entity)
      time_direction = if remote_time.positive? && loaded_time.positive? && (remote_time - loaded_time).abs > 0.001
                         remote_time > loaded_time ? :newer : :older
                       end

      remote_mtime = if remote_mtime.nil?
                       File.file?(source_path.to_s) ? File.mtime(source_path.to_s).to_f : 0.0
                     else
                       remote_mtime.to_f
                     end
      loaded_mtime = entity_loaded_source_mtime(entity)
      mtime_direction = if remote_mtime.positive? && loaded_mtime.positive? && (remote_mtime - loaded_mtime).abs > 0.5
                          remote_mtime > loaded_mtime ? :newer : :older
                        end
      # file-recovery 表示 JSON 与共享 SKP 本体不一致，此时文件时间比旧 JSON 的
      # published_at 更接近真实先后；若两套证据冲突且没有 recovery 标记则停止自动更新。
      return mtime_direction if remote_revision.include?('|file-recovery:') && mtime_direction
      return :unknown if time_direction && mtime_direction && time_direction != mtime_direction
      return time_direction if time_direction
      return mtime_direction if mtime_direction
      return :newer if loaded_revision.empty? && !remote_revision.empty?
      :unknown
    rescue StandardError
      :unknown
    end

    def verify_loaded_space_snapshot!(entity, expected_revision, expected_signature)
      raise '空间载入结果无效。' unless entity && entity.valid?
      loaded_revision = loaded_entity_source_revision(entity)
      loaded_signature = normalize_fast_signature(loaded_entity_source_signature(entity))
      verified_signature = normalize_fast_signature(entity.get_attribute(ENTITY_DICT, 'source_verified_signature', '').to_s)
      package_revision = entity.get_attribute(ENTITY_DICT, 'source_package_revision', '').to_s
      package_identity = entity.get_attribute(ENTITY_DICT, 'source_package_identity', '').to_s
      verified_schema = entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i
      if !expected_revision.to_s.empty? && loaded_revision.to_s != expected_revision.to_s
        raise "空间载入后的版本标记不一致（#{loaded_revision} / #{expected_revision}），更新已回滚。"
      end
      expected_sig = normalize_fast_signature(expected_signature)
      if !expected_sig.empty? && loaded_signature != expected_sig
        raise "空间载入后的文件签名不一致（#{loaded_signature} / #{expected_sig}），更新已回滚。"
      end
      if verified_schema < SPACE_LOAD_VERIFIED_SCHEMA || verified_signature.empty? || verified_signature != loaded_signature || package_identity.empty?
        raise '空间载入快照没有通过完整验证，已阻止显示为最新。'
      end
      if !package_revision.empty? && !loaded_revision.empty? && package_revision != loaded_revision
        raise '空间载入包版本与实体版本不一致，更新已回滚。'
      end
      true
    end

    def assert_space_update_direction!(item, entity, source_path, allow_unknown: false)
      direction = space_update_direction(item, entity, source_path)
      if direction == :older
        raise "共享目录中的 #{item['number']}:#{item['name']} 版本早于当前已载入模型，已阻止旧版覆盖。请先检查是谁用旧插件写回清单，或从版本历史恢复后再更新。"
      end
      if direction == :unknown && !allow_unknown
        raise "无法确认 #{item['number']}:#{item['name']} 的共享版本是否更新。为避免旧模型覆盖新模型，已停止更新；请先让发布者使用当前插件重新发布一次。"
      end
      direction
    end

    def space_authoritative_revision(item, source_path = '', actual_signature: nil)
      return '' unless item.is_a?(Hash)
      revision = item['source_revision'].to_s
      published_at = item['last_publish_at'].to_s
      declared_signature = normalize_fast_signature(item['last_signature'].to_s)
      actual_signature = normalize_fast_signature(actual_signature.nil? ? fast_file_signature(source_path) : actual_signature)
      base = if !revision.empty?
               revision
             elsif !(published_at.empty? && declared_signature.empty?)
               ['space-legacy', published_at, declared_signature].join('|')
             elsif !actual_signature.empty?
               "space-file|#{actual_signature}"
             else
               ''
             end
      return base if base.empty?
      if !actual_signature.empty? && (declared_signature.empty? || declared_signature != actual_signature)
        return "#{base}|file-recovery:#{actual_signature}"
      end
      base
    rescue StandardError
      ''
    end

    # 抽屉可能在短时间内连续刷新。局域网 File.file?/File.size/File.mtime 每次都
    # 会产生 SMB 往返，因此这里只给“界面状态”做很短的元数据缓存；发布、更新、
    # 版本冲突判断仍使用上面的实时签名，不受此缓存影响。
    def space_status_file_snapshot(path, ttl: 0.65)
      expanded = FastPath.expand(path.to_s)
      return { exists: false, size: 0, size_mb: 0, signature: '' } if expanded.empty?
      now = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      @space_status_file_snapshot_cache ||= {}
      cached = @space_status_file_snapshot_cache[expanded]
      if cached.is_a?(Hash) && now - cached[:checked_at].to_f <= ttl.to_f
        return cached
      end
      stat = File.stat(expanded)
      result = {
        exists: stat.file?,
        size: stat.size.to_i,
        size_mb: (stat.size.to_f / 1024.0 / 1024.0).round(1),
        signature: "#{stat.mtime.to_f}|#{stat.size}",
        checked_at: now
      }
      @space_status_file_snapshot_cache[expanded] = result
      result
    rescue StandardError
      result = { exists: false, size: 0, size_mb: 0, signature: '', checked_at: now || 0.0 }
      @space_status_file_snapshot_cache[expanded] = result if defined?(expanded) && !expanded.to_s.empty?
      result
    end

    def watched_signature(path)
      fast_file_signature(path)
    end

    def cache_directory(_model = Sketchup.active_model)
      base = ENV['LOCALAPPDATA'].to_s
      base = File.join(Dir.tmpdir, 'SU_LinkHub_Local') if base.empty?
      dir = File.join(base, 'SU_LinkHub', 'model_cache')
      FileUtils.mkdir_p(dir)
      dir
    end

    def local_mirror_cleanup_active_paths
      active = {}
      Array(@space_batch_prefetch_jobs&.values).each do |job|
        Array(job.is_a?(Hash) ? job[:results]&.values : []).each do |row|
          path = row.is_a?(Hash) ? row[:path].to_s : ''
          active[FastPath.expand(path)] = true unless path.empty?
        rescue StandardError
          nil
        end
      end
      active
    rescue StandardError
      {}
    end

    def cleanup_local_mirror_cache!
      root = cache_directory
      return true unless Dir.exist?(root)
      now = Time.now.to_f
      protected_paths = local_mirror_cleanup_active_paths
      files = Dir.glob(File.join(root, '*'))
      files.each do |path|
        next unless File.file?(path)
        age = now - (File.mtime(path).to_f rescue now)
        if File.basename(path).include?('.tmp') && age > LOCAL_MIRROR_TEMP_MAX_AGE_SECONDS
          File.delete(path) rescue nil
        elsif File.extname(path).downcase == '.skp' && age > LOCAL_MIRROR_MAX_AGE_DAYS * 86_400
          expanded = FastPath.expand(path)
          File.delete(path) unless protected_paths[expanded] || age < LOCAL_MIRROR_RECENT_PROTECT_SECONDS
        end
      end

      skps = Dir.glob(File.join(root, '*.skp')).select { |path| File.file?(path) }
      rows = skps.map do |path|
        stat = File.stat(path)
        [path, stat.size.to_i, stat.mtime.to_f]
      rescue StandardError
        nil
      end.compact
      total = rows.sum { |row| row[1] }
      target = (LOCAL_MIRROR_MAX_BYTES * 0.90).to_i
      if total > LOCAL_MIRROR_MAX_BYTES
        rows.sort_by { |row| row[2] }.each do |path, size, mtime|
          break if total <= target
          next if protected_paths[FastPath.expand(path)]
          next if now - mtime < LOCAL_MIRROR_RECENT_PROTECT_SECONDS
          begin
            File.delete(path)
            total -= size
          rescue StandardError
            next
          end
        end
      end
      log("本地镜像缓存整理完成：#{(total.to_f / 1024 / 1024).round(1)}MB / #{Dir.glob(File.join(root, '*.skp')).length} 个 SKP")
      true
    rescue StandardError => e
      log_exception('整理本地模型镜像缓存失败', e)
      false
    end

    def schedule_local_mirror_cache_cleanup!(delay: 4.0, retry_count: 0)
      return false if @shutting_down
      runtime_start_timer(delay.to_f, false, label: 'cache:local_mirror_cleanup', key: 'cache:local_mirror_cleanup') do
        if @shutting_down
          next
        elsif publish_critical_section? || soft_heavy_interaction?
          schedule_local_mirror_cache_cleanup!(delay: 3.0, retry_count: retry_count.to_i + 1) if retry_count.to_i < 12
          next
        elsif @local_mirror_cleanup_thread && @local_mirror_cleanup_thread.alive?
          next
        end
        generation = @runtime_generation.to_i
        @local_mirror_cleanup_thread = Thread.new do
          Thread.current.name = 'SU_LinkHub-mirror-cleanup' if Thread.current.respond_to?(:name=)
          cleanup_local_mirror_cache! if !@shutting_down && @runtime_generation.to_i == generation
        rescue StandardError => e
          log_exception('后台整理本地模型镜像缓存失败', e)
        ensure
          @local_mirror_cleanup_thread = nil if Thread.current == @local_mirror_cleanup_thread
        end
      end
      true
    rescue StandardError => e
      log_exception('安排本地镜像缓存整理失败', e)
      false
    end

    def mirror_cache_key(source_path)
      Digest::SHA1.hexdigest(FastPath.expand(source_path).tr('\\', '/').downcase)
    rescue StandardError
      Digest::SHA1.hexdigest(source_path.to_s)
    end

    def mirror_cache_path(key, source_path, signature)
      path_key = mirror_cache_key(source_path)[0, 14]
      sig_key = Digest::SHA1.hexdigest(signature.to_s)[0, 14]
      File.join(cache_directory, "#{key}_#{path_key}_#{sig_key}_#{LOCAL_MIRROR_NAMESPACE}.skp")
    end

    def purge_old_mirrors(key, source_path, keep_path)
      prefix = "#{key}_#{mirror_cache_key(source_path)[0, 14]}_"
      files = Dir.glob(File.join(cache_directory, "#{prefix}*.skp"))
      files = files.reject { |path| same_file_path?(path, keep_path) }
      files.sort_by { |path| File.mtime(path) rescue Time.at(0) }.reverse_each.with_index do |path, index|
        next if index < [LOCAL_MIRROR_KEEP - 1, 0].max
        File.delete(path) if File.file?(path)
      rescue StandardError
        next
      end
      true
    rescue StandardError => e
      log_exception('清理本地模型镜像失败', e)
      false
    end

    def sampled_file_content_signature(path, sample_bytes: 65_536)
      stat = File.stat(path)
      return '' unless stat.file? && stat.size.positive?
      size = stat.size.to_i
      first = ''.b
      last = ''.b
      File.open(path, 'rb') do |file|
        first = file.read([sample_bytes.to_i, size].min).to_s
        if size > sample_bytes.to_i
          file.seek([size - sample_bytes.to_i, 0].max, IO::SEEK_SET)
          last = file.read(sample_bytes.to_i).to_s
        end
      end
      "#{size}|sample-sha256:#{Digest::SHA256.hexdigest(first + last)}"
    rescue StandardError
      ''
    end

    # v0.13.6.170：LinkHub 自己生成的 TEMP 随机候选在同一生命周期内是不可变的。
    # 对这些临时文件复用已算过的完整 SHA，避免 serialize -> promote -> verify 多个阶段
    # 重复读同一份几十/上百 MB 文件；共享盘正式文件绝不走此缓存。
    def generated_ephemeral_content_signature_cache_key(path, stat = nil)
      target = FastPath.expand(path.to_s)
      temp_root = FastPath.expand(TEMP_ROOT_DIR.to_s)
      return '' unless target == temp_root || target.start_with?(temp_root + File::SEPARATOR)
      stat ||= File.stat(target)
      return '' unless stat.file? && stat.size.positive?
      "#{normalize_soft_library_key(target)}|#{stat.size.to_i}|#{stat.mtime.to_f}"
    rescue StandardError
      ''
    end

    # 低频危险写盘事务使用整文件 SHA-256；日常刷新仍可使用快速/抽样签名。
    def full_file_content_signature(path)
      stat = File.stat(path)
      return '' unless stat.file? && stat.size.positive?
      cache_key = generated_ephemeral_content_signature_cache_key(path, stat)
      unless cache_key.empty?
        @generated_ephemeral_content_signature_cache ||= {}
        cached = @generated_ephemeral_content_signature_cache[cache_key].to_s
        return cached unless cached.empty?
      end
      signature = "#{stat.size.to_i}|sha256:#{linkhub_file_sha256_hexdigest(path)}"
      if !cache_key.empty?
        @generated_ephemeral_content_signature_cache ||= {}
        @generated_ephemeral_content_signature_cache[cache_key] = signature
        # 临时候选 token 都是唯一名，防止长会话缓存无限增长。
        @generated_ephemeral_content_signature_cache.shift while @generated_ephemeral_content_signature_cache.length > 96
      end
      signature
    rescue StandardError
      ''
    end

    # 后台候选采用分块 SHA 并在块间主动让出 Ruby 调度。旧版 IO.popen(certutil.exe)
    # 会偶发弹出黑色控制台窗口，也可能等待子进程管道/安全软件扫描。4MB 分块不会创建
    # 外部窗口；前后 fast 签名一致性仍防止计算途中候选被替换。
    def background_full_file_content_signature(path)
      target = FastPath.expand(path.to_s)
      return '' unless File.file?(target) && File.size(target).positive?
      before = fast_file_signature(target)
      return '' if before.empty?
      digest = Digest::SHA256.new
      File.open(target, 'rb') do |file|
        while (chunk = file.read(4 * 1024 * 1024))
          digest.update(chunk)
          Thread.pass
        end
      end
      after = fast_file_signature(target)
      return '' if after.empty? || before != after
      "#{File.size(target).to_i}|sha256:#{digest.hexdigest}"
    rescue StandardError
      ''
    end

    # 6.66：同目录原子 rename 前后若 dev/ino/size 完全一致，说明 rollback 仍是
    # 预检时那一个文件对象；rename 不改变内容，因此可以复用已经验证过的整文件 SHA。
    # Windows/SMB 若不提供稳定 inode（ino<=0）则返回空，自动回退原来的整文件 SHA。
    def stable_file_identity_token(path)
      stat = File.stat(path.to_s)
      return '' unless stat.file? && stat.size.positive?
      ino = stat.ino.to_i rescue 0
      dev = stat.dev.to_i rescue 0
      return '' unless ino.positive?
      "#{dev}|#{ino}|#{stat.size.to_i}|#{stat.mtime.to_f}"
    rescue StandardError
      ''
    end

    def stable_full_file_snapshot_signature(path)
      before = fast_file_signature(path)
      return '' if before.empty?
      content = full_file_content_signature(path)
      after = fast_file_signature(path)
      return '' if content.empty? || after.empty? || before != after
      "#{after}|#{content}"
    rescue StandardError
      ''
    end

    # 从“mtime|size|size|sha256:...”稳定快照里取回前半段快速签名。
    # 候选生成/传输阶段只用它做早期并发变化检测；真正开始替换前仍会对已移走的
    # backup 做一次完整 SHA-256 与原始快照比对，所以不会因为减少重复 NAS 全盘读取
    # 而放弃最终的强校验。
    def full_snapshot_fast_signature(signature)
      text = signature.to_s
      return text unless text.include?('sha256:')
      parts = text.split('|')
      return '' if parts.length < 4
      parts.first(2).join('|')
    rescue StandardError
      ''
    end

    # v0.13.6.67：从稳定完整快照中取回真正的整文件内容指纹。
    # 格式为 mtime|size|size|sha256:...，后两段就是 full_file_content_signature。
    def full_snapshot_content_signature(signature)
      text = signature.to_s
      parts = text.split('|')
      return '' if parts.length < 4 || !parts.last.to_s.start_with?('sha256:')
      parts.last(2).join('|')
    rescue StandardError
      ''
    end

    # 发布候选上传期间只需要判断共享目标“有没有动过”，不应反复整文件 SHA。
    # fast + 首尾抽样用于传输窗口的轻量守卫；真正替换前仍会把已移走 rollback
    # 做一次整文件 SHA 并与最初完整基线比对，因此并发安全边界没有放掉。
    def publish_target_light_guard(path)
      fast = fast_file_signature(path)
      sample = sampled_file_content_signature(path)
      return '' if fast.empty? || sample.empty?
      "#{fast}|#{sample}"
    rescue StandardError
      ''
    end

    # 如果上一次安全发布快照的 sidecar 与当前目标快速签名一致，并且目标/快照
    # 首尾抽样也一致，则可以直接复用 sidecar 中已经验证过的整文件 SHA。
    # 最终 rename 到 rollback 后仍会重新整文件 SHA 一次，所以这里只是减少发布前
    # 对同一个 NAS SKP 的一次全盘读取，不改变最终强校验。
    def trusted_safe_checkpoint_content_signature(target, key, expected_fast = '')
      return '' unless File.file?(target.to_s)
      checkpoint = latest_safe_publish_checkpoint_path_for(target, key, create: false)
      meta_path = "#{checkpoint}.json"
      return '' unless File.file?(checkpoint) && File.file?(meta_path)
      meta = read_json_file(meta_path) rescue {}
      content = meta['content_signature'].to_s
      recorded_fast = normalize_fast_signature(meta['signature'].to_s)
      actual_fast = normalize_fast_signature(fast_file_signature(target))
      expected = normalize_fast_signature(expected_fast)
      return '' if content.empty? || !content.include?('sha256:') || actual_fast.empty?
      return '' if !expected.empty? && actual_fast != expected
      return '' if !recorded_fast.empty? && recorded_fast != actual_fast
      target_sample = sampled_file_content_signature(target)
      checkpoint_sample = sampled_file_content_signature(checkpoint)
      return '' if target_sample.empty? || checkpoint_sample.empty? || target_sample != checkpoint_sample
      content
    rescue StandardError
      ''
    end

    # source 已在上一步完整 SHA-256 校验过时使用的 create-only 提升。
    # 与通用 promote_file_create_only! 不同，它不再把同一个 remote_stage 从 NAS 完整读一遍；
    # 只对最终 target 做一次“fast-before -> full SHA -> fast-after”稳定校验。
    # 仅用于 LinkHub 自己生成的随机隐藏 stage 文件，不改变发布/回滚等其它高风险链路。
    def promote_preverified_file_create_only!(source, target, expected_content_signature)
      expected = expected_content_signature.to_s
      raise '候选文件不存在。' unless File.file?(source) && File.size(source).positive?
      raise '候选文件缺少已验证的完整内容指纹。' if expected.empty? || !expected.include?('sha256:')
      raise '目标文件已经存在，已停止以避免覆盖。' if File.exist?(target)
      linked = false
      begin
        File.link(source, target)
        linked = true
      rescue Errno::EEXIST
        raise '目标文件在最终落盘窗口被另一任务创建，已停止且未覆盖。'
      rescue StandardError
        begin
          File.open(target, File::WRONLY | File::CREAT | File::EXCL, 0o666) do |out|
            File.open(source, 'rb') { |input| IO.copy_stream(input, out) }
            out.flush
          end
        rescue Errno::EEXIST
          raise '目标文件在最终落盘窗口被另一任务创建，已停止且未覆盖。'
        end
      end
      before = fast_file_signature(target)
      # 同目录 hard-link 成功时 target 与已经完整 SHA 验证过的 stage 是同一文件内容，
      # 再整文件 SHA 只会制造一次重复读取；copy fallback 才需要重新做完整 SHA。
      content = linked ? expected : full_file_content_signature(target)
      after = fast_file_signature(target)
      unless !before.empty? && before == after && content == expected && File.size(target) == File.size(source)
        # 和通用安全提升一致：验证异常时保留 target 现场，不在 hash->delete 窗口误删
        # 可能被另一协作者替换的新文件；上层事务会决定是否安全恢复 backup。
        raise '候选文件创建后稳定完整校验失败；为避免误删并发写入，已保留目标文件供核对。'
      end
      File.delete(source) if File.file?(source)
      {
        'fast_signature' => after.to_s,
        'content_signature' => content.to_s,
        'snapshot_signature' => "#{after}|#{content}"
      }
    end

    def space_source_snapshot_signature(path)
      fast = fast_file_signature(path)
      sample = sampled_file_content_signature(path)
      return '' if fast.empty? || sample.empty?
      "#{fast}|#{sample}"
    rescue StandardError
      ''
    end

    def mirror_stage_mutex_for(key, source_path)
      @mirror_stage_mutex_guard ||= Mutex.new
      @mirror_stage_mutexes ||= {}
      token = "#{key}|#{mirror_cache_key(source_path)}"
      @mirror_stage_mutex_guard.synchronize { @mirror_stage_mutexes[token] ||= Mutex.new }
    end

    def stage_source_mirror(key, source_path, signature)
      mutex = mirror_stage_mutex_for(key, source_path)
      mutex.synchronize do
        target = mirror_cache_path(key, source_path, signature)
        expected_size = File.size(source_path)
        source_content = sampled_file_content_signature(source_path)
        if File.file?(target) && File.size(target) == expected_size && expected_size.positive? &&
           !source_content.empty? && sampled_file_content_signature(target) == source_content
          return target
        end

        temp = "#{target}.tmp_#{Process.pid}_#{SecureRandom.hex(4)}"
        File.delete(temp) if File.file?(temp)
        before = [fast_file_signature(source_path), source_content]
        raise SyncDeferredError, '源 SKP 文件为空，可能仍在保存。' unless expected_size.positive? && !source_content.empty?

        linkhub_copy_file(source_path, temp)
        after = [fast_file_signature(source_path), sampled_file_content_signature(source_path)]
        copied_size = File.size(temp)
        copied_content = sampled_file_content_signature(temp)
        if before != after || copied_size != expected_size || copied_content != after[1]
          File.delete(temp) if File.file?(temp)
          raise SyncDeferredError, '源 SKP 正在保存或镜像校验不一致，已延后本次同步。'
        end

        File.delete(target) if File.file?(target)
        File.rename(temp, target)
        purge_old_mirrors(key, source_path, target)
        target
      end
    rescue SyncDeferredError
      raise
    rescue StandardError => e
      File.delete(temp) if defined?(temp) && File.file?(temp)
      raise "建立本地模型镜像失败：#{e.message}"
    end

    def source_mirror_ready_path(key, source_path, signature)
      target = mirror_cache_path(key, source_path, signature)
      return '' unless File.file?(target) && File.file?(source_path)
      expected_size = File.size(source_path)
      return '' unless expected_size.positive? && File.size(target) == expected_size
      source_content = sampled_file_content_signature(source_path)
      return '' if source_content.empty? || sampled_file_content_signature(target) != source_content
      target
    rescue StandardError
      ''
    end

    def space_mirror_key(item)
      id = item.is_a?(Hash) ? item['id'].to_s : item.to_s
      "space_#{id.gsub(/[^0-9A-Za-z]/, '')[0, 12]}"
    end

    def schedule_space_mirror_prefetch(item, source_path, signature, model = Sketchup.active_model)
      return false if @shutting_down || publish_critical_section?
      return false unless item.is_a?(Hash) && File.file?(source_path)
      return true unless source_mirror_ready_path(space_mirror_key(item), source_path, signature).empty?
      touched_age = Time.now.to_f - File.mtime(source_path).to_f
      return false if touched_age >= 0 && touched_age < 1.2
      @space_mirror_prefetch_mutex ||= Mutex.new
      @space_mirror_prefetch_queue ||= []
      @space_mirror_prefetch_queued ||= {}
      token = [space_mirror_key(item), FastPath.expand(source_path), signature.to_s].join('|')
      start_worker = false
      @space_mirror_prefetch_mutex.synchronize do
        return true if @space_mirror_prefetch_queued[token]
        @space_mirror_prefetch_queued[token] = true
        @space_mirror_prefetch_queue << {
          token: token,
          key: space_mirror_key(item),
          source: FastPath.expand(source_path),
          signature: signature.to_s,
          label: "#{item['number']}:#{item['name']}"
        }
        start_worker = !(@space_mirror_prefetch_thread && @space_mirror_prefetch_thread.alive?)
      end
      start_space_mirror_prefetch_worker! if start_worker
      true
    rescue StandardError => e
      log_exception('安排空间本地镜像预取失败', e)
      false
    end

    def start_space_mirror_prefetch_worker!
      return false if @shutting_down
      @space_mirror_prefetch_mutex ||= Mutex.new
      @space_mirror_prefetch_queue ||= []
      @space_mirror_prefetch_queued ||= {}
      created = false
      @space_mirror_prefetch_mutex.synchronize do
        return true if @space_mirror_prefetch_thread && @space_mirror_prefetch_thread.alive?
        @space_mirror_prefetch_thread = Thread.new do
          Thread.current.name = 'SU_LinkHub-space-prefetch' if Thread.current.respond_to?(:name=)
          loop do
            job = nil
            @space_mirror_prefetch_mutex.synchronize { job = @space_mirror_prefetch_queue.shift }
            break unless job
            begin
              break if @shutting_down
              target = stage_source_mirror(job[:key], job[:source], job[:signature])
              log("空间本地镜像预取完成：#{job[:label]} / #{File.basename(target)}")
            rescue SyncDeferredError => e
              log("空间本地镜像预取延后：#{job[:label]} / #{e.message}")
            rescue StandardError => e
              log_exception("空间本地镜像预取失败：#{job[:label]}", e)
            ensure
              @space_mirror_prefetch_mutex.synchronize { @space_mirror_prefetch_queued.delete(job[:token]) }
            end
          end
        ensure
          restart = false
          @space_mirror_prefetch_mutex.synchronize do
            @space_mirror_prefetch_thread = nil if Thread.current == @space_mirror_prefetch_thread
            # 修复“队列刚入项而旧线程恰好退出”的窄窗口，确保任务不会永久滞留。
            restart = !@shutting_down && !@space_mirror_prefetch_queue.empty?
          end rescue nil
          start_space_mirror_prefetch_worker! if restart
        end
        register_background_gvl_thread!(@space_mirror_prefetch_thread)
        created = true
      end
      created || true
    rescue StandardError => e
      log_exception('启动空间本地镜像预取线程失败', e)
      false
    end

    def stop_space_mirror_prefetch_worker!
      @space_mirror_prefetch_mutex ||= Mutex.new
      @space_mirror_prefetch_mutex.synchronize do
        @space_mirror_prefetch_queue = []
        @space_mirror_prefetch_queued = {}
      end
      thread = @space_mirror_prefetch_thread
      if thread && thread.alive? && thread != Thread.current
        thread.join(1.5)
        log('空间镜像预取线程仍在完成当前文件；已清空后续队列。') if thread.alive?
      end
      @space_mirror_prefetch_thread = nil unless thread&.alive?
      true
    rescue StandardError => e
      log_exception('停止空间本地镜像预取线程失败', e)
      false
    end

    def preferred_space_load_path(item, source_path, signature, model = Sketchup.active_model)
      key = space_mirror_key(item)
      cached = source_mirror_ready_path(key, source_path, signature)
      unless cached.empty?
        log("空间载入命中本地镜像：#{item['number']}:#{item['name']}")
        return cached
      end

      # SketchUp 直接从 SMB/映射盘解析 SKP 会产生大量随机网络读取。第一次点击更新时，
      # 先顺序复制一次再从本机解析，通常比“边联网边解析”更快、更稳定。后台预取若正在
      # 处理同一文件，会通过文件级互斥与这里汇合，不会发生双重复制。
      started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      cached = stage_source_mirror(key, source_path, signature)
      elapsed = ((Process.clock_gettime(Process::CLOCK_MONOTONIC) - started) * 1000.0).round
      log("空间首次载入本地镜像就绪：#{item['number']}:#{item['name']} / #{elapsed}ms")
      cached
    rescue SyncDeferredError
      raise
    rescue StandardError => e
      log("空间本地镜像不可用，回退源文件直读：#{item['number']}:#{item['name']} / #{e.message}")
      schedule_space_mirror_prefetch(item, source_path, signature, model)
      source_path
    end

    def reference_package_path_for(source_path)
      base = source_path.to_s.sub(/\.skp\z/i, '')
      "#{base}#{REFERENCE_PACKAGE_SUFFIX}"
    end

    def legacy_reference_meta_path_for(source_path)
      legacy_metadata_path(source_path, REFERENCE_META_SUFFIX, strip_skp: true)
    end

    def reference_meta_path_for(source_path)
      stem = File.basename(source_path.to_s).sub(/\.skp\z/i, '')
      metadata_file_path(source_path, 'references', "#{stem}#{REFERENCE_META_SUFFIX}")
    end

    def read_reference_meta(source_path)
      path = reference_meta_path_for(source_path)
      path = metadata_read_path(path, legacy_reference_meta_path_for(source_path))
      return nil unless File.file?(path)
      JSON.parse(File.read(path, mode: 'rb'))
    rescue StandardError => e
      log_exception('读取参考包清单失败', e)
      nil
    end

    def valid_reference_package(source_path, source_signature_value = nil)
      package = reference_package_path_for(source_path)
      meta = read_reference_meta(source_path)
      return nil unless File.file?(package) && meta.is_a?(Hash)
      signature = source_signature_value.to_s.empty? ? fast_file_signature(source_path) : source_signature_value.to_s
      return nil unless meta['source_signature'].to_s == signature
      return nil unless File.size(package).positive?
      { path: package, meta: meta }
    rescue StandardError
      nil
    end

    def layer_and_folder_visible?(layer)
      return true unless layer
      return false if layer.respond_to?(:visible?) && !layer.visible?
      folder = layer.respond_to?(:folder) ? layer.folder : nil
      while folder
        return false if folder.respond_to?(:visible?) && !folder.visible?
        folder = folder.respond_to?(:folder) ? folder.folder : nil
      end
      true
    rescue StandardError
      true
    end

    def root_entity_visible?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid?
      return false if entity.respond_to?(:hidden?) && entity.hidden?
      return false unless layer_and_folder_visible?(entity.respond_to?(:layer) ? entity.layer : nil)
      if model.respond_to?(:drawing_element_visible?) && defined?(Sketchup::InstancePath)
        begin
          return !!model.drawing_element_visible?(Sketchup::InstancePath.new([entity]))
        rescue StandardError
          # Fall back to direct visibility checks above.
        end
      end
      entity.respond_to?(:visible?) ? entity.visible? : true
    rescue StandardError
      false
    end

    # Create a dedicated reference package from the source model while it is already open.
    # Only currently visible top-level groups/components are included. This shifts the expensive
    # filtering work to publish time and lets downstream models load a much smaller SKP.
    def publish_current_visible_reference_package
      model = Sketchup.active_model
      source_path = model.path.to_s
      raise '请先保存当前源模型，再生成参考包。' if source_path.empty?
      raise '当前模型正在组件编辑层级内，请先退出组件编辑。' unless model_safe_for_reload?(model)

      saved = model.save
      raise '源模型保存失败，未生成参考包。' unless saved || File.file?(source_path)

      visible_tags = model.layers.to_a.select { |layer| layer != model.layers[0] && layer_and_folder_visible?(layer) }.map { |layer| layer.name.to_s }.sort
      candidates = model.entities.to_a.select do |entity|
        (entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)) &&
          root_entity_visible?(entity, model) && !plugin_managed_reference?(entity)
      end
      raw_count = model.entities.grep(Sketchup::Face).length + model.entities.grep(Sketchup::Edge).length
      raise '当前可见根层级没有可发布的群组或组件。请把需要参考的内容放入群组/组件并设置标记。' if candidates.empty?

      package_definition = model.definitions.add("LH_REF_PACKAGE_#{SecureRandom.hex(6)}")
      candidates.each do |entity|
        copied = package_definition.entities.add_instance(entity.definition, entity.transformation)
        copied.name = entity.name.to_s if copied.respond_to?(:name=) && entity.respond_to?(:name)
        copied.layer = entity.layer if copied.respond_to?(:layer=) && entity.respond_to?(:layer)
      end

      package_path = reference_package_path_for(source_path)
      temp_path = package_path.sub(/\.skp\z/i, ".tmp_#{Process.pid}_#{SecureRandom.hex(4)}.skp")
      File.delete(temp_path) if File.file?(temp_path)
      saved_package = if package_definition.respond_to?(:save_copy)
                        package_definition.save_copy(temp_path)
                      else
                        package_definition.save_as(temp_path)
                      end
      raise 'SketchUp 未能写出参考包。' unless saved_package || File.file?(temp_path)
      File.delete(package_path) if File.file?(package_path)
      File.rename(temp_path, package_path)

      model.definitions.remove(package_definition) if package_definition.valid? && model.definitions.respond_to?(:remove)
      # Removing the temporary definition changes the source model; save once more so its
      # final signature is stable. The package geometry still matches because only the temp
      # definition itself changed between the two saves.
      model.save
      final_signature = fast_file_signature(source_path)
      meta = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'world_normalized' => true,
        'world_frame' => identity_transformation_array,
        'source_path' => source_path,
        'source_signature' => final_signature,
        'generated_at' => Time.now.iso8601,
        'visible_tags' => visible_tags,
        'top_level_instances' => candidates.length,
        'root_raw_geometry_skipped' => raw_count
      }
      meta_path = reference_meta_path_for(source_path)
      ensure_metadata_target!(meta_path)
      File.write(meta_path, JSON.pretty_generate(meta), mode: 'wb')
      retire_legacy_metadata_file(legacy_reference_meta_path_for(source_path), meta_path)
      message = "参考包已生成：#{File.basename(package_path)}，包含#{candidates.length}个可见根层级对象"
      message = "#{message}；另有#{raw_count}条根层级原始边/面未打包" if raw_count.positive?
      show_status(message, raw_count.positive? ? 'error' : 'success')
      true
    rescue StandardError => e
      begin
        File.delete(temp_path) if defined?(temp_path) && File.file?(temp_path)
        model.definitions.remove(package_definition) if defined?(package_definition) && package_definition && package_definition.valid? && model.definitions.respond_to?(:remove)
      rescue StandardError
        nil
      end
      log_exception('生成当前模型参考包失败', e)
      raise e
    end

    def choose_load_asset(key, link, source_path, source_signature_value)
      if link['prefer_reference_package']
        package = valid_reference_package(source_path, source_signature_value)
        if package
          return {
            path: package[:path],
            type: 'reference',
            label: '筛选参考包',
            signature: fast_file_signature(package[:path]),
            meta: package[:meta]
          }
        end
      end

      if link['sync_strategy'].to_s == 'mirror'
        mirror = stage_source_mirror(key, source_path, source_signature_value)
        return { path: mirror, type: 'mirror', label: '本地镜像', signature: fast_file_signature(mirror), meta: nil }
      end

      # Direct loading avoids the old double I/O path (copy once, parse once). For manual
      # clicks during an active save, defer briefly instead of reading a half-written SKP.
      touched_age = Time.now.to_f - File.mtime(source_path).to_f
      raise SyncDeferredError, '源 SKP 刚刚发生写入，请稍后再点一次更新。' if touched_age >= 0 && touched_age < 1.2
      { path: source_path, type: 'direct', label: '源文件直读', signature: source_signature_value, meta: nil }
    end

    def strip_root_section_planes!(definition)
      return 0 unless defined?(Sketchup::SectionPlane)
      planes = definition.entities.grep(Sketchup::SectionPlane)
      planes.each { |plane| plane.erase! if plane.valid? }
      planes.length
    rescue StandardError => e
      log_exception('剔除链接模型剖面失败', e)
      0
    end

    def container_tag_catalog_profile(definition, limit = LINK_TAG_SCAN_LIMIT_NORMAL)
      names = {}
      visited = {}
      queue = [definition]
      scanned = 0
      until queue.empty? || scanned >= limit.to_i
        current = queue.shift
        next unless current && current.valid?
        id = current.object_id
        next if visited[id]
        visited[id] = true
        current.entities.each do |entity|
          next unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
          scanned += 1
          layer = entity.layer if entity.respond_to?(:layer)
          name = layer.name.to_s if layer
          names[name] = true unless name.to_s.empty? || name == 'Layer0' || name == 'Untagged'
          queue << entity.definition if entity.respond_to?(:definition)
          break if scanned >= limit.to_i
        end
      end
      { names: names.keys.sort, scanned: scanned, truncated: !queue.empty? || scanned >= limit.to_i }
    rescue StandardError => e
      log_exception('读取链接模型容器标记失败', e)
      { names: [], scanned: 0, truncated: false }
    end

    def container_tag_catalog(definition, limit = LINK_TAG_SCAN_LIMIT_NORMAL)
      container_tag_catalog_profile(definition, limit)[:names]
    end

    def definition_selected_branch?(definition, selected, memo, visiting)
      key = definition.object_id
      return memo[key] if memo.key?(key)
      return false if visiting[key]
      visiting[key] = true
      matched = definition.entities.any? do |entity|
        next false unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
        own = selected.include?(entity.layer.name.to_s)
        own || definition_selected_branch?(entity.definition, selected, memo, visiting)
      end
      visiting.delete(key)
      memo[key] = matched
      matched
    rescue StandardError
      false
    end

    # Additional display filter. It only hides container branches and never unhides source-hidden
    # objects. Therefore it is safe for normal SketchUp modelling where tags are assigned to
    # groups/components. A reload restores the unfiltered source state.
    def apply_container_display_filter!(definition, selected_names)
      selected = Array(selected_names).map(&:to_s).to_h { |name| [name, true] }
      return 0 if selected.empty?
      memo = {}
      hidden_count = 0
      visited = {}
      queue = [definition]
      until queue.empty?
        current = queue.shift
        next unless current && current.valid?
        id = current.object_id
        next if visited[id]
        visited[id] = true
        current.entities.each do |entity|
          next unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
          own = selected.key?(entity.layer.name.to_s)
          descendant = definition_selected_branch?(entity.definition, selected, memo, {})
          unless own || descendant
            unless entity.hidden?
              entity.hidden = true
              hidden_count += 1
            end
            next
          end
          queue << entity.definition unless own
        end
      end
      hidden_count
    rescue StandardError => e
      log_exception('应用仅显示标记失败', e)
      0
    end

    def newer_model_version_error?(error)
      message = error.message.to_s.downcase
      message.include?('newer model version') || message.include?('allow_newer') ||
        message.include?('较新版本') || message.include?('更高版本')
    rescue StandardError
      false
    end

    # SketchUp 2024 can read a component saved by a newer SketchUp release only when
    # DefinitionList#load receives allow_newer: true. We first use the normal path so
    # same-version files keep the fastest path; only a confirmed version mismatch retries.
    def load_definition_compat(definitions, path)
      loaded_from_newer = false
      definition = begin
        definitions.load(path)
      rescue StandardError => error
        raise unless newer_model_version_error?(error)

        loaded_from_newer = true
        definitions.load(path, allow_newer: true)
      end
      raise '模型定义载入失败。' unless definition
      definition.set_attribute(ENTITY_DICT, 'loaded_from_newer_version', loaded_from_newer)
      definition
    end

    def definition_loaded_from_newer?(definition)
      !!definition.get_attribute(ENTITY_DICT, 'loaded_from_newer_version', false)
    rescue StandardError
      false
    end

    def model_safe_for_reload?(model = Sketchup.active_model)
      path = model.respond_to?(:active_path) ? model.active_path : nil
      path.nil? || path.empty?
    rescue StandardError
      true
    end

    # 同步定义前后保护协调模型当前相机与已选场景，避免原位 reload 后视角跳变。
    # 这里只保护协调模型的视图；源模型场景由 v0.5.2 的“原生源文件编辑”完整保留。
    def capture_active_view_state(model = Sketchup.active_model)
      camera = model.active_view.camera
      selected_page = model.pages.respond_to?(:selected_page) ? model.pages.selected_page : nil
      {
        'page_pid' => (selected_page.respond_to?(:persistent_id) ? selected_page.persistent_id : nil),
        'page_name' => (selected_page.respond_to?(:name) ? selected_page.name.to_s : ''),
        'eye' => camera.eye.to_a,
        'target' => camera.target.to_a,
        'up' => camera.up.to_a,
        'perspective' => !!camera.perspective?,
        'fov' => (camera.respond_to?(:fov) ? camera.fov.to_f : nil),
        'height' => (camera.respond_to?(:height) ? camera.height.to_f : nil),
        'aspect_ratio' => (camera.respond_to?(:aspect_ratio) ? camera.aspect_ratio.to_f : nil)
      }
    rescue StandardError => e
      log_exception('记录同步前视角失败', e)
      nil
    end

    def restore_active_view_state(snapshot, model = Sketchup.active_model)
      return false unless snapshot.is_a?(Hash)

      page = nil
      page_pid = snapshot['page_pid']
      if page_pid && model.pages.respond_to?(:each)
        page = model.pages.find do |candidate|
          candidate.respond_to?(:persistent_id) && candidate.persistent_id == page_pid
        end
      end
      if !page && !snapshot['page_name'].to_s.empty?
        page = model.pages[snapshot['page_name'].to_s] rescue nil
      end
      model.pages.selected_page = page if page && model.pages.respond_to?(:selected_page=)

      eye = Geom::Point3d.new(snapshot['eye'])
      target = Geom::Point3d.new(snapshot['target'])
      up = Geom::Vector3d.new(snapshot['up'])
      camera = Sketchup::Camera.new(eye, target, up, !!snapshot['perspective'])
      if snapshot['perspective']
        camera.fov = snapshot['fov'].to_f if camera.respond_to?(:fov=) && snapshot['fov']
      else
        camera.height = snapshot['height'].to_f if camera.respond_to?(:height=) && snapshot['height']
      end
      ratio = snapshot['aspect_ratio'].to_f
      camera.aspect_ratio = ratio if camera.respond_to?(:aspect_ratio=) && ratio.positive?
      model.active_view.camera = camera
      model.active_view.invalidate
      true
    rescue StandardError => e
      log_exception('恢复同步前视角失败', e)
      false
    end

    def entity_layer_name(entity)
      layer = entity.respond_to?(:layer) ? entity.layer : nil
      layer ? layer.name.to_s : ''
    rescue StandardError
      ''
    end

    def entity_definition_path(entity)
      return '' unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
      definition = entity.definition
      return '' unless definition && definition.respond_to?(:path)
      definition.path.to_s
    rescue StandardError
      ''
    end

    def legacy_linkhub_reference?(entity)
      return false unless entity && entity.valid?
      discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
      kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
      source = entity.get_attribute(ENTITY_DICT, 'source', '').to_s
      attr_signal = DISCIPLINES.key?(discipline) && %w[model skp].include?(kind) && !source.empty?
      return true if attr_signal

      layer_name = entity_layer_name(entity)
      managed_layers = DISCIPLINES.values.flat_map { |item| [item['model_tag'], item['legacy_tag']] }
      layer_signal = managed_layers.include?(layer_name) || layer_name.start_with?('LH_')
      name = entity.respond_to?(:name) ? entity.name.to_s : ''
      definition_name = if entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
                          entity.definition.name.to_s
                        else
                          ''
                        end
      name_signal = name.start_with?('LH ') || name.start_with?('LH_') || definition_name.start_with?('LH_WORLD_')
      layer_signal && name_signal
    rescue StandardError
      false
    end

    def plugin_managed_reference?(entity)
      return false unless entity && entity.valid?
      return true if entity.respond_to?(:get_attribute) && entity.get_attribute(ENTITY_DICT, 'managed', false)
      if entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
        return true if world_wrapper_definition?(entity.definition)
      end
      legacy_linkhub_reference?(entity)
    rescue StandardError
      false
    end

    def dependency_path_map(source_model_path)
      read_sidecar_dependencies(source_model_path).each_with_object({}) do |item, memo|
        resolved = item['resolved_path'].to_s
        next if resolved.empty?
        memo[FastPath.expand(resolved).tr('\\', '/').downcase] = item
      rescue StandardError
        next
      end
    end

    def embedded_reference_match(entity, source_model_path, dependency_map)
      return [:managed, nil] if plugin_managed_reference?(entity)
      definition_path = entity_definition_path(entity)
      unless definition_path.empty?
        normalized = FastPath.expand(definition_path).tr('\\', '/').downcase rescue definition_path.downcase
        source_normalized = FastPath.expand(source_model_path.to_s).tr('\\', '/').downcase rescue source_model_path.to_s.downcase
        return [:dependency_path, dependency_map[normalized]] if normalized != source_normalized && dependency_map.key?(normalized)
      end
      [nil, nil]
    rescue StandardError
      [nil, nil]
    end

    def strip_embedded_references!(definition, source_model_path)
      dependencies = read_sidecar_dependencies(source_model_path)
      dependency_map = dependency_path_map(source_model_path)
      visited_definitions = { definition.object_id => true }
      stats = { removed: 0, scanned: 0, removed_definitions: [] }
      strip_embedded_references_from_entities!(
        definition.entities,
        source_model_path,
        dependencies,
        visited_definitions,
        dependency_map,
        stats
      )
      Array(stats[:removed_definitions]).compact.uniq.reverse_each do |removed_definition|
        next unless removed_definition.valid?
        next unless removed_definition.respond_to?(:instances) && removed_definition.instances.empty?
        next if removed_definition == definition
        Sketchup.active_model.definitions.remove(removed_definition) if Sketchup.active_model.definitions.respond_to?(:remove)
      rescue StandardError
        next
      end
      definition.set_attribute(ENTITY_DICT, 'stripped_reference_count', stats[:removed]) if definition && definition.valid?
      log("循环联动净化：扫描#{stats[:scanned]}个容器，剔除#{stats[:removed]}个引用") if stats[:removed].positive?
      deduplicate_dependencies(dependencies)
    rescue StandardError => e
      log_exception('递归剔除联动引用失败', e)
      deduplicate_dependencies(read_sidecar_dependencies(source_model_path) + Array(dependencies))
    end

    def strip_embedded_references_from_entities!(entities, source_model_path, dependencies, visited_definitions, dependency_map, stats)
      candidates = []
      candidates.concat(entities.grep(Sketchup::Group))
      candidates.concat(entities.grep(Sketchup::ComponentInstance))
      candidates.uniq.each do |entity|
        next unless entity.valid?
        stats[:scanned] += 1
        match_type, matched_dependency = embedded_reference_match(entity, source_model_path, dependency_map)

        if match_type
          discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
          kind = entity.get_attribute(ENTITY_DICT, 'kind', '').to_s
          source = entity.get_attribute(ENTITY_DICT, 'source', '').to_s
          if DISCIPLINES.key?(discipline) && !source.empty? && %w[model skp].include?(kind)
            dependencies << dependency_record(discipline, 'model', source, source_model_path, "embedded-#{match_type}")
          elsif matched_dependency
            dependencies << matched_dependency.merge('origin' => "embedded-#{match_type}")
          end
          removed_definition = entity.definition if entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
          entity.locked = false if entity.respond_to?(:locked=)
          entity.erase! if entity.valid?
          stats[:removed_definitions] << removed_definition if removed_definition
          stats[:removed] += 1
          next
        end

        child_definition = entity.definition
        child_id = child_definition.object_id
        next if visited_definitions[child_id]
        visited_definitions[child_id] = true
        strip_embedded_references_from_entities!(
          child_definition.entities,
          source_model_path,
          dependencies,
          visited_definitions,
          dependency_map,
          stats
        )
      end
    rescue StandardError => e
      log_exception('内嵌引用递归净化失败', e)
    end

    # Collaboration publish cache: FULL + manifest
    # -------------------------

    def project_dir_for_model(model = Sketchup.active_model)
      source_path = model && model.respond_to?(:path) ? model.path.to_s : ''
      raise '请先保存当前 SketchUp 模型，再使用协同缓存。' if source_path.empty?
      FastPath.expand(File.dirname(source_path))
    end

    def project_collab_root_for_dir(project_dir)
      File.join(FastPath.expand(project_dir.to_s), COLLAB_FOLDER_NAME)
    end

    def collaboration_root_from_asset_path(path)
      current = File.dirname(FastPath.expand(path.to_s))
      loop do
        return current if File.basename(current).casecmp(COLLAB_FOLDER_NAME).zero?
        parent = File.dirname(current)
        break if parent == current
        current = parent
      end
      ''
    rescue StandardError
      ''
    end

    def collaboration_layout_notice_content
      <<~TEXT
        此目录由 SU LinkHub 自动维护，请勿在协作过程中手动改名或移动正在使用的文件。

        目录层级：
        - architecture / landscape：各专业当前有效 FULL.skp 与 manifest.json。
        - 软装+硬装：当前有效空间 SKP 与 空间模型.json。
        - *.sulink.lock.json：成员修改期间的临时占用文件，发布或退出后自动移除。
        - _冲突保护：仅在检测到并发覆盖风险时保存本地待合并候选，不属于日常历史。
        - _协作锁归档：仅保存损坏或过期锁的少量 JSON 诊断记录。

        正常发布使用临时候选与瞬时回滚安全替换当前有效 SKP；每个对象只轮换保留最近 #{PUBLISH_HISTORY_KEEP} 个历史版本，不会无限累计。
      TEXT
    end

    def ensure_collaboration_layout_notice!(project_dir)
      root = project_collab_root_for_dir(project_dir)
      FileUtils.mkdir_p(root)
      notice = File.join(root, METADATA_NOTICE_NAME)
      content = collaboration_layout_notice_content
      current = File.file?(notice) ? File.read(notice, mode: 'r:UTF-8') : ''
      File.write(notice, content, mode: 'w:UTF-8') if current != content && (current.empty? || current.start_with?('此目录由 SU LinkHub 自动维护'))
      notice
    rescue StandardError => e
      log_exception('写入协同目录说明失败', e)
      ''
    end

    def project_collab_json_for_dir(project_dir)
      File.join(FastPath.expand(project_dir.to_s), PROJECT_COLLAB_FILE)
    end

    def resolve_collab_dir_value(value, model = Sketchup.active_model)
      text = value.to_s.strip
      return '' if text.empty?
      resolved = resolve_path(text, model)
      resolved = File.dirname(resolved) if File.basename(resolved).casecmp(PROJECT_COLLAB_FILE).zero? || File.extname(resolved).downcase == '.json'
      FastPath.expand(resolved)
    rescue StandardError
      text
    end

    def resolve_collab_json_value(value, model = Sketchup.active_model)
      text = value.to_s.strip
      return '' if text.empty?
      resolved = resolve_path(text, model)
      resolved = project_collab_json_for_dir(resolved) if File.directory?(resolved)
      FastPath.expand(resolved)
    rescue StandardError
      text
    end

    def selected_collab_project_dir_for_state(state, model = Sketchup.active_model)
      state = load_state(model) unless state.is_a?(Hash)
      raw_dir = state['collab_project_dir'].to_s
      dir = resolve_collab_dir_value(raw_dir, model)
      return dir unless dir.empty?

      raw_json = state['collab_project_json'].to_s
      json = resolve_collab_json_value(raw_json, model)
      return File.dirname(json) unless json.empty?

      state.fetch('links', {}).each_value do |link|
        json = resolve_collab_json_value(link['collab_project_manifest_path'].to_s, model) rescue ''
        return File.dirname(json) unless json.to_s.empty?
      end
      ''
    rescue StandardError
      ''
    end

    def collab_project_dir_for_model(model = Sketchup.active_model, state = nil, require_configured: false)
      state ||= load_state(model)
      dir = selected_collab_project_dir_for_state(state, model)
      unless dir.empty?
        FileUtils.mkdir_p(dir)
        return FastPath.expand(dir)
      end
      raise "请先点击“连接协同”，选择共享项目目录或 #{PROJECT_COLLAB_FILE}。" if require_configured
      project_dir_for_model(model)
    end

    def project_collab_json_for_model(model = Sketchup.active_model, state = nil)
      project_collab_json_for_dir(collab_project_dir_for_model(model, state))
    end

    def collab_cache_dir_for(key, model = Sketchup.active_model, state = nil)
      dir = File.join(project_collab_root_for_dir(collab_project_dir_for_model(model, state)), key.to_s)
      FileUtils.mkdir_p(dir)
      dir
    end

    def collab_cache_paths_for(key, model = Sketchup.active_model, state = nil)
      dir = collab_cache_dir_for(key, model, state)
      project_dir = collab_project_dir_for_model(model, state)
      {
        project_manifest: project_collab_json_for_dir(project_dir),
        manifest: File.join(dir, 'manifest.json'),
        full: File.join(dir, "#{key}_FULL.skp")
      }
    end

    def ensure_empty_project_collab_manifest!(project_dir, model = Sketchup.active_model, state = nil)
      project_dir = FastPath.expand(project_dir.to_s)
      FileUtils.mkdir_p(project_dir)
      json_path = project_collab_json_for_dir(project_dir)
      with_project_collab_write_lock(json_path) do
        return json_path if File.file?(json_path) && project_collab_manifest_file?(json_path)
        raise "#{PROJECT_COLLAB_FILE} 已存在但不是 SU LinkHub 项目协同清单：#{json_path}" if File.file?(json_path)

        payload = {
          'schema' => PROJECT_COLLAB_SCHEMA,
          'kind' => 'sulink_collab_project',
          'plugin_version' => EXTENSION_VERSION,
          'project_dir' => '',
          'project_dir_hint' => project_dir,
          'collab_dir' => COLLAB_FOLDER_NAME,
          'updated_at' => Time.now.iso8601,
          'settings' => {
            'schema' => PROJECT_SETTINGS_SCHEMA,
            'updated_at' => '',
            'updated_by' => '',
            'host' => '',
            'paths' => {}
          },
          'disciplines' => {}
        }
        temp = "#{json_path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
        linkhub_mv(temp, json_path)
      ensure
        begin
          File.delete(temp) if defined?(temp) && temp && File.file?(temp)
        rescue StandardError
          nil
        end
      end
      json_path
    end

    def set_collab_project_location!(state, path_or_dir, model = Sketchup.active_model)
      raw = path_or_dir.to_s
      raise '请选择共享项目目录或 协同.json。' if raw.empty?
      json_path = File.directory?(raw) ? project_collab_json_for_dir(raw) : FastPath.expand(raw)
      project_dir = File.directory?(raw) ? FastPath.expand(raw) : File.dirname(json_path)
      json_path = ensure_empty_project_collab_manifest!(project_dir, model, state) unless File.file?(json_path)
      state['collab_project_dir'] = store_path(project_dir, model)
      state['collab_project_json'] = store_path(json_path, model)
      json_path
    end

    def prepare_collab_project_structure!(state, project_dir, model = Sketchup.active_model, create_if_missing: true)
      dir = FastPath.expand(project_dir.to_s)
      raise '协同项目文件夹无效。' if dir.empty?
      FileUtils.mkdir_p(dir)
      json_path = project_collab_json_for_dir(dir)
      if File.file?(json_path)
        raise "#{PROJECT_COLLAB_FILE} 不是有效的 SU LinkHub 协同清单：#{json_path}" unless project_collab_manifest_file?(json_path)
      elsif create_if_missing
        json_path = ensure_empty_project_collab_manifest!(dir, model, state)
      else
        raise "所选文件夹里没有 #{PROJECT_COLLAB_FILE}。新项目请点击“新建”，由插件自动创建。"
      end

      state['collab_project_dir'] = store_path(dir, model)
      state['collab_project_json'] = store_path(json_path, model)
      FileUtils.mkdir_p(project_collab_root_for_dir(dir))
      ensure_collaboration_layout_notice!(dir)
      normalize_space_models_state!(state, model)
      assets_dir = space_models_assets_dir(state, model)
      FileUtils.mkdir_p(assets_dir) unless assets_dir.to_s.empty?
      write_space_models_manifest!(state, model) unless File.file?(space_models_manifest_path(state, model))
      json_path
    end

    def create_collab_project_interactive!(state = nil, model = Sketchup.active_model)
      state ||= load_state(model)

      # 新建协同项目只需要确定“协同.json”的保存位置。
      # 当前 SKP 是否命名、是否保存，与创建项目清单及按空间发布无关，不能作为前置条件。
      selected_path = UI.savepanel(
        "新建协同项目：保存 #{PROJECT_COLLAB_FILE}",
        nil,
        PROJECT_COLLAB_FILE
      )
      return '' if selected_path.nil? || selected_path.to_s.empty?

      # 项目清单使用固定文件名。即使用户在保存窗口改了名称，也以其所选文件夹为项目根目录，
      # 最终写入该目录下的“协同.json”，避免连接端因文件名不一致而找不到项目。
      dir = FastPath.expand(File.dirname(selected_path.to_s))
      json_path = project_collab_json_for_dir(dir)
      existing = File.file?(json_path)
      if existing && !project_collab_manifest_file?(json_path)
        raise "#{PROJECT_COLLAB_FILE} 已存在但不是有效的 SU LinkHub 协同清单：#{json_path}"
      end

      json_path = prepare_collab_project_structure!(state, dir, model, create_if_missing: true)
      reset_workspace_selection!(state)
      applied = apply_collab_project_manifest!(state, json_path, allow_empty: true)
      sync_space_models_from_manifest!(state, model)
      if state['project_name'].to_s.empty? || state['project_name'].to_s == '未命名项目'
        state['project_name'] = File.basename(dir)
      end

      # 这里只把连接状态写入当前模型的属性内存，不触发 model.save，也不要求生成 SKP 文件。
      # 用户以后主动保存当前 SKP 时，这些属性会随模型一同保存；即使不保存，也可凭协同.json重新连接。
      save_state(state, model, write_manifest: false)
      refresh_dialog
      names = applied.map { |item| DISCIPLINES[item]['name'] }.join('、')
      if existing
        message = applied.empty? ? "已连接现有协同项目：#{json_path}。当前暂无专业缓存。" : "已连接现有协同项目：#{names}；#{json_path}。"
      else
        message = "已保存 #{PROJECT_COLLAB_FILE}：#{json_path}；并创建协同数据目录和空的空间模型清单。当前 SKP 无需先保存。"
      end
      show_status(message, 'success')
      json_path
    end

    def ensure_collab_project_ready!(state = nil, model = Sketchup.active_model, interactive: true)
      state ||= load_state(model)
      dir = selected_collab_project_dir_for_state(state, model)
      unless dir.to_s.empty?
        prepare_collab_project_structure!(state, dir, model, create_if_missing: true)
        save_state(state, model, write_manifest: false)
        return FastPath.expand(dir)
      end
      return '' unless interactive
      json_path = create_collab_project_interactive!(state, model)
      json_path.to_s.empty? ? '' : File.dirname(json_path)
    end

    def relative_to_project(path, project_dir)
      Pathname.new(FastPath.expand(path)).relative_path_from(Pathname.new(FastPath.expand(project_dir))).to_s.tr('\\', '/')
    rescue StandardError
      File.basename(path.to_s)
    end

    def project_collab_manifest_file?(path)
      return false unless File.file?(path.to_s)
      return false unless File.basename(path.to_s).casecmp(PROJECT_COLLAB_FILE).zero? || File.extname(path.to_s).downcase == '.json'
      data = JSON.parse(File.read(path, mode: 'rb'))
      data.is_a?(Hash) && data['schema'].to_i == PROJECT_COLLAB_SCHEMA && data['kind'].to_s == 'sulink_collab_project'
    rescue StandardError
      false
    end

    def collab_cache_manifest_file?(path)
      return false unless File.file?(path.to_s)
      return false unless File.extname(path.to_s).downcase == '.json'
      data = JSON.parse(File.read(path, mode: 'rb'))
      data.is_a?(Hash) && data['schema'].to_i == COLLAB_CACHE_SCHEMA && data['kind'].to_s == 'sulink_collab_cache'
    rescue StandardError
      false
    end

    def resolve_manifest_asset_path(base_dir, value)
      text = value.to_s
      return '' if text.empty?
      candidates = []
      if absolute_file_path?(text) || (Pathname.new(text).absolute? rescue false)
        candidates << (FastPath.expand(text) rescue text)
        # 兼容清单里写死发布者盘符的情况：如果用户从共享目录打开 manifest.json，
        # FULL 文件通常就在该清单同目录下。
        candidates << FastPath.expand(File.basename(text), base_dir)
      else
        candidates << FastPath.expand(text, base_dir)
      end
      candidates.compact.map(&:to_s).reject(&:empty?).uniq.find { |path| File.file?(path) } || candidates.first.to_s
    rescue StandardError
      text
    end

    def read_collab_cache_manifest(path)
      raise '请选择 SU LinkHub 生成的 manifest.json 协同缓存清单。' unless File.file?(path.to_s)
      data = JSON.parse(File.read(path, mode: 'rb'))
      unless data.is_a?(Hash) && data['schema'].to_i == COLLAB_CACHE_SCHEMA && data['kind'].to_s == 'sulink_collab_cache'
        raise '这个 JSON 不是单专业缓存清单。项目总清单请选择项目根目录下的 协同.json。'
      end
      base = File.dirname(path.to_s)
      full = resolve_manifest_asset_path(base, data['full_path'] || data['full'] || data['full_file'])
      raise '协同缓存清单中的 FULL 模型不存在。' unless File.file?(full)
      data.merge(
        'manifest_path' => FastPath.expand(path),
        'full_resolved' => full
      )
    rescue JSON::ParserError
      raise '清单文件不是有效 JSON。请选择 SU LinkHub 生成的 manifest.json。'
    end

    HOST_WORK_MODEL_DISCIPLINES = %w[architecture landscape].freeze unless const_defined?(:HOST_WORK_MODEL_DISCIPLINES, false)

    def host_work_model_discipline?(key)
      HOST_WORK_MODEL_DISCIPLINES.include?(key.to_s)
    end

    def root_group_or_component?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid?
      return false unless entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
      return false if plugin_managed_reference?(entity)
      model.entities.to_a.include?(entity)
    rescue StandardError
      false
    end

    def selected_host_work_model_entities(model = Sketchup.active_model)
      return [] unless model && model.respond_to?(:selection)
      model.selection.to_a.select { |entity| root_group_or_component?(entity, model) }
    rescue StandardError
      []
    end

    def strict_selected_host_work_model_entity(model = Sketchup.active_model)
      return nil unless model && model.respond_to?(:selection)
      selected = model.selection.to_a
      return nil unless selected.length == 1
      entity = selected.first
      root_group_or_component?(entity, model) ? entity : nil
    rescue StandardError
      nil
    end

    def host_work_model_entity(state, key, model = Sketchup.active_model)
      return nil unless host_work_model_discipline?(key)
      link = state.dig('links', key.to_s)
      return nil unless link
      roots = model.entities.to_a.select { |entity| root_group_or_component?(entity, model) }
      pid = link['native_work_entity_pid'].to_i
      if pid.positive?
        found = roots.find do |entity|
          entity.respond_to?(:persistent_id) && entity.persistent_id.to_i == pid
        rescue StandardError
          false
        end
        return found if found && found.valid?
      end
      marked = roots.select do |entity|
        entity.get_attribute(ENTITY_DICT, 'host_work_model', false) == true &&
          entity.get_attribute(ENTITY_DICT, 'host_work_discipline', '').to_s == key.to_s
      rescue StandardError
        false
      end
      marked.length == 1 ? marked.first : nil
    rescue StandardError
      nil
    end

    def host_work_model_selection_ready?(state, key, model = Sketchup.active_model)
      return true if host_work_model_entity(state, key, model)
      !!strict_selected_host_work_model_entity(model)
    rescue StandardError
      false
    end

    def validate_host_work_model_entity!(entity, key, model = Sketchup.active_model)
      name = DISCIPLINES.dig(key.to_s, 'name').to_s
      name = key.to_s if name.empty?
      raise "请选择模型根层级中的一个普通群组或组件，作为#{name}工作模型。" unless root_group_or_component?(entity, model)
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      raise "选中的#{name}工作模型没有有效组件定义。" unless definition && definition.valid?
      foreign = foreign_managed_reference_count(definition, key)
      if foreign.positive?
        raise "选中的#{name}工作模型内部包含 #{foreign} 个其他专业 LinkHub 引用。请把参考模型移到工作模型外部后再发布。"
      end
      entity
    end

    def host_work_model_for_publish!(state, key, model = Sketchup.active_model)
      link = state.dig('links', key.to_s)
      raise '专业不存在。' unless link
      stored = host_work_model_entity(state, key, model)
      return [validate_host_work_model_entity!(stored, key, model), false] if stored

      selected = model.selection.to_a
      discipline_name = DISCIPLINES.dig(key.to_s, 'name').to_s
      if selected.empty?
        raise "首次发布#{discipline_name}前，请先在模型根层级选中一个群组或组件；该对象会被固定为#{discipline_name}工作模型。"
      end
      if selected.length != 1
        raise "首次发布#{discipline_name}只能选择一个群组或组件。当前共选中 #{selected.length} 个对象。"
      end
      entity = strict_selected_host_work_model_entity(model)
      unless entity
        raise "首次发布#{discipline_name}时，选中的对象必须是模型根层级中的普通群组或组件，不能是散线、散面或其他专业参考。"
      end
      [validate_host_work_model_entity!(entity, key, model), true]
    end

    def remember_host_work_model!(state, key, entity, model = Sketchup.active_model)
      return false unless host_work_model_discipline?(key)
      validate_host_work_model_entity!(entity, key, model)
      link = state.dig('links', key.to_s)
      return false unless link
      model.entities.to_a.each do |candidate|
        next unless candidate && candidate.valid? && candidate.respond_to?(:set_attribute)
        next unless candidate.get_attribute(ENTITY_DICT, 'host_work_discipline', '').to_s == key.to_s
        candidate.set_attribute(ENTITY_DICT, 'host_work_model', false) unless candidate == entity
      rescue StandardError
        next
      end
      entity.set_attribute(ENTITY_DICT, 'host_work_model', true)
      entity.set_attribute(ENTITY_DICT, 'host_work_discipline', key.to_s)
      link['native_work_entity_pid'] = entity.respond_to?(:persistent_id) ? entity.persistent_id.to_i : 0
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      link['native_work_entity_definition_guid'] = definition && definition.respond_to?(:guid) ? definition.guid.to_s : ''
      label = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
      label = definition.name.to_s.strip if label.empty? && definition && definition.respond_to?(:name)
      link['native_work_entity_name'] = label
      link['native_work_entity_assigned_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      true
    rescue StandardError => e
      log_exception("记录#{key}工作模型失败", e)
      false
    end

    def managed_collaboration_flag_key(key)
      key.to_s == 'architecture' ? 'architecture_collab_managed' : 'landscape_collab_managed'
    end

    # 建筑/景观首次发布成功后，不再从共享 FULL 重新载入一次。
    # 直接用当前选定工作模型在内存中建立与共享 FULL 等价的受管根组件，
    # 保持画面、位置和当前编辑连续性；随后立即取得协作占用并进入修改状态。
    def takeover_published_host_work_model!(state, key, work_model_entity, model = Sketchup.active_model)
      discipline = key.to_s
      return false unless host_work_model_discipline?(discipline)
      return false unless host_discipline_for(state) == discipline
      return true if discipline_managed_collaboration?(state, discipline, model)
      raise '首次发布的工作模型已经失效，无法进入协作修改状态。' unless work_model_entity && work_model_entity.valid?

      link = state.dig('links', discipline)
      raise '专业状态不存在。' unless link
      full = resolve_path(link['collab_full_path'].to_s, model)
      raise "#{link['name']}共享 FULL 不存在，无法完成首次发布。" unless File.file?(full)

      flag_key = managed_collaboration_flag_key(discipline)
      source_signature = fast_file_signature(full)
      lock_acquired_here = false
      operation_open = false

      # 首次发布完成后继续由发布者占用，避免刚发布就被界面误判成“有更新”。
      lock_info = source_lock_info(full, link, model, state)
      if lock_info['exists'] && !lock_info['stale'] && !lock_info['owned']
        lock_info = force_takeover_same_user_source_lock!(discipline, link, full, state, model) if lock_info['same_user_recoverable']
        unless lock_info && lock_info['owned']
          owner = lock_info && !lock_info['owner'].to_s.empty? ? lock_info['owner'].to_s : '其他成员'
          raise "#{owner} 已取得#{link['name']}协作占用，首次发布已写出但无法继续进入修改。"
        end
      end
      unless lock_info['owned']
        record = acquire_source_lock(discipline, link, full, state)
        assign_lock_state!(link, record, source_signature)
        lock_acquired_here = true
      end

      structure = ensure_professional_structure(discipline, model)
      model.start_operation("首次发布#{link['name']}并继续修改", true)
      operation_open = true

      # save_collab_full_only_cache! 写出的 FULL 本质上是“根实例及其世界变换”的定义。
      # 这里在内存中建立同样的定义，再套入绝对世界 wrapper；不读取磁盘 SKP，
      # 因而不会出现首次发布后还要点击下载/更新、或者重新解析一次模型的停顿。
      full_definition = model.definitions.add("LH_COLLAB_#{DISCIPLINES.dig(discipline, 'code')}_LIVE_#{SecureRandom.hex(5)}")
      add_publishable_entities_to_definition!(full_definition, [work_model_entity])
      # Sketchup::Entities 在 SU 2024-2026 中不是 Ruby Array，不提供 empty?。
      # v0.9.41/0.9.42 在 FULL 已经写出后走到这里会抛出 NoMethodError，
      # 造成“协同目录已有模型但首次发布失败”，并留下一个等待下载的半完成状态。
      raise "#{link['name']}工作模型没有可发布内容。" if full_definition.entities.to_a.empty?
      _wrapper, _source_child, managed = create_world_wrapper!(
        discipline,
        full_definition,
        identity_transformation,
        store_path(full, model),
        model
      )
      raise "#{link['name']}受管工作模型创建失败。" unless managed && managed.valid?

      display_name = "LH #{link['name']} 协作工作模型"
      mark_entity(
        managed,
        discipline: discipline,
        kind: 'model',
        source: store_path(full, model),
        display_name: display_name,
        tag: structure[:model_tag],
        mode: 'direct',
        signature: source_signature,
        locked: false,
        editing: true
      )
      managed.set_attribute(ENTITY_DICT, 'source_file_signature', source_signature)
      managed.set_attribute(ENTITY_DICT, 'source_revision', authoritative_link_revision(link, full))
      managed.set_attribute(ENTITY_DICT, 'load_asset_path', full)
      managed.set_attribute(ENTITY_DICT, 'load_asset_type', 'full')
      managed.set_attribute(ENTITY_DICT, 'absolute_world', true)
      managed.set_attribute(ENTITY_DICT, 'world_wrapper_schema', WORLD_WRAPPER_SCHEMA)
      managed.set_attribute(ENTITY_DICT, 'preview_editing', true)

      if work_model_entity.valid? && work_model_entity != managed
        work_model_entity.locked = false if work_model_entity.respond_to?(:locked=)
        work_model_entity.erase!
      end

      link[flag_key] = true
      link['model_path'] = store_path(full, model)
      link['native_publish_path'] = store_path(full, model)
      link['edit_session_active'] = true
      link['edit_workflow'] = "#{discipline}_managed"
      link['native_work_entity_pid'] = managed.respond_to?(:persistent_id) ? managed.persistent_id.to_i : 0
      link['native_work_entity_definition_guid'] = managed.definition.respond_to?(:guid) ? managed.definition.guid.to_s : ''
      link['native_work_entity_name'] = display_name if link['native_work_entity_name'].to_s.empty?
      update_file_stamp(link, link['model_path'], full)
      begin_preview_state!(link, managed, full, model)
      link['status'] = "首次发布完成 · 正在修改#{link['name']} · 待发布"

      model.selection.clear
      model.selection.add(managed)
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false

      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, discipline]] = false

      # 把首次发布后的受管状态写回当前工作 SKP，再进入组件；不需要用户重载。
      begin
        model.save unless model.path.to_s.empty?
      rescue StandardError => save_error
        log_exception("保存#{link['name']}首次协作状态失败", save_error)
      end

      entered = enter_managed_discipline_edit_context!(discipline, managed, model)
      refresh_dialog
      refresh_workspace_toolbar(model)
      show_status(
        entered ? "#{link['name']}首次发布完成，已直接进入修改并保持协作占用；无需下载或重载。" : "#{link['name']}首次发布完成并保持解锁修改；请双击工作模型进入组件。",
        entered ? 'success' : 'info'
      )
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      if defined?(link) && link
        link[managed_collaboration_flag_key(discipline)] = false rescue nil
        if lock_acquired_here && defined?(full) && !full.to_s.empty?
          release_source_lock(link, full, model, state) rescue nil
          clear_edit_state!(link, restore_previous: false) rescue nil
        end
        clear_preview_state!(link, restore_auto: true) rescue nil
        save_state(state, model, write_manifest: false) rescue nil
      end
      log_exception("首次发布#{discipline}进入持续修改状态失败", e)
      raise
    end

    def publishable_root_entities_for_cache(model = Sketchup.active_model)
      model.entities.to_a.select do |entity|
        (entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)) &&
          root_entity_visible?(entity, model) &&
          !plugin_managed_reference?(entity)
      end
    rescue StandardError
      []
    end

    def architecture_publishable_root_entities(model = Sketchup.active_model)
      model.entities.to_a.select do |entity|
        (entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)) &&
          !plugin_managed_reference?(entity)
      end
    rescue StandardError
      []
    end

    def save_definition_copy_to!(definition, target, label)
      ensure_metadata_target!(target)
      FileUtils.mkdir_p(File.dirname(target))
      raise "#{label}目标已存在。首次发布不能覆盖已有协同模型；请先连接/更新到最新版本后再修改。" if File.file?(target)
      token = "#{Process.pid}-#{SecureRandom.hex(4)}"
      local_candidate = File.join(TEMP_WORK_DIR, "SU_LinkHub-first-publish-#{token}.skp")
      remote_stage = File.join(File.dirname(target), ".#{File.basename(target)}.first-stage-#{token}.skp")
      saved = definition.respond_to?(:save_as) ? definition.save_as(local_candidate) : false
      saved = definition.save_copy(local_candidate) if (!File.file?(local_candidate) || !File.size(local_candidate).positive?) && definition.respond_to?(:save_copy)
      raise "SketchUp 未能写出#{label}候选。" unless saved || File.file?(local_candidate)
      raise "#{label}候选文件为空。" unless File.file?(local_candidate) && File.size(local_candidate).positive?
      candidate_signature = full_file_content_signature(local_candidate)
      raise "#{label}候选完整校验失败。" if candidate_signature.empty?
      raise "#{label}目标在候选生成期间已经由其他任务创建；首次发布已停止。" if File.exist?(target)
      file_operation_with_retry { linkhub_copy_file(local_candidate, remote_stage) }
      raise "#{label}共享候选传输失败。" unless full_file_content_signature(remote_stage) == candidate_signature
      raise "#{label}目标在传输期间已经由其他任务创建；首次发布已停止。" if File.exist?(target)
      promote_file_create_only!(remote_stage, target)
      raise "#{label}最终内容校验失败。" unless full_file_content_signature(target) == candidate_signature
      true
    ensure
      File.delete(local_candidate) if defined?(local_candidate) && local_candidate && File.file?(local_candidate)
      File.delete(remote_stage) if defined?(remote_stage) && remote_stage && File.file?(remote_stage)
    end

    def add_publishable_entities_to_definition!(target_definition, source_entities)
      Array(source_entities).each do |entity|
        next unless entity && entity.valid?
        next unless entity.respond_to?(:definition) && entity.definition
        copied = target_definition.entities.add_instance(entity.definition, entity.transformation)
        # FULL 缓存保留根组件实例材质与所有嵌套结构。
        copy_instance_visual_properties!(entity, copied)
      rescue StandardError => e
        log_exception('复制协同发布根对象失败', e)
        next
      end
      target_definition
    end

    def count_definition_entities(definition, seen = {}, limit = 2_000_000)
      return 0 unless definition && definition.valid? && limit.positive?
      identity = definition.object_id
      return 0 if seen[identity]
      seen[identity] = true
      count = 0
      definition.entities.each do |entity|
        count += 1
        break if count >= limit
        if entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
          count += count_definition_entities(entity.definition, seen, limit - count)
        end
      end
      count
    rescue StandardError
      0
    end

    def save_collab_full_only_cache!(key, info, candidates, paths, model = Sketchup.active_model)
      full_definition = model.definitions.add("LH_COLLAB_#{info['code']}_FULL_#{SecureRandom.hex(5)}")
      add_publishable_entities_to_definition!(full_definition, candidates)
      save_definition_copy_to!(full_definition, paths[:full], 'FULL 有材质协同缓存')
      full_signature = fast_file_signature(paths[:full])
      {
        full_signature: full_signature,
        entity_count: count_definition_entities(full_definition)
      }
    end

    def relative_to_dir(path, dir)
      Pathname.new(FastPath.expand(path)).relative_path_from(Pathname.new(FastPath.expand(dir))).to_s
    rescue StandardError
      File.basename(path.to_s)
    end

    def read_json_file(path)
      JSON.parse(File.read(path.to_s, mode: 'rb'))
    rescue JSON::ParserError
      nil
    end

    def existing_project_collab_manifest(project_dir)
      path = project_collab_json_for_dir(project_dir)
      return {} unless File.file?(path)
      data = read_json_file(path)
      data.is_a?(Hash) ? data : {}
    rescue StandardError
      {}
    end

    # 建筑与景观可以由不同成员同时发布。协同.json 是两者共享的索引，
    # 若各自“读取旧 JSON → 写回”没有跨进程锁，后完成者会把另一专业刚写入的
    # revision 整段覆盖掉。所有项目清单写入必须在同一把短锁内重新读取并合并。
    def with_project_collab_write_lock(project_json, timeout: 4.0)
      lock_path = "#{project_json}.sulink-write.lock"
      deadline = monotonic_time + timeout.to_f
      acquired = false
      loop do
        begin
          File.open(lock_path, File::WRONLY | File::CREAT | File::EXCL) do |io|
            io.write(JSON.generate({
              'pid' => Process.pid,
              'host' => current_host_name,
              'user' => current_user_name,
              'created_at' => Time.now.iso8601(6)
            }))
          end
          acquired = true
          break
        rescue Errno::EEXIST
          begin
            age = Time.now.to_f - File.mtime(lock_path).to_f
            File.delete(lock_path) if age > 20.0
          rescue StandardError
            nil
          end
          raise '项目协同清单正由其他成员更新，请稍后重试。' if monotonic_time >= deadline
          sleep(0.06)
        end
      end
      yield
    ensure
      File.delete(lock_path) if acquired && File.file?(lock_path)
    end

    def write_project_collab_manifest!(project_dir, discipline_key, discipline_manifest)
      project_dir = FastPath.expand(project_dir.to_s)
      project_json = project_collab_json_for_dir(project_dir)
      FileUtils.mkdir_p(File.dirname(project_json))
      with_project_collab_write_lock(project_json) do
        # 必须在取得锁以后重新读取，不能使用等待锁之前的旧 disciplines。
        data = existing_project_collab_manifest(project_dir)
        disciplines = data['disciplines'].is_a?(Hash) ? data['disciplines'] : {}
        entry = {
          'discipline' => discipline_key.to_s,
          'discipline_name' => DISCIPLINES.dig(discipline_key.to_s, 'name').to_s,
          'version' => discipline_manifest['version'].to_s,
          'revision_id' => discipline_manifest['revision_id'].to_s,
          'generated_at' => discipline_manifest['generated_at'].to_s,
          'manifest' => relative_to_project(discipline_manifest['manifest_path'].to_s, project_dir),
          'full' => relative_to_project(discipline_manifest['full_resolved'].to_s, project_dir),
          'source_model' => discipline_manifest['source_model'].to_s,
          'full_signature' => discipline_manifest['full_signature'].to_s,
          'published_by' => discipline_manifest['published_by'].to_s,
          'host' => discipline_manifest['host'].to_s
        }
        payload = {
          'schema' => PROJECT_COLLAB_SCHEMA,
          'kind' => 'sulink_collab_project',
          'plugin_version' => EXTENSION_VERSION,
          # v0.6.22 起不再把发布者的盘符写成强依赖。旧版读取到空值时也会
          # 自动以“所选 协同.json 所在文件夹”为项目根目录，可兼容 H:\ 与 UNC 共享路径。
          'project_dir' => '',
          'project_dir_hint' => project_dir,
          'collab_dir' => COLLAB_FOLDER_NAME,
          'updated_at' => Time.now.iso8601(6),
          'settings' => (data['settings'].is_a?(Hash) ? data['settings'] : {
            'schema' => PROJECT_SETTINGS_SCHEMA, 'updated_at' => '', 'updated_by' => '', 'host' => '', 'paths' => {}
          }),
          'disciplines' => disciplines.merge(discipline_key.to_s => entry)
        }
        temp = "#{project_json}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
        linkhub_mv(temp, project_json)
      ensure
        begin
          File.delete(temp) if defined?(temp) && temp && File.file?(temp)
        rescue StandardError
          nil
        end
      end
      project_json
    end

    def default_project_settings_payload
      {
        'schema' => PROJECT_SETTINGS_SCHEMA,
        'updated_at' => '',
        'updated_by' => '',
        'host' => '',
        'paths' => {}
      }
    end

    def portable_project_setting_path(path, project_dir)
      text = path.to_s.strip
      return '' if text.empty?
      expanded = FastPath.expand(text)
      base = FastPath.expand(project_dir.to_s)
      begin
        relative = Pathname.new(expanded).relative_path_from(Pathname.new(base)).to_s
        return relative.tr('\\', '/') unless relative.start_with?('..') || Pathname.new(relative).absolute?
      rescue StandardError
        nil
      end
      expanded
    rescue StandardError
      text
    end

    def resolve_project_setting_dir(value, project_dir)
      text = value.to_s.strip
      return '' if text.empty?
      if absolute_file_path?(text) || (Pathname.new(text).absolute? rescue false)
        FastPath.expand(text)
      else
        FastPath.expand(text, project_dir.to_s)
      end
    rescue StandardError
      text
    end

    def project_path_settings_from_manifest(project, model = Sketchup.active_model)
      data = project.is_a?(Hash) ? project : {}
      manifest_path = data['manifest_path'].to_s
      project_dir = data['project_dir_resolved'].to_s
      project_dir = File.dirname(manifest_path) if project_dir.empty? && !manifest_path.empty?
      project_dir = selected_collab_project_dir_for_state(load_state(model), model) if project_dir.empty?
      settings = data['settings'].is_a?(Hash) ? data['settings'] : {}
      paths = settings['paths'].is_a?(Hash) ? settings['paths'] : {}
      PROJECT_PATH_SETTING_KEYS.keys.each_with_object({}) do |key, memo|
        memo[key] = resolve_project_setting_dir(paths[key].to_s, project_dir)
      end
    rescue StandardError => e
      log_exception('解析项目固定路径失败', e)
      PROJECT_PATH_SETTING_KEYS.keys.each_with_object({}) { |key, memo| memo[key] = '' }
    end

    def current_project_path_settings(model = Sketchup.active_model, force: false)
      state = load_state(model)
      json_path = resolve_collab_json_value(state['collab_project_json'].to_s, model)
      return PROJECT_PATH_SETTING_KEYS.keys.each_with_object({}) { |key, memo| memo[key] = '' } if json_path.empty? || !File.file?(json_path)
      @project_path_settings_cache ||= {}
      cache = @project_path_settings_cache[model.object_id]
      now = monotonic_time
      if !force && cache.is_a?(Hash) && cache[:manifest].to_s == json_path.to_s && now - cache[:checked_at].to_f < 4.0
        return cache[:paths].dup
      end
      signature = fast_file_signature(json_path)
      if !force && cache.is_a?(Hash) && cache[:signature].to_s == signature.to_s
        cache[:checked_at] = now
        return cache[:paths].dup
      end
      project = read_project_collab_manifest(json_path, allow_empty: true)
      paths = project_path_settings_from_manifest(project, model)
      @project_path_settings_cache[model.object_id] = { signature: signature, paths: paths, manifest: json_path, checked_at: now }
      paths.dup
    rescue StandardError => e
      log_exception('读取项目固定路径失败', e)
      PROJECT_PATH_SETTING_KEYS.keys.each_with_object({}) { |key, memo| memo[key] = '' }
    end

    def write_project_path_settings!(paths, model = Sketchup.active_model)
      state = load_state(model)
      project_dir = collab_project_dir_for_model(model, state, require_configured: true)
      project_json = project_collab_json_for_dir(project_dir)
      normalized = {}
      PROJECT_PATH_SETTING_KEYS.each_key do |key|
        value = paths.is_a?(Hash) ? paths[key].to_s.strip : ''
        if !value.empty?
          expanded = FastPath.expand(value)
          raise "#{PROJECT_PATH_SETTING_KEYS[key]}路径不存在：#{expanded}" unless Dir.exist?(expanded)
          normalized[key] = portable_project_setting_path(expanded, project_dir)
        else
          normalized[key] = ''
        end
      end
      with_project_collab_write_lock(project_json) do
        data = existing_project_collab_manifest(project_dir)
        data = {
          'schema' => PROJECT_COLLAB_SCHEMA,
          'kind' => 'sulink_collab_project',
          'plugin_version' => EXTENSION_VERSION,
          'project_dir' => '',
          'project_dir_hint' => project_dir,
          'collab_dir' => COLLAB_FOLDER_NAME,
          'disciplines' => {}
        } unless data.is_a?(Hash) && data['kind'].to_s == 'sulink_collab_project'
        data['schema'] = PROJECT_COLLAB_SCHEMA
        data['kind'] = 'sulink_collab_project'
        data['plugin_version'] = EXTENSION_VERSION
        data['project_dir'] = ''
        data['project_dir_hint'] = project_dir
        data['collab_dir'] = COLLAB_FOLDER_NAME
        data['disciplines'] = {} unless data['disciplines'].is_a?(Hash)
        data['updated_at'] = Time.now.iso8601(6)
        data['settings'] = {
          'schema' => PROJECT_SETTINGS_SCHEMA,
          'updated_at' => Time.now.iso8601(6),
          'updated_by' => current_user_name,
          'host' => current_host_name,
          'paths' => normalized
        }
        temp = "#{project_json}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
        File.write(temp, JSON.pretty_generate(data), mode: 'w:UTF-8')
        linkhub_mv(temp, project_json)
      ensure
        File.delete(temp) if defined?(temp) && temp && File.file?(temp) rescue nil
      end
      @project_path_settings_cache ||= {}
      @project_path_settings_cache.delete(model.object_id)
      apply_project_path_settings!(state, model, force: true)
      refresh_workspace_toolbar(model, detailed: true)
      normalized
    end

    def local_library_path_defaults
      {
        'soft_model_root' => soft_library_root.to_s,
        'soft_material_root' => material_library_root(SOFT_SPACE_COLLECTION_KEY).to_s,
        'hard_material_root' => material_library_root(SPACE_COLLECTION_KEY).to_s,
        'architecture_model_root' => architecture_library_root.to_s,
        'architecture_material_root' => material_library_root('architecture').to_s,
        'landscape_model_root' => landscape_library_root.to_s,
        'landscape_material_root' => material_library_root('landscape').to_s,
        'plugin_release_root' => DEFAULT_PLUGIN_RELEASE_ROOT
      }
    rescue StandardError
      {}
    end

    def project_settings_for_dialog(model = Sketchup.active_model)
      current = current_project_path_settings(model, force: true)
      local_library_path_defaults.each do |key, path|
        next unless current[key].to_s.empty? && !path.to_s.empty?
        current[key] = path if key.to_s == 'plugin_release_root' || Dir.exist?(path.to_s)
      end
      current
    end

    def persist_project_path_setting!(key, value, model = Sketchup.active_model)
      return false unless PROJECT_PATH_SETTING_KEYS.key?(key.to_s)
      state = load_state(model)
      connection = collaboration_connection_info(state, model)
      return false unless connection['connected'] == true
      current = current_project_path_settings(model, force: true)
      local_library_path_defaults.each do |default_key, path|
        next unless current[default_key].to_s.empty? && !path.to_s.empty?
        current[default_key] = path if default_key.to_s == 'plugin_release_root' || Dir.exist?(path.to_s)
      end
      expanded = value.to_s.strip.empty? ? '' : FastPath.expand(value.to_s)
      return true if current[key.to_s].to_s == expanded
      current[key.to_s] = expanded
      write_project_path_settings!(current, model)
      true
    rescue StandardError => e
      log_exception("保存项目固定路径 #{key} 失败", e)
      false
    end

    def architecture_library_root
      return @architecture_library_root_session.to_s if defined?(@architecture_library_root_session) && !@architecture_library_root_session.nil?
      raw = Sketchup.read_default(ARCHITECTURE_LIBRARY_PREF_SECTION, ARCHITECTURE_LIBRARY_ROOT_PREF_KEY, '').to_s
      @architecture_library_root_session = raw.empty? ? '' : FastPath.expand(raw)
    rescue StandardError
      @architecture_library_root_session = ''
    end

    def set_architecture_library_root(path, persist_project: true)
      root = path.to_s.empty? ? '' : FastPath.expand(path.to_s)
      raise '请选择有效的建筑模型库文件夹。' if root.empty? || !Dir.exist?(root)
      Sketchup.write_default(ARCHITECTURE_LIBRARY_PREF_SECTION, ARCHITECTURE_LIBRARY_ROOT_PREF_KEY, root)
      @architecture_library_root_session = root
      persist_project_path_setting!('architecture_model_root', root) if persist_project
      root
    end

    def apply_project_path_settings!(state = nil, model = Sketchup.active_model, project: nil, force: false)
      state ||= load_state(model)
      paths = project ? project_path_settings_from_manifest(project, model) : current_project_path_settings(model, force: force)
      applied = []
      missing = []
      paths.each do |key, path|
        next if path.to_s.empty?
        unless Dir.exist?(path)
          missing << "#{PROJECT_PATH_SETTING_KEYS[key]}：#{path}"
          next
        end
        case key
        when 'soft_model_root'
          set_soft_library_root(path, persist_project: false)
        when 'soft_material_root'
          set_material_library_root(SOFT_SPACE_COLLECTION_KEY, path, persist_project: false)
        when 'hard_material_root'
          set_material_library_root(SPACE_COLLECTION_KEY, path, persist_project: false)
        when 'architecture_model_root'
          set_architecture_library_root(path, persist_project: false)
        when 'architecture_material_root'
          set_material_library_root('architecture', path, persist_project: false)
        when 'landscape_model_root'
          set_landscape_library_root(path, persist_project: false)
        when 'landscape_material_root'
          set_material_library_root('landscape', path, persist_project: false)
        when 'plugin_release_root'
          # 只作为项目级更新源。
        end
        applied << key
      rescue StandardError => e
        missing << "#{PROJECT_PATH_SETTING_KEYS[key]}：#{e.message}"
      end
      @project_path_settings_cache ||= {}
      json_path = resolve_collab_json_value(state['collab_project_json'].to_s, model)
      @project_path_settings_cache[model.object_id] = { signature: fast_file_signature(json_path), paths: paths, manifest: json_path, checked_at: monotonic_time } unless json_path.to_s.empty?
      log("项目固定路径有 #{missing.length} 项不可用：#{missing.join(' | ')}") unless missing.empty?
      { applied: applied, missing: missing, paths: paths }
    rescue StandardError => e
      log_exception('自动应用项目固定路径失败', e)
      { applied: [], missing: [e.message.to_s], paths: {} }
    end

    def parse_linkhub_version_from_filename(path)
      name = File.basename(path.to_s)
      match = name.match(/(?:^|[_\-\s])v?(\d+(?:\.\d+){1,4})(?=[_\-\s.]|$)/i)
      match ? match[1].to_s : ''
    rescue StandardError
      ''
    end

    def compare_linkhub_versions(a, b)
      left = a.to_s.split('.').map { |part| part.to_i }
      right = b.to_s.split('.').map { |part| part.to_i }
      length = [left.length, right.length].max
      left += [0] * (length - left.length)
      right += [0] * (length - right.length)
      left <=> right
    rescue StandardError
      0
    end

    # RBZ 是 ZIP。只做极轻量的完成性检查：发布端文件至少静置 2 秒，且尾部已经
    # 出现 ZIP End of Central Directory。完整安装校验仍由 SketchUp 原生接口负责。
    def linkhub_update_archive_complete?(path, require_settled: true)
      return false unless File.file?(path)
      stat = File.stat(path)
      return false unless stat.size.to_i >= 22
      if require_settled && Time.now.to_f - stat.mtime.to_f < PLUGIN_UPDATE_ARCHIVE_SETTLE_SECONDS
        return false
      end
      tail_size = [stat.size.to_i, 65_557].min
      tail = File.open(path, 'rb') do |file|
        file.seek(-tail_size, IO::SEEK_END)
        file.read(tail_size).to_s
      end
      tail.include?("PK\x05\x06".b)
    rescue StandardError
      false
    end

    def stage_linkhub_update_archive!(path)
      source = FastPath.expand(path.to_s)
      raise '插件更新包尚未复制完整，请稍后再试。' unless linkhub_update_archive_complete?(source)
      before_fast = fast_file_signature(source)
      # 更新包通常只有数 MB，整包 SHA256 的成本远低于一次安装失败；这里不采用
      # 首尾抽样，避免同尺寸中段损坏或被替换的包绕过暂存校验。
      before_content = small_file_content_signature(source)
      raise '无法验证插件更新包内容，请检查发布目录。' if before_fast.empty? || before_content.empty?
      local = File.join(TEMP_WORK_DIR, "SU_LinkHub-update-#{Process.pid}-#{SecureRandom.hex(4)}.rbz")
      file_operation_with_retry { linkhub_copy_file(source, local) }
      after_fast = fast_file_signature(source)
      after_content = small_file_content_signature(source)
      local_content = small_file_content_signature(local)
      unless before_fast == after_fast && before_content == after_content && before_content == local_content &&
             linkhub_update_archive_complete?(local, require_settled: false)
        File.delete(local) if File.file?(local)
        raise '插件更新包在复制期间仍有变化，已取消安装；请等待发布完成后重试。'
      end
      local
    rescue StandardError
      File.delete(local) if defined?(local) && local && File.file?(local)
      raise
    end

    def plugin_update_status(model = Sketchup.active_model, force: false)
      paths = current_project_path_settings(model, force: force)
      root = paths['plugin_release_root'].to_s.strip
      root = DEFAULT_PLUGIN_RELEASE_ROOT if root.empty?
      return { available: false, configured: false, root: '', version: '', path: '', error: '' } if root.empty?
      return { available: false, configured: true, root: root, version: '', path: '', error: '插件发布目录不存在' } unless Dir.exist?(root)
      @plugin_update_status_cache ||= {}
      cache = @plugin_update_status_cache[model.object_id]
      now = monotonic_time
      dir_stamp = File.mtime(root).to_f rescue 0.0
      if !force && cache.is_a?(Hash) && cache[:root].to_s == root && cache[:dir_stamp].to_f == dir_stamp && now - cache[:checked_at].to_f < PLUGIN_UPDATE_SCAN_INTERVAL
        return cache[:status].dup
      end
      candidates = Dir.children(root).filter_map do |name|
        next unless File.extname(name).casecmp('.rbz').zero?
        path = File.join(root, name)
        next unless File.file?(path)
        next unless linkhub_update_archive_complete?(path)
        version = parse_linkhub_version_from_filename(path)
        next if version.empty?
        { path: path, version: version, mtime: (File.mtime(path).to_f rescue 0.0) }
      end
      best = candidates.max do |one, two|
        cmp = compare_linkhub_versions(one[:version], two[:version])
        cmp.zero? ? (one[:mtime] <=> two[:mtime]) : cmp
      end
      status = if best && compare_linkhub_versions(best[:version], EXTENSION_VERSION).positive?
                 { available: true, configured: true, root: root, version: best[:version], path: best[:path], error: '' }
               else
                 { available: false, configured: true, root: root, version: best ? best[:version] : '', path: best ? best[:path] : '', error: '' }
               end
      @plugin_update_status_cache[model.object_id] = { root: root, dir_stamp: dir_stamp, checked_at: now, status: status }
      status.dup
    rescue StandardError => e
      { available: false, configured: true, root: root.to_s, version: '', path: '', error: e.message.to_s }
    end

    def reload_or_update_plugin!(model = Sketchup.active_model)
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再更新插件。' if publish_critical_section? || publish_post_quiet?
      if @updating || @single_space_update_job || @space_batch_update_job || @soft_model_batch_job
        raise '模型或模型库任务正在执行，请等待完成后再更新插件。'
      end
      ensure_soft_ingest_batch_not_writing!('插件更新')
      status = plugin_update_status(model, force: true)
      if status[:available]
        archive = status[:path].to_s
        show_status("发现 SU LinkHub v#{status[:version]}，正在安装并热重载…", 'warning')
        unless GavinTools::SULinkHubMultiSpace.respond_to?(:install_archive_and_reload!)
          raise '插件更新接口未载入。请先安装 v0.13.1 修复版；之后可继续使用目录自动更新。'
        end
        local_archive = stage_linkhub_update_archive!(archive)
        result = GavinTools::SULinkHubMultiSpace.install_archive_and_reload!(local_archive, show_dialog: false)
        raise "插件更新安装失败：#{File.basename(archive)}" unless result
        true
      else
        show_status('SU LinkHub 正在后台重载…', 'success')
        unless GavinTools::SULinkHubMultiSpace.respond_to?(:schedule_runtime_reload!)
          raise '插件热重载接口未载入。请重新启动 SketchUp 后再试。'
        end
        GavinTools::SULinkHubMultiSpace.schedule_runtime_reload!(show_dialog: false)
      end
    rescue StandardError => e
      UI.messagebox(
        "SU LinkHub 重载/更新失败。\n\n" \
        "#{e.class}: #{e.message}\n\n" \
        "如果正在从旧版本升级到本修复版，请先手动安装一次 v0.13.1；以后即可直接用黄色重载按钮更新。"
      )
      false
    ensure
      File.delete(local_archive) if defined?(local_archive) && local_archive && File.file?(local_archive)
    end

    def project_settings_dialog_html
      rows = PROJECT_PATH_SETTING_KEYS.map do |key, label|
        %(<div class="row"><label>#{label}</label><div class="field"><input id="#{key}" spellcheck="false"><button data-browse="#{key}" title="选择文件夹">…</button></div></div>)
      end.join
      keys_json = JSON.generate(PROJECT_PATH_SETTING_KEYS.keys)
      <<~HTML
        <!doctype html><html><head><meta charset="utf-8"><style>
        *{box-sizing:border-box}body{margin:0;background:#f5f6f8;color:#202532;font:13px/1.35 "Microsoft YaHei",sans-serif}.wrap{padding:16px}.title{font-size:16px;font-weight:700}.sub{font-size:11px;color:#7b8494;margin:2px 0 10px}.row{margin:8px 0}.row label{display:block;font-size:11px;color:#687284;margin-bottom:4px}.field{display:flex;gap:6px}.field input{height:31px;min-width:0;flex:1;border:1px solid #d7dce5;border-radius:7px;background:white;padding:0 9px;color:#252b36}.field button{width:34px;border:1px solid #d7dce5;border-radius:7px;background:#fff;font-weight:700;color:#5d6674;cursor:pointer}.foot{display:flex;gap:8px;margin-top:14px}.foot button{height:34px;flex:1;border-radius:8px;border:1px solid #d7dce5;background:#fff;cursor:pointer}.foot .save{background:#4f596b;color:#fff;border-color:#4f596b}.hint{padding:8px 10px;background:#eef1f6;border-radius:8px;color:#687284;font-size:11px;margin-top:10px}.status{font-size:11px;color:#a46c14;min-height:15px;margin-top:8px}
        </style></head><body><div class="wrap"><div class="title">项目固定路径</div><div class="sub">保存到当前协同.json · 新模型连接项目后自动恢复</div>#{rows}<div class="hint">插件发布目录中若出现更高版本的 SU_LinkHub_v*.rbz，抽屉右上角重载按钮会变黄；点击即可安装最新版并热重载。</div><div id="status" class="status"></div><div class="foot"><button onclick="sketchup.close_settings()">取消</button><button class="save" onclick="save()">保存到协同 JSON</button></div></div><script>
        const KEYS=#{keys_json};function setPaths(data){KEYS.forEach(k=>{document.getElementById(k).value=(data&&data[k])||''})}function setPath(k,v){const el=document.getElementById(k);if(el)el.value=v||''}function setStatus(t){document.getElementById('status').textContent=t||''}function save(){let p={};KEYS.forEach(k=>p[k]=document.getElementById(k).value.trim());sketchup.save_settings(JSON.stringify(p))}document.addEventListener('click',e=>{let b=e.target.closest('[data-browse]');if(b)sketchup.browse_path(b.dataset.browse,document.getElementById(b.dataset.browse).value||'')});window.ProjectSettings={setPaths,setPath,setStatus};
        </script></body></html>
      HTML
    end

    def show_project_settings_dialog(model = Sketchup.active_model)
      state = load_state(model)
      connection = collaboration_connection_info(state, model)
      raise '请先连接协同项目，再配置项目固定路径。' unless connection['connected'] == true
      if @project_settings_dialog && @project_settings_dialog.visible?
        @project_settings_dialog.bring_to_front
        @project_settings_dialog.execute_script("window.ProjectSettings.setPaths(#{JSON.generate(project_settings_for_dialog(model))})")
        return true
      end
      dialog = UI::HtmlDialog.new(dialog_title: 'SU LinkHub · 项目固定路径', preferences_key: 'SU_LinkHub_ProjectSettings', scrollable: true, resizable: true, width: 560, height: 610, style: UI::HtmlDialog::STYLE_DIALOG)
      dialog.set_html(project_settings_dialog_html)
      dialog.add_action_callback('browse_path') do |_ctx, key, current|
        safe_callback("选择#{PROJECT_PATH_SETTING_KEYS[key.to_s] || '目录'}") do
          options = { title: "选择#{PROJECT_PATH_SETTING_KEYS[key.to_s] || '文件夹'}" }
          expanded = current.to_s.strip
          options[:directory] = expanded if !expanded.empty? && Dir.exist?(expanded)
          selected = UI.select_directory(options)
          next unless selected && !selected.to_s.empty?
          dialog.execute_script("window.ProjectSettings.setPath(#{JSON.generate(key.to_s)},#{JSON.generate(FastPath.expand(selected.to_s))})")
        end
      end
      dialog.add_action_callback('save_settings') do |_ctx, payload|
        safe_callback('保存项目固定路径') do
          paths = JSON.parse(payload.to_s)
          write_project_path_settings!(paths, model)
          dialog.execute_script("window.ProjectSettings.setStatus('已保存到协同.json，并已应用到当前模型。')")
        end
      end
      dialog.add_action_callback('close_settings') { |_ctx| dialog.close }
      dialog.set_on_closed { @project_settings_dialog = nil }
      @project_settings_dialog = dialog
      dialog.show
      runtime_start_timer(0.08, false, label: 'project_settings_seed') do
        next unless dialog.visible?
        dialog.execute_script("window.ProjectSettings.setPaths(#{JSON.generate(project_settings_for_dialog(model))})")
      end
      true
    end

    def project_collab_root_candidates(json_path, data)
      roots = []
      roots << File.dirname(FastPath.expand(json_path.to_s))
      stored = data.is_a?(Hash) ? data['project_dir'].to_s : ''
      roots << FastPath.expand(stored) unless stored.empty?
      hint = data.is_a?(Hash) ? data['project_dir_hint'].to_s : ''
      roots << FastPath.expand(hint) unless hint.empty?
      roots.compact.map(&:to_s).reject(&:empty?).uniq
    rescue StandardError
      [File.dirname(json_path.to_s)]
    end

    def project_relative_suffix_from_absolute(value, stored_project_dir = '')
      text = value.to_s.tr('\\', '/')
      stored = stored_project_dir.to_s.tr('\\', '/')
      unless stored.empty?
        prefix = stored.end_with?('/') ? stored : "#{stored}/"
        if text.downcase.start_with?(prefix.downcase)
          return text[prefix.length..-1].to_s
        end
      end
      marker = "/#{COLLAB_FOLDER_NAME}/"
      index = text.downcase.index(marker.downcase)
      return text[(index + 1)..-1].to_s if index
      nil
    rescue StandardError
      nil
    end

    def resolve_project_collab_path(project_roots, value, stored_project_dir = '')
      text = value.to_s
      return '' if text.empty?
      roots = Array(project_roots).map { |root| FastPath.expand(root.to_s) rescue root.to_s }.reject(&:empty?).uniq
      roots = [Dir.pwd] if roots.empty?
      candidates = []
      if absolute_file_path?(text) || (Pathname.new(text).absolute? rescue false)
        candidates << (FastPath.expand(text) rescue text)
        suffix = project_relative_suffix_from_absolute(text, stored_project_dir)
        if suffix && !suffix.empty?
          roots.each { |root| candidates << FastPath.expand(suffix, root) }
        end
      else
        roots.each { |root| candidates << FastPath.expand(text, root) }
      end
      candidates = candidates.compact.map(&:to_s).reject(&:empty?).uniq
      candidates.find { |path| File.file?(path) } || candidates.first.to_s
    rescue StandardError
      text
    end

    def read_project_collab_manifest(path_or_dir, allow_empty: false)
      raw = path_or_dir.to_s
      json_path = File.directory?(raw) ? project_collab_json_for_dir(raw) : raw
      raise "请选择项目文件夹，或选择项目根目录下的 #{PROJECT_COLLAB_FILE}。" unless File.file?(json_path)
      data = JSON.parse(File.read(json_path, mode: 'rb'))
      unless data.is_a?(Hash) && data['schema'].to_i == PROJECT_COLLAB_SCHEMA && data['kind'].to_s == 'sulink_collab_project'
        raise "这个 JSON 不是 SU LinkHub 项目协同清单。请选择项目根目录下的 #{PROJECT_COLLAB_FILE}。"
      end
      stored_project_dir = data['project_dir'].to_s
      project_roots = project_collab_root_candidates(json_path, data)
      resolved = {}
      source_disciplines = data['disciplines'].is_a?(Hash) ? data['disciplines'] : {}
      source_disciplines.each do |key, entry|
        next unless DISCIPLINES.key?(key.to_s) && entry.is_a?(Hash)
        manifest_path = resolve_project_collab_path(project_roots, entry['manifest'], stored_project_dir)
        full_path = resolve_project_collab_path(project_roots, entry['full'], stored_project_dir)
        next unless File.file?(full_path)
        resolved[key.to_s] = entry.merge(
          'manifest_resolved' => manifest_path,
          'full_resolved' => full_path
        )
      end
      if resolved.empty? && !allow_empty
        raise '这个项目协同清单里没有可用的 FULL 缓存。请先在发布方发布缓存，或确认大家选择的是同一个项目根目录下的 协同.json。'
      end
      data.merge('manifest_path' => FastPath.expand(json_path), 'project_dir_resolved' => project_roots.first.to_s, 'project_roots_tried' => project_roots, 'disciplines_resolved' => resolved)
    rescue JSON::ParserError
      raise "#{PROJECT_COLLAB_FILE} 不是有效 JSON。"
    end

    def apply_collab_project_manifest!(state, path_or_dir, only_key: nil, allow_empty: true)
      raw_location = path_or_dir.to_s
      if File.directory?(raw_location)
        json = project_collab_json_for_dir(raw_location)
        raw_location = ensure_empty_project_collab_manifest!(raw_location) unless File.file?(json)
      end
      project = read_project_collab_manifest(raw_location, allow_empty: allow_empty)
      set_collab_project_location!(state, project['manifest_path'].to_s)
      apply_project_path_settings!(state, Sketchup.active_model, project: project, force: true)
      host = host_discipline_for(state)
      applied = []
      project['disciplines_resolved'].each do |key, entry|
        next if only_key && key != only_key.to_s
        # 建筑与景观都使用同一份协同 FULL。当前专业如果已有发布版本，也应读取
        # 清单并进入统一的更新/修改/发布逻辑，不能再把景观永远跳过。
        next if key == host && host != 'coordination' && !%w[architecture landscape].include?(key)
        link = state['links'][key]
        next unless link
        full = entry['full_resolved'].to_s
        if source_used_by_other_discipline?(state, key, full)
          log("跳过#{DISCIPLINES[key]['name']}协同缓存：FULL 已被其他专业使用 #{full}")
          next
        end
        link['model_path'] = store_path(full)
        link['collab_manifest_path'] = store_path(entry['manifest_resolved'].to_s)
        link['collab_project_manifest_path'] = store_path(project['manifest_path'].to_s)
        link['collab_full_path'] = store_path(full)
        link['collab_cache_version'] = entry['version'].to_i
        link['collab_revision_id'] = entry['revision_id'].to_s
        link['collab_last_publish_at'] = entry['generated_at'].to_s
        link['collab_full_signature'] = entry['full_signature'].to_s
        link['collab_last_published_by'] = entry['published_by'].to_s
        link['collab_last_publish_host'] = entry['host'].to_s
        link['prefer_reference_package'] = true
        link['sync_strategy'] = 'direct'
        link['enabled'] = true if link['enabled'].nil?
        link['status'] = if key == 'architecture' && host == 'architecture'
                           '发现建筑协同版本 · 可另存副本或直接更新'
                         else
                           '已连接项目协同缓存 · 请点击更新'
                         end
        # 已经载入的建筑不能在这里只刷新“已读签名”，否则新版本会被静默标成最新。
        update_file_stamp(link, link['model_path'], full) if File.file?(full) && !managed_model_instance_for(key, Sketchup.active_model)
        clear_model_caches!(link)
        applied << key
      end
      raise '没有可连接的专业缓存，请检查项目协同清单与共享文件。' if applied.empty? && !allow_empty
      applied
    end

    # 室内空间发布恢复策略（v0.13.6.59）：
    # 旧实现会在正式候选生成之前，对当前空间 Definition 再执行一次 save_copy/save_as。
    # 这相当于一次发布连续触发两次 SketchUp 原生 Definition 序列化；实机崩溃追踪已经
    # 证明可在 space_recovery_save_begin 内直接触发 SketchUp 原生闪退。
    #
    # 新策略只在这里准备“恢复快照计划”，不调用任何 SketchUp 原生保存 API。
    # 稍后本次发布候选已经由唯一的一次 definition.save_as 成功写出后，再用纯文件复制
    # 把该候选保存到本机恢复目录。这样仍保留事故恢复点，同时把发布前额外 native save
    # 从主线程彻底移除。
    def save_space_recovery_before_collab_publish!(item, entity, model = Sketchup.active_model, context: '空间发布')
      raise '当前 SketchUp 模型无效，无法准备发布恢复快照。' unless model
      raise '当前空间模型无效，无法准备发布恢复快照。' unless entity && entity.valid? && entity.respond_to?(:definition)
      source_path = model.path.to_s
      raise "请先保存当前 SketchUp 模型，再执行#{context}。" if source_path.empty?

      model_clean = model.respond_to?(:modified?) ? !model.modified? : false
      if model_clean
        publish_breadcrumb!('space_recovery_skipped', context: context.to_s, reason: '当前工作 SU 已保存且未修改')
        log("#{context}前跳过恢复快照：当前工作 SU 已保存且未修改")
        return nil
      end

      directory = space_update_rollback_directory(model)
      safe_name = safe_space_filename("#{item['number']}_#{item['name']}")
      stamp = Time.now.strftime('%Y%m%d_%H%M%S')
      token = SecureRandom.hex(2)
      path = File.join(directory, "PUBLISH_#{safe_name}_#{stamp}_#{token}.skp")
      plan = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'kind' => 'space_publish_recovery_from_candidate',
        'created_at' => Time.now.iso8601(6),
        'source_model' => source_path,
        'space_id' => item['id'].to_s,
        'space_number' => item['number'].to_s,
        'space_name' => item['name'].to_s,
        'definition_name' => (entity.definition.name.to_s rescue ''),
        'outer_transformation' => (entity.transformation.to_a rescue []),
        'snapshot_file' => path,
        'safe_name' => safe_name,
        'context' => context.to_s
      }
      publish_breadcrumb!(
        'space_recovery_deferred_to_candidate',
        context: context.to_s, path: path,
        reason: '避免发布前第二次 Definition save_copy/save_as 原生序列化'
      )
      log("#{context}恢复快照已改为候选复用：不再单独调用 Definition.save_copy/save_as")
      plan
    rescue StandardError => e
      log_exception("#{context}前准备当前空间恢复快照计划失败", e)
      raise e
    end

    # 本次发布候选已经成功由 SketchUp 原生 API 写到本机后，恢复快照只做普通文件复制。
    # 这里没有 model.start_operation、Definition.save_as/save_copy 或其它原生序列化调用。
    def persist_space_recovery_from_candidate!(plan, prepared_candidate, entity, model = Sketchup.active_model, proxy_layout: true)
      return '' unless plan.is_a?(Hash)
      path = plan['snapshot_file'].to_s
      source = prepared_candidate.is_a?(Hash) ? prepared_candidate[:path].to_s : ''
      expected_size = prepared_candidate.is_a?(Hash) ? prepared_candidate[:size].to_i : 0
      expected_content = prepared_candidate.is_a?(Hash) ? prepared_candidate[:content_signature].to_s : ''
      raise '本机发布候选不存在，无法创建恢复副本。' if source.empty? || !File.file?(source)
      raise '本机发布候选为空，无法创建恢复副本。' unless expected_size.positive? && File.size(source) == expected_size
      raise '发布恢复副本路径无效。' if path.empty?

      started = monotonic_time
      publish_breadcrumb!(
        'space_recovery_candidate_copy_begin',
        source: source, path: path, candidate_size: expected_size,
        representation: (proxy_layout ? 'proxy' : 'full')
      )
      FileUtils.mkdir_p(File.dirname(path))
      file_operation_with_retry([0.0, 0.05, 0.15]) { linkhub_copy_file(source, path) }
      raise '当前空间发布恢复副本写出失败。' unless File.file?(path) && File.size(path) == expected_size
      unless expected_content.empty?
        copied_content = full_file_content_signature(path)
        raise '当前空间发布恢复副本内容校验失败。' unless copied_content == expected_content
      end

      metadata = plan.dup
      metadata.delete('safe_name')
      metadata.delete('context')
      metadata['snapshot_representation'] = proxy_layout ? 'proxy_publish_candidate' : 'full_publish_candidate'
      metadata['candidate_size'] = expected_size
      metadata['candidate_content_signature'] = expected_content
      metadata['definition_name_after_candidate'] = (entity && entity.valid? && entity.respond_to?(:definition) ? entity.definition.name.to_s : '') rescue ''
      metadata['outer_transformation_after_candidate'] = (entity && entity.valid? ? entity.transformation.to_a : []) rescue []
      # 6.66：恢复候选 SKP 本体已经是事故恢复的权威内容；这个 sidecar 只是说明性元数据。
      # 不再为 1~3KB JSON 强制 fsync。实机 6.65 中这一行单独放大到约 1.2s。
      fast_atomic_write_file("#{path}.json", JSON.pretty_generate(metadata))

      safe_name = plan['safe_name'].to_s
      unless safe_name.empty?
        prefix = File.join(File.dirname(path), "PUBLISH_#{safe_name}_*.skp")
        Dir.glob(prefix).sort_by { |candidate| File.mtime(candidate) rescue Time.at(0) }.reverse_each.with_index do |candidate, index|
          next if index < 3
          File.delete(candidate) if File.file?(candidate)
          sidecar = "#{candidate}.json"
          File.delete(sidecar) if File.file?(sidecar)
        rescue StandardError
          next
        end
      end

      publish_breadcrumb!(
        'space_recovery_candidate_copy_returned',
        path: path, size: File.size(path), elapsed_ms: elapsed_ms(started)
      )
      log("#{plan['context']}恢复快照已从本次候选复制：#{File.basename(path)} / #{File.size(path)} bytes / #{elapsed_ms(started)}ms")
      path
    rescue StandardError => e
      begin
        File.delete(path) if defined?(path) && path && File.file?(path)
        sidecar = "#{path}.json" if defined?(path) && path
        File.delete(sidecar) if defined?(sidecar) && sidecar && File.file?(sidecar)
      rescue StandardError
        nil
      end
      log_exception('从发布候选创建当前空间恢复快照失败', e)
      raise e
    end

    # v0.13.6.67：候选本来就在本机 C 盘时，直接把它“认领”为恢复快照。
    # 同卷 File.rename 只是目录项移动，通常是毫秒级；不再为了恢复快照复制整份 SKP。
    # 如果 TEMP 与 LOCALAPPDATA 不在同一卷，保留旧的后台 copy 路径。
    def adopt_background_publish_candidate_as_recovery!(plan, prepared_candidate)
      return false unless plan.is_a?(Hash) && prepared_candidate.is_a?(Hash)
      source = prepared_candidate[:path].to_s
      destination = plan['snapshot_file'].to_s
      return false if source.empty? || destination.empty? || !File.file?(source)
      src = FastPath.expand(source).tr('\\', '/')
      dst = FastPath.expand(destination).tr('\\', '/')
      src_volume = src[/\A[A-Za-z]:/]
      dst_volume = dst[/\A[A-Za-z]:/]
      return false if src_volume.to_s.empty? || dst_volume.to_s.empty? || !src_volume.casecmp?(dst_volume)
      FileUtils.mkdir_p(File.dirname(destination))
      File.delete(destination) if File.file?(destination)
      File.rename(source, destination)
      prepared_candidate[:path] = destination
      plan['candidate_adopted'] = true
      plan['adopted_at'] = Time.now.iso8601(6)
      publish_breadcrumb!('space_recovery_candidate_adopted', path: destination, size: File.size(destination))
      true
    rescue StandardError => e
      log_exception('后台发布候选认领为本机恢复快照失败，继续使用后台复制兜底', e)
      false
    end

    # v0.13.6.61：异步空间发布在主线程完成唯一一次 Definition 序列化后，
    # 恢复副本也交给后台 I/O worker。此函数只操作普通文件和 JSON，不访问 SketchUp API。
    def persist_space_recovery_from_candidate_background!(plan, prepared_candidate, proxy_layout: true)
      return '' unless plan.is_a?(Hash)
      path = plan['snapshot_file'].to_s
      source = prepared_candidate.is_a?(Hash) ? prepared_candidate[:path].to_s : ''
      expected_size = prepared_candidate.is_a?(Hash) ? prepared_candidate[:size].to_i : 0
      expected_content = prepared_candidate.is_a?(Hash) ? prepared_candidate[:content_signature].to_s : ''
      raise '本机发布候选不存在，无法创建恢复副本。' if source.empty? || !File.file?(source)
      raise '本机发布候选为空，无法创建恢复副本。' unless expected_size.positive? && File.size(source) == expected_size
      raise '发布恢复副本路径无效。' if path.empty?

      started = monotonic_time
      adopted = !!plan['candidate_adopted'] && same_file_path?(source, path)
      if adopted
        publish_breadcrumb!(
          'space_recovery_candidate_reuse_begin', path: path, candidate_size: expected_size,
          representation: (proxy_layout ? 'proxy' : 'full'), background: true
        )
        raise '已认领的本机恢复候选不存在。' unless File.file?(path) && File.size(path) == expected_size
        # 候选内容 SHA 已由 worker 在同一路径上计算过；路径未变、大小未变时不再重复读整文件。
        current_fast = fast_file_signature(path)
        verified_fast = prepared_candidate[:verified_fast_signature].to_s
        if !verified_fast.empty? && current_fast != verified_fast
          raise '已认领的本机恢复候选在校验后发生变化。'
        end
      else
        publish_breadcrumb!(
          'space_recovery_candidate_copy_begin',
          source: source, path: path, candidate_size: expected_size,
          representation: (proxy_layout ? 'proxy' : 'full'), background: true
        )
        FileUtils.mkdir_p(File.dirname(path))
        file_operation_with_retry([0.0, 0.05, 0.15]) { linkhub_copy_file(source, path) }
        raise '当前空间发布恢复副本写出失败。' unless File.file?(path) && File.size(path) == expected_size
        unless expected_content.empty?
          copied_content = full_file_content_signature(path)
          raise '当前空间发布恢复副本内容校验失败。' unless copied_content == expected_content
        end
      end

      metadata = plan.dup
      metadata.delete('safe_name')
      metadata.delete('context')
      metadata['snapshot_representation'] = proxy_layout ? 'proxy_publish_candidate' : 'full_publish_candidate'
      metadata['candidate_size'] = expected_size
      metadata['candidate_content_signature'] = expected_content
      metadata['background_publish'] = true
      durable_write_file("#{path}.json", JSON.pretty_generate(metadata))

      safe_name = plan['safe_name'].to_s
      unless safe_name.empty?
        prefix = File.join(File.dirname(path), "PUBLISH_#{safe_name}_*.skp")
        Dir.glob(prefix).sort_by { |candidate| File.mtime(candidate) rescue Time.at(0) }.reverse_each.with_index do |candidate, index|
          next if index < 3
          File.delete(candidate) if File.file?(candidate)
          sidecar = "#{candidate}.json"
          File.delete(sidecar) if File.file?(sidecar)
        rescue StandardError
          next
        end
      end

      publish_breadcrumb!(
        (adopted ? 'space_recovery_candidate_reuse_returned' : 'space_recovery_candidate_copy_returned'),
        path: path, size: File.size(path), elapsed_ms: elapsed_ms(started), background: true
      )
      path
    rescue StandardError => e
      begin
        File.delete(path) if defined?(path) && path && File.file?(path)
        sidecar = "#{path}.json" if defined?(path) && path
        File.delete(sidecar) if defined?(sidecar) && sidecar && File.file?(sidecar)
      rescue StandardError
        nil
      end
      log_exception('后台从发布候选创建当前空间恢复快照失败', e)
      raise e
    end

    # 旧同步发布/兼容入口仍保留整份工作 SU 的安全保存策略。
    # v0.13.6.69 起，空间、建筑模型和景观/建筑异步发布都以“本机候选文件”作为恢复点，
    # 不再为每次后台发布额外保存整份工作 SU，避免前台固定卡顿和重复原生保存风险。
    def save_current_model_before_collab_publish!(model = Sketchup.active_model, context: '发布')
      raise '当前 SketchUp 模型无效，无法保存。' unless model
      source_path = model.path.to_s
      raise "请先保存当前 SketchUp 模型，再执行#{context}。" if source_path.empty?
      raise '当前模型正在执行发布前保存，请稍候。' if @publish_presave_in_progress

      @publish_presave_records ||= {}
      key = model.object_id
      generation = user_edit_generation(model)
      record = @publish_presave_records[key]
      file_signature = fast_file_signature(source_path)
      unchanged_since_safe_save = record.is_a?(Hash) &&
                                  record[:generation].to_i == generation &&
                                  record[:path].to_s == FastPath.expand(source_path).to_s &&
                                  !file_signature.empty?
      model_clean = model.respond_to?(:modified?) ? !model.modified? : false
      if model_clean || unchanged_since_safe_save
        reason = model_clean ? '当前工作 SU 未修改' : '自上次安全保存后没有新的用户建模事务'
        publish_breadcrumb!('work_model_save_skipped', context: context.to_s, reason: reason, generation: generation)
        log("#{context}前跳过重复整模保存：#{reason} / generation=#{generation}")
        @publish_presave_records[key] = {
          generation: generation,
          path: FastPath.expand(source_path),
          signature: file_signature,
          saved_at: Time.now.to_f
        }
        return true
      end

      @publish_presave_in_progress = true
      started = monotonic_time
      publish_breadcrumb!('work_model_save_begin', context: context.to_s, source: source_path, generation: generation)
      saved = model.save
      raise "当前模型保存失败，已停止#{context}。" if saved == false
      publish_breadcrumb!('work_model_save_returned', elapsed_ms: elapsed_ms(started), source: source_path)
      # 第一版继续保留 model.save 与 definition.save_as 之间的短安全窗口。发布网络
      # 阶段异步化需要整体拆分发布状态机，不能只删 sleep 后直接冒险连续原生保存。
      sleep(PUBLISH_POST_SAVE_SETTLE_SECONDS) if PUBLISH_POST_SAVE_SETTLE_SECONDS.positive?
      publish_breadcrumb!('work_model_save_settled', wait_seconds: PUBLISH_POST_SAVE_SETTLE_SECONDS)
      @publish_presave_records[key] = {
        generation: generation,
        path: FastPath.expand(source_path),
        signature: fast_file_signature(source_path),
        saved_at: Time.now.to_f
      }
      log("#{context}前已保存当前 SU：#{File.basename(source_path)} / #{elapsed_ms(started)}ms / generation=#{generation}")
      true
    rescue StandardError => e
      log_exception("#{context}前保存当前模型失败", e)
      raise e
    ensure
      @publish_presave_in_progress = false
    end

    def apply_published_collab_cache_to_state!(state, key, manifest, paths, project_manifest_path, model = Sketchup.active_model)
      link = state['links'][key]
      return false unless link
      link['collab_manifest_path'] = store_path(paths[:manifest], model)
      link['collab_project_manifest_path'] = store_path(project_manifest_path, model)
      link['collab_full_path'] = store_path(paths[:full], model)
      link['model_path'] = store_path(paths[:full], model) if %w[architecture landscape].include?(key.to_s)
      link['collab_cache_version'] = manifest['version'].to_i
      link['collab_revision_id'] = manifest['revision_id'].to_s
      link['collab_last_publish_at'] = manifest['generated_at'].to_s
      link['collab_full_signature'] = manifest['full_signature'].to_s
      link['collab_last_published_by'] = manifest['published_by'].to_s
      link['collab_last_publish_host'] = manifest['host'].to_s
      true
    end

    # 受管建筑直接提交到 *_FULL.skp 后，同步登记协同清单。
    # 这样其他成员不仅能从文件签名看到“有更新”，还能看到提交人和提交时间。
    def record_direct_collab_commit!(state, key, link, result, model = Sketchup.active_model)
      target = result[:path].to_s
      return false unless collab_shared_cache_model_path?(target)
      manifest_path = resolve_path(link['collab_manifest_path'].to_s, model)
      raise "找不到#{link['name']}协同 manifest.json，无法登记本次提交。" unless File.file?(manifest_path)
      existing = JSON.parse(File.read(manifest_path, mode: 'rb'))
      existing = {} unless existing.is_a?(Hash)
      generated_at = Time.now.iso8601(6)
      version = Time.now.strftime('%Y%m%d%H%M%S')
      revision_id = new_publish_revision("#{key}-direct")
      payload = existing.merge(
        'schema' => COLLAB_CACHE_SCHEMA,
        'kind' => 'sulink_collab_cache',
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => key.to_s,
        'discipline_name' => link['name'].to_s,
        'version' => version,
        'revision_id' => revision_id,
        'source_model' => model.path.to_s,
        'source_signature' => model.path.to_s.empty? ? '' : fast_file_signature(model.path.to_s),
        'generated_at' => generated_at,
        'published_by' => current_user_name,
        'host' => current_host_name,
        'full_path' => relative_to_dir(target, File.dirname(manifest_path)),
        'full_signature' => result[:signature].to_s
      )
      temp = "#{manifest_path}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(temp, manifest_path)

      project_json = resolve_path(link['collab_project_manifest_path'].to_s, model)
      project_dir = File.file?(project_json) ? File.dirname(project_json) : selected_collab_project_dir_for_state(state, model)
      unless project_dir.to_s.empty?
        project_json = write_project_collab_manifest!(
          project_dir,
          key,
          payload.merge('manifest_path' => manifest_path, 'full_resolved' => target)
        )
        link['collab_project_manifest_path'] = store_path(project_json, model)
      end
      link['collab_manifest_path'] = store_path(manifest_path, model)
      link['collab_full_path'] = store_path(target, model)
      link['collab_cache_version'] = version.to_i
      link['collab_revision_id'] = revision_id
      link['collab_last_publish_at'] = generated_at
      link['collab_full_signature'] = result[:signature].to_s
      link['collab_last_published_by'] = current_user_name
      link['collab_last_publish_host'] = current_host_name
      true
    rescue StandardError => e
      log_exception("登记#{link && link['name'] ? link['name'] : key}直接提交版本失败", e)
      false
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    # v0.13.6.69：建筑/景观首次 FULL 发布也统一为“前台本机候选 + 后台共享发布”。
    # 旧同步实现继续保留给其它兼容入口，但建筑/景观在 publish_collab_cache_sync 顶部直接分流到这里。
    def enqueue_first_discipline_background_publish!(state, key, info, source_path, model = Sketchup.active_model)
      discipline = key.to_s
      raise '只有建筑/景观首次发布可以进入专业后台队列。' unless %w[architecture landscape].include?(discipline)
      raise "#{info['name']}已经在后台发布队列中。" if managed_discipline_background_publish_active?(discipline)
      publish_guard_acquired = false
      operation_open = false
      enqueued = false
      publish_error = nil
      prepared = nil

      work_model_entity, work_model_needs_assignment = host_work_model_for_publish!(state, discipline, model)
      candidates = [work_model_entity]
      raw_count = 0
      project_dir = ensure_collab_project_ready!(state, model, interactive: true)
      raise '未选择协同项目文件夹，已取消发布。' if project_dir.to_s.empty?
      paths = collab_cache_paths_for(discipline, model, state)
      existing = [paths[:full], paths[:manifest]].compact.select { |candidate| File.file?(candidate.to_s) }
      unless existing.empty?
        raise "协同目录已经存在#{info['name']}发布文件，不能把当前本机状态当作首次发布覆盖。请先连接并更新到共享最新版；已保留现有文件：#{existing.join('；')}"
      end

      publish_guard_acquired = enter_publish_critical_section!(
        kind: "first_publish_#{discipline}", subject: "#{info['name']}首次发布候选封装", target: paths[:full], model: model
      )
      publish_breadcrumb!('first_publish_preflight', discipline: discipline, candidate_count: candidates.length, background_queue: true)
      publish_breadcrumb!(
        'work_model_recovery_deferred_to_candidate',
        context: "#{info['name']}首次发布",
        reason: '统一异步首次发布：本机 FULL 候选保留为恢复点，不再额外保存整份工作 SU'
      )
      version = Time.now.strftime('%Y%m%d%H%M%S')
      revision_id = new_publish_revision("#{discipline}-first")

      model.start_operation("生成#{info['name']}首次后台发布候选", true)
      operation_open = true
      full_definition = model.definitions.add("LH_COLLAB_#{info['code']}_FULL_#{SecureRandom.hex(5)}")
      add_publishable_entities_to_definition!(full_definition, candidates)
      raise "#{info['name']}工作模型没有可发布内容。" if full_definition.entities.to_a.empty?
      entity_count = count_definition_entities(full_definition)
      prepared = serialize_publish_definition_candidate!(full_definition, paths[:full], discipline, defer_content_signature: true)
      model.abort_operation
      operation_open = false

      work_name = if work_model_entity
                    candidate_name = work_model_entity.respond_to?(:name) ? work_model_entity.name.to_s.strip : ''
                    candidate_definition = work_model_entity.respond_to?(:definition) ? work_model_entity.definition : nil
                    candidate_name = candidate_definition.name.to_s.strip if candidate_name.empty? && candidate_definition && candidate_definition.respond_to?(:name)
                    candidate_name
                  else
                    ''
                  end
      manifest = {
        'schema' => COLLAB_CACHE_SCHEMA,
        'kind' => 'sulink_collab_cache',
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => discipline,
        'discipline_name' => info['name'],
        'version' => version,
        'revision_id' => revision_id,
        'source_model' => FastPath.expand(source_path.to_s),
        'source_signature' => fast_file_signature(source_path),
        'generated_at' => Time.now.iso8601(6),
        'published_by' => current_user_name,
        'host' => current_host_name,
        'full_path' => relative_to_dir(paths[:full], File.dirname(paths[:manifest])),
        'full_signature' => '',
        'top_level_instances' => candidates.length,
        'entity_count' => entity_count,
        'root_raw_geometry_skipped' => raw_count,
        'work_model_persistent_id' => work_model_entity && work_model_entity.respond_to?(:persistent_id) ? work_model_entity.persistent_id.to_i : 0,
        'work_model_name' => work_name
      }
      remember_host_work_model!(state, discipline, work_model_entity, model) if work_model_entity && work_model_needs_assignment
      link = state.dig('links', discipline)
      job_id = "bgfirst-#{discipline}-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"
      link['first_publish_pending'] = true
      link['first_publish_error'] = ''
      link['background_publish_state'] = 'queued'
      link['background_publish_job_id'] = job_id
      link['background_publish_candidate'] = prepared[:path].to_s
      link['background_publish_error'] = ''
      link['status'] = '首次发布已加入统一队列 · 本地工作模型保留'
      save_state(state, model, write_manifest: false)

      enqueue_space_publish_job!({
        job_id: job_id,
        job_kind: 'discipline_first',
        space_id: "discipline:#{discipline}",
        discipline: discipline,
        label: info['name'].to_s,
        target: paths[:full].to_s,
        publish_key: discipline,
        expected_signature: '',
        baseline_path: '',
        baseline_signature: '',
        source_model_path: model.path.to_s,
        model_object_id: model.object_id,
        prepared: prepared,
        initial_publish: true,
        first_manifest: manifest,
        first_manifest_path: paths[:manifest].to_s,
        project_dir: project_dir.to_s,
        work_model_persistent_id: manifest['work_model_persistent_id'].to_i
      }, model)
      enqueued = true
      show_publish_notice("#{info['name']}首次发布已加入统一队列；现在可以继续操作其它模型。", 'success')
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      {
        success: true,
        queued: true,
        key: discipline,
        job_id: job_id,
        full_path: paths[:full].to_s,
        manifest_path: paths[:manifest].to_s,
        message: "#{info['name']}首次发布已加入后台队列"
      }
    rescue StandardError => e
      publish_error = e
      model.abort_operation rescue nil if operation_open
      if prepared.is_a?(Hash) && !enqueued
        path = prepared[:path].to_s
        File.delete(path) if !path.empty? && File.file?(path)
      end
      if defined?(link) && link && !enqueued
        link['first_publish_pending'] = false
        link['first_publish_error'] = e.message.to_s
        link['background_publish_state'] = ''
        link['background_publish_job_id'] = ''
        link['background_publish_candidate'] = ''
        link['background_publish_error'] = e.message.to_s
        link['status'] = "首次发布未入队 · 本地工作模型保留 · #{e.message}"
        save_state(state, model, write_manifest: false) rescue nil
      end
      raise
    ensure
      leave_publish_critical_section!(success: !!enqueued, error: publish_error, model: model) if publish_guard_acquired
    end

    def publish_collab_cache_sync
      publish_guard_acquired = false
      publish_success = false
      publish_error = nil
      model = Sketchup.active_model
      raise '当前模型正在组件编辑层级内，请先退出组件编辑。' unless model_safe_for_reload?(model)

      source_path = model.path.to_s
      if source_path.empty?
        return { success: false, error: '用户取消保存当前模型。' } unless save_active_model
        source_path = model.path.to_s
      end

      state = load_state(model)
      key = host_discipline_for(state)
      raise '请先把“当前工作区”设置为建筑、软装＋硬装或景观，再发布协同缓存。' unless DISCIPLINES.key?(key)
      info = DISCIPLINES.fetch(key)
      if %w[architecture landscape].include?(key.to_s)
        return enqueue_first_discipline_background_publish!(state, key, info, source_path, model)
      end

      # 建筑与景观首次发布不再扫描整个模型根层级。用户当前选中的唯一群组/组件
      # 被确认为本专业工作模型；后续发布固定使用该实体，避免把参考、临时对象或
      # 其他根组件一起带入共享 FULL，也绕开根层级散线对首次发布的误阻止。
      work_model_entity = nil
      work_model_needs_assignment = false
      if host_work_model_discipline?(key) && host_discipline_for(state) == key
        work_model_entity, work_model_needs_assignment = host_work_model_for_publish!(state, key, model)
        candidates = [work_model_entity]
        raw_count = 0
      else
        candidates = key == 'architecture' ? architecture_publishable_root_entities(model) : publishable_root_entities_for_cache(model)
        raw_count = model.entities.grep(Sketchup::Face).length + model.entities.grep(Sketchup::Edge).length
        if key == 'architecture' && raw_count.positive?
          raise "建筑根层级仍有 #{raw_count} 条散线/散面。请先把建筑内容编组后再发布，避免共享建筑缺件。"
        end
      end
      raise '当前根层级没有可发布的群组或组件。请先把本专业内容放进群组/组件。' if candidates.empty?

      publish_guard_acquired = enter_publish_critical_section!(
        kind: "first_publish_#{key}",
        subject: "#{info['name']}首次发布",
        target: source_path,
        model: model
      )
      publish_breadcrumb!('first_publish_preflight', discipline: key, candidate_count: candidates.length)
      save_current_model_before_collab_publish!(model, context: "#{info['name']}首次发布")
      project_dir = ensure_collab_project_ready!(state, model, interactive: true)
      raise '未选择协同项目文件夹，已取消发布。' if project_dir.to_s.empty?
      paths = collab_cache_paths_for(key, model, state)
      existing_first_publish_assets = [paths[:full], paths[:manifest]].compact.select { |candidate| File.file?(candidate.to_s) }
      unless existing_first_publish_assets.empty?
        raise "协同目录已经存在#{info['name']}发布文件，不能把当前本机状态当作首次发布覆盖。请先连接并更新到共享最新版；已保留现有文件：#{existing_first_publish_assets.join('；')}"
      end
      version = Time.now.strftime('%Y%m%d%H%M%S')
      revision_id = new_publish_revision("#{key}-first")

      publish_breadcrumb!('first_publish_operation_start_begin', target: paths[:full])
      model.start_operation("发布#{info['name']} FULL 协同缓存", true)
      operation_open = true
      publish_breadcrumb!('first_publish_cache_save_begin', target: paths[:full])
      cache_result = save_collab_full_only_cache!(key, info, candidates, paths, model)
      publish_breadcrumb!('first_publish_cache_save_returned', signature: cache_result[:full_signature].to_s)
      model.abort_operation
      publish_breadcrumb!('first_publish_operation_aborted')
      operation_open = false

      manifest = {
        'schema' => COLLAB_CACHE_SCHEMA,
        'kind' => 'sulink_collab_cache',
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => key,
        'discipline_name' => info['name'],
        'version' => version,
        'revision_id' => revision_id,
        'source_model' => FastPath.expand(source_path),
        'source_signature' => fast_file_signature(source_path),
        'generated_at' => Time.now.iso8601(6),
        'published_by' => current_user_name,
        'host' => current_host_name,
        'full_path' => relative_to_dir(paths[:full], File.dirname(paths[:manifest])),
        'full_signature' => cache_result[:full_signature],
        'top_level_instances' => candidates.length,
        'entity_count' => cache_result[:entity_count],
        'root_raw_geometry_skipped' => raw_count,
        'work_model_persistent_id' => work_model_entity && work_model_entity.respond_to?(:persistent_id) ? work_model_entity.persistent_id.to_i : 0,
        'work_model_name' => if work_model_entity
                               candidate_name = work_model_entity.respond_to?(:name) ? work_model_entity.name.to_s.strip : ''
                               candidate_definition = work_model_entity.respond_to?(:definition) ? work_model_entity.definition : nil
                               candidate_name = candidate_definition.name.to_s.strip if candidate_name.empty? && candidate_definition && candidate_definition.respond_to?(:name)
                               candidate_name
                             else
                               ''
                             end
      }
      ensure_metadata_target!(paths[:manifest])
      discipline_manifest_temp = "#{paths[:manifest]}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      File.write(discipline_manifest_temp, JSON.pretty_generate(manifest), mode: 'w:UTF-8')
      # 首次发布的 manifest 也必须遵守 create-if-absent：另一台电脑若在 FULL 生成
      # 期间抢先建立了同专业 manifest，本次停止而不是把对方清单强制覆盖。
      promote_file_create_only!(discipline_manifest_temp, paths[:manifest])

      project_manifest_payload = manifest.merge(
        'manifest_path' => paths[:manifest],
        'full_resolved' => paths[:full]
      )
      project_manifest_path = write_project_collab_manifest!(project_dir, key, project_manifest_payload)
      apply_published_collab_cache_to_state!(state, key, manifest, paths, project_manifest_path, model)
      remember_host_work_model!(state, key, work_model_entity, model) if work_model_entity && work_model_needs_assignment
      if work_model_entity && host_work_model_discipline?(key) && !discipline_managed_collaboration?(state, key, model)
        takeover_published_host_work_model!(state, key, work_model_entity, model)
      end
      save_state(state, model)

      # 首次发布与后续发布使用同一套恢复兜底：公共“最近安全快照”用于抵御旧客户端
      # 覆盖，个人快照按 用户@电脑 独立保存，别人正常发布不会覆盖它。
      first_publish_content = full_file_content_signature(paths[:full])
      raise '首次发布正式 FULL 文件无法读取完整内容指纹，未把本次操作认定为安全发布。' if first_publish_content.empty?
      first_safe_checkpoint = write_latest_safe_publish_checkpoint!(
        paths[:full], key, signature: cache_result[:full_signature].to_s, expected_content_signature: first_publish_content
      )
      first_personal_source = !first_safe_checkpoint.to_s.empty? && File.file?(first_safe_checkpoint) ? first_safe_checkpoint : paths[:full]
      first_personal_checkpoint = write_personal_publish_checkpoint!(
        first_personal_source, key, signature: cache_result[:full_signature].to_s,
        published_target: paths[:full], expected_content_signature: first_publish_content
      )

      message = "#{info['name']}有材质协同缓存已发布"
      if first_personal_checkpoint.to_s.empty?
        message = "#{message}；警告：个人恢复快照未写入，请立即检查协同目录权限"
      end
      if work_model_entity
        work_name = state.dig('links', key, 'native_work_entity_name').to_s
        work_name = '当前选中组件' if work_name.empty?
        message = "#{message}；工作模型：#{work_name}"
      end
      message = "#{message}；已跳过 #{raw_count} 条根层级散线/散面" if raw_count.positive?
      show_publish_notice(message, 'success')
      refresh_dialog
      publish_success = true
      {
        success: true,
        key: key,
        version: version,
        manifest_path: paths[:manifest],
        project_manifest_path: project_manifest_path,
        full_path: paths[:full],
        safe_checkpoint: first_safe_checkpoint.to_s,
        personal_checkpoint: first_personal_checkpoint.to_s,
        generated_at: manifest['generated_at'],
        message: message
      }
    rescue StandardError => e
      publish_error = e
      begin
        model.abort_operation if defined?(operation_open) && operation_open && model
      rescue StandardError
        nil
      end
      log_exception('发布协同缓存失败', e)
      show_publish_notice("协同缓存发布失败：#{e.message}", 'error')
      { success: false, error: e.message.to_s }
    ensure
      File.delete(discipline_manifest_temp) if defined?(discipline_manifest_temp) && discipline_manifest_temp && File.file?(discipline_manifest_temp) rescue nil
      leave_publish_critical_section!(success: !!publish_success, error: publish_error, model: model) if publish_guard_acquired
    end

    def publish_collab_cache
      model = Sketchup.active_model
      state = load_state(model)
      key = host_discipline_for(state)
      message = '发布当前专业有材质协同缓存吗？'
      if host_work_model_discipline?(key) && !host_work_model_entity(state, key, model)
        entity = strict_selected_host_work_model_entity(model)
        name = DISCIPLINES.dig(key, 'name').to_s
        if entity
          label = entity.respond_to?(:name) ? entity.name.to_s.strip : ''
          definition = entity.respond_to?(:definition) ? entity.definition : nil
          label = definition.name.to_s.strip if label.empty? && definition && definition.respond_to?(:name)
          label = '当前选中组件' if label.empty?
          message = "将“#{label}”设为#{name}工作模型并首次发布吗？

之后发布会固定使用这个工作模型，不会把其他根对象一起打包；首次发布成功后会直接保持解锁修改，无需下载或重载。"
        else
          message = "首次发布#{name}前，请先在模型根层级只选中一个群组或组件。"
        end
      end
      return false unless native_confirm_yes?(message)
      result = publish_collab_cache_sync
      result && result[:success]
    rescue StandardError => e
      show_publish_notice("协同缓存发布失败：#{e.message}", 'error')
      false
    end

    def apply_collab_manifest_to_link!(state, key, manifest_path)
      manifest = read_collab_cache_manifest(manifest_path)
      manifest_key = manifest['discipline'].to_s
      if DISCIPLINES.key?(manifest_key) && manifest_key != key
        raise "该清单属于#{DISCIPLINES[manifest_key]['name']}，不能连接到#{DISCIPLINES[key]['name']}卡片。"
      end
      full = manifest['full_resolved']
      if source_used_by_other_discipline?(state, key, full)
        raise '这个协同缓存已经连接到其他专业。一个缓存清单只能归属一个专业。'
      end
      link = state['links'][key]
      link['model_path'] = store_path(full)
      link['collab_manifest_path'] = store_path(manifest['manifest_path'])
      link['collab_full_path'] = store_path(full)
      link['collab_cache_version'] = manifest['version'].to_i
      link['collab_revision_id'] = manifest['revision_id'].to_s
      link['collab_last_publish_at'] = manifest['generated_at'].to_s
      link['collab_full_signature'] = manifest['full_signature'].to_s
      link['collab_last_published_by'] = manifest['published_by'].to_s
      link['collab_last_publish_host'] = manifest['host'].to_s
      link['prefer_reference_package'] = true
      link['sync_strategy'] = 'direct'
      link['status'] = '已连接协同缓存 · 请点击更新'
      update_file_stamp(link, link['model_path'], full) if File.file?(full)
      clear_model_caches!(link)
      true
    end

    def erase_old_model_instances(key, model = Sketchup.active_model)
      old_definitions = []
      managed_model_entities(model, discipline: key).each do |entity|
        old_definitions << entity.definition if entity.is_a?(Sketchup::ComponentInstance)
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase! if entity.valid?
      end
      old_definitions
    end

    def remove_unused_managed_definitions(definitions, model = Sketchup.active_model)
      definitions.compact.uniq.each do |definition|
        next unless definition.valid?
        next unless definition.respond_to?(:instances) && definition.instances.empty?
        # 这些 definition 明确来自刚刚被替换的受管链接实例；无其他实例时可安全移除，
        # 这样同一路径重新载入时不会误用旧缓存。
        model.definitions.remove(definition) if model.definitions.respond_to?(:remove)
      rescue StandardError
        next
      end
    end

    def managed_model_instance_for(key, model = Sketchup.active_model)
      instances = managed_model_instances_for(key, model)
      instances.find { |entity| world_wrapper_instance?(entity) } || instances.first
    rescue StandardError
      nil
    end

    def direct_instance_current?(instance, stored_path, signature)
      return false unless instance && instance.valid?
      return false unless instance.get_attribute(ENTITY_DICT, 'display_mode', '').to_s == 'direct'
      return false unless same_file_path?(resolve_path(instance.get_attribute(ENTITY_DICT, 'source', '').to_s), resolve_path(stored_path))
      instance.get_attribute(ENTITY_DICT, 'source_signature', '').to_s == signature.to_s
    rescue StandardError
      false
    end

    def reload_definition_in_place!(instance, mirror_path, model)
      definition = instance.definition
      preserved_transform = instance.transformation
      if definition.respond_to?(:reload) && definition.instances.length <= 1
        begin
          result = definition.reload(mirror_path)
          raise 'SketchUp 未能原位重载本地镜像。' if result == false
          soft_invalidate_definition_bounds!(definition)
          # 某些模型改变坐标轴后，reload 可能连带改写实例矩阵；先恢复更新前的精确矩阵，
          # 后续再根据源坐标轴元数据做相对补偿。
          instance.transformation = preserved_transform if instance.valid?
          definition.set_attribute(ENTITY_DICT, 'loaded_from_newer_version', false)
          return [instance.definition, instance]
        rescue StandardError => error
          raise unless newer_model_version_error?(error)
        end
      end

      # 兼容回退：先载入新定义，成功后才删除旧实例，且沿用更新前的精确世界矩阵。
      loaded = load_definition_compat(model.definitions, mirror_path)
      raise '模型定义载入失败。' unless loaded
      new_instance = model.entities.add_instance(loaded, preserved_transform)
      raise '新专业模型实例创建失败。' unless new_instance && new_instance.valid?
      instance.locked = false if instance.respond_to?(:locked=)
      instance.erase! if instance.valid?
      [loaded, new_instance]
    end

    def load_linked_model(key, state, force: false)
      total_started = monotonic_time
      stages = {}
      model = Sketchup.active_model
      link = state['links'].fetch(key)
      if host_native_link?(state, key, model)
        return { ok: true, skipped: true, host_native: true, message: "#{link['name']}是当前工作专业，使用本文件原生内容，不建立自身外链", dependencies: [] }
      end
      stored_path = link['model_path'].to_s
      return { ok: true, skipped: true, no_source: true, message: '未设置模型文件', dependencies: [] } if stored_path.empty?

      stage = monotonic_time
      source_path = auto_relocate(stored_path, model)
      stages[:path] = elapsed_ms(stage)
      return { ok: false, message: "找不到模型文件：#{source_path}", dependencies: [] } unless File.file?(source_path)

      stage = monotonic_time
      source_sig = fast_file_signature(source_path)
      source_revision = authoritative_link_revision(link, source_path)
      source_revision = "file|#{source_sig}" if source_revision.empty?
      source_bytes = File.size(source_path) rescue 0
      link['source_size_mb'] = (source_bytes.to_f / 1024.0 / 1024.0).round(1)
      link['large_model_mode'] = source_bytes >= LINK_LARGE_SOURCE_BYTES
      asset = choose_load_asset(key, link, source_path, source_sig)
      effective_signature = "revision:#{source_revision}|file:#{source_sig}|asset:#{asset[:type]}|#{asset[:signature]}|filter:#{link['display_filter_enabled'] ? Array(link['display_selected_tags']).sort.join(',') : 'off'}|section:#{link['ignore_section_planes']}|world:#{WORLD_WRAPPER_SCHEMA}"
      stages[:asset] = elapsed_ms(stage)
      instance = managed_model_instance_for(key, model)
      sidecar_dependencies = read_sidecar_dependencies(source_path)
      unless force || !direct_instance_current?(instance, stored_path, effective_signature)
        dependencies = deduplicate_dependencies(sidecar_dependencies + Array(link['embedded_dependencies']))
        link['embedded_dependencies'] = dependencies
        link['embedded_link_count'] = dependencies.length
        link['mode'] = 'full'
        link['status'] = "已同步 · 绝对世界原位 · #{asset[:label]}"
        reapply_professional_visibility!(key, state, model)
        return { ok: true, skipped: true, unchanged: true, message: "#{link['name']}源模型无变化", dependencies: dependencies }
      end

      unless model_safe_for_reload?(model)
        raise SyncDeferredError, '当前正在编辑组件。请先退出组件编辑，再同步专业模型。'
      end

      link['status'] = instance ? "正在以绝对世界原位更新#{asset[:label]}…" : "正在以绝对世界原位载入#{asset[:label]}…"
      refresh_dialog
      before_layers = layer_snapshot(model)
      structure = ensure_professional_structure(key, model)
      had_instance = !!instance
      legacy_instance = instance && !world_wrapper_instance?(instance) ? instance : nil
      world_info = absolute_world_frame_for_asset(asset, source_path, link)
      world_frame = world_info[:transformation]

      # Parse/reload the source definition first. The final managed instance is always an identity
      # world wrapper; source model axis changes are absorbed by its internal child transform.
      stage = monotonic_time
      if instance && world_wrapper_instance?(instance)
        loaded_definition, source_child = reload_world_source_definition!(instance, asset[:path], model, key, stored_path)
      elsif legacy_instance && legacy_instance.valid?
        loaded_definition, legacy_instance = reload_definition_in_place!(legacy_instance, asset[:path], model)
        source_child = nil
      else
        loaded_definition = load_definition_compat(model.definitions, asset[:path])
        raise '模型定义载入失败。' unless loaded_definition
        source_child = nil
      end
      stages[:load] = elapsed_ms(stage)

      loaded_from_newer = definition_loaded_from_newer?(loaded_definition)
      link['source_newer_version'] = loaded_from_newer

      stage = monotonic_time
      section_count = link['ignore_section_planes'] ? strip_root_section_planes!(loaded_definition) : 0
      embedded = strip_embedded_references!(loaded_definition, source_path)
      stripped_count = loaded_definition.get_attribute(ENTITY_DICT, 'stripped_reference_count', 0).to_i
      link['last_stripped_reference_count'] = stripped_count
      dependencies = deduplicate_dependencies(sidecar_dependencies + embedded)
      link['embedded_dependencies'] = dependencies
      link['embedded_link_count'] = dependencies.length
      stages[:clean] = elapsed_ms(stage)

      stage = monotonic_time
      tag_limit = if source_bytes >= LINK_VERY_LARGE_SOURCE_BYTES
                    LINK_TAG_SCAN_LIMIT_VERY_LARGE
                  elsif source_bytes >= LINK_LARGE_SOURCE_BYTES
                    LINK_TAG_SCAN_LIMIT_LARGE
                  else
                    LINK_TAG_SCAN_LIMIT_NORMAL
                  end
      catalog_profile = container_tag_catalog_profile(loaded_definition, tag_limit)
      link['display_tag_catalog'] = catalog_profile[:names]
      link['display_tag_catalog_scanned'] = catalog_profile[:scanned].to_i
      link['display_tag_catalog_truncated'] = !!catalog_profile[:truncated]
      hidden_count = if link['display_filter_enabled'] && !Array(link['display_selected_tags']).empty?
                       apply_container_display_filter!(loaded_definition, link['display_selected_tags'])
                     else
                       0
                     end
      stages[:filter] = elapsed_ms(stage)

      stage = monotonic_time
      if instance && world_wrapper_instance?(instance)
        source_child ||= world_source_child(instance)
        if source_child && source_child.valid? && source_child.definition == loaded_definition
          source_child.transformation = world_frame
          set_world_source_child_attributes!(source_child, key, stored_path)
        else
          source_child = replace_world_source_child!(instance, loaded_definition, world_frame, key, stored_path)
        end
      else
        _wrapper_definition, source_child, new_outer = create_world_wrapper!(key, loaded_definition, world_frame, stored_path, model)
        if legacy_instance && legacy_instance.valid?
          legacy_instance.locked = false if legacy_instance.respond_to?(:locked=)
          legacy_instance.erase!
        end
        instance = new_outer
      end
      instance.transformation = identity_transformation
      duplicate_count = consolidate_managed_model_instances!(key, instance, model)
      stages[:world] = elapsed_ms(stage)

      organize_new_tags(before_layers, key, model)
      mark_entity(
        instance,
        discipline: key,
        kind: 'model',
        source: stored_path,
        display_name: "LH #{link['name']} 绝对世界原位 #{asset[:label]}",
        tag: structure[:model_tag],
        mode: 'direct',
        signature: effective_signature
      )
      instance.set_attribute(ENTITY_DICT, 'load_asset_path', asset[:path])
      instance.set_attribute(ENTITY_DICT, 'load_asset_type', asset[:type])
      instance.set_attribute(ENTITY_DICT, 'source_file_signature', source_sig)
      instance.set_attribute(ENTITY_DICT, 'source_revision', source_revision)
      instance.set_attribute(ENTITY_DICT, 'absolute_world', true)
      instance.set_attribute(ENTITY_DICT, 'world_wrapper_schema', WORLD_WRAPPER_SCHEMA)
      instance.locked = true if instance.respond_to?(:locked=)
      reapply_professional_visibility!(key, state, model)
      link['last_source_axes'] = world_info[:axes]
      link['last_instance_transform'] = identity_transformation_array
      link['absolute_world_enabled'] = true
      link['world_wrapper_schema'] = WORLD_WRAPPER_SCHEMA
      link['last_world_frame_source'] = world_info[:source]
      update_file_stamp(link, stored_path, source_path)
      link['mode'] = 'full'
      link['last_update'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      link['last_asset_type'] = asset[:type]
      link['last_section_plane_count'] = section_count
      link['last_load_ms'] = elapsed_ms(total_started)
      extras = []
      extras << "递归剔除#{stripped_count}个循环联动" if stripped_count.positive?
      extras << "清理#{duplicate_count}个重复联动实例" if duplicate_count.positive?
      extras << "移除#{section_count}个剖面" if section_count.positive?
      extras << "仅显示标记，隐藏#{hidden_count}个容器" if hidden_count.positive?
      extras << '高版本只读兼容' if loaded_from_newer
      if source_bytes >= LINK_LARGE_SOURCE_BYTES
        extras << "大模型保护（#{link['source_size_mb']}MB）"
        extras << "标记目录限量扫描#{tag_limit}项" if catalog_profile[:truncated]
        extras << '建议源专业生成筛选参考包' if asset[:type] == 'direct' && !valid_reference_package(source_path, source_sig)
      end
      extras << '绝对世界原位'
      extras << world_info[:warning] unless world_info[:warning].to_s.empty?
      suffix = extras.empty? ? '' : " · #{extras.join(' · ')}"
      link['status'] = "已同步 · #{asset[:label]} · #{link['last_load_ms']}ms#{suffix}"
      message = had_instance ? "#{link['name']}已按绝对世界原位更新" : "#{link['name']}已按绝对世界原位载入"
      message = "#{message}；#{extras.join('，')}" unless extras.empty?
      stages[:total] = elapsed_ms(total_started)
      log("更新 #{key}：总计#{stages[:total]}ms，路径#{stages[:path]}ms，资源准备#{stages[:asset]}ms，SKP解析#{stages[:load]}ms，循环净化#{stages[:clean]}ms，显示过滤#{stages[:filter]}ms，世界封装#{stages[:world]}ms，资源=#{asset[:type]}")
      { ok: true, message: message, dependencies: dependencies }
    rescue SyncDeferredError => e
      link['status'] = '等待安全同步' if link
      { ok: true, skipped: true, deferred: true, message: "#{link ? link['name'] : key}：#{e.message}", dependencies: sidecar_dependencies || [] }
    rescue StandardError => e
      log_exception("更新#{key}模型失败", e)
      link['status'] = '更新失败' if link
      { ok: false, message: "#{link ? link['name'] : key}模型更新失败：#{e.message}", dependencies: sidecar_dependencies || [] }
    end

    def update_file_stamp(link, stored_path, resolved_path)
      link['last_mtimes'][stored_path] = File.mtime(resolved_path).to_f
      link['last_sizes'][stored_path] = File.size(resolved_path)
      link['last_signatures'][stored_path] = watched_signature(resolved_path)
    rescue StandardError
      nil
    end

    def same_file_path?(first, second)
      return false if first.to_s.empty? || second.to_s.empty?
      FastPath.expand(first).tr('\\', '/').downcase == FastPath.expand(second).tr('\\', '/').downcase
    rescue StandardError
      first.to_s.downcase == second.to_s.downcase
    end

    def clear_model_caches!(link)
      link['embedded_dependencies'] = []
      link['embedded_link_count'] = 0
    end

    def active_model_file_path(model = Sketchup.active_model)
      path = model.path.to_s
      path.empty? ? '' : FastPath.expand(path)
    rescue StandardError
      model.path.to_s
    end

    def host_discipline_for(state)
      value = state['host_discipline'].to_s
      DISCIPLINES.key?(value) ? value : 'coordination'
    rescue StandardError
      'coordination'
    end


    def workspace_role_label(role)
      case role.to_s
      when 'architecture' then '建筑'
      when SPACE_COLLECTION_KEY then '硬装'
      when SOFT_SPACE_COLLECTION_KEY then '软装'
      when 'landscape' then '景观'
      else '协同'
      end
    end

    def normalize_workspace_role(value)
      role = value.to_s
      WORKSPACE_ROLES.include?(role) ? role : ''
    rescue StandardError
      ''
    end

    def current_workspace_role(model = Sketchup.active_model, state = nil)
      state ||= load_state(model)
      normalize_workspace_role(host_discipline_for(state))
    rescue StandardError
      ''
    end

    def lock_record_actor_role(record, fallback_role = '')
      role = normalize_workspace_role(record.is_a?(Hash) ? record['actor_role'] : '')
      role = normalize_workspace_role(fallback_role) if role.empty?
      role
    rescue StandardError
      ''
    end

    # 进程身份用于心跳和关闭清理；实际编辑/发布权限还必须绑定取得锁时的工作区。
    # 这样在同一个 SketchUp 中从“室内”切到“景观”后，不会因为 PID/session 相同
    # 而错误接管室内正在编辑的模型。
    def lock_record_owned_by_active_workspace?(record, token, fallback_role = '', model = Sketchup.active_model, state = nil)
      return false unless record.is_a?(Hash) && lock_record_from_current_process?(record)
      actor_role = lock_record_actor_role(record, fallback_role)
      current_role = current_workspace_role(model, state)
      return false if !actor_role.empty? && actor_role != current_role
      # 同进程、同工作区即可恢复真实锁 token；模型状态回滚可能留下旧 token，
      # 不能因此再次出现“自己占用自己”。工作区身份才是本版新增的权限边界。
      true
    rescue StandardError
      false
    end

    def authoritative_workspace_publish?(state, subject_role, lock_info = nil, model = Sketchup.active_model)
      expected_role = normalize_workspace_role(subject_role)
      current_role = current_workspace_role(model, state)
      return false if expected_role.empty?
      if lock_info.is_a?(Hash) && lock_info['owned']
        # 本人通过当前会话取得/接管的锁，跨专业编辑也允许做权威覆盖。
        # 原共享版本仍由 atomic_publish_definition 在覆盖前自动备份。
        owner = normalize_lock_identity(lock_info['owner'])
        return true if !owner.empty? && owner == normalize_lock_identity(current_user_name)
      end
      return false if current_role != expected_role
      return true unless lock_info.is_a?(Hash)
      actor_role = normalize_workspace_role(lock_info['actor_role'])
      lock_info['owned'] && (actor_role.empty? || actor_role == current_role)
    rescue StandardError
      false
    end

    # “当前工作区”只表示本文件的主要工作焦点。建筑与景观首次发布后，
    # 都切换为统一受管 FULL 根组件，不再继续把本机原生根对象当作长期发布源。
    def discipline_managed_collaboration?(state, key, model = Sketchup.active_model)
      discipline = key.to_s
      return false unless %w[architecture landscape].include?(discipline)
      return false unless host_discipline_for(state) == discipline
      link = state.dig('links', discipline)
      return false unless link
      flag_key = discipline == 'architecture' ? 'architecture_collab_managed' : 'landscape_collab_managed'
      return true if link[flag_key]
      !!managed_model_instance_for(discipline, model)
    rescue StandardError
      false
    end

    def architecture_managed_collaboration?(state, model = Sketchup.active_model)
      return true if architecture_collection_active?(state, model)
      discipline_managed_collaboration?(state, 'architecture', model)
    end

    def landscape_managed_collaboration?(state, model = Sketchup.active_model)
      discipline_managed_collaboration?(state, 'landscape', model)
    end

    def host_native_link?(state, key, model = Sketchup.active_model)
      discipline = key.to_s
      return false unless host_discipline_for(state) == discipline
      return false if discipline_managed_collaboration?(state, discipline, model)
      true
    rescue StandardError
      false
    end

    def refresh_discipline_collab_entry!(state, key, model = Sketchup.active_model)
      discipline = key.to_s
      link = state.dig('links', discipline)
      return nil unless link
      candidates = []
      candidates << resolve_path(link['collab_project_manifest_path'].to_s, model)
      selected_dir = selected_collab_project_dir_for_state(state, model)
      candidates << project_collab_json_for_dir(selected_dir) unless selected_dir.to_s.empty?
      json_path = candidates.map(&:to_s).reject(&:empty?).find { |path| File.file?(path) }
      return nil unless json_path
      project = read_project_collab_manifest(json_path, allow_empty: true)
      entry = project.dig('disciplines_resolved', discipline)
      return nil unless entry.is_a?(Hash)
      full = entry['full_resolved'].to_s
      return nil unless File.file?(full)

      link['model_path'] = store_path(full, model)
      link['collab_manifest_path'] = store_path(entry['manifest_resolved'].to_s, model)
      link['collab_project_manifest_path'] = store_path(project['manifest_path'].to_s, model)
      link['collab_full_path'] = store_path(full, model)
      link['collab_cache_version'] = entry['version'].to_i
      link['collab_revision_id'] = entry['revision_id'].to_s
      link['collab_last_publish_at'] = entry['generated_at'].to_s
      link['collab_full_signature'] = entry['full_signature'].to_s
      link['collab_last_published_by'] = entry['published_by'].to_s
      link['collab_last_publish_host'] = entry['host'].to_s
      link['prefer_reference_package'] = true
      link['sync_strategy'] = 'direct'
      link['enabled'] = true if link['enabled'].nil?
      entry
    rescue StandardError => e
      name = DISCIPLINES.dig(discipline, 'name').to_s
      log_exception("刷新#{name.empty? ? discipline : name}协同版本信息失败", e)
      nil
    end

    def refresh_architecture_collab_entry!(state, model = Sketchup.active_model)
      # 旧 links[architecture] 不再读取建筑_FULL、manifest 或旧锁。仅写入一个
      # 由新集合聚合得到的只读投影，满足尚未清理的通用 UI 字段读取。
      retire_legacy_architecture_runtime_state!(state, model)
      rows, = architecture_drawer_collection_state(state, model, detailed: true)
      link = state.dig('links', 'architecture') || {}
      editing = rows.any? { |row| row['editing_by_self'] == true }
      locked_other = rows.any? { |row| row['editing_by_other'] == true }
      pending = rows.any? { |row| row['status_code'].to_s == 'pending' }
      link['status_code'] = editing ? 'editing' : (locked_other ? 'locked' : (pending ? 'pending' : (rows.empty? ? 'empty' : 'current')))
      link['status_label'] = editing ? '待发布 · 修改中' : (locked_other ? '其他成员占用' : (pending ? '有建筑待更新' : (rows.empty? ? '待新增建筑模型' : '建筑模型已更新')))
      link['architecture_update_required'] = pending
      link['source_locked_by_other'] = locked_other
      link['source_lock_owned'] = editing
      link['loaded'] = rows.any? { |row| row['loaded'] == true }
      true
    rescue StandardError => e
      log_exception('刷新建筑集合投影失败', e)
      false
    end

    def refresh_landscape_collab_entry!(state, model = Sketchup.active_model)
      refresh_discipline_collab_entry!(state, 'landscape', model)
    end

    def self_reference_path?(path, model = Sketchup.active_model)
      active = active_model_file_path(model)
      return false if active.empty? || path.to_s.empty?
      same_file_path?(FastPath.expand(path.to_s), active)
    rescue StandardError
      false
    end

    def source_used_by_other_discipline?(state, target_key, resolved_path)
      state['links'].any? do |key, link|
        next false if key == target_key
        stored = link['model_path'].to_s
        next false if stored.empty?
        same_file_path?(auto_relocate(stored), resolved_path)
      end
    rescue StandardError
      false
    end

    def dependency_block_reason(state, origin_key, item, model = Sketchup.active_model)
      target_key = item['discipline'].to_s
      resolved = item['resolved_path'].to_s
      host_key = host_discipline_for(state)
      return '来源专业自身引用' if target_key == origin_key
      return '当前工作专业回流' if host_key != 'coordination' && target_key == host_key
      return '当前工作文件自引用' if self_reference_path?(resolved, model)
      origin_path = auto_relocate(state.dig('links', origin_key, 'model_path').to_s, model)
      return '来源模型自引用' if !origin_path.to_s.empty? && same_file_path?(origin_path, resolved)
      return '同一源文件已分配给其他专业' if source_used_by_other_discipline?(state, target_key, resolved)
      nil
    rescue StandardError
      nil
    end

    def purge_host_self_link!(state, model = Sketchup.active_model)
      host_key = host_discipline_for(state)
      return 0 if host_key == 'coordination'
      link = state['links'][host_key]
      return 0 unless link
      # 建筑/景观统一协作模式保留受管根组件与协同路径；这里不能再把它当成自引用清除。
      managed_flag = host_key == 'architecture' ? link['architecture_collab_managed'] : link['landscape_collab_managed']
      if %w[architecture landscape].include?(host_key) && (!link['collab_full_path'].to_s.empty? || managed_flag)
        return 0
      end
      removed = 0
      # 当前专业的原生内容永远不作为自己的外部链接。无论路径是否已保存，都清掉该卡片。
      unless link['model_path'].to_s.empty?
        link['model_path'] = ''
        clear_model_caches!(link)
      end
      managed_model_instances_for(host_key, model).each do |entity|
        entity.locked = false if entity.respond_to?(:locked=)
        entity.erase! if entity.valid?
        removed += 1
      rescue StandardError
        next
      end
      link['auto_update'] = false
      link['embedded_dependencies'] = []
      link['embedded_link_count'] = 0
      link['status'] = '当前工作专业 · 使用本文件原生内容'
      removed
    rescue StandardError => e
      log_exception('清理当前专业自引用失败', e)
      0
    end

    def apply_discovered_dependencies!(state, origin_key, dependencies)
      changed_keys = []
      messages = []
      return { changed_keys: changed_keys, messages: messages } unless state['auto_discover_dependencies']

      origin_link = state['links'][origin_key]
      origin_source = auto_relocate(origin_link['model_path'].to_s)
      blocked = []
      deduplicate_dependencies(dependencies).each do |item|
        target_key = item['discipline'].to_s
        kind = item['kind'].to_s
        resolved = item['resolved_path'].to_s
        next unless DISCIPLINES.key?(target_key)
        next unless File.file?(resolved)
        reason = dependency_block_reason(state, origin_key, item)
        if reason
          blocked << "#{DISCIPLINES[target_key]['name']}：#{reason}"
          next
        end
        next if same_file_path?(resolved, origin_source)

        target = state['links'][target_key]
        if kind == 'model'
          current_stored = target['model_path'].to_s
          current_resolved = auto_relocate(current_stored)
          if current_stored.empty?
            target['model_path'] = store_path(resolved)
            clear_model_caches!(target)
            target['last_source_axes'] = []
            target['coordinate_tracking_requested'] = request_coordinate_tracking(resolved) || coordinate_tracking_requested?(resolved)
            target['auto_update'] = false
            target['status'] = "由#{origin_link['name']}自动关联"
            changed_keys << target_key
            messages << "已自动补全#{target['name']}模型"
          elsif same_file_path?(current_resolved, resolved)
            next
          else
            messages << "发现#{target['name']}候选来源但未覆盖现有链接"
          end
        end
      end
      origin_link['last_blocked_backflow_count'] = blocked.length
      origin_link['last_blocked_backflow'] = blocked.uniq
      messages << "已拦截#{blocked.length}项循环回流" if blocked.any?
      { changed_keys: changed_keys.uniq, messages: messages.uniq }
    end

    # -------------------------
    # Cooperative checkout / edit lock
    # -------------------------

    def current_user_name
      ENV['USERNAME'].to_s.empty? ? (ENV['USER'].to_s.empty? ? '未知用户' : ENV['USER'].to_s) : ENV['USERNAME'].to_s
    rescue StandardError
      '未知用户'
    end

    def current_host_name
      name = Socket.gethostname.to_s
      name.empty? ? ENV['COMPUTERNAME'].to_s : name
    rescue StandardError
      ENV['COMPUTERNAME'].to_s.empty? ? '未知电脑' : ENV['COMPUTERNAME'].to_s
    end

    # 同一 Windows / 系统账号在异常退出、重启 SketchUp 或升级插件后，旧锁文件
    # 可能仍显示“zhou 编辑中”。这类锁不能继续按“其他成员”阻塞本人。
    # 只有旧锁不属于当前 SketchUp 进程时才允许自动中断；同一进程内不同工作区
    # 仍保持 v0.9.55 的隔离，避免景观在室内仍活跃时误接管。
    def normalize_lock_identity(value)
      value.to_s.strip.downcase
    rescue StandardError
      ''
    end

    def lock_record_owned_by_current_user?(record)
      return false unless record.is_a?(Hash)
      owner = normalize_lock_identity(record['owner'])
      current = normalize_lock_identity(current_user_name)
      return true if !owner.empty? && !current.empty? && owner == current
      # 极早期锁可能没有 owner；仅在 owner 缺失时以同电脑作为兼容回收条件。
      host = normalize_lock_identity(record['host'])
      current_host = normalize_lock_identity(current_host_name)
      owner.empty? && !host.empty? && !current_host.empty? && host == current_host
    rescue StandardError
      false
    end

    def same_user_lock_recoverable?(record)
      lock_record_owned_by_current_user?(record) && !lock_record_from_current_process?(record)
    rescue StandardError
      false
    end

    def interrupt_same_user_lock_file!(lock_path, source_path, record, label)
      return false unless File.file?(lock_path.to_s) && same_user_lock_recoverable?(record)
      begin
        annotated = record.dup
        annotated['interrupted_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        annotated['interrupted_reason'] = 'same_user_force_takeover'
        annotated['interrupted_by_owner'] = current_user_name
        annotated['interrupted_by_host'] = current_host_name
        annotated['interrupted_by_pid'] = Process.pid
        annotated['interrupted_by_session_id'] = current_runtime_session_id
        write_lock_record(lock_path, annotated, expected_token: record['token'])
      rescue StandardError => annotate_error
        log_exception('写入本人遗留锁中断记录失败', annotate_error)
      end
      # 注释写入与归档之间再核对一次 token，避免并发时误归档刚被其他会话接管的新锁。
      current = read_lock_record(lock_path)
      return false unless current && current['token'].to_s == record['token'].to_s && same_user_lock_recoverable?(current)
      archived = archive_lock_file(lock_path, source_path, label)
      File.delete(lock_path) if !archived && File.file?(lock_path)
      log("已强制中断本人遗留协作锁：#{File.basename(source_path.to_s)} / #{record['owner']}@#{record['host']} / PID #{record['pid']}")
      true
    rescue StandardError => e
      log_exception('中断本人遗留协作锁失败', e)
      false
    end

    # Active lock stays beside the source SKP as a temporary compatibility file so older
    # LinkHub versions can still see that somebody is submitting. It is deleted on release.
    def edit_lock_path_for(source_path)
      "#{source_path}#{LOCK_SUFFIX}"
    end

    def archive_lock_file(lock_path, source_path, label)
      return false unless File.file?(lock_path)
      filename = "#{File.basename(source_path.to_s)}.#{label}_#{Time.now.strftime('%Y%m%d_%H%M%S_%L')}_#{SecureRandom.hex(3)}.json"
      collab_root = collaboration_root_from_asset_path(source_path)
      target = if collab_root.empty?
                 metadata_file_path(source_path, File.join('locks', 'archive'), filename)
               else
                 File.join(collab_root, '_协作锁归档', filename)
               end
      ensure_metadata_target!(target) if collab_root.empty?
      FileUtils.mkdir_p(File.dirname(target))
      linkhub_mv(lock_path, target)
      true
    rescue StandardError => e
      log_exception('归档协作锁失败', e)
      false
    end

    def read_lock_record(lock_path)
      return nil unless File.file?(lock_path)
      value = JSON.parse(File.read(lock_path, mode: 'rb'))
      value.is_a?(Hash) ? value : nil
    rescue StandardError
      nil
    end

    def parse_time_value(value)
      Time.parse(value.to_s)
    rescue StandardError
      nil
    end

    def local_process_alive?(pid)
      value = pid.to_i
      return false if value <= 0
      Process.kill(0, value)
      true
    rescue Errno::EPERM
      true
    rescue StandardError
      false
    end

    # token 会随模型状态保存，不能单独作为“这是我的锁”的依据。SketchUp 异常退出后，
    # 新进程可能重新载入旧 token；若继续按 token 续期，旧锁就会被永久复活。
    # 本机锁必须同时属于当前电脑、当前 SketchUp 进程和当前 token。
    def current_runtime_session_id
      GavinTools::SULinkHubMultiSpace.const_get(:RUNTIME_SESSION_ID, false).to_s
    rescue StandardError
      "#{current_host_name}:#{Process.pid}"
    end

    def lock_record_from_current_process?(record)
      return false unless record.is_a?(Hash)
      host = record['host'].to_s
      same_host_pid = !host.empty? && host.casecmp(current_host_name).zero? && record['pid'].to_i == Process.pid
      return false unless same_host_pid
      session_id = record['session_id'].to_s
      session_id.empty? || session_id == current_runtime_session_id
    rescue StandardError
      false
    end

    def lock_record_from_replaced_current_session?(record)
      return false unless record.is_a?(Hash)
      host = record['host'].to_s
      return false if host.empty? || !host.casecmp(current_host_name).zero?
      return false unless record['pid'].to_i == Process.pid
      session_id = record['session_id'].to_s
      !session_id.empty? && session_id != current_runtime_session_id
    rescue StandardError
      false
    end

    def lock_record_owned_by_current_process?(record, token)
      value = token.to_s
      !value.empty? && record.is_a?(Hash) && record['token'].to_s == value && lock_record_from_current_process?(record)
    rescue StandardError
      false
    end

    def lock_record_stale?(record, lock_path = nil)
      return true unless record.is_a?(Hash)
      # 热重载、状态回滚或异常保存可能让模型里的 token 丢失，但锁文件仍属于
      # 当前 SketchUp 进程。此时绝不能让用户等待 10 分钟；同进程锁可立即接回。
      return false if lock_record_from_current_process?(record)
      return true if lock_record_from_replaced_current_session?(record)
      host = record['host'].to_s
      pid = record['pid'].to_i
      if !host.empty? && host.casecmp(current_host_name).zero?
        local_heartbeat = parse_time_value(record['heartbeat_at']) || parse_time_value(record['started_at'])
        if local_process_alive?(pid)
          return local_heartbeat ? (Time.now - local_heartbeat) > LOCK_REMOTE_STALE_SECONDS : false
        end
        # 同一台电脑可以可靠判断旧 SketchUp 进程是否仍存在；进程已死时立即回收，
        # 不再额外保留 60 秒，保证崩溃后重开即可恢复修改。
        return true
      end

      heartbeat = parse_time_value(record['heartbeat_at']) || parse_time_value(record['started_at'])
      if heartbeat
        return (Time.now - heartbeat) > LOCK_REMOTE_STALE_SECONDS
      end

      return (Time.now - File.mtime(lock_path)) > LOCK_REMOTE_STALE_SECONDS if lock_path && File.file?(lock_path)
      true
    rescue StandardError
      false
    end

    def source_lock_info(source_path, link = nil, model = Sketchup.active_model, state = nil)
      path = edit_lock_path_for(source_path)
      record = read_lock_record(path)
      return { 'exists' => false, 'path' => path, 'stale' => false, 'owned' => false, 'same_user' => false, 'same_user_recoverable' => false, 'actor_role' => '' } unless record

      state ||= load_state(model)
      fallback_role = link ? link['edit_actor_role'].to_s : ''
      actor_role = lock_record_actor_role(record, fallback_role)
      if actor_role.empty? && lock_record_from_current_process?(record)
        # 旧锁缺少 actor_role 时按被编辑模型自己的专业保守迁移，不能按当前
        # UI 工作区猜测，否则用户切到景观后第一次刷新就可能接管建筑/室内锁。
        actor_role = normalize_workspace_role(record['discipline'])
        actor_role = current_workspace_role(model, state) if actor_role.empty?
        record['actor_role'] = actor_role unless actor_role.empty?
        record['actor_role_name'] = workspace_role_label(actor_role) unless actor_role.empty?
        write_lock_record(path, record, expected_token: record['token']) unless actor_role.empty?
      end
      stale = lock_record_stale?(record, path)
      schedule_stale_lock_cleanup!(path, source_path, record, 'stale_source_auto') if stale
      exact_owned = link && lock_record_owned_by_current_process?(record, link['edit_lock_token'])
      active_owned = lock_record_owned_by_active_workspace?(record, link ? link['edit_lock_token'] : '', actor_role, model, state)
      if link && active_owned && !exact_owned
        link['edit_lock_token'] = record['token'].to_s
        link['edit_actor_role'] = actor_role
        link['edit_lock_path'] = store_path(path)
        link['edit_started_at'] = record['started_at'].to_s
        link['edit_owner'] = record['owner'].to_s
        link['edit_host'] = record['host'].to_s
        link['edit_pid'] = record['pid'].to_i
        log("已恢复当前#{workspace_role_label(actor_role)}工作区的#{link['name']}协作锁：#{File.basename(source_path.to_s)}")
      end
      {
        'exists' => true,
        'path' => path,
        'stale' => stale,
        'owned' => !!active_owned,
        'process_owned' => lock_record_from_current_process?(record),
        'same_user' => lock_record_owned_by_current_user?(record),
        'same_user_recoverable' => same_user_lock_recoverable?(record),
        'actor_role' => actor_role,
        'actor_role_name' => workspace_role_label(actor_role),
        'owner' => record['owner'].to_s,
        'host' => record['host'].to_s,
        'pid' => record['pid'].to_i,
        'started_at' => record['started_at'].to_s,
        'heartbeat_at' => record['heartbeat_at'].to_s,
        'project_name' => record['project_name'].to_s
      }
    rescue StandardError
      { 'exists' => false, 'path' => edit_lock_path_for(source_path), 'stale' => false, 'owned' => false, 'same_user' => false, 'same_user_recoverable' => false, 'actor_role' => '' }
    end

    def ensure_active_workspace_owns_source_lock!(link, source_path, model = Sketchup.active_model, state = nil, action: '操作')
      return { 'exists' => false, 'owned' => false } unless link && File.file?(source_path.to_s)
      state ||= load_state(model)
      info = source_lock_info(source_path, link, model, state)
      return info unless info['exists'] && !info['stale']
      return info if info['owned']
      if info['same_user_recoverable']
        discipline = normalize_workspace_role(link['discipline'])
        discipline = normalize_workspace_role(info['actor_role']) if discipline.empty?
        recovered = force_takeover_same_user_source_lock!(discipline, link, source_path, state, model)
        return recovered if recovered && recovered['owned']
      end
      role = info['actor_role_name'].to_s
      owner = info['owner'].to_s.empty? ? '其他成员' : info['owner'].to_s
      actor = role.empty? ? owner : "#{owner}（#{role}工作区）"
      raise "#{link['name']}正由#{actor}修改，当前#{workspace_role_label(current_workspace_role(model, state))}工作区不能#{action}。"
    end

    def write_lock_record(lock_path, record, exclusive: false, expected_token: nil)
      FileUtils.mkdir_p(File.dirname(lock_path.to_s))
      content = JSON.pretty_generate(record)
      if exclusive
        flags = File::WRONLY | File::CREAT | File::EXCL
        File.open(lock_path, flags, 0o644) do |file|
          file.write(content)
          file.flush
          file.fsync rescue nil
        end
        return true
      end

      expected = expected_token.to_s
      unless expected.empty?
        current = read_lock_record(lock_path)
        raise '协作锁已经被其他会话接管，已停止本次写入。' unless current && current['token'].to_s == expected
      end
      temp = "#{lock_path}.tmp-#{Process.pid}-#{SecureRandom.hex(4)}"
      File.open(temp, File::WRONLY | File::CREAT | File::TRUNC, 0o644) do |file|
        file.write(content)
        file.flush
        file.fsync rescue nil
      end
      parsed = JSON.parse(File.read(temp, mode: 'rb'))
      raise '协作锁临时文件校验失败。' unless parsed.is_a?(Hash) && parsed['token'].to_s == record['token'].to_s
      unless expected.empty?
        current = read_lock_record(lock_path)
        raise '协作锁在写入期间已经变化，已停止覆盖。' unless current && current['token'].to_s == expected
      end
      linkhub_mv(temp, lock_path)
      true
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def acquire_source_lock(key, link, source_path, state)
      lock_path = edit_lock_path_for(source_path)
      existing = read_lock_record(lock_path)
      if File.file?(lock_path) && existing.nil?
        unless archive_lock_file(lock_path, source_path, 'corrupt')
          raise '发现损坏的协作锁文件且无法清理，请检查文件权限。'
        end
      end
      if existing
        if lock_record_from_current_process?(existing)
          actor_role = lock_record_actor_role(existing, link['edit_actor_role'])
          actor_role = normalize_workspace_role(existing['discipline']) if actor_role.empty?
          actor_role = current_workspace_role(Sketchup.active_model, state) if actor_role.empty?
          current_role = current_workspace_role(Sketchup.active_model, state)
          if !actor_role.empty? && actor_role != current_role
            raise "#{link['name']}正由当前 SketchUp 中的#{workspace_role_label(actor_role)}工作区修改。请切回该工作区发布或结束修改，不能由#{workspace_role_label(current_role)}工作区接管。"
          end
          existing['actor_role'] = actor_role unless actor_role.empty?
          existing['actor_role_name'] = workspace_role_label(actor_role) unless actor_role.empty?
          existing['heartbeat_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
          write_lock_record(lock_path, existing, expected_token: existing['token'])
          existing['lock_path'] = lock_path
          log("接回当前#{workspace_role_label(actor_role)}工作区遗留的#{link['name']}协作锁")
          return existing
        elsif same_user_lock_recoverable?(existing)
          unless interrupt_same_user_lock_file!(lock_path, source_path, existing, 'same_user_takeover')
            raise "#{link['name']}的本人遗留占用无法中断，请检查协同文件夹权限。"
          end
          # 锁文件已归档；继续在下方创建当前进程的新锁。
        elsif lock_record_stale?(existing, lock_path)
          unless archive_lock_file(lock_path, source_path, 'stale')
            File.delete(lock_path) if File.file?(lock_path)
          end
        else
          owner = existing['owner'].to_s.empty? ? '其他成员' : existing['owner'].to_s
          host = existing['host'].to_s
          started = existing['started_at'].to_s
          if !host.empty? && host.casecmp(current_host_name).zero?
            raise "模型正在由同一台电脑上的另一个 SketchUp 进程使用（#{owner}，PID #{existing['pid']}，#{started}）。请先在那个窗口发布或关闭。"
          end
          raise "模型正在由#{owner}使用（#{host}，#{started}）。请等待对方通过 LinkHub“发布”或“取消修改”释放占用后再编辑。"
        end
      end

      now = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      record = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'token' => SecureRandom.hex(18),
        'discipline' => key,
        'discipline_name' => link['name'].to_s,
        'source_path' => source_path,
        'owner' => current_user_name,
        'host' => current_host_name,
        'pid' => Process.pid,
        'session_id' => current_runtime_session_id,
        'actor_role' => current_workspace_role(Sketchup.active_model, state),
        'actor_role_name' => workspace_role_label(current_workspace_role(Sketchup.active_model, state)),
        'started_at' => now,
        'heartbeat_at' => now,
        'project_name' => state['project_name'].to_s,
        'coordination_model' => Sketchup.active_model.path.to_s
      }
      write_lock_record(lock_path, record, exclusive: true)
      record['lock_path'] = lock_path
      record
    rescue Errno::EEXIST
      raise '模型刚刚被其他成员签出，请刷新后重试。'
    rescue Errno::EACCES
      raise '没有权限在源模型旁创建协作锁文件。请检查 NAS/文件夹写入权限。'
    end

    def force_takeover_same_user_source_lock!(key, link, source_path, state, model = Sketchup.active_model, allow_current_process: false)
      path = edit_lock_path_for(source_path)
      record = read_lock_record(path)
      return nil unless lock_record_owned_by_current_user?(record)
      if lock_record_from_current_process?(record)
        return nil unless allow_current_process
        previous_role = lock_record_actor_role(record, link['edit_actor_role'])
        current_role = current_workspace_role(model, state)
        record['previous_actor_role'] = previous_role unless previous_role.empty? || previous_role == current_role
        record['actor_role'] = current_role unless current_role.empty?
        record['actor_role_name'] = workspace_role_label(current_role) unless current_role.empty?
        record['owner'] = current_user_name if record['owner'].to_s.empty?
        record['workspace_rebound_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
        record['heartbeat_at'] = record['workspace_rebound_at']
        write_lock_record(path, record, expected_token: record['token'])
        fresh = record.merge('lock_path' => path)
        log("#{link['name']}显式发布：当前进程内本人锁已从#{workspace_role_label(previous_role)}切换到#{workspace_role_label(current_role)}。")
      else
        unless interrupt_same_user_lock_file!(path, source_path, record, 'same_user_force_publish')
          raise "#{link['name']}的本人遗留占用无法中断。"
        end
        fresh = acquire_source_lock(key, link, source_path, state)
      end
      assign_lock_state!(link, fresh, fast_file_signature(source_path))
      link['edit_session_active'] = true
      link['edit_workflow'] = "#{key}_same_user_recovered"
      link['status'] = "已中断 #{current_user_name} 的遗留编辑状态 · 当前会话已接管"
      save_state(state, model, write_manifest: false)
      log("#{link['name']}已由同名用户强制接管，允许继续修改或发布。")
      source_lock_info(source_path, link, model, state)
    end

    def lock_owned?(link, source_path, model = Sketchup.active_model, state = nil)
      record = read_lock_record(edit_lock_path_for(source_path))
      return false unless record
      state ||= load_state(model)
      actor_role = lock_record_actor_role(record, link ? link['edit_actor_role'] : '')
      owned = lock_record_owned_by_active_workspace?(record, link ? link['edit_lock_token'] : '', actor_role, model, state)
      if owned && link
        link['edit_lock_token'] = record['token'].to_s
        link['edit_actor_role'] = actor_role
      end
      owned
    rescue StandardError
      false
    end

    def heartbeat_edit_locks(state)
      now = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      recovered = false
      state['links'].each do |key, link|
        next unless link['edit_session_active']
        source = auto_relocate(link['model_path'].to_s)
        next unless File.file?(source)
        path = edit_lock_path_for(source)
        record = read_lock_record(path)
        next unless record
        exact_owned = lock_record_owned_by_current_process?(record, link['edit_lock_token'])
        same_process = lock_record_from_current_process?(record)
        next unless exact_owned || same_process
        actor_role = lock_record_actor_role(record, link['edit_actor_role'])
        actor_role = normalize_workspace_role(record['discipline']) if actor_role.empty?
        actor_role = normalize_workspace_role(key) if actor_role.empty?
        record['actor_role'] = actor_role unless actor_role.empty?
        record['actor_role_name'] = workspace_role_label(actor_role) unless actor_role.empty?
        if same_process && !exact_owned
          link['edit_lock_token'] = record['token'].to_s
          link['edit_actor_role'] = actor_role
          link['edit_lock_path'] = store_path(path)
          link['edit_started_at'] = record['started_at'].to_s
          link['edit_owner'] = record['owner'].to_s
          link['edit_host'] = record['host'].to_s
          link['edit_pid'] = record['pid'].to_i
          recovered = true
        end
        record['heartbeat_at'] = now
        write_lock_record(path, record, expected_token: record['token'])
      rescue StandardError => e
        log_exception('更新协作锁心跳失败', e)
      end
      recovered
    end

    def heartbeat_edit_locks_if_due(state, interval = 30.0)
      return false unless state['links'].any? { |_key, link| link['edit_session_active'] }
      @edit_lock_heartbeat_at ||= 0.0
      now = monotonic_time
      return false if now - @edit_lock_heartbeat_at < interval.to_f
      recovered = heartbeat_edit_locks(state)
      @edit_lock_heartbeat_at = now
      recovered
    rescue StandardError
      false
    end

    def release_source_lock(link, source_path, model = Sketchup.active_model, state = nil, process_cleanup: false)
      path = edit_lock_path_for(source_path)
      record = read_lock_record(path)
      return false unless record
      owned = if process_cleanup
                lock_record_owned_by_current_process?(record, link['edit_lock_token']) || lock_record_from_current_process?(record)
              else
                state ||= load_state(model)
                lock_record_owned_by_active_workspace?(record, link['edit_lock_token'], link['edit_actor_role'], model, state)
              end
      return false unless owned
      File.delete(path) if File.file?(path)
      true
    rescue StandardError => e
      log_exception('释放协作锁失败', e)
      false
    end

    def release_current_process_lock_file!(lock_path, token)
      path = lock_path.to_s
      return false if path.empty?
      record = read_lock_record(path)
      return false unless lock_record_owned_by_current_process?(record, token) || lock_record_from_current_process?(record)
      File.delete(path) if File.file?(path)
      true
    rescue StandardError => e
      log_exception('关闭模型时释放协作锁失败', e)
      false
    end

    # 关闭模型/退出 SketchUp 的清理只能删除外部锁文件，绝不 set_attribute、
    # 改组件锁定状态或保存模型，避免影响原生保存提示与 Undo。
    def release_model_collaboration_locks!(model = Sketchup.active_model)
      return false unless model
      state = load_state(model)
      released = 0
      state['links'].each_value do |link|
        token = link['edit_lock_token'].to_s
        stored = link['model_path'].to_s
        lock_paths = []
        recorded_lock = link['edit_lock_path'].to_s
        lock_paths << resolve_path(recorded_lock, model) unless recorded_lock.empty?
        lock_paths << edit_lock_path_for(resolve_path(stored, model)) unless stored.empty?
        next if lock_paths.empty?
        # 正常退出时以锁文件记录的 host / pid / session_id 为最终依据。即使模型状态
        # 尚未来得及保存 token，也能删除本进程自己创建的锁，避免关闭 SU 后残留修改中。
        released += 1 if lock_paths.uniq.any? { |path| release_current_process_lock_file!(path, token) }
      end
      [Array(state['space_models']), Array(state['architecture_models'])].flatten.each do |item|
        token = item['edit_lock_token'].to_s
        stored = item['model_path'].to_s
        next if stored.empty?
        source = resolve_path(stored, model)
        released += 1 if release_current_process_lock_file!(edit_lock_path_for(source), token)
      end
      log("关闭模型已释放 #{released} 个本进程协作锁") if released.positive?
      true
    rescue StandardError => e
      log_exception('关闭模型时清理协作锁失败', e)
      false
    end

    def release_all_model_collaboration_locks!
      models = []
      (@coordinate_model_observers || {}).each_value do |record|
        model = record.is_a?(Hash) ? record[:model] : nil
        models << model if model
      end
      active = Sketchup.active_model rescue nil
      models << active if active
      models.compact.uniq { |model| model.object_id }.each do |model|
        release_model_collaboration_locks!(model)
      end
      true
    rescue StandardError => e
      log_exception('退出 SketchUp 时清理协作锁失败', e)
      false
    end

    def assign_lock_state!(link, record, source_signature_value)
      link['edit_lock_token'] = record['token'].to_s
      link['edit_actor_role'] = lock_record_actor_role(record, link['edit_actor_role'])
      link['edit_lock_path'] = store_path(record['lock_path'].to_s)
      link['edit_source_signature'] = source_signature_value.to_s
      link['edit_started_at'] = record['started_at'].to_s
      link['edit_owner'] = record['owner'].to_s
      link['edit_host'] = record['host'].to_s
      link['edit_pid'] = record['pid'].to_i
    end

    def clear_edit_state!(link, restore_previous: false)
      if restore_previous
        link['mode'] = 'full'
        link['auto_update'] = false
      end
      link['edit_session_active'] = false
      link['edit_lock_token'] = ''
      link['edit_actor_role'] = ''
      link['edit_lock_path'] = ''
      link['edit_source_signature'] = ''
      link['edit_started_at'] = ''
      link['edit_owner'] = ''
      link['edit_host'] = ''
      link['edit_pid'] = 0
      link['edit_previous_mode'] = link['mode'].to_s
      link['edit_previous_auto_update'] = false
      link['edit_workflow'] = 'native_inline'
      link['edit_safe_paused'] = false
      link['edit_safe_paused_at'] = ''
      link['edit_safe_pause_reason'] = ''
    end

    def monotonic_time
      Process.clock_gettime(Process::CLOCK_MONOTONIC)
    rescue StandardError
      Time.now.to_f
    end

    def elapsed_ms(started_at)
      ((monotonic_time - started_at.to_f) * 1000.0).round
    rescue StandardError
      0
    end

    # 记录最近一次真实交互。所有后台缓存、外包盒预热与延迟清理都应主动避让，
    # 而不是和用户的移动、缩放、选择、抽屉动画争抢同一个 SketchUp 主线程。
    def note_runtime_interaction!(model = Sketchup.active_model, source: :foreground)
      return false unless model
      @runtime_last_interaction_at ||= {}
      @runtime_last_interaction_sources ||= {}
      key = model.object_id
      @runtime_last_interaction_at[key] = monotonic_time
      @runtime_last_interaction_sources[key] = source.to_s
      true
    rescue StandardError
      false
    end

    def runtime_last_interaction_source(model = Sketchup.active_model)
      return '' unless model
      (@runtime_last_interaction_sources || {})[model.object_id].to_s
    rescue StandardError
      ''
    end

    def background_work_idle?(model = Sketchup.active_model, min_idle: BACKGROUND_WORK_IDLE_SECONDS)
      return false unless model
      return false if @updating || soft_heavy_interaction? || publish_critical_section? || publish_post_quiet?
      # 发布队列优先。代真缓存预热、定义边界预热等可恢复任务在发布期间暂停，
      # 避免与候选保存、外部 SHA 和用户进入空间同时争用磁盘及 Ruby 时间片。
      return false if any_background_publish_active?
      # 六面代理分片之间 source_definition 仍是任务输入，不能让通用定义清理
      # 把它当成“当前无实例”的闲置定义移除。
      return false if @soft_visual_proxy_upgrade_job
      return false if workspace_toolbar_fast_interaction_active?(model)
      return false if @soft_thumbnail_rendering || @soft_library_scanning
      last = (@runtime_last_interaction_at || {})[model.object_id].to_f
      last <= 0.0 || (monotonic_time - last) >= min_idle.to_f
    rescue StandardError
      false
    end

    def log_slow_operation(label, started_at, threshold_ms = PERFORMANCE_SLOW_OPERATION_MS, details = nil)
      value = elapsed_ms(started_at)
      return value if value < threshold_ms.to_f
      suffix = details.to_s.strip
      suffix = suffix.empty? ? '' : " · #{suffix}"
      log("性能记录：#{label} #{value}ms#{suffix}")
      value
    rescue StandardError
      0
    end

    # 编辑签出走快速路径：配置路径存在时绝不递归搜索项目目录。
    # 只有路径确实失效时，才回退到较慢的自动重新定位。
    def resolve_source_for_edit(stored_path, model = Sketchup.active_model)
      direct = resolve_path(stored_path, model)
      return direct if File.file?(direct)
      auto_relocate(stored_path, model)
    rescue StandardError
      resolve_path(stored_path, model)
    end

    def windows_platform?
      return Sketchup.platform == :platform_win if Sketchup.respond_to?(:platform)
      !!(RUBY_PLATFORM =~ /mswin|mingw|cygwin/i)
    rescue StandardError
      !!(RUBY_PLATFORM =~ /mswin|mingw|cygwin/i)
    end

    # v0.5.4：不再在 SketchUp 的 Ruby 进程内使用 Fiddle 调用 Win32 API。
    # 文件占用检测改由独立 PowerShell 子进程完成；即使系统调用异常，
    # 也不会破坏 SketchUp 内置 Ruby 运行时或导致整个 SketchUp 闪退。
    def run_child_with_timeout(environment, command, timeout_seconds: 8.0)
      pid = Process.spawn(environment, *command, out: File::NULL, err: File::NULL)
      status = nil
      begin
        Timeout.timeout(timeout_seconds) do
          _waited_pid, status = Process.wait2(pid)
        end
      rescue Timeout::Error
        Process.kill('KILL', pid) rescue nil
        Process.wait(pid) rescue nil
        return { 'started' => true, 'timed_out' => true, 'exit_code' => -3 }
      end
      { 'started' => true, 'timed_out' => false, 'exit_code' => status.exitstatus.to_i }
    rescue Errno::ENOENT => e
      log_exception('启动外部安全检测进程失败', e)
      { 'started' => false, 'timed_out' => false, 'exit_code' => -4 }
    rescue StandardError => e
      log_exception('外部安全检测进程异常', e)
      { 'started' => false, 'timed_out' => false, 'exit_code' => -5 }
    end

    def powershell_command(script)
      [
        'powershell.exe', '-NoLogo', '-NoProfile', '-NonInteractive',
        '-WindowStyle', 'Hidden', '-ExecutionPolicy', 'Bypass', '-Command', script
      ]
    end

    def windows_exclusive_file_probe(path)
      source = FastPath.expand(path.to_s)
      script = <<~'POWERSHELL'.gsub(/\s+/, ' ').strip
        $ErrorActionPreference = 'Stop';
        $p = $env:SU_LINKHUB_PROBE_PATH;
        try {
          $stream = [System.IO.File]::Open(
            $p,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::ReadWrite,
            [System.IO.FileShare]::None
          );
          $stream.Dispose();
          exit 0;
        } catch [System.UnauthorizedAccessException] {
          exit 5;
        } catch [System.IO.IOException] {
          exit 32;
        } catch {
          exit 1;
        }
      POWERSHELL
      result = run_child_with_timeout(
        { 'SU_LINKHUB_PROBE_PATH' => source },
        powershell_command(script),
        timeout_seconds: 3.0
      )

      unless result['started']
        return {
          'available' => false,
          'error_code' => result['exit_code'],
          'message' => '无法启动独立文件占用检测进程。为避免覆盖源模型，本次已阻止签出。'
        }
      end
      if result['timed_out']
        return {
          'available' => false,
          'error_code' => -3,
          'message' => '文件占用检测超时，项目盘或网络路径响应过慢。为避免覆盖，本次已阻止签出。'
        }
      end

      code = result['exit_code'].to_i
      return { 'available' => true, 'error_code' => 0 } if code.zero?

      message = case code
                when 5
                  '源 SKP 正在被占用，或当前账号没有写入权限。'
                when 32
                  '源 SKP 正在被其他 SketchUp 或程序占用。'
                else
                  "无法安全取得源 SKP 的独占访问权（检测退出码 #{code}）。"
                end
      { 'available' => false, 'error_code' => code, 'message' => message }
    rescue StandardError => e
      log_exception('独立 Windows 文件占用检测失败', e)
      {
        'available' => false,
        'error_code' => -2,
        'message' => '无法确认源模型是否被占用，为避免覆盖，本次已阻止签出。'
      }
    end

    def portable_exclusive_file_probe(path)
      File.open(path, File::RDWR) do |file|
        acquired = file.flock(File::LOCK_EX | File::LOCK_NB)
        return { 'available' => false, 'error_code' => 33 } unless acquired
        file.flock(File::LOCK_UN)
      end
      { 'available' => true, 'error_code' => 0 }
    rescue Errno::EACCES, Errno::EPERM
      { 'available' => false, 'error_code' => 5 }
    rescue StandardError => e
      log_exception('通用文件占用检测失败', e)
      {
        'available' => false,
        'error_code' => -2,
        'message' => '无法确认源模型是否被占用，为避免覆盖，本次已阻止解锁。'
      }
    end

    # 协同缓存文件会被所有成员作为参考模型读取。
    # 提交时不能要求 *_FULL.skp 处于无人读取的独占状态，否则多人协同时
    # 只要有人连接建筑/硬装/软装缓存，就会误判为“文件被占用”。
    # 对这类共享缓存，提交安全性由 LinkHub 协作锁 + mtime/size 版本签名 + 原子写入验证负责。
    def collab_shared_cache_model_path?(path)
      text = FastPath.expand(path.to_s).tr('\\', '/') rescue path.to_s.tr('\\', '/')
      lower = text.downcase
      lower.include?('/_su_linkhub协同/') && lower.end_with?('_full.skp')
    rescue StandardError
      false
    end

    def should_skip_exclusive_probe_for_commit?(path)
      collab_shared_cache_model_path?(path)
    rescue StandardError
      false
    end

    def source_edit_availability(source_path)
      source = FastPath.expand(source_path.to_s)
      return { 'available' => false, 'message' => "源模型不存在：#{source}" } unless File.file?(source)

      probe = windows_platform? ? windows_exclusive_file_probe(source) : portable_exclusive_file_probe(source)
      return probe if probe['available']

      code = probe['error_code'].to_i
      message = probe['message'].to_s
      if message.empty?
        message = case code
                  when 32, 33
                    '源 SKP 正在被其他 SketchUp 或程序占用。'
                  when 5
                    '源 SKP 正在被占用，或当前账号没有独占访问权限。'
                  when 2, 3
                    '源 SKP 已被移动或删除。'
                  else
                    "无法取得源 SKP 的独占访问权（Windows 错误码 #{code}）。"
                  end
      end
      probe['message'] = message
      probe
    end

    def ensure_source_available_for_edit!(source_path, action_name)
      result = source_edit_availability(source_path)
      return true if result['available']

      raise SourceFileBusyError, "#{action_name}已取消：#{result['message']}\n请先关闭占用该文件的 SketchUp 窗口或其他程序，再重试。当前本地修改不会丢失。\n\n#{source_path}"
    end

    def push_edit_state_to_dialog(key, link)
      return unless @dialog && @dialog.visible?
      source = resolve_path(link['model_path'].to_s)
      lock_info = source.to_s.empty? ? { 'exists' => false, 'owned' => false } : source_lock_info(source, link)
      payload = {
        'edit_session_active' => !!link['edit_session_active'],
        'edit_workflow' => link['edit_workflow'].to_s,
        'edit_owner' => link['edit_owner'].to_s,
        'edit_host' => link['edit_host'].to_s,
        'auto_update' => !!link['auto_update'],
        'status' => link['status'].to_s,
        'status_code' => link['edit_session_active'] ? 'editing' : 'pending',
        'status_label' => link['edit_session_active'] ? '本机签出' : '待更新',
        'status_detail' => link['status'].to_s,
        'source_lock_exists' => !!lock_info['exists'],
        'source_lock_owned' => !!lock_info['owned'],
        'source_locked_by_other' => !!lock_info['exists'] && !lock_info['stale'] && !lock_info['owned'] && !lock_info['same_user_recoverable'],
        'source_lock_self_recoverable' => !!lock_info['same_user_recoverable']
      }
      json_key = JSON.generate(key.to_s)
      json_payload = JSON.generate(payload)
      @dialog.execute_script("window.LinkHub && window.LinkHub.patchLink(#{json_key}, #{json_payload});")
      true
    rescue StandardError => e
      log_exception('快速刷新签出状态失败', e)
      false
    end

    def shell_open_source_file(path)
      source = FastPath.expand(path.to_s)
      raise "找不到源模型：#{source}" unless File.file?(source)

      if windows_platform?
        # 由独立 PowerShell 进程调用 Windows 文件关联，不再在 SketchUp
        # 的 Ruby VM 内使用 ShellExecuteW/Fiddle，避免原生内存访问冲突。
        script = <<~'POWERSHELL'.gsub(/\s+/, ' ').strip
          $ErrorActionPreference = 'Stop';
          Start-Process -FilePath $env:SU_LINKHUB_OPEN_PATH;
        POWERSHELL
        pid = Process.spawn(
          { 'SU_LINKHUB_OPEN_PATH' => source },
          *powershell_command(script),
          out: File::NULL,
          err: File::NULL
        )
        Process.detach(pid)
        true
      else
        command = RUBY_PLATFORM =~ /darwin/i ? ['open', source] : ['xdg-open', source]
        pid = Process.spawn(*command, out: File::NULL, err: File::NULL)
        Process.detach(pid)
        true
      end
    rescue StandardError => e
      log_exception('打开源模型失败', e)
      raise "无法使用系统关联的 SketchUp 打开源模型：#{e.message}"
    end

    # -------------------------
    # v0.6.6 Native SketchUp lock workflow
    # -------------------------

    def edit_transition_quiet?
      monotonic_time < @edit_transition_quiet_until.to_f
    rescue StandardError
      false
    end

    def mark_edit_transition_quiet!
      @edit_transition_quiet_until = [@edit_transition_quiet_until.to_f, monotonic_time + EDIT_TRANSITION_QUIET_SECONDS].max
      true
    rescue StandardError
      false
    end

    def managed_edit_safe_paused?(link)
      !!(link && link['edit_safe_paused'])
    rescue StandardError
      false
    end

    def space_edit_safe_paused?(item)
      !!(item && item['edit_safe_paused'])
    rescue StandardError
      false
    end

    def paused_architecture_model_records(state)
      Array(state && state['architecture_models']).select { |item| space_edit_safe_paused?(item) }
    rescue StandardError
      []
    end

    def paused_space_edit_records(state)
      Array(state && state['space_models']).select { |item| space_edit_safe_paused?(item) }
    rescue StandardError
      []
    end

    def paused_space_edit_record(state)
      paused_space_edit_records(state).sort_by { |item| item['edit_safe_paused_at'].to_s }.last
    rescue StandardError
      nil
    end

    def clear_managed_safe_pause!(link)
      return false unless link
      link['edit_safe_paused'] = false
      link['edit_safe_paused_at'] = ''
      link['edit_safe_pause_reason'] = ''
      true
    end

    # 安全暂存状态同时存在于清单 item 与空间根实体属性中。两者必须原子清理，
    # 否则会出现“item 已恢复编辑/已发布，但实体仍 safe_paused=true”的幽灵会话：
    # 协作锁正常释放后，local_space_edit_session? 仍会把它判成未结束编辑，最终显示
    # “修改锁失效”。entity 参数可选以兼容旧调用点；所有状态边界都应传入实体。
    def clear_space_safe_pause!(item, entity = nil)
      return false unless item
      item['edit_safe_paused'] = false
      item['edit_safe_paused_at'] = ''
      item['edit_safe_pause_reason'] = ''
      if entity && entity.valid? && entity.respond_to?(:set_attribute)
        entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      end
      true
    end

    def entity_persistent_key(entity)
      return 0 unless entity && entity.valid?
      return entity.persistent_id.to_i if entity.respond_to?(:persistent_id)
      return entity.entityID.to_i if entity.respond_to?(:entityID)
      entity.object_id
    rescue StandardError
      0
    end

    # ComponentDefinition#guid 不是“定义对象身份”。SketchUp 在正常修改组件内部
    # 几何、材质、属性时可能刷新 GUID；若把 GUID 当作身份，每一次正常编辑都会
    # 被误判成“设为唯一/替换定义”。这里优先使用 persistent_id，并在同一运行代
    # 内直接比较定义对象引用；GUID 仅适合文件交换标识，不参与编辑防呆判断。
    def definition_identity_key(definition)
      return '' unless definition && definition.valid?
      pid = definition.respond_to?(:persistent_id) ? definition.persistent_id.to_i : 0
      return "pid:#{pid}" if pid.positive?
      "oid:#{definition.object_id}"
    rescue StandardError
      ''
    end

    def same_definition_identity?(current_definition, record)
      return false unless current_definition && current_definition.valid? && record.is_a?(Hash)
      baseline_definition = record[:definition]
      if baseline_definition && baseline_definition.respond_to?(:valid?) && baseline_definition.valid?
        return true if current_definition.equal?(baseline_definition) || current_definition == baseline_definition
      end
      baseline_key = record[:definition_key].to_s
      return true if baseline_key.empty?
      definition_identity_key(current_definition) == baseline_key
    rescue StandardError
      false
    end

    def edit_root_key_for_space(space_id)
      "space:#{space_id}"
    end

    def edit_root_key_for_architecture_model(architecture_id)
      "architecture_model:#{architecture_id}"
    end

    def architecture_id_from_edit_root_key(key)
      text = key.to_s
      text.start_with?('architecture_model:') ? text.split(':', 2)[1].to_s : ''
    end

    def active_path_inside_protected_root?(entity, model = Sketchup.active_model)
      return false unless entity && entity.valid? && model
      path = Array(model.active_path)
      !path.empty? && path.first == entity
    rescue StandardError
      false
    end

    def rebind_protected_definition!(entity, record)
      return false unless entity && entity.valid? && record.is_a?(Hash)
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      return false unless definition && definition.valid?
      record[:definition] = definition
      record[:definition_key] = definition_identity_key(definition)
      source = managed_discipline_edit_source_entity(entity)
      record[:source] = source
      record[:source_definition] = source && source.respond_to?(:definition) ? source.definition : nil
      record[:source_definition_key] = source && source.respond_to?(:definition) ? definition_identity_key(source.definition) : ''
      true
    rescue StandardError
      false
    end

    # SketchUp 的 Group 在第一次进入编辑、撤回后重做或自动唯一化时，可能在不改变
    # 外层实例身份/位置的情况下更换 definition 对象。只要用户此刻确实位于该受管
    # 根组件内部，就把它视为正常的内部编辑并刷新定义基线。
    def safely_rebind_protected_definition!(entity, record, model = Sketchup.active_model)
      return false unless active_path_inside_protected_root?(entity, model)
      rebind_protected_definition!(entity, record)
    rescue StandardError
      false
    end

    def root_guard_entity?(entity)
      entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group) ||
        entity.is_a?(Sketchup::Face) || entity.is_a?(Sketchup::Edge) ||
        (defined?(Sketchup::Image) && entity.is_a?(Sketchup::Image))
    rescue StandardError
      false
    end

    def root_guard_entity_ids(model = Sketchup.active_model)
      return [] unless model
      # 根层级很大时仍必须保护“误放家具/组件”这一条数据安全链。超过阈值只
      # 跳过散线散面，不再像旧逻辑那样把整个根层级新增对象检测完全关闭。
      # 这样大型项目里从组件库、复制粘贴或第三方插件误放到 model.entities 的
      # 群组/组件仍能在空间发布前被准确拦截。
      entities = model.entities.to_a
      if entities.length > EDIT_ROOT_GUARD_LIMIT
        entities.select do |entity|
          entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance) ||
            (defined?(Sketchup::Image) && entity.is_a?(Sketchup::Image))
        end.map { |entity| entity_persistent_key(entity) }.reject(&:zero?).sort
      else
        entities.select { |entity| root_guard_entity?(entity) }.map { |entity| entity_persistent_key(entity) }.reject(&:zero?).sort
      end
    rescue StandardError
      []
    end

    def managed_workspace_root_snapshot(model = Sketchup.active_model)
      return {} unless model
      snapshot = {}
      %w[architecture landscape].each do |discipline|
        snapshot[discipline] = managed_model_entities(model, discipline: discipline).map { |entity| entity_persistent_key(entity) }.reject(&:zero?).sort
      end
      architecture_model_entities(model).group_by { |entity| entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s }.each do |architecture_id, entities|
        next if architecture_id.empty?
        snapshot[edit_root_key_for_architecture_model(architecture_id)] = entities.map { |entity| entity_persistent_key(entity) }.reject(&:zero?).sort
      end
      space_model_entities(model).group_by { |entity| entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s }.each do |space_id, entities|
        next if space_id.empty?
        snapshot[edit_root_key_for_space(space_id)] = entities.map { |entity| entity_persistent_key(entity) }.reject(&:zero?).sort
      end
      snapshot
    rescue StandardError
      {}
    end

    def capture_edit_root_protection!(key, entity, model = Sketchup.active_model)
      return false unless model && entity && entity.valid?
      @edit_root_protections ||= {}
      source = managed_discipline_edit_source_entity(entity)
      @edit_root_protections[[model.object_id, key.to_s]] = {
        entity: entity,
        entity_pid: entity_persistent_key(entity),
        entity_class: entity.is_a?(Sketchup::Group) ? 'group' : 'component',
        definition: (entity.respond_to?(:definition) ? entity.definition : nil),
        definition_key: (entity.respond_to?(:definition) ? definition_identity_key(entity.definition) : ''),
        source: source,
        source_definition: (source && source.respond_to?(:definition) ? source.definition : nil),
        source_definition_key: (source && source.respond_to?(:definition) ? definition_identity_key(source.definition) : ''),
        transformation: (entity.respond_to?(:transformation) ? entity.transformation.to_a.map(&:to_f) : []),
        world_wrapper: world_wrapper_instance?(entity),
        wrapper_extra_count: world_wrapper_extra_content_count(entity),
        root_entity_ids: root_guard_entity_ids(model),
        root_guard_containers_only: model.entities.length > EDIT_ROOT_GUARD_LIMIT,
        managed_root_snapshot: managed_workspace_root_snapshot(model),
        captured_at: monotonic_time
      }
      true
    rescue StandardError => e
      log_exception('记录受管根模型保护基线失败', e)
      false
    end

    def clear_edit_root_protection!(key, model = Sketchup.active_model)
      @edit_root_protections&.delete([model.object_id, key.to_s]) if model
      true
    rescue StandardError
      false
    end

    def same_transformation_array?(left, right, tolerance = 1.0e-6)
      a = Array(left).map(&:to_f)
      b = Array(right).map(&:to_f)
      return false unless a.length == 16 && b.length == 16
      # SketchUp 在部分保存、撤回和动态组件事务后会产生极小浮点漂移。
      # 1e-8 对大型世界坐标过于敏感，会把没有可见位移的正常编辑误判为根组件移动。
      a.each_with_index.all? { |value, index| (value - b[index]).abs <= tolerance }
    rescue StandardError
      false
    end

    # 仅在受管根组件从模型根层级消失时执行有限深度搜索。正常状态全部走根索引，
    # 不会因为这个防呆功能扫描大型建筑内部。
    def find_nested_managed_entities(model, discipline: nil, space_id: nil, architecture_id: nil, limit: EDIT_DEEP_SCAN_LIMIT)
      return [] unless model
      queue = []
      model.entities.each do |entity|
        next unless entity.is_a?(Sketchup::ComponentInstance) || entity.is_a?(Sketchup::Group)
        queue << [entity, 0]
      end
      found = []
      seen_definitions = {}
      scanned = 0
      until queue.empty? || scanned >= limit.to_i
        entity, depth = queue.shift
        scanned += 1
        if depth.positive? && entity.respond_to?(:get_attribute) && entity.get_attribute(ENTITY_DICT, 'managed', false)
          entity_discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
          entity_space_id = entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s
          entity_architecture_id = entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s
          discipline_ok = discipline.to_s.empty? || entity_discipline == discipline.to_s
          space_ok = space_id.to_s.empty? || entity_space_id == space_id.to_s
          architecture_ok = architecture_id.to_s.empty? || entity_architecture_id == architecture_id.to_s
          found << entity if discipline_ok && space_ok && architecture_ok
        end
        definition = entity.respond_to?(:definition) ? entity.definition : nil
        next unless definition && definition.valid?
        def_key = definition.object_id
        next if seen_definitions[def_key]
        seen_definitions[def_key] = true
        definition.entities.each do |child|
          next unless child.is_a?(Sketchup::ComponentInstance) || child.is_a?(Sketchup::Group)
          queue << [child, depth + 1]
        end
      end
      found
    rescue StandardError
      []
    end

    def root_architecture_model_entities_for_id(architecture_id, model = Sketchup.active_model)
      return [] unless model
      model.entities.select do |entity|
        entity && entity.valid? && entity.respond_to?(:get_attribute) &&
          entity.get_attribute(ENTITY_DICT, 'managed', false) &&
          entity.get_attribute(ENTITY_DICT, 'kind', '').to_s == 'architecture_model' &&
          entity.get_attribute(ENTITY_DICT, 'architecture_id', '').to_s == architecture_id.to_s
      end
    rescue StandardError
      []
    end

    def root_space_entities_for_id(space_id, model = Sketchup.active_model)
      return [] unless model
      model.entities.select do |entity|
        entity && entity.valid? && entity.respond_to?(:get_attribute) &&
          entity.get_attribute(ENTITY_DICT, 'managed', false) &&
          entity.get_attribute(ENTITY_DICT, 'kind', '').to_s == 'space_model' &&
          entity.get_attribute(ENTITY_DICT, 'space_id', '').to_s == space_id.to_s
      end
    rescue StandardError
      []
    end

    def protected_workspace_root_issue(record, model = Sketchup.active_model)
      return '' unless record.is_a?(Hash) && model
      baseline = record[:managed_root_snapshot].is_a?(Hash) ? record[:managed_root_snapshot] : {}
      current = managed_workspace_root_snapshot(model)
      baseline.each do |root_key, ids|
        expected = Array(ids).map(&:to_i).reject(&:zero?).sort
        next if expected.empty?
        actual = Array(current[root_key]).map(&:to_i).reject(&:zero?).sort
        next if expected == actual
        label = if root_key.to_s.start_with?('space:')
                  space_id = root_key.to_s.split(':', 2)[1].to_s
                  state = load_state(model)
                  item = space_model_record(state, space_id)
                  item ? "空间 #{item['number']}:#{item['name']}" : "空间 #{space_id}"
                elsif root_key.to_s.start_with?('architecture_model:')
                  architecture_id = architecture_id_from_edit_root_key(root_key)
                  state = load_state(model)
                  item = architecture_model_record(state, architecture_id)
                  item ? "建筑 #{architecture_display_name(item, state)}" : "建筑 #{architecture_id}"
                else
                  DISCIPLINES.dig(root_key.to_s, 'name').to_s
                end
        label = root_key.to_s if label.empty?
        return "#{label}受管根组件被删除、复制、替换或嵌套"
      end
      ''
    rescue StandardError
      ''
    end

    def protected_unexpected_root_content_issue(record, model = Sketchup.active_model)
      return '' unless record.is_a?(Hash) && model && model.active_path.nil?
      baseline = Array(record[:root_entity_ids]).map(&:to_i)
      return '' if baseline.empty?
      containers_only = !!record[:root_guard_containers_only]
      additions = model.entities.select do |entity|
        guarded = if containers_only
                    entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance) ||
                      (defined?(Sketchup::Image) && entity.is_a?(Sketchup::Image))
                  else
                    root_guard_entity?(entity)
                  end
        guarded && !baseline.include?(entity_persistent_key(entity))
      end
      additions.reject! do |entity|
        entity.respond_to?(:get_attribute) && entity.get_attribute(ENTITY_DICT, 'managed', false)
      end
      return '' if additions.empty?
      kinds = additions.first(3).map do |entity|
        if entity.is_a?(Sketchup::Group)
          '群组'
        elsif entity.is_a?(Sketchup::ComponentInstance)
          '组件'
        elsif entity.is_a?(Sketchup::Face) || entity.is_a?(Sketchup::Edge)
          '散线/散面'
        else
          '对象'
        end
      end.uniq.join('、')
      "修改会话期间在模型根层级新增了#{additions.length}个#{kinds}；这些内容不会进入当前专业发布文件"
    rescue StandardError
      ''
    end

    # 只检查指定受管根模型本身。不同专业、不同空间是彼此独立的协同单元；
    # 当前空间发布不得因为其他受管空间/建筑被载入、更新、锁定或由其他成员修改而失败。
    # workspace_snapshot 仍只用于诊断；root_content 可由空间发布显式启用，专门阻止
    # 本次空间修改期间误写到整个 SKP 根层级的非受管对象。
    def protected_root_issue(key, model = Sketchup.active_model, include_workspace_snapshot: false, include_root_content: false)
      return '' unless model
      @edit_root_protections ||= {}
      record = @edit_root_protections[[model.object_id, key.to_s]]
      return '' unless record.is_a?(Hash)
      if key.to_s.start_with?('space:')
        space_id = key.to_s.split(':', 2)[1].to_s
        roots = root_space_entities_for_id(space_id, model)
        current = roots.first
        if current.nil?
          state = load_state(model)
          item = space_model_record(state, space_id)
          discipline = item ? space_record_collection_key(item) : SPACE_COLLECTION_KEY
          nested = find_nested_managed_entities(model, discipline: discipline, space_id: space_id)
          return nested.empty? ? '空间根组件被删除或炸开' : '空间根组件被意外成组、组件化或嵌套到其他对象内部'
        end
        return '同一个空间出现了多个受管根组件' if roots.length != 1
      elsif key.to_s.start_with?('architecture_model:')
        architecture_id = architecture_id_from_edit_root_key(key)
        roots = root_architecture_model_entities_for_id(architecture_id, model)
        current = roots.first
        if current.nil?
          nested = find_nested_managed_entities(model, discipline: 'architecture', architecture_id: architecture_id)
          return nested.empty? ? '建筑根组件被删除或炸开' : '建筑根组件被意外成组、组件化或嵌套到其他对象内部'
        end
        return '同一个建筑模型出现了多个受管根组件' if roots.length != 1
      else
        discipline = key.to_s
        roots = managed_model_entities(model, discipline: discipline)
        current = roots.first
        if current.nil?
          nested = find_nested_managed_entities(model, discipline: discipline)
          return nested.empty? ? "#{DISCIPLINES.dig(discipline, 'name')}根组件被删除或炸开" : "#{DISCIPLINES.dig(discipline, 'name')}根组件被意外成组、组件化或嵌套到其他对象内部"
        end
        return "同一专业出现了 #{roots.length} 个受管根组件" if roots.length != 1
      end
      current_pid = entity_persistent_key(current)
      same_root_object = record[:entity] && current.equal?(record[:entity])
      return '受管根组件被替换，已不再是开始修改时的对象' unless same_root_object || (current_pid.positive? && current_pid == record[:entity_pid].to_i)
      current_class = current.is_a?(Sketchup::Group) ? 'group' : 'component'
      return '受管根组件在修改期间被转换为另一种容器类型' unless current_class == record[:entity_class]
      if current.respond_to?(:definition) && !same_definition_identity?(current.definition, record)
        unless safely_rebind_protected_definition!(current, record, model)
          return '受管根组件被执行了“设为唯一/替换定义”等结构操作'
        end
      end
      if current.respond_to?(:transformation) && !same_transformation_array?(current.transformation.to_a, record[:transformation])
        if key.to_s.start_with?('architecture_model:')
          # 多建筑允许在建筑工作区整体移动/旋转/缩放。发布前会由
          # bake_space_outer_transformation! 把外层变换烘焙进独立建筑文件，
          # 因此这不是结构损坏，也不应在全面自检中被列为严重问题。
          record[:transformation] = current.transformation.to_a.map(&:to_f)
          record[:outer_transform_rebased_at] = monotonic_time
        else
          return '受管根组件在模型根层级被移动、旋转或缩放'
        end
      end
      if record[:world_wrapper] && world_wrapper_extra_content_count(current) > record[:wrapper_extra_count].to_i
        return '对象被误放入 LinkHub 世界坐标封装层；请进入真正的源模型组件后修改'
      end
      if include_workspace_snapshot
        workspace_issue = protected_workspace_root_issue(record, model)
        return workspace_issue unless workspace_issue.empty?
      end
      if include_root_content
        root_content_issue = protected_unexpected_root_content_issue(record, model)
        return root_content_issue unless root_content_issue.empty?
      end
      ''
    rescue StandardError => e
      log_exception('检查受管根模型结构失败', e)
      "结构检查异常：#{e.message}"
    end

    def local_managed_edit_session?(discipline, link, model = Sketchup.active_model)
      return false unless link.is_a?(Hash) && model
      state_active = !!link['edit_session_active'] || !!link['preview_edit_active'] || managed_edit_safe_paused?(link)
      # “待提交”可以在主动上锁后释放协作 token，但仍然是明确的本机本地状态。
      return true if link['preview_pending_publish']
      # 崩溃或旧版本可能留下单独的 token。只有 token 与真实会话状态同时存在时
      # 才把它算作本机修改，避免把陈旧状态纳入结构审计。
      return true if state_active && !link['edit_lock_token'].to_s.empty?
      return true if managed_edit_safe_paused?(link)
      entity = native_edit_entity(discipline, model)
      return false unless entity && entity.valid?
      local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) ||
                        entity.get_attribute(ENTITY_DICT, 'preview_editing', false) ||
                        entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      local_attribute || !entity_native_locked?(entity)
    rescue StandardError
      false
    end

    def local_space_edit_session?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      return false if linked_space_record?(item)
      space_id = item['id'].to_s
      return false if space_id.empty?
      state_active = state['space_editing_id'].to_s == space_id || !!item['editing'] || space_edit_safe_paused?(item)
      return true if state_active && !item['edit_lock_token'].to_s.empty?
      return true if space_edit_safe_paused?(item)
      entity = space_model_entity(space_id, model)
      return false unless entity && entity.valid?
      # 进入某个空间时，插件会临时解除其它参考空间根的原生锁，以免 SketchUp 把
      # 共享 Definition 的锁传播到内部组件。该解锁只是视口编辑兼容措施，不是这些
      # 参考空间的新修改会话，不能显示成“修改锁失效”。
      return false if space_reference_root_temporarily_unlocked?(item, entity, state, model)
      return false if space_reference_root_exit_transition?(item, entity, state, model)
      local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) ||
                        entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      local_attribute || !entity_native_locked?(entity)
    rescue StandardError
      false
    end

    def local_architecture_model_edit_session?(item, state, model = Sketchup.active_model)
      return false unless item.is_a?(Hash) && state.is_a?(Hash) && model
      architecture_id = item['id'].to_s
      return false if architecture_id.empty?
      state_active = state['architecture_editing_id'].to_s == architecture_id || !!item['editing'] || space_edit_safe_paused?(item)
      return true if state_active && !item['edit_lock_token'].to_s.empty?
      return true if space_edit_safe_paused?(item)
      entity = architecture_model_entity(architecture_id, model)
      return false unless entity && entity.valid?
      local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) ||
                        entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
      local_attribute || !entity_native_locked?(entity)
    rescue StandardError
      false
    end

    # 这里只返回当前 SketchUp 进程实际持有/暂存的修改会话。
    # item['editing'] 可能是旧状态或界面状态，不能据此把其他成员的空间纳入本机防呆检查。
    def active_edit_root_keys(state, model = Sketchup.active_model)
      keys = []
      %w[architecture landscape].each do |discipline|
        next if discipline == 'architecture' && architecture_collection_active?(state, model)
        link = state.dig('links', discipline)
        keys << discipline if local_managed_edit_session?(discipline, link, model)
      end
      Array(state['architecture_models']).each do |item|
        keys << edit_root_key_for_architecture_model(item['id']) if local_architecture_model_edit_session?(item, state, model)
      end
      Array(state['space_models']).each do |item|
        keys << edit_root_key_for_space(item['id']) if local_space_edit_session?(item, state, model)
      end
      keys.uniq
    rescue StandardError
      []
    end

    def rebuild_active_edit_root_protections!(model = Sketchup.active_model)
      return false unless model
      # 热重载/升级后丢弃旧版本留下的全局误报阻止状态，并按当前有效根模型重建基线。
      @edit_structure_blocked&.delete(model.object_id)
      @edit_structure_notified&.delete(model.object_id)
      state = load_state(model)
      active_edit_root_keys(state, model).each do |key|
        entity = if key.to_s.start_with?('space:')
                   space_model_entity(key.to_s.split(':', 2)[1], model)
                 elsif key.to_s.start_with?('architecture_model:')
                   architecture_model_entity(architecture_id_from_edit_root_key(key), model)
                 else
                   native_edit_entity(key, model)
                 end
        capture_edit_root_protection!(key, entity, model) if entity && entity.valid?
      end
      schedule_edit_structure_audit(model, 0.08)
      true
    rescue StandardError => e
      log_exception('恢复编辑根模型保护状态失败', e)
      false
    end

    def schedule_native_lock_sync(model = Sketchup.active_model, delay = 0.12)
      return false unless model
      return false if publish_critical_section? || publish_post_quiet? || edit_transition_quiet?
      @native_lock_sync_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(5)
      @native_lock_sync_tokens[key] = token
      runtime_start_timer(
        [delay.to_f, 0.08].max, false, label: 'edit:native_lock_sync',
        key: "edit:native_lock_sync:#{key}", model: model, active_model_only: true
      ) do
        next unless @native_lock_sync_tokens[key] == token
        # 右键原生解锁会产生事务，因此仍会在很短延迟后被纠正；连续建模事务只保留
        # 最后一项检查，不再堆积大量失效 timer。
        sync_native_preview_state(model) if native_lock_snapshot_changed?(model)
      end
      true
    rescue StandardError
      false
    end

    def schedule_edit_structure_audit(model = Sketchup.active_model, delay = EDIT_STRUCTURE_AUDIT_DELAY)
      return false unless model
      return false if publish_critical_section? || publish_post_quiet? || soft_heavy_interaction?
      @edit_structure_audit_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(5)
      @edit_structure_audit_tokens[key] = token
      runtime_start_timer(
        delay.to_f, false, label: 'edit:structure_audit', key: "edit:structure_audit:#{key}",
        model: model, active_model_only: true
      ) do
        next unless @edit_structure_audit_tokens[key] == token
        next if soft_heavy_interaction?
        audit_active_edit_structures(model)
      end
      true
    rescue StandardError
      false
    end

    def unlocked_managed_root_entries(state, model = Sketchup.active_model)
      entries = []
      # 只处理本机真实修改会话。模型载入/代真切换/更新事务中的瞬时解锁，或旧状态
      # 残留的未授权解锁，不应被“多个根同时修改”逻辑误接管。
      active_keys = active_edit_root_keys(state, model)
      %w[architecture landscape].each do |discipline|
        next unless active_keys.include?(discipline)
        entity = native_edit_entity(discipline, model)
        entries << [discipline, entity] if entity && entity.valid? && !entity_native_locked?(entity)
      end
      Array(state['architecture_models']).each do |item|
        key = edit_root_key_for_architecture_model(item['id'])
        next unless active_keys.include?(key)
        entity = architecture_model_entity(item['id'], model)
        entries << [key, entity] if entity && entity.valid? && !entity_native_locked?(entity)
      end
      Array(state['space_models']).each do |item|
        key = edit_root_key_for_space(item['id'])
        next unless active_keys.include?(key)
        entity = space_model_entity(item['id'], model)
        entries << [key, entity] if entity && entity.valid? && !entity_native_locked?(entity)
      end
      entries
    rescue StandardError
      []
    end

    def current_edit_focus_key(state, model = Sketchup.active_model, entries: nil)
      entries = unlocked_managed_root_entries(state, model) if entries.nil?
      path = Array(model.active_path)
      unless path.empty?
        root = path.first
        match = entries.find { |_key, entity| entity == root }
        return match.first if match
      end
      active_architecture_id = state['architecture_editing_id'].to_s
      unless active_architecture_id.empty?
        key = edit_root_key_for_architecture_model(active_architecture_id)
        return key if entries.any? { |entry_key, _entity| entry_key == key }
      end
      active_space_id = state['space_editing_id'].to_s
      unless active_space_id.empty?
        key = edit_root_key_for_space(active_space_id)
        return key if entries.any? { |entry_key, _entity| entry_key == key }
      end
      %w[architecture landscape].each do |discipline|
        link = state.dig('links', discipline) || {}
        next if managed_edit_safe_paused?(link)
        return discipline if entries.any? { |entry_key, _entity| entry_key == discipline }
      end
      entries.last && entries.last.first
    rescue StandardError
      nil
    end

    def repair_multiple_unlocked_managed_roots!(state, model = Sketchup.active_model)
      entries = unlocked_managed_root_entries(state, model)
      return false if entries.length <= 1
      keep_key = current_edit_focus_key(state, model, entries: entries)
      focus_group = if keep_key.to_s.start_with?('space:')
                      :space_collection
                    elsif keep_key.to_s.start_with?('architecture_model:')
                      :architecture_collection
                    else
                      keep_key.to_s
                    end
      keep_keys = entries.map(&:first).select do |key|
        if focus_group == :space_collection
          key.to_s.start_with?('space:')
        elsif focus_group == :architecture_collection
          key.to_s.start_with?('architecture_model:')
        else
          key.to_s == keep_key.to_s
        end
      end
      repair_entries = entries.reject { |key, _entity| keep_keys.include?(key) }
      # 同一室内集合或同一建筑集合的多个本机修改根同时解锁是 v0.13.0 的正常工作流。
      return false if repair_entries.empty?
      operation_open = false
      model.start_operation('修复跨专业受管根模型同时解锁', true, false, true)
      operation_open = true
      repair_entries.each do |key, entity|
        entity.locked = true if entity.respond_to?(:locked=)
        entity.set_attribute(ENTITY_DICT, 'safe_paused', true)
        if key.to_s.start_with?('space:')
          space_id = key.to_s.split(':', 2)[1].to_s
          item = space_model_record(state, space_id)
          next unless item
          lock = space_lock_info(item, model, state: state)
          owned_session = lock['exists'] && !lock['stale'] && lock['owned'] &&
                          (item['editing'] || !item['edit_lock_token'].to_s.empty? || state['space_editing_id'].to_s == space_id)
          if owned_session
            item['editing'] = true
            item['edit_safe_paused'] = true
            item['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
            item['edit_safe_pause_reason'] = '自动修复多个根模型同时解锁'
            item['status'] = '未发布修改已安全暂存 · 自动修复重复解锁'
          else
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
            clear_space_safe_pause!(item)
          end
          state['space_editing_id'] = '' if state['space_editing_id'].to_s == space_id
        elsif key.to_s.start_with?('architecture_model:')
          architecture_id = architecture_id_from_edit_root_key(key)
          item = architecture_model_record(state, architecture_id)
          next unless item
          lock = space_lock_info(item, model, state: state)
          owned_session = lock['exists'] && !lock['stale'] && lock['owned'] &&
                          (item['editing'] || !item['edit_lock_token'].to_s.empty? || state['architecture_editing_id'].to_s == architecture_id)
          if owned_session
            item['editing'] = true
            item['edit_safe_paused'] = true
            item['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
            item['edit_safe_pause_reason'] = '自动修复多个根模型同时解锁'
            item['status'] = '未发布修改已安全暂存 · 自动修复重复解锁'
          else
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
            clear_space_safe_pause!(item)
          end
          state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == architecture_id
        else
          link = state.dig('links', key)
          next unless link
          source = preview_source_for_entity(link, entity, model)
          lock = source_lock_info(source, link, model, state)
          owned_session = lock['exists'] && !lock['stale'] && lock['owned'] &&
                          (link['edit_session_active'] || link['preview_edit_active'] || !link['edit_lock_token'].to_s.empty?)
          if owned_session
            link['edit_safe_paused'] = true
            link['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
            link['edit_safe_pause_reason'] = '自动修复多个根模型同时解锁'
            link['preview_edit_active'] = true
            link['preview_pending_publish'] = false
            link['status'] = '未发布修改已安全暂存 · 自动修复重复解锁'
          else
            entity.set_attribute(ENTITY_DICT, 'editing', false)
            entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
            entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
            clear_managed_safe_pause!(link)
          end
        end
        @native_lock_state_cache ||= {}
        cache_key = if key.to_s.start_with?('space:')
                      space_native_cache_key(model, key.to_s.split(':', 2)[1])
                    elsif key.to_s.start_with?('architecture_model:')
                      [model.object_id, key.to_s]
                    else
                      [model.object_id, key]
                    end
        @native_lock_state_cache[cache_key] = true
      end
      state['space_edit_display_mode'] = '' if state['space_editing_id'].to_s.empty?
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      mark_edit_transition_quiet!
      labels = repair_entries.map do |key, _entity|
        if key.to_s.start_with?('space:')
          '硬装/软装空间'
        elsif key.to_s.start_with?('architecture_model:')
          '建筑模型'
        else
          DISCIPLINES.dig(key, 'name').to_s
        end
      end.reject(&:empty?).uniq.join('、')
      show_edit_safety_notice("检测到跨专业根模型同时解锁，已保留当前专业的待发布模型，并安全锁定其它专业：#{labels}", 'error')
      log("自动修复跨专业根模型同时解锁：保留 #{keep_keys.join(', ')}，修复 #{repair_entries.map(&:first).join(', ')}")
      schedule_edit_structure_audit(model, EDIT_TRANSITION_QUIET_SECONDS + 0.08)
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      log_exception('自动修复多个受管根模型同时解锁失败', e)
      false
    end

    def audit_unexpected_nested_roots(state, model = Sketchup.active_model)
      # 只审计本机实际持有的修改会话；其他成员正在修改的模型与本机当前发布互不干扰。
      active_keys = active_edit_root_keys(state, model)
      %w[architecture landscape].each do |discipline|
        next unless active_keys.include?(discipline)
        next unless managed_model_entities(model, discipline: discipline).empty?
        nested = find_nested_managed_entities(model, discipline: discipline)
        return "#{DISCIPLINES.dig(discipline, 'name')}受管根模型被嵌套到其他组/组件中" unless nested.empty?
      end
      Array(state['architecture_models']).each do |item|
        key = edit_root_key_for_architecture_model(item['id'])
        next unless active_keys.include?(key)
        next unless root_architecture_model_entities_for_id(item['id'], model).empty?
        nested = find_nested_managed_entities(model, discipline: 'architecture', architecture_id: item['id'])
        return "建筑 #{architecture_display_name(item, state)} 的根组件被嵌套到其他组/组件中" unless nested.empty?
      end
      Array(state['space_models']).each do |item|
        key = edit_root_key_for_space(item['id'])
        next unless active_keys.include?(key)
        next unless root_space_entities_for_id(item['id'], model).empty?
        nested = find_nested_managed_entities(model, discipline: space_record_collection_key(item), space_id: item['id'])
        return "空间 #{item['number']}:#{item['name']} 的根组件被嵌套到其他组/组件中" unless nested.empty?
      end
      ''
    rescue StandardError
      ''
    end

    # 编辑防呆提示必须是非阻塞的。此前 show_status 在模型库与抽屉都未展开时
    # 会退化成 UI.messagebox，导致用户每次移动、贴材质都被弹窗打断。结构检查
    # 只在状态栏、已打开面板或视口提示层显示；真正发布时仍会给出明确错误。
    def show_edit_safety_notice(message, level = 'error')
      text = message.to_s.strip
      return false if text.empty?
      payload = JSON.generate({ 'message' => text, 'level' => level.to_s })
      delivered = false
      [
        [@dialog, 'window.LinkHub && window.LinkHub.showToast'],
        [@soft_designer_dialog, 'window.SoftDesigner && window.SoftDesigner.showToast'],
        [@landscape_library_dialog, 'window.LandscapeLibrary && window.LandscapeLibrary.showToast'],
        [@architecture_library_dialog, 'window.ArchitectureLibrary && window.ArchitectureLibrary.showToast'],
        [@material_library_dialog, 'window.MaterialLibrary && window.MaterialLibrary.showToast'],
        [@soft_schedule_dialog, 'window.SoftSchedule && window.SoftSchedule.showToast']
      ].each do |dialog, js_call|
        next unless dialog && dialog.visible?
        dialog.execute_script("#{js_call}(#{payload});")
        delivered = true
      rescue StandardError
        nil
      end
      if @status_overlay_enabled
        overlay = ensure_status_overlay_for_model(Sketchup.active_model)
        if overlay && overlay.respond_to?(:show_message)
          overlay.show_message(text, level)
          delivered = true
        end
      end
      Sketchup.set_status_text(text, SB_PROMPT) rescue nil
      log("编辑结构提示：#{text}")
      delivered || true
    rescue StandardError
      false
    end

    def current_active_edit_structure_issue(model = Sketchup.active_model, state = nil)
      return '' unless model
      state ||= load_state(model)
      active_edit_root_keys(state, model).each do |key|
        issue = protected_root_issue(key, model).to_s
        return issue unless issue.empty?
      end
      audit_unexpected_nested_roots(state, model).to_s
    rescue StandardError => e
      log_exception('实时复核编辑结构失败', e)
      "结构检查异常：#{e.message}"
    end

    def audit_active_edit_structures(model = Sketchup.active_model)
      return false unless model && model == Sketchup.active_model
      return false if publish_critical_section? || publish_post_quiet? || @updating || @edit_focus_switch_in_progress
      return false if @space_publish_in_progress || @space_explicit_publish_in_progress || @architecture_explicit_publish_in_progress
      if edit_transition_quiet?
        schedule_edit_structure_audit(model, [@edit_transition_quiet_until.to_f - monotonic_time + 0.04, 0.08].max)
        return false
      end
      state = load_state(model)
      return false if repair_multiple_unlocked_managed_roots!(state, model)
      unexpected_issue = audit_unexpected_nested_roots(state, model).to_s
      protected_issue = ''
      active_edit_root_keys(state, model).each do |key|
        protected_issue = protected_root_issue(key, model).to_s
        break unless protected_issue.empty?
      end
      issue = protected_issue.empty? ? unexpected_issue : protected_issue
      if issue.empty?
        @edit_structure_blocked&.delete(model.object_id)
        @edit_structure_notified&.delete(model.object_id)
        return true
      end

      # 运行时审计不写入发布阻止状态；只有点击发布时的目标校验才有权阻止。
      @edit_structure_notified ||= {}
      already_notified = @edit_structure_notified[model.object_id].to_s == issue
      @edit_structure_notified[model.object_id] = issue

      # 运行时审计只做非阻塞提示，不再自动执行 model.undo。Observer 无法可靠知道
      # 当前事务的真实意图；错误撤回一次材质、移动或动态组件事务，比延后到发布前
      # 拦截更危险。真正发布时仍会针对当前目标做严格、独立的结构校验。
      unless already_notified
        show_edit_safety_notice("检测到当前受管根模型可能有结构变化：#{issue}。你可以继续编辑；发布当前目标时插件会再次精确核对。", 'info')
      end
      log("根模型结构审计提示（未自动撤回）：#{issue}") unless already_notified
      false
    rescue StandardError => e
      log_exception('执行编辑结构安全检查失败', e)
      false
    end

    def resolve_definition_identity_issue_for_publish(key, entity, issue, model = Sketchup.active_model, interactive: false, label: '')
      text = issue.to_s
      return text unless text.include?('设为唯一/替换定义')
      record = @edit_root_protections && @edit_root_protections[[model.object_id, key.to_s]]
      return text unless record.is_a?(Hash) && entity && entity.valid?

      # Group 的自动唯一化是 SketchUp 正常行为，不应阻止发布；只更新 definition
      # 基线，根实例身份、容器类型和变换仍由后续复核继续检查。
      if entity.is_a?(Sketchup::Group)
        return text unless rebind_protected_definition!(entity, record)
        return protected_root_issue(key, model).to_s
      end

      return text unless interactive
      target_label = label.to_s.empty? ? '当前受管模型' : label.to_s
      confirmed = native_confirm_yes?("#{target_label} 的组件定义与开始修改时不同。\n\n这可能来自 SketchUp 的自动唯一化，也可能是你主动替换了根组件定义。根实例本身仍会继续检查位置、数量和容器类型。是否以当前定义继续发布？")
      return text unless confirmed
      return text unless rebind_protected_definition!(entity, record)
      protected_root_issue(key, model).to_s
    rescue StandardError
      issue.to_s
    end

    def validate_managed_edit_structure!(discipline, entity, model = Sketchup.active_model, interactive_definition_rebind: false)
      key = discipline.to_s
      capture_edit_root_protection!(key, entity, model) unless @edit_root_protections&.key?([model.object_id, key])
      # 发布只校验当前目标专业根模型。其他专业/空间的增删改、远端占用或根层级普通对象
      # 都不会进入当前定义文件，因此不得阻止当前专业发布。
      issue = protected_root_issue(key, model)
      issue = resolve_definition_identity_issue_for_publish(key, entity, issue, model, interactive: interactive_definition_rebind, label: DISCIPLINES.dig(key, 'name').to_s)
      if issue.empty?
        @edit_structure_blocked&.delete(model.object_id)
        @edit_structure_notified&.delete(model.object_id)
      else
        @edit_structure_blocked ||= {}
        @edit_structure_blocked[model.object_id] = issue
        raise "发布已阻止：当前#{DISCIPLINES.dig(key, 'name')}根模型结构异常：#{issue}。请只修复当前受管根组件后再发布。"
      end
      definition = commit_definition_for_entity(entity)
      raise '发布已阻止：源模型定义已经失效。' unless definition && definition.valid?
      true
    end

    def validate_space_edit_structure!(item, entity, model = Sketchup.active_model, interactive_definition_rebind: false)
      key = edit_root_key_for_space(item['id'])
      capture_edit_root_protection!(key, entity, model) unless @edit_root_protections&.key?([model.object_id, key])
      # 空间协同按空间文件独立发布：其它受管空间/建筑/景观不会阻止当前空间。
      # 空间根内部的普通组件、组合家具及其子实例允许任意移动/旋转/复制；这些都是
      # Definition 内部合法内容，不能拿它们的 transformation 当成空间根结构异常。
      # model.entities 的额外对象不属于当前空间定义，也可能是在切换其它空间/专业、
      # 插件生成临时对象或长时间保留多个修改会话期间合法产生。旧版按“进入空间时
      # 的全局快照”硬拦截，重载插件后快照消失便又能发布，说明它无法可靠归因。
      # 发布继续严格验证当前受管根本身；根层额外对象只记诊断，绝不连带阻止。
      issue = protected_root_issue(key, model)
      issue = resolve_definition_identity_issue_for_publish(key, entity, issue, model, interactive: interactive_definition_rebind, label: space_ui_label(item))
      protection = @edit_root_protections && @edit_root_protections[[model.object_id, key]]
      root_content_note = protected_unexpected_root_content_issue(protection, model) if protection
      unless root_content_note.to_s.empty?
        log("空间发布忽略不属于当前空间定义的模型根层对象：#{space_ui_label(item)} / #{root_content_note}")
        # 诊断一次后把当前世界根作为新基线，避免跨空间切换时反复扫描和重复记录。
        protection[:root_entity_ids] = root_guard_entity_ids(model)
        protection[:root_guard_containers_only] = model.entities.length > EDIT_ROOT_GUARD_LIMIT
      end
      if issue.empty?
        @edit_structure_blocked&.delete(model.object_id)
        @edit_structure_notified&.delete(model.object_id)
      else
        @edit_structure_blocked ||= {}
        @edit_structure_blocked[model.object_id] = issue
        raise "空间发布已阻止：#{space_ui_label(item)} 根组件结构异常：#{issue}。请只修复当前空间根组件后再发布。"
      end
      raise '空间发布已阻止：当前空间定义已经失效。' unless entity.definition && entity.definition.valid?
      true
    end

    def validate_architecture_model_edit_structure!(item, entity, model = Sketchup.active_model, interactive_definition_rebind: false)
      key = edit_root_key_for_architecture_model(item['id'])
      capture_edit_root_protection!(key, entity, model) unless @edit_root_protections&.key?([model.object_id, key])
      issue = protected_root_issue(key, model)
      issue = resolve_definition_identity_issue_for_publish(
        key,
        entity,
        issue,
        model,
        interactive: interactive_definition_rebind,
        label: "建筑 #{architecture_display_name(item, load_state(model))}"
      )
      if issue.empty?
        @edit_structure_blocked&.delete(model.object_id)
        @edit_structure_notified&.delete(model.object_id)
      else
        @edit_structure_blocked ||= {}
        @edit_structure_blocked[model.object_id] = issue
        raise "建筑发布已阻止：当前建筑 #{architecture_display_name(item, load_state(model))} 根组件结构异常：#{issue}。请只修复当前建筑根组件后再发布。"
      end
      definition = entity.respond_to?(:definition) ? entity.definition : nil
      raise '建筑发布已阻止：当前建筑定义已经失效。' unless definition && definition.valid?
      true
    end

    def definition_empty?(definition)
      definition && definition.valid? && definition.respond_to?(:entities) && definition.entities.length.zero?
    rescue StandardError
      false
    end

    def confirm_empty_definition_publish?(label, definition)
      return true unless definition_empty?(definition)
      native_confirm_yes?("#{label} 当前是空模型。\n\n继续发布会把共享文件更新为空内容，但仍保留该协同条目。是否确认发布？")
    rescue StandardError
      false
    end

    def new_world_wrapper_extra_content_count(key, entity, model = Sketchup.active_model)
      current = world_wrapper_extra_content_count(entity)
      record = @edit_root_protections && @edit_root_protections[[model.object_id, key.to_s]]
      baseline = record.is_a?(Hash) ? record[:wrapper_extra_count].to_i : 0
      [current - baseline, 0].max
    rescue StandardError
      0
    end

    def pause_managed_edit_for_switch!(state, discipline, target_label, model = Sketchup.active_model)
      link = state.dig('links', discipline.to_s)
      return false unless link && managed_discipline_local_edit_active?(discipline, state, model)
      return false if managed_edit_safe_paused?(link)
      entity = native_edit_entity(discipline, model)
      raise "未找到正在修改的#{link['name']}根模型，不能安全切换。" unless entity && entity.valid?
      source_entity = managed_discipline_edit_source_entity(entity)
      if !model.active_path.nil? && !active_path_inside_managed_discipline?(entity, source_entity, model)
        raise '当前正在编辑与 LinkHub 无关的组件，请先退出该组件后再切换专业。'
      end
      source = resolve_source_for_edit(link['model_path'].to_s, model)
      lock = source_lock_info(source, link, model, state)
      # 切换专业时 current_workspace_role 已经可能变为目标专业；这会让同一进程
      # 在原专业取得的锁暂时显示 owned=false。安全暂存不写共享文件，只需确认锁
      # 仍由当前 SketchUp 进程持有，不能因此阻止跨专业切换。
      locally_owned = lock['owned'] || lock['process_owned']
      raise "#{link['name']}协作占用已失效，不能自动暂存；请先恢复占用。" unless lock['exists'] && !lock['stale'] && locally_owned
      validate_managed_edit_structure!(discipline, entity, model)
      @edit_focus_switch_in_progress = true
      @managed_discipline_edit_contexts&.delete([model.object_id, discipline.to_s])
      model.active_path = nil unless model.active_path.nil?
      raise "未能退出#{link['name']}组件层级，未执行专业切换。" unless model.active_path.nil?
      operation_open = false
      model.start_operation("安全暂存#{link['name']}修改", true, false, true)
      operation_open = true
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', true)
      link['edit_safe_paused'] = true
      link['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      link['edit_safe_pause_reason'] = "切换到#{target_label}"
      link['preview_edit_active'] = true
      link['preview_pending_publish'] = false
      link['status'] = "未发布修改已安全暂存 · 切换到#{target_label}"
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, discipline.to_s]] = true
      mark_edit_transition_quiet!
      log("安全暂存#{link['name']}修改并保留协作占用：切换到#{target_label}")
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    ensure
      @edit_focus_switch_in_progress = false
    end

    def pause_architecture_model_edit_for_switch!(state, item, target_label, model = Sketchup.active_model)
      return false unless item && local_architecture_model_edit_session?(item, state, model)
      return false if space_edit_safe_paused?(item)
      entity = architecture_model_entity(item['id'], model)
      raise "未找到建筑 #{architecture_display_name(item, state)} 根组件，不能安全切换。" unless entity && entity.valid?
      if !model.active_path.nil? && !active_path_inside_protected_root?(entity, model)
        raise '当前正在编辑与 LinkHub 无关的组件，请先退出该组件后再切换专业。'
      end
      lock = space_lock_info(item, model, state: state)
      locally_owned = lock['owned'] || lock['process_owned']
      raise "建筑 #{architecture_display_name(item, state)} 的协作占用已失效，不能自动暂存。" unless lock['exists'] && !lock['stale'] && locally_owned
      validate_architecture_model_edit_structure!(item, entity, model)
      @edit_focus_switch_in_progress = true
      model.active_path = nil unless model.active_path.nil?
      raise '未能退出当前建筑组件层级，未执行专业切换。' unless model.active_path.nil?
      operation_open = false
      model.start_operation("安全暂存建筑 #{architecture_display_name(item, state)}", true, false, true)
      operation_open = true
      restore_architecture_model_isolation!(item, model)
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', true)
      item['editing'] = true
      item['edit_safe_paused'] = true
      item['edit_safe_paused_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      item['edit_safe_pause_reason'] = "切换到#{target_label}"
      item['status'] = "未发布修改已安全暂存 · 切换到#{target_label}"
      state['architecture_editing_id'] = '' if state['architecture_editing_id'].to_s == item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, edit_root_key_for_architecture_model(item['id'])]] = true
      mark_edit_transition_quiet!
      log("安全暂存建筑 #{architecture_display_name(item, state)} 并保留协作占用：切换到#{target_label}")
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    ensure
      @edit_focus_switch_in_progress = false
    end

    def pause_space_edit_for_switch!(state, item, target_label, model = Sketchup.active_model)
      return false unless item && local_space_edit_session?(item, state, model)
      return false if space_edit_safe_paused?(item)
      entity = space_model_entity(item['id'], model)
      raise "未找到 #{space_ui_label(item)} 根组件，不能安全切换。" unless entity && entity.valid?
      if !model.active_path.nil? && !active_path_inside_space?(entity, model)
        raise '当前正在编辑与 LinkHub 无关的组件，请先退出该组件后再切换专业。'
      end
      lock = space_lock_info(item, model, state: state)
      locally_owned = lock['owned'] || lock['process_owned']
      raise "#{space_ui_label(item)} 的协作占用已失效，不能自动暂存。" unless lock['exists'] && !lock['stale'] && locally_owned
      validate_space_edit_structure!(item, entity, model)
      @edit_focus_switch_in_progress = true
      @space_edit_contexts&.delete(model.object_id)
      model.active_path = nil unless model.active_path.nil?
      raise '未能退出当前空间组件层级，未执行专业切换。' unless model.active_path.nil?

      # 直接从 A 双击/切到 B 时，如果 A 只是误入且没有任何模型修改，就不制造一个
      # “A 待发布”的遗留会话。自动锁回 A、释放 A 的协作占用，然后继续进入 B。
      # 无法确定未修改时仍走下面原有的保留占用路径。
      unchanged_target = auto_relocate(item['model_path'].to_s, model)
      if space_edit_content_unchanged?(item, entity, unchanged_target, model)
        finished = finish_unmodified_space_edit_session!(
          state, item, entity, unchanged_target, model,
          reason: :switch, preserve_representation: true, notify: false, refresh: false
        )
        mark_edit_transition_quiet!
        log("切换编辑焦点时自动结束未修改空间：#{item['number']}:#{item['name']} → #{target_label}")
        return finished
      end

      operation_open = false
      model.start_operation("安全暂存空间 #{item['number']}:#{item['name']}", true, false, true)
      operation_open = true
      restore_space_isolation!(item, model)
      clear_space_publish_pending!(item)
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      clear_space_safe_pause!(item, entity)
      item['editing'] = true
      item['status'] = "修改中 · 全局预览 · 已切换到#{target_label}"
      state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      @soft_designer_dialog.close if @soft_designer_dialog && @soft_designer_dialog.visible?
      mark_edit_transition_quiet!
      log("空间保持解锁和当前显示并切换焦点：#{item['number']}:#{item['name']} → #{target_label}")
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    ensure
      @edit_focus_switch_in_progress = false
    end

    # v0.13.0：同一模型集合允许多个本专业单元同时保持修改占用和根组件解锁。
    # SketchUp 同一时刻仍只能进入一个 active_path，因此 *_editing_id 只表示“当前焦点”，
    # 不再表示“唯一正在修改”的模型。跨专业切换仍采用安全暂存，避免不同专业同时抢占编辑上下文。
    def handoff_space_focus_for_multi_edit!(state, item, target_label, model = Sketchup.active_model)
      return false unless item && local_space_edit_session?(item, state, model)
      entity = space_model_entity(item['id'], model)
      return false unless entity && entity.valid?
      if !model.active_path.nil? && !active_path_inside_space?(entity, model)
        return false
      end
      lock = space_lock_info(item, model, state: state)
      return false unless lock['exists'] && !lock['stale'] && lock['owned']
      @edit_focus_switch_in_progress = true
      @space_edit_contexts&.delete(model.object_id)
      model.active_path = nil unless model.active_path.nil?
      operation_open = false
      model.start_operation("切换空间焦点 #{item['number']}:#{item['name']}", true, false, true)
      operation_open = true
      restore_space_isolation!(item, model)
      clear_space_publish_pending!(item)
      clear_space_safe_pause!(item)
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      item['editing'] = true
      item['status'] = '待发布'
      state['space_editing_id'] = '' if state['space_editing_id'].to_s == item['id'].to_s
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_open = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[space_native_cache_key(model, item['id'])] = false
      log("空间保持解锁并切换焦点：#{item['number']}:#{item['name']} → #{target_label}")
      true
    rescue StandardError
      model.abort_operation rescue nil if defined?(operation_open) && operation_open
      raise
    ensure
      @edit_focus_switch_in_progress = false
    end

