    def prepare_edit_focus_switch!(target, model = Sketchup.active_model)
      return false unless model
      state = load_state(model)
      target_text = target.to_s
      target_space_id = target_text.start_with?('space:') ? target_text.split(':', 2)[1].to_s : ''
      target_architecture_id = target_text.start_with?('architecture_model:') ? architecture_id_from_edit_root_key(target_text) : ''
      target_label = if !target_architecture_id.empty?
                       target_item = architecture_model_record(state, target_architecture_id)
                       target_item ? "建筑 #{architecture_display_name(target_item, state)}" : '另一个建筑模型'
                     elsif !target_space_id.empty?
                       target_item = space_model_record(state, target_space_id)
                       target_item ? "空间 #{target_item['number']}:#{target_item['name']}" : '另一个硬装/软装空间'
                     else
                       DISCIPLINES.dig(target_text, 'name').to_s
                     end
      target_label = target_text if target_label.empty?
      switched = false

      if !target_space_id.empty?
        # v0.13.5.6 起不再允许“多个待发布空间同时在整个 SKP 根层级保持解锁”。
        # 协作占用可以保留多个，但真正可编辑的空间只有当前焦点一个；其余空间
        # 一律安全暂存并锁回根组件。这样 model.entities 永远不是空间编辑容器。
        Array(state['space_models']).each do |row|
          next if row['id'].to_s == target_space_id
          next unless local_space_edit_session?(row, state, model)
          next if space_edit_safe_paused?(row)
          switched = pause_space_edit_for_switch!(state, row, target_label, model) || switched
          state = load_state(model)
        end
        # 跨专业仍安全暂存：多个建筑待发布时全部保留占用但锁回根层级。
        Array(state['architecture_models']).each do |row|
          next unless local_architecture_model_edit_session?(row, state, model)
          next if space_edit_safe_paused?(row)
          switched = pause_architecture_model_edit_for_switch!(state, row, target_label, model) || switched
          state = load_state(model)
        end
      elsif !target_architecture_id.empty?
        paused_architecture_model_records(state).each { |row| resume_architecture_pending_root_unfocused!(state, row, model) }
        active_architecture_id = state['architecture_editing_id'].to_s
        if !active_architecture_id.empty? && active_architecture_id != target_architecture_id
          active_item = architecture_model_record(state, active_architecture_id)
          switched = handoff_architecture_focus_for_multi_edit!(state, active_item, target_label, model) || switched if active_item
          state = load_state(model)
        end
        Array(state['space_models']).each do |row|
          next unless local_space_edit_session?(row, state, model)
          next if space_edit_safe_paused?(row)
          switched = pause_space_edit_for_switch!(state, row, target_label, model) || switched
          state = load_state(model)
        end
      else
        # 景观/协调等其它专业：继续沿用安全暂存，把所有室内/建筑待发布根保护起来。
        Array(state['space_models']).each do |row|
          next unless local_space_edit_session?(row, state, model)
          next if space_edit_safe_paused?(row)
          switched = pause_space_edit_for_switch!(state, row, target_label, model) || switched
          state = load_state(model)
        end
        Array(state['architecture_models']).each do |row|
          next unless local_architecture_model_edit_session?(row, state, model)
          next if space_edit_safe_paused?(row)
          switched = pause_architecture_model_edit_for_switch!(state, row, target_label, model) || switched
          state = load_state(model)
        end
      end

      %w[architecture landscape].each do |discipline|
        # 新建筑集合已经由 architecture_models 单独处理，不再重复走旧 architecture link。
        next if discipline == 'architecture' && architecture_collection_active?(state, model)
        next if discipline == target_text
        link = state.dig('links', discipline)
        next unless link && managed_discipline_local_edit_active?(discipline, state, model)
        next if managed_edit_safe_paused?(link)
        switched = pause_managed_edit_for_switch!(state, discipline, target_label, model) || switched
        state = load_state(model)
      end
      save_state(state, model, write_manifest: false)
      switched
    end

    def native_edit_entity(key, model = Sketchup.active_model)
      managed_model_instance_for(key, model)
    rescue StandardError
      nil
    end

    def entity_native_locked?(entity)
      return true unless entity && entity.valid?
      entity.respond_to?(:locked?) ? !!entity.locked? : true
    rescue StandardError
      true
    end

    # 本地临时修改提交时，直接写回当前连接的 SKP。
    # 不再暗中切换到另一个“协同发布”文件，避免用户看到按钮成功但源文件日期不变。
    # 写回时只在目标同目录创建瞬时回滚文件；验证成功立即删除，不累计历史 SKP。
    def native_publish_root(model = Sketchup.active_model)
      base = model_directory(model)
      base ||= Dir.home
      File.join(base, '_SU_LinkHub协同')
    end

    def native_publish_target_for(_key, link, model = Sketchup.active_model)
      current = resolve_source_for_edit(link['model_path'].to_s, model)
      return current if File.file?(current)

      legacy = resolve_path(link['native_publish_path'].to_s, model)
      return legacy if File.file?(legacy)

      raise '当前连接的源 SKP 不存在，无法提交修改。请先重新定位模型。'
    end

    def legacy_native_publish_manifest_path(target)
      "#{target}.sulink.publish.json"
    end

    def native_publish_manifest_path(target)
      filename = "#{File.basename(target.to_s)}.sulink.publish.json"
      metadata_file_path(target, 'publish', filename)
    end

    def commit_definition_for_entity(entity)
      return nil unless entity && entity.valid?
      if world_wrapper_instance?(entity)
        child = world_source_child(entity)
        return child.definition if child && child.valid?
      end
      entity.definition
    rescue StandardError
      nil
    end

    def world_wrapper_extra_content_count(entity)
      return 0 unless world_wrapper_instance?(entity)
      source_child = world_source_child(entity)
      entity.definition.entities.count { |item| item != source_child }
    rescue StandardError
      0
    end

    def foreign_managed_reference_count(definition, own_key, limit = 100_000)
      return 0 unless definition && definition.respond_to?(:entities)
      queue = [definition]
      seen = {}
      scanned = 0
      count = 0
      until queue.empty? || scanned >= limit
        current = queue.shift
        next unless current && current.respond_to?(:entities)
        id = current.object_id
        next if seen[id]
        seen[id] = true
        current.entities.each do |entity|
          scanned += 1
          break if scanned >= limit
          if entity.respond_to?(:get_attribute) && entity.get_attribute(ENTITY_DICT, 'managed', false)
            discipline = entity.get_attribute(ENTITY_DICT, 'discipline', '').to_s
            count += 1 if !discipline.empty? && discipline != own_key.to_s
          end
          if entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)
            queue << entity.definition
          end
        rescue StandardError
          next
        end
      end
      count
    rescue StandardError
      0
    end

    def publish_conflict_path_for(target, key)
      collab_root = collaboration_root_from_asset_path(target)
      folder = if collab_root.empty?
                 metadata_file_path(target, File.join('conflicts', key.to_s), '')
               else
                 File.join(collab_root, '_冲突保护', key.to_s)
               end
      FileUtils.mkdir_p(folder)
      base = File.basename(target, File.extname(target))
      File.join(folder, "#{base}_本地待合并_#{Time.now.strftime('%Y%m%d_%H%M%S')}_#{SecureRandom.hex(2)}.skp")
    end

    def forced_overwrite_backup_path_for(target, key)
      collab_root = collaboration_root_from_asset_path(target)
      folder = if collab_root.empty?
                 metadata_file_path(target, File.join('forced_overwrite', key.to_s), '')
               else
                 File.join(collab_root, '_强制覆盖前备份', key.to_s)
               end
      FileUtils.mkdir_p(folder)
      base = File.basename(target, File.extname(target))
      File.join(folder, "#{base}_被本专业强制覆盖前_#{Time.now.strftime('%Y%m%d_%H%M%S')}_#{SecureRandom.hex(2)}.skp")
    end

    def preserve_forced_overwrite_target!(target, key)
      return '' unless File.file?(target)
      backup = forced_overwrite_backup_path_for(target, key)
      linkhub_copy_file(target, backup)
      raise '强制覆盖前备份校验失败，已停止发布。' unless File.file?(backup) && File.size(backup) == File.size(target) && File.size(backup).positive?
      backup
    end

    def publish_history_folder_for(target, key)
      collab_root = collaboration_root_from_asset_path(target)
      root = collab_root.empty? ? File.join(File.dirname(target.to_s), '_SU_LinkHub版本历史') : File.join(collab_root, '_版本历史')
      base = File.basename(target.to_s, File.extname(target.to_s))
      File.join(root, key.to_s.gsub(/[^0-9A-Za-z_\-]/, '_'), base)
    end

    def archive_publish_rollback!(target, rollback, key, keep: PUBLISH_HISTORY_KEEP)
      return '' unless rollback && File.file?(rollback)
      folder = publish_history_folder_for(target, key)
      FileUtils.mkdir_p(folder)
      stamp = Time.now.strftime('%Y%m%d_%H%M%S')
      destination = File.join(folder, "#{stamp}--#{SecureRandom.hex(3)}--#{File.basename(target)}")
      file_operation_with_retry { linkhub_mv!(rollback, destination) }
      raise '发布历史归档失败。' unless File.file?(destination) && File.size(destination).positive?
      files = Dir.glob(File.join(folder, '*.skp')).select { |path| File.file?(path) }.sort_by { |path| File.mtime(path) rescue Time.at(0) }.reverse
      files.drop([keep.to_i, 1].max).each { |path| File.delete(path) rescue nil }
      destination
    rescue StandardError => e
      log_exception('归档发布前版本失败', e)
      ''
    end

    def latest_safe_publish_checkpoint_path_for(target, key, create: true)
      collab_root = collaboration_root_from_asset_path(target)
      root = collab_root.empty? ? metadata_file_path(target, 'latest_safe', '') : File.join(collab_root, '_最新安全快照')
      folder = File.join(root, key.to_s.gsub(/[^0-9A-Za-z_\-]/, '_'))
      FileUtils.mkdir_p(folder) if create
      File.join(folder, File.basename(target.to_s))
    end

    def latest_safe_publish_checkpoint_status(target, key)
      target = target.to_s
      checkpoint = latest_safe_publish_checkpoint_path_for(target, key, create: false)
      return { 'exists' => false, 'checkpoint' => checkpoint, 'drift' => false } unless File.file?(checkpoint)
      meta = read_json_file("#{checkpoint}.json") rescue {}
      trusted_content = trusted_safe_checkpoint_content_signature(target, key)
      unless trusted_content.empty?
        # 正式文件 fast 签名仍与最近一次安全发布一致，且正式文件/快照首尾抽样相同。
        # 直接复用发布时已经记录的完整 SHA，避免每次双击先读取两遍大型 SKP。
        return {
          'exists' => true,
          'checkpoint' => checkpoint,
          'target_exists' => true,
          'drift' => false,
          'target_content_signature' => trusted_content,
          'checkpoint_content_signature' => trusted_content,
          'checkpoint_plugin_version' => meta['plugin_version'].to_s,
          'checkpoint_saved_at' => meta['saved_at'].to_s,
          'checkpoint_saved_by' => meta['saved_by'].to_s,
          'checkpoint_host' => meta['host'].to_s
        }
      end
      target_content = File.file?(target) ? full_file_content_signature(target) : ''
      checkpoint_content = full_file_content_signature(checkpoint)
      drift = !File.file?(target) || (!target_content.empty? && !checkpoint_content.empty? && target_content != checkpoint_content)
      {
        'exists' => true,
        'checkpoint' => checkpoint,
        'target_exists' => File.file?(target),
        'drift' => drift,
        'target_content_signature' => target_content,
        'checkpoint_content_signature' => checkpoint_content,
        'checkpoint_plugin_version' => meta['plugin_version'].to_s,
        'checkpoint_saved_at' => meta['saved_at'].to_s,
        'checkpoint_saved_by' => meta['saved_by'].to_s,
        'checkpoint_host' => meta['host'].to_s
      }
    rescue StandardError => e
      { 'exists' => false, 'checkpoint' => checkpoint.to_s, 'drift' => false, 'error' => e.message.to_s }
    end

    # 只修复一种已经由当前加载验证链完整证明的缺口：当前实体的 revision、文件
    # 快速签名、package revision、验证 schema 与 package identity 全部匹配正式文件，
    # 而安全快照 sidecar 仍记录旧文件签名。先对正式文件做一次稳定完整 SHA，再用
    # hard-link 快速更新滚动快照；普通文件漂移、旧载入或包标缺失都不会进入此分支。
    def repair_verified_space_safe_checkpoint_gap!(item, entity, source, remote_revision, remote_signature)
      return false unless item.is_a?(Hash) && entity && entity.valid? && File.file?(source.to_s)
      space_id = item['id'].to_s
      revision = remote_revision.to_s
      signature = normalize_fast_signature(remote_signature)
      return false if space_id.empty? || signature.empty? || !revision.start_with?("space-#{space_id}-")

      verify_loaded_space_snapshot!(entity, revision, signature)
      package_revision = entity.get_attribute(ENTITY_DICT, 'source_package_revision', '').to_s
      package_identity = entity.get_attribute(ENTITY_DICT, 'source_package_identity', '').to_s
      verified_schema = entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i
      return false if package_revision.empty? || package_revision != revision || package_identity.empty? || verified_schema < SPACE_LOAD_VERIFIED_SCHEMA

      key = "space_#{space_id}"
      checkpoint = latest_safe_publish_checkpoint_path_for(source, key, create: false)
      meta_path = "#{checkpoint}.json"
      return false unless File.file?(checkpoint) && File.file?(meta_path)
      meta = read_json_file(meta_path) rescue {}
      recorded_signature = normalize_fast_signature(meta['signature'].to_s)
      return false if recorded_signature.empty? || recorded_signature == signature

      stable_snapshot = stable_full_file_snapshot_signature(source)
      stable_fast = normalize_fast_signature(full_snapshot_fast_signature(stable_snapshot))
      content_signature = full_snapshot_content_signature(stable_snapshot)
      raise '恢复安全快照时共享空间文件发生变化。' if stable_fast != signature || content_signature.empty?
      repaired = write_latest_safe_publish_checkpoint!(
        source, key,
        signature: signature,
        expected_content_signature: content_signature
      )
      raise '已验证新版的安全快照补写失败。' if repaired.to_s.empty?
      log("空间中断发布安全快照已补写：#{item['number']}:#{item['name']} / #{revision}")
      true
    rescue StandardError => e
      log_exception("修复空间中断发布安全快照失败：#{item.is_a?(Hash) ? "#{item['number']}:#{item['name']}" : '未知空间'}", e)
      false
    end

    # 新版本开始编辑前核对正式共享 SKP 与“最近安全发布快照”。两者内容不同，
    # 说明正式文件在上一次安全发布之后被其他路径改写：最常见是旧版插件、旧会话、
    # 手工替换或第三方同步。此时不能直接以被改写文件为新基线继续编辑，否则会把
    # 已经发生的数据丢失进一步固化。快照文件保持只读，由管理员核对后决定恢复哪份。
    def assert_latest_safe_checkpoint_consistent!(target, key, label)
      status = latest_safe_publish_checkpoint_status(target, key)
      return true unless status['exists'] && status['drift']
      checkpoint = status['checkpoint'].to_s
      saved = status['checkpoint_saved_at'].to_s
      by = status['checkpoint_saved_by'].to_s
      detail = []
      detail << "最近安全快照：#{checkpoint}" unless checkpoint.empty?
      detail << "快照时间：#{saved}" unless saved.empty?
      detail << "快照发布者：#{by}" unless by.empty?
      raise "#{label}共享 SKP 与最近安全发布快照内容不一致，疑似被旧版插件、旧会话或外部程序覆盖。为防止继续覆盖，已阻止进入修改。请先运行“全面检查”并保留/核对正式文件与安全快照。#{detail.empty? ? '' : "\n" + detail.join("\n")}"
    end

    # 每个共享对象只额外保留“最近一次由当前安全版本成功发布”的一份滚动快照。
    # 这是专门防旧插件/旧会话之后直接覆写正式 SKP：即使对方完全不理解新 revision，
    # 最近一次安全发布内容仍有独立副本可恢复，不会只存在于被覆盖的正式文件里。
    def write_latest_safe_publish_checkpoint!(target, key, signature: '', expected_content_signature: '')
      return '' unless File.file?(target.to_s)
      destination = latest_safe_publish_checkpoint_path_for(target, key)
      temp = "#{destination}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      before_fast = fast_file_signature(target)
      expected_content = expected_content_signature.to_s

      # 6.64：正式 target 在上一步已经做过整文件 SHA。这里不再读源文件 2~3 遍；
      # 只要求复制前后 fast 不变，并对新写出的 temp 做一次完整 SHA。
      if !expected_content.empty? && expected_content.include?('sha256:')
        unless signature.to_s.empty? || normalize_fast_signature(before_fast) == normalize_fast_signature(signature)
          raise '安全快照生成前正式共享文件已经变化。'
        end
        checkpoint_linked = false
        begin
          File.delete(temp) if File.file?(temp)
          File.link(target, temp)
          checkpoint_linked = true
        rescue StandardError
          file_operation_with_retry { linkhub_copy_file(target, temp) }
        end
        after_fast = fast_file_signature(target)
        # hard-link 与刚刚完成完整 SHA 验证的正式 target 是同一个文件对象；fast 未变化即可复用 SHA。
        temp_content = checkpoint_linked ? expected_content : full_file_content_signature(temp)
        unless !before_fast.empty? && before_fast == after_fast && temp_content == expected_content &&
               File.file?(temp) && File.size(temp).positive? && File.size(temp) == File.size(target)
          raise '安全快照复制期间源文件发生变化或内容校验失败。'
        end
        linkhub_mv(temp, destination)
        raise '安全快照落盘校验失败。' unless File.file?(destination) && File.size(destination) == File.size(target)
        after_content = expected_content
      else
        # 兼容旧入口：没有来自发布事务的可信 SHA 时仍走完整强校验。
        before_content = full_file_content_signature(target)
        raise '安全快照源文件无法稳定读取。' if before_fast.empty? || before_content.empty?
        file_operation_with_retry { linkhub_copy_file(target, temp) }
        after_fast = fast_file_signature(target)
        after_content = full_file_content_signature(target)
        temp_content = full_file_content_signature(temp)
        unless before_fast == after_fast && before_content == after_content && temp_content == after_content &&
               File.file?(temp) && File.size(temp).positive? && File.size(temp) == File.size(target)
          raise '安全快照复制期间源文件发生变化或内容校验失败。'
        end
        linkhub_mv(temp, destination)
        raise '安全快照落盘内容校验失败。' unless File.file?(destination) && full_file_content_signature(destination) == after_content
      end
      meta = "#{destination}.json"
      payload = {
        'schema' => 2,
        'plugin_version' => EXTENSION_VERSION,
        'source' => target.to_s,
        'checkpoint' => destination.to_s,
        'signature' => signature.to_s.empty? ? after_fast : signature.to_s,
        'content_signature' => after_content,
        'saved_at' => Time.now.iso8601(6),
        'saved_by' => current_user_name,
        'host' => current_host_name
      }
      meta_temp = "#{meta}.tmp-#{Process.pid}-#{SecureRandom.hex(2)}"
      File.write(meta_temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
      linkhub_mv(meta_temp, meta)
      destination
    rescue StandardError => e
      log_exception('写入最近安全发布快照失败', e)
      ''
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
      File.delete(meta_temp) if defined?(meta_temp) && meta_temp && File.file?(meta_temp)
    end

    def personal_publish_checkpoint_user_key
      name = current_user_name.to_s.strip
      host = current_host_name.to_s.strip
      name = 'unknown' if name.empty?
      host = 'unknown-host' if host.empty?
      identity = "#{name}@#{host}"
      safe = identity.gsub(/[\\\/:*?"<>|]/, '_').gsub(/\s+/, '_').gsub(/\A\.+|\.+\z/, '')
      safe = 'user' if safe.empty?
      "#{safe[0, 56]}_#{Digest::SHA1.hexdigest(identity)[0, 8]}"
    rescue StandardError
      identity = "#{current_user_name}@#{current_host_name}"
      "user_#{Digest::SHA1.hexdigest(identity)[0, 8]}"
    end

    def personal_publish_checkpoint_path_for(target, key, create: true)
      collab_root = collaboration_root_from_asset_path(target)
      root = collab_root.empty? ? metadata_file_path(target, 'personal_publish', '') : File.join(collab_root, '_个人发布快照')
      folder = File.join(root, personal_publish_checkpoint_user_key, key.to_s.gsub(/[^0-9A-Za-z_\-]/, '_'))
      FileUtils.mkdir_p(folder) if create
      File.join(folder, File.basename(target.to_s))
    end

    # 每位协作者独立保留自己最近一次成功发布的 SKP。它不会被其他人的正常发布
    # 覆盖；即使旧版插件/旧会话绕过新协议改写正式文件，用户仍可直接进协同目录
    # 找回自己的最后版本并手工恢复。
    def write_personal_publish_checkpoint!(source, key, signature: '', published_target: nil, expected_content_signature: '')
      source = source.to_s
      published_target = published_target.to_s
      published_target = source if published_target.empty?
      return '' unless File.file?(source)
      destination = personal_publish_checkpoint_path_for(published_target, key)
      temp = "#{destination}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
      before_fast = fast_file_signature(source)
      if same_file_path?(source, published_target) && !signature.to_s.empty? && normalize_fast_signature(before_fast) != normalize_fast_signature(signature)
        raise '正式共享文件在个人快照生成前已再次变化；未把变化后的文件冒充为本人的发布版本。'
      end

      expected_content = expected_content_signature.to_s
      if !expected_content.empty? && expected_content.include?('sha256:')
        # 6.66：source 已经有可信完整 SHA。若文件系统支持 hard-link，快照只新增目录项，
        # 不再 copy + 重新 SHA 整份 SKP；NAS/跨卷自动回退旧强校验路径。
        personal_linked = false
        begin
          File.delete(temp) if File.file?(temp)
          File.link(source, temp)
          personal_linked = true
        rescue StandardError
          file_operation_with_retry { linkhub_copy_file(source, temp) }
        end
        after_fast = fast_file_signature(source)
        temp_content = personal_linked ? expected_content : full_file_content_signature(temp)
        unless !before_fast.empty? && before_fast == after_fast && temp_content == expected_content &&
               File.file?(temp) && File.size(temp) == File.size(source)
          raise '个人发布快照复制期间源文件发生变化或内容校验失败。'
        end
        source_content = expected_content
        linkhub_mv(temp, destination)
        raise '个人发布快照落盘校验失败。' unless File.file?(destination) && File.size(destination) == File.size(source)
      else
        source_content = full_file_content_signature(source)
        raise '个人发布快照源文件无法稳定读取。' if source_content.empty?
        file_operation_with_retry { linkhub_copy_file(source, temp) }
        after_fast = fast_file_signature(source)
        after_content = full_file_content_signature(source)
        temp_content = full_file_content_signature(temp)
        unless before_fast == after_fast && source_content == after_content && temp_content == source_content &&
               File.file?(temp) && File.size(temp) == File.size(source)
          raise '个人发布快照复制期间源文件发生变化或内容校验失败。'
        end
        linkhub_mv(temp, destination)
        raise '个人发布快照落盘校验失败。' unless full_file_content_signature(destination) == source_content
      end
      meta = "#{destination}.json"
      payload = {
        'schema' => 2, 'plugin_version' => EXTENSION_VERSION, 'source' => published_target,
        'snapshot_source' => source, 'checkpoint' => destination.to_s, 'signature' => signature.to_s,
        'content_signature' => source_content, 'saved_at' => Time.now.iso8601(6),
        'saved_by' => current_user_name, 'host' => current_host_name
      }
      # 个人快照 SKP 已经完成内容验证；sidecar 不属于崩溃事务边界，不为小 JSON 强制 fsync。
      fast_atomic_write_file(meta, JSON.pretty_generate(payload))
      destination
    rescue StandardError => e
      log_exception('写入个人最近发布快照失败', e)
      ''
    ensure
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
    end

    def publish_rollback_path_for(target)
      File.join(
        File.dirname(target.to_s),
        ".#{File.basename(target.to_s)}.sulink-rollback-#{Process.pid}-#{SecureRandom.hex(4)}.skp"
      )
    end

    def promote_file_create_only!(source, target)
      raise '候选文件不存在。' unless File.file?(source) && File.size(source).positive?
      raise '目标文件已经存在，已停止以避免覆盖。' if File.exist?(target)
      source_signature = full_file_content_signature(source)
      raise '候选文件无法读取完整内容指纹。' if source_signature.empty?
      linked = false
      begin
        File.link(source, target)
        linked = true
      rescue Errno::EEXIST
        raise '目标文件在最终落盘窗口被另一任务创建，已停止且未覆盖。'
      rescue StandardError
        begin
          File.open(target, File::WRONLY | File::CREAT | File::EXCL, 0o666) do |out|
            File.open(source, 'rb') { |input| IO.copy_stream(input, out) }
            out.flush
            out.fsync rescue nil
          end
        rescue Errno::EEXIST
          raise '目标文件在最终落盘窗口被另一任务创建，已停止且未覆盖。'
        end
      end
      target_signature = full_file_content_signature(target)
      unless target_signature == source_signature
        # 校验失败时不能直接删除 target：从“读指纹”到“删除”之间仍可能被另一任务替换。
        # 保留现场并报错，宁可产生一个待人工核对文件，也绝不误删第三方的新版本。
        raise '候选文件创建后完整内容校验失败；为避免误删并发写入，已保留目标文件供核对。'
      end
      File.delete(source) if File.file?(source)
      true
    end

    # 只删除“仍能证明就是本次候选”的文件。先隔离再复核，避免 hash -> delete 之间
    # 被第三方替换后误删别人版本。若隔离后发现内容已变化，则优先无覆盖地放回。
    def remove_file_if_content_matches!(path, expected_content_signature)
      target = FastPath.expand(path.to_s)
      expected = expected_content_signature.to_s
      return true unless File.file?(target)
      return false if expected.empty? || full_file_content_signature(target) != expected
      quarantine = "#{target}.sulink-remove-check-#{Process.pid}-#{SecureRandom.hex(4)}"
      linkhub_mv(target, quarantine)
      moved = full_file_content_signature(quarantine)
      if moved == expected
        File.delete(quarantine) if File.file?(quarantine)
        return true
      end
      promote_file_create_only!(quarantine, target) if File.file?(quarantine) && !File.exist?(target)
      false
    rescue StandardError => e
      begin
        promote_file_create_only!(quarantine, target) if defined?(quarantine) && quarantine && File.file?(quarantine) && !File.exist?(target)
      rescue StandardError
        nil
      end
      log_exception('按完整内容安全删除文件失败', e)
      false
    end

    # v0.13.6.153：共享空间通常位于 UNC/SMB。对这种路径，写完 90~100MB 候选后
    # 立刻从 NAS 再完整 SHA 一遍，现场可额外耗时 16~60 秒；这不是上传，而是重复读回。
    # 本机候选已经做过完整 SHA，SMB/TCP 本身提供可靠写入错误反馈，因此网络快速路径
    # 用“本机完整 SHA + copy_stream 实际字节数 + 远端 size/stat + 最终同目录 rename”验证，
    # 不再把刚写完的远端 SKP 整包读回。非 UNC、本地盘仍保留原来的完整 SHA 强校验。
    # v0.13.6.170：网络快速路径不仅识别 \\server\share，也识别 Windows 映射盘。
    # 映射盘用 FileSystemObject.DriveType=3（Remote）判断并按盘符缓存，避免每次发布都触发 COM。
    def windows_remote_drive_path?(path)
      return false unless windows_platform?
      text = path.to_s.strip
      match = text.match(/\A([A-Za-z]):[\\\/]/)
      return false unless match
      drive_key = match[1].upcase
      @windows_remote_drive_cache ||= {}
      return @windows_remote_drive_cache[drive_key] if @windows_remote_drive_cache.key?(drive_key)
      remote = false
      begin
        require 'win32ole' unless defined?(WIN32OLE)
        fso = WIN32OLE.new('Scripting.FileSystemObject')
        drive = fso.GetDrive("#{drive_key}:")
        remote = drive && drive.DriveType.to_i == 3
      rescue StandardError => e
        log("映射盘网络类型检测失败 #{drive_key}:：#{e.class}: #{e.message}") rescue nil
        remote = false
      end
      @windows_remote_drive_cache[drive_key] = !!remote
    rescue StandardError
      false
    end

    def publish_unc_network_path?(path)
      text = path.to_s.tr('\\', '/')
      text.start_with?('//') || windows_remote_drive_path?(path)
    rescue StandardError
      false
    end

    def publish_network_fast_path?(target)
      publish_unc_network_path?(target) && collaboration_storage_path?(target)
    rescue StandardError
      false
    end

    # 最终替换只锁非常短的 rename 窗口。上传隐藏 stage 可以并行，但真正把 target
    # 换掉时按目标文件串行；第二个发布者拿到锁后会重新核对 target fast signature，
    # 因而不会因为跳过远端整包 SHA 而放松并发覆盖保护。
    def with_publish_final_swap_lock(target, timeout: 8.0)
      lock_path = File.join(File.dirname(target.to_s), ".#{File.basename(target.to_s)}.sulink-final-swap.lock")
      deadline = monotonic_time + timeout.to_f
      acquired = false
      loop do
        begin
          File.open(lock_path, File::WRONLY | File::CREAT | File::EXCL, 0o666) do |io|
            io.write(JSON.generate({
              'pid' => Process.pid,
              'host' => current_host_name,
              'user' => current_user_name,
              'created_at' => Time.now.iso8601(6)
            }))
          end
          acquired = true
          break
        rescue Errno::EEXIST
          begin
            # 这里只覆盖最终 rename 窗口，正常生命周期远短于 1 分钟。保守 120 秒
            # 才认作崩溃遗留，避免慢 NAS 上误删仍在工作的锁。
            age = Time.now.to_f - File.mtime(lock_path).to_f
            File.delete(lock_path) if age > 120.0
          rescue StandardError
            nil
          end
          raise SourceFileBusyError, '另一个协同发布正在完成最终替换，请稍后重试。' if monotonic_time >= deadline
          sleep(0.05)
        end
      end
      yield
    ensure
      begin
        File.delete(lock_path) if acquired
      rescue StandardError
        nil
      end
    end

    # UNC/SMB 专用最终交换：target 与隐藏 stage 位于同一目录，使用 rename 只修改目录项，
    # 不再 hard-link + 删除 + 再次读回整份文件。rollback 在后发布维护完成前一直保留。
    def network_fast_swap_preverified_stage!(temp, target, candidate_size, candidate_content_signature, stage_target_existed:, stage_target_fast:)
      result = nil
      rollback = nil
      with_publish_final_swap_lock(target) do
        current_exists = File.exist?(target)
        current_fast = current_exists ? fast_file_signature(target) : ''
        if current_exists != !!stage_target_existed || (current_exists && current_fast != stage_target_fast.to_s)
          raise PublishConflictError.new('共享模型在候选上传期间被其他任务更新。正式文件未覆盖，请重新发布。', '')
        end

        if current_exists
          rollback = publish_rollback_path_for(target)
          File.delete(rollback) if File.exist?(rollback)
          publish_breadcrumb!('target_to_rollback_begin', target: target, rollback: rollback, mode: 'network_rename')
          file_operation_with_retry { File.rename(target, rollback) }
          rollback_fast = fast_file_signature(rollback)
          unless !rollback_fast.empty? && rollback_fast == stage_target_fast.to_s && !File.exist?(target)
            begin
              File.rename(rollback, target) if File.exist?(rollback) && !File.exist?(target)
            rescue StandardError
              nil
            end
            raise PublishConflictError.new('共享旧版本在最终替换窗口发生变化，已停止发布。', '')
          end
          publish_breadcrumb!('target_to_rollback_returned', rollback_exists: true, mode: 'network_rename')
          publish_breadcrumb!('rollback_hash_reused', rollback: rollback, mode: 'network_fast_signature')
        end

        publish_breadcrumb!('candidate_replace_target_begin', target: target, fallback: false, mode: 'network_rename')
        raise '远端发布候选不存在。' unless File.exist?(temp)
        raise '最终替换窗口目标文件意外存在，已停止发布。' if File.exist?(target)
        file_operation_with_retry { File.rename(temp, target) }
        stat = File.stat(target)
        unless stat.file? && stat.size.to_i == candidate_size.to_i && candidate_size.to_i.positive?
          begin
            File.rename(rollback, target) if rollback && File.exist?(rollback) && !File.exist?(target)
          rescue StandardError
            nil
          end
          raise '正式共享文件大小验证失败。'
        end
        fast = "#{stat.mtime.to_f}|#{stat.size.to_i}"
        publish_breadcrumb!('candidate_replace_target_returned', target_exists: true, target_size: stat.size.to_i, mode: 'network_rename')
        result = {
          rollback_path: rollback.to_s,
          promoted: {
            'fast_signature' => fast,
            'content_signature' => candidate_content_signature.to_s,
            'snapshot_signature' => "#{fast}|#{candidate_content_signature}",
            'mtime' => stat.mtime
          }
        }
      end
      result
    rescue PublishConflictError
      begin
        File.rename(rollback, target) if rollback && File.exist?(rollback) && !File.exist?(target)
      rescue StandardError
        nil
      end
      raise
    rescue StandardError
      begin
        File.rename(rollback, target) if rollback && File.exist?(rollback) && !File.exist?(target)
      rescue StandardError
        nil
      end
      raise
    end

    def file_operation_with_retry(delays = [0.0, 0.18, 0.45, 0.9])
      last_error = nil
      Array(delays).each do |delay|
        sleep(delay.to_f) if delay.to_f.positive?
        begin
          return yield
        rescue StandardError => e
          last_error = e
        end
      end
      raise last_error if last_error
      false
    end

    # v0.13.6.189：整文件 SHA256 改为 4MB 分块读取。Digest::SHA256.file 固定 16KB 一次
    # File#read，每一块都要释放/重新拿 GVL；后台线程里 60MB 文件就是 3800 多次 GVL 交接。
    # 摘要结果与 Digest::SHA256.file 完全相同，异常照常抛出。
    def linkhub_file_sha256_hexdigest(path)
      digest = Digest::SHA256.new
      File.open(path.to_s, 'rb') do |file|
        buffer = String.new(capacity: LINKHUB_HASH_CHUNK_BYTES)
        digest.update(buffer) while file.read(LINKHUB_HASH_CHUNK_BYTES, buffer)
      end
      digest.hexdigest
    end

    # v0.13.6.189：文件移动/原子替换统一入口。
    # 旧代码 62 处 FileUtils.mv(..., force: true)：force 会吞掉所有 SystemCallError，
    # 于是 (1) 共享盘上别的成员恰好在读同一文件时的瞬时占用直接变成“静默没写进去”，
    # 锁心跳、项目 JSON、清单缓存都可能悄悄丢一次；(2) 外层 file_operation_with_retry
    # 永远收不到异常，注释里写的“网络盘短暂占用时重试”实际从未发生。
    # linkhub_mv!：与 FileUtils.mv(src, dest) 相同语义（目标是目录则移入、跨卷退回复制），
    #              失败照常抛出，交给外层重试/回滚。
    # linkhub_mv： 保持旧的 force 语义（最终失败不抛出），但先对瞬时占用短暂重试，
    #              并把最终失败写进日志，不再无声丢失。
    def linkhub_mv!(source, target)
      src = source.to_s
      dst = target.to_s
      return FileUtils.mv(src, dst) if File.directory?(dst)
      begin
        File.rename(src, dst)
      rescue Errno::EXDEV, Errno::EPERM
        FileUtils.mv(src, dst)
      end
      0
    end

    def linkhub_mv(source, target)
      attempt = 0
      begin
        linkhub_mv!(source, target)
      rescue Errno::EACCES, Errno::EBUSY, Errno::EAGAIN => e
        delay = LINKHUB_MV_RETRY_DELAYS[attempt]
        if delay && File.exist?(source.to_s)
          attempt += 1
          sleep(delay)
          retry
        end
        log("文件替换失败（已重试 #{attempt} 次，按旧逻辑继续）：#{File.basename(target.to_s)} / #{e.class.name.split('::').last}")
        nil
      rescue SystemCallError => e
        unless e.is_a?(Errno::ENOENT)
          log("文件替换失败（按旧逻辑继续）：#{File.basename(target.to_s)} / #{e.class.name.split('::').last}")
        end
        nil
      end
    end

    # v0.13.6.189：写往网络共享的大文件改用 8MB 分块复制。
    # FileUtils.copy_file → IO.copy_stream 在 Windows 上固定 16KB 一次 WriteFile；
    # SMB 对每个小块同步确认，现场 NAS 实测 16KB≈46MB/s、4MB≈104MB/s（发布日志里
    # 60MB 候选上传 6.2 秒）。语义保持与 FileUtils.copy_file(src, dest) 一致：覆盖写
    # 目标、不保留时间戳、任何读写错误照常抛出（调用方的重试/回滚逻辑不变）。
    # 本机目标或小文件仍走标准库，行为完全不变。
    def linkhub_copy_file(source, target)
      src = source.to_s
      dst = target.to_s
      network_target = dst.start_with?('//', '\\\\')
      if !network_target || File.size(src) < LINKHUB_COPY_MIN_CHUNKED_BYTES
        return FileUtils.copy_file(src, dst)
      end
      File.open(src, 'rb') do |input|
        File.open(dst, 'wb') do |output|
          buffer = String.new(capacity: LINKHUB_COPY_CHUNK_BYTES)
          output.write(buffer) while input.read(LINKHUB_COPY_CHUNK_BYTES, buffer)
        end
      end
      nil
    end

    # 本地 NTFS 上把几十至数百 MB 的正式 SKP rename 成 rollback，可能被同步盘或
    # 杀毒过滤器阻塞二三十秒。先为旧文件建立同卷 hard-link 回滚点，再只删除正式
    # 路径的目录项，数据块完全不移动。无法 hard-link（NAS/FAT/权限限制）时返回 nil，
    # 调用方继续使用原来的 rename 安全路径。
    def detach_publish_target_with_hardlink_rollback!(target, rollback, expected_guard: '')
      linked = false
      identity = stable_file_identity_token(target)
      return nil if identity.empty? || !File.file?(target)
      File.delete(rollback) if File.file?(rollback)
      File.link(target, rollback)
      linked = true
      rollback_identity = stable_file_identity_token(rollback)
      current_identity = stable_file_identity_token(target)
      unless !rollback_identity.empty? && rollback_identity == identity && current_identity == identity
        raise PublishConflictError.new('建立发布回滚点时共享目标发生变化，已停止发布。', '')
      end
      unless expected_guard.to_s.empty?
        rollback_guard = publish_target_light_guard(rollback)
        unless !rollback_guard.empty? && rollback_guard == expected_guard.to_s
          raise PublishConflictError.new('建立发布回滚点时共享目标内容发生变化，已停止发布。', '')
        end
      end
      File.delete(target)
      raise '旧正式文件路径未能释放。' if File.exist?(target)
      { mode: 'hardlink_detach', identity: rollback_identity }
    rescue PublishConflictError
      File.delete(rollback) if linked && File.file?(rollback) && File.file?(target)
      raise
    rescue StandardError => e
      File.delete(rollback) if linked && File.file?(rollback) && File.file?(target)
      log("发布回滚 hard-link 快速路径不可用，回退同目录重命名：#{e.class}: #{e.message}") rescue nil
      nil
    end

    def restore_publish_rollback!(target, rollback, expected_current_content: '')
      return true if rollback.to_s.empty? || !File.file?(rollback)
      displaced = nil
      if File.file?(target)
        current_content = full_file_content_signature(target)
        if !expected_current_content.to_s.empty? && current_content != expected_current_content.to_s
          log("跳过自动恢复发布回滚：正式文件已不是本次候选；回滚文件保留 #{rollback}")
          return false
        end
        displaced = "#{target}.rollback-displaced-#{Process.pid}-#{SecureRandom.hex(3)}"
        linkhub_mv(target, displaced)
        moved_content = full_file_content_signature(displaced)
        if !expected_current_content.to_s.empty? && moved_content != expected_current_content.to_s
          promote_file_create_only!(displaced, target) unless File.exist?(target)
          log("跳过自动恢复：最终窗口实际移走的正式文件已变化；回滚文件保留 #{rollback}")
          return false
        end
      end
      if File.exist?(target)
        promote_file_create_only!(displaced, target) if displaced && File.file?(displaced) && !File.exist?(target)
        return false
      end
      promote_file_create_only!(rollback, target)
      File.delete(displaced) if displaced && File.file?(displaced)
      File.file?(target) && File.size(target).positive?
    rescue StandardError => e
      begin
        promote_file_create_only!(displaced, target) if defined?(displaced) && displaced && File.file?(displaced) && !File.exist?(target)
      rescue StandardError
        nil
      end
      log_exception('恢复发布瞬时回滚文件失败', e)
      false
    end

    def collaboration_storage_path?(path)
      !collaboration_root_from_asset_path(path).empty?
    rescue StandardError
      false
    end

    # 将组件定义写入候选 SKP，再核对版本、使用瞬时回滚文件原子替换并验证结果。
    # 返回包含 path / backup / signature / size 的 Hash；本专业强制覆盖时 backup 保存被覆盖前版本。任何一步失败都不会伪报成功。
    # v0.13.6.27：把 SketchUp 原生 Definition 序列化与 SMB/NAS 发布拆开。
    # 此方法只在本机临时目录生成候选 SKP；调用者可在 save_as 返回后立即结束/撤回
    # 临时 SketchUp operation，再进入纯文件系统发布阶段。
    def serialize_publish_definition_candidate!(definition, target, key, defer_content_signature: false)
      target = FastPath.expand(target.to_s)
      raise '提交目标不是有效的 SKP 路径。' unless File.extname(target).casecmp('.skp').zero?
      raise '不能把外部联动组件写回当前正在打开的工作模型。' if same_file_path?(target, Sketchup.active_model.path.to_s)
      raise '缺少可序列化的发布定义。' unless definition && definition.valid?

      token = "#{Process.pid}-#{SecureRandom.hex(4)}"
      local_candidate = File.join(TEMP_WORK_DIR, "SU_LinkHub-publish-#{token}.skp")
      local_save_started = monotonic_time
      publish_breadcrumb!(
        'candidate_local_save_begin',
        target: target, local_candidate: local_candidate, remote_stage: '',
        discipline: key.to_s
      )
      # v0.13.6.153：空间发布候选优先使用 save_copy。save_as 会把当前 Definition
      # 绑定到临时候选路径并触发额外的原生状态重建；现场日志里同一 95MB 空间
      # 正常 save 约 1.3s，但偶发会在 save_as 内阻塞十几到四十秒。发布只需要
      # 一份本机候选，不需要改变 Definition 的关联路径，因此优先走无副作用的 save_copy。
      save_method = definition.respond_to?(:save_copy) ? :save_copy : :save_as
      saved = definition.respond_to?(save_method) ? definition.public_send(save_method, local_candidate) : false
      publish_breadcrumb!(
        'candidate_local_save_returned',
        target: target, local_exists: File.file?(local_candidate),
        local_size: (File.file?(local_candidate) ? File.size(local_candidate) : 0),
        save_method: save_method.to_s
      )
      unless File.file?(local_candidate) && File.size(local_candidate).positive?
        File.delete(local_candidate) if File.file?(local_candidate)
        # 极少数旧 SketchUp 虽暴露 save_copy 但实际写盘失败；只在这种真实失败时
        # 才回退 save_as，避免正常发布每次都进入有副作用的保存路径。
        if save_method == :save_copy && definition.respond_to?(:save_as)
          begin
            publish_breadcrumb!('candidate_local_save_as_fallback_begin', target: target, local_candidate: local_candidate)
            saved = definition.save_as(local_candidate)
            publish_breadcrumb!(
              'candidate_local_save_as_fallback_returned',
              local_exists: File.file?(local_candidate),
              local_size: (File.file?(local_candidate) ? File.size(local_candidate) : 0)
            )
          rescue StandardError
            saved = false
          end
        end
      end
      raise 'SketchUp 未能写出本地提交候选模型。' unless saved || File.file?(local_candidate)
      raise '本地提交候选模型为空，已取消写入。' unless File.file?(local_candidate) && File.size(local_candidate).positive?

      candidate_size = File.size(local_candidate)
      candidate_content_signature = defer_content_signature ? '' : full_file_content_signature(local_candidate)
      if !defer_content_signature && candidate_content_signature.empty?
        raise '本地提交候选无法生成内容指纹，已取消正式写入。'
      end
      log("发布候选本机序列化：#{File.basename(target)} / #{candidate_size} bytes / #{elapsed_ms(local_save_started)}ms#{defer_content_signature ? ' / 内容指纹后台计算' : ''}")
      {
        path: local_candidate,
        size: candidate_size,
        content_signature: candidate_content_signature,
        token: token
      }
    rescue StandardError
      File.delete(local_candidate) if defined?(local_candidate) && local_candidate && File.file?(local_candidate)
      raise
    end

    # 已经完成本机 SketchUp 序列化的候选，只在这里进行版本复核、SMB/NAS 传输、
    # 原子替换、回滚与快照。此阶段禁止持有 SketchUp model.start_operation。
    def atomic_publish_prepared_candidate!(prepared, target, key, link, expected_signature: '', baseline_path: '', baseline_signature: '', force_overwrite: false, source_model_path: '', keep_local_candidate: false, defer_personal_checkpoint: false, defer_post_publish_maintenance: false)
      target = FastPath.expand(target.to_s)
      raise '提交目标不是有效的 SKP 路径。' unless File.extname(target).casecmp('.skp').zero?
      # prepared candidate 也会在后台 worker 中调用；这里绝不能访问 Sketchup.active_model。
      # 主线程调用方若需要“不得覆盖当前工作 SU”的保护，必须显式传入 source_model_path；
      # 为空代表未保存工作 SU，此时只执行纯文件发布。
      source_model_path = source_model_path.to_s
      if !source_model_path.empty? && same_file_path?(target, source_model_path)
        raise '不能把外部联动组件写回当前正在打开的工作模型。'
      end
      FileUtils.mkdir_p(File.dirname(target))
      if File.file?(target) && expected_signature.to_s.empty? && !force_overwrite
        raise PublishConflictError.new('共享目标已经存在，但当前会话没有可验证的编辑基线。为避免旧会话/首次发布覆盖别人版本，已停止发布；请先更新到最新共享模型后再修改。', '')
      end

      prepared = prepared.is_a?(Hash) ? prepared : {}
      local_candidate = prepared[:path].to_s
      candidate_size = prepared[:size].to_i
      candidate_content_signature = prepared[:content_signature].to_s
      token = prepared[:token].to_s
      token = "#{Process.pid}-#{SecureRandom.hex(4)}" if token.empty?
      network_fast_publish = publish_network_fast_path?(target) && !force_overwrite
      raise '本地发布候选不存在。' unless File.file?(local_candidate) && File.size(local_candidate).positive?
      actual_size = File.size(local_candidate)
      raise '本地发布候选大小发生变化，已停止正式写入。' unless candidate_size.positive? && actual_size == candidate_size
      verified_fast = prepared[:verified_fast_signature].to_s
      current_fast = fast_file_signature(local_candidate)
      if !candidate_content_signature.empty? && !verified_fast.empty? && current_fast == verified_fast
        # worker 已经对同一文件做过整文件 SHA，且 mtime/size 未变；不要在后台再读第二遍。
        actual_content_signature = candidate_content_signature
        publish_breadcrumb!('candidate_local_hash_reused', size: actual_size)
      else
        actual_content_signature = full_file_content_signature(local_candidate)
        publish_breadcrumb!('candidate_local_hash_recomputed', size: actual_size)
      end
      raise '本地发布候选无法生成内容指纹，已停止发布。' if actual_content_signature.empty?
      candidate_content_signature = actual_content_signature if candidate_content_signature.empty?
      unless actual_content_signature == candidate_content_signature
        raise '本地发布候选内容在正式写入前发生变化，已停止发布。'
      end

      temp = File.join(File.dirname(target), ".#{File.basename(target)}.sulink-tmp-#{token}.skp")
      rollback = nil
      conflict_copy = nil
      forced_backup = ''
      history_backup = ''
      force_applied = false
      # 保存候选可能耗时较长，完成后再次核对临时编辑所基于的源版本。
      if !baseline_path.to_s.empty? && File.file?(baseline_path) && !baseline_signature.to_s.empty?
        latest_baseline = fast_file_signature(baseline_path)
        if latest_baseline != baseline_signature.to_s
          if force_overwrite
            force_applied = true
            forced_backup = preserve_forced_overwrite_target!(target, key) if forced_backup.empty?
            log("本专业强制发布：候选生成期间检测到源版本变化，覆盖前已备份 #{forced_backup}")
          else
            conflict_copy = publish_conflict_path_for(target, key)
            file_operation_with_retry { linkhub_copy_file(local_candidate, conflict_copy) }
            raise '本地冲突候选保存失败。' unless File.file?(conflict_copy) && File.size(conflict_copy) == candidate_size
            raise PublishConflictError.new(
              "生成候选期间源模型已被更新。未覆盖对方版本；本地候选已保存：#{conflict_copy}",
              conflict_copy
            )
          end
        end
      end

      if File.file?(target) && !expected_signature.to_s.empty?
        current_signature = fast_file_signature(target)
        if current_signature != expected_signature.to_s
          if force_overwrite
            force_applied = true
            forced_backup = preserve_forced_overwrite_target!(target, key) if forced_backup.empty?
            log("本专业强制发布：目标版本与编辑基线不同，覆盖前已备份 #{forced_backup}")
          else
            conflict_copy = publish_conflict_path_for(target, key)
            file_operation_with_retry { linkhub_copy_file(local_candidate, conflict_copy) }
            raise '本地冲突候选保存失败。' unless File.file?(conflict_copy) && File.size(conflict_copy) == candidate_size
            raise PublishConflictError.new(
              "提交期间源模型已被其他成员更新。未覆盖对方版本；本地候选已保存：#{conflict_copy}",
              conflict_copy
            )
          end
        end
      end

      # expected_signature 的核对发生在本机候选生成后；共享目录复制本身仍可能
      # 持续数秒。先拍目标内容快照，并在远端临时文件传完后再次核对，封住
      # “检查完成 -> SMB 传输 -> 正式替换”之间被其他成员发布的竞态窗口。
      stage_target_existed = File.file?(target)
      stage_target_guard = ''
      stage_target_fast = ''
      stage_target_content = ''
      stage_target_snapshot = ''
      if stage_target_existed
        trusted_content = trusted_safe_checkpoint_content_signature(target, key, expected_signature.to_s)
        if !trusted_content.empty?
          publish_breadcrumb!('target_snapshot_checkpoint_reuse_begin', target: target, target_existed: true)
          stage_target_fast = fast_file_signature(target)
          stage_target_guard = network_fast_publish ? stage_target_fast : publish_target_light_guard(target)
          stage_target_content = trusted_content
          stage_target_snapshot = "#{stage_target_fast}|#{trusted_content}"
          publish_breadcrumb!('target_snapshot_checkpoint_reuse_returned', target: target, guard_ready: !stage_target_guard.empty?)
        else
          publish_breadcrumb!('target_snapshot_hash_begin', target: target, target_existed: true)
          stage_target_snapshot = stable_full_file_snapshot_signature(target)
          stage_target_content = full_snapshot_content_signature(stage_target_snapshot)
          stage_target_fast = full_snapshot_fast_signature(stage_target_snapshot)
          stage_target_guard = network_fast_publish ? stage_target_fast : publish_target_light_guard(target)
          publish_breadcrumb!('target_snapshot_hash_returned', target: target, snapshot_ready: !stage_target_snapshot.to_s.empty?)
        end
      end
      if stage_target_existed && (stage_target_snapshot.empty? || stage_target_content.empty? || stage_target_guard.empty? || stage_target_fast.empty?)
        conflict_copy = publish_conflict_path_for(target, key)
        file_operation_with_retry { linkhub_copy_file(local_candidate, conflict_copy) }
        raise PublishConflictError.new(
          "提交前无法稳定读取共享目标。正式文件未改动；本地候选已保存：#{conflict_copy}",
          conflict_copy
        )
      end
      publish_breadcrumb!(
        'candidate_local_ready', candidate_size: candidate_size, target: target,
        target_existed: stage_target_existed, target_snapshot: stage_target_snapshot
      )
      remote_copy_started = monotonic_time
      publish_breadcrumb!('candidate_stage_copy_begin', local_candidate: local_candidate, remote_stage: temp, candidate_size: candidate_size)
      # 6.65：若候选与目标目录恰好位于同一 NTFS 卷，优先 hard-link；这时 3~300MB
      # 候选无需再复制一遍。NAS/跨卷不支持 hard-link 时自动退回 copy_file。
      stage_linked = false
      begin
        File.delete(temp) if File.file?(temp)
        File.link(local_candidate, temp)
        stage_linked = true
      rescue StandardError
        file_operation_with_retry { linkhub_copy_file(local_candidate, temp) }
      end
      unless File.file?(temp) && File.size(temp) == candidate_size && File.size(temp).positive?
        raise '提交候选从本机传输到共享目录失败，正式文件未被改动。'
      end
      if stage_linked
        # hard-link 与已经完整 SHA 校验过的本机候选是同一份文件内容，重复 SHA 没有价值。
        remote_content_signature = candidate_content_signature
        publish_breadcrumb!('remote_stage_hash_reused', remote_stage: temp, size: File.size(temp), mode: 'hardlink')
      elsif network_fast_publish
        # UNC/SMB：FileUtils.copy_file 已在 close 前返回写入错误，且本机候选已完整 SHA。
        # 现场 95MB SKP 上传本身约 3 秒，但立刻从 NAS 全量 SHA 读回会额外 16~60 秒。
        # 网络快速路径只核对远端长度/快速 stat，完整内容指纹直接继承已验证的本机候选。
        remote_fast = fast_file_signature(temp)
        raise '网络候选上传后无法读取文件状态。' if remote_fast.empty? || File.size(temp).to_i != candidate_size.to_i
        remote_content_signature = candidate_content_signature
        publish_breadcrumb!('remote_stage_network_trusted', remote_stage: temp, size: candidate_size, fast: remote_fast)
      else
        publish_breadcrumb!('remote_stage_hash_begin', remote_stage: temp, size: File.size(temp))
        remote_content_signature = full_file_content_signature(temp)
        publish_breadcrumb!('remote_stage_hash_returned', remote_stage: temp, signature_ready: !remote_content_signature.to_s.empty?)
      end
      unless !remote_content_signature.empty? && remote_content_signature == candidate_content_signature
        raise '提交候选传输后的内容与本机候选不一致，正式文件未被改动。'
      end
      publish_breadcrumb!('candidate_stage_copy_returned', remote_stage: temp, temp_exists: true, temp_size: File.size(temp), mode: (stage_linked ? 'hardlink' : 'copy'))
      log("发布候选传输共享目录：#{File.basename(target)} / #{candidate_size} bytes / #{elapsed_ms(remote_copy_started)}ms / #{stage_linked ? 'hardlink' : 'copy'}")
      latest_target_existed = File.file?(target)
      latest_target_guard = if latest_target_existed
                              network_fast_publish ? fast_file_signature(target) : publish_target_light_guard(target)
                            else
                              ''
                            end
      target_changed_during_stage = latest_target_existed != stage_target_existed ||
                                    (latest_target_existed && latest_target_guard != stage_target_guard)
      if target_changed_during_stage
        conflict_copy = publish_conflict_path_for(target, key)
        file_operation_with_retry { linkhub_copy_file(local_candidate, conflict_copy) }
        unless File.file?(conflict_copy) && File.size(conflict_copy) == candidate_size
          raise '检测到共享目标在传输期间变化，且本地冲突候选保存失败；正式文件未被改动。'
        end
        publish_breadcrumb!(
          'candidate_stage_target_conflict', target: target,
          before_snapshot: stage_target_guard, after_snapshot: latest_target_guard,
          before_existed: stage_target_existed, after_existed: latest_target_existed,
          conflict_copy: conflict_copy
        )
        raise PublishConflictError.new(
          "共享模型在候选传输期间被其他任务更新。未覆盖新版本；本地候选已保存：#{conflict_copy}",
          conflict_copy
        )
      end
      publish_breadcrumb!('candidate_ready', candidate_size: candidate_size, target: target, local_candidate: local_candidate, remote_stage: temp)
      force_copy_fallback = false
      promoted = nil

      if network_fast_publish
        # UNC/SMB 快速最终交换：上传完成后不再对 90~100MB stage 做重复整包读取，
        # 也不在共享盘上尝试 hard-link。最终窗口用短生命周期 EXCL 锁串行化，
        # 重新核对 target 的 mtime+size 后，仅做同目录 rename；rollback 始终保留到
        # 后台安全快照/版本历史维护结束。
        begin
          publish_breadcrumb!('network_final_swap_begin', target: target, target_existed: stage_target_existed)
          fast_swap = network_fast_swap_preverified_stage!(
            temp, target, candidate_size, candidate_content_signature,
            stage_target_existed: stage_target_existed,
            stage_target_fast: stage_target_fast
          )
          rollback = fast_swap[:rollback_path].to_s
          rollback = nil if rollback.empty?
          promoted = fast_swap[:promoted]
          temp = nil # stage 已通过 rename 消费，ensure 不再对刚删除的 SMB 路径做额外 stat。
          publish_breadcrumb!('network_final_swap_returned', target: target, rollback: rollback.to_s)
        rescue PublishConflictError
          raise
        rescue StandardError => e
          raise SourceFileBusyError, "网络共享最终替换失败。正式文件会优先保留/恢复，发布候选仍在本机：#{target}\n#{e.message}"
        end
      else
        if File.file?(target)
          rollback = publish_rollback_path_for(target)
          begin
            publish_breadcrumb!('target_to_rollback_begin', target: target, rollback: rollback)
            detached = detach_publish_target_with_hardlink_rollback!(
              target, rollback, expected_guard: stage_target_guard
            )
            if detached
              target_identity_before_move = detached[:identity].to_s
              rollback_identity_after_move = stable_file_identity_token(rollback)
              rollback_mode = detached[:mode].to_s
            else
              target_identity_before_move = stable_file_identity_token(target)
              # NAS/跨卷不支持 hard-link 时保留原来的同目录 rename 安全路径。
              file_operation_with_retry { File.rename(target, rollback) }
              rollback_identity_after_move = stable_file_identity_token(rollback)
              rollback_mode = 'rename'
            end
            publish_breadcrumb!('target_to_rollback_returned', rollback_exists: File.file?(rollback), mode: rollback_mode)
            if !target_identity_before_move.empty? && target_identity_before_move == rollback_identity_after_move &&
               !stage_target_content.to_s.empty?
              moved_content = stage_target_content
              publish_breadcrumb!('rollback_hash_reused', rollback: rollback, mode: rollback_mode)
            else
              publish_breadcrumb!('rollback_hash_begin', rollback: rollback)
              moved_content = full_file_content_signature(rollback)
              publish_breadcrumb!('rollback_hash_returned', rollback: rollback, snapshot_ready: !moved_content.to_s.empty?)
            end
            unless !stage_target_content.to_s.empty? && moved_content == stage_target_content
              begin
                promote_file_create_only!(rollback, target) unless File.exist?(target)
              rescue StandardError
                nil
              end
              raise PublishConflictError.new('共享目标在最终替换窗口发生变化。实际移走的版本与预检版本不一致；已停止发布，未把未知版本当作覆盖前文件。', '')
            end
          rescue PublishConflictError
            raise
          rescue StandardError => e
            unless force_overwrite
              raise SourceFileBusyError, "提交时无法替换共享缓存文件。可能是真的有程序以独占方式打开了该 SKP，或网络盘拒绝重命名：#{target}\n#{e.message}"
            end
            # 只有本专业工作区的强制发布允许从“原子重命名”降级为“先备份再覆盖写”。
            # 目标仍被系统独占写锁时此路径也会失败，不会伪报成功。
            force_applied = true
            forced_backup = preserve_forced_overwrite_target!(target, key) if forced_backup.empty?
            file_operation_with_retry { linkhub_copy_file(target, rollback) }
            force_copy_fallback = true
            log("本专业强制发布：目标不允许重命名，已切换为备份后覆盖写模式。")
          end
        end

        begin
          publish_breadcrumb!('candidate_replace_target_begin', target: target, fallback: force_copy_fallback)
          if force_copy_fallback
            file_operation_with_retry { linkhub_copy_file(temp, target) }
            File.delete(temp) if File.file?(temp)
            before_promoted = fast_file_signature(target)
            promoted_content = full_file_content_signature(target)
            after_promoted = fast_file_signature(target)
            raise '覆盖写后的正式候选稳定校验失败。' if before_promoted.empty? || before_promoted != after_promoted || promoted_content != candidate_content_signature
            promoted = { 'fast_signature' => after_promoted, 'content_signature' => promoted_content }
          else
            # remote_stage 已经整文件 SHA 验证过；create-only 提升不要再把 stage 本身从 NAS 读一遍。
            promoted = promote_preverified_file_create_only!(temp, target, candidate_content_signature)
          end
          publish_breadcrumb!('candidate_replace_target_returned', target_exists: File.file?(target), target_size: (File.file?(target) ? File.size(target) : 0))
        rescue StandardError => e
          restored = restore_publish_rollback!(target, rollback, expected_current_content: candidate_content_signature)
          detail = restored ? '已恢复覆盖前文件。' : '自动恢复未执行/未完成；若正式文件已被第三方再次写入则会原样保留，请同时保留 .sulink-rollback 文件。'
          raise SourceFileBusyError, "提交候选文件写回失败。目标 SKP 可能被操作系统独占写锁或网络盘拒绝覆盖：#{target}\n#{detail}\n#{e.message}"
        end
      end

      if network_fast_publish
        # network_fast_swap_preverified_stage! 已在 final-swap 锁内完成 stat/size 核对；
        # 不再紧接着对刚 rename 的 NAS 文件执行 utime + 多次 File.stat，避免服务端 AV/索引器
        # 把一次元数据刷新放大成十几秒。stage 的 mtime 本身就是本次本机序列化时间。
        signature = promoted.is_a?(Hash) ? promoted['fast_signature'].to_s : ''
        target_content_signature = promoted.is_a?(Hash) ? promoted['content_signature'].to_s : ''
        publish_breadcrumb!('target_content_hash_reused', target: target, signature_ready: !target_content_signature.empty?, mode: 'network_local_sha')
        if signature.empty? || target_content_signature.empty? || target_content_signature != candidate_content_signature
          restored = restore_publish_rollback!(target, rollback, expected_current_content: candidate_content_signature)
          rollback = nil if restored
          raise(restored ? '网络提交签名验证失败，已恢复提交前文件。' : "网络提交签名验证失败；请保留 .sulink-rollback 文件并核对：#{target}")
        end
        publish_breadcrumb!('target_verify_size_ok', target: target, size: candidate_size, mode: 'network_fast')
      else
        # 明确刷新修改时间，并验证真正写回了用户当前连接的 SKP。
        now = Time.now
        File.utime(now, now, target) rescue nil
        # utime 会改变快速签名中的 mtime；内容 SHA 可以复用，但 fast 必须重新读取一次。
        signature = fast_file_signature(target)
        unless File.file?(target) && File.size(target) == candidate_size && File.size(target).positive?
          restored = restore_publish_rollback!(target, rollback, expected_current_content: candidate_content_signature)
          rollback = nil if restored
          raise(restored ? '提交文件验证失败，已恢复提交前文件。' : "提交文件验证失败；若正式文件已被第三方再次写入则不会自动覆盖它。请保留同目录的 .sulink-rollback 文件并核对：#{target}")
        end
        # promote_preverified_file_create_only! 已经完成 fast-before -> full SHA -> fast-after。
        # 这里直接复用结果，不再把刚写好的 NAS target 连续整文件读取两遍。
        target_content_signature = promoted.is_a?(Hash) ? promoted['content_signature'].to_s : ''
        publish_breadcrumb!('target_content_hash_reused', target: target, signature_ready: !target_content_signature.empty?)
        if signature.empty? || target_content_signature.empty? || target_content_signature != candidate_content_signature
          restored = restore_publish_rollback!(target, rollback, expected_current_content: candidate_content_signature)
          rollback = nil if restored
          raise(restored ? '提交后稳定签名验证失败，已恢复提交前文件。' : "提交后正式文件又发生变化；未把变化后的文件当成本次发布。请保留 .sulink-rollback 文件并核对：#{target}")
        end
        publish_breadcrumb!('target_verify_size_ok', target: target, size: File.size(target))
      end

      safe_checkpoint = ''
      personal_checkpoint = ''
      personal_checkpoint_pending = false
      personal_source = target
      post_publish_maintenance_pending = !!defer_post_publish_maintenance

      if post_publish_maintenance_pending
        # 正式共享文件已经完成 create-only 提升 + 内容指纹验证。此刻隐藏 rollback 仍在同目录，
        # 所以已经具备立即恢复条件。安全快照 / 版本历史 / 个人快照全部属于发布后的维护工作，
        # 不再阻塞空间协作锁释放；worker 会继续串行整理。
        personal_checkpoint_pending = true
        publish_breadcrumb!(
          'post_publish_maintenance_deferred', target: target, rollback: rollback.to_s,
          content_signature: candidate_content_signature.to_s
        )
      else
        publish_breadcrumb!('safe_checkpoint_begin', target: target)
        safe_checkpoint = write_latest_safe_publish_checkpoint!(
          target, key, signature: signature, expected_content_signature: candidate_content_signature
        )
        publish_breadcrumb!('safe_checkpoint_returned', checkpoint: safe_checkpoint.to_s, ok: !safe_checkpoint.to_s.empty?)
        log("最近安全发布快照：#{safe_checkpoint.empty? ? '写入失败（正式发布仍已验证）' : safe_checkpoint}")
        if !safe_checkpoint.to_s.empty? && File.file?(safe_checkpoint)
          safe_meta = read_json_file("#{safe_checkpoint}.json") rescue {}
          personal_source = safe_checkpoint if safe_meta['signature'].to_s == signature.to_s
        end
        if defer_personal_checkpoint
          personal_checkpoint_pending = true
          publish_breadcrumb!('personal_checkpoint_deferred', source: personal_source)
        else
          publish_breadcrumb!('personal_checkpoint_begin', source: personal_source)
          personal_checkpoint = write_personal_publish_checkpoint!(
            personal_source, key, signature: signature, published_target: target,
            expected_content_signature: candidate_content_signature
          )
          publish_breadcrumb!('personal_checkpoint_returned', checkpoint: personal_checkpoint.to_s, ok: !personal_checkpoint.to_s.empty?)
          log("个人最近发布快照：#{personal_checkpoint.empty? ? '写入失败（正式发布仍已验证）' : personal_checkpoint}")
        end

        if rollback && File.file?(rollback)
          publish_breadcrumb!('rollback_archive_begin', rollback: rollback)
          history_backup = archive_publish_rollback!(target, rollback, key)
          publish_breadcrumb!('rollback_archive_returned', history_backup: history_backup.to_s, ok: !history_backup.to_s.empty?)
          if !history_backup.to_s.empty?
            rollback = nil
          else
            log("发布前版本未能归档，已保留瞬时回滚文件：#{rollback}")
          end
        end
      end

      final_size = candidate_size.to_i
      final_mtime = if network_fast_publish && promoted.is_a?(Hash) && promoted['mtime'].is_a?(Time)
                      promoted['mtime']
                    else
                      File.mtime(target)
                    end

      payload = {
        'schema' => 3,
        'plugin_version' => EXTENSION_VERSION,
        'discipline' => key,
        'discipline_name' => link['name'].to_s,
        'published_at' => Time.now.iso8601,
        'published_by' => current_user_name,
        'host' => current_host_name,
        'source_model' => source_model_path,
        'commit_file' => target,
        'backup_file' => forced_backup.to_s,
        'history_file' => history_backup.to_s,
        'safe_checkpoint_file' => safe_checkpoint.to_s,
        'personal_checkpoint_file' => personal_checkpoint.to_s,
        'post_publish_maintenance_pending' => !!post_publish_maintenance_pending,
        'rollback_file' => rollback.to_s,
        'forced_overwrite' => !!force_applied,
        'force_copy_fallback' => !!force_copy_fallback,
        'signature' => signature,
        'content_signature' => candidate_content_signature.to_s,
        'baseline_signature' => expected_signature.to_s,
        'size' => final_size,
        'workflow' => force_applied ? 'authoritative_workspace_force_commit' : 'linkhub_explicit_safe_commit'
      }
      # 协同目录已有专业 manifest.json / 空间模型.json 作为唯一版本清单，
      # 不再为每个共享 SKP 额外创建嵌套的 publish 元数据目录。
      unless collaboration_storage_path?(target)
        begin
          manifest = native_publish_manifest_path(target)
          ensure_metadata_target!(manifest)
          manifest_temp = "#{manifest}.tmp-#{Process.pid}-#{SecureRandom.hex(3)}"
          File.write(manifest_temp, JSON.pretty_generate(payload), mode: 'w:UTF-8')
          linkhub_mv(manifest_temp, manifest)
          retire_legacy_metadata_file(legacy_native_publish_manifest_path(target), manifest)
        rescue StandardError => e
          log_exception('写入提交记录失败，但源 SKP 已成功更新', e)
        ensure
          File.delete(manifest_temp) if defined?(manifest_temp) && manifest_temp && File.file?(manifest_temp)
        end
      end

      publish_breadcrumb!('atomic_publish_verified', target: target, signature: signature, size: final_size)
      {
        path: target,
        backup: forced_backup.to_s,
        history: history_backup.to_s,
        safe_checkpoint: safe_checkpoint.to_s,
        personal_checkpoint: personal_checkpoint.to_s,
        personal_checkpoint_pending: !!personal_checkpoint_pending,
        personal_checkpoint_source: personal_source.to_s,
        post_publish_maintenance_pending: !!post_publish_maintenance_pending,
        rollback_path: rollback.to_s,
        forced_overwrite: !!force_applied,
        force_copy_fallback: !!force_copy_fallback,
        signature: signature,
        content_signature: candidate_content_signature.to_s,
        size: final_size,
        mtime: final_mtime
      }
    rescue PublishConflictError
      raise
    rescue StandardError
      if rollback && File.file?(rollback)
        restored = restore_publish_rollback!(target, rollback, expected_current_content: candidate_content_signature.to_s)
        rollback = nil if restored
      end
      raise
    ensure
      File.delete(local_candidate) if !keep_local_candidate && defined?(local_candidate) && local_candidate && File.file?(local_candidate)
      File.delete(temp) if defined?(temp) && temp && File.file?(temp)
      File.delete(manifest_temp) if defined?(manifest_temp) && manifest_temp && File.file?(manifest_temp)
    end


    # 兼容建筑/景观/旧调用：仍提供原来的单函数入口，但内部也统一使用
    # “本机序列化 -> 纯文件发布”两段实现。只有空间发布会进一步把 SketchUp
    # candidate operation 在两段之间 abort 掉。
    def atomic_publish_definition(definition, target, key, link, expected_signature: '', baseline_path: '', baseline_signature: '', force_overwrite: false)
      expanded_target = FastPath.expand(target.to_s)
      raise '提交目标不是有效的 SKP 路径。' unless File.extname(expanded_target).casecmp('.skp').zero?
      raise '不能把外部联动组件写回当前正在打开的工作模型。' if same_file_path?(expanded_target, Sketchup.active_model.path.to_s)
      FileUtils.mkdir_p(File.dirname(expanded_target))
      if File.file?(expanded_target) && expected_signature.to_s.empty? && !force_overwrite
        raise PublishConflictError.new('共享目标已经存在，但当前会话没有可验证的编辑基线。为避免旧会话/首次发布覆盖别人版本，已停止发布；请先更新到最新共享模型后再修改。', '')
      end
      prepared = serialize_publish_definition_candidate!(definition, expanded_target, key)
      atomic_publish_prepared_candidate!(
        prepared, expanded_target, key, link,
        expected_signature: expected_signature,
        baseline_path: baseline_path,
        baseline_signature: baseline_signature,
        force_overwrite: force_overwrite
      )
    end

    def normalize_fast_signature(value)
      text = value.to_s
      parts = text.split('|')
      return "#{parts[0]}|#{parts[1]}" if parts.length >= 2 && parts[0].to_s.match?(/\A-?\d+(?:\.\d+)?\z/) && parts[1].to_s.match?(/\A\d+\z/)
      text
    rescue StandardError
      value.to_s
    end

    def loaded_entity_source_signature(entity)
      return '' unless entity && entity.valid? && entity.respond_to?(:get_attribute)
      raw = entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s
      return raw unless raw.empty?

      # 兼容 v0.6.10 及更早版本：旧属性可能保存的是
      # “mtime|size|asset:...|filter:...”的有效载入签名。提交冲突检查只需要
      # 源 SKP 本体的 mtime|size，不能把后续显示参数一起拿去比较。
      legacy = entity.get_attribute(ENTITY_DICT, 'source_signature', '').to_s
      normalize_fast_signature(legacy)
    rescue StandardError
      ''
    end

    def preview_baseline_signature(link, entity, source)
      stored = normalize_fast_signature(link['preview_base_signature'].to_s)
      return stored unless stored.empty?
      loaded = normalize_fast_signature(loaded_entity_source_signature(entity))
      return loaded unless loaded.empty?
      fast_file_signature(source)
    rescue StandardError
      ''
    end

    def begin_preview_state!(link, entity, source, model = Sketchup.active_model)
      baseline = preview_baseline_signature(link, entity, source)
      was_previewing = link['preview_edit_active'] || link['preview_pending_publish']
      link['preview_edit_active'] = true
      link['preview_pending_publish'] = false
      link['preview_base_signature'] = baseline
      link['preview_source_path'] = source.to_s.empty? ? '' : store_path(source, model)
      link['preview_started_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S') if link['preview_started_at'].to_s.empty?
      link['preview_relocked_at'] = ''
      link['preview_conflict'] = false
      link['preview_conflict_detail'] = ''
      link['last_commit_result'] = ''
      link['last_commit_verified'] = false
      link['auto_update'] = false
      baseline
    end

    def mark_preview_pending!(link, entity, source, model = Sketchup.active_model)
      baseline = preview_baseline_signature(link, entity, source)
      link['preview_edit_active'] = false
      link['preview_pending_publish'] = true
      link['preview_base_signature'] = baseline
      link['preview_source_path'] = source.to_s.empty? ? '' : store_path(source, model)
      link['preview_started_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S') if link['preview_started_at'].to_s.empty?
      link['preview_relocked_at'] = Time.now.strftime('%Y-%m-%d %H:%M:%S')
      link['preview_conflict'] = false
      link['preview_conflict_detail'] = ''
      link['last_commit_result'] = '' if link['last_commit_result'].to_s == 'running'
      link['last_commit_verified'] = false if link['last_commit_result'].to_s != 'success'
      # 记录确认起点以兼容旧状态字段；当前版本不再增加额外等待时间。
      now = Time.now
      link['commit_countdown_started_at'] = now.strftime('%Y-%m-%d %H:%M:%S')
      link['commit_countdown_until'] = (now.to_f + PUBLISH_CONFIRM_SECONDS)
      link['auto_update'] = false
      baseline
    end

    def clear_preview_state!(link, restore_auto: true)
      link['preview_edit_active'] = false
      link['preview_pending_publish'] = false
      link['preview_base_signature'] = ''
      link['preview_source_path'] = ''
      link['preview_started_at'] = ''
      link['preview_relocked_at'] = ''
      link['preview_conflict'] = false
      link['preview_conflict_detail'] = ''
      link['commit_countdown_started_at'] = ''
      link['commit_countdown_until'] = 0
      link['auto_update'] = false
      link['edit_previous_auto_update'] = false
      true
    end

    def managed_discipline_edit_source_entity(outer)
      return nil unless outer && outer.valid?
      child = world_wrapper_instance?(outer) ? world_source_child(outer) : nil
      child && child.valid? ? child : outer
    rescue StandardError
      outer
    end

    def architecture_edit_source_entity(outer)
      managed_discipline_edit_source_entity(outer)
    end

    def landscape_edit_source_entity(outer)
      managed_discipline_edit_source_entity(outer)
    end

    def active_path_inside_managed_discipline?(outer, source, model = Sketchup.active_model)
      path = Array(model.active_path)
      return false if path.empty?
      path.include?(source || outer)
    rescue StandardError
      false
    end

    def active_path_inside_architecture?(outer, source, model = Sketchup.active_model)
      active_path_inside_managed_discipline?(outer, source, model)
    end

    def active_path_inside_landscape?(outer, source, model = Sketchup.active_model)
      active_path_inside_managed_discipline?(outer, source, model)
    end

    # 世界坐标封装是插件内部结构，用户点“修改”时直接进入真正的专业源组件。
    def enter_managed_discipline_edit_context!(key, outer, model = Sketchup.active_model)
      discipline = key.to_s
      return false unless outer && outer.valid? && model
      source = managed_discipline_edit_source_entity(outer)
      @managed_discipline_edit_contexts ||= {}
      context_key = [model.object_id, discipline]
      @managed_discipline_edit_contexts[context_key] = {
        discipline: discipline,
        outer: outer,
        source: source,
        inside: true,
        transitioning: true
      }
      return true if active_path_inside_managed_discipline?(outer, source, model)
      return false unless model.active_path.nil?
      path = source == outer ? [outer] : [outer, source]
      model.selection.clear
      model.selection.add(outer)
      model.active_path = path if model.respond_to?(:active_path=)
      inside = active_path_inside_managed_discipline?(outer, source, model)
      if inside
        @managed_discipline_edit_contexts[context_key][:transitioning] = false
      else
        @managed_discipline_edit_contexts.delete(context_key)
      end
      inside
    rescue StandardError => e
      @managed_discipline_edit_contexts&.delete([model.object_id, discipline]) if model
      name = DISCIPLINES.dig(discipline, 'name').to_s
      log_exception("自动进入#{name.empty? ? discipline : name}组件失败", e)
      false
    end

    def enter_architecture_edit_context!(outer, model = Sketchup.active_model)
      enter_managed_discipline_edit_context!('architecture', outer, model)
    end

    def enter_landscape_edit_context!(outer, model = Sketchup.active_model)
      enter_managed_discipline_edit_context!('landscape', outer, model)
    end

    def handle_managed_discipline_active_path_change(key, model = Sketchup.active_model)
      discipline = key.to_s
      return false unless model
      return false unless workspace_ready?(nil, model)
      return false if @architecture_explicit_publish_in_progress
      @managed_discipline_edit_contexts ||= {}
      context_key = [model.object_id, discipline]
      record = @managed_discipline_edit_contexts[context_key]
      unless record
        # ESC 退出后不永久保留跟踪记录。用户之后原生双击重新进入源组件时，
        # 只要仍持有协作占用，就恢复跟踪，下一次 ESC 仍能正确回到全模。
        state = load_state(model)
        link = state.dig('links', discipline)
        return false unless link && link['edit_session_active']
        outer = native_edit_entity(discipline, model)
        return false unless outer && outer.valid?
        source = managed_discipline_edit_source_entity(outer)
        return false unless active_path_inside_managed_discipline?(outer, source, model)
        @managed_discipline_edit_contexts[context_key] = {
          discipline: discipline, outer: outer, source: source, inside: true, transitioning: false
        }
        refresh_workspace_toolbar(model)
        return true
      end

      outer = record[:outer]
      source = record[:source]
      unless outer && outer.valid?
        @managed_discipline_edit_contexts.delete(context_key)
        return false
      end
      path = Array(model.active_path)
      # 离开真正源组件但仍停留在内部世界坐标包裹层时，直接越过包裹层回到根部。
      if source && source != outer && path.include?(outer) && !path.include?(source) && record[:inside]
        model.active_path = nil
      end
      if active_path_inside_managed_discipline?(outer, source, model)
        record[:inside] = true
        record[:transitioning] = false
        return true
      end
      return false unless record[:inside]

      model.active_path = nil unless model.active_path.nil?
      return false unless model.active_path.nil?
      @managed_discipline_edit_contexts.delete(context_key)

      state = load_state(model)
      link = state.dig('links', discipline)
      return false unless link && link['edit_session_active']
      entity = native_edit_entity(discipline, model)
      return false unless entity && entity.valid?
      operation_started = false
      model.start_operation("退出#{link['name']}查看全模", true, false, true)
      operation_started = true
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
      link['preview_edit_active'] = true
      link['preview_pending_publish'] = false
      link['status'] = "#{current_user_name} 正在修改#{link['name']} · 已退出组件查看全模"
      save_state(state, model, write_manifest: false)
      model.commit_operation
      operation_started = false
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, discipline]] = false
      refresh_dialog
      refresh_workspace_toolbar(model)
      show_status("已退出到全模；#{link['name']}仍由你占用，发布只能使用 LinkHub 按钮。", 'info')
      true
    rescue StandardError => e
      model.abort_operation rescue nil if defined?(operation_started) && operation_started
      name = DISCIPLINES.dig(discipline, 'name').to_s
      log_exception("ESC 后退出#{name.empty? ? discipline : name}查看全模失败", e)
      false
    end

    # 历史方法名保留给 ModelObserver 调度；现在同时处理建筑与景观。
    def handle_architecture_active_path_change(model = Sketchup.active_model)
      changed = false
      state = load_state(model)
      %w[architecture landscape].each do |discipline|
        next if discipline == 'architecture' && architecture_collection_active?(state, model)
        changed = handle_managed_discipline_active_path_change(discipline, model) || changed
      end
      changed
    end

    def native_begin_edit_session(key)
      model = Sketchup.active_model
      raise '该专业正在后台发布，正式发布完成前不能重新进入修改。' if managed_discipline_background_publish_active?(key.to_s)
      discipline = key.to_s
      state = load_state(model)
      link = state['links'][discipline]
      raise '专业不存在。' unless link
      raise '当前工作专业使用本文件原生内容，不需要解锁外部参考。' if host_native_link?(state, discipline, model)
      managed_workflow = %w[architecture landscape].include?(discipline)
      if managed_workflow
        preflight_source = resolve_source_for_edit(link['model_path'].to_s, model)
        raise "#{link['name']}协同模型路径无效。" unless File.file?(preflight_source)
        assert_latest_safe_checkpoint_consistent!(preflight_source, discipline, link['name'].to_s)
      end
      switched_focus = managed_workflow ? prepare_edit_focus_switch!(discipline, model) : false
      state = load_state(model)
      link = state['links'][discipline]
      if managed_workflow
        raise "请先退出当前组件编辑层级，再修改#{link['name']}。" unless model.active_path.nil?
      end
      entity = native_edit_entity(discipline, model)
      raise '当前模型中尚未载入该专业，请先点击更新。' unless entity && entity.valid?
      safe_resume = managed_workflow && managed_edit_safe_paused?(link)
      already_unlocked = !entity_native_locked?(entity)
      return true if already_unlocked && !managed_workflow

      source = resolve_source_for_edit(link['model_path'].to_s, model)
      raise '源模型路径无效，不能建立临时编辑基线。' unless File.file?(source)
      acquired_here = false
      if managed_workflow
        refresh_discipline_collab_entry!(state, discipline, model)
        source = resolve_source_for_edit(link['model_path'].to_s, model)
        raise "#{link['name']}协同模型路径无效。" unless File.file?(source)
        assert_latest_safe_checkpoint_consistent!(source, discipline, link['name'].to_s)
        if managed_discipline_remote_pending?(discipline, state, model)
          raise "#{link['name']}有成员提交了新版本，请先更新后再修改。"
        end
        lock_info = source_lock_info(source, link, model, state)
        if lock_info['exists'] && !lock_info['stale'] && !lock_info['owned']
          lock_info = force_takeover_same_user_source_lock!(discipline, link, source, state, model) if lock_info['same_user_recoverable']
          unless lock_info && lock_info['owned']
            raise "#{lock_info && !lock_info['owner'].to_s.empty? ? lock_info['owner'] : '其他成员'} 正在修改#{link['name']}"
          end
        end
        unless lock_info['owned']
          record = acquire_source_lock(discipline, link, source, state)
          assign_lock_state!(link, record, fast_file_signature(source))
          acquired_here = true
        end
        link['edit_session_active'] = true
      end

      clear_managed_safe_pause!(link) if safe_resume
      begin_preview_state!(link, entity, source, model)
      link['edit_workflow'] = managed_workflow ? "#{discipline}_managed" : 'native_preview'

      operation_name = if managed_workflow
                         already_unlocked ? "恢复#{link['name']}协作占用" : "解锁#{link['name']}协作模型"
                       else
                         "临时解锁#{link['name']}联动模型"
                       end
      model.start_operation(operation_name, true)
      entity.locked = false if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', true)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
      entity.set_attribute(ENTITY_DICT, 'safe_paused', false)
      model.selection.clear
      model.selection.add(entity)
      model.commit_operation
      capture_edit_root_protection!(discipline, entity, model) if managed_workflow

      link['status'] = managed_workflow ? "#{current_user_name} 正在修改#{link['name']}" : '临时预览编辑中 · 未占用协作锁'
      save_state(state, model, write_manifest: false)
      @native_lock_state_cache ||= {}
      @native_lock_state_cache[[model.object_id, discipline]] = false
      entered = managed_workflow ? enter_managed_discipline_edit_context!(discipline, entity, model) : false
      refresh_dialog
      if managed_workflow
        recovered = acquired_here && already_unlocked
        success_message = if safe_resume
                            "已继续#{link['name']}未发布修改；协作占用和本地内容均保持不变。"
                          elsif switched_focus
                            "已安全暂存上一专业并进入#{link['name']}组件；旧修改未发布、未丢失。"
                          elsif recovered
                            "已回收上次中断的#{link['name']}占用并进入组件；本地未发布内容仍保留。"
                          else
                            "已进入#{link['name']}组件；ESC 可退出到全模；协作占用继续保留，发布只能使用 LinkHub 按钮。"
                          end
        show_status(entered ? success_message : "#{link['name']}已取得协作占用并解锁，请双击进入组件。", entered ? 'success' : 'error')
      else
        show_status("#{link['name']}已临时解锁。此操作不占协作锁；可快速试改，确认后先上锁，再点击“提交修改”。", 'success')
      end
      true
    rescue StandardError
      model.abort_operation rescue nil
      if defined?(acquired_here) && acquired_here && defined?(link) && link && defined?(source) && !source.to_s.empty?
        begin
          model.start_operation("恢复#{link['name']}锁定", true)
          entity.locked = true if defined?(entity) && entity && entity.valid? && entity.respond_to?(:locked=)
          model.commit_operation
        rescue StandardError
          model.abort_operation rescue nil
        end
        release_source_lock(link, source, model, state) rescue nil
        clear_edit_state!(link, restore_previous: false) rescue nil
        clear_preview_state!(link, restore_auto: true) rescue nil
        save_state(state, model, write_manifest: false) rescue nil if defined?(state) && state
      end
      raise
    end

    def native_publish_and_lock(key, allow_unlocked: false)
      started = monotonic_time
      publish_guard_acquired = false
      publish_error = nil
      queue_operation_open = false
      enqueued = false
      model = Sketchup.active_model
      state = load_state(model)
      discipline = key.to_s
      link = state['links'][discipline]
      raise '专业不存在。' unless link
      raise "#{link['name']}已经在后台发布队列中。" if managed_discipline_background_publish_active?(discipline)
      entity = native_edit_entity(key, model)
      raise '未找到该专业联动模型。' unless entity && entity.valid?
      raise '请先退出所有组件编辑层级，再执行提交。' unless model.active_path.nil?
      unless allow_unlocked || entity_native_locked?(entity)
        raise '请先使用 SketchUp 自带右键“锁定”，确认整体效果后再点击提交修改。'
      end

      validate_managed_edit_structure!(discipline, entity, model, interactive_definition_rebind: true)
      source = resolve_source_for_edit(link['model_path'].to_s, model)
      raise '当前连接源文件不存在，无法核对版本并提交。' unless File.file?(source)
      target = native_publish_target_for(key, link, model)
      baseline = preview_baseline_signature(link, entity, source)
      lock_subject = target
      publish_guard_acquired = enter_publish_critical_section!(
        kind: "managed_#{discipline}", subject: "#{link['name']}发布候选封装", target: target, model: model
      )
      publish_breadcrumb!('managed_publish_preflight', source: source, target: target, baseline: baseline, background_queue: true)

      lock_info = source_lock_info(lock_subject, link, model, state)
      if lock_info['exists'] && !lock_info['stale'] && !lock_info['owned']
        lock_info = force_takeover_same_user_source_lock!(discipline, link, lock_subject, state, model, allow_current_process: true) if lock_info['same_user']
        unless lock_info && lock_info['owned']
          owner = lock_info ? [lock_info['owner'], lock_info['host']].reject(&:empty?).join('@') : ''
          role = lock_info ? lock_info['actor_role_name'].to_s : ''
          raise "#{owner.empty? ? '其他成员' : owner}#{role.empty? ? '' : "（#{role}工作区）"}正在提交或编辑该模型"
        end
      end
      unless lock_info['owned']
        record = acquire_source_lock(key, link, lock_subject, state)
        assign_lock_state!(link, record, fast_file_signature(lock_subject))
      end
      link['edit_session_active'] = true
      link['edit_workflow'] = 'linkhub_explicit_commit'
      save_state(state, model, write_manifest: false)
      publish_breadcrumb!(
        'work_model_recovery_deferred_to_candidate',
        context: "#{link['name']}发布",
        reason: '统一异步发布：受管专业本机候选保留为恢复点，不再额外保存整份工作 SU'
      )

      unless same_file_path?(model.path.to_s, lock_subject)
        if should_skip_exclusive_probe_for_commit?(lock_subject)
          log("共享协同缓存提交跳过独占占用检测：#{lock_subject}")
        else
          ensure_source_available_for_edit!(lock_subject, '提交修改')
        end
      end
      current_source_signature = fast_file_signature(source)
      if !baseline.to_s.empty? && current_source_signature != baseline.to_s
        raise PublishConflictError.new('源模型在临时编辑期间已经更新，本地修改尚未覆盖对方版本。')
      end

      extra_wrapper_content = new_world_wrapper_extra_content_count(discipline, entity, model)
      if extra_wrapper_content.positive?
        continue_without_wrapper_extras = native_confirm_yes?("检测到你在 LinkHub 最外层封装中新增了 #{extra_wrapper_content} 个对象。

这些对象不会进入当前专业共享 SKP；真正源模型内部的修改会正常发布。是否忽略外层对象并继续？")
        raise '已取消提交；请把需要发布的对象移入真正的源模型组件后再试。' unless continue_without_wrapper_extras
      end
      commit_definition = commit_definition_for_entity(entity)
      raise '未找到可提交的源模型定义。' unless commit_definition
      foreign = foreign_managed_reference_count(commit_definition, key)
      raise "提交已阻止：当前源模型内部仍包含#{foreign}个其他专业 LinkHub 引用。请先移出或删除后再提交。" if foreign.positive?

      expected_signature = baseline.to_s.empty? ? fast_file_signature(target) : baseline
      prepared = serialize_publish_definition_candidate!(commit_definition, target, discipline, defer_content_signature: true)
      job_id = "bgdiscipline-#{discipline}-#{Time.now.strftime('%Y%m%d_%H%M%S')}-#{Process.pid}-#{SecureRandom.hex(4)}"

      # 只把当前根模型锁回，物理协作锁与 token 保留到后台正式文件+版本登记完成。
      model.start_operation("加入#{link['name']}后台发布队列", true, false, true)
      queue_operation_open = true
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
      link['background_publish_state'] = 'queued'
      link['background_publish_job_id'] = job_id
      link['background_publish_candidate'] = prepared[:path].to_s
      link['background_publish_error'] = ''
      link['last_commit_result'] = 'running'
      link['last_commit_verified'] = false
      link['status'] = '已加入发布队列 · 后台等待发布 · 协作占用保留'
      save_state(state, model, write_manifest: false)
      model.commit_operation
      queue_operation_open = false

      enqueue_space_publish_job!({
        job_id: job_id,
        job_kind: 'managed_discipline',
        space_id: "discipline:#{discipline}",
        discipline: discipline,
        label: link['name'].to_s,
        target: target.to_s,
        publish_key: discipline,
        expected_signature: expected_signature.to_s,
        baseline_path: source.to_s,
        baseline_signature: baseline.to_s,
        force_overwrite: false,
        source_model_path: model.path.to_s,
        model_object_id: model.object_id,
        prepared: prepared,
        initial_publish: false,
        started_monotonic: started
      }, model)
      enqueued = true
      show_status("#{link['name']}已加入统一发布队列；现在可以继续操作其它空间/建筑/景观。", 'success')
      refresh_dialog
      refresh_workspace_toolbar(model) rescue nil
      true
    rescue StandardError => e
      publish_error = e
      model.abort_operation rescue nil if queue_operation_open
      if defined?(prepared) && prepared.is_a?(Hash) && !enqueued
        path = prepared[:path].to_s
        File.delete(path) if !path.empty? && File.file?(path)
      end
      if defined?(link) && link && !enqueued
        begin
          recovery_state = load_state(model)
          recovery_link = recovery_state.dig('links', discipline)
          recovery_entity = native_edit_entity(discipline, model)
          if recovery_link && recovery_entity && recovery_entity.valid?
            recovery_link['background_publish_state'] = ''
            recovery_link['background_publish_job_id'] = ''
            recovery_link['background_publish_candidate'] = ''
            recovery_link['background_publish_error'] = e.message.to_s
            recovery_link['last_commit_result'] = 'error'
            recovery_link['status'] = "发布队列加入失败 · 继续修改 · #{e.message}"
            recovery_entity.locked = false if recovery_entity.respond_to?(:locked=)
            recovery_entity.set_attribute(ENTITY_DICT, 'editing', true)
            recovery_entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
            source2 = resolve_source_for_edit(recovery_link['model_path'].to_s, model)
            begin_preview_state!(recovery_link, recovery_entity, source2, model) if File.file?(source2)
            save_state(recovery_state, model, write_manifest: false)
          end
        rescue StandardError => recovery_error
          log_exception("#{discipline}后台发布入队失败后恢复修改状态失败", recovery_error)
        end
      end
      raise e
    ensure
      leave_publish_critical_section!(success: !!enqueued, error: publish_error, model: model) if publish_guard_acquired
    end

    def native_relock_only(key)
      model = Sketchup.active_model
      state = load_state(model)
      link = state['links'][key]
      entity = native_edit_entity(key, model)
      raise '未找到该专业联动模型。' unless entity && entity.valid?
      raise '请先退出组件编辑层级。' unless model.active_path.nil?
      source = resolve_source_for_edit(link['model_path'].to_s, model)
      raise '当前连接源文件不存在。' unless File.file?(source)
      ensure_active_workspace_owns_source_lock!(link, source, model, state, action: '锁定或暂存该修改') if link['edit_session_active']
      mark_preview_pending!(link, entity, source, model)

      model.start_operation("暂存并锁定#{link['name']}", true)
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
      model.commit_operation

      # 兼容从旧版“解锁即签出”迁移来的会话：仅上锁时释放旧锁。
      release_source_lock(link, source, model, state) if link['edit_session_active'] && File.file?(source)
      clear_edit_state!(link, restore_previous: false)
      link['status'] = '本地修改已暂存 · 待提交'
      save_state(state, model, write_manifest: false)
      refresh_dialog
      show_status("#{link['name']}已上锁，本地修改仍保留但尚未提交。确认效果后可点击“提交修改”。", 'success')
      true
    rescue StandardError
      model.abort_operation rescue nil
      raise
    end

    def native_discard_and_reload(key)
      model = Sketchup.active_model
      raise '该专业正在后台发布，完成前不能放弃/重载。' if managed_discipline_background_publish_active?(key.to_s)
      state = load_state(model)
      link = state['links'][key]
      entity = native_edit_entity(key, model)
      raise '未找到该专业联动模型。' unless entity && entity.valid?
      raise '请先退出组件编辑层级。' unless model.active_path.nil?
      entity.locked = true if entity.respond_to?(:locked=)
      entity.set_attribute(ENTITY_DICT, 'editing', false)
      entity.set_attribute(ENTITY_DICT, 'preview_editing', false)
      source = resolve_source_for_edit(link['model_path'].to_s, model)
      ensure_active_workspace_owns_source_lock!(link, source, model, state, action: '放弃或重载该修改') if link['edit_session_active'] && File.file?(source)
      release_source_lock(link, source, model, state) if link['edit_session_active'] && File.file?(source)
      clear_edit_state!(link, restore_previous: false)
      clear_preview_state!(link, restore_auto: true)
      clear_edit_root_protection!(key, model)
      save_state(state, model, write_manifest: false)
      result = load_linked_model(key, state, force: true)
      raise result[:message] unless result[:ok]
      save_state(state, model)
      refresh_dialog
      show_status("#{link['name']}本地临时修改已放弃，并从已连接文件重新载入。", 'success')
      true
    end

    # v0.5.4 延续场景安全外部编辑，并把“签出”和“打开模型”拆开。
    # 组件定义文件不包含源模型的 Pages/Scenes、样式、活动相机等模型级数据，旧流程会造成场景丢失。
    # 新流程签出后直接打开真正的源 SKP，由 SketchUp 原生保存，完整保留模型级信息。
    def begin_edit_session(key, open_after: false)
      native_begin_edit_session(key)
    end

    def open_checked_out_source(key)
      state = load_state
      link = state['links'][key]
      entity = native_edit_entity(key)
      raise '当前模型中尚未载入该专业。' unless entity && entity.valid?
      Sketchup.active_model.selection.clear
      Sketchup.active_model.selection.add(entity)
      show_status("已选中#{link['name']}联动模型。双击进入组件即可编辑。", 'success')
      true
    end

    def legacy_inline_recovery_path(source_path)
      base = File.basename(source_path, File.extname(source_path))
      File.join(File.dirname(source_path), "#{base}_旧版内嵌编辑待合并_#{Time.now.strftime('%Y%m%d_%H%M%S')}.skp")
    end

    def recover_legacy_inline_session!(key, state, link, source)
      instance = active_edit_entity(key)
      raise '未找到旧版内嵌编辑组件，无法生成恢复副本。' unless instance && instance.valid?
      path = legacy_inline_recovery_path(source)
      saved = instance.definition.respond_to?(:save_as) ? instance.definition.save_as(path) : false
      raise '无法保存旧版内嵌编辑恢复副本。' unless saved || File.file?(path)

      release_source_lock(link, source, Sketchup.active_model, state)
      clear_edit_state!(link, restore_previous: true)
      link['status'] = '旧版修改已另存 · 待手动合并'
      save_state(state)
      result = load_linked_model(key, state, force: true)
      save_state(state)
      refresh_dialog
      raise result[:message] unless result[:ok]
      show_status("检测到 v0.5.1 旧版内嵌编辑。为保护源模型场景，未覆盖源文件；几何修改已另存到：#{path}。请打开原源 SKP 后手动合并。", 'error')
      false
    end

    def finish_edit_session(key)
      state = load_state
      link = state.dig('links', key)
      until_ts = link ? link['commit_countdown_until'].to_f : 0.0
      remaining = until_ts - Time.now.to_f
      if remaining.positive?
        raise "为避免误触，请等待 #{remaining.ceil} 秒后再点击确认提交。"
      end
      name = link && link['name'] ? link['name'] : DISCIPLINES.dig(key, 'name').to_s
      return false unless native_confirm_yes?("确认提交#{name}修改并写回协同缓存吗？\n\n提交会覆盖该专业当前共享缓存，请确认已经检查无误。")
      native_publish_and_lock(key)
    end

    def discard_edit_session(key)
      cancel_preview_without_reload!(key)
    end

    def managed_discipline_remote_pending?(key, state, model = Sketchup.active_model)
      discipline = key.to_s
      link = state.dig('links', discipline)
      return false unless link
      stored = link['collab_full_path'].to_s.empty? ? link['model_path'].to_s : link['collab_full_path'].to_s
      source = resolve_path(stored, model)
      return false unless File.file?(source)
      entity = managed_model_instance_for(discipline, model)
      return true unless entity && entity.valid?

      current_revision = authoritative_link_revision(link, source)
      loaded_revision = loaded_entity_source_revision(entity)
      unless current_revision.empty?
        # Upgrade path: an entity loaded before v0.9.87 has no revision and must be
        # refreshed once instead of being accepted by a colliding mtime/size pair.
        return true if loaded_revision.empty?
        return loaded_revision != current_revision
      end

      loaded = normalize_fast_signature(loaded_entity_source_signature(entity))
      current = normalize_fast_signature(fast_file_signature(source))
      loaded.empty? || current.empty? || loaded != current
    rescue StandardError
      false
    end

    def architecture_remote_pending?(state, model = Sketchup.active_model)
      return false unless architecture_collection_active?(state, model)
      architecture_collection_remote_pending?(state, model)
    rescue StandardError
      false
    end

    def landscape_remote_pending?(state, model = Sketchup.active_model)
      managed_discipline_remote_pending?('landscape', state, model)
    end

    def managed_discipline_local_edit_active?(key, state, model = Sketchup.active_model)
      discipline = key.to_s
      link = state.dig('links', discipline)
      local_managed_edit_session?(discipline, link, model)
    rescue StandardError
      false
    end

    def architecture_local_edit_active?(state, model = Sketchup.active_model)
      return false unless architecture_collection_active?(state, model)
      !!architecture_collection_local_edit_record(state, model)
    rescue StandardError
      false
    end

    def landscape_local_edit_active?(state, model = Sketchup.active_model)
      managed_discipline_local_edit_active?('landscape', state, model)
    end

    # 建筑与景观发布只允许由 LinkHub 发布按钮触发：退出内部组件层级、写回共享 FULL 并最终上锁。
    # 发布失败时恢复解锁；若发布前位于组件内则重新进入，原本在全模审阅则留在根层级。
    def publish_managed_discipline_now(key, model = Sketchup.active_model)
      discipline = key.to_s
      raise '该专业已经在后台发布队列中。' if managed_discipline_background_publish_active?(discipline)
      guard_acquired = false
      was_inside = false
      state = load_state(model)
      link = state.dig('links', discipline)
      raise '专业不存在。' unless link
      raise "#{link['name']}发布正在进行，请稍候。" if @architecture_explicit_publish_in_progress
      entity = native_edit_entity(discipline, model)
      raise "未找到正在修改的#{link['name']}协同模型。" unless entity && entity.valid?
      raise "当前#{link['name']}没有处于修改状态。" unless managed_discipline_local_edit_active?(discipline, state, model)

      source_entity = managed_discipline_edit_source_entity(entity)
      if !model.active_path.nil? && !active_path_inside_managed_discipline?(entity, source_entity, model)
        raise '当前正在编辑另一个组件，请先结束该组件编辑。'
      end
      was_inside = active_path_inside_managed_discipline?(entity, source_entity, model)
      preview_definition = commit_definition_for_entity(entity)
      return false unless confirm_empty_definition_publish?(link['name'], preview_definition)

      @architecture_explicit_publish_in_progress = true
      guard_acquired = true
      @managed_discipline_edit_contexts&.delete([model.object_id, discipline])
      model.active_path = nil unless model.active_path.nil?
      raise "未能退出#{link['name']}组件层级，发布尚未开始。" unless model.active_path.nil?
      native_publish_and_lock(discipline, allow_unlocked: true)
    rescue StandardError => e
      begin
        raise StopIteration unless guard_acquired
        recovery_state = load_state(model)
        recovery_link = recovery_state.dig('links', discipline)
        recovery_entity = native_edit_entity(discipline, model)
        if recovery_link && recovery_link['edit_session_active'] && recovery_entity && recovery_entity.valid?
          source = resolve_source_for_edit(recovery_link['model_path'].to_s, model)
          begin_preview_state!(recovery_link, recovery_entity, source, model)
          recovery_link['status'] = "#{recovery_link['name']}发布未完成 · 继续修改"
          recovery_entity.locked = false if recovery_entity.respond_to?(:locked=)
          recovery_entity.set_attribute(ENTITY_DICT, 'editing', true)
          recovery_entity.set_attribute(ENTITY_DICT, 'preview_editing', true)
          save_state(recovery_state, model, write_manifest: false)
          @native_lock_state_cache ||= {}
          @native_lock_state_cache[[model.object_id, discipline]] = false
          if was_inside
            enter_managed_discipline_edit_context!(discipline, recovery_entity, model)
          else
            @managed_discipline_edit_contexts&.delete([model.object_id, discipline])
          end
        end
      rescue StopIteration
        nil
      rescue StandardError => recovery_error
        log_exception("#{discipline}发布失败后恢复编辑层级失败", recovery_error)
      end
      raise e
    ensure
      @architecture_explicit_publish_in_progress = false if guard_acquired
      refresh_workspace_toolbar(model) rescue nil
    end

    def publish_architecture_now(model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      item = architecture_collection_local_edit_record(state, model) || selected_architecture_model_record(state, model)
      raise '请先选择或修改一个建筑模型。' unless item
      if item['editing'] || state['architecture_editing_id'].to_s == item['id'].to_s
        publish_architecture_model(item['id'], model)
      else
        edit_architecture_model(item['id'], model)
      end
    end

    def publish_landscape_now(model = Sketchup.active_model)
      publish_managed_discipline_now('landscape', model)
    end

    def architecture_quick_action(model = Sketchup.active_model)
      architecture_collection_quick_action(model)
    end

    def update_landscape_safely(notify: true, force: false)
      model = Sketchup.active_model
      raise '景观正在后台发布，正式发布完成前不能更新/载入。' if managed_discipline_background_publish_active?('landscape')
      raise '请先退出组件编辑层级，再更新景观。' unless model.active_path.nil?
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再更新景观。' if publish_critical_section? || publish_post_quiet?
      raise '模型库批量任务正在执行，请等待完成后再更新景观。' if @soft_model_batch_job
      state = load_state(model)
      link = state.dig('links', 'landscape')
      raise '景观专业不存在。' unless link
      raise '当前景观仍有本地修改待发布，请先发布或继续修改。' if landscape_local_edit_active?(state, model)
      refresh_landscape_collab_entry!(state, model)
      source = resolve_path(link['model_path'].to_s, model)
      raise '尚未找到可用的景观协同模型。请先连接正确的协同.json，或先发布景观缓存。' unless File.file?(source)

      bootstrap_takeover = host_discipline_for(state) == 'landscape' &&
                           !discipline_managed_collaboration?(state, 'landscape', model) &&
                           !managed_model_instance_for('landscape', model)
      takeover_entities = bootstrap_takeover ? landscape_native_root_entities_for_takeover(model, state) : []
      local_raw_geometry = bootstrap_takeover ? root_raw_geometry_count(model) : 0
      if bootstrap_takeover && takeover_entities.empty? && local_raw_geometry.positive?
        raise "当前工作 SU 根层级仍有 #{local_raw_geometry} 条散线/散面，不能把它当作空白文件接管共享景观。请先删除干净，或把本地景观编组后选中该组再获取。"
      end

      if bootstrap_takeover
        if takeover_entities.any?
          label = takeover_entities.length == 1 ? '当前选中的本地景观工作模型' : "当前 #{takeover_entities.length} 个本地景观根模型"
          confirmed = native_confirm_yes?("协同中已经存在已发布的景观模型。\n\n获取后会用共享景观替换#{label}，其他专业参考不会删除。是否继续？")
          return false unless confirmed
        end

        raise '当前正在执行其他模型更新，请稍后再试。' if @updating
        view_state = capture_active_view_state
        @updating = true
        begin_soft_heavy_interaction(:linked_model_update)
        operation_open = false
        begin
          model.start_operation('获取共享景观并接管工作模型', true)
          operation_open = true
          link['landscape_collab_managed'] = true
          result = load_linked_model('landscape', state, force: true)
          raise result[:message].to_s unless result[:ok] && !result[:host_native]

          replaced_count = 0
          takeover_entities.each do |entity|
            next unless entity && entity.valid?
            entity.locked = false if entity.respond_to?(:locked=)
            entity.erase!
            replaced_count += 1
          end
          discovered = apply_discovered_dependencies!(state, 'landscape', result[:dependencies] || [])
          link['status'] = takeover_entities.empty? ? '空白工作文件已获取共享景观并完成接管' : '已用共享景观接管本地工作模型'
          save_state(state, model, write_manifest: false)
          model.commit_operation
          operation_open = false
          reapply_professional_visibility!('landscape', state, model)
          relock_managed_entities
          refresh_dialog
          refresh_workspace_toolbar(model)
          suffix = replaced_count.positive? ? "；已替换 #{replaced_count} 个本地景观根模型" : '；当前为空白工作文件，已直接载入'
          dependency_note = Array(discovered[:messages]).empty? ? '' : "；#{Array(discovered[:messages]).join('；')}"
          show_status("已获取协同中的最新景观模型#{suffix}#{dependency_note}", 'success') if notify
          return true
        rescue StandardError
          model.abort_operation rescue nil if operation_open
          raise
        ensure
          restore_active_view_state(view_state)
          @updating = false
          end_soft_heavy_interaction(:linked_model_update)
        end
      end

      pending = landscape_remote_pending?(state, model)
      unless pending || force || !managed_model_instance_for('landscape', model)
        show_status('景观已经是最新版本，无需更新。', 'success') if notify
        return true
      end
      link['landscape_collab_managed'] = true if host_discipline_for(state) == 'landscape'
      save_state(state, model, write_manifest: false)
      success = update_links(['landscape'], notify: notify, force: true)
      refresh_workspace_toolbar(model)
      success
    rescue StandardError => e
      log_exception('安全更新景观失败', e)
      show_status("景观未更新：#{e.message}", 'error') if notify
      false
    end

    def landscape_quick_action(model = Sketchup.active_model)
      if managed_discipline_background_publish_active?('landscape')
        job = background_publish_job_snapshot('discipline:landscape')
        show_status("景观正在后台发布 #{job['progress'].to_i}% · #{job['stage_label']}", 'info')
        return true
      end
      state = load_state(model)
      refresh_landscape_collab_entry!(state, model)
      link = state.dig('links', 'landscape')
      raise '景观专业不存在。' unless link

      if landscape_local_edit_active?(state, model)
        return native_begin_edit_session('landscape') if managed_edit_safe_paused?(link)
        return publish_landscape_now(model)
      end
      source = resolve_path(link['collab_full_path'].to_s.empty? ? link['model_path'].to_s : link['collab_full_path'].to_s, model)
      if host_discipline_for(state) == 'landscape' && !link['landscape_collab_managed'] && !managed_model_instance_for('landscape', model)
        # 与建筑一致：重连后共享端已有景观 FULL 就先获取，不误走首次发布。
        return update_landscape_safely(notify: true, force: true) if File.file?(source)
        result = publish_collab_cache_sync
        return !!(result && result[:success])
      end
      return update_landscape_safely(notify: true) if landscape_remote_pending?(state, model) || !managed_model_instance_for('landscape', model)
      begin_edit_session('landscape')
    end

    # 其他成员占用建筑时，共享 FULL 仍是最近一次已经发布的稳定版本。
    # 此入口只读取该版本，不取得、释放或覆盖对方的协作锁。
    def update_architecture_previous_published(model = Sketchup.active_model)
      state = ensure_architecture_models_ready!(model)
      item = selected_architecture_model_record(state, model)
      return update_architecture_model(item['id'], notify: true, model: model) if item
      update_all_architecture_models(notify: true, model: model)
    end

    def architecture_publish_author(link)
      owner = link['collab_last_published_by'].to_s.strip
      host = link['collab_last_publish_host'].to_s.strip
      return '其他成员' if owner.empty? && host.empty?
      return host if owner.empty?
      return owner if host.empty? || owner.casecmp(host).zero?
      "#{owner}@#{host}"
    rescue StandardError
      '其他成员'
    end

    def architecture_skipped_root_geometry_count(link, model = Sketchup.active_model)
      path = resolve_path(link['collab_manifest_path'].to_s, model)
      return 0 unless File.file?(path)
      payload = JSON.parse(File.read(path, mode: 'rb'))
      payload.is_a?(Hash) ? payload['root_raw_geometry_skipped'].to_i : 0
    rescue StandardError
      0
    end

    def architecture_backup_directory
      raw = Sketchup.read_default(HUD_PREF_SECTION, ARCHITECTURE_BACKUP_DIR_PREF_KEY, '').to_s.strip
      return '' if raw.empty?
      FastPath.expand(raw)
    rescue StandardError
      ''
    end

    def set_architecture_backup_directory(path)
      directory = path.to_s.strip
      raise '请选择有效的副本文件夹。' if directory.empty?
      directory = FastPath.expand(directory)
      raise '选择的副本文件夹不存在。' unless Dir.exist?(directory)
      Sketchup.write_default(HUD_PREF_SECTION, ARCHITECTURE_BACKUP_DIR_PREF_KEY, directory)
      directory
    end

    def architecture_backup_interval_minutes
      raw = Sketchup.read_default(
        HUD_PREF_SECTION,
        ARCHITECTURE_BACKUP_INTERVAL_PREF_KEY,
        ARCHITECTURE_BACKUP_INTERVAL_DEFAULT
      )
      value = raw.to_i
      value = 0 if value.negative?
      [value, ARCHITECTURE_BACKUP_INTERVAL_MAX].min
    rescue StandardError
      ARCHITECTURE_BACKUP_INTERVAL_DEFAULT
    end

    def set_architecture_backup_interval_minutes(value)
      text = value.to_s.strip
      raise '副本提醒间隔必须是整数分钟。' unless text.match?(/\A\d+\z/)
      minutes = text.to_i
      raise "副本提醒间隔不能超过 #{ARCHITECTURE_BACKUP_INTERVAL_MAX} 分钟。" if minutes > ARCHITECTURE_BACKUP_INTERVAL_MAX
      Sketchup.write_default(HUD_PREF_SECTION, ARCHITECTURE_BACKUP_INTERVAL_PREF_KEY, minutes)
      minutes
    end

    def working_copy_backup_record_key(model = Sketchup.active_model)
      path = active_model_file_path(model)
      basis = if path.empty?
                "session:#{model.object_id}"
              else
                normalized = FastPath.expand(path).tr('\\', '/')
                normalized = normalized.downcase if windows_platform?
                "path:#{normalized}"
              end
      Digest::SHA1.hexdigest(basis)
    rescue StandardError
      Digest::SHA1.hexdigest("session:#{model.object_id}")
    end

    def working_copy_backup_records
      raw = Sketchup.read_default(HUD_PREF_SECTION, WORKING_COPY_BACKUP_RECORDS_PREF_KEY, '{}').to_s
      parsed = JSON.parse(raw)
      parsed.is_a?(Hash) ? parsed : {}
    rescue StandardError
      {}
    end

    def record_working_copy_backup!(path, model = Sketchup.active_model, timestamp: Time.now)
      target = FastPath.expand(path.to_s)
      raise '副本文件不存在，不能登记保存时间。' unless File.file?(target) && File.size(target).positive?
      records = working_copy_backup_records
      records[working_copy_backup_record_key(model)] = {
        'path' => target,
        'at' => timestamp.iso8601,
        'model_path' => active_model_file_path(model)
      }
      ordered = records.to_a.sort_by { |_key, item| Time.parse(item['at'].to_s).to_f rescue 0.0 }
      records = ordered.last(WORKING_COPY_BACKUP_RECORD_LIMIT).each_with_object({}) do |(key, item), memo|
        memo[key] = item
      end
      Sketchup.write_default(HUD_PREF_SECTION, WORKING_COPY_BACKUP_RECORDS_PREF_KEY, JSON.generate(records))
      true
    end

    # 副本位置和时间属于当前电脑的个人保护设置，不写入 SKP，也不进入 SketchUp Undo 栈。
    # 首次升级仍兼容读取 v0.9.20 已经写在模型状态中的最后一次副本。
    def architecture_backup_record(link, model = Sketchup.active_model)
      records = working_copy_backup_records
      key = working_copy_backup_record_key(model)
      if records.key?(key)
        record = records[key]
        path = record.is_a?(Hash) ? FastPath.expand(record['path'].to_s) : ''
        raw = record.is_a?(Hash) ? record['at'].to_s.strip : ''
        return nil if path.empty? || raw.empty? || !File.file?(path)
        Time.parse(raw)
        return { 'path' => path, 'at' => raw }
      end

      return nil unless link
      stored_path = link['architecture_last_backup_path'].to_s
      path = resolve_path(stored_path, model)
      raw = link['architecture_last_backup_at'].to_s.strip
      return nil if stored_path.empty? || raw.empty? || !File.file?(path)
      Time.parse(raw)
      { 'path' => path, 'at' => raw }
    rescue StandardError
      nil
    end

    def architecture_last_backup_time(link, model = Sketchup.active_model)
      record = architecture_backup_record(link, model)
      record ? Time.parse(record['at'].to_s) : nil
    rescue StandardError
      nil
    end

    def architecture_last_backup_path(link, model = Sketchup.active_model)
      record = architecture_backup_record(link, model)
      record ? record['path'].to_s : ''
    rescue StandardError
      ''
    end

    def architecture_backup_prompt_due?(link, model = Sketchup.active_model, now: Time.now)
      interval = architecture_backup_interval_minutes
      return true if interval <= 0
      last_time = architecture_last_backup_time(link, model)
      return true unless last_time
      (now.to_f - last_time.to_f) >= interval * 60.0
    rescue StandardError
      true
    end

    def architecture_backup_minutes_remaining(link, model = Sketchup.active_model, now: Time.now)
      interval = architecture_backup_interval_minutes
      return 0 if interval <= 0
      last_time = architecture_last_backup_time(link, model)
      return 0 unless last_time
      remaining = interval * 60.0 - (now.to_f - last_time.to_f)
      remaining.positive? ? (remaining / 60.0).ceil : 0
    rescue StandardError
      0
    end

    def open_directory_path(path, label = '文件夹')
      directory = FastPath.expand(path.to_s)
      raise "#{label}不存在。" unless Dir.exist?(directory)
      if windows_platform?
        pid = Process.spawn('explorer.exe', directory.tr('/', '\\'), out: File::NULL, err: File::NULL)
      else
        command = RUBY_PLATFORM =~ /darwin/i ? ['open', directory] : ['xdg-open', directory]
        pid = Process.spawn(*command, out: File::NULL, err: File::NULL)
      end
      Process.detach(pid)
      show_status("已打开#{label}：#{directory}", 'success')
      true
    end

    def open_collaboration_project_directory(model = Sketchup.active_model)
      state = load_state(model)
      directory = selected_collab_project_dir_for_state(state, model).to_s
      raise '当前尚未连接有效的协同项目。' if directory.empty?
      open_directory_path(directory, '协同项目文件夹')
    end

    def open_linkhub_log_directory
      directory = File.dirname(LOG_PATH)
      FileUtils.mkdir_p(directory)
      open_directory_path(directory, 'LinkHub 日志文件夹')
    end

    def edit_architecture_backup_interval_from_drawer(model = Sketchup.active_model)
      current = architecture_backup_interval_minutes
      result = UI.inputbox(
        ['建筑更新提醒间隔（分钟，0 表示每次询问）'],
        [current],
        'SU LinkHub · 工作模型副本设置'
      )
      return false unless result
      value = result.first.to_s.strip
      raise '请输入 0 到 525600 之间的整数分钟。' unless value.match?(/\A\d+\z/)
      save_architecture_backup_settings(value.to_i, model)
      refresh_workspace_toolbar(model, detailed: true)
      true
    end

    def choose_architecture_backup_directory(model = Sketchup.active_model, notify: true)
      current = architecture_backup_directory
      initial = Dir.exist?(current) ? current : (model_directory(model) || Dir.home)
      chosen = UI.select_directory(title: '选择工作模型副本文件夹', directory: initial)
      return '' if chosen.to_s.empty?
      directory = set_architecture_backup_directory(chosen)
      refresh_dialog
      show_status("工作模型副本将固定保存到：#{directory}", 'success') if notify
      directory
    rescue StandardError => e
      log_exception('设置建筑副本文件夹失败', e)
      show_status("副本文件夹设置失败：#{e.message}", 'error') if notify
      ''
    end

    def open_architecture_backup_directory(model = Sketchup.active_model)
      directory = architecture_backup_directory
      raise '尚未设置有效的工作模型副本文件夹。' unless Dir.exist?(directory)
      if windows_platform?
        # Explorer 的 /e, 参数若被拆成两个 ArgumentList 项，会忽略目标并回落到“文档”。
        # 直接把已验证的目录作为唯一参数传入，可正确处理中文及带空格路径。
        pid = Process.spawn('explorer.exe', directory.tr('/', '\\'), out: File::NULL, err: File::NULL)
        Process.detach(pid)
      else
        command = RUBY_PLATFORM =~ /darwin/i ? ['open', directory] : ['xdg-open', directory]
        pid = Process.spawn(*command, out: File::NULL, err: File::NULL)
        Process.detach(pid)
      end
      show_status("已打开工作模型副本文件夹：#{directory}", 'success')
      true
    end

    def open_or_choose_architecture_backup_directory(model = Sketchup.active_model)
      directory = architecture_backup_directory
      return open_architecture_backup_directory(model) if Dir.exist?(directory)
      !choose_architecture_backup_directory(model).to_s.empty?
    end

    def save_architecture_backup_settings(interval_minutes, model = Sketchup.active_model)
      minutes = set_architecture_backup_interval_minutes(interval_minutes)
      refresh_dialog
      detail = minutes.zero? ? '每次建筑更新都询问是否保存副本。' : "距上次成功副本超过 #{minutes} 分钟时才会再次提醒。"
      show_status("工作模型副本设置已保存；#{detail}", 'success')
      true
    end

    def architecture_backup_default_path(model = Sketchup.active_model, directory: nil, timestamp: Time.now)
      folder = directory.to_s.strip
      folder = architecture_backup_directory if folder.empty?
      folder = model_directory(model) || Dir.home if folder.empty? || !Dir.exist?(folder)
      stamp = timestamp.strftime('%Y%m%d_%H%M%S')
      base = File.join(folder, "#{stamp}--建筑备份.skp")
      return base unless File.exist?(base)

      index = 2
      loop do
        candidate = File.join(folder, "#{stamp}--建筑备份--#{index}.skp")
        return candidate unless File.exist?(candidate)
        index += 1
      end
    rescue StandardError
      File.join(Dir.home, "#{Time.now.strftime('%Y%m%d_%H%M%S')}--建筑备份.skp")
    end

    def choose_architecture_backup_path(model, source_path)
      directory = architecture_backup_directory
      directory = choose_architecture_backup_directory(model, notify: false) unless Dir.exist?(directory)
      return '' if directory.to_s.empty?
      target = FastPath.expand(architecture_backup_default_path(model, directory: directory))
      current = active_model_file_path(model)
      raise '副本不能覆盖当前正在打开的工作模型，请换一个文件名。' if !current.empty? && same_file_path?(target, current)
      raise '副本不能覆盖建筑协同源文件，请换一个文件夹或文件名。' if same_file_path?(target, source_path)
      raise '副本路径必须是一个 SKP 文件。' unless File.extname(target).casecmp('.skp').zero?
      target
    end

    # SketchUp::Model#save_copy 只能用于至少正常保存过一次的模型。
    # 新建且未命名的工作模型先让用户选择正式工作文件位置；取消时不创建副本，
    # 调用方也必须停止建筑更新，避免“副本失败但仍继续覆盖”。
    def ensure_model_saved_before_working_copy(model = Sketchup.active_model, notify: true)
      return true unless active_model_file_path(model).empty?

      suggested = model.title.to_s.strip
      suggested = '未命名模型' if suggested.empty?
      suggested = "#{suggested}.skp" unless File.extname(suggested).casecmp('.skp').zero?
      initial = model_directory(model)
      initial = nil unless initial && Dir.exist?(initial)
      path = UI.savepanel('当前工作模型尚未保存，请先保存后再创建副本', initial, suggested)
      if path.nil? || path.to_s.strip.empty?
        show_status('已取消首次保存；没有创建副本，也没有执行后续操作。', 'info') if notify
        return false
      end

      path = FastPath.expand(path.to_s)
      path = "#{path}.skp" unless File.extname(path).casecmp('.skp').zero?
      saved = model.save(path)
      raise 'SketchUp 未能保存当前工作模型。' if saved == false
      current = active_model_file_path(model)
      current = path if current.empty?
      raise '当前工作模型没有成功写出，副本尚未创建。' unless File.file?(current) && File.size(current).positive?

      show_status("当前工作模型已首次保存：#{current}", 'success') if notify
      true
    rescue StandardError => e
      log_exception('创建副本前首次保存工作模型失败', e)
      show_status("当前工作模型保存失败：#{e.message}", 'error') if notify
      false
    end

    def save_architecture_working_copy!(model, target)
      raise '当前工作模型尚未完成首次保存，不能创建副本。' if active_model_file_path(model).empty?
      FileUtils.mkdir_p(File.dirname(target))
      before_mtime = File.file?(target) ? File.mtime(target).to_f : 0.0
      saved = false
      begin
        saved = model.respond_to?(:save_copy) ? model.save_copy(target) : false
      rescue StandardError => copy_error
        raise copy_error unless copy_error.message.to_s.match?(/must be saved before copying/i)

        # 个别 SketchUp 版本即使已有路径，也会在当前文件尚未落盘时拒绝 save_copy。
        # 只针对这一条明确错误正常保存一次当前工作文件，然后重试副本；其他异常不吞掉。
        current_saved = model.save
        raise '当前工作模型需要先正常保存，但 SketchUp 保存失败。' if current_saved == false
        File.delete(target) if before_mtime <= 0.0 && File.file?(target)
        saved = model.respond_to?(:save_copy) ? model.save_copy(target) : false
      end
      raise 'SketchUp 未能另存当前工作模型，当前操作已停止。' if saved == false
      raise '副本文件没有成功写出，当前操作已停止。' unless File.file?(target) && File.size(target).positive?
      if before_mtime.positive? && File.mtime(target).to_f <= before_mtime && saved != true
        raise '无法确认副本已被覆盖写入，当前操作已停止。请换一个新文件名。'
      end
      target
    rescue StandardError => e
      log_exception('另存工作模型副本失败', e)
      raise e
    end

    def save_working_copy_now(model = Sketchup.active_model, notify: true)
      return false unless ensure_model_saved_before_working_copy(model, notify: notify)
      state = load_state(model)
      link = state.dig('links', 'architecture') || {}
      source = resolve_path(link['model_path'].to_s, model)
      target = choose_architecture_backup_path(model, source)
      if target.empty?
        show_status('已取消保存工作模型副本。', 'info') if notify
        return false
      end
      save_architecture_working_copy!(model, target)
      record_working_copy_backup!(target, model)
      refresh_dialog
      show_status("整份工作模型副本已保存：#{target}", 'success') if notify
      true
    rescue StandardError => e
      log_exception('立即保存工作模型副本失败', e)
      show_status("副本保存失败：#{e.message}", 'error') if notify
      false
    end

    def root_raw_geometry_count(model = Sketchup.active_model)
      model.entities.grep(Sketchup::Face).length + model.entities.grep(Sketchup::Edge).length
    rescue StandardError
      0
    end

    def native_root_entities_for_remote_takeover(discipline, model = Sketchup.active_model, state = nil)
      state ||= load_state(model)
      key = discipline.to_s
      work_model = host_work_model_entity(state, key, model)
      return [work_model] if work_model && work_model.valid?

      selected = strict_selected_host_work_model_entity(model)
      return [selected] if selected && selected.valid?

      candidates = model.entities.to_a.select { |entity| root_group_or_component?(entity, model) }
      return [] if candidates.empty?
      return candidates if candidates.length == 1

      label = DISCIPLINES.dig(key, 'name').to_s
      label = key if label.empty?
      raise "获取共享#{label}前，当前模型根层级存在多个普通群组/组件。请只选中需要被共享#{label}替换的原工作模型；空白 SU 可直接获取。"
    rescue StandardError => e
      raise e if e.message.to_s.include?('获取共享') || e.message.to_s.include?('首次切换为共享')
      []
    end

    # 首次把建筑工作文件切换为统一协作根时，只替换此前选定的建筑工作模型。
    # 其他根层级参考、临时组和辅助内容必须保留，不能再像旧版那样全部删除。
    def architecture_native_root_entities_for_takeover(model = Sketchup.active_model, state = nil)
      native_root_entities_for_remote_takeover('architecture', model, state)
    end

    def landscape_native_root_entities_for_takeover(model = Sketchup.active_model, state = nil)
      native_root_entities_for_remote_takeover('landscape', model, state)
    end

    def update_architecture_safely(notify: true, force: false)
      model = Sketchup.active_model
      state = ensure_architecture_models_ready!(model)
      item = selected_architecture_model_record(state, model)
      if item
        update_architecture_model(item['id'], notify: notify, model: model)
      else
        update_all_architecture_models(notify: notify, model: model)
      end
    end

    def update_links(initial_keys, notify: true, force: false)
      raise '发布正在进行或仍处于原生收尾阶段，请稍后再更新联动模型。' if publish_critical_section? || publish_post_quiet?
      raise '模型库批量任务正在执行，请等待完成后再更新联动模型。' if @soft_model_batch_job
      return false if @updating
      log("开始极速更新：#{Array(initial_keys).join(', ')} force=#{force}")
      view_state = capture_active_view_state
      @updating = true
      begin_soft_heavy_interaction(:linked_model_update)
      begin
        state = load_state
        refresh_architecture_collab_entry!(state, Sketchup.active_model)
        removed_self = purge_host_self_link!(state)
        queue = Array(initial_keys).select { |key| DISCIPLINES.key?(key) }
        visited = {}
        messages = []
        messages << "已清理#{removed_self}个当前专业自引用实例" if removed_self.positive?
        success = true

        until queue.empty?
          key = queue.shift
          next if visited[key]
          visited[key] = true
          link = state['links'][key]
          unless link['enabled']
            messages << "#{link['name']}已断开，已跳过"
            next
          end
          if key == 'architecture' && architecture_remote_pending?(state)
            messages << '建筑有新版本，请在建筑卡片单独点击“更新”，可另存整份模型副本或直接更新'
            next
          end
          native_entity = native_edit_entity(key)
          if link['edit_session_active'] || (native_entity && !entity_native_locked?(native_entity))
            messages << "#{link['name']}正在 LinkHub 协同修改，已跳过更新"
            next
          end

          model_result = load_linked_model(key, state, force: force)
          if model_result[:deferred]
            messages << model_result[:message]
          elsif !model_result[:skipped]
            messages << model_result[:message]
            success &&= model_result[:ok]
          end

          discovered = apply_discovered_dependencies!(state, key, model_result[:dependencies] || [])
          messages.concat(discovered[:messages])
          discovered[:changed_keys].each { |changed_key| queue << changed_key unless visited[changed_key] }

          link['status'] = '未连接' if model_result[:no_source]
        end

        normalize_space_models_state!(state, Sketchup.active_model)
        if Array(state['space_models']).any? { |item| !item['legacy_key'].to_s.empty? }
          safe_model_operation(Sketchup.active_model, '迁移软装＋硬装空间模型', internal_sync: true) do
            adopt_legacy_space_entities!(state, Sketchup.active_model)
          end
        end
        visited.keys.each { |visited_key| reapply_professional_visibility!(visited_key, state, Sketchup.active_model) }
        save_state(state)
        relock_managed_entities
        refresh_dialog
        compact_messages = messages.compact.reject(&:empty?).uniq
        if notify
          if compact_messages.empty?
            show_status('源文件没有变化，无需重载。', 'success')
          else
            show_status(compact_messages.join('；'), success ? 'success' : 'error')
          end
        end
        success
      ensure
        restore_active_view_state(view_state)
        @updating = false
        end_soft_heavy_interaction(:linked_model_update)
      end
    end

    def update_link(key, notify: true, force: false)
      if key.to_s == 'architecture'
        state = load_state
        refresh_architecture_collab_entry!(state, Sketchup.active_model)
        if !state.dig('links', 'architecture', 'collab_full_path').to_s.empty?
          return update_architecture_safely(notify: notify, force: force)
        end
      end
      update_links([key], notify: notify, force: force)
    end

    # v0.6.43：提交失败自动退出待确认；提交确认期间提供取消提交。
    # 先重新载入共享缓存，再把外层联动实例恢复到绝对世界原位。
    def refresh_and_reset_link(key)
      update_link(key, notify: false, force: true)
      lock_current_link_position(key)
    rescue StandardError => e
      log_exception("刷新并重置#{key}失败", e)
      raise e
    end

    def lock_current_link_position(key)
      state = load_state
      link = state['links'][key]
      raise '专业不存在。' unless link
      instance = managed_model_instance_for(key)
      raise '该专业模型尚未载入，无法重置绝对原位。' unless instance && instance.valid?
      source = auto_relocate(link['model_path'].to_s)
      raise "找不到源模型：#{source}" unless File.file?(source)

      unless world_wrapper_instance?(instance)
        result = load_linked_model(key, state, force: true)
        raise result[:message].to_s unless result[:ok]
        instance = managed_model_instance_for(key)
      end
      raise '绝对世界封装建立失败。' unless world_wrapper_instance?(instance)

      world_info = absolute_world_frame_for_asset({ type: link['last_asset_type'].to_s }, source, link)
      child = world_source_child(instance)
      child.transformation = world_info[:transformation] if child && child.valid?
      instance.transformation = identity_transformation
      link['last_source_axes'] = world_info[:axes]
      link['last_instance_transform'] = identity_transformation_array
      link['absolute_world_enabled'] = true
      link['world_wrapper_schema'] = WORLD_WRAPPER_SCHEMA
      link['last_world_frame_source'] = world_info[:source]
      link['status'] = '已重置为绝对世界原位'
      save_state(state, Sketchup.active_model, write_manifest: false)
      refresh_dialog
      show_status("#{link['name']}已重置到绝对世界原位。外层联动实例固定为世界坐标单位矩阵，源模型轴点只在内部换算，不再累计偏移。", 'success')
      true
    end

    def save_link_performance_settings(key, strategy, prefer_package, ignore_sections, filter_enabled, tags_json)
      state = load_state
      link = state['links'][key]
      raise '专业不存在。' unless link
      parsed_tags = begin
        Array(JSON.parse(tags_json.to_s)).map(&:to_s).map(&:strip).reject(&:empty?).uniq
      rescue JSON::ParserError
        []
      end
      strategy_value = %w[direct mirror].include?(strategy.to_s) ? strategy.to_s : 'direct'
      filter_value = filter_enabled == true || filter_enabled.to_s == 'true'
      raise '开启“仅显示标记”时至少选择一个标记。' if filter_value && parsed_tags.empty?
      link['sync_strategy'] = strategy_value
      link['prefer_reference_package'] = prefer_package == true || prefer_package.to_s == 'true'
      link['ignore_section_planes'] = ignore_sections == true || ignore_sections.to_s == 'true'
      link['display_filter_enabled'] = filter_value
      link['display_selected_tags'] = parsed_tags
      link['status'] = '联动设置已保存 · 请点击更新'
      save_state(state, Sketchup.active_model, write_manifest: false)
      refresh_dialog
      show_status('联动设置已保存。下次更新会按新策略重载。', 'success')
      true
    rescue StandardError => e
      log_exception('保存联动性能设置失败', e)
      show_status("保存联动设置失败：#{e.message}", 'error')
      false
    end

    # -------------------------
    # Manual synchronization only
    # -------------------------

    # v0.6.7 起彻底取消实时更新和轮询计时器。保留这个空方法仅用于
    # 兼容旧调用点，确保旧项目升级后不会启动任何后台重载。
    def refresh_timer_state
      false
    end

    def start_timer
      false
    end

    def stop_timer
      false
    end

    def check_auto_updates
      false
    end

    def dependency_candidates_for(state, target_key)
      target = state['links'][target_key]
      candidates = []
      seen = {}
      state['links'].each do |origin_key, origin_link|
        next if origin_key == target_key
        Array(origin_link['embedded_dependencies']).each do |item|
          next unless item.is_a?(Hash)
          next unless item['discipline'].to_s == target_key
          next if host_discipline_for(state) == target_key
          next if dependency_block_reason(state, origin_key, item)
          kind = item['kind'].to_s
          next unless kind == 'model'
          resolved = item['resolved_path'].to_s
          next if resolved.empty?
          next unless File.file?(resolved)

          already_used = same_file_path?(auto_relocate(target['model_path'].to_s), resolved)
          next if already_used

          identity = [kind, FastPath.expand(resolved).downcase]
          next if seen[identity]
          seen[identity] = true
          candidates << {
            'kind' => kind,
            'resolved_path' => resolved,
            'name' => File.basename(resolved),
            'origin_key' => origin_key,
            'origin_name' => origin_link['name'],
            'reason' => kind == 'model' && !target['model_path'].to_s.empty? ? '与现有模型链接不同' : '可补全'
          }
        end
      end
      candidates
    end

    def accept_dependency(target_key, kind, resolved_path)
      return unless DISCIPLINES.key?(target_key)
      path = resolved_path.to_s
      unless File.file?(path)
        show_status("候选文件不存在：#{path}", 'error')
        return
      end

      state = load_state
      if host_discipline_for(state) == target_key || self_reference_path?(path)
        show_status('已阻止当前工作专业或当前文件形成自引用。', 'error')
        return
      end
      if source_used_by_other_discipline?(state, target_key, path)
        show_status('同一源模型已经分配给其他专业，不能重复采用。', 'error')
        return
      end
      link = state['links'][target_key]
      raise '只支持采用 SketchUp 模型来源。' unless kind.to_s == 'model'
      previous_path = auto_relocate(link['model_path'].to_s)
      same_source = !previous_path.to_s.empty? && same_file_path?(previous_path, path)
      link['model_path'] = store_path(path)
      clear_model_caches!(link)
      link['last_source_axes'] = [] unless same_source
      link['coordinate_tracking_requested'] = request_coordinate_tracking(path) || coordinate_tracking_requested?(path)
      link['auto_update'] = false
      link['status'] = '已采用关联来源 · 请点击更新'
      save_state(state)
      refresh_dialog
      show_status('已采用关联来源，请手动点击“更新”。', 'success')
    end

    # -------------------------
    # Structured health/status model
    # -------------------------

    def stored_signature_for(link, stored_path)
      signature = link.fetch('last_signatures', {})[stored_path].to_s
      return signature unless signature.empty?

      mtime = link.fetch('last_mtimes', {})[stored_path].to_f
      size = link.fetch('last_sizes', {})[stored_path].to_i
      return '' if mtime <= 0 || size <= 0

      "#{mtime}|#{size}"
    rescue StandardError
      ''
    end

    def file_pending_for_link?(link, stored_path, resolved_path)
      return false if stored_path.to_s.empty? || resolved_path.to_s.empty?
      return false unless File.file?(resolved_path)

      current = watched_signature(resolved_path)
      saved = stored_signature_for(link, stored_path)
      saved.empty? || current != saved
    rescue StandardError
      false
    end

    def structured_link_status(link, model_path:, model_exists:, loaded:)
      raw = link['status'].to_s
      model_connected = !link['model_path'].to_s.empty?

      unless link['enabled']
        return {
          'status_code' => 'disabled',
          'status_label' => '已断开',
          'status_detail' => '该专业已断开；当前模型中不会保留参考实例，也不会参与更新或显示切换'
        }
      end

      # Hard errors always win. A missing source must never look merely "pending".
      if (model_connected && !model_exists) || raw.match?(/失败|报错|损坏|无法载入|无法读取/)
        reasons = []
        reasons << '模型源文件丢失' if model_connected && !model_exists
        reasons << raw if reasons.empty? && !raw.empty?
        return {
          'status_code' => 'error',
          'status_label' => '异常',
          'status_detail' => reasons.join(' · ')
        }
      end

      if link['is_host_discipline'] && !link['managed_collaboration_available']
        return {
          'status_code' => 'current',
          'status_label' => '当前专业',
          'status_detail' => '本文件原生内容；不会把当前 SKP 或当前专业重新连接回自身'
        }
      end

      if link['preview_conflict']
        return {
          'status_code' => 'error',
          'status_label' => '提交冲突',
          'status_detail' => link['preview_conflict_detail'].to_s.empty? ? '本地修改仍保留，尚未写入源 SKP' : link['preview_conflict_detail'].to_s
        }
      end

      discipline_key = link['discipline'].to_s
      managed_discipline = %w[architecture landscape].include?(discipline_key) && link['managed_collaboration_available']
      if %w[architecture landscape].include?(discipline_key) && managed_discipline_background_publish_active?(discipline_key)
        job = background_publish_job_snapshot("discipline:#{discipline_key}")
        return {
          'status_code' => 'waiting',
          'status_label' => "发布 #{job['progress'].to_i}%",
          'status_detail' => "#{job['stage_label']} · 已进入统一后台发布队列；其它模型可继续操作"
        }
      end
      if managed_discipline && link['source_locked_by_other']
        owner = link['source_lock_owner'].to_s
        host = link['source_lock_host'].to_s
        who = [owner, host].reject(&:empty?).join('@')
        return {
          'status_code' => 'locked',
          'status_label' => owner.empty? ? '他人修改中' : "#{owner}修改中",
          'status_detail' => who.empty? ? "#{link['name']}已被其他成员占用；仍可读取上一发布版" : "#{who} 正在修改#{link['name']}；仍可读取上一发布版"
        }
      end

      if managed_discipline && link['source_lock_self_recoverable']
        return {
          'status_code' => 'waiting',
          'status_label' => '本人遗留占用',
          'status_detail' => "#{link['source_lock_owner'].to_s.empty? ? current_user_name : link['source_lock_owner']} 的上次编辑状态仍在；点击恢复或发布会自动中断旧会话并由当前会话接管"
        }
      end

      interrupted_managed_edit = managed_discipline && !link['source_lock_owned'] &&
                                      (link['preview_edit_active'] || link['preview_pending_publish'] || link['edit_session_active'])
      if interrupted_managed_edit
        return {
          'status_code' => 'waiting',
          'status_label' => '修改中断',
          'status_detail' => '上次 SketchUp 进程已结束；本地未发布内容仍保留，点击“恢复”重新取得占用'
        }
      end

      if link['edit_safe_paused']
        return {
          'status_code' => 'waiting',
          'status_label' => '未发布修改已暂存',
          'status_detail' => "#{link['name']}根组件已安全锁定，协作占用和本地修改仍保留；点击“继续”恢复编辑"
        }
      end

      if link['preview_edit_active']
        if managed_discipline
          inside = link['managed_edit_context_inside'] == true
          return {
            'status_code' => 'editing',
            'status_label' => '我在修改',
            'status_detail' => inside ?
              "#{link['name']}组件内修改中；ESC 可退出到全模，点击 LinkHub 发布后提交" :
              "已退出到全模；#{link['name']}仍解锁并由你占用，双击可继续，点击 LinkHub 发布后提交"
          }
        end
        return {
          'status_code' => 'editing',
          'status_label' => '临时编辑中',
          'status_detail' => '原生锁定/解锁不参与协同提交；请使用 LinkHub“修改 / 发布 / 取消修改”流程'
        }
      end

      if link['preview_pending_publish']
        if managed_discipline
          return {
            'status_code' => 'pending',
            'status_label' => '待发布',
            'status_detail' => "本地#{link['name']}修改已保留，协作占用仍由你持有；可继续修改或发布"
          }
        end
        return {
          'status_code' => 'pending',
          'status_label' => '本地待提交',
          'status_detail' => link['last_commit_result'].to_s == 'error' ? "上次提交失败：#{link['preview_conflict_detail']}" : '已选择提交，可确认写回当前连接的源 SKP'
        }
      end

      if link['edit_session_active']
        return {
          'status_code' => 'editing',
          'status_label' => '正在提交',
          'status_detail' => raw.empty? ? '正在检查占用并写入当前连接的源 SKP' : raw
        }
      end

      if link['source_locked_by_other']
        owner = link['source_lock_owner'].to_s
        host = link['source_lock_host'].to_s
        who = [owner, host].reject(&:empty?).join('@')
        return {
          'status_code' => 'locked',
          'status_label' => owner.empty? ? '他人修改中' : "#{owner}修改中",
          'status_detail' => who.empty? ? '源模型已被其他成员签出' : "#{who} 正在编辑源模型"
        }
      end

      if raw.match?(/正在|载入中|同步中|更新中/)
        return {
          'status_code' => 'syncing',
          'status_label' => '同步中',
          'status_detail' => raw
        }
      end

      if raw.match?(/等待安全同步|稍后再点|刚刚发生写入/)
        return {
          'status_code' => 'waiting',
          'status_label' => '等待同步',
          'status_detail' => raw
        }
      end

      unless model_connected
        return {
          'status_code' => 'disconnected',
          'status_label' => '未连接',
          'status_detail' => '尚未连接模型文件'
        }
      end

      pending_reasons = []
      if model_connected && model_exists
        pending_reasons << '模型尚未载入' unless loaded
        managed = %w[architecture landscape].include?(link['discipline'].to_s) && link['managed_collaboration_available']
        if managed
          pending_reasons << '检测到协同清单新版本' if link['remote_update_required'] == true
        else
          pending_reasons << '检测到模型新版本' if file_pending_for_link?(link, link['model_path'], model_path)
        end
      end
      pending_reasons << '联动设置已修改' if raw.match?(/请点击更新|下次更新生效|设置已保存|已连接/)

      unless pending_reasons.empty?
        if link['managed_collaboration_available']
          author = architecture_publish_author(link)
          at = link['collab_last_publish_at'].to_s
          source_note = at.empty? ? author : "#{author} · #{at}"
          return {
            'status_code' => 'pending',
            'status_label' => '有更新',
            'status_detail' => link['discipline'].to_s == 'architecture' ? "#{source_note} 提交了建筑新版本 · 可另存整份 SU 副本或直接更新" : "#{source_note} 提交了#{link['name']}新版本 · 请更新后继续修改"
          }
        end
        return {
          'status_code' => 'pending',
          'status_label' => '待更新',
          'status_detail' => pending_reasons.uniq.join(' · ')
        }
      end

      if link['last_commit_result'].to_s == 'success' && link['last_commit_verified']
        if link['managed_collaboration_available']
          return {
            'status_code' => 'current',
            'status_label' => '已是最新',
            'status_detail' => link['native_last_publish_at'].to_s.empty? ? "#{link['name']}修改已发布到共享最新版" : "#{link['name']}修改已发布 · #{link['native_last_publish_at']}"
          }
        end
        return {
          'status_code' => 'current',
          'status_label' => '提交成功',
          'status_detail' => raw.empty? ? '修改已经写入当前连接的源 SKP' : raw
        }
      end

      {
        'status_code' => 'current',
        'status_label' => '已是最新',
        'status_detail' => raw.empty? ? '已与源文件保持一致' : raw
      }
    rescue StandardError => e
      log_exception('计算联动状态失败', e)
      {
        'status_code' => 'error',
        'status_label' => '状态检查失败',
        'status_detail' => e.message.to_s
      }
    end

    def public_state
      state = load_state
      state['plugin_version'] = EXTENSION_VERSION
      state['runtime_generation'] = @runtime_generation.to_i
      state['runtime_session_id'] = current_runtime_session_id
      state['runtime_timer_count'] = runtime_timer_registry.length
      state['hot_reload_supported'] = true
      state['bootstrap_api'] = GavinTools::SULinkHubMultiSpace::BOOTSTRAP_API
      state['status_overlay_enabled'] = !!@status_overlay_enabled
      model = Sketchup.active_model
      state['model_saved'] = !model.path.to_s.empty?
      state['realtime_update_enabled'] = false
      state['tag_folders_supported'] = tag_folders_supported?(model)
      state['sync_mode'] = 'manual_only'
      state['host_discipline'] = host_discipline_for(state)
      onboarding = collaboration_connection_info(state, model)
      state['onboarding_stage'] = onboarding['stage'].to_s
      state['onboarding_message'] = onboarding['message'].to_s
      state['onboarding_error'] = onboarding['error'].to_s
      state['workspace_configured'] = onboarding['workspace_configured'] == true
      collab_dir = onboarding['project_dir'].to_s
      collab_json = onboarding['json_path'].to_s
      state['collab_project_dir_resolved'] = collab_dir
      state['collab_project_json_resolved'] = collab_json
      state['collab_project_exists'] = onboarding['valid'] == true
      # 未完成连接和工作区选择时保持纯只读、轻量状态，不扫描模型或协同缓存。
      return state unless onboarding['stage'] == 'ready'
      backup_dir = architecture_backup_directory
      state['architecture_backup_dir'] = backup_dir
      state['architecture_backup_dir_exists'] = !backup_dir.empty? && Dir.exist?(backup_dir)

      # 只读刷新提交人、版本与共享 FULL 路径；不在面板轮询中写模型或改“已读签名”。
      if state['collab_project_exists']
        refresh_architecture_collab_entry!(state, model)
        refresh_landscape_collab_entry!(state, model)
        sync_space_models_from_manifest!(state, model)
      end
      architecture_link = state.dig('links', 'architecture') || {}
      last_backup_time = architecture_last_backup_time(architecture_link, model)
      last_backup_path = architecture_last_backup_path(architecture_link, model)
      state['architecture_backup_interval_minutes'] = architecture_backup_interval_minutes
      state['architecture_backup_last_at'] = last_backup_time ? last_backup_time.strftime('%Y-%m-%d %H:%M:%S') : ''
      state['architecture_backup_last_path'] = last_backup_time ? last_backup_path : ''
      state['architecture_backup_prompt_due'] = architecture_backup_prompt_due?(architecture_link, model)
      state['architecture_backup_minutes_remaining'] = architecture_backup_minutes_remaining(architecture_link, model)
      architecture_pending = architecture_remote_pending?(state, model)
      landscape_pending = landscape_remote_pending?(state, model)

      selected_entities = model.selection.to_a
      state['links'].each do |key, link|
        link['is_host_discipline'] = state['host_discipline'] == key
        collaboration_available = %w[architecture landscape].include?(key.to_s) && !link['collab_full_path'].to_s.empty? && File.file?(resolve_path(link['collab_full_path'].to_s, model))
        managed_flag = key.to_s == 'architecture' ? link['architecture_collab_managed'] : link['landscape_collab_managed']
        managed_collaboration = collaboration_available && !!managed_flag && !!managed_model_instance_for(key, model)
        link['managed_collaboration_available'] = collaboration_available
        link['managed_collaboration'] = managed_collaboration
        link['architecture_collaboration_available'] = key == 'architecture' && collaboration_available
        link['architecture_managed_collaboration'] = key == 'architecture' && managed_collaboration
        link['architecture_update_required'] = key == 'architecture' && !!architecture_pending
        link['landscape_collaboration_available'] = key == 'landscape' && collaboration_available
        link['landscape_managed_collaboration'] = key == 'landscape' && managed_collaboration
        link['landscape_update_required'] = key == 'landscape' && !!landscape_pending
        link['remote_update_required'] = (key == 'architecture' && !!architecture_pending) || (key == 'landscape' && !!landscape_pending)
        link['architecture_publish_author'] = key == 'architecture' ? architecture_publish_author(link) : ''
        link['enabled'] = link.key?('enabled') ? !!link['enabled'] : true
        # 面板刷新只读取状态，不创建标签或文件夹，防止打开面板时修改模型。
        link['visible'] = !link['system_hidden'] && professional_visible?(key, model)
        link['visibility_repair_needed'] = professional_visibility_repair_needed?(key, link, model)
        link['visibility_mode'] = 'system_dual'
        # 界面刷新保持只读且可预测；文件重定位仅在连接/更新动作中执行。
        model_path = resolve_path(link['model_path'], model)
        link['model_exists'] = !link['model_path'].to_s.empty? && File.file?(model_path)
        link['model_resolved'] = model_path
        link['model_size_mb'] = if File.file?(model_path)
                                  (File.size(model_path).to_f / 1024.0 / 1024.0).round(1)
                                else
                                  0
                                end
        link['clean_ready'] = false
        link['proxy_ready'] = false
        link['proxy_selected_count'] = 0
        link['proxy_tag_count'] = 0
        link['proxy_missing_tags'] = []
        link['mode'] = 'full'
        link['sync_mode'] = link['sync_strategy'].to_s
        current_instance = managed_model_instance_for(key, model)
        link['loaded'] = !!current_instance
        begin
          current_display_path = current_instance ? current_instance.get_attribute(ENTITY_DICT, 'load_asset_path', '').to_s : ''
          current_display_path = link['collab_full_path'].to_s if current_display_path.empty?
          current_display_path = link['model_path'].to_s if current_display_path.empty?
          link['current_display_mode'] = 'material'
          link['current_display_path'] = current_display_path
          link['current_display_resolved'] = resolve_path(current_display_path, model) rescue current_display_path
        rescue StandardError
          link['current_display_mode'] = 'material'
          link['current_display_path'] = link['model_path'].to_s
          link['current_display_resolved'] = link['current_display_path']
        end
        link['highlighted'] = !!(current_instance && selected_entities.include?(current_instance))
        link['native_locked'] = current_instance ? entity_native_locked?(current_instance) : true
        link['native_editing'] = !!(current_instance && !entity_native_locked?(current_instance))
        if %w[architecture landscape].include?(key.to_s) && current_instance
          managed_source = managed_discipline_edit_source_entity(current_instance)
          inside_managed = active_path_inside_managed_discipline?(current_instance, managed_source, model)
          link['managed_edit_context_inside'] = inside_managed
          link['architecture_edit_context_inside'] = key.to_s == 'architecture' && inside_managed
          link['landscape_edit_context_inside'] = key.to_s == 'landscape' && inside_managed
        else
          link['managed_edit_context_inside'] = false
          link['architecture_edit_context_inside'] = false
          link['landscape_edit_context_inside'] = false
        end
        link['preview_edit_active'] = !!link['preview_edit_active'] || link['native_editing']
        link['preview_pending_publish'] = !!link['preview_pending_publish']
        link['preview_conflict'] = !!link['preview_conflict']
        link['local_commit_available'] = !!current_instance
        link['native_publish_ready'] = !link['native_publish_path'].to_s.empty? && File.file?(resolve_path(link['native_publish_path'].to_s, model))
        link['collab_manifest_exists'] = !link['collab_manifest_path'].to_s.empty? && File.file?(resolve_path(link['collab_manifest_path'].to_s, model))
        link['collab_full_exists'] = !link['collab_full_path'].to_s.empty? && File.file?(resolve_path(link['collab_full_path'].to_s, model))
        link['collab_connected'] = link['collab_manifest_exists'] && link['collab_full_exists']
        link['absolute_world_ready'] = !!(current_instance && world_wrapper_instance?(current_instance))
        link['display_selected_count'] = Array(link['display_selected_tags']).length
        link['display_tag_count'] = Array(link['display_tag_catalog']).length
        if File.file?(model_path)
          package = valid_reference_package(model_path)
          link['reference_package_ready'] = !!package
          link['reference_package_path'] = package ? package[:path] : reference_package_path_for(model_path)
          link['reference_package_size_mb'] = package ? (File.size(package[:path]).to_f / 1024.0 / 1024.0).round(1) : 0
          coordinate_meta = read_coordinate_metadata(model_path)
          link['coordinate_meta_ready'] = !!coordinate_meta
          link['coordinate_tracking_requested'] = coordinate_tracking_requested?(model_path) || !!link['coordinate_tracking_requested']
          lock_info = source_lock_info(model_path, link)
          link['source_lock_exists'] = lock_info['exists']
          link['source_lock_stale'] = lock_info['stale']
          link['source_lock_owned'] = lock_info['owned']
          link['source_lock_self_recoverable'] = !!lock_info['same_user_recoverable']
          link['source_locked_by_other'] = lock_info['exists'] && !lock_info['stale'] && !lock_info['owned'] && !lock_info['same_user_recoverable']
          link['source_lock_owner'] = lock_info['owner'].to_s
          link['source_lock_host'] = lock_info['host'].to_s
          link['source_lock_started_at'] = lock_info['started_at'].to_s
        else
          link['reference_package_ready'] = false
          link['reference_package_path'] = ''
          link['coordinate_meta_ready'] = false
          link['reference_package_size_mb'] = 0
          link['source_lock_exists'] = false
          link['source_lock_stale'] = false
          link['source_lock_owned'] = false
          link['source_lock_self_recoverable'] = false
          link['source_locked_by_other'] = false
          link['source_lock_owner'] = ''
          link['source_lock_host'] = ''
          link['source_lock_started_at'] = ''
        end
        link['dependency_candidates'] = dependency_candidates_for(state, key)
        link['embedded_link_count'] = Array(link['embedded_dependencies']).length if link['embedded_link_count'].to_i <= 0
        structured = structured_link_status(
          link,
          model_path: model_path,
          model_exists: link['model_exists'],
          loaded: link['loaded']
        )
        link.merge!(structured)
      end

      state['space_display_mode'] = %w[proxy full].include?(state['space_display_mode'].to_s) ? state['space_display_mode'].to_s : 'proxy'
      state['space_edit_display_mode'] = %w[proxy full].include?(state['space_edit_display_mode'].to_s) ? state['space_edit_display_mode'].to_s : ''
      state['space_effective_display_mode'] = displayed_space_display_mode(state, model)
      state['space_models'] = Array(state['space_models']).sort_by { |item| item['number'].to_i }.map do |item|
        # 面板状态刷新只检查确定路径，不为缺失文件递归扫描项目目录。
        # 后台发布期间共享目标会经历临时文件/rollback/原子替换，绝不能把这几十到几百毫秒
        # 的过渡态显示成“文件缺失/待更新”，更不能因此允许用户点击更新参与竞态。
        resolved = resolve_path(item['model_path'].to_s, model)
        entity = space_model_entity(item['id'], model)
        background_job = background_publish_job_snapshot(item['id'])
        background_active = background_publish_active_state?(item)
        file_snapshot = if background_active && entity && entity.valid?
                          { exists: true, signature: item['last_signature'].to_s, size_mb: 0.0 }
                        else
                          space_status_file_snapshot(resolved)
                        end
        exists = file_snapshot[:exists] == true
        actual_representation = entity && entity.valid? ? entity.get_attribute(ENTITY_DICT, 'space_representation', 'full').to_s : state['space_effective_display_mode'].to_s
        display_asset = { path: resolved }
        loaded = !!(entity && entity.valid?)
        inside_edit_context = loaded && active_path_inside_space?(entity, model)
        local_edit_flag = local_space_edit_session?(item, state, model)
        lock = space_lock_info(item, model, source_path: resolved)
        lock_active = lock['exists'] && !lock['stale']
        editing_by_self = lock_active && lock['owned'] && local_edit_flag
        recoverable_self_lock = lock_active && !lock['owned'] && !!lock['same_user_recoverable']
        editing_by_other = lock_active && !lock['owned'] && !recoverable_self_lock
        stale_local_session = local_edit_flag && lock['stale']
        lock_lost = local_edit_flag && !editing_by_self && !editing_by_other && !recoverable_self_lock && !stale_local_session
        force_recovery = space_force_recovery_active?(item, state)
        publish_pending = editing_by_self && !!item['publish_pending'] && loaded && entity_native_locked?(entity)
        publish_remaining = 0
        file_signature = file_snapshot[:signature].to_s
        loaded_signature = loaded ? entity.get_attribute(ENTITY_DICT, 'source_file_signature', '').to_s : ''
        current_revision = space_authoritative_revision(item, resolved, actual_signature: file_signature)
        loaded_revision = loaded ? loaded_entity_source_revision(entity) : ''
        verified_schema = loaded ? entity.get_attribute(ENTITY_DICT, 'source_load_verified_schema', 0).to_i : 0
        update_direction = if background_active
                             :same
                           elsif !exists
                             :unknown
                           elsif !loaded
                             :newer
                           else
                             space_update_direction(
                               item, entity, resolved,
                               remote_signature: file_signature,
                               remote_mtime: (file_signature.split('|', 2).first.to_f rescue nil)
                             )
                           end
        revision_pending = background_active ? false : (!loaded || verified_schema < SPACE_LOAD_VERIFIED_SCHEMA || update_direction == :newer)
        if exists && revision_pending && !background_active
          schedule_space_mirror_prefetch(item, display_asset[:path], current_revision, model)
        end
        owner_name = lock['owner'].to_s.empty? ? '其他成员' : lock['owner'].to_s
        owner_place = [lock['owner'].to_s, lock['host'].to_s].reject(&:empty?).join('@')
        status_code, status_label, status_detail = if background_active
                                                    bg_status = background_job['status'].to_s
                                                    bg_progress = background_job['progress'].to_i
                                                    bg_stage = background_job['stage_label'].to_s
                                                    bg_stage = item['background_publish_state'].to_s == 'finishing' ? '远端发布完成 · 正在本地收尾' : '后台发布中' if bg_stage.empty?
                                                    bg_elapsed = background_job['stage_elapsed_seconds'].to_i
                                                    label = case bg_status
                                                            when 'queued' then '发布队列 · 5%'
                                                            when 'success' then '发布完成 · 96% · 收尾'
                                                            else "发布 #{bg_progress}%"
                                                            end
                                                    detail = "#{bg_stage}#{bg_elapsed.positive? ? " · 本阶段#{bg_elapsed}s" : ''}；当前空间暂时锁定，其他空间可正常继续工作"
                                                    ['waiting', label, detail]
                                                  elsif initial_space_publish_pending?(item)
                                                    initial_error = item['initial_publish_error'].to_s
                                                    label = initial_error.empty? ? '首次发布待完成' : '首次发布失败 · 可重试'
                                                    detail = initial_error.empty? ? '本地空间已创建；正式共享 SKP 尚未完成。点击发布可重新加入后台队列。' : "本地空间和发布候选均保留；点击重试不会覆盖已存在的共享文件。#{initial_error}"
                                                    ['waiting', label, detail]
                                                  elsif force_recovery
                                                    ['waiting', '强制解锁 · 仅恢复', '本地历史取物模式：不取得协作占用、禁止发布；退出空间或再次点击强制解锁会恢复进入前快照']
                                                  elsif !exists
                                                    ['error', '文件缺失', '共享空间 SKP 不存在，请检查协同文件夹']
                                                  elsif recoverable_self_lock
                                                    ['waiting', '本人遗留占用', "#{owner_name} 的上次编辑状态仍在；点击修改或发布会自动中断旧会话并由当前会话接管"]
                                                  elsif editing_by_other
                                                    ['editing', "修改中 · #{owner_name}", "#{owner_place} 从 #{lock['started_at']} 开始修改；仍可点击更新载入其修改前的上一发布版，不会中断对方"]
                                                  elsif item['edit_safe_paused'] && editing_by_self
                                                    ['waiting', '未发布修改已暂存', '空间根组件已安全锁定，协作占用与本地修改仍保留；点击“继续”恢复编辑']
                                                  elsif publish_pending
                                                    ['editing', '待发布', '空间已锁定；可立即发布，暂不发布则保留本地修改与空间占用']
                                                  elsif editing_by_self
                                                    if inside_edit_context
                                                      ['editing', '修改中 · 我', item['edit_references_visible'] ? '空间内修改中；其他参考已显示，ESC 可退出到全模' : '空间内修改中；ESC 可退出到全模，发布只能使用 LinkHub 按钮']
                                                    else
                                                      ['editing', '修改中 · 我', '已退出到全模；空间仍由你占用，双击或点击“进入”可继续，发布只能使用 LinkHub 按钮']
                                                    end
                                                  elsif stale_local_session
                                                    ['waiting', '修改中断', '上次 SketchUp 会话已经结束；过期占用正在自动回收。可点击“修改”恢复，或点击“更新”放弃本地未发布内容并载入上一发布版']
                                                  elsif lock_lost
                                                    ['error', '修改锁失效', '当前空间处于本地解锁状态，但协同占用已丢失；请更新放弃修改后重试']
                                                  elsif !loaded
                                                    ['pending', '待载入', '点击“更新”载入该空间模型']
                                                  elsif update_direction == :older
                                                    ['error', '共享版本更旧', '共享目录版本早于当前已载入模型，已阻止降级；请检查旧客户端写回或从历史恢复']
                                                  elsif update_direction == :unknown
                                                    ['waiting', '版本待核对', '共享文件与清单的先后关系无法确认；为避免旧模型覆盖新模型，请由发布者用当前插件重新发布']
                                                  elsif verified_schema < SPACE_LOAD_VERIFIED_SCHEMA
                                                    ['pending', '待验证更新', '当前空间由旧版插件载入，尚未通过定义隔离与包快照验证；请更新一次']
                                                  elsif revision_pending
                                                    ['pending', '待更新', editing_by_other ? '对方正在修改；仍可载入其修改前的上一发布版，不会中断对方' : '空间模型.json 已发布新版本；本地镜像不会作为版本依据']
                                                  else
                                                    ['current', '已更新', item['status'].to_s.empty? ? '已按绝对世界轴载入并通过包快照验证' : item['status'].to_s]
                                                  end
        item.merge(
          'display_filename' => "#{item['number']}:#{item['name']}.skp",
          'model_resolved' => resolved,
          'model_exists' => exists,
          'display_representation' => actual_representation == 'proxy' ? 'proxy' : 'full',
          'model_size_mb' => file_snapshot[:size_mb].to_f,
          'loaded' => loaded,
          'locked' => loaded ? entity_native_locked?(entity) : true,
          'editing' => editing_by_self || editing_by_other || recoverable_self_lock || background_active,
          'editing_by_self' => editing_by_self,
          'background_publish_active' => background_active,
          'background_publish_status' => background_job['status'].to_s,
          'background_publish_stage' => background_job['stage_label'].to_s,
          'background_publish_progress' => background_job['progress'].to_i,
          'initial_publish_pending' => initial_space_publish_pending?(item),
          'initial_publish_error' => item['initial_publish_error'].to_s,
          'editing_by_other' => editing_by_other,
          # “回收遗留占用”必须严格按锁文件 owner 与当前插件用户匹配；不能只因同电脑
          # 或旧锁 owner 缺失就显示，避免误解除其他成员的真实占用。
          'edit_same_user' => lock_active && !lock['owner'].to_s.empty? &&
                              normalize_lock_identity(lock['owner']) == normalize_lock_identity(current_user_name),
          'edit_self_recoverable' => recoverable_self_lock,
          'edit_context_inside' => inside_edit_context,
          'edit_safe_paused' => !!item['edit_safe_paused'],
          'force_recovery_active' => force_recovery,
          'edit_lock_lost' => lock_lost,
          'edit_owner' => lock['owner'].to_s,
          'edit_host' => lock['host'].to_s,
          'edit_started_at' => lock['started_at'].to_s,
          'references_visible_during_edit' => !!item['edit_references_visible'],
          'publish_pending' => publish_pending,
          'publish_remaining' => publish_remaining,
          'hidden' => loaded && entity.respond_to?(:hidden?) ? entity.hidden? : false,
          'selected' => loaded && selected_entities.include?(entity),
          'status_code' => status_code,
          'status_label' => status_label,
          'status_detail' => status_detail
        )
      end
      active_collection_for_status = space_workspace_role?(host_discipline_for(state)) ? host_discipline_for(state) : SPACE_COLLECTION_KEY
      loaded_spaces = spaces_for_collection(state, active_collection_for_status).select { |item| item['loaded'] }
      state['space_collection_loaded_count'] = loaded_spaces.length
      state['space_collection_visible_count'] = loaded_spaces.count { |item| !item['hidden'] }
      state['space_proxy_available_count'] = 0
      # 面板眼睛跟随当前硬装/软装工作区真实状态；两边不再共用一个总显隐。
      state['space_collection_hidden_active'] = space_collection_hidden_active?(state, model, active_collection_for_status)
      state['space_collection_editing'] = spaces_for_collection(state, active_collection_for_status).any? { |item| item['editing_by_self'] }
      state['space_collection_name'] = space_collection_label(active_collection_for_status)
      state['space_models_manifest_resolved'] = space_models_manifest_path(state, model)
      designer_space = spaces_for_collection(state, SOFT_SPACE_COLLECTION_KEY).find { |space| space['editing_by_self'] && space['edit_context_inside'] }
      state['soft_designer_available'] = !!designer_space
      state['soft_designer_space_id'] = designer_space ? designer_space['id'].to_s : ''
      state['soft_designer_space_name'] = designer_space ? "#{designer_space['number']}:#{designer_space['name']}" : ''
      state
    end

    def status_overlay_supported?
      false
    end

    def status_overlay_enabled?
      false
    end

    def overlay_record_for(model = Sketchup.active_model)
      @status_overlay_records ||= {}
      @status_overlay_records[model.object_id]
    rescue StandardError
      nil
    end

    def remove_overlay_from_manager(model, overlay)
      return false unless model && overlay
      begin
        overlay.deactivate! if overlay.respond_to?(:deactivate!)
        overlay.enabled = false if overlay.respond_to?(:enabled=)
      rescue StandardError
        nil
      end
      begin
        manager = model.overlays
        manager.remove(overlay) if manager && manager.respond_to?(:remove)
      rescue StandardError
        nil
      end
      true
    end

    def remove_duplicate_status_overlays(model)
      return false unless model && model.respond_to?(:overlays)
      manager = model.overlays
      return false unless manager.respond_to?(:each)
      duplicates = []
      manager.each do |overlay|
        next unless overlay.respond_to?(:id)
        duplicates << overlay if overlay.id.to_s == HUD_OVERLAY_ID
      end
      duplicates.each { |overlay| remove_overlay_from_manager(model, overlay) }
      true
    rescue StandardError => e
      log_exception('清理旧视口状态卡失败', e)
      false
    end

    def ensure_status_overlay_for_model(model = Sketchup.active_model)
      return nil unless @status_overlay_enabled
      return nil unless model && model.respond_to?(:overlays)
      return nil unless defined?(ViewportStatusOverlay)
      @status_overlay_records ||= {}
      key = model.object_id
      record = @status_overlay_records[key]
      if record && record[:overlay]
        overlay = record[:overlay]
        begin
          overlay.activate! if overlay.respond_to?(:activate!)
          overlay.enabled = true if overlay.respond_to?(:enabled=)
          return overlay
        rescue StandardError
          @status_overlay_records.delete(key)
        end
      end

      remove_duplicate_status_overlays(model)
      overlay = ViewportStatusOverlay.new(model)
      model.overlays.add(overlay)
      overlay.enabled = true if overlay.respond_to?(:enabled=)
      overlay.activate! if overlay.respond_to?(:activate!)
      @status_overlay_records[key] = { model: model, overlay: overlay }
      overlay
    rescue StandardError => e
      log_exception('创建视口状态卡失败', e)
      nil
    end

    def shutdown_status_overlays!
      records = @status_overlay_records || {}
      records.each_value do |record|
        next unless record.is_a?(Hash)
        remove_overlay_from_manager(record[:model], record[:overlay])
      end
      @status_overlay_records = {}
      true
    rescue StandardError => e
      log_exception('卸载视口状态卡失败', e)
      @status_overlay_records = {}
      false
    end

    def short_hud_status(link)
      code = link['status_code'].to_s
      label = link['status_label'].to_s
      return ['禁用', [112, 122, 138]] if code == 'disabled' || link['enabled'] == false
      host = !!link['is_host_discipline'] && !link['architecture_collaboration_available']
      case code
      when 'current'
        host ? ['本专业', [40, 132, 196]] : ['已更新', [35, 174, 102]]
      when 'pending'
        label.include?('提交') ? ['待提交', [230, 145, 38]] : ['待更新', [230, 145, 38]]
      when 'waiting'
        ['等待中', [230, 145, 38]]
      when 'error'
        ['异常', [222, 77, 77]]
      when 'editing'
        label.include?('提交') ? ['提交中', [67, 126, 235]] : ['编辑中', [135, 86, 214]]
      when 'locked'
        ['占用中', [135, 86, 214]]
      when 'syncing'
        ['更新中', [67, 126, 235]]
      when 'disconnected'
        ['待连接', [112, 122, 138]]
      else
        if label.include?('异常') || label.include?('失败')
          ['异常', [222, 77, 77]]
        elsif label.include?('待')
          ['待更新', [230, 145, 38]]
        elsif label.include?('当前专业')
          ['本专业', [40, 132, 196]]
        elsif label.include?('已') || label.include?('成功')
          ['已更新', [35, 174, 102]]
        else
          ['待连接', [112, 122, 138]]
        end
      end
    end

    def hud_items_from_state(state)
      links = state.is_a?(Hash) ? state['links'] : {}
      links ||= {}
      items = []
      %w[architecture].each do |key|
        link = links[key].is_a?(Hash) ? links[key] : {}
        label, color = short_hud_status(link)
        items << { 'key' => key, 'name' => DISCIPLINES[key]['name'], 'label' => label, 'color' => color }
      end
      SPACE_COLLECTION_KEYS.each do |collection_key|
        spaces = spaces_for_collection(state, collection_key)
        space_status = if spaces.empty?
                         { 'status_code' => 'disconnected', 'status_label' => '待新增' }
                       elsif spaces.any? { |item| item['status_code'].to_s == 'error' }
                         { 'status_code' => 'error', 'status_label' => '异常' }
                       elsif spaces.any? { |item| item['status_code'].to_s == 'editing' }
                         { 'status_code' => 'editing', 'status_label' => '编辑中' }
                       elsif spaces.any? { |item| %w[pending waiting].include?(item['status_code'].to_s) }
                         { 'status_code' => 'pending', 'status_label' => '待更新' }
                       else
                         { 'status_code' => 'current', 'status_label' => "#{spaces.length}个空间" }
                       end
        label, color = short_hud_status(space_status)
        items << { 'key' => collection_key, 'name' => space_collection_label(collection_key), 'label' => label, 'color' => color }
      end
      %w[landscape].each do |key|
        link = links[key].is_a?(Hash) ? links[key] : {}
        label, color = short_hud_status(link)
        items << { 'key' => key, 'name' => DISCIPLINES[key]['name'], 'label' => label, 'color' => color }
      end
      items
    end

    def refresh_status_overlay(state = nil, model = Sketchup.active_model)
      return false unless @status_overlay_enabled
      return false unless model == Sketchup.active_model
      overlay = ensure_status_overlay_for_model(model)
      return false unless overlay
      state ||= public_state
      overlay.update_items(hud_items_from_state(state))
      model.active_view.invalidate
      true
    rescue StandardError => e
      log_exception('刷新视口状态卡失败', e)
      false
    end

    def handle_active_model_for_status_card(model = Sketchup.active_model)
      @status_overlay_enabled = false
      Sketchup.write_default(HUD_PREF_SECTION, HUD_PREF_KEY, false)
      remove_duplicate_status_overlays(model)
      false
    rescue StandardError => e
      log_exception('清理已取消的视口状态卡失败', e)
      false
    end

    # 左侧抽屉是唯一工作入口，不依赖 HtmlDialog。
    # 新建、打开或切换模型后轻量恢复折叠把手；只有展开时才读取详细协同状态。
    def handle_active_model_for_workspace_toolbar(model = Sketchup.active_model)
      restore_workspace_locked_selection_colors!(except_model: model)
      unless linkhub_enabled?
        shutdown_workspace_toolbars! unless (@workspace_toolbar_records || {}).empty?
        return false
      end
      return false unless workspace_toolbar_supported?
      GavinTools::SULinkHubMultiSpace::Runtime.runtime_start_timer(0.05, false) do
        next unless model == Sketchup.active_model
        if workspace_ready?(nil, model)
          attach_workspace_toolbar_selection_observer(model)
          start_native_lock_monitor
          # 若上次在强制解锁恢复模式中保存/异常退出，启动后先恢复进入前快照，
          # 绝不让历史取物状态跨会话变成可发布状态。
          recover_interrupted_space_force_recovery!(model)
        end
        refresh_workspace_toolbar(model)
        schedule_persistent_library_warmup(model, delay: 0.65)
      end
      true
    rescue StandardError => e
      log_exception('切换模型时恢复快速抽屉失败', e)
      false
    end

    def set_status_overlay_enabled(_enabled)
      @status_overlay_enabled = false
      Sketchup.write_default(HUD_PREF_SECTION, HUD_PREF_KEY, false)
      shutdown_status_overlays!
      remove_duplicate_status_overlays(Sketchup.active_model)
      false
    rescue StandardError
      false
    end

    def show_status_overlay
      false
    end

    # 兼容从旧版本热重载后仍留在 SketchUp 工具栏中的第二个旧按钮。
    # v0.9.76 起该按钮的职责改为“重载插件”，完整重启后会显示新名称和提示。
    def toggle_status_overlay
      GavinTools::SULinkHubMultiSpace.schedule_runtime_reload!
      true
    rescue StandardError
      false
    end

    def save_active_model
      model = Sketchup.active_model
      if model.path.to_s.empty?
        suggested = model.title.to_s.strip
        suggested = '未命名模型' if suggested.empty?
        path = UI.savepanel('保存当前 SketchUp 模型', nil, "#{suggested}.skp")
        return false if path.nil? || path.to_s.empty?
        path = "#{path}.skp" unless File.extname(path).casecmp('.skp').zero?
        saved = model.save(path)
      else
        saved = model.save
      end
      raise 'SketchUp 未能保存当前模型。' if saved == false
      show_status("当前模型已保存：#{File.basename(model.path)}", 'success')
      refresh_dialog
      true
    rescue StandardError => e
      log_exception('保存当前模型失败', e)
      show_status("保存失败：#{e.message}", 'error')
      false
    end

    def dialog_file
      File.join(__dir__, 'ui', 'index.html')
    end

    def show_dialog
      # v0.10.9：主 HtmlDialog 已退出产品流程。所有管理、工作区切换、
      # 发布、更新与诊断统一从左侧抽屉完成，避免重复状态树和首次点击被吞。
      model = Sketchup.active_model
      overlay = ensure_workspace_toolbar_for_model(model)
      raise '当前 SketchUp 版本不支持 LinkHub 抽屉。' unless overlay
      overlay.expand_drawer!(pin: true) if overlay.respond_to?(:expand_drawer!)
      refresh_workspace_toolbar(model, detailed: true)
      show_status('SU LinkHub 已统一使用左侧抽屉面板。', 'info')
      true
    rescue StandardError => e
      log_exception('打开 LinkHub 抽屉失败', e)
      false
    end

    def pick_source_file(title, extensions)
      allowed = Array(extensions).map { |ext| ext.to_s.downcase }
      # 不向 Windows 原生窗口传入筛选字符串。少数 SketchUp 2024 环境
      # 在解析筛选字符串时会失去响应甚至退出，选择后再校验扩展名更稳妥。
      log("打开文件选择窗口：#{title}")
      path = UI.openpanel(title, nil, nil)
      return nil if path.nil? || path.to_s.empty?

      unless allowed.include?(File.extname(path).downcase)
        UI.messagebox("请选择以下类型的文件：#{allowed.join('、')}")
        return nil
      end
      log("已选择文件：#{path}")
      path
    rescue Exception => e # rubocop:disable Lint/RescueException
      log_exception('文件选择失败', e)
      UI.messagebox("SU LinkHub 无法打开文件选择窗口。\n#{e.class}: #{e.message}\n\n日志：#{LOG_PATH}")
      nil
    end

    def create_collab_project
      safe_callback('新建协同项目', onboarding: true) do
        state = load_state
        json_path = create_collab_project_interactive!(state, Sketchup.active_model)
        next if json_path.to_s.empty?
        refresh_workspace_toolbar(Sketchup.active_model, detailed: true)
        overlay = workspace_toolbar_overlay(Sketchup.active_model)
        overlay.open_workspace_picker! if overlay && overlay.respond_to?(:open_workspace_picker!)
        json_path
      end
    end

    def connect_existing_collab_project
      safe_callback('连接已有协同项目', onboarding: true) do
        path = pick_source_file("选择已有项目根目录下的 #{PROJECT_COLLAB_FILE}", ['.json'])
        next unless path && !path.to_s.empty?
        json_path = FastPath.expand(path)
        raise "所选位置没有 #{PROJECT_COLLAB_FILE}。新项目请点击“新建”。" unless File.file?(json_path)
        raise "这不是有效的 SU LinkHub #{PROJECT_COLLAB_FILE}。" unless project_collab_manifest_file?(json_path)

        state = load_state
        reset_workspace_selection!(state)
        applied = apply_collab_project_manifest!(state, json_path, allow_empty: true)
        normalize_space_models_state!(state, Sketchup.active_model)
        sync_space_models_from_manifest!(state, Sketchup.active_model)
        prepare_collab_project_structure!(state, File.dirname(json_path), Sketchup.active_model, create_if_missing: false)
        save_state(state)
        refresh_dialog
        names = applied.map { |item| DISCIPLINES[item]['name'] }.join('、')
        dir = selected_collab_project_dir_for_state(state)
        if applied.empty?
          show_status("已连接协同项目：#{dir}。当前还没有专业缓存，可开始新增空间或发布当前专业。", 'success')
        else
          show_status("项目协同已连接：#{names}；协同位置：#{dir}。", 'success')
        end
        refresh_workspace_toolbar(Sketchup.active_model, detailed: true)
        overlay = workspace_toolbar_overlay(Sketchup.active_model)
        overlay.open_workspace_picker! if overlay && overlay.respond_to?(:open_workspace_picker!)
      end
    end

    # 兼容旧面板与旧快捷入口。
    def choose_collab_project
      connect_existing_collab_project
    end

    def refresh_linkhub_status(model = Sketchup.active_model, notify: false)
      state = ensure_space_models_ready!(model)
      save_state(state, model, write_manifest: false)
      sync_native_preview_state(model)
      refresh_dialog
      refresh_workspace_toolbar(model, detailed: true)
      show_status('协同状态已检查。', 'success') if notify
      true
    end

    # 工作区标签切换时只读取模型属性与当前 SU 根实例，立即构造一份可绘制卡片。
    # 这里严禁检查共享文件、锁文件或重载组件；那些权威检查留给空闲后的详细刷新。
    def workspace_local_space_snapshot(state, role, model = Sketchup.active_model)
      return {} unless state.is_a?(Hash) && space_workspace_role?(role)
      collection_key = normalize_space_collection_key(role)
      collection_hidden = space_collection_hidden_for(state, collection_key)
      groups = Array(state['space_groups'])
      # 根索引只取一次；不能在每张卡片上重复验证/扫描模型根层。
      entities_by_id = managed_root_index(model)[:spaces_by_id] || {}
      rows = spaces_for_collection(state, collection_key).map do |space|
        entity = entities_by_id[space['id'].to_s]
        entity = nil unless entity && entity.valid?
        loaded = !!(entity && entity.valid?)
        linked = linked_space_record?(space)
        editing_self = if loaded
                         state_active = state['space_editing_id'].to_s == space['id'].to_s ||
                                        space['editing'] == true || space_edit_safe_paused?(space)
                         local_attribute = entity.get_attribute(ENTITY_DICT, 'editing', false) ||
                                           entity.get_attribute(ENTITY_DICT, 'safe_paused', false)
                         (state_active && !space['edit_lock_token'].to_s.empty?) ||
                           space_edit_safe_paused?(space) || local_attribute || !entity_native_locked?(entity)
                       else
                         false
                       end
        editing_any = editing_self || space['editing'] == true
        background = background_publish_active_state?(space)
        initial_pending = initial_space_publish_pending?(space)
        raw_status = space['status'].to_s
        error_state = raw_status.match?(/失败|异常|缺失|中断/)
        pending_state = !error_state && raw_status.match?(/待更新|请点击更新|有更新|待按需验证/)

        source = linked ? canonical_space_record(state, space) : nil
        source_name = source ? source['name'].to_s : space['linked_source_name'].to_s
        job = background ? background_publish_job_snapshot(space['id']) : {}
        status_code = if background
                        'waiting'
                      elsif editing_self
                        'editing'
                      elsif error_state
                        'error'
                      elsif initial_pending || pending_state || !loaded
                        'pending'
                      else
                        'current'
                      end
        display_status = if linked
                           source_name.empty? ? '联动来源已缺失' : "联动于（#{source_name}）"
                         elsif background
                           stage = job['stage_label'].to_s
                           stage = '发布队列处理中' if stage.empty?
                           "#{stage} #{job['progress'].to_i}%"
                         elsif editing_self
                           space['publish_pending'] ? '待发布' : '待发布 · 修改中'
                         elsif initial_pending
                           space['initial_publish_error'].to_s.empty? ? '待首次发布' : '首次发布失败 · 可重试'
                         elsif error_state
                           raw_status
                         elsif !loaded
                           '待载入'
                         elsif pending_state
                           '有更新'
                         else
                           # “后台发布完成 · 已锁定”是过程状态，专业切换不应先显示灰色，
                           # 随后又跳成“已更新”。已驻留且无待办时直接显示稳定终态。
                           '已更新'
                         end

        primary_action, primary_label, primary_tooltip = if linked
          if !loaded && source
            ["drawer_space_update:#{space['id']}", '载入', '载入来源空间并恢复这个联动放置']
          else
            ["drawer_space_disabled:#{space['id']}", '联动', source ? "内容联动于（#{source_name}）；请修改来源空间" : '联动来源已缺失，请刷新协同清单']
          end
        elsif background
          ["drawer_space_disabled:#{space['id']}", job['status'].to_s == 'queued' ? '队列' : '发布中', '当前空间正在后台发布；其他空间可正常操作']
        elsif initial_pending
          ["drawer_space_publish:#{space['id']}", space['initial_publish_error'].to_s.empty? ? '发布' : '重试', '首次共享发布尚未完成；本地空间已保留']
        elsif editing_self
          [space_edit_safe_paused?(space) ? "drawer_space_edit:#{space['id']}" : "drawer_space_publish:#{space['id']}", space_edit_safe_paused?(space) ? '继续' : '发布', '继续或发布当前空间修改']
        elsif !loaded
          ["drawer_space_update:#{space['id']}", '载入', '将这个空间载入当前工作 SU']
        elsif pending_state || error_state
          ["drawer_space_update:#{space['id']}", '更新', '从协同目录载入该空间当前发布版']
        else
          ["drawer_space_edit:#{space['id']}", '修改', '取得空间占用并自动进入组件']
        end

        group = groups.find { |candidate| candidate['id'].to_s == space['group_id'].to_s }
        visible = loaded && !entity.hidden? && !collection_hidden
        {
          'id' => space['id'].to_s,
          'number' => space['number'].to_i,
          'collection_key' => collection_key,
          'raw_name' => space['name'].to_s,
          'group_id' => space['group_id'].to_s,
          'group_order' => space['group_order'].to_i,
          'name' => group ? "#{group['name']} · #{space_ui_label(space)}" : space_ui_label(space),
          'status_code' => status_code,
          'status' => display_status,
          'last_update' => space['last_update'].to_s,
          'loaded' => loaded,
          'manage_selectable' => !editing_any && !background,
          'manage_can_rename' => !editing_any && !background && !initial_pending,
          'manage_can_delete' => !editing_any && !background,
          'manage_can_group' => !editing_any && !background && !initial_pending,
          'color' => linked ? [52, 137, 218] : (editing_self ? [205, 78, 82] : workspace_drawer_status_color(status_code)),
          'publish_warning' => editing_self,
          'linked_space' => linked,
          'linked_source_space_id' => space['linked_source_space_id'].to_s,
          'linked_source_name' => source_name,
          'action' => primary_action,
          'action_label' => primary_label,
          'tooltip' => primary_tooltip,
          'enabled' => !background && !primary_action.start_with?('drawer_space_disabled:'),
          'release_occupancy_action' => '',
          'resident_action' => loaded ? "drawer_space_unload:#{space['id']}" : '',
          'resident_tooltip' => loaded ? '卸载这个空间；点击后会再次确认。只影响当前工作 SU，不删除共享文件、不影响其他成员' : '',
          'resident_enabled' => !editing_self && !background && !initial_pending,
          'resident_loaded' => loaded,
          'visibility_action' => "drawer_space_visibility:#{space['id']}",
          'visibility_tooltip' => loaded ? (visible ? "隐藏这个#{space_collection_label(collection_key)}空间" : "显示这个#{space_collection_label(collection_key)}空间") : '该空间尚未载入',
          'visibility_enabled' => loaded && !background,
          'visible' => visible
        }
      end

      rows.concat(pending_linked_space_drawer_rows(state, collection_key, model))

      drawer_groups = groups.sort_by { |group| group['order'].to_i }.map do |group|
        members = rows.select { |space| space['group_id'].to_s == group['id'].to_s }
        loaded_members = members.select { |space| space['loaded'] == true }
        visibility = group_collection_visibility_state(group, collection_key)
        suspended = visibility['suspended'] == true
        visible_count = loaded_members.count { |space| space['visible'] == true }
        group.merge(
          'visibility_suspended' => suspended,
          'visibility_restore_ids' => Array(visibility['restore_ids']),
          'visible' => !suspended && visible_count.positive?,
          'visibility_enabled' => !loaded_members.empty?,
          'visible_count' => visible_count,
          'loaded_count' => loaded_members.length
        )
      end
      {
        'drawer_spaces' => rows,
        'drawer_groups' => drawer_groups,
        'drawer_space_loaded_count' => rows.count { |row| row['loaded'] == true },
        'drawer_space_hidden' => collection_hidden
      }
    rescue StandardError => e
      log_exception('构造工作区本地卡片快照失败', e)
      {}
    end

    # v0.13.6.29：已连接项目中的专业切换是 UI 导航，不应同步等待 NAS/锁/完整状态树。
    # 先立即更新本机工作区身份与 Overlay；自引用清理、详细状态核验延迟到真正空闲后。
    def set_host_discipline_value_fast(value, model = Sketchup.active_model, notify: true)
      state = load_state(model)
      role = value.to_s
      role = SOFT_SPACE_COLLECTION_KEY if role == 'furniture'
      raise '请选择建筑、硬装、软装或景观工作区。' unless WORKSPACE_ROLES.include?(role)
      return true if host_discipline_for(state) == role && state['workspace_configured'] == true
      project_known = !state['collab_project_json'].to_s.empty? || !state['collab_project_dir'].to_s.empty?
      return set_host_discipline_value(value, model, notify: notify) unless project_known && state['workspace_configured'] == true

      if @material_library_dialog && @material_library_dialog.visible? && @material_library_discipline.to_s != role
        @material_library_dialog.close
        @material_library_dialog = nil
        @material_library_discipline = ''
      end
      @architecture_library_dialog.close if role != 'architecture' && @architecture_library_dialog && @architecture_library_dialog.visible?
      @soft_designer_dialog.close if role != SOFT_SPACE_COLLECTION_KEY && @soft_designer_dialog && @soft_designer_dialog.visible?
      @landscape_library_dialog.close if role != 'landscape' && @landscape_library_dialog && @landscape_library_dialog.visible?

      state['host_discipline'] = role
      state['workspace_configured'] = true
      state['professional_section_collapsed'] = {} unless state['professional_section_collapsed'].is_a?(Hash)
      state['professional_section_collapsed']['architecture'] = role != 'architecture'
      state['professional_section_collapsed'][SPACE_COLLECTION_KEY] = role != SPACE_COLLECTION_KEY
      state['professional_section_collapsed'][SOFT_SPACE_COLLECTION_KEY] = role != SOFT_SPACE_COLLECTION_KEY
      # 工作区身份只属于当前工作 SKP，本次切换不写 NAS sidecar。
      save_state(state, model, write_manifest: false)
      overlay = workspace_toolbar_overlay(model)
      if overlay && overlay.respond_to?(:set_workspace_local!)
        local_snapshot = space_workspace_role?(role) ? workspace_local_space_snapshot(state, role, model) : nil
        overlay.set_workspace_local!(role, local_snapshot: local_snapshot)
      end
      overlay.close_workspace_picker! if overlay && overlay.respond_to?(:close_workspace_picker!)
      mark_workspace_toolbar_fast_interaction!(model, duration: 1.8)
      schedule_workspace_switch_finalize(role, model)
      if notify
        label = role == SPACE_COLLECTION_KEY ? '硬装' : (role == SOFT_SPACE_COLLECTION_KEY ? '软装' : DISCIPLINES.dig(role, 'name').to_s)
        show_status("已切换到#{label}工作区；详细协同状态将在空闲时刷新。", 'success')
      end
      true
    rescue StandardError => e
      log_exception('快速切换工作区失败', e)
      set_host_discipline_value(value, model, notify: notify)
    end

    def schedule_workspace_switch_finalize(role, model = Sketchup.active_model)
      @workspace_switch_finalize_token ||= {}
      key = model.object_id
      @workspace_switch_finalize_token[key] = @workspace_switch_finalize_token[key].to_i + 1
      token = @workspace_switch_finalize_token[key]
      runtime_start_timer(0.9, false, label: 'workspace:switch_finalize') do
        next unless model == Sketchup.active_model
        next unless @workspace_switch_finalize_token[key].to_i == token
        overlay = workspace_toolbar_overlay(model)
        has_snapshot = overlay && overlay.respond_to?(:workspace_snapshot_available?) && overlay.workspace_snapshot_available?(role)
        # 已访问过的专业直接复用完整本地快照。专业切换本身不再触发 NAS/锁/全项目扫描；
        # 后台 presence monitor / “全面检查”会自然刷新权威状态。
        if has_snapshot
          next unless background_work_idle?(model, min_idle: 0.8)
          fresh = load_state(model)
          next unless host_discipline_for(fresh) == role.to_s
          attach_coordinate_observer(model)
          start_native_lock_monitor
          start_space_presence_monitor
          next
        end

        # 第一次进入一个从未缓存过的专业，需要生成一次完整树，但必须等真正空闲；
        # 连续切标签/转动视图时不断后移，避免“点完标签 1 秒后又突然卡几秒”。
        unless background_work_idle?(model, min_idle: 2.8)
          schedule_workspace_switch_finalize(role, model)
          next
        end
        fresh = load_state(model)
        next unless host_discipline_for(fresh) == role.to_s
        removed = purge_host_self_link!(fresh, model)
        save_state(fresh, model, write_manifest: false) if removed.positive?
        invalidate_workspace_connection_cache!(model)
        attach_coordinate_observer(model)
        start_native_lock_monitor
        start_space_presence_monitor
        refresh_workspace_toolbar(model, detailed: true, state: fresh)
        # 工作区切换不再顺带刷新所有 HtmlDialog；打开的专业库/清单各自有自己的状态观察器。
      end
      true
    rescue StandardError => e
      log_exception('延迟完成工作区切换失败', e)
      false
    end

    def set_host_discipline_value(value, model = Sketchup.active_model, notify: true)
      state = load_state(model)
      connection = collaboration_connection_info(state, model)
      raise connection['message'].to_s unless connection['valid'] == true
      role = value.to_s
      role = SOFT_SPACE_COLLECTION_KEY if role == 'furniture'
      raise '请选择建筑、硬装、软装或景观工作区。' unless WORKSPACE_ROLES.include?(role)
      if @material_library_dialog && @material_library_dialog.visible? && @material_library_discipline.to_s != role
        @material_library_dialog.close
        @material_library_dialog = nil
        @material_library_discipline = ''
      end
      if role != 'architecture' && @architecture_library_dialog && @architecture_library_dialog.visible?
        @architecture_library_dialog.close
      end
      if role != SOFT_SPACE_COLLECTION_KEY && @soft_designer_dialog && @soft_designer_dialog.visible?
        @soft_designer_dialog.close
      end
      if role != 'landscape' && @landscape_library_dialog && @landscape_library_dialog.visible?
        @landscape_library_dialog.close
      end
      state['host_discipline'] = role
      state['workspace_configured'] = true
      state['professional_section_collapsed'] = {} unless state['professional_section_collapsed'].is_a?(Hash)
      # 工作区切换后，当前专业默认展开，另一专业默认收纳；用户仍可随后手动展开两边。
      state['professional_section_collapsed']['architecture'] = role != 'architecture'
      state['professional_section_collapsed'][SPACE_COLLECTION_KEY] = role != SPACE_COLLECTION_KEY
      state['professional_section_collapsed'][SOFT_SPACE_COLLECTION_KEY] = role != SOFT_SPACE_COLLECTION_KEY
      removed = purge_host_self_link!(state)
      save_state(state, model)
      invalidate_workspace_connection_cache!(model)
      if state['workspace_references_visible'] == false
        set_workspace_references_visible!(true, model, notify: false)
      end
      attach_coordinate_observer(model)
      start_native_lock_monitor
      start_space_presence_monitor
      refresh_dialog
      overlay = workspace_toolbar_overlay(model)
      overlay.close_workspace_picker! if overlay && overlay.respond_to?(:close_workspace_picker!)
      refresh_workspace_toolbar(model, detailed: true)
      if notify
        label = role == 'coordination' ? '协调总模' : DISCIPLINES[role]['name']
        label = '硬装' if role == SPACE_COLLECTION_KEY
        label = '软装' if role == SOFT_SPACE_COLLECTION_KEY
        suffix = removed.positive? ? "，并清理#{removed}个旧自引用实例" : ''
        remote_note = ''
        if %w[architecture landscape].include?(role)
          link = state.dig('links', role) || {}
          source = resolve_path(link['collab_full_path'].to_s.empty? ? link['model_path'].to_s : link['collab_full_path'].to_s, model)
          managed = discipline_managed_collaboration?(state, role, model)
          remote_note = "；协同中已有#{label}模型，请点击顶部下载按钮获取最新版本" if File.file?(source) && !managed
        end
        show_status("当前工作模型已设为#{label}#{suffix}#{remote_note}。", 'success')
      end
      true
    end

    def choose_host_discipline_from_drawer(model = Sketchup.active_model)
      state = load_state(model)
      connection = collaboration_connection_info(state, model)
      raise connection['message'].to_s unless connection['valid'] == true
      overlay = workspace_toolbar_overlay(model)
      raise 'LinkHub 抽屉不可用。' unless overlay && overlay.respond_to?(:open_workspace_picker!)
      overlay.expand_drawer!(pin: true) if overlay.respond_to?(:expand_drawer!)
      overlay.open_workspace_picker!
      refresh_workspace_toolbar(model, detailed: true, state: state)
      true
    end

    # v0.13.6.75：多数 LinkHub 操作完成后统一回到 SketchUp 原生选择工具。
    # 发布、编辑、替换、更新等动作结束后若仍残留临时工具，用户会看到白色鼠标并且下一次点选无效。
    # 放置、吸管、油漆桶属于明确的持续工具，必须保留，不在这里强制打断。
    def schedule_restore_default_select_tool(model = Sketchup.active_model, delay: 0.04, reason: '', rearm_workspace_candidate: false)
      return false unless model && model == Sketchup.active_model
      @restore_default_select_tokens ||= {}
      key = model.object_id
      token = SecureRandom.hex(5)
      @restore_default_select_tokens[key] = token
      runtime_start_timer(delay.to_f, false, label: 'tool:restore_native_select', key: "tool:restore_native_select:#{key}") do
        next unless @restore_default_select_tokens[key] == token
        next unless model == Sketchup.active_model
        next if @soft_placement_tool || @landscape_placement_tool || @library_pipette_tool
        begin
          # 先取消仍在排队的双击桥/ToolState 回调。普通操作短暂抑制重挂；家具
          # 退出后若仍选中受管家具，则在 SelectionTool 恢复后立刻重新武装，避免
          # “退出 -> 立即再双击”被原生 SketchUp 抢先打开六面代理 Definition。
          suppress_workspace_double_click_rearm!(
            model,
            seconds: (rearm_workspace_candidate ? 0.0 : WORKSPACE_DOUBLE_CLICK_REARM_SUPPRESS_SECONDS)
          )
          bridge = (@workspace_double_click_bridge_records || {})[key]
          if bridge.is_a?(Hash) && bridge[:tool]
            active_tool = model.tools.active_tool if model.respond_to?(:tools)
            model.tools.pop_tool if active_tool && active_tool.equal?(bridge[:tool])
          end
          click_record = (@workspace_toolbar_click_tools || {})[key]
          if click_record.is_a?(Hash) && click_record[:tool]
            active_tool = model.tools.active_tool if model.respond_to?(:tools)
            model.tools.pop_tool if active_tool && active_tool.equal?(click_record[:tool])
          end
          model.select_tool(nil)
          if rearm_workspace_candidate
            @workspace_double_click_rearm_suppress_until&.delete(key)
            @workspace_escape_suppress_until&.delete(key) if !model.active_path.nil?
            runtime_start_timer(0.015, false, label: 'tool:restore_native_select_rearm', key: "tool:restore_native_select_rearm:#{key}", model: model, active_model_only: true) do
              @workspace_double_click_rearm_suppress_until&.delete(key)
              arm_workspace_double_click_candidate(model)
            end
          end
          Sketchup.set_status_text('') if Sketchup.respond_to?(:set_status_text)
          if ENV['SULINK_TOOL_TRACE'].to_s == '1'
            suffix = reason.to_s.empty? ? '' : " · #{reason}"
            log("已恢复 SketchUp 默认选择工具#{suffix}")
          end
        rescue StandardError => e
          log_exception('恢复 SketchUp 默认选择工具失败', e)
        ensure
          @restore_default_select_tokens.delete(key) if @restore_default_select_tokens[key] == token
        end
      end
      true
    rescue StandardError => e
      log_exception('安排恢复 SketchUp 默认选择工具失败', e)
      false
    end

    def safe_callback_should_restore_select_tool?(context)
      text = context.to_s
      return false if text.match?(/放置|吸管|油漆桶|使用.*材质|启用.*材质/)
      true
    rescue StandardError
      true
    end

    def safe_callback(context, onboarding: false, guard: true)
      started = monotonic_time
      action_key = context.to_s
      callback_claimed = false
      callback_invoked = false
      @safe_callback_active ||= {}
      @safe_callback_active_started_at ||= {}
      @safe_callback_last_started ||= {}
      if guard
        if @safe_callback_active[action_key].to_i.positive?
          active_started = @safe_callback_active_started_at[action_key].to_f
          active_age = active_started.positive? ? started - active_started : Float::INFINITY
          if active_age > 2.5
            log("已清理通用回调残留门禁：#{action_key} / #{active_age.finite? ? active_age.round(2) : '旧运行代'}秒")
            @safe_callback_active.delete(action_key)
            @safe_callback_active_started_at.delete(action_key)
          else
            log("通用回调防重复：#{action_key} / #{active_age.round(2)}秒")
            show_status("#{action_key}正在处理中，请勿重复点击。", 'info')
            return nil
          end
        end
        previous = @safe_callback_last_started[action_key].to_f
        if previous.positive? && (started - previous) < RUNTIME_ACTION_DEBOUNCE_SECONDS
          log("通用回调冷却跳过：#{action_key} / #{((started - previous) * 1000.0).round}ms")
          return nil
        end
        @safe_callback_last_started[action_key] = started
        @safe_callback_active[action_key] = @safe_callback_active[action_key].to_i + 1
        @safe_callback_active_started_at[action_key] = started
        callback_claimed = true
      end
      callback_invoked = true
      note_runtime_interaction!(Sketchup.active_model)
      require_workspace_ready! unless onboarding
      yield
    rescue SyncDeferredError => e
      log_exception(context, e)
      show_status(e.message.to_s, 'error')
      nil
    rescue SourceFileBusyError => e
      log_exception(context, e)
      show_status(e.message.to_s.lines.first.to_s.strip, 'error')
      UI.messagebox("SU LinkHub 已阻止本次操作。\n\n#{e.message}")
      nil
    rescue Exception => e # rubocop:disable Lint/RescueException
      log_exception(context, e)
      show_status("操作失败：#{e.message}", 'error')
      UI.messagebox("SU LinkHub 操作失败。\n#{e.class}: #{e.message}\n\n日志：#{LOG_PATH}")
      nil
    ensure
      if defined?(callback_claimed) && callback_claimed && defined?(action_key) && action_key
        @safe_callback_active ||= {}
        @safe_callback_active[action_key] = [@safe_callback_active[action_key].to_i - 1, 0].max
        if @safe_callback_active[action_key].zero?
          @safe_callback_active.delete(action_key)
          @safe_callback_active_started_at&.delete(action_key)
        end
      end
      log_slow_operation("操作 #{context}", started, 150.0) if defined?(started) && started
      if defined?(callback_invoked) && callback_invoked && safe_callback_should_restore_select_tool?(context)
        schedule_restore_default_select_tool(Sketchup.active_model, delay: 0.05, reason: context.to_s) rescue nil
      end
    end

    def native_confirm_yes?(message)
      type = defined?(UI::MB_YESNO) ? UI::MB_YESNO : 4
      yes = defined?(UI::IDYES) ? UI::IDYES : 6
      UI.messagebox(message.to_s, type) == yes
    rescue StandardError
      false
    end

